            opacity: 0 !important;
            pointer-events: none;
            transition: opacity 0.6s !important;
        }

        /* Retro scan lines */
        body::after {
            content: '';
            position: fixed;
            top: 0;
            left: 0;
            width: 100%;
            height: 100%;
            z-index: 10;
            background: repeating-linear-gradient(
