                rgba(0, 0, 0, 0.05),
                rgba(0, 0, 0, 0.05) 1px,
                transparent 1px,
                transparent 4px
            );
            pointer-events: none; /* Allow clicking through the scan lines */
        }

        .container {
            max-width: 800px;
            margin: 0 auto;
            padding: 20px;
