  },
  { at: 'constants.terrainGenerator.screenWidthPx', value: 480, pins: [{ file: 'src/systems/TerrainGenerator.js', text: 'options.screenWidthPx || 480' }] },
  { at: 'constants.terrainGenerator.pxPerMeterDefault', value: 20, pins: [{ file: 'src/systems/TerrainGenerator.js', text: 'options.pxPerMeter || 20' }] },
]);

/** Derived engine value engine.gravity.y: RunScene sets `world.engine.gravity.y = PHYSICS.gravityPxS2 / 1000`. */
export const GRAVITY_Y_PIN = Object.freeze({ file: 'src/scenes/RunScene.js', text: 'world.engine.gravity.y = PHYSICS.gravityPxS2 / 1000;' });

export class RulesetRegistryError extends Error {
  /** @param {string} code @param {string} detail */
  constructor(code, detail) {
    super(`${code}: ${detail}`);
    this.name = 'RulesetRegistryError';
    this.code = code;
  }
}

const isPlainObject = (v) => {
  if (v === null || typeof v !== 'object') return false;
  const p = Object.getPrototypeOf(v);
  return p === Object.prototype || p === null;
};

/** A value `export const` data can have: not a function/class/symbol; arrays and plain objects are data. */
const isData = (v) => typeof v !== 'function' && typeof v !== 'symbol' && typeof v !== 'undefined';

/**
 * Compare a module namespace with its registry entry.
 * @param {{id:string, exports:Object, statics?:Object}} source one RULESET_SOURCES entry
 * @param {Object} ns module namespace (or a plain object standing in for one)
 * @returns {{unregistered:string[], stale:string[]}} sorted names. Both lists empty = the registry is complete.
 */
export function classifyExports(source, ns) {
  const unregistered = [];
  const seen = new Set();
  const patterns = source.excludePatterns || [];
  for (const name of Object.keys(ns)) {
    const v = ns[name];
    if (typeof v === 'function') {
      // Code. Only a class with registered statics may carry data; any other enumerable static data is unregistered.
      const registeredStatics = (source.statics && source.statics[name]) || null;
      for (const sk of Object.keys(v)) {
        if (typeof v[sk] === 'function') continue;
        seen.add(`${name}.${sk}`);
        if (!registeredStatics || !(sk in registeredStatics)) unregistered.push(`${name}.${sk}`);
      }
      continue;
    }
    if (!isData(v)) continue;
    seen.add(name);
    if (!(name in source.exports) && !patterns.some((p) => p.pattern.test(name))) unregistered.push(name);
  }
  const stale = [];
  for (const p of patterns) if (!Object.keys(ns).some((n) => typeof ns[n] !== 'function' && p.pattern.test(n))) stale.push(String(p.pattern));
  for (const name of Object.keys(source.exports)) if (!(name in ns) || typeof ns[name] === 'function') stale.push(name);
  for (const [cls, members] of Object.entries(source.statics || {})) {
    for (const m of Object.keys(members)) if (!seen.has(`${cls}.${m}`)) stale.push(`${cls}.${m}`);
  }
  return { unregistered: unregistered.sort(), stale: stale.sort() };
}

const NUM_RE = /^-?(?:0x[0-9a-fA-F]+|\d+(?:\.\d+)?(?:e[+-]?\d+)?)$/;
const parseNum = (t) => (NUM_RE.test(t.trim()) ? Number(t.trim()) : null);
const stripFreeze = (rhs) => {
  const m = /^Object\.freeze\((.*)\)$/.exec(rhs.trim());
  return m ? m[1].trim() : rhs.trim();
};

/** Parse a numeric literal, a flat numeric array, or a flat `{key: number}` object. No eval. Null when not such a literal. */
function parseLiteral(rhs) {
  const t = stripFreeze(rhs);
  const n = parseNum(t);
  if (n !== null) return n;
  if (t.startsWith('[') && t.endsWith(']')) {
    const parts = t.slice(1, -1).split(',').map((x) => x.trim()).filter((x) => x.length);
    const vals = parts.map(parseNum);
    return vals.length && vals.every((v) => v !== null) ? vals : null;
  }
  if (t.startsWith('{') && t.endsWith('}')) {
    const out = {};
    const parts = t.slice(1, -1).split(',').map((x) => x.trim()).filter((x) => x.length);
    if (!parts.length) return null;
    for (const part of parts) {
      const m = /^([A-Za-z_][A-Za-z0-9_]*)\s*:\s*(.+)$/.exec(part);
      const v = m ? parseNum(m[2]) : null;
      if (v === null) return null;
      out[m[1]] = v;
    }
    return out;
  }
  return null;
}

/**
 * Column-0 single-line `[export ]const NAME = <literal>;` declarations whose value is a numeric literal, a flat numeric
 * array or a flat object of numbers (optionally `Object.freeze`d). Returns `{NAME: value}`. Anything else (computed
 * values, multi-line literals, strings) is not reported: that is the documented extraction gap.
 * @param {string} text
 * @returns {Object<string, (number|number[]|Object)>}
 */
export function scanNumericConsts(text) {
  const out = {};
  for (const line of text.split('\n')) {
    const m = /^(?:export )?const ([A-Za-z_][A-Za-z0-9_]*) = (.+?);\s*(?:\/\/.*)?$/.exec(line);
    if (!m) continue;
    const v = parseLiteral(m[2]);
    if (v !== null) out[m[1]] = v;
  }
  return out;
}

/**
 * Compare a file's scanned constants with its SOURCE_EXTRACTS entry.
 * @returns {{unregistered:string[], stale:string[]}}
 */
export function classifyExtract(extract, text) {
  const found = scanNumericConsts(text);
  const unregistered = Object.keys(found).filter((n) => !(n in extract.consts)).sort();
  const stale = Object.keys(extract.consts).filter((n) => !(n in found)).sort();
  return { unregistered, stale };
}

/**
 * Deep copy of plain JSON-like data with every key in `omit` removed at ANY depth (objects inside arrays included).
 * Rejects anything that is not null/boolean/string/finite number/array/plain object, so a function or class instance
 * hiding inside a table cannot be silently dropped from the identity.
 * @param {*} value
 * @param {Iterable<string>} [omit]
 * @param {string} [path]
 * @returns {*}
 */
export function projectData(value, omit = [], path = '$') {
  const skip = omit instanceof Set ? omit : new Set(omit);
  const walk = (v, p) => {
    if (v === null || typeof v === 'boolean' || typeof v === 'string') return v;
    if (typeof v === 'number') {
      if (!Number.isFinite(v)) throw new RulesetRegistryError('non-finite-number', p);
      return v;
    }
    if (Array.isArray(v)) return v.map((x, i) => walk(x, `${p}[${i}]`));
    if (isPlainObject(v)) {
      const out = {};
      for (const k of Object.keys(v)) {
        if (skip.has(k)) continue;
        out[k] = walk(v[k], `${p}.${k}`);
      }
      return out;
    }
    throw new RulesetRegistryError('not-data', `${p} (${typeof v})`);
  };
  return walk(value, path);
}

/** Every key path in a value, sorted and de-duplicated (arrays contribute `[]`). Used to review "what stays included". */
export function keyPaths(value) {
  const out = new Set();
  const walk = (v, p) => {
    if (Array.isArray(v)) {
      for (const x of v) walk(x, `${p}[]`);
      if (!v.length) out.add(`${p}[]`);
    } else if (v && typeof v === 'object') {
      for (const k of Object.keys(v)) walk(v[k], `${p}.${k}`);
    } else out.add(p);
  };
  walk(value, '');
  return [...out].sort();
}

/**
 * Count of each denylisted key actually present (any depth) in `value`: lets tests prove an entry is not dead.
 * @param {*} value @param {string[]} keys @returns {Object<string,number>}
 */
export function countKeys(value, keys) {
  const want = new Set(keys);
  const out = Object.fromEntries(keys.map((k) => [k, 0]));
  const walk = (v) => {
    if (Array.isArray(v)) v.forEach(walk);
    else if (v && typeof v === 'object') {
      for (const k of Object.keys(v)) {
        if (want.has(k)) out[k]++;
        walk(v[k]);
      }
    }
  };
  walk(value);
  return out;
}/**
 * Scoreboard helpers keyed on `rulesetId` (Replay Contract v1, section 7.5; issue #123). Pure: no Phaser, no clock, no
 * randomness, no storage. Nothing here touches RunRecord, the SaveStore ledger hashes (V1-V4) or sanitizeRun: wiring a
 * rulesetId into the local ledger would need a V5 hash and is an owner decision (open question Q7).
 *
 * Rules enforced:
 * - A board key always contains a `rulesetId` (never null: legacy outcomes are not eligible for any ruleset board).
 * - Only a `match` outcome, produced by a named verifier under a named ruleset, may appear on a board.
 * - Entries of different rulesets are never merged implicitly. A board that spans rulesets must be built with an explicit
 *   cross-ruleset call, whose result is a different kind of object (`kind: 'cross-ruleset'`).
 * - Historical validity and current eligibility are separate fields.
 */
import { canonicalize } from './canonicalJson.js';
import { RULESET_ID_RE } from './ruleset.js';
import { RulesetRegistryError } from './rulesetRegistry.js';
import { validateOutcomeRecord } from './rulesetVerifier.js';

export class RulesetMixError extends Error {
  /** @param {string} message */
  constructor(message) {
    super(message);
    this.name = 'RulesetMixError';
    this.code = 'ruleset-mix';
  }
}

const isId = (s) => typeof s === 'string' && RULESET_ID_RE.test(s);

/**
 * Stable key of one scoreboard: canonical JSON text of `{format, rulesetId, lane, biomeMask, seed}`.
 * @param {{rulesetId:string, lane:string, biomeMask:number, seed?:(string|null)}} parts `lane` is the existing mode
 *        string (`normal`/`daily`/`daily-draft`), `seed` null for boards that span seeds.
 * @returns {string}
 */
export function scoreboardKey({ rulesetId, lane, biomeMask, seed = null }) {
  if (!isId(rulesetId)) throw new RulesetRegistryError('bad-scoreboard-key', 'rulesetId must be sha256:<hex> (legacy/null runs have no board)');
  if (typeof lane !== 'string' || !lane) throw new RulesetRegistryError('bad-scoreboard-key', 'lane required');
  if (!Number.isSafeInteger(biomeMask) || biomeMask < 0) throw new RulesetRegistryError('bad-scoreboard-key', 'biomeMask must be a non-negative integer');
  if (seed !== null && typeof seed !== 'string') throw new RulesetRegistryError('bad-scoreboard-key', 'seed must be a string or null');
  return canonicalize({ format: 'bb-board-key', rulesetId, lane, biomeMask, seed });
}

/**
 * Why an outcome record may not be placed on any ruleset board, or null when it may. The record is first checked with
 * `validateOutcomeRecord`: a record with no/null verifierId, malformed digests, unknown keys or a boolean `verified` is
 * `invalid-record` and never eligible.
 */
export function ineligibleReason(record) {
  if (!record || typeof record !== 'object' || Array.isArray(record)) return 'not-a-record';
  try {
    validateOutcomeRecord(record);
  } catch (e) {
    if (e instanceof RulesetRegistryError) return 'invalid-record';
    throw e;
  }
  if (record.outcome === 'consistent-with' || record.outcome === 'inconclusive-legacy') return 'legacy-outcome';
  if (record.outcome === 'refused') return 'refused';
  if (record.outcome === 'diverged') return 'diverged';
  return null; // a validated `match`: verifiedUnder is a rulesetId and verifierId is named
}

/**
 * Split entries by the ruleset each was verified under. Never merges. Entries are `{record, ...anything}`.
 * @param {Array<{record:Object}>} entries
 * @param {string} [currentRulesetId] when given, each partition reports `currentlyEligible`.
 * @returns {{boards: Map<string, {rulesetId:string, historicallyValid:true, currentlyEligible:(boolean|null), entries:Array}>, ineligible:Array<{entry:Object, reason:string}>}}
 */
export function partitionByRuleset(entries, currentRulesetId = null) {
  const boards = new Map();
  const ineligible = [];
  for (const entry of entries) {
    const reason = ineligibleReason(entry && entry.record);
    if (reason) {
      ineligible.push({ entry, reason });
      continue;
    }
    const id = entry.record.verifiedUnder;
    if (!boards.has(id)) boards.set(id, { rulesetId: id, historicallyValid: true, currentlyEligible: currentRulesetId === null ? null : id === currentRulesetId, entries: [] });
    boards.get(id).entries.push(entry);
  }
  return { boards, ineligible };
}

/** The entries a board for `rulesetId` may show: exactly those verified under it. */
export function boardEntries(entries, rulesetId) {
  if (!isId(rulesetId)) throw new RulesetRegistryError('bad-scoreboard-key', 'rulesetId must be sha256:<hex>');
  const p = partitionByRuleset(entries).boards.get(rulesetId);
  return p ? p.entries : [];
}

/** Throws RulesetMixError unless every entry is eligible and verified under one and the same ruleset. Returns that id (null for no entries). */
export function assertSingleRuleset(entries) {
  const { boards, ineligible } = partitionByRuleset(entries);
  if (ineligible.length) throw new RulesetMixError(`board input contains an ineligible entry (${ineligible[0].reason})`);
  if (boards.size > 1) throw new RulesetMixError(`board input mixes rulesets: ${[...boards.keys()].sort().join(', ')}`);
  return boards.size ? [...boards.keys()][0] : null;
}

/**
 * Explicit cross-ruleset view (a history board). The caller must opt in; every entry keeps its own `rulesetId` and the
 * result's `kind` says it spans rulesets, so it cannot be mistaken for a current board.
 * @param {Array<{record:Object}>} entries
 * @param {{crossRuleset:true, currentRulesetId?:string}} opts
 */
export function crossRulesetView(entries, opts) {
  if (!opts || opts.crossRuleset !== true) throw new RulesetMixError('a board spanning rulesets must be requested with {crossRuleset: true}');
  const { boards } = partitionByRuleset(entries, opts.currentRulesetId || null);
  const rows = [];
  for (const id of [...boards.keys()].sort()) {
    const b = boards.get(id);
    for (const entry of b.entries) rows.push({ rulesetId: id, historicallyValid: true, currentlyEligible: b.currentlyEligible, entry });
  }
  return Object.freeze({ kind: 'cross-ruleset', rulesetIds: Object.freeze([...boards.keys()].sort()), rows: Object.freeze(rows) });
}/**
 * Verifier selection and outcome records (Replay Contract v1, sections 7.3 and 7.4; issue #123).
 *
 * `resolveVerifier(manifest, registry)` decides WHICH verifier may examine a manifest. It never runs one. A manifest
 * is only ever examined under the ruleset it names: an unknown or unrunnable ruleset is a refusal, never a fallback to
 * "the current one". The registry holds publisher-supplied data only: ruleset documents (id always recomputed from the
 * canonical bytes) and the allowlist of publisher-built verifier-bundle digests. Nothing in this module loads, imports,
 * evaluates or executes a verifier bundle; callers that later run an allowlisted bundle do so outside this module.
 *
 * Pure: no Phaser, no clock, no randomness, no network.
 */
import { CJSONError, canonicalize } from './canonicalJson.js';
import { RULESET_ID_RE, assertRulesetShape, parseRuleset, rulesetIdOf } from './ruleset.js';
import { RulesetRegistryError } from './rulesetRegistry.js';

export const IN_GAME_VERIFIER = 'in-game';

/** Stable refusal reasons. The first two are the contract's (7.3); the rest are malformed-input refusals. */
export const REFUSAL = Object.freeze({
  UNKNOWN_RULESET: 'unknown-ruleset',
  HISTORICAL_VERIFIER_REQUIRED: 'historical-verifier-required',
  MALFORMED_MANIFEST: 'malformed-manifest',
  MALFORMED_RULESET_ID: 'malformed-ruleset-id',
  NULL_RULESET_NOT_LEGACY: 'null-ruleset-not-legacy',
  RULESET_FIELD_MISMATCH: 'ruleset-field-mismatch',
});

export const OUTCOMES = Object.freeze(['match', 'diverged', 'consistent-with', 'inconclusive-legacy', 'refused']);
const RUN_OUTCOMES = ['match', 'diverged'];
const LEGACY_OUTCOMES = ['consistent-with', 'inconclusive-legacy'];

const DIGEST_RE = RULESET_ID_RE; // same `sha256:<64 hex>` shape for every Tier A digest
const isDigest = (s) => typeof s === 'string' && DIGEST_RE.test(s);

function loadRuleset(entry) {
  const r = entry && entry.ruleset;
  if (r instanceof Uint8Array || ArrayBuffer.isView(r)) return parseRuleset(r);
  return { doc: assertRulesetShape(r), rulesetId: rulesetIdOf(r) };
}

/**
 * Build a ruleset registry.
 *
 * @param {Object} o
 * @param {{ruleset:(Object|Uint8Array)}} o.current   the ruleset THIS build implements; verified by the in-game verifier.
 * @param {Array<{ruleset:(Object|Uint8Array), verifierId?:(string|null)}>} [o.archive] older rulesets. `verifierId` is
 *        the digest of the publisher-built historical verifier bundle that can reproduce it, or null when only the
 *        ruleset document itself is archived (preservation without a runnable verifier).
 * @param {string[]} [o.verifierAllowlist] digests of publisher-built bundles the publisher has allowlisted (the registry
 *        holds digests only, never bundle bytes). A digest naming a bundle that is not on this list is NEVER selected.
 * @returns {Readonly<{currentId:string, get:function(string):(Object|null), ids:function():string[], isAllowlisted:function(string):boolean}>}
 * @throws {RulesetRegistryError}
 */
export function createRulesetRegistry({ current, archive = [], verifierAllowlist = [] }) {
  const entries = new Map();
  const cur = loadRuleset(current);
  entries.set(cur.rulesetId, Object.freeze({ rulesetId: cur.rulesetId, ruleset: cur.doc, simRevision: cur.doc.simRevision, verifierId: IN_GAME_VERIFIER, current: true }));
  for (const a of archive) {
    const { doc, rulesetId } = loadRuleset(a);
    if (entries.has(rulesetId)) throw new RulesetRegistryError('duplicate-ruleset', rulesetId);
    const verifierId = a.verifierId === undefined ? null : a.verifierId;
    if (verifierId !== null && !isDigest(verifierId)) throw new RulesetRegistryError('bad-verifier-id', String(verifierId));
    entries.set(rulesetId, Object.freeze({ rulesetId, ruleset: doc, simRevision: doc.simRevision, verifierId, current: false }));
  }
  for (const d of verifierAllowlist) if (!isDigest(d)) throw new RulesetRegistryError('bad-verifier-id', String(d));
  const allow = new Set(verifierAllowlist);
  return Object.freeze({
    currentId: cur.rulesetId,
    get: (id) => (typeof id === 'string' && entries.has(id) ? entries.get(id) : null),
    ids: () => [...entries.keys()].sort(),
    isAllowlisted: (digest) => allow.has(digest),
  });
}

const refusal = (reason, rulesetId, extra = {}) => Object.freeze({ status: 'refused', reason, rulesetId: rulesetId === undefined ? null : rulesetId, verifierId: null, ...extra });

const sameEngine = (a, b) => !!a && !!b && a.phaser === b.phaser && a.matter === b.matter;

/**
 * Decide which verifier may examine `manifest` (7.3).
 *
 * Results (frozen plain objects, `status` first):
 * - `{status:'run', rulesetId, simRevision, verifierId, historical}`: examine under exactly that ruleset. `verifierId` is
 *   `'in-game'` for the current ruleset, else the allowlisted historical bundle digest (`historical:true`).
 * - `{status:'legacy-only', verifiedUnder, verifierId:'in-game', allowedOutcomes}`: a legacy-derived manifest (null
 *   ruleset). Only a verifier that declares its own ruleset may look, and only `consistent-with` / `inconclusive-legacy`
 *   can come out (5.3).
 * - `{status:'refused', reason, rulesetId, verifierId, ...}`: `unknown-ruleset`, `historical-verifier-required` (names the
 *   needed bundle digest, or null when none is archived), or a malformed-input reason. Never falls back to the current ruleset.
 *
 * @param {Object} manifest a parsed bb-replay-manifest (only `causal.sim` and `info.provenance` are read)
 * @param {ReturnType<typeof createRulesetRegistry>} registry
 */
export function resolveVerifier(manifest, registry) {
  const sim = manifest && manifest.causal && manifest.causal.sim;
  if (!manifest || typeof manifest !== 'object' || !sim || typeof sim !== 'object' || !('rulesetId' in sim)) {
    return refusal(REFUSAL.MALFORMED_MANIFEST, null, { detail: 'causal.sim.rulesetId is required (null only for legacy-derived manifests)' });
  }
  const id = sim.rulesetId;
  if (id === null) {
    const provenance = manifest.info && manifest.info.provenance;
    if (provenance !== 'legacy-derived') {
      return refusal(REFUSAL.NULL_RULESET_NOT_LEGACY, null, { detail: 'a null rulesetId is only legal when info.provenance is legacy-derived' });
    }
    return Object.freeze({
      status: 'legacy-only',
      verifiedUnder: registry.currentId,
      verifierId: IN_GAME_VERIFIER,
      allowedOutcomes: Object.freeze([...LEGACY_OUTCOMES]),
    });
  }
  if (!isDigest(id)) return refusal(REFUSAL.MALFORMED_RULESET_ID, null, { detail: 'rulesetId must be sha256:<64 lowercase hex>' });
  const entry = registry.get(id);
  if (!entry) return refusal(REFUSAL.UNKNOWN_RULESET, id, { detail: 'no ruleset with this id is registered; the current ruleset is never tried instead' });

  // Consistency copies (4.3: required whenever rulesetId is non-null; null only on legacy-derived manifests). A missing one
  // is a malformed manifest; a disagreement with the ruleset it names is a refusal, not a mismatch.
  const doc = entry.ruleset;
  if (!Number.isSafeInteger(sim.simRevision)) return refusal(REFUSAL.MALFORMED_MANIFEST, id, { field: 'simRevision', detail: 'causal.sim.simRevision is required with a non-null rulesetId' });
  if (!Number.isSafeInteger(sim.tickHz)) return refusal(REFUSAL.MALFORMED_MANIFEST, id, { field: 'tickHz', detail: 'causal.sim.tickHz is required with a non-null rulesetId' });
  if (!sim.engine || typeof sim.engine !== 'object') return refusal(REFUSAL.MALFORMED_MANIFEST, id, { field: 'engine', detail: 'causal.sim.engine is required with a non-null rulesetId' });
  if (sim.simRevision !== entry.simRevision) return refusal(REFUSAL.RULESET_FIELD_MISMATCH, id, { field: 'simRevision' });
  if (sim.tickHz !== doc.versions.tickHz) return refusal(REFUSAL.RULESET_FIELD_MISMATCH, id, { field: 'tickHz' });
  if (!sameEngine(sim.engine, doc.engine)) return refusal(REFUSAL.RULESET_FIELD_MISMATCH, id, { field: 'engine' });

  if (entry.current) {
    return Object.freeze({ status: 'run', rulesetId: id, simRevision: entry.simRevision, verifierId: IN_GAME_VERIFIER, historical: false });
  }
  if (entry.verifierId === null) {
    return refusal(REFUSAL.HISTORICAL_VERIFIER_REQUIRED, id, { verifierId: null, detail: 'ruleset is archived but no verifier bundle is registered for it' });
  }
  if (!registry.isAllowlisted(entry.verifierId)) {
    return refusal(REFUSAL.HISTORICAL_VERIFIER_REQUIRED, id, { verifierId: entry.verifierId, detail: 'the verifier bundle for this ruleset is not on the allowlist (absent or unreviewed)' });
  }
  return Object.freeze({ status: 'run', rulesetId: id, simRevision: entry.simRevision, verifierId: entry.verifierId, historical: true });
}

const OUTCOME_KEYS = new Set(['outcome', 'verifiedUnder', 'verifierId', 'tapeDigest', 'manifestDigest', 'firstDivergence', 'reason', 'claimedRulesetId']);

function failOutcome(code, detail) {
  throw new RulesetRegistryError(`bad-outcome-record:${code}`, detail);
}

/**
 * Check an outcome record (as built here, or read back from storage). There is no boolean `verified`: a record is a
 * statement by a named verifier. Unknown keys (a stray `verified: true` included) are rejected.
 * @param {Object} rec
 * @returns {Object} rec
 * @throws {RulesetRegistryError}
 */
export function validateOutcomeRecord(rec) {
  if (!rec || typeof rec !== 'object' || Array.isArray(rec)) failOutcome('shape', 'not an object');
  for (const k of Object.keys(rec)) if (!OUTCOME_KEYS.has(k)) failOutcome('unknown-key', k);
  if (!OUTCOMES.includes(rec.outcome)) failOutcome('outcome', String(rec.outcome));
  if (!isDigest(rec.tapeDigest)) failOutcome('tapeDigest', 'sha256:<hex> required');
  if (!isDigest(rec.manifestDigest)) failOutcome('manifestDigest', 'sha256:<hex> required');
  if (rec.outcome === 'refused') {
    if (rec.verifiedUnder !== null || rec.verifierId !== null) failOutcome('refused', 'a refusal has no verifier: verifiedUnder and verifierId must be null');
    if (typeof rec.reason !== 'string' || !rec.reason) failOutcome('refused', 'reason required');
    if (rec.firstDivergence !== undefined) failOutcome('refused', 'firstDivergence is not allowed');
    return rec;
  }
  if ('reason' in rec || 'claimedRulesetId' in rec) failOutcome('unexpected', 'reason/claimedRulesetId belong to refusals');
  if (!isDigest(rec.verifiedUnder)) failOutcome('verifiedUnder', 'a rulesetId is required: every statement names its ruleset');
  if (typeof rec.verifierId !== 'string' || !(rec.verifierId === IN_GAME_VERIFIER || isDigest(rec.verifierId))) failOutcome('verifierId', 'in-game or a bundle digest');
  if (rec.firstDivergence !== undefined) {
    if (rec.outcome !== 'diverged') failOutcome('firstDivergence', 'only a diverged outcome carries one');
    if (rec.firstDivergence === null || typeof rec.firstDivergence !== 'object') failOutcome('firstDivergence', 'object required');
    try {
      canonicalize(rec.firstDivergence);
    } catch (e) {
      if (e instanceof CJSONError) failOutcome('firstDivergence', e.message);
      throw e;
    }
  }
  return rec;
}

/**
 * Build an outcome record (7.4) from a resolution and a result. The record names the ruleset and verifier from the
 * RESOLUTION (never from the manifest's claim), so it cannot attribute a result to a verifier that did not produce it.
 *
 * @param {Object} o
 * @param {string} o.outcome `match`/`diverged` (resolution.status 'run'), `consistent-with`/`inconclusive-legacy`
 *        (resolution.status 'legacy-only'), or `refused` (resolution.status 'refused').
 * @param {ReturnType<typeof resolveVerifier>} o.resolution
 * @param {string} o.tapeDigest
 * @param {string} o.manifestDigest
 * @param {Object} [o.firstDivergence] CompareResult, `diverged` only
 * @returns {Readonly<Object>}
 */
export function makeOutcomeRecord({ outcome, resolution, tapeDigest, manifestDigest, firstDivergence }) {
  if (!resolution || typeof resolution !== 'object') failOutcome('resolution', 'required');
  let rec;
  if (resolution.status === 'refused') {
    if (outcome !== 'refused') failOutcome('outcome', `a refused resolution can only produce outcome "refused", not "${outcome}"`);
    rec = { outcome, verifiedUnder: null, verifierId: null, tapeDigest, manifestDigest, reason: resolution.reason };
    if (resolution.rulesetId) rec.claimedRulesetId = resolution.rulesetId;
  } else if (resolution.status === 'run') {
    if (!RUN_OUTCOMES.includes(outcome)) failOutcome('outcome', `a run resolution produces match or diverged, not "${outcome}"`);
    rec = { outcome, verifiedUnder: resolution.rulesetId, verifierId: resolution.verifierId, tapeDigest, manifestDigest };
  } else if (resolution.status === 'legacy-only') {
    if (!LEGACY_OUTCOMES.includes(outcome)) failOutcome('outcome', `a legacy manifest can only be consistent-with or inconclusive-legacy, not "${outcome}"`);
    rec = { outcome, verifiedUnder: resolution.verifiedUnder, verifierId: resolution.verifierId, tapeDigest, manifestDigest };
  } else failOutcome('resolution', `unknown status ${resolution.status}`);
  if (firstDivergence !== undefined) rec.firstDivergence = firstDivergence;
  validateOutcomeRecord(rec);
  return Object.freeze(rec);
}/**
 * The ruleset of the running build, for the live evidence path (#116). Uses Vite (`import.meta.glob` + JSON import), so
 * like src/data/index.js it is NOT importable from Jest; only src/services.js imports it. The committed artifact
 * (tools/ruleset/current.json + archive/<hex>.json, #123) is what CI proves equal to a fresh assembly of this source tree
 * (`node tools/ruleset/build-ruleset.mjs --check`), so the game does not re-assemble it (the assembly needs source text
 * of several files, which the browser bundle does not carry). The loaded bytes are re-hashed against the pointer.
 */
import current from '../../../tools/ruleset/current.json';
import { digestOf } from './canonicalSha256.js';

const archive = import.meta.glob('../../../tools/ruleset/archive/*.json', { import: 'default' });

/**
 * @returns {Promise<{doc:object, rulesetId:string}>}
 * @throws when the archive file is missing or does not hash to the id in current.json
 */
export async function loadCurrentRuleset() {
  const hex = String(current.rulesetId).replace(/^sha256:/, '');
  const key = Object.keys(archive).find((k) => k.endsWith(`/${hex}.json`));
  if (!key) throw new Error(`ruleset archive file for ${current.rulesetId} is not in this build`);
  const doc = await archive[key]();
  if (digestOf(doc) !== current.rulesetId) throw new Error(`ruleset archive ${hex} does not hash to its name`);
  return { doc, rulesetId: current.rulesetId };
}/**
 * Deterministic exact BUILD ID for savestate build binding (#238, parent #119 Phase 3B).
 *
 * Why this exists: `envelope.js` requires a `build` identity (`gameVersion`, `buildId`,
 * `physicsIdentity`, `matterVersion`, `savestateLayoutId`), but nothing in the tree produced it.
 * This module composes one from artifacts the repository already commits and CI already proves:
 *
 *   - `gameVersion`        `package.json` (the release version)
 *   - `physicsIdentity`    `tools/ruleset/current.json` (`rulesetId` + `simRevision`), which
 *                          `node tools/ruleset/build-ruleset.mjs --check` proves equals a fresh
 *                          assembly of this source tree
 *   - `matterVersion`      the bundled Matter version recorded in the archived ruleset
 *                          (`engine.matter`); the same pin the physics identity already carries
 *   - `savestateLayoutId`  `savestateLayoutIdOf()` over a trusted declarative layout descriptor
 *   - `sourceTripwireId`   a digest-of-digests over `tools/ruleset/source-digest.json`'s causal file
 *                          digests: the "compiled closure" signal that a causal file changed
 *
 * PURE and Jest-importable: no fs, browser globals, Phaser or Vite `import.meta.glob`. The Node CLI
 * and the thin runtime loader supply the parts, so every invariant here stays testable.
 *
 * Fail-closed: a missing or malformed part throws a coded `BuildIdentityError`. We never hash a
 * sentinel or emit a partial identity, mirroring `makeProvenance()`'s `proven:false` discipline.
 * `buildId` is NOT a function of semver alone: version, ruleset, simulation revision, Matter
 * version, layout schema and the causal-source tripwire are all in the closure.
 *
 * The source tripwire contributes its DIGESTS, never raw file bytes. `sourceTextDigest()` below is
 * the single CRLF->LF normalizer shared with `tools/ruleset/lib.mjs`, so an autocrlf checkout
 * cannot change the identity.
 */
import { canonicalBytes, utf8Encode } from '../replay/canonicalJson.js';
import { digestOf, digestOfBytes } from '../replay/canonicalSha256.js';
import { savestateLayoutIdOf } from './layout.js';

export const BUILD_IDENTITY_FORMAT = 'bb-build-identity';
export const BUILD_IDENTITY_FORMAT_VERSION = 1;
/** Domain separator for the build hash. Change it only with a deliberate identity-format break. */
export const BUILD_IDENTITY_DOMAIN = 'bb-build-identity-v1';

const HASH = /^sha256:[0-9a-f]{64}$/;
const SEMVER = /^(?:0|[1-9][0-9]*)\.(?:0|[1-9][0-9]*)\.(?:0|[1-9][0-9]*)$/;
const TRIPWIRE_FORMAT = 'bb-source-tripwire';
const TRIPWIRE_FORMAT_VERSION = 1;

/**
 * The exact input parts, in canonical form. Removing any one is a hard error, never a default.
 * `savestateLayoutId` may instead be supplied as `layoutDescriptor` and `sourceTripwire` may
 * instead be supplied as `sourceTripwireId`; those aliases are listed in `ALLOWED_PARTS`.
 */
export const REQUIRED_PARTS = Object.freeze([
  'gameVersion',
  'physicsIdentity',
  'matterVersion',
  'savestateLayoutId',
  'sourceTripwire',
]);
export const REQUIRED_PHYSICS_PARTS = Object.freeze(['rulesetId', 'simRevision']);
export const ALLOWED_PARTS = Object.freeze([
  ...REQUIRED_PARTS,
  'layoutDescriptor',
  'sourceTripwireId',
]);

/** Coded failure for every invalid composition. Never a sentinel identity. */
export class BuildIdentityError extends Error {
  /**
   * @param {string} code stable code, e.g. `missing-part` or `invalid-part`
   * @param {string} [part] the offending part path
   * @param {string} [detail] short redacted detail
   */
  constructor(code, part = '', detail = '') {
    super(`${code}${part ? ` at ${JSON.stringify(part)}` : ''}${detail ? ` (${detail})` : ''}`);
    this.name = 'BuildIdentityError';
    this.code = code;
    this.part = part;
  }
}

const fail = (code, part = '', detail = '') => { throw new BuildIdentityError(code, part, detail); };
const own = (x, k) => Object.prototype.hasOwnProperty.call(x, k);
/**
 * Reject class instances, arrays and proxies-of-classes while accepting plain objects from another
 * realm (Jest's jsdom vm loads JSON modules with that realm's `Object.prototype`, so an identity
 * check against this realm's `Object.prototype` would wrongly reject them). A plain object's
 * prototype is either `null` or an object whose own prototype is `null`.
 */
const plain = (x) => {
  if (x === null || typeof x !== 'object' || Array.isArray(x)) return false;
  const proto = Object.getPrototypeOf(x);
  return proto === null || Object.getPrototypeOf(proto) === null;
};
const present = (v) => v !== undefined && v !== null && !(typeof v === 'string' && v.length === 0);

/**
 * Digest of one causal source file's text, normalizing CRLF -> LF exactly as the committed source
 * tripwire does. This is the ONE normalizer: `tools/ruleset/lib.mjs`'s `tripwireDigests()` calls it.
 * @param {string} text
 * @returns {string} `sha256:<64 lowercase hex>`
 */
export function sourceTextDigest(text) {
  if (typeof text !== 'string') fail('invalid-source-text', 'text');
  return digestOfBytes(utf8Encode(text.replace(/\r\n/g, '\n')));
}

/**
 * Digest-of-digests over a parsed `bb-source-tripwire` document. Human annotations (`note`,
 * `attestation`, `changedFiles`, `simRevision`) are deliberately excluded: they can change without
 * any causal file changing. Canonical JSON sorts object keys, but tripwire paths contain `/`, which
 * BB-CJSON forbids in object keys, so paths are emitted as a sorted array of `[path, digest]` rows.
 * @param {object} tripwire parsed `tools/ruleset/source-digest.json`
 * @returns {string} `sha256:<64 lowercase hex>`
 */
export function sourceTripwireIdOf(tripwire) {
  if (!plain(tripwire)) fail('invalid-part', 'sourceTripwire');
  if (tripwire.format !== TRIPWIRE_FORMAT) fail('invalid-part', 'sourceTripwire.format');
  if (tripwire.formatVersion !== TRIPWIRE_FORMAT_VERSION) fail('invalid-part', 'sourceTripwire.formatVersion');
  if (!plain(tripwire.files)) fail('invalid-part', 'sourceTripwire.files');
  const paths = Object.keys(tripwire.files);
  if (paths.length === 0) fail('invalid-part', 'sourceTripwire.files');
  const rows = paths.sort().map((file) => {
    const digest = tripwire.files[file];
    if (typeof file !== 'string' || file.length === 0) fail('invalid-part', 'sourceTripwire.files');
    if (typeof digest !== 'string' || !HASH.test(digest)) fail('invalid-part', `sourceTripwire.files.${file}`);
    return [file, digest];
  });
  return digestOf({ format: TRIPWIRE_FORMAT, formatVersion: TRIPWIRE_FORMAT_VERSION, files: rows });
}

function normalizeParts(parts) {
  if (!plain(parts)) fail('invalid-parts');
  for (const key of Object.keys(parts)) if (!ALLOWED_PARTS.includes(key)) fail('unknown-part', key);

  if (!own(parts, 'gameVersion')) fail('missing-part', 'gameVersion');
  if (typeof parts.gameVersion !== 'string' || !SEMVER.test(parts.gameVersion)) fail('invalid-part', 'gameVersion');

  if (!own(parts, 'physicsIdentity')) fail('missing-part', 'physicsIdentity');
  const physics = parts.physicsIdentity;
  if (!plain(physics)) fail('invalid-part', 'physicsIdentity');
  for (const key of Object.keys(physics)) if (!REQUIRED_PHYSICS_PARTS.includes(key)) fail('unknown-part', `physicsIdentity.${key}`);
  for (const key of REQUIRED_PHYSICS_PARTS) if (!own(physics, key)) fail('missing-part', `physicsIdentity.${key}`);
  if (typeof physics.rulesetId !== 'string' || !HASH.test(physics.rulesetId)) fail('invalid-part', 'physicsIdentity.rulesetId');
  if (!Number.isSafeInteger(physics.simRevision) || physics.simRevision < 1 || Object.is(physics.simRevision, -0)) {
    fail('invalid-part', 'physicsIdentity.simRevision');
  }

  if (!own(parts, 'matterVersion')) fail('missing-part', 'matterVersion');
  if (typeof parts.matterVersion !== 'string' || !SEMVER.test(parts.matterVersion)) fail('invalid-part', 'matterVersion');

  const hasLayoutId = own(parts, 'savestateLayoutId');
  const hasLayoutDesc = own(parts, 'layoutDescriptor');
  if (hasLayoutId && hasLayoutDesc) fail('ambiguous-part', 'savestateLayoutId');
  if (!hasLayoutId && !hasLayoutDesc) fail('missing-part', 'savestateLayoutId');
  let layoutId;
  if (hasLayoutId) {
    if (typeof parts.savestateLayoutId !== 'string' || !HASH.test(parts.savestateLayoutId)) fail('invalid-part', 'savestateLayoutId');
    layoutId = parts.savestateLayoutId;
  } else {
    try {
      layoutId = savestateLayoutIdOf(parts.layoutDescriptor);
    } catch (error) {
      fail('invalid-layout-descriptor', 'layoutDescriptor', error && error.code ? String(error.code) : '');
    }
  }

  const hasTripwire = own(parts, 'sourceTripwire');
  const hasTripwireId = own(parts, 'sourceTripwireId');
  if (hasTripwire && hasTripwireId) fail('ambiguous-part', 'sourceTripwire');
  if (!hasTripwire && !hasTripwireId) fail('missing-part', 'sourceTripwire');
  let sourceTripwireId;
  if (hasTripwireId) {
    if (typeof parts.sourceTripwireId !== 'string' || !HASH.test(parts.sourceTripwireId)) fail('invalid-part', 'sourceTripwireId');
    sourceTripwireId = parts.sourceTripwireId;
  } else {
    sourceTripwireId = sourceTripwireIdOf(parts.sourceTripwire);
  }

  return Object.freeze({
    gameVersion: parts.gameVersion,
    physicsIdentity: Object.freeze({ rulesetId: physics.rulesetId, simRevision: physics.simRevision }),
    matterVersion: parts.matterVersion,
    savestateLayoutId: layoutId,
    sourceTripwireId,
  });
}

/** Domain-separated `tag \0 canonicalJson` digest, matching cache-provenance.mjs's identity shape. */
function identityDigestOf(closure) {
  const tag = utf8Encode(`${BUILD_IDENTITY_DOMAIN}\0`);
  const body = canonicalBytes(closure);
  const tagged = new Uint8Array(tag.length + body.length);
  tagged.set(tag, 0);
  tagged.set(body, tag.length);
  return digestOfBytes(tagged);
}

/** The explicitly enumerated closure `buildId` covers. Nothing outside this list can affect it. */
const closureOf = (normalized) => ({
  gameVersion: normalized.gameVersion,
  physicsIdentity: normalized.physicsIdentity,
  matterVersion: normalized.matterVersion,
  savestateLayoutId: normalized.savestateLayoutId,
  sourceTripwireId: normalized.sourceTripwireId,
});

/**
 * Compose the full build-identity record from raw parts.
 * @param {object} parts `{gameVersion, physicsIdentity:{rulesetId,simRevision}, matterVersion, layoutDescriptor|savestateLayoutId, sourceTripwire|sourceTripwireId}`
 * @returns {Readonly<{format:string, formatVersion:number, gameVersion:string, buildId:string, physicsIdentity:object, matterVersion:string, savestateLayoutId:string, sourceTripwireId:string}>}
 * @throws {BuildIdentityError}
 */
export function composeBuildIdentity(parts) {
  const normalized = normalizeParts(parts);
  return Object.freeze({
    format: BUILD_IDENTITY_FORMAT,
    formatVersion: BUILD_IDENTITY_FORMAT_VERSION,
    gameVersion: normalized.gameVersion,
    buildId: identityDigestOf(closureOf(normalized)),
    physicsIdentity: normalized.physicsIdentity,
    matterVersion: normalized.matterVersion,
    savestateLayoutId: normalized.savestateLayoutId,
    sourceTripwireId: normalized.sourceTripwireId,
  });
}

/**
 * The `buildId` alone.
 * @param {object} parts same shape as `composeBuildIdentity`
 * @returns {string} `sha256:<64 lowercase hex>`
 * @throws {BuildIdentityError}
 */
export function buildIdOf(parts) {
  return composeBuildIdentity(parts).buildId;
}

/**
 * The exact five-field descriptor `envelope.js` requires (`build` / `expectedIdentity`). The full
 * record also carries `format`, `formatVersion` and `sourceTripwireId`, which the envelope's strict
 * schema rejects, so callers must use this projection rather than the record itself.
 * @param {object} record a `composeBuildIdentity()` result
 * @returns {Readonly<{gameVersion:string, buildId:string, physicsIdentity:object, matterVersion:string, savestateLayoutId:string}>}
 * @throws {BuildIdentityError}
 */
export function buildDescriptorOf(record) {
  if (!plain(record)) fail('invalid-identity');
  for (const key of ['gameVersion', 'buildId', 'physicsIdentity', 'matterVersion', 'savestateLayoutId']) {
    if (!own(record, key) || !present(record[key])) fail('missing-part', key);
  }
  if (typeof record.gameVersion !== 'string' || !SEMVER.test(record.gameVersion)) fail('invalid-part', 'gameVersion');
  if (typeof record.buildId !== 'string' || !HASH.test(record.buildId)) fail('invalid-part', 'buildId');
  if (typeof record.matterVersion !== 'string' || !SEMVER.test(record.matterVersion)) fail('invalid-part', 'matterVersion');
  if (typeof record.savestateLayoutId !== 'string' || !HASH.test(record.savestateLayoutId)) fail('invalid-part', 'savestateLayoutId');
  if (!plain(record.physicsIdentity)) fail('invalid-part', 'physicsIdentity');
  if (typeof record.physicsIdentity.rulesetId !== 'string' || !HASH.test(record.physicsIdentity.rulesetId)) fail('invalid-part', 'physicsIdentity.rulesetId');
  if (!Number.isSafeInteger(record.physicsIdentity.simRevision) || record.physicsIdentity.simRevision < 1) fail('invalid-part', 'physicsIdentity.simRevision');
  return Object.freeze({
    gameVersion: record.gameVersion,
    buildId: record.buildId,
    physicsIdentity: Object.freeze({ rulesetId: record.physicsIdentity.rulesetId, simRevision: record.physicsIdentity.simRevision }),
    matterVersion: record.matterVersion,
    savestateLayoutId: record.savestateLayoutId,
  });
}

function descriptorProblem(candidate) {
  if (!plain(candidate)) return { code: 'invalid-identity', part: '' };
  const keys = ['gameVersion', 'buildId', 'physicsIdentity', 'matterVersion', 'savestateLayoutId'];
  for (const key of Object.keys(candidate)) if (!keys.includes(key)) return { code: 'unknown-identity-part', part: key };
  for (const key of keys) if (!own(candidate, key) || !present(candidate[key])) return { code: 'missing-identity-part', part: key };
  if (typeof candidate.gameVersion !== 'string' || !SEMVER.test(candidate.gameVersion)) return { code: 'invalid-identity-part', part: 'gameVersion' };
  if (typeof candidate.buildId !== 'string' || !HASH.test(candidate.buildId)) return { code: 'invalid-identity-part', part: 'buildId' };
  if (typeof candidate.matterVersion !== 'string' || !SEMVER.test(candidate.matterVersion)) return { code: 'invalid-identity-part', part: 'matterVersion' };
  if (typeof candidate.savestateLayoutId !== 'string' || !HASH.test(candidate.savestateLayoutId)) return { code: 'invalid-identity-part', part: 'savestateLayoutId' };
  if (!plain(candidate.physicsIdentity)) return { code: 'invalid-identity-part', part: 'physicsIdentity' };
  for (const key of Object.keys(candidate.physicsIdentity)) {
    if (!REQUIRED_PHYSICS_PARTS.includes(key)) return { code: 'unknown-identity-part', part: `physicsIdentity.${key}` };
  }
  for (const key of REQUIRED_PHYSICS_PARTS) {
    if (!own(candidate.physicsIdentity, key) || !present(candidate.physicsIdentity[key])) return { code: 'missing-identity-part', part: `physicsIdentity.${key}` };
  }
  if (typeof candidate.physicsIdentity.rulesetId !== 'string' || !HASH.test(candidate.physicsIdentity.rulesetId)) return { code: 'invalid-identity-part', part: 'physicsIdentity.rulesetId' };
  if (!Number.isSafeInteger(candidate.physicsIdentity.simRevision) || candidate.physicsIdentity.simRevision < 1) return { code: 'invalid-identity-part', part: 'physicsIdentity.simRevision' };
  return null;
}

/**
 * Compare two envelope-shaped build identities without throwing. This is a read-only diagnostic
 * companion to `envelope.js`, which remains the admission authority; the comparison codes match
 * `compareExpected()` there exactly (`build-mismatch`, `physics-mismatch`, `matter-mismatch`,
 * `layout-mismatch`).
 * @param {object} candidate
 * @param {object} expected
 * @returns {{ok:true}|{ok:false, code:string, part?:string}}
 */
export function inspectBuildIdentity(candidate, expected) {
  try {
    const candidateProblem = descriptorProblem(candidate);
    if (candidateProblem) return { ok: false, ...candidateProblem };
    const expectedProblem = descriptorProblem(expected);
    if (expectedProblem) return { ok: false, ...expectedProblem };
    if (candidate.gameVersion !== expected.gameVersion || candidate.buildId !== expected.buildId) {
      return { ok: false, code: 'build-mismatch', part: 'buildId' };
    }
    if (candidate.physicsIdentity.rulesetId !== expected.physicsIdentity.rulesetId ||
        candidate.physicsIdentity.simRevision !== expected.physicsIdentity.simRevision) {
      return { ok: false, code: 'physics-mismatch', part: 'physicsIdentity' };
    }
    if (candidate.matterVersion !== expected.matterVersion) return { ok: false, code: 'matter-mismatch', part: 'matterVersion' };
    if (candidate.savestateLayoutId !== expected.savestateLayoutId) return { ok: false, code: 'layout-mismatch', part: 'savestateLayoutId' };
    return { ok: true };
  } catch {
    return { ok: false, code: 'invalid-identity', part: '' };
  }
}/**
 * BbSavestateCache V1: pure format/identity/section-admission foundation (#119).
 * No production save/load, Matter objects, storage, UI, ranked-state mutation or
 * trust claim. An accepted envelope is NOT a restorable world and NOT proof of
 * a legitimate run. Diagnostic snapshots are intentionally incompatible.
 *
 * Owners already decided: single-use suspend retains full tick-zero tape;
 * repeatable practice reload is tool-assisted. Enforcement of both is a
 * separate runtime/recorder/ranking PR, never inferred from these bytes.
 */
import { canonicalBytes, parseCanonical, CJSONError } from '../replay/canonicalJson.js';
import { digestOf } from '../replay/canonicalSha256.js';
import { inspectLayoutRegistration } from './layout.js';

export const SAVESTATE_ENVELOPE_KIND = 'bb-savestate-cache';
export const SAVESTATE_ENVELOPE_VERSION = 1;
const HASH = /^sha256:[0-9a-f]{64}$/;
const SEMVER = /^(?:0|[1-9][0-9]*)\.(?:0|[1-9][0-9]*)\.(?:0|[1-9][0-9]*)$/;
const RUN_ID = /^[A-Za-z0-9_.:-]{1,96}$/;
const ALLOWED_PURPOSES = new Set(['suspend', 'practice']);

export class SavestateEnvelopeError extends Error {
  constructor(code, pointer = '') {
    super(`${code} at ${JSON.stringify(pointer)}`);
    this.name = 'SavestateEnvelopeError';
    this.code = code;
    this.pointer = pointer;
  }
}

const fail = (code, pointer = '') => { throw new SavestateEnvelopeError(code, pointer); };
const own = (x, k) => Object.prototype.hasOwnProperty.call(x, k);
const plain = x => x !== null && typeof x === 'object' && !Array.isArray(x) &&
  (Object.getPrototypeOf(x) === Object.prototype || Object.getPrototypeOf(x) === null);
const schema = (value, required, pointer) => {
  if (!plain(value)) fail('invalid-field', pointer);
  for (const k of required) if (!own(value, k)) fail('missing-field', `${pointer}/${k}`);
  for (const k of Object.keys(value)) if (!required.includes(k)) fail('unknown-envelope-field', `${pointer}/${k}`);
};
const text = (v, p, re, max = 128) => {
  if (typeof v !== 'string' || v.length === 0 || v.length > max || (re && !re.test(v))) fail('invalid-field', p);
};
const int = (v, p, min = 0) => {
  if (!Number.isSafeInteger(v) || v < min || Object.is(v, -0)) fail('invalid-field', p);
};

function identity(build, p) {
  schema(build, ['gameVersion','buildId','physicsIdentity','matterVersion','savestateLayoutId'], p);
  text(build.gameVersion, `${p}/gameVersion`, SEMVER);
  text(build.buildId, `${p}/buildId`, HASH);
  text(build.matterVersion, `${p}/matterVersion`, SEMVER);
  text(build.savestateLayoutId, `${p}/savestateLayoutId`, HASH);
  schema(build.physicsIdentity, ['rulesetId','simRevision'], `${p}/physicsIdentity`);
  text(build.physicsIdentity.rulesetId, `${p}/physicsIdentity/rulesetId`, HASH);
  int(build.physicsIdentity.simRevision, `${p}/physicsIdentity/simRevision`, 1);
}

function shape(e, hasIntegrity) {
  const fields = ['kind','version','purpose','build','runId','tick','payload'];
  if (hasIntegrity) fields.push('integrity');
  schema(e, fields, '');
  if (e.kind !== SAVESTATE_ENVELOPE_KIND || e.version !== SAVESTATE_ENVELOPE_VERSION) fail('unsupported-format-version', '/version');
  if (!ALLOWED_PURPOSES.has(e.purpose)) fail('invalid-field', '/purpose');
  identity(e.build, '/build');
  text(e.runId, '/runId', RUN_ID, 96);
  int(e.tick, '/tick');
  schema(e.payload, ['sections'], '/payload');
  if (!plain(e.payload.sections)) fail('invalid-field', '/payload/sections');
  if (hasIntegrity) text(e.integrity, '/integrity', HASH);
}

/**
 * ParseCanonical gives us a bounded (32 levels) acyclic tree of plain objects
 * and arrays. Freeze it before calling a trusted-but-possibly-buggy validator:
 * its verdict must not describe different bytes than the checksum covered.
 * The caller also receives this immutable snapshot, so admission cannot later
 * be mistaken for validation of a modified envelope.
 */
function freezeParsedTree(root) {
  const nodes = [root];
  while (nodes.length) {
    const node = nodes.pop();
    if (node === null || typeof node !== 'object' || Object.isFrozen(node)) continue;
    for (const value of Object.values(node)) {
      if (value !== null && typeof value === 'object') nodes.push(value);
    }
    Object.freeze(node);
  }
  return root;
}

function verifyExpected(expected) {
  if (!plain(expected)) fail('missing-runtime-identity');
  identity(expected, '/expectedIdentity');
}

function compareExpected(actual, expected) {
  if (actual.gameVersion !== expected.gameVersion || actual.buildId !== expected.buildId) fail('build-mismatch', '/build/buildId');
  if (actual.physicsIdentity.rulesetId !== expected.physicsIdentity.rulesetId ||
      actual.physicsIdentity.simRevision !== expected.physicsIdentity.simRevision) fail('physics-mismatch', '/build/physicsIdentity');
  if (actual.matterVersion !== expected.matterVersion) fail('matter-mismatch', '/build/matterVersion');
  if (actual.savestateLayoutId !== expected.savestateLayoutId) fail('layout-mismatch', '/build/savestateLayoutId');
}

/**
 * Encode an explicitly shaped envelope with a SHA-256 *error-detection* seal.
 * This is NOT an authentication/MAC/signature and DOES NOT confer run trust.
 * `integrity` must be omitted; the writer computes it over the entire header
 * and section payload so changing tick/purpose/build also invalidates the seal.
 */
export function snapshotEnvelopeBytes(unsignedEnvelope) {
  shape(unsignedEnvelope, false);
  // Canonical encoding rejects hidden/accessor properties, prototype keys,
  // nonfinite ordinary numbers, -0, sparse arrays and oversized objects.
  const bytes = canonicalBytes(unsignedEnvelope);
  // Parse a fresh object so the caller cannot mutate the envelope while the
  // digest is being created or after it is returned.
  const copy = parseCanonical(bytes);
  const sealed = { ...copy, integrity: digestOf(copy) };
  return canonicalBytes(sealed);
}

/**
 * Validate untrusted serialized bytes against an explicitly caller-supplied
 * exact-build identity and a trusted locally registered schema validator.
 * Does NOT perform restoration. Returns { ok:true, admission:'envelope-only',
 * envelope } or {ok:false,code,pointer}; malformed input never mutates state.
 * No valid production layout is shipped by this foundation PR.
 */
export function inspectSnapshotEnvelope(bytes, expectedIdentity, registeredLayout) {
  try {
    // Parser performs strict UTF-8, duplicate-key, canonical-json, prototype,
    // size, depth and number checks before any custom validation.
    const envelope = parseCanonical(bytes);
    shape(envelope, true);
    verifyExpected(expectedIdentity);
    const { integrity, ...unsigned } = envelope;
    if (integrity !== digestOf(unsigned)) fail('digest-mismatch', '/integrity');
    compareExpected(envelope.build, expectedIdentity);
    if (!inspectLayoutRegistration(registeredLayout, expectedIdentity.savestateLayoutId)) {
      fail('unsupported-layout', '/build/savestateLayoutId');
    }
    // Preserve the exact reviewed snapshot bytes through validation and handoff.
    // Any accidental in-place transformation by a future class validator must
    // fail rather than silently changing what was digest-verified.
    freezeParsedTree(envelope);
    // This function is supplied by trusted shipped code, never snapshot data.
    // A future production schema registry must audit every SIM field and every
    // reference; a truthy-but-not-true return is deliberately not admission.
    let accepted = false;
    try { accepted = registeredLayout.validateSections(envelope.payload.sections) === true; }
    catch { fail('invalid-section', '/payload/sections'); }
    if (!accepted) fail('invalid-section', '/payload/sections');
    return { ok:true, admission:'envelope-only', envelope };
  } catch (error) {
    if (error instanceof SavestateEnvelopeError || error instanceof CJSONError) {
      return { ok:false, code:error.code, pointer:error.pointer };
    }
    return { ok:false, code:'invalid-envelope', pointer:'' };
  }
}/**
 * Versioned ID for the *declared schema* of one production savestate layout.
 * A layout identity is not a causal fingerprint, a state digest or proof of play.
 * This layer intentionally registers NO production layouts: schema/matter work
 * must land before any runtime can accept a savestate for restoration (#119).
 */
import { canonicalBytes, CJSONError } from '../replay/canonicalJson.js';
import { digestOf } from '../replay/canonicalSha256.js';

export const SAVESTATE_LAYOUT_FORMAT_VERSION = 1;
export const SAVESTATE_LAYOUT_KIND = 'bb-savestate-layout';
const MAX_LAYOUT_BYTES = 64 * 1024;

export function savestateLayoutIdOf(descriptor) {
  // BB-CJSON itself rejects functions, accessors, proto keys, unsafe numbers,
  // non-plain objects, excessively nested values and undefined.
  const bytes = canonicalBytes(descriptor);
  if (bytes.byteLength > MAX_LAYOUT_BYTES) throw new CJSONError('too-large', '', 'savestate layout descriptor exceeds 64 KiB');
  if (!descriptor || typeof descriptor !== 'object' || Array.isArray(descriptor) ||
      Object.keys(descriptor).length === 0) throw new CJSONError('invalid-layout', '', 'a nonempty explicit descriptor is required');
  return digestOf({ kind: SAVESTATE_LAYOUT_KIND, version: SAVESTATE_LAYOUT_FORMAT_VERSION, descriptor });
}

/**
 * A trusted, locally shipped layout registration must supply both a descriptor
 * and a pure, strict section validator. It is NEVER read out of snapshot bytes.
 * It is a validator seam, NOT an executable restore/materializer registry.
 */
export function inspectLayoutRegistration(registration, expectedId) {
  if (!registration || typeof registration !== 'object' || Array.isArray(registration) ||
      typeof registration.validateSections !== 'function') return false;
  try { return savestateLayoutIdOf(registration.descriptor) === expectedId; }
  catch { return false; }
}/**
 * The *declared* savestate layout schema of this build, for build-identity composition (#238).
 *
 * This is NOT a layout registration: it carries no `validateSections`, and `layout.js` still
 * registers zero production layouts, so `inspectSnapshotEnvelope()` cannot admit a snapshot with
 * it. It exists because `buildId` must bind the layout schema (`savestateLayoutId`) and the
 * currently-shipped layout registry declares no sections. Every production schema addition MUST
 * extend this descriptor in the same change; because `buildId` hashes `savestateLayoutId`, any
 * change here produces a different build identity, which is the intended fail-closed behaviour.
 */
export const SAVESTATE_LAYOUT_DECLARATION_VERSION = 1;

export const SAVESTATE_LAYOUT_DESCRIPTOR = Object.freeze({
  version: SAVESTATE_LAYOUT_DECLARATION_VERSION,
  sections: Object.freeze({}),
});/**
 * Read-only identity of the RUNNING build (#238). This is the seam a live build uses to report
 * exactly what it is; it writes nothing, touches no storage, mutates no ruleset and performs no
 * restore.
 *
 * Choice of location: the pure composition lives in `./buildIdentity.js`. This module is also
 * Jest-importable: its top-level imports are plain data (`package.json`, the committed source
 * tripwire) and pure modules. Only `loadCurrentBuildIdentity()` reaches for
 * `../replay/runtimeRuleset.js`, and it does so with a DYNAMIC import, because that module uses
 * Vite's `import.meta.glob`, which Jest cannot import (see its header and `src/data/index.js`).
 * That split keeps `composeCurrentBuildIdentity()` testable in Jest while the live path still
 * reuses the one archive loader the replay evidence path already trusts. No Phaser import.
 */
import packageInfo from '../../../package.json';
import sourceTripwire from '../../../tools/ruleset/source-digest.json';
import { BuildIdentityError, buildDescriptorOf, composeBuildIdentity } from './buildIdentity.js';
import { SAVESTATE_LAYOUT_DESCRIPTOR } from './layoutDeclaration.js';

/**
 * The parts a running build supplies, from its already-loaded ruleset and the committed artifacts.
 * @param {{doc:object, rulesetId:string}} ruleset `loadCurrentRuleset()`'s result
 * @returns {object}
 * @throws {BuildIdentityError} when the ruleset cannot prove a part
 */
export function buildIdentityPartsOf(ruleset) {
  if (ruleset === null || typeof ruleset !== 'object' || Array.isArray(ruleset)) throw new BuildIdentityError('invalid-ruleset', '');
  const { doc, rulesetId } = ruleset;
  if (doc === null || typeof doc !== 'object' || Array.isArray(doc)) throw new BuildIdentityError('invalid-ruleset', 'doc');
  if (doc.engine === null || typeof doc.engine !== 'object' || Array.isArray(doc.engine)) throw new BuildIdentityError('invalid-ruleset', 'doc.engine');
  return {
    gameVersion: packageInfo.version,
    physicsIdentity: { rulesetId, simRevision: doc.simRevision },
    matterVersion: doc.engine.matter,
    layoutDescriptor: SAVESTATE_LAYOUT_DESCRIPTOR,
    sourceTripwire,
  };
}

/**
 * Compose the running build's full identity from an already-loaded ruleset. Pure.
 * @param {{doc:object, rulesetId:string}} ruleset
 * @returns {Readonly<object>} full `bb-build-identity` record
 */
export function composeCurrentBuildIdentity(ruleset) {
  return composeBuildIdentity(buildIdentityPartsOf(ruleset));
}

/**
 * The envelope-shaped projection of the running build's identity. Pure.
 * @param {{doc:object, rulesetId:string}} ruleset
 * @returns {Readonly<object>} the five fields `envelope.js` requires
 */
export function currentBuildDescriptorOf(ruleset) {
  return buildDescriptorOf(composeCurrentBuildIdentity(ruleset));
}

/**
 * Load the committed ruleset and report this build's full identity. Read-only.
 * @returns {Promise<Readonly<object>>}
 */
export async function loadCurrentBuildIdentity() {
  const { loadCurrentRuleset } = await import('../replay/runtimeRuleset.js');
  return composeCurrentBuildIdentity(await loadCurrentRuleset());
}

/**
 * Load the committed ruleset and report this build's envelope-shaped identity. Read-only.
 * @returns {Promise<Readonly<object>>}
 */
export async function loadCurrentBuildDescriptor() {
  return buildDescriptorOf(await loadCurrentBuildIdentity());
}/**
 * OWNER: progression engineer. Pure. No Phaser, no Date.now() inside.
 *
 * W5 achievements: evaluate the catalogue against the player's accumulated state and return the ones newly
 * unlocked.
 *
 * The timestamp is a PARAMETER, never read here. Spec W5 says so explicitly ("stored with a timestamp
 * supplied by the caller"), and the reason is testability: an evaluator that calls Date.now() cannot be
 * tested for "unlocks once, with a stable time" without freezing the clock, and a replayed save produces a
 * different unlock time every time it is evaluated.
 *
 * "Unlocks once" is enforced by the caller's stored set, not by this module: the module reports what the
 * state QUALIFIES for, and `newlyUnlocked` subtracts what the profile already has. That keeps the module
 * stateless, so evaluating the same state twice is idempotent.
 */
import { sanitizeBiomeProgress } from './BiomeDiscovery.js';

/**
 * Every metric the evaluator can compute. A catalogue entry naming something else is a bug in the data,
 * and the catalogue test pins this list so it fails loudly instead of never unlocking.
 */
export const METRICS = Object.freeze([
  'runs', 'totalDistanceM', 'bestDistanceM', 'bestScore', 'bestCombo', 'maxAirtimeMs',
  'tricksLanded', 'trickKinds', 'nearMisses', 'bsodBluffs', 'bsodSurfs', 'dailyRuns', 'bestStreak',
  'shards', 'level', 'biomesDiscovered',
]);

/**
 * Marvin decision 9: one canonical order for the whole catalogue. Group first (the grid's section order),
 * then metric (so one ladder such as runs 1/10/50 stays together instead of interleaving with another
 * metric's thresholds), then target ascending. The grid, `qualified` / `newlyUnlocked` (and so the order
 * creditRun reports and the toast shows) all read this order, so the easiest rung of a ladder is always
 * listed, evaluated and announced before the harder ones.
 */
export const GROUP_ORDER = Object.freeze(['distance', 'skill', 'daily', 'collection', 'biomes']);

/** Metric rank inside a group: exactly the METRICS set, ordered for display. */
export const METRIC_ORDER = Object.freeze([
  'runs', 'bestDistanceM', 'totalDistanceM', 'bestScore',
  'bestCombo', 'maxAirtimeMs', 'tricksLanded', 'trickKinds', 'nearMisses', 'bsodBluffs', 'bsodSurfs',
  'dailyRuns', 'bestStreak',
  'shards', 'level', 'biomesDiscovered',
]);

const rankIn = (list, v) => {
  const i = list.indexOf(v);
  return i < 0 ? list.length : i;
};

/**
 * Sort achievement defs into the canonical order: group, metric, target. Stable: ties keep their input
 * order. An unknown group or metric sorts after every known one rather than jumping to the front.
 * Pure: returns a new array and leaves the input alone.
 * @param {Array<Object>} list
 * @returns {Array<Object>}
 */
export function sortAchievements(list) {
  const arr = Array.isArray(list) ? list.filter(Boolean) : [];
  return arr
    .map((a, i) => ({ a, i }))
    .sort((x, y) => (rankIn(GROUP_ORDER, x.a.group) - rankIn(GROUP_ORDER, y.a.group))
      || (rankIn(METRIC_ORDER, x.a.metric) - rankIn(METRIC_ORDER, y.a.metric))
      || ((Number.isFinite(x.a.target) ? x.a.target : Infinity) - (Number.isFinite(y.a.target) ? y.a.target : Infinity))
      || (x.i - y.i))
    .map((e) => e.a);
}

/**
 * The shipped catalogue. Loaded from data/achievements/achievements.json by the service; this fallback
 * keeps a pure test or a headless caller independent of the bundler, exactly as SHOP_ITEMS does.
 */
// ACH-2: bestCombo is the combo MULTIPLIER (x1 plus 0.25 per unique flip/helicopter type in one jump, so
// x2.0 at most). The old 5/10/20 targets could never be met. combo-5/10/20 now ask for x1.25 / x1.5 /
