  { id: 'trail-cyan', kind: 'trail', slot: 'trail', name: 'Cyan Trail', price: 0, unlockLevel: 2, value: 'cyan' },
  { id: 'glow-lime', kind: 'glow', slot: 'glow', name: 'Lime Glow', price: 0, unlockLevel: 5, value: 'lime' },
