  { id: 'rider-drone', kind: 'rider', slot: 'rider', name: 'Neon Sled Drone', price: 0, unlockLevel: 1, value: 'drone', grant: 'biome', biome: 'micro-mountain', unlockText: 'COMPLETE MICRO MOUNTAIN' },
