Object.defineProperty(HUES, 'sledGlow', { value: HUES.glow, enumerable: false });
export const COSMETIC_HUES = Object.freeze(HUES);

/** The palette keys a UI theme may override. Never `danger`, `bg`, `lime` or `amber`. */
export const UI_THEME_KEYS = Object.freeze(['cyan', 'magenta', 'text', 'bgAlt']);

/** Cosmetic id -> catalogue entry, derived from COSMETIC_ITEMS so it cannot disagree with the shop. */
const CATALOGUE = Object.freeze(Object.fromEntries(
  COSMETIC_ITEMS.map((i) => [i.id, Object.freeze({ kind: i.kind, slot: i.slot, value: i.value })]),
));

/**
 * The catalogue entry a SLOT holds, matched by id or by equipped value but only within that slot.
 *
 * Values repeat across slots ('cyan' is a trail, a glow and a theme), so a slot-blind lookup by value would
 * hand the glow slot the trail entry and the item would render as missing.
 * @param {string} slot @param {string} idOrValue @returns {{kind:string,slot:string,value:string,id:string}|null}
 */
export function cosmeticInSlot(slot, idOrValue) {
  if (typeof idOrValue !== 'string' || !idOrValue) return null;
  const direct = CATALOGUE[idOrValue];
  if (direct && direct.slot === slot) return { ...direct, id: idOrValue };
  for (const [id, entry] of Object.entries(CATALOGUE)) {
    if (entry.slot === slot && entry.value === idOrValue) return { ...entry, id };
  }
  return null;
}

/**
 * Resolve a catalogue entry by ID **or by equipped value**.
 *
 * Both are needed because `ProfileStore.equip()` stores the item's `value` ('mint'), not its id
 * ('rider-hue-mint'), so an item equipped through the shop arrives here as 'mint' while one written by
 * hand or by a test arrives as the id. Accepting only the id meant a shop-equipped cosmetic silently
 * refused to render — exactly the "tests green, feature invisible" failure this module exists to prevent.
 * @param {string} idOrValue @returns {{kind:string,slot:string,value:string,id?:string}|null}
 */
export function cosmeticFor(idOrValue) {
  if (typeof idOrValue !== 'string' || !idOrValue) return null;
  const direct = CATALOGUE[idOrValue];
  if (direct) return { ...direct, id: idOrValue };
  for (const [id, entry] of Object.entries(CATALOGUE)) {
    // `value` is only unique within a slot ('cyan' is a trail, a glow and a theme), so a bare value returns
    // the first match. Callers that know the slot use cosmeticInSlot(), which the resolver does.
    if (entry.value === idOrValue) return { ...entry, id };
  }
  return null;
}

/**
 * Resolve a profile's equipped cosmetics into drawable colours.
 *
 * Pure. Returns hex strings because the entity-side callers convert to ints where they need to; the
 * palette is passed in both forms so this never reaches into Phaser or the content loader.
 *
 * @param {Object|null} profile the profile (may be absent / mid-migration)
 * @param {Object} palette the active palette as ints (0xRRGGBB)
 * @param {Object<string,string>} paletteHex the same palette as '#rrggbb' strings
 * @param {{colorblind?:boolean}} [o]
 * @returns {{rider:string, riderShape:string, glow:string, trail:string[], theme:string, danger:string,
 *            overridden:boolean, missing:string[]}}
 *   `riderShape` is 'default' (the neon rider) or a rider hue's `shape` ('drone'). A shape is drawn in the
 *   rider colour and palette keys only, so unlike a hue it survives the colourblind palette.
 */
export function resolveCosmetics(profile, palette, paletteHex, o = {}) {
  const hex = paletteHex || {};
  const colorblind = Boolean(o && o.colorblind);
  const equipped = (profile && profile.equipped && typeof profile.equipped === 'object') ? profile.equipped : {};

  // Pre-W4 defaults, straight off the palette, so an unequipped profile renders exactly as it used to.
  const base = {
    rider: hex.magenta,
    glow: hex.cyan,
    trail: [hex.cyan, hex.lime, hex.amber, hex.magenta],
    theme: 'default',
  };

  // The equipped rider's SHAPE (Micro glow-up). Resolved before the colourblind refusal on purpose: a shape
  // recolours nothing (the drone is drawn in the rider colour, which colourblind mode has already reset to
  // palette magenta, plus palette keys), so refusing it would only take away something the player earned.
  const riderEntry = cosmeticInSlot('rider', equipped.rider);
  const riderHue = riderEntry && COSMETIC_HUES.rider[riderEntry.value];
  base.riderShape = (riderHue && typeof riderHue.shape === 'string') ? riderHue.shape : 'default';

  if (colorblind) {
    return { ...base, danger: hex.danger, overridden: true, missing: [] };
  }

  const missing = [];
  const out = { ...base };

  /** Look up the equipped id for a slot, recording ids this build cannot draw. */
  const lookup = (slot) => {
    const id = equipped[slot];
    if (!id || id === 'default') return null;
    // Match within the slot: `equip()` writes a bare value ('mint'), so a value that exists in two slots
    // must resolve to the one this slot draws.
    const entry = cosmeticInSlot(slot, id);
    if (!entry) { missing.push(id); return null; }
    const hue = COSMETIC_HUES[entry.kind] && COSMETIC_HUES[entry.kind][entry.value];
    if (!hue) { missing.push(id); return null; }
    return { entry, hue };
  };

  const rider = lookup('rider');
  if (rider) out.rider = rider.hue.color;

  const glow = lookup('glow');
  if (glow) out.glow = glow.hue.color;

  const trail = lookup('trail');
  if (trail && Array.isArray(trail.hue.stops)) out.trail = trail.hue.stops.slice();

  // The theme name is reported for the UI to apply; it never recolours hazards, and in colourblind mode
  // it is refused above with everything else.
  const theme = lookup('theme');
  if (theme) out.theme = theme.entry.value;

  return { ...out, danger: hex.danger, overridden: false, missing };
}

/**
 * The UI palette with the profile's equipped theme laid over it (audit SHOP-5). Pure.
 *
 * ui/Theme.js calls this for every menu, panel and HUD painter, so a theme reaches everything that already
 * reads the UI palette. The world (terrain, hazards, the sled) is drawn from Palette.getPalette() by
 * RunScene and is never themed. Under a colourblind palette the theme is refused wholesale, the same rule
 * resolveCosmetics applies, and only UI_THEME_KEYS can move, so `danger` is untouchable here.
 *
 * @param {Object<string,string>} baseHex the active palette as '#rrggbb' strings
 * @param {Object|null} profile
 * @param {{colorblind?:boolean}} [o]
 * @returns {Object<string,string>} a new palette object (the input is never mutated)
 */
export function themedUiPalette(baseHex, profile, o = {}) {
  const out = { ...(baseHex || {}) };
  if (o && o.colorblind) return out;
  const eq = (profile && profile.equipped && typeof profile.equipped === 'object') ? profile.equipped : {};
  const entry = cosmeticInSlot('theme', eq.theme);
  const hue = entry && COSMETIC_HUES.theme[entry.value];
  const ui = hue && hue.ui;
  if (!ui) return out;
  for (const k of UI_THEME_KEYS) {
    if (typeof ui[k] === 'string' && /^#[0-9a-fA-F]{6}$/.test(ui[k])) out[k] = ui[k];
  }
  return out;
}

/**
 * The title a profile has equipped, as drawn text, or null for DEFAULT (audit SHOP-2). Pure.
 *
 * Callers show this in place of the level title, and the level title when it is null. An equipped value
 * this build does not know (a hand edit, a removed title) is null, so the badge falls back rather than
 * printing junk.
 * @param {Object|null} profile @returns {string|null}
 */
export function equippedTitle(profile) {
  const eq = (profile && profile.equipped && typeof profile.equipped === 'object') ? profile.equipped : {};
  const entry = cosmeticInSlot('title', eq.title);
  return entry ? entry.value : null;
}/**
 * OWNER: gameplay (readable-chaos pass, phase 3). Pure death legibility: who killed the run, how the hop was timed against
 * the ground telegraph's own ideal-hop window (HazardTelegraph GROUND_WARN, whose arrival is predicted with B3's predictX
 * for moving hazards), the Game Over header line, the crash beat schedule and the same-seed DIED HERE x.
 * No Phaser, no clock, no randomness. Everything here runs after a crash has been decided (RunScene.doCrash): nothing
 * feeds back into physics, score, the RunRecord, its ledger hash, the sim or biome discovery. The report travels in the
 * registry (REG.LAST_CRASH), never in the record.
 */
import { GROUND_WARN } from './HazardTelegraph.js';

/**
 * Crash beat (after the existing TUNING.hitStopCrashMs hit-stop): FX run at slowScale for slowMs, and the camera eases
 * in by zoomIn over the same time and holds it until Game Over. Visual only; the run clock is already stopped.
 */
export const CRASH_BEAT = Object.freeze({ slowMs: 400, slowScale: 0.25, hitStopScale: 0.08, zoomIn: 0.18 });

/** A hop older than this before the ideal window counts as no hop at all (ms). */
const NO_HOP_BEFORE_MS = 1000;

const CAUSE_NAMES = Object.freeze({ terrain: 'HEAD FIRST', badLanding: 'BAD LANDING', chasm: 'FELL INTO THE VOID', bsod: 'ERASED BY THE BSOD' });

const crashes = (def) => !!def && (!def.onHit || def.onHit.effect === 'crash');

/** "rollingBoulder" -> "ROLLING BOULDER". */
function idToName(id) {
  return String(id || '').replace(/([a-z0-9])([A-Z])/g, '$1 $2').replace(/[_-]+/g, ' ').trim().toUpperCase();
}

/**
 * The killer's name for the crash banner and the Game Over line. Only a def that crashes is ever named (blind, slow,
 * scramble never kill, so a Shatter Wall is never the killer); otherwise the cause names it.
 * @param {string} cause CRASH payload cause: 'hazard' | 'terrain' | 'badLanding' | 'chasm'.
 * @param {Object} [def] the hazard def for a hazard crash.
 * @returns {string}
 */
export function killerName(cause, def) {
  if (cause === 'hazard') {
    if (!crashes(def)) return 'CRASH';
    return def.name ? String(def.name).toUpperCase() : idToName(def.id) || 'CRASH';
  }
  return CAUSE_NAMES[cause] || 'CRASH';
}

/**
 * How the last hop sat against the ideal-hop window of the hazard that killed: the window is the telegraph's
 * (arrival - hopLeadMs .. + hopWindowMs, the sim oracle's rule).
 * @param {number|null|undefined} lastHopMs run time of the last executed hop.
 * @param {number} arrivalMs run time the sled reached the hazard (telegraph prediction, or the crash time).
 * @param {typeof GROUND_WARN} [t]
 * @returns {{kind:'none'|'early'|'late'|'onTime', s:number}} s = seconds outside the window, 2 decimals.
 */
export function hopTiming(lastHopMs, arrivalMs, t = GROUND_WARN) {
  const open = arrivalMs - t.hopLeadMs;
  const close = open + t.hopWindowMs;
  const r2 = (ms) => Math.round(ms / 10) / 100;
  if (!Number.isFinite(lastHopMs) || lastHopMs < open - NO_HOP_BEFORE_MS) return { kind: 'none', s: 0 };
  if (lastHopMs < open) return { kind: 'early', s: r2(open - lastHopMs) };
  if (lastHopMs > close) return { kind: 'late', s: r2(lastHopMs - close) };
  return { kind: 'onTime', s: 0 };
}

/** @param {{kind:string, s:number}} h @returns {string} */
export function verdictText(h) {
  if (!h || h.kind === 'none') return 'NO HOP';
  if (h.kind === 'onTime') return 'HOP WAS ON TIME';
  return `HOP WAS ${h.s.toFixed(2)} S ${h.kind === 'late' ? 'LATE' : 'EARLY'}`;
}

/**
 * @typedef {Object} CrashReportData  REG.LAST_CRASH (registry only).
 * @property {string|null} runId the run's id (RunRecord.id), so Game Over shows the line only for that run
 * @property {string} seed @property {number} biomeMask @property {number} x world px of the crash
 * @property {number} distM @property {string} cause @property {string|null} hazardId
 * @property {string} name killer name @property {string} verdict hop verdict ('' when not a hazard crash)
 * @property {string} line Game Over header line, e.g. "PACKET SPIKE AT 301 M - HOP WAS 0.21 S LATE".
 */

/**
 * @param {{runId?:string, seed:string, biomeMask?:number, cause:string, def?:Object, x:number, startX:number, pxPerMeter:number,
 *   lastHopMs?:number|null, arrivalMs?:number|null, crashMs:number}} o
 * @returns {CrashReportData}
 */
export function crashReport(o) {
  const name = killerName(o.cause, o.def);
  const isHazard = o.cause === 'hazard' && crashes(o.def);
  const arrival = Number.isFinite(o.arrivalMs) ? o.arrivalMs : o.crashMs;
  const verdict = isHazard ? verdictText(hopTiming(o.lastHopMs, arrival)) : '';
  const distM = Math.max(0, Math.floor((o.x - o.startX) / (o.pxPerMeter || 1)));
  return {
    runId: o.runId == null ? null : o.runId,
    seed: o.seed,
    biomeMask: o.biomeMask || 0,
    x: o.x,
    distM,
    cause: o.cause,
    hazardId: isHazard ? o.def.id : null,
    name,
    verdict,
    line: `${name} AT ${distM} M${verdict ? ` - ${verdict}` : ''}`,
  };
}

const smooth01 = (u) => { const c = u < 0 ? 0 : u > 1 ? 1 : u; return c * c * (3 - 2 * c); };

/**
 * @param {number} msSinceCrash real ms since the crash was decided.
 * @param {number} hitStopMs the existing crash hit-stop (TUNING.hitStopCrashMs).
 * @returns {{fxScale:number, zoomMul:number}}
 */
export function crashBeat(msSinceCrash, hitStopMs) {
  const t = Number.isFinite(msSinceCrash) ? msSinceCrash : 0;
  const fxScale = t < hitStopMs ? CRASH_BEAT.hitStopScale : t < hitStopMs + CRASH_BEAT.slowMs ? CRASH_BEAT.slowScale : 1;
  return { fxScale, zoomMul: 1 + CRASH_BEAT.zoomIn * smooth01((t - hitStopMs) / CRASH_BEAT.slowMs) };
}

/**
 * World x of the DIED HERE marker: the last crash, only on a retry of the same seed and mask.
 * @param {CrashReportData|null|undefined} lastCrash
 * @param {string} seed @param {number} [biomeMask]
 * @returns {number|null}
 */
export function deathMarkerX(lastCrash, seed, biomeMask) {
  if (!lastCrash || lastCrash.seed !== seed || (lastCrash.biomeMask || 0) !== (biomeMask || 0)) return null;
  return Number.isFinite(lastCrash.x) ? lastCrash.x : null;
}

/**
 * The Game Over header line for this record: only when the report is for this very run (same id) and it crashed.
 * @param {CrashReportData|null|undefined} lastCrash @param {{id?:string, cause?:string}|null|undefined} rec
 * @returns {string}
 */
export function gameOverLine(lastCrash, rec) {
  if (!lastCrash || !rec || rec.cause !== 'crash' || lastCrash.runId == null || lastCrash.runId !== rec.id) return '';
  return lastCrash.line || '';
}/**
 * Bitstream Bluffs — OFFICIAL DAILY DRAFT (equal-budget arcade competition).
 *
 * Versioned, independent from the permanent upgrade shop and Data Shard bank.
 * Every pilot may distribute the same 1,200 DRAFT CREDITS among the exact
 * ordinary permanent-upgrade curves, edit the build at will, and retain it
 * between visits. The budget applies to *all ranks combined*; it is not a
 * per-category allowance. Classic Daily remains a zero-upgrade contest.
 *
 * All values are source-defined and deterministic. Raising the budget or
 * revising costs MUST increment DRAFT_RULES_VERSION and change the board's
 * competitive identity, never reinterpret old ranked records.
 */
import {UPGRADE_CATALOG, UPGRADE_IDS, emptyUpgradeRanks,
  nextUpgradePrice, activeUpgradeRanks} from './PermanentUpgrades.js';

// v2 (2026-11-20): the three Shard Magnet upgrades joined the catalogue. A new version is a new board.
export const DRAFT_RULES_VERSION=2;
/** Draft catalogue: the shop's upgrades except any marked `draft: false` (rules v2: all ten). */
export const DRAFT_UPGRADES=UPGRADE_CATALOG.filter(u=>u.draft!==false);
const DRAFT_IDS=DRAFT_UPGRADES.map(u=>u.id);
export const DRAFT_BUDGET=1200;

/** Sum every rank's canonical shop price (no free ranks, no shard spending). */
export function draftCost(input){
  const raw=input&&typeof input==='object'&&!Array.isArray(input)?input:{};
  let spend=0;
  for(const id of DRAFT_IDS){
    const n=raw[id]??0;
    if(!Number.isSafeInteger(n)||n<0||n>DRAFT_BUDGET)return Infinity;
    for(let rank=0;rank<n;rank++){
      const price=nextUpgradePrice(id,rank);
      if(price===null)return Infinity;
      spend+=price;
      if(spend>DRAFT_BUDGET)return spend;
    }
  }
  return spend;
}

/** Only exact known positive integer ranks under the published budget rank. */
export function validDraftRanks(input){
  if(!input||typeof input!=='object'||Array.isArray(input))return false;
  // Known non-Draft upgrades (e.g. MAGNET PULL) may appear only at rank 0: a full rank sheet stays valid.
  if(Object.keys(input).some(k=>!DRAFT_IDS.includes(k)&&!(UPGRADE_IDS.includes(k)&&!input[k])))return false;
  return DRAFT_IDS.every(id=>input[id]===undefined||
    (Number.isSafeInteger(input[id])&&input[id]>=0))&&draftCost(input)<=DRAFT_BUDGET;
}

/** Normalize persisted settings safely without silently spending the player's bank. */
export function sanitizeDraftRanks(input){
  // Every known id keeps its key (profile shape is stable); non-Draft upgrades always stay 0.
  const out=emptyUpgradeRanks();
  if(!input||typeof input!=='object'||Array.isArray(input))return out;
  // Clamp rather than trust a wildly over-budget saved blob. The catalogue
  // order is stable, making the result deterministic and restart-safe.
  for(const id of DRAFT_IDS){
    const target=Number.isSafeInteger(input[id])&&input[id]>0?input[id]:0;
    for(let rank=0;rank<Math.min(target,DRAFT_BUDGET);rank++){
      const price=nextUpgradePrice(id,rank);
      if(price===null||draftCost({...out,[id]:rank+1})>DRAFT_BUDGET)break;
      out[id]=rank+1;
    }
  }
  return out;
}

/** Atomic draft edit calculation; never mutates input, no player currency. */
export function changeDraftRank(current,id,delta){
  if(!DRAFT_IDS.includes(id)||!Number.isSafeInteger(delta)||Math.abs(delta)!==1)
    return {ok:false,ranks:sanitizeDraftRanks(current),reason:'invalid-change'};
  const old=sanitizeDraftRanks(current);
  const next=Math.max(0,old[id]+delta);
  if(next===old[id])return {ok:false,ranks:old,reason:'at-zero'};
  const ranks={...old,[id]:next};
  if(!validDraftRanks(ranks))return {ok:false,ranks:old,reason:'over-budget'};
  return {ok:true,ranks,cost:draftCost(ranks),remaining:DRAFT_BUDGET-draftCost(ranks)};
}

/** The exact applied snapshot: no unknown names or unspent/purchased upgrades. */
export const draftActiveRanks=input=>activeUpgradeRanks(sanitizeDraftRanks(input));/**
 * OWNER: core-logic engineer. NO Phaser imports.
 * Public signatures are a contract - do not change without updating src/ARCHITECTURE.md.
 *
 * Daily patch rule (design doc section 6.2, stretch): one movement rule per UTC day, applies to EVERY run
 * that day; the rule id is stored on every RunRecord. The rule changes at 00:00 UTC: index = whole days since the
 * Unix epoch (UTC) modulo RULES.length, so every device agrees without any network.
 */

/**
 * Modifier keys PhysicsTuner understands. All are multipliers (default 1) applied to the base PHYSICS values.
 * @typedef {Object} DailyModifiers
 * @property {number} [tuckSpeedMul]      extra speed while tucked (e.g. 1.5 = +50%).
 * @property {number} [tuckSteerMul]      steering authority while tucked (e.g. 0.5 = -50%).
 * @property {number} [gravityMul]
 * @property {number} [frictionMul]
 * @property {number} [airControlMul]
 * @property {number} [pushForceMul]
 */

/**
 * @typedef {Object} DailyRule
 * @property {string} id            stable id, e.g. 'tuckBoost'.
 * @property {string} name          display name.
 * @property {string} description   one line for the UI.
 * @property {DailyModifiers} modifiers
 */

/**
 * @typedef {Object} DailyInfo
 * @property {string} dateKey  'YYYY-MM-DD' (UTC).
 * @property {DailyRule} rule
 * @property {string} seed     the daily seed string, `daily-${dateKey}`.
 */

const DAY_MS = 86400000;
/** infoForDateKey memo (pure answers, bounded). */
const INFO_CACHE = new Map();
const INFO_CACHE_MAX = 4096;

export class DailyPatch {
  /** All rules, order is stable (index = days since epoch % length). Append only: reordering changes history. @type {DailyRule[]} */
  static RULES = [
    {
      id: 'tuckBoost',
      name: 'Tuck Boost',
      description: 'Tuck grants +50% speed, but steering -50%.',
      modifiers: { tuckSpeedMul: 1.5, tuckSteerMul: 0.5 },
    },
    {
      id: 'heavyPackets',
      name: 'Heavy Packets',
      description: 'Gravity +25%: faster descents, shorter airtime.',
      modifiers: { gravityMul: 1.25 },
    },
    {
      id: 'featherweight',
      name: 'Featherweight',
      description: 'Gravity -20%: floaty jumps, but the sled pushes harder to stay on the ground.',
      modifiers: { gravityMul: 0.8, airControlMul: 0.9 },
    },
    {
      id: 'slickLines',
      name: 'Slick Lines',
      description: 'Friction -40% everywhere: fast and hard to stop.',
      modifiers: { frictionMul: 0.6 },
    },
    {
      id: 'stickyBits',
      name: 'Sticky Bits',
      description: 'Friction +50% but pushing off is twice as strong.',
      modifiers: { frictionMul: 1.5, pushForceMul: 2 },
    },
    {
      id: 'airDancer',
      name: 'Air Dancer',
      description: 'Air control +50% for easier tricks, tuck steering -25%.',
      modifiers: { airControlMul: 1.5, tuckSteerMul: 0.75 },
    },
    {
      id: 'stiffNeck',
      name: 'Stiff Neck',
      description: 'Air control -40%: tricks take commitment.',
      modifiers: { airControlMul: 0.6 },
    },
    {
      id: 'turboTuck',
      name: 'Turbo Tuck',
      description: 'Tuck grants +30% speed and friction -20%, but gravity +10%.',
      modifiers: { tuckSpeedMul: 1.3, frictionMul: 0.8, gravityMul: 1.1 },
    },
  ];

  /**
   * @param {Date} [date=new Date()] interpreted in UTC. An invalid Date falls back to "now".
   * @returns {DailyInfo}
   */
  static getDailyInfo(date = new Date()) {
    const d = date instanceof Date && !Number.isNaN(date.getTime()) ? date : new Date();
    const dateKey = d.toISOString().slice(0, 10);
    const dayNumber = Math.floor(d.getTime() / DAY_MS);
    const n = DailyPatch.RULES.length;
    const rule = DailyPatch.RULES[((dayNumber % n) + n) % n];
    return { dateKey, rule, seed: `daily-${dateKey}` };
  }

  /**
   * The daily run's biome mask (W3, D6). Derived from the UTC date key ALONE, by a pure function, so every
   * player runs the same mask on the same day regardless of what they have unlocked - that is the point
   * of D6: a locked biome may appear as a preview. Widening it with unlocks would make the daily
   * leaderboard compare different terrain for different players.
   *
   * Before CUTOVER_DATE_KEY the cycle is 9 days, indexed by the epoch day: 4 clear days (mask 0, the terrain
   * everyone knows) and one day for each batch-1 signature biome. Every past date keeps exactly that mask, so
   * past Daily records and practice replays of past dates stay valid.
   *
   * From CUTOVER_DATE_KEY (decision 5, Marvin 2026-11-16) the cycle is 15 days, indexed from the cutover
   * day: all 11 biomes once plus 4 clear days. The six W6 biomes premiere first, each followed by a clear day
   * until the last pair, then the batch-1 biomes.
   * @param {Date|number} [when=new Date()]
   * @returns {number} biome mask.
   */
  static biomeMaskForDate(when = new Date()) {
    const d = when instanceof Date ? when : new Date(typeof when === 'number' ? when : Date.now());
    const t = Number.isNaN(d.getTime()) ? Date.now() : d.getTime();
    const dayNumber = Math.floor(t / DAY_MS);
    const cutoverDay = Math.floor(Date.parse(`${DailyPatch.CUTOVER_DATE_KEY}T00:00:00Z`) / DAY_MS);
    if (dayNumber < cutoverDay) {
      const CYCLE_V1 = [0, 0, 0, 0, 1, 2, 4, 8, 16];
      return CYCLE_V1[((dayNumber % CYCLE_V1.length) + CYCLE_V1.length) % CYCLE_V1.length];
    }
    const CYCLE_V2 = [32, 0, 64, 0, 128, 0, 256, 0, 512, 1024, 1, 2, 4, 8, 16];
    return CYCLE_V2[(dayNumber - cutoverDay) % CYCLE_V2.length];
  }

  /** First UTC date of the 15-day, all-biome Daily rotation (decision 5). Dates before it keep the 9-day cycle. */
  static get CUTOVER_DATE_KEY() { return '2026-11-17'; }

  /**
   * @param {string} id
   * @returns {DailyRule|null}
   */
  static getRuleById(id) {
    return DailyPatch.RULES.find((r) => r.id === id) || null;
  }

  /**
   * Milliseconds until the next 00:00 UTC rule change (additive helper for a countdown on the title screen).
   * @param {Date} [date=new Date()]
   * @returns {number}
   */
  static msUntilNextRule(date = new Date()) {
    const t = date instanceof Date && !Number.isNaN(date.getTime()) ? date.getTime() : Date.now();
    return DAY_MS - (((t % DAY_MS) + DAY_MS) % DAY_MS);
  }

  /**
   * Additive helper: parse the UTC date key out of a daily seed.
   * @param {string} seed
   * @returns {string|null} 'YYYY-MM-DD' for a seed of the form `daily-YYYY-MM-DD`, else null.
   */
  static dateKeyFromSeed(seed) {
    const m = typeof seed === 'string' ? /^daily-(\d{4}-\d{2}-\d{2})$/.exec(seed) : null;
    if (!m) return null;
    const t = Date.parse(`${m[1]}T00:00:00.000Z`);
    return Number.isNaN(t) || new Date(t).toISOString().slice(0, 10) !== m[1] ? null : m[1];
  }

  /**
   * Additive helper (decisions 1/2): everything a given UTC date's Daily was, from its date key alone.
   * A practice run of a past date replays THAT date's rule and mask; the official surfaces use the same
   * answer to check a record really was played on the date's mask and rule. Pure.
   * @param {string} dateKey 'YYYY-MM-DD'
   * @returns {{dateKey:string, seed:string, rule:DailyRule, biomeMask:number}|null} null for a malformed key.
   */
  static infoForDateKey(dateKey) {
    if (typeof dateKey !== 'string') return null;
    // Memoised: the Daily surfaces ask once per stored run, and a device can hold thousands. The answer is
    // a pure function of the key, so the cache can never go stale; it is bounded and returns frozen objects.
    const hit = INFO_CACHE.get(dateKey);
    if (hit !== undefined) return hit;
    const k = DailyPatch.dateKeyFromSeed(`daily-${dateKey}`);
    let out = null;
    if (k) {
      // Noon UTC: well inside the day whatever the rounding, so the rule and the mask are that day's.
      const noon = new Date(Date.parse(`${k}T12:00:00.000Z`));
      const info = DailyPatch.getDailyInfo(noon);
      out = Object.freeze({ dateKey: k, seed: info.seed, rule: info.rule, biomeMask: DailyPatch.biomeMaskForDate(noon) });
    }
    if (INFO_CACHE.size >= INFO_CACHE_MAX) INFO_CACHE.clear();
    INFO_CACHE.set(dateKey, out);
    return out;
  }

  /**
   * Additive helper (decision 2): the label a run on this seed wears on the HUD and on Game Over.
   * An official Daily (started from the DAILY RUN menu item) is 'DAILY RUN'; any other run on a
   * `daily-YYYY-MM-DD` seed is a practice run, 'DAILY PRACTICE YYYY-MM-DD'; every other seed has none.
   * @param {string} seed @param {boolean} official
   * @returns {string}
   */
  static dailyRunLabel(seed, official) {
    const k = DailyPatch.dateKeyFromSeed(seed);
    if (!k) return '';
    return official === true ? 'DAILY RUN' : `DAILY PRACTICE ${k}`;
  }

  /**
   * Additive helper (decision 2, HUD): the in-run rule-line prefix. 'DAILY RUN' only for the official Daily,
   * 'DAILY PRACTICE <date>' for any other daily-YYYY-MM-DD seed, 'DAILY RULE' for every other seed.
   * @param {string|null|undefined} seed
   * @param {boolean|undefined} official
   * @returns {string}
   */
  static hudRuleLabel(seed, official) {
    return DailyPatch.dailyRunLabel(seed, official) || 'DAILY RULE';
  }

  /**
   * Additive helper (decision 2, HUD): the rule a run on this seed plays, the same answer RunScene gives.
   * A daily-YYYY-MM-DD seed plays that date's rule; every other seed plays today's. Pure for a given `now`.
   * @param {string|null|undefined} seed
   * @param {Date} [now]
   * @returns {string} rule id, or '' if none
   */
  static ruleIdForSeed(seed, now) {
    const k = DailyPatch.dateKeyFromSeed(seed);
    const info = k ? DailyPatch.infoForDateKey(k) : DailyPatch.getDailyInfo(now);
    return (info && info.rule && info.rule.id) || '';
  }

  /**
   * Additive helper: format a millisecond duration for the "NEXT PATCH IN" countdown, e.g. '3H 12M'.
   * Under one hour it reads '12M'; under one minute '<1M'. Rounds minutes up so the display never shows 0 early.
   * Non-finite or non-positive input gives '0M'.
   * @param {number} ms
   * @returns {string}
   */
  static formatCountdown(ms) {
    if (!Number.isFinite(ms) || ms <= 0) return '0M';
    const totalMin = Math.ceil(ms / 60000);
    if (ms < 60000) return '<1M';
    const h = Math.floor(totalMin / 60);
    const m = totalMin % 60;
    return h > 0 ? `${h}H ${m}M` : `${m}M`;
  }
}/** #79: offline inspection of stored GhostTape v1 poses, not a replay or event log. */
import { decodeTrace, GHOST_TAPE_FORMAT } from './ghost/GhostTape.js';
import { renderRunTraceArt } from './run-trace-art.js';

export const MAX_STRIP_FILE_BYTES = 2 * 1024 * 1024;
export const MAX_STRIP_POSES = 32_768;
export const MAX_STRIP_POINTS = 1_024;
export const MAX_STRIP_SVG_BYTES = 48 * 1024;

const COMPONENT_LIMIT = 1e9;
const CHARS_PER_POSE = 16; // v1: three Float32 components, twelve bytes, no base64 padding
const POSE_WIDTH = 3;
const TICKS_PER_SAMPLE = 4;
const TICKS_PER_SECOND = 120;
const PLOT = { x: 64, y: 127, w: 1072, h: 218 };

function readPoses(tape) {
  if (!tape || tape.format !== GHOST_TAPE_FORMAT || tape.version !== 1 ||
      (tape.simTickHz !== undefined && tape.simTickHz !== TICKS_PER_SECOND)) {
    throw new TypeError('Expected a supported GhostTape v1 file');
  }
  const encoded = tape.trace;
  if (typeof encoded !== 'string' || encoded.length < 2 * CHARS_PER_POSE ||
      encoded.length > MAX_STRIP_POSES * CHARS_PER_POSE ||
      encoded.length % CHARS_PER_POSE !== 0 || /[^A-Za-z0-9+/]/.test(encoded)) {
    throw new TypeError('Expected 2 to 32,768 complete GhostTape v1 poses');
  }
  const poses = decodeTrace({ trace: encoded });
  if (poses.length !== POSE_WIDTH * (encoded.length / CHARS_PER_POSE) ||
      !poses.every((v) => Number.isFinite(v) && Math.abs(v) <= COMPONENT_LIMIT)) {
    throw new RangeError('GhostTape poses must be complete, finite and within coordinate limits');
  }
  return poses;
}

function boundsAndIndices(poses, start, end, selected) {
  const size = end - start + 1;
  const exact = size <= MAX_STRIP_POINTS;
  // Bound the overview even with both endpoints and one non-extremal cursor pose.
  const bucketCount = exact ? size : Math.floor((MAX_STRIP_POINTS - 3) / 4);
  const indices = exact ? [] : [start];
  const bounds = [Infinity, Infinity, -Infinity, -Infinity];
  for (let bucket = 0; bucket < bucketCount; bucket++) {
    const a = exact ? start + bucket : start + 1 + Math.floor(bucket * (size - 2) / bucketCount);
    const b = exact ? a + 1 : start + 1 + Math.floor((bucket + 1) * (size - 2) / bucketCount);
    const extremes = [a, a, a, a];
    for (let i = a + 1; i < b; i++) {
      const x = poses[POSE_WIDTH * i], y = poses[POSE_WIDTH * i + 1];
      if (x < poses[POSE_WIDTH * extremes[0]]) extremes[0] = i;
      if (y < poses[POSE_WIDTH * extremes[1] + 1]) extremes[1] = i;
      if (x > poses[POSE_WIDTH * extremes[2]]) extremes[2] = i;
      if (y > poses[POSE_WIDTH * extremes[3] + 1]) extremes[3] = i;
    }
    if (!exact && selected !== null && selected >= a && selected < b) extremes.push(selected);
    // Keep extrema and the selected pose in trace order, not X order: a sled can backtrack.
    for (const i of new Set(extremes.sort((left, right) => left - right))) indices.push(i);
  }
  if (!exact) indices.push(end);
  // All X/Y extrema of the exact window occur on retained vertices.
  for (const i of indices) {
    const x = poses[POSE_WIDTH * i], y = poses[POSE_WIDTH * i + 1];
    bounds[0] = Math.min(bounds[0], x);
    bounds[1] = Math.min(bounds[1], y);
    bounds[2] = Math.max(bounds[2], x);
    bounds[3] = Math.max(bounds[3], y);
  }
  return { bounds, indices };
}

function createProjection(poses, [minX, minY, maxX, maxY]) {
  const spanX = maxX - minX, spanY = maxY - minY;
  // Equal units per SVG pixel on both axes, even for a flat or vertical trace.
  const scale = spanX || spanY ? Math.min(PLOT.w / spanX, PLOT.h / spanY) : 1;
  const left = PLOT.x + (PLOT.w - spanX * scale) / 2;
  const top = PLOT.y + (PLOT.h - spanY * scale) / 2;
  const quantize = (v) => Math.round(v * 100) / 100;
  return (index) => [
    quantize(left + (poses[POSE_WIDTH * index] - minX) * scale),
    quantize(top + (poses[POSE_WIDTH * index + 1] - minY) * scale),
  ];
}

function svgFor(poses, count, start, end, selected) {
  const { bounds, indices } = boundsAndIndices(poses, start, end, selected);
  const point = createProjection(poses, bounds);
  const path = indices.map((i, near) => `${near ? 'L' : 'M'}${point(i).join(' ')}`).join(' ');
  const [startX, startY] = point(start), [endX, endY] = point(end);
  const from = start + 1, to = end + 1, size = to - from + 1;
  const [selectedX, selectedY] = selected === null ? [0, 0] : point(selected);
  const cursor = selected === null ? '' :
    `<circle cx="${selectedX}" cy="${selectedY}" r="13" fill="none" stroke="#ffc977" stroke-width="2.4"/>`;
  const svg = `<svg xmlns="http://www.w3.org/2000/svg" width="1200" height="440" viewBox="0 0 1200 440" role="img" aria-labelledby="strip-title strip-desc">
<title id="strip-title">Bitstream Bluffs Downhill Run Strip</title>
<desc id="strip-desc">Recorded sled samples ${from} through ${to} of ${count}. Local, unverified pose trace only; no terrain or event data.</desc>
<defs>
  <linearGradient id="panel" x2="1" y2="1"><stop stop-color="#121e37"/><stop offset="1" stop-color="#1d1531"/></linearGradient>
  <linearGradient id="trace" gradientUnits="userSpaceOnUse" x1="64" x2="1136" y1="0" y2="0"><stop stop-color="#6af4ff"/><stop offset=".5" stop-color="#9ab2ff"/><stop offset="1" stop-color="#fda4f0"/></linearGradient>
  <pattern id="grid" width="46" height="36" patternUnits="userSpaceOnUse"><path d="M46 0H0V36" fill="none" stroke="#344763" stroke-width="1"/></pattern>
</defs>
<rect width="1200" height="440" rx="18" fill="#090f1d"/>
<rect x="13" y="13" width="1174" height="414" rx="15" fill="url(#panel)" stroke="#394864"/>
<rect x="47" y="107" width="1106" height="258" rx="11" fill="#0b1426" stroke="#374968"/>
<rect x="48" y="108" width="1104" height="256" rx="10" fill="url(#grid)"/>
<g font-family="system-ui,sans-serif">
  <text x="49" y="43" fill="#78eafa" font-size="13" font-weight="700" letter-spacing="2.4">BITSTREAM BLUFFS / TRACE V1</text>
  <text x="47" y="79" fill="#f0f5ff" font-weight="750" font-size="34">Downhill Run Strip</text>
  <rect x="910" y="38" width="243" height="37" rx="18.5" fill="#382149" stroke="#e696dc"/>
  <text x="1031.5" y="62" text-anchor="middle" fill="#ffd1f3" font-size="15" font-weight="700" letter-spacing="1.25">LOCAL / UNVERIFIED</text>
  <path d="${path}" fill="none" stroke="url(#trace)" stroke-opacity=".24" stroke-width="10" stroke-linejoin="round" stroke-linecap="round"/>
  <path d="${path}" fill="none" stroke="url(#trace)" stroke-width="3.2" stroke-linejoin="round" stroke-linecap="round"/>
  <circle cx="${startX}" cy="${startY}" r="8" fill="none" stroke="#6af4ff" stroke-width="2.6"/>
  <path d="M${endX} ${endY - 5}l5 5-5 5-5-5z" fill="#ffb8ea" stroke="#352044" stroke-width="1"/>
  ${cursor}
  <circle cx="58" cy="388" r="6" fill="none" stroke="#6af4ff" stroke-width="2"/>
  <text x="72" y="393" fill="#daecfc" font-size="14">${start === 0 ? 'Trace start' : 'Section start'} - sample ${from}</text>
  <path d="M299 382l6 6-6 6-6-6z" fill="#ffb8ea"/>
  <text x="315" y="393" fill="#daecfc" font-size="14">${end === count - 1 ? 'Trace end' : 'Section end'} - sample ${to}</text>
  <text x="1152" y="393" text-anchor="end" fill="#dfebfb" font-size="14">${indices.length} of ${size} window poses shown (${count} in trace)</text>
  <text x="49" y="415" fill="#a9b9d8" font-size="12">Recorded path only. Equal X/Y scale; +X right, +Y down. No terrain, events or replay claims.</text>
</g>
</svg>
`;
  if (svg.length > MAX_STRIP_SVG_BYTES) throw new RangeError('Strip SVG exceeded its byte limit');
  return svg;
}

/** Open bounded local JSON. Only validated pose geometry survives this call. */
export function openDownhillRunTrace(json) {
  if (typeof json !== 'string' || json.length > MAX_STRIP_FILE_BYTES ||
      new TextEncoder().encode(json).length > MAX_STRIP_FILE_BYTES) {
    throw new RangeError('Use one GhostTape JSON file no larger than 2 MiB');
  }
  let tape;
  try { tape = JSON.parse(json); }
  catch { throw new TypeError('Could not read GhostTape JSON'); }
  const poses = readPoses(tape), count = poses.length / POSE_WIDTH;
  // Expose neither the tape header nor mutable internal pose storage.
  const valid = (index) => Number.isInteger(index) && index >= 0 && index < count;
  return Object.freeze({
    count,
    // The artwork uses the full validated path, never the current strip window or the tape header.
    renderArt() {
      return renderRunTraceArt(poses);
    },
    sample(index) {
      if (!valid(index)) throw new RangeError('Choose a recorded sample');
      const tick = (index + 1) * TICKS_PER_SAMPLE;
      return { x: poses[POSE_WIDTH * index], y: poses[POSE_WIDTH * index + 1], tick,
        nominalSeconds: tick / TICKS_PER_SECOND };
    },
    render({ start = 0, end = count - 1, selected = null } = {}) {
      if (!valid(start) || !valid(end) || start >= end ||
          (selected !== null && (!valid(selected) || selected < start || selected > end))) {
        throw new RangeError('Choose a section of two or more recorded samples');
      }
      return svgFor(poses, count, start, end, selected);
    },
  });
}/**
 * OWNER: input/audio/glitch engineer. NO Phaser imports (pure, Jest-testable). Never emits events.
 * Public signatures are a contract - do not change without updating src/ARCHITECTURE.md.
 *
 * Seed-deterministic schedule of glitch events. The schedule depends ONLY on (seed, run-time, distance-based
 * frequency ramp) - never on wall clock or Math.random - so identical seeds glitch identically.
 * Gap between events: uniform in GLITCH.earlyGapMs early on, blending to GLITCH.lateGapMs as distance goes from
 * half of TERRAIN.difficultyRampStartM to the full value (so from 1000 m on the gaps are 3-6 s).
 * Duration 50-200 ms (GLITCH.durationMs). RunScene owns the instance, calls update() each frame and emits
 * EVT.GLITCH_START / EVT.GLITCH_END from the result (payload: id, kind, durationMs, intensity of the GlitchEvent).
 *
 * Determinism detail: every event consumes exactly five random numbers in a fixed order (gap, kind, duration,
 * intensity, pattern). Only the gap is later scaled by the distance blend, so with a fixed distance the schedule is
 * identical for a seed no matter how often update() is called.
 * The event id carries a seed-derived pattern tag (`g12-3fa9`) which GlitchPipeline uses for block layout.
 */
import { Rng } from './Rng.js';
import { GLITCH, TERRAIN } from '../constants.js';

/**
 * @typedef {Object} GlitchEvent
 * @property {string} id         e.g. 'g3-1a2b' (index + 4 hex digits of seed-derived pattern).
 * @property {'rgbSplit'|'scanlineWobble'|'stutter'|'dropout'|'static'} kind
 * @property {number} startMs    run-time ms when it starts.
 * @property {number} durationMs
 * @property {number} intensity  0..1
 */

/**
 * Blend factor 0 (early range) .. 1 (late range) for a distance.
 * @param {number} distanceM
 * @returns {number}
 */
export function glitchRamp(distanceM) {
  const r = TERRAIN.difficultyRampStartM;
  const t = (distanceM - r * 0.5) / (r * 0.5);
  return t <= 0 ? 0 : t >= 1 ? 1 : t * t * (3 - 2 * t);
}

/**
 * Gap range in ms for a distance.
 * @param {number} distanceM
 * @returns {[number, number]}
 */
export function glitchGapRange(distanceM) {
  const f = glitchRamp(distanceM);
  const e = GLITCH.earlyGapMs;
  const l = GLITCH.lateGapMs;
  return [e[0] + (l[0] - e[0]) * f, e[1] + (l[1] - e[1]) * f];
}

export class GlitchDirector {
  /** @param {{seed:string}} options */
  constructor(options) {
    this.seed = String(options && options.seed != null ? options.seed : '');
    this.reset();
  }

  /**
   * Draw the next event after `afterMs`.
   * @param {number} afterMs end time of the previous event (0 for the first).
   * @param {number} distanceM
   * @returns {GlitchEvent}
   * @private
   */
  _generate(afterMs, distanceM) {
    const rng = this.rng;
    const uGap = rng.next();
    const kind = GLITCH.kinds[Math.floor(rng.next() * GLITCH.kinds.length)];
    const uDur = rng.next();
    const uInt = rng.next();
    const pattern = Math.floor(rng.next() * 0xffff);
    const [lo, hi] = glitchGapRange(distanceM);
    const f = glitchRamp(distanceM);
    const d = GLITCH.durationMs;
    const n = this._count++;
    return {
      id: `g${n}-${pattern.toString(16).padStart(4, '0')}`,
      kind,
      startMs: Math.round(afterMs + lo + (hi - lo) * uGap),
      durationMs: Math.round(d[0] + (d[1] - d[0]) * uDur),
      intensity: Math.round((0.4 + 0.6 * uInt * (0.75 + 0.25 * f)) * 1000) / 1000,
    };
  }

  /**
   * Advance the schedule.
   * @param {number} runTimeMs run time excluding pauses.
   * @param {number} distanceM furthest distance so far (drives the frequency ramp).
   * @returns {{started: GlitchEvent[], ended: GlitchEvent[], active: GlitchEvent|null}}
   *          started/ended = transitions since the previous call (usually empty).
   */
  update(runTimeMs, distanceM) {
    const started = [];
    const ended = [];
    let guard = 0;
    while (guard++ < 64) {
      if (this.active && runTimeMs >= this.active.startMs + this.active.durationMs) {
        ended.push(this.active);
        this.active = null;
        continue;
      }
      if (!this.active && runTimeMs >= this.next.startMs) {
        const ev = this.next;
        this.active = ev;
        started.push(ev);
        this.next = this._generate(ev.startMs + ev.durationMs, distanceM);
        continue;
      }
      break;
    }
    return { started, ended, active: this.active };
  }

  /**
   * First `count` events of this seed's schedule at a fixed distance (does not touch live state). Test helper.
   * @param {number} count
   * @param {number} [distanceM=0]
   * @returns {GlitchEvent[]}
   */
  preview(count, distanceM = 0) {
    const d = new GlitchDirector({ seed: this.seed });
    const out = [d.next];
    while (out.length < count) {
      const last = out[out.length - 1];
      out.push(d._generate(last.startMs + last.durationMs, distanceM));
    }
    return out.slice(0, count);
  }

  /** Restart schedule from t=0 with the same seed. @returns {void} */
  reset() {
    this.rng = new Rng(this.seed).fork('glitch');
    this._count = 0;
    /** @type {GlitchEvent|null} */
    this.active = null;
    /** @type {GlitchEvent} */
    this.next = this._generate(0, 0);
  }
}/**
 * OWNER: gameplay engineer. Phaser-free and pure (no Math.random, no Date): unit-tested in tests/src/biome-b3-motion.test.js.
 *
 * B3 "Motion" (spec §4 / §5 `HazardDef.motion`): the math of the moving biome hazards. Hazard.js only CALLS these, and
 * TerrainGenerator uses `rollSweep` to keep a rolling hazard's whole track clear (placement rule). Every value is a
 * function of the def's `motion`, the spawn (its x and its seeded `phase`), the run time and the sled x.
 *
 * - `roll` {speedPxS, rangePx?, dir?} (Rolling Boulder, Dew Drop): the hazard waits at its spawn x until the sled comes
 *   within ROLL_ACTIVATE_PX behind it, then rolls along the ground for at most rangePx and rests there. B3 tuning
 *   (Marvin 2026-11-15): `dir` +1 (shipped, the default) rolls downhill, away from the sled, slower than it, so the sled
 *   slowly catches it (hop it or pass it), and a roll may gently overtake a slow or stopped sled; -1 rolls toward it.
 *   The speed follows the slope (rollTargetSpeed: a floor share of the cap on flat ground, the cap `speedPxS` on steep
 *   ground) and changes at ROLL_ACCEL_PX_S2 from rest. It is integrated on a fixed ROLL_STEP_MS grid counted from the
 *   start, over the ground the hazard rides, so the position is a pure function of the run time since the start and the
 *   terrain: the frame rate never changes where it is.
 * - `gate` {periodMs, openMs} (Gear Gate): open for openMs, closed for the rest of each period. The phase (0..1) is the
 *   gate's own draw from the 'biomeHaz' fork, stored on the spawn by the generator. A closed spell never lasts longer
 *   than GATE_MAX_CLOSED_MS, so a gate is never closed for the whole time it is on screen ahead of the sled.
 */

const clamp = (v, lo, hi) => (v < lo ? lo : v > hi ? hi : v);
const num = (v, d) => (Number.isFinite(v) ? v : d);

// ------------------------------------------------------------------------------------------------ roll

/** The sled must be this close (px, behind the spawn x) before a rolling hazard starts. It is on screen by then. */
export const ROLL_ACTIVATE_PX = 340;
/**
 * Bounds of a roll. B3 tuning (Marvin 2026-11-15): a roll goes downhill, away from the sled, slower than the sled, and a
 * roll that catches a slow or stopped sled from behind is a gentle overtake. `speedPxS` is the roll's cap (reached on
 * ground at least ROLL_FULL_SLOPE_DEG steep); ROLL_MAX_SPEED_PX_S keeps every cap under the stall net's restart speed
 * (TUNING.stallNudgeToPxS 130), so a sled the net restarts always outruns it.
 */
export const ROLL_DEFAULT_SPEED_PX_S = 100;
export const ROLL_MAX_SPEED_PX_S = 120;
export const ROLL_DEFAULT_RANGE_PX = 160;
export const ROLL_MAX_RANGE_PX = 200;
/** Share of the cap the roll keeps on flat or rising ground (it never stalls or rolls back). */
export const ROLL_FLOOR_SHARE = 0.4;
/** Slope (deg, downhill along the roll) at which the roll reaches its cap; linear from the floor below it. */
export const ROLL_FULL_SLOPE_DEG = 20;
/** The roll speeds up (from rest at the start) and slows down toward the slope's speed at this rate (px/s^2). */
export const ROLL_ACCEL_PX_S2 = 250;
/** Fixed integration step (ms), counted from the start of the roll: the frame rate never changes where it is. */
export const ROLL_STEP_MS = 10;

/**
 * @typedef {{activeAtMs:number|null, offsetPx:number, vPxS:number, simMs:number, simDist:number, simV:number}} RollState
 * activeAtMs = run time the roll started; offsetPx = signed x offset from the spawn now; vPxS = signed x speed now (a
 * telegraph's closing speed is sled speed - vPxS). simMs / simDist / simV: the last fixed-step grid point (ms since the
 * start, distance rolled, speed), so each step only integrates the new grid points.
 */

/** @returns {RollState} */
export function emptyRollState() {
  return { activeAtMs: null, offsetPx: 0, vPxS: 0, simMs: 0, simDist: 0, simV: 0 };
}

/**
 * Roll cap, range and direction of a `motion` block, clamped to the bounds. `dir` +1 (the default) rolls downhill, away
 * from the sled; -1 rolls toward it.
 * @param {{speedPxS?:number, rangePx?:number, dir?:number}|null|undefined} motion
 * @returns {{speedPxS:number, rangePx:number, dir:number}}
 */
export function rollParams(motion) {
  const m = motion || {};
  return {
    speedPxS: clamp(num(m.speedPxS, ROLL_DEFAULT_SPEED_PX_S), 0, ROLL_MAX_SPEED_PX_S),
    rangePx: clamp(num(m.rangePx, ROLL_DEFAULT_RANGE_PX), 0, ROLL_MAX_RANGE_PX),
    dir: num(m.dir, 1) < 0 ? -1 : 1,
  };
}

/**
 * The speed (px/s, >= 0) a roll heads for on ground of this slope ("fake but fun" physics): ROLL_FLOOR_SHARE of the cap
 * on flat or rising ground, the cap from ROLL_FULL_SLOPE_DEG down, linear between. The slope is read along the roll's
 * own direction (deg, + = y down, the generator's slopeDegAt).
 * @param {Object|null|undefined} motion @param {number} slopeDeg @returns {number}
 */
export function rollTargetSpeed(motion, slopeDeg) {
  const p = rollParams(motion);
  const down = clamp((num(slopeDeg, 0) * p.dir) / ROLL_FULL_SLOPE_DEG, 0, 1);
  return p.speedPxS * (ROLL_FLOOR_SHARE + (1 - ROLL_FLOOR_SHARE) * down);
}

/**
 * x span (relative to the spawn x) a hazard with this motion can occupy. Not moving along x: {lo: 0, hi: 0}.
 * @param {{kind?:string}|null|undefined} motion
 * @returns {{lo:number, hi:number}}
 */
export function rollSweep(motion) {
  if (!motion || motion.kind !== 'roll') return { lo: 0, hi: 0 };
  const p = rollParams(motion);
  return p.dir < 0 ? { lo: -p.rangePx, hi: 0 } : { lo: 0, hi: p.rangePx };
}

/**
 * Advance a roll's grid state to `msActive` ms after its start (pure; returns new numbers). Each ROLL_STEP_MS step reads
 * the slope at the hazard's x, moves the speed toward rollTargetSpeed by at most ROLL_ACCEL_PX_S2, and moves the hazard
 * by the step's mean speed (trapezoid), stopping at the end of the range. Between grid points the hazard moves on at
 * the grid speed.
 */
function advance(motion, sim, msActive, slopeFn, x0) {
  const p = rollParams(motion);
  const slope = typeof slopeFn === 'function' ? slopeFn : () => 0;
  let { simMs, simDist, simV } = sim;
  if (!(msActive >= simMs)) { simMs = 0; simDist = 0; simV = 0; }
  const dt = ROLL_STEP_MS / 1000;
  const dvMax = ROLL_ACCEL_PX_S2 * dt;
  while (simMs + ROLL_STEP_MS <= msActive && simDist < p.rangePx) {
    const vt = rollTargetSpeed(motion, slope(x0 + p.dir * simDist));
    const v1 = simV + clamp(vt - simV, -dvMax, dvMax);
    simDist += ((simV + v1) / 2) * dt;
    simV = v1;
    simMs += ROLL_STEP_MS;
    if (simDist >= p.rangePx) { simDist = p.rangePx; simV = 0; }
  }
  if (simDist >= p.rangePx) simMs = Math.max(simMs, Math.floor(msActive / ROLL_STEP_MS) * ROLL_STEP_MS);
  const dist = Math.min(p.rangePx, simDist + (simV * Math.max(0, msActive - simMs)) / 1000);
  return { simMs, simDist, simV, offsetPx: p.dir * dist, vPxS: dist >= p.rangePx ? 0 : p.dir * simV };
}

/**
 * Signed x offset from the spawn x after rolling for `msActive` ms (0 before the start) over the ground `slopeFn`
 * (x -> slope deg; missing = flat) from spawn x `x0`.
 * @param {Object|null|undefined} motion @param {number} msActive @param {(x:number)=>number} [slopeFn] @param {number} [x0]
 * @returns {number}
 */
export function rollOffsetAt(motion, msActive, slopeFn, x0 = 0) {
  if (!motion || !(msActive > 0)) return 0;
  return advance(motion, { simMs: 0, simDist: 0, simV: 0 }, msActive, slopeFn, num(x0, 0)).offsetPx;
}

/**
 * One step of a rolling hazard. Starts the roll on the first step at which the sled is within ROLL_ACTIVATE_PX behind
 * the spawn x (`sledX >= x0 - ROLL_ACTIVATE_PX`); afterwards only the run time and the ground matter. Does not mutate
 * `state`.
 * @param {RollState|null|undefined} state
 * @param {Object} motion the def's `motion`
 * @param {number} x0 spawn x (world px)
 * @param {number} sledX
 * @param {number} tMs run time (ms)
 * @param {(x:number)=>number} [slopeFn] ground slope (deg) at x: the surface the hazard rides (missing = flat)
 * @returns {RollState}
 */
export function rollStep(state, motion, x0, sledX, tMs, slopeFn) {
  const s = state || emptyRollState();
  let at = Number.isFinite(s.activeAtMs) ? s.activeAtMs : null;
  if (at === null && Number.isFinite(sledX) && sledX >= x0 - ROLL_ACTIVATE_PX) at = num(tMs, 0);
  if (at === null) return emptyRollState();
  const sim = { simMs: num(s.simMs, 0), simDist: num(s.simDist, 0), simV: num(s.simV, 0) };
  const r = advance(motion, sim, Math.max(0, num(tMs, 0) - at), slopeFn, x0);
  return { activeAtMs: at, offsetPx: r.offsetPx, vPxS: r.vPxS, simMs: r.simMs, simDist: r.simDist, simV: r.simV };
}

/**
 * Where a rolling hazard will be at run time `tMs`, from its current state (a telegraph's prediction; the same
 * integration as rollStep). A roll that has not started waits at its spawn x.
 * @param {RollState} state @param {Object} motion @param {number} x0 @param {number} tMs
 * @param {(x:number)=>number} [slopeFn] @returns {number}
 */
export function rollPredictX(state, motion, x0, tMs, slopeFn) {
  const at = state && Number.isFinite(state.activeAtMs) ? state.activeAtMs : null;
  if (at === null) return x0;
  return x0 + rollStep(state, motion, x0, x0, tMs, slopeFn).offsetPx;
}

// ------------------------------------------------------------------------------------------------ gate

/** An open spell is at least this long: at 1.2x the top expected speed (840 px/s) the sled crosses a gate in < 0.1 s. */
export const GATE_MIN_OPEN_MS = 400;
/**
 * A closed spell is at most this long. Measured in the built game (B2 view probe): at 800 px/s about 0.56 s of ground is
 * on screen ahead of the sled, so a gate always opens at least once between entering the screen and being reached.
 */
export const GATE_MAX_CLOSED_MS = 500;
export const GATE_MIN_CLOSED_MS = 100;
const GATE_DEFAULT = { periodMs: 1400, openMs: 900 };

/**
 * Period, open and closed time of a `gate` motion, inside the bounds (closedMs = periodMs - openMs).
 * @param {{periodMs?:number, openMs?:number}|null|undefined} motion
 * @returns {{periodMs:number, openMs:number, closedMs:number}}
 */
export function gateTiming(motion) {
  const m = motion || {};
  const openMs = Math.max(GATE_MIN_OPEN_MS, num(m.openMs, GATE_DEFAULT.openMs));
  const periodRaw = num(m.periodMs, GATE_DEFAULT.periodMs);
  const closedMs = clamp(periodRaw - openMs, GATE_MIN_CLOSED_MS, GATE_MAX_CLOSED_MS);
  return { periodMs: openMs + closedMs, openMs, closedMs };
}

/** Position inside the cycle (ms, [0, period)) at run time tMs with phase (0..1). */
function cycleMs(motion, phase, tMs) {
  const { periodMs } = gateTiming(motion);
  const u = num(tMs, 0) + clamp(num(phase, 0), 0, 1) * periodMs;
  return ((u % periodMs) + periodMs) % periodMs;
}

/**
 * Is the gate open at run time tMs? Each cycle starts open.
 * @param {Object} motion @param {number} phase the spawn's seeded phase (0..1) @param {number} tMs @returns {boolean}
 */
export function gateOpenAt(motion, phase, tMs) {
  return cycleMs(motion, phase, tMs) < gateTiming(motion).openMs;
}

/**
 * ms until the gate next opens or closes (a telegraph's countdown).
 * @param {Object} motion @param {number} phase @param {number} tMs @returns {number}
 */
export function gateNextChangeMs(motion, phase, tMs) {
  const { periodMs, openMs } = gateTiming(motion);
  const c = cycleMs(motion, phase, tMs);
  return c < openMs ? openMs - c : periodMs - c;
}/**
 * OWNER: gameplay (readable-chaos pass). Pure scheduling for the ground-hazard telegraph: which ground hazards are
 * announced before they enter the view, in which colour, when the chevron goes lime ("hop now"), and which sounds play
 * once. No Phaser, no window, no randomness, no clock: RunScene feeds it the live hazards and the sled, and
 * entities/GroundTelegraph.js draws the marks it returns. Nothing here touches physics, terrain, score or the record.
 *
 * Why: measured on the built game (scratchpad fable-10x/PICK.md), a ground hazard first appeared on screen ~481 px ahead,
 * a median 0.85 s (p10 0.67 s) before the sled reached it, and the hop has to be pressed ~0.38 s out. The marks are
 * time-based (about GROUND_WARN.leadS of travel), so the warning no longer shrinks as the sled speeds up.
 */

/**
 * Telegraph tuning. Kept here (not in PhysicsTuner.TUNING): it is UI timing, not physics.
 *  - leadS / minPx / maxPx: a hazard is announced when it is within speed x leadS px, clamped. maxPx gives 1.33 s at
 *    1200 px/s. Terrain is generated TERRAIN.bufferAheadScreens = 3 screens = 1440 px ahead (to the end of that chunk),
 *    so above ~720 px/s a hazard is announced as soon as its chunk exists; measured minimum lead 1.67 s.
 *  - hopLeadMs / hopWindowMs / minVxPxS: the sim hop oracle's rule (tools/sim/browser.js policies.hop): hop when the box
 *    centre is hopLeadMs away, down to hopWindowMs later.
 *  - maxMarks: nearest N hazards are planned (late-game density is ~4.5 ground hazards per maxPx).
 *  - warnGapMs: at most one warn sound per this long (events are never dropped, only the sound).
 *  - clearMarginPx: an airborne sled forecast to land this far past the box is "clear" of it.
 *  - arrivalHorizonMs / arrivalStepMs: a moving hazard's arrival is searched this far ahead, in steps this long, then
 *    refined by bisection (predictArrival).
 *  - gateMarginMs: a gate (B3 Gear Gate) counts as open at arrival only if it is open from this long before the predicted
 *    arrival to this long after it. It covers the crossing (~30 ms) and the drift of a 1 to 2 s estimate while the speed
 *    changes, and 2x it fits inside the 900 ms open spell.
 */
export const GROUND_WARN = Object.freeze({
  leadS: 2.0,
  minPx: 700,
  maxPx: 1600,
  hopLeadMs: 380,
  hopWindowMs: 250,
  minVxPxS: 60,
  maxMarks: 6,
  warnGapMs: 220,
  clearMarginPx: 60,
  arrivalHorizonMs: 4000,
  arrivalStepMs: 20,
  gateMarginMs: 150,
});

const clamp = (v, lo, hi) => (v < lo ? lo : v > hi ? hi : v);

/**
 * What the player should do about a hazard def: 'hop' (it crashes the sled), 'brace' (it slows / scrambles / otherwise
 * hinders, hopping is optional), or null (air hazards have their own telegraph, entities/AirTelegraph.js).
 * @param {import('../data/schemas.js').HazardDef|null|undefined} def
 * @returns {'hop'|'brace'|null}
 */
export function hazardResponse(def) {
  if (!def || def.placement === 'air') return null;
  return !def.onHit || def.onHit.effect === 'crash' ? 'hop' : 'brace';
}

/**
 * How far ahead (world px) a ground hazard is announced at this speed.
 * @param {number} speedPxS
 * @param {typeof GROUND_WARN} [t]
 * @returns {number}
 */
export function warnDistancePx(speedPxS, t = GROUND_WARN) {
  const s = Number.isFinite(speedPxS) ? speedPxS : 0;
  return clamp(s * t.leadS, t.minPx, t.maxPx);
}

/**
 * True while a hop pressed now puts the apex over the box: the exact rule of the sim's hop oracle.
 * @param {number} dx hazard centre minus sled x (px).
 * @param {number} vx sled horizontal speed (px/s).
 * @param {typeof GROUND_WARN} [t]
 * @returns {boolean}
 */
export function inHopWindow(dx, vx, t = GROUND_WARN) {
  if (!(dx > 0)) return false;
  const v = Math.max(vx, t.minVxPxS);
  const etaMs = dx / v * 1000;
  return etaMs <= t.hopLeadMs && etaMs > t.hopLeadMs - t.hopWindowMs;
}

/**
 * True while a hop pressed now puts the apex over the box, from the time to arrival (ms): the oracle's rule in time.
 * @param {number} etaMs
 * @param {typeof GROUND_WARN} [t]
 * @returns {boolean}
 */
export function inHopWindowMs(etaMs, t = GROUND_WARN) {
  return etaMs > 0 && etaMs <= t.hopLeadMs && etaMs > t.hopLeadMs - t.hopWindowMs;
}

/**
 * When the sled (at constant horizontal speed) reaches a hazard's box centre. A hazard with `predictX(tMs)` (B3: Hazard
 * entity, systems/HazardMotion.js) is timed with it: its centre at run time now + tau is cx + predictX(now + tau) -
 * predictX(now) (predictX gives the ground x, the centre may sit off it on a slope). Nothing here assumes which way, how
 * fast or how far a hazard moves. Without predictX, without nowMs, or when predictX does not change between now and the
 * static arrival, the answer is exactly dx / vx (the sim oracle's rule).
 * Known limit: Hazard.predictX treats a roll that has not started as resting at its spawn point; it starts when the sled
 * is ROLL_ACTIVATE_PX (340 px) behind it, and from that frame on the estimate is exact.
 * @param {{cx:number, predictX?:(tMs:number)=>number}} h
 * @param {{x:number, vx:number}} sled
 * @param {number|undefined} nowMs run time (the time base of predictX).
 * @param {typeof GROUND_WARN} [t]
 * @returns {{etaMs:number, cxAtArrival:number}} etaMs Infinity when the sled does not catch it within the horizon.
 */
export function predictArrival(h, sled, nowMs, t = GROUND_WARN) {
  const vx = Math.max(sled.vx, t.minVxPxS);
  const dx = h.cx - sled.x;
  const staticEta = dx / vx * 1000;
  if (typeof h.predictX !== 'function' || !Number.isFinite(nowMs)) return { etaMs: staticEta, cxAtArrival: h.cx };
  const p0 = h.predictX(nowMs);
  if (!Number.isFinite(p0)) return { etaMs: staticEta, cxAtArrival: h.cx };
  const cxAt = (tau) => h.cx + h.predictX(nowMs + tau) - p0;
  if (cxAt(staticEta) === h.cx && cxAt(staticEta / 2) === h.cx) return { etaMs: staticEta, cxAtArrival: h.cx };
  const gap = (tau) => cxAt(tau) - (sled.x + vx * tau / 1000);
  if (!(gap(0) > 0)) return { etaMs: 0, cxAtArrival: cxAt(0) };
  let lo = 0;
  let hi = null;
  for (let tau = t.arrivalStepMs; tau <= t.arrivalHorizonMs; tau += t.arrivalStepMs) {
    if (gap(tau) <= 0) { hi = tau; break; }
    lo = tau;
  }
  if (hi === null) return { etaMs: Infinity, cxAtArrival: h.cx };
  for (let i = 0; i < 14; i++) {
    const mid = (lo + hi) / 2;
    if (gap(mid) > 0) lo = mid; else hi = mid;
  }
  return { etaMs: hi, cxAtArrival: cxAt(hi) };
}

/**
 * B3 Gear Gate verdict at the predicted arrival: 'open' when `isPassable` holds from gateMarginMs before arrivalMs and
 * the next change is more than 2 x gateMarginMs after that (so open across the whole margin), else 'closed'. null for
 * a hazard without the gate API or without an arrival.
 * @param {{isPassable?:(t:number)=>boolean, gateNextChangeMs?:(t:number)=>number|null}} h
 * @param {number} arrivalMs run time.
 * @param {typeof GROUND_WARN} [t]
 * @returns {'open'|'closed'|null}
 */
export function gateVerdict(h, arrivalMs, t = GROUND_WARN) {
  if (typeof h.isPassable !== 'function' || typeof h.gateNextChangeMs !== 'function') return null;
  if (h.gateNextChangeMs(0) == null) return null; // not a gate (Hazard.gateNextChangeMs is null for anything else)
  if (!Number.isFinite(arrivalMs)) return 'closed';
  const from = arrivalMs - t.gateMarginMs;
  return h.isPassable(from) && h.gateNextChangeMs(from) > 2 * t.gateMarginMs ? 'open' : 'closed';
}

/**
 * @typedef {Object} TelegraphMark
 * @property {Object} ref the hazard object passed in (identity is the mark's key).
 * @property {'hop'|'brace'} kind
 * @property {'warn'|'go'|'clear'|'open'} state 'go' = inside the hop window; 'clear' = the sled is flying over it;
 *   'open' = a Gear Gate that will be open when the sled gets there (drawn dim, silent, never lime).
 * @property {'danger'|'amber'|'lime'} color palette key: red = hop, amber = brace, lime = hop now.
 * @property {boolean} clear draw dim, play nothing.
 * @property {number} dx px from the sled to the box centre.
 * @property {number} etaS seconds to the box centre at the current horizontal speed (moving hazards: predicted with
 *   predictArrival; Infinity when the sled will not catch it).
 * @property {number|null} arrivalMs run time of the predicted arrival (null without opts.nowMs).
 * @property {'open'|'closed'|null} gate Gear Gate verdict at arrival (gateVerdict); null for anything else.
 * @property {number} urgency 0 at the warn distance .. 1 at the box.
 */

/**
 * Plan this frame's semantic marks without a viewport. The current camera decides where to draw them later.
 * @param {Iterable<{def:Object, cx:number, w:number, hit?:boolean}>} hazards live hazards (Hazard entities or plain objects).
 * @param {{x:number, vx:number, speed:number, grounded:boolean, landX?:number|null}} sled landX = ballistic touchdown x while airborne.
 * @param {{isMuted?:(h:Object)=>boolean, nowMs?:number}} [opts] isMuted: hazards that currently do nothing (warded) are
 *   skipped. nowMs: run time, needed to time moving hazards (predictX) and judge gates; without it all are static.
 * @param {typeof GROUND_WARN} [t]
 * @returns {TelegraphMark[]} nearest first, at most t.maxMarks.
 */
export function planTelegraphMarks(hazards, sled, opts = {}, t = GROUND_WARN) {
  const warn = warnDistancePx(sled.speed, t);
  const vx = Math.max(sled.vx, t.minVxPxS);
  const flying = !sled.grounded && Number.isFinite(sled.landX);
  const marks = [];
  for (const h of hazards) {
    if (!h || h.hit) continue;
    const kind = hazardResponse(h.def);
    if (!kind) continue;
    const dx = h.cx - sled.x;
    if (!(dx > 0) || dx > warn) continue;
    if (opts.isMuted && opts.isMuted(h)) continue;
    const half = (h.w || 0) / 2;
    const arr = predictArrival(h, sled, opts.nowMs, t);
    const arrivalMs = Number.isFinite(opts.nowMs) ? opts.nowMs + arr.etaMs : null;
    const gate = Number.isFinite(opts.nowMs) ? gateVerdict(h, arrivalMs, t) : null;
    const clear = flying && sled.landX > arr.cxAtArrival + half + t.clearMarginPx;
    const open = !clear && gate === 'open';
    const go = !clear && !open && kind === 'hop' && sled.grounded && inHopWindowMs(arr.etaMs, t);
    marks.push({
      ref: h,
      kind,
      state: clear ? 'clear' : open ? 'open' : go ? 'go' : 'warn',
      color: go ? 'lime' : kind === 'hop' ? 'danger' : 'amber',
      clear,
      dx,
      etaS: arr.etaMs / 1000,
      arrivalMs,
      gate,
      urgency: clamp(1 - dx / warn, 0, 1),
    });
  }
  marks.sort((a, b) => a.dx - b.dx);
  if (marks.length > t.maxMarks) marks.length = t.maxMarks;
  return marks;
}

/** Keep the former explicit-horizon hint for historical diagnostics. Live planning and rendering do not use it. */
export function planTelegraph(hazards, sled, viewRight, opts = {}, t = GROUND_WARN) {
  return planTelegraphMarks(hazards, sled, opts, t).map((mark) => ({
    ...mark, onScreen: mark.ref.cx - (mark.ref.w || 0) / 2 < viewRight,
  }));
}

/** Version of the TelegraphTracker snapshot layout. */
export const TRACKER_SNAPSHOT_VERSION = 1;

/**
 * Remembers which hazards were already announced so each sound plays once. One per run.
 *
 * State is plain data keyed by the stable hazard id (`Hazard.hid`, `${chunk.index}:${spawn ordinal}`, assigned in
 * RunScene.takeChunk), never by object identity, so snapshot()/restore() carry it across a savestate and a restored game
 * (hazards rebuilt from chunk data) neither re-warns nor re-stamps. Issue #119 Phase 2.
 */
export class TelegraphTracker {
  /** @param {typeof GROUND_WARN} [t] */
  constructor(t = GROUND_WARN) {
    this.t = t;
    /** @type {Map<string, {warned:number|null, cued:boolean, arrival:number|null}>} hazard id -> state. */
    this._h = new Map();
    this._lastWarnSoundMs = -1e9;
  }

  /** @param {Object|string} ref hazard (or its id). @returns {string} */
  static idOf(ref) {
    const id = typeof ref === 'string' ? ref : ref && ref.hid;
    if (typeof id !== 'string' || !id) throw new Error('TelegraphTracker: hazard has no stable id (hid)');
    return id;
  }

  _entry(id) {
    let e = this._h.get(id);
    if (!e) { e = { warned: null, cued: false, arrival: null }; this._h.set(id, e); }
    return e;
  }

  /**
   * @param {number} nowMs run time.
   * @param {TelegraphMark[]} marks this frame's plan.
   * @returns {Array<{type:'warn'|'go', kind:'hop'|'brace', ref:Object, sound:boolean}>} 'warn' when a hazard is first
   *   announced (sound false when another warn sounded under warnGapMs ago), 'go' when it first enters the hop window.
   */
  update(nowMs, marks) {
    const events = [];
    for (const m of marks) {
      const id = TelegraphTracker.idOf(m.ref);
      if (Number.isFinite(m.arrivalMs)) this._entry(id).arrival = m.arrivalMs;
      if (m.clear || m.state === 'open') continue;
      const e = this._entry(id);
      if (e.warned === null) {
        e.warned = nowMs;
        const sound = nowMs - this._lastWarnSoundMs >= this.t.warnGapMs;
        if (sound) this._lastWarnSoundMs = nowMs;
        events.push({ type: 'warn', kind: m.kind, ref: m.ref, sound });
      }
      if (m.state === 'go' && !e.cued) {
        e.cued = true;
        events.push({ type: 'go', kind: m.kind, ref: m.ref, sound: true });
      }
    }
    return events;
  }

  /**
   * The latest planned arrival for a hazard (crash report: the ideal-hop window of the hazard that killed).
   * @param {Object|string} ref hazard. @returns {number|null} run time (ms), or null if it was never planned with a run time.
   */
  lastArrivalMs(ref) {
    const e = this._h.get(TelegraphTracker.idOf(ref));
    return e && e.arrival !== null ? e.arrival : null;
  }

  /** @param {Object|string} ref hazard. @returns {number|null} run time (ms) it was first announced, or null. */
  firstWarnMs(ref) {
    const e = this._h.get(TelegraphTracker.idOf(ref));
    return e && e.warned !== null ? e.warned : null;
  }

  /** Forget a dropped chunk's hazards (ids `${chunkIndex}:*`), so the state stays bounded like the old WeakMaps were. */
  forgetChunk(chunkIndex) {
    const prefix = `${chunkIndex}:`;
    for (const id of [...this._h.keys()]) if (id.startsWith(prefix)) this._h.delete(id);
  }

  /** @returns {{v:number, lastWarnSoundMs:number, hazards:Array<[string, number|null, boolean, number|null]>}} plain JSON data, id-sorted. */
  snapshot() {
    const hazards = [...this._h].sort((a, b) => (a[0] < b[0] ? -1 : a[0] > b[0] ? 1 : 0))
      .map(([id, e]) => [id, e.warned, e.cued, e.arrival]);
    return { v: TRACKER_SNAPSHOT_VERSION, lastWarnSoundMs: this._lastWarnSoundMs, hazards };
  }

  /**
   * Replace state only after validating the complete snapshot. Rejected/corrupt
   * data must not leave a partially restored game (or silently erase warnings).
   * @param {ReturnType<TelegraphTracker['snapshot']>} snap
   */
  restore(snap) {
    if (!snap || snap.v !== TRACKER_SNAPSHOT_VERSION || !Array.isArray(snap.hazards) ||
        !Number.isFinite(snap.lastWarnSoundMs)) {
      throw new Error('TelegraphTracker.restore: unsupported or invalid snapshot');
    }
    const next = new Map();
    for (const record of snap.hazards) {
      if (!Array.isArray(record) || record.length !== 4) {
        throw new Error('TelegraphTracker.restore: invalid hazard snapshot entry');
      }
      const [id, warned, cued, arrival] = record;
      if (typeof id !== 'string' || !id ||
          (warned !== null && !Number.isFinite(warned)) ||
          typeof cued !== 'boolean' ||
          (arrival !== null && !Number.isFinite(arrival))) {
        throw new Error('TelegraphTracker.restore: invalid hazard snapshot entry');
      }
      if (next.has(id)) throw new Error('TelegraphTracker.restore: duplicate hazard id');
      next.set(id, { warned, cued, arrival });
    }
    this._h = next;
    this._lastWarnSoundMs = snap.lastWarnSoundMs;
  }
}/**
 * First-run tutorial hint scheduler (pure, Phaser-free).
 *
 * One hint is on screen at a time. Every frame the scene tells the scheduler which hints currently have their trigger
 * condition (`wants`), and gets back the show / hide transitions to emit. Rules:
 *  - a hint that is up stays at least `minMs` (readable) unless the player performs the action (`complete`);
 *  - it hides once its trigger is gone (after `minMs`) and always after `maxMs` (it never gets stuck); a hint that timed
 *    out must see its trigger go false before it can show again;
 *  - after any hide there is a `gapMs` pause before the next hint;
 *  - nothing shows before `startMs` of run time except hints marked `early` (push: the sled is stalled);
 *  - when something of higher priority wants to show, the current hint is replaced once it has been up `minMs`;
 *  - `danger` hints (an imminent hazard, a stall) may show while `danger` is set; every other hint is held back then, so
 *    a low-priority hint cannot swallow the warning window of a hazard;
 *  - `perRun` caps how often one hint may show in one run; ids in `done` never show again.
 * Persistence of `done` and any counters is the caller's job (it gets `{id, show}` events and `complete()` results).
 */
export const HINT_DEFS = {
  push: { priority: 5, minMs: 1500, maxMs: 6000, danger: true, early: true },
  hop: { priority: 4, minMs: 1500, maxMs: 4500, danger: true },
  boost: { priority: 3, minMs: 2200, maxMs: 2200 },
  flip: { priority: 2, minMs: 1500, maxMs: 5000, perRun: 3 },
  tuck: { priority: 1, minMs: 2500, maxMs: 4500, perRun: 1 },
};

export class HintScheduler {
  /**
   * @param {{defs?:object, done?:Set<string>, gapMs?:number, startMs?:number}} [opts]
   */
  constructor(opts = {}) {
    this.defs = opts.defs || HINT_DEFS;
    this.done = opts.done || new Set();
    this.gapMs = opts.gapMs != null ? opts.gapMs : 600;
    this.startMs = opts.startMs != null ? opts.startMs : 2500;
    this.cur = null; // { id, since }
    this.lastHideAt = -1e9;
    this.latched = new Set();
    this.shows = {};
  }

  get currentId() { return this.cur ? this.cur.id : null; }

  _best(now, wants, danger, aboveP) {
    let best = null;
    for (const id of Object.keys(this.defs)) {
      const d = this.defs[id];
      if (!wants[id] || this.done.has(id) || this.latched.has(id)) continue;
      if (d.perRun && (this.shows[id] || 0) >= d.perRun) continue;
      if (danger && !d.danger) continue;
      if (now < this.startMs && !d.early) continue;
      if (aboveP != null && d.priority <= aboveP) continue;
      if (!best || d.priority > this.defs[best].priority) best = id;
    }
    return best;
  }

  /**
   * @param {number} now run time in ms
   * @param {Object<string, boolean>} wants hint id -> trigger condition holds this frame
   * @param {boolean} [danger] an imminent danger is pending: only `danger` hints may start
   * @returns {{id:string, show:boolean}[]}
   */
  update(now, wants, danger = false) {
    const out = [];
    for (const id of [...this.latched]) if (!wants[id]) this.latched.delete(id);
    const cur = this.cur;
    if (cur) {
      const d = this.defs[cur.id];
      const age = now - cur.since;
      if (age >= d.maxMs) {
        this.latched.add(cur.id);
        out.push(this._hide(now));
      } else if (age >= d.minMs && (!wants[cur.id] || this._best(now, wants, false, d.priority))) {
        out.push(this._hide(now));
      }
    }
    if (!this.cur && now - this.lastHideAt >= this.gapMs) {
      const id = this._best(now, wants, danger, null);
      if (id) {
        this.cur = { id, since: now };
        this.shows[id] = (this.shows[id] || 0) + 1;
        out.push({ id, show: true });
      }
    }
    return out;
  }

  _hide(now) {
    const id = this.cur.id;
    this.cur = null;
    this.lastHideAt = now;
    return { id, show: false };
  }

  /** The player did what the hint asks: hide it now (even below minMs) and never show it again. Returns the events. */
  complete(id, now) {
    if (this.done.has(id)) return [];
    this.done.add(id);
    return this.cur && this.cur.id === id ? [this._hide(now)] : [];
  }
}/**
 * OWNER: input/audio/glitch engineer.
 * Public signatures are a contract - do not change without updating src/ARCHITECTURE.md.
 *
 * Unifies keyboard (window listeners, so it works in every scene), gamepad (navigator.getGamepads polled every
 * game step and on poll()) and touch (DOM overlay + optional device tilt) into one VirtualPad. Instantiated ONCE by
 * createServices(game) and stored at REG.INPUT. Other code never touches the keyboard directly; it polls
 * `inputRouter.poll()` (RunScene, every frame) and/or listens for EVT.INPUT_ACTION (menus).
 * Game keys (Space, arrows) get preventDefault so the page never scrolls; keys typed into text fields are ignored.
 *
 * INPUT_ACTION emitted per press (pressed:true) and release (pressed:false), source keyboard|gamepad|touch:
 *   W/ArrowUp 'up' (+ArrowUp 'airBrake'), S/ArrowDown 'down' (+ArrowDown 'parachute'), A/ArrowLeft 'left',
 *   D/ArrowRight 'right', Space 'hop'+'confirm', Enter 'confirm', Shift 'reset', Esc 'pause' (menus: treat as back),
 *   Backspace 'cancel'; gamepad A 'hop'+'confirm', B 'cancel', X 'airBrake', Y 'parachute', Back 'reset',
 *   Start 'pause', d-pad / left stick 'up|down|left|right'; and 'anyKey' on every first press of any key / button /
 *   touch-tap (used for audio unlock and title screens). Direction actions auto-repeat with the OS key repeat.
 * Pure DOM (no Phaser import) so it can be exercised under jsdom.
 */
import { VirtualPad, emptyPadState } from './VirtualPad.js';
import { EVT } from '../events.js';
import { getPaletteCss } from '../ui/Palette.js';
import { layoutButton } from './ControlLayouts.js';
import { eventTimeOnClock, perfNow } from './PadDerive.js';

/** Keyboard bindings by KeyboardEvent.code: pad button name and INPUT_ACTION names. */
const KEYMAP = {
  KeyW: { pad: 'push', actions: ['up'] },
  KeyA: { pad: 'tiltBack', actions: ['left'] },
  KeyD: { pad: 'tiltForward', actions: ['right'] },
  KeyS: { pad: 'brake', actions: ['down'] },
  Space: { pad: 'hop', actions: ['hop', 'confirm'], confirm: true },
  ShiftLeft: { pad: 'reset', actions: ['reset'] },
  ShiftRight: { pad: 'reset', actions: ['reset'] },
  ArrowLeft: { pad: 'heliLeft', actions: ['left'] },
  ArrowRight: { pad: 'heliRight', actions: ['right'] },
  ArrowUp: { pad: 'airBrake', actions: ['up', 'airBrake'] },
  ArrowDown: { pad: 'parachute', actions: ['down', 'parachute'] },
  Escape: { pad: 'pause', actions: ['pause'] },
  Enter: { pad: 'confirm', actions: ['confirm'] },
  NumpadEnter: { pad: 'confirm', actions: ['confirm'] },
  Backspace: { pad: null, actions: ['cancel'] },
};
const PREVENT = new Set(['Space', 'ArrowLeft', 'ArrowRight', 'ArrowUp', 'ArrowDown']);
const REPEATABLE = new Set(['up', 'down', 'left', 'right']);

const STICK_MENU = 0.6;
const btn = (g, i) => !!(g.buttons[i] && (g.buttons[i].pressed || g.buttons[i].value > 0.5));
const trig = (g, i, t) => !!(g.buttons[i] && g.buttons[i].value > t);
const ax = (g, i) => (g.axes && g.axes[i]) || 0;

/** Gamepad bindings (W3C standard mapping, also what Steam Deck reports). */
const GP_BINDINGS = [
  { id: 'A', test: (g) => btn(g, 0), pad: 'hop', actions: ['hop', 'confirm'], confirm: true },
  { id: 'B', test: (g) => btn(g, 1), pad: 'brake', actions: ['cancel'] },
  { id: 'X', test: (g) => btn(g, 2), pad: 'airBrake', actions: ['airBrake'] },
  { id: 'Y', test: (g) => btn(g, 3), pad: 'parachute', actions: ['parachute'] },
  { id: 'LB', test: (g) => btn(g, 4), pad: 'heliLeft', actions: [] },
  { id: 'RB', test: (g) => btn(g, 5), pad: 'heliRight', actions: [] },
  { id: 'LT', test: (g) => trig(g, 6, 0.4), pad: 'tuck', actions: [] },
  { id: 'RT', test: (g) => trig(g, 7, 0.25), pad: 'push', actions: [] },
  { id: 'Back', test: (g) => btn(g, 8), pad: 'reset', actions: ['reset'] },
  { id: 'Start', test: (g) => btn(g, 9), pad: 'pause', actions: ['pause'] },
  { id: 'DUp', test: (g) => btn(g, 12), pad: null, actions: ['up'] },
  { id: 'DDown', test: (g) => btn(g, 13), pad: null, actions: ['down'] },
  { id: 'DLeft', test: (g) => btn(g, 14), pad: 'tiltBack', actions: ['left'] },
  { id: 'DRight', test: (g) => btn(g, 15), pad: 'tiltForward', actions: ['right'] },
  { id: 'LSUp', test: (g) => ax(g, 1) < -STICK_MENU, pad: null, actions: ['up'] },
  { id: 'LSDown', test: (g) => ax(g, 1) > STICK_MENU, pad: null, actions: ['down'] },
  { id: 'LSLeft', test: (g) => ax(g, 0) < -STICK_MENU, pad: null, actions: ['left'] },
  { id: 'LSRight', test: (g) => ax(g, 0) > STICK_MENU, pad: null, actions: ['right'] },
  { id: 'RSLeft', test: (g) => ax(g, 2) < -0.5, pad: 'heliLeft', actions: [] },
  { id: 'RSRight', test: (g) => ax(g, 2) > 0.5, pad: 'heliRight', actions: [] },
];

const isEditable = (t) =>
  !!t && (t.tagName === 'INPUT' || t.tagName === 'TEXTAREA' || t.tagName === 'SELECT' || t.isContentEditable === true);

export class InputRouter {
  /**
   * @param {Phaser.Game} game
   */
  constructor(game) {
    this.game = game;
    this.pad = new VirtualPad();
    this.enabled = true;
    /** @type {import('./SaveStore.js').Settings|null} */
    this.settings = null;
    this.runActive = false;
    /** @type {Set<string>} KeyboardEvent.code currently held. */
    this.keysDown = new Set();
    this._activeKeyBindings = new Map();
    /** @type {Object<string,boolean>} previous gamepad binding states. */
    this.gpPrev = {};
    /** @type {Object<string,boolean>} previous aggregate pad states (all aliases of a pad button). */
    this.gpPadPrev = {};
    this.gpConnected = false;
    this._listeners = [];
    this._gameListeners = [];
    this._orientation = null;
    this._destroyed = false;
    this._tickBound = () => this._pollGamepads();
    /** Clock that DOM event.timeStamp and Phaser's rAF time share (overridable in tests). */
    this.now = perfNow;
    this._bind();
  }

  // ----------------------------------------------------------------------------------------------------------- setup

  _bind() {
    const hasWindow = typeof window !== 'undefined';
    if (hasWindow) {
      this._on(window, 'keydown', (e) => this._onKeyDown(e), { capture: true });
      this._on(window, 'keyup', (e) => this._onKeyUp(e), { capture: true });
      this._on(window, 'blur', () => this._releaseKeyboard());
      this._on(window, 'pointerdown', (e) => this._onPointerDown(e), { capture: true });
      this._on(window, 'gamepadconnected', () => { this.gpConnected = true; });
      this._on(window, 'gamepaddisconnected', () => this._onGamepadGone());
      if (typeof document !== 'undefined') {
        this._on(document, 'visibilitychange', () => { if (document.hidden) this._releaseKeyboard(); });
      }
    }
    const ev = this.game && this.game.events;
    if (ev) {
      this._onGame('prestep', this._tickBound);
      this._onGame(EVT.RUN_START, () => { this._releaseKeyboard(); this.runActive = true; this.pad.setOverlayContext(true); });
      this._onGame(EVT.RUN_END, () => { this._releaseKeyboard(); this.runActive = false; this.pad.setOverlayContext(false); });
      this._onGame(EVT.RUN_ABORT, () => { this._releaseKeyboard(); this.runActive = false; this.pad.setOverlayContext(false); });
      this._onGame(EVT.GAME_PAUSE, () => this.pad.setOverlayContext(false));
      this._onGame(EVT.GAME_RESUME, () => this.pad.setOverlayContext(this.runActive));
      this._onGame(EVT.SETTINGS_CHANGED, (p) => { if (p && p.settings) this.applySettings(p.settings); });
    }
  }

  _on(target, type, fn, opts) {
    target.addEventListener(type, fn, opts);
    this._listeners.push([target, type, fn, opts]);
  }

  _onGame(name, fn) {
    this.game.events.on(name, fn);
    this._gameListeners.push([name, fn]);
  }

  _emit(action, pressed, source) {
    const ev = this.game && this.game.events;
    if (ev) ev.emit(EVT.INPUT_ACTION, { action, pressed, source });
  }

  // ---------------------------------------------------------------------------------------------------------- keyboard

  /** Gameplay rebinding NEVER changes the menu's logical directional/NOTES actions. */
  _binding(code) {
    const old = KEYMAP[code];
    if (!old || !this.runActive || !this.settings) return old;
    const override = layoutButton(this.settings.controlLayout, code);
    return override === undefined ? old : { ...old, pad: override };
  }

  /**
   * event.timeStamp on the performance.now() clock, or null when it is not on that clock (legacy epoch
   * timestamps, synthetic events, jsdom). A null time keeps the pre-#115 scheduling for that change.
   * @param {Event} e
   * @returns {number|null}
   */
  _eventTime(e) {
    return eventTimeOnClock(e && e.timeStamp, this.now());
  }

  _onKeyDown(e) {
    if (this._destroyed) return;
    if (e.ctrlKey || e.metaKey || e.altKey) return; // keep browser shortcuts working
    if (isEditable(e.target)) return;
    const code = e.code;
    const b = this._binding(code);
    if (PREVENT.has(code)) e.preventDefault();
    if (!b) {
      if (!e.repeat && code) this._emit('anyKey', true, 'keyboard');
      return;
    }
    if (e.repeat) {
      for (const a of b.actions) if (REPEATABLE.has(a)) this._emit(a, true, 'keyboard');
      return;
    }
    this.keysDown.add(code);
    this._activeKeyBindings.set(code, b);
    const t = this._eventTime(e);
    if (b.pad) this.pad.setButton(b.pad, true, 'keyboard', t);
    if (b.confirm) this.pad.setButton('confirm', true, 'keyboard', t);
    for (const a of b.actions) this._emit(a, true, 'keyboard');
    this._emit('anyKey', true, 'keyboard');
  }

  _onKeyUp(e) {
    if (this._destroyed) return;
    const code = e.code;
    const b = this._activeKeyBindings.get(code) || KEYMAP[code];
    if (PREVENT.has(code) && !isEditable(e.target)) e.preventDefault();
    if (!b || !this.keysDown.has(code)) return;
    this.keysDown.delete(code);
    this._activeKeyBindings.delete(code);
    const t = this._eventTime(e);
    if (b.pad) {
      // another physical key may still hold the same pad button (e.g. both Shift keys)
      const still = [...this._activeKeyBindings.entries()].some(([k, other]) => this.keysDown.has(k) && other.pad === b.pad);
      if (!still) this.pad.setButton(b.pad, false, 'keyboard', t);
    }
    if (b.confirm) this.pad.setButton('confirm', false, 'keyboard', t);
    for (const a of b.actions) this._emit(a, false, 'keyboard');
  }

  _releaseKeyboard() {
    for (const code of [...this.keysDown]) {
      const b = this._activeKeyBindings.get(code) || KEYMAP[code];
      if (b) for (const a of b.actions) this._emit(a, false, 'keyboard');
    }
    this.keysDown.clear();
    this._activeKeyBindings.clear();
    this.pad.releaseSource('keyboard');
  }

  // ----------------------------------------------------------------------------------------------------------- touch

  _onPointerDown(e) {
    if (this._destroyed || e.pointerType !== 'touch') return;
    this.pad.state.lastSource = 'touch';
    this._emit('anyKey', true, 'touch');
    this._requestOrientation();
  }

  _requestOrientation() {
    if (!this.settings || !this.settings.touchRotate90 || this._orientationAsked) return;
    this._orientationAsked = true;
    try {
      const DOE = typeof DeviceOrientationEvent !== 'undefined' ? DeviceOrientationEvent : null;
      if (DOE && typeof DOE.requestPermission === 'function') {
        // iOS 13+: must be called from a user gesture; never throws into the game.
        DOE.requestPermission().then((r) => { if (r === 'granted') this._listenOrientation(); }).catch(() => {});
      }
    } catch (err) { /* ignore */ }
  }

  _listenOrientation() {
    if (this._orientation || typeof window === 'undefined' || this._destroyed) return;
    this._orientation = (e) => {
      if (e.beta == null || e.gamma == null) return;
      let angle = 0;
      try {
        angle = (window.screen && window.screen.orientation && window.screen.orientation.angle) || window.orientation || 0;
      } catch (err) { /* ignore */ }
      angle = ((angle % 360) + 360) % 360;
      // Roll about the axis normal to the screen, clockwise positive as the player sees it (device held like a wheel).
      const roll = angle === 90 ? e.beta : angle === 270 ? -e.beta : angle === 180 ? -e.gamma : e.gamma;
      this.pad.setTilt(Math.max(-1, Math.min(1, roll / 30)), 'device');
    };
    window.addEventListener('deviceorientation', this._orientation);
  }

  _unlistenOrientation() {
    if (this._orientation && typeof window !== 'undefined') window.removeEventListener('deviceorientation', this._orientation);
    this._orientation = null;
    this.pad.setTilt(0, 'device');
  }

  // --------------------------------------------------------------------------------------------------------- gamepad

  _getGamepad() {
    try {
      const list = typeof navigator !== 'undefined' && navigator.getGamepads ? navigator.getGamepads() : null;
      if (!list) return null;
      let first = null;
      for (const g of list) {
        if (!g || !g.connected) continue;
        if (g.mapping === 'standard') return g;
        if (!first) first = g;
      }
      return first;
    } catch (err) {
      return null;
    }
  }

  _onGamepadGone() {
    this.gpConnected = false;
    this.gpPrev = {};
    this.gpPadPrev = {};
    this.pad.releaseSource('gamepad');
  }

  _pollGamepads() {
    if (this._destroyed) return;
    const g = this._getGamepad();
    if (!g) {
      if (this.gpActive) {
        this.gpActive = false;
        this._onGamepadGone();
      }
      return;
    }
    this.gpActive = true;
    // Several physical inputs may bind the same pad button (LB/RSLeft -> heliLeft, RB/RSRight ->
    // heliRight). Aggregate them BEFORE writing the pad so releasing one alias cannot cancel another
    // that is still held; every aggregate still writes the single 'gamepad' source.
    const padNext = {};
    const pending = [];
    for (const b of GP_BINDINGS) {
      const down = !!b.test(g);
      const changed = down !== !!this.gpPrev[b.id];
      this.gpPrev[b.id] = down;
      const target = b.pad;
      if (target) padNext[target] = !!padNext[target] || down;
      if (b.confirm) padNext.confirm = !!padNext.confirm || down;
      if (!changed) continue;
      for (const a of b.actions) pending.push([a, down]);
      if (down) pending.push(['anyKey', true]);
    }
    // Pad writes are applied before emitting so action listeners observe the current pad state,
    // matching the keyboard path.
    for (const [name, down] of Object.entries(padNext)) {
      if (down === !!this.gpPadPrev[name]) continue;
      this.gpPadPrev[name] = down;
      this.pad.setButton(name, down, 'gamepad');
    }
    for (const [a, d] of pending) this._emit(a, d, 'gamepad');
    this.pad.setTilt(ax(g, 0), 'gamepad');
  }

  // ------------------------------------------------------------------------------------------------------ public API

  /**
   * Read the current normalized control state. Call at most once per frame per consumer scene
   * (it consumes the one-shot `pressed` edges and polls gamepads). The result carries a non-enumerable
   * `timeline` of timestamped changes since the last poll (VirtualPad.poll; null while disabled) for
   * SimClock.padsFor (issue #115).
   * @returns {import('./VirtualPad.js').VirtualPadState}
   */
  poll() {
    this._pollGamepads();
    const s = this.pad.poll();
    if (!this.enabled) {
      const n = emptyPadState();
      n.lastSource = s.lastSource;
      Object.defineProperty(n, 'timeline', { value: null, enumerable: false });
      return n;
    }
    return s;
  }

  /**
   * Enable/disable gameplay input (e.g. while paused or typing initials). When disabled poll() returns a neutral
   * state but EVT.INPUT_ACTION menu events still fire.
   * @param {boolean} enabled
   * @returns {void}
   */
  setEnabled(enabled) {
    this.enabled = enabled;
  }

  /**
   * Apply settings (touch overlay mode / 90-degree rotate). Safe to call repeatedly.
   * @param {import('./SaveStore.js').Settings} settings
   * @returns {void}
   */
  applySettings(settings) {
    if (this._destroyed || !settings) return;
    if (this.settings && this.settings.controlLayout !== settings.controlLayout) this._releaseKeyboard();
    this.settings = settings;
    try {
      const canvas = this.game && this.game.canvas;
      const parent = (canvas && canvas.parentElement) || (typeof document !== 'undefined' ? document.body : null);
      if (parent) {
        this.pad.mountTouchOverlay(parent, settings);
        if (this.pad.overlay) {
          try { this.pad.overlay.setColors(getPaletteCss(this.game)); } catch (err) { /* palette not ready */ }
          this.pad.overlay.setContextVisible(this.runActive);
        }
      }
    } catch (err) { /* DOM unavailable */ }
    if (settings.touchRotate90) {
      this._orientationAsked = false;
      const DOE = typeof DeviceOrientationEvent !== 'undefined' ? DeviceOrientationEvent : null;
      if (DOE && typeof DOE.requestPermission === 'function') {
        // wait for a touch gesture (see _onPointerDown)
      } else if (typeof window !== 'undefined' && 'DeviceOrientationEvent' in window) this._listenOrientation();
    } else this._unlistenOrientation();
  }

  /** Remove all listeners / overlay. @returns {void} */
  destroy() {
    this._destroyed = true;
    for (const [t, type, fn, opts] of this._listeners) t.removeEventListener(type, fn, opts);
    this._listeners = [];
    for (const [name, fn] of this._gameListeners) this.game.events.off(name, fn);
    this._gameListeners = [];
    this._unlistenOrientation();
    this.keysDown.clear();
    this.pad.destroy();
  }
}/**
 * OWNER: gameplay. NO Phaser imports. Pure and deterministic.
 *
 * Playful snow-racing Kodiaks (issue #47; owner override 2026-11-21: rivals, not killers). Three bears
 * Marvin named and coloured:
 *  - KERNEL-PANIC KODIAK (white, polar): rides ahead, glitchy telegraphed feints, then a real
 *    stop-dead block in your line. Hop it, or it shoves you back.
 *  - BRUTE-FORCE KODIAK (brown, grizzly): charges from behind and rams; hop over the lunge.
 *  - BLACK-ICE KODIAK (black, Vermont black bear): rides ahead and slides under your predicted
 *    landing; change the landing (tilt, airbrake, divebomb) or out-ride it.
 * Contact never crashes the sled: a bear shoves it back and up by a bounded amount (kodiakKnockback),
 * then the race goes on.
 *
 * A bear is a kinematic racer on the terrain surface, advanced once per fixed simulation tick
 * (#59). It has no Matter body: collision is a tick-exact box test against the sled, so bears
 * never reorder the physics solver. Every choice (when, which bear, feint or real) comes from a
 * seeded stream per encounter, so the same seed and inputs give the same bears (ghost tapes).
 * Owner decisions still open (docs/issue-47-kodiaks.md): the Sync Level gate, the Daily rule.
 */
import { Rng } from './Rng.js';

/** Bump when spawn cadence, behaviour or collision changes (old ghost tapes would replay differently). */
export const KODIAK_VERSION = 3; // v3: contact shoves the sled back, no crash; v2: packs
/** Proposal, not an owner value: Kodiaks start appearing at this Sync Level in ordinary runs. */
export const KODIAK_MIN_SYNC_LEVEL = 6;
/** No bear before this distance into a run, then one encounter every GAP metres. */
export const KODIAK_FIRST_M = 450;
export const KODIAK_GAP_M = [650, 1200];
export const KODIAK_LIFETIME_MS = 15000;
const BODY = { w: 42, h: 26 };

export const KODIAK_DEFS = Object.freeze({
  kernelPanic: Object.freeze({ kind: 'kernelPanic', id: 'kernelPanicKodiak', name: 'KERNEL-PANIC KODIAK', short: 'KERNEL-PANIC',
    from: 'ahead', color: 0xeaf4ff, rim: 0x9fdcff, accent: 0x2ccde5 }),
  bruteForce: Object.freeze({ kind: 'bruteForce', id: 'bruteForceKodiak', name: 'BRUTE-FORCE KODIAK', short: 'BRUTE-FORCE',
    from: 'behind', color: 0x8a5a2b, rim: 0xc49060, accent: 0xffb347 }),
  blackIce: Object.freeze({ kind: 'blackIce', id: 'blackIceKodiak', name: 'BLACK-ICE KODIAK', short: 'BLACK-ICE',
    from: 'ahead', color: 0x15151b, rim: 0x7fb8d8, accent: 0x9fe8ff }),
});
export const KODIAK_KINDS = Object.freeze(Object.keys(KODIAK_DEFS));
/**
 * Contact shove (issue #47 owner override: racing rivals, never instant death). A bear that touches the sled
 * pushes it BACKWARD, against its travel, by a bounded amount that grows with how fast the two were closing,
 * and lifts it. Velocities in px/s. All three bears share one envelope until playtests say otherwise (the owner
 * has not chosen per-bear values). Each bear shoves once per encounter; after any shove no bear shoves again for
 * `immunityMs`, so a pack cannot chain shoves.
 */
export const KODIAK_KNOCK = Object.freeze({ basePx: 80, perClosingPx: 0.35, maxPx: 220, upPx: 200, immunityMs: 1000 });

/**
 * Do Kodiaks appear on this run? From KODIAK_MIN_SYNC_LEVEL in ordinary runs. Never on Dailies or
 * in the Gym until an explicit event rule says so (issue #47: account level must not change a
 * stock-vs-stock competition).
 */
export function kodiaksEnabledFor({ level, daily = false, gym = false } = {}) {
  if (daily === true || gym === true) return false;
  return Number.isFinite(level) && level >= KODIAK_MIN_SYNC_LEVEL;
}

/** Pack composition modes (owner, 2026-11-21: race bears come in packs; same-type vs mixed is a playtest question). */
export const KODIAK_PACK_MODES = Object.freeze(['same', 'mixed']);
/** Gap (px) between pack members on the same side: staggers their arrival. */
export const KODIAK_PACK_SPACING_PX = 170;

/**
 * Encounter `n` (0-based) of a run: where it starts (metres from the start) and its pack. A pack has
 * 2 or 3 bears (the run's first pack always 2). 'same': one type throughout. 'mixed': at least two
 * different types (all three in a pack of three).
 * @returns {{n:number, atM:number, kind:string, members:string[], mode:string}}
 */
export function kodiakEncounter(seed, n, mode = 'same') {
  let atM = KODIAK_FIRST_M;
  for (let i = 0; i < n; i++) {
    const r = new Rng(String(seed)).fork(`kodiak/gap/${i}`);
    atM += KODIAK_GAP_M[0] + r.next() * (KODIAK_GAP_M[1] - KODIAK_GAP_M[0]);
  }
  const pick = new Rng(String(seed)).fork(`kodiak/kind/${n}`);
  const kind = KODIAK_KINDS[Math.floor(pick.next() * KODIAK_KINDS.length)];
  const size = n === 0 ? 2 : new Rng(String(seed)).fork(`kodiak/size/${n}`).next() < 0.6 ? 2 : 3;
  let members;
  if (mode === 'mixed') {
    // The lead type first, then the others in a seeded order: every member of a pack of 2 or 3 differs.
    const rest = KODIAK_KINDS.filter((k) => k !== kind);
    if (new Rng(String(seed)).fork(`kodiak/mix/${n}`).next() < 0.5) rest.reverse();
    members = [kind, ...rest].slice(0, size);
  } else members = Array(size).fill(kind);
  return { n, atM, kind, members, mode: mode === 'mixed' ? 'mixed' : 'same' };
}

/**
 * The bears of a pack, spread out so they arrive one after another: each side's members are
 * KODIAK_PACK_SPACING_PX further away than the one before.
 */
export function spawnKodiakPack(seed, enc, sled) {
  const perSide = { ahead: 0, behind: 0 };
  return (enc.members || [enc.kind]).map((kind, i) => {
    const side = KODIAK_DEFS[kind].from;
    const offset = perSide[side]++ * KODIAK_PACK_SPACING_PX;
    return spawnKodiak(seed, { n: enc.n, kind, member: i }, sled, offset);
  });
}

/** Bear box (world px) standing on the surface at (x, groundY). */
export function kodiakBox(x, groundY) {
  return { x: x - BODY.w / 2, y: groundY - BODY.h, w: BODY.w, h: BODY.h };
}

/**
 * A new bear for an encounter, placed off screen ahead of or behind the sled.
 * @param {string} seed
 * @param {{n:number, kind:string}} enc from kodiakEncounter
 * @param {{x:number, vx:number}} sled
 */
export function spawnKodiak(seed, enc, sled, offsetPx = 0) {
  const def = KODIAK_DEFS[enc.kind];
  const behind = def.from === 'behind';
  return {
    kind: enc.kind, n: enc.n, member: enc.member || 0, def,
    x: sled.x + (behind ? -620 - offsetPx : 640 + offsetPx),
    speed: Math.max(120, sled.vx * (behind ? 1 : 0.88)),
    phase: 'approach', phaseMs: 0, ageMs: 0,
    rng: new Rng(String(seed)).fork(`kodiak/brain/${enc.n}/${enc.member || 0}`),
    feints: 0, targetX: null, groundY: NaN, sledAhead: behind,
    hit: false, done: false,
  };
}

const approach = (v, target, rate, dtS) => v + Math.max(-rate * dtS, Math.min(rate * dtS, target - v));

/**
 * Advance one bear by one tick.
 * @param {object} k bear state (mutated)
 * @param {{x:number, vx:number, grounded:boolean, landX:number|null}} sled
 * @param {number} dtMs the tick
 * @param {boolean} [busy] another pack member is telegraphing or attacking: this one holds its pace
 *   and never starts an attack, so the player faces one attack at a time
 * @returns {{telegraph?:'feint'|'real', lunge?:boolean, done?:boolean}} what happened this tick
 */
export function stepKodiak(k, sled, dtMs, busy = false) {
  const dtS = dtMs / 1000;
  const ev = {};
  k.ageMs += dtMs;
  k.phaseMs += dtMs;
  const dx = k.x - sled.x; // + : bear ahead of the sled
  const sv = Math.max(0, sled.vx);
  const go = (phase) => { k.phase = phase; k.phaseMs = 0; };
  if (k.kind === 'bruteForce') {
    if (k.phase === 'approach') {
      k.speed = approach(k.speed, sv + 150, 600, dtS); // catch up from behind
      if (dx > -150 && !busy) { go('tele'); ev.telegraph = 'real'; }
      else if (busy && dx > -260) k.speed = approach(k.speed, sv, 900, dtS); // wait its turn, just behind
    } else if (k.phase === 'tele') {
      k.speed = approach(k.speed, sv + 40, 900, dtS); // rear up, matching pace
      if (k.phaseMs >= 650) { go('lunge'); ev.lunge = true; }
    } else if (k.phase === 'lunge') {
      k.speed = approach(k.speed, sv + 380, 2400, dtS);
      // The charge carries it well clear ahead before it tires: it never slows down under the sled.
      if (dx > 160 || k.phaseMs >= 1600) go('recover');
    } else if (k.phase === 'recover') {
      // Spent: it slows hard, so re-passing it is a clean hop at real closing speed (never a slow crawl over
      // its back, which no hop can clear).
      k.speed = approach(k.speed, sv * 0.4, 1600, dtS);
      if (k.phaseMs >= 2500) go('leave');
    }
  } else if (k.kind === 'kernelPanic') {
    if (k.phase === 'approach') {
      k.speed = approach(k.speed, sv * 0.85, 400, dtS); // the player closes in
      if (busy && dx < 320) k.speed = approach(k.speed, sv, 900, dtS); // wait its turn, just ahead
      else if (dx < 260) { go('tele'); ev.telegraph = k.feints < 2 && k.rng.next() < 0.6 ? 'feint' : 'real'; k.real = ev.telegraph === 'real'; if (!k.real) k.feints++; }
    } else if (k.phase === 'tele') {
      k.speed = approach(k.speed, sv * 0.9, 600, dtS);
      if (k.phaseMs >= (k.real ? 700 : 420)) {
        if (k.real) { go('lunge'); ev.lunge = true; } else go('approach');
      }
    } else if (k.phase === 'lunge') {
      k.speed = approach(k.speed, 0, 2600, dtS); // KERNEL PANIC: stops dead across the line
      if (k.phaseMs >= 1600) go('leave');
    }
  } else if (k.kind === 'blackIce') {
    if (k.phase === 'approach') {
      // Black-Ice never blocks the ground: it keeps ahead of the sled (speeding up if the sled gains) and only
      // threatens landings.
      k.speed = approach(k.speed, dx < 220 ? sv * 1.3 : sv, 700, dtS);
      // Reads the terrain: when the sled is airborne and its landing is ahead, slide under it.
      // It can surge forward or brake to a stop, so any landing within reach of it counts.
      if (!busy && !sled.grounded && Number.isFinite(sled.landX) && Math.abs(sled.landX - k.x) < 450 && dx > 60 && dx < 700) {
        k.targetX = sled.landX; go('tele'); ev.telegraph = 'real';
      } else if (dx < -40 || k.phaseMs >= 6000) go('leave'); // out-ridden (in the air), or no landing to read
    } else if (k.phase === 'tele') {
      // It COMMITS to the landing spot it telegraphed (the glint): change your landing (divebomb short,
      // parachute or airbrake long) and it slides to the wrong place. Its slide speed is capped too.
      if (sled.grounded) go('leave'); // the landing came and went: hit or miss, it is done
      else {
        const etaS = Math.max(0.15, Number.isFinite(sled.etaMs) ? sled.etaMs / 1000 : 0.6);
        k.speed = approach(k.speed, Math.max(0, Math.min(sv * 1.4, (k.targetX - k.x) / etaS)), 900, dtS);
      }
      if (k.phaseMs >= 2500) go('leave');
    }
  }
  if (k.phase === 'leave') k.speed = approach(k.speed, sv * (dx > 0 ? 1.35 : 0.5), 500, dtS); // clear the stage
  k.x += k.speed * dtS;
  if (k.ageMs >= KODIAK_LIFETIME_MS || (k.phase === 'leave' && Math.abs(dx) > 900) || dx < -1400) { k.done = true; ev.done = true; }
  return ev;
}

/** A pack member nearer than this to the sled is an obstacle to hop: the others hold off. */
export const KODIAK_CLEAR_PX = 220;

/** A bear that is telegraphing or attacking (the pack's one active threat). */
export const kodiakThreatening = (k) => !k.done && (k.phase === 'tele' || k.phase === 'lunge');

/**
 * Advance a whole pack by one tick: members in order, at most one of them threatening at a time, and
 * none attacking while another is close enough to need hopping.
 * @returns {Array<{k:object, ev:object}>}
 */
export function stepKodiakPack(bears, sled, dtMs) {
  const out = [];
  for (const k of bears) {
    if (k.done) continue;
    // Busy while another member attacks OR is close enough to need hopping (a tired grizzly just ahead):
    // the player never has to clear two bears at once.
    const busy = bears.some((o) => o !== k && (kodiakThreatening(o) || (!o.done && !o.hit && Math.abs(o.x - sled.x) < KODIAK_CLEAR_PX)));
    out.push({ k, ev: stepKodiak(k, sled, dtMs, busy) });
  }
  return out;
}

/**
 * Tick-exact collision. A sled whose bottom clears the bear's back (8 px of forgiveness) is safe: hopping
 * over a bear is the counter to every attack, and the only way past one on the ground.
 * @param {{x:number,y:number,w:number,h:number}} bearBox
 * @param {{x:number,y:number,w:number,h:number}} sledBox
 */
export function kodiakHits(bearBox, sledBox) {
  return sledBox.x < bearBox.x + bearBox.w && bearBox.x < sledBox.x + sledBox.w &&
    sledBox.y + sledBox.h > bearBox.y + 8 && sledBox.y < bearBox.y + bearBox.h;
}

/**
 * The sled's velocity change (px/s) for a bear contact: backward (dvx < 0) and up (dvy < 0, y grows down). The
 * backward push grows with how fast the two were closing and is capped at KODIAK_KNOCK.maxPx. Pure: the same
 * bear and sled give the same shove.
 * @param {{speed:number}} k the bear that touched the sled
 * @param {{vx:number}} sled
 * @returns {{dvx:number, dvy:number}}
 */
export function kodiakKnockback(k, sled) {
  const closing = Math.abs(k.speed - Math.max(0, sled.vx));
  const back = Math.min(KODIAK_KNOCK.maxPx, KODIAK_KNOCK.basePx + KODIAK_KNOCK.perClosingPx * closing);
  return { dvx: -back, dvy: -KODIAK_KNOCK.upPx };
}/**
 * #82: local analytics over a bounded, caller-selected SaveStore history.
 * This module has no persistence, scene, or standing-update side effects.
 */
import { countsForDailyBest, countsForDraftDailyBest, isModdedOnly, isRankable } from './Ranking.js';
import { BOOSTS } from './Boosts.js';
import { activeUpgradeRanks } from './PermanentUpgrades.js';
import {
  DRAFT_LEDGER_HASH_V, INITIALS_MIN, LEDGER_HASH_V, UPGRADE_LEDGER_HASH_V,
  normalizeInitials, verifyLedgerHash,
} from './SaveStore.js';

export const MAX_LOCAL_RANKING_RECORDS = 1000;
const boards = ['clean', 'modded', 'daily-classic', 'daily-draft'];
const ledgerVersions = [LEDGER_HASH_V, UPGRADE_LEDGER_HASH_V, DRAFT_LEDGER_HASH_V];
const metricUnits = Object.freeze({
  distanceM: 'm',
  score: 'points',
  averageProgressMps: 'm/s',
  trickVariety: 'types',
  efficiencyPointsPerM: 'points/m',
  maxAirtimeMs: 'ms',
  survivalMs: 'ms',
});
const metricKeys = Object.keys(metricUnits);

const isObject = (value) => value !== null && typeof value === 'object' && !Array.isArray(value);
const nonnegative = (value) => Number.isFinite(value) && value >= 0;
const isMask = (value) => Number.isInteger(value) && value >= 0 && value <= 0xffffffff;
const nonempty = (value) => typeof value === 'string' && value.trim().length > 0;
const byId = (a, b) => (a.id < b.id ? -1 : a.id > b.id ? 1 : 0);
const canonicalZero = (value) => value === 0 ? 0 : value;

function loadoutOf({ boosts, upgradeRanks }) {
  if (boosts !== undefined && (!Array.isArray(boosts) || ![...boosts].every((id) => BOOSTS.includes(id)))) return null;
  if (upgradeRanks !== undefined && !isObject(upgradeRanks)) return null;
  const ranks = activeUpgradeRanks(upgradeRanks);
  // Do not silently treat malformed, future, or inactive values as a known loadout.
  if (upgradeRanks && Object.entries(upgradeRanks).some(([id, rank]) => !Object.hasOwn(ranks, id) || ranks[id] !== rank)) return null;
  return { boosts: [...new Set(boosts ?? [])].sort(), upgradeRanks: ranks };
}

function boardOf(record) {
  if (countsForDraftDailyBest(record)) return 'daily-draft';
  if (countsForDailyBest(record)) return 'daily-classic';
  // An invalid Official Daily stamp isn't evidence of an ordinary practice run.
  if (record.dailyOfficial === true) return null;
  if (isModdedOnly(record)) return 'modded';
  if (isRankable(record)) return 'clean';
  return null;
}

function scopeOf(board, seed, biomeMask, dailyRuleId, loadout) {
  return { board, seed, biomeMask, dailyRuleId, ...loadout };
}

function ratio(a, b, scale = 1) {
  const value = b > 0 ? (a / b) * scale : NaN;
  return Number.isFinite(value) ? canonicalZero(value) : null;
}

function candidateOf(record) {
  if (!isObject(record) || !ledgerVersions.includes(record.hashV) ||
      !nonempty(record.id) || !nonempty(record.seed) || !nonempty(record.dailyRuleId) ||
      !isMask(record.biomeMask ?? 0) || record.imported === true ||
      normalizeInitials(record.initials).length < INITIALS_MIN || record.cause !== 'crash' ||
      ![record.distanceM, record.score, record.durationMs, record.maxAirtimeMs].every(nonnegative) ||
      !isObject(record.tricks) || !Object.values(record.tricks).every(nonnegative)) return null;
  if (record.biomeMask === null ||
      (record.dailyOfficial !== undefined && typeof record.dailyOfficial !== 'boolean')) return null;

  const loadout = loadoutOf(record);
  // Permanent upgrade ranks weren't committed by v2, so don't infer them there.
  if (!loadout || (record.hashV === LEDGER_HASH_V && Object.keys(loadout.upgradeRanks).length) ||
      !verifyLedgerHash(record)) return null;
  const board = boardOf(record);
  if (!board) return null;
  const hasAppliedLoadout = loadout.boosts.length > 0 || Object.keys(loadout.upgradeRanks).length > 0;
  // Only compare known loadouts. A hash-consistent but contradictory record
  // must not enter a clean cohort, or be treated as an empty modded loadout.
  if ((board === 'clean' || board === 'daily-classic') && hasAppliedLoadout) return null;
  if (board === 'modded' && !hasAppliedLoadout) return null;

  const scope = scopeOf(board, record.seed, record.biomeMask ?? 0, record.dailyRuleId, loadout);
  const scopeKey = JSON.stringify(scope);
  const values = {
    distanceM: canonicalZero(record.distanceM),
    score: canonicalZero(record.score),
    // Divide the stored values first, then scale: separately rounding a
    // scaled operand can split otherwise equal physical ratios.
    averageProgressMps: ratio(record.distanceM, record.durationMs, 1000),
    trickVariety: Object.values(record.tricks).filter((count) => count > 0).length,
    efficiencyPointsPerM: ratio(record.score, record.distanceM),
    maxAirtimeMs: canonicalZero(record.maxAirtimeMs),
    // Zero can mean an unavailable historical duration after store normalization.
    survivalMs: record.durationMs > 0 ? record.durationMs : null,
  };
  return {
    id: record.id, scopeKey, values,
    signature: JSON.stringify([record.hashV, record.ledgerHash, scopeKey, values]),
  };
}

function localCohort(history, scopeKey) {
  const byRun = new Map();
  const conflicts = new Set();
  for (const record of history) {
    const candidate = candidateOf(record);
    if (!candidate) continue;
    const prior = byRun.get(candidate.id);
    if (!prior) byRun.set(candidate.id, candidate);
    else if (prior.signature !== candidate.signature) conflicts.add(candidate.id);
  }
  // Resolve identity collisions before applying the cohort filter.
  return [...byRun.values()].filter((row) => !conflicts.has(row.id) && row.scopeKey === scopeKey).sort(byId);
}

function percentileRanks(rows, metric) {
  const available = rows.filter((row) => row.values[metric] !== null)
    .sort((a, b) => a.values[metric] - b.values[metric]);
  const n = available.length;
  if (n < 2) return n;
  for (let start = 0; start < n;) {
    let end = start + 1;
    while (end < n && available[end].values[metric] === available[start].values[metric]) end++;
    const midrank = 100 * (start + (end - start) / 2) / n;
    for (let i = start; i < end; i++) available[i].percentiles[metric] = midrank;
    start = end;
  }
  return n;
}

function dominates(a, b) {
  let better = false;
  for (const key of metricKeys) {
    if (a.values[key] < b.values[key]) return false;
    if (a.values[key] > b.values[key]) better = true;
  }
  return better;
}

/**
 * Analyze one explicit board/course/rule/loadout cohort from a recent history
 * obtained with SaveStore.getRecentRuns(limit). Same score does not imply
 * same result; rows are ordered by run ID, not official board placement.
 * @param {Array<object>} history current SaveStore history snapshot
 * @param {{board:string, seed:string, biomeMask:number, dailyRuleId:string,
 *   boosts?:string[], upgradeRanks?:Object<string,number>}} selection exact cohort
 */
export function calculateLocalRankings(history, selection) {
  if (!Array.isArray(history)) throw new TypeError('Local ranking history must be an array');
  if (history.length > MAX_LOCAL_RANKING_RECORDS) {
    throw new RangeError(`Local ranking history is limited to ${MAX_LOCAL_RANKING_RECORDS} records`);
  }
  if (!isObject(selection) || !boards.includes(selection.board) || !nonempty(selection.seed) ||
      !isMask(selection.biomeMask) || !nonempty(selection.dailyRuleId)) {
    throw new TypeError('Select one explicit board, seed, biome mask, and movement rule');
  }
  const loadout = loadoutOf(selection);
  if (!loadout) throw new TypeError('Invalid local ranking loadout');
  const cohort = scopeOf(selection.board, selection.seed, selection.biomeMask, selection.dailyRuleId, loadout);
  const rows = localCohort(history, JSON.stringify(cohort)).map(({ id, values }) => ({
    id, values,
    percentiles: Object.fromEntries(metricKeys.map((key) => [key, null])),
    pareto: null,
  }));

  const metrics = Object.fromEntries(metricKeys.map((key) => [
    key, { unit: metricUnits[key], sampleSize: percentileRanks(rows, key) },
  ]));
  const complete = rows.filter((row) => metricKeys.every((key) => row.values[key] !== null));
  for (const row of complete) {
    row.pareto = complete.some((other) => dominates(other, row)) ? 'dominated' : 'nondominated';
  }

  return {
    cohort, historySize: history.length, sampleSize: rows.length, metrics, rows,
    frontierSampleSize: complete.length,
    frontierIds: complete.filter((row) => row.pareto === 'nondominated').map((row) => row.id),
  };
}/**
 * OWNER: gameplay. Pure layout for the BEST and DIED HERE gate labels. Your best distance is often (nearly) where you
 * died, so the two poles stand a few px apart. When they are close, both labels are hung off the LEFT of the leftmost
 * pole (text extends away from the hazard that killed you, so the ground telegraph's column stays clear), stacked on
 * a shared baseline so neither text overprints the other and no pole crosses either text. Far apart, each label
 * stays centred over its own pole as before. No Phaser, no randomness.
 */

/** Gap (px) between the leftmost pole and the text hanging off it. */
export const LABEL_PAD = 6;
/** Poles closer than this (px) share a stacked label block; further apart, the labels cannot meet. */
export const NEAR_PX = 220;
/** Label heights above the terrain at the pole (px): the BEST gate is 90 tall, the DIED HERE gate 118. */
export const BEST_LABEL_RISE = 96;
export const DEATH_LABEL_RISE = 126;

/**
 * @typedef {{x:number, y:number, originX:number}} LabelPlacement world position of the label's bottom edge + text origin x.
 * @param {{x:number, y:number}|null} best BEST pole: world x and the terrain y it stands on (null when absent or y unknown).
 * @param {{x:number, y:number}|null} death DIED HERE pole, same shape.
 * @returns {{best: LabelPlacement|null, death: LabelPlacement|null}}
 */
export function layoutMarkerLabels(best, death) {
  const ok = (m) => !!m && Number.isFinite(m.x) && Number.isFinite(m.y);
  const own = (m, rise) => (ok(m) ? { x: m.x, y: m.y - rise, originX: 0.5 } : null);
  if (!ok(best) || !ok(death) || Math.abs(best.x - death.x) >= NEAR_PX) {
    return { best: own(best, BEST_LABEL_RISE), death: own(death, DEATH_LABEL_RISE) };
  }
  const x = Math.min(best.x, death.x) - LABEL_PAD;
  const base = Math.min(best.y, death.y); // the higher terrain point (smaller y): both labels clear both poles' ground
  return {
    best: { x, y: base - BEST_LABEL_RISE, originX: 1 },
    death: { x, y: base - DEATH_LABEL_RISE, originX: 1 },
  };
}


/**
 * #253: marker rendering must NEVER read the mutable terrain generator.
 * The physically joined Matter mesh retains the exact polyline it built
 * collision bodies from; sample that existing geometry with the identical
 * TerrainGenerator.heightAt segment formula, but without invoking _chunkAt,
 * changing _lastChunk, generating future chunks, or queuing terrain.
 *
 * At a shared boundary either joined neighbor has the same endpoint height.
 * Iterate the mesh's insertion order consistently and never request a chunk.
 * Return NaN until physically joined; the normal marker update defers drawing.
 * SIM8 release contract: rendering must not touch generator caches or queues.
 *
 * @param {number} x marker world coordinate
 * @param {Map<number,{startX:number,endX:number,points:{x:number,y:number}[]}>} joined
 *   actual Matter TerrainMesh.chunks, not speculative TerrainGenerator.activeList
 * @returns {number} unchanged geometry height, or NaN when unjoined/invalid
 */
export function joinedMarkerHeight(x, joined) {
  if (!Number.isFinite(x) || !joined || typeof joined.values !== 'function') return NaN;
  for (const chunk of joined.values()) {
    if (!chunk || !Number.isFinite(chunk.startX) || !Number.isFinite(chunk.endX) ||
        x < chunk.startX || x > chunk.endX) continue;
    const p = chunk.points;
    if (!Array.isArray(p) || p.length < 2) continue;
    const sp = p[1].x - p[0].x;
    if (!(sp > 0) || !Number.isFinite(sp)) continue;
    // Mirror TerrainGenerator._segIndex and heightAt: this is a read-only
    // interpolation over joined collider points, not a generator lookup.
    const i = Math.max(0, Math.min(p.length - 2, Math.floor((x - chunk.startX) / sp)));
    const a = p[i], b = p[i+1];
    if (!a || !b || !Number.isFinite(a.x) || !Number.isFinite(b.x) ||
        !Number.isFinite(a.y) || !Number.isFinite(b.y) || !(b.x > a.x)) return NaN;
    return a.y + ((b.y - a.y) * (x - a.x)) / (b.x - a.x);
  }
  return NaN;
}/**
 * Portable-math patch for Phaser's bundled matter-js (issue #121).
 *
 * Phaser 3.90.0 ships matter-js as `Phaser.Physics.Matter.Matter`. Nine of its functions call the native Math.sin/cos/atan2/
 * acos/pow, whose last bit is not guaranteed to be the same in every browser engine. They sit on the authoritative path
 * (body rotation every sub-step, collision axes, and the sled's chamfered vertices at construction), so this module replaces
 * exactly those nine properties on the shared Matter module objects with line-for-line equivalents that call pmath. Matter's own
 * callers look these functions up on the module objects at call time (like installTerrainContactFix does for Collision.collides),
 * so replacing the property is enough; nothing is forked and no global Math is touched.
 *
 * The bodies below are copies of the Phaser 3.90.0 / matter-js 0.20 source (MIT) with only the Math calls swapped. They are tied to
 * that exact version: package.json pins phaser exactly and tests/determinism/matter-portable.test.js asserts Phaser.VERSION is
 * '3.90.0' and checks each function's contract against the original, so an upgrade fails loudly instead of silently diverging.
 * Idempotent. Any change to these bodies changes simulation results: bump SIM_REVISION.
 */
import pmath from './pmath.js';

export const EXPECTED_PHASER_VERSION = '3.90.0';
/** `Module.function` names replaced on the Matter object, in a stable order (also pinned by the test). */
export const PATCHED_FUNCTIONS = Object.freeze([
  'Axes.rotate', 'Vector.rotate', 'Vector.rotateAbout', 'Vector.angle', 'Vertices.rotate', 'Vertices.chamfer',
  'Bodies.polygon', 'Body.rotate', 'Composite.rotate',
]);
export const PORTABLE_FLAG = '__bbPortableMath';

/**
 * @param {object} Matter the Matter module Phaser bundles (Phaser.Physics.Matter.Matter).
 * @returns {boolean} true when installed (or already installed); false when Matter lacks the modules (logic-only test mocks).
 */
export function installPortableMatter(Matter) {
  if (!Matter || !Matter.Axes || !Matter.Vector || !Matter.Vertices || !Matter.Bodies || !Matter.Body || !Matter.Composite || !Matter.Common) return false;
  if (Matter.Vector.rotate[PORTABLE_FLAG]) return true;
  const { Axes, Vector, Vertices, Bodies, Body, Composite, Common } = Matter;
  const orig = {};
  const put = (mod, name, fn) => {
    const o = Matter[mod][name];
    orig[`${mod}.${name}`] = o;
    fn[PORTABLE_FLAG] = true;
    fn.original = o;
    Matter[mod][name] = fn;
  };

  put('Axes', 'rotate', function rotate(axes, angle) {
    if (angle === 0) return;
    const cos = pmath.cos(angle), sin = pmath.sin(angle);
    for (let i = 0; i < axes.length; i++) {
      const axis = axes[i];
      const xx = axis.x * cos - axis.y * sin;
      axis.y = axis.x * sin + axis.y * cos;
      axis.x = xx;
    }
  });

  put('Vector', 'rotate', function rotate(vector, angle, output) {
    const cos = pmath.cos(angle), sin = pmath.sin(angle);
    if (!output) output = {};
    const x = vector.x * cos - vector.y * sin;
    output.y = vector.x * sin + vector.y * cos;
    output.x = x;
    return output;
  });

  put('Vector', 'rotateAbout', function rotateAbout(vector, angle, point, output) {
    const cos = pmath.cos(angle), sin = pmath.sin(angle);
    if (!output) output = {};
    const x = point.x + ((vector.x - point.x) * cos - (vector.y - point.y) * sin);
    output.y = point.y + ((vector.x - point.x) * sin + (vector.y - point.y) * cos);
    output.x = x;
    return output;
  });

  put('Vector', 'angle', function angle(vectorA, vectorB) {
    return pmath.atan2(vectorB.y - vectorA.y, vectorB.x - vectorA.x);
  });

  put('Vertices', 'rotate', function rotate(vertices, angle, point) {
    if (angle === 0) return;
    const cos = pmath.cos(angle), sin = pmath.sin(angle), pointX = point.x, pointY = point.y, n = vertices.length;
    for (let i = 0; i < n; i++) {
      const vertex = vertices[i];
      const dx = vertex.x - pointX, dy = vertex.y - pointY;
      vertex.x = pointX + (dx * cos - dy * sin);
      vertex.y = pointY + (dx * sin + dy * cos);
    }
  });

  put('Vertices', 'chamfer', function chamfer(vertices, radius, quality, qualityMin, qualityMax) {
    if (typeof radius === 'number') radius = [radius];
    else radius = radius || [8];
    quality = (typeof quality !== 'undefined') ? quality : -1; // -1 = automatic
    qualityMin = qualityMin || 2;
    qualityMax = qualityMax || 14;
    const newVertices = [];
    for (let i = 0; i < vertices.length; i++) {
      const prevVertex = vertices[i - 1 >= 0 ? i - 1 : vertices.length - 1];
      const vertex = vertices[i];
      const nextVertex = vertices[(i + 1) % vertices.length];
      const currentRadius = radius[i < radius.length ? i : radius.length - 1];
      if (currentRadius === 0) { newVertices.push(vertex); continue; }
      const prevNormal = Vector.normalise({ x: vertex.y - prevVertex.y, y: prevVertex.x - vertex.x });
      const nextNormal = Vector.normalise({ x: nextVertex.y - vertex.y, y: vertex.x - nextVertex.x });
      const diagonalRadius = Math.sqrt(2 * pmath.pow(currentRadius, 2));
      const radiusVector = Vector.mult(Common.clone(prevNormal), currentRadius);
      const midNormal = Vector.normalise(Vector.mult(Vector.add(prevNormal, nextNormal), 0.5));
      const scaledVertex = Vector.sub(vertex, Vector.mult(midNormal, diagonalRadius));
      let precision = quality;
      if (quality === -1) precision = pmath.pow(currentRadius, 0.32) * 1.75; // automatic precision
      precision = Common.clamp(precision, qualityMin, qualityMax);
      if (precision % 2 === 1) precision += 1; // an even value is more likely to reduce axes by symmetry
      const alpha = pmath.acos(Vector.dot(prevNormal, nextNormal));
      const theta = alpha / precision;
      for (let j = 0; j < precision; j++) newVertices.push(Vector.add(Vector.rotate(radiusVector, theta * j), scaledVertex));
    }
    return newVertices;
  });

  put('Bodies', 'polygon', function polygon(x, y, sides, radius, options) {
    options = options || {};
    if (sides < 3) return Bodies.circle(x, y, radius, options);
    const theta = 2 * Math.PI / sides;
    let path = '';
    const offset = theta * 0.5;
    for (let i = 0; i < sides; i += 1) {
      const angle = offset + (i * theta);
      const xx = pmath.cos(angle) * radius;
      const yy = pmath.sin(angle) * radius;
      path += 'L ' + xx.toFixed(3) + ' ' + yy.toFixed(3) + ' ';
    }
    const poly = { label: 'Polygon Body', position: { x, y }, vertices: Vertices.fromPath(path) };
    if (options.chamfer) {
      const chamferOpt = options.chamfer;
      poly.vertices = Vertices.chamfer(poly.vertices, chamferOpt.radius, chamferOpt.quality, chamferOpt.qualityMin, chamferOpt.qualityMax);
      delete options.chamfer;
    }
    return Body.create(Common.extend({}, poly, options));
  });

  put('Body', 'rotate', function rotate(body, rotation, point, updateVelocity) {
    if (!point) {
      Body.setAngle(body, body.angle + rotation, updateVelocity);
    } else {
      const cos = pmath.cos(rotation), sin = pmath.sin(rotation);
      const dx = body.position.x - point.x, dy = body.position.y - point.y;
      Body.setPosition(body, { x: point.x + (dx * cos - dy * sin), y: point.y + (dx * sin + dy * cos) }, updateVelocity);
      Body.setAngle(body, body.angle + rotation, updateVelocity);
    }
  });

  put('Composite', 'rotate', function rotate(composite, rotation, point, recursive) {
    const cos = pmath.cos(rotation), sin = pmath.sin(rotation);
    const bodies = recursive ? Composite.allBodies(composite) : composite.bodies;
    for (let i = 0; i < bodies.length; i++) {
      const body = bodies[i];
      const dx = body.position.x - point.x, dy = body.position.y - point.y;
      Body.setPosition(body, { x: point.x + (dx * cos - dy * sin), y: point.y + (dx * sin + dy * cos) });
      Body.rotate(body, rotation);
    }
    return composite;
  });

  Matter[PORTABLE_FLAG] = orig;
  return true;
}

/** Test helper: the original (native-Math) functions captured at install time, or null before install. */
export function originalMatterFunctions(Matter) { return (Matter && Matter[PORTABLE_FLAG]) || null; }/**
 * Micro Mountain glow-up: the HUGE bees of the dew-drops backdrop. Pure, cosmetic only.
 *
 * SledHEAD canon (Marvin): Micro Mountain is the wild space Pete keeps for his bees, and the player rides it
 * as an RC micro sled drone. The bees are ordinary bees at ordinary bee size, so next to the micro rider they
 * are huge. They are pollinators going about their business: one or two on screen at most, drifting slowly,
 * wings a blur.
 *
 * WHY A SEPARATE PURE MODULE. Background.js is an entity; the placement, the motion and the drawn shape are
 * pure functions of (scrollX, timeMs, seed), so they live here where Jest can sweep them. Background only
 * appends `beePrimitives(beesAt(...))` to the dew-drops decor and draws them with its existing decor painter.
 *
 * RULES (tests/src/micro-bees.test.js):
 *  - no Phaser, window, Math.random or Date.now: layout from a seeded mulberry32, animation from scene time;
 *  - palette KEYS only and never `danger`, so colourblind mode and the biome palette apply and only hazards
 *    read as hazards;
 *  - low alpha (BEE_MAX_FILL_ALPHA / BEE_MAX_LINE_ALPHA) so a Dew Drop or a Royal Jelly Wax in front of a bee
 *    keeps its contrast;
 *  - inside the W6 decor bounds: 0..GAME_HEIGHT vertically, at most 96 px of overhang left and right;
 *  - zero gameplay effect: nothing here is read by the generator, the physics or the sim.
 */
import { GAME_WIDTH, GAME_HEIGHT } from '../constants.js';

/** Bees per tile. The tile is far wider than the screen, so each bee is on screen at most once: <= 2 visible. */
export const BEE_COUNT = 2;
/** Horizontal tile (layer px) the bees repeat over. */
export const BEE_TILE = 1800;
/** Parallax factor: slow, so a bee drifts past rather than whipping by at top speed. */
export const BEE_PARALLAX = 0.04;
/** A bee's full height (wing tip to feet) as a fraction of the screen height: "a quarter to a half". */
export const BEE_HEIGHT = Object.freeze([0.3, 0.4]);
/** The most any bee fill may add over the backdrop (the bg-coloured stripes excepted, they only darken). */
export const BEE_MAX_FILL_ALPHA = 0.1;
/** The most any bee line may add. */
export const BEE_MAX_LINE_ALPHA = 0.3;

/** A bee's geometry is in units of `u`, where the full height is 0.6 u (see beePrimitives). */
const HEIGHT_U = 0.6;
/** Half the widest extent of a bee in u (the stinger behind, the antennae in front), with a margin for the tilt. */
const HALF_W_U = 0.48;
/** The W6 decor overhang rule; the fade keeps the drawn bee inside it. */
const OVERHANG = 96;

/** mulberry32: visual-only, deterministic randomness (the same generator the backdrop decor uses). */
function mulberry32(a) {
  return () => {
    a |= 0;
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

/**
 * The fixed per-seed bee layout. Pure: rebuilt on every call (a handful of PRNG draws), so the output can
 * never depend on what was drawn before.
 * @param {number} [seed=0] the backdrop's decor seed (Background.decorSeed)
 * @returns {Array<{id:number,x0:number,dir:1|-1,speed:number,y0:number,h:number,ph:number}>}
 */
export function beeLayout(seed = 0) {
  const s = Number.isFinite(seed) ? Math.trunc(seed) : 0;
  const rnd = mulberry32((0xb33b ^ Math.imul(s, 0x9e3779b1)) >>> 0);
  const span = (lo, hi) => lo + rnd() * (hi - lo);
  const out = [];
  for (let i = 0; i < BEE_COUNT; i++) {
    const h = span(BEE_HEIGHT[0], BEE_HEIGHT[1]) * GAME_HEIGHT;
    out.push({
      id: i,
      // spread across the tile so the two are rarely on screen together
      x0: (i + span(0.1, 0.6)) * (BEE_TILE / BEE_COUNT),
      dir: rnd() < 0.5 ? -1 : 1,
      speed: span(7, 14), // px/s of its own, on top of the parallax drift
      // the body centre; leaves room for the wings above and the feet below at the largest size
      y0: span(0.42, 0.5) * GAME_HEIGHT,
      h,
      ph: rnd() * Math.PI * 2,
    });
  }
  return out;
}

/**
 * The bees on screen at one camera scroll and scene time. Pure.
 * @param {number} scrollX camera scroll X (world px)
 * @param {number} [timeMs=0] scene time
 * @param {number} [seed=0] layout seed
 * @returns {Array<{id:number,x:number,y:number,h:number,dir:1|-1,rot:number,flap:number,alpha:number}>}
 *   x/y the body centre on screen, h the full height in px, rot the body tilt (rad), flap the wing phase
 *   (rad), alpha 0..1 (fades in and out at the screen edges so a bee never pops)
 */
export function beesAt(scrollX, timeMs = 0, seed = 0) {
  const sx = Number.isFinite(scrollX) ? scrollX : 0;
  const t = Number.isFinite(timeMs) ? timeMs : 0;
  const out = [];
  for (const b of beeLayout(seed)) {
    const halfW = (b.h / HEIGHT_U) * HALF_W_U;
    // the widest the centre may go and still keep every point inside the overhang rule
    const edge = OVERHANG - halfW;
    let x = (b.x0 + b.dir * b.speed * (t / 1000) - sx * BEE_PARALLAX) % BEE_TILE;
    if (x < 0) x += BEE_TILE;
    x -= edge; // the tile starts at the left limit: x runs over [-edge, BEE_TILE - edge)
    if (x > GAME_WIDTH + edge) continue;
    // fade over the band where part of the bee is outside the screen
    const inL = (x + edge) / (halfW + edge);
    const inR = (GAME_WIDTH + edge - x) / (halfW + edge);
    const alpha = Math.max(0, Math.min(1, inL, inR));
    if (alpha <= 0.01) continue;
    out.push({
      id: b.id,
      x,
      y: b.y0 + Math.sin(t / 900 + b.ph) * 5,
      h: b.h,
      dir: b.dir,
      rot: Math.sin(t / 1300 + b.ph) * 0.07,
      flap: (t / 9 + b.ph) % (Math.PI * 2),
      alpha,
    });
  }
  return out;
}

/** Rotate local (lx, ly) by `rot` about the bee centre and mirror by `dir`. */
function place(bee, lx, ly) {
  const c = Math.cos(bee.rot);
  const s = Math.sin(bee.rot);
  const x = lx * bee.dir;
  return { x: bee.x + x * c - ly * s, y: bee.y + x * s + ly * c };
}

/** Closed ellipse in bee-local space, as screen points. */
function ellipse(bee, cx, cy, rx, ry, rot, n) {
  const pts = [];
  const cr = Math.cos(rot);
  const sr = Math.sin(rot);
  for (let i = 0; i < n; i++) {
    const a = (i / n) * Math.PI * 2;
    const ex = Math.cos(a) * rx;
    const ey = Math.sin(a) * ry;
    pts.push(place(bee, cx + ex * cr - ey * sr, cy + ex * sr + ey * cr));
  }
  return pts;
}

/**
 * The drawable primitives for some bees, in the motifDecor format (`poly`, `line`, `circle`; a palette colour
 * KEY each, never `danger`), all at one decor `depth`, each tagged `bee: id`. Pure.
 *
 * Neon vector bee, side view, facing `dir`: two translucent wing blurs at the extremes of the stroke and a
 * rim on the current wing; a striped abdomen (amber outline, bg bands) with a stinger; a fuzzy thorax; a head
 * with an eye and antennae; two dangling legs. About 34 draw calls a bee.
 * @param {Array<Object>} bees from beesAt
 * @param {number} depth the decor depth to draw at (Background: after the last silhouette layer)
 * @returns {Array<Object>}
 */
export function beePrimitives(bees, depth) {
  const out = [];
  for (const bee of bees || []) {
    const u = bee.h / HEIGHT_U;
    const a = bee.alpha;
    const tag = { depth, bee: bee.id };
    const F = (v) => Math.min(BEE_MAX_FILL_ALPHA, v) * a;
    const Ln = (v) => Math.min(BEE_MAX_LINE_ALPHA, v) * a;
    // wings: attached on top of the thorax, swept back; two blurs at the ends of the stroke, a rim on the
    // current position (flap), so the wing reads as a fast blur rather than a solid shape
    const wx = -0.02 * u;
    const wy = -0.1 * u;
    const wing = (ang) => ellipse(bee, wx - Math.sin(ang) * 0.17 * u, wy - Math.cos(ang) * 0.17 * u, 0.075 * u, 0.17 * u, -ang, 12);
    out.push({ kind: 'poly', ...tag, color: 'text', fillAlpha: F(0.07), lineAlpha: 0, pts: wing(0.15) });
    out.push({ kind: 'poly', ...tag, color: 'cyan', fillAlpha: F(0.06), lineAlpha: 0, pts: wing(0.75) });
    out.push({ kind: 'poly', ...tag, color: 'cyan', fillAlpha: 0, lineAlpha: Ln(0.22), pts: wing(0.45 + Math.sin(bee.flap) * 0.3) });
    // abdomen: amber body and outline, three bg-coloured bands, a stinger at the tail
    const ax = -0.17 * u;
    const ay = 0.035 * u;
    const arx = 0.24 * u;
    const ary = 0.14 * u;
    const tilt = 0.12;
    out.push({ kind: 'poly', ...tag, color: 'amber', fillAlpha: F(0.1), lineAlpha: Ln(0.3), pts: ellipse(bee, ax, ay, arx, ary, tilt, 16) });
    for (const k of [-0.45, 0, 0.42]) {
      const w = 0.06;
      const band = [];
      for (const [fx, sy] of [[k - w, -1], [k + w, -1], [k + w, 1], [k - w, 1]]) {
        const hy = ary * Math.sqrt(Math.max(0, 1 - fx * fx)) * 0.92;
        const lx = fx * arx;
        const ly = sy * hy;
        band.push(place(bee, ax + lx * Math.cos(tilt) - ly * Math.sin(tilt), ay + lx * Math.sin(tilt) + ly * Math.cos(tilt)));
      }
      out.push({ kind: 'poly', ...tag, color: 'bg', fillAlpha: 0.45 * a, lineAlpha: 0, pts: band });
    }
    const tail = place(bee, ax - arx * Math.cos(tilt), ay - arx * Math.sin(tilt));
    const sting = place(bee, ax - (arx + 0.05 * u) * Math.cos(tilt), ay - (arx + 0.05 * u) * Math.sin(tilt) + 0.01 * u);
    out.push({ kind: 'line', ...tag, color: 'amber', alpha: Ln(0.3), width: 1, pts: [tail, sting] });
    // thorax: a fuzzy ball (text rim over a faint amber fill)
    out.push({ kind: 'poly', ...tag, color: 'amber', fillAlpha: F(0.08), lineAlpha: 0, pts: ellipse(bee, 0.04 * u, -0.01 * u, 0.1 * u, 0.095 * u, 0, 12) });
    out.push({ kind: 'poly', ...tag, color: 'text', fillAlpha: 0, lineAlpha: Ln(0.2), pts: ellipse(bee, 0.04 * u, -0.01 * u, 0.1 * u, 0.095 * u, 0, 12) });
    // head, eye, antennae
    const hx = 0.19 * u;
    const hy = 0.02 * u;
    out.push({ kind: 'poly', ...tag, color: 'amber', fillAlpha: 0, lineAlpha: Ln(0.28), pts: ellipse(bee, hx, hy, 0.065 * u, 0.075 * u, 0, 10) });
    const eye = place(bee, hx + 0.025 * u, hy - 0.015 * u);
    out.push({ kind: 'circle', ...tag, color: 'text', fillAlpha: F(0.1), lineAlpha: 0, x: eye.x, y: eye.y, r: Math.max(1, 0.025 * u) });
    const ab = place(bee, hx + 0.01 * u, hy - 0.07 * u);
    out.push({
      kind: 'line', ...tag, color: 'text', alpha: Ln(0.25), width: 1,
      pts: [place(bee, hx + 0.16 * u, hy - 0.17 * u), place(bee, hx + 0.1 * u, hy - 0.12 * u), ab, place(bee, hx + 0.21 * u, hy - 0.11 * u)],
    });
    // two legs dangling from the thorax, swaying a little with the flight
    const sway = Math.sin(bee.flap * 0.1) * 0.02 * u;
    for (const lx of [-0.01, 0.08]) {
      out.push({
        kind: 'line', ...tag, color: 'text', alpha: Ln(0.2), width: 1,
        pts: [place(bee, lx * u, 0.07 * u), place(bee, (lx - 0.03) * u + sway, 0.15 * u), place(bee, (lx - 0.01) * u + sway, 0.22 * u)],
      });
    }
  }
  return out;
}/**
 * OWNER: progression engineer. NO Phaser imports.
 * Public signatures are a contract - do not change without updating src/ARCHITECTURE.md.
 *
 * W2 — Missions (pure). Everything here is data + arithmetic on the profile and a RunRecord; no
 * rendering, no storage, no clocks. The service that wires this to events lives elsewhere.
 *
 * Determinism is the load-bearing property: a mission draw is a pure function of
 * `profile.missions.counter` (and the profile's unlocks), so two devices at the same counter show
 * the same three missions and a replayed run can never re-roll the slots. No Math.random and no
 * Date.now anywhere in this file.
 *
 * Three mission families:
 *   singleRun   one run must reach `target` on `metric`
 *   cumulative  `metric` accumulates across runs until it reaches `target`
 *   combo       the same run must contain every trick in `require`
 */
import { Rng } from './Rng.js';
import { earnedBiomeIds, unlockedBiomeIds, enabledBiomeMask, BASE_BIOME_ID } from './ProfileStore.js';

/** How many missions are active at once (spec §5 W2). */
export const SLOTS = 3;

/** Base payout for finishing one mission. */
export const MISSION_REWARD = Object.freeze({ xp: 60, shards: 8 });

/** Bonus for clearing all SLOTS in one run. */
export const SET_BONUS = Object.freeze({ xp: 150, shards: 20 });

/** Tier multipliers applied to MISSION_REWARD; index 1..4. */
const TIER_MULT = [0, 1, 1.6, 2.4, 3.5];

/** RunRecord fields that can feed a singleRun/cumulative metric. */
const RECORD_METRICS = new Set([
  'distanceM', 'score', 'shards', 'nearMisses', 'maxAirtimeMs', 'bestCombo', 'tricks',
  // #65: arcade bridges the sled entered this run. Not stored in the RunRecord (and so not in any ledger hash):
  // MissionsService counts BIOME_ENTER `{id:null}` events and hands the total to the roll beside the record.
  'bridges',
  // #65: power-ups collected this run, by power-up id (`{mapleWax: 2}`); a template names the one it wants in `pickup`.
  // Same route as `bridges`: counted live from POWERUP_COLLECTED, never stored in the RunRecord.
  'pickups',
]);

/**
 * Trick families: a mission may ask for a family name and accept any variant the tracker emits.
 * TrickTracker emits `helicopterCCW` / `helicopterCW`, and a player has no way to choose which way
 * they spin, so a mission asking for "a heli" must accept both. Getting this wrong would make a
 * mission impossible for roughly half of all runs.
 */
const TRICK_FAMILIES = Object.freeze({
  helicopter: ['helicopterCCW', 'helicopterCW'],
  flip: ['backflip', 'frontflip'],
});

const isNum = (v) => typeof v === 'number' && Number.isFinite(v);
const tierOf = (t) => (isNum(t && t.tier) ? Math.min(4, Math.max(1, Math.round(t.tier))) : 1);

/** XP a template pays when completed. */
export function xpForTemplate(t) {
  return Math.round(MISSION_REWARD.xp * TIER_MULT[tierOf(t)]);
}

/** Shards a template pays when completed. */
export function shardsForTemplate(t) {
  return Math.round(MISSION_REWARD.shards * TIER_MULT[tierOf(t)]);
}

/**
 * Did the run contain this trick? Family names expand to their variants.
 * @param {Object<string,number>} tricks trick type -> count
 * @param {string} want
 */
export function hasTrick(tricks, want) {
  if (!tricks || typeof tricks !== 'object') return false;
  const family = TRICK_FAMILIES[want];
  if (family) return family.some((k) => (tricks[k] || 0) > 0);
  return (tricks[want] || 0) > 0;
}

/**
 * Read this run's value for a template's metric. Cumulative templates count the run's contribution;
 * `runs` counts the run itself as 1.
 * @param {Object} t template
 * @param {{record?:*, profile?:*, live?:*}} ctx
 * @returns {number} finite, >= 0
 */
function runValue(t, ctx) {
  const record = (ctx && ctx.record) || {};
  const live = (ctx && ctx.live) || null;
  const metric = t && t.metric;
  if (!metric) return 0;
  if (metric === 'runs') return 1;
  if (metric === 'pickups') {
    const byId = (live && live.pickups) || record.pickups;
    const n = byId && typeof byId === 'object' && typeof t.pickup === 'string' && Object.hasOwn(byId, t.pickup) ? byId[t.pickup] : 0;
    return isNum(n) ? Math.max(0, n) : 0;
  }
  // Live counters (mid-run toasts) win when present: they are strictly fresher than the record.
  if (live && isNum(live[metric])) return Math.max(0, live[metric]);
  if (isNum(record[metric])) return Math.max(0, record[metric]);
  return 0;
}

/**
 * Progress toward a template, 0..target, inclusive and capped so bars never overflow.
 * @param {Object} t
 * @param {{record?:*, profile?:*, live?:*}} ctx
 * @returns {number}
 */
export function progressFor(t, ctx) {
  if (!t || typeof t !== 'object') return 0;
  if (t.type === 'combo') {
    const req = comboRequirement(t);
    if (!req.length) return 0;
    const have = new Set(comboTricksFrom(ctx).map(familyOf));
    return req.filter((r) => have.has(familyOf(r))).length;
  }
  const target = isNum(t.target) ? t.target : 0;
  if (!(target > 0)) return 0;
  let have = runValue(t, ctx);
  if (t.type === 'cumulative') {
    const banked = ctx && ctx.profile && ctx.profile.missions && ctx.profile.missions.progress;
    const prev = banked && isNum(banked[t.id]) ? banked[t.id] : 0;
    have += Math.max(0, prev);
  }
  return Math.min(target, Math.max(0, have));
}

/** The `require` list of a combo template, normalised to a string array. */
/** Canonical family name for a trick type, so 'helicopter' and 'helicopterCCW' compare equal. */
function familyOf(name) {
  const n = String(name || '');
  for (const [fam, members] of Object.entries(TRICK_FAMILIES)) {
    if (fam === n || members.includes(n)) return fam;
  }
  return n;
}

/** Trick-type names from the current combo, in the shapes contexts provide them. */
function comboTricksFrom(ctx) {
  const c = ctx && (ctx.combo || (ctx.live && ctx.live.combo) || (ctx.record && ctx.record.combo));
  if (!Array.isArray(c)) return [];
  return c.map((x) => (typeof x === 'string' ? x : (x && (x.type || x.trick)) || '')).filter(Boolean);
}

function comboRequirement(t) {
  return Array.isArray(t.require) ? t.require.filter((r) => typeof r === 'string') : [];
}

/**
 * Is the template satisfied by this context?
 *
 * Combo templates must be met *within a single combo*, not merely somewhere in the run. That is what
 * the mission title says ("land a backflip and a heli in one combo"), so an aggregate trick tally
 * would pay for behaviour the player was never asked to perform. The live side supplies real combo
 * membership: RunScene's COMBO_CHANGED carries `tricks: snap.comboTricks`. When a context has no combo
 * membership at all (a bare RunRecord, which does not group tricks by combo), a combo mission is NOT
 * satisfied — we under-award rather than pay for the wrong thing.
 *
 * @param {Object} t
 * @param {{record?:*, profile?:*, live?:*, combo?:string[]}} ctx
 */
export function satisfies(t, ctx) {
  if (!t || typeof t !== 'object') return false;
  // A biome mission ("1500 m in Debutmont") is met only on a run that had that biome switched on. The mask
  // is the run's (record.biomeMask, or the live counters' copy mid-run); the bit is resolved exactly as the
  // draw gate resolves it, so a mission can never be offered under one rule and completed under another.
  if (t.biome) {
    const live = ctx && ctx.live;
    const record = ctx && ctx.record;
    const runMask = live && isNum(live.biomeMask) ? live.biomeMask : (record && isNum(record.biomeMask) ? record.biomeMask : 0);
    if (!maskCoversBiome(runMask, t.biome, ctx && ctx.biomeDefs)) return false;
  }
  if (t.type === 'combo') {
    const req = comboRequirement(t);
    if (!req.length) return false;
    const combo = comboTricksFrom(ctx);
    if (combo.length) {
      const have = new Set(combo.map((n) => familyOf(n)));
      return req.every((r) => have.has(familyOf(r)));
    }
    // No combo membership available: fall back to the aggregate only when the template explicitly
    // opts in. Default is strict.
    if (t.allowAnyCombo === true) {
      const tricks = (ctx && ctx.record && ctx.record.tricks) || {};
      return req.every((r) => hasTrick(tricks, r));
    }
    return false;
  }
  const target = isNum(t.target) ? t.target : 0;
  if (!(target > 0)) return false;
  return progressFor(t, ctx) >= target;
}

/**
 * UI state for one mission: fraction 0..1, done flag and a short progress string.
 * Never throws, even for a malformed template or missing context.
 * @param {Object} t
 * @param {{record?:*, profile?:*, live?:*}} ctx
 * @returns {{id:string, fraction:number, done:boolean, text:string, have:number, target:number}}
 */
export function missionState(t, ctx) {
  const safe = t && typeof t === 'object' ? t : {};
  const target = isNum(safe.target) ? safe.target : comboRequirement(safe).length;
  const done = satisfies(safe, ctx);
  let have = 0;
  let fraction = 0;
  let text = '';
  if (safe.type === 'combo') {
    const req = comboRequirement(safe);
    have = progressFor(safe, ctx);
    fraction = req.length ? have / req.length : 0;
    text = `${have}/${req.length} tricks`;
  } else {
    have = progressFor(safe, ctx);
    fraction = target > 0 ? Math.min(1, have / target) : 0;
    text = `${fmt(have)}/${fmt(target)}`;
  }
  return { id: String(safe.id || ''), fraction, done, text, have, target };
}

/** Short progress text for a mission, for the HUD strip / Title list. */
export function missionProgressText(t, have) {
  const safe = t && typeof t === 'object' ? t : {};
  const target = isNum(safe.target) ? safe.target : comboRequirement(safe).length;
  const h = isNum(have) ? have : 0;
  if (safe.type === 'combo') return `${h}/${target} tricks`;
  return `${fmt(h)}/${fmt(target)}`;
}

/** Thousands separators without relying on toLocaleString (Jest environments vary). */
function fmt(n) {
  const v = Math.round(isNum(n) ? n : 0);
  return String(v).replace(/\B(?=(\d{3})+(?!\d))/g, ',');
}

/**
 * Deterministic mission seed for a counter. Namespaced so it cannot collide with terrain/hazard
 * streams derived from a run seed.
 */
export function missionSeed(counter, extra) {
  const c = isNum(counter) ? Math.max(0, Math.round(counter)) : 0;
  return extra ? `missions:${c}:${extra}` : `missions:${c}`;
}

/**
 * Is a template offerable to this profile? Biome-tied missions need the biome unlocked AND enabled
 * via the biome mask, and templates excluded by the active daily rule are filtered out.
 * @param {Object} t
 * @param {Object} profile
 * @param {string|null} ruleId
 */
export function isOfferable(t, profile, ruleId, biomeDefs) {
  if (!t || typeof t !== 'object') return false;
  const defs = Array.isArray(biomeDefs) ? biomeDefs : [];
  if (Array.isArray(t.excludedRuleIds) && ruleId && t.excludedRuleIds.includes(ruleId)) return false;
  if (t.needsBridges) {
    // #65: a bridge only exists between two biomes, so the player needs an earned biome besides the base one, and
    // not all of them switched OFF (the enabled mask has no bit for the base biome, so a zero mask means no bridges).
    // With no table (a legacy caller) an OFF choice cannot be resolved, so the earned check alone decides.
    const earned = (defs.length ? earnedBiomeIds(profile, defs) : unlockedBiomeIds(profile)).filter((id) => id !== BASE_BIOME_ID);
    if (!earned.length) return false;
    if (defs.length && enabledBiomeMask(profile, defs) === 0) return false;
  }
  if (t.biome) {
    // Earned, not merely listed: `profile.unlocked.biomes` is part of the profile shape but nothing
    // populates it, so reading it alone made every biome mission unofferable to a real profile.
    // With no table (a legacy caller) fall back to the profile's own view, which is the pre-W3
    // behaviour; the run-start and draw paths always pass the table.
    const unlocked = defs.length ? earnedBiomeIds(profile, defs) : unlockedBiomeIds(profile);
    if (!unlocked.includes(t.biome)) return false;
    // A disabled signature must not spawn missions for terrain the player will never see. Unlocked biomes
    // default ON (issue #65), so what is OFF is the profile's explicit `biomeOff`; the enabled mask resolves
    // that against the biome table. The base biome has no bit in it and is always eligible. With no table
    // (a legacy caller) an OFF choice cannot be resolved to a biome, so the unlocked check above decides.
    if (defs.length && !maskCoversBiome(enabledBiomeMask(profile, defs), t.biome, defs)) return false;
  }
  return true;
}

/**
 * Does a biome mask include this biome? Shared by the draw gate (the profile's enabled mask) and the completion
 * gate (the run's mask) so the two can never drift. The base biome is always covered.
 *
 * With no table to resolve the id against (a legacy caller), the only decidable case is "everything off",
 * so that fails closed and any non-zero mask passes; with a table, the biome's own bit must be set.
 * @param {number} mask
 * @param {string} biomeId
 * @param {Array<{id:string,bit:number}>} [biomeDefs]
 * @returns {boolean}
 */
function maskCoversBiome(mask, biomeId, biomeDefs) {
  // The base biome is the terrain of every run, whatever its mask (Daily, seed@mask, Gym), so a mission for
  // it is always eligible and completable ("1500 m in Debutmont" must not depend on a no-op bit).
  if (biomeId === BASE_BIOME_ID) return true;
  const m = isNum(mask) ? mask >>> 0 : 0;
  const defs = Array.isArray(biomeDefs) ? biomeDefs : [];
  const def = defs.find((d) => d && d.id === biomeId);
  const bit = def && isNum(def.bit) ? def.bit : null;
  if (bit === null) return m !== 0;
  return (m & bit) !== 0;
}

/**
 * Draw `count` distinct offerable missions for this profile, deterministically.
 *
 * Selection: seed a stream from `profile.missions.counter`, then walk the offerable list and pick
 * without replacement. Ordering the candidates by id first keeps the result independent of how the
 * JSON happens to be sorted on disk.
 *
 * @param {Object} profile
 * @param {Array} templates
 * @param {number} [count=SLOTS]
 * @param {{ruleId?:string|null, exclude?:string[]}} [o]
 * @returns {Array} chosen templates (fewer than `count` only if the pool is smaller)
 */
/** Default tier thresholds, mirroring `missions.json: tierUnlock`. Kept here only as a fallback for
 * callers that pass a bare template array (tests, tools); the app always passes the data value. */
export const DEFAULT_TIER_UNLOCK = Object.freeze({ 1: 1, 2: 3, 3: 6, 4: 10 });

/**
 * The highest mission tier a given Sync Level may draw (D7).
 * @param {number} level Sync Level, 1-based
 * @param {Object} [unlock] tier -> min level map, from `missions.json`
 * @returns {number} 1..4
 */
export function maxTierForLevel(level, unlock = DEFAULT_TIER_UNLOCK) {
  const lv = Number.isFinite(level) ? level : 1;
  let best = 1;
  for (const [tier, min] of Object.entries(unlock || {})) {
    const t = Number(tier); const m = Number(min);
    if (Number.isFinite(t) && Number.isFinite(m) && lv >= m && t > best) best = t;
  }
  return best;
}

export function drawMissions(profile, templates, count = SLOTS, o = {}) {
  const all = Array.isArray(templates) ? templates.filter((t) => t && typeof t === 'object') : [];
  const ruleId = o.ruleId !== undefined ? o.ruleId : (profile && profile.missions && profile.missions.ruleId) || null;
  const exclude = new Set([...(o.exclude || []), ...((profile && profile.missions && profile.missions.active) || [])]);
  const unlock = o.tierUnlock || (profile && profile.missions && profile.missions.tierUnlock) || DEFAULT_TIER_UNLOCK;
  const biomeDefs = Array.isArray(o.biomeDefs) ? o.biomeDefs : [];
  const level = (profile && Number.isFinite(profile.level)) ? profile.level : 1;
  const maxTier = maxTierForLevel(level, unlock);
  const eligible = all
    .filter((t) => isOfferable(t, profile, ruleId, biomeDefs))
    .filter((t) => !exclude.has(t.id));
  // D7: low levels draw only low tiers. Filtering (rather than weighting) keeps the seed stream
  // identical for a given counter, so a saved profile's next draw is still reproducible.
  const belowCeiling = (t) => !Number.isFinite(t.tier) || t.tier <= maxTier;
  let pool = eligible.filter(belowCeiling);
  // D7's fill guarantee: "fall back to the highest unlocked tier, never an empty slot". Home's first
  // version read this as licence to widen to EVERY eligible tier, which would hand a level-1 profile a
  // tier-4 mission in a squeeze — it cannot happen against the shipped data, but the code must not
  // depend on that. Widen only to the highest tier at or below the ceiling, never above it, and only
  // as far as needed; if even that cannot fill the set, return a shorter set rather than leak a tier.
  const want = Math.max(1, Math.round(count));
  if (pool.length && pool.length < want) {
    for (let tier = maxTier; tier >= 1 && pool.length < want; tier--) {
      const extra = eligible.filter((t) => t.tier === tier);
      if (extra.length) pool = pool.concat(extra);
    }
  }
  // Dedupe: the widened loop may re-add templates already in the pool.
  const seen = new Set();
  pool = pool
    .filter((t) => (seen.has(t.id) ? false : seen.add(t.id)))
    .sort((a, b) => String(a.id).localeCompare(String(b.id)));
  if (!pool.length) return [];
  const n = Math.min(want, pool.length);
  const rng = new Rng(missionSeed(profile && profile.missions && profile.missions.counter, 'draw'));
  const picked = [];
  const left = pool.slice();
  for (let i = 0; i < n; i++) {
    const idx = rng.int(0, left.length - 1);
    picked.push(left[idx]);
    left.splice(idx, 1);
  }
  return picked;
}

/**
 * Roll the whole set against a finished run: pay for everything completed, carry progress for what
 * is not, draw replacements, and pay the set bonus when all slots were cleared.
 *
 * Pure: returns a new missions block; the caller merges it into the profile and persists.
 *
 * @param {Object} profile
 * @param {Array} activeTemplates templates currently in the slots (unknown ids already dropped)
 * @param {Object} record the finished RunRecord
 * @param {Array} allTemplates full pool, for drawing replacements
 * @param {{ruleId?:string|null, live?:*, appliedHashes?:string[]}} [o] `appliedHashes` are the
 *        ledgerHashes this profile has already been credited for (ProfileStore's bounded ring). A
 *        run whose hash is in there pays nothing — that is what makes a replayed RUN_END, a double
 *        scene start or a retry idempotent. Missions.js stays pure by taking the ring rather than
 *        owning it.
 * @returns {{active:string[], counter:number, progress:Object<string,number>,
 *            completed:Array<{id:string,xp:number,shards:number}>, xp:number, shards:number,
 *            setCleared:boolean, bank:number, duplicate:boolean}}
 */
export function rollSet(profile, activeTemplates, record, allTemplates, o = {}) {
  const p = profile && typeof profile === 'object' ? profile : {};
  const prevMissions = (p.missions && typeof p.missions === 'object') ? p.missions : {};
  const prevActive = Array.isArray(prevMissions.active) ? prevMissions.active : [];
  const prevProgress = (prevMissions.progress && typeof prevMissions.progress === 'object') ? prevMissions.progress : {};
  const all = Array.isArray(allTemplates) ? allTemplates : [];
  const byId = new Map(all.filter((t) => t && t.id).map((t) => [t.id, t]));
  const ruleId = o.ruleId !== undefined ? o.ruleId : (prevMissions.ruleId || null);

  // Idempotency: a run already credited pays nothing. Checked before any mutation so a replay
  // cannot advance progress, re-roll slots or pay a set bonus either.
  const hash = record && typeof record.ledgerHash === 'string' ? record.ledgerHash : '';
  const applied = Array.isArray(o.appliedHashes) ? o.appliedHashes : [];
  if (hash && applied.includes(hash)) {
    return {
      active: prevActive.slice(),
      counter: isNum(prevMissions.counter) ? prevMissions.counter : 0,
      progress: { ...prevProgress },
      completed: [],
      xp: 0,
      shards: 0,
      setCleared: false,
      bank: 0,
      duplicate: true,
    };
  }

  // Resolve the slots. An active id with no template (data removed under the player's feet) is
  // dropped rather than treated as a fatal error.
  const slots = (Array.isArray(activeTemplates) ? activeTemplates : []).filter((t) => t && t.id);

  const completed = [];
  const keep = [];
  const progress = {};
  let xp = 0;
  let shards = 0;

  for (const t of slots) {
    const ctx = {
      record: record || {}, profile: { ...p, missions: { ...prevMissions, progress: prevProgress } }, live: o.live, biomeDefs: o.biomeDefs,
    };
    const done = (t.type === 'combo' && o.completedComboIds instanceof Set && o.completedComboIds.has(t.id)) || satisfies(t, ctx);
    if (done) {
      const gainXp = xpForTemplate(t);
      const gainShards = shardsForTemplate(t);
      xp += gainXp;
      shards += gainShards;
      completed.push({ id: t.id, title: t.title, xp: gainXp, shards: gainShards });
      // The slot is cleared and will be refilled below.
      continue;
    }
    keep.push(t.id);
    // Carry forward cumulative progress (capped at the target) so a long mission keeps its history.
    const have = progressFor(t, ctx);
    if (t.type === 'cumulative') progress[t.id] = Math.min(isNum(t.target) ? t.target : have, have);
    else if (isNum(prevProgress[t.id])) progress[t.id] = prevProgress[t.id];
  }

  const setCleared = slots.length > 0 && completed.length === slots.length && slots.length >= SLOTS;
  if (setCleared) {
    xp += SET_BONUS.xp;
    shards += SET_BONUS.shards;
  }

  // Refill: keep surviving slots, then draw fresh ones that are neither kept nor just completed.
  let counter = isNum(prevMissions.counter) ? prevMissions.counter : 0;
  const targetSlots = Math.max(SLOTS, slots.length || 0);
  let active = keep.slice();
  // A just-completed mission is not a replacement: immediately drawing it again makes the player
  // repeat the same goal instead of seeing a new objective.
  const completedIds = completed.map((c) => c.id);
  let guard = 0;
  while (active.length < targetSlots && guard < 32) {
    guard += 1;
    counter += 1;
    const drawnProfile = { ...p, missions: { ...prevMissions, counter, active, progress } };
    const drawn = drawMissions(drawnProfile, all, targetSlots - active.length, {
      ruleId, exclude: [...active, ...completedIds], tierUnlock: o.tierUnlock,
      biomeDefs: o.biomeDefs,
    });
    if (!drawn.length) break;
    for (const d of drawn) {
      if (active.length >= targetSlots) break;
      if (!active.includes(d.id)) active.push(d.id);
    }
  }
  // Drop progress for missions no longer active so the profile does not grow without bound.
  const activeSet = new Set(active);
  for (const id of Object.keys(progress)) {
    if (!activeSet.has(id)) delete progress[id];
  }
  // Backfill any slot that could not be drawn (tiny pool) rather than leaving a hole the UI must
  // special-case; `byId` keeps this honest about what actually exists.
  for (const id of active) {
    if (!byId.has(id)) active = active.filter((x) => x !== id);
  }

  return {
    active, counter, progress, completed, xp, shards, setCleared, bank: shards, duplicate: false,
  };
}

/**
 * Read the profile's active missions as templates, dropping ids with no template.
 * @param {Object} profile
 * @param {Array} templates
 * @returns {Array}
 */
export function activeTemplates(profile, templates) {
  const ids = (profile && profile.missions && Array.isArray(profile.missions.active)) ? profile.missions.active : [];
  const byId = new Map((Array.isArray(templates) ? templates : []).filter((t) => t && t.id).map((t) => [t.id, t]));
  return ids.map((id) => byId.get(id)).filter(Boolean);
}

/** True when this record's metric is one the missions system understands (used by data validation). */
export function isRecordMetric(metric) {
  return RECORD_METRICS.has(metric) || metric === 'runs';
}/**
 * OWNER: progression engineer. Thin glue: owns the active mission list, rolls it on RUN_END, and
 * publishes UI state. NO Phaser imports, no rendering, no storage of its own.
 *
 * Why this is called BY ProgressionService rather than subscribing to RUN_END itself: crediting is
 * idempotent against the profile's `credited` ring, and that decision belongs to ProgressionService.
 * If missions listened to RUN_END independently, "did this run already pay?" would come down to
 * listener order — a replayed event could pay missions once and XP zero times, or the reverse. One
 * listener, one decision, no second ring.
 */
import { EVT } from '../events.js';
import { REG } from '../constants.js';
import {
  rollSet, activeTemplates, missionState, missionProgressText, xpForTemplate, shardsForTemplate, satisfies,
} from './Missions.js';

/**
 * UI state of a cumulative mission from its banked progress only (no run in flight).
 * @param {Object} t template @param {*} banked profile.missions.progress[t.id]
 * @returns {{fraction:number, text:string, done:boolean}}
 */
function bankedState(t, banked) {
  const target = Number.isFinite(t.target) ? t.target : 0;
  const have = Math.min(target, Math.max(0, Number.isFinite(banked) ? banked : 0));
  return {
    fraction: target > 0 ? have / target : 0,
    text: missionProgressText(t, have),
    done: target > 0 && have >= target,
  };
}

export class MissionsService {
  /**
   * @param {Phaser.Game} game
   * @param {{templates:Array, store:*, now?:function():number}} o
   */
  constructor(game, o) {
    this.game = game;
    this.templates = Array.isArray(o && o.templates) ? o.templates : [];
    /** D7 tier thresholds (tier -> min Sync Level); injected from missions.json at boot. */
    this.tierUnlock = (o && o.tierUnlock) || null;
    /** W3 biome table, so a mission for a switched-off signature is never offered. */
    this.biomeDefs = (o && Array.isArray(o.biomeDefs)) ? o.biomeDefs : [];
    this.store = o && o.store;
    this.now = (o && o.now) || (() => Date.now());
    this.alive = true;
    this.lastRoll = null;
    this._bound = [];
    this._subscribed = false;
    this._completedThisRun = new Set();
    this.resetLive();
  }

  /** @returns {Object} the live profile. */
  get profile() {
    return this.store ? this.store.profile : null;
  }

  /**
   * Boot: make sure the profile has a full set of missions, then publish. Deterministic — the draw
   * depends only on the profile's counter and unlocks, so this is safe to run on every boot.
   * @returns {Promise<MissionsService>}
   */
  async init() {
    this.alive = true;
    this.ensureSlots();
    // ensureSlots() replaces store.profile (applyMissions builds a new object), but ProgressionService
    // published REG.PROFILE before missions existed. Views derive their saves from REG.PROFILE, so a boost
    // toggle before the first run saved the pre-draw profile and wiped the mission set. Republish here.
    if (this.store && this.store.profile && this.game.registry) this.game.registry.set(REG.PROFILE, this.store.profile);
    this.publish();
    this._subscribe();
    this.game.events.once('destroy', () => this.destroy());
    return this;
  }

  /**
   * Track live counters and toast a mission the moment it is met, rather than waiting for RUN_END.
   * The spec asks for exactly this: "evaluated from the final RunRecord plus live events ... so a
   * mid-run completion can toast immediately". Only the counters a mission can actually use are
   * tracked, and none of it is persisted — the final roll at RUN_END is still the source of truth
   * for payout, which is what keeps the live path from ever double-paying.
   */
  _subscribe() {
    const ev = this.game.events;
    if (!ev || this._subscribed) return;
    this._subscribed = true;
    const on = (name, fn) => { ev.on(name, fn); this._bound.push([name, fn]); };

    this.resetLive();
    on(EVT.RUN_START, (payload) => {
      this._gymPractice = payload?.gym === true;
      this.resetLive();
      this._completedThisRun.clear();
      // The run's biome mask, so a biome mission toasts live only when this run can actually pay it.
      // RunScene resolves REG.BIOME_MASK once in create(), before it emits RUN_START, and never re-reads it.
      const reg = this.game.registry;
      const mask = reg && typeof reg.get === 'function' ? reg.get(REG.BIOME_MASK) : 0;
      this.live.biomeMask = Number.isFinite(mask) ? mask >>> 0 : 0;
    });
    on(EVT.RUN_ABORT, () => { this._gymPractice = false; this.resetLive(); });
    on(EVT.DISTANCE_CHANGED, (p) => { this.live.distanceM = (p && p.meters) || 0; this._checkLive(); });
    on(EVT.SCORE_CHANGED, (p) => { this.live.score = (p && p.total) || 0; this._checkLive(); });
    on(EVT.SHARD_COLLECTED, () => { this.live.shards += 1; this._checkLive(); });
    on(EVT.NEAR_MISS, () => { this.live.nearMisses += 1; this._checkLive(); });
    // #65: RunScene announces an arcade bridge as BIOME_ENTER `{id:null, entering:false}`, once per entry (the opening
    // Debutmont enter has an id and does not count). Meta only: nothing here reaches the simulation.
    // #65: power-ups collected this run, by id (RunScene emits POWERUP_COLLECTED once per pickup). Meta only.
    on(EVT.POWERUP_COLLECTED, (p) => {
      const id = p && p.id;
      if (typeof id !== 'string' || !id || id === '__proto__') return;
      this.live.pickups[id] = (Object.hasOwn(this.live.pickups, id) ? this.live.pickups[id] : 0) + 1;
      this._checkLive();
    });
    on(EVT.BIOME_ENTER, (p) => {
      if (!p || p.id !== null || p.entering !== false) return;
      this.live.bridges += 1;
      this._checkLive();
    });
    on(EVT.COMBO_CHANGED, (p) => {
      this.live.bestCombo = Math.max(this.live.bestCombo, (p && p.multiplier) || 1);
      // Real combo membership (RunScene publishes snap.comboTricks), so a combo mission is judged on
      // one combo rather than on the run's aggregate trick tally.
      if (p && Array.isArray(p.tricks)) this.live.combo = p.tricks.map((t) => (typeof t === 'string' ? t : t && (t.type || t.trick))).filter(Boolean);
      this._checkLive();
    });
    on(EVT.LANDING, (p) => {
      const ms = (p && (p.airMs || p.airtimeMs)) || 0;
      if (ms > this.live.maxAirtimeMs) this.live.maxAirtimeMs = ms;
      this._checkLive(Boolean(p && p.quality && p.quality !== 'crash'));
    });
    on(EVT.TRICK, (p) => {
      const t = p && (p.type || p.trick);
      if (typeof t === 'string') this.live.tricks[t] = (this.live.tricks[t] || 0) + 1;
      this._checkLive();
    });
  }

  /** Zero the live counters for a fresh run. */
  resetLive() {
    this.live = { distanceM: 0, score: 0, shards: 0, nearMisses: 0, bridges: 0, pickups: {}, bestCombo: 1, maxAirtimeMs: 0, tricks: {}, combo: [] };
    if (!this._completedThisRun) this._completedThisRun = new Set();
  }

  /**
   * Publish a mid-run toast for any mission whose target the live counters just met. Nothing is
   * paid here — `onRunCredited` at RUN_END remains the only place that pays, so the live path cannot
   * double-award even if a metric oscillates.
   */
  _checkLive(landed = false) {
    // The Gym emits ordinary trick/score/near-miss events for responsive
    // practice feedback. They must NEVER satisfy a live mission, show a
    // mission-completion toast, or consume a mission's per-run completion key.
    if (!this.alive || !this.store || this._gymPractice === true
        || this.game?.registry?.get?.(REG.BSOD_GYM) === true) return;
    const p = this.profile;
    if (!p) return;
    const ctx = { live: this.live, record: this.live, profile: p, biomeDefs: this.biomeDefs };
    for (const t of activeTemplates(p, this.templates)) {
      if (!t || this._completedThisRun.has(t.id)) continue;
      if (t.type === 'combo' && !landed) continue;
      let met = false;
      try { met = satisfies(t, ctx); } catch (e) { met = false; }
      if (!met) continue;
      this._completedThisRun.add(t.id);
      this.game.events.emit(EVT.MISSION_COMPLETED, {
        id: t.id, title: t.title, xp: xpForTemplate(t), shards: shardsForTemplate(t),
      });
    }
  }

  /** Fill any empty mission slots and persist. Safe to call repeatedly. */
  ensureSlots() {
    const p = this.profile;
    if (!p || !this.store) return null;
    const active = activeTemplates(p, this.templates);
    if (active.length >= 3) return null;
    // Reuse the roll path with a synthetic empty record: no mission completes, it only refills.
    const out = rollSet(p, [], { ledgerHash: '', distanceM: 0 }, this.templates, {
      tierUnlock: this.tierUnlock || undefined,
      biomeDefs: this.biomeDefs,
    });
    this.store.applyMissions(out);
    return out;
  }

  /**
   * Apply a finished run to the mission set. Called by ProgressionService only after the run was
   * genuinely credited, so idempotency is already guaranteed upstream.
   *
   * @param {Object} record the finished RunRecord
   * @returns {Object|null} roll result, or null if nothing could be applied
   */
  onRunCredited(record) {
    if (!this.alive) return null;
    const p = this.profile;
    if (!p || !this.store) return null;
    const active = activeTemplates(p, this.templates);
    // `bridges` and `pickups` are per-run counts the RunRecord does not carry; the roll reads them from this copy (never stored).
    const rolled = { ...(record || {}), bridges: this.live.bridges, pickups: { ...this.live.pickups } };
    const out = rollSet(p, active, rolled, this.templates, {
      tierUnlock: this.tierUnlock || undefined,
      biomeDefs: this.biomeDefs,
      completedComboIds: this._completedThisRun,
    });
    this.store.applyMissions(out);
    this.lastRoll = out;
    this.publish(out);
    return out;
  }

  /**
   * Live progress for one mission during a run, for a mid-run toast. Cheap and pure.
   * @param {Object} template
   * @param {{record?:*, live?:*}} ctx
   */
  stateFor(template, ctx) {
    const p = this.profile;
    // The biome table rides along so a biome mission's live state uses the same mask gate as the payout.
    return missionState(template, { biomeDefs: this.biomeDefs, ...ctx, profile: p });
  }

  /**
   * Publish the mission view for the UI: the three actives with their progress, ready to draw.
   * Scenes read this from the registry instead of recomputing geometry.
   * @param {Object} [roll] result of the last roll, if any
   */
  publish(roll) {
    const p = this.profile;
    if (!p) return;
    const actives = activeTemplates(p, this.templates);
    const progress = (p.missions && p.missions.progress) || {};
    const rows = actives.map((t) => {
      // Between runs there is no run to add. A cumulative mission's progress is exactly what is banked in
      // the profile; feeding the banked value in as a record as well published it twice (20/50 showed
      // 40/50, 25/50 showed DONE), and missionState counts any record as one more run for a `runs`
      // metric, so cumulative rows are built from the bank alone. Single-run and combo rows start at 0.
      const st = t.type === 'cumulative' ? bankedState(t, progress[t.id]) : missionState(t, { record: {}, profile: p });
      return {
        id: t.id,
        title: t.title,
        type: t.type,
        tier: t.tier,
        biome: t.biome || null,
        fraction: st.fraction,
        text: st.text,
        done: st.done,
        xp: xpForTemplate(t),
        shards: shardsForTemplate(t),
      };
    });
    const view = {
      active: rows,
      // Completed this run: what the toast and Game Over should list.
      completed: roll && Array.isArray(roll.completed) ? roll.completed : [],
      setCleared: Boolean(roll && roll.setCleared),
      xp: roll ? roll.xp : 0,
      shards: roll ? roll.shards : 0,
    };
    this.game.registry.set(REG.MISSIONS, view);
  }

  /** Detach. Safe to call twice. */
  destroy() {
    this.alive = false;
    const ev = this.game && this.game.events;
    if (ev) for (const [name, fn] of this._bound) ev.off(name, fn);
    this._bound.length = 0;
    this._subscribed = false;
  }
}

/**
 * Build and initialise the missions service.
 * @param {Phaser.Game} game
 * @param {{templates:Array, store:*, now?:function():number}} o
 * @returns {Promise<MissionsService>}
 */
export async function createMissionsService(game, o) {
  const svc = new MissionsService(game, o);
  await svc.init();
  return svc;
}/**
 * OWNER: input/audio/glitch engineer. Pure logic: no DOM, no Phaser (issue #115).
 *
 * Derivation of the held fields of a VirtualPadState from raw button holds. Shared by VirtualPad (live
 * state) and SimClock.padsFor (per-tick pads rebuilt from a timestamped input timeline), so SimClock does
 * not depend on VirtualPad / TouchOverlay.
 */

/**
 * Held fields of a VirtualPadState derived from raw button holds (issue #115: shared by the live pad and by
 * SimClock when it rebuilds a per-tick pad from a timeline).
 * @param {Object<string,boolean>} h raw held name -> down
 * @param {number} analog dead-zoned analog tilt (0 = none)
 * @returns {object}
 */
export function deriveHeld(h, analog = 0) {
  const back = !!h.tiltBack;
  const fwd = !!h.tiltForward;
  const digital = back && fwd ? 0 : fwd ? 1 : back ? -1 : 0;
  return {
    push: !!h.push, brake: !!h.brake, hop: !!h.hop, reset: !!h.reset, airBrake: !!h.airBrake,
    parachute: !!h.parachute, divebomb: !!h.divebomb, corkscrew: !!h.corkscrew, pause: !!h.pause,
    tuck: !!h.tuck || (back && fwd),
    tilt: analog !== 0 ? analog : digital,
    heli: /** @type {-1|0|1} */ ((h.heliRight ? 1 : 0) - (h.heliLeft ? 1 : 0)),
  };
}

/**
 * A DOM event's timeStamp if it is on the performance.now() clock (the clock of Phaser's rAF time), else
 * null. Legacy epoch timestamps, synthetic events and jsdom's Date.now() stamps are rejected, and an
 * untimed change keeps the pre-#115 schedule (first tick of the polling frame).
 * @param {number} t event.timeStamp
 * @param {number} now current performance.now()
 * @returns {number|null}
 */
export function eventTimeOnClock(t, now) {
  if (!Number.isFinite(t) || t <= 0 || !Number.isFinite(now)) return null;
  return t <= now + 1000 && t >= now - 60000 ? t : null;
}

/** performance.now() where available (browsers, jsdom), else Date.now(). @returns {number} */
export const perfNow = () => (typeof performance !== 'undefined' && performance.now ? performance.now() : Date.now());/**
 * Permanent, opt-in, softcapped upgrades.
 *
 * Bought ranks never disappear and there is no designer-imposed maximum rank.
 * Gameplay impact approaches finite asymptotes so repeated purchasing gives
 * diminishing returns. Cost rises as ranks rise. Purchased ranks are disabled
 * on official Daily runs and when UPGRADE MODE is off.
 *
 * This is a pure module: bank mutations and persistence are owned by ProfileStore.
 */
export const UPGRADE_CATALOG = Object.freeze([
  { id: 'speed', label: 'RACE SPEED', basePrice: 28, priceScale: 4, curveK: 12, cap: .30 },
  { id: 'hop', label: 'HOP HEIGHT', basePrice: 26, priceScale: 4, curveK: 12, cap: .22 },
  { id: 'flip', label: 'FLIP CONTROL', basePrice: 30, priceScale: 5, curveK: 10, cap: .33 },
  { id: 'canopy', label: 'PARACHUTE FUEL', basePrice: 34, priceScale: 5, curveK: 14, cap: .70 },
  { id: 'airbrake', label: 'AIRBRAKE LIFT', basePrice: 30, priceScale: 4, curveK: 12, cap: .55 },
  { id: 'divebomb', label: 'DIVEBOMB POWER', basePrice: 27, priceScale: 4, curveK: 10, cap: .48 },
  { id: 'bsodGrace', label: 'BSOD HEAD START', basePrice: 48, priceScale: 7, curveK: 18, cap: .25 },
  // Shard Magnet (owner, 2026-11-20): pull strength, duration and how many magnets drop.
  { id: 'magnetMagnitude', label: 'MAGNET MAGNITUDE', basePrice: 32, priceScale: 5, curveK: 10, cap: 1.5 },
  { id: 'magnetMeasure', label: 'MAGNET MEASURE', basePrice: 30, priceScale: 5, curveK: 10, cap: 1.0 },
  { id: 'magnetMyriad', label: 'MYRIAD MAGNETS', basePrice: 36, priceScale: 6, curveK: 12, cap: 1.0 },
]);
/**
 * High-tier canopy milestone: successful BSOD Bluffing pressurizes the sail.
 * The original 880ms one-tank-per-flight rule remains intact for every
 * clean run and for purchased ranks below 12. Only an actual earned escape
 * (never merely surviving near the wall) can restore spent canopy fuel.
 *
 * Milestone and coefficients are provisional balancing values; recovery
 * per successive Bluff declines without imposing a hard chain limit.
 */
export const CANOPY_BLUFF_RECOVERY_RANK = 12;
export function canopyBluffRecoveryMs(rank, chain, fullMs) {
  if (!Number.isSafeInteger(rank) || rank < CANOPY_BLUFF_RECOVERY_RANK
      || !Number.isSafeInteger(chain) || chain < 1
      || !Number.isFinite(fullMs) || fullMs <= 0) return 0;
  const milestoneRanks = rank - CANOPY_BLUFF_RECOVERY_RANK + 1;
  const fraction = 0.74 * milestoneRanks / (milestoneRanks + 2) / Math.sqrt(chain);
  return Math.max(0, Math.min(fullMs, fullMs * fraction));
}
export const UPGRADE_IDS = Object.freeze(UPGRADE_CATALOG.map(u => u.id));
const byId = Object.fromEntries(UPGRADE_CATALOG.map(u => [u.id, u]));
const validRank = n => Number.isSafeInteger(n) && n >= 0;
export const emptyUpgradeRanks = () => Object.fromEntries(UPGRADE_IDS.map(id => [id, 0]));

/** Unknown keys and invalid ranks cannot become invisible, ranked gameplay modifiers. */
export function sanitizeUpgradeRanks(input) {
  const raw = input && typeof input === 'object' && !Array.isArray(input) ? input : {};
  const ranks = emptyUpgradeRanks();
  for (const id of UPGRADE_IDS) if (validRank(raw[id])) ranks[id] = raw[id];
  return ranks;
}

/** Canonical on-record snapshot: only positive known ranks, in stable catalogue order. */
export function activeUpgradeRanks(input) {
  const raw = sanitizeUpgradeRanks(input);
  return Object.fromEntries(UPGRADE_IDS.filter(id => raw[id] > 0).map(id => [id, raw[id]]));
}

/** A null price represents an unrepresentable transaction, never a free purchase. */
export function nextUpgradePrice(id, currentRank = 0) {
  const spec = byId[id];
  if (!spec || !validRank(currentRank)) return null;
  const r = currentRank;
  const price = Math.ceil(spec.basePrice + spec.priceScale * r * (1 + r / 12));
  return Number.isSafeInteger(price) && price >= 1 ? price : null;
}

export function upgradeBenefit(id, rank = 0) {
  const spec = byId[id];
  if (!spec || !validRank(rank) || !rank) return 0;
  return spec.cap * (rank / (rank + spec.curveK));
}

export function upgradeEffects(input) {
  const ranks = sanitizeUpgradeRanks(input);
  const b = (id) => upgradeBenefit(id, ranks[id]);
  return Object.freeze({
    speedMul: 1 + b('speed'),
    hopMul: 1 + b('hop'),
    flipMul: 1 + b('flip'),
    canopyFuelMul: 1 + b('canopy'),
    airbrakeLiftMul: 1 + b('airbrake'),
    divebombMul: 1 + b('divebomb'),
    bsodAccelerationMul: 1 - b('bsodGrace'),
    magnetMul: 1 + b('magnetMagnitude'),
    magnetDurationMul: 1 + b('magnetMeasure'),
    magnetSpawnMul: 1 + b('magnetMyriad'),
  });
}

/**
 * A run snapshot is taken ONCE at run start. Daylies must refuse all upgrades;
 * a purchased rank alone has no effect until UPGRADE MODE is explicitly enabled.
 */
export function upgradeLoadoutForRun(profile, { daily = false } = {}) {
  const ranks = activeUpgradeRanks(profile?.upgrades);
  const enabled = profile?.upgradesEnabled === true && daily !== true && Object.keys(ranks).length > 0;
  return { enabled, ranks: enabled ? ranks : {}, effects: upgradeEffects(enabled ? ranks : {}) };
}

/** Atomic pure transaction: return original identity on any refusal. */
export function purchaseUpgrade(profile, id) {
  if (!profile || typeof profile !== 'object' || !byId[id]) return profile;
  const ranks = sanitizeUpgradeRanks(profile.upgrades);
  const rank = ranks[id];
  if (!Number.isSafeInteger(profile.bank) || profile.bank < 0) return profile;
  if (!Number.isSafeInteger(rank + 1)) return profile;
  const price = nextUpgradePrice(id, rank);
  if (price === null || profile.bank < price) return profile;
  return { ...profile, bank: profile.bank - price, upgrades: { ...ranks, [id]: rank + 1 } };
}/**
 * OWNER: gameplay engineer. Phaser-free (keep it so: it is unit-testable).
 * Public signatures are a contract - do not change without updating src/ARCHITECTURE.md.
 *
 * Single source of the EFFECTIVE physics constants for a frame: base PHYSICS (doc 4.2) x tuck x terrain-mod zones
 * x daily rule x timed effects. Also holds the doc-units -> Matter-units conversion helpers (ARCHITECTURE.md section 7)
 * and every gameplay "feel" tunable (TUNING) so nothing else hard-codes numbers.
 *
 * MATTER 0.20 NOTE (bundled with Phaser 3.90): Body.setVelocity / getVelocity and angular velocity are NORMALISED to
 * a 1000/60 ms base step, not to the actual sub-step. So "px/s -> Matter" is `pxPerSecToStep(v, BASE_STEP_MS)`. The
 * helpers still accept a delta so they stay correct if that ever changes.
 */
import { PHYSICS, MAX_PHYSICS_STEP_MS } from '../constants.js';
import { AIR_NEAR_MISS_BELOW_PX } from './TerrainGenerator.js';
import { isWarded } from './Wards.js';
import { glideDrag } from './BiomeEffects.js';
import pmath from './pmath.js';

/** Matter's internal base delta in ms (Body._baseDelta). */
export const BASE_STEP_MS = 1000 / 60;

/**
 * Gameplay feel tunables that the design doc does not pin down. Everything is in doc units (px, s, deg).
 * Tweak here only.
 */
export const TUNING = Object.freeze({
  /**
   * Matter sliding friction of the sled. MUST stay 0: Matter 0.20's friction solver jams a body on slopes below ~15 deg
   * for ANY friction >= 0.0005 (verified). All runner drag is applied manually via groundResist / brakeResist instead.
   */
  groundFriction: 0,
  /** Matter static friction of the sled (0 for the same reason). */
  groundFrictionStatic: 0,
  /**
   * Extra manual runner resistance on the ground, 1/s (exponential speed decay). Scaled by frictionMul.
   * Was 0.04. The seam "ghost" contacts (terrainSnapNormals) used to bleed ~30 % of the cruise speed (grounded speed was a flat
   * ~480 px/s on 0-24 degree slopes); with them gone the sled ran ~31 % faster (average 465 -> 607 px/s) and every jump launched
   * ~25 % faster. 0.10 gives back some of that (average ~581 px/s, +25 % vs the old game) while keeping the jump airtimes at or above
   * the old ones (chunk-0 jump 706 ms vs 689, later jumps ~1000 ms vs 840). 0.17 = +17 % pace but a 600 ms first jump; 0.25 = +9 % pace
   * but jumps 17 % shorter than before and 6 % under 400 ms.
   */
  groundResist: 0.10,
  /**
   * Multiplier on the doc drag (PHYSICS.dragUntucked 0.015) when written to Matter frictionAir. Matter 0.20 applies
   * frictionAir per 16.7 ms base step (= 0.9/s for the literal 0.015), which capped speed at ~120-250 px/s and stalled
   * the sled in every dip (QA: hands-off run covered ~110 m in 20 s). 0.15 (= 0.14/s) keeps the doc ratios (tuck halves
   * drag, boosts divide it) and, with groundResist 0.04 and quadDrag below, gives a 350-500 px/s cruise on ordinary
   * 8-12 degree terrain and ~600+ on steep drops (was 0.3). Set to 1 for the literal doc value.
   */
  dragFeelMul: 0.15,
  /**
   * Multiplier on air tilt authority (on top of PHYSICS.airControlFactor 0.7 and the doc's 420 deg/s^2): 5 = 1470 deg/s^2 in the air.
   * Was 3.6 (1060). A flip must be HELD for ~0.65 s before the sled has turned far enough to be finished by the levelling spring
   * (airIdleLevelK), and generated jumps give ~1.0 s of air, so the slack between the earliest good release and touchdown (which is the
   * whole release window, see airIdleLevelK) was only ~250 ms; 5 buys back ~100 ms of it. With maxAngularVelDegS 900 the rotation
   * of a held flip is about the same as before: ~600 deg in 1.0 s, ~960 deg in 1.4 s (measured in the sim: 627 deg at 1054 ms, 944 at 1394 ms).
   */
  airTiltFeelMul: 5,
  /** Ground friction multiplier and extra manual decay while braking (S). */
  brakeFrictionMul: 1,
  brakeResist: 2.2,
  /** Aerial angular damping while braking (S in air), 1/s. */
  airBrakeAngularDamp: 5,
  /** Quadratic drag (1/px) giving a soft terminal velocity on very steep slopes (about +0.15/s at 500 px/s; was 0.00009). */
  quadDrag: 0.0003,
  /**
   * Runner contact normals (TerrainContact.js). Matter's SAT picks the minimum-overlap axis, which at the 16 px quad seams is
   * often a wall axis or one of the 24-gon runner's own 15 degree face axes instead of the ground's normal ("ghost" normals).
   * With this on, every runner/terrain contact uses the quad's top-face normal. This was the root cause of the post-landing
   * spin / terrain crashes after good landings (and a hidden speed-dependent drag of ~30 % on cruise speed).
   * Contacts where the runner is deeper than terrainSnapMaxDepthPx below the quad's top plane (real walls: gap edges) are left alone.
   */
  terrainSnapNormals: true,
  terrainSnapMaxDepthPx: 10,
  /**
   * Landing settle: for landSettleMs after a touchdown (contact after >= groundedGraceMs of air) the post-solve angular velocity is
   * capped at landSpinMaxDegS. A rigid sled that lands on one runner first gets +/-400..700 deg/s from the contact solver and rocks
   * onto the other runner; with 8 ms sub-steps and zero friction nothing damps that, so a good landing bounced into a flip.
   * 0 disables. Ground lean (A/D) accelerates only ~210 deg/s^2, so normal riding never reaches the cap.
   */
  landSpinMaxDegS: 200,
  landSettleMs: 150,
  /** Ground lean torque multiplier (relative to maxTiltTorque). */
  groundTiltMul: 0.5,
  /**
   * Angular velocity cap, deg/s (1100 before). Reached after ~0.6 s of held tilt. With the old weak levelling every 100 ms of late
   * release added ~100 deg of spin the player could not time; 900 keeps a double flip possible in ~1.4 s of air (see airTiltFeelMul).
   */
  maxAngularVelDegS: 900,
  /** Held airborne flips approach a stable, controllable rate instead of accelerating forever. */
  flipTargetDegS: 680,
  flipAccelDegS2: 1300,
  hopMinimumHoldMs: 150, // candidate minimum variable-hop ascent
  divebombDownPxS2: 1400, // atmospheric downward push, no horizontal penalty
  /** Push kick: surface speed set by W when stalled (px/s), and re-trigger delay. */
  pushKickPxS: 90,
  /**
   * Stall safety net (stallNudgeStep, called from Sled.applyControls): forward speed ALONG THE SLOPE below stallNudgeBelowPxS (so
   * stopped or rolling backwards) for stallNudgeAfterMs on slopes < stallNudgeMaxSlopeDeg with no brake -> auto-push forward at
   * stallNudgeAccelPxS2 (net of gravity on an up-slope) until the speed passes stallNudgeToPxS (a little above the 120 px/s "moving
   * again" mark so the sled does not hover just under it). 240 (was 160) turns a sled that rolled back at 50 px/s on a 12 deg ramp
   * round and up to 120 within ~1.5 s of letting go of the brake.
   */
  stallNudgeBelowPxS: 40,
  stallNudgeAfterMs: 600,
  stallNudgeMaxSlopeDeg: 16,
  stallNudgeToPxS: 130,
  stallNudgeAccelPxS2: 240,
  pushCooldownMs: 280,
  /** Hop: speed along the surface normal (px/s; was 300, raised so an average hop is ~0.8 s of air) and coyote/buffer windows. */
  hopPxS: 360,
  hopCoyoteMs: 90,
  hopBufferMs: 110,
  /** Ground contact hysteresis (ms) before the sled counts as airborne. */
  groundedGraceMs: 45,
  /** #247 owner retune: increased decel cannot inflate the already-approved-feel upward kick. No float. */
  airBrakeLiftBudgetFraction: 0.40, // fixed prior reference: only this much spent velocity pays for upward impulse
  airBrakeKickUpRatio: 1.5,
  airBrakeKickUpCapPxS: 420,
  /** Seconds-based helicopter spin rate of the visual (deg/s). */
  heliSpinDegS: 760,
  /** Hazard / power-up defaults. */
  scrambleGravityWobble: 0.45,
  scrambleTorqueJitterDegS2: 380,
  /** Invulnerability after Hashed Backup saves you or after a respawn (ms). */
  invulnerableMs: 900,
  /** Opening grace: non-hazard crashes before this distance (m) become recovers, at most openingGraceMax per run. */
  openingGraceM: 150,
  openingGraceMax: 3,
  /** A body falling this far below the interpolated ground line has fallen into a gap/void: crash. */
  voidDepthPx: 320,
  /** Camera. */
  cameraLerpX: 5.5,
  cameraLerpY: 3.2,
  lookAheadSec: 0.4,
  lookAheadMaxPx: 170,
  /** Speed-zoom: 1.0 below zoomSpeedLo px/s, zoomMin at zoomSpeedHi px/s and above; zoomLerp = 1/s smoothing. */
  zoomMin: 0.82,
  zoomSpeedLo: 150,
  zoomSpeedHi: 600,
  zoomLerp: 2.2,
  /** Speed streaks start at streakSpeedLo px/s and reach full strength at streakSpeedHi. */
  streakSpeedLo: 420,
  streakSpeedHi: 700,
  /** Hit-stop (ms of frozen physics) on perfect/hard landings and on a crash. */
  hitStopLandingMs: 45,
  hitStopCrashMs: 70,
  /** Trick -> speed loop. Boost = base x comboMult x (1 + trickCountBonus x (tricks-1)); perfect x perfectMul; capped. */
  boostBasePxS: 60,
  boostTrickCountBonus: 0.2,
  boostPerfectMul: 1.5,
  boostCapPxS: 260,
  boostPerfectNoTrickPxS: 30,
  /** After a boost the drag (air, ground resist, quadratic) is multiplied by boostDragMul for boostDragMs. */
  boostDragMs: 1200,
  boostDragMul: 0.3,
  /** A sloppy landing keeps this fraction of the speed. */
  sloppySpeedKeep: 0.92,
  /** Forgiveness: TrickTracker 'crash' landings up to this angle (deg) / impact (px/s) become a sloppy wobble instead. */
  forgiveAngleDeg: 78,
  forgiveImpactPxS: 1700,
  /**
   * Ground snap (crest smoothing): a sled that was grounded >= snapMinGroundMs, did not hop/launch in the last snapQuietMs,
   * left the ground < snapWindowMs ago, rises from the surface slower than snapMaxVnPxS and has ground that falls away by
   * less than snapMaxDropDeg (over the look-ahead) gets its surface-normal speed clamped to snapKeepVnPxS plus snapDownPxS/s
   * of downforce. Real kickers (drop > snapMaxDropDeg, or vn above the cap) are untouched.
   */
  /**
   * Hands-off air rotation (no tilt held), see airIdleSpin(): `airIdleLevelK` (1/s^2) springs the nose toward the landing attitude by
   * the SHORTEST way (error clamped to +-1.2 rad), `airIdleSpinDamp` (1/s) damps the spin. They were 8 and 3, which left a released flip
   * spinning at 600-1000 deg/s for ~1 s with a spring far too weak to stop it; at 80 and 12 the spin is gone within ~0.3 s and an
   * UNHURRIED release (>= ~450 ms of air left) lands level from any attitude. Holding tilt is untouched (the spring only acts with no
   * input) and still crashes. Stronger constant values (120 / 18) look like a snap and measured no better; what the window still lacked
   * was authority when little air is left, see airIdleUrgencyRefMs.
   *
   * What the window really is: a flip let go after about 0.42 s of held tilt (about a third of a turn, plus ~50 deg of coast) is carried round
   * to one full turn, and one let go before that unwinds to a plain landing; the tipping point between the two is 180 deg from level,
   * where the spring flips direction. A release up to ~0.85 s of hold (about 470 deg of rotation) still finishes ONE flip, later ones go on
   * to a second turn (a double on long air). Before the urgency scaling the sled needed ~0.45 s to come back from the tipping point, so
   * anything released with less than that left (about 100 ms either side of the tipping point, and every release 200 ms or more after
   * the earliest good one) landed on its side. With it, a release at any rotation lands on the runners if >= ~250 ms of air is left.
   */
  airIdleSpinDamp: 12,
  airIdleLevelK: 80,
  /**
   * Where the hands-off sled settles: this many degrees nose-down of the ground slope at the predicted touchdown (Sled.airSlopeDeg, from
   * RunScene.airForecast). 15 is what the old "aim at the velocity heading" rule produced on generated landings (median 16, p10-p90
   * 12-19 deg), so an unattended landing stays a "good" one (PERFECT_ANGLE_DEG 12 .. GOOD 28) and a PERFECT one still has to be earned
   * with tilt: aiming at the slope itself made ~100 % of hands-off landings perfect, +25 % speed and a failing hop policy (measured).
   */
  airIdleLandOffsetDeg: 15,
  /**
   * Levelling urgency: with `eta` ms of air left (Sled.airEtaMs) the spring is multiplied by u^2 and the spin damping by u, where
   * u = clamp(airIdleUrgencyRefMs / eta, 1, airIdleUrgencyMax) (the same damping ratio, a faster settle). 400 ms and 3 => unchanged above 400 ms
   * of air, 4x spring at 200 ms, 9x (the cap) from 133 ms. That is enough to turn a release from the tipping point with 250 ms left into a
   * landing, and still not enough (wMax limits the turn to ~45 deg per 50 ms) to rescue one let go inverted with <~100 ms left.
   */
  airIdleUrgencyRefMs: 400,
  airIdleUrgencyMax: 3,
  snapMinGroundMs: 100,
  snapQuietMs: 350,
  snapWindowMs: 160,
  snapMaxVnPxS: 130,
  snapKeepVnPxS: 0,
  snapMaxDropDeg: 11,
  snapMinSpeedPxS: 250,
  /** Near miss: crash hazard passed within this many px above / below its centre line (plus half its height). */
  nearMissAbovePx: 80,
  nearMissBelowPx: 30,
  /** Air hazards are passed underneath: an airborne sled crossing the box x within this far below its bottom pays (generator constant). */
  airNearMissBelowPx: AIR_NEAR_MISS_BELOW_PX,
  /** Air hazard warning (alert pulse, sound and the STAY LOW marker over the lip) once the box is this close ahead; the lip is ~400 px before it. */
  airWarnAheadPx: 900,
  tuckHintSlopeDeg: 12, // a steep grounded descent shows the tuck hint ...
  tuckHintMs: 800, // ... after this long on it
  tuckHintShowMs: 2500, // minimum time on screen once shown (then it hides when the steep stretch ends)
  tuckHintWaitMs: 8000, // a hint waiting for another hint to clear is dropped after this long
  tuckHintMaxShows: 2, // shown this many times (across runs) without the player tucking -> done for good
  nearMissPoints: 25,
  nearMissSlowMs: 80,
  shardRadiusPx: 18,
  shardChainMs: 1500,
  shardPointsPerChain: 5,
  shardPointsCap: 50,
  milestoneEveryM: 500,
  /**
   * B3 tuning, glide power-ups (BiomeEffects.glideDrag): at full glide strength (frictionMul at the 0.2 floor) speedMul is
   * lifted by glideSpeedLift (frictionAir / speedMul) and quadDrag cut by glideQuadCut, both scaled by the strength.
   */
  glideSpeedLift: 0.35,
  glideQuadCut: 0.35,
  /** Screen shake amplitudes (px). */
  shakeHardLanding: 3,
  shakeCrash: 7,
});

/**
 * @typedef {Object} TunerContext
 * @property {boolean} tucked
 * @property {import('../data/schemas.js').TerrainModDef[]} zones  mods the sled is currently inside.
 * @property {import('./DailyPatch.js').DailyModifiers} [daily]
 * @property {boolean} [scrambled]  garbage-data vent active (controls/gravity perturbed).
 * @property {boolean} [slowed]     overflow firewall active.
 * @property {number} [speedBoost]  packet burst multiplier (1 = none).
 * @property {number} [slowFactor]  overflow firewall speed multiplier while slowed (default PHYSICS.slowFactor).
 * @property {number} [timeMs]      run time, used for the scramble wobble.
 * @property {boolean} [parachute]  parachute stall active (gravity x0.5, steering locked).
 * @property {boolean} [airBrake]   air brake held while airborne.
 * @property {boolean} [airborne]
 * @property {boolean} [braking]    S held.
 * @property {import('./Wards.js').WardState} [wards]  B0: active wards; a zone whose mod id is warded is skipped.
 * @property {number} [glideFrictionMul]   B0 `glide` power-up: multiplier on ground friction (groundResist), 1 = none.
 * @property {number} [stabilizeBounceMul] B0 `stabilize` power-up: multiplier on bounce, 1 = none.
 */

/**
 * @typedef {Object} EffectivePhysics
 * @property {number} gravityPxS2        px/s^2 (down).
 * @property {number} frictionAir        Matter frictionAir (see ARCHITECTURE.md 7).
 * @property {number} groundFriction     Matter friction for terrain contact.
 * @property {number} tiltTorqueDegS2    deg/s^2 at full input on ground.
 * @property {number} airControl         multiplier on tilt torque while airborne.
 * @property {number} bounceMul
 * @property {number} speedMul           overall speed multiplier for boosts/slows (applied as drag scaling).
 * @property {number} [steerMul]         0 = steering locked (parachute), 1 normal, tucked daily rule may reduce.
 * @property {number} [tiltSign]         -1 when scrambled (inverted controls).
 * @property {number} [groundResist]     manual runner resistance 1/s.
 * @property {number} [quadDrag]
 * @property {number} [pushForceMul]
 * @property {number} [beltDrivePxS2]  horizontal drive from conveyor-belt zones (px/s^2), always >= 0.
 * @property {number} [beltDirection]  +1 the belt carries you forward, -1 it fights you.
 * @property {number} [scrambleJitterDegS2] random torque amplitude while scrambled.
 * @property {number} [restitution]
 * @property {number} [landingRebound] share of the touchdown speed a scored landing gets back as an upward rebound (0 =
 *   none; zone `physics.landingRebound`, larger share wins, times stabilizeBounceMul^2; BiomeEffects.springRebound).
 */

/** px/s -> Matter per-step velocity for a step of deltaMs. @param {number} pxPerS @param {number} deltaMs @returns {number} */
export function pxPerSecToStep(pxPerS, deltaMs) {
  return (pxPerS * deltaMs) / 1000;
}

/** Inverse of pxPerSecToStep. @param {number} pxPerStep @param {number} deltaMs @returns {number} px/s */
export function stepToPxPerSec(pxPerStep, deltaMs) {
  return (pxPerStep * 1000) / deltaMs;
}

/** Gravity in px/s^2 -> Phaser Matter `world.gravity.y` (scale left at the default 0.001). @param {number} g @returns {number} */
export function gravityToMatter(g) {
  return g / 1000;
}

/** deg/s^2 angular acceleration -> change in Matter angularVelocity (rad/step) for one step. @param {number} degS2 @param {number} deltaMs @returns {number} */
export function angAccelToStep(degS2, deltaMs) {
  const dt = deltaMs / 1000;
  return (degS2 * Math.PI) / 180 * dt * dt;
}

/**
 * Hands-off air rotation, one step (pure; Sled.applyControls uses it when airborne with no tilt input): a spring toward the
 * landing attitude by the SHORTEST way (error clamped to +-1.2 rad) plus exponential spin damping. See TUNING.airIdleLevelK / airIdleSpinDamp.
 * With `ctx` (what RunScene.airForecast gives Sled: ballistic ms to touchdown and ground slope there) the attitude is slope + airIdleLandOffsetDeg
 * and the spring/damping scale with urgency (TUNING.airIdleUrgencyRefMs); without it the target is the velocity heading and nothing is scaled.
 * @param {number} w angular velocity, rad/s (clockwise positive, like the body angle).
 * @param {number} angle body angle, rad (any multiple of a turn).
 * @param {number} vx velocity px/s.
 * @param {number} vy velocity px/s (down positive).
 * @param {number} dt seconds.
 * @param {typeof TUNING} [t]
 * @param {{etaMs?:number, slopeDeg?:number|null}|null} [ctx] landing forecast (etaMs Infinity / slopeDeg null = unknown).
 * @returns {number} new angular velocity, rad/s.
 */
export function airIdleSpin(w, angle, vx, vy, dt, t = TUNING, ctx = null) {
  const target = ctx && ctx.slopeDeg != null ? (ctx.slopeDeg + t.airIdleLandOffsetDeg) * Math.PI / 180 : pmath.atan2(vy, vx);
  let err = target - angle;
  err = pmath.atan2(pmath.sin(err), pmath.cos(err));
  const eta = ctx && ctx.etaMs != null ? ctx.etaMs : Infinity;
  const u = Math.min(t.airIdleUrgencyMax, Math.max(1, t.airIdleUrgencyRefMs / Math.max(eta, 1)));
  const spring = Math.max(-1.2, Math.min(1.2, err)) * t.airIdleLevelK * u * u * dt;
  return (w + spring) * pmath.exp(-t.airIdleSpinDamp * u * dt);
}

/**
 * Conveyor belt, one physics step (pure; Sled.applyControls feeds it and applies the result).
 * A belt carries the sled along the surface tangent while it is grounded, with no player input — that is
 * the whole mechanic. `drivePxS2` is always a positive magnitude and `direction` carries the sign, so a
 * caller cannot add a negative magnitude by mistake, and `direction: -1` is a belt fighting the player.
 * Returns a velocity delta in px/s to add this step; zero when airborne or when no belt is under the sled.
 * @param {{grounded:boolean, drivePxS2:number, direction:number, slopeDeg:number, stepMs:number}} i
 * @returns {{dvx:number, dvy:number}}
 */
export function conveyorStep(i) {
  if (!i || !i.grounded || !(i.drivePxS2 > 0)) return { dvx: 0, dvy: 0 };
  const rad = ((i.slopeDeg || 0) * Math.PI) / 180;
  const drive = i.drivePxS2 * (i.direction === -1 ? -1 : 1) * ((i.stepMs || 0) / 1000);
  return { dvx: pmath.cos(rad) * drive, dvy: pmath.sin(rad) * drive };
}

/**
 * Geyser vent, one physics step (W6, Vertigo Vents; pure — Sled.applyControls supplies it and applies the result).
 *
 * The spec's W6 table says "Geysers that launch you", and `geyser-vent.json` has carried
 * `launch: { velocityPxS, cooldownMs }` since the biome shipped — but nothing ever read the field, so the
 * mechanic did not exist while its data and schema looked present. This is the same failure shape as the
 * conveyor belt's unused `direction`; both are why "the data is there" is never evidence that a mechanic works.
 *
 * A vent fires only from the ground, and only when its cooldown has expired — without that, a vent under the
 * sled would kick on every physics step and hold the sled in the air forever.
 *
 * @param {{grounded:boolean, launch?:{velocityPxS?:number, cooldownMs?:number}, cooldownLeftMs?:number}} i
 * @param {number} [defaultCooldownMs] used when the vent's data omits a usable cooldown.
 * @returns {{fire:boolean, dvy:number, cooldownMs:number}} upward velocity change (px/s, negative = up).
 */
export function geyserStep(i, defaultCooldownMs = 900) {
  const inert = { fire: false, dvy: 0, cooldownMs: 0 };
  if (!i || !i.grounded) return inert;
  const l = i.launch;
  if (!l || typeof l !== 'object') return inert;
  const v = l.velocityPxS;
  if (!Number.isFinite(v) || v <= 0) return inert;
  if ((i.cooldownLeftMs || 0) > 0) return inert;
  const cd = Number.isFinite(l.cooldownMs) && l.cooldownMs > 0 ? l.cooldownMs : defaultCooldownMs;
  return { fire: true, dvy: -v, cooldownMs: cd };
}

/**
 * Stall safety net, one physics step (pure; Sled.applyControls feeds it and applies the result).
 * A sled that is stopped or rolling BACKWARDS (speed along the slope tangent below `stallNudgeBelowPxS`) on non-steep ground with no
 * brake for `stallNudgeAfterMs` gets a gentle push along the tangent up to `stallNudgeToPxS`. The test is the signed tangential speed,
 * not the speed magnitude: a sled sliding backwards down a gentle up-slope at 50 px/s has |v| > 40 but is exactly the case the net is for.
 * On an up-slope the push also cancels the gravity component along the slope, so it is a net 160 px/s^2 on any slope (on a 12 deg
 * up-slope gravity alone is ~190 px/s^2, more than the raw push). Once started it continues until the target speed is reached.
 * Never acts while braking, airborne, on steep ground, or while the sled is moving forward at or above the threshold.
 * @param {{crawlMs:number, nudging:boolean}} st state from the previous step.
 * @param {{grounded:boolean, braking:boolean, slopeDeg:number, vx:number, vy:number, stepMs:number, gravityPxS2:number}} i velocity px/s, slope deg (+ = downhill).
 * @param {typeof TUNING} [t]
 * @returns {{crawlMs:number, nudging:boolean, dvx:number, dvy:number}} velocity change (px/s) to add this step.
 */
export function stallNudgeStep(st, i, t = TUNING) {
  const rad = (i.slopeDeg * Math.PI) / 180;
  const tx = pmath.cos(rad);
  const ty = pmath.sin(rad);
  const vt = i.vx * tx + i.vy * ty; // signed speed along the slope (+ = downhill / forward)
  const eligible = i.grounded && !i.braking && Math.abs(i.slopeDeg) < t.stallNudgeMaxSlopeDeg;
  const crawl = eligible && vt < (st.nudging ? t.stallNudgeToPxS : t.stallNudgeBelowPxS);
  const crawlMs = crawl ? st.crawlMs + i.stepMs : 0;
  const nudging = crawl && crawlMs > t.stallNudgeAfterMs;
  let dv = 0;
  if (nudging) {
    const dt = i.stepMs / 1000;
    dv = Math.min(t.stallNudgeAccelPxS2 * dt, t.stallNudgeToPxS - vt);
    // cancel the pull of gravity along an up-slope (ty < 0) so the push is a net acceleration
    dv += Math.max(0, -ty) * i.gravityPxS2 * dt;
  }
  return { crawlMs, nudging, dvx: tx * dv, dvy: ty * dv };
}

export class PhysicsTuner {
  /** @param {Partial<typeof PHYSICS>} [overrides] dev-time overrides of base values. */
  constructor(overrides = {}) {
    this.base = { ...PHYSICS, ...overrides };
    this.tuning = TUNING;
  }

  /**
   * @param {TunerContext} ctx
   * @returns {EffectivePhysics}
   */
  getEffective(ctx) {
    const b = this.base;
    const t = this.tuning;
    const daily = ctx.daily || {};
    const zones = ctx.zones || [];

    let gravityMul = daily.gravityMul || 1;
    let frictionMul = daily.frictionMul || 1;
    let bounceMul = 1;
    // W6: the surface-feel multipliers a zone can carry. Kept separate from the three base ones so the
    // existing mods read exactly as before; each defaults to 1 and multiplies, so two overlapping zones
    // compound rather than one silently winning.
    let zoneSpeedMul = 1;
    let zoneSteerMul = 1;
    let zonePushMul = 1;
    // W6 conveyor: a belt drives the sled itself, so its force must not be folded into a multiplier on
    // the player's push key (which only fires on flat ground while W is held — a belt that needs you to
    // push is not a belt). The magnitude accumulates and the sign is carried separately in
    // beltDirection, so a consumer cannot add a negative magnitude by mistake.
    let beltDrive = 0;
    let beltDirection = 1;
    // W6 geysers: the vent's launch data, resolved here so the consumer does not walk the zone list again.
    // `launch` lives on the MOD DEF (geyser-vent.json), not on zone.physics, so it is read from the def.
    let geyserLaunch = null;
    // Sky Jellyfish felt bounce: the share of the touchdown speed a landing gets back (BiomeEffects.springRebound).
    // Overlapping zones take the larger share, never a compounded one (a bounce, not a launch).
    let landingRebound = 0;
    for (const z of zones) {
      // B0 ward: a warded mod is skipped entirely, as if the sled were not in that zone (Wards.js).
      if (ctx.wards && z && isWarded(ctx.wards, { modId: z.id })) continue;
      const p = (z && z.physics) || {};
      if (p.gravityMul) gravityMul *= p.gravityMul;
      if (p.frictionMul) frictionMul *= p.frictionMul;
      if (p.bounceMul) bounceMul *= p.bounceMul;
      if (p.speedMul) zoneSpeedMul *= p.speedMul;
      if (p.steerMul) zoneSteerMul *= p.steerMul;
      if (p.pushForceMul) zonePushMul *= p.pushForceMul;
      if (p.landingRebound > landingRebound) landingRebound = p.landingRebound;
      if (p.beltDrivePxS2 > 0) {
        beltDrive += p.beltDrivePxS2;
        // Last zone wins the sign. Two belts facing opposite ways is a data situation the shipped table
        // does not produce; picking the nearer (last) zone keeps the behaviour deterministic.
        beltDirection = (z && z.direction) === -1 || (z && z.physics && z.physics.direction) === -1 ? -1 : 1;
      }
      if (z && z.launch && typeof z.launch === 'object') geyserLaunch = z.launch;
    }

    // B0 glide / stabilize power-ups (values already clamped by BiomeEffects at pickup).
    const glide = glideDrag(frictionMul, ctx.glideFrictionMul, t); // B3: the pure glide math (BiomeEffects)
    frictionMul = glide.frictionMul;
    if (ctx.stabilizeBounceMul > 0) bounceMul *= ctx.stabilizeBounceMul;
    // the Rails damp the rebound as they damp restitution: by bounceMul squared (a bounce's energy)
    if (ctx.stabilizeBounceMul > 0) landingRebound *= ctx.stabilizeBounceMul * ctx.stabilizeBounceMul;

    let speedMul = (ctx.speedBoost || 1) * zoneSpeedMul * glide.speedMul * (ctx.upgradeEffects?.speedMul || 1);
    if (ctx.slowed) speedMul *= ctx.slowFactor || b.slowFactor;
    let dragMul = 1;
    let steerMul = 1;
    if (ctx.tucked) {
      gravityMul *= b.tuckGravityMul;
      dragMul *= b.tuckDragMul;
      speedMul *= daily.tuckSpeedMul || 1;
      steerMul *= daily.tuckSteerMul == null ? 1 : daily.tuckSteerMul;
    }
    const airDensity = Number.isFinite(ctx.atmosphereDensity) ? Math.max(0, Math.min(1, ctx.atmosphereDensity)) : 1;
    if (ctx.parachute && airDensity > 0) {
      gravityMul *= 1 - (1 - b.parachuteGravityMul) * airDensity;
      steerMul = 0;
    }

    let tiltSign = 1;
    let jitter = 0;
    if (ctx.scrambled) {
      tiltSign = -1;
      jitter = t.scrambleTorqueJitterDegS2;
      const tm = (ctx.timeMs || 0) / 1000;
      gravityMul *= 1 + t.scrambleGravityWobble * pmath.sin(tm * 11) * pmath.cos(tm * 4.3);
    }

    const resistBase = t.groundResist * frictionMul + (ctx.braking && !ctx.airborne ? t.brakeResist : 0);
    const frictionBrake = ctx.braking && !ctx.airborne ? t.brakeFrictionMul : 1;

    return {
      gravityPxS2: b.gravityPxS2 * gravityMul,
      // Linear drag falls as speedMul rises, so terminal speed scales ~ speedMul (packet burst +30 %, firewall -50 %).
      frictionAir: (b.dragUntucked * t.dragFeelMul * dragMul) / Math.max(0.2, speedMul),
      groundFriction: t.groundFriction * frictionMul * frictionBrake,
      tiltTorqueDegS2: b.maxTiltTorqueDegS2,
      airControl: b.airControlFactor * t.airTiltFeelMul * (daily.airControlMul || 1) * zoneSteerMul,
      bounceMul,
      speedMul,
      hopMul: ctx.upgradeEffects?.hopMul || 1,
      flipMul: ctx.upgradeEffects?.flipMul || 1,
      airbrakeLiftMul: ctx.upgradeEffects?.airbrakeLiftMul || 1,
      divebombMul: ctx.upgradeEffects?.divebombMul || 1,
      steerMul,
      tiltSign,
      groundResist: resistBase,
      quadDrag: t.quadDrag * glide.quadMul,
      pushForceMul: (daily.pushForceMul || 1) * zonePushMul,
      beltDrivePxS2: beltDrive,
      beltDirection,
      geyserLaunch,
      scrambleJitterDegS2: jitter,
      restitution: Math.min(0.9, 0.02 * bounceMul * bounceMul),
      landingRebound,
    };
  }
}

/**
 * Advance a Phaser Matter world by `deltaMs` in sub-steps no larger than MAX_PHYSICS_STEP_MS.
 * Requires `matterWorld.autoUpdate === false` (set in the Matter config). Call once per frame from RunScene.update.
 * @param {Phaser.Physics.Matter.World} matterWorld
 * @param {number} deltaMs frame delta (clamp upstream to <= 50).
 * @param {(stepMs:number)=>void} [beforeStep] hook to apply forces/torques for each sub-step.
 * @param {(stepMs:number)=>void} [afterStep] optional hook after each sub-step (collision events have fired).
 * @returns {number} number of sub-steps run.
 */
export function stepWorld(matterWorld, deltaMs, beforeStep, afterStep) {
  if (!(deltaMs > 0)) return 0;
  const n = Math.max(1, Math.ceil(deltaMs / MAX_PHYSICS_STEP_MS));
  const step = deltaMs / n;
  for (let i = 0; i < n; i++) {
    if (beforeStep) beforeStep(step);
    matterWorld.step(step);
    if (afterStep) afterStep(step);
  }
  return n;
}{
