      g.fillRect(tw + TAB_SLANT + 6 + i * 4, 6, 2, 3);
    }
  }

  /**
   * Corner brackets, `out` px outside the frame (0 or 1: the breathing), with a bright pixel at each corner.
   * @param {number} out
   */
  _paintBrackets(out) {
