});
for (const [ch, rows] of Object.entries(EXTRA_GLYPHS)) {
  const cols = [0, 0, 0, 0, 0];
  rows.forEach((row, r) => {
    for (let c = 0; c < 5; c++) if (row[c] === '1') cols[c] |= 1 << r;
  });
  GLYPHS.set(ch, cols);
}

/** @param {string} ch @returns {{cols:number[], first:number, width:number}} trimmed glyph metrics. */
function metrics(ch) {
  const cols = GLYPHS.get(ch) || GLYPHS.get('?');
  let first = 0;
  let last = 4;
  while (first < 5 && cols[first] === 0) first++;
  while (last >= 0 && cols[last] === 0) last--;
  if (first > last) return { cols, first: 0, width: 0 };
  return { cols, first, width: last - first + 1 };
}

/**
 * Width in font pixels of a single line of text (multiply by the integer scale).
 * @param {string} str
 * @returns {number}
 */
export function measureText(str) {
  let w = 0;
  for (const ch of String(str)) {
    const m = metrics(ch);
    w += (m.width === 0 ? 2 : m.width) + 1;
  }
  return Math.max(0, w - 1);
}

/**
 * Shorten `str` with '..' so it fits `maxPx` (unscaled font px).
 * @param {string} str @param {number} maxPx @returns {string}
 */
export function ellipsize(str, maxPx) {
  str = String(str);
  if (measureText(str) <= maxPx) return str;
  while (str.length > 1 && measureText(str + '..') > maxPx) str = str.slice(0, -1);
  return str + '..';
}

/**
 * Greedy word wrap.
 * @param {string} str @param {number} maxPx unscaled font px @param {number} [maxLines=3]
 * @returns {string} lines joined by newline (last line ellipsized if text did not fit)
 */
export function wrapText(str, maxPx, maxLines = 3) {
  const words = String(str).split(' ');
  const lines = [];
  let cur = '';
  for (const w of words) {
    const next = cur ? `${cur} ${w}` : w;
    if (measureText(next) <= maxPx || !cur) cur = next;
    else {
      lines.push(cur);
      cur = w;
    }
  }
  if (cur) lines.push(cur);
  if (lines.length > maxLines) {
    lines.length = maxLines;
    lines[maxLines - 1] = ellipsize(`${lines[maxLines - 1]} ..`, maxPx);
  }
  return lines.join('\n');
}

/** @returns {string} the characters this font can draw (for upper-casing / filtering). */
export function hasGlyph(ch) {
  return GLYPHS.has(ch);
}

function buildTexture(scene, key, cellW, cellH, pad, dilate) {
  const chars = [...GLYPHS.keys()];
  const perRow = 16;
  const rows = Math.ceil(chars.length / perRow);
  const tex = scene.textures.createCanvas(key, perRow * cellW, rows * cellH);
  const ctx = tex.context;
  ctx.fillStyle = '#ffffff';
  const data = { retroFont: true, font: key, size: 8, lineHeight: FONT_LINE_H, chars: {} };
  const W = perRow * cellW;
  const H = rows * cellH;
  chars.forEach((ch, i) => {
    const cx = (i % perRow) * cellW;
    const cy = Math.floor(i / perRow) * cellH;
    const m = metrics(ch);
    for (let c = 0; c < 5; c++) {
      for (let r = 0; r < 8; r++) {
        if (!(m.cols[c] & (1 << r))) continue;
        const px = cx + pad + (c - m.first);
        const py = cy + pad + r;
        if (dilate) ctx.fillRect(px - 1, py - 1, 3, 3);
        else ctx.fillRect(px, py, 1, 1);
      }
    }
    const gw = m.width;
    const fw = gw + pad * 2 || 1;
    const fh = 8 + pad * 2;
    data.chars[ch.charCodeAt(0)] = {
      x: cx, y: cy, width: fw, height: fh,
      centerX: fw >> 1, centerY: fh >> 1,
      xOffset: -pad, yOffset: -pad,
      xAdvance: (gw === 0 ? 2 : gw) + 1,
      data: {}, kerning: {},
      u0: cx / W, v0: cy / H, u1: (cx + fw) / W, v1: (cy + fh) / H,
    };
  });
  tex.refresh();
  tex.setFilter(1); // NEAREST
  scene.cache.bitmapFont.add(key, { data, texture: key, frame: null });
}

/**
 * Generate the bitmap fonts once per game (idempotent). Call from PreloadScene.
 * @param {Phaser.Scene} scene
 * @returns {void}
 */
export function installFonts(scene) {
  if (scene.textures.exists(FONT_KEY)) return;
  buildTexture(scene, FONT_KEY, 7, 9, 0, false);
  buildTexture(scene, FONT_OUTLINE_KEY, 9, 11, 1, true);
}/**
 * OWNER: UI engineer.
 * Phaser-free layout for the profile UI: the TitleScene level badge and the whole contents of the
 * PROFILE view. `Views.js` and `TitleScene.js` only draw what this returns, so positions, text,
 * palette keys and alphas can be unit-tested (overlap + contrast) in Jest without booting Phaser.
 *
 * Every box is in panel-local / screen-local game pixels (480x270 virtual canvas, 5x7 font: 7 cap
 * rows + 1 descender row). `x`/`y` are the TOP-LEFT corner, `w`/`h` the measured extent, so a
 * renderer can draw with `anchor: 'left'` at (x, y) and a test can intersect the boxes directly.
 */
import { measureText } from './PixelFont.js';
import { loadLevelTable, levelForXp, BASE_BIOME_ID } from '../systems/Progression.js';
import { fmtInt, fmtSec, fmtClock, idToLabel } from './Format.js';
import { equippedTitle } from '../systems/Cosmetics.js';
import { sanitizeBiomeProgress, BIOME_IDS } from '../systems/BiomeDiscovery.js';
import { TITLE_CARD } from './MissionsLayout.js';

/**
 * Decision 3: the tag an UNLOCKED biome's toggle row carries. It replaces the unlock level on that row (the
 * level is already reached, so it told the player nothing). NEW = unlocked, never entered; SEEN = a run
 * entered one of its sectors; DONE = a run rode one of its sectors to the end. Locked biomes keep "LVL n".
 */
export const BIOME_STATE_TAGS = Object.freeze({ unlocked: 'NEW', encountered: 'SEEN', completed: 'DONE' });
const STATE_COLORS = Object.freeze({ unlocked: 'text', encountered: 'cyan', completed: 'lime' });

/**
 * Label and colour of one unlocked biome's toggle row. The widest (SKY JELLYFISH MOUNTAIN SEEN/DONE) is
 * 148 px, inside the ~150 px a two-column toggle band leaves before the ON/OFF value (unit-tested).
 * @param {{name:string, state:string}} row a ProfileStore.biomeToggleRows row
 * @returns {{text:string, color:string}}
 */
export function toggleLabel(row) {
  const r = row && typeof row === 'object' ? row : {};
  const state = BIOME_STATE_TAGS[r.state] ? r.state : 'unlocked';
  return { text: `${String(r.name || r.id || '').toUpperCase()} ${BIOME_STATE_TAGS[state]}`, color: STATE_COLORS[state] };
}

/**
 * PROFILE view panel size. Taller than the leaderboard because it carries 10 stats and 11 signatures.
 *
 * 240, not 224: with all five W3 signatures unlocked the toggle menu runs to local y 205, and the BACK
 * button sits at `h - 22`. At h=224 that is y 202, so the fifth ON/OFF row drew underneath the button.
 * 240 puts the button at 218 and leaves the menu clear by 13px. It still fits the 270px canvas at y=22
 * (bottom 262). The panel's own `items` were always well clear; it was the toggle band, which is
 * returned separately and so is not covered by `overlappingPairs(items)`, that overflowed.
 */
export const PROFILE_PANEL = Object.freeze({ w: 416, h: 240 });

/**
 * Screen position of the Title level badge: the top of the right-hand cabinet card (MissionsLayout.TITLE_CARD),
 * its player section, above BEST and the Daily Patch. Overlap with the logo and the card's other lines is
 * asserted in tests/src/profilelayout.test.js and tests/src/missionslayout.test.js.
 */
export const TITLE_BADGE = Object.freeze({
  x: TITLE_CARD.x + TITLE_CARD.pad,
  y: TITLE_CARD.y + TITLE_CARD.sections.level,
  lineH: TITLE_CARD.sections.title - TITLE_CARD.sections.level,
  /** The badge text column's width: the card's inner width. */
  w: TITLE_CARD.w - TITLE_CARD.pad * 2,
});

const GLYPH_H = 8; // 7 cap rows + the descender row: a conservative box for overlap tests
const PAD = 12;
const RIGHT = PROFILE_PANEL.w - PAD;

/** @returns {string} 'H:MM:SS' over an hour, else 'M:SS'. Lifetime totals get large, so plain m:ss is not enough. */
export function fmtPlaytime(ms) {
  const total = Math.max(0, Math.floor((Number(ms) || 0) / 1000));
  if (total < 3600) return fmtClock(total * 1000);
  const h = Math.floor(total / 3600);
  const m = Math.floor((total % 3600) / 60);
  return `${h}:${String(m).padStart(2, '0')}:${String(total % 60).padStart(2, '0')}`;
}

/** 'garbage-dump-glacier' -> 'GARBAGE DUMP GLACIER'. Biome ids are kebab-case, ids elsewhere are camelCase. */
function label(id) {
  return idToLabel(String(id || '').replace(/[-_]+/g, ' '));
}

/**
 * Build one text box. Right-aligned text still records its true left edge so overlap tests are exact.
 * @param {string} key
 * @param {string} text
 * @param {number} x left edge (left/center) or right edge (right-aligned)
 * @param {number} y top edge
 * @param {string} color palette key
 * @param {{align?:'left'|'right', alpha?:number, outline?:'dark'|'glow'|'none'}} [o]
 */
function box(key, text, x, y, color, o = {}) {
  const t = String(text === undefined || text === null ? '' : text);
  const align = o.align || 'left';
  const w = measureText(t);
  return {
    key,
    text: t,
    x: align === 'right' ? x - w : x,
    y,
    w,
    h: GLYPH_H,
    align,
    color,
    alpha: o.alpha === undefined ? 1 : o.alpha,
    outline: o.outline || 'none',
  };
}

/**
 * Lifetime stat rows, in reading order. Device-best values come straight from the profile the
 * progression service publishes — this file never re-derives a best from the stored run list.
 * @param {Object} life profile.lifetime
 * @returns {[string,string][]}
 */
export function statRows(life) {
  const l = life && typeof life === 'object' ? life : {};
  const tricks = l.tricks && typeof l.tricks === 'object' ? l.tricks : {};
  const trickTotal = Object.values(tricks).reduce((a, b) => a + (Number(b) || 0), 0);
  return [
    ['RUNS', fmtInt(l.runs)],
    ['TOTAL DISTANCE', `${fmtInt(l.distanceM)} M`],
    ['PLAY TIME', fmtPlaytime(l.playMs)],
    ['BEST SCORE', fmtInt(l.bestScore)],
    ['BEST DISTANCE', `${fmtInt(l.bestDistanceM)} M`],
    ['BEST COMBO', `x${(Number(l.bestCombo) || 0).toFixed(2)}`],
    ['BEST AIR', `${fmtSec(l.maxAirtimeMs)} S`],
    // RUN SHARDS, not DATA SHARDS: lifetime.shards counts shards earned by runs only (mission shards and
    // spending never touch it), so it is neither the spendable balance nor all shards ever earned. The
    // spendable figure is the bank, drawn on the LIFETIME header row.
    ['RUN SHARDS', fmtInt(l.shards)],
    ['NEAR MISSES', fmtInt(l.nearMisses)],
    ['TRICKS', fmtInt(trickTotal)],
  ];
}

/**
 * Layout of the PROFILE view. Defensive: a missing/partial profile renders as a level 1 pilot with
 * zeroes rather than throwing, because a view can be opened before the first run ever credits.
 * @param {{profile?:Object, levels?:*}} o `levels` is the parsed levels.json (content.progression)
 * @returns {{w:number,h:number,items:Object[],bar:{x:number,y:number,w:number,h:number,ratio:number,color:string}}}
 */
export function profileLayout(o = {}) {
  const table = loadLevelTable(o.levels);
  const p = o.profile && typeof o.profile === 'object' ? o.profile : {};
  const life = p.lifetime && typeof p.lifetime === 'object' ? p.lifetime : {};
  const xp = Number(p.xp) || 0;
  // Derive the level from XP (the same rule ProfileStore applies on every load), so a stale or
  // hand-edited `level` field can never make the badge disagree with the XP figure beside it.
  const level = levelForXp(xp, table);
  const entry = table.levels.find((e) => e.level === level) || { xpMin: 0, title: '' };
  const next = table.levels.find((e) => e.level === level + 1) || null;
  const span = next ? next.xpMin - entry.xpMin : 0;
  const ratio = next && span > 0 ? Math.min(1, Math.max(0, (xp - entry.xpMin) / span)) : 1;

  const items = [];
  // Sync Level row: level + the title earned at that level.
  items.push(box('level', `SYNC LEVEL ${level}`, PAD, 24, 'lime'));
  // SHOP-2: an equipped title replaces the level title; DEFAULT shows the level title.
  items.push(box('title', equippedTitle(p) || String(entry.title || '').toUpperCase(), RIGHT, 24, 'text', { align: 'right', alpha: 0.85 }));
  // XP row: figure, Resonance bar, and what is left to the next level.
  items.push(box('xp', `XP ${fmtInt(xp)}`, PAD, 36, 'amber'));
  const bar = { x: 96, y: 36, w: 190, h: 7, ratio, color: ratio >= 1 ? 'amber' : 'lime' };
  if (next) items.push(box('tonext', `${fmtInt(Math.max(0, next.xpMin - xp))} TO L${level + 1}`, RIGHT, 36, 'text', { align: 'right', alpha: 0.85 }));
  else items.push(box('tonext', 'MAX SYNC', RIGHT, 36, 'amber', { align: 'right' }));

  // Lifetime block: two columns of five, so ten numbers fit without shrinking the font.
  items.push(box('lifetime-head', 'LIFETIME', PAD, 54, 'amber'));
  // The spendable balance is the shard figure a player acts on, so it is the primary one on this screen.
  items.push(box('bank', `BANK ${fmtInt(Math.max(0, Number(p.bank) || 0))}`, RIGHT, 54, 'amber', { align: 'right' }));
  const rows = statRows(life);
  rows.forEach(([k, v], i) => {
    const col = i < 5 ? 0 : 1;
    const labelX = col === 0 ? PAD : 208;
    const valueRight = col === 0 ? 186 : RIGHT;
    const y = 66 + (i % 5) * 12;
    items.push(box(`stat-k${i}`, k, labelX, y, 'text', { alpha: 0.7 }));
    items.push(box(`stat-v${i}`, v, valueRight, y, 'cyan', { align: 'right' }));
  });

  // Biomes: W3 ships the first five signatures, so the W1 "SIGNATURE LOCKED - COMING ONLINE" note is
  // no longer true for them. It now states how many reached biomes have a playable signature vs how
  // many are still pending W6, which stays honest as W6 adds the rest.
  // Hyphen, not an em dash: the 5x7 font has no U+2014 and would draw '?'. 
  const order = Array.isArray(table.biomeOrder) ? table.biomeOrder : [];
  // The base biome is unlocked from the first run (issue #65), whatever the profile's list says.
  const reached = new Set([BASE_BIOME_ID, ...(Array.isArray(p.pendingBiomes) ? p.pendingBiomes : [])]);
  const reachedCount = order.filter((id) => reached.has(id)).length;
  const sigIds = new Set(Array.isArray(o.playableBiomeIds) ? o.playableBiomeIds : []);
  const sigCount = order.filter((id) => reached.has(id) && sigIds.has(id)).length;
  // The base biome is online but has no ON/OFF toggle (it cannot be turned off), so it is a plain name row.
  const isToggle = (id) => id !== BASE_BIOME_ID && reached.has(id) && sigIds.has(id);
  const toggleCount = order.filter(isToggle).length;
  // SIGNATURES UNLOCKED, not BIOMES REACHED: the count is biomes unlocked by Sync Level (pendingBiomes),
  // which a player has with zero runs played, so "reached" claimed something that never happened.
  items.push(box('sig-head', `SIGNATURES UNLOCKED ${reachedCount}/${order.length}`, PAD, 132, 'magenta'));
  const note = sigIds.size === 0
    ? 'SIGNATURE LOCKED - COMING ONLINE'
    : `${sigCount} SIGNATURE${sigCount === 1 ? '' : 'S'} ONLINE`;
  items.push(box('sig-note', note, RIGHT, 132, 'text', { align: 'right', alpha: 0.7 }));
  // Signature names sit ABOVE the toggle menu, not behind it. Luna's round-2 finding: the menu was
  // drawn at y=150 in Views.js while the names ran from y=146, so the ON/OFF rows covered the names.
  // The geometry lives here now so overlap stays unit-tested instead of depending on two files agreeing.
  // Name pitch is 10, not 11: the shipped table has ELEVEN biomes (4 rows) and the toggle menu has to
  // fit under them inside a 224px panel. At pitch 11 with an 11px menu the deepest row ran to y=242.
    // NAME_TOP must clear the header row (y=132 + GLYPH_H 8) — starting at 138 overlapped it. Pitch 9 is
  // the tightest that satisfies the GLYPH_H+1 rule in MissionsLayout, and it is what lets four name rows
  // plus five toggle rows fit in a 224px panel.
  const NAME_TOP = 141;
  const NAME_PITCH = 9;
  // Every signature WITHOUT a toggle row gets a plain name row: a toggle exists only for a biome that is
  // both unlocked and playable. An unlocked biome already appears in the toggle menu below, labelled with
  // its unlock level, so listing it twice was pure duplication. This used to list only the not-playable
  // ones, and production passes every shipped id as playable, so LOCKED biomes vanished from the screen
  // (audit F11): a new player could not see what was coming.
  // Two columns (x 12 and 208, the LIFETIME columns), not three: a locked name carries a "LVL n" tag, and
  // "SKY JELLYFISH MOUNTAIN LVL 25" does not fit a 134px third of the panel.
  const NAME_COLS = 2;
  const NAME_COL_X = [PAD, 208];
  const levelOf = (id) => {
    const e = table.levels.find((l) => l.biome === id);
    return e ? e.level : null;
  };
  const prog = sanitizeBiomeProgress(p.biomeProgress);
  const namedOnly = order.filter((id) => !isToggle(id));
  namedOnly.forEach((id, i) => {
    const x = NAME_COL_X[i % NAME_COLS];
    const y = NAME_TOP + Math.floor(i / NAME_COLS) * NAME_PITCH;
    const has = reached.has(id);
    // 0.55 alpha keeps even the unreached names above the 4.5:1 contrast floor in both palettes.
    const name = box(`sig-${id}`, label(id), x, y, has ? 'amber' : 'text', { alpha: has ? 1 : 0.55 });
    items.push(name);
    // A locked signature says when it unlocks, in the shop's own "LVL n" wording.
    const lv = levelOf(id);
    let right = name;
    if (!has && lv) {
      right = box(`lock-${id}`, `LVL ${lv}`, name.x + name.w + 6, y, 'text', { alpha: 0.55 });
      items.push(right);
    }
    // Decision 3: a biome can be entered before it is unlocked (a Daily plays the date's mask), so a plain
    // name row also says SEEN / DONE when that happened. Its own box: the name and LVL texts stay exact.
    const st = prog.completed.includes(id) ? 'completed' : prog.encountered.includes(id) ? 'encountered' : null;
    if (st) items.push(box(`state-${id}`, BIOME_STATE_TAGS[st], right.x + right.w + 6, y, STATE_COLORS[st]));
  });

  // The toggle menu's band: below the last name row, sized so the deepest row still clears the panel
  // floor. Five signatures is the worst case; a sixth would push past h, which is why the height is
  // computed from `order` rather than hardcoded.
  const nameRows = Math.max(1, Math.ceil(namedOnly.length / NAME_COLS));
  const lastNameBottom = namedOnly.length
    ? NAME_TOP + (nameRows - 1) * NAME_PITCH + GLYPH_H
    : NAME_TOP - NAME_PITCH + GLYPH_H; // no plain rows: sit directly under the header
  // W6: eleven signatures cannot stack in one column. At 9px pitch, 11 rows from y 142 reach 241 while
  // BACK starts at 218, so the last three would be covered by a button the player cannot see through —
  // the exact defect W3's audit already caught once. Split into two columns instead of shrinking the pitch:
  // 6 rows per column at 9px is 54px, clearing BACK by 22px, and the font stays legible.
  // Balanced columns (ceil(n/2) rows each, at most 6) rather than always filling 6 before wrapping: now that
  // locked names are listed above the menu, 6-7 unlocked signatures under two name rows would otherwise
  // reach the ACHIEVEMENTS line at y 206. Balanced, names plus toggles never exceed six rows in total.
  const TOGGLE_MAX_ROWS = 6;
  const TOGGLE_COLS = order.length > TOGGLE_MAX_ROWS ? 2 : 1;
  const TOGGLE_ROWS_PER_COL = Math.max(1, Math.min(TOGGLE_MAX_ROWS, Math.ceil(toggleCount / TOGGLE_COLS)));
  const toggleMenu = {
    x: PAD + 2,
    y: lastNameBottom + 2,
    w: PROFILE_PANEL.w - (PAD * 2) - 4,
    // 9 not 11: the rows must clear the panel floor beneath the signature names. GLYPH_H is 8, so
    // 9 still leaves a clear row gap.
    rowH: 9,
    columns: TOGGLE_COLS,
    rowsPerColumn: TOGGLE_ROWS_PER_COL,
  };

  // Two buttons want the strip beside BACK, and both belong on this screen:
  //   * W5's ACHIEVEMENTS entry — the spec puts the grid in Profile, and Title has no seventh row;
  //   * W4's SHARD SHOP — Title's band fits six 2x rows (y92..196, daily strip at 202) and the shop was
  //     the seventh, the overflow CC Friday caught with SETTINGS.
  // BACK is right-aligned at x w-76, so both fit left of it: 96 + 8 + 96 = 200px, well inside 416.
  const achUnlocked = Object.keys(p.achievements && typeof p.achievements === 'object' ? p.achievements : {}).length;
  const achTotal = Number(o.achievementTotal) > 0 ? Number(o.achievementTotal) : 0;
  items.push(box('ach-summary',
    achTotal ? `ACHIEVEMENTS ${achUnlocked}/${achTotal}` : `ACHIEVEMENTS ${achUnlocked}`,
    PAD, PROFILE_PANEL.h - 34, 'amber', { alpha: 0.9 }));
  // Decision 3: how many biomes this pilot has actually entered and ridden through, on the same line as the
  // achievements count (right-aligned; the toggle band always ends above this line).
  const biomeTotal = order.length || BIOME_IDS.length;
  items.push(box('biome-progress', `BIOMES SEEN ${prog.encountered.length}/${biomeTotal} DONE ${prog.completed.length}/${biomeTotal}`,
    RIGHT, PROFILE_PANEL.h - 34, 'cyan', { align: 'right', alpha: 0.9 }));
  const BTN_Y = PROFILE_PANEL.h - 22;
  const achButton = { x: PAD, y: BTN_Y, w: 96, h: 16 };
  const shopButton = { x: PAD + 96 + 8, y: BTN_Y, w: 96, h: 16 };
  // SHOP-2: TITLES opens the title picker. Third in the strip (x 220..316), still clear of BACK at x 340.
  const titlesButton = { x: PAD + (96 + 8) * 2, y: BTN_Y, w: 96, h: 16 };

  // Physical rows the menu occupies: with two columns that is the taller column, not the row count, which
  // is what the overlap test has to measure.
  const togglePhysicalRows = toggleCount ? TOGGLE_ROWS_PER_COL : 0;
  return {
    w: PROFILE_PANEL.w, h: PROFILE_PANEL.h, items, bar, toggleMenu,
    toggleRowCount: toggleCount, togglePhysicalRows, achButton, achUnlocked, achTotal, shopButton, titlesButton,
  };
}

/**
 * Title-screen level badge. Two short lines in the top-left corner, left of the logo: the subtitle
 * sits at y 76-83 and the menu panel starts at y 92, so a centred badge there would collide with both.
 * `outline: 'dark'` because the badge sits on the animated backdrop, not on a flat panel.
 * @param {{profile?:Object, levels?:*}} o
 * @returns {{level:number, items:Object[]}|null} null = nothing to draw (no profile yet)
 */
export function titleBadgeLayout(o = {}) {
  const p = o.profile;
  if (!p || typeof p !== 'object') return null;
  const table = loadLevelTable(o.levels);
  const level = levelForXp(Number(p.xp) || 0, table);
  const entry = table.levels.find((e) => e.level === level) || { title: '' };
  const items = [
    box('badge-level', `SYNC LEVEL ${level}`, TITLE_BADGE.x, TITLE_BADGE.y, 'lime', { outline: 'dark' }),
    // SHOP-2: the equipped title, else the level title.
    box('badge-title', equippedTitle(p) || String(entry.title || '').toUpperCase(), TITLE_BADGE.x, TITLE_BADGE.y + TITLE_BADGE.lineH, 'text', { outline: 'dark', alpha: 0.85 }),
  ];
  return { level, items };
}

/** @param {Object[]} items @returns {Object[]} every overlapping pair, for tests and HUD probes. */
export function overlappingPairs(items) {
  const hits = [];
  for (let i = 0; i < items.length; i++) {
    for (let j = i + 1; j < items.length; j++) {
      const p = items[i];
      const q = items[j];
      const ix = Math.min(p.x + p.w, q.x + q.w) - Math.max(p.x, q.x);
      const iy = Math.min(p.y + p.h, q.y + q.h) - Math.max(p.y, q.y);
      if (ix > 1 && iy > 1) hits.push([p.key, q.key]);
    }
  }
  return hits;
}/** Read-only rider-relative terrain minimap. No gameplay state or collisions. */
import { GAME_WIDTH, GAME_HEIGHT, SCENES } from '../constants.js';
import { rectsHit } from './HudLayout.js';

export const MINIMAP_BOUNDS=Object.freeze({w:104,h:49,left:8,top:80,bottom:178,right:GAME_WIDTH-112});
/** Dwell before a voluntary corner change; a slot that hits the rider moves at once. */
export const MINIMAP_SWITCH_DWELL_MS=600;
/** Alpha while a centre banner / strip paints over the map. */
export const MINIMAP_OCCLUDED_ALPHA=0.28;

export function minimapCorner(riderScreenX,riderScreenY){
  // Owner rule: never obscure the rider when they drift into the bottom-left quadrant.
  return Number.isFinite(riderScreenX)&&Number.isFinite(riderScreenY)&&
    riderScreenX<GAME_WIDTH*0.37&&riderScreenY>GAME_HEIGHT*0.56
    ? 'top-right':'bottom-left';
}
export function minimapPlacement(corner){
  return corner==='top-right'
    ? {x:MINIMAP_BOUNDS.right,y:MINIMAP_BOUNDS.top,w:MINIMAP_BOUNDS.w,h:MINIMAP_BOUNDS.h}
    : {x:MINIMAP_BOUNDS.left,y:MINIMAP_BOUNDS.bottom,w:MINIMAP_BOUNDS.w,h:MINIMAP_BOUNDS.h};
}
/** Screen box the rider occupies (game px), padded so the map never crowds them. */
export function minimapRiderRect(riderScreenX,riderScreenY){
  if(!Number.isFinite(riderScreenX)||!Number.isFinite(riderScreenY))return null;
  return {x:riderScreenX-16,y:riderScreenY-24,w:32,h:34};
}
/**
 * Candidate slots in preference order. Bottom-left first (owner rule), then the
 * same column lifted clear of the touch buttons, then top-right. When the rider
 * is in the bottom-left quadrant the owner rule puts top-right first.
 */
export function minimapCandidates(riderScreenX,riderScreenY,keepOuts=[]){
  const {w,h,left}=MINIMAP_BOUNDS;
  const bl=minimapPlacement('bottom-left'),tr=minimapPlacement('top-right');
  const out=[{corner:'bottom-left',...bl}];
  // Lift above whatever bottom-left keep-out (the left touch cluster, the
  // power-up row) it would touch, but never into the top HUD rows.
  let top=bl.y;
  for(const k of keepOuts)if(rectsHit({x:left,y:bl.y,w,h},k,2))top=Math.min(top,k.y-h-4);
  if(top<bl.y&&top>=MINIMAP_BOUNDS.top+h/2)out.push({corner:'left-raised',x:left,y:Math.round(top),w,h});
  out.push({corner:'top-right',...tr});
  if(minimapCorner(riderScreenX,riderScreenY)==='top-right')out.sort((a,b)=>(b.corner==='top-right')-(a.corner==='top-right'));
  return out;
}
/**
 * Pick the first candidate clear of the rider and every keep-out. If none is
 * fully clear, the rider still wins: the least-covered slot that misses the rider.
 */
export function chooseMinimapSlot(riderScreenX,riderScreenY,keepOuts=[]){
  const rider=minimapRiderRect(riderScreenX,riderScreenY);
  const cands=minimapCandidates(riderScreenX,riderScreenY,keepOuts);
  let best=null,bestHits=Infinity;
  for(const c of cands){
    if(rider&&rectsHit(c,rider,2))continue;
    const hits=keepOuts.filter(k=>rectsHit(c,k,2)).length;
    if(hits===0)return c;
    if(hits<bestHits){best=c;bestHits=hits;}
  }
  return best||cands[0];
}
/** Sample the SAME deterministic terrain as the physical sled, over a small
 * local span. Never display speculative POIs, discovered hazards, or fake map
 * coordinates. Geometry is scaled into a flat 0..1 preview rectangle.
 */
export function minimapTerrainProfile(heightAt,playerX,{behind=150,ahead=550,steps=26}={}){
  if(typeof heightAt!=='function'||!Number.isFinite(playerX))return null;
  const lo=Math.max(0,playerX-behind),hi=Math.max(lo+1,playerX+ahead);
  const points=[];let min=Infinity,max=-Infinity;
  for(let i=0;i<=steps;i++){
    const x=lo+(hi-lo)*i/steps;
    let y=NaN;
    try{y=heightAt(x)}catch{return null;}
    if(!Number.isFinite(y))return null;
    min=Math.min(min,y);max=Math.max(max,y);
    points.push({u:i/steps,y});
  }
  const height=Math.max(44,max-min);
  for(const p of points)p.v=0.18+0.64*(p.y-min)/height;
  return {points,riderU:Math.max(0,Math.min(1,(playerX-lo)/(hi-lo))),minY:min,maxY:max};
}
/** World px of terrain to show ahead: always more than the screen already shows at this zoom. */
export function minimapAheadPx(riderScreenX,zoom){
  const z=Number.isFinite(zoom)&&zoom>0?zoom:1;
  const visible=(GAME_WIDTH-(Number.isFinite(riderScreenX)?riderScreenX:GAME_WIDTH*0.38))/z;
  return Math.round(Math.max(550,Math.min(1400,visible*1.6)));
}

export class RunMinimap {
  constructor(scene){
    this.scene=scene;
    this.g=scene.add.graphics();
    scene.hud.add(this.g);
    this.elapsed=Infinity;
    this.lastCorner=null;
    this.rect=null;
    this._pending=null;
    this._pendingMs=0;
  }
  /** Settle on a slot: move at once off the rider, otherwise only after the new choice holds for the dwell. */
  _settle(choice,rider,dtMs){
    const cur=this.rect;
    if(!cur||(rider&&rectsHit(cur,rider,2))){this._pending=null;return choice;}
    if(choice.corner===this.lastCorner&&choice.y===cur.y){this._pending=null;return choice;}
    if(this._pending?.corner!==choice.corner){this._pending=choice;this._pendingMs=0;return cur;}
    this._pendingMs+=dtMs;
    if(this._pendingMs<MINIMAP_SWITCH_DWELL_MS)return cur;
    this._pending=null;
    return choice;
  }
  /**
   * @param {number} dt
   * @param {{keepOuts?:object[],occluders?:object[]}} [hud] keep-outs (touch buttons,
   *   fixed HUD rows, bottom row) the map must not sit on; occluders (centre banners,
   *   the full-width strip) it dims under instead of pushing them into the playfield.
   */
  update(dt,{keepOuts=[],occluders=[]}={}){
    this.elapsed+=Number.isFinite(dt)?Math.max(0,dt):16.7;
    if(this.rect)this.g.setAlpha(occluders.some(o=>rectsHit(this.rect,o))?MINIMAP_OCCLUDED_ALPHA:1);
    if(this.elapsed<110)return;
    const stepMs=Number.isFinite(this.elapsed)?this.elapsed:110;
    this.elapsed=0;
    let run;
    try{run=this.scene.scene.get(SCENES.RUN);}catch{}
    const sled=run?.sled,terrain=run?.terrain,cam=run?.cameras?.main;
    if(!sled||!terrain||!cam||run.crashed){this.g.clear();this.rect=null;return;}
    const sx=(sled.x-cam.scrollX-GAME_WIDTH/2)*cam.zoom+GAME_WIDTH/2;
    const sy=(sled.y-cam.scrollY-GAME_HEIGHT/2)*cam.zoom+GAME_HEIGHT/2;
    const rect=this._settle(chooseMinimapSlot(sx,sy,keepOuts),minimapRiderRect(sx,sy),stepMs);
    this.lastCorner=rect.corner;
    this.rect=rect;
    // Only sample actual terrain: the current game's deterministic world.
    const profile=minimapTerrainProfile(x=>terrain.heightAt(x),sled.x,
      {ahead:minimapAheadPx(sx,cam.zoom),steps:32});
    const g=this.g;g.clear();if(!profile)return;
    const {x,y,w,h}=rect,pad=6;
    g.fillStyle(0x060f1e,.76).fillRoundedRect(x,y,w,h,3);
    g.lineStyle(1,0x2ccde5,.74).strokeRoundedRect(x+.5,y+.5,w-1,h-1,3);
    const chartX=x+pad,chartY=y+7,chartW=w-pad*2,chartH=h-15;
    g.lineStyle(1,0x81bfff,.84);
    let prev=null;
    for(const p of profile.points){
      const next={x:chartX+p.u*chartW,y:chartY+p.v*chartH};
      if(prev)g.lineBetween(prev.x,prev.y,next.x,next.y);
      prev=next;
    }
    const rp=profile.points[Math.max(0,Math.min(profile.points.length-1,
      Math.round(profile.riderU*(profile.points.length-1))))];
    const rx=chartX+profile.riderU*chartW,ry=chartY+rp.v*chartH;
    g.fillStyle(0xffd24b,1).fillCircle(rx,ry-2,2.6);
    g.lineStyle(1,0xffd24b,1).lineBetween(rx,ry-5,rx,ry-10);
    g.lineStyle(1,0x2ccde5,.4).lineBetween(x+w-11,y+h-5,x+w-5,y+h-5);
  }
  destroy(){this.g?.destroy();this.g=null;}
}/**
 * OWNER: UI engineer.
 * Subtle scanline + vignette overlay generated at runtime (no image assets), an optional rolling bright band
 * (the slow refresh "roll" of a CRT, menus only), and a one-time CRT power-on intro.
 */
import { GAME_WIDTH, GAME_HEIGHT } from '../constants.js';
import { isReducedMotion, tweenProgress, Ease, clamp01 } from './Motion.js';

const KEY = 'bb-scanlines';
const BAND_KEY = 'bb-scanband';
const BAND_H = 28;

/** @param {Phaser.Scene} scene @returns {void} create the shared overlay textures once. */
export function installScanlineTexture(scene) {
  if (!scene.textures.exists(KEY)) {
    const tex = scene.textures.createCanvas(KEY, GAME_WIDTH, GAME_HEIGHT);
    const ctx = tex.context;
    const grad = ctx.createRadialGradient(GAME_WIDTH / 2, GAME_HEIGHT / 2, GAME_HEIGHT * 0.45, GAME_WIDTH / 2, GAME_HEIGHT / 2, GAME_WIDTH * 0.62);
    grad.addColorStop(0, 'rgba(0,0,0,0)');
    grad.addColorStop(1, 'rgba(0,0,0,0.45)');
    ctx.fillStyle = grad;
    ctx.fillRect(0, 0, GAME_WIDTH, GAME_HEIGHT);
    ctx.fillStyle = 'rgba(0,0,0,0.16)';
    for (let y = 1; y < GAME_HEIGHT; y += 2) ctx.fillRect(0, y, GAME_WIDTH, 1);
    tex.refresh();
  }
  if (!scene.textures.exists(BAND_KEY)) {
    // A soft white band, brightest in the middle; drawn additively at low alpha it lifts the scanlines it
    // passes over, the way a CRT's refresh roll does.
    const tex = scene.textures.createCanvas(BAND_KEY, GAME_WIDTH, BAND_H);
    const ctx = tex.context;
    if (ctx && typeof ctx.createLinearGradient === 'function') {
      const g = ctx.createLinearGradient(0, 0, 0, BAND_H);
      g.addColorStop(0, 'rgba(255,255,255,0)');
      g.addColorStop(0.5, 'rgba(255,255,255,1)');
      g.addColorStop(1, 'rgba(255,255,255,0)');
      ctx.fillStyle = g;
      ctx.fillRect(0, 0, GAME_WIDTH, BAND_H);
    }
    tex.refresh();
  }
}

/**
 * Add the overlay to a scene (non-interactive, top depth).
 * @param {Phaser.Scene} scene
 * @param {number} [alpha=1]
 * @param {{roll?:boolean}} [o] roll: add the slow rolling bright band (menus; not the gameplay HUD, where a
 *   moving band would read as a visual event). Skipped while reduce motion is on.
 * @returns {Phaser.GameObjects.Image} the scanline image; the band (if any) is `image.band` and is destroyed
 *   with it.
 */
export function addScanlines(scene, alpha = 1, o = {}) {
  installScanlineTexture(scene);
  const img = scene.add.image(0, 0, KEY).setOrigin(0, 0).setDepth(10000).setAlpha(alpha);
  if (o.roll && scene.tweens && typeof scene.tweens.add === 'function') {
    const band = scene.add.image(0, -BAND_H, BAND_KEY).setOrigin(0, 0).setDepth(10000).setAlpha(0.035 * alpha);
    if (typeof band.setBlendMode === 'function') band.setBlendMode(1); // Phaser.BlendModes.ADD
    // One pass every 7 s, then a pause: a constant band would become wallpaper, an occasional one reads as
    // the tube. Read reduced motion on each update so a preference change hides a moving band immediately.
    const tw = scene.tweens.add({
      targets: band,
      y: { from: -BAND_H, to: GAME_HEIGHT },
      duration: 7000,
      repeatDelay: 2500,
      repeat: -1,
      onUpdate: () => band.setVisible(!isReducedMotion(scene)),
      onRepeat: () => band.setVisible(!isReducedMotion(scene)),
    });
    band.setVisible(!isReducedMotion(scene));
    img.band = band;
    if (typeof img.once === 'function') {
      img.once('destroy', () => {
        if (tw && typeof tw.remove === 'function') tw.remove();
        if (band.scene) band.destroy();
      });
    }
  }
  return img;
}

/** Module-level: the power-on plays once per page load, on whichever menu boots first. */
let poweredOn = false;

/**
 * One-time CRT power-on: from black, a bright dot stretches into a horizontal line, the line opens vertically
 * into the picture, with a brief white bloom. Plays only on the first call per page load (later scene starts
 * are not a power-on) and not at all under reduce motion (the scene's normal fade-in covers it).
 * @param {Phaser.Scene} scene
 * @param {{force?:boolean, duration?:number}} [o] force: play even if it already played (tests, debugging)
 * @returns {boolean} true if it plays
 */
export function playCrtPowerOn(scene, o = {}) {
  if (poweredOn && !o.force) return false;
  poweredOn = true;
  if (isReducedMotion(scene) || !scene.add || typeof scene.add.graphics !== 'function') return false;
  const g = scene.add.graphics().setDepth(20001);
  const W = GAME_WIDTH;
  const H = GAME_HEIGHT;
  const cy = Math.round(H / 2);
  const draw = (p) => {
    if (!g.scene) return;
    g.clear();
    if (p >= 1) return;
    // 0..0.3 dot -> line; 0.3..0.75 line opens to full height; 0.75..1 bloom fades
    const lineP = Ease.outCubic(clamp01(p / 0.3));
    const openP = Ease.inOutCubic(clamp01((p - 0.3) / 0.45));
    const bloom = clamp01((p - 0.3) / 0.15) * (1 - clamp01((p - 0.6) / 0.4));
    const lw = Math.max(2, Math.round(W * lineP));
    const oh = Math.round((H / 2) * openP);
    // black covers everything outside the opening picture
    g.fillStyle(0x000000, 1);
    g.fillRect(0, 0, W, Math.max(0, cy - oh));
    g.fillRect(0, cy + Math.max(1, oh), W, H);
    if (oh < 1) {
      g.fillRect(0, cy, Math.round((W - lw) / 2), 1);
      g.fillRect(Math.round((W + lw) / 2), cy, W, 1);
    }
    // the scan line itself, riding the opening edges
    g.fillStyle(0xffffff, 0.9 * (1 - openP * 0.7));
    g.fillRect(Math.round((W - lw) / 2), cy - oh, lw, 1);
    if (oh > 0) g.fillRect(0, cy + oh, W, 1);
    if (bloom > 0) {
      g.fillStyle(0xffffff, 0.25 * bloom);
      g.fillRect(0, cy - oh, W, oh * 2 + 1);
    }
  };
  draw(0);
  tweenProgress(scene, {
    duration: o.duration || 620,
    onUpdate: (_e, raw) => draw(raw),
    onComplete: () => { if (g.scene) g.destroy(); },
  });
  return true;
}/**
 * Score inspector INSIDE the game, over the actual StemMusicDirector lab.
 * Draws unverified MIDI-like SOURCE candidates with a separate
 * visible ORIGINAL OGG PCM waveform (not a post-FX output or gold notes).
 *
 * Any edit is an isolated, exported PATCH, NOT a live music correction.
 * The game's audio, saved profile, settings and base performance.json stay
 * byte-for-byte untouched. Music Lab remains the source of the real clock.
 */
import Phaser from 'phaser';
import { Panel } from './Panel.js';
import { Button } from './Button.js';
import { MenuList } from './MenuList.js';
import { NeonText } from './Neon.js';
import { ellipsize } from './PixelFont.js';
import { ScoreCorrectionDraft } from '../systems/music/ScoreCorrectionDraft.js';
import { nearbyPerformanceEvents } from '../systems/music/PerformanceScore.js';
import { originalStemWaveform } from '../systems/music/SourceStemWaveform.js';

const RATE=48000;
const HALF_WINDOW=2*RATE;
const GRAPH={x:41,y:51,w:409,h:105};
const ROLES=['melody','bass','drums','guitar','piano','other'];
const DRUMS=['kick','snare','hat','tom','cymbal'];
const noteName=n=>['C','C#','D','D#','E','F','F#','G','G#','A','A#','B'][n%12]+
	(Math.floor(n/12)-1);
const ms=x=>Math.round(x/RATE*1000);

export class ScoreInspectorView {
	constructor(scene,theme,{lab,onClose,draft}){
		if(!lab?.score||!lab?.lab?.pack)throw new Error('No verified source score to inspect');
		this.scene=scene;
		this.theme=theme;
		this.labView=lab;
		this.score=lab.score;
		this.draft=draft||new ScoreCorrectionDraft(this.score);
		if(this.draft.scoreHash!==this.score.scoreHash)
			throw new Error('Cannot inspect patches for different source version');
		this.onClose=onClose;
		this.alive=true;
		this.role=ROLES.includes(lab.solo.toLowerCase())?
			lab.solo.toLowerCase():lab.score.featuredStem;
		this.anchorFrame=lab._clockFrame()||0;
		this.follow=true;
		this.comparison=false; // V2 is overlay ONLY, never live audio
		this.reviewIndex=-1;
		this.selectedId=null;
		this.message='TENTATIVE NOTES. NO EDITS ARE APPLIED TO MUSIC.';
		this.windowStart=0;
		this.waveformCoverage=0;
		this.waveformSource=null;
		this._hitBoxes=[];
		this.panel=new Panel(scene,theme,{
			x:6,y:7,w:468,h:253,title:'SCORE INSPECTOR  //  DRAFT ONLY',
			color:'amber',fillAlpha:1,
		}).setDepth(560);
		// Prevent hidden parent Music Lab buttons from handling pointer
		// events in the inspector's blank areas.
		const shield=new Phaser.GameObjects.Zone(scene,0,0,468,253)
			.setOrigin(0,0).setInteractive();
		this.panel.add(shield);

		this.menu=new MenuList(scene,theme,{
			x:10,y:23,w:446,rowH:18,color:'amber',parent:this.panel,
			items:[{kind:'choice',label:'INSTRUMENT ROLE',options:
				ROLES.map(role=>({value:role,label:role.toUpperCase()})),
				get:()=>this.role,set:role=>this.setRole(role)}],
		});

		this.graph=new Phaser.GameObjects.Graphics(scene);
		this.graph.setPosition(GRAPH.x,GRAPH.y);
		this.panel.add(this.graph);
		this.hitArea=new Phaser.GameObjects.Zone(scene,
			GRAPH.x,GRAPH.y,GRAPH.w,GRAPH.h).setOrigin(0,0).setInteractive(
				{useHandCursor:true});
		this.panel.add(this.hitArea);
		this.hitArea.on('pointerdown',(pointer,x,y)=>this.pick(x,y));

		this.windowLabel=new NeonText(scene,theme,10,161,'',{
			color:'cyan',outline:'none',
		});
		this.panel.add(this.windowLabel);
		this.reviewButton=new Button(scene,theme,{
			x:352,y:158,w:99,h:13,label:'NEXT SUSPECT',color:'magenta',
			onClick:()=>this.nextReview(),parent:this.panel,
		}).setDisabled(true);
		this.detailLine=new NeonText(scene,theme,10,172,'',{
			color:'amber',outline:'none',
		});
		this.panel.add(this.detailLine);
		this.helpLine=new NeonText(scene,theme,10,184,'',{
			color:'text',outline:'none',
		});
		this.panel.add(this.helpLine);
		this.messageLine=new NeonText(scene,theme,10,195,'',{
			color:'magenta',outline:'none',
		});
		this.panel.add(this.messageLine);
		const control=(x,y,w,label,fn,color='cyan')=>{
			return new Button(scene,theme,{x,y,w,h:15,label,
				onClick:fn,color,parent:this.panel});
		};
		this.controls={
			prev:control(10,210,57,'< NOTE',()=>this.shift(-1)),
			next:control(71,210,57,'NOTE >',()=>this.shift(1)),
			early:control(132,210,54,'-10MS',()=>this.modify('nudge',-480)),
			late:control(190,210,54,'+10MS',()=>this.modify('nudge',480)),
			down:control(248,210,54,'-OCT',()=>this.modify('octave',-12)),
			up:control(306,210,54,'+OCT',()=>this.modify('octave',12)),
			hear:control(364,210,87,'HEAR STEM',()=>this.hear()),
			reject:control(10,233,66,'REJECT',()=>this.modify('reject'), 'magenta'),
			accept:control(81,233,66,'ACCEPT',()=>this.modify('accept'), 'lime'),
			undo:control(152,233,62,'UNDO',()=>this.modify('undo'), 'amber'),
			export:control(219,233,63,'PATCH',()=>this.exportPatch()),
			compare:control(286,233,41,'V2',()=>this.toggleComparison(),'magenta'),
			follow:control(332,233,53,'FOLLOW',()=>this.toggleFollow()),
		};
		this.back=control(390,231,68,'BACK',()=>this.close(),'magenta');
		this._paletteUnbind=theme.bind(()=>this.refresh());
		this.refresh();
	}

	/** Jump to a machine-DISAGREEMENT passage on the SAME song's real
	 * source game clock. This is not a confirmed bad note or gold label.
	 * It seeks only the lab's sandbox engine, never the main game stream.
	 */
	nextReview(){
		const rows=this.labView?.reviewQueue?.excerpts||[];
		if(!rows.length||!this.labView?.experimentalScore)return false;
		this.reviewIndex=(this.reviewIndex+1)%rows.length;
		const row=rows[this.reviewIndex];
		this.role=row.role;
		this.anchorFrame=Math.min(this.score.frameCount-1,
			row.startFrame+2*RATE);
		this.follow=false;
		this.comparison=true;
		this.selectedId=null;
		this._selectNearest();
		this.menu.refresh();
		this.labView._solo(row.role.toUpperCase());
		this.labView.lab.seekTo(Math.max(0,row.startFrame/RATE-.2));
		this.message='UNVERIFIED RANK '+row.priorityOrder+
			' '+row.role.toUpperCase()+' BASE '+row.releaseCount+
			' / V2 '+row.candidateCount+'; MATCH '+row.samePitchWithin50ms;
		this.refresh();
		return true;
	}

	setRole(role){
		if(!ROLES.includes(role))return;
		this.role=role;
		this.selectedId=null;
		this._selectNearest();
		this.message='CHANGED ROLE. SOURCE ESTIMATES ARE NOT GOLD NOTES.';
		this.menu?.refresh(); // keep the selected instrument selector in sync
		this.refresh();
	}

	_clock(){
		return this.labView?._clockFrame()??this.anchorFrame;
	}

	_events(){
		return this.score.events[this.role]||[];
	}

	_selectNearest(){
		const events=this._events();
		if(!events.length){this.selectedId=null;return;}
		const frame=this.anchorFrame;
		let low=0,high=events.length;
		while(low<high){
			const mid=(low+high)>>1;
			if(events[mid].startFrame<frame)low=mid+1;
			else high=mid;
		}
		const idx=low===0?0:low===events.length?events.length-1:
			Math.abs(events[low].startFrame-frame)<
				Math.abs(events[low-1].startFrame-frame)?low:low-1;
		this.selectedId=events[idx].id;
	}

	_selected(){
		const events=this._events();
		return events.find(event=>event.id===this.selectedId)||null;
	}

	_preview(event){
		return this.draft.preview(event.id)||event;
	}

	/** Move to the previous/next source event (not a guessed beat). */
	shift(direction){
		const events=this._events();
		if(!events.length)return;
		const current=events.findIndex(e=>e.id===this.selectedId);
		const next=(current<0?0:Math.max(0,Math.min(events.length-1,
			current+(direction<0?-1:1))));
		this.selectedId=events[next].id;
		this.anchorFrame=events[next].startFrame;
		this.follow=false;
		this.message='SOURCE EVENT SELECTED; AUDIO NOT CHANGED.';
		this.refresh();
	}

	pick(x,y){
		if(!this._hitBoxes.length)return;
		let best=null,score=Infinity;
		for(const rect of this._hitBoxes){
			// Pointer is local to the rectangle; choose closest note.
			const dx=Math.max(0,rect.x-x,x-(rect.x+rect.w));
			const dy=Math.max(0,rect.y-y,y-(rect.y+rect.h));
			const distance=dx*dx+dy*dy;
			if(distance<score){score=distance;best=rect;}
		}
		if(!best||score>100)return;
		this.selectedId=best.id;
		this.anchorFrame=this.draft.preview(best.id).startFrame;
		this.follow=false;
		this.message='SOURCE EVENT SELECTED; USE +10MS/-10MS OR OCTAVE.';
		this.refresh();
	}

	modify(action,amount=0){
		const event=this._selected();
		if(!event)return;
		if(!this.draft.modify(event.id,action,amount)){
			this.message='INVALID EDIT: FRAME/PITCH LIMIT OR NEIGHBOR ORDER.';
			this.refresh();return;
		}
		this.follow=false;
		this.message=action.toUpperCase()+
			' DRAFT ONLY. EXPORT PATCH TO KEEP THIS CORRECTION.';
		this.refresh();
	}

	hear(){
		const event=this._selected();
		if(!event||!this.labView?.lab?.pack)return;
		const frame=this.draft.preview(event.id).startFrame;
		// A transcription guess is NOT a soloable sound. Listen to its
		// instrument ROLE via the actual game mixer, honoring the current
		// Dynamic Orchestra source/replacement setting. This is not an
		// invented single-note audition or the old standalone lab.
		this.labView._solo(this.role.toUpperCase());
		this.labView.lab.seekTo(Math.max(0,(frame/RATE)-.18));
		this.message='REAL GAME ROLE SOLOED AND SEEKED NEAR THE ATTACK.';
		this.refresh();
	}

	toggleComparison(){
		if(!this.labView?.experimentalScore){
			this.comparison=false;
			this.message=this.labView?.experimentalStatus||
				'UNVERIFIED CANDIDATE NOT AVAILABLE';
		}else{
			this.comparison=!this.comparison;
			this.message=this.comparison?
				'PINK V2 EXPERIMENTAL; CYAN RELEASE. NEITHER IS GOLD.':
				'RELEASE SCORE ONLY. MUSIC IS UNCHANGED.';
		}
		this.refresh();
	}

	toggleFollow(){
		this.follow=!this.follow;
		if(this.follow)this.anchorFrame=this._clock();
		this.message=this.follow?'FOLLOWING LIVE WEB AUDIO CLOCK':
			'VIEW FIXED TO SELECTED CANDIDATES';
		this.refresh();
	}

	exportPatch(){
		const data=this.draft.export();
		if(!data||typeof document==='undefined')return;
		const blob=new Blob([JSON.stringify(data,null,2)+'\n'],
			{type:'application/json'});
		const url=URL.createObjectURL(blob);
		try{
			const link=document.createElement('a');
			link.href=url;
			link.download='bitstream-candidate-fixes-'+this.score.songId+
				'-'+this.score.scoreHash.slice(0,10)+'.json';
			document.body.appendChild(link);
			link.click();
			link.remove();
		}finally{
			setTimeout(()=>URL.revokeObjectURL(url),10000);
		}
		this.message='PATCH EXPORTED. MUSIC AND SAVE ARE STILL UNCHANGED.';
		this.refresh();
	}

	/** Draw only a four-second viewport, even for full 3-minute songs. */
	refresh(){
		if(!this.alive)return;
		if(this.follow)this.anchorFrame=this._clock();
		if(!this._selected())this._selectNearest();
		this.windowStart=Math.max(0,Math.min(
			this.score.frameCount-2*HALF_WINDOW,
			this.anchorFrame-HALF_WINDOW));
		const g=this.graph,pal=this.theme.pal;
		g.clear();
		g.fillStyle(pal.bg,1);
		g.fillRect(0,0,GRAPH.w,GRAPH.h);
		g.lineStyle(1,pal.text,.11);
		for(let i=1;i<4;i++){
			g.lineBetween(i*GRAPH.w/4,0,i*GRAPH.w/4,GRAPH.h);
		}
		// The actual ORIGINAL OGG decode cache, not synthesized MIDI notes:
		// these source PCM peaks follow the same four-second source-frame
		// window as the provisional piano roll and its moving WebAudio playhead.
		// The original recording may be replaced/routed or FX-processed, so
		// NEVER claim this overlay represents final DSP/rendered amplitude.
		const director=this.labView?.lab;
		const sourceRole=this.role==='melody' ?
			director?._activeVoiceFor(director.pack) : this.role;
		const waveform=sourceRole ? originalStemWaveform(
			director?.pack,director?.cache,sourceRole,this.windowStart,
			this.windowStart+2*HALF_WINDOW,204) : null;
		this.waveformSource=sourceRole||null;
		this.waveformCoverage=waveform?.coverage||0;
		if(waveform?.available){
			const h=19,yBottom=GRAPH.h-2;
			g.lineStyle(1,pal.amber,.23);
			g.lineBetween(0,yBottom-h,GRAPH.w,yBottom-h);
			g.fillStyle(pal.amber,.43);
			for(let i=0;i<waveform.bins.length;i++){
				const peak=waveform.bins[i];
				if(peak<=0)continue;
				const x=i/waveform.bins.length*GRAPH.w;
				g.fillRect(x,yBottom-Math.max(1,peak*h),
					Math.ceil(GRAPH.w/waveform.bins.length),Math.max(1,peak*h));
			}
		}
		let events=nearbyPerformanceEvents(this.score,[this.role],
			this.windowStart+HALF_WINDOW,HALF_WINDOW);
		const experimental=this.comparison?this.labView?.experimentalScore:null;
		const candidateEvents=experimental?nearbyPerformanceEvents(experimental,
			[this.role],this.windowStart+HALF_WINDOW,HALF_WINDOW):[];
		// A role's events are original-source hypotheses, not rendered
		// audio transients. The viewed clock is the real game's clock.
		this._hitBoxes=[];
		const pitches=[...events,...candidateEvents]
			.filter(e=>e.event.pitch!==undefined).map(e=>e.event.pitch);
		const sorted=pitches.slice().sort((a,b)=>a-b);
		const median=sorted.length?sorted[Math.floor(sorted.length/2)]:60;
		const minPitch=Math.max(0,Math.min(103,median-11));
		const maxPitch=minPitch+23;
		const roleDrums=this.role==='drums';
		const yFor=e=>{
			if(roleDrums){
				const lane=DRUMS.indexOf(e.class);
				return Math.max(2,Math.min(GRAPH.h-11,
					2+(lane<0?4:lane)*(GRAPH.h-4)/5));
			}
			return 2+(maxPitch-e.pitch)*(GRAPH.h-4)/24;
		};
		if(roleDrums){
			g.lineStyle(1,pal.cyan,.16);
			for(let lane=1;lane<5;lane++){
				g.lineBetween(0,lane*GRAPH.h/5,GRAPH.w,lane*GRAPH.h/5);
			}
		}else{
			g.lineStyle(1,pal.cyan,.08);
			for(let p=minPitch;p<=maxPitch;p+=12){
				const y=2+(maxPitch-p)*(GRAPH.h-4)/24;
				g.lineBetween(0,y,GRAPH.w,y);
			}
		}
		// Purple/pink V2 is drawn behind CYAN release events, but cannot
		// be selected, edited or exported as an approved/gold source.
		// Its notes have NEVER been synthesized into released audio.
		for(const {event} of candidateEvents){
			const x=(event.startFrame-this.windowStart)/
				(2*HALF_WINDOW)*GRAPH.w;
			if(x<0||x>=GRAPH.w)continue;
			const y=yFor(event);
			if(y<0||y>=GRAPH.h-4)continue;
			const width=roleDrums?3:Math.max(3,Math.min(120,
				(event.endFrame-event.startFrame)/
				(2*HALF_WINDOW)*GRAPH.w));
			g.fillStyle(pal.magenta,.38);
			g.fillRect(x,y,width,roleDrums?11:4);
		}
		for(const {event} of events){
			const adjusted=this._preview(event);
			if(adjusted.status==='reject')continue;
			const x=(adjusted.startFrame-this.windowStart)/
				(2*HALF_WINDOW)*GRAPH.w;
			if(x<0||x>=GRAPH.w)continue;
			const y=yFor(adjusted);
			if(y<0||y>=GRAPH.h-4)continue;
			const width=roleDrums?3:Math.max(3,Math.min(120,
				(adjusted.endFrame-adjusted.startFrame)/
				(2*HALF_WINDOW)*GRAPH.w));
			const height=roleDrums?11:4;
			const selected=event.id===this.selectedId;
			const color=selected?pal.amber:
				this.draft.edits.has(event.id)?pal.text:pal.cyan;
			g.fillStyle(color,selected?1:.7);
			g.fillRect(x,y,width,height);
			this._hitBoxes.push({id:event.id,x,y,w:width,h:height});
		}
		const clockX=(this._clock()-this.windowStart)/
			(2*HALF_WINDOW)*GRAPH.w;
		if(clockX>=0&&clockX<=GRAPH.w){
			g.lineStyle(1,pal.lime,.9);
			g.lineBetween(clockX,0,clockX,GRAPH.h);
		}
		g.lineStyle(1,pal.cyan,.5);
		g.strokeRect(.5,.5,GRAPH.w-1,GRAPH.h-1);
		const a=Math.floor(this.windowStart/RATE*10)/10;
		const b=Math.ceil((this.windowStart+2*HALF_WINDOW)/RATE*10)/10;
		this.windowLabel.setText(ellipsize(
			this.role.toUpperCase()+' '+a.toFixed(1)+'-'+b.toFixed(1)+
			'S / '+(roleDrums?'DRUM HITS':'MIDI*')+
			' / OGG '+Math.round(this.waveformCoverage*100)+'%'+
			' / GREEN = LIVE',331));
		const event=this._selected();
		const preview=event&&this._preview(event);
		const desc=preview?(this.role.toUpperCase()+'  '+
			(roleDrums?preview.class.toUpperCase():
				noteName(preview.pitch)+' ('+preview.pitch+')')+
			' @'+(preview.startFrame/RATE).toFixed(3)+'S  '+
			event.id.slice(0,12)+'  '+preview.status.toUpperCase()):
			'NO SOURCE CANDIDATES';
		this.detailLine.setText(ellipsize(desc,446));
		this.helpLine.setText(ellipsize(
			(this.comparison&&experimental?
				'CYAN BASE / PINK V2 / WHITE DRAFT / AMBER RAW OGG':
				'CYAN NOTES / WHITE DRAFT / AMBER RAW OGG')+
			' / GREEN LIVE / NO GOLD NOTES',446));
		// The selected eight-second machine-review record already states
		// the count comparison. Do not append overlapping four-second counts.
		const counts=this.comparison&&experimental&&this.reviewIndex<0?
			'  BASE '+events.length+' / V2 '+candidateEvents.length:'';
		const corrupted=this.labView?.reviewStatus?.startsWith(
			'REVIEW SHORTLIST REJECTED:');
		this.messageLine.setText(ellipsize(
			(corrupted?this.labView.reviewStatus:this.message)+counts+
			'  ('+this.draft.count+' EDITS)',447));
		this.controls.up.setDisabled(!event||roleDrums);
		this.controls.down.setDisabled(!event||roleDrums);
		this.controls.export.setDisabled(!this.draft.count);
		this.reviewButton.setDisabled(!this.labView?.reviewQueue?.excerpts?.length||
			!this.labView?.experimentalScore);
		this.controls.compare.setDisabled(!this.labView?.experimentalScore);
		this.controls.compare.setLabel(this.comparison?'V2 ON':'V2');
		this.controls.follow.setLabel(this.follow?'FREEZE':'FOLLOW');
	}

	handleAction(action){
		if(action==='cancel'){this.close();return true;}
		if(action==='alt'){this.nextReview();return true;}
		if(action==='left'){this.shift(-1);return true;}
		if(action==='right'){this.shift(1);return true;}
		if(action==='up'||action==='down'){
			const index=ROLES.indexOf(this.role);
			this.setRole(ROLES[(index+(action==='up'?-1:1)+ROLES.length)%
				ROLES.length]);
			return true;
		}
		if(action==='confirm'){this.hear();return true;}
		return true;
	}

	close(){
		if(this.alive)this.onClose();
	}

	destroy(){
		if(!this.alive)return;
		this.alive=false;
		this._paletteUnbind?.();
		this.panel.destroy();
		this.panel=null;
	}
}/**
 * W4 shop — the SHOP view's layout, kept Phaser-free so it can be overlap-tested in Jest.
 *
 * Same contract as ProfileLayout: every box is in panel-local game pixels, `x`/`y` is the TOP-LEFT
 * corner and `w`/`h` the measured extent, so a test can intersect boxes directly and a renderer can draw
 * left-anchored without re-applying an origin.
 *
 * ONE LIST, NOT TWO. The first version of this view drew a static layer of headers and item names AND a
 * MenuList of the same rows at a different pitch, so every line was two strings on top of each other (CC
 * Friday's W4 rejection, defect 1). The fix is structural, not cosmetic: this module returns a single
 * ordered list of rows — each either a header (drawn, never selectable) or an interactive row — and the
 * view feeds exactly that list to one MenuList. A header can no longer land on a row's y, because nothing
 * is positioned independently any more.
 *
 * Defect 2 was the same root cause from the other side: the static layer could never be refreshed, so
 * after a purchase the bank line still read the old balance. Now every visible string is a row in one
 * list, so rebuilding after a purchase redraws all of it.
 */
import { measureText } from './PixelFont.js';
import { UPGRADE_CATALOG, sanitizeUpgradeRanks, nextUpgradePrice } from '../systems/PermanentUpgrades.js';
import { BSOD_GYM_PRICE, gymVisible, gymOwned, gymAdvanced, gymSetupForProfile, GYM_SETUP_OPTIONS } from '../systems/BsodGym.js';
import { SHOP_ITEMS, isOwned } from '../systems/ProfileStore.js';
import { loadLevelTable, levelForXp } from '../systems/Progression.js';

/** Shop panel: wide enough for "NAME .......... 120" with the price right-aligned. */
export const SHOP_PANEL = Object.freeze({ w: 416, h: 236 });

/**
 * The catalogue is shown one slot per page (audit F4 fit). The flat list was 247 of 248 px tall with nine
 * cosmetic rows; the eleven level rewards would have pushed it off a 270 px screen. Titles are not a page:
 * they are equipped (and Static Rider bought) from the Profile view's TITLES screen.
 */
export const SHOP_PAGES = Object.freeze(['trail', 'glow', 'rider', 'theme']);

const GLYPH_H = 8;
const PAD = 12;
// A glyph is 8 tall, so an 11 px pitch leaves 3 px of clear air between lines. The tallest page is the
// bank line, the page row, six items, a boosts header, two toggles, a loadout header and the loadout line:
// 13 rows, 143 px plus margins, inside the 236 px panel.
const ROW_H = 11;

const BOOSTS = Object.freeze([
  { id: 'errorCorrection', label: 'ERROR CORRECTION' },
  { id: 'headStart', label: 'HEAD START' },
]);

const upper = (s) => String(s === undefined || s === null ? '' : s).toUpperCase();

/**
 * The whole shop as one ordered list of rows.
 *
 * Row shapes:
 *   { kind:'page',   key, label, state, slot, page }  — the page selector ("← TRAIL →", "1/4"); selectable
 *   { kind:'header', key, label }                    — section heading, never selectable
 *   { kind:'item',   key, id, label, state, disabled, owned, equipped, locked, price }
 *   { kind:'boost',  key, id, label, on, locked, unlockLevel, state, disabled }
 *                                                    — a toggle row; locked (not in unlocked.boosts) = disabled
 *   { kind:'static', key, label, color }             — the loadout line, never selectable
 * Every row owns its measured text box in `texts`; that array is what the overlap test intersects.
 *
 * @param {Object} o
 * @param {Object|null} o.profile
 * @param {Object} [o.levels] parsed levels.json (content.progression); only used to name the level that
 *   unlocks a locked boost. Without it a locked boost reads "LOCKED".
 * @param {number} [o.page] index into SHOP_PAGES (default 0); wraps both ways
 * @returns {{w:number,h:number,rows:Array,texts:Array<{key:string,text:string,x:number,y:number,w:number,h:number,color:string}>,
 *            rowH:number, band:{x:number,y:number,w:number}, bankText:string, loadoutText:string, firstSelectable:number,
 *            page:number, pageCount:number, pageSlot:string}}
 */
export function shopLayout(o = {}) {
  const profile = o.profile || {};
  const equipped = (profile.equipped && typeof profile.equipped === 'object') ? profile.equipped : {};
  const boosts = (profile.boosts && typeof profile.boosts === 'object') ? profile.boosts : {};
  const bank = Number.isFinite(profile.bank) ? profile.bank : 0;
  const level = Number.isFinite(profile.level) ? profile.level : 1;
  const grants = (profile.unlocked && typeof profile.unlocked === 'object' && profile.unlocked.boosts
    && typeof profile.unlocked.boosts === 'object') ? profile.unlocked.boosts : {};
  const levelRows = (o.levels && Array.isArray(o.levels.levels)) ? o.levels.levels : [];

  const rows = [];
  const texts = [];

  // Title band. The panel's own Panel object draws the frame title, so this row carries the BANK only —
  // and it is a row like any other, which is what keeps it refreshable.
  const bankText = `BANK ${bank}`;
  rows.push({ kind: 'head', key: 'head', label: '', right: bankText });

  // One slot per page, cheapest first inside it, so like is compared with like.
  const n = SHOP_PAGES.length;
  const rawPage = Number.isFinite(o.page) ? Math.trunc(o.page) : 0;
  const page = ((rawPage % n) + n) % n;
  const pageSlot = SHOP_PAGES[page];
  // The page row doubles as the slot heading: "← TRAIL →" with its position, so a player always knows
  // there is more than one page and where they are in it.
  rows.push({
    kind: 'page', key: 'page', slot: pageSlot, page, label: `← ${upper(pageSlot)} →`, state: `${page + 1}/${n}`,
    disabled: false,
  });
  const sorted = [...SHOP_ITEMS]
    .filter((i) => i && i.slot === pageSlot)
    .sort((a, b) => (a.price - b.price) || ((a.unlockLevel || 1) - (b.unlockLevel || 1)));

  for (const it of sorted) {
    const owned = isOwned(profile, it.id);
    // equip() stores the catalogue's VALUE ('mint'), older profiles may hold the ID; accept both.
    const isEquipped = equipped[it.slot] === it.id || equipped[it.slot] === it.value;
    // A biome grant (the Neon Sled Drone) is locked until its biome is completed, whatever the level, and its
    // locked state names the condition ("COMPLETE MICRO MOUNTAIN") rather than a level it does not have.
    const grantLocked = it.grant === 'biome' && !owned;
    const locked = grantLocked || level < (it.unlockLevel || 1);
    const affordable = bank >= (it.price || 0);

    // State is in the TEXT, not only the colour: colourblind mode and a small screen both have to tell
    // "owned" from "buy" from "locked", and colour alone cannot do that.
    let state;
    if (isEquipped) state = 'EQUIPPED';
    else if (owned) state = 'EQUIP';
    else if (grantLocked) state = upper(it.unlockText || 'LOCKED');
    else if (locked) state = `LVL ${it.unlockLevel}`;
    else state = it.price > 0 ? String(it.price) : 'REWARD';

    // SHOP-3: the EQUIPPED row is selectable, and selecting it returns the slot to DEFAULT (the view calls
    // ProfileStore.unequip). It used to be disabled, so focus skipped it and nothing on screen could ever
    // take a cosmetic back off. A separate DEFAULT row per page would cost a row the tallest page needs.
    rows.push({
      kind: 'item', key: `item-${it.id}`, id: it.id, slot: it.slot, label: upper(it.name), state,
      owned, equipped: isEquipped, locked, affordable, price: it.price,
      disabled: !isEquipped && (locked || (!owned && !affordable)),
    });
  }

  // Boosts are part of the same list because they are part of the same panel. The old view positioned
  // them from an estimate of the catalogue's height, which is exactly how they landed on the TRAIL rows.
  rows.push({ kind: 'header', key: 'hdr-boosts', label: 'BOOSTS' });
  // F3: a boost is offered only once the profile owns it. Ownership is the grant record ProfileStore
  // writes when a level-up crosses the boost's level (`unlocked.boosts[id]`, levels 8 and 15 today); the
  // shop shows that record, it does not re-derive it from the level. A locked boost stays visible, says
  // the level that unlocks it, and cannot be selected.
  for (const b of BOOSTS) {
    const locked = !grants[b.id];
    const entry = levelRows.find((l) => l && l.boost === b.id);
    const unlockLevel = entry && Number.isFinite(entry.level) ? entry.level : null;
    const on = boosts[b.id] === true;
    const state = locked ? (unlockLevel ? `LVL ${unlockLevel}` : 'LOCKED') : (on ? 'ON' : 'OFF');
    rows.push({ kind: 'boost', key: `boost-${b.id}`, id: b.id, label: b.label, on, locked, unlockLevel, state, disabled: locked });
  }

  // Loadout: what the next run will actually look like.
  rows.push({ kind: 'header', key: 'hdr-loadout', label: 'LOADOUT' });
  const loadoutText = ['trail', 'glow', 'rider', 'theme']
    .map((slot) => {
      const v = equipped[slot];
      const shown = (v && v !== 'default') ? upper(String(v).replace(/^[a-z]+-(hue|glow)-/, '')) : 'DEFAULT';
      return `${upper(slot)} ${shown}`;
    })
    .join('  ');
  rows.push({ kind: 'static', key: 'loadout', label: loadoutText, color: 'text' });
  rows.push({ kind: 'upgradeLink', key: 'upgradeLink', label: 'PERMANENT UPGRADES', state: 'OPEN' });

  // Lay the rows out and measure every drawn string. Because y comes from this single loop, a row's text
  // and the menu's own row geometry cannot disagree.
  let y = 8;
  let firstSelectable = -1;
  rows.forEach((r, i) => {
    r.y = y;
    r.index = i;
    if (r.kind === 'head') {
      const bw = measureText(r.right);
      r.texts = [{ key: 'head-right', text: r.right, x: SHOP_PANEL.w - PAD - bw, y, w: bw, h: GLYPH_H, color: 'amber' }];
    } else if (r.kind === 'page') {
      if (firstSelectable < 0) firstSelectable = i;
      const rw = measureText(r.state);
      r.texts = [
        { key: `${r.key}-label`, text: r.label, x: PAD + 6, y, w: measureText(r.label), h: GLYPH_H, color: 'magenta' },
        { key: `${r.key}-right`, text: r.state, x: SHOP_PANEL.w - PAD - 6 - rw, y, w: rw, h: GLYPH_H, color: 'magenta' },
      ];
    } else if (r.kind === 'upgradeLink') {
      const rw = measureText(r.state);
      r.texts = [
        { key: r.key + '-label', text: r.label, x: PAD + 6, y, w: measureText(r.label), h: GLYPH_H, color: 'lime' },
        { key: r.key + '-right', text: r.state, x: SHOP_PANEL.w - PAD - 6 - rw, y, w: rw, h: GLYPH_H, color: 'lime' },
      ];
    } else if (r.kind === 'item') {
      if (firstSelectable < 0) firstSelectable = i;
      const right = r.state;
      const rw = measureText(right);
      const labelColor = r.equipped ? 'lime' : (r.locked ? 'text' : 'text');
      r.texts = [
        { key: `${r.key}-label`, text: r.label, x: PAD + 6, y, w: measureText(r.label), h: GLYPH_H, color: labelColor },
        { key: `${r.key}-right`, text: right, x: SHOP_PANEL.w - PAD - 6 - rw, y, w: rw, h: GLYPH_H,
          color: r.equipped ? 'cyan' : (r.owned ? 'lime' : (r.locked ? 'text' : 'amber')) },
      ];
    } else if (r.kind === 'boost') {
      if (firstSelectable < 0) firstSelectable = i;
      const stateText = r.state;
      const rw = measureText(stateText);
      r.texts = [
        { key: `${r.key}-label`, text: r.label, x: PAD + 6, y, w: measureText(r.label), h: GLYPH_H, color: 'text' },
        { key: `${r.key}-right`, text: stateText, x: SHOP_PANEL.w - PAD - 6 - rw, y, w: rw, h: GLYPH_H, color: (!r.locked && r.on) ? 'lime' : 'text' },
      ];
    } else {
      r.texts = [{ key: `${r.key}-label`, text: r.label, x: PAD, y, w: measureText(r.label), h: GLYPH_H, color: r.kind === 'header' ? 'magenta' : (r.color || 'text') }];
    }
    for (const t of r.texts) texts.push(t);
    y += ROW_H;
  });

  // Height: last row, plus room for the BACK button the base View pins to the panel floor.
  const contentH = y + 30;
  return {
    w: SHOP_PANEL.w,
    h: Math.max(SHOP_PANEL.h, contentH),
    rows,
    texts,
    rowH: ROW_H,
    band: { x: PAD - 6, y: 8, w: SHOP_PANEL.w - (PAD - 6) * 2 },
    bankText,
    loadoutText,
    firstSelectable,
    page,
    pageCount: n,
    pageSlot,
  };
}

/**
 * Every item row the shop shows, across all of its pages, in page order. For callers that need the whole
 * catalogue as the shop presents it (the shop prompt's "is anything buyable here" agreement, for one).
 * @param {Object} o same options as shopLayout, minus `page`
 * @returns {Array<Object>} the `kind:'item'` rows
 */
export function shopAllRows(o = {}) {
  const out = [];
  for (let page = 0; page < SHOP_PAGES.length; page++) {
    for (const r of shopLayout({ ...o, page }).rows) if (r.kind === 'item') out.push(r);
  }
  return out;
}

/**
 * MenuList items for the shop: the SAME rows in the SAME order. Headers and the loadout line become
 * non-selectable rows so the menu's geometry places them too — the single-geometry rule again.
 *
 * `onSelect` is left null here; the view attaches the buy/equip handler by id, because this module must
 * stay Phaser-free and side-effect-free.
 *
 * @param {Object} layout
 * @returns {Array<Object>}
 */
export function shopMenuItems(layout) {
  return layout.rows.map((r) => {
    if (r.kind === 'page') {
      return { kind: 'action', rowKind: 'page', label: r.label, sub: r.state, page: r.page, disabled: false, onSelect: null };
    }
    if (r.kind === 'upgradeLink') return { kind: 'action', rowKind: 'upgradeLink', label: r.label, sub: r.state, disabled: false };
    if (r.kind === 'item') {
      return { kind: 'action', id: r.id, label: r.label, sub: r.state, rowKind: 'item', disabled: r.disabled, onSelect: null };
    }
    if (r.kind === 'boost') {
      // A locked boost is a disabled row that shows its unlock level instead of an ON/OFF value.
      if (r.locked) {
        return { kind: 'action', id: r.id, label: r.label, rowKind: 'boost', boostId: r.id, sub: r.state, disabled: true, onSelect: null };
      }
      return {
        kind: 'choice', id: r.id, label: r.label, rowKind: 'boost', boostId: r.id, disabled: false,
        options: [{ value: false, label: 'OFF' }, { value: true, label: 'ON' }],
        get: () => r.on, set: null,
      };
    }
    // head / header / static: drawn, never selectable, never focusable.
    return { kind: 'static', label: r.label, rowKind: r.kind, key: r.key, disabled: true };
  });
}

/** Pure page for the permanent-upgrade catalog; shares the shop's single-row geometry. */
export function upgradeShopLayout(o = {}) {
  const profile = o.profile || {};
  const bank = Number.isSafeInteger(profile.bank) ? profile.bank : 0;
  const ranks = sanitizeUpgradeRanks(profile.upgrades);
  const rows = [
    { kind: 'head', key: 'head', label: '', right: 'BANK ' + bank },
    { kind: 'upgradeBack', key: 'upgradeBack', label: '← BACK TO SHOP', state: '' },
    { kind: 'upgradeToggle', key: 'upgradeToggle', label: 'UPGRADE MODE', state: profile.upgradesEnabled === true ? 'ON' : 'OFF' },
    { kind: 'header', key: 'header', label: 'PURCHASE PERMANENT RANKS' },
  ];
  for (const spec of UPGRADE_CATALOG) {
    const rank = ranks[spec.id];
    const price = nextUpgradePrice(spec.id, rank);
    rows.push({ kind: 'upgradeItem', key: 'upgrade-' + spec.id, id: spec.id,
      label: spec.label + ' R' + rank,
      state: price == null ? 'UNAVAILABLE' : '' + price,
      disabled: price == null,
    });
  }
  // The Gym remains entirely absent until the first legitimately scored
  // BSOD escape. Do not reveal how to earn that discovery in store copy.
  if (gymVisible(profile)) {
    const owned = gymOwned(profile);
    rows.push({ kind: 'gym', key: 'bsodGym', id: 'bsodGym',
      label: 'BSOD GYM', state: owned ? 'ENTER' : `LOCKED ${BSOD_GYM_PRICE}`,
      disabled: !owned && bank < BSOD_GYM_PRICE });
    // No disabled / mysterious hint row before the actual in-Gym 5x unlock.
    if (gymAdvanced(profile)) rows.push({ kind: 'gymSetupLink', key: 'bsodGymSetup',
      id: 'bsodGymSetup', label: 'GYM SETUP', state: 'OPEN' });
  }
  rows.push({ kind: 'static', key: 'softcap', label: 'UNLIMITED RANKS / DIMINISHING RETURNS' });
  rows.push({ kind: 'static', key: 'ranked', label: 'MODE ON = MODDED, OFFICIAL DAILY CLEAN' });
  const texts = [];
  let y = 8;
  for (const row of rows) {
    row.y = y;
    if (row.kind === 'head') {
      const w = measureText(row.right);
      row.texts = [{ key: 'head-bank', text: row.right, x: SHOP_PANEL.w - PAD - w, y, w, h: GLYPH_H, color: 'amber' }];
    } else {
      const left = row.kind === 'header' || row.kind === 'static' ? PAD : PAD + 6;
      row.texts = [{ key: row.key + '-label', text: row.label,
        x: left, y, w: measureText(row.label), h: GLYPH_H,
        color: row.kind === 'gym' ? 'cyan' : row.kind === 'upgradeItem' ? 'text' : row.kind === 'upgradeBack' ? 'cyan' : 'magenta' }];
      if (row.state) {
        const w = measureText(row.state);
        row.texts.push({ key: row.key + '-state', text: row.state,
          x: SHOP_PANEL.w - PAD - 6 - w, y, w, h: GLYPH_H, color: 'amber' });
      }
    }
    texts.push(...row.texts);
    y += ROW_H;
  }
  return { w: SHOP_PANEL.w, h: SHOP_PANEL.h, rows, texts, rowH: ROW_H,
    band: { x: PAD - 6, y: 8, w: SHOP_PANEL.w - (PAD - 6) * 2 } };
}

export { ROW_H as SHOP_ROW_H, GLYPH_H as SHOP_GLYPH_H };

// ---- SHOP-2: the TITLES screen (opened from the Profile view) -----------------------------------------

/** TITLES panel: narrower than the shop, one row per title plus the level-title DEFAULT row. */
export const TITLES_PANEL = Object.freeze({ w: 300 });

/**
 * The TITLES screen as one ordered list of rows, the same single-list rule as the shop.
 *
 * Rows: the BANK head; a DEFAULT row that names the level title ("LEVEL: PACKET JOCKEY") and puts the slot
 * back to DEFAULT; then one row per catalogue title. States are spelled out: EQUIPPED, EQUIP, a price,
 * ACHIEVEMENT (an achievement title not earned yet) or LVL n. Selecting EQUIPPED returns to DEFAULT, as
 * in the shop (SHOP-3).
 *
 * @param {{profile?:Object, levels?:Object}} o
 * @returns {{w:number,h:number,rows:Array,texts:Array,rowH:number,band:{x:number,y:number,w:number},bankText:string,firstSelectable:number}}
 */
export function titlesLayout(o = {}) {
  const profile = o.profile || {};
  const equipped = (profile.equipped && typeof profile.equipped === 'object') ? profile.equipped : {};
  const bank = Number.isFinite(profile.bank) ? profile.bank : 0;
  const table = loadLevelTable(o.levels);
  const level = levelForXp(Number(profile.xp) || 0, table);
  const entry = table.levels.find((e) => e.level === level) || { title: '' };
  const rows = [];
  const texts = [];
  const bankText = `BANK ${bank}`;
  rows.push({ kind: 'head', key: 'head', right: bankText });

  const items = SHOP_ITEMS.filter((i) => i && i.slot === 'title');
  const anyEquipped = items.some((it) => equipped.title === it.id || equipped.title === it.value);
  rows.push({
    kind: 'default', key: 'title-default', id: 'default', label: `LEVEL: ${upper(entry.title)}`,
    state: anyEquipped ? 'EQUIP' : 'EQUIPPED', equipped: !anyEquipped, disabled: false,
  });
  for (const it of items) {
    const owned = isOwned(profile, it.id);
    const isEquipped = equipped.title === it.id || equipped.title === it.value;
    const locked = !owned && it.grant !== 'achievement' && level < (it.unlockLevel || 1);
    let state;
    if (isEquipped) state = 'EQUIPPED';
    else if (owned) state = 'EQUIP';
    else if (it.grant === 'achievement') state = 'ACHIEVEMENT';
    else if (locked) state = `LVL ${it.unlockLevel}`;
    else state = String(it.price);
    const buyable = !owned && it.price > 0 && !locked && bank >= it.price;
    rows.push({
      kind: 'item', key: `title-${it.id}`, id: it.id, label: upper(it.name), state, owned, equipped: isEquipped,
      locked, price: it.price, disabled: !isEquipped && !owned && !buyable,
    });
  }

  let y = 8;
  let firstSelectable = -1;
  rows.forEach((r, i) => {
    r.y = y;
    r.index = i;
    if (r.kind === 'head') {
      const bw = measureText(r.right);
      r.texts = [{ key: 'head-right', text: r.right, x: TITLES_PANEL.w - PAD - bw, y, w: bw, h: GLYPH_H, color: 'amber' }];
    } else {
      if (firstSelectable < 0) firstSelectable = i;
      const rw = measureText(r.state);
      r.texts = [
        { key: `${r.key}-label`, text: r.label, x: PAD + 6, y, w: measureText(r.label), h: GLYPH_H, color: r.equipped ? 'lime' : 'text' },
        { key: `${r.key}-right`, text: r.state, x: TITLES_PANEL.w - PAD - 6 - rw, y, w: rw, h: GLYPH_H,
          color: r.equipped ? 'cyan' : (r.owned ? 'lime' : 'amber') },
      ];
    }
    for (const t of r.texts) texts.push(t);
    y += ROW_H;
  });
  return {
    w: TITLES_PANEL.w,
    h: y + 30,
    rows,
    texts,
    rowH: ROW_H,
    band: { x: PAD - 6, y: 8, w: TITLES_PANEL.w - (PAD - 6) * 2 },
    bankText,
    firstSelectable,
  };
}

/**
 * MenuList items for the TITLES screen: the same rows in the same order. The view attaches onSelect.
 * @param {Object} layout @returns {Array<Object>}
 */
export function titlesMenuItems(layout) {
  return layout.rows.map((r) => {
    if (r.kind === 'head') return { kind: 'static', label: '', rowKind: 'head', disabled: true };
    return { kind: 'action', rowKind: r.kind, id: r.id, label: r.label, sub: r.state, disabled: r.disabled, onSelect: null };
  });
}


/** Only referenced after real five-in-one-flight Gym mastery. No fallback
 * teaser exists in the normal Shop or permanent upgrades page. */
export function gymSetupLayout(o = {}) {
  const profile = o.profile || {};
  const bank = Number.isSafeInteger(profile.bank) ? profile.bank : 0;
  const setup = gymSetupForProfile(profile);
  const fields = [
    {id:'gapPx',label:'WALL GAP'},
    {id:'wallSpeedPxS',label:'WALL START SPEED'},
    {id:'launchHeightPx',label:'LAUNCH HEIGHT'},
    {id:'launchSpeedPxS',label:'START VELOCITY'},
    {id:'launchRisePxS',label:'UPWARD VELOCITY'},
  ];
  const rows = [
    {kind:'head',key:'head',label:'',right:'BANK '+bank},
    {kind:'gymSetupBack',key:'gymSetupBack',label:'← BACK TO UPGRADES'},
    {kind:'header',key:'gymSetupHead',label:'BSOD GYM / CUSTOM LAUNCH'},
    ...fields.map(f=>({kind:'gymSetupChoice',key:f.id,id:f.id,label:f.label,
      state:String(setup[f.id]),choices:GYM_SETUP_OPTIONS[f.id]})),
    {kind:'gymSetupStart',key:'gymSetupStart',label:'START PRACTICE'},
    {kind:'static',key:'gymSetupNote',label:'REAL PHYSICS / FORWARD-ONLY WALL'},
  ];
  return { w:SHOP_PANEL.w,h:SHOP_PANEL.h,rows,rowH:ROW_H,
    band:{x:PAD-6,y:8,w:SHOP_PANEL.w-(PAD-6)*2} };
}/**
 * OWNER: UI engineer.
 * UI sounds through the AudioSynth contract (silent with the stub; never throws).
 */
import { REG } from '../constants.js';

/**
 * @param {Phaser.Scene|Phaser.Game} sceneOrGame
 * @param {'uiMove'|'uiSelect'|'uiBack'|'powerup'|'combo'|'trick'|'landPerfect'|string} name
 * @param {{pitch?:number, volume?:number}} [opts]
 * @returns {void}
 */
export function uiSfx(sceneOrGame, name, opts) {
  try {
    const game = sceneOrGame.game || sceneOrGame;
    const audio = game.registry.get(REG.AUDIO);
    if (audio) audio.playSfx(name, opts);
  } catch (e) {
    /* audio must never break UI */
  }
}/** Isolated in-game Music Lab six-role audition mixer.
 * Pointer + keyboard/gamepad controls. All values exist only in the
 * SoundLabView's ephemeral sandbox director, never persisted to the game.
 */
import Phaser from 'phaser';
import {Panel} from './Panel.js';
import {Button} from './Button.js';
import {NeonText} from './Neon.js';
import {LAB_STEMS,LAB_MIX_PRESETS,labGainFor} from '../systems/music/LabStemMix.js';

export class StemMixerView {
  constructor(scene,theme,{lab,onClose}){
    this.scene=scene;this.theme=theme;this.labView=lab;this.onClose=onClose;
    this.alive=true;this.selected=0;
    this.panel=new Panel(scene,theme,{x:6,y:7,w:468,h:253,
      title:'STEM MIXER // LAB SANDBOX ONLY',color:'cyan',fillAlpha:1})
      .setDepth(560);
    const shield=new Phaser.GameObjects.Zone(scene,0,0,468,253)
      .setOrigin(0,0).setInteractive();
    this.panel.add(shield);
    this.panel.add(new NeonText(scene,theme,12,25,
      '5 INSTRUMENT STEMS + BIOME MELODY / NOTES = PLAYHEAD',
      {color:'cyan',outline:'none'}));
    this.panel.add(new NeonText(scene,theme,12,37,
      'SOLO IS TEMPORARY. BOOST MAY INCREASE MIX LOUDNESS.',
      {color:'text',outline:'none'}).setAlpha(.72));
    this.roleLabels=[];
    this.rows=[];
    for(let i=0;i<LAB_STEMS.length;i++){
      const role=LAB_STEMS[i],y=54+i*25;
      const name=new NeonText(scene,theme,12,y+4,role.toUpperCase(),
        {color:'lime',outline:'none'});
      this.panel.add(name);this.roleLabels.push(name);
      const create=(x,w,label,action,color='cyan')=>new Button(scene,theme,{
        x,y,w,h:18,label,color,parent:this.panel,
        onClick:()=>{this.selected=i;action();this.refresh();},
      });
      const solo=create(87,47,'SOLO',()=>this.toggleSolo(role),'magenta');
      const buttons=LAB_MIX_PRESETS.map((preset,j)=>
        create([139,197,255,320][j],[53,53,60,60][j],
          ['MUTE','DUCK','1.0x','BOOST'][j],
          ()=>this.setLevel(role,preset.gain),
          ['magenta','amber','cyan','lime'][j]));
      const level=new NeonText(scene,theme,386,y+4,'1.00x',
        {color:'amber',outline:'none'});
      this.panel.add(level);
      this.rows.push({solo,buttons,level});
    }
    this.status=new NeonText(scene,theme,12,209,'',
      {color:'cyan',outline:'none'});this.panel.add(this.status);
    this.hint=new NeonText(scene,theme,12,222,
      'UP/DOWN STEM  LEFT/RIGHT LEVEL  CONFIRM SOLO',
      {color:'text',outline:'none'});this.panel.add(this.hint);
    this.reset=new Button(scene,theme,{x:12,y:235,w:135,h:14,
      label:'RESET ALL LEVELS',color:'amber',parent:this.panel,
      onClick:()=>this.resetAll()});
    this.clearSolo=new Button(scene,theme,{x:152,y:235,w:91,h:14,
      label:'CLEAR SOLO',color:'cyan',parent:this.panel,
      onClick:()=>{this.labView._solo('ALL');this.refresh();}});
    this.back=new Button(scene,theme,{x:390,y:233,w:68,h:16,
      label:'BACK',color:'magenta',parent:this.panel,onClick:()=>this.close()});
    this.refresh();
  }

  setLevel(role,gain){
    if(!LAB_STEMS.includes(role)||!LAB_MIX_PRESETS.some(p=>p.gain===gain))return;
    this.labView._setStemLevel(role,gain);
    this.refresh();
  }
  toggleSolo(role){
    if(!LAB_STEMS.includes(role))return;
    this.labView._solo(this.labView.solo===role.toUpperCase()?
      'ALL':role.toUpperCase());
    this.refresh();
  }
  resetAll(){
    this.labView._resetStemMix();
    this.refresh();
  }
  refresh(){
    if(!this.alive)return;
    const lab=this.labView;
    const levels=lab.mixLevels||{};
    for(let i=0;i<LAB_STEMS.length;i++){
      const role=LAB_STEMS[i],row=this.rows[i];
      const own=levels[role]??1;
      const audible=labGainFor(role,levels,lab.solo);
      row.solo.setLabel(lab.solo===role.toUpperCase()?'SOLO*':'SOLO');
      row.level.setText(`${audible.toFixed(2)}x`);
      row.level.setAlpha(audible===0?.43:1);
      this.roleLabels[i].setAlpha(i===this.selected?1:.72);
      for(let j=0;j<row.buttons.length;j++)
        row.buttons[j].setLabel(own===LAB_MIX_PRESETS[j].gain?
          ['MUTE*','DUCK*','1.0x*','BOOST*'][j]:
          ['MUTE','DUCK','1.0x','BOOST'][j]);
    }
    const selected=LAB_STEMS[this.selected];
    this.status.setText(`${selected.toUpperCase()} ${(levels[selected]??1).toFixed(2)}x`+
      `  /  SOLO ${lab.solo}  /  UNSAVED LAB MIX`);
  }
  handleAction(action){
    if(action==='cancel'){this.close();return true;}
    if(action==='up'||action==='down'){
      this.selected=(this.selected+(action==='down'?1:-1)+LAB_STEMS.length)%LAB_STEMS.length;
      this.refresh();return true;
    }
    if(action==='left'||action==='right'){
      const role=LAB_STEMS[this.selected];
      const level=this.labView.mixLevels[role]??1;
      const index=LAB_MIX_PRESETS.findIndex(p=>p.gain===level);
      const next=Math.max(0,Math.min(LAB_MIX_PRESETS.length-1,
        (index<0?2:index)+(action==='left'?-1:1)));
      this.setLevel(role,LAB_MIX_PRESETS[next].gain);return true;
    }
    if(action==='confirm'||action==='alt'){
      this.toggleSolo(LAB_STEMS[this.selected]);return true;
    }
    return true;
  }
  close(){if(this.alive)this.onClose();}
  destroy(){if(!this.alive)return;this.alive=false;this.panel.destroy();this.panel=null;}
}/**
 * OWNER: UI engineer.
 * Per-scene palette binder. Every coloured UI element registers a callback with `bind()`; when the player swaps
 * the colour-blind palette (EVT.SETTINGS_CHANGED) all callbacks are re-run, so the swap is visible live.
 * The listener on game.events is removed on scene shutdown.
 *
 * Audit SHOP-5: the equipped UI theme (profile.equipped.theme) is laid over the palette here, so every
 * menu, panel and HUD painter that reads `pal`/`css`/`color()` is themed. Cosmetics.themedUiPalette owns
 * the rules: only UI accent keys move, `danger` never does, and a colourblind palette refuses the theme.
 * Call refresh() after the profile's theme changes (ShopView does).
 */
import { EVT } from '../events.js';
import { REG, PALETTE_KEYS } from '../constants.js';
import { getPaletteCss } from './Palette.js';
import { themedUiPalette } from '../systems/Cosmetics.js';

/**
 * The active UI palette, themed, as {css, pal}.
 * @param {Phaser.Game} game @returns {{css:Object<string,string>, pal:Object<string,number>}}
 */
export function themedPalette(game) {
  const base = getPaletteCss(game);
  const reg = game.registry;
  const settings = (reg && reg.get(REG.SETTINGS)) || {};
  const profile = (reg && reg.get(REG.PROFILE)) || null;
  const css = themedUiPalette(base, profile, { colorblind: settings.palette === 'colorblind' });
  /** @type {Object<string,number>} */
  const pal = {};
  for (const k of PALETTE_KEYS) pal[k] = parseInt(css[k].slice(1), 16);
  return { css, pal };
}

export class Theme {
  /** @param {Phaser.Scene} scene */
  constructor(scene) {
    this.scene = scene;
    this.game = scene.game;
    const t = themedPalette(this.game);
    /** @type {Object<string,number>} */
    this.pal = t.pal;
    /** @type {Object<string,string>} */
    this.css = t.css;
    /** @type {Set<function(Object<string,number>):void>} */
    this.subs = new Set();
    this._onChange = (p) => {
      if (!p || p.key === 'palette') this.refresh();
    };
    this.game.events.on(EVT.SETTINGS_CHANGED, this._onChange);
    this._destroy = () => this.destroy();
    scene.events.once('shutdown', this._destroy);
    scene.events.once('destroy', this._destroy);
  }

  /**
   * @param {string} key palette key, e.g. 'cyan'
   * @returns {number}
   */
  color(key) {
    return this.pal[key] !== undefined ? this.pal[key] : 0xffffff;
  }

  /**
   * Register a palette-dependent painter; it runs immediately and after each palette change.
   * @param {function(Object<string,number>, Theme):void} fn
   * @returns {function():void} unbind
   */
  bind(fn) {
    this.subs.add(fn);
    fn(this.pal, this);
    return () => this.subs.delete(fn);
  }

  /** Re-read the palette and repaint everything bound. @returns {void} */
  refresh() {
    const t = themedPalette(this.game);
    this.pal = t.pal;
    this.css = t.css;
    for (const fn of [...this.subs]) {
      try {
        fn(this.pal, this);
      } catch (e) {
        this.subs.delete(fn); // painter belongs to a destroyed object
      }
    }
  }

  /** @returns {void} */
  destroy() {
    if (!this.game) return;
    this.game.events.off(EVT.SETTINGS_CHANGED, this._onChange);
    this.scene.events.off('shutdown', this._destroy);
    this.scene.events.off('destroy', this._destroy);
    this.subs.clear();
    this.game = null;
  }
}/**
 * The base View (a centred panel with a BACK button), in its own module so views outside Views.js
 * (GhostFavoritesView) can extend it without importing the whole view catalogue. Views.js re-exports it.
 */
import { GAME_WIDTH, GAME_HEIGHT } from '../constants.js';
import { Panel } from './Panel.js';
import { Keycaps } from './ViewChrome.js';
import { Button } from './Button.js';
import { uiSfx } from './Sound.js';
import { transitionIn, transitionOut } from './Motion.js';
import { measureText } from './PixelFont.js';

/**
 * Base: centred panel with a BACK button.
 *
 * Motion: the panel opens with Motion.transitionIn (a CRT zip: a line draws across, the panel unfolds from
 * it) and closes with Motion.transitionOut (a ghost frame collapses where the panel was). Both collapse to a
 * short fade under reduce motion. The panel's geometry is never animated away from its layout outside the
 * open tween, and destroy() stays synchronous (the ghost is a separate, self-destroying graphic), so view
 * navigation and teardown behave exactly as before for every caller and test. The host scene owns the
 * dim layer behind the panel (Motion.openDim/closeDim).
 */
export class View {
  /**
   * @param {Phaser.Scene} scene
   * @param {import('./Theme.js').Theme} theme
   * @param {{w:number,h:number,title:string,color?:string,onClose:function():void,y?:number,backLabel?:string,
   *          hints?:Array<{keys?:string[],key?:string,label?:string}>, hintsAt?:'tab'|'foot'}} o
   *   `hints` draws a keycap row: in the title-tab line (right-aligned, the default) or at the panel foot,
   *   left of BACK. A tab-row hint that would run into the title tab is dropped, never overlapped.
   */
  constructor(scene, theme, o) {
    this.scene = scene;
    this.theme = theme;
    this.onClose = o.onClose;
    this.alive = true;
    const x = Math.round((GAME_WIDTH - o.w) / 2);
    const y = o.y !== undefined ? o.y : Math.round((GAME_HEIGHT - o.h) / 2);
    this.frameColorKey = o.color || 'cyan';
    this.panel = new Panel(scene, theme, { x, y, w: o.w, h: o.h, title: o.title, color: this.frameColorKey, fillAlpha: 1 });
    this.panel.setDepth(500);
    this.w = o.w;
    this.h = o.h;
    this.back = new Button(scene, theme, {
      x: o.w - 76, y: o.h - 22, w: 68, h: 16, label: o.backLabel || 'BACK', color: 'magenta', onClick: () => this.close(),
    });
    this.panel.add(this.back);
    this.hintRow = null;
    if (o.hints && o.hints.length) {
      const foot = o.hintsAt === 'foot';
      const caps = new Keycaps(scene, theme, {
        x: foot ? 12 : o.w - 10, y: foot ? o.h - 19 : 2, items: o.hints, align: foot ? 'left' : 'right', color: this.frameColorKey,
      });
      // the tab is the title plus 16 px padding, a 10 px slant and the three data ticks (~26 px)
      const tabEnd = measureText(String(o.title || '')) + 16 + 10 + 26;
      if (!foot && caps.x < tabEnd) caps.destroy();
      else { this.panel.add(caps); this.hintRow = caps; }
    }
    transitionIn(scene, this.panel, { w: o.w, h: o.h, color: theme.color(this.frameColorKey) });
  }

  close() {
    uiSfx(this.scene, 'uiBack');
    if (this.alive) this.onClose();
  }

  handleAction(action) {
    if (action === 'cancel') this.close();
    return true;
  }

  destroy() {
    this.alive = false;
    if (this.panel) {
      // A hidden panel (Settings while Manage Sound is open over it) leaves no ghost: it was not on screen.
      if (this.panel.visible !== false && this.panel.scene) {
        transitionOut(this.scene, {
          x: this.panel.x, y: this.panel.y, w: this.w, h: this.h,
          color: this.theme.color(this.frameColorKey), depth: 501,
        });
      }
      this.panel.destroy();
    }
    this.panel = null;
  }
}/**
 * OWNER: UI engineer.
 * Shared chrome for the modal sub-views (Views.js and friends): keycap hint rows, section dividers, glowing
 * progress bars, focus rings, state chips and the staggered row reveal. Everything paints from palette keys
 * (so the colour-blind palette and equipped UI themes apply) and nothing here changes a view's geometry:
 * helpers draw INTO space a view already owns, or on their own Graphics layered under/over the content.
 *
 * Paint helpers are plain functions over a Graphics so a view can fold them into one repaint; the two
 * widgets (Keycaps, SectionHeader) are Containers that bind to the theme themselves.
 */
import Phaser from 'phaser';
import { NeonText, strokeRectPx, glowRectPx } from './Neon.js';
import { measureText } from './PixelFont.js';
import { isReducedMotion, tweenProgress, Ease } from './Motion.js';

// ------------------------------------------------------------------ pixel patterns

/** 5x6 padlock. */
export const LOCK_GLYPH = Object.freeze(['.XXX.', 'X...X', 'X...X', 'XXXXX', 'XXXXX', 'XXXXX']);
/** 5x5 shard (the currency's diamond). */
export const SHARD_GLYPH = Object.freeze(['..X..', '.XXX.', 'XXXXX', '.XXX.', '..X..']);
/** 5x4 tick. */
export const CHECK_GLYPH = Object.freeze(['....X', 'X..X.', '.XX..', '..X..']);

/**
 * Paint a small bitmap given as rows of 'X' / '.', one fillRect per run.
 * @param {Phaser.GameObjects.Graphics} g @param {number} x @param {number} y
 * @param {readonly string[]} rows @param {number} color @param {number} [alpha=1]
 */
export function paintPattern(g, x, y, rows, color, alpha = 1) {
  g.fillStyle(color, alpha);
  rows.forEach((row, r) => {
    let c = 0;
    while (c < row.length) {
      if (row[c] !== 'X') { c += 1; continue; }
      let e = c;
      while (e < row.length && row[e] === 'X') e += 1;
      g.fillRect(x + c, y + r, e - c, 1);
      c = e;
    }
  });
}

// ------------------------------------------------------------------ podium

/**
 * Palette key for a leaderboard rank (0-based): gold ~ amber, silver ~ text, bronze ~ magenta. Shape carries
 * the rank too (the numbered chip), so the colour-blind palette never has to tell them apart by hue alone.
 * @param {number} i @returns {'amber'|'text'|'magenta'|null} null below the podium
 */
export function podiumKey(i) {
  return i === 0 ? 'amber' : i === 1 ? 'text' : i === 2 ? 'magenta' : null;
}

// ------------------------------------------------------------------ rules, bars, rings, chips

/**
 * A horizontal rule that fades out to the right, with a bright pip at its start: the section divider.
 * @param {Phaser.GameObjects.Graphics} g @param {number} x0 @param {number} x1 @param {number} y
 * @param {number} color @param {number} [alpha=0.7]
 */
export function paintRule(g, x0, x1, y, color, alpha = 0.7) {
  const w = x1 - x0;
  if (w <= 2) return;
  const steps = 8;
  const sw = Math.ceil(w / steps);
  for (let i = 0; i < steps; i++) {
    g.fillStyle(color, alpha * (1 - i / (steps * 1.25)) * 0.8);
    g.fillRect(x0 + i * sw, y, Math.min(sw, x1 - (x0 + i * sw)), 1);
  }
  g.fillStyle(color, 1);
  g.fillRect(x0, y - 1, 2, 3);
}

/**
 * A glowing progress bar: dark well, outer glow, a segmented fill with a bright top half and a hot leading
 * edge, and a crisp border. `ratio` is 0..1.
 * @param {Phaser.GameObjects.Graphics} g @param {Object<string,number>} pal
 * @param {{x:number,y:number,w:number,h:number}} r @param {number} ratio @param {string} colorKey
 * @param {{segments?:number, glow?:number}} [o]
 */
export function paintGlowBar(g, pal, r, ratio, colorKey, o = {}) {
  const c = pal[colorKey];
  const { x, y, w, h } = r;
  const k = Math.min(1, Math.max(0, Number(ratio) || 0));
  glowRectPx(g, x, y, w, h, c, o.glow === undefined ? 0.8 : o.glow);
  g.fillStyle(pal.bg, 1);
  g.fillRect(x, y, w, h);
  const iw = w - 2;
  const fw = Math.round(iw * k);
  if (fw > 0) {
    g.fillStyle(c, 0.6);
    g.fillRect(x + 1, y + 1, fw, h - 2);
    g.fillStyle(c, 1);
    g.fillRect(x + 1, y + 1, fw, Math.max(1, Math.ceil((h - 2) / 2)));
    if (fw > 2) {
      g.fillStyle(pal.text, 0.9);
      g.fillRect(x + fw, y + 1, 1, h - 2);
    }
  }
  const segs = o.segments === undefined ? 10 : o.segments;
  if (segs > 1) {
    g.fillStyle(pal.bg, 0.55);
    for (let i = 1; i < segs; i++) g.fillRect(x + 1 + Math.round((iw * i) / segs), y + 1, 1, h - 2);
  }
  strokeRectPx(g, x, y, w, h, c, 0.9);
}

/**
 * Focus ring for a button/row. The FIRST stroke is the same strokeRect the views always drew (tests and
 * layouts read it); the glow halo and bright corners are extra.
 * @param {Phaser.GameObjects.Graphics} g @param {Object<string,number>} pal
 * @param {{x:number,y:number,w:number,h:number}} r @param {string} colorKey
 */
export function paintFocusRing(g, pal, r, colorKey) {
  const c = pal[colorKey];
  g.lineStyle(1, c, 1);
  g.strokeRect(r.x - 1.5, r.y - 1.5, r.w + 3, r.h + 3);
  strokeRectPx(g, r.x - 4, r.y - 4, r.w + 8, r.h + 8, c, 0.14);
  strokeRectPx(g, r.x - 3, r.y - 3, r.w + 6, r.h + 6, c, 0.3);
  g.fillStyle(pal.text, 0.95);
  for (const [cx, cy] of [[r.x - 2, r.y - 2], [r.x + r.w + 1, r.y - 2], [r.x - 2, r.y + r.h + 1], [r.x + r.w + 1, r.y + r.h + 1]]) g.fillRect(cx, cy, 1, 1);
}

/**
 * A state chip behind a right-aligned state word: 'solid' (filled: equipped / active), 'outline' (owned),
 * 'bright' (can be bought now: outline + faint fill) or 'dim' (locked). `glyph` ('lock' | 'shard') draws a
 * small icon at its left; the chip box grows to the left to make room, and the returned box says where it
 * landed.
 * @param {Phaser.GameObjects.Graphics} g @param {Object<string,number>} pal
 * @param {{right:number, y:number, textW:number, h?:number, colorKey:string, mode:'solid'|'outline'|'bright'|'dim', glyph?:'lock'|'shard'}} o
 * @returns {{x:number,y:number,w:number,h:number}}
 */
export function paintStateChip(g, pal, o) {
  const h = o.h || 9;
  const lockW = o.glyph ? 8 : 0;
  const w = o.textW + 6 + lockW;
  const x = o.right - w;
  const c = pal[o.colorKey];
  const a = o.mode === 'solid' ? 0.9 : o.mode === 'bright' ? 0.9 : o.mode === 'outline' ? 0.55 : 0.3;
  if (o.mode === 'solid') {
    g.fillStyle(c, 0.28);
    g.fillRect(x, o.y, w, h);
  } else if (o.mode === 'bright') {
    g.fillStyle(c, 0.12);
    g.fillRect(x, o.y, w, h);
  }
  // pixel-rounded border: the four corners are left open
  g.fillStyle(c, a);
  g.fillRect(x + 1, o.y, w - 2, 1);
  g.fillRect(x + 1, o.y + h - 1, w - 2, 1);
  g.fillRect(x, o.y + 1, 1, h - 2);
  g.fillRect(x + w - 1, o.y + 1, 1, h - 2);
  if (o.glyph === 'lock') paintPattern(g, x + 3, o.y + 1, LOCK_GLYPH, pal.text, 0.55);
  else if (o.glyph === 'shard') paintPattern(g, x + 3, o.y + 2, SHARD_GLYPH, c, 1);
  return { x, y: o.y, w, h };
}

// ------------------------------------------------------------------ widgets

const CAP_H = 11;

/**
 * A row of keycap hints: `[ENTER] CONFIRM   [← →] [N] SWITCH BOARD`. Each item is {keys:[...]|key, label}.
 * `x` is the left edge, or the right edge with align:'right'. Paint only (no hit zones).
 * `summary` is the plain-text reading of the row (tests, screen readers); `totalW` its pixel width.
 */
export class Keycaps extends Phaser.GameObjects.Container {
  /**
   * @param {Phaser.Scene} scene @param {import('./Theme.js').Theme} theme
   * @param {{x:number,y:number,items:Array<{keys?:string[], key?:string, label?:string}>,
   *          align?:'left'|'right', color?:string, parent?:Phaser.GameObjects.Container}} o
   */
  constructor(scene, theme, o) {
    super(scene, 0, o.y);
    this.theme = theme;
    this.colorKey = o.color || 'cyan';
    this.caps = []; // {x,w}
    this.summary = '';
    const GAP_KEY = 2;
    const GAP_LABEL = 4;
    const GAP_ITEM = 9;
    let cx = 0;
    const labels = [];
    const keys = [];
    const items = (o.items || []).filter(Boolean);
    items.forEach((it, n) => {
      const ks = it.keys || (it.key ? [it.key] : []);
      ks.forEach((k, ki) => {
        const w = Math.max(11, measureText(k) + 9);
        this.caps.push({ x: cx, w });
        keys.push({ x: cx + Math.floor((w - measureText(k)) / 2), text: k });
        cx += w + (ki < ks.length - 1 ? GAP_KEY : 0);
      });
      if (it.label) {
        cx += GAP_LABEL;
        labels.push({ x: cx, text: it.label });
        cx += measureText(it.label);
      }
      if (n < items.length - 1) cx += GAP_ITEM;
      this.summary += (n ? '  ' : '') + ks.join(' / ') + (it.label ? ' ' + it.label : '');
    });
    this.totalW = cx;
    this.setX(Math.round(o.align === 'right' ? o.x - cx : o.x));
    this.g = new Phaser.GameObjects.Graphics(scene);
    this.add(this.g);
    for (const k of keys) this.add(new NeonText(scene, theme, k.x, 2, k.text, { color: 'text', outline: 'none' }));
    for (const l of labels) this.add(new NeonText(scene, theme, l.x, 2, l.text, { color: 'text', outline: 'none', alpha: 0.65 }));
    scene.add.existing(this);
    if (o.parent) o.parent.add(this);
    this._unbind = theme.bind((pal) => this._paint(pal));
  }

  _paint(pal) {
    const g = this.g;
    if (!g) return;
    g.clear();
    const c = pal[this.colorKey];
    for (const cap of this.caps) {
      const { x, w } = cap;
      g.fillStyle(pal.bgAlt, 1);
      g.fillRect(x, 0, w, CAP_H - 1);
      g.fillStyle(pal.text, 0.1);
      g.fillRect(x + 1, 1, w - 2, 3);
      // border with open corners, and a heavier bottom edge: the key's lip
      g.fillStyle(c, 0.6);
      g.fillRect(x + 1, 0, w - 2, 1);
      g.fillRect(x, 1, 1, CAP_H - 3);
      g.fillRect(x + w - 1, 1, 1, CAP_H - 3);
      g.fillStyle(c, 1);
      g.fillRect(x + 1, CAP_H - 2, w - 2, 1);
      g.fillStyle(pal.bg, 0.9);
      g.fillRect(x + 1, CAP_H - 1, w - 2, 1);
    }
  }

  destroy(fromScene) {
    if (this._unbind) this._unbind();
    this._unbind = null;
    this.g = null;
    super.destroy(fromScene);
  }
}

/**
 * Section header: label, then a fading rule to `w` (or to `ruleTo`, when something sits at the right).
 */
export class SectionHeader extends Phaser.GameObjects.Container {
  /**
   * @param {Phaser.Scene} scene @param {import('./Theme.js').Theme} theme
   * @param {{x:number,y:number,w:number,text:string,color?:string,ruleTo?:number, parent?:Phaser.GameObjects.Container}} o
   */
  constructor(scene, theme, o) {
    super(scene, o.x, o.y);
    this.theme = theme;
    this.colorKey = o.color || 'amber';
    this.w = o.w;
    this.ruleFrom = measureText(o.text) + 6;
    this.ruleTo = o.ruleTo === undefined ? o.w : o.ruleTo;
    this.g = new Phaser.GameObjects.Graphics(scene);
    this.add(this.g);
    this.label = new NeonText(scene, theme, 0, 0, o.text, { color: this.colorKey, outline: 'none' });
    this.add(this.label);
    scene.add.existing(this);
    if (o.parent) o.parent.add(this);
    this._unbind = theme.bind((pal) => {
      if (!this.g) return;
      this.g.clear();
      paintRule(this.g, this.ruleFrom, this.ruleTo, 4, pal[this.colorKey], 0.7);
    });
  }

  destroy(fromScene) {
    if (this._unbind) this._unbind();
    this._unbind = null;
    this.g = null;
    super.destroy(fromScene);
  }
}

// ------------------------------------------------------------------ staggered reveal

const hasTweens = (scene) => !!(scene && scene.tweens && typeof scene.tweens.addCounter === 'function');
const live = (o) => !!(o && o.scene);

/** Where a reveal starts (ms): after the panel's CRT zip has opened. */
export const REVEAL_START = 150;
/** Gap between consecutive rows (ms). */
export const REVEAL_STEP = 24;

/**
 * Fade groups of objects in one after another (alpha 0 -> its current value). Skipped under reduce motion
 * and on scenes with no tween manager, so the end state is always what a test or a reduced-motion player sees.
 * Only use it on objects nothing else re-alphas while the reveal runs.
 * @param {Phaser.Scene} scene @param {Array<Array<Phaser.GameObjects.GameObject>>} groups
 * @param {{start?:number, step?:number, duration?:number}} [o]
 * @returns {void}
 */
export function staggerAlpha(scene, groups, o = {}) {
  if (!hasTweens(scene) || isReducedMotion(scene)) return;
  const start = o.start === undefined ? REVEAL_START : o.start;
  const step = o.step === undefined ? REVEAL_STEP : o.step;
  groups.forEach((objs, i) => {
    const list = (objs || []).filter(live);
    if (!list.length) return;
    const base = list.map((ob) => ob.alpha);
    list.forEach((ob) => ob.setAlpha(0));
    tweenProgress(scene, {
      duration: o.duration || 150,
      delay: start + i * step,
      ease: Ease.outQuad,
      onUpdate: (p) => list.forEach((ob, k) => { if (live(ob)) ob.setAlpha(base[k] * p); }),
    });
  });
}

/**
 * Reveal a MenuList's rows with a short slide-in, top to bottom. Uses visibility and x (never alpha, which
 * MenuList.refresh owns), and restores both exactly at the end of each row's tween.
 * @param {Phaser.Scene} scene @param {{rows?:Array<Object>}} menu
 * @param {{start?:number, step?:number, slide?:number}} [o]
 * @returns {void}
 */
export function staggerMenuRows(scene, menu, o = {}) {
  if (!menu || !menu.rows || !hasTweens(scene) || isReducedMotion(scene)) return;
  const start = o.start === undefined ? REVEAL_START : o.start;
  const step = o.step === undefined ? REVEAL_STEP : o.step;
  const slide = o.slide === undefined ? 8 : o.slide;
  menu.rows.forEach((row, i) => {
    const parts = [row.label, row.value, row.sub, row.badge].filter(live);
    if (!parts.length) return;
    const bx = parts.map((p) => p.x);
    parts.forEach((p) => { p.setVisible(false); p.setX(p.x - slide); });
    let shown = false;
    tweenProgress(scene, {
      duration: 150,
      delay: start + Math.min(i, 14) * step,
      ease: Ease.outCubic,
      onUpdate: (p) => {
        parts.forEach((part, k) => {
          if (!live(part)) return;
          if (!shown) part.setVisible(true);
          part.setX(bx[k] - slide * (1 - p));
        });
        shown = true;
      },
    });
  });
}/**
 * OWNER: UI engineer.
 * Modal sub-screens shared by TitleScene and PauseScene: leaderboard, settings, seed entry, sharecode export/import.
 * A view is a Panel plus content; the host scene feeds it MenuInput actions via handleAction(). Each view calls
 * `onClose()` when the player backs out. destroy() removes everything it created (DOM boxes included).
 */
import Phaser from 'phaser';
import { REG, GAME_WIDTH, GAME_HEIGHT } from '../constants.js';
