/**
 * @typedef {Object} BitstreamBluffPayload
 * @property {'bsod'} hazardType
 * @property {number} points  immediate bonus (also emitted once via NEAR_MISS).
 * @property {number} x  world rider position on escaping BSOD danger band.
 * @property {number} y
 * @property {number} chain  successful bluffs without landing; >1 is Surfing the Void.
 * @property {boolean} surfing
 * @property {number} closestGapPx  minimum positive collision-edge separation.
 * @property {number} [canopyRecoveredMs]  bonus fuel restored only for enabled high-tier canopy loadouts.
 */

/**
 * @typedef {Object} BsodStatePayload
 * @property {boolean} active whether the physical chase is running.
 * @property {number|null} gapPx signed distance in px: sled Matter body's leftmost bounds.min.x minus the BSOD's rightmost/front collision edge X. Zero means contact. Null when inactive.
 * @property {number} wallSpeedPxS nonnegative world-X BSOD wall speed.
 * @property {number} worldTailwindPxS world-X air speed (0 in vacuum).
 * @property {number} sledVelocityXPxS signed world-X sled velocity, never scalar speed.
 * @property {number} relativeAirX worldTailwindPxS - sledVelocityXPxS, zero in vacuum.
 * @property {number} proximity01 normalized physical danger, from 0 to 1.
 * @property {number|null} timeToImpactMs instantaneous time to contact, null when nonclosing/indeterminate. Not a guaranteed death timer.
 * @property {number} atmosphereDensity aerodynamic coupling from 0 (vacuum) to 1.
 */

/**
 * @typedef {Object} LandingBoostPayload
 * @property {number} amountPxS  speed added, px/s.
 * @property {'perfect'|'good'} quality
 * @property {number} comboMult
 * @property {number} tricks  NUMBER of tricks banked by the landing (RunScene sends a count, not names).
 */

/**
 * @typedef {Object} NearMissPayload
 * @property {string} hazardType
 * @property {number} points
 * @property {number} x  world px.
 * @property {number} y  world px.
 */

/**
 * @typedef {Object} ShardCollectedPayload
 * @property {number} chain   current chain length.
 * @property {number} points  points awarded for this shard.
 * @property {number} total   cumulative shard POINTS this run (not a count; RunScene sends points).
 * @property {number} [count] additive: true number of shards collected this run (including this one).
 * @property {number} x  world px.
 * @property {number} y  world px.
 */

/**
 * @typedef {Object} MilestonePayload
 * @property {number} sector
 * @property {number} distanceM
 * @property {number} [points]  additive: bonus paid (ScoreManager.checkMilestones / milestoneBonus).
 */

/**
 * @typedef {Object} FlowChangedPayload
 * @property {number} flow          current flow multiplier (1..SCORING.flowMax).
 * @property {number} previous      flow before this change.
 * @property {'gain'|'halved'|'timeout'} reason  gain = clean landing after a flip / helicopter; halved = sloppy landing or a
 *   shield-absorbed hit; timeout = the flow timer expired and the bonus was halved (flow is still above 1; the timer restarted).
 * @property {number} timeoutFrac   remaining timeout 0..1 (1 right after a gain).
 * @property {number} best          best flow this run.
 */

/**
 * @typedef {Object} FlowLostPayload
 * @property {number} previous      flow that was lost (> 1).
 * @property {'crash'|'reset'|'timeout'} reason  crash = a real crash; reset = Shift; timeout = repeated timeouts halved the bonus
 *   below SCORING.flowClearBelow and flow returned to 1.
 */

/**
 * @typedef {Object} NewBestPayload
 * @property {number} distanceM
 * @property {number} previousBestM
 */

/**
 * @typedef {Object} TutorialHintPayload
 * @property {'push'|'hop'|'flip'|'land'|'tuck'|'boost'} id
 * @property {boolean} show
 */

/**
 * @typedef {Object} RunStartPayload
 * @property {string} runId        unique id for this run (e.g. `${Date.now()}-${seed}`).
 * @property {string} seed         seed string used for terrain + glitch schedule.
 * @property {string} dailyRuleId  id of the daily patch rule in effect (see DailyPatch), e.g. 'tuckBoost'.
 * @property {number} startedAt    epoch ms.
 * @property {boolean} [dailyOfficial] additive (decision 2): true only for the official Daily run, so the HUD can tell it from a typed daily-* practice run.
 */

/**
 * @typedef {Object} RunEndPayload
 * @property {import('./systems/SaveStore.js').RunRecord} record  the finished run (same object stored in REG.LAST_RECORD).
 * @property {{encountered:string[], completed:string[]}} [biomeVisits] additive (decision 3): biomes this run entered
 *           and rode through (BiomeDiscovery.detectBiomeVisits). Not part of the record or its ledger hash.
 */

/**
 * @typedef {Object} RunAbortPayload
 * @property {string} runId
 */

/**
 * @typedef {Object} CrashPayload
 * @property {'hazard'|'terrain'|'badLanding'|'chasm'|'bsod'} cause
 * @property {number} x           world px.
 * @property {number} y           world px.
 * @property {number} speedPxS    sled speed at impact, px/s.
 * @property {string} [hazardId]  hazard def id when cause==='hazard'.
 * @property {boolean} negated    true if a shield charge (Hashed Backup, or a biome shield pickup such as Heat Shield) absorbed it
 *           (run continues; no RUN_END; a POWERUP_EXPIRED 'consumed' follows).
 * @property {boolean} fatal    additive explicit discriminator: true exactly for a real run-ending death,
 *           false for a shield-negated crash. A Gym catch emits only GYM_ATTEMPT_RESET.
 * @property {string} runId    owning run identity, shared with subsequent RUN_END record.id;
 *           retries use a new runId. A fatal-music consumer may key its trigger to this.
 * Nothing else is added by the Readable Chaos pass: the killer name, hop verdict and Game Over line travel in the registry
 * (REG.LAST_CRASH, src/data/schemas.js `LastCrash`), never on this payload, the RunRecord or its ledger hash.
 */

/**
 * @typedef {Object} RespawnPayload
 * @property {'manual'|'backup'|'recover'} reason  manual = Shift; backup = Hashed Backup used; recover = automatic.
 * @property {number} x
 * @property {number} y
 * @property {number} comboPenalty   unique tricks dropped from the pending combo by this respawn (>=0).
 */

/**
 * @typedef {Object} LandingPayload
 * @property {'perfect'|'good'|'sloppy'|'crash'} quality  see LANDING_QUALITY.
 * @property {number} angleDeg      sled angle relative to ground slope at touchdown (0 = aligned), degrees.
 * @property {number} impactSpeedPxS  vertical-ish impact speed in px/s (speed component along ground normal).
 * @property {number} airtimeMs
 * @property {number} bonusPoints   perfect-landing bonus actually awarded (0 if not perfect).
 * @property {number} bankedPoints  trick points banked by this landing (after combo multiplier AND flow).
 * @property {boolean} hard         true if impact was hard enough to trigger screen shake / big thud.
 * @property {number} x
 * @property {number} y
 * @property {string} [comboName]   additive: display name of the tricks just banked ('' when none).
 * @property {number} [comboMult]   additive: combo multiplier applied to the bank.
 * @property {number} [flowUsed]    additive: flow multiplier applied to the bank (after this landing's gain).
 * @property {boolean} [midSpin]    additive: true when an unfinished helicopter spin cost the landing a grade.
 */

/**
 * @typedef {Object} TrickPayload
 * @property {'backflip'|'frontflip'|'helicopterCCW'|'helicopterCW'|'corkscrew'|'airBrake'|'parachute'} type
 * @property {number} count        completed repetitions inside this event (e.g. 2 for a double flip).
 * @property {number} value        provisional (unbanked) points for this trick, before combo multiplier.
 * @property {boolean} isNew       true if this trick type is new in the current combo (raised the multiplier).
 * @property {number} airtimeMs    airtime so far.
 */

/**
 * @typedef {Object} ComboChangedPayload
 * @property {number} multiplier  current combo multiplier (starts 1, +0.25 per unique trick).
 * @property {string[]} tricks    unique trick types in the pending combo, in order performed.
 * @property {number} pendingPoints  unbanked trick points (before multiplier).
 * @property {'trick'|'landing'|'crash'|'reset'} reason
 */

/**
 * @typedef {Object} ScoreChangedPayload
 * @property {number} total          total score (integer, never negative).
 * @property {number} distancePoints
 * @property {number} trickPoints    banked trick points (incl. perfect-landing bonuses).
 * @property {number} delta          change since the previous SCORE_CHANGED (may be negative).
 */

/**
 * @typedef {Object} DistanceChangedPayload
 * @property {number} meters  furthest distance reached this run, integer metres.
 */

/**
 * @typedef {Object} PowerUpCollectedPayload
 * @property {string} id         power-up def id (src/data/powerups): 'clockPulse' | 'packetBurst' | 'hashedBackup' and, since B1-B4, every biome pickup id.
 * @property {number} durationMs  0 for instant/charge based (hashedBackup).
 * @property {number} charges     remaining charges (hashedBackup), else 0.
 */

/**
 * @typedef {Object} PowerUpExpiredPayload
 * @property {string} id         power-up def id (see PowerUpCollectedPayload).
 * @property {'timeout'|'consumed'|'respawn'|'replaced'} reason  timeout = ran out; consumed = a shield charge was spent
 *           (id = the pickup that granted it); respawn = the effect ended on a manual respawn (Shift); replaced (additive, B3/B4)
 *           = a different glide / stabilize pickup took over the single slot (id = the one that was replaced).
 */

/**
 * @typedef {Object} HazardHitPayload
 * @property {string} hazardId   hazard def id (src/data/hazards).
 * @property {'crash'|'slow'|'scramble'|'blind'|'gust'} effect  blind / gust are additive (B0, HazardDef.onHit.effect).
 * @property {number} durationMs  0 for crash and gust; effect length otherwise.
 * @property {number} x
 * @property {number} y
 */

/**
 * @typedef {Object} EffectEndPayload
 * @property {'slow'|'scramble'} effect
 */

/**
 * @typedef {Object} ZonePayload
 * @property {'highBandwidth'|'compression'|'wirelessBridge'} modId  terrain mod id (src/data/terrainMods).
 * @property {number} x0 zone start, world px.
 * @property {number} x1 zone end, world px.
 */

/**
 * @typedef {Object} GlitchStartPayload
 * @property {string} id           unique per glitch within a run, e.g. 'g12'.
 * @property {'rgbSplit'|'scanlineWobble'|'stutter'|'dropout'|'static'} kind  (GLITCH.kinds)
 * @property {number} durationMs   50-200 ms typically.
 * @property {number} intensity    0..1.
 */

/**
 * @typedef {Object} GlitchEndPayload
 * @property {string} id
 */

/**
 * @typedef {Object} PausePayload
 * @property {number} runTimeMs  run time excluding paused time.
 */

/**
 * @typedef {Object} SettingsChangedPayload
 * @property {string} key      settings key that changed, e.g. 'screenShake'.
 * @property {*} value         new value.
 * @property {import('./systems/SaveStore.js').Settings} settings  full settings after change.
 */

/**
 * @typedef {Object} InputActionPayload
 * @property {'hop'|'reset'|'pause'|'confirm'|'cancel'|'up'|'down'|'left'|'right'|'airBrake'|'parachute'|'anyKey'} action
 * @property {boolean} pressed  true on press, false on release.
 * @property {'keyboard'|'gamepad'|'touch'} source
 *//**
 * Game boot + Phaser config. FOUNDATION-OWNED. Public signatures are a contract - do not change without
 * updating src/ARCHITECTURE.md.
 */
import Phaser from 'phaser';
import { GAME_WIDTH, GAME_HEIGHT, TARGET_FPS } from './constants.js';
import { PreloadScene } from './scenes/PreloadScene.js';
import { TitleScene } from './scenes/TitleScene.js';
import { RunScene } from './scenes/RunScene.js';
import { UIScene } from './scenes/UIScene.js';
import { PauseScene } from './scenes/PauseScene.js';
import { GameOverScene } from './scenes/GameOverScene.js';
import { GlitchPipeline, GLITCH_PIPELINE_KEY } from './shaders/GlitchPipeline.js';

/** @type {Phaser.Types.Core.GameConfig} */
export const config = {
  type: Phaser.WEBGL, // WebGL mandatory (design doc section 3); no canvas fallback
  parent: 'game-container',
  width: GAME_WIDTH,
  height: GAME_HEIGHT,
  backgroundColor: '#05060f',
  pixelArt: true,
  roundPixels: true,
  powerPreference: 'high-performance',
  scale: { mode: Phaser.Scale.FIT, autoCenter: Phaser.Scale.CENTER_BOTH },
  fps: { target: TARGET_FPS, forceSetTimeOut: false }, // no fps.limit: Phaser's limiter drops early rAF frames and stutters
  input: { gamepad: true },
  physics: {
    default: 'matter',
    matter: {
      gravity: { x: 0, y: 0.9 }, // 900 px/s^2 (scale 0.001 -> px/s^2 / 1000); see ARCHITECTURE.md section 7
      autoUpdate: false, // RunScene steps the world manually in <= 8 ms sub-steps (PhysicsTuner.stepWorld)
      debug: false,
    },
  },
  // Order only matters for the first scene; the rest are started by key.
  scene: [PreloadScene, TitleScene, RunScene, UIScene, PauseScene, GameOverScene],
  callbacks: {
    postBoot: (game) => {
      game.renderer.pipelines.addPostPipeline(GLITCH_PIPELINE_KEY, GlitchPipeline);
    },
  },
};

export const game = new Phaser.Game(config);
if (typeof window !== 'undefined') window.__bbGame = game; // handy for headless tests / debugging/**
 * FOUNDATION-OWNED glue. Public signatures are a contract - do not change without updating src/ARCHITECTURE.md.
 * Creates the long-lived services ONCE and shares them through game.registry (keys in constants.REG).
 */
import { REG } from './constants.js';
import { EVT } from './events.js';
import { loadContent } from './data/index.js';
import { SaveStore } from './systems/SaveStore.js';
import { GhostLibrary } from './systems/ghost/GhostLibrary.js';
import { InputRouter } from './systems/InputRouter.js';
import { AudioSynth } from './systems/AudioSynth.js';
import { createProgressionService } from './systems/ProgressionService.js';
import { createMissionsService } from './systems/MissionsService.js';
import { RULESET_KEY } from './systems/replay/evidenceCapture.js';

/**
 * Instantiate SaveStore, load settings, create InputRouter + AudioSynth, load content, set a default seed.
 * Called by PreloadScene.create() (UI engineer) before starting TitleScene. Idempotent.
 * @param {Phaser.Game} game
 * @returns {Promise<void>} resolves when SaveStore.init() finished.
 */
export async function createServices(game) {
  if (game.registry.get(REG.SAVE_STORE)) return;
  const saveStore = new SaveStore();
  await saveStore.init();
  // Issue #56: local ghost tapes per course (IndexedDB, memory fallback; never rejects).
  const ghosts = new GhostLibrary();
  await ghosts.init();
  game.registry.set(REG.GHOSTS, ghosts);
  const settings = saveStore.loadSettings();
  game.registry.set(REG.SAVE_STORE, saveStore);
  game.registry.set(REG.SETTINGS, settings);
  game.registry.set(REG.CONTENT, loadContent());
  // Replay evidence (#116): the committed ruleset of this build. Non-blocking; without it runs simply produce no evidence.
  // (dynamic import: runtimeRuleset.js uses Vite's import.meta.glob, like data/index.js, so Jest must not load it statically)
  import('./systems/replay/runtimeRuleset.js').then((m) => m.loadCurrentRuleset()).then((r) => game.registry.set(RULESET_KEY, r)).catch((e) => console.warn(`[replay-evidence] ruleset unavailable: ${e && e.message}`));
  game.registry.set(REG.INPUT, new InputRouter(game));
  game.registry.set(REG.AUDIO, new AudioSynth(game));
  if (!game.registry.get(REG.SEED)) game.registry.set(REG.SEED, String(Date.now()));
  game.registry.get(REG.INPUT).applySettings(settings);
  game.registry.get(REG.AUDIO).applySettings(settings);
  // W1: progression service (profile load + one-time backfill + RUN_END listener). Additive.
  const progression = await createProgressionService(game, { levels: game.registry.get(REG.CONTENT).progression });
  game.registry.set(REG.PROGRESSION, progression);
  // Profile entitlement is not available during initial AudioSynth
  // construction. Reapply once progression has loaded it so saved,
  // purchased vocal enablement is honored on a new browser session.
  game.registry.get(REG.AUDIO).applySettings(settings);
  // W2: missions. The service is created after progression so it can borrow the already-loaded
  // profile store, and it is attached to progression BEFORE RUN_END can fire (both happen during
  // preload, before TitleScene exists). Additive.
  const missions = await createMissionsService(game, {
    templates: game.registry.get(REG.CONTENT).missions.templates,
    // D7 tier thresholds come from the data, not from a constant in the service.
    tierUnlock: game.registry.get(REG.CONTENT).missions.tierUnlock,
    biomeDefs: Object.values(game.registry.get(REG.CONTENT).biomes || {}),
    store: progression.store,
  });
  game.registry.set(REG.MISSIONS_SERVICE, missions);
  progression.missions = missions;
}

/**
 * The ONLY way to change a setting: updates registry settings, persists, emits EVT.SETTINGS_CHANGED.
 * @param {Phaser.Game} game
 * @param {keyof import('./systems/SaveStore.js').Settings} key
 * @param {*} value
 * @returns {void}
 */
export function updateSetting(game, key, value) {
  const settings = game.registry.get(REG.SETTINGS);
  settings[key] = value;
  game.registry.get(REG.SAVE_STORE).saveSettings(settings);
  game.events.emit(EVT.SETTINGS_CHANGED, { key, value, settings });
}import { EventEmitter } from 'events';
import { AudioSynth, SFX } from '../../../src/systems/AudioSynth.js';
import { EVT } from '../../../src/events.js';

describe('AudioSynth without WebAudio', () => {
  test('every public method is a silent no-op and never throws', () => {
    const game = { events: new EventEmitter() };
    const a = new AudioSynth(game);
    expect(() => {
      a.unlock();
      SFX.forEach((n) => a.playSfx(n, { pitch: 1.2, volume: 0.5 }));
      a.playSfx('nope');
      a.startMusic('seed');
      a.stopMusic();
      a.duckMusic(100);
      a.glitch('static', 100, 0.9);
      a.setSpeed(500);
      a.setIntensity(0.5);
      a.applySettings({ masterVolume: 0.5, musicVolume: 1, sfxVolume: 0 });
      a.applySettings(undefined);
    }).not.toThrow();
    expect(a.ctx).toBeNull();
  });

  test('handles every subscribed event and unsubscribes on destroy', () => {
    const game = { events: new EventEmitter() };
    const a = new AudioSynth(game);
    const payloads = {
      [EVT.RUN_START]: { seed: 'x' }, [EVT.RUN_END]: {}, [EVT.RUN_ABORT]: {},
      [EVT.LANDING]: { quality: 'perfect', hard: false }, [EVT.TRICK]: { count: 2 },
      [EVT.COMBO_CHANGED]: { reason: 'trick', multiplier: 1.5 }, [EVT.CRASH]: { negated: true },
      [EVT.RESPAWN]: {}, [EVT.POWERUP_COLLECTED]: {}, [EVT.POWERUP_EXPIRED]: { reason: 'timeout' },
      [EVT.HAZARD_HIT]: { effect: 'slow' }, [EVT.ZONE_ENTER]: {}, [EVT.GLITCH_START]: { kind: 'dropout', durationMs: 80, intensity: 1 },
      [EVT.DISTANCE_CHANGED]: { meters: 500 }, [EVT.SETTINGS_CHANGED]: { settings: { masterVolume: 1, musicVolume: 1, sfxVolume: 1 } },
      [EVT.GAME_PAUSE]: {}, [EVT.GAME_RESUME]: {}, [EVT.INPUT_ACTION]: { action: 'anyKey' },
    };
    for (const [k, v] of Object.entries(payloads)) expect(() => game.events.emit(k, v)).not.toThrow();
    a.destroy();
    for (const k of Object.keys(payloads)) expect(game.events.listenerCount(k)).toBe(0);
  });

  test('works with no game events at all', () => {
    expect(() => new AudioSynth({}).destroy()).not.toThrow();
  });
});import { GlitchDirector, glitchGapRange, glitchRamp } from '../../../src/systems/GlitchDirector.js';
import { GLITCH } from '../../../src/constants.js';

function run(seed, seconds, dist = () => 0) {
  const d = new GlitchDirector({ seed });
  const starts = [];
  const ends = [];
  for (let t = 0; t <= seconds * 1000; t += 16) {
    const r = d.update(t, dist(t));
    r.started.forEach((e) => starts.push({ ...e, at: t }));
    r.ended.forEach((e) => ends.push({ id: e.id, at: t }));
  }
  return { starts, ends };
}

describe('GlitchDirector', () => {
  test('same seed => identical schedule, different seed => different', () => {
    const a = run('abc', 120);
    const b = run('abc', 120);
    const c = run('abd', 120);
    expect(a.starts.map((e) => [e.id, e.kind, e.startMs, e.durationMs, e.intensity])).toEqual(
      b.starts.map((e) => [e.id, e.kind, e.startMs, e.durationMs, e.intensity]));
    expect(a.starts.length).toBeGreaterThan(5);
    expect(c.starts.map((e) => e.startMs)).not.toEqual(a.starts.map((e) => e.startMs));
  });

  test('schedule is independent of the update cadence', () => {
    const d1 = new GlitchDirector({ seed: 's1' });
    const d2 = new GlitchDirector({ seed: 's1' });
    const s1 = [];
    const s2 = [];
    for (let t = 0; t < 90000; t += 7) d1.update(t, 0).started.forEach((e) => s1.push(e.id + e.startMs));
    for (let t = 0; t < 90000; t += 40) d2.update(t, 0).started.forEach((e) => s2.push(e.id + e.startMs));
    expect(s1).toEqual(s2);
  });

  test('early gaps 5-15 s, durations 50-200 ms, intensity 0..1, valid kinds', () => {
    const { starts } = run('gaps', 600);
    let prevEnd = 0;
    for (const e of starts) {
      const gap = e.startMs - prevEnd;
      expect(gap).toBeGreaterThanOrEqual(GLITCH.earlyGapMs[0] - 1);
      expect(gap).toBeLessThanOrEqual(GLITCH.earlyGapMs[1] + 1);
      expect(e.durationMs).toBeGreaterThanOrEqual(GLITCH.durationMs[0]);
      expect(e.durationMs).toBeLessThanOrEqual(GLITCH.durationMs[1]);
      expect(e.intensity).toBeGreaterThan(0);
      expect(e.intensity).toBeLessThanOrEqual(1);
      expect(GLITCH.kinds).toContain(e.kind);
      prevEnd = e.startMs + e.durationMs;
    }
  });

  test('past 1000 m gaps tighten to 3-6 s', () => {
    expect(glitchRamp(0)).toBe(0);
    expect(glitchRamp(1000)).toBe(1);
    expect(glitchGapRange(1500)).toEqual([...GLITCH.lateGapMs]);
    const { starts } = run('late', 300, () => 1500);
    // the first event was drawn at distance 0; later ones use the late range
    for (let i = 2; i < starts.length; i++) {
      const gap = starts[i].startMs - (starts[i - 1].startMs + starts[i - 1].durationMs);
      expect(gap).toBeGreaterThanOrEqual(3000 - 1);
      expect(gap).toBeLessThanOrEqual(6000 + 1);
    }
  });

  test('started/ended pair up; active reflects state; reset replays', () => {
    const { starts, ends } = run('pairs', 100);
    expect(starts.length).toBeGreaterThanOrEqual(ends.length);
    expect(starts.length - ends.length).toBeLessThanOrEqual(1);
    const d = new GlitchDirector({ seed: 'pairs' });
    const first = d.preview(1)[0];
    const r = d.update(first.startMs + 1, 0);
    expect(r.started[0].id).toBe(first.id);
    expect(r.active.id).toBe(first.id);
    const r2 = d.update(first.startMs + first.durationMs + 1, 0);
    expect(r2.ended[0].id).toBe(first.id);
    expect(r2.active).toBeNull();
    d.reset();
    expect(d.update(first.startMs + 1, 0).started[0].id).toBe(first.id);
  });

  test('a huge time jump starts and ends events without looping forever', () => {
    const d = new GlitchDirector({ seed: 'jump' });
    const r = d.update(10 * 60 * 1000, 0);
    expect(r.started.length).toBeGreaterThan(0);
    expect(r.started.length).toBeLessThanOrEqual(64);
  });
});import { EventEmitter } from 'events';
import { InputRouter } from '../../../src/systems/InputRouter.js';
import { EVT } from '../../../src/events.js';

function key(type, code, extra = {}) {
  const e = new KeyboardEvent(type, { code, bubbles: true, cancelable: true, ...extra });
  window.dispatchEvent(e);
  return e;
}

function setup() {
  const game = { events: new EventEmitter(), canvas: null, registry: { get: () => undefined } };
  const router = new InputRouter(game);
  const actions = [];
  game.events.on(EVT.INPUT_ACTION, (p) => actions.push(p));
  return { game, router, actions };
}

describe('InputRouter keyboard', () => {
  test('maps doc 4.1 keys and emits INPUT_ACTION', () => {
    const { router, actions } = setup();
    key('keydown', 'KeyW');
    key('keydown', 'KeyA');
    key('keydown', 'Space');
    key('keydown', 'ShiftLeft');
    key('keydown', 'ArrowLeft');
    key('keydown', 'ArrowUp');
    key('keydown', 'KeyS');
    let s = router.poll();
    expect(s).toMatchObject({ push: true, tilt: -1, hop: true, reset: true, heli: -1, airBrake: true, brake: true });
    expect(s.pressed).toMatchObject({ hop: true, reset: true, airBrake: true, confirm: true, pause: false });
    expect(router.poll().pressed.hop).toBe(false);
    key('keydown', 'KeyD');
    expect(router.poll()).toMatchObject({ tuck: true, tilt: 0 });
    key('keydown', 'ArrowDown');
    key('keydown', 'Escape');
    s = router.poll();
    expect(s.parachute).toBe(true);
    expect(s.pressed).toMatchObject({ parachute: true, pause: true });
    key('keyup', 'KeyW');
    expect(router.poll().push).toBe(false);
    const names = actions.filter((a) => a.pressed).map((a) => a.action);
    expect(names).toEqual(expect.arrayContaining(['hop', 'confirm', 'reset', 'airBrake', 'pause', 'left', 'up', 'down', 'anyKey']));
    expect(actions.every((a) => a.source === 'keyboard')).toBe(true);
    router.destroy();
  });

  test('prevents default for space/arrows only, ignores ctrl combos and text fields', () => {
    const { router } = setup();
    expect(key('keydown', 'Space').defaultPrevented).toBe(true);
    expect(key('keydown', 'ArrowDown').defaultPrevented).toBe(true);
    expect(key('keydown', 'KeyW').defaultPrevented).toBe(false);
    key('keyup', 'Space');
    key('keyup', 'ArrowDown');
    expect(key('keydown', 'KeyW', { ctrlKey: true }).defaultPrevented).toBe(false);
    key('keyup', 'KeyW');
    const input = document.createElement('input');
    document.body.appendChild(input);
    const e = new KeyboardEvent('keydown', { code: 'Space', bubbles: true, cancelable: true });
    input.dispatchEvent(e);
    expect(e.defaultPrevented).toBe(false);
    expect(router.poll().hop).toBe(false);
    router.destroy();
  });

  test('both Shift keys: releasing one keeps reset held', () => {
    const { router } = setup();
    key('keydown', 'ShiftLeft');
    key('keydown', 'ShiftRight');
    key('keyup', 'ShiftLeft');
    expect(router.poll().reset).toBe(true);
    key('keyup', 'ShiftRight');
    expect(router.poll().reset).toBe(false);
    router.destroy();
  });

  test('blur releases held keys', () => {
    const { router } = setup();
    key('keydown', 'KeyW');
    window.dispatchEvent(new Event('blur'));
    expect(router.poll().push).toBe(false);
    router.destroy();
  });

  test('setEnabled(false) returns neutral state but still emits menu actions', () => {
    const { router, actions } = setup();
    router.setEnabled(false);
    key('keydown', 'KeyW');
    expect(router.poll().push).toBe(false);
    expect(actions.some((a) => a.action === 'up')).toBe(true);
    router.setEnabled(true);
    expect(router.poll().push).toBe(true);
    router.destroy();
  });

  test('destroy removes every listener', () => {
    const { game, router, actions } = setup();
    router.destroy();
    key('keydown', 'KeyW');
    expect(actions.length).toBe(0);
    expect(game.events.listenerCount('prestep')).toBe(0);
    expect(game.events.listenerCount(EVT.RUN_START)).toBe(0);
  });
});

describe('InputRouter gamepad', () => {
  afterEach(() => { delete navigator.getGamepads; });

  function pad(over = {}) {
    const buttons = Array.from({ length: 17 }, () => ({ pressed: false, value: 0 }));
    return { connected: true, mapping: 'standard', axes: [0, 0, 0, 0], buttons, ...over };
  }

  test('stick tilt, RT push, A hop, Start pause, disconnect releases', () => {
    const { router, actions } = setup();
    const g = pad();
    navigator.getGamepads = () => [g];
    g.axes[0] = 0.05;
    expect(router.poll().tilt).toBe(0);
    g.axes[0] = -1;
    g.buttons[7] = { pressed: true, value: 1 };
    g.buttons[0] = { pressed: true, value: 1 };
    g.buttons[9] = { pressed: true, value: 1 };
    const s = router.poll();
    expect(s).toMatchObject({ tilt: -1, push: true, hop: true, lastSource: 'gamepad' });
    expect(s.pressed).toMatchObject({ hop: true, pause: true });
    expect(actions.some((a) => a.action === 'pause' && a.source === 'gamepad')).toBe(true);
    navigator.getGamepads = () => [null];
    const after = router.poll();
    expect(after.push).toBe(false);
    expect(after.tilt).toBe(0);
    router.destroy();
  });
});import { VirtualPad, emptyPadState } from '../../../src/systems/VirtualPad.js';

describe('VirtualPad', () => {
  test('starts neutral', () => {
    expect(new VirtualPad().poll()).toEqual(emptyPadState());
  });

  test('A/D tilt, both = tuck with zero tilt', () => {
    const p = new VirtualPad();
    p.setButton('tiltBack', true, 'keyboard');
    expect(p.poll().tilt).toBe(-1);
    p.setButton('tiltForward', true, 'keyboard');
    const s = p.poll();
    expect(s.tuck).toBe(true);
    expect(s.tilt).toBe(0);
    p.setButton('tiltBack', false, 'keyboard');
    expect(p.poll().tilt).toBe(1);
    expect(p.poll().tuck).toBe(false);
  });

  test('pressed edges fire once and survive a press/release between polls', () => {
    const p = new VirtualPad();
    p.setButton('hop', true, 'keyboard');
    p.setButton('hop', false, 'keyboard');
    const a = p.poll();
    expect(a.hop).toBe(false);
    expect(a.pressed.hop).toBe(true);
    expect(p.poll().pressed.hop).toBe(false);
    p.setButton('hop', true, 'keyboard');
    p.setButton('hop', true, 'touch'); // second source is not a new edge
    expect(p.poll().pressed.hop).toBe(true);
    expect(p.poll().pressed.hop).toBe(false);
  });

  test('sources are independent: keyboard release does not cancel a touch hold', () => {
    const p = new VirtualPad();
    p.setButton('push', true, 'touch');
    p.setButton('push', true, 'keyboard');
    p.setButton('push', false, 'keyboard');
    expect(p.poll().push).toBe(true);
    expect(p.state.lastSource).toBe('keyboard');
    p.setButton('push', false, 'touch');
    expect(p.poll().push).toBe(false);
  });

  test('heli axis', () => {
    const p = new VirtualPad();
    p.setButton('heliLeft', true, 'keyboard');
    expect(p.poll().heli).toBe(-1);
    p.setButton('heliRight', true, 'keyboard');
    expect(p.poll().heli).toBe(0);
    p.setButton('heliLeft', false, 'keyboard');
    expect(p.poll().heli).toBe(1);
  });

  test('analog tilt: dead-zone, overrides digital, rescaled, clamped', () => {
    const p = new VirtualPad();
    p.setTilt(0.1);
    expect(p.poll().tilt).toBe(0);
    p.setButton('tiltBack', true, 'keyboard');
    p.setTilt(0.1);
    expect(p.poll().tilt).toBe(-1); // inside dead-zone: digital wins
    p.setTilt(1);
    expect(p.poll().tilt).toBe(1);
    p.setTilt(0.575);
    expect(p.poll().tilt).toBeCloseTo(0.5, 5);
    p.setTilt(5);
    expect(p.poll().tilt).toBe(1);
    expect(p.poll().lastSource).toBe('gamepad');
  });

  test('largest analog source wins; releaseSource clears gamepad', () => {
    const p = new VirtualPad();
    p.setTilt(0.5, 'gamepad');
    p.setTilt(-1, 'device');
    expect(p.poll().tilt).toBe(-1);
    p.releaseSource('touch');
    expect(p.poll().tilt).toBeGreaterThan(0);
    p.releaseSource('gamepad');
    expect(p.poll().tilt).toBe(0);
  });

  test('unknown buttons ignored; destroy resets', () => {
    const p = new VirtualPad();
    p.setButton('nope', true, 'keyboard');
    p.setButton('brake', true, 'keyboard');
    p.destroy();
    expect(p.poll()).toEqual(emptyPadState());
  });

  test('touch overlay mounts, shows only in run context, buttons drive the pad', () => {
    const p = new VirtualPad();
    const parent = document.createElement('div');
    document.body.appendChild(parent);
    p.mountTouchOverlay(parent, { touchOverlay: 'on', touchRotate90: false });
    const root = parent.querySelector('.bb-touch-overlay');
    expect(root).not.toBeNull();
    expect(root.style.display).toBe('none');
    p.setOverlayContext(true);
    expect(root.style.display).toBe('block');
    expect(root.querySelectorAll('[data-btn]').length).toBe(12);
    // drive the overlay directly (jsdom has no elementFromPoint layout)
    p.overlay._assign(1, 'hop');
    p.overlay._assign(2, 'tiltBack');
    p.overlay._assign(3, 'tiltForward');
    const s = p.poll();
    expect(s.hop).toBe(true);
    expect(s.pressed.hop).toBe(true);
    expect(s.tuck).toBe(true);
    expect(s.lastSource).toBe('touch');
    p.setOverlayContext(false); // hiding releases everything
    expect(p.poll().hop).toBe(false);
    p.destroy();
    expect(parent.querySelector('.bb-touch-overlay')).toBeNull();
  });

  test('overlay mode off never shows; auto hidden without touch', () => {
    const p = new VirtualPad();
    const parent = document.createElement('div');
    p.mountTouchOverlay(parent, { touchOverlay: 'off' });
    p.setOverlayContext(true);
    expect(p.overlay.isVisible()).toBe(false);
    p.destroy();
  });
});// Biome-tagged content FIXTURES for the B0 groundwork tests (not a test file, not shipped content).
