const byId = (arr) => Object.fromEntries(arr.map((d) => [d.id, JSON.parse(JSON.stringify(d))]));

/** Shipped content WITHOUT its biome-tagged defs (B1+ ships real ones): the fixture tests test the engine, not the tuning. */
export const baseOnly = (o) => Object.fromEntries(Object.entries(o).filter(([, d]) => !d.biome));

/** Shipped BASE content plus every fixture above, as TerrainGenerator options overrides. */
export function withBiomeFixtures(content, extra = {}) {
  return {
    hazardDefs: { ...baseOnly(content.hazards), ...byId([FX_GROUND_HAZARD, FX_AIR_HAZARD]), ...(extra.hazards || {}) },
    powerupDefs: { ...baseOnly(content.powerups), ...byId([FX_WARD_POWERUP, FX_STABILIZE_POWERUP]), ...(extra.powerups || {}) },
  };
}

/** Mask with both fixture biomes on (garbage-dump-glacier 2 | space-mountain 32). */
export const FX_MASK = 2 | 32;// Shared test helpers (not a test file). Reads content JSON with fs (no Vite import.meta.glob under Jest).
import fs from 'fs';
import path from 'path';
import { TerrainGenerator } from '../../src/systems/TerrainGenerator.js';

const dataDir = path.resolve('src/data');

export function readDir(sub) {
  const dir = path.join(dataDir, sub);
  return fs
    .readdirSync(dir)
    .filter((f) => f.endsWith('.json'))
    .sort()
    .map((f) => JSON.parse(fs.readFileSync(path.join(dir, f), 'utf8')));
}

const byId = (arr) => Object.fromEntries(arr.map((d) => [d.id, d]));

export function loadContent() {
  return {
    chunks: readDir('chunks'),
    hazards: byId(readDir('hazards')),
    powerups: byId(readDir('powerups')),
    terrainMods: byId(readDir('terrainMods')),
    biomes: byId(readDir('biomes')),
  };
}

export function makeGen(seed = 'test-seed', overrides = {}) {
  const c = loadContent();
  return new TerrainGenerator({
    seed,
    chunkDefs: c.chunks,
    hazardDefs: c.hazards,
    powerupDefs: c.powerups,
    modDefs: c.terrainMods,
    biomeDefs: Object.values(c.biomes),
    ...overrides,
  });
}

export const segAngle = (p, i) => (Math.atan2(p[i + 1].y - p[i].y, p[i + 1].x - p[i].x) * 180) / Math.PI;
export const inGap = (chunk, i) =>
  chunk.gaps.some((g) => chunk.points[i].x >= g.x0 && chunk.points[i + 1].x <= g.x1);

/** Points of chunks [0,n) as one polyline, bridge chunks excluded (their gap is a deliberate jump). */
export function solidPoints(gen, n) {
  const out = [];
  for (let i = 0; i < n; i++) {
    const c = gen.getChunk(i);
    if (c.kind === 'bridge') continue;
    for (const p of c.points) if (!out.length || p.x > out[out.length - 1].x) out.push(p);
  }
  return out;
}

/**
 * 1-D rolling point mass along the polyline (65% of g*sin(slope), linear + quadratic drag, as seen in QA).
 * @returns {{stalledAtM:number|null, reachedM:number}} stall = < 10 px/s for more than 1 s.
 */
export function rollSim(gen, maxM, ppm = 20) {
  const nChunks = Math.ceil((maxM * ppm) / 1100) + 20;
  const pts = solidPoints(gen, nChunks);
  let v = 90;
  let i = 0;
  let pos = pts[0].x;
  let below = 0;
  for (let t = 0; i < pts.length - 2 && pos < maxM * ppm; t += 0.01) {
    const a = Math.atan2(pts[i + 1].y - pts[i].y, pts[i + 1].x - pts[i].x);
    v = Math.max(0, v + (900 * Math.sin(a) * 0.65 - 0.2 * v - 0.0003 * v * v) * 0.01);
    pos += v * Math.cos(a) * 0.01;
    while (i < pts.length - 2 && pos >= pts[i + 1].x) i++;
    below = v < 10 ? below + 0.01 : 0;
    if (below > 1) return { stalledAtM: pos / ppm, reachedM: pos / ppm };
    if (t > 4000) break;
  }
  return { stalledAtM: null, reachedM: pos / ppm };
}

/**
 * Ballistic launch detector: from every ground point launch at speed v along the local tangent (g = 900),
 * measure flight time until the polyline is met again. A "launch" is a flight of >= minAirS seconds; flights do
 * not overlap. Returns [{x, y, airS, landX}] over chunks [0,n).
 */
export function findLaunches(gen, n, v = 450, minAirS = 0.6) {
  const chunks = [];
  for (let i = 0; i < n; i++) chunks.push(gen.getChunk(i));
  const pts = [];
  for (const c of chunks) for (const p of c.points) if (!pts.length || p.x > pts[pts.length - 1].x) pts.push({ x: p.x, y: p.y });
  const ground = (x, from) => {
    let k = from;
    while (k < pts.length - 2 && pts[k + 1].x < x) k++;
    const a = pts[k];
    const b = pts[k + 1];
    return [a.y + ((b.y - a.y) * (x - a.x)) / (b.x - a.x), k];
  };
  const out = [];
  let skipTo = -1;
  for (let i = 1; i < pts.length - 2; i++) {
    if (pts[i].x <= skipTo) continue;
    const a = Math.atan2(pts[i].y - pts[i - 1].y, pts[i].x - pts[i - 1].x);
    const vx = v * Math.cos(a);
    const vy = v * Math.sin(a);
    let k = i;
    let landed = null;
    for (let t = 0.04; t < 3; t += 0.04) {
      const x = pts[i].x + vx * t;
      const y = pts[i].y + vy * t + 450 * t * t;
      if (x > pts[pts.length - 2].x) break;
      const [gy, kk] = ground(x, k);
      k = kk;
      if (y >= gy - 2 && t > 0.1) { landed = { t, x }; break; }
    }
    if (landed && landed.t >= minAirS) {
      out.push({ x: pts[i].x, y: pts[i].y, airS: landed.t, landX: landed.x });
      skipTo = landed.x;
    }
  }
  return out;
}/**
 * W5 achievements grid layout — the geometry gates that the Profile view's suite established as the
 * pattern: no overlapping text, every row inside the panel, nothing under the BACK button.
 *
 * A layout bug here is a visual bug the unit tests can still catch, which is the whole reason the grid is
 * Phaser-free. The specific failure this guards against is the one W3's Profile panel already hit: a row
 * list that grows past the BACK button at `h - 22`.
 */
import {
  achievementsLayout, achievementRows, pageCount, clampPage, overlappingPairs,
  ACH_PANEL, ROWS_PER_PAGE, GROUPS, toastLayout, TOAST_BOX,
} from '../../src/ui/AchievementsLayout.js';
import { ACHIEVEMENTS } from '../../src/systems/Achievements.js';
import { measureText } from '../../src/ui/PixelFont.js';

/** A profile that has done nothing yet. */
const EMPTY = { v: 1, xp: 0, level: 1, achievements: {}, lifetime: { runs: 0, tricks: {} } };

/** A profile with everything unlocked, for the worst-case page. */
const MAXED = {
  v: 1, xp: 6_000_000, level: 30,
  achievements: Object.fromEntries(ACHIEVEMENTS.map((a) => [a.id, 1_700_000_000_000])),
  lifetime: { runs: 9999, distanceM: 9e6, bestDistanceM: 9e6, bestScore: 9e6, bestCombo: 99, maxAirtimeMs: 99000, tricks: {}, shards: 9e6, nearMisses: 9000 },
};

describe('achievementRows', () => {
  test('every achievement appears once, under a header', () => {
    const rows = achievementRows();
    const ids = rows.filter((r) => r.kind === 'row').map((r) => r.id);
    expect(ids.length).toBe(ACHIEVEMENTS.length);
    expect(new Set(ids).size).toBe(ACHIEVEMENTS.length);
  });

  test('a header precedes its group', () => {
    const rows = achievementRows();
    expect(rows[0].kind).toBe('header');
    for (const g of GROUPS) expect(rows.some((r) => r.kind === 'header' && r.label === g.label)).toBe(true);
  });
});

describe('paging', () => {
  test('covers every row across all pages exactly once', () => {
    const rows = achievementRows();
    const seen = [];
    for (let p = 0; p < pageCount(rows); p += 1) {
      for (const r of achievementsLayout({ page: p }).rows) {
        if (r.kind === 'row') seen.push(r.id);
      }
    }
    expect(seen.sort()).toEqual(rows.filter((r) => r.kind === 'row').map((r) => r.id).sort());
  });

  test('a page never shows more rows than the pitch allows', () => {
    for (let p = 0; p < pageCount(); p += 1) {
      expect(achievementsLayout({ page: p }).rows.length).toBeLessThanOrEqual(ROWS_PER_PAGE);
    }
  });

  test('an out-of-range page is clamped rather than blank', () => {
    const n = pageCount();
    expect(clampPage(99)).toBe(n - 1);
    expect(clampPage(-5)).toBe(0);
    expect(achievementsLayout({ page: 99 }).rows.length).toBeGreaterThan(0);
  });

  test('junk page values do not throw', () => {
    for (const p of [undefined, null, NaN, 'x', 1.7]) expect(() => achievementsLayout({ page: p })).not.toThrow();
  });
});

describe('geometry', () => {
  test('no two drawn boxes overlap on any page, with nothing unlocked', () => {
    for (let p = 0; p < pageCount(); p += 1) {
      const l = achievementsLayout({ profile: EMPTY, page: p });
      expect(overlappingPairs(l.items)).toEqual([]);
    }
  });

  test('no two drawn boxes overlap on any page, with everything unlocked', () => {
    // Longest values ("9/9" style progress and long names) are the tight case for the right-hand column.
    for (let p = 0; p < pageCount(); p += 1) {
      const l = achievementsLayout({ profile: MAXED, page: p });
      expect(overlappingPairs(l.items)).toEqual([]);
    }
  });

  test('every box sits inside the panel', () => {
    for (let p = 0; p < pageCount(); p += 1) {
      for (const it of achievementsLayout({ profile: MAXED, page: p }).items) {
        expect({ key: it.key, ok: it.x >= 0 && it.x + it.w <= ACH_PANEL.w }).toEqual({ key: it.key, ok: true });
        expect({ key: it.key, ok: it.y >= 0 && it.y + it.h <= ACH_PANEL.h }).toEqual({ key: it.key, ok: true });
      }
    }
  });

  test('no row is drawn under the BACK button', () => {
    // The exact bug W3's Profile panel hit: BACK is placed at h - 22 by the View base class, so any row
    // whose box reaches that line is covered by a button the player cannot see through.
    const backTop = ACH_PANEL.h - 22;
    for (let p = 0; p < pageCount(); p += 1) {
      for (const it of achievementsLayout({ page: p }).items) {
        if (it.key === 'page') continue; // the footer is the page indicator, positioned deliberately
        expect({ key: it.key, clear: it.y + it.h <= backTop }).toEqual({ key: it.key, clear: true });
      }
    }
  });

  test('the page footer stays clear of the BACK button horizontally', () => {
    // BACK occupies the right 76px of the panel, so the footer must end before that column starts.
    const l = achievementsLayout({ page: 0 });
    const backLeft = ACH_PANEL.w - 76;
    expect(l.footer.x + l.footer.w).toBeLessThanOrEqual(backLeft);
  });

  test('the panel fits the 270px canvas at its y offset', () => {
    // The View base class centres when y is omitted; the achievements view pins y=13, so this must fit.
    expect(13 + ACH_PANEL.h).toBeLessThanOrEqual(270);
  });
});

describe('row rendering state', () => {
  test('an unlocked achievement reads done, and a locked one does not', () => {
    const rows = achievementsLayout({ profile: EMPTY, page: 0 }).rows.filter((r) => r.kind === 'row');
    expect(rows.every((r) => r.done === false)).toBe(true);

    const done = achievementsLayout({ profile: MAXED, page: 0 }).rows.filter((r) => r.kind === 'row');
    expect(done.every((r) => r.done === true)).toBe(true);
  });

  test('progress never exceeds the target, and a done row is full', () => {
    const rows = achievementsLayout({ profile: MAXED, page: 0 }).rows.filter((r) => r.kind === 'row');
    for (const r of rows) expect(r.ratio).toBe(1);
  });

  test('partial progress is reported honestly', () => {
    const p = { ...EMPTY, lifetime: { ...EMPTY.lifetime, runs: 5 } };
    const rows = achievementsLayout({ profile: p }).rows.filter((r) => r.kind === 'row');
    const ten = rows.find((r) => r.id === 'ten-runs');
    if (ten) expect(ten.progress).toBe('5/10');
  });

  test('every achievement carries a description for the grid', () => {
    for (const a of ACHIEVEMENTS) expect(a.desc.length).toBeGreaterThan(0);
  });
});

describe('toastLayout', () => {
  const A = (name, desc) => ({ id: name.toLowerCase(), name, desc: desc || '' });
  // Same contract as PixelFont.ellipsize: truncate to a PIXEL width, not a character count. A
  // character-count stub would pass a 138-char string through and the assertion below would be a lie.
  const cut = (s, maxPx) => {
    let out = String(s);
    while (out.length > 1 && measureText(out) > maxPx) out = out.slice(0, -2) + '~';
    return out;
  };

  test('nothing to announce renders nothing', () => {
    for (const v of [null, undefined, [], 'x', [{}, { name: '' }]]) expect(toastLayout(v)).toBeNull();
  });

  test('one unlock shows its name and its description', () => {
    const l = toastLayout([A('First Descent', 'Finish your first run.')], { ellipsize: cut });
    expect(l.lines[0].text).toBe('UNLOCKED FIRST DESCENT');
    expect(l.lines[1].text).toBe('FINISH YOUR FIRST RUN.');
  });

  // Decision 9 (2026-11-14) changed this contract: up to three unlocks are all named, in order; more than
  // three show two names and a count. It used to be the first name and "+2 MORE" here.
  test('several unlocks are named in order, all three when they fit', () => {
    const l = toastLayout([A('First Descent', 'x'), A('Doubled Up', 'y'), A('Kilometre Club', 'z')], { ellipsize: cut });
    expect(l.lines.map((x) => x.text)).toEqual(['UNLOCKED FIRST DESCENT', 'DOUBLED UP', 'KILOMETRE CLUB']);
    for (const line of l.lines) {
      expect(line.y + line.h).toBeLessThanOrEqual(TOAST_BOX.maxY);
      expect(line.x + line.w).toBeLessThanOrEqual(TOAST_BOX.x + TOAST_BOX.w);
    }
    expect(overlappingPairs(l.lines)).toEqual([]);
  });

  test('a long name is ellipsised inside the box, not allowed to run under the header', () => {
    const l = toastLayout([A('Marathon Machine', 'Ride 25,000 m in total.')], { ellipsize: cut });
    for (const line of l.lines) {
      expect({ key: line.key, fits: line.x + line.w <= TOAST_BOX.x + TOAST_BOX.w }).toEqual({ key: line.key, fits: true });
    }
  });

  test('the toast stays inside its measured band', () => {
    const l = toastLayout([A('First Descent', 'Finish your first run.')], { ellipsize: cut });
    for (const line of l.lines) {
      expect(line.y).toBeGreaterThanOrEqual(TOAST_BOX.y);
      expect(line.y + line.h).toBeLessThanOrEqual(TOAST_BOX.maxY);
    }
  });

  test('the band does not collide with the header or the panels', () => {
    // Measured from GameOverScene: header ink starts at x 156 (scale 4, centred), RUN REPORT at y 54,
    // LEDGER at x 250. The toast must stay left of 156 and above 54 to avoid all three.
    expect(TOAST_BOX.x + TOAST_BOX.w).toBeLessThanOrEqual(156);
    expect(TOAST_BOX.maxY).toBeLessThanOrEqual(54);
  });

  test('works without an injected ellipsize', () => {
    expect(() => toastLayout([A('First Descent', 'd')])).not.toThrow();
  });
});/**
 * Marvin decision 9 (2026-11-14): "Combo achievements resolve in deterministic progression order; grant all
 * simultaneously earned achievements."
 *
 * After the ACH-2 retarget the combo ladder is x1.25 / x1.5 / x1.75 / x2.0, but `combo-2` (x2.0, the
 * hardest) was listed first, so it led the grid and the unlock toast. The fix is one canonical order for the
 * whole catalogue: group (GROUP_ORDER), then metric (METRIC_ORDER, so one ladder stays together), then
 * target ascending, stable on catalogue order for ties. The grid, `qualified`/`newlyUnlocked` and the toast
 * all read that order.
 *
 * The comparator is tested on a SHUFFLED fixture, not only on the shipped catalogue: the shipped list is
 * already stored in canonical order, so a test that only reads it would still pass with the sort deleted.
 */
import fs from 'fs';

import {
  ACHIEVEMENTS, METRICS, GROUP_ORDER, METRIC_ORDER, sortAchievements, qualified, newlyUnlocked,
  groupedAchievements,
} from '../../src/systems/Achievements.js';
import { achievementRows, GROUPS, toastLayout } from '../../src/ui/AchievementsLayout.js';
import { sanitizeProfile, creditRun } from '../../src/systems/ProfileStore.js';
import { measureText } from '../../src/ui/PixelFont.js';

const read = (p) => JSON.parse(fs.readFileSync(p, 'utf8'));
const LEVELS = read('src/data/progression/levels.json');
const ids = (list) => list.map((a) => a.id);
const COMBO_ORDER = ['combo-5', 'combo-10', 'combo-20', 'combo-2'];

describe('the canonical order: group, then metric, then target', () => {
  test('GROUP_ORDER covers every group the catalogue uses, and METRIC_ORDER is exactly METRICS', () => {
    for (const a of ACHIEVEMENTS) expect({ id: a.id, known: GROUP_ORDER.includes(a.group) }).toEqual({ id: a.id, known: true });
    expect([...METRIC_ORDER].sort()).toEqual([...METRICS].sort());
  });

  test('a shuffled catalogue sorts into group order, ladders together, targets ascending', () => {
    const fx = [
      { id: 'b-hi', group: 'biomes', metric: 'biomesDiscovered', target: 9 },
      { id: 's-combo-hi', group: 'skill', metric: 'bestCombo', target: 2 },
      { id: 'd-runs-hi', group: 'distance', metric: 'runs', target: 50 },
      { id: 's-tricks-lo', group: 'skill', metric: 'tricksLanded', target: 10 },
      { id: 's-combo-lo', group: 'skill', metric: 'bestCombo', target: 1.25 },
      { id: 'd-runs-lo', group: 'distance', metric: 'runs', target: 1 },
      { id: 'b-lo', group: 'biomes', metric: 'biomesDiscovered', target: 2 },
      { id: 's-combo-mid', group: 'skill', metric: 'bestCombo', target: 1.5 },
    ];
    expect(ids(sortAchievements(fx))).toEqual([
      'd-runs-lo', 'd-runs-hi', 's-combo-lo', 's-combo-mid', 's-combo-hi', 's-tricks-lo', 'b-lo', 'b-hi',
    ]);
  });

  test('ties keep their catalogue order (stable), and unknown groups or metrics sort last, not first', () => {
    const fx = [
      { id: 'z-unknown', group: 'mystery', metric: 'runs', target: 1 },
      { id: 'tie-1', group: 'distance', metric: 'runs', target: 10 },
      { id: 'tie-2', group: 'distance', metric: 'runs', target: 10 },
      { id: 'odd-metric', group: 'distance', metric: 'nope', target: 1 },
    ];
    expect(ids(sortAchievements(fx))).toEqual(['tie-1', 'tie-2', 'odd-metric', 'z-unknown']);
  });

  test('the input is not mutated', () => {
    const fx = [{ id: 'b', group: 'skill', metric: 'runs', target: 2 }, { id: 'a', group: 'distance', metric: 'runs', target: 1 }];
    sortAchievements(fx);
    expect(ids(fx)).toEqual(['b', 'a']);
  });

  test('the shipped catalogue is already in canonical order', () => {
    expect(ids(ACHIEVEMENTS)).toEqual(ids(sortAchievements(ACHIEVEMENTS)));
  });

  test('achievements.json lists every entry in the same order as the built-in catalogue', () => {
    const json = read('src/data/achievements/achievements.json');
    const list = Array.isArray(json) ? json : json.achievements;
    expect(ids(list)).toEqual(ids(ACHIEVEMENTS));
  });
});

describe('combo achievements climb in progression order everywhere', () => {
  const combos = (list) => list.filter((a) => a.metric === 'bestCombo');

  test('catalogue order is x1.25, x1.5, x1.75, x2.0', () => {
    expect(ids(combos(ACHIEVEMENTS))).toEqual(COMBO_ORDER);
    expect(combos(ACHIEVEMENTS).map((a) => a.target)).toEqual([1.25, 1.5, 1.75, 2]);
  });

  test('the grid shows them in that order', () => {
    const rows = achievementRows().filter((r) => r.kind === 'row').map((r) => r.id);
    expect(rows.filter((id) => COMBO_ORDER.includes(id))).toEqual(COMBO_ORDER);
  });

  test('evaluation returns them in that order', () => {
    expect(ids(combos(qualified({ bestCombo: 2 })))).toEqual(COMBO_ORDER);
    expect(ids(combos(newlyUnlocked({ bestCombo: 2 }, {})))).toEqual(COMBO_ORDER);
  });

  test('names and descriptions match their targets: the x2.0 one is the capstone, not "Wireless Legend" at x1.75', () => {
    const want = {
      'combo-5': ['Combo Starter', 'Land a x1.25 combo.'],
      'combo-10': ['Chain Reaction', 'Land a x1.5 combo.'],
      'combo-20': ['Unbroken', 'Land a x1.75 combo.'],
      'combo-2': ['Doubled Up', 'Land a x2 combo.'],
    };
    for (const a of combos(ACHIEVEMENTS)) expect({ id: a.id, name: a.name, desc: a.desc }).toEqual({ id: a.id, name: want[a.id][0], desc: want[a.id][1] });
  });
});

describe('everything earned at once is granted at once, in order', () => {
  const v1 = (o = {}) => sanitizeProfile({ v: 1, ...o }, LEVELS);
  const rec = (o = {}) => ({
    version: 1, id: 'run-1', seed: 's', dailyRuleId: 'none', startedAt: 0, endedAt: 4242, durationMs: 60000,
    score: 0, distanceM: 0, trickPoints: 0, tricks: {}, bestCombo: 1, maxAirtimeMs: 0, cause: 'crash',
    ledgerHash: 'h1', shards: 0, nearMisses: 0, ...o,
  });

  test('a run that reaches x1.75 unlocks x1.25, x1.5 and x1.75 together, in order, with one timestamp', () => {
    const res = creditRun(v1(), rec({ bestCombo: 1.75 }), LEVELS);
    const got = res.awards.achievements.filter((a) => a.metric === 'bestCombo').map((a) => a.id);
    expect(got).toEqual(['combo-5', 'combo-10', 'combo-20']);
    expect(res.profile.achievements['combo-2']).toBeUndefined();
    const stamps = got.map((id) => res.profile.achievements[id]);
    expect(stamps).toEqual([4242, 4242, 4242]);
  });

  test('the awards list for a whole run follows the canonical catalogue order', () => {
    const res = creditRun(v1(), rec({ bestCombo: 2, distanceM: 1200 }), LEVELS);
    const got = ids(res.awards.achievements);
    expect(got).toEqual(ids(ACHIEVEMENTS).filter((id) => got.includes(id)));
    expect(got.indexOf('first-descent')).toBeLessThan(got.indexOf('combo-5'));
