describe('toast: names in order, overflow counted on the last line', () => {
  const A = (name) => ({ id: name.toLowerCase(), name, desc: 'd' });
  const cut = (s, maxPx) => {
    let out = String(s);
    while (out.length > 1 && measureText(out) > maxPx) out = out.slice(0, -2) + '~';
    return out;
  };

  test('two unlocks show both names', () => {
    const l = toastLayout([A('First Descent'), A('Combo Starter')], { ellipsize: cut });
    expect(l.lines.map((x) => x.text)).toEqual(['UNLOCKED FIRST DESCENT', 'COMBO STARTER']);
  });

  test('four or more show two names and a count of the rest', () => {
    const l = toastLayout([A('First Descent'), A('Combo Starter'), A('Chain Reaction'), A('Unbroken')], { ellipsize: cut });
    expect(l.lines.map((x) => x.text)).toEqual(['UNLOCKED FIRST DESCENT', 'COMBO STARTER', '+2 MORE']);
  });
});/**
 * W5 achievements — the store integration, which is where a correct evaluator still ships broken.
 *
 * The pure evaluator is tested next door. What this file pins is the SEAM: that creditRun stamps
 * achievements into the same save it credits XP into, that the timestamp comes from the record rather than
 * the clock, that rewards land with the stamp, and that a save round-trip does not lose or duplicate them.
 */
import { creditRun, unlockAchievementsFor, sanitizeProfile, grantAchievementReward } from '../../src/systems/ProfileStore.js';
import { defaultProfile } from '../../src/systems/Progression.js';

const NOW = 1_700_000_000_000;

/** A finished run record carrying just enough for crediting and achievement thresholds. */
const run = (o = {}) => ({
  version: 1,
  id: 'r1',
  seed: 's',
  startedAt: NOW - 60_000,
  endedAt: NOW,
  durationMs: 60_000,
  distanceM: 100,
  score: 1000,
  maxCombo: 2,
  maxAirtimeMs: 100,
  tricks: {},
  shards: 0,
  ledgerHash: 'abc12345',
  ...o,
});

const fresh = (o = {}) => ({ ...defaultProfile(), ...o });

describe('creditRun stamps achievements', () => {
  test('a first run unlocks the first-run achievement, stamped with the record end time', () => {
    const { profile, awards } = creditRun(fresh(), run());
    expect(awards.achievements.map((a) => a.id)).toContain('first-descent');
    // The timestamp is the RECORD's end, not Date.now(): a replayed save must produce the same unlock time.
    expect(profile.achievements['first-descent']).toBe(NOW);
  });

  test('the same run credited twice does not restamp or double-grant', () => {
    const first = creditRun(fresh(), run());
    // creditRun refuses a re-credited ledger hash outright, which is the first line of defence against a
    // double grant. The evaluator's own idempotency is covered directly below and in the pure suite.
    expect(creditRun(first.profile, run())).toBeNull();
    const after = sanitizeProfile(first.profile);
    expect(after.achievements).toEqual(first.profile.achievements);
  });

  test('a run that crosses a distance threshold unlocks it on that run', () => {
    const { profile, awards } = creditRun(fresh(), run({ distanceM: 1200 }));
    expect(awards.achievements.map((a) => a.id)).toContain('dist-1k');
    expect(profile.achievements['dist-1k']).toBe(NOW);
  });

  test('a run just under a threshold does not unlock it', () => {
    const { awards } = creditRun(fresh(), run({ distanceM: 999 }));
    expect(awards.achievements.map((a) => a.id)).not.toContain('dist-1k');
  });

  test('a reward is granted in the same save as its unlock', () => {
    // biomes-2 grants a cosmetic. Reaching it must hand over the item atomically, or the player sees the
    // achievement but never gets what it promised.
    const p = fresh({ lifetime: { ...defaultProfile().lifetime, runs: 1 } });
    const { profile, added } = unlockAchievementsFor(p, null, { at: NOW, biomeCount: 2 });
    expect(added.map((a) => a.id)).toContain('biomes-2');
    expect(profile.unlocked.cosmetics).toContain('trail-hue-aurora');
  });

  test('a title reward lands in unlocked.titles', () => {
    const p = fresh();
    const { profile, added } = unlockAchievementsFor(p, null, { at: NOW, biomeCount: 5 });
    expect(added.map((a) => a.id)).toContain('biomes-5');
    expect(profile.unlocked.titles).toContain('CARTOGRAPHER');
  });

  test('a reward is not granted twice', () => {
    const p = fresh();
    const once = unlockAchievementsFor(p, null, { at: NOW, biomeCount: 5 });
    const twice = unlockAchievementsFor(once.profile, null, { at: NOW, biomeCount: 5 });
    expect(twice.added).toEqual([]);
    expect(twice.profile.unlocked.titles.filter((t) => t === 'CARTOGRAPHER')).toHaveLength(1);
  });
});

describe('unlockAchievementsFor is pure', () => {
  test('does not mutate the profile it is given', () => {
    const p = fresh();
    const snapshot = JSON.stringify(p);
    unlockAchievementsFor(p, run({ distanceM: 9000 }), { at: NOW, biomeCount: 11 });
    expect(JSON.stringify(p)).toBe(snapshot);
  });

  test('a missing timestamp unlocks nothing rather than storing NaN', () => {
    const p = fresh();
    const { profile, added } = unlockAchievementsFor(p, run({ distanceM: 9000 }), { biomeCount: 11 });
    expect(added).toEqual([]);
    expect(profile.achievements).toEqual({});
  });

  test('junk input does not throw', () => {
    for (const p of [null, undefined, {}, 5]) {
      expect(() => unlockAchievementsFor(p, null, { at: NOW })).not.toThrow();
    }
  });
});

describe('sanitizeProfile keeps achievements trustworthy', () => {
  test('drops non-finite timestamps and junk keys', () => {
    const raw = { v: 1, achievements: { ok: NOW, bad: 'soon', worse: NaN, alsoBad: null } };
    const p = sanitizeProfile(raw);
    expect(p.achievements).toEqual({ ok: NOW });
  });

  test('an array is not a valid achievements map', () => {
    const p = sanitizeProfile({ v: 1, achievements: ['a', 'b'] });
    expect(p.achievements).toEqual({});
  });

  test('a missing block becomes an empty map', () => {
    expect(sanitizeProfile({ v: 1 }).achievements).toEqual({});
  });

  test('unlocks survive a save/load round trip', () => {
    const { profile } = creditRun(fresh(), run({ distanceM: 1200 }));
    const reloaded = sanitizeProfile(JSON.parse(JSON.stringify(profile)));
    expect(reloaded.achievements).toEqual(profile.achievements);
  });
});

describe('grantAchievementReward', () => {
  test('ignores an achievement with no reward', () => {
    const p = fresh();
    const before = JSON.stringify(p);
    grantAchievementReward(p, { id: 'x' });
    expect(JSON.stringify(p)).toBe(before);
  });

  test('ignores an unknown reward kind instead of throwing', () => {
    const p = fresh();
    expect(() => grantAchievementReward(p, { id: 'x', reward: { mystery: 'thing' } })).not.toThrow();
  });

  test('creates the unlocked block when the profile has none', () => {
    const p = { v: 1 };
    grantAchievementReward(p, { id: 'x', reward: { cosmetic: 'rider-hue-mint' } });
    expect(p.unlocked.cosmetics).toEqual(['rider-hue-mint']);
  });
});/**
 * Achievement evaluation fixes from the post-sprint audit (ACH-1, ACH-2, ACH-5, and the daily/streak half of
 * ACH-3). Driven through the real creditRun so the credited-run path is what is tested.
 */
import fs from 'fs';

import { sanitizeProfile, creditRun } from '../../src/systems/ProfileStore.js';
import { ACHIEVEMENTS, metricsFrom, progressFor } from '../../src/systems/Achievements.js';
import { SCORING } from '../../src/constants.js';
import { DailyPatch } from '../../src/systems/DailyPatch.js';

// Decisions 1/2: only an OFFICIAL Daily run (started from the DAILY RUN item: a v2 record with
// dailyOfficial, on the date's own rule and mask) counts as a Daily run. These fixtures used to be any run
// on a daily seed; they are stamped official so the Daily achievements they test are still reached.
const off = (k) => {
  const info = DailyPatch.infoForDateKey(k);
  return { seed: `daily-${k}`, hashV: 2, dailyOfficial: true, dailyRuleId: info.rule.id, ...(info.biomeMask ? { biomeMask: info.biomeMask } : {}) };
};


const read = (p) => JSON.parse(fs.readFileSync(p, 'utf8'));
const LEVELS = read('src/data/progression/levels.json');

const rec = (o = {}) => ({
  version: 1, id: 'run-1', seed: 's', dailyRuleId: 'none', startedAt: 0, endedAt: 1000, durationMs: 60000,
  score: 0, distanceM: 0, trickPoints: 0, tricks: {}, bestCombo: 1, maxAirtimeMs: 0, cause: 'crash',
  ledgerHash: 'h1', shards: 0, nearMisses: 0, ...o,
});

const v1 = (o = {}) => sanitizeProfile({ v: 1, ...o }, LEVELS);

describe('ACH-1: tricksLanded counts the credited run once', () => {
  test('one run with 5 backflips does not unlock "Land 10 tricks"', () => {
    const res = creditRun(v1(), rec({ tricks: { backflip: 5 } }), LEVELS);
    expect(res.profile.lifetime.tricks.backflip).toBe(5);
    expect(res.profile.achievements['tricks-10']).toBeUndefined();
  });

  test('two runs of 5 tricks do unlock it, on the second run', () => {
    const first = creditRun(v1(), rec({ tricks: { backflip: 5 } }), LEVELS).profile;
    const second = creditRun(first, rec({ id: 'run-2', ledgerHash: 'h2', endedAt: 2000, tricks: { frontflip: 5 } }), LEVELS);
    expect(second.awards.achievements.map((a) => a.id)).toContain('tricks-10');
    expect(second.profile.achievements['tricks-10']).toBe(2000);
  });
});

describe('ACH-5: combo progress starts from nothing', () => {
  test('a fresh profile with 0 runs shows no progress toward the combo achievements', () => {
    const m = metricsFrom(v1(), null, {});
    const shown = ACHIEVEMENTS.filter((a) => a.metric === 'bestCombo').map((a) => achShown(a, m));
    expect(shown.every((v) => v === 0)).toBe(true);
  });

  test('a recorded multiplier still reads through', () => {
    const p = v1({ lifetime: { bestCombo: 1.5 } });
    expect(metricsFrom(p, null, {}).bestCombo).toBe(1.5);
    expect(metricsFrom(v1(), { bestCombo: 1.25 }, {}).bestCombo).toBe(1.25);
  });
});

function achShown(a, m) { return progressFor(a, m).value; }

describe('ACH-3 (daily and streak half): creditRun feeds the evaluator dailyRuns and streak', () => {
  test('a run on a daily seed unlocks Daily Habit', () => {
    const res = creditRun(v1(), rec({ ...off('2026-11-13') }), LEVELS);
    expect(res.awards.achievements.map((a) => a.id)).toContain('daily-1');
    expect(res.profile.lifetime.dailyRuns).toBe(1);
  });

  test('an ordinary seed does not count as a daily run', () => {
    for (const seed of ['s', 'daily-2026-13-40', 'xdaily-2026-11-13', 'daily-2026-11-13@3']) {
      const res = creditRun(v1(), rec({ seed }), LEVELS);
      expect({ seed, daily: res.profile.achievements['daily-1'] }).toEqual({ seed, daily: undefined });
      expect(res.profile.lifetime.dailyRuns).toBe(0);
    }
  });

  test('a caller-supplied streak unlocks the streak achievements and is kept as the best streak', () => {
    const three = creditRun(v1(), rec({ ...off('2026-11-13') }), LEVELS, { streak: 3 });
    expect(three.awards.achievements.map((a) => a.id)).toEqual(expect.arrayContaining(['daily-1', 'streak-3']));
    expect(three.profile.achievements['streak-7']).toBeUndefined();
    expect(three.profile.lifetime.bestStreak).toBe(3);
    const seven = creditRun(three.profile, rec({ id: 'r2', ledgerHash: 'h2', ...off('2026-11-17') }), LEVELS, { streak: 7 });
    expect(seven.awards.achievements.map((a) => a.id)).toEqual(['streak-7']);
    // A broken streak later never lowers the best.
    const later = creditRun(seven.profile, rec({ id: 'r3', ledgerHash: 'h3', ...off('2026-11-30') }), LEVELS, { streak: 1 });
    expect(later.profile.lifetime.bestStreak).toBe(7);
  });

  test('the caller cannot feed biomesDiscovered through the same door', () => {
    const p = v1({ xp: 1e9 });
    const res = creditRun(p, rec(), LEVELS, { streak: 0, biomeCount: 11 });
    expect(['biomes-2', 'biomes-5', 'biomes-11'].filter((id) => res.profile.achievements[id] !== undefined)).toEqual([]);
  });

  test('the grid reads the stored counts, so an unlocked daily row is not shown at 0', () => {
    const res = creditRun(v1(), rec({ ...off('2026-11-13') }), LEVELS, { streak: 3 });
    const m = metricsFrom(res.profile, null, {});
    expect({ dailyRuns: m.dailyRuns, bestStreak: m.bestStreak }).toEqual({ dailyRuns: 1, bestStreak: 3 });
  });
});

describe('ACH-2: every combo achievement is reachable by the combo multiplier', () => {
  const maxMult = SCORING.comboStart + SCORING.comboStep * SCORING.comboStepTypes.length;
  const combos = () => ACHIEVEMENTS.filter((a) => a.metric === 'bestCombo');

  test('every bestCombo target is at or below the top multiplier', () => {
    expect(maxMult).toBe(2);
    expect(combos().filter((a) => a.target > maxMult).map((a) => a.id)).toEqual([]);
  });

  test('every target is a multiplier the game can produce (x1 plus whole combo steps)', () => {
    for (const a of combos()) {
      const steps = (a.target - SCORING.comboStart) / SCORING.comboStep;
      expect({ id: a.id, whole: Number.isInteger(steps) && steps >= 1 }).toEqual({ id: a.id, whole: true });
    }
  });

  test('the four combo achievements have four distinct targets, and 5/10/20 climb', () => {
    const t = Object.fromEntries(combos().map((a) => [a.id, a.target]));
    expect(new Set(Object.values(t)).size).toBe(4);
    expect(t['combo-5']).toBeLessThan(t['combo-10']);
    expect(t['combo-10']).toBeLessThan(t['combo-20']);
  });

  // Decision 9 (2026-11-14): ids stay (saves key on them) but the names climb with the targets. Before it,
  // this pinned the old names, with "Wireless Legend" at x1.75 and the x2.0 capstone listed first.
  test('ids are unchanged, names climb with the targets, and each description states its own target', () => {
    const want = { 'combo-2': 'Doubled Up', 'combo-5': 'Combo Starter', 'combo-10': 'Chain Reaction', 'combo-20': 'Unbroken' };
    for (const a of combos()) {
      expect({ id: a.id, name: a.name, states: a.desc.includes(`x${a.target}`) || a.desc.includes(`${a.target}x`) })
        .toEqual({ id: a.id, name: want[a.id], states: true });
    }
  });

  test('achievements.json carries the same combo entries as the built-in catalogue', () => {
    const json = read('src/data/achievements/achievements.json');
    const list = Array.isArray(json) ? json : json.achievements;
    const pick = (a) => ({ id: a.id, name: a.name, desc: a.desc, target: a.target });
    expect(list.filter((a) => a.metric === 'bestCombo').map(pick)).toEqual(combos().map(pick));
  });
});/**
 * W5 achievements — the gate the spec names explicitly:
 *   "each achievement has a test with a fixture that triggers it and one that just misses."
 *
 * So this file is deliberately mechanical: it walks the whole catalogue and, for every entry, asserts
 * BOTH that a fixture at the threshold unlocks it and that a fixture one unit short does not. A
 * hand-written test per achievement would drift from the data the first time someone edits a target;
 * driving off the catalogue means adding an achievement automatically adds its two cases.
 */
import {
  ACHIEVEMENTS, METRICS, achievementFor, metricsFrom, qualified, newlyUnlocked,
  stampNew, progressFor, groupedAchievements,
} from '../../src/systems/Achievements.js';

/** A profile whose lifetime block is all zeroes. */
const EMPTY_PROFILE = {
  v: 1, xp: 0, level: 1, bank: 0,
  lifetime: {
    runs: 0, distanceM: 0, playMs: 0, score: 0, tricks: {}, shards: 0, nearMisses: 0,
    bestScore: 0, bestDistanceM: 0, bestCombo: 1, maxAirtimeMs: 0,
  },
  achievements: {},
};

/** Build metrics that satisfy `def` exactly, by putting its target in the metric it reads. */
function metricsAt(def, value) {
  const m = {};
  for (const k of METRICS) m[k] = 0;
  m.level = 1;
  m.bestCombo = 1;
  m[def.metric] = value;
  return m;
}

describe('the catalogue', () => {
  test('ships about 25 achievements', () => {
    expect(ACHIEVEMENTS.length).toBeGreaterThanOrEqual(20);
    expect(ACHIEVEMENTS.length).toBeLessThanOrEqual(75);
  });

  test('ids are unique and non-empty', () => {
    const ids = ACHIEVEMENTS.map((a) => a.id);
    expect(new Set(ids).size).toBe(ids.length);
    for (const id of ids) expect(id).toMatch(/^[a-z0-9-]+$/);
  });

  test('every metric is one the evaluator can compute', () => {
    // A typo'd metric is the failure mode that looks fine forever: the achievement simply never unlocks.
    const bad = ACHIEVEMENTS.filter((a) => !METRICS.includes(a.metric)).map((a) => `${a.id}:${a.metric}`);
    expect(bad).toEqual([]);
  });

  test('every target is a positive finite number', () => {
    for (const a of ACHIEVEMENTS) {
      expect({ id: a.id, ok: Number.isFinite(a.target) && a.target > 0 }).toEqual({ id: a.id, ok: true });
    }
  });

  test('every achievement has a name, a description and a group', () => {
    for (const a of ACHIEVEMENTS) {
      expect(typeof a.name).toBe('string');
      expect(a.name.length).toBeGreaterThan(0);
      expect(typeof a.desc).toBe('string');
      expect(typeof a.group).toBe('string');
    }
  });

  test('covers all five families the spec names', () => {
    const groups = new Set(ACHIEVEMENTS.map((a) => a.group));
    for (const g of ['skill', 'distance', 'daily', 'collection', 'biomes']) expect(groups.has(g)).toBe(true);
  });

  test('rewards name a real cosmetic or a non-empty title', () => {
    for (const a of ACHIEVEMENTS.filter((x) => x.reward)) {
      const r = a.reward;
      const ok = (typeof r.cosmetic === 'string' && r.cosmetic.length > 0)
        || (typeof r.title === 'string' && r.title.length > 0);
      expect({ id: a.id, ok }).toEqual({ id: a.id, ok: true });
    }
  });
});

describe('every achievement triggers at its target and just misses below it', () => {
  // Driven off the catalogue, so a new achievement cannot ship without both cases.
  for (const def of ACHIEVEMENTS) {
    test(`${def.id} (${def.metric} >= ${def.target})`, () => {
      const hit = qualified(metricsAt(def, def.target));
      expect(hit.map((a) => a.id)).toContain(def.id);

      // One unit short must NOT unlock. For a threshold of 1 there is no smaller positive value, so the
      // miss case is 0 (which is also the honest "has not done it at all" state).
      const miss = def.target > 1 ? def.target - 1 : 0;
      const missed = qualified(metricsAt(def, miss));
      expect(missed.map((a) => a.id)).not.toContain(def.id);
    });
  }
});

describe('metricsFrom', () => {
  test('an empty profile and no run yields zeros, not NaN', () => {
    const m = metricsFrom(null, null);
    for (const k of METRICS) expect(Number.isFinite(m[k])).toBe(true);
    expect(m.runs).toBe(0);
    expect(m.level).toBe(1);
  });

  test('a finished run folds its own values in when the profile has not been credited yet', () => {
    // Order of operations matters: the evaluator may run before the credit lands, so the run's own
    // distance/score have to count or the achievement arrives one run late.
    const m = metricsFrom(EMPTY_PROFILE, { distanceM: 1200, score: 11000, bestCombo: 3, maxAirtimeMs: 2100 });
    expect(m.bestDistanceM).toBe(1200);
    expect(m.bestScore).toBe(11000);
    expect(m.bestCombo).toBe(3);
    expect(m.maxAirtimeMs).toBe(2100);
  });

  test('a credited run is not double-counted into the bests', () => {
    const p = { ...EMPTY_PROFILE, lifetime: { ...EMPTY_PROFILE.lifetime, bestDistanceM: 1200, bestScore: 11000 } };
    const m = metricsFrom(p, { distanceM: 1200, score: 11000 });
    expect(m.bestDistanceM).toBe(1200);
    expect(m.bestScore).toBe(11000);
  });

  test('trick kinds counts distinct names across lifetime and the run', () => {
    const p = { ...EMPTY_PROFILE, lifetime: { ...EMPTY_PROFILE.lifetime, tricks: { ollie: 3, spin: 0 } } };
    const m = metricsFrom(p, { tricks: { spin: 2, grab: 1 } });
    // `spin: 0` in the lifetime is not a landed trick and must not count as a kind.
    expect(m.trickKinds).toBe(3);
    expect(m.tricksLanded).toBe(6);
  });

  test('caller-owned facts are respected', () => {
    const m = metricsFrom(EMPTY_PROFILE, null, { biomeCount: 5, streak: 7, dailyRuns: 4 });
    expect(m.biomesDiscovered).toBe(5);
    expect(m.bestStreak).toBe(7);
    expect(m.dailyRuns).toBe(4);
  });

  test('a junk profile does not throw', () => {
    for (const p of [undefined, null, 42, 'x', {}, { lifetime: 5 }]) {
      expect(() => metricsFrom(p, null)).not.toThrow();
    }
  });
});

describe('unlocks once', () => {
  test('newlyUnlocked excludes what the profile has, in either storage shape', () => {
    const metrics = metricsAt({ metric: 'runs', target: 10 }, 10);
    expect(newlyUnlocked(metrics, {}).map((a) => a.id)).toContain('ten-runs');
    expect(newlyUnlocked(metrics, { 'ten-runs': 1000 }).map((a) => a.id)).not.toContain('ten-runs');
    expect(newlyUnlocked(metrics, [{ id: 'ten-runs', at: 1000 }]).map((a) => a.id)).not.toContain('ten-runs');
    expect(newlyUnlocked(metrics, ['ten-runs']).map((a) => a.id)).not.toContain('ten-runs');
  });

  test('stampNew records the caller timestamp and refuses to restamp', () => {
    const first = stampNew({}, [{ id: 'ten-runs' }, { id: 'first-descent' }], 5000);
    expect(first.store).toEqual({ 'ten-runs': 5000, 'first-descent': 5000 });
    expect(first.added).toHaveLength(2);

    const again = stampNew(first.store, [{ id: 'ten-runs' }], 9999);
    expect(again.store['ten-runs']).toBe(5000); // history is not rewritten
    expect(again.added).toHaveLength(0);
  });

  test('a non-finite timestamp stores nothing rather than NaN', () => {
    for (const at of [undefined, null, NaN, Infinity, 'now']) {
      const r = stampNew({}, [{ id: 'ten-runs' }], at);
      expect(r.store).toEqual({});
      expect(r.added).toEqual([]);
    }
  });

  test('evaluating the same state twice is idempotent', () => {
    const metrics = metricsAt({ metric: 'combo', target: 10 }, 10);
    metrics.bestCombo = 10;
    const once = stampNew({}, newlyUnlocked(metrics, {}), 1000);
    const twice = stampNew(once.store, newlyUnlocked(metrics, once.store), 2000);
    expect(twice.added).toEqual([]);
    expect(twice.store).toEqual(once.store);
  });
});

describe('progressFor', () => {
  test('reports a clamped ratio and a done flag', () => {
    const def = achievementFor('dist-5k');
    expect(progressFor(def, { bestDistanceM: 0 })).toMatchObject({ value: 0, target: 5000, ratio: 0, done: false });
    expect(progressFor(def, { bestDistanceM: 2500 })).toMatchObject({ value: 2500, ratio: 0.5, done: false });
    expect(progressFor(def, { bestDistanceM: 5000 })).toMatchObject({ done: true, ratio: 1 });
