function bareDirector(featuredStem = 'guitar') {
	const director = Object.create(StemMusicDirector.prototype);
	const gainCalls=[];
	const effectCalls=[];
	director.mixer = {
		setGain: (...args) => {gainCalls.push(args);return true;},
		setEffectParam: (...args) => {effectCalls.push(args);return true;},
		selectBiome: jest.fn(),
