  s._playerHopElapsedMs=TUNING.hopMinimumHoldMs+2;
  step(s,{hop:false,variableHop:true,airBrake:false,noAutoNudge:true,pressed:{}});
  expect(s._playerHopActive).toBe(false);
  expect(s._protectedHopExtraVyPxS).toBe(0);
