});// Phaser-free logic behind Sled.applyControls: hands-off air rotation (flip release window) and the stall safety net.
import { TUNING, airIdleSpin, stallNudgeStep } from '../../src/systems/PhysicsTuner.js';

const DEG = Math.PI / 180;
const wrap = (a) => Math.atan2(Math.sin(a), Math.cos(a));

/** Hands-off sled in flight at constant velocity (heading 0): spin it from `angleDeg` at `wDegS`, return the state after `ms`. */
function coast(angleDeg, wDegS, ms, vx = 500, vy = 0) {
  const h = 1 / 125;
  let a = angleDeg * DEG;
  let w = wDegS * DEG;
  for (let t = 0; t < ms / 1000 - 1e-9; t += h) {
    w = airIdleSpin(w, a, vx, vy, h);
    a += w * h;
  }
  return { angleDeg: a / DEG, wDegS: w / DEG, errDeg: wrap(Math.atan2(vy, vx) - a) / DEG };
}

describe('airIdleSpin (hands-off air rotation)', () => {
  test('a level sled with no spin stays put', () => {
    expect(airIdleSpin(0, 0, 500, 0, 0.008)).toBeCloseTo(0, 10);
  });

  test('spin decays and the nose comes back to the heading', () => {
    const r = coast(40, 300, 600);
    expect(Math.abs(r.wDegS)).toBeLessThan(10);
    expect(Math.abs(r.errDeg)).toBeLessThan(10);
  });

  test('it levels the SHORT way: 200 deg round and still spinning the same way, it finishes the turn instead of unwinding', () => {
    // 200 deg clockwise of level: the nearest level is the next one (160 deg on), not the one 200 deg back
    const r = coast(200, 600, 500);
    expect(r.angleDeg).toBeGreaterThan(330);
    expect(Math.abs(r.errDeg)).toBeLessThan(15);
  });

  test('flip release window: a held flip let go at 200-340 deg of rotation is level again within 0.3 s, at 420 deg within 0.45 s', () => {
    for (const [deg, ms, tol] of [[200, 300, 25], [270, 300, 25], [340, 300, 25], [420, 450, 25]]) {
      // a held flip (counter-clockwise, negative angle) released at `deg` of rotation spinning at the capped rate
      const r = coast(-deg, -TUNING.maxAngularVelDegS, ms);
      expect(Math.abs(r.errDeg)).toBeLessThan(tol);
      expect(Math.abs(r.wDegS)).toBeLessThan(250);
    }
  });

  test('a sled released less than half a turn in unwinds back instead of tumbling on', () => {
    const r = coast(-60, -400, 400);
    expect(Math.abs(r.errDeg)).toBeLessThan(10);
    expect(r.angleDeg).toBeGreaterThan(-100);
  });

  test('the spin cap still allows a double flip in 1.4 s of held tilt, but not in 1.0 s', () => {
    const torque = 420 * 0.7 * TUNING.airTiltFeelMul; // deg/s^2 in the air at full tilt (maxTiltTorque x airControlFactor x feel)
    const held = (sec) => {
      let w = 0;
      let rot = 0;
      for (let t = 0; t < sec; t += 0.002) {
        w = Math.min(TUNING.maxAngularVelDegS, w + torque * 0.002);
        rot += w * 0.002;
      }
      return rot;
    };
    expect(held(1.4)).toBeGreaterThan(720);
    expect(held(1.0)).toBeLessThan(720);
  });
});

/** Same as coast() but with the landing forecast RunScene feeds Sled: ground slope at touchdown and ms left in the air. */
function levelWith(angleDeg, wDegS, airMs, slopeDeg, vx = 600, vy = 300) {
  const h = 1 / 125;
  let a = angleDeg * DEG;
  let w = wDegS * DEG;
  for (let t = 0; t < airMs / 1000 - 1e-9; t += h) {
    w = airIdleSpin(w, a, vx, vy, h, TUNING, { etaMs: airMs - t * 1000, slopeDeg });
    w = Math.max(-TUNING.maxAngularVelDegS * DEG, Math.min(TUNING.maxAngularVelDegS * DEG, w));
    a += w * h;
  }
  return { angleDeg: a / DEG, errDeg: wrap(a - slopeDeg * DEG) / DEG };
}

describe('airIdleSpin with a landing forecast (late / early flip release)', () => {
  const slope = 12;
  const rest = slope + TUNING.airIdleLandOffsetDeg; // where a hands-off sled settles: slightly nose-down of the slope, a "good" landing

  test('without a forecast nothing changed: it still aims at the velocity heading', () => {
    expect(airIdleSpin(0, 0.3, 500, 0, 0.008)).toBeLessThan(0);
    expect(airIdleSpin(0, -0.3, 500, 0, 0.008, TUNING, null)).toBeGreaterThan(0);
  });

  test('with a forecast it settles at the slope plus the landing offset, not at the heading', () => {
    const r = levelWith(rest + 30, 0, 800, slope);
    expect(Math.abs(wrap((r.angleDeg - rest) * DEG) / DEG)).toBeLessThan(3);
    expect(Math.abs(r.errDeg)).toBeGreaterThan(8); // not a free perfect landing
    expect(Math.abs(r.errDeg)).toBeLessThan(20); // but safely inside the "good" band (28)
  });

  test('levelling gets stronger as the ground gets closer', () => {
    const far = Math.abs(airIdleSpin(0, 1, 600, 300, 0.008, TUNING, { etaMs: 1000, slopeDeg: slope }));
    const near = Math.abs(airIdleSpin(0, 1, 600, 300, 0.008, TUNING, { etaMs: 150, slopeDeg: slope }));
    const nearer = Math.abs(airIdleSpin(0, 1, 600, 300, 0.008, TUNING, { etaMs: 80, slopeDeg: slope }));
    expect(near).toBeGreaterThan(far * 2);
    expect(nearer).toBeLessThanOrEqual(near * (TUNING.airIdleUrgencyMax / 2) ** 2 + 1e-9); // capped
    expect(airIdleSpin(0, 1, 600, 300, 0.008, TUNING, { etaMs: 1, slopeDeg: slope })).toBeCloseTo(airIdleSpin(0, 1, 600, 300, 0.008, TUNING, { etaMs: 10, slopeDeg: slope }), 6);
  });

  test('a flip let go anywhere in 0.4-0.85 s of held tilt lands level with >= 270 ms of air left, however late', () => {
    const torque = 420 * 0.7 * TUNING.airTiltFeelMul;
    for (const holdMs of [450, 550, 650, 750, 850]) {
      let w = 0;
      let rot = 0;
      for (let t = 0; t < holdMs / 1000; t += 0.002) { w = Math.min(TUNING.maxAngularVelDegS, w + torque * 0.002); rot += w * 0.002; }
      const r = levelWith(-rot, -w, 270, slope);
      expect(Math.abs(r.errDeg)).toBeLessThan(28);
    }
  });

  test('a release at the half-turn tipping point (140 deg round, 270 ms left) still comes down level either way', () => {
    expect(Math.abs(levelWith(-140, -630, 270, slope).errDeg)).toBeLessThan(28);
    expect(Math.abs(levelWith(-170, -700, 270, slope).errDeg)).toBeLessThan(28);
  });

  test('but a sled released inverted with almost no air left still crashes', () => {
    for (const ms of [30, 50, 70]) expect(Math.abs(levelWith(-180, -600, ms, slope).errDeg)).toBeGreaterThan(55);
  });

  test('a sled released inverted with 100 ms left does not get a free landing either', () => {
    expect(Math.abs(levelWith(-170, -800, 100, slope).errDeg)).toBeGreaterThan(28);
  });
});

describe('stallNudgeStep (stall safety net)', () => {
  const base = { grounded: true, braking: false, slopeDeg: 0, vx: 0, vy: 0, stepMs: 8, gravityPxS2: 900 };
  /** Run the net for `ms` with the sled held at the given velocity; returns the final state. */
  function hold(inputs, ms) {
    let st = { crawlMs: 0, nudging: false };
    let last = { dvx: 0, dvy: 0 };
    for (let t = 0; t < ms; t += 8) {
      last = stallNudgeStep(st, { ...base, ...inputs }, TUNING);
      st = { crawlMs: last.crawlMs, nudging: last.nudging };
    }
    return { st, last };
  }

  test('a stopped sled on flat ground is pushed forward after stallNudgeAfterMs, not before', () => {
    expect(hold({}, TUNING.stallNudgeAfterMs - 20).st.nudging).toBe(false);
    const r = hold({}, TUNING.stallNudgeAfterMs + 40);
    expect(r.st.nudging).toBe(true);
    expect(r.last.dvx).toBeGreaterThan(0);
  });

  test('rolling BACKWARDS faster than the crawl speed still counts as stalled (speed magnitude is not the test)', () => {
    // 12 deg up-slope: tangent points up the hill (slope negative); rolling back down the hill at 55 px/s
    const slope = -12;
    const back = { slopeDeg: slope, vx: -55 * Math.cos(slope * DEG), vy: -55 * Math.sin(slope * DEG) };
    const r = hold(back, TUNING.stallNudgeAfterMs + 40);
    expect(r.st.nudging).toBe(true);
    expect(r.last.dvx).toBeGreaterThan(0); // pushes up the hill (+x)
    expect(r.last.dvy).toBeLessThan(0);
  });

  test('on an up-slope the push cancels gravity along the slope: net acceleration equals stallNudgeAccelPxS2', () => {
    const slope = -12;
    const r = hold({ slopeDeg: slope }, TUNING.stallNudgeAfterMs + 40);
    const dv = Math.hypot(r.last.dvx, r.last.dvy);
    const dt = 0.008;
    const gravAlong = 900 * Math.sin(12 * DEG);
    expect(dv / dt).toBeCloseTo(TUNING.stallNudgeAccelPxS2 + gravAlong, 3);
  });

  test('never pushes a sled that moves forward at or above the crawl speed', () => {
    for (const slope of [-12, -4, 0, 6, 12]) {
      const v = TUNING.stallNudgeBelowPxS + 5;
      const r = hold({ slopeDeg: slope, vx: v * Math.cos(slope * DEG), vy: v * Math.sin(slope * DEG) }, 3000);
      expect(r.st.nudging).toBe(false);
      expect(r.last.dvx).toBe(0);
      expect(Math.abs(r.last.dvy)).toBe(0);
    }
  });

  test('never pushes while braking, airborne or on steep ground', () => {
    expect(hold({ braking: true }, 3000).st.nudging).toBe(false);
    expect(hold({ grounded: false }, 3000).st.nudging).toBe(false);
    expect(hold({ slopeDeg: TUNING.stallNudgeMaxSlopeDeg + 1 }, 3000).st.nudging).toBe(false);
    expect(hold({ slopeDeg: -(TUNING.stallNudgeMaxSlopeDeg + 1) }, 3000).st.nudging).toBe(false);
  });

  test('the crawl timer restarts when the brake is touched', () => {
    let st = { crawlMs: 0, nudging: false };
    for (let t = 0; t < 500; t += 8) st = (({ crawlMs, nudging }) => ({ crawlMs, nudging }))(stallNudgeStep(st, base, TUNING));
    st = (({ crawlMs, nudging }) => ({ crawlMs, nudging }))(stallNudgeStep(st, { ...base, braking: true }, TUNING));
    expect(st.crawlMs).toBe(0);
  });

  test('once started it keeps pushing until the target speed, then stops', () => {
    let st = { crawlMs: 0, nudging: false };
    let vx = 0;
    for (let t = 0; t < 4000; t += 8) {
      const r = stallNudgeStep(st, { ...base, vx }, TUNING);
      vx += r.dvx;
      st = { crawlMs: r.crawlMs, nudging: r.nudging };
    }
    expect(vx).toBeCloseTo(TUNING.stallNudgeToPxS, 3);
    expect(st.nudging).toBe(false);
    expect(vx).toBeGreaterThan(120);
  });
});import { jest } from '@jest/globals';
import { EventEmitter } from 'events';
import { AudioSynth } from '../../src/systems/AudioSynth.js';
import { EVT } from '../../src/events.js';

const makeAudio = () => {
  const events = new EventEmitter();
  const a = new AudioSynth({ events });
  const param = () => ({ setTargetAtTime: jest.fn() });
  a.nodes = {
    master: { gain: param() }, musicBus: { gain: param() }, sfxBus: { gain: param() },
    windGain: { gain: param() }, windFilter: { frequency: param() },
    musicFilter: { frequency: param() }, musicSrc: { gain: param() },
  };
  a.ctx = { currentTime: 10, close: jest.fn() };
  a.settings = { windEnabled: true, windVolume: 1 };
  a._stemMusic.setSpeed = jest.fn();
  return { a, events, gain: a.nodes.windGain.gain.setTargetAtTime };
};
const state = (overrides = {}) => ({
  active: true, gapPx: 400, wallSpeedPxS: 300,
  worldTailwindPxS: 850, sledVelocityXPxS: 100,
  relativeAirX: 750, proximity01: 0.7,
  timeToImpactMs: 1200, atmosphereDensity: 1, ...overrides,
});

describe('authoritative BSOD wind signal consumed read-only', () => {
  test('positive and negative relative airflow have the same loudness', () => {
    const { a, events, gain } = makeAudio();
    events.emit(EVT.BSOD_STATE_CHANGED, state({ relativeAirX: 750 }));
    const positive = gain.mock.lastCall[0];
    events.emit(EVT.BSOD_STATE_CHANGED, state({ relativeAirX: -750 }));
    expect(positive).toBeGreaterThan(0);
    expect(gain.mock.lastCall[0]).toBeCloseTo(positive);
    a.destroy();
  });
  test('velocity matching is silent even at maximum danger; speed still drives music', () => {
    const { a, events, gain } = makeAudio();
    events.emit(EVT.BSOD_STATE_CHANGED, state({ relativeAirX: 0, proximity01: 1 }));
    expect(gain.mock.lastCall[0]).toBe(0);
    expect(a._bsodDanger01).toBe(1);
    a._ready = () => true;
    const count = gain.mock.calls.length;
    a.setSpeed(950);
    expect(a._stemMusic.setSpeed).toHaveBeenCalledWith(950);
    expect(a._speedIntensity).toBeCloseTo(0.95);
    expect(gain).toHaveBeenCalledTimes(count);
    a.destroy();
  });

  test('wind mute, wind slider and pause affect audio only', () => {
    const { a, events, gain } = makeAudio();
    events.emit(EVT.BSOD_STATE_CHANGED, state());
    const loud = gain.mock.lastCall[0];
    a.settings.windVolume = 0.5;
    a._applyWindFromBsod();
    expect(gain.mock.lastCall[0]).toBeCloseTo(loud * 0.5);
    a.settings.windEnabled = false;
    a._applyWindFromBsod();
    expect(gain.mock.lastCall[0]).toBe(0);
    expect(a._bsodDanger01).toBe(0.7);
    a.settings.windEnabled = true;
    a._setPaused(true);
    expect(gain.mock.lastCall[0]).toBe(0);
    a._setPaused(false);
    expect(gain.mock.lastCall[0]).toBeCloseTo(loud * 0.5);
    a.destroy();
  });
  test('vacuum and inactive snapshots explicitly silence wind without silencing danger', () => {
    const { a, events, gain } = makeAudio();
    events.emit(EVT.BSOD_STATE_CHANGED, state({
      atmosphereDensity: 0, worldTailwindPxS: 0, relativeAirX: 0, proximity01: 1,
    }));
    expect(gain.mock.lastCall[0]).toBe(0);
    expect(a._bsodDanger01).toBe(1);
    events.emit(EVT.BSOD_STATE_CHANGED, state({
      atmosphereDensity: 0.25, relativeAirX: 1000,
    }));
    expect(gain.mock.lastCall[0]).toBeCloseTo(0.055);
    events.emit(EVT.BSOD_STATE_CHANGED, { active: false });
    expect(gain.mock.lastCall[0]).toBe(0);
    expect(a._bsodDanger01).toBe(0);
    a.destroy();
  });

  test('run end and abort reset state; listener cleanup is complete', () => {
    const { a, events, gain } = makeAudio();
    a.stopMusic = jest.fn();
    events.emit(EVT.BSOD_STATE_CHANGED, state());
    events.emit(EVT.RUN_END, {});
    expect(gain.mock.lastCall[0]).toBe(0);
    expect(a._bsodDanger01).toBe(0);
    events.emit(EVT.BSOD_STATE_CHANGED, state());
    events.emit(EVT.RUN_ABORT, {});
    expect(gain.mock.lastCall[0]).toBe(0);
    a.destroy();
    expect(events.listenerCount(EVT.BSOD_STATE_CHANGED)).toBe(0);
  });
  test('headless subscription, invalid numeric state and source event are safe', () => {
    const game = { events: new EventEmitter() };
    const a = new AudioSynth(game);
    expect(() => game.events.emit(EVT.BSOD_STATE_CHANGED,
      state({ relativeAirX: NaN, atmosphereDensity: Infinity, proximity01: NaN })))
      .not.toThrow();
    expect(a._windRelativePxS).toBe(0);
    expect(a._bsodDanger01).toBe(0);
    expect(() => game.events.emit(EVT.BSOD_STATE_CHANGED, null)).not.toThrow();
    a.destroy();
    expect(game.events.listenerCount(EVT.BSOD_STATE_CHANGED)).toBe(0);
  });
  test('throwing music and WebAudio consumers never abort BSOD signal propagation',()=>{
    const {a,events,gain}=makeAudio();
    a._stemMusic.setBsodDanger=jest.fn(()=>{throw Error('DSP failed')});
    expect(()=>events.emit(EVT.BSOD_STATE_CHANGED,state())).not.toThrow();
    expect(gain).toHaveBeenCalled();
    a._stemMusic.setBsodDanger=jest.fn();
    const original=a.nodes.windGain.gain.setTargetAtTime;
    a.nodes.windGain.gain.setTargetAtTime=jest.fn(()=>{throw Error('closed AudioParam')});
    expect(()=>events.emit(EVT.BSOD_STATE_CHANGED,state({proximity01:0.99}))).not.toThrow();
    expect(a._stemMusic.setBsodDanger).toHaveBeenCalledWith(0.99);
    a.nodes.windGain.gain.setTargetAtTime=original;
    events.emit(EVT.BSOD_STATE_CHANGED,state({relativeAirX:1000}));
    expect(gain.mock.lastCall[0]).toBeGreaterThan(0);
    a.destroy();
  });
  test('settings event actually toggles environmental wind with music disabled', () => {
    const { a, events, gain } = makeAudio();
    events.emit(EVT.BSOD_STATE_CHANGED, state());
    const makeSettings = (windEnabled) => ({
      masterVolume: 1, musicVolume: 0, sfxVolume: 0,
      windVolume: 0.6, windEnabled,
      musicEnabledSongs: { '01_FEsxYVStla4': false,
        '03_WRBGQUqD54U': false, '31_FYImnz5-hXs': false,
        '33_local-one-more-run-bitstream-bluffs': false },
    });
    events.emit(EVT.SETTINGS_CHANGED, { settings: makeSettings(false) });
    expect(a.settings.windEnabled).toBe(false);
    expect(gain.mock.lastCall[0]).toBe(0);
    events.emit(EVT.SETTINGS_CHANGED, { settings: makeSettings(true) });
    expect(a.settings.windEnabled).toBe(true);
    expect(gain.mock.lastCall[0]).toBeGreaterThan(0);
    a.destroy();
  });
});import {jest} from '@jest/globals';
import {EventEmitter} from 'events';
import {AudioSynth} from '../../src/systems/AudioSynth.js';
import {EVT} from '../../src/events.js';
import {defaultSongSelection} from '../../src/systems/music/MusicPlaylist.js';
import {VINYL_SCRATCH_SECONDS} from '../../src/systems/music/TurntableScratch.js';

const fakeParam=()=>({setTargetAtTime:jest.fn(),cancelScheduledValues:jest.fn()});
function setup() {
  const events=new EventEmitter();
  const a=new AudioSynth({events});
  const ctx={currentTime:42,state:'running',close:jest.fn()};
  a.ctx=ctx;
  a.nodes={
    musicFilter:{frequency:fakeParam()},musicSrc:{gain:fakeParam()},
    windGain:{gain:fakeParam()},windFilter:{frequency:fakeParam()},
    master:{gain:fakeParam()},musicBus:{gain:fakeParam()},sfxBus:{gain:fakeParam()},
  };
  a.settings={masterVolume:.8,musicVolume:.6,sfxVolume:.8,
    musicEnabledSongs:defaultSongSelection(),windEnabled:true,windVolume:1};
  const d={started:true,ready:true,disposed:false,transportPaused:false,
    pack:{duration:180,id:'one-more-run'},track:{id:'one-more-run'},
    catalog:[{id:'one-more-run'},{id:'other-track'}],
    ctx,clockStart:20,activeNodes:new Set([{}]),trackIndex:0,
    _resumeOffset:0,_token:8,_loading:null,stop:jest.fn(),
    transportPause:jest.fn(function(){
      if(!this.started)return false;
      this._resumeOffset=ctx.currentTime-this.clockStart;
      this.started=false;this.transportPaused=true;
      this._token++;
      this.activeNodes.clear();
      return true;
    }),
    transportPlay:jest.fn(function(){
      if(this.started)return true;
      this.started=true;this.transportPaused=false;
      return true;
    }),
    transportStep:jest.fn(function(){
      this.started=false;this._resumeOffset=0;
      this.trackIndex=1;this.track=this.catalog[1];this._token++;
      return true;
    }),
    attach:jest.fn(),applySettings:jest.fn(),setMenuMode:jest.fn(),
    setBsodDanger:jest.fn(),
  };
  a._stemMusic=d;
  a._musicWanted=true;
  a._vinylScratch={play:jest.fn(()=>VINYL_SCRATCH_SECONDS),cancel:jest.fn(),destroy:jest.fn()};
  a.unlock=jest.fn();
  a._ensureCtx=jest.fn(()=>true);
  a._activateStemMusic=jest.fn(()=>true);
  return {a,d,ctx,events};
}

describe('user vinyl pause/resume owns only ONE preserved stem transport',()=>{
  beforeEach(()=>jest.useFakeTimers());
  afterEach(()=>{jest.clearAllTimers();jest.useRealTimers();});

  test('GAME_PAUSE freezes soundtrack source frame BEFORE scratch, resume scratch THEN same song offset',()=>{
    const {a,d,events,ctx}=setup();
    events.emit(EVT.GAME_PAUSE,{runTimeMs:3000});
    expect(a._paused).toBe(true);
    expect(d.transportPause).toHaveBeenCalledTimes(1);
    expect(d.started).toBe(false);
    expect(d._resumeOffset).toBe(22);
    expect(d.transportPaused).toBe(true);
    expect(a._musicWanted).toBe(false);
    expect(a._vinylScratch.play).toHaveBeenCalledWith('pause');
    expect(a.nodes.musicSrc.gain.setTargetAtTime.mock.lastCall[0]).toBe(0);
    expect(a.getBeatTiming()).toMatchObject({trusted:false,release:'immediate'});
    events.emit(EVT.GAME_RESUME,{runTimeMs:3000});
    expect(a._paused).toBe(false);
    expect(a._vinylScratch.play).toHaveBeenCalledWith('resume');
    expect(d.transportPlay).not.toHaveBeenCalled();
    jest.advanceTimersByTime(204);
    expect(d.transportPlay).not.toHaveBeenCalled();
    jest.advanceTimersByTime(1);
    expect(d.transportPlay).toHaveBeenCalledTimes(1);
    expect(d._resumeOffset).toBe(22);
    expect(d.trackIndex).toBe(0);
    expect(a._musicWanted).toBe(true);
    a.destroy();
  });

  test('rapid pause/resume supersedes scheduled old starts; never duplicates streams',()=>{
    const {a,d,events}=setup();
    events.emit(EVT.GAME_PAUSE,{});
    events.emit(EVT.GAME_RESUME,{});
    jest.advanceTimersByTime(70);
    events.emit(EVT.GAME_PAUSE,{});
    expect(a._vinylScratch.cancel).toHaveBeenCalled();
    expect(d.transportPause).toHaveBeenCalledTimes(1);
    jest.advanceTimersByTime(1000);
    expect(d.transportPlay).not.toHaveBeenCalled();
    events.emit(EVT.GAME_RESUME,{});
    jest.advanceTimersByTime(205);
    expect(d.transportPlay).toHaveBeenCalledTimes(1);
    events.emit(EVT.GAME_RESUME,{});
    jest.advanceTimersByTime(1000);
    expect(d.transportPlay).toHaveBeenCalledTimes(1);
    a.destroy();
  });

  test.each([0,.000])('muted master volume %s freezes/resumes WITHOUT scratch',level=>{
    const {a,d,events}=setup();
    a.settings.masterVolume=level;
    events.emit(EVT.GAME_PAUSE,{});
    expect(d.transportPause).toHaveBeenCalledTimes(1);
    expect(a._vinylScratch.play).not.toHaveBeenCalled();
    events.emit(EVT.GAME_RESUME,{});
    expect(d.transportPlay).toHaveBeenCalledTimes(1);
    expect(a._vinylScratch.play).not.toHaveBeenCalled();
    a.destroy();
  });

  test('muted music and disabled song selection never emit scratch',()=>{
    for(const mute of ['music','allSongs']){
      const {a,d,events}=setup();
      if(mute==='music')a.settings.musicVolume=0;
      else a.settings.musicEnabledSongs=Object.fromEntries(
        Object.keys(a.settings.musicEnabledSongs).map(id=>[id,false]));
      events.emit(EVT.GAME_PAUSE,{});
      expect(a._vinylScratch.play).not.toHaveBeenCalled();
      events.emit(EVT.GAME_RESUME,{});
      expect(a._vinylScratch.play).not.toHaveBeenCalled();
      expect(d.transportPlay).toHaveBeenCalledTimes(mute==='music'?1:0);
      a.destroy();
    }
  });

  test('game death/crash and run-abort never trigger a vinyl scratch',()=>{
    const {a,d,events}=setup();
    a.playSfx=jest.fn();
    events.emit(EVT.CRASH,{});
    expect(a._vinylScratch.play).not.toHaveBeenCalled();
    events.emit(EVT.RUN_END,{});
    expect(a._vinylScratch.play).not.toHaveBeenCalled();
    expect(a._vinylPauseSession).toBeNull();
    events.emit(EVT.RUN_ABORT,{});
    expect(a._vinylScratch.play).not.toHaveBeenCalled();
    a.destroy();
  });

  test('RUN_ABORT during optional reverse scratch cancels timer but restores continuous menu soundtrack exactly once',()=>{
    const {a,d,events}=setup();
    events.emit(EVT.GAME_PAUSE,{});
    const saved=d._resumeOffset;
    events.emit(EVT.GAME_RESUME,{});
    expect(a._vinylResume).not.toBeNull();
    events.emit(EVT.RUN_ABORT,{reason:'quit'});
    expect(a._vinylResume).toBeNull();
    expect(d.transportPlay).toHaveBeenCalledTimes(1);
    expect(d._resumeOffset).toBe(saved);
    expect(d.started).toBe(true);
    expect(a._musicMode).toBe('menu');
    jest.advanceTimersByTime(1000);
    expect(d.transportPlay).toHaveBeenCalledTimes(1);
    expect(a._vinylPauseSession).toBeNull();
    expect(a._vinylScratch.play).toHaveBeenCalledTimes(2);
    a.destroy();
  });

  test('RUN_ABORT directly from PauseScene resumes same original soundtrack without vinyl on quit',()=>{
    const {a,d,events}=setup();
    events.emit(EVT.GAME_PAUSE,{reason:'manual',pauseToken:'run:1'});
    const stopped=d._resumeOffset;
    events.emit(EVT.RUN_ABORT,{reason:'quit',pauseToken:'run:1'});
    expect(d.transportPlay).toHaveBeenCalledTimes(1);
    expect(d._resumeOffset).toBe(stopped);
    expect(a._musicMode).toBe('menu');
