// Minimal fixed-tick scene contract. The real-browser benchmark makes the same
// reference/timed comparison with the production RunScene and TapePlayer.
function makeGame() {
  const body = { position: { x: 0, y: 1 }, angle: 0, velocity: { x: 0, y: 0 }, angularVelocity: 0 };
  const run = {
    sled: { body }, score: { getTotal: () => body.position.x * 10 },
    simClock: new SimClock(), tapePlayer: new TapePlayer(defaultTape()),
    runRandom: { physicsScramble: { state: 42 } },
    simTick(dt, pad) {
      this.sled.body.position.x += dt + Number(pad.push);
      this.crashed = this.simClock.tick === 4;
    },
  };
  const schedule = [];
  const game = {
    scene: { getScene: () => run }, registry: { get: () => undefined },
    step(time, dt) {
      schedule.push([time, dt]);
      for (let n = run.simClock.advance(dt); n > 0; n--) {
        run.simTick(dt, run.tapePlayer.padAt(++run.simClock.tick));
      }
    },
  };
  return { game, run, schedule };
}

test('changing the measurement clock changes timing data but not tick schedule or result', () => {
  const first = makeGame();
  const reference = replayFrames({ tickLimit: 9, measure: false, keys: replayKeys }, first.game, () => {
    throw new Error('Reference must not read the measurement clock');
  });
  expect(reference.tick).toBe(4);
  expect(reference.crashed).toBe(true);
  expect(reference.tickTimes).toEqual([]);
  const timed = [1, 10_000].map((increment) => {
    const next = makeGame();
    const originalTick = next.run.simTick;
    let reading = 0;
    const result = replayFrames({ tickLimit: 9, measure: true, keys: replayKeys }, next.game, () => reading += increment);
    expect(next.run.simTick).toBe(originalTick);
    expect(next.schedule).toEqual(first.schedule);
    expect(result.states).toEqual(reference.states);
    expect(result.tickTimes).toEqual(Array(4).fill(increment));
    return result;
  });
  expect(summarize(timed[0].frameTimes)).not.toEqual(summarize(timed[1].frameTimes));
});

test('step failures restore the original tick method and do not report a partial result', () => {
  const { game, run } = makeGame();
  const originalTick = run.simTick;
  game.step = () => { throw new Error('failed frame'); };
  expect(() => replayFrames({ tickLimit: 9, measure: true, keys: replayKeys }, game)).toThrow('failed frame');
  expect(run.simTick).toBe(originalTick);
});

test('saved tape cannot pass on an early crash even if all earlier checks agree', () => {
  const tape = { checkpoints: [[2]] };
  const result = { tick: 4, crashed: true, checked: 1, savedRecord: false, droppedMs: 0, desync: null, states: [[]] };
  expect(() => assertReplay(result, tape, 5, false)).not.toThrow();
  expect(() => assertReplay(result, tape, 5, true)).toThrow(/without crashing/);
  expect(() => assertReplay(result, tape, 4, true)).toThrow(/without crashing/);
  expect(() => assertReplay({ ...result, tick: 5, crashed: false }, tape, 5, true)).not.toThrow();
});/**
 * B1 "Wards" content (spec §4 table and bounds): the biome hazard and power-up of Debutmont, Garbage Dump Glacier,
 * Underwater Mountain and Candy Cane Canyon. Loader + schema check for the new JSON, the values the spec names, and the
 * pairing rule (each ward switches off something its own biome has).
 */
import { readDir, loadContent, makeGen } from './_helpers.js';
import { PALETTE_KEYS } from '../../src/constants.js';
import { emptyWards, addWard, isWarded, tickWards, wardSpeedFactor, wardSpeedMul, WARD_MIN_MS, WARD_MAX_MS, WARD_MAX_SPEED_FACTOR } from '../../src/systems/Wards.js';
import { hazardDrawKind, powerupDrawKind, hazardColorKey } from '../../src/systems/BiomeEffects.js';
import { BIOME_SPAWN_MAX_CHANCE, BIOME_HAZARD_MAX_CHANCE } from '../../src/systems/TerrainGenerator.js';

const c = loadContent();
const biomeHaz = readDir('hazards').filter((d) => d.biome);
const biomePu = readDir('powerups').filter((d) => d.biome);

/** Spec §4 B1 rows. */
const B1 = {
  debutmont: { hazard: 'groomerCat', powerup: 'mapleWax' },
  'garbage-dump-glacier': { hazard: 'seagullDive', powerup: 'slickWaxSpray' },
  'underwater-mountain': { hazard: 'seaweedTangle', powerup: 'aquaLungBubble' },
  'candy-cane-canyon': { hazard: 'chocolateRiver', powerup: 'sweetToothCoating' },
};

describe('B1 content: loader and schema', () => {
  test('exactly the B1 biome defs are shipped, one hazard and one power-up per B1 biome', () => {
    const byBiome = (list) => Object.fromEntries(Object.keys(B1).map((b) => [b, list.filter((d) => d.biome === b).map((d) => d.id)]));
    expect(byBiome(biomeHaz)).toEqual(Object.fromEntries(Object.entries(B1).map(([b, r]) => [b, [r.hazard]])));
    expect(byBiome(biomePu)).toEqual(Object.fromEntries(Object.entries(B1).map(([b, r]) => [b, [r.powerup]])));
    // B2 adds Crystal Cavern and Vertigo Vents defs; the B1 biomes still hold exactly 4 + 4 (the 6 + 6 total is pinned in
    // biome-b2-content.test.js)
    expect(biomeHaz.filter((d) => B1[d.biome]).length).toBe(4);
    expect(biomePu.filter((d) => B1[d.biome]).length).toBe(4);
    // loadContent (the shape the game's loader produces) carries them by id
    for (const r of Object.values(B1)) {
      expect(c.hazards[r.hazard]).toBeDefined();
      expect(c.powerups[r.powerup]).toBeDefined();
    }
  });

  test('every biome def names a real biome, and follows the hazard / power-up schema', () => {
    const effects = ['crash', 'slow', 'scramble', 'blind', 'gust'];
    for (const h of biomeHaz) {
      expect(c.biomes[h.biome]).toBeDefined();
      expect(typeof h.shapeKey).toBe('string');
      expect(h.size.w).toBeGreaterThan(0);
      expect(h.size.h).toBeGreaterThan(0);
      expect(effects).toContain(h.onHit.effect);
      expect(h.weight).toBeGreaterThan(0);
      expect(h.minDistanceM).toBeGreaterThanOrEqual(0);
      expect(['ground', 'air']).toContain(h.placement);
      expect(PALETTE_KEYS).toContain(h.colorKey);
      expect(h.spawn.baseChance).toBeGreaterThan(0);
      expect(h.spawn.baseChance).toBeLessThanOrEqual(BIOME_HAZARD_MAX_CHANCE); // B1 presence amendment (c): 0.75 for hazards
    }
    for (const p of biomePu) {
      expect(c.biomes[p.biome]).toBeDefined();
      expect(typeof p.shapeKey).toBe('string');
      expect(p.radius).toBeGreaterThan(0);
      expect(['slowmo', 'speedBoost', 'shield', 'ward', 'glide', 'stabilize']).toContain(p.effect.kind);
      expect(PALETTE_KEYS).toContain(p.colorKey);
      expect(p.spawn.baseChance).toBeGreaterThan(0);
      expect(p.spawn.baseChance).toBeLessThanOrEqual(BIOME_SPAWN_MAX_CHANCE);
    }
  });

  test('every new shapeKey has its own drawing (never the generic fallback); crash hazards are `danger`', () => {
    for (const h of biomeHaz) expect({ id: h.id, draw: hazardDrawKind(h) }).toEqual({ id: h.id, draw: h.shapeKey });
    for (const p of biomePu) expect({ id: p.id, draw: powerupDrawKind(p) }).toEqual({ id: p.id, draw: p.shapeKey });
    const keys = [...biomeHaz, ...biomePu].map((d) => d.shapeKey);
    expect(new Set(keys).size).toBe(keys.length);
    for (const h of biomeHaz.filter((d) => d.onHit.effect === 'crash')) {
      expect(h.colorKey).toBe('danger');
      expect(hazardColorKey(h)).toBe('danger');
    }
  });
});

describe('B1 content: the spec §4 values', () => {
  test('Debutmont: Groomer Cat slow 0.7 x 900 ms on the ground; Maple Wax speedBoost 1.2 x 2 s', () => {
    expect(c.hazards.groomerCat).toMatchObject({ placement: 'ground', onHit: { effect: 'slow', speedFactor: 0.7, durationMs: 900 } });
    expect(c.hazards.groomerCat.motion).toBeUndefined(); // static in B1; motion kinds land in B3
    expect(c.powerups.mapleWax.effect).toEqual({ kind: 'speedBoost', speedFactor: 1.2, durationMs: 2000 });
  });

  test('Garbage Dump Glacier: Seagull Dive is an air crash hazard; Slick Wax Spray wards stickyPatch 4 s + speed 1.1', () => {
    expect(c.hazards.seagullDive).toMatchObject({ placement: 'air', onHit: { effect: 'crash' }, colorKey: 'danger' });
    expect(c.powerups.slickWaxSpray.effect).toEqual({ kind: 'ward', durationMs: 4000, mods: ['stickyPatch'], hazards: [], effects: [], speedFactor: 1.1 });
  });

  test('Underwater Mountain: Seaweed Tangle slow 0.6 x 1.2 s; Aqua-Lung Bubble wards slowMotion 4 s', () => {
    expect(c.hazards.seaweedTangle).toMatchObject({ placement: 'ground', onHit: { effect: 'slow', speedFactor: 0.6, durationMs: 1200 } });
    expect(c.powerups.aquaLungBubble.effect).toEqual({ kind: 'ward', durationMs: 4000, mods: ['slowMotion'], hazards: [], effects: [] });
  });

  test('Candy Cane Canyon: Chocolate River is a wide ground strip, slow 0.6 x 1.0 s; Sweet-Tooth wards slow effects 5 s', () => {
    const r = c.hazards.chocolateRiver;
    expect(r).toMatchObject({ placement: 'ground', onHit: { effect: 'slow', speedFactor: 0.6, durationMs: 1000 } });
    expect(r.size.w).toBeGreaterThanOrEqual(3 * r.size.h); // a strip: much wider than tall
    expect(c.powerups.sweetToothCoating.effect).toEqual({ kind: 'ward', durationMs: 5000, mods: [], hazards: [], effects: ['slow'] });
  });
});

describe('B1 content: each ward counters its own biome', () => {
  test('ward durations are inside the spec band (4-6 s), so Wards.addWard keeps them unchanged', () => {
    for (const p of biomePu.filter((d) => d.effect.kind === 'ward')) {
      expect(p.effect.durationMs).toBeGreaterThanOrEqual(WARD_MIN_MS);
      expect(p.effect.durationMs).toBeLessThanOrEqual(WARD_MAX_MS);
    }
  });

  test('a ward\'s mods are its biome\'s signature mod, and exist as terrain mods', () => {
    for (const p of biomePu.filter((d) => d.effect.kind === 'ward')) {
      for (const m of p.effect.mods) {
        expect(c.terrainMods[m]).toBeDefined();
        expect({ ward: p.id, mod: m }).toEqual({ ward: p.id, mod: c.biomes[p.biome].mod });
      }
    }
  });

  test('Sweet-Tooth Coating wards off the Chocolate River (and nothing it should not)', () => {
    const w = addWard(emptyWards(), 'sweetToothCoating', c.powerups.sweetToothCoating.effect);
    expect(isWarded(w, { effect: c.hazards.chocolateRiver.onHit.effect })).toBe(true);
    expect(isWarded(w, { effect: 'crash' })).toBe(false);
    expect(isWarded(w, { modId: 'sugarRush' })).toBe(false);
  });

  test('Slick Wax Spray wards stickyPatch; Aqua-Lung Bubble wards slowMotion', () => {
    expect(isWarded(addWard(emptyWards(), 'slickWaxSpray', c.powerups.slickWaxSpray.effect), { modId: 'stickyPatch' })).toBe(true);
    expect(isWarded(addWard(emptyWards(), 'aquaLungBubble', c.powerups.aquaLungBubble.effect), { modId: 'slowMotion' })).toBe(true);
  });
});

describe('Wards.js B1 extension: optional ward speedFactor', () => {
  test('wardSpeedFactor: 1 when absent, clamped to [1, WARD_MAX_SPEED_FACTOR] (a bonus, never a slow)', () => {
    expect(WARD_MAX_SPEED_FACTOR).toBe(1.2);
    expect(wardSpeedFactor(undefined)).toBe(1);
    expect(wardSpeedFactor(1.1)).toBe(1.1);
    expect(wardSpeedFactor(0.5)).toBe(1);
    expect(wardSpeedFactor(3)).toBe(1.2);
  });

  test('wardSpeedMul: product over active wards; ends with the ward; plain wards add nothing', () => {
    let w = addWard(emptyWards(), 'slickWaxSpray', c.powerups.slickWaxSpray.effect);
    w = addWard(w, 'aquaLungBubble', c.powerups.aquaLungBubble.effect);
    expect(wardSpeedMul(w)).toBeCloseTo(1.1, 12);
    expect(wardSpeedMul(emptyWards())).toBe(1);
    expect(wardSpeedMul(null)).toBe(1);
    tickWards(w, 4001);
    expect(wardSpeedMul(w)).toBe(1);
  });
});

describe('B1 content: measured presence in biome chunks (slot rule, spec §4 amendment)', () => {
  // Long-range floors (8 seeds x 300 chunks). After the presence amendment the measured shares of ELIGIBLE chunks are
  // groomerCat 42.5 %, seagullDive 33.5 %, seaweedTangle 44.2 %, chocolateRiver 27.3 %; the early-terrain target and its
  // open items live in biome-b1-presence.test.js. These floors stay as a second, long-range regression pin.
  const ROWS = [
    [1, 'debutmont', 'groomerCat', 'mapleWax', 0.08],
    [2, 'garbage-dump-glacier', 'seagullDive', 'slickWaxSpray', 0.12],
    [8, 'underwater-mountain', 'seaweedTangle', 'aquaLungBubble', 0.06],
    [64, 'candy-cane-canyon', 'chocolateRiver', 'sweetToothCoating', 0.05],
  ];
  test.each(ROWS)('mask %p (%s): hazard %s, power-up %s, hazard share of eligible chunks >= %p, power-up in 25-45 %% of biome chunks', (mask, biome, hz, pu, floor) => {
    const air = c.hazards[hz].placement === 'air';
    let all = 0;
    let elig = 0;
    let h = 0;
    let p = 0;
    for (const seed of ['b1-share-a', 'b1-share-b', 'b1-share-c', 'b1-share-d']) {
      const g = makeGen(seed, { biomeMask: mask });
      for (let i = 1; i < 300; i++) {
        const ch = g.getChunk(i);
        if (ch.biome !== biome) continue;
        all++;
        const ok = air ? ch.defId === 'gen-jump' : ch.kind !== 'bridge' && ch.defId !== 'gen-jump';
        if (ok) elig++;
        if (ch.hazards.some((q) => q.defId === hz)) h++;
        if (ch.powerups.some((q) => q.defId === pu)) p++;
      }
    }
    expect(elig).toBeGreaterThan(60);
    expect(h / elig).toBeGreaterThanOrEqual(floor);
    expect(p / all).toBeGreaterThanOrEqual(0.25);
    expect(p / all).toBeLessThanOrEqual(0.45);
  });
});

describe('B1 invariant: same seed + mask gives identical terrain twice (shipped content)', () => {
  test.each([1, 2, 8, 64])('mask %p: two generators, forward and reverse call order, deep-equal over 150 chunks', (mask) => {
    const snap = (ch) => JSON.parse(JSON.stringify(ch));
    const a = makeGen('b1-det', { biomeMask: mask });
    const b = makeGen('b1-det', { biomeMask: mask });
    const rev = [];
    for (let i = 149; i >= 0; i--) rev[i] = snap(b.getChunk(i));
    let biomeSpawns = 0;
    for (let i = 0; i < 150; i++) {
      const ch = snap(a.getChunk(i));
      expect(ch).toEqual(rev[i]);
      biomeSpawns += [...ch.hazards, ...ch.powerups].filter((s) => (c.hazards[s.defId] || c.powerups[s.defId]).biome).length;
    }
    expect(biomeSpawns).toBeGreaterThan(0); // the stream really contains biome spawns
  });
});/**
 * B1 "Wards": the SHIPPED biome defs through the shipped RunScene dispatch, HUD tables and entity drawing (same fake
 * Phaser seam as biome-effects-runscene.test.js). The built-game gate checks the same effects on the real sled.
 */
import { jest } from '@jest/globals';

const Body = {
  getVelocity: (b) => ({ x: b.velocity.x, y: b.velocity.y }),
  setVelocity: (b, v) => { b.velocity = { x: v.x, y: v.y }; },
  getAngularVelocity: () => 0,
  setAngularVelocity: () => {},
};
class Stub { constructor() { this.alpha = 0; } setAlpha(a) { this.alpha = a; return this; } setFillStyle() { return this; } }
const FakePhaser = {
  Scene: class {},
  Physics: { Matter: { Matter: { Bodies: { rectangle: (x, y, w, h, o) => ({ x, y, w, h, ...o }), circle: (x, y, r, o) => ({ x, y, r, ...o }) }, Body } } },
  Renderer: { WebGL: { Pipelines: { PostFXPipeline: class {} } } },
  GameObjects: { Container: class {}, Graphics: class {}, BitmapText: class {}, Zone: class {}, Image: class {}, Rectangle: class {}, Text: class {} },
  BlendModes: { ADD: 1 },
  Scenes: { Events: { UPDATE: 'update', SHUTDOWN: 'shutdown', DESTROY: 'destroy' } },
  Math: { Between: (a) => a, Clamp: (v, a, b) => Math.min(b, Math.max(a, v)) },
};
jest.unstable_mockModule('phaser', () => ({ default: FakePhaser }));
jest.unstable_mockModule('../../src/shaders/GlitchPipeline.js', () => ({ GlitchPipeline: { install() {} } }));

const { RunScene } = await import('../../src/scenes/RunScene.js');
const { UIScene } = await import('../../src/scenes/UIScene.js');
const { Hazard } = await import('../../src/entities/Hazard.js');
const { PowerUp } = await import('../../src/entities/PowerUp.js');
const { EVT } = await import('../../src/events.js');
const { PhysicsTuner, BASE_STEP_MS } = await import('../../src/systems/PhysicsTuner.js');
const { loadContent } = await import('./_helpers.js');

const C = loadContent();
const MODS = C.terrainMods;
const PAD = { tuck: false, brake: false };

function makeRun({ zones = [] } = {}) {
  const emitted = [];
  const scaled = [];
  const s = Object.create(RunScene.prototype);
  Object.assign(s, {
    game: { events: { emit: (e, p) => { emitted.push([e, p]); } } },
    emitted,
    scaled,
    sled: {
      x: 1000, y: 0, vx: 300, vy: 20, inWorld: true, invulnerableMs: 0, grounded: true, parachuteMs: 0, airBrakeActive: false,
      body: { velocity: { x: 300 * BASE_STEP_MS / 1000, y: 20 * BASE_STEP_MS / 1000 } },
      scaleVelocity(k) { scaled.push(k); }, wobble() {},
    },
    fx: { sparks() {}, ring() {} },
    shake() {},
    flashRect: new Stub(),
    blindRect: new Stub(),
    palette: { cyan: 1, amber: 2, lime: 3, bg: 0 },
    tuner: new PhysicsTuner(),
    dailyMods: {},
    crashed: false,
    pendingCrash: null,
    runTimeMs: 0,
    slowMs: 0, slowFactor: 0.5, scrambleMs: 0, boostMs: 0, boostFactor: 1, slowmoMs: 0, slowmoScale: 0.5, shieldCharges: 0,
    collectedPowerups: new Set(),
    _despawn: [],
  });
  s.getZoneDefs = () => zones;
  s._resetBiomeEffects();
  return s;
}
const hit = (id) => ({ def: C.hazards[id], cx: 1000, cy: 0, color: 5, gfx: null, hit: false });
const take = (id) => ({ def: C.powerups[id], spawn: { x: 1000, y: 0 }, color: 5, destroy() {} });
const phys = (s) => s.tuner.getEffective(s.physicsContext(PAD));
const events = (s, name) => s.emitted.filter(([e]) => e === name).map(([, p]) => p);

describe('B1 hazards through RunScene.onHazard (shipped defs)', () => {
  test.each([
    ['groomerCat', 0.7, 900],
    ['seaweedTangle', 0.6, 1200],
    ['chocolateRiver', 0.6, 1000],
  ])('%s: a slow of %p x %p ms on the sled (instant velocity cut + tuner speedMul), then it ends', (id, k, ms) => {
    const s = makeRun();
    s.onHazard(hit(id));
    expect(s.scaled).toEqual([k]);
    expect(phys(s).speedMul).toBeCloseTo(k, 12);
    expect(events(s, EVT.HAZARD_HIT)).toEqual([{ hazardId: id, effect: 'slow', durationMs: ms, x: 1000, y: 0 }]);
    s.tickEffects(ms + 1);
    expect(phys(s).speedMul).toBeCloseTo(1, 12);
    expect(events(s, EVT.EFFECT_END)).toEqual([{ effect: 'slow' }]);
  });

  test('seagullDive queues a crash', () => {
    const s = makeRun();
    s.onHazard(hit('seagullDive'));
    expect(s.pendingCrash).toEqual({ cause: 'hazard', hazardId: 'seagullDive' });
  });
});

describe('B1 power-ups through RunScene.onPowerUp (shipped defs)', () => {
  test('Maple Wax: a 1.2 speed boost for 2 s, reported (and expired) under its OWN id', () => {
    const s = makeRun();
    s.onPowerUp(take('mapleWax'));
    expect(s.scaled).toEqual([1.2]);
    expect(phys(s).speedMul).toBeCloseTo(1.2, 12);
    expect(events(s, EVT.POWERUP_COLLECTED)).toEqual([{ id: 'mapleWax', durationMs: 2000, charges: 0 }]);
    s.tickEffects(2001);
    expect(phys(s).speedMul).toBeCloseTo(1, 12);
    expect(events(s, EVT.POWERUP_EXPIRED)).toEqual([{ id: 'mapleWax', reason: 'timeout' }]);
  });

  test('a base Packet Burst still expires as packetBurst', () => {
    const s = makeRun();
    s.onPowerUp(take('packetBurst'));
    s.tickEffects(3001);
    expect(events(s, EVT.POWERUP_EXPIRED)).toEqual([{ id: 'packetBurst', reason: 'timeout' }]);
  });

  test('Slick Wax Spray: stickyPatch is neutralised AND the sled gets a 1.1 speed boost while the 4 s ward runs', () => {
    const s = makeRun({ zones: [MODS.stickyPatch] });
    const plain = phys(makeRun());
    const sticky = phys(s);
    expect(sticky.groundResist).toBeGreaterThan(plain.groundResist);
    s.onPowerUp(take('slickWaxSpray'));
    expect(s.scaled).toEqual([1.1]);
    const w = phys(s);
    expect(w.groundResist).toBeCloseTo(plain.groundResist, 12);
    expect(w.speedMul).toBeCloseTo(1.1, 12);
    expect(events(s, EVT.POWERUP_COLLECTED)).toEqual([{ id: 'slickWaxSpray', durationMs: 4000, charges: 0 }]);
    s.tickEffects(4001);
    const after = phys(s);
    expect(after.groundResist).toBeCloseTo(sticky.groundResist, 12);
    expect(after.speedMul).toBeCloseTo(1, 12);
    expect(events(s, EVT.POWERUP_EXPIRED)).toEqual([{ id: 'slickWaxSpray', reason: 'timeout' }]);
  });

  test('Slick Wax\'s speed and a Packet Burst are separate: both multiply, and each chip ends on its own', () => {
    const s = makeRun();
    s.onPowerUp(take('packetBurst'));
    s.onPowerUp(take('slickWaxSpray'));
    expect(phys(s).speedMul).toBeCloseTo(1.3 * 1.1, 12);
    s.tickEffects(3001);
    expect(phys(s).speedMul).toBeCloseTo(1.1, 12);
    expect(events(s, EVT.POWERUP_EXPIRED)).toEqual([{ id: 'packetBurst', reason: 'timeout' }]);
  });

  test('Aqua-Lung Bubble: the slowMotion zone stops acting (gravity and friction back to base) for 4 s', () => {
    const s = makeRun({ zones: [MODS.slowMotion] });
    const plain = phys(makeRun());
    const slowZone = phys(s);
    expect(slowZone.gravityPxS2).toBeLessThan(plain.gravityPxS2);
    s.onPowerUp(take('aquaLungBubble'));
    const w = phys(s);
    expect(w.gravityPxS2).toBeCloseTo(plain.gravityPxS2, 12);
    expect(w.groundResist).toBeCloseTo(plain.groundResist, 12);
    expect(s.scaled).toEqual([]); // no speed part
    s.tickEffects(4001);
    expect(phys(s).gravityPxS2).toBeCloseTo(slowZone.gravityPxS2, 12);
  });

  test('Sweet-Tooth Coating: a Chocolate River hit while it runs does nothing (no HAZARD_HIT, no velocity cut, speedMul 1)', () => {
    const s = makeRun();
    s.onPowerUp(take('sweetToothCoating'));
    s.onHazard(hit('chocolateRiver'));
    expect(events(s, EVT.HAZARD_HIT)).toEqual([]);
    expect(s.scaled).toEqual([]);
    expect(phys(s).speedMul).toBeCloseTo(1, 12);
    s.tickEffects(5001);
    s.onHazard(hit('chocolateRiver'));
    expect(events(s, EVT.HAZARD_HIT).map((p) => p.hazardId)).toEqual(['chocolateRiver']);
  });

  test('Sweet-Tooth Coating also stops a river slow that is already acting', () => {
    const s = makeRun();
    s.onHazard(hit('chocolateRiver'));
    expect(phys(s).speedMul).toBeCloseTo(0.6, 12);
    s.onPowerUp(take('sweetToothCoating'));
    expect(phys(s).speedMul).toBeCloseTo(1, 12);
  });
});

describe('B1 HUD entries (UIScene)', () => {
  const ui = () => Object.assign(Object.create(UIScene.prototype), { content: C, nowMs: 0, warnY: 40, effects: new Map() });
  const recorder = () => {
    const ops = [];
    return { ops, g: new Proxy({}, { get: (t, k) => (...a) => { ops.push([k, ...a]); return undefined; } }) };
  };
  const IDS = ['mapleWax', 'slickWaxSpray', 'aquaLungBubble', 'sweetToothCoating'];

  test('each B1 pickup has its own HUD name (not an id-derived label)', () => {
    const u = ui();
    expect(IDS.map((id) => u._powerInfo(id).name)).toEqual(['MAPLE WAX', 'SLICK WAX', 'AQUA-LUNG', 'SWEET-TOOTH']);
    // the rows' own colours (the id-derived fallback is cyan for a speedBoost pickup, so Maple's amber needs its row)
    expect(IDS.map((id) => u._powerInfo(id).color)).toEqual(['amber', 'cyan', 'cyan', 'magenta']);
  });

  test('each B1 pickup chip draws its own icon: not the unknown square, not the generic ward icon, all different', () => {
    const u = ui();
    const draw = (id) => { const r = recorder(); u._drawIcon(r.g, id, 10, 10, 1); return JSON.stringify(r.ops.filter(([k]) => k !== 'lineStyle' && k !== 'fillStyle')); };
    const square = JSON.stringify([['strokeRect', 5, 5, 10, 10]]);
    const wardIcon = (() => {
      const v = Object.assign(Object.create(UIScene.prototype), { content: { powerups: { w: { effect: { kind: 'ward' } } } } });
      const r = recorder(); v._drawIcon(r.g, 'w', 10, 10, 1); return JSON.stringify(r.ops.filter(([k]) => k !== 'lineStyle' && k !== 'fillStyle'));
    })();
    const icons = IDS.map(draw);
    for (const ic of icons) {
      expect(ic).not.toBe(square);
      expect(ic).not.toBe(wardIcon);
    }
    expect(new Set(icons).size).toBe(IDS.length);
  });

  test('a B1 slow hazard names itself on the warning line; a base slow keeps SPEED CUT', () => {
    const u = ui();
    const made = [];
    u._t = () => { const t = { text: '', setText(x) { this.text = x; return t; }, setColorKey() { return t; }, destroy() {} }; made.push(t); return t; };
    u.onHazard({ hazardId: 'chocolateRiver', effect: 'slow', durationMs: 1500 });
    expect(made[0].text).toContain('CHOCOLATE RIVER');
    u._removeEffect('slow');
    u.onHazard({ hazardId: 'groomerCat', effect: 'slow', durationMs: 900 });
    expect(made[1].text).toContain('GROOMER CAT');
    u._removeEffect('slow');
    u.onHazard({ hazardId: 'seaweedTangle', effect: 'slow', durationMs: 1200 });
    expect(made[2].text).toContain('SEAWEED TANGLE');
    u._removeEffect('slow');
    u.onHazard({ hazardId: 'overflowFirewall', effect: 'slow', durationMs: 1500 });
    expect(made[3].text).toContain('SPEED CUT');
  });
});

describe('B1 drawing: every new shapeKey has its own routine', () => {
  const PAL = { danger: 0xff0000, magenta: 0xff00ff, lime: 0x00ff00, cyan: 0x00ffff, amber: 0xffaa00, bg: 0, bgAlt: 1, text: 0xffffff };
  const scene = () => ({
    matter: { world: { add() {}, remove() {} } },
    add: {
      graphics: () => {
        const ops = [];
        const g = new Proxy({ ops, y: 0 }, {
          get: (t, k) => (k in t ? t[k] : (...a) => { ops.push([k, ...a]); return g; }),
          set: (t, k, v) => { t[k] = v; return true; },
        });
        return g;
      },
    },
  });
  const shape = (gfx) => JSON.stringify(gfx.ops.filter(([k]) => /^fill(Rect|Triangle|Points|Circle|Ellipse)$|^stroke|^lineBetween$/.test(k)).map(([k]) => k));

  test('the four hazards draw non-generic, mutually different shapes; Seagull Dive is `danger`', () => {
    const out = {};
    for (const id of ['groomerCat', 'seagullDive', 'seaweedTangle', 'chocolateRiver']) {
      const def = C.hazards[id];
      const h = new Hazard(scene(), def, { x: 100, y: 50, rotationDeg: 0 }, PAL);
      expect(h.drawKind).toBe(def.shapeKey);
      out[id] = shape(h.gfx);
      // the same def with an unknown shapeKey draws the generic box: the real drawing must differ from it
      const generic = new Hazard(scene(), { ...def, shapeKey: 'zzUnknownShape' }, { x: 100, y: 50, rotationDeg: 0 }, PAL);
      expect(generic.drawKind).toBe('generic');
      expect(out[id]).not.toBe(shape(generic.gfx));
      if (id === 'seagullDive') expect(h.color).toBe(PAL.danger);
    }
    expect(new Set(Object.values(out)).size).toBe(4);
  });

  test('the four pickups draw non-generic, mutually different glyphs', () => {
    const out = {};
    for (const id of ['mapleWax', 'slickWaxSpray', 'aquaLungBubble', 'sweetToothCoating']) {
      const def = C.powerups[id];
      const p = new PowerUp(scene(), def, { x: 100, y: 50 }, PAL);
      expect(p.drawKind).toBe(def.shapeKey);
      out[id] = shape(p.gfx);
      const generic = new PowerUp(scene(), { ...def, shapeKey: 'zzUnknownGlyph' }, { x: 100, y: 50 }, PAL);
      expect(generic.drawKind).toBe('generic');
      expect(out[id]).not.toBe(shape(generic.gfx));
    }
    expect(new Set(Object.values(out)).size).toBe(4);
  });
});/**
 * B1 presence (spec §4, amended by the spec author 2026-11-14 after the lead found biome hazards too rare to be felt):
 *   (a) a biome ground hazard needs >= BIOME_HAZARD_CLEARANCE_PX (240) from any other hazard, not the base 480 px;
 *       the 240 px chunk-edge margin stays (so base hazards across a chunk border stay >= 480 px apart);
 *   (b) the descent-ahead rule binds a biome `slow` hazard only when its speedFactor < BIOME_GENTLE_SLOW_FACTOR (0.6);
 *       a gentler slow (Groomer 0.7, Seaweed 0.6) may sit on flat or downhill ground, never before an uphill;
 *   (c) the biome HAZARD chance cap may rise to 0.75 (power-ups keep 0.5);
 *   (d) the replace rule stays the fallback.
 * Target: over 8 seeds x chunks 0-44 at each single biome bit, the biome hazard sits in 35-55 % of that biome's chunks
 * eligible for its placement kind, and at least 1 per 2 km of biome terrain on every seed. Shipped content.
 */
import { makeGen, loadContent } from './_helpers.js';
import {
  HAZARD_MIN_SPACING_PX, BIOME_HAZARD_CLEARANCE_PX, BIOME_GENTLE_SLOW_FACTOR, BIOME_EDGE_MARGIN_PX, SPACING_PX,
} from '../../src/systems/TerrainGenerator.js';

const c = loadContent();
const ROWS = [
  [1, 'debutmont', 'groomerCat'],
  [2, 'garbage-dump-glacier', 'seagullDive'],
  [8, 'underwater-mountain', 'seaweedTangle'],
  [64, 'candy-cane-canyon', 'chocolateRiver'],
];
const SEEDS = ['pres1', 'pres2', 'pres3', 'pres4', 'pres5', 'pres6', 'pres7', 'pres8'];
const eligibleFor = (def, ch) => (def.placement === 'air' ? ch.defId === 'gen-jump' : ch.kind !== 'bridge' && ch.defId !== 'gen-jump');
const deg = (pts, k) => (Math.atan2(pts[k + 1].y - pts[k].y, SPACING_PX) * 180) / Math.PI;

/** Share of eligible chunks and per-seed 1-per-2-km check over chunks 1..44 at a single biome bit. */
function presence(mask, biome, id, seeds) {
  const def = c.hazards[id];
  let elig = 0;
  let has = 0;
  const perSeed = [];
  for (const seed of seeds) {
    const g = makeGen(seed, { biomeMask: mask });
    let km = 0;
    let n = 0;
    for (let i = 1; i < 45; i++) {
      const ch = g.getChunk(i);
      if (ch.biome !== biome) continue;
      km += (ch.endX - ch.startX) / 20000;
      const here = ch.hazards.some((q) => q.defId === id);
      if (here) n++;
      if (eligibleFor(def, ch)) { elig++; if (here) has++; }
    }
    perSeed.push({ seed, n, km: +km.toFixed(2), ok: km < SHORT_KM || n * 2 >= km });
  }
  const share = has / elig;
  console.log(`${id} (${seeds.length} seeds): ${has}/${elig} eligible = ${(100 * share).toFixed(1)} %; per seed ${perSeed.map((p) => `${p.n}/${p.km}km`).join(' ')}`);
  return { elig, share, perSeed, fails: perSeed.filter((p) => !p.ok).length };
}
const ROB = Array.from({ length: 32 }, (_, k) => `rob${k + 1}`);
// re-pinned for #65: Debutmont base + arcade bridges. Re-assessed, not widened: measured over 400 seeds the hazard shares are
// unchanged by the new stream (every biome hazard within +/-0.02 of its pre-#65 share, all inside the band), so the
// generator still places hazards as specified. What moved is the SAMPLE: every biome sector now opens with an arcade bridge
// (~100 m), so the same chunks 0-44 hold ~25 % fewer eligible biome chunks (8 seeds: 28 -> 22; 32 seeds: 224 -> 175), and the
// 8- and 32-seed shares, whose standard error is 0.07-0.1 / 0.04 against a +/-0.1 band, flip on sampling noise (seaweed
// 35.7 % -> 31.8 % on the same hazard rate). So the band is asserted on BIG (150 seeds, standard error ~0.02); the small
// samples still run and keep their eligible-count and per-seed checks. The per-seed 1-per-2-km rule is judged on seeds with
// >= SHORT_KM of the biome in chunks 0-44: a slice shorter than that (the shorter, the likelier now that a bridge opens each
// biome sector) can hold no eligible hazard slot by chance, which these comments already named as the cause of every miss.
const BIG = Array.from({ length: 150 }, (_, k) => `big${k + 1}`);
const SHORT_KM = 1;

describe('B1 presence: the biome hazard is felt in early terrain (chunks 0-44, single biome bit)', () => {
  // Target (lead): 35-55 % of eligible chunks on 8 seeds, and >= 1 per 2 km of biome terrain on every seed. The 8-seed
  // sample is small (17-28 eligible chunks), so the band is also asserted on 32 independent seeds.
  test.each([[1, 'debutmont', 'groomerCat'], [8, 'underwater-mountain', 'seaweedTangle']])(
    'mask %p (%s): %s meets the full target (band on 150 seeds, 1 per 2 km on every seed with >= 1 km of biome)', (mask, biome, id) => {
      const a = presence(mask, biome, id, SEEDS);
      expect(a.elig).toBeGreaterThanOrEqual(15);
      for (const p of a.perSeed) expect(p).toMatchObject({ ok: true });
      const b = presence(mask, biome, id, ROB);
      expect(b.fails).toBeLessThanOrEqual(2); // 0 of the seeds with >= 1 km of biome terrain at #65 (2/30 before it counted shorter slices too)
      const big = presence(mask, biome, id, BIG);
      expect(big.share).toBeGreaterThanOrEqual(0.35);
      expect(big.share).toBeLessThanOrEqual(0.55);
    });

  test('mask 2 (garbage-dump-glacier): seagullDive meets the band; OPEN for the lead: the 1-per-2-km rule fails on some seeds', () => {
    // Air hazards sit only in biome jump chunks (often 2-3 per seed in chunks 0-44, a third of them already holding a base
    // Rogue Packet). No amendment covers the air slot, so the per-seed rule is pinned at its measured value, not met.
    const a = presence(2, 'garbage-dump-glacier', 'seagullDive', SEEDS);
    expect(a.share).toBeGreaterThanOrEqual(0.35);
    expect(a.share).toBeLessThanOrEqual(0.55);
    expect(a.fails).toBeLessThanOrEqual(3); // measured 3 of the 6 seeds with biome terrain
    const b = presence(2, 'garbage-dump-glacier', 'seagullDive', ROB);
    expect(b.share).toBeGreaterThanOrEqual(0.35);
    expect(b.share).toBeLessThanOrEqual(0.55);
    expect(b.fails).toBeLessThanOrEqual(4); // measured 3/30
  });

  test('mask 64 (candy-cane-canyon): chocolateRiver meets the band', () => {
    // Lead ruling (2026-11-14): speedFactor 0.5 -> 0.6 puts the river under the gentle-slow rule (amendment b)
    // instead of descent-ahead; at 0.5 it reached only ~21 % of eligible chunks. Sweet-Tooth still wards it.
    const a = presence(64, 'candy-cane-canyon', 'chocolateRiver', SEEDS);
    expect(a.share).toBeGreaterThanOrEqual(0.35);
    expect(a.share).toBeLessThanOrEqual(0.55);
    const b = presence(64, 'candy-cane-canyon', 'chocolateRiver', ROB);
    expect(b.share).toBeGreaterThanOrEqual(0.35);
    expect(b.share).toBeLessThanOrEqual(0.55);
  });
});

/** Every placed biome hazard of one def over 8 seeds x 300 chunks, with its chunk and generator. */
function placements(mask, id, n = 300) {
  const out = [];
  for (const seed of SEEDS) {
    const g = makeGen(seed, { biomeMask: mask });
    for (let i = 1; i < n; i++) {
      const ch = g.getChunk(i);
      for (const h of ch.hazards) if (h.defId === id) out.push({ g, ch, h, i });
    }
  }
  return out;
}

describe('B1 amended placement rules (a) and (b)', () => {
  test('(a) a biome ground hazard keeps >= 240 px from every hazard (and uses the closer spacing); base pairs keep 480 px', () => {
    expect(BIOME_HAZARD_CLEARANCE_PX).toBe(240);
    expect(BIOME_EDGE_MARGIN_PX).toBe(240);
    let closer = 0;
    for (const [mask, , id] of ROWS.filter(([, , i]) => c.hazards[i].placement !== 'air')) {
      for (const seed of SEEDS.slice(0, 4)) {
        const g = makeGen(seed, { biomeMask: mask });
        const all = [];
        for (let i = 0; i < 300; i++) all.push(...g.getChunk(i).hazards);
        for (let k = 1; k < all.length; k++) {
          const a = all[k - 1];
          const b = all[k];
          // re-pinned for #65: Debutmont base + arcade bridges. Debutmont is the base biome now, so its own hazard (Groomer
          // Cat) sits in the base stream of every mask: ANY biome-tagged hazard is a biome hazard here, not only this row's.
          const biomeInvolved = !!(c.hazards[a.defId].biome || c.hazards[b.defId].biome);
          expect({ a: a.defId, b: b.defId, gap: b.x - a.x, ok: b.x - a.x >= (biomeInvolved ? BIOME_HAZARD_CLEARANCE_PX : HAZARD_MIN_SPACING_PX) })
            .toMatchObject({ ok: true });
          if (biomeInvolved && b.x - a.x < HAZARD_MIN_SPACING_PX) closer++;
        }
      }
    }
    expect(closer).toBeGreaterThan(10);
  });


  test.each([[1, 'groomerCat'], [8, 'seaweedTangle'], [64, 'chocolateRiver']])('(b) mask %p: %s never sits before an uphill (240 px ahead), and some sit off a descent', (mask, id) => {
    const ps = placements(mask, id);
    expect(ps.length).toBeGreaterThan(20);
    let offDescent = 0;
    for (const { g, ch, h } of ps) {
      const pts = ch.points;
      const k0 = Math.max(0, Math.min(pts.length - 2, Math.floor((h.x - ch.startX) / SPACING_PX)));
      const k1 = Math.min(pts.length - 2, k0 + Math.ceil(BIOME_EDGE_MARGIN_PX / SPACING_PX));
      for (let k = k0; k <= k1; k++) expect(deg(pts, k)).toBeGreaterThanOrEqual(0);
      if (!g._descentAhead(pts, k0, ch.endX)) offDescent++;
    }
    expect(offDescent).toBeGreaterThan(0);
  });
});

describe('B1 stall check: no biome slow hit can stop the sled', () => {
  /**
   * The QA point-mass model of _helpers.rollSim (65 % of g sin(slope), linear + quadratic drag), started at the hazard
   * with a deliberately LOW entry speed (300 px/s; the expected speed past 1000 m, where biome sectors start, is >= 520)
   * cut by the hazard's speedFactor, then run for 2 s along the following terrain. The slow's own drag scaling is
   * included: while slowed the linear drag is divided by speedFactor (PhysicsTuner frictionAir / speedMul).
   */
  const ENTRY_PX_S = 300;
  function minSpeedAfterHit(g, ch, h, k) {
    const pts = [];
    for (let j = ch.index; j <= ch.index + 2; j++) for (const p of g.getChunk(j).points) if (!pts.length || p.x > pts[pts.length - 1].x) pts.push(p);
    const eff = c.hazards[h.defId].onHit;
    let v = ENTRY_PX_S * eff.speedFactor;
    let i = pts.findIndex((p) => p.x > h.x) - 1;
    let pos = h.x;
    let min = v;
    for (let t = 0; t < 2; t += 0.01) {
      const a = Math.atan2(pts[i + 1].y - pts[i].y, pts[i + 1].x - pts[i].x);
      const lin = t * 1000 < eff.durationMs ? 0.2 / eff.speedFactor : 0.2;
      v = Math.max(0, v + (900 * Math.sin(a) * 0.65 - lin * v - 0.0003 * v * v) * 0.01);
      pos += v * Math.cos(a) * 0.01;
      while (i < pts.length - 2 && pos >= pts[i + 1].x) i++;
      min = Math.min(min, v);
    }
    void k;
    return min;
  }

  test.each([[1, 'groomerCat'], [8, 'seaweedTangle'], [64, 'chocolateRiver']])('mask %p: every %s placement keeps the sled moving (> 40 px/s) for 2 s after the hit', (mask, id) => {
    const ps = placements(mask, id);
    expect(ps.length).toBeGreaterThan(20);
    let worst = Infinity;
    for (const { g, ch, h } of ps) worst = Math.min(worst, minSpeedAfterHit(g, ch, h));
    console.log(`${id}: worst speed within 2 s of a hit from ${ENTRY_PX_S} px/s: ${worst.toFixed(1)} px/s over ${ps.length} placements`);
    expect(worst).toBeGreaterThan(40);
  });
});/**
 * B2 "Sight" content (spec §4 table and bounds): the biome hazard and power-up of Crystal Cavern (16) and Vertigo Vents
 * (1024). Loader + schema check for the new JSON, the values the spec names, the pairing rule (the Goggles ward off the
 * blind both B2 hazards cause, and the scramble of the base Garbage Data Vent), and the shield-source helpers that let
 * the biome-only Heat Shield report its own HUD chip.
 */
import { readDir, loadContent, makeGen } from './_helpers.js';
import { PALETTE_KEYS } from '../../src/constants.js';
import { emptyWards, addWard, isWarded, tickWards, WARD_MIN_MS, WARD_MAX_MS } from '../../src/systems/Wards.js';
import {
  hazardDrawKind, powerupDrawKind, hazardColorKey, BLIND_MIN_VISIBILITY, blindVisibility,
  addShieldSource, spendShieldSource, shieldChargesFor, SHIELD_DEFAULT_SOURCE,
} from '../../src/systems/BiomeEffects.js';
import { BIOME_SPAWN_MAX_CHANCE, BIOME_HAZARD_MAX_CHANCE } from '../../src/systems/TerrainGenerator.js';

const c = loadContent();
const biomeHaz = readDir('hazards').filter((d) => d.biome);
const biomePu = readDir('powerups').filter((d) => d.biome);

/** Spec §4 B2 rows. */
const B2 = {
  'crystal-cavern': { hazard: 'shatterWall', powerup: 'crystalClearGoggles' },
  'vertigo-vents': { hazard: 'ashCloud', powerup: 'heatShield' },
};
const B2_HAZ = Object.values(B2).map((r) => c.hazards[r.hazard]);
const B2_PU = Object.values(B2).map((r) => c.powerups[r.powerup]);

describe('B2 content: loader and schema', () => {
  test('exactly one hazard and one power-up per B2 biome; 6 biome hazards and 6 biome power-ups shipped after B1 + B2', () => {
    const byBiome = (list) => Object.fromEntries(Object.keys(B2).map((b) => [b, list.filter((d) => d.biome === b).map((d) => d.id)]));
    expect(byBiome(biomeHaz)).toEqual(Object.fromEntries(Object.entries(B2).map(([b, r]) => [b, [r.hazard]])));
    expect(byBiome(biomePu)).toEqual(Object.fromEntries(Object.entries(B2).map(([b, r]) => [b, [r.powerup]])));
    // B3 adds Pyramid Peak, Steampunk Slopes and Micro Mountain defs; the B1 + B2 biomes still hold exactly 6 + 6 (the
    // 9 + 9 total is pinned in biome-b3-content.test.js)
    const B1B2 = new Set([...Object.keys(B2), 'debutmont', 'garbage-dump-glacier', 'underwater-mountain', 'candy-cane-canyon']);
    expect(biomeHaz.filter((d) => B1B2.has(d.biome)).length).toBe(6);
    expect(biomePu.filter((d) => B1B2.has(d.biome)).length).toBe(6);
    for (const r of Object.values(B2)) {
      expect(c.hazards[r.hazard]).toBeDefined();
      expect(c.powerups[r.powerup]).toBeDefined();
    }
  });

  test('every B2 def names a real biome and follows the hazard / power-up schema and the §4 chance caps', () => {
    for (const h of B2_HAZ) {
      expect(c.biomes[h.biome]).toBeDefined();
      expect(h.size.w).toBeGreaterThan(0);
      expect(h.size.h).toBeGreaterThan(0);
      expect(h.weight).toBeGreaterThan(0);
      expect(h.minDistanceM).toBeGreaterThanOrEqual(0);
      expect(['ground', 'air']).toContain(h.placement);
      expect(PALETTE_KEYS).toContain(h.colorKey);
      expect(h.spawn.baseChance).toBeGreaterThan(0);
      expect(h.spawn.baseChance).toBeLessThanOrEqual(BIOME_HAZARD_MAX_CHANCE);
    }
    for (const p of B2_PU) {
      expect(c.biomes[p.biome]).toBeDefined();
      expect(p.radius).toBeGreaterThan(0);
      expect(PALETTE_KEYS).toContain(p.colorKey);
      expect(p.spawn.baseChance).toBeGreaterThan(0);
      expect(p.spawn.baseChance).toBeLessThanOrEqual(BIOME_SPAWN_MAX_CHANCE);
    }
  });

  test('every B2 shapeKey has its own drawing, all shapeKeys stay unique; the blind hazards are not drawn as danger', () => {
    for (const h of B2_HAZ) expect({ id: h.id, draw: hazardDrawKind(h) }).toEqual({ id: h.id, draw: h.shapeKey });
    for (const p of B2_PU) expect({ id: p.id, draw: powerupDrawKind(p) }).toEqual({ id: p.id, draw: p.shapeKey });
    const keys = [...biomeHaz, ...biomePu].map((d) => d.shapeKey);
    expect(new Set(keys).size).toBe(keys.length);
    for (const h of B2_HAZ) {
      expect(h.colorKey).not.toBe('danger'); // `danger` is for crash hazards (spec §4); a blind hit never crashes
      expect(hazardColorKey(h)).toBe(h.colorKey);
    }
  });
});

describe('B2 content: the spec §4 values', () => {
  test('Crystal Cavern: Shatter Wall is a ground blind of 1.2 s (no crash); Goggles ward blind and scramble for 6 s', () => {
    expect(c.hazards.shatterWall).toMatchObject({ placement: 'ground', onHit: { effect: 'blind', durationMs: 1200 } });
    expect(c.powerups.crystalClearGoggles.effect).toEqual({ kind: 'ward', durationMs: 6000, mods: [], hazards: [], effects: ['blind', 'scramble'] });
  });

  test('Vertigo Vents: Ash Cloud is an air blind (same kind and timing); Heat Shield is the existing shield, 1 charge', () => {
    expect(c.hazards.ashCloud).toMatchObject({ placement: 'air', onHit: { effect: 'blind', durationMs: 1200 } });
    expect(c.powerups.heatShield.effect).toEqual({ kind: 'shield', charges: 1 });
    // the same kind as the base Hashed Backup, but its own biome-only def
    expect(c.powerups.heatShield.effect.kind).toBe(c.powerups.hashedBackup.effect.kind);
    expect(c.powerups.hashedBackup.biome).toBeUndefined();
  });

  test('blind is readable: both B2 hazards keep >= 35 % visibility as defined (never clamped up from below)', () => {
    for (const h of B2_HAZ) {
      expect(h.onHit.visibility).toBeGreaterThanOrEqual(BLIND_MIN_VISIBILITY);
      expect(blindVisibility(h.onHit.visibility)).toBe(h.onHit.visibility);
    }
  });

  test('Shatter Wall fits the slot rule: its box fits in a base ground hazard box + 8 px (vent, firewall, chasm)', () => {
    const w = c.hazards.shatterWall.size;
    const fits = Object.values(c.hazards).filter((d) => !d.biome && d.placement === 'ground' && w.w <= d.size.w + 8 && w.h <= d.size.h + 8).map((d) => d.id).sort();
    expect(fits).toEqual(['garbageDataVent', 'glitchChasm', 'overflowFirewall']);
  });
});

describe('B2 content: each power-up counters its own biome', () => {
  test('the Goggles ward is inside the 4-6 s band (Wards.addWard keeps 6 s) and wards both B2 hazards and the base scramble', () => {
    const e = c.powerups.crystalClearGoggles.effect;
    expect(e.durationMs).toBeGreaterThanOrEqual(WARD_MIN_MS);
    expect(e.durationMs).toBeLessThanOrEqual(WARD_MAX_MS);
    const w = addWard(emptyWards(), 'crystalClearGoggles', e);
    expect(w.wards[0].msLeft).toBe(6000);
    expect(isWarded(w, { effect: c.hazards.shatterWall.onHit.effect })).toBe(true);
    expect(isWarded(w, { effect: c.hazards.ashCloud.onHit.effect })).toBe(true);
    expect(isWarded(w, { effect: c.hazards.garbageDataVent.onHit.effect })).toBe(true);
    expect(isWarded(w, { effect: 'crash' })).toBe(false);
    expect(isWarded(w, { effect: 'slow' })).toBe(false);
    expect(isWarded(w, { modId: c.biomes['crystal-cavern'].mod })).toBe(false); // echoZone is a score zone, not a hazard
    tickWards(w, 6001);
    expect(isWarded(w, { effect: 'blind' })).toBe(false);
  });

  test('Heat Shield is a biome-only shield: absent from mask 0, and the base Hashed Backup keeps its def', () => {
    const g = makeGen('b2-shield', { biomeMask: 0 });
    for (let i = 0; i < 120; i++) {
      const ch = g.getChunk(i);
      expect(ch.powerups.some((p) => p.defId === 'heatShield')).toBe(false);
      expect(ch.hazards.some((h) => h.defId === 'shatterWall' || h.defId === 'ashCloud')).toBe(false);
    }
  });
});

describe('BiomeEffects B2: shield sources (which pickup a spent shield charge came from)', () => {
  test('a spent charge reports the most recent source; with no tracked source it is the base Hashed Backup', () => {
    expect(SHIELD_DEFAULT_SOURCE).toBe('hashedBackup');
    let s = addShieldSource(undefined, 'hashedBackup', 1);
    s = addShieldSource(s, 'heatShield', 1);
    expect(s).toEqual(['hashedBackup', 'heatShield']);
    let r = spendShieldSource(s);
    expect(r.id).toBe('heatShield');
    r = spendShieldSource(r.sources);
    expect(r.id).toBe('hashedBackup');
    r = spendShieldSource(r.sources);
    expect(r).toEqual({ sources: [], id: 'hashedBackup' }); // a W4 boost charge is never tracked: it is the Backup's
  });

  test('addShieldSource does not mutate, and adds one entry per charge (at least 1)', () => {
    const a = ['hashedBackup'];
    const b = addShieldSource(a, 'heatShield', 2);
    expect(a).toEqual(['hashedBackup']);
    expect(b).toEqual(['hashedBackup', 'heatShield', 'heatShield']);
    expect(addShieldSource([], 'heatShield', 0)).toEqual(['heatShield']);
  });

  test('shieldChargesFor: a biome shield counts its own charges; the Hashed Backup keeps the pool minus the others (a lone Backup keeps it all)', () => {
    expect(shieldChargesFor(['hashedBackup'], 'hashedBackup', 2)).toBe(2); // 1 pickup + 1 boost charge: unchanged x2
    expect(shieldChargesFor(['hashedBackup', 'heatShield'], 'heatShield', 2)).toBe(1);
    expect(shieldChargesFor(['hashedBackup', 'heatShield'], 'hashedBackup', 2)).toBe(1);
    expect(shieldChargesFor(undefined, 'heatShield', 1)).toBe(0); // an untracked charge is never a Heat Shield's
    expect(shieldChargesFor(undefined, 'hashedBackup', 1)).toBe(1);
  });

  test('an untracked charge (Error Correction boost, granted at spawn) belongs to the Hashed Backup, never to the Heat Shield chip', () => {
    // pool 2 = 1 boost charge + 1 Heat Shield pickup
    expect(shieldChargesFor(['heatShield'], 'heatShield', 2)).toBe(1);
    expect(shieldChargesFor(['heatShield'], 'hashedBackup', 2)).toBe(1);
    // pool 3 = 1 boost charge + 1 Hashed Backup + 1 Heat Shield: the Backup chip keeps the boost charge as before B2
    expect(shieldChargesFor(['hashedBackup', 'heatShield'], 'hashedBackup', 3)).toBe(2);
    expect(shieldChargesFor(['hashedBackup', 'heatShield'], 'heatShield', 3)).toBe(1);
  });
});/**
 * B2 "Sight": the SHIPPED Crystal Cavern and Vertigo Vents defs through the shipped RunScene dispatch, HUD tables and
