import { jest } from '@jest/globals';

const Body = {
  getVelocity: (b) => ({ x: b.velocity.x, y: b.velocity.y }),
  setVelocity: (b, v) => { b.velocity = { x: v.x, y: v.y }; },
  getAngularVelocity: () => 0,
  setAngularVelocity: () => {},
};
class Stub { constructor() { this.alpha = 0; } setAlpha(a) { this.alpha = a; return this; } setFillStyle() { return this; } }
const FakePhaser = {
  Scene: class {},
  Physics: { Matter: { Matter: { Bodies: { rectangle: (x, y, w, h, o) => ({ x, y, w, h, ...o }), circle: (x, y, r, o) => ({ x, y, r, ...o }) }, Body } } },
  Renderer: { WebGL: { Pipelines: { PostFXPipeline: class {} } } },
  GameObjects: { Container: class {}, Graphics: class {}, BitmapText: class {}, Zone: class {}, Image: class {}, Rectangle: class {}, Text: class {} },
  BlendModes: { ADD: 1 },
  Scenes: { Events: { UPDATE: 'update', SHUTDOWN: 'shutdown', DESTROY: 'destroy' } },
  Math: { Between: (a) => a, Clamp: (v, a, b) => Math.min(b, Math.max(a, v)) },
};
jest.unstable_mockModule('phaser', () => ({ default: FakePhaser }));
jest.unstable_mockModule('../../src/shaders/GlitchPipeline.js', () => ({ GlitchPipeline: { install() {} } }));

const { RunScene } = await import('../../src/scenes/RunScene.js');
const { UIScene } = await import('../../src/scenes/UIScene.js');
const { Hazard } = await import('../../src/entities/Hazard.js');
const { PowerUp } = await import('../../src/entities/PowerUp.js');
const { EVT } = await import('../../src/events.js');
const { PhysicsTuner, BASE_STEP_MS } = await import('../../src/systems/PhysicsTuner.js');
const { BLIND_MIN_VISIBILITY } = await import('../../src/systems/BiomeEffects.js');
const { loadContent } = await import('./_helpers.js');

const C = loadContent();
const PAD = { tuck: false, brake: false };

function makeRun() {
  const emitted = [];
  const scaled = [];
  const s = Object.create(RunScene.prototype);
  Object.assign(s, {
    game: { events: { emit: (e, p) => { emitted.push([e, p]); } } },
    emitted,
    scaled,
    sled: {
      x: 1000, y: 0, vx: 300, vy: 20, inWorld: true, invulnerableMs: 0, grounded: true, parachuteMs: 0, airBrakeActive: false, shield: false,
      body: { velocity: { x: 300 * BASE_STEP_MS / 1000, y: 20 * BASE_STEP_MS / 1000 } },
      scaleVelocity(k) { scaled.push(k); }, wobble() {},
    },
    fx: { sparks() {}, ring() {} },
    shake() {},
    flashRect: new Stub(),
    blindRect: new Stub(),
    palette: { cyan: 1, amber: 2, lime: 3, bg: 0 },
    tuner: new PhysicsTuner(),
    dailyMods: {},
    crashed: false,
    pendingCrash: null,
    runTimeMs: 0,
    startX: 0,
    openingGraces: 0,
    slowMs: 0, slowFactor: 0.5, scrambleMs: 0, boostMs: 0, boostFactor: 1, slowmoMs: 0, slowmoScale: 0.5, shieldCharges: 0,
    collectedPowerups: new Set(),
    score: { onShieldHit: () => null, getSnapshot: () => ({ comboTricks: [] }) },
    emitFlow() {},
    _despawn: [],
  });
  s.getZoneDefs = () => [];
  s._resetBiomeEffects();
  return s;
}
const hit = (id) => ({ def: C.hazards[id], cx: 1000, cy: 0, color: 5, gfx: null, hit: false });
const take = (id) => ({ def: C.powerups[id], spawn: { x: 1000, y: 0 }, color: 5, destroy() {} });
const phys = (s) => s.tuner.getEffective(s.physicsContext(PAD));
const events = (s, name) => s.emitted.filter(([e]) => e === name).map(([, p]) => p);
const overlay = (s) => { s.updateBlindOverlay(); return s.blindRect.alpha; };

describe('B2 hazards through RunScene.onHazard (shipped defs)', () => {
  test.each(['shatterWall', 'ashCloud'])('%s: blind for 1.2 s: overlay up within the visibility floor, no crash, then clear', (id) => {
    const s = makeRun();
    const def = C.hazards[id];
    s.onHazard(hit(id));
    expect(s.pendingCrash).toBe(null);
    expect(s.scaled).toEqual([]); // no speed change
    expect(events(s, EVT.HAZARD_HIT)).toEqual([{ hazardId: id, effect: 'blind', durationMs: 1200, x: 1000, y: 0 }]);
    expect(s.flashRect.alpha).toBeGreaterThan(0); // the flash
    s.tickEffects(600);
    const mid = overlay(s);
    expect(mid).toBeCloseTo(1 - def.onHit.visibility, 9);
    expect(mid).toBeLessThanOrEqual(1 - BLIND_MIN_VISIBILITY + 1e-12);
    s.tickEffects(601);
    expect(overlay(s)).toBe(0);
    expect(events(s, EVT.EFFECT_END)).toEqual([{ effect: 'blind' }]);
  });
});

describe('B2 Crystal Clear Goggles (ward vs blind and scramble, 6 s)', () => {
  test('a Shatter Wall or Ash Cloud hit while the Goggles run does nothing (no HAZARD_HIT, overlay stays 0)', () => {
    const s = makeRun();
    s.onPowerUp(take('crystalClearGoggles'));
    expect(events(s, EVT.POWERUP_COLLECTED)).toEqual([{ id: 'crystalClearGoggles', durationMs: 6000, charges: 0 }]);
    s.onHazard(hit('shatterWall'));
    s.onHazard(hit('ashCloud'));
    expect(events(s, EVT.HAZARD_HIT)).toEqual([]);
    expect(s.blindMs).toBe(0);
    expect(overlay(s)).toBe(0);
  });

  test('a Garbage Data Vent scramble while the Goggles run does nothing (controls not inverted, no jitter)', () => {
    const plain = phys(makeRun());
    const sc = makeRun();
    sc.onHazard(hit('garbageDataVent'));
    expect(phys(sc).tiltSign).toBe(-1); // control: the scramble really acts without the Goggles
    const s = makeRun();
    s.onPowerUp(take('crystalClearGoggles'));
    s.onHazard(hit('garbageDataVent'));
    expect(events(s, EVT.HAZARD_HIT)).toEqual([]);
    expect(s.scrambleMs).toBe(0);
    expect(phys(s).tiltSign).toBe(plain.tiltSign);
    expect(phys(s).scrambleJitterDegS2).toBe(plain.scrambleJitterDegS2);
  });

  test('the Goggles also stop a blind and a scramble that are already acting', () => {
    const s = makeRun();
    s.onHazard(hit('shatterWall'));
    s.onHazard(hit('garbageDataVent'));
    s.tickEffects(300);
    expect(overlay(s)).toBeGreaterThan(0.3);
    expect(phys(s).tiltSign).toBe(-1);
    s.onPowerUp(take('crystalClearGoggles'));
    expect(overlay(s)).toBe(0);
    expect(phys(s).tiltSign).toBe(1);
  });

  test('after 6 s the Goggles expire under their own id and blind acts again', () => {
    const s = makeRun();
    s.onPowerUp(take('crystalClearGoggles'));
    s.tickEffects(6001);
    expect(events(s, EVT.POWERUP_EXPIRED)).toEqual([{ id: 'crystalClearGoggles', reason: 'timeout' }]);
    s.onHazard(hit('shatterWall'));
    expect(events(s, EVT.HAZARD_HIT).map((p) => p.hazardId)).toEqual(['shatterWall']);
    s.tickEffects(600);
    expect(overlay(s)).toBeGreaterThan(0.3);
  });
});

describe('B2 Heat Shield (the existing shield, 1 charge, its own HUD chip)', () => {
  test('a pickup adds 1 charge and raises the sled shield; a hazard crash is negated and the Heat Shield chip expires', () => {
    const s = makeRun();
    s.onPowerUp(take('heatShield'));
    expect(s.shieldCharges).toBe(1);
    expect(s.sled.shield).toBe(true);
    expect(events(s, EVT.POWERUP_COLLECTED)).toEqual([{ id: 'heatShield', durationMs: 0, charges: 1 }]);
    s.onHazard(hit('packetSpike'));
    expect(s.pendingCrash).toEqual({ cause: 'hazard', hazardId: 'packetSpike' });
    s.resolveCrash({ x: 2000, y: 0, vx: 300, vy: 0 });
    expect(s.crashed).toBe(false);
    expect(s.shieldCharges).toBe(0);
    expect(events(s, EVT.CRASH)).toEqual([expect.objectContaining({ hazardId: 'packetSpike', negated: true })]);
    expect(events(s, EVT.POWERUP_EXPIRED)).toEqual([{ id: 'heatShield', reason: 'consumed' }]);
  });

  test('with a Hashed Backup and a Heat Shield each chip shows its own x1, and each spend expires the right chip', () => {
    const s = makeRun();
    s.onPowerUp(take('hashedBackup'));
    s.onPowerUp(take('heatShield'));
    expect(events(s, EVT.POWERUP_COLLECTED).map((p) => [p.id, p.charges])).toEqual([['hashedBackup', 1], ['heatShield', 1]]);
    s.pendingCrash = { cause: 'hazard', hazardId: 'packetSpike' };
    s.resolveCrash({ x: 2000, y: 0, vx: 300, vy: 0 });
    s.sled.invulnerableMs = 0;
    s.pendingCrash = { cause: 'hazard', hazardId: 'packetSpike' };
    s.resolveCrash({ x: 2400, y: 0, vx: 300, vy: 0 });
    expect(events(s, EVT.POWERUP_EXPIRED).map((p) => p.id)).toEqual(['heatShield', 'hashedBackup']);
  });

  test('a lone Hashed Backup still expires as hashedBackup (base behaviour unchanged)', () => {
    const s = makeRun();
    s.onPowerUp(take('hashedBackup'));
    s.pendingCrash = { cause: 'hazard', hazardId: 'packetSpike' };
    s.resolveCrash({ x: 2000, y: 0, vx: 300, vy: 0 });
    expect(events(s, EVT.POWERUP_EXPIRED)).toEqual([{ id: 'hashedBackup', reason: 'consumed' }]);
  });
});

describe('B2 HUD entries (UIScene)', () => {
  const ui = () => Object.assign(Object.create(UIScene.prototype), { content: C, nowMs: 0, warnY: 40, effects: new Map() });
  const recorder = () => {
    const ops = [];
    return { ops, g: new Proxy({}, { get: (t, k) => (...a) => { ops.push([k, ...a]); return undefined; } }) };
  };
  const IDS = ['crystalClearGoggles', 'heatShield'];

  test('each B2 pickup has its own HUD name and colour', () => {
    const u = ui();
    expect(IDS.map((id) => u._powerInfo(id).name)).toEqual(['GOGGLES', 'HEAT SHIELD']);
    expect(IDS.map((id) => u._powerInfo(id).color)).toEqual(['cyan', 'magenta']);
  });

  test('each B2 pickup chip draws its own icon: not the unknown square, not the ward icon, not the Hashed Backup', () => {
    const u = ui();
    const draw = (id) => { const r = recorder(); u._drawIcon(r.g, id, 10, 10, 1); return JSON.stringify(r.ops.filter(([k]) => k !== 'lineStyle' && k !== 'fillStyle')); };
    const square = JSON.stringify([['strokeRect', 5, 5, 10, 10]]);
    const wardIcon = (() => {
      const v = Object.assign(Object.create(UIScene.prototype), { content: { powerups: { w: { effect: { kind: 'ward' } } } } });
      const r = recorder(); v._drawIcon(r.g, 'w', 10, 10, 1); return JSON.stringify(r.ops.filter(([k]) => k !== 'lineStyle' && k !== 'fillStyle'));
    })();
    const icons = IDS.map(draw);
    for (const ic of icons) {
      expect(ic).not.toBe(square);
      expect(ic).not.toBe(wardIcon);
      expect(ic).not.toBe(draw('hashedBackup'));
    }
    expect(new Set(icons).size).toBe(IDS.length);
  });

  test('a B2 blind names its hazard on the warning line; a nameless blind keeps BLINDED', () => {
    const u = ui();
    const made = [];
    u._t = () => { const t = { text: '', setText(x) { this.text = x; return t; }, setColorKey() { return t; }, destroy() {} }; made.push(t); return t; };
    u.onHazard({ hazardId: 'shatterWall', effect: 'blind', durationMs: 1200 });
    expect(made[0].text).toContain('SHATTER WALL');
    u._removeEffect('blind');
    u.onHazard({ hazardId: 'ashCloud', effect: 'blind', durationMs: 1200 });
    expect(made[1].text).toContain('ASH CLOUD');
    u._removeEffect('blind');
    u.onHazard({ effect: 'blind', durationMs: 1200 });
    expect(made[2].text).toContain('BLINDED');
  });
});

describe('B2 drawing: every new shapeKey has its own routine', () => {
  const PAL = { danger: 0xff0000, magenta: 0xff00ff, lime: 0x00ff00, cyan: 0x00ffff, amber: 0xffaa00, bg: 0, bgAlt: 1, text: 0xffffff };
  const scene = () => ({
    matter: { world: { add() {}, remove() {} } },
    add: {
      graphics: () => {
        const ops = [];
        const g = new Proxy({ ops, y: 0 }, {
          get: (t, k) => (k in t ? t[k] : (...a) => { ops.push([k, ...a]); return g; }),
          set: (t, k, v) => { t[k] = v; return true; },
        });
        return g;
      },
    },
  });
  const shape = (gfx) => JSON.stringify(gfx.ops.filter(([k]) => /^fill(Rect|Triangle|Points|Circle|Ellipse)$|^stroke|^lineBetween$/.test(k)).map(([k]) => k));

  test('both hazards draw non-generic, mutually different shapes, in their own colour (not danger)', () => {
    const out = {};
    for (const id of ['shatterWall', 'ashCloud']) {
      const def = C.hazards[id];
      const h = new Hazard(scene(), def, { x: 100, y: 50, rotationDeg: 0 }, PAL);
      expect(h.drawKind).toBe(def.shapeKey);
      expect(h.color).toBe(PAL[def.colorKey]);
      out[id] = shape(h.gfx);
      const generic = new Hazard(scene(), { ...def, shapeKey: 'zzUnknownShape' }, { x: 100, y: 50, rotationDeg: 0 }, PAL);
      expect(generic.drawKind).toBe('generic');
      expect(out[id]).not.toBe(shape(generic.gfx));
    }
    expect(new Set(Object.values(out)).size).toBe(2);
  });

  test('the Shatter Wall keeps the usual hit-box brackets (telegraphable like any ground hazard)', () => {
    const h = new Hazard(scene(), C.hazards.shatterWall, { x: 100, y: 50, rotationDeg: 0 }, PAL);
    expect(h.gfx.ops.filter(([k]) => k === 'lineBetween').length).toBeGreaterThanOrEqual(8);
  });

  test('both pickups draw non-generic glyphs, different from each other and from the Hashed Backup shield', () => {
    const out = {};
    for (const id of ['crystalClearGoggles', 'heatShield', 'hashedBackup']) {
      const def = C.powerups[id];
      const p = new PowerUp(scene(), def, { x: 100, y: 50 }, PAL);
      expect(p.drawKind).toBe(def.shapeKey);
      out[id] = shape(p.gfx);
      const generic = new PowerUp(scene(), { ...def, shapeKey: 'zzUnknownGlyph' }, { x: 100, y: 50 }, PAL);
      expect(out[id]).not.toBe(shape(generic.gfx));
    }
    expect(new Set(Object.values(out)).size).toBe(3);
  });
});/**
 * B2 "Sight" placement: presence (spec §4 presence amendment, same target and method as biome-b1-presence.test.js), the
 * blind fairness rule (TerrainGenerator.blindClearAheadPx: no crash hazard in the stretch the sled rides blinded), and
 * determinism for masks 16 and 1024 (shipped content).
 */
import { makeGen, loadContent } from './_helpers.js';
import {
  BIOME_HAZARD_CLEARANCE_PX, BIOME_BLIND_REACT_MS, BIOME_BLIND_SPEED_MUL, blindClearAheadPx, expectedSpeedPxS,
} from '../../src/systems/TerrainGenerator.js';

const c = loadContent();
const SEEDS = ['pres1', 'pres2', 'pres3', 'pres4', 'pres5', 'pres6', 'pres7', 'pres8'];
const ROB = Array.from({ length: 32 }, (_, k) => `rob${k + 1}`);
// re-pinned for #65: Debutmont base + arcade bridges. Same re-assessment as biome-b1-presence.test.js: the generator's hazard
// rates are unchanged (400 seeds, +/-0.02), the sample is ~25 % smaller because each biome sector opens with an arcade bridge,
// so the band is asserted on BIG (150 seeds) and the per-seed 1-per-2-km rule on seeds with >= SHORT_KM of the biome.
const BIG = Array.from({ length: 150 }, (_, k) => `big${k + 1}`);
const SHORT_KM = 1;
/** Chunks the generator can place the def in: air hazards only in generated jumps (isJump), ground never in a bridge or jump. */
const eligibleFor = (def, ch) => (def.placement === 'air' ? ch.defId === 'gen-jump' : ch.kind !== 'bridge' && ch.defId !== 'gen-jump');
const isCrash = (id) => { const d = c.hazards[id]; return !d.onHit || d.onHit.effect === 'crash'; };

function presence(mask, biome, id, seeds) {
  const def = c.hazards[id];
  let elig = 0;
  let has = 0;
  const perSeed = [];
  for (const seed of seeds) {
    const g = makeGen(seed, { biomeMask: mask });
    let km = 0;
    let n = 0;
    for (let i = 1; i < 45; i++) {
      const ch = g.getChunk(i);
      if (ch.biome !== biome) continue;
      km += (ch.endX - ch.startX) / 20000;
      const here = ch.hazards.some((q) => q.defId === id);
      if (here) n++;
      if (eligibleFor(def, ch)) { elig++; if (here) has++; }
    }
    perSeed.push({ seed, n, km: +km.toFixed(2), ok: km < SHORT_KM || n * 2 >= km });
  }
  const share = has / elig;
  console.log(`${id} (${seeds.length} seeds): ${has}/${elig} eligible = ${(100 * share).toFixed(1)} %; per seed ${perSeed.map((p) => `${p.n}/${p.km}km`).join(' ')}`);
  return { elig, share, perSeed, fails: perSeed.filter((p) => !p.ok).length };
}

describe('B2 presence: the biome hazard is felt in early terrain (chunks 0-44, single biome bit)', () => {
  test('mask 16 (crystal-cavern): shatterWall meets the full target (band on 150 seeds, 1 per 2 km on every seed with >= 1 km of biome)', () => {
    const a = presence(16, 'crystal-cavern', 'shatterWall', SEEDS);
    expect(a.elig).toBeGreaterThanOrEqual(15);
    for (const p of a.perSeed) expect(p).toMatchObject({ ok: true });
    const b = presence(16, 'crystal-cavern', 'shatterWall', ROB);
    expect(b.fails).toBeLessThanOrEqual(2); // measured 0 at #65, among seeds with >= 1 km of Crystal terrain in chunks 0-44
    const big = presence(16, 'crystal-cavern', 'shatterWall', BIG);
    expect(big.share).toBeGreaterThanOrEqual(0.35);
    expect(big.share).toBeLessThanOrEqual(0.55);
  });

  test('mask 1024 (vertigo-vents): ashCloud meets the band (150 seeds); OPEN for the lead (as B1 seagullDive): the 1-per-2-km rule fails on some seeds', () => {
    // An air hazard sits only in a generated jump of a Vertigo sector, above the no-hop arc (the existing air pass; the
    // spec's "air zone" uses it, as "no new mechanism" for Vertigo requires). Chance is at the 0.75 cap already.
    const a = presence(1024, 'vertigo-vents', 'ashCloud', SEEDS);
    expect(a.fails).toBeLessThanOrEqual(2); // measured 0 of the seeds with >= 1 km of Vertigo terrain at #65
    const b = presence(1024, 'vertigo-vents', 'ashCloud', ROB);
    expect(b.fails).toBeLessThanOrEqual(5); // measured 2 of 22 seeds with >= 1 km at #65 (an air hazard needs a generated jump)
    const big = presence(1024, 'vertigo-vents', 'ashCloud', BIG);
    expect(big.share).toBeGreaterThanOrEqual(0.35);
    expect(big.share).toBeLessThanOrEqual(0.55);
  });
});

describe('B2 presence: long range (4 seeds x 300 chunks), hazard floor and power-up band', () => {
  const ROWS = [
    [16, 'crystal-cavern', 'shatterWall', 'crystalClearGoggles', 0.35, 0.25, 0.45],
    // Heat Shield chance 0.25 (19 % of Vertigo chunks), below B1's 25-45 % power-up band on purpose: at 0.4 (32 %) the
    // extra shield charges lifted hop survival on mask 1024 by +22 % (18 -> 22 of 48), outside the +/-15 % sim tolerance.
    [1024, 'vertigo-vents', 'ashCloud', 'heatShield', 0.25, 0.12, 0.3],
  ];
  test.each(ROWS)('mask %p (%s): hazard %s, power-up %s, hazard share of eligible chunks >= %p, power-up share of biome chunks in [%p, %p]', (mask, biome, hz, pu, floor, lo, hi) => {
    let all = 0;
    let elig = 0;
    let h = 0;
    let p = 0;
    for (const seed of ['b1-share-a', 'b1-share-b', 'b1-share-c', 'b1-share-d']) {
      const g = makeGen(seed, { biomeMask: mask });
      for (let i = 1; i < 300; i++) {
        const ch = g.getChunk(i);
        if (ch.biome !== biome) continue;
        all++;
        if (eligibleFor(c.hazards[hz], ch)) elig++;
        if (ch.hazards.some((q) => q.defId === hz)) h++;
        if (ch.powerups.some((q) => q.defId === pu)) p++;
      }
    }
    console.log(`${hz}: ${h}/${elig} eligible = ${(100 * h / elig).toFixed(1)} %; ${pu}: ${p}/${all} = ${(100 * p / all).toFixed(1)} %`);
    expect(elig).toBeGreaterThan(60);
    expect(h / elig).toBeGreaterThanOrEqual(floor);
    expect(p / all).toBeGreaterThanOrEqual(lo);
    expect(p / all).toBeLessThanOrEqual(hi);
  });
});

/** Every hazard of 300 chunks of one seed + mask, in x order. */
function allHazards(seed, mask) {
  const g = makeGen(seed, { biomeMask: mask });
  const out = [];
  for (let i = 0; i < 300; i++) { const ch = g.getChunk(i); for (const h of ch.hazards) out.push({ ...h, chunk: ch.index, endX: ch.endX }); }
  return out;
}

describe('B2 blind fairness: a hazard hidden by blind is not a cheap death', () => {
  test('blindClearAheadPx = (durationMs + react) at 1.2 x the expected speed', () => {
    expect(BIOME_BLIND_REACT_MS).toBe(500);
    expect(BIOME_BLIND_SPEED_MUL).toBe(1.2);
    expect(blindClearAheadPx({ durationMs: 1200 }, 2000)).toBe(Math.round(expectedSpeedPxS(2000) * 1.2 * 1.7));
    expect(blindClearAheadPx({}, 0)).toBe(Math.round(340 * 1.2 * 1.7));
  });

  test('no Shatter Wall has a crash hazard of its own chunk inside its blind stretch; keeps 240 px from every hazard', () => {
    let n = 0;
    for (const seed of ['fair1', 'fair2', 'fair3', 'fair4', 'fair5', 'fair6', 'fair7', 'fair8']) {
      const hs = allHazards(seed, 16);
      for (const w of hs.filter((h) => h.defId === 'shatterWall')) {
        n++;
        const ahead = blindClearAheadPx(c.hazards.shatterWall.onHit, w.x / 20);
        for (const q of hs) {
          if (q === w) continue;
          expect(Math.abs(q.x - w.x)).toBeGreaterThanOrEqual(BIOME_HAZARD_CLEARANCE_PX);
          if (q.chunk === w.chunk && q.x > w.x && isCrash(q.defId)) expect({ id: q.defId, gap: q.x - w.x, ok: q.x - w.x > ahead }).toMatchObject({ ok: true });
        }
      }
    }
    expect(n).toBeGreaterThan(100);
  });

  test('measured: under 5 % of Shatter Walls (and no Ash Cloud) meet a crash hazard within the 1.2 s blind at the expected speed', () => {
    // Without the rule 268 of 910 Shatter Walls (29 %) did. The residue is all in the NEXT chunk, which the pass cannot see.
    for (const [mask, id, max] of [[16, 'shatterWall', 0.05], [1024, 'ashCloud', 0]]) {
      let n = 0;
      let met = 0;
      let sameChunk = 0;
      for (let s = 1; s <= 32; s++) {
        const hs = allHazards(`fair${s}`, mask);
        for (const w of hs.filter((h) => h.defId === id)) {
          n++;
          const next = hs.find((q) => q.x > w.x && isCrash(q.defId));
          if (next && next.x - w.x <= expectedSpeedPxS(w.x / 20) * 1.2) { met++; if (next.chunk === w.chunk) sameChunk++; }
        }
      }
      console.log(`${id}: ${met}/${n} placements meet a crash hazard within the 1.2 s blind at the expected speed (${sameChunk} in the same chunk)`);
      expect(n).toBeGreaterThan(200);
      expect(met / n).toBeLessThanOrEqual(max);
      expect(sameChunk).toBe(0);
    }
  });

  // The rule binds only `blind` defs: masks 1, 2, 8, 64 (B1 content) keep their e080803 digests in
  // micro-swell-isolation.test.js, which still includes every B1 def.
});

describe('B2 invariant: same seed + mask gives identical terrain twice (shipped content)', () => {
  test.each([16, 1024])('mask %p: two generators, forward and reverse call order, deep-equal over 150 chunks', (mask) => {
    const snap = (ch) => JSON.parse(JSON.stringify(ch));
    const a = makeGen('b2-det', { biomeMask: mask });
    const b = makeGen('b2-det', { biomeMask: mask });
    const rev = [];
    for (let i = 149; i >= 0; i--) rev[i] = snap(b.getChunk(i));
    let biomeSpawns = 0;
    for (let i = 0; i < 150; i++) {
      const ch = snap(a.getChunk(i));
      expect(ch).toEqual(rev[i]);
      biomeSpawns += [...ch.hazards, ...ch.powerups].filter((s) => (c.hazards[s.defId] || c.powerups[s.defId]).biome).length;
    }
    expect(biomeSpawns).toBeGreaterThan(0);
  });
});/**
 * B3 "Motion" content (spec §4 table and bounds): the biome hazard and power-up of Pyramid Peak (4), Steampunk Slopes
 * (256) and Micro Mountain (512). Loader + schema check for the new JSON, the values the spec names, the motion blocks
 * the generator and Hazard.js read, and the pairing rule (each pickup counters its own biome: the glides lower the ground
 * friction, the Clockwork Treads ward off the Steampunk conveyor belt).
 */
import { readDir, loadContent, makeGen } from './_helpers.js';
import { PALETTE_KEYS } from '../../src/constants.js';
import { emptyWards, addWard, isWarded, tickWards, WARD_MIN_MS, WARD_MAX_MS } from '../../src/systems/Wards.js';
import { hazardDrawKind, powerupDrawKind, hazardColorKey, glideFrictionMul, timedPowerupMs, glideStrength, glideDrag } from '../../src/systems/BiomeEffects.js';
import { rollParams, gateTiming, GATE_MAX_CLOSED_MS, ROLL_MAX_RANGE_PX } from '../../src/systems/HazardMotion.js';
import { BIOME_SPAWN_MAX_CHANCE, BIOME_HAZARD_MAX_CHANCE, BIOME_REPLACE_SLACK_PX } from '../../src/systems/TerrainGenerator.js';
import { PhysicsTuner } from '../../src/systems/PhysicsTuner.js';

const c = loadContent();
const biomeHaz = readDir('hazards').filter((d) => d.biome);
const biomePu = readDir('powerups').filter((d) => d.biome);

/** Spec §4 B3 rows. */
const B3 = {
  'pyramid-peak': { hazard: 'rollingBoulder', powerup: 'sandrunnerSkis', motion: 'roll' },
  'steampunk-slopes': { hazard: 'gearGate', powerup: 'clockworkTreads', motion: 'gate' },
  'micro-mountain': { hazard: 'dewDrop', powerup: 'royalJellyWax', motion: 'roll' },
};
const B3_HAZ = Object.values(B3).map((r) => c.hazards[r.hazard]);
const B3_PU = Object.values(B3).map((r) => c.powerups[r.powerup]);

describe('B3 content: loader and schema', () => {
  test('exactly one hazard and one power-up per B3 biome; 9 biome hazards and 9 biome power-ups shipped after B1-B3', () => {
    const byBiome = (list) => Object.fromEntries(Object.keys(B3).map((b) => [b, list.filter((d) => d.biome === b).map((d) => d.id)]));
    expect(byBiome(biomeHaz)).toEqual(Object.fromEntries(Object.entries(B3).map(([b, r]) => [b, [r.hazard]])));
    expect(byBiome(biomePu)).toEqual(Object.fromEntries(Object.entries(B3).map(([b, r]) => [b, [r.powerup]])));
    // B4 adds Space Mountain and Sky Jellyfish Mountain defs; the B1-B3 biomes still hold exactly 9 + 9 (the 11 + 11 total
    // is pinned in biome-b4-content.test.js)
    const B4_BIOMES = new Set(['space-mountain', 'sky-jellyfish-mountain']);
    expect(biomeHaz.filter((d) => !B4_BIOMES.has(d.biome)).length).toBe(9);
    expect(biomePu.filter((d) => !B4_BIOMES.has(d.biome)).length).toBe(9);
    for (const r of Object.values(B3)) {
      expect(c.hazards[r.hazard]).toBeDefined();
      expect(c.powerups[r.powerup]).toBeDefined();
    }
  });

  test('every B3 def names a real biome and follows the hazard / power-up schema and the §4 chance caps', () => {
    for (const h of B3_HAZ) {
      expect(c.biomes[h.biome]).toBeDefined();
      expect(h.size.w).toBeGreaterThan(0);
      expect(h.size.h).toBeGreaterThan(0);
      expect(h.weight).toBeGreaterThan(0);
      expect(h.minDistanceM).toBeGreaterThanOrEqual(0);
      expect(h.placement).toBe('ground');
      expect(PALETTE_KEYS).toContain(h.colorKey);
      expect(h.spawn.baseChance).toBeGreaterThan(0);
      expect(h.spawn.baseChance).toBeLessThanOrEqual(BIOME_HAZARD_MAX_CHANCE);
    }
    for (const p of B3_PU) {
      expect(c.biomes[p.biome]).toBeDefined();
      expect(p.radius).toBeGreaterThan(0);
      expect(PALETTE_KEYS).toContain(p.colorKey);
      expect(p.spawn.baseChance).toBeGreaterThan(0);
      expect(p.spawn.baseChance).toBeLessThanOrEqual(BIOME_SPAWN_MAX_CHANCE);
    }
  });

  test('every B3 shapeKey has its own drawing and all biome shapeKeys stay unique', () => {
    for (const h of B3_HAZ) expect({ id: h.id, draw: hazardDrawKind(h) }).toEqual({ id: h.id, draw: h.shapeKey });
    for (const p of B3_PU) expect({ id: p.id, draw: powerupDrawKind(p) }).toEqual({ id: p.id, draw: p.shapeKey });
    const keys = [...biomeHaz, ...biomePu].map((d) => d.shapeKey);
    expect(new Set(keys).size).toBe(keys.length);
  });

  test('all three B3 hazards crash, so they are `danger` in both the JSON and hazardColorKey (the palette switch reads the JSON)', () => {
    for (const h of B3_HAZ) {
      expect(h.onHit).toEqual({ effect: 'crash' });
      expect(h.colorKey).toBe('danger');
      expect(hazardColorKey(h)).toBe('danger');
    }
  });
});

describe('B3 content: the spec §4 values and the motion blocks', () => {
  test('Pyramid Peak: Rolling Boulder rolls (motion roll, B3 tuning: downhill away from the sled, capped at 80 px/s), crash on contact', () => {
    const b = c.hazards.rollingBoulder;
    expect(b.motion.kind).toBe('roll');
    expect(rollParams(b.motion)).toEqual({ speedPxS: 80, rangePx: 120, dir: 1 }); // inside the bounds: not clamped
  });

  test('Micro Mountain: Dew Drop reuses motion roll (smaller and slower than the boulder), crash on contact', () => {
    const d = c.hazards.dewDrop;
    expect(d.motion.kind).toBe('roll');
    const p = rollParams(d.motion);
    expect(p).toEqual({ speedPxS: 75, rangePx: 120, dir: 1 });
    expect(p.speedPxS).toBeLessThanOrEqual(rollParams(c.hazards.rollingBoulder.motion).speedPxS);
    expect(p.rangePx).toBeLessThanOrEqual(ROLL_MAX_RANGE_PX);
    expect(d.size.w * d.size.h).toBeLessThan(c.hazards.rollingBoulder.size.w * c.hazards.rollingBoulder.size.h);
  });

  test('Steampunk Slopes: Gear Gate opens and closes on a period (motion gate), closed spell inside the fairness bound', () => {
    const g = c.hazards.gearGate;
    expect(g.motion.kind).toBe('gate');
    const t = gateTiming(g.motion);
    expect(t).toEqual({ periodMs: g.motion.periodMs, openMs: g.motion.openMs, closedMs: g.motion.periodMs - g.motion.openMs });
    expect(t.closedMs).toBeLessThanOrEqual(GATE_MAX_CLOSED_MS);
    expect(t.openMs).toBeGreaterThan(t.closedMs);
  });

  test('B3 tuning: Sandrunner Skis are a short punchy slick burst, Royal Jelly Wax a longer gentler glide (both kind glide)', () => {
    const skis = c.powerups.sandrunnerSkis.effect;
    const jelly = c.powerups.royalJellyWax.effect;
    expect(skis).toEqual({ kind: 'glide', frictionMul: 0.3, durationMs: 2000 });
    expect(jelly).toEqual({ kind: 'glide', frictionMul: 0.55, durationMs: 5000 });
    for (const e of [skis, jelly]) {
      expect(glideFrictionMul(e.frictionMul)).toBe(e.frictionMul); // inside the bounds: not clamped
      expect(timedPowerupMs(e)).toBe(e.durationMs);
    }
    // their own flavours: the Skis are slicker and shorter, the wax gentler and longer
    expect(glideStrength(skis.frictionMul)).toBeGreaterThan(glideStrength(jelly.frictionMul));
    expect(skis.durationMs).toBeLessThan(jelly.durationMs);
  });

  test('Clockwork Treads: ward against the conveyorBelt mod for 4 s', () => {
    expect(c.powerups.clockworkTreads.effect).toEqual({ kind: 'ward', durationMs: 4000, mods: ['conveyorBelt'], hazards: [], effects: [] });
  });

  test('each B3 hazard fits the slot rule (its box fits in a base ground hazard box + 8 px)', () => {
    for (const h of B3_HAZ) {
      const fits = Object.values(c.hazards).filter((d) => !d.biome && d.placement === 'ground'
        && h.size.w <= d.size.w + BIOME_REPLACE_SLACK_PX && h.size.h <= d.size.h + BIOME_REPLACE_SLACK_PX);
      expect({ id: h.id, fits: fits.length > 0 }).toEqual({ id: h.id, fits: true });
    }
  });
});

describe('B3 content: each power-up counters its own biome', () => {
  test('Clockwork Treads ward the Steampunk mod (conveyorBelt) and nothing a B3 hazard does', () => {
    const e = c.powerups.clockworkTreads.effect;
    expect(e.durationMs).toBeGreaterThanOrEqual(WARD_MIN_MS);
    expect(e.durationMs).toBeLessThanOrEqual(WARD_MAX_MS);
    const w = addWard(emptyWards(), 'clockworkTreads', e);
    expect(c.biomes['steampunk-slopes'].mod).toBe('conveyorBelt');
    expect(isWarded(w, { modId: 'conveyorBelt' })).toBe(true);
    expect(isWarded(w, { modId: 'stickyPatch' })).toBe(false);
    expect(isWarded(w, { hazardId: 'gearGate' })).toBe(false);
    expect(isWarded(w, { effect: 'crash' })).toBe(false);
    // the conveyor's drive is gone while the Treads run, and back after 4 s
    const t = new PhysicsTuner();
    const zone = [c.terrainMods.conveyorBelt];
    expect(t.getEffective({ zones: zone }).beltDrivePxS2).toBeGreaterThan(0);
    expect(t.getEffective({ zones: zone, wards: w }).beltDrivePxS2).toBe(0);
    tickWards(w, 4001);
    expect(t.getEffective({ zones: zone, wards: w }).beltDrivePxS2).toBeGreaterThan(0);
  });

  test('a glide lowers all three drags of the real tuner in each glide biome (no zone needed)', () => {
    const t = new PhysicsTuner();
    const base = t.getEffective({});
    for (const id of ['sandrunnerSkis', 'royalJellyWax']) {
      const m = glideFrictionMul(c.powerups[id].effect.frictionMul);
      const g = t.getEffective({ glideFrictionMul: m });
      const d = glideDrag(1, m);
      expect(g.groundResist).toBeCloseTo(base.groundResist * m, 12);
      expect(g.frictionAir).toBeCloseTo(base.frictionAir / d.speedMul, 12);
      expect(g.quadDrag).toBeCloseTo(base.quadDrag * d.quadMul, 12);
      expect(d.speedMul).toBeGreaterThan(1.1);
    }
  });

  test('no B3 def appears at mask 0', () => {
    const ids = new Set([...B3_HAZ, ...B3_PU].map((d) => d.id));
    const g = makeGen('b3-mask0', { biomeMask: 0 });
    for (let i = 0; i < 120; i++) {
      const ch = g.getChunk(i);
      expect(ch.hazards.some((h) => ids.has(h.defId))).toBe(false);
      expect(ch.powerups.some((p) => ids.has(p.defId))).toBe(false);
    }
  });
});/**
 * B3 "Motion": the SHIPPED Pyramid Peak, Steampunk Slopes and Micro Mountain defs through the shipped Hazard entity
 * (motion, drawing), RunScene dispatch (an open Gear Gate is passed, a closed one crashes; glide; Treads ward) and HUD
 * tables. Same fake Phaser seam as biome-b2-effects.test.js. The built-game gate checks the same effects on the real sled.
 */
import { jest } from '@jest/globals';

const moved = [];
const Body = {
  getVelocity: (b) => ({ x: b.velocity.x, y: b.velocity.y }),
  setVelocity: (b, v) => { b.velocity = { x: v.x, y: v.y }; },
  getAngularVelocity: () => 0,
  setAngularVelocity: () => {},
  setPosition: (b, p) => { b.x = p.x; b.y = p.y; moved.push(p); },
  setAngle: (b, a) => { b.angle = a; },
};
class Stub { constructor() { this.alpha = 0; } setAlpha(a) { this.alpha = a; return this; } setFillStyle() { return this; } }
const FakePhaser = {
  Scene: class {},
  Physics: { Matter: { Matter: { Bodies: { rectangle: (x, y, w, h, o) => ({ x, y, w, h, ...o }), circle: (x, y, r, o) => ({ x, y, r, ...o }) }, Body } } },
  Renderer: { WebGL: { Pipelines: { PostFXPipeline: class {} } } },
  GameObjects: { Container: class {}, Graphics: class {}, BitmapText: class {}, Zone: class {}, Image: class {}, Rectangle: class {}, Text: class {} },
  BlendModes: { ADD: 1 },
  Scenes: { Events: { UPDATE: 'update', SHUTDOWN: 'shutdown', DESTROY: 'destroy' } },
  Math: { Between: (a) => a, Clamp: (v, a, b) => Math.min(b, Math.max(a, v)) },
};
jest.unstable_mockModule('phaser', () => ({ default: FakePhaser }));
jest.unstable_mockModule('../../src/shaders/GlitchPipeline.js', () => ({ GlitchPipeline: { install() {} } }));

const { RunScene } = await import('../../src/scenes/RunScene.js');
const { UIScene } = await import('../../src/scenes/UIScene.js');
const { Hazard } = await import('../../src/entities/Hazard.js');
const { PowerUp } = await import('../../src/entities/PowerUp.js');
const { EVT } = await import('../../src/events.js');
const { PhysicsTuner, BASE_STEP_MS } = await import('../../src/systems/PhysicsTuner.js');
const { ROLL_ACTIVATE_PX, gateOpenAt, gateTiming, rollOffsetAt, rollParams } = await import('../../src/systems/HazardMotion.js');
const { loadContent, makeGen } = await import('./_helpers.js');
const { glideDrag } = await import('../../src/systems/BiomeEffects.js');

const C = loadContent();
const PAD = { tuck: false, brake: false };
const PAL = { danger: 0xff0000, magenta: 0xff00ff, lime: 0x00ff00, cyan: 0x00ffff, amber: 0xffaa00, bg: 0, bgAlt: 1, text: 0xffffff };

/** A fake scene for the entity: graphics that record draw calls and keep their position, a sled, the ground. */
function scene({ sledX = -1e9, heightAt = (x) => 200 + x * 0.25, slopeAt = () => Math.atan(0.25) * 180 / Math.PI } = {}) {
  return {
    matter: { world: { add() {}, remove() {} } },
    sled: { x: sledX },
    heightFn: heightAt,
    terrain: { slopeDegAt: slopeAt, heightAt },
    add: {
      graphics: (o) => {
        const ops = [];
        const g = new Proxy({ ops, x: o ? o.x : 0, y: o ? o.y : 0, rotation: 0, visible: true }, {
          get: (t, k) => {
            if (k in t) return t[k];
            if (k === 'setPosition') return (x, y) => { t.x = x; t.y = y; return g; };
            if (k === 'setRotation') return (r) => { t.rotation = r; return g; };
            if (k === 'setVisible') return (v) => { t.visible = v; return g; };
            if (k === 'clear') return () => { ops.length = 0; return g; };
            return (...a) => { ops.push([k, ...a]); return g; };
          },
          set: (t, k, v) => { t[k] = v; return true; },
        });
        return g;
      },
    },
  };
}
const spawnOn = (sc, x, extra = {}) => ({ x, y: sc.heightFn(x), rotationDeg: sc.terrain.slopeDegAt(x), ...extra });

function makeRun({ zones = [] } = {}) {
  const emitted = [];
  const s = Object.create(RunScene.prototype);
  Object.assign(s, {
    game: { events: { emit: (e, p) => { emitted.push([e, p]); } } },
    emitted,
    sled: {
      x: 1000, y: 0, vx: 300, vy: 20, inWorld: true, invulnerableMs: 0, grounded: true, parachuteMs: 0, airBrakeActive: false, shield: false,
      body: { velocity: { x: 300 * BASE_STEP_MS / 1000, y: 20 * BASE_STEP_MS / 1000 } },
      scaleVelocity() {}, wobble() {},
    },
    fx: { sparks() {}, ring() {} },
    shake() {},
    flashRect: new Stub(),
    blindRect: new Stub(),
    palette: { cyan: 1, amber: 2, lime: 3, bg: 0 },
    tuner: new PhysicsTuner(),
    dailyMods: {},
    crashed: false,
    pendingCrash: null,
    runTimeMs: 0,
    startX: 0,
    openingGraces: 0,
    slowMs: 0, slowFactor: 0.5, scrambleMs: 0, boostMs: 0, boostFactor: 1, slowmoMs: 0, slowmoScale: 0.5, shieldCharges: 0,
    collectedPowerups: new Set(),
    score: { onShieldHit: () => null, getSnapshot: () => ({ comboTricks: [] }) },
    emitFlow() {},
    _despawn: [],
  });
  s.getZoneDefs = () => zones;
  s._resetBiomeEffects();
  return s;
}
const take = (id) => ({ def: C.powerups[id], spawn: { x: 1000, y: 0 }, color: 5, destroy() {} });
const phys = (s) => s.tuner.getEffective(s.physicsContext(PAD));
const events = (s, name) => s.emitted.filter(([e]) => e === name).map(([, p]) => p);

describe('B3 rolling hazards: the shipped entity moves along the ground (Hazard.update -> HazardMotion.rollStep)', () => {
  test.each(['rollingBoulder', 'dewDrop'])('%s waits at its spawn until the sled is within ROLL_ACTIVATE_PX, then rolls downhill, away from it', (id) => {
    const sc = scene();
    const x0 = 3000;
    const h = new Hazard(sc, C.hazards[id], spawnOn(sc, x0), PAL);
    const cx0 = h.cx;
    const cy0 = h.cy;
    sc.sled.x = x0 - ROLL_ACTIVATE_PX - 50;
    h.update(1000, 0, 99999);
    h.update(3000, 0, 99999);
    expect(h.cx).toBe(cx0); // not started
    expect(h.rolling).toBeFalsy();
    sc.sled.x = x0 - ROLL_ACTIVATE_PX;
    h.update(3000, 0, 99999); // starts here
    h.update(3500, 0, 99999);
    const m = C.hazards[id].motion;
    const off = rollOffsetAt(m, 500, sc.terrain.slopeDegAt, x0); // the pure motion over the ground the entity rides
    expect(off).toBeGreaterThan(20);
    expect(h.cx - cx0).toBeCloseTo(off, 6); // downhill (+x), away from the sled
    expect(h.roll.vPxS).toBeGreaterThan(0);
    expect(h.roll.vPxS).toBeLessThanOrEqual(rollParams(m).speedPxS);
    expect(h.predictX(4000)).toBeCloseTo(x0 + rollOffsetAt(m, 1000, sc.terrain.slopeDegAt, x0), 6); // the telegraph API
    expect(h.rolling).toBe(true);
    // it follows the ground: y moves with heightAt at its new x (the box centre stays h/2 above the surface)
    expect(h.cy).toBeGreaterThan(cy0);
    const box = h._boxAt(h.gfx.x, h.gfx.y, h.gfx.rotation);
    expect(h.body.x).toBeCloseTo(box.bcx, 9); // the sensor moved with it (same hit-box geometry as a static hazard)
    expect(h.body.y).toBeCloseTo(box.bcy, 9);
    expect(h.body.angle).toBeCloseTo(h.gfx.rotation, 12);
    expect(h.gfx.x).toBeCloseTo(x0 + off, 6);
    expect(h.gfx.y).toBeCloseTo(sc.heightFn(x0 + off), 6);
    // after its range it rests
    h.update(60000, 0, 99999);
    expect(h.gfx.x).toBeCloseTo(x0 + C.hazards[id].motion.rangePx, 6);
    expect(h.rolling).toBe(false);
  });

  test('the motion runs even off camera (the sim hop policy, near-miss and hop hint read h.cx)', () => {
    const sc = scene({ sledX: 2700 });
    const h = new Hazard(sc, C.hazards.rollingBoulder, spawnOn(sc, 3000), PAL);
    h.update(0, -5000, -4000); // camera far away
    h.update(500, -5000, -4000);
    expect(h.gfx.visible).toBe(false);
    expect(h.gfx.x).toBeCloseTo(3000 + rollOffsetAt(C.hazards.rollingBoulder.motion, 500, sc.terrain.slopeDegAt, 3000), 6);
    expect(h.gfx.x).toBeGreaterThan(3020);
  });

  test('a Dew Drop on the Micro dew swell rides the same surface the sled rides (generator heightAt == collider points)', () => {
    // a real Micro Mountain chunk with a dewSwell zone: the swell is in the chunk points (T2), so heightAt is the polyline
    const g = makeGen('b3-dew', { biomeMask: 512 });
    let chunk = null;
    let zone = null;
    for (let i = 1; i < 200 && !zone; i++) {
      const ch = g.getChunk(i);
      const z = ch.zones.find((q) => q.modId === 'dewSwell' && q.x1 - q.x0 > 400);
      if (z) { chunk = ch; zone = z; }
    }
    expect(zone).not.toBe(null);
    const polyY = (x) => {
      const p = chunk.points;
      for (let k = 0; k < p.length - 1; k++) if (x >= p[k].x && x <= p[k + 1].x) return p[k].y + (p[k + 1].y - p[k].y) * (x - p[k].x) / (p[k + 1].x - p[k].x);
      return NaN;
    };
    const sc = scene({ heightAt: (x) => g.heightAt(x), slopeAt: (x) => g.slopeDegAt(x) });
    const x0 = Math.round(zone.x0 + 300);
    const h = new Hazard(sc, C.hazards.dewDrop, spawnOn(sc, x0), PAL);
    sc.sled.x = x0 - 100;
    let t = 0;
    let worst = 0;
    h.update(t, 0, 99999);
    for (let k = 0; k < 90; k++) {
      t += 16;
      h.update(t, 0, 99999);
      worst = Math.max(worst, Math.abs(h.gfx.y - polyY(h.gfx.x)));
    }
    expect(h.gfx.x).toBeGreaterThan(x0 + 40); // it really rolled (downhill) across the swell
    expect(worst).toBeLessThan(1e-6);
  });
});

describe('B3 Gear Gate: open/closed from the seeded phase and run time', () => {
  test('the entity reads the spawn phase; isPassable(t) is gateOpenAt(motion, phase, t); the drawing changes with it', () => {
    const sc = scene();
    const def = C.hazards.gearGate;
    const h = new Hazard(sc, def, spawnOn(sc, 3000, { phase: 0.25 }), PAL);
    const per = gateTiming(def.motion).periodMs;
    for (let t = 0; t < per * 2; t += 50) expect(h.isPassable(t)).toBe(gateOpenAt(def.motion, 0.25, t));
    // draw open, then closed: different shapes
    const tOpen = [...Array(per).keys()].find((t) => gateOpenAt(def.motion, 0.25, t));
    const tShut = [...Array(per).keys()].find((t) => !gateOpenAt(def.motion, 0.25, t));
    h.update(tOpen, 0, 99999);
    expect(h.open).toBe(true);
    const a = JSON.stringify(h.gfx.ops);
    h.update(tShut, 0, 99999);
    expect(h.open).toBe(false);
    expect(JSON.stringify(h.gfx.ops)).not.toBe(a);
  });

  test('RunScene.onHazard: an open gate is passed (no hit, the gate stays armed); a closed gate crashes', () => {
    const sc = scene();
    const def = C.hazards.gearGate;
    const h = new Hazard(sc, def, spawnOn(sc, 3000, { phase: 0 }), PAL);
    const s = makeRun();
    s.runTimeMs = 100; // open (each cycle starts open)
    s.onHazard(h);
    expect(h.hit).toBe(false);
    expect(s.pendingCrash).toBe(null);
    expect(events(s, EVT.HAZARD_HIT)).toEqual([]);
    s.runTimeMs = gateTiming(def.motion).openMs + 10; // closed
    s.onHazard(h);
    expect(h.hit).toBe(true);
    expect(s.pendingCrash).toEqual({ cause: 'hazard', hazardId: 'gearGate' });
    expect(events(s, EVT.HAZARD_HIT).map((p) => `${p.hazardId}:${p.effect}`)).toEqual(['gearGate:crash']);
  });

  test('a rolling hazard crashes on contact like any crash hazard (no gate check applies)', () => {
    for (const id of ['rollingBoulder', 'dewDrop']) {
      const sc = scene();
      const h = new Hazard(sc, C.hazards[id], spawnOn(sc, 3000), PAL);
      const s = makeRun();
      s.onHazard(h);
      expect(s.pendingCrash).toEqual({ cause: 'hazard', hazardId: id });
    }
  });
});

describe('B3 power-ups through RunScene.onPowerUp (shipped defs)', () => {
  test.each(['sandrunnerSkis', 'royalJellyWax'])('%s: glide, all three drags lowered for its duration, then back', (id) => {
    const s = makeRun();
    const b = phys(s);
    const e = C.powerups[id].effect;
    s.onPowerUp(take(id));
    expect(events(s, EVT.POWERUP_COLLECTED)).toEqual([{ id, durationMs: e.durationMs, charges: 0 }]);
    const d = glideDrag(1, e.frictionMul);
    const g = phys(s);
    expect(g.groundResist).toBeCloseTo(b.groundResist * e.frictionMul, 12);
    expect(g.frictionAir).toBeCloseTo(b.frictionAir / d.speedMul, 12);
    expect(g.quadDrag).toBeCloseTo(b.quadDrag * d.quadMul, 12);
    s.tickEffects(e.durationMs - 1);
    expect(phys(s).speedMul).toBeCloseTo(d.speedMul, 12);
    s.tickEffects(2);
    expect(phys(s)).toEqual(b);
    expect(events(s, EVT.POWERUP_EXPIRED)).toEqual([{ id, reason: 'timeout' }]);
  });

  test('Clockwork Treads: the conveyor belt drive is 0 while the 4 s ward runs, then back', () => {
    const s = makeRun({ zones: [C.terrainMods.conveyorBelt] });
    const drive = phys(s).beltDrivePxS2;
    expect(drive).toBeGreaterThan(0);
    s.onPowerUp(take('clockworkTreads'));
    expect(phys(s).beltDrivePxS2).toBe(0);
    expect(phys(s).pushForceMul).toBe(phys(makeRun()).pushForceMul); // the belt's push multiplier is gone too
    s.tickEffects(4001);
    expect(phys(s).beltDrivePxS2).toBe(drive);
  });
});

describe('B3 HUD entries (UIScene)', () => {
  const ui = () => Object.assign(Object.create(UIScene.prototype), { content: C, nowMs: 0, warnY: 40, effects: new Map() });
  const recorder = () => {
    const ops = [];
    return { ops, g: new Proxy({}, { get: (t, k) => (...a) => { ops.push([k, ...a]); return undefined; } }) };
  };
  const IDS = ['sandrunnerSkis', 'royalJellyWax', 'clockworkTreads'];

  test('each B3 pickup has its own HUD name and colour', () => {
    const u = ui();
    expect(IDS.map((id) => u._powerInfo(id).name)).toEqual(['SANDRUNNER SKIS', 'JELLY WAX', 'CLOCKWORK TREADS']);
    expect(IDS.map((id) => u._powerInfo(id).color)).toEqual(['amber', 'amber', 'cyan']);
  });

  test('each B3 pickup chip draws its own icon: not the unknown square, not its kind icon, all different', () => {
    const u = ui();
    const draw = (id) => { const r = recorder(); u._drawIcon(r.g, id, 10, 10, 1); return JSON.stringify(r.ops.filter(([k]) => k !== 'lineStyle' && k !== 'fillStyle')); };
    const square = JSON.stringify([['strokeRect', 5, 5, 10, 10]]);
    const kindIcon = (kind) => {
      const v = Object.assign(Object.create(UIScene.prototype), { content: { powerups: { w: { effect: { kind } } } } });
      const r = recorder(); v._drawIcon(r.g, 'w', 10, 10, 1); return JSON.stringify(r.ops.filter(([k]) => k !== 'lineStyle' && k !== 'fillStyle'));
    };
    const icons = IDS.map(draw);
    for (const ic of icons) {
      expect(ic).not.toBe(square);
      expect(ic).not.toBe(kindIcon('glide'));
      expect(ic).not.toBe(kindIcon('ward'));
    }
    expect(new Set(icons).size).toBe(IDS.length);
  });
});

describe('B3 drawing: every new shapeKey has its own routine', () => {
  const shape = (gfx) => JSON.stringify(gfx.ops.filter(([k]) => /^fill(Rect|Triangle|Points|Circle|Ellipse)$|^stroke|^lineBetween$/.test(k)).map(([k]) => k));

  test('the three hazards draw non-generic, mutually different shapes in `danger`, with the usual hit-box brackets', () => {
    const out = {};
    for (const id of ['rollingBoulder', 'dewDrop', 'gearGate']) {
      const def = C.hazards[id];
      const sc = scene();
      const h = new Hazard(sc, def, spawnOn(sc, 100), PAL);
      expect(h.drawKind).toBe(def.shapeKey);
      expect(h.color).toBe(PAL.danger);
      out[id] = shape(h.gfx);
      expect(h.gfx.ops.filter(([k]) => k === 'lineBetween').length).toBeGreaterThanOrEqual(8); // brackets (telegraphable)
      const generic = new Hazard(sc, { ...def, shapeKey: 'zzUnknownShape' }, spawnOn(sc, 100), PAL);
      expect(generic.drawKind).toBe('generic');
      expect(out[id]).not.toBe(shape(generic.gfx));
    }
    expect(new Set(Object.values(out)).size).toBe(3);
  });

  test('the three pickups draw non-generic glyphs, different from each other', () => {
    const out = {};
    for (const id of ['sandrunnerSkis', 'royalJellyWax', 'clockworkTreads']) {
      const def = C.powerups[id];
      const p = new PowerUp(scene(), def, { x: 100, y: 50 }, PAL);
      expect(p.drawKind).toBe(def.shapeKey);
      out[id] = shape(p.gfx);
      const generic = new PowerUp(scene(), { ...def, shapeKey: 'zzUnknownGlyph' }, { x: 100, y: 50 }, PAL);
      expect(out[id]).not.toBe(shape(generic.gfx));
    }
    expect(new Set(Object.values(out)).size).toBe(3);
  });
});/**
 * B3 "Motion": the pure math of the moving hazards and the glide (spec §4 / §6 B0.4 "test seam for the sled").
 * `systems/HazardMotion.js` holds `rollStep` / `rollOffsetAt` (Rolling Boulder, Dew Drop) and `gateOpenAt` (Gear Gate);
 * `BiomeEffects.glideFriction` is the one place a glide changes ground friction. Hazard.js and PhysicsTuner only call
 * these. No Math.random, no Date: every value is a function of the def, the spawn (its x and its seeded phase), the run
 * time and the sled x.
 */
import {
  ROLL_ACTIVATE_PX, ROLL_MAX_RANGE_PX, ROLL_MAX_SPEED_PX_S, rollParams, rollOffsetAt, rollStep, rollPredictX, rollSweep,
  rollTargetSpeed, ROLL_FLOOR_SHARE, ROLL_FULL_SLOPE_DEG, ROLL_ACCEL_PX_S2,
  GATE_MIN_OPEN_MS, GATE_MAX_CLOSED_MS, gateTiming, gateOpenAt, gateNextChangeMs, emptyRollState,
} from '../../src/systems/HazardMotion.js';
import { glideFriction, glideFrictionMul, glideStrength, glideDrag, GLIDE_MIN_FRICTION_MUL } from '../../src/systems/BiomeEffects.js';
import { PhysicsTuner, TUNING } from '../../src/systems/PhysicsTuner.js';

const ROLL = { kind: 'roll', speedPxS: 100, rangePx: 160, dir: 1 };
const GATE = { kind: 'gate', periodMs: 1400, openMs: 900 };
const FLAT = () => 0;
const STEEP = () => 30;
const WAVY = (x) => 10 + 12 * Math.sin(x / 37);
/** continuous-time offset on a constant slope: ramp at ROLL_ACCEL_PX_S2 from rest to the target, then constant */
const onSlope = (motion, slopeDeg, ms) => {
  const v = rollTargetSpeed(motion, slopeDeg);
  const t = ms / 1000;
  const tr = v / ROLL_ACCEL_PX_S2;
  const d = t <= tr ? (ROLL_ACCEL_PX_S2 * t * t) / 2 : (v * tr) / 2 + v * (t - tr);
  return Math.min(rollParams(motion).rangePx, d);
};

describe('HazardMotion: roll parameters (B3 tuning: downhill, away from the sled, gently capped)', () => {
  test('rollParams reads speed (the cap), range and direction, clamped to the bounds; direction defaults to +1 (downhill)', () => {
    expect(rollParams(ROLL)).toEqual({ speedPxS: 100, rangePx: 160, dir: 1 });
    expect(rollParams({ kind: 'roll', speedPxS: 999, rangePx: 999, dir: -1 })).toEqual({ speedPxS: ROLL_MAX_SPEED_PX_S, rangePx: ROLL_MAX_RANGE_PX, dir: -1 });
    expect(rollParams({ kind: 'roll' }).dir).toBe(1);
    expect(rollParams({ kind: 'roll', dir: 7 }).dir).toBe(1);
    expect(rollParams({ kind: 'roll', dir: -3 }).dir).toBe(-1);
    expect(rollParams({ kind: 'roll', speedPxS: -5, rangePx: -5 })).toMatchObject({ speedPxS: 0, rangePx: 0 });
    // the cap stays gentle: below the stall net's restart speed, so a restarted sled always outruns a roll
    expect(ROLL_MAX_SPEED_PX_S).toBeLessThanOrEqual(120);
  });

  test('rollSweep is the x span the hazard can occupy, relative to its spawn x', () => {
    expect(rollSweep(ROLL)).toEqual({ lo: 0, hi: 160 });
    expect(rollSweep({ ...ROLL, dir: -1 })).toEqual({ lo: -160, hi: 0 });
    expect(rollSweep(null)).toEqual({ lo: 0, hi: 0 });
    expect(rollSweep(GATE)).toEqual({ lo: 0, hi: 0 }); // a gate never moves along x
  });

  test('rollTargetSpeed follows the slope: the floor share of the cap on flat or rising ground, the cap on steep ground', () => {
    expect(rollTargetSpeed(ROLL, 0)).toBeCloseTo(100 * ROLL_FLOOR_SHARE, 12);
    expect(rollTargetSpeed(ROLL, -15)).toBeCloseTo(100 * ROLL_FLOOR_SHARE, 12); // never stalls or turns back on a rise
    expect(rollTargetSpeed(ROLL, ROLL_FULL_SLOPE_DEG)).toBeCloseTo(100, 12);
    expect(rollTargetSpeed(ROLL, 60)).toBeCloseTo(100, 12);
    expect(rollTargetSpeed(ROLL, ROLL_FULL_SLOPE_DEG / 2)).toBeCloseTo(100 * (ROLL_FLOOR_SHARE + (1 - ROLL_FLOOR_SHARE) / 2), 12);
    expect(rollTargetSpeed(ROLL, 5)).toBeLessThan(rollTargetSpeed(ROLL, 12));
    expect(rollTargetSpeed(ROLL, NaN)).toBeCloseTo(100 * ROLL_FLOOR_SHARE, 12);
    // an uphill (dir -1) roll reads the slope along its own travel: rising ground (negative slope) is "downhill" for it
    expect(rollTargetSpeed({ ...ROLL, dir: -1 }, -ROLL_FULL_SLOPE_DEG)).toBeCloseTo(100, 12);
    expect(ROLL_FLOOR_SHARE).toBeGreaterThan(0);
  });
});

describe('HazardMotion: rollOffsetAt (a pure function of the time since the roll started and the ground)', () => {
  test('0 before it starts; it starts from rest, speeds up to the slope\'s speed, and rests at the end of its range', () => {
    expect(rollOffsetAt(ROLL, -100, FLAT, 0)).toBe(0);
    expect(rollOffsetAt(ROLL, 0, FLAT, 0)).toBe(0);
    for (const ms of [50, 100, 250, 500, 1000, 2000]) {
      expect(rollOffsetAt(ROLL, ms, FLAT, 0)).toBeCloseTo(onSlope(ROLL, 0, ms), 1);
      expect(rollOffsetAt(ROLL, ms, STEEP, 0)).toBeCloseTo(onSlope(ROLL, 30, ms), 1);
    }
    expect(rollOffsetAt(ROLL, 100, FLAT, 0)).toBeLessThan(100 * ROLL_FLOOR_SHARE * 0.1); // from rest: slower than full speed at first
    expect(rollOffsetAt(ROLL, 60000, FLAT, 0)).toBe(160);
    expect(rollOffsetAt({ ...ROLL, dir: -1 }, 500, () => -30, 0)).toBeCloseTo(-onSlope(ROLL, 30, 500), 1);
    expect(rollOffsetAt(null, 500, FLAT, 0)).toBe(0);
    expect(rollOffsetAt(ROLL, 500)).toBeCloseTo(onSlope(ROLL, 0, 500), 1); // no ground function = flat
  });

  test('it follows the slope: faster down steep ground than on flat ground, and never faster than the cap', () => {
    expect(rollOffsetAt(ROLL, 1500, STEEP, 0)).toBeGreaterThan(rollOffsetAt(ROLL, 1500, FLAT, 0) * 1.5);
    let last = 0;
    for (let ms = 10; ms <= 4000; ms += 10) {
      const o = rollOffsetAt(ROLL, ms, WAVY, 500);
      expect(o - last).toBeGreaterThanOrEqual(0); // always downhill (+x), never back
      expect((o - last) / 0.01).toBeLessThanOrEqual(100 + 1e-9);
      last = o;
    }
  });

  test('frame-rate independent: the same run time gives the same offset whatever the frame steps, on any ground', () => {
    const run = (dts) => {
      let s = rollStep(emptyRollState(), ROLL, 1000, 1000, 0, WAVY); // starts at run time 0 in every case
      let t = 0;
      for (const dt of dts) { t += dt; s = rollStep(s, ROLL, 1000, 1000, t, WAVY); }
      return s;
    };
    const a = run(Array(60).fill(10));
    const b = run(Array(30).fill(20));
    const c = run([7, 13, 50, 30, 100, 200, 100, 100]);
    const d = run([600]);
    expect(a.offsetPx).toBeGreaterThan(20);
    for (const q of [b, c, d]) {
      expect(q.offsetPx).toBeCloseTo(a.offsetPx, 9);
      expect(q.vPxS).toBeCloseTo(a.vPxS, 9);
    }
    expect(a.offsetPx).toBeCloseTo(rollOffsetAt(ROLL, 600, WAVY, 1000), 9);
  });
});

describe('HazardMotion: rollStep (starts when the sled comes within ROLL_ACTIVATE_PX)', () => {
  test('stays put while the sled is further than ROLL_ACTIVATE_PX behind its spawn x', () => {
    let s = emptyRollState();
    s = rollStep(s, ROLL, 2000, 2000 - ROLL_ACTIVATE_PX - 1, 100, FLAT);
    expect(s).toEqual(emptyRollState());
    expect(s.activeAtMs).toBe(null);
    s = rollStep(s, ROLL, 2000, 2000 - ROLL_ACTIVATE_PX - 1, 5000, FLAT);
    expect(s.offsetPx).toBe(0);
  });

  test('starts on the step the sled reaches the activation line, then rolls downhill (+x) with run time', () => {
    let s = emptyRollState();
    s = rollStep(s, ROLL, 2000, 2000 - ROLL_ACTIVATE_PX, 1000, FLAT);
    expect(s.activeAtMs).toBe(1000);
    expect(s.offsetPx).toBe(0);
    expect(s.vPxS).toBe(0);
    s = rollStep(s, ROLL, 2000, 1500, 1500, FLAT); // the sled x no longer matters once rolling
    expect(s.activeAtMs).toBe(1000);
    expect(s.offsetPx).toBeCloseTo(onSlope(ROLL, 0, 500), 1);
    expect(s.offsetPx).toBeGreaterThan(0); // away from the sled
    expect(s.vPxS).toBeCloseTo(rollTargetSpeed(ROLL, 0), 6); // reached the flat-ground speed
    s = rollStep(s, ROLL, 2000, 0, 90000, FLAT);
    expect(s.offsetPx).toBe(160);
    expect(s.vPxS).toBe(0); // resting
  });

  test('does not mutate its input; a missing state is a fresh one; an earlier run time recomputes from the start', () => {
    const s0 = emptyRollState();
    const snap = JSON.stringify(s0);
    const s1 = rollStep(s0, ROLL, 2000, 1900, 50, FLAT);
    expect(JSON.stringify(s0)).toBe(snap);
    expect(s1.activeAtMs).toBe(50);
    expect(rollStep(undefined, ROLL, 2000, 1900, 50, FLAT)).toEqual(s1);
    const late = rollStep(s1, ROLL, 2000, 1900, 2050, FLAT);
    const back = rollStep(late, ROLL, 2000, 1900, 550, FLAT);
    expect(back.offsetPx).toBeCloseTo(rollStep(s1, ROLL, 2000, 1900, 550, FLAT).offsetPx, 9);
  });

  test('rollPredictX: where the hazard will be at a later run time (for a telegraph), consistent with rollStep', () => {
    const idle = emptyRollState();
    expect(rollPredictX(idle, ROLL, 2000, 99999, WAVY)).toBe(2000); // not started: it waits at its spawn x
    const s = rollStep(idle, ROLL, 2000, 1900, 1000, WAVY);
    const snap = JSON.stringify(s);
    for (const t of [1000, 1234, 1500, 3000]) expect(rollPredictX(s, ROLL, 2000, t, WAVY)).toBeCloseTo(2000 + rollStep(s, ROLL, 2000, 1900, t, WAVY).offsetPx, 9);
    expect(rollPredictX(s, ROLL, 2000, 60000, WAVY)).toBe(2160);
    expect(JSON.stringify(s)).toBe(snap);
  });
});

describe('HazardMotion: gate timing', () => {
  test('gateTiming reads period and open time, keeping open >= GATE_MIN_OPEN_MS and closed <= GATE_MAX_CLOSED_MS', () => {
    expect(gateTiming(GATE)).toEqual({ periodMs: 1400, openMs: 900, closedMs: 500 });
    const long = gateTiming({ kind: 'gate', periodMs: 5000, openMs: 1000 });
    expect(long.closedMs).toBe(GATE_MAX_CLOSED_MS);
    expect(long.periodMs).toBe(1000 + GATE_MAX_CLOSED_MS);
    expect(gateTiming({ kind: 'gate', periodMs: 600, openMs: 50 }).openMs).toBe(GATE_MIN_OPEN_MS);
    expect(gateTiming(null).closedMs).toBeLessThanOrEqual(GATE_MAX_CLOSED_MS);
  });

  test('gateOpenAt: open for openMs, closed for closedMs, every period; the phase shifts the cycle', () => {
    const open = (t, ph = 0) => gateOpenAt(GATE, ph, t);
    expect(open(0)).toBe(true);
    expect(open(899)).toBe(true);
    expect(open(900)).toBe(false);
    expect(open(1399)).toBe(false);
    expect(open(1400)).toBe(true);
    expect(open(1400 * 7 + 950)).toBe(false);
    // phase 0.5 = the cycle is 700 ms in at t = 0: open for 200 ms more, then closed
    expect(open(0, 0.5)).toBe(true);
    expect(open(200, 0.5)).toBe(false);
    expect(open(700, 0.5)).toBe(true);
    // share of open time over many periods = openMs / periodMs
    let n = 0;
    for (let t = 0; t < 14000; t += 1) if (open(t, 0.37)) n++;
    expect(n / 14000).toBeCloseTo(900 / 1400, 3);
  });

  test('a closed spell never lasts longer than closedMs, whatever the phase (the gate always reopens)', () => {
    for (const ph of [0, 0.1, 0.33, 0.5, 0.77, 0.999]) {
      let run = 0;
      let worst = 0;
      for (let t = 0; t < 6000; t += 1) {
        if (!gateOpenAt(GATE, ph, t)) { run++; worst = Math.max(worst, run); } else run = 0;
      }
      expect(worst).toBeLessThanOrEqual(500);
    }
  });

  test('gateNextChangeMs: ms until the gate flips (for a telegraph)', () => {
    expect(gateNextChangeMs(GATE, 0, 0)).toBe(900);
    expect(gateNextChangeMs(GATE, 0, 850)).toBe(50);
    expect(gateNextChangeMs(GATE, 0, 900)).toBe(500);
    expect(gateNextChangeMs(GATE, 0, 1300)).toBe(100);
    expect(gateNextChangeMs(GATE, 0.5, 0)).toBe(200);
  });

  test('negative or non-finite run time and phase are safe', () => {
    expect(typeof gateOpenAt(GATE, NaN, NaN)).toBe('boolean');
    expect(gateOpenAt(GATE, 0, -100)).toBe(gateOpenAt(GATE, 0, 1300));
  });
});

describe('BiomeEffects.glideFriction (the glide math PhysicsTuner calls)', () => {
  test('multiplies the friction multiplier by the clamped glide multiplier; no glide changes nothing', () => {
    expect(glideFriction(1, 0.7)).toBeCloseTo(0.7, 12);
    expect(glideFriction(1.5, 0.7)).toBeCloseTo(1.05, 12);
    expect(glideFriction(1, 0.01)).toBeCloseTo(glideFrictionMul(0.01), 12); // floor 0.2
    expect(glideFriction(1, 3)).toBe(1); // a glide never raises friction
    expect(glideFriction(0.8, undefined)).toBe(0.8);
    expect(glideFriction(0.8, 0)).toBe(0.8);
    expect(glideFriction(0.8, 1)).toBe(0.8);
  });

  test('PhysicsTuner routes the glide through glideFriction: groundResist and groundFriction scale by it', () => {
    const t = new PhysicsTuner();
    const base = t.getEffective({});
    const g = t.getEffective({ glideFrictionMul: 0.7 });
    expect(g.groundResist).toBeCloseTo(base.groundResist * glideFriction(1, 0.7), 12);
    // out-of-range context values are clamped by the same math (the B0 pickup already clamps; the tuner never trusts it)
    expect(t.getEffective({ glideFrictionMul: 0.05 }).groundResist).toBeCloseTo(base.groundResist * 0.2, 12);
  });
});

describe('B3 tuning: a glide is felt (BiomeEffects.glideDrag cuts all three drags, not only ground friction)', () => {
  test('glideStrength: 0 for no glide, 1 at the friction floor, linear between', () => {
    for (const m of [undefined, null, 0, -1, 1, 1.5, NaN]) expect(glideStrength(m)).toBe(0);
    expect(glideStrength(GLIDE_MIN_FRICTION_MUL)).toBeCloseTo(1, 12);
    expect(glideStrength(0.01)).toBeCloseTo(1, 12); // clamped to the floor
    expect(glideStrength(0.6)).toBeCloseTo(0.5, 12);
  });

  test('glideDrag: no glide is exactly the old math (frictionMul unchanged, speedMul 1, quadMul 1)', () => {
    for (const m of [undefined, 0, 1, 3]) expect(glideDrag(0.8, m)).toEqual({ frictionMul: glideFriction(0.8, m), speedMul: 1, quadMul: 1 });
  });

  test('glideDrag: a glide of strength s lifts speedMul by glideSpeedLift x s and cuts quadDrag by glideQuadCut x s', () => {
    const t = { glideSpeedLift: 0.4, glideQuadCut: 0.3 };
    const g = glideDrag(1, 0.6, t);
    expect(g.frictionMul).toBeCloseTo(0.6, 12);
    expect(g.speedMul).toBeCloseTo(1 + 0.4 * 0.5, 12);
    expect(g.quadMul).toBeCloseTo(1 - 0.3 * 0.5, 12);
    const full = glideDrag(1, GLIDE_MIN_FRICTION_MUL, t);
    expect(full.speedMul).toBeCloseTo(1.4, 12);
    expect(full.quadMul).toBeCloseTo(0.7, 12);
    // the shipped TUNING knobs are positive (a glide really lifts), bounded (a glide never removes drag)
    expect(TUNING.glideSpeedLift).toBeGreaterThan(0);
    expect(TUNING.glideSpeedLift).toBeLessThanOrEqual(1);
    expect(TUNING.glideQuadCut).toBeGreaterThan(0);
    expect(TUNING.glideQuadCut).toBeLessThanOrEqual(0.9);
    expect(glideDrag(1, 0.6).speedMul).toBeCloseTo(1 + TUNING.glideSpeedLift * 0.5, 12);
  });

  test('PhysicsTuner: a glide lowers groundResist, frictionAir and quadDrag; no glide leaves every output exactly as before', () => {
    const t = new PhysicsTuner();
    const base = t.getEffective({});
    // no glide: byte-identical outputs for every no-glide context value
    for (const m of [undefined, 1, 0]) expect(t.getEffective({ glideFrictionMul: m })).toEqual(base);
    expect(base.speedMul).toBe(1);
    expect(base.quadDrag).toBe(TUNING.quadDrag);
    const g = t.getEffective({ glideFrictionMul: 0.6 });
    const d = glideDrag(1, 0.6);
    expect(g.groundResist).toBeCloseTo(base.groundResist * 0.6, 12);
    expect(g.speedMul).toBeCloseTo(d.speedMul, 12);
    expect(g.frictionAir).toBeCloseTo(base.frictionAir / d.speedMul, 12);
    expect(g.quadDrag).toBeCloseTo(TUNING.quadDrag * d.quadMul, 12);
    // stacks with a Packet Burst (both multiply speedMul)
    expect(t.getEffective({ glideFrictionMul: 0.6, speedBoost: 1.3 }).speedMul).toBeCloseTo(1.3 * d.speedMul, 12);
  });
});/**
 * B3 "Motion" placement: presence (spec §4 presence amendment, same target and method as the B1 / B2 presence tests), the
 * rolling-hazard track rule (TerrainGenerator._biomeGroundAt: the whole x span a Rolling Boulder or Dew Drop can roll over
 * keeps every clearance its spawn point keeps), the Gear Gate phase (the gate's own 4th draw of the 'biomeHaz' fork,
 * stored on the spawn), the fairness numbers for the moving hazards, and determinism for masks 4, 256 and 512.
 */
import { makeGen, loadContent } from './_helpers.js';
import { Rng, hashInts } from '../../src/systems/Rng.js';
import {
  BIOME_HAZARD_CLEARANCE_PX, BIOME_EDGE_MARGIN_PX, BIOME_SLOT_DRAWS, expectedSpeedPxS, ROLL_TRACK_EDGE_MARGIN_PX,
} from '../../src/systems/TerrainGenerator.js';
import {
  rollSweep, rollParams, rollTargetSpeed, ROLL_ACTIVATE_PX, gateTiming, GATE_MAX_CLOSED_MS,
} from '../../src/systems/HazardMotion.js';
import { TUNING } from '../../src/systems/PhysicsTuner.js';
import { PHYSICS } from '../../src/constants.js';

const c = loadContent();
const SEEDS = ['pres1', 'pres2', 'pres3', 'pres4', 'pres5', 'pres6', 'pres7', 'pres8'];
const ROB = Array.from({ length: 32 }, (_, k) => `rob${k + 1}`);
// re-pinned for #65: Debutmont base + arcade bridges. Same re-assessment as biome-b1-presence.test.js: the generator's hazard
// rates are unchanged (400 seeds, +/-0.02), the sample is ~25 % smaller because each biome sector opens with an arcade bridge,
// so the band is asserted on BIG (150 seeds) and the per-seed 1-per-2-km rule on seeds with >= SHORT_KM of the biome.
const BIG = Array.from({ length: 150 }, (_, k) => `big${k + 1}`);
const SHORT_KM = 1;
const eligibleFor = (def, ch) => ch.kind !== 'bridge' && ch.defId !== 'gen-jump';
const B3 = [
  [4, 'pyramid-peak', 'rollingBoulder', 'sandrunnerSkis'],
  [256, 'steampunk-slopes', 'gearGate', 'clockworkTreads'],
  [512, 'micro-mountain', 'dewDrop', 'royalJellyWax'],
];

function presence(mask, biome, id, seeds) {
  const def = c.hazards[id];
  let elig = 0;
  let has = 0;
  const perSeed = [];
  for (const seed of seeds) {
    const g = makeGen(seed, { biomeMask: mask });
    let km = 0;
    let n = 0;
    for (let i = 1; i < 45; i++) {
      const ch = g.getChunk(i);
      if (ch.biome !== biome) continue;
      km += (ch.endX - ch.startX) / 20000;
      const here = ch.hazards.some((q) => q.defId === id);
      if (here) n++;
      if (eligibleFor(def, ch)) { elig++; if (here) has++; }
    }
    perSeed.push({ seed, n, km: +km.toFixed(2), ok: km < SHORT_KM || n * 2 >= km });
  }
  const share = has / elig;
  console.log(`${id} (${seeds.length} seeds): ${has}/${elig} eligible = ${(100 * share).toFixed(1)} %; per seed ${perSeed.map((p) => `${p.n}/${p.km}km`).join(' ')}`);
  return { elig, share, perSeed, fails: perSeed.filter((p) => !p.ok).length };
}

/** Every chunk (0..n) of a seed + mask with its hazards. */
function chunks(seed, mask, n = 300) {
  const g = makeGen(seed, { biomeMask: mask });
  const out = [];
  for (let i = 0; i < n; i++) out.push(g.getChunk(i));
  return { g, out };
}

describe('B3 Gear Gate phase: the gate\'s own draw', () => {
  test('every gear gate spawn carries phase = the 4th number of its chunk\'s biomeHaz fork (fixed draws: 5 per slot)', () => {
    expect(BIOME_SLOT_DRAWS).toBe(5);
    let n = 0;
    const phases = new Set();
    for (const seed of ['gate1', 'gate2', 'gate3', 'gate4']) {
      const { g, out } = chunks(seed, 256, 200);
      for (const ch of out) {
        for (const h of ch.hazards.filter((q) => q.defId === 'gearGate')) {
          const r = new Rng(hashInts(g.seedState, ch.index + 1)).fork('biomeHaz');
          r.next(); r.next(); r.next();
          const h3 = r.next();
          expect(h.phase).toBeCloseTo(h3, 6);
          expect(h.phase).toBeGreaterThanOrEqual(0);
          expect(h.phase).toBeLessThan(1);
          phases.add(h.phase);
          n++;
        }
        // no other hazard carries a phase
        for (const h of ch.hazards.filter((q) => q.defId !== 'gearGate')) expect(h.phase).toBeUndefined();
      }
    }
    expect(n).toBeGreaterThan(30);
    expect(phases.size).toBe(n); // each gate its own phase
  });
});

describe('B3 rolling hazards: the whole roll track keeps the spawn clearances', () => {
  test.each([[4, 'rollingBoulder'], [512, 'dewDrop']])('mask %p: every %s track is inside the track edge margins, clear of lips, gaps (its own and the neighbour chunks\' ), other hazards (240) and power-ups (90)', (mask, id) => {
    const sw = rollSweep(c.hazards[id].motion);
    expect(sw.lo).toBe(0); // B3 tuning: it really moves, downhill (+x), away from the sled
    expect(sw.hi).toBeGreaterThan(0);
    let n = 0;
    for (const seed of ['roll1', 'roll2', 'roll3', 'roll4', 'roll5', 'roll6']) {
      const { out } = chunks(seed, mask);
      const all = out.flatMap((ch) => ch.hazards);
      for (const ch of out) {
        for (const h of ch.hazards.filter((q) => q.defId === id)) {
          n++;
          const lo = h.x + sw.lo;
          const hi = h.x + sw.hi;
          // the spawn keeps the biome edge margin; B3 tuning: the downhill track may run on into it, up to
          // ROLL_TRACK_EDGE_MARGIN_PX (>= the spec's 96 px) from the chunk end
          expect(h.x).toBeGreaterThanOrEqual(ch.startX + BIOME_EDGE_MARGIN_PX);
          expect(h.x).toBeLessThanOrEqual(ch.endX - BIOME_EDGE_MARGIN_PX);
          expect(lo).toBeGreaterThanOrEqual(ch.startX + ROLL_TRACK_EDGE_MARGIN_PX);
          expect(hi).toBeLessThanOrEqual(ch.endX - ROLL_TRACK_EDGE_MARGIN_PX);
          expect(ROLL_TRACK_EDGE_MARGIN_PX).toBeGreaterThanOrEqual(96);
          for (const q of all) {
            if (q === h) continue;
            const d = q.x < lo ? lo - q.x : q.x > hi ? q.x - hi : 0;
            expect({ q: q.defId, d, ok: d >= BIOME_HAZARD_CLEARANCE_PX }).toMatchObject({ ok: true });
          }
          for (const p of ch.powerups) {
            const d = p.x < lo ? lo - p.x : p.x > hi ? p.x - hi : 0;
            expect({ p: p.defId, d, ok: d >= 90 }).toMatchObject({ ok: true });
          }
          const near = out.slice(Math.max(0, ch.index - 1), ch.index + 2); // this chunk and its neighbours
          for (const nc of near) {
            for (const gp of nc.gaps) expect(hi < gp.x0 - 96 || lo > gp.x1 + 96).toBe(true);
            for (const l of nc.launches) {
              expect(hi < l.x - 40 || lo > l.x + 40).toBe(true);
              // B3 tuning: a sled landing from a lip gets the roll's whole range of ground before the spawn (as the old
              // uphill track gave it): the spawn sits >= range past the landing zone (landX + 160)
              if (l.landX != null && h.x > l.x) expect({ id, past: h.x - (l.landX + 160), ok: h.x - (l.landX + 160) > sw.hi - sw.lo }).toMatchObject({ ok: true });
            }
          }
        }
      }
    }
    expect(n).toBeGreaterThan(40);
  });
});

describe('B3 tuning: the downhill track end keeps ROLL_TRACK_EDGE_MARGIN_PX from the chunk end', () => {
  test('a long roll (range 200) spawned at the spawn margin is refused; range 120 there is allowed', () => {
    const g = makeGen('edge-rule', { biomeMask: 4 });
    const ch = g.getChunk(5);
    const chunk = { ...ch, hazards: [], powerups: [], gaps: [] };
    const x = chunk.endX - BIOME_EDGE_MARGIN_PX;
    const def = (rangePx) => ({ id: 'probe', motion: { kind: 'roll', speedPxS: 80, rangePx, dir: 1 } });
    expect(g._rollTrackClear(chunk, def(200), x, [], null)).toBe(false); // track end 40 px from the chunk end
    expect(g._rollTrackClear(chunk, def(120), x, [], null)).toBe(true); // exactly ROLL_TRACK_EDGE_MARGIN_PX
  });
});

describe('B3 presence: the biome hazard is felt in early terrain (chunks 0-44, single biome bit)', () => {
  test.each(B3)('mask %p (%s): %s share of eligible chunks and 1 per 2 km', (mask, biome, id) => {
    const a = presence(mask, biome, id, SEEDS);
    const b = presence(mask, biome, id, ROB);
    const big = presence(mask, biome, id, BIG);
    expect(a.elig).toBeGreaterThanOrEqual(15);
    // pinned at the measured values below (see ARCHITECTURE B3 addendum)
    expect(big.share).toBeGreaterThanOrEqual(PRESENCE[id].lo);
    expect(big.share).toBeLessThanOrEqual(PRESENCE[id].hi);
    expect(b.fails).toBeLessThanOrEqual(PRESENCE[id].robFails);
  });
});

/**
 * Measured (chunks 0-44), re-pinned for #65: Debutmont base + arcade bridges, on BIG (150 seeds): rollingBoulder 37.4 %
 * (chance 0.45), gearGate 42.3 %, dewDrop 41.4 %. Before #65 the 8/32-seed samples read 41.9 % / 35.4 % (rolling),
 * 55.6 % / 39.5 % (gear gate), 44.4 % / 37.2 % (dew drop); 400 seeds read 37.0 / 41.3 / 39.7 % before and 37.1 / 42.3 / 40.4 %
 * after, so the rates did not move (see the note at BIG). robFails: seeds with >= 1 km of the biome in chunks 0-44 that miss
 * 1 per 2 km (0 of ~21 per hazard at #65).
 */
const PRESENCE = {
  rollingBoulder: { lo: 0.35, hi: 0.55, robFails: 2 },
  gearGate: { lo: 0.35, hi: 0.55, robFails: 2 },
  dewDrop: { lo: 0.35, hi: 0.55, robFails: 2 },
};

describe('B3 presence: long range (4 seeds x 300 chunks), hazard floor and power-up band', () => {
  // Measured: rollingBoulder 83/252 = 32.9 %, sandrunnerSkis 126/356 = 35.4 %; gearGate 75/208 = 36.1 %, clockworkTreads
  // 134/341 = 39.3 %; dewDrop 82/227 = 36.1 %, royalJellyWax 130/348 = 37.4 %. The pickups keep 90 px from a rolling
  // hazard's whole track (_trackDist); they stay inside B1's 25-45 % power-up band.
  const ROWS = [
    [4, 'pyramid-peak', 'rollingBoulder', 'sandrunnerSkis', 0.3, 0.25, 0.45],
    [256, 'steampunk-slopes', 'gearGate', 'clockworkTreads', 0.33, 0.25, 0.45],
    [512, 'micro-mountain', 'dewDrop', 'royalJellyWax', 0.33, 0.25, 0.45],
  ];
  test.each(ROWS)('mask %p (%s): hazard %s, power-up %s, hazard share of eligible chunks >= %p, power-up share of biome chunks in [%p, %p]', (mask, biome, hz, pu, floor, lo, hi) => {
    let all = 0;
    let elig = 0;
    let h = 0;
    let p = 0;
    for (const seed of ['b1-share-a', 'b1-share-b', 'b1-share-c', 'b1-share-d']) {
      const g = makeGen(seed, { biomeMask: mask });
      for (let i = 1; i < 300; i++) {
        const ch = g.getChunk(i);
        if (ch.biome !== biome) continue;
        all++;
        if (eligibleFor(c.hazards[hz], ch)) elig++;
        if (ch.hazards.some((q) => q.defId === hz)) h++;
        if (ch.powerups.some((q) => q.defId === pu)) p++;
      }
    }
    console.log(`${hz}: ${h}/${elig} eligible = ${(100 * h / elig).toFixed(1)} %; ${pu}: ${p}/${all} = ${(100 * p / all).toFixed(1)} %`);
    expect(elig).toBeGreaterThan(60);
    expect(h / elig).toBeGreaterThanOrEqual(floor);
    expect(p / all).toBeGreaterThanOrEqual(lo);
    expect(p / all).toBeLessThanOrEqual(hi);
  });
});

describe('B3 fairness numbers (moving hazards)', () => {
  test('a rolling hazard starts while it is on screen, and rolls before it can reach the sled', () => {
    // B2's built-game view probe: at least 348 px of ground are on screen ahead of the sled at any speed >= 100 px/s.
    expect(ROLL_ACTIVATE_PX).toBeLessThanOrEqual(348);
    for (const id of ['rollingBoulder', 'dewDrop']) {
      const p = rollParams(c.hazards[id].motion);
      // a sled that has stopped dead at the activation line is never reached: the roll ends short of it
      expect(p.rangePx).toBeLessThan(ROLL_ACTIVATE_PX - c.hazards[id].size.w);
    }
  });

  test('the contact is dodgeable by a hop at the expected speed (hop air time covers the closing pass with margin)', () => {
    const g = PHYSICS.gravityPxS2 || 900;
    const v0 = TUNING.hopPxS;
    for (const id of ['rollingBoulder', 'dewDrop']) {
      const def = c.hazards[id];
      const p = rollParams(def.motion);
      const boxH = def.size.h * 0.8; // crash hit-box height
      // time the sled's underside is above the box: v0 t - g t^2 / 2 >= boxH
      const disc = v0 * v0 - 2 * g * boxH;
      expect(disc).toBeGreaterThan(0);
      const above = (2 * Math.sqrt(disc)) / g;
      for (const distM of [0, 1000, 2000, 4000]) {
        const v = expectedSpeedPxS(distM);
        const closing = v - p.speedPxS * p.dir; // B3 tuning: it rolls away, so the sled closes at v - roll (worst case: the cap)
        const overlap = (def.size.w * 0.72 + 40) / closing; // box + sled length (~40 px) pass under the sled
        const windowMs = (above - overlap) * 1000;
        console.log(`${id} @ ${distM} m: v ${v.toFixed(0)}, closing ${closing.toFixed(0)} px/s, above box ${(above * 1000).toFixed(0)} ms, pass ${(overlap * 1000).toFixed(0)} ms, hop window ${windowMs.toFixed(0)} ms`);
        expect(windowMs).toBeGreaterThan(300);
      }
    }
  });

  test('B3 tuning: a roll that catches a sled up from behind never reaches a moving sled, and overtakes a stopped one slowly', () => {
    for (const id of ['rollingBoulder', 'dewDrop']) {
      const m = c.hazards[id].motion;
      const p = rollParams(m);
      expect(p.dir).toBe(1); // downhill, away from the sled
      // its top speed (the cap) is under the stall net's restart speed and far under the slowest expected sled speed
      expect(p.speedPxS).toBeLessThan(TUNING.stallNudgeToPxS);
      expect(p.speedPxS).toBeLessThan(expectedSpeedPxS(0) / 3);
      // where a sled stops (flat or rising ground) the roll is at its floor: slower than one push kick, so W escapes it
      const flat = rollTargetSpeed(m, 0);
      expect(flat).toBeLessThan(TUNING.pushKickPxS);
      console.log(`${id}: cap ${p.speedPxS} px/s (flat ground ${flat.toFixed(0)} px/s); closing on a stopped sled ${flat.toFixed(0)}-${p.speedPxS} px/s; push kick ${TUNING.pushKickPxS}, stall net ${TUNING.stallNudgeToPxS}`);
    }
  });

  test('a Gear Gate is never closed for the whole time it is on screen before the sled reaches it (1.2 x expected speed)', () => {
    const t = gateTiming(c.hazards.gearGate.motion);
    expect(t.closedMs).toBeLessThanOrEqual(GATE_MAX_CLOSED_MS);
    // B2 view probe (ahead px by speed); the top expected speed is 700 px/s (SPEED_TAIL), x1.2 = 840 px/s
    const AHEAD = [[300, 410], [500, 453], [700, 470], [900, 499]];
    const ahead = (v) => { let a = AHEAD[0][1]; for (const [s, px] of AHEAD) if (v >= s) a = px; return a; };
    for (const distM of [500, 1000, 2000, 6000, 10000]) {
      const v = expectedSpeedPxS(distM) * 1.2;
      const onScreenMs = (ahead(v) / v) * 1000;
      console.log(`gearGate @ ${distM} m: 1.2 x v = ${v.toFixed(0)} px/s, on screen ${onScreenMs.toFixed(0)} ms before reach, closed spell ${t.closedMs} ms, open ${t.openMs} ms, cross ${(1000 * (c.hazards.gearGate.size.w + 40) / v).toFixed(0)} ms`);
      expect(onScreenMs).toBeGreaterThan(t.closedMs);
      expect(t.openMs).toBeGreaterThan((1000 * (c.hazards.gearGate.size.w + 40)) / v * 3);
    }
  });
});

describe('B3 invariant: same seed + mask gives identical terrain twice (shipped content)', () => {
  test.each([4, 256, 512])('mask %p: two generators, forward and reverse call order, deep-equal over 150 chunks', (mask) => {
    const snap = (ch) => JSON.parse(JSON.stringify(ch));
    const a = makeGen('b3-det', { biomeMask: mask });
    const b = makeGen('b3-det', { biomeMask: mask });
    const rev = [];
    for (let i = 149; i >= 0; i--) rev[i] = snap(b.getChunk(i));
    let biomeSpawns = 0;
    for (let i = 0; i < 150; i++) {
      const ch = snap(a.getChunk(i));
      expect(ch).toEqual(rev[i]);
      biomeSpawns += [...ch.hazards, ...ch.powerups].filter((s) => (c.hazards[s.defId] || c.powerups[s.defId]).biome).length;
    }
    expect(biomeSpawns).toBeGreaterThan(0);
  });
});/**
 * B4 "Air" content (spec §4 table and bounds): the biome hazard and power-up of Space Mountain (32) and Sky Jellyfish
 * Mountain (128). Loader + schema check for the new JSON, the values the spec names, and the pairing rule (each pickup
 * counters its own biome: the Gravity Stabilizer widens the landing tolerance that Space's long low-gravity flights test,
 * the Stabilizer Rails also damp the bounce of Sky Jellyfish's bouncySpring mod).
 */
import { readDir, loadContent, makeGen } from './_helpers.js';
import { PALETTE_KEYS } from '../../src/constants.js';
import {
  hazardDrawKind, powerupDrawKind, hazardColorKey, gustImpulse, GUST_MAX_PX_S, stabilizeToleranceDeg, stabilizeBounceMul,
  timedPowerupMs, resolveLanding,
} from '../../src/systems/BiomeEffects.js';
import { BIOME_SPAWN_MAX_CHANCE, BIOME_HAZARD_MAX_CHANCE } from '../../src/systems/TerrainGenerator.js';
import { PhysicsTuner, TUNING } from '../../src/systems/PhysicsTuner.js';

const c = loadContent();
const biomeHaz = readDir('hazards').filter((d) => d.biome);
const biomePu = readDir('powerups').filter((d) => d.biome);

/** Spec §4 B4 rows. */
const B4 = {
  'space-mountain': { hazard: 'meteor', powerup: 'gravityStabilizer' },
  'sky-jellyfish-mountain': { hazard: 'gustFront', powerup: 'stabilizerRails' },
};
const B4_HAZ = Object.values(B4).map((r) => c.hazards[r.hazard]);
const B4_PU = Object.values(B4).map((r) => c.powerups[r.powerup]);

describe('B4 content: loader and schema', () => {
  test('exactly one hazard and one power-up per B4 biome; all 11 biomes now ship 11 hazards and 11 power-ups', () => {
    const byBiome = (list) => Object.fromEntries(Object.keys(B4).map((b) => [b, list.filter((d) => d.biome === b).map((d) => d.id)]));
    expect(byBiome(biomeHaz)).toEqual(Object.fromEntries(Object.entries(B4).map(([b, r]) => [b, [r.hazard]])));
    expect(byBiome(biomePu)).toEqual(Object.fromEntries(Object.entries(B4).map(([b, r]) => [b, [r.powerup]])));
    expect(biomeHaz.length).toBe(11);
    expect(biomePu.length).toBe(11);
    // one of each per biome, every biome covered (spec §10 completion contract)
    for (const b of Object.keys(c.biomes)) {
      expect({ b, h: biomeHaz.filter((d) => d.biome === b).length, p: biomePu.filter((d) => d.biome === b).length }).toEqual({ b, h: 1, p: 1 });
    }
  });

  test('every B4 def names a real biome and follows the hazard / power-up schema and the §4 chance caps', () => {
    for (const h of B4_HAZ) {
      expect(c.biomes[h.biome]).toBeDefined();
      expect(h.size.w).toBeGreaterThan(0);
      expect(h.size.h).toBeGreaterThan(0);
      expect(h.weight).toBeGreaterThan(0);
      expect(h.minDistanceM).toBeGreaterThanOrEqual(0);
      expect(h.placement).toBe('air');
      expect(PALETTE_KEYS).toContain(h.colorKey);
      expect(h.spawn.baseChance).toBeGreaterThan(0);
      expect(h.spawn.baseChance).toBeLessThanOrEqual(BIOME_HAZARD_MAX_CHANCE);
    }
    for (const p of B4_PU) {
      expect(c.biomes[p.biome]).toBeDefined();
      expect(p.radius).toBeGreaterThan(0);
      expect(PALETTE_KEYS).toContain(p.colorKey);
      expect(p.spawn.baseChance).toBeGreaterThan(0);
      expect(p.spawn.baseChance).toBeLessThanOrEqual(BIOME_SPAWN_MAX_CHANCE);
    }
  });

  test('both B4 hazards carry a display name (death legibility names the killer from it)', () => {
    expect(c.hazards.meteor.name).toBe('Meteor');
    expect(c.hazards.gustFront.name).toBe('Gust Front');
  });

  test('every B4 shapeKey has its own drawing and all biome shapeKeys stay unique', () => {
    for (const h of B4_HAZ) expect({ id: h.id, draw: hazardDrawKind(h) }).toEqual({ id: h.id, draw: h.shapeKey });
    for (const p of B4_PU) expect({ id: p.id, draw: powerupDrawKind(p) }).toEqual({ id: p.id, draw: p.shapeKey });
    const keys = [...biomeHaz, ...biomePu].map((d) => d.shapeKey);
    expect(new Set(keys).size).toBe(keys.length);
  });

  test('Meteor crashes, so it is `danger`; Gust Front never crashes, so it is not', () => {
    expect(c.hazards.meteor.onHit).toEqual({ effect: 'crash' });
    expect(c.hazards.meteor.colorKey).toBe('danger');
    expect(hazardColorKey(c.hazards.meteor)).toBe('danger');
    expect(c.hazards.gustFront.onHit.effect).toBe('gust');
    expect(c.hazards.gustFront.colorKey).not.toBe('danger');
    expect(hazardColorKey(c.hazards.gustFront)).toBe(c.hazards.gustFront.colorKey);
  });
});

describe('B4 content: the spec §4 values', () => {
  test('Space Mountain: Meteor is an air crash hazard in the jump arcs (like Seagull Dive)', () => {
    expect(c.hazards.meteor).toMatchObject({ placement: 'air', onHit: { effect: 'crash' }, biome: 'space-mountain' });
  });

  test('Sky Jellyfish: Gust Front is an air zone with ONE bounded impulse (<= 180 px/s, never clamped from above)', () => {
    const g = c.hazards.gustFront;
    expect(g.placement).toBe('air');
    expect(Array.isArray(g.onHit.impulsePxS)).toBe(true);
    const [x, y] = g.onHit.impulsePxS;
    expect(Math.hypot(x, y)).toBeLessThanOrEqual(GUST_MAX_PX_S);
    expect(gustImpulse(g.onHit.impulsePxS)).toEqual({ dvx: x, dvy: y });
    expect(Math.hypot(x, y)).toBeGreaterThanOrEqual(100); // felt: a kick, not a nudge
  });

  test('Gravity Stabilizer: stabilize, landing tolerance +12 deg for 5 s (no bounce change)', () => {
    const e = c.powerups.gravityStabilizer.effect;
    expect(e).toEqual({ kind: 'stabilize', landingToleranceDeg: 12, durationMs: 5000 });
    expect(stabilizeToleranceDeg(e.landingToleranceDeg)).toBe(12);
    expect(stabilizeBounceMul(e.bounceMul)).toBe(1);
    expect(timedPowerupMs(e)).toBe(5000);
  });

  test('Stabilizer Rails: the shared stabilize kind, with a damped bounce (bounceMul < 1, inside the clamp)', () => {
    const e = c.powerups.stabilizerRails.effect;
    expect(e.kind).toBe('stabilize');
    expect(e.bounceMul).toBeGreaterThan(0.1);
    expect(e.bounceMul).toBeLessThan(1);
    expect(stabilizeBounceMul(e.bounceMul)).toBe(e.bounceMul);
    expect(stabilizeToleranceDeg(e.landingToleranceDeg)).toBe(e.landingToleranceDeg);
    expect(timedPowerupMs(e)).toBe(e.durationMs);
  });
});

describe('B4 content: each power-up counters its own biome', () => {
  test('the Gravity Stabilizer turns a landing just past the forgiveness angle from a crash into a wobble', () => {
    const tol = c.powerups.gravityStabilizer.effect.landingToleranceDeg;
    const land = { quality: 'crash', angleDeg: TUNING.forgiveAngleDeg + 6, impactSpeedPxS: 500 };
    expect(resolveLanding(land, 0).quality).toBe('crash');
    expect(resolveLanding(land, tol).quality).toBe('sloppy');
    // past the widened tolerance it still crashes (the stabilizer is a margin, not invulnerability)
    expect(resolveLanding({ ...land, angleDeg: TUNING.forgiveAngleDeg + tol + 1 }, tol).quality).toBe('crash');
  });

  test('the Stabilizer Rails damp the Sky Jellyfish bouncySpring mod on the real tuner (bounce and restitution lower)', () => {
    expect(c.biomes['sky-jellyfish-mountain'].mod).toBe('bouncySpring');
    const t = new PhysicsTuner();
    const zone = [c.terrainMods.bouncySpring];
    const m = stabilizeBounceMul(c.powerups.stabilizerRails.effect.bounceMul);
    const bouncy = t.getEffective({ zones: zone });
    const railed = t.getEffective({ zones: zone, stabilizeBounceMul: m });
    expect(bouncy.bounceMul).toBeGreaterThan(1.5);
    expect(railed.bounceMul).toBeCloseTo(bouncy.bounceMul * m, 12);
    expect(railed.restitution).toBeLessThan(bouncy.restitution * 0.5);
  });

  test('no B4 def appears at mask 0', () => {
    const ids = new Set([...B4_HAZ, ...B4_PU].map((d) => d.id));
    const g = makeGen('b4-mask0', { biomeMask: 0 });
    for (let i = 0; i < 120; i++) {
      const ch = g.getChunk(i);
      expect(ch.hazards.some((h) => ids.has(h.defId))).toBe(false);
      expect(ch.powerups.some((p) => ids.has(p.defId))).toBe(false);
    }
  });
});/**
 * B4 "Air": the SHIPPED Space Mountain and Sky Jellyfish Mountain defs through RunScene dispatch (Meteor crash, Gust
 * Front impulse, never named as the killer; both stabilizers on the real landing path and the frame tuner), HUD tables
 * and drawing. Same fake Phaser seam as biome-b3-effects.test.js. The built-game gate checks the same effects on the real sled.
 */
import { jest } from '@jest/globals';

const moved = [];
const Body = {
  getVelocity: (b) => ({ x: b.velocity.x, y: b.velocity.y }),
  setVelocity: (b, v) => { b.velocity = { x: v.x, y: v.y }; },
  getAngularVelocity: () => 0,
  setAngularVelocity: () => {},
  setPosition: (b, p) => { b.x = p.x; b.y = p.y; moved.push(p); },
  setAngle: (b, a) => { b.angle = a; },
};
class Stub { constructor() { this.alpha = 0; } setAlpha(a) { this.alpha = a; return this; } setFillStyle() { return this; } }
const FakePhaser = {
  Scene: class {},
  Physics: { Matter: { Matter: { Bodies: { rectangle: (x, y, w, h, o) => ({ x, y, w, h, ...o }), circle: (x, y, r, o) => ({ x, y, r, ...o }) }, Body } } },
  Renderer: { WebGL: { Pipelines: { PostFXPipeline: class {} } } },
  GameObjects: { Container: class {}, Graphics: class {}, BitmapText: class {}, Zone: class {}, Image: class {}, Rectangle: class {}, Text: class {} },
  BlendModes: { ADD: 1 },
  Scenes: { Events: { UPDATE: 'update', SHUTDOWN: 'shutdown', DESTROY: 'destroy' } },
  Math: { Between: (a) => a, Clamp: (v, a, b) => Math.min(b, Math.max(a, v)) },
};
jest.unstable_mockModule('phaser', () => ({ default: FakePhaser }));
jest.unstable_mockModule('../../src/shaders/GlitchPipeline.js', () => ({ GlitchPipeline: { install() {} } }));

const { RunScene } = await import('../../src/scenes/RunScene.js');
const { UIScene } = await import('../../src/scenes/UIScene.js');
const { Hazard } = await import('../../src/entities/Hazard.js');
const { PowerUp } = await import('../../src/entities/PowerUp.js');
const { EVT } = await import('../../src/events.js');
const { PhysicsTuner, BASE_STEP_MS, TUNING } = await import('../../src/systems/PhysicsTuner.js');

const { loadContent, makeGen } = await import('./_helpers.js');
const { GUST_MAX_PX_S, springRebound } = await import('../../src/systems/BiomeEffects.js');

const C = loadContent();
const PAD = { tuck: false, brake: false };
const PAL = { danger: 0xff0000, magenta: 0xff00ff, lime: 0x00ff00, cyan: 0x00ffff, amber: 0xffaa00, bg: 0, bgAlt: 1, text: 0xffffff };

/** A fake scene for the entity: graphics that record draw calls and keep their position, a sled, the ground. */
function scene({ sledX = -1e9, heightAt = (x) => 200 + x * 0.25, slopeAt = () => Math.atan(0.25) * 180 / Math.PI } = {}) {
  return {
    matter: { world: { add() {}, remove() {} } },
    sled: { x: sledX },
    heightFn: heightAt,
    terrain: { slopeDegAt: slopeAt, heightAt },
    add: {
      graphics: (o) => {
        const ops = [];
        const g = new Proxy({ ops, x: o ? o.x : 0, y: o ? o.y : 0, rotation: 0, visible: true }, {
          get: (t, k) => {
            if (k in t) return t[k];
            if (k === 'setPosition') return (x, y) => { t.x = x; t.y = y; return g; };
            if (k === 'setRotation') return (r) => { t.rotation = r; return g; };
            if (k === 'setVisible') return (v) => { t.visible = v; return g; };
            if (k === 'clear') return () => { ops.length = 0; return g; };
            return (...a) => { ops.push([k, ...a]); return g; };
          },
          set: (t, k, v) => { t[k] = v; return true; },
        });
        return g;
      },
    },
  };
}
const spawnOn = (sc, x, extra = {}) => ({ x, y: sc.heightFn(x), rotationDeg: sc.terrain.slopeDegAt(x), ...extra });

function makeRun({ zones = [] } = {}) {
  const emitted = [];
  const s = Object.create(RunScene.prototype);
  Object.assign(s, {
    game: { events: { emit: (e, p) => { emitted.push([e, p]); } } },
    emitted,
    sled: {
      x: 1000, y: 0, vx: 300, vy: 20, inWorld: true, invulnerableMs: 0, grounded: true, parachuteMs: 0, airBrakeActive: false, shield: false,
      body: { velocity: { x: 300 * BASE_STEP_MS / 1000, y: 20 * BASE_STEP_MS / 1000 } },
      scaleVelocity() {}, wobble() {},
    },
    fx: { sparks() {}, ring() {} },
    shake() {},
    flashRect: new Stub(),
    blindRect: new Stub(),
    palette: { cyan: 1, amber: 2, lime: 3, bg: 0 },
    tuner: new PhysicsTuner(),
    dailyMods: {},
    crashed: false,
    pendingCrash: null,
    runTimeMs: 0,
    startX: 0,
    openingGraces: 0,
    slowMs: 0, slowFactor: 0.5, scrambleMs: 0, boostMs: 0, boostFactor: 1, slowmoMs: 0, slowmoScale: 0.5, shieldCharges: 0,
    collectedPowerups: new Set(),
    score: { onShieldHit: () => null, getSnapshot: () => ({ comboTricks: [] }) },
    emitFlow() {},
    _despawn: [],
  });
  s.getZoneDefs = () => zones;
  s._resetBiomeEffects();
  return s;
}
const take = (id) => ({ def: C.powerups[id], spawn: { x: 1000, y: 0 }, color: 5, destroy() {} });
const phys = (s) => s.tuner.getEffective(s.physicsContext(PAD));
const events = (s, name) => s.emitted.filter(([e]) => e === name).map(([, p]) => p);

const hit = (id) => ({ def: C.hazards[id], cx: 1000, cy: 0, color: 5, gfx: null, hit: false });
const toPxS = (v) => (v * 1000) / BASE_STEP_MS;
const vel = (s) => ({ x: toPxS(s.sled.body.velocity.x), y: toPxS(s.sled.body.velocity.y) });
/** RunScene.handleTricksAndLanding needs a score and a few emitters; the landing path itself is the shipped one. */
const landable = (s) => {
  s.score = { getSnapshot: () => ({ multiplier: 1, comboTricks: [] }), onLanding: () => ({ bonus: 0, banked: 0, multiplierUsed: 1 }) };
  s.emitCombo = () => {}; s.emitScore = () => {}; s._zoneScoreMulAt = () => 1; s.applyLandingBoost = () => {};
  return s;
};
const LAND = { quality: 'crash', angleDeg: TUNING.forgiveAngleDeg + 6, impactSpeedPxS: 450, airtimeMs: 900 };
const FS = { x: 1000, y: 0, vx: 300, vy: 0, groundAngleDeg: 22 };

describe('B4 hazards through RunScene.onHazard (shipped defs)', () => {
  test('Meteor: a hit queues a crash named meteor (the killer death legibility shows)', () => {
    const s = makeRun();
    s.onHazard(hit('meteor'));
    expect(s.pendingCrash).toEqual({ cause: 'hazard', hazardId: 'meteor' });
    expect(events(s, EVT.HAZARD_HIT)).toEqual([{ hazardId: 'meteor', effect: 'crash', durationMs: 0, x: 1000, y: 0 }]);
  });

  test('Gust Front: the real sled body velocity changes by exactly the def impulse (<= 180 px/s), no crash, HAZARD_HIT 0 ms', () => {
    const s = makeRun();
    const [ix, iy] = C.hazards.gustFront.onHit.impulsePxS;
    const v0 = vel(s);
    s.onHazard(hit('gustFront'));
    const v1 = vel(s);
    expect(v1.x - v0.x).toBeCloseTo(ix, 6);
    expect(v1.y - v0.y).toBeCloseTo(iy, 6);
    expect(Math.hypot(v1.x - v0.x, v1.y - v0.y)).toBeLessThanOrEqual(GUST_MAX_PX_S + 1e-9);
    expect([s.sled.vx, s.sled.vy]).toEqual([300 + ix, 20 + iy]); // Sled's px/s cache kept in step
    expect(s.pendingCrash).toBe(null);
    expect(events(s, EVT.HAZARD_HIT)).toEqual([{ hazardId: 'gustFront', effect: 'gust', durationMs: 0, x: 1000, y: 0 }]);
  });

  test('a gust is never named as the killer: what the gust pushes you into is', () => {
    // into a hazard
    const a = makeRun();
    a.onHazard(hit('gustFront'));
    a.onHazard(hit('meteor'));
    expect(a.pendingCrash).toEqual({ cause: 'hazard', hazardId: 'meteor' });
    // into a bad landing
    const b = landable(makeRun());
    b.onHazard(hit('gustFront'));
    b.handleTricksAndLanding({ tricks: [], landing: { ...LAND, angleDeg: 120 } }, FS);
    expect(b.pendingCrash).toEqual({ cause: 'badLanding' });
    // a second gust front does not overwrite an earlier queued killer, and adds no hazardId of its own
    const c = makeRun();
    c.onHazard(hit('meteor'));
    const g2 = hit('gustFront');
    c.crashed = false;
    c.onHazard(g2);
    expect(c.pendingCrash).toEqual({ cause: 'hazard', hazardId: 'meteor' });
  });
});

describe('B4 power-ups through RunScene.onPowerUp (shipped defs, the shared stabilize kind)', () => {
  test.each(['gravityStabilizer', 'stabilizerRails'])('%s: a landing just past the forgiveness angle crashes without it, is a wobble with it, crashes again after 5 s', (id) => {
    const plain = landable(makeRun());
    plain.handleTricksAndLanding({ tricks: [], landing: LAND }, FS);
    expect(plain.pendingCrash).toEqual({ cause: 'badLanding' });

    const s = landable(makeRun());
    s.onPowerUp(take(id));
    expect(events(s, EVT.POWERUP_COLLECTED)).toEqual([{ id, durationMs: 5000, charges: 0 }]);
    s.handleTricksAndLanding({ tricks: [], landing: LAND }, FS);
    expect(s.pendingCrash).toBe(null);
    expect(events(s, EVT.LANDING).map((p) => p.quality)).toEqual(['sloppy']);
    s.tickEffects(5001);
    expect(events(s, EVT.POWERUP_EXPIRED)).toEqual([{ id, reason: 'timeout' }]);
    s.handleTricksAndLanding({ tricks: [], landing: LAND }, FS);
    expect(s.pendingCrash).toEqual({ cause: 'badLanding' });
  });

  test('Stabilizer Rails damp the Sky Jellyfish bouncySpring on the frame tuner (bounceMul, restitution), back after 5 s', () => {
    const s = makeRun({ zones: [C.terrainMods.bouncySpring] });
    const bouncy = phys(s);
    s.onPowerUp(take('stabilizerRails'));
    const railed = phys(s);
    expect(railed.bounceMul).toBeCloseTo(bouncy.bounceMul * C.powerups.stabilizerRails.effect.bounceMul, 12);
    expect(railed.restitution).toBeLessThan(bouncy.restitution * 0.5);
    s.tickEffects(5001);
    expect(phys(s).bounceMul).toBeCloseTo(bouncy.bounceMul, 12);
  });

  test('the Gravity Stabilizer leaves the bounce alone (no bounceMul: it is the landing margin only)', () => {
    const s = makeRun({ zones: [C.terrainMods.bouncySpring] });
    const bouncy = phys(s);
    s.onPowerUp(take('gravityStabilizer'));
    expect(phys(s).bounceMul).toBeCloseTo(bouncy.bounceMul, 12);
  });

  test('taking the other stabilizer replaces the first one (the chip of the first expires as replaced)', () => {
    const s = makeRun();
    s.onPowerUp(take('gravityStabilizer'));
    s.onPowerUp(take('stabilizerRails'));
    expect(events(s, EVT.POWERUP_EXPIRED)).toEqual([{ id: 'gravityStabilizer', reason: 'replaced' }]);
  });
});

describe('B4 HUD entries (UIScene)', () => {
  const ui = () => Object.assign(Object.create(UIScene.prototype), { content: C, nowMs: 0, warnY: 40, effects: new Map() });
  const recorder = () => {
    const ops = [];
    return { ops, g: new Proxy({}, { get: (t, k) => (...a) => { ops.push([k, ...a]); return undefined; } }) };
  };
  const IDS = ['gravityStabilizer', 'stabilizerRails'];

  test('each B4 pickup has its own HUD name and colour', () => {
    const u = ui();
    expect(IDS.map((id) => u._powerInfo(id).name)).toEqual(['GRAV STABILIZER', 'STABILIZER RAILS']);
    expect(IDS.map((id) => u._powerInfo(id).color)).toEqual(['amber', 'lime']);
  });

  test('each B4 pickup chip draws its own icon: not the unknown square, not the stabilize kind icon, both different', () => {
    const u = ui();
    const draw = (id) => { const r = recorder(); u._drawIcon(r.g, id, 10, 10, 1); return JSON.stringify(r.ops.filter(([k]) => k !== 'lineStyle' && k !== 'fillStyle')); };
    const square = JSON.stringify([['strokeRect', 5, 5, 10, 10]]);
    const v = Object.assign(Object.create(UIScene.prototype), { content: { powerups: { w: { effect: { kind: 'stabilize' } } } } });
    const r = recorder(); v._drawIcon(r.g, 'w', 10, 10, 1);
    const kindIcon = JSON.stringify(r.ops.filter(([k]) => k !== 'lineStyle' && k !== 'fillStyle'));
    const icons = IDS.map(draw);
    for (const ic of icons) {
      expect(ic).not.toBe(square);
      expect(ic).not.toBe(kindIcon);
    }
    expect(new Set(icons).size).toBe(2);
  });

  test('a Gust Front names itself on the warning line; a nameless gust keeps GUST', () => {
    const u = ui();
    const made = [];
    u._t = () => { const t = { text: '', setText(x) { this.text = x; return t; }, setColorKey() { return t; }, destroy() {} }; made.push(t); return t; };
    u.onHazard({ effect: 'gust', durationMs: 0, hazardId: 'gustFront' });
    expect(made[0].text).toContain('GUST FRONT');
    const w = ui();
    const made2 = [];
    w._t = () => { const t = { text: '', setText(x) { this.text = x; return t; }, setColorKey() { return t; }, destroy() {} }; made2.push(t); return t; };
    w.onHazard({ effect: 'gust', durationMs: 0 });
    expect(made2[0].text).toContain('GUST');
    expect(made2[0].text).not.toContain('FRONT');
  });
});

describe('B4 drawing: every new shapeKey has its own routine', () => {
  const shape = (gfx) => JSON.stringify(gfx.ops.filter(([k]) => /^fill(Rect|Triangle|Points|Circle|Ellipse)$|^stroke|^lineBetween$/.test(k)).map(([k]) => k));
  const air = (x) => ({ x, y: 50, rotationDeg: 0 });

  test('Meteor draws its own shape in `danger`; Gust Front its own in cyan (not danger); both differ from the generic box', () => {
    const out = {};
    for (const id of ['meteor', 'gustFront']) {
      const def = C.hazards[id];
      const sc = scene();
      const h = new Hazard(sc, def, air(100), PAL);
      expect(h.drawKind).toBe(def.shapeKey);
      expect(h.color).toBe(id === 'meteor' ? PAL.danger : PAL.cyan);
      out[id] = shape(h.gfx);
      const generic = new Hazard(sc, { ...def, shapeKey: 'zzUnknownShape' }, air(100), PAL);
      expect(generic.drawKind).toBe('generic');
      expect(out[id]).not.toBe(shape(generic.gfx));
    }
    expect(out.meteor).not.toBe(out.gustFront);
  });

  test('the Gust Front streaks point the way the gust pushes (its arrowhead tip lies along the impulse)', () => {
    const def = C.hazards.gustFront;
    const h = new Hazard(scene(), def, air(100), PAL);
    const tri = h.gfx.ops.filter(([k]) => k === 'fillTriangle').pop();
    expect(tri).toBeDefined();
    const [, tx, ty] = tri;
    const [ix, iy] = def.onHit.impulsePxS;
    // tip relative to the box centre (0, -h/2) points along the impulse
    const cx = tx;
    const cy = ty + def.size.h / 2;
    expect((cx * ix + cy * iy) / (Math.hypot(cx, cy) * Math.hypot(ix, iy))).toBeGreaterThan(0.99);
  });

  test('both pickups draw non-generic glyphs, different from each other', () => {
    const out = {};
    for (const id of ['gravityStabilizer', 'stabilizerRails']) {
      const def = C.powerups[id];
      const p = new PowerUp(scene(), def, { x: 100, y: 50 }, PAL);
      expect(p.drawKind).toBe(def.shapeKey);
      out[id] = shape(p.gfx);
      const generic = new PowerUp(scene(), { ...def, shapeKey: 'zzUnknownGlyph' }, { x: 100, y: 50 }, PAL);
      expect(out[id]).not.toBe(shape(generic.gfx));
    }
    expect(new Set(Object.values(out)).size).toBe(2);
  });
});

describe('Sky Jellyfish felt bounce through RunScene.handleTricksAndLanding (shipped bouncySpring def)', () => {
  const GOOD = { quality: 'good', angleDeg: 3, impactSpeedPxS: 800, airtimeMs: 600 };
  /** A landable run whose sled records the slope-normal rebound, with the frame tuner as update() leaves it. */
  const springy = (zones, rails = false) => {
    const s = landable(makeRun({ zones }));
    s.calls = [];
    s.sled.launchNormal = (up, angleDeg) => { s.calls.push([up, angleDeg]); };
    if (rails) s.onPowerUp(take('stabilizerRails'));
    s.currentPhys = phys(s);
    return s;
  };

  test('a scored landing in a bouncySpring zone rebounds once along the landing slope normal', () => {
    const s = springy([C.terrainMods.bouncySpring]);
    s.handleTricksAndLanding({ tricks: [], landing: GOOD }, FS);
    const up = springRebound(800, C.terrainMods.bouncySpring.physics.landingRebound);
    expect(up).toBeCloseTo(160, 9);
    expect(s.calls).toEqual([[up, FS.groundAngleDeg]]);
  });

  test('an impact under the 120 px/s felt floor gives no rebound, even inside the zone', () => {
    const s = springy([C.terrainMods.bouncySpring]);
    s.handleTricksAndLanding({ tricks: [], landing: { ...GOOD, impactSpeedPxS: 500 } }, FS);
    expect(springRebound(500, C.terrainMods.bouncySpring.physics.landingRebound)).toBe(0);
    expect(s.calls).toEqual([]);
  });

  test('negative controls: plain ground, a crash landing and an unscored touchdown give no rebound', () => {
    const plain = springy([]);
    plain.handleTricksAndLanding({ tricks: [], landing: GOOD }, FS);
    expect(plain.calls).toEqual([]);
    const crash = springy([C.terrainMods.bouncySpring]);
    crash.handleTricksAndLanding({ tricks: [], landing: { ...GOOD, angleDeg: 120, quality: 'crash' } }, FS);
    expect(crash.calls).toEqual([]);
    expect(crash.pendingCrash).toEqual({ cause: 'badLanding' });
    const none = springy([C.terrainMods.bouncySpring]);
    none.handleTricksAndLanding({ tricks: [] }, FS);
    expect(none.calls).toEqual([]);
  });

  test('with the Stabilizer Rails the same landing rebounds far less (here: not at all), and the bounce is back after 5 s', () => {
    const s = springy([C.terrainMods.bouncySpring], true);
    s.handleTricksAndLanding({ tricks: [], landing: GOOD }, FS);
    const bare = springRebound(800, C.terrainMods.bouncySpring.physics.landingRebound);
    expect(s.calls.reduce((a, [up]) => a + up, 0)).toBeLessThan(bare * 0.5);
    s.tickEffects(5001);
    s.currentPhys = phys(s);
    s.handleTricksAndLanding({ tricks: [], landing: GOOD }, FS);
    expect(s.calls[s.calls.length - 1]).toEqual([bare, FS.groundAngleDeg]);
  });
});/**
 * B4 "Air" placement: presence (spec §4 presence amendment, same target and method as biome-b2-presence.test.js), the
 * low-gravity fairness rule for biome air boxes (TerrainGenerator.flightGravityMul: under Space Mountain's lowGravity zone
 * a no-hop flight drops less, so the Meteor box is lifted to keep AIR_CLEARANCE_PX over the flatter arc), and determinism
 * for masks 32 and 128 (shipped content).
 */
import { makeGen, loadContent } from './_helpers.js';
import { flightGravityMul } from '../../src/systems/TerrainGenerator.js';

const c = loadContent();
const SEEDS = ['pres1', 'pres2', 'pres3', 'pres4', 'pres5', 'pres6', 'pres7', 'pres8'];
const ROB = Array.from({ length: 32 }, (_, k) => `rob${k + 1}`);
// re-pinned for #65: Debutmont base + arcade bridges. Same re-assessment as biome-b1-presence.test.js: the generator's hazard
// rates are unchanged (400 seeds, +/-0.02), the sample is ~25 % smaller because each biome sector opens with an arcade bridge,
// so the band is asserted on BIG (150 seeds) and the per-seed 1-per-2-km rule on seeds with >= SHORT_KM of the biome.
const BIG = Array.from({ length: 150 }, (_, k) => `big${k + 1}`);
const SHORT_KM = 1;
/** Air hazards are placed only in generated jumps (isJump). */
const eligible = (ch) => ch.defId === 'gen-jump';

function presence(mask, biome, id, seeds) {
  let elig = 0;
  let has = 0;
  const perSeed = [];
  for (const seed of seeds) {
    const g = makeGen(seed, { biomeMask: mask });
    let km = 0;
    let n = 0;
    for (let i = 1; i < 45; i++) {
      const ch = g.getChunk(i);
      if (ch.biome !== biome) continue;
      km += (ch.endX - ch.startX) / 20000;
      const here = ch.hazards.some((q) => q.defId === id);
      if (here) n++;
      if (eligible(ch)) { elig++; if (here) has++; }
    }
    perSeed.push({ seed, n, km: +km.toFixed(2), ok: km < SHORT_KM || n * 2 >= km });
  }
  const share = has / elig;
  console.log(`${id} (${seeds.length} seeds): ${has}/${elig} eligible = ${(100 * share).toFixed(1)} %; per seed ${perSeed.map((p) => `${p.n}/${p.km}km`).join(' ')}`);
  return { elig, share, perSeed, fails: perSeed.filter((p) => !p.ok).length };
}

describe('B4 presence: the biome hazard is felt in early terrain (chunks 0-44, single biome bit)', () => {
  // Both B4 hazards are air hazards: like B1's Seagull Dive and B2's Ash Cloud they sit only in a generated jump of their
  // biome, above the no-hop arc, with the chance at the 0.75 cap. The band holds; the 1-per-2-km rule fails on seeds
  // with few generated jumps in their biome sectors (OPEN for the lead, as for seagullDive / ashCloud).
  test.each([
    [32, 'space-mountain', 'meteor', 2, 6],
    [128, 'sky-jellyfish-mountain', 'gustFront', 2, 6],
  ])('mask %p (%s): %s meets the 35-60 %% band (150 seeds); 1-per-2-km misses (seeds with >= 1 km of biome) at most %p / 8 and %p / 32 seeds', (mask, biome, id, f8, f32) => {
    const a = presence(mask, biome, id, SEEDS);
    expect(a.elig).toBeGreaterThanOrEqual(10);
    expect(a.fails).toBeLessThanOrEqual(f8);
    const b = presence(mask, biome, id, ROB);
    expect(b.fails).toBeLessThanOrEqual(f32); // 2 of ~22 seeds with >= 1 km of biome at #65 (an air hazard needs a generated jump)
    const big = presence(mask, biome, id, BIG);
    expect(big.share).toBeGreaterThanOrEqual(0.35);
    expect(big.share).toBeLessThanOrEqual(0.6);
  });
});

describe('B4 presence: long range (16 seeds x 300 chunks), hazard floor and power-up band', () => {
  // re-pinned for #65: Debutmont base + arcade bridges. The sample grew from 4 seeds to 16 (the original four first): bridges
  // took ~25 % of the biome chunks, and 4 seeds now read meteor 29.2 % / gustFront 28.9 % (below both old floors) while 60
  // seeds read 34.1 / 33.7 % before #65 and 34.8 / 33.3 % after, i.e. the placement rate did not move. gustFront's old 0.35
  // floor came from one lucky 4-seed sample (35.6 %); its rate was 33.7 % over 60 seeds even then, so its floor is 0.3 like meteor's.
  const LONG = [...['b1-share-a', 'b1-share-b', 'b1-share-c', 'b1-share-d'], ...Array.from({ length: 12 }, (_, k) => `b4-share-${k + 1}`)];
  const ROWS = [
    // measured 33.5 % at long range (119 / 355): Space's generated jumps past 2 km often carry a base air hazard already
    // (one air box per jump), so the floor is 0.3 (B2's Vertigo row uses 0.25 for the same reason)
    [32, 'space-mountain', 'meteor', 'gravityStabilizer', 0.3, 0.25, 0.45],
    [128, 'sky-jellyfish-mountain', 'gustFront', 'stabilizerRails', 0.3, 0.25, 0.45],
  ];
  test.each(ROWS)('mask %p (%s): hazard %s, power-up %s, hazard share of eligible chunks >= %p, power-up share of biome chunks in [%p, %p]', (mask, biome, hz, pu, floor, lo, hi) => {
    let all = 0;
    let elig = 0;
    let h = 0;
    let p = 0;
    for (const seed of LONG) {
      const g = makeGen(seed, { biomeMask: mask });
      for (let i = 1; i < 300; i++) {
        const ch = g.getChunk(i);
        if (ch.biome !== biome) continue;
        all++;
        if (eligible(ch)) elig++;
        if (ch.hazards.some((q) => q.defId === hz)) h++;
        if (ch.powerups.some((q) => q.defId === pu)) p++;
      }
    }
    console.log(`${hz}: ${h}/${elig} eligible = ${(100 * h / elig).toFixed(1)} %; ${pu}: ${p}/${all} = ${(100 * p / all).toFixed(1)} %`);
    expect(elig).toBeGreaterThan(60);
    expect(h / elig).toBeGreaterThanOrEqual(floor);
    expect(p / all).toBeGreaterThanOrEqual(lo);
    expect(p / all).toBeLessThanOrEqual(hi);
  });
});

describe('B4 low-gravity fairness: a Meteor stays above every no-hop arc under the zone gravity', () => {
  const MODS = c.terrainMods;
  test('flightGravityMul: product of the gravityMul < 1 of the zones over the flight span; 1 with none (and gravityMul > 1 never lowers the box)', () => {
    const map = { lowGravity: MODS.lowGravity, compression: MODS.compression, bouncySpring: MODS.bouncySpring };
    expect(MODS.lowGravity.physics.gravityMul).toBe(0.7);
    expect(flightGravityMul([], map, 0, 500)).toBe(1);
    expect(flightGravityMul([{ modId: 'lowGravity', x0: 100, x1: 300 }], map, 0, 500)).toBeCloseTo(0.7, 12);
    expect(flightGravityMul([{ modId: 'lowGravity', x0: 600, x1: 900 }], map, 0, 500)).toBe(1); // outside the span
    expect(flightGravityMul([{ modId: 'lowGravity', x0: -300, x1: 10 }], map, 0, 500)).toBeCloseTo(0.7, 12); // overlaps the lip
    expect(flightGravityMul([{ modId: 'bouncySpring', x0: 0, x1: 500 }], map, 0, 500)).toBe(1); // no gravityMul
    expect(flightGravityMul([{ modId: 'compression', x0: 0, x1: 500 }], map, 0, 500)).toBe(1); // heavier: arcs only drop more
    expect(flightGravityMul([{ modId: 'lowGravity', x0: 0, x1: 200 }, { modId: 'lowGravity', x0: 250, x1: 500 }], map, 0, 500)).toBeCloseTo(0.49, 12);
    expect(flightGravityMul([{ modId: 'nope', x0: 0, x1: 500 }], map, 0, 500)).toBe(1);
  });

  test('every Meteor whose flight crosses a lowGravity zone is placed higher than it would be at normal gravity; the others are unchanged', () => {
    // control: the same content with lowGravity's gravity at 1 (the arc model's own g), so only the fairness lift differs
    const flat = { ...MODS, lowGravity: { ...MODS.lowGravity, physics: { ...MODS.lowGravity.physics, gravityMul: 1 } } };
    let lifted = 0;
    let same = 0;
    for (let s = 1; s <= 12; s++) {
      const a = makeGen(`rob${s}`, { biomeMask: 32 });
      const b = makeGen(`rob${s}`, { biomeMask: 32, modDefs: flat });
      for (let i = 1; i < 150; i++) {
        const ca = a.getChunk(i);
        const cb = b.getChunk(i);
        const ma = ca.hazards.filter((h) => h.defId === 'meteor');
        const mb = cb.hazards.filter((h) => h.defId === 'meteor');
        expect(ma.map((h) => h.x)).toEqual(mb.map((h) => h.x)); // same slots and x: only the height may move
        for (let k = 0; k < ma.length; k++) {
          let lip = null;
          for (const l of ca.launches) if (l.x < ma[k].x && (!lip || l.x > lip.x)) lip = l;
          const low = ca.zones.some((z) => z.modId === 'lowGravity' && z.x0 <= lip.landX && z.x1 >= lip.x);
          if (low) { expect(ma[k].y).toBeLessThan(mb[k].y - 10); lifted++; } else { expect(ma[k].y).toBe(mb[k].y); same++; }
        }
      }
    }
    console.log(`meteors lifted by the low-gravity rule: ${lifted}, unchanged: ${same}`);
    expect(lifted).toBeGreaterThan(10);
    expect(same).toBeGreaterThan(10);
  });
});

describe('B4 invariant: same seed + mask gives identical terrain twice (shipped content)', () => {
  test.each([32, 128])('mask %p: two generators, forward and reverse call order, deep-equal over 150 chunks', (mask) => {
    const snap = (ch) => JSON.parse(JSON.stringify(ch));
    const a = makeGen('b4-det', { biomeMask: mask });
    const b = makeGen('b4-det', { biomeMask: mask });
    const rev = [];
    for (let i = 149; i >= 0; i--) rev[i] = snap(b.getChunk(i));
    let biomeSpawns = 0;
    for (let i = 0; i < 150; i++) {
      const ch = snap(a.getChunk(i));
      expect(ch).toEqual(rev[i]);
      biomeSpawns += [...ch.hazards, ...ch.powerups].filter((s) => (c.hazards[s.defId] || c.powerups[s.defId]).biome).length;
    }
    expect(biomeSpawns).toBeGreaterThan(0);
  });
});/**
 * Audit T1 — the six W6 backdrops are drawn, distinct, bounded, deterministic and hazard-safe.
 *
 * The W6 biome files named six backgrounds (stars, candy-stripes, jellyfish, brass-pipes, dew-drops,
 * vents) that did not exist, so six biomes drew base ridges. biome-background.test.js now proves every
 * named id is a real motif; this file proves each one actually LOOKS like something:
 *   - its silhouette profile differs from the base ridge profile;
 *   - its decor pass (motifDecor) emits primitives, repeatably for one seed, differently for another;
 *   - everything stays on screen (480x270 plus a small margin);
 *   - nothing is drawn in the `danger` colour (hazards must stay the only thing that reads as a hazard),
 *     checked both on the pure geometry and on the real renderer's draw calls;
 *   - the draw cost per frame stays within a small multiple of the base backdrop.
 */
import { motifGeometry, motifDecor, motifProfile, MOTIFS, Background } from '../../src/entities/Background.js';
import { GAME_WIDTH, GAME_HEIGHT, PALETTE_KEYS } from '../../src/constants.js';
import { readDir } from './_helpers.js';

const BATCH1 = ['ridges', 'drift', 'terraces', 'currents', 'facets'];
const W6 = [...new Set(readDir('biomes').map((b) => b.background))].filter((id) => !BATCH1.includes(id)).sort();
const SCROLLS = [0, 137, 480, 1001, 2500, 7777, 40_000, 123_456, 12_345_678];
const TIMES = [0, 250, 1600, 9999];
const XM = 96; // decor anchored just off screen may overhang this far (gear teeth, cane hooks, ring)

/** Every point a primitive touches, for the bounds check. */
function pointsOf(d) {
  if (d.kind === 'circle') return [{ x: d.x, y: d.y }];
  if (d.kind === 'rect') return [{ x: d.x, y: d.y }, { x: d.x + d.w, y: d.y + d.h }];
  return d.pts;
}

/** A Graphics stand-in that records every call and the colour it was made with. */
function recordingScene() {
  const calls = [];
  const gfx = new Proxy({}, {
    get(_, name) {
      if (name === 'setScrollFactor' || name === 'setDepth') return () => gfx;
      return (...args) => { calls.push([name, ...args]); return gfx; };
    },
  });
  return { scene: { add: { graphics: () => gfx } }, calls };
}

// A palette where every key is a distinct value, `danger` a sentinel no other key shares.
const DANGER = 0xdead01;
const PAL = { bg: 0x010101, bgAlt: 0x020202, cyan: 0x030303, magenta: 0x040404, lime: 0x050505, amber: 0x060606, text: 0x070707, danger: DANGER };

function drawLog(motif, scrollX, timeMs) {
  const { scene, calls } = recordingScene();
  const bg = new Background(scene, PAL);
  bg.setMotif(motif);
  bg.update(scrollX, timeMs, 0);
  return calls;
}

describe('audit T1: the W6 backdrops', () => {
  test('the biome files name exactly six backdrops beyond the batch-1 five', () => {
    expect(W6).toEqual(['brass-pipes', 'candy-stripes', 'dew-drops', 'jellyfish', 'stars', 'vents']);
    for (const id of W6) expect(MOTIFS).toContain(id);
  });

  test.each(W6)('%s: its silhouette shape is its own, not the base ridge profile', (id) => {
    const g = motifGeometry(id, 0);
    expect(g.motif).toBe(id);
    expect(g.layers.length).toBeGreaterThanOrEqual(2);
    // Sample the profile across a screen and a half: a shape that fell through to 'peak' would match it.
    const L = g.layers[0];
    let diff = 0;
    for (let x = 0; x < 720; x += 8) diff += Math.abs(motifProfile(g.shape, x, L.seed) - motifProfile('peak', x, L.seed));
    expect(diff).toBeGreaterThan(5);
    for (let x = -500; x < 5000; x += 13) {
      const h = motifProfile(g.shape, x, L.seed);
      expect(Number.isFinite(h) && h >= 0 && h <= 1).toBe(true);
    }
  });

  test('the six silhouettes are six different shapes', () => {
    const shapes = W6.map((id) => motifGeometry(id, 0).shape);
    expect(new Set(shapes).size).toBe(6);
    expect(shapes).not.toContain('peak');
  });

  test.each(W6)('%s: the decor pass draws something on every screen', (id) => {
    for (const x of SCROLLS) {
      const d = motifDecor(id, x, 1000);
      expect({ id, x, n: d.length >= 4 }).toEqual({ id, x, n: true });
    }
  });

  test.each(W6)('%s: decor is deterministic per seed and differs between seeds', (id) => {
    for (const x of [0, 2500, 123_456]) {
      expect(motifDecor(id, x, 700, 0)).toEqual(motifDecor(id, x, 700, 0));
      expect(motifDecor(id, x, 700, 9)).toEqual(motifDecor(id, x, 700, 9));
    }
    // A different seed lays the items out differently on at least one screen.
    const differs = SCROLLS.some((x) => JSON.stringify(motifDecor(id, x, 700, 0)) !== JSON.stringify(motifDecor(id, x, 700, 9)));
    expect(differs).toBe(true);
  });

  test.each(W6)('%s: it animates from scene time, and only from scene time', (id) => {
    // Same time => same frame (no Math.random / Date.now); different time => something moved.
    const moved = SCROLLS.some((x) => JSON.stringify(motifDecor(id, x, 0)) !== JSON.stringify(motifDecor(id, x, 1234)));
    expect(moved).toBe(true);
    const a = motifDecor(id, 5000, 4321);
    const b = motifDecor(id, 5000, 4321);
    expect(a).toEqual(b);
  });

  test.each(W6)('%s: every decor primitive stays on screen', (id) => {
    for (const x of SCROLLS) {
      for (const t of TIMES) {
        for (const d of motifDecor(id, x, t)) {
          for (const p of pointsOf(d)) {
            const ok = Number.isFinite(p.x) && Number.isFinite(p.y) && p.x >= -XM && p.x <= GAME_WIDTH + XM && p.y >= 0 && p.y <= GAME_HEIGHT;
            if (!ok) throw new Error(`${id} @scroll ${x} t ${t}: ${d.kind} point (${p.x}, ${p.y}) off screen`);
          }
          if (d.kind === 'circle') expect(d.r > 0 && d.r < 40).toBe(true);
        }
      }
    }
  });

  test.each(W6)('%s: the silhouette stays inside the frame', (id) => {
    for (const x of SCROLLS) {
      const g = motifGeometry(id, x);
      for (const L of g.layers) {
        for (let sx = 0; sx <= GAME_WIDTH; sx += 8) {
          const y = GAME_HEIGHT * L.baseY - Math.abs(motifProfile(g.shape, sx + x * L.factor, L.seed)) * L.amp;
          expect(y > 0 && y < GAME_HEIGHT).toBe(true);
        }
      }
    }
  });

  test.each(W6)('%s: only palette keys, never the danger colour', (id) => {
    const keys = new Set(motifGeometry(id, 0).layers.map((l) => l.color));
    for (const x of SCROLLS) for (const t of TIMES) for (const d of motifDecor(id, x, t)) keys.add(d.color);
    for (const k of keys) expect(PALETTE_KEYS).toContain(k);
    expect(keys.has('danger')).toBe(false);
  });

  test('batch-1 motifs and the base backdrop have no decor (their draws are unchanged)', () => {
    for (const id of [...BATCH1, null, undefined, 'nope']) expect(motifDecor(id, 500, 500)).toEqual([]);
  });
});

describe('audit T1: the renderer draws the W6 backdrops', () => {
  const baseCalls = drawLog(null, 2500, 1000);

  test('the base backdrop draws the same calls as ridges and uses no decor primitives', () => {
    expect(drawLog('ridges', 2500, 1000)).toEqual(baseCalls);
    expect(baseCalls.some((c) => c[0] === 'fillCircle')).toBe(false);
  });

  test.each(W6)('%s: the frame differs from the base frame and includes its decor', (id) => {
    for (const x of [0, 2500, 123_456]) {
      const calls = drawLog(id, x, 1000);
      expect(calls).not.toEqual(drawLog(null, x, 1000));
      // Each decor primitive costs at least one draw call beyond the two silhouette layers.
      const geomOnly = drawLog(null, x, 1000).length;
      expect(calls.length).toBeGreaterThan(geomOnly + motifDecor(id, x, 1000).length);
    }
  });

  test.each([...MOTIFS, null])('%s: no draw call uses the danger colour', (id) => {
    for (const x of [0, 777, 2500, 123_456]) {
      for (const t of TIMES) {
        for (const c of drawLog(id, x, t)) {
          if (c[0] === 'fillStyle') expect(c[1]).not.toBe(DANGER);
          if (c[0] === 'lineStyle') expect(c[2]).not.toBe(DANGER);
        }
      }
    }
  });

  test.each(W6)('%s: draw cost stays within 2.5x the base backdrop on every screen', (id) => {
    // The backdrop is redrawn every frame (no cache), so the guard is calls per frame. Sweep a long
    // stretch of run, not a handful of positions: item density varies along the tile.
    const xs = [...SCROLLS];
    for (let x = 0; x < 60_000; x += 997) xs.push(x);
    let worst = 0;
    let most = 0;
    for (const x of xs) {
      for (const t of [0, 1600]) {
        worst = Math.max(worst, drawLog(id, x, t).length / drawLog(null, x, t).length);
        most = Math.max(most, motifDecor(id, x, t).length);
      }
    }
    expect(worst).toBeLessThanOrEqual(2.5);
    expect(most).toBeLessThanOrEqual(80);
  });
});/**
 * W3 — the biome `background` motif reaches the renderer.
 *
 * CC Friday's finding: `background` (`ridges`/`drift`/`terraces`/`currents`/`facets`) is declared in
 * every biome file and read by nothing, so a biome looked identical to base terrain apart from colour.
 * That is half the "skin" half of W3's deliverable.
 *
 * The failures worth guarding, in order of how easy they are to ship:
 *   1. An unknown/missing motif must fall back to the base backdrop, never draw nothing. A blank sky is
 *      worse than a plain one, and the base path already works.
 *   2. The motif must be RESTORED on exit. A tint or silhouette that outlives its sector means the
 *      player is looking at terrain they are not on — CC Friday asked for revert explicitly.
 *   3. Each motif must actually change the geometry it draws. Five motifs that all render the base
 *      ridge are five no-ops with five names, which is precisely the bug this file exists for.
 *
 * Geometry is asserted through `motifGeometry`, a pure function, rather than by pixel-diffing, because
 * the point is that the *shape* differs per motif — a screenshot would only prove something was drawn.
 */
import { motifGeometry, MOTIFS, Background } from '../../src/entities/Background.js';
import { readDir } from './_helpers.js';

/** A scene stub with just what the Background constructor touches. */
function fakeScene() {
  const gfx = { setScrollFactor() { return gfx; }, setDepth() { return gfx; }, destroy() {} };
  return { add: { graphics: () => gfx } };
}

describe('audit T1: every backdrop a biome file names is a real motif', () => {
  // Read the biome files, not a list: the W6 batch named six motifs that did not exist, and the old
  // hardcoded test below only knew the batch-1 five, so it stayed green while six biomes fell back.
  const biomes = readDir('biomes');
  const named = [...new Set(biomes.map((b) => b.background))];

  test('the biome files name backgrounds at all (the loader found them)', () => {
    expect(biomes.length).toBeGreaterThanOrEqual(11);
    expect(named.every((id) => typeof id === 'string' && id.length > 0)).toBe(true);
  });

  test.each(biomes.map((b) => [b.id, b.background]))('%s: background "%s" is a motif with its own geometry', (biome, id) => {
    // `motif === id` matters: the fallback returns 'ridges' with two layers, so "has layers" alone
    // would pass for a motif that does not exist.
    const g = motifGeometry(id, 777);
    expect({ biome, id, known: MOTIFS.includes(id), motif: g.motif }).toEqual({ biome, id, known: true, motif: id });
    expect(g.layers.length).toBeGreaterThan(0);
  });

  test.each(biomes.map((b) => [b.id, b.background]))('%s: setMotif("%s") leaves a non-null motif on the Background', (biome, id) => {
    const bg = new Background(fakeScene(), {});
    bg.setMotif(id);
    expect({ biome, motif: bg.motif }).toEqual({ biome, motif: id });
    bg.setMotif(null);
    expect(bg.motif).toBeNull();
  });
});

describe('background motifs exist and are distinct', () => {
  test('every motif the biome files name is a real motif', () => {
    for (const id of ['ridges', 'drift', 'terraces', 'currents', 'facets']) {
      expect({ id, known: MOTIFS.includes(id) }).toMatchObject({ id, known: true });
    }
  });

  test('each motif produces a different silhouette from the others', () => {
    // Compare the sampled layer profile of every pair. Any two identical motifs would mean one of the
    // five biomes still looks like another.
    const sig = (m) => JSON.stringify(motifGeometry(m, 1234));
    const seen = new Map();
    for (const m of MOTIFS) seen.set(sig(m), [...(seen.get(sig(m)) || []), m]);
    const dupes = [...seen.values()].filter((g) => g.length > 1);
    expect(dupes).toEqual([]);
  });

  test('an unknown motif falls back to the base backdrop instead of drawing nothing', () => {
    // A typo in a JSON file, or a W6 biome naming a motif that has not shipped.
    for (const bad of ['nope', '', null, undefined, 42, 'RIDGES']) {
      const g = motifGeometry(bad, 500);
      expect({ bad, layers: Array.isArray(g.layers) && g.layers.length }).toMatchObject({ bad, layers: 2 });
    }
  });

  test('base terrain (no biome) draws exactly the pre-W3 backdrop', () => {
    // The golden rule of this campaign: mask 0 must be untouched. The base motif is the original two
    // ridges, so anything else here would be a visual regression on every existing run.
    expect(motifGeometry(null, 500)).toEqual(motifGeometry('ridges', 500));
    expect(motifGeometry('ridges', 500).layers.length).toBe(2);
  });

  test('the geometry is a pure function of (motif, scrollX)', () => {
    // Pure so a repaint at any scroll position is stable and repeatable — the same reason the original
    // backdrop made every layer position a function of scrollX.
    expect(motifGeometry('drift', 900)).toEqual(motifGeometry('drift', 900));
    expect(motifGeometry('drift', 900)).not.toEqual(motifGeometry('drift', 901));
  });

  test('motif geometry is finite at extreme scroll positions', () => {
    // Far into a long run the scroll offset is large; a NaN here would draw nothing at all.
    for (const m of MOTIFS) {
      for (const x of [0, 1, 99999, 12_345_678]) {
        const g = motifGeometry(m, x);
        const ok = g.layers.every((l) => Number.isFinite(l.baseY) && Number.isFinite(l.amp) && Number.isFinite(l.factor));
        expect({ m, x, ok }).toMatchObject({ m, x, ok: true });
      }
    }
  });
});/**
 * #65 terrain: Debutmont is the base biome and arcade is the bridge at every biome change.
 *
 * The pure pieces (biomeForSector, arcadeBridgeLengthM, biomeAtPosition) are tested against the shipped content, and the
 * real generator is checked against them chunk by chunk so terrain and every consumer agree on one answer.
 */
import {
  TerrainGenerator, biomeForSector, biomeAtPosition, arcadeBridgeLengthM, sectorHasBridge, BASE_BIOME_ID, SECTOR_M, BASE_SECTORS,
  BIOME_BASE_WEIGHT, ARCADE_BRIDGE_MIN_FRAC, ARCADE_BRIDGE_MAX_FRAC, ARCADE_BRIDGE_RAMP_M, ARCADE_BRIDGE_CAP_MUL,
  arcadeBridgeCapM,
} from '../../src/systems/TerrainGenerator.js';
import { Rng, xxHash32 } from '../../src/systems/Rng.js';
import { GHOST_PHYSICS_VERSION } from '../../src/systems/ghost/GhostTape.js';
import { SIM_REVISION, LAST_RELEASED_SIM_REVISION } from '../../src/systems/replay/ruleset.js';
import { makeGen, readDir } from './_helpers.js';
import { layout } from '../../tools/sim/biome-layout.mjs';

const DEFS = readDir('biomes');
const ALL = DEFS.reduce((m, d) => m | d.bit, 0);
const HOME_BIT = DEFS.find((d) => d.id === BASE_BIOME_ID).bit;
const SEEDS = ['alpha', 'bitstream-bluffs', '42', 'seed@mask0', '2026-11-13'];
const MASKS = [0, 2, 6, ALL];
const PPM = 20;

/** The pre-#65 draw, kept verbatim: null meant arcade. The new pick must equal it except null -> home. */
function oldBiomeForSector(seed, sector, biomeMask, biomeDefs) {
  if (!(sector >= BASE_SECTORS)) return null;
  const mask = biomeMask >>> 0;
  if (!mask) return null;
  const eligible = biomeDefs.filter((d) => d && d.bit && (mask & d.bit) !== 0);
  if (!eligible.length) return null;
  const rng = new Rng(xxHash32(`biome:${sector}`, new Rng(seed).baseSeed));
  const pick = rng.weighted(eligible.concat([{ id: null, weight: BIOME_BASE_WEIGHT }]), (d) => d.weight || 1);
  return pick && pick.id ? pick.id : null;
}

describe('home biome is the base', () => {
  test('BASE_BIOME_ID is a shipped biome', () => {
    expect(DEFS.map((d) => d.id)).toContain(BASE_BIOME_ID);
  });

  test('sectors 0 and 1 are home at any mask', () => {
    for (const seed of SEEDS) for (const mask of [0, ...MASKS, 1, 16, ALL]) {
      expect(biomeForSector(seed, 0, mask, DEFS)).toBe(BASE_BIOME_ID);
      expect(biomeForSector(seed, 1, mask, DEFS)).toBe(BASE_BIOME_ID);
    }
  });

  test('mask 0 is home in every sector, and never has a bridge', () => {
    for (const seed of SEEDS) for (let s = 0; s < 300; s++) {
      expect(biomeForSector(seed, s, 0, DEFS)).toBe(BASE_BIOME_ID);
      expect(sectorHasBridge(seed, s, 0, DEFS)).toBe(false);
    }
  });

  test('no defs, or defs without the mask bits: home (never null)', () => {
    expect(biomeForSector('alpha', 7, ALL, [])).toBe(BASE_BIOME_ID);
    expect(biomeForSector('alpha', 7, ALL, undefined)).toBe(BASE_BIOME_ID);
    expect(biomeForSector('alpha', 7, 1 << 20, DEFS)).toBe(BASE_BIOME_ID);
  });

  test('the home bit in the mask is a no-op: never double-weighted', () => {
    for (const seed of SEEDS) for (const mask of [0, 2, 6, 18, ALL & ~HOME_BIT]) for (let s = 0; s < 400; s++) {
      expect(biomeForSector(seed, s, mask | HOME_BIT, DEFS)).toBe(biomeForSector(seed, s, mask & ~HOME_BIT, DEFS));
    }
  });

  test('same stream, same draws: every non-home pick equals the old pick, and old null is now home', () => {
    for (const seed of SEEDS) for (const mask of [0, 2, 6, 18, ALL & ~HOME_BIT]) for (let s = 0; s < 400; s++) {
      const old = oldBiomeForSector(seed, s, mask, DEFS);
      expect(biomeForSector(seed, s, mask, DEFS)).toBe(old === null ? BASE_BIOME_ID : old);
    }
  });

  test('never returns a biome whose bit is not in the mask (home excepted)', () => {
    for (const d of DEFS) for (let s = 0; s < 400; s++) {
      expect([d.id, BASE_BIOME_ID]).toContain(biomeForSector('locked', s, d.bit, DEFS));
    }
  });
});

describe('bridge length curve', () => {
  test('constants: 1/6 of a sector at the start, 1/4 from 5000 m', () => {
    expect(ARCADE_BRIDGE_MIN_FRAC).toBeCloseTo(1 / 6, 12);
    expect(ARCADE_BRIDGE_MAX_FRAC).toBeCloseTo(1 / 4, 12);
    expect(ARCADE_BRIDGE_RAMP_M).toBe(5000);
  });

  test('linear in the start distance, capped', () => {
    expect(arcadeBridgeLengthM(0)).toBeCloseTo(SECTOR_M / 6, 9);
    expect(arcadeBridgeLengthM(ARCADE_BRIDGE_RAMP_M)).toBeCloseTo(SECTOR_M / 4, 9);
    expect(arcadeBridgeLengthM(ARCADE_BRIDGE_RAMP_M / 2)).toBeCloseTo((SECTOR_M / 6 + SECTOR_M / 4) / 2, 9);
    expect(arcadeBridgeLengthM(20000)).toBeCloseTo(125, 9);
    expect(arcadeBridgeLengthM(-5)).toBeCloseTo(SECTOR_M / 6, 9);
    let prev = 0;
    for (let m = 0; m <= 8000; m += 250) {
      const len = arcadeBridgeLengthM(m);
      expect(len).toBeGreaterThanOrEqual(prev);
      expect(len).toBeLessThanOrEqual(125 + 1e-9);
      prev = len;
    }
  });

  test('the cap is 1.5 x the target length: about 125 m at the start, 187.5 m from 5000 m', () => {
    expect(ARCADE_BRIDGE_CAP_MUL).toBe(1.5);
    expect(arcadeBridgeCapM(0)).toBeCloseTo(125, 9);
    expect(arcadeBridgeCapM(ARCADE_BRIDGE_RAMP_M)).toBeCloseTo(187.5, 9);
    expect(arcadeBridgeCapM(30000)).toBeCloseTo(187.5, 9);
  });

  test('biomeAtPosition at chunk level: the first chunk is always arcade; a later chunk only while it ends under the cap', () => {
    let checked = 0;
    for (const seed of SEEDS) for (let s = 1; s < 80; s++) {
      if (!sectorHasBridge(seed, s, ALL, DEFS)) continue;
      const start = s * SECTOR_M;
      const biome = biomeForSector(seed, s, ALL, DEFS);
      const run = start + 30; // a bridge whose first chunk started 30 m into the sector
      const cap = arcadeBridgeCapM(start);
      expect(biomeAtPosition(seed, run, ALL, DEFS, true)).toBeNull();
      expect(biomeAtPosition(seed, run, ALL, DEFS, { first: true, endM: run + 1e6 })).toBeNull(); // however long the first chunk is
      expect(biomeAtPosition(seed, start + 10, ALL, DEFS, { runStartM: run, endM: run + cap })).toBeNull();
      expect(biomeAtPosition(seed, start + 10, ALL, DEFS, { runStartM: run, endM: run + cap + 0.01 })).toBe(biome);
      // past the window the biome takes it, whatever its end
      expect(biomeAtPosition(seed, start + arcadeBridgeLengthM(start) + 0.01, ALL, DEFS, { runStartM: run, endM: run + 1 })).toBe(biome);
      checked++;
    }
    expect(checked).toBeGreaterThan(30);
  });

  test('biomeAtX: bridge is the first `length` metres of a changing sector, exactly', () => {
    let checked = 0;
    for (const seed of SEEDS) for (let s = 1; s < 80; s++) {
      if (!sectorHasBridge(seed, s, ALL, DEFS)) continue;
      const start = s * SECTOR_M;
      const len = arcadeBridgeLengthM(start);
      const biome = biomeForSector(seed, s, ALL, DEFS);
      expect(biomeAtPosition(seed, start, ALL, DEFS)).toBeNull();
      expect(biomeAtPosition(seed, start + len - 0.01, ALL, DEFS)).toBeNull();
      expect(biomeAtPosition(seed, start + len + 0.01, ALL, DEFS)).toBe(biome);
      expect(biomeAtPosition(seed, start + SECTOR_M - 0.01, ALL, DEFS)).toBe(biome);
      // the sector before the boundary is the previous biome, with no bridge at its end
      expect(biomeAtPosition(seed, start - 0.01, ALL, DEFS)).toBe(biomeForSector(seed, s - 1, ALL, DEFS));
      checked++;
    }
    expect(checked).toBeGreaterThan(30);
  });

  test('no bridge between consecutive sectors of the same biome, and none at the run start', () => {
    for (const seed of SEEDS) {
      expect(biomeAtPosition(seed, 0, ALL, DEFS)).toBe(BASE_BIOME_ID);
      for (let s = 1; s < 120; s++) {
        const same = biomeForSector(seed, s, ALL, DEFS) === biomeForSector(seed, s - 1, ALL, DEFS);
        expect(sectorHasBridge(seed, s, ALL, DEFS)).toBe(!same);
        if (same) {
          const b = biomeForSector(seed, s, ALL, DEFS);
          for (const dx of [0, 1, 40, 100, 200, 499]) expect(biomeAtPosition(seed, s * SECTOR_M + dx, ALL, DEFS)).toBe(b);
        }
      }
    }
  });
});

/** Chunk starts (metres) with the sector's first chunk flagged, for a generator. */
function walk(gen, uptoM) {
  const out = [];
  for (let i = 0; ; i++) {
    const c = gen.getChunk(i);
    if (c.startX / PPM >= uptoM) break;
    out.push({ i, c, startM: c.startX / PPM, endM: c.endX / PPM, biome: c.biome === undefined ? null : c.biome });
  }
  return out;
}

describe('the real generator follows the model, chunk-aligned', () => {
  const UPTO = 9000;

  test.each(SEEDS)('seed %s at the full mask: every chunk is the model biome; arcade only at changes', (seed) => {
    const gen = makeGen(seed, { biomeMask: ALL });
    const chunks = walk(gen, UPTO);
    const bridgeSectors = new Set();
    const arcadeSectors = new Set();
    for (let k = 0; k < chunks.length; k++) {
      const { c, startM, biome } = chunks[k];
      const sector = Math.floor(startM / SECTOR_M);
      const first = k > 0 && sector > Math.floor(chunks[k - 1].startM / SECTOR_M);
      let j = k;
      while (j > 0 && Math.floor(chunks[j - 1].startM / SECTOR_M) === sector) j--;
      // A chunk the cap refuses is built as the sector's biome, so its real end is not the end the cap judged: the
      // generator's arcade replay is (and for a chunk that does come out arcade it is the real end).
      const arcadeEndM = gen._arcadeEndPx(gen.bounds[chunks[k].i], chunks[k].i) / PPM;
      if (biome === null) expect(arcadeEndM).toBeCloseTo(chunks[k].endM, 6);
      expect(biome).toBe(biomeAtPosition(seed, startM, ALL, DEFS, { first, runStartM: chunks[j].startM, endM: arcadeEndM }));
      expect(gen.biomeAtX(c.startX)).toBe(biome);
      expect(gen.biomeAtX(c.endX - 1)).toBe(biome);
      if (biome === null) arcadeSectors.add(sector);
      if (sectorHasBridge(seed, sector, ALL, DEFS)) bridgeSectors.add(sector);
    }
    // bridges exist exactly at the biome changes, nowhere else
    const lastSector = Math.floor(chunks[chunks.length - 1].startM / SECTOR_M);
    const expected = new Set([...bridgeSectors].filter((s) => s <= lastSector));
    expect(arcadeSectors).toEqual(expected);
    expect(expected.size).toBeGreaterThan(3);
  });

  test('every bridge is whole chunks: first chunk of the sector, then chunks starting inside the window that fit the cap', () => {
    for (const seed of SEEDS) {
      const gen = makeGen(seed, { biomeMask: ALL });
      const chunks = walk(gen, UPTO);
      for (let s = 1; s < 18; s++) {
        if (!sectorHasBridge(seed, s, ALL, DEFS)) continue;
        const start = s * SECTOR_M;
        const win = start + arcadeBridgeLengthM(start);
        const inSector = chunks.filter((q) => Math.floor(q.startM / SECTOR_M) === s);
        const arcade = inSector.filter((q) => q.biome === null);
        expect(arcade.length).toBeGreaterThanOrEqual(1); // minimum one chunk, however long the chunk over the boundary was
        expect(inSector[0].biome).toBeNull(); // the breather opens the bridge
        // the arcade chunks are contiguous from the sector's first chunk
        expect(arcade.map((q) => q.i)).toEqual(inSector.slice(0, arcade.length).map((q) => q.i));
        for (const q of arcade.slice(1)) expect(q.startM).toBeLessThan(win);
        // the whole bridge stays under the cap, measured from its own first chunk
        const last = arcade[arcade.length - 1];
        expect(last.endM - arcade[0].startM).toBeLessThanOrEqual(arcadeBridgeCapM(start) + 1e-9);
        // the chunk after the bridge belongs to the sector's biome
        expect(inSector[arcade.length].biome).toBe(biomeForSector(seed, s, ALL, DEFS));
      }
    }
  });

  test('bridge length distribution: a few thousand bridges, none over the cap, median near the target', () => {
    const lens = [];
    let worstOverCap = -Infinity;
    for (let n = 0; n < 60; n++) {
      for (const r of layout(`dist-${n}`, ALL, 12000)) {
        if (r.biome !== 'ARCADE') continue;
        lens.push(r.endM - r.startM);
        worstOverCap = Math.max(worstOverCap, r.endM - r.startM - arcadeBridgeCapM(r.sector * SECTOR_M));
      }
    }
    lens.sort((a, b) => a - b);
    expect(lens.length).toBeGreaterThan(1000);
    expect(worstOverCap).toBeLessThanOrEqual(1e-9);
    expect(Math.max(...lens)).toBeLessThanOrEqual(ARCADE_BRIDGE_CAP_MUL * SECTOR_M * ARCADE_BRIDGE_MAX_FRAC + 1e-9);
    const median = lens[Math.floor(lens.length / 2)];
    expect(median).toBeGreaterThan(75);
    expect(median).toBeLessThan(125);
  });

  test('bridge terrain is exactly today\'s arcade (null-biome) terrain generation', () => {
    // A bridge chunk carries no biome field, and equals the chunk a generator with no biome content builds there
    // only when the stream up to it matches; the cheap, exact claim is that it has none of the biome machinery.
    const seed = 'alpha';
    const gen = makeGen(seed, { biomeMask: ALL });
    const arcade = walk(gen, 4000).filter((q) => q.biome === null && q.i > 0);
    expect(arcade.length).toBeGreaterThan(3);
    for (const { c } of arcade) {
      expect('biome' in c).toBe(false);
      expect(c.hazards.every((h) => !DEFS.some((d) => d.id && h.biome === d.id))).toBe(true);
    }
  });

  test('mask 0 is pure Debutmont: no arcade chunk anywhere past the opening jump, every chunk tagged home', () => {
    for (const seed of SEEDS) {
      for (const q of walk(makeGen(seed, { biomeMask: 0 }), 6000)) expect(q.biome).toBe(BASE_BIOME_ID);
    }
  });

  test('a generator without biome content has no biome chunks at all', () => {
    for (const q of walk(makeGen('alpha', { biomeMask: ALL, biomeDefs: [] }), 3000)) expect(q.biome).toBeNull();
  });

  test('streamed and random-access generation agree (determinism across call order)', () => {
    const a = makeGen('stream', { biomeMask: ALL });
    const b = makeGen('stream', { biomeMask: ALL });
    const fwd = walk(a, 5000).map((q) => [q.i, q.biome, q.startM]);
    const rev = [];
    const n = fwd.length;
    for (let i = n - 1; i >= 0; i--) {
      const c = b.getChunk(i);
      rev.unshift([i, c.biome === undefined ? null : c.biome, c.startX / PPM]);
    }
    expect(rev).toEqual(fwd);
  });
});

describe('layout is deterministic', () => {
  test('5 seeds x masks {0, 2, 6, 2047}: the same layout twice, and bridges only where the biome changes', () => {
    for (const seed of SEEDS) for (const mask of MASKS) {
      const a = layout(seed, mask, 6000);
      const b = layout(seed, mask, 6000);
      expect(b).toEqual(a);
      for (let k = 1; k < a.length; k++) {
        // consecutive runs always differ, and an arcade run is always sandwiched between two different biomes
        expect(a[k].biome).not.toBe(a[k - 1].biome);
        if (a[k].biome === 'ARCADE') {
          expect(a[k + 1]).toBeDefined();
          expect(a[k + 1].biome).not.toBe(a[k - 1].biome);
        }
      }
      if (mask === 0) expect(a.map((r) => r.biome)).toEqual([BASE_BIOME_ID]);
    }
  });
});

