});/**
 * Issue #65: the biome "Debumont" was renamed "Debutmont". The legacy id is an alias, not a second biome:
 * old saves migrate losslessly and a stale music pack / voice request resolves to the new key. A guard test
 * keeps the misspelling out of the tree everywhere except this alias layer and the historical CHANGELOG.
 */
import fs from 'fs';
import { execFileSync } from 'child_process';
import { LEGACY_BIOME_ALIASES, canonicalBiomeId, canonicalLegacyId } from '../../src/data/biomeAliases.js';
import { sanitizeProfile } from '../../src/systems/ProfileStore.js';
import { sanitizeBiomeProgress, mergeBiomeVisits, BIOME_IDS } from '../../src/systems/BiomeDiscovery.js';
import { normalizePack } from '../../src/systems/music/MusicPack.js';
import { voiceSourceForBiome } from '../../src/systems/music/BiomeVoices.js';

const LEGACY = 'debu' + 'mont'; // split so this guard does not match itself
const LEVELS = JSON.parse(fs.readFileSync('src/data/progression/levels.json', 'utf8'));

describe('legacy biome alias helpers', () => {
  test('maps the legacy id and leaves everything else alone', () => {
    expect(LEGACY_BIOME_ALIASES).toEqual({ [LEGACY]: 'debutmont' });
    expect(canonicalBiomeId(LEGACY)).toBe('debutmont');
    expect(canonicalBiomeId('debutmont')).toBe('debutmont');
    expect(canonicalBiomeId('pyramid-peak')).toBe('pyramid-peak');
    expect(canonicalBiomeId('toString')).toBe('toString');
    expect(canonicalBiomeId(undefined)).toBeUndefined();
    expect(canonicalBiomeId(7)).toBe(7);
  });
  test('rewrites ids embedded in mission ids, source keys and asset paths', () => {
    expect(canonicalLegacyId(`t4-biome-${LEGACY}`)).toBe('t4-biome-debutmont');
    expect(canonicalLegacyId(`voice:${LEGACY}`)).toBe('voice:debutmont');
    expect(canonicalLegacyId(`adaptive/${LEGACY}/bass-0000.ogg`)).toBe('adaptive/debutmont/bass-0000.ogg');
    expect(canonicalLegacyId(null)).toBeNull();
  });
  test('the shipped biome table uses only the new id', () => {
    expect(BIOME_IDS).toContain('debutmont');
    expect(BIOME_IDS).not.toContain(LEGACY);
    expect(LEVELS.biomeOrder).toContain('debutmont');
    expect(fs.existsSync('src/data/biomes/debutmont.json')).toBe(true);
    expect(fs.existsSync(`src/data/biomes/${LEGACY}.json`)).toBe(false);
  });
});

describe('an old save migrates losslessly', () => {
  test('biomeProgress and unlocked.biomes follow the rename', () => {
    const p = sanitizeProfile({
      v: 1,
      biomeProgress: { encountered: [LEGACY, 'pyramid-peak'], completed: [LEGACY] },
      unlocked: { biomes: [LEGACY, 'pyramid-peak'] },
    }, LEVELS);
    expect(p.biomeProgress).toEqual({ encountered: ['debutmont', 'pyramid-peak'], completed: ['debutmont'] });
    expect(p.unlocked.biomes).toEqual(['debutmont', 'pyramid-peak']);
  });
  test('a save holding both spellings merges to one entry', () => {
    const p = sanitizeProfile({
      v: 1,
      biomeProgress: { encountered: [LEGACY, 'debutmont'], completed: ['debutmont', LEGACY] },
      unlocked: { biomes: ['debutmont', LEGACY] },
    }, LEVELS);
    expect(p.biomeProgress).toEqual({ encountered: ['debutmont'], completed: ['debutmont'] });
    expect(p.unlocked.biomes).toEqual(['debutmont']);
  });
  test('mission ids and their progress follow the rename; the larger count wins on a collision', () => {
    // Any mission id that embeds the legacy spelling follows the rename (shipped data has none left, hence the made-up id).
    const OLD = `x-biome-${LEGACY}`;
    const p = sanitizeProfile({
      v: 1,
      missions: {
        counter: 3,
        active: [OLD, 'other-mission'],
        progress: { [OLD]: 900, 'other-mission': 2 },
      },
    }, LEVELS);
    expect(p.missions.active).toEqual(['x-biome-debutmont', 'other-mission']);
    expect(p.missions.progress).toEqual({ 'x-biome-debutmont': 900, 'other-mission': 2 });

    const both = sanitizeProfile({
      v: 1,
      missions: { progress: { [OLD]: 900, 'x-biome-debutmont': 400 } },
    }, LEVELS);
    expect(both.missions.progress).toEqual({ 'x-biome-debutmont': 900 });
    const bothRev = sanitizeProfile({
      v: 1,
      missions: { progress: { 'x-biome-debutmont': 1200, [OLD]: 900 } },
    }, LEVELS);
    expect(bothRev.missions.progress).toEqual({ 'x-biome-debutmont': 1200 });
  });
  test('the retired "1500 m in Debutmont" mission (either spelling) keeps its slot as the Maple Wax mission, with no stale progress', () => {
    for (const id of [`t4-biome-${LEGACY}`, 't4-biome-debutmont']) {
      const p = sanitizeProfile({
        v: 1,
        missions: { counter: 3, active: [id, 'other-mission'], progress: { [id]: 900, 'other-mission': 2 } },
      }, LEVELS);
      expect(p.missions.active).toEqual(['t4-pickup-maple-wax', 'other-mission']);
      expect(p.missions.progress).toEqual({ 'other-mission': 2 });
    }
    const dup = sanitizeProfile({ v: 1, missions: { active: ['t4-biome-debutmont', 't4-pickup-maple-wax'] } }, LEVELS);
    expect(dup.missions.active).toEqual(['t4-pickup-maple-wax']); // never two copies of one mission
  });
  test('a crafted __proto__ / constructor mission progress key cannot poison the result', () => {
    const raw = JSON.parse('{"v":1,"missions":{"progress":{"__proto__":{"polluted":1},"constructor":5,"x-biome-debutmont":7}}}');
    const p = sanitizeProfile(raw, LEVELS);
    expect(Object.getPrototypeOf(p.missions.progress)).toBe(Object.prototype);
    expect(p.missions.progress.polluted).toBeUndefined();
    expect(Object.keys(p.missions.progress)).toEqual(['x-biome-debutmont']);
    expect({}.polluted).toBeUndefined();
  });
  test('run visits recorded under the legacy id merge into the canonical set', () => {
    expect(sanitizeBiomeProgress({ encountered: [LEGACY], completed: [] }).encountered).toEqual(['debutmont']);
    const merged = mergeBiomeVisits({ encountered: [LEGACY], completed: [] }, { encountered: ['debutmont'], completed: ['debutmont'] });
    expect(merged).toEqual({ encountered: ['debutmont'], completed: ['debutmont'] });
  });
});

describe('music lookups accept the legacy id', () => {
  test('a stale voice request resolves to the new key', () => {
    expect(voiceSourceForBiome(LEGACY)).toBe('voice:debutmont');
    expect(voiceSourceForBiome('debutmont')).toBe('voice:debutmont');
  });
  test('a pack still written with the legacy keys and paths loads under the new ones', () => {
    const stems = (n) => ({
      vocals: 'v.ogg', drums: 'd.ogg', bass: 'b.ogg', guitar: 'g.ogg', piano: 'p.ogg', other: 'o.ogg',
      [`voice:${LEGACY}`]: `adaptive/${LEGACY}/melody-000${n}.ogg`,
    });
    const files = [0, 1].map((n) => `adaptive/${LEGACY}/bass-000${n}.ogg`);
    const p = normalizePack({
      format: 'bitstream-music-pack-v1', id: 'stale', sampleRate: 48000, frameCount: 96000,
      segments: [{ startFrame: 0, frames: 48000, sources: stems(0) }, { startFrame: 48000, frames: 48000, sources: stems(1) }],
      adaptive: { featuredStem: 'guitar', variants: { bass: { [LEGACY]: files } } },
    });
    expect(p.sourceNames).toContain('voice:debutmont');
    expect(p.sourceNames).not.toContain(`voice:${LEGACY}`);
    expect(p.segments[1].sources['voice:debutmont']).toBe('adaptive/debutmont/melody-0001.ogg');
    expect(p.adaptive.variants.bass.debutmont).toEqual(['adaptive/debutmont/bass-0000.ogg', 'adaptive/debutmont/bass-0001.ogg']);
    expect(p.adaptive.variants.bass[LEGACY]).toBeUndefined();
  });
});

describe('a pack carrying both spellings of one key is rejected', () => {
  const stems = (extra) => ({ vocals: 'v.ogg', drums: 'd.ogg', bass: 'b.ogg', guitar: 'g.ogg', piano: 'p.ogg', other: 'o.ogg', ...extra });
  const seg = (extra) => [{ startFrame: 0, frames: 48000, sources: stems(extra) }, { startFrame: 48000, frames: 48000, sources: stems(extra) }];
  const pack = (o) => ({ format: 'bitstream-music-pack-v1', id: 'dup', sampleRate: 48000, frameCount: 96000, ...o });
  const DUP = /duplicate biome key \(legacy alias\)/;
  test('source keys', () => {
    const both = { [`voice:${LEGACY}`]: 'a.ogg', 'voice:debutmont': 'b.ogg' };
    expect(() => normalizePack(pack({ segments: seg(both) }))).toThrow(DUP);
  });
  test('adaptive biome keys', () => {
    const files = ['x.ogg', 'y.ogg'];
    expect(() => normalizePack(pack({
      segments: seg({}),
      adaptive: { featuredStem: 'guitar', variants: { bass: { [LEGACY]: files, debutmont: files } } },
    }))).toThrow(DUP);
  });
  test('roomSends keys', () => {
    expect(() => normalizePack(pack({ segments: seg({ 'voice:debutmont': 'b.ogg' }), roomSends: { [`voice:${LEGACY}`]: 0.1, 'voice:debutmont': 0.2 } }))).toThrow(DUP);
  });
});

describe('guard: the misspelling stays out of the tree', () => {
  // The alias layer and its test name the legacy id on purpose; CHANGELOG.md keeps it in entries that describe
  // already-shipped releases (and in the entry that records this rename).
  const ALLOWED = new Set([
    'src/data/biomeAliases.js',
    'tests/src/biome-debutmont-alias.test.js',
    'CHANGELOG.md',
    // Frozen artifacts: the ruleset archive is content-addressed and immutable (each file hashes to its own name, and a
    // ruleset is never edited), and the illustrative ruleset fixture is pinned by the manifest examples' digests.
    'tests/fixtures/replay/v1/ruleset-illustrative.json',
  ]);
  const FROZEN_PREFIXES = ['tools/ruleset/archive/'];
  test('no tracked text file outside the allowlist contains it (case-insensitive)', () => {
    // `-t` tags each path: "S" = skip-worktree (a sparse checkout without the OGG media), "H" = normal.
    const tracked = execFileSync('git', ['ls-files', '-t', '-z'], { encoding: 'utf8', maxBuffer: 64 * 1024 * 1024 })
      .split('\0').filter(Boolean).map((e) => ({ sparse: e[0] === 'S', path: e.slice(2) }));
    const offenders = [];
    for (const { sparse, path: f } of tracked) {
      if (ALLOWED.has(f) || FROZEN_PREFIXES.some((p) => f.startsWith(p))) continue;
      // The path check comes first so a re-added adaptive/<legacy>/*.ogg fails even though its bytes are skipped.
      if (f.toLowerCase().includes(LEGACY)) { offenders.push(f + ' (path)'); continue; }
      if (f.endsWith('.ogg')) continue;
      let buf;
      try {
        buf = fs.readFileSync(f);
      } catch (err) {
        // Only a sparse (skip-worktree) path may be absent from disk; anything else unreadable is a real problem.
        if (err.code === 'ENOENT' && sparse) continue;
        throw err;
      }
      if (buf.subarray(0, 8000).includes(0)) continue; // binary
      if (buf.toString('utf8').toLowerCase().includes(LEGACY)) offenders.push(f);
    }
    expect(offenders).toEqual([]);
  });
});/**
 * Issue #65 (Track B, profile): unlocked biomes default ON, the player's explicit OFF is authoritative, and
 * Debutmont is the base biome, unlocked from run 1.
 *
 * The profile stores explicit OFF choices in `biomeOff` (a bitfield of the biome table's `bit`s). The legacy
 * opt-in `biomeMask` is ignored, so every existing profile migrates to all-unlocked-ON with no PROFILE_VERSION
 * bump (a bump would wipe every profile). The base biome has no toggle and no bit in the run-start mask.
 */
import fs from 'fs';
import { jest } from '@jest/globals';
import {
  sanitizeProfile, ProfileStore, PROFILE_KEY, enabledBiomeMask, toggleBiome, biomeToggleRows,
  unlockedBiomeIds, earnedBiomeIds, BASE_BIOME_ID,
} from '../../src/systems/ProfileStore.js';
import { defaultProfile, PROFILE_VERSION } from '../../src/systems/Progression.js';
import { parseSeedMask } from '../../src/systems/SaveStore.js';
import { readDir } from './_helpers.js';
jest.unstable_mockModule('phaser', () => ({ default: { Scene: class {}, GameObjects: new Proxy({}, { get: () => class {} }) } }));
jest.unstable_mockModule('../../src/data/index.js', () => ({ content: {}, loadContent: () => ({}) }));
const { TitleScene } = await import('../../src/scenes/TitleScene.js');
const { GameOverScene } = await import('../../src/scenes/GameOverScene.js');
const { REG } = await import('../../src/constants.js');

const LEVELS = JSON.parse(fs.readFileSync('src/data/progression/levels.json', 'utf8'));
const DEFS = readDir('biomes');
const bitOf = (id) => DEFS.find((d) => d.id === id).bit;
const xpAt = (level) => LEVELS.levels.find((l) => l.level === level).xpMin;
const at = (level, o = {}) => sanitizeProfile({ v: 1, xp: xpAt(level), ...o }, LEVELS);
const GLACIER = bitOf('garbage-dump-glacier');
const PYRAMID = bitOf('pyramid-peak');

function memStorage() {
  const m = new Map();
  return { getItem: (k) => (m.has(k) ? m.get(k) : null), setItem: (k, v) => m.set(k, String(v)), removeItem: (k) => m.delete(k) };
}

describe('Debutmont is the base biome', () => {
  test('its data says unlocked from level 1, and the level table grants it there (Garbage Dump Glacier is the first earned biome, at level 4)', () => {
    expect(DEFS.find((d) => d.id === BASE_BIOME_ID).unlockLevel).toBe(1);
    expect(LEVELS.levels.find((l) => l.level === 1).biome).toBe('debutmont');
    expect(LEVELS.levels.find((l) => l.level === 4).biome).toBe('garbage-dump-glacier');
    expect(LEVELS.levels.find((l) => l.level === 2).biome).toBeNull();
    expect(LEVELS.levels.filter((l) => l.biome).map((l) => l.biome)).toEqual(LEVELS.biomeOrder);
  });

  test('a fresh profile at L1 has Debutmont unlocked and a run mask of 0', () => {
    const p = new ProfileStore({ levels: LEVELS }).load();
    expect(p.level).toBe(1);
    expect(unlockedBiomeIds(p)).toEqual(['debutmont']);
    expect(earnedBiomeIds(p, DEFS)).toEqual(['debutmont']);
    expect(enabledBiomeMask(p, DEFS)).toBe(0);
  });

  test('it is unlocked even for a profile built without the level table', () => {
    expect(unlockedBiomeIds({})).toEqual(['debutmont']);
    expect(unlockedBiomeIds(sanitizeProfile({ v: 1, xp: 5 }, null))).toContain('debutmont');
  });

  test('it has no toggle row and toggleBiome refuses it, so it can never be turned off', () => {
    const p = at(30);
    expect(biomeToggleRows(p, DEFS).map((r) => r.id)).not.toContain('debutmont');
    expect(toggleBiome(p, 'debutmont', DEFS)).toBe(p);
  });

  test('its bit never appears in enabledBiomeMask, whatever the profile carries', () => {
    for (const lvl of [1, 4, 30]) {
      for (const biomeOff of [0, 1, 2, 0xffffffff]) {
        expect(enabledBiomeMask(at(lvl, { biomeOff }), DEFS) & bitOf('debutmont')).toBe(0);
      }
    }
    expect(enabledBiomeMask(at(30), DEFS)).toBe(DEFS.reduce((a, d) => (d.id === 'debutmont' ? a : a | d.bit), 0));
  });
});

describe('unlocked biomes default ON', () => {
  test('after leveling to L4, Garbage Dump Glacier is ON without the player touching anything', () => {
    const s = new ProfileStore({ levels: LEVELS, storage: memStorage() });
    s.load();
    expect(enabledBiomeMask(s.profile, DEFS)).toBe(0);
    s.save({ ...s.profile, xp: xpAt(4) });
    expect(s.profile.level).toBe(4);
    expect(enabledBiomeMask(s.profile, DEFS)).toBe(GLACIER);
    expect(biomeToggleRows(s.profile, DEFS).find((r) => r.id === 'garbage-dump-glacier')).toMatchObject({ unlocked: true, enabled: true });
  });

  test('a newly unlocked biome is ON at its unlock level, every level up to the cap', () => {
    let expected = 0;
    for (let lvl = 1; lvl <= 30; lvl++) {
      const entry = LEVELS.levels.find((l) => l.level === lvl);
      if (entry.biome && entry.biome !== BASE_BIOME_ID) expected |= bitOf(entry.biome);
      expect({ lvl, mask: enabledBiomeMask(at(lvl), DEFS) }).toEqual({ lvl, mask: expected });
    }
  });
});

describe('an explicit OFF is authoritative', () => {
  test('it persists across save, load and sanitize, and across a later level-up', () => {
    const storage = memStorage();
    const a = new ProfileStore({ levels: LEVELS, storage });
    a.load();
    a.save({ ...a.profile, xp: xpAt(4) });
    a.save(toggleBiome(a.profile, 'garbage-dump-glacier', DEFS));
    expect(a.profile.biomeOff).toBe(GLACIER);
    expect(enabledBiomeMask(a.profile, DEFS)).toBe(0);

    const b = new ProfileStore({ levels: LEVELS, storage });
    b.load();
    expect(b.profile.biomeOff).toBe(GLACIER);
    expect(enabledBiomeMask(b.profile, DEFS)).toBe(0);
    expect(sanitizeProfile(JSON.parse(storage.getItem(PROFILE_KEY)), LEVELS).biomeOff).toBe(GLACIER);

    // A later level-up unlocks Pyramid Peak ON by default; the glacier stays OFF.
    b.save({ ...b.profile, xp: xpAt(7) });
    expect(b.profile.level).toBe(7);
    expect(b.profile.biomeOff).toBe(GLACIER);
    expect(enabledBiomeMask(b.profile, DEFS)).toBe(PYRAMID);
  });

  test('turning a biome back ON clears only its own OFF bit', () => {
    const off = at(7, { biomeOff: GLACIER | PYRAMID });
    const back = toggleBiome(off, 'garbage-dump-glacier', DEFS);
    expect(back.biomeOff).toBe(PYRAMID);
    expect(enabledBiomeMask(back, DEFS)).toBe(GLACIER);
  });

  test('biomeOff is sanitized to a non-negative integer, never a bump of PROFILE_VERSION', () => {
    expect(PROFILE_VERSION).toBe(1);
    expect(defaultProfile().biomeOff).toBe(0);
    for (const bad of [-5, NaN, 'x', null, undefined, {}, [], Infinity]) {
      expect(at(4, { biomeOff: bad }).biomeOff).toBe(0);
    }
    expect(at(4, { biomeOff: 6.2 }).biomeOff).toBe(6);
  });
});

describe('legacy profiles migrate to all-unlocked-ON', () => {
  test('a legacy profile with biomeMask 0 at level 28 has every unlocked biome ON', () => {
    const p = sanitizeProfile({ v: 1, xp: xpAt(28), biomeMask: 0 }, LEVELS);
    expect(p.level).toBe(28);
    expect('biomeMask' in p).toBe(false); // no longer written
    const all = DEFS.reduce((a, d) => (d.id === 'debutmont' ? a : a | d.bit), 0);
    expect(enabledBiomeMask(p, DEFS)).toBe(all);
    expect(biomeToggleRows(p, DEFS).every((r) => r.unlocked && r.enabled)).toBe(true);
  });

  test('the legacy mask is ignored, even a non-zero one', () => {
    const p = at(7, { biomeMask: GLACIER });
    expect(enabledBiomeMask(p, DEFS)).toBe(GLACIER | PYRAMID);
  });
});

describe('a locked biome can never be enabled', () => {
  test('toggleBiome refuses it', () => {
    const p = at(4);
    expect(toggleBiome(p, 'pyramid-peak', DEFS)).toBe(p);
  });

  test('a crafted biomeOff cannot enable or disturb a locked biome: only unlocked bits ever reach the mask', () => {
    for (const biomeOff of [0, PYRAMID, 0xffffffff, ~GLACIER >>> 0]) {
      expect(enabledBiomeMask(at(4, { biomeOff }), DEFS) & ~GLACIER).toBe(0);
    }
  });

  test('a crafted legacy mask cannot enable a locked biome', () => {
    expect(enabledBiomeMask(at(1, { biomeMask: 0xffffffff }), DEFS)).toBe(0);
    expect(enabledBiomeMask(at(4, { biomeMask: 0xffffffff }), DEFS)).toBe(GLACIER);
  });

  test('a stale OFF bit for a not-yet-unlocked biome is inert until unlocked, then keeps it OFF (explicit OFF wins)', () => {
    // Not reachable through the UI (toggleBiome refuses locked biomes); only a hand-edited save gets here.
    expect(enabledBiomeMask(at(4, { biomeOff: PYRAMID }), DEFS)).toBe(GLACIER); // Pyramid Peak still locked
    expect(enabledBiomeMask(at(7, { biomeOff: PYRAMID }), DEFS)).toBe(GLACIER); // unlocked, but explicitly OFF
  });

  test('a profile with no level table still never enables a biome it has not earned', () => {
    expect(enabledBiomeMask({ biomeOff: 0, pendingBiomes: [] }, DEFS)).toBe(0);
    expect(enabledBiomeMask(null, DEFS)).toBe(0);
  });
});

describe('run-start mask precedence is unchanged', () => {
  const content = { biomes: Object.fromEntries(DEFS.map((d) => [d.id, d])) };
  const sceneWith = (profile, extra = {}) => {
    const values = new Map([[REG.CONTENT, content], [REG.PROFILE, profile]]);
    for (const [k, v] of Object.entries(extra)) values.set(k, v);
    return {
      values,
      ctx: {
        registry: { get: (k) => values.get(k), set: (k, v) => values.set(k, v) },
        scene: { start: jest.fn() }, _closeView() {}, leaving: false, pulse: null, _commitPending() {},
      },
    };
  };
  const startMask = (profile, ...args) => {
    const { ctx, values } = sceneWith(profile);
    TitleScene.prototype.startRun.call(ctx, ...args);
    return values.get(REG.BIOME_MASK);
  };
  const L7 = () => at(7);

  test('a normal START RUN / bare seed uses the new default (every unlocked biome ON)', () => {
    expect(startMask(L7(), 'alpha')).toBe(GLACIER | PYRAMID);
    expect(startMask(at(1), 'alpha')).toBe(0);
    expect(startMask(toggleBiome(L7(), 'pyramid-peak', DEFS), 'alpha')).toBe(GLACIER);
  });

  test('seed@mask wins, including @0 and bits the profile has not unlocked (a shared seed reproduces)', () => {
    const want = parseSeedMask('alpha@16', DEFS).biomeMask;
    expect(startMask(L7(), 'alpha@16')).toBe(want);
    expect(startMask(L7(), 'alpha@0')).toBe(0);
    expect(startMask(at(1), `alpha@${GLACIER}`)).toBe(GLACIER);
  });

  test('a Daily maskOverride wins, including an override of 0', () => {
    expect(startMask(L7(), 'alpha', 8)).toBe(8);
    expect(startMask(L7(), 'daily-2026-11-13', 0)).toBe(0);
  });

  test('the BSOD Gym start (mask override 0) stays at 0 whatever the profile has ON', () => {
    expect(startMask({ ...L7(), bsodGym: { discovered: true, owned: true } }, 'bsod-gym', 0, { gym: true })).toBe(0);
  });

  test('NEW SEED takes the new default; RETRY reuses the record mask, not the profile default', () => {
    const profile = L7();
    const ns = sceneWith(profile, { [REG.BIOME_MASK]: 8 });
    GameOverScene.prototype.newSeed.call({ ...ns.ctx, rec: { seed: 'alpha', id: 'r1', biomeMask: 8 } });
    expect(ns.values.get(REG.BIOME_MASK)).toBe(GLACIER | PYRAMID);

    for (const recMask of [0, 8, GLACIER]) {
      const rt = sceneWith(profile);
      GameOverScene.prototype.retry.call({ ...rt.ctx, rec: { seed: 'alpha', id: 'r1', biomeMask: recMask } });
      expect(rt.values.get(REG.BIOME_MASK)).toBe(recMask);
    }
  });
});/**
 * Marvin decision 3 (audit ACH-3 / ACH-6): a biome is ENCOUNTERED when the sled actually reaches one of its
 * sectors, and COMPLETED when the sled rides one of its sectors from start to end without its run-ending
 * crash inside it. Pure detection lives in src/systems/BiomeDiscovery.js; these tests pin it against the
 * real generator's `biomeForSector`, so detection and the drawn terrain can never disagree. Debutmont is the base
 * biome (#65): encountered from sector 0 at any mask; arcade bridges are never recorded.
 */
import fs from 'fs';
import path from 'path';
import {
  BIOME_IDS, sectorOfX, detectBiomeVisits, sanitizeBiomeProgress, mergeBiomeVisits,
} from '../../src/systems/BiomeDiscovery.js';
import { biomeForSector, sectorHasBridge, BASE_BIOME_ID, SECTOR_M, BASE_SECTORS } from '../../src/systems/TerrainGenerator.js';
import { loadContent, makeGen } from './_helpers.js';

const CONTENT = loadContent();
const DEFS = Object.values(CONTENT.biomes);
const PPM = 20;
const SECTOR_PX = SECTOR_M * PPM;
const LEVELS = JSON.parse(fs.readFileSync(path.resolve('src/data/progression/levels.json'), 'utf8'));

/** First seed whose 0-based sector 2 is `id` at mask `bit`, searched deterministically. */
function seedWithSector2(id, bit, sector = BASE_SECTORS) {
  for (let i = 0; i < 500; i++) {
    const seed = `d3-${id}-${i}`;
    if (biomeForSector(seed, sector, bit, DEFS) === id) return seed;
  }
  throw new Error(`no seed puts ${id} at sector ${sector}`);
}

describe('BIOME_IDS: the known biome id list', () => {
  test('is exactly the shipped biome JSON ids, in the level table biomeOrder', () => {
    const shipped = fs.readdirSync(path.resolve('src/data/biomes')).filter((f) => f.endsWith('.json'))
      .map((f) => JSON.parse(fs.readFileSync(path.resolve('src/data/biomes', f), 'utf8')).id).sort();
    expect([...BIOME_IDS].sort()).toEqual(shipped);
    expect([...BIOME_IDS]).toEqual(LEVELS.biomeOrder);
  });
});

describe('sectorOfX: the same 0-based sector rule as TerrainGenerator._sectorOf', () => {
  test('boundaries at every SECTOR_M metres', () => {
    expect(sectorOfX(0, PPM)).toBe(0);
    expect(sectorOfX(SECTOR_PX - 1, PPM)).toBe(0);
    expect(sectorOfX(SECTOR_PX, PPM)).toBe(1);
    expect(sectorOfX(2 * SECTOR_PX + 5, PPM)).toBe(2);
  });
});

/** detectBiomeVisits fed by a real generator's own answer, as RunScene feeds it. */
function detect(seed, mask, o) {
  const gen = makeGen(seed, { biomeMask: mask });
  return detectBiomeVisits({ biomeAt: (x) => gen.biomeAtX(x), pxPerMeter: PPM, ...o });
}

describe('detectBiomeVisits', () => {
  // Sectors 0-1 are Debutmont (the home biome), sector 2 is Crystal Cavern, so a bridge opens sector 2 (#65).
  const seed = seedWithSector2('crystal-cavern', 16);
  const MASK = 16;
  const HOME = BASE_BIOME_ID;
  const run = (o) => detect(o.seed || seed, o.biomeMask === undefined ? MASK : o.biomeMask, o);

  test('the home biome is encountered from sector 0, even at mask 0 (arcade is never recorded)', () => {
    const v0 = run({ biomeMask: 0, furthestX: 10, crashX: 10 });
    expect(v0).toEqual({ encountered: [HOME], completed: [] });
    const v1 = run({ biomeMask: 0, furthestX: 40 * SECTOR_PX, crashX: 40 * SECTOR_PX });
    expect(v1).toEqual({ encountered: [HOME], completed: [HOME] });
  });

  test('a run that never reaches sector 2 encounters only the home biome', () => {
    const v = run({ furthestX: 2 * SECTOR_PX - 1, crashX: 2 * SECTOR_PX - 1 });
    expect(v).toEqual({ encountered: [HOME], completed: [HOME] });
  });

  test('still inside the arcade bridge that opens the biome sector: the biome is not encountered yet', () => {
    expect(sectorHasBridge(seed, 2, 16, DEFS)).toBe(true);
    const gen = makeGen(seed, { biomeMask: MASK });
    // The generator's own bridge edge: the first chunk of sector 2 that is the biome.
    let edge = 2 * SECTOR_PX;
    while (gen.biomeAtX(edge) !== 'crystal-cavern') edge += 16;
    expect(gen.biomeAtX(edge - 1)).toBeNull();
    expect(run({ furthestX: 2 * SECTOR_PX + 10, crashX: 2 * SECTOR_PX + 10 }).encountered).toEqual([HOME]);
    expect(run({ furthestX: edge - 1, crashX: edge - 1 }).encountered).toEqual([HOME]);
    expect(run({ furthestX: edge, crashX: edge }).encountered).toEqual([HOME, 'crystal-cavern']);
  });

  test('discovery matches gen.biomeAtX at every bridge edge: never credits a biome not yet reached, never misses one reached', () => {
    // Independent of the probe rule: sample the generator every 5 m up to x and union the answers.
    const sampled = (gen, x) => {
      const ids = new Set();
      for (let px = 0; px <= x; px += 100) { const id = gen.biomeAtX(px); if (id) ids.add(id); }
      const last = gen.biomeAtX(x);
      if (last) ids.add(last);
      return ids;
    };
    let edges = 0;
    for (const sd of ['edge-a', 'edge-b', 'edge-c', 'edge-d']) {
      const mask = 0x7ff;
      const gen = makeGen(sd, { biomeMask: mask });
      for (let s = 2; s < 24; s++) {
        if (!sectorHasBridge(sd, s, mask, DEFS)) continue;
        const want = biomeForSector(sd, s, mask, DEFS);
        let edge = s * SECTOR_PX;
        while (gen.biomeAtX(edge) !== want) edge += 16;
        for (const x of [edge - 1, edge]) {
          const v = detect(sd, mask, { furthestX: x, crashX: x });
          expect(new Set(v.encountered)).toEqual(sampled(gen, x));
        }
        expect(new Set(detect(sd, mask, { furthestX: edge - 1 }).encountered).has(want)).toBe(
          sampled(gen, edge - 1).has(want),
        );
        edges++;
      }
    }
    expect(edges).toBeGreaterThan(20);
  });

  test('past the bridge the biome is encountered; crashing inside it does not complete it', () => {
    const x = 2 * SECTOR_PX + SECTOR_PX / 2;
    const v = run({ furthestX: x, crashX: x });
    expect(v).toEqual({ encountered: [HOME, 'crystal-cavern'], completed: [HOME] });
  });

  test('riding the whole sector through to its end completes it', () => {
    const x = 3 * SECTOR_PX + 10;
    const v = run({ furthestX: x, crashX: x });
    expect(v.encountered).toContain('crystal-cavern');
    expect(v.completed).toContain('crystal-cavern');
  });

  test('a run-ending crash back inside an earlier biome sector voids that sector (respawned behind)', () => {
    // The sled reached sector 3 before, but its fatal crash is in sector 2.
    const v = run({ furthestX: 3 * SECTOR_PX + 10, crashX: 2 * SECTOR_PX + 50 });
    expect(v.encountered).toContain('crystal-cavern');
    expect(v.completed).not.toContain('crystal-cavern');
  });

  test('every sector up to the furthest x is checked, matching biomeForSector one by one', () => {
    const seed2 = 'd3-scan';
    const mask = 1 | 2 | 4 | 8;
    const furthestX = 20 * SECTOR_PX + SECTOR_PX / 2; // past any bridge into sector 20
    const v = detect(seed2, mask, { furthestX, crashX: furthestX });
    const enc = new Set();
    const comp = new Set();
    for (let s = 0; s <= 20; s++) {
      const id = biomeForSector(seed2, s, mask, DEFS);
      enc.add(id); if (s < 20) comp.add(id);
    }
    expect(new Set(v.encountered)).toEqual(enc);
    expect(new Set(v.completed)).toEqual(comp);
    expect(enc.size).toBeGreaterThan(1); // the scan is not vacuous
  });

  test('arcade (null) is never recorded, whatever the mask or distance', () => {
    for (const mask of [0, 2, 0x7ff]) {
      const v = detect('d3-arcade', mask, { furthestX: 60 * SECTOR_PX, crashX: 60 * SECTOR_PX });
      for (const id of [...v.encountered, ...v.completed]) expect(BIOME_IDS).toContain(id);
    }
  });

  test('output is in canonical BIOME_IDS order, deduplicated', () => {
    const v = detect('d3-order', 0x7ff, { furthestX: 60 * SECTOR_PX, crashX: 60 * SECTOR_PX });
    const order = (list) => list.map((id) => BIOME_IDS.indexOf(id));
    expect(order(v.encountered)).toEqual([...order(v.encountered)].sort((a, b) => a - b));
    expect(new Set(v.encountered).size).toBe(v.encountered.length);
    expect(v.completed.every((id) => v.encountered.includes(id))).toBe(true);
  });

  test('junk input degrades to empty rather than throwing', () => {
    expect(detectBiomeVisits()).toEqual({ encountered: [], completed: [] });
    expect(detectBiomeVisits({ biomeAt: () => 'debutmont', furthestX: NaN })).toEqual({ encountered: [], completed: [] });
    expect(detectBiomeVisits({ furthestX: 100 })).toEqual({ encountered: [], completed: [] }); // no terrain answer
  });
});

describe('sanitizeBiomeProgress / mergeBiomeVisits', () => {
  test('keeps only known ids, dedupes, canonical order, completed is a subset of encountered', () => {
    const p = sanitizeBiomeProgress({ encountered: ['pyramid-peak', 'nope', 'debutmont', 'debutmont', 7], completed: ['vertigo-vents', 'bogus'] });
    expect(p).toEqual({ encountered: ['debutmont', 'pyramid-peak', 'vertigo-vents'], completed: ['vertigo-vents'] });
  });

  test('anything that is not an object reads as empty sets', () => {
    for (const raw of [undefined, null, 'x', 3, []]) expect(sanitizeBiomeProgress(raw)).toEqual({ encountered: [], completed: [] });
  });

  test('merge is a union and never removes what was already recorded', () => {
    const a = { encountered: ['debutmont'], completed: ['debutmont'] };
    const m = mergeBiomeVisits(a, { encountered: ['pyramid-peak'], completed: [] });
    expect(m).toEqual({ encountered: ['debutmont', 'pyramid-peak'], completed: ['debutmont'] });
    expect(a).toEqual({ encountered: ['debutmont'], completed: ['debutmont'] }); // input untouched
  });
});/**
 * B0: the RunScene dispatch of every new hazard effect and power-up kind (audit T3: no Jest test imported RunScene, so a
 * deleted dispatch branch failed nothing). The scene methods under test are the shipped ones, called on a stub built
 * from RunScene.prototype; Phaser is a small fake with just the Matter Body calls the gust uses. The built-game gate
 * (tools/sim/gate-playthrough.mjs) checks the same effects on the real sled.
 */
import { jest } from '@jest/globals';

const Body = {
  getVelocity: (b) => ({ x: b.velocity.x, y: b.velocity.y }),
  setVelocity: (b, v) => { b.velocity = { x: v.x, y: v.y }; },
  getAngularVelocity: () => 0,
  setAngularVelocity: () => {},
};
class Stub { constructor() { this.alpha = 0; } setAlpha(a) { this.alpha = a; return this; } setFillStyle() { return this; } }
const FakePhaser = {
  Scene: class {},
  Physics: { Matter: { Matter: { Bodies: { rectangle: (x, y, w, h, o) => ({ x, y, w, h, ...o }), circle: (x, y, r, o) => ({ x, y, r, ...o }) }, Body } } },
  Renderer: { WebGL: { Pipelines: { PostFXPipeline: class {} } } },
  GameObjects: { Container: class {}, Graphics: class {}, BitmapText: class {}, Zone: class {}, Image: class {}, Rectangle: class {}, Text: class {} },
  BlendModes: { ADD: 1 },
  Scenes: { Events: { UPDATE: 'update', SHUTDOWN: 'shutdown', DESTROY: 'destroy' } },
  Math: { Between: (a) => a, Clamp: (v, a, b) => Math.min(b, Math.max(a, v)) },
};
jest.unstable_mockModule('phaser', () => ({ default: FakePhaser }));
jest.unstable_mockModule('../../src/shaders/GlitchPipeline.js', () => ({ GlitchPipeline: { install() {} } }));

const { RunScene } = await import('../../src/scenes/RunScene.js');
const { UIScene } = await import('../../src/scenes/UIScene.js');
const { Hazard } = await import('../../src/entities/Hazard.js');
const { PowerUp } = await import('../../src/entities/PowerUp.js');
const { EVT } = await import('../../src/events.js');
const { PhysicsTuner, TUNING, BASE_STEP_MS } = await import('../../src/systems/PhysicsTuner.js');
const { GUST_MAX_PX_S, BLIND_MIN_VISIBILITY } = await import('../../src/systems/BiomeEffects.js');
const { loadContent } = await import('./_helpers.js');

const MODS = loadContent().terrainMods;
const PAD = { tuck: false, brake: false };
const toPxS = (v) => (v * 1000) / BASE_STEP_MS;

function makeRun({ zones = [] } = {}) {
  const emitted = [];
  const s = Object.create(RunScene.prototype);
  Object.assign(s, {
    game: { events: { emit: (e, p) => { emitted.push([e, p]); } } },
    emitted,
    sled: {
      x: 1000, y: 0, vx: 300, vy: 20, inWorld: true, invulnerableMs: 0, grounded: true, parachuteMs: 0, airBrakeActive: false,
      body: { velocity: { x: 300 * BASE_STEP_MS / 1000, y: 20 * BASE_STEP_MS / 1000 } },
      scaleVelocity() {}, wobble() {},
    },
    fx: { sparks() {}, ring() {} },
    shake() {},
    flashRect: new Stub(),
    blindRect: new Stub(),
    palette: { cyan: 1, amber: 2, lime: 3, bg: 0 },
    tuner: new PhysicsTuner(),
    dailyMods: {},
    crashed: false,
    pendingCrash: null,
    runTimeMs: 0,
    slowMs: 0, slowFactor: 0.5, scrambleMs: 0, boostMs: 0, boostFactor: 1, slowmoMs: 0, slowmoScale: 0.5, shieldCharges: 0,
    collectedPowerups: new Set(),
    _despawn: [],
    _airTricks: 0,
    maxAirtimeMs: 0,
    _landings: 0,
  });
  s.getZoneDefs = () => zones;
  s._resetBiomeEffects();
  return s;
}

const hazard = (onHit, id = 'fxHazard') => ({ def: { id, onHit }, cx: 1000, cy: 0, color: 5, gfx: null, hit: false });
const pickup = (effect, id = 'fxPickup') => ({ def: { id, effect }, spawn: { x: 1000, y: 0 }, color: 5, destroy() {} });
const phys = (s) => s.tuner.getEffective(s.physicsContext(PAD));
const events = (s, name) => s.emitted.filter(([e]) => e === name).map(([, p]) => p);

describe('RunScene.onPowerUp: ward', () => {
  test('a ward vs stickyPatch makes the effective groundResist the un-sticky value while it lasts, then sticky again', () => {
    const s = makeRun({ zones: [MODS.stickyPatch] });
    const base = makeRun().tuner.getEffective(makeRun().physicsContext(PAD)).groundResist;
    const sticky = phys(s).groundResist;
    expect(sticky).toBeGreaterThan(base);
    s.onPowerUp(pickup({ kind: 'ward', durationMs: 4000, mods: ['stickyPatch'], hazards: [], effects: [] }, 'slickWax'));
    expect(phys(s).groundResist).toBeCloseTo(base, 12);
    expect(events(s, EVT.POWERUP_COLLECTED)).toEqual([{ id: 'slickWax', durationMs: 4000, charges: 0 }]);
    s.tickEffects(3990);
    expect(phys(s).groundResist).toBeCloseTo(base, 12);
    s.tickEffects(20);
    expect(phys(s).groundResist).toBeCloseTo(sticky, 12);
    expect(events(s, EVT.POWERUP_EXPIRED)).toEqual([{ id: 'slickWax', reason: 'timeout' }]);
  });

  test('a warded hazard id does nothing and reports no hit', () => {
    const s = makeRun();
    s.onPowerUp(pickup({ kind: 'ward', durationMs: 5000, hazards: ['groomerCat'] }));
    s.onHazard(hazard({ effect: 'crash' }, 'groomerCat'));
    expect(s.pendingCrash).toBe(null);
    expect(events(s, EVT.HAZARD_HIT)).toEqual([]);
    s.onHazard(hazard({ effect: 'crash' }, 'packetSpike'));
    expect(s.pendingCrash).toEqual({ cause: 'hazard', hazardId: 'packetSpike' });
  });

  test('a warded effect (blind, slow) does nothing, and an active slow stops acting while warded', () => {
    const s = makeRun();
    s.onHazard(hazard({ effect: 'slow', durationMs: 1500, speedFactor: 0.5 }, 'firewall'));
    expect(phys(s).speedMul).toBeCloseTo(0.5, 9);
    s.onPowerUp(pickup({ kind: 'ward', durationMs: 5000, effects: ['blind', 'slow'] }));
    expect(phys(s).speedMul).toBeCloseTo(1, 9);
    s.onHazard(hazard({ effect: 'blind', durationMs: 1200, visibility: 0.4 }, 'shatterWall'));
    expect(s.blindMs).toBe(0);
    expect(events(s, EVT.HAZARD_HIT).map((p) => p.effect)).toEqual(['slow']);
  });

  test('a manual reset (Shift) ends every ward, glide, stabilize and blind with reason respawn', () => {
    const s = makeRun();
    Object.assign(s, {
      pickSafe: () => ({}), respawnAt: () => ({ x: 0, y: 0 }), emitFlow() {}, emitCombo() {}, emitScore() {},
      score: { penalizeReset: () => ({ comboPenalty: 0, pointsLost: 0 }) },
    });
    s.onPowerUp(pickup({ kind: 'ward', durationMs: 5000, mods: ['stickyPatch'] }, 'slickWax'));
    s.onPowerUp(pickup({ kind: 'glide', frictionMul: 0.7, durationMs: 4000 }, 'sandrunner'));
    s.onPowerUp(pickup({ kind: 'stabilize', landingToleranceDeg: 12, durationMs: 5000 }, 'gravStab'));
    s.onHazard(hazard({ effect: 'blind', durationMs: 1200 }, 'shatterWall'));
    s.manualReset();
    expect(events(s, EVT.POWERUP_EXPIRED)).toEqual([
      { id: 'slickWax', reason: 'respawn' }, { id: 'sandrunner', reason: 'respawn' }, { id: 'gravStab', reason: 'respawn' },
    ]);
    expect(events(s, EVT.EFFECT_END)).toEqual([{ effect: 'blind' }]);
    expect(s.wards.wards).toEqual([]);
    expect([s.glideMs, s.stabilizeMs, s.blindMs]).toEqual([0, 0, 0]);
  });
});

describe('RunScene.onPowerUp: glide and stabilize', () => {
  test('a glide lowers ground friction (groundResist x frictionMul) for its duration', () => {
    const s = makeRun();
    const base = phys(s).groundResist;
    s.onPowerUp(pickup({ kind: 'glide', frictionMul: 0.7, durationMs: 4000 }, 'sandrunner'));
    expect(phys(s).groundResist).toBeCloseTo(base * 0.7, 12);
    s.tickEffects(4001);
    expect(phys(s).groundResist).toBeCloseTo(base, 12);
    expect(events(s, EVT.POWERUP_EXPIRED)).toEqual([{ id: 'sandrunner', reason: 'timeout' }]);
  });

  test('a stabilize widens landing tolerance: a landing that would crash becomes a wobble', () => {
    const land = { quality: 'crash', angleDeg: TUNING.forgiveAngleDeg + 8, impactSpeedPxS: 400, airtimeMs: 600 };
    const fs = { x: 1000, y: 0, vx: 300, vy: 0 };
    const stubLanding = (s) => {
      s.score = { getSnapshot: () => ({ multiplier: 1, comboTricks: [] }), onLanding: () => ({ bonus: 0, banked: 0, multiplierUsed: 1 }) };
      s.emitCombo = () => {}; s.emitScore = () => {}; s.emitFlow = () => {}; s._zoneScoreMulAt = () => 1; s.applyLandingBoost = () => {};
    };
    const plain = makeRun();
    stubLanding(plain);
    plain.handleTricksAndLanding({ tricks: [], landing: land }, fs);
    expect(plain.pendingCrash).toEqual({ cause: 'badLanding' });

    const s = makeRun();
    stubLanding(s);
    s.onPowerUp(pickup({ kind: 'stabilize', landingToleranceDeg: 12, durationMs: 5000 }, 'gravStab'));
    s.handleTricksAndLanding({ tricks: [], landing: land }, fs);
    expect(s.pendingCrash).toBe(null);
    expect(events(s, EVT.LANDING).map((p) => p.quality)).toEqual(['sloppy']);
  });

  test('a stabilize bounceMul damps bounce', () => {
    const s = makeRun({ zones: [MODS.bouncySpring] });
    const before = phys(s).bounceMul;
    s.onPowerUp(pickup({ kind: 'stabilize', landingToleranceDeg: 12, bounceMul: 0.5, durationMs: 5000 }));
    expect(phys(s).bounceMul).toBeCloseTo(before * 0.5, 12);
  });
});

describe('RunScene.onHazard: gust and blind', () => {
  test('a gust changes the sled velocity by the bounded impulse', () => {
    const s = makeRun();
    const v0 = { x: toPxS(s.sled.body.velocity.x), y: toPxS(s.sled.body.velocity.y) };
    s.onHazard(hazard({ effect: 'gust', impulsePxS: [400, -300] }, 'gustFront'));
    const dvx = toPxS(s.sled.body.velocity.x) - v0.x;
    const dvy = toPxS(s.sled.body.velocity.y) - v0.y;
    expect(Math.hypot(dvx, dvy)).toBeCloseTo(GUST_MAX_PX_S, 6);
    expect(dvx).toBeGreaterThan(0);
    expect(dvy).toBeLessThan(0);
    expect(events(s, EVT.HAZARD_HIT)).toEqual([{ hazardId: 'gustFront', effect: 'gust', durationMs: 0, x: 1000, y: 0 }]);
    expect(s.pendingCrash).toBe(null);
  });

  test('blind shows the overlay (>= 35 % visibility), never crashes, and ends with EFFECT_END', () => {
    const s = makeRun();
    s.onHazard(hazard({ effect: 'blind', durationMs: 1200, visibility: 0.05 }, 'shatterWall'));
    expect(s.pendingCrash).toBe(null);
    expect(events(s, EVT.HAZARD_HIT)[0]).toMatchObject({ effect: 'blind', durationMs: 1200 });
    s.tickEffects(400);
    s.updateBlindOverlay();
    expect(s.blindRect.alpha).toBeGreaterThan(0.5);
    expect(s.blindRect.alpha).toBeLessThanOrEqual(1 - BLIND_MIN_VISIBILITY + 1e-12);
    s.tickEffects(900);
    s.updateBlindOverlay();
    expect(s.blindRect.alpha).toBe(0);
    expect(events(s, EVT.EFFECT_END)).toEqual([{ effect: 'blind' }]);
  });

  test('base effects still dispatch as before (slow, scramble, crash)', () => {
    const s = makeRun();
    s.onHazard(hazard({ effect: 'scramble' }, 'vent'));
    expect(events(s, EVT.HAZARD_HIT)[0]).toMatchObject({ effect: 'scramble', durationMs: 2000 });
    expect(s.scrambleMs).toBe(2000);
    s.onHazard(hazard({ effect: 'slow', speedFactor: 0.5 }, 'fw'));
    expect(s.slowMs).toBe(1500);
    s.onHazard(hazard({ effect: 'crash' }, 'spike'));
    expect(s.pendingCrash).toEqual({ cause: 'hazard', hazardId: 'spike' });
  });
});

describe('UIScene: HUD entries for every new kind', () => {
  const content = {
    powerups: {
      fxWard: { id: 'fxWard', effect: { kind: 'ward' } },
      fxGlide: { id: 'fxGlide', effect: { kind: 'glide' } },
      fxStab: { id: 'fxStab', effect: { kind: 'stabilize' } },
      fxOdd: { id: 'fxOdd', effect: { kind: 'mystery' } },
    },
  };
  const ui = () => Object.assign(Object.create(UIScene.prototype), { content, nowMs: 0, warnY: 40, effects: new Map() });
  const recorder = () => {
    const ops = [];
    return { ops, g: new Proxy({}, { get: (t, k) => (...a) => { ops.push(k); return undefined; } }) };
  };

  test('a biome pickup without its own POWERUP_INFO row gets its kind\'s colour and an id-derived name', () => {
    const u = ui();
    expect(u._powerInfo('fxWard')).toEqual({ name: 'FX WARD', color: 'cyan' });
    expect(u._powerInfo('fxGlide').color).toBe('lime');
    expect(u._powerInfo('fxStab').color).toBe('amber');
    expect(u._powerInfo('clockPulse').name).toBe('CLOCK PULSE');
  });

  test('ward, glide and stabilize chips draw their own icon, not the unknown-id square', () => {
    const u = ui();
    const draw = (id) => { const r = recorder(); u._drawIcon(r.g, id, 10, 10, 1); return r.ops.filter((k) => k !== 'lineStyle' && k !== 'fillStyle'); };
    const square = draw('fxOdd');
    expect(square).toEqual(['strokeRect']);
    for (const id of ['fxWard', 'fxGlide', 'fxStab']) {
      expect(draw(id)).not.toEqual(square);
      expect(draw(id).length).toBeGreaterThan(1);
    }
    expect(draw('fxWard')).not.toEqual(draw('fxGlide'));
    expect(draw('fxGlide')).not.toEqual(draw('fxStab'));
  });

  test('blind and gust raise a warning line; an instant gust stays up for its showMs', () => {
    const u = ui();
    const made = [];
    u._t = () => { const t = { text: '', setText(x) { this.text = x; return t; }, setColorKey() { return t; }, destroy() {} }; t.__snap = false; made.push(t); return t; };
    u.onHazard({ effect: 'blind', durationMs: 1200 });
    u.onHazard({ effect: 'gust', durationMs: 0 });
    expect([...u.effects.keys()]).toEqual(['blind', 'gust']);
    expect(made[0].text).toContain('BLINDED');
    expect(made[1].text).toContain('GUST');
    expect(u.effects.get('gust').remaining).toBeGreaterThanOrEqual(700);
  });
});

describe('Hazard.js / PowerUp.js: biome defs with a new shapeKey still draw, crash hazards keep `danger`', () => {
  const PAL = { danger: 0xff0000, magenta: 0xff00ff, lime: 0x00ff00, cyan: 0x00ffff, amber: 0xffaa00, bg: 0, text: 0xffffff };
  const scene = () => ({
    matter: { world: { add() {}, remove() {} } },
    add: {
      graphics: () => {
        const ops = [];
        const g = new Proxy({ ops, y: 0 }, {
          get: (t, k) => (k in t ? t[k] : (...a) => { ops.push([k, ...a]); return g; }),
          set: (t, k, v) => { t[k] = v; return true; },
        });
        return g;
      },
    },
  });
  const fills = (gfx) => gfx.ops.filter(([k]) => /^fill|^stroke/.test(k));

  test('a biome crash hazard is drawn in `danger` even when its JSON names another colour; a base def is not recoloured', () => {
    const biome = new Hazard(scene(), { id: 'meteor', biome: 'space-mountain', shapeKey: 'meteor', size: { w: 30, h: 30 }, onHit: { effect: 'crash' }, placement: 'air', colorKey: 'magenta' }, { x: 100, y: 50, rotationDeg: 0 }, PAL);
    expect(biome.color).toBe(PAL.danger);
    const chasm = new Hazard(scene(), { id: 'glitchChasm', shapeKey: 'chasm', size: { w: 64, h: 40 }, onHit: { effect: 'crash' }, placement: 'ground', colorKey: 'magenta' }, { x: 100, y: 50, rotationDeg: 0 }, PAL);
    expect(chasm.color).toBe(PAL.magenta);
    const slow = new Hazard(scene(), { id: 'seaweed', biome: 'underwater-mountain', shapeKey: 'seaweed', size: { w: 30, h: 30 }, onHit: { effect: 'slow' }, placement: 'ground', colorKey: 'lime' }, { x: 100, y: 50, rotationDeg: 0 }, PAL);
    expect(slow.color).toBe(PAL.lime);
  });

  test('an unknown hazard shapeKey draws the visible generic box', () => {
    const h = new Hazard(scene(), { id: 'groomer', biome: 'debutmont', shapeKey: 'groomerCat', size: { w: 30, h: 20 }, onHit: { effect: 'slow' }, placement: 'ground', colorKey: 'lime' }, { x: 100, y: 50, rotationDeg: 0 }, PAL);
    expect(h.drawKind).toBe('generic');
    const ops = fills(h.gfx);
    expect(ops.some(([k, , , w, ht]) => k === 'fillRect' && w === 30 && ht === 20)).toBe(true);
  });

  test('an unknown power-up shapeKey draws a filled glyph, not just the ring', () => {
    const p = new PowerUp(scene(), { id: 'mapleWax', biome: 'debutmont', shapeKey: 'mapleWax', radius: 10, effect: { kind: 'speedBoost' }, colorKey: 'amber' }, { x: 100, y: 50 }, PAL);
    expect(p.drawKind).toBe('generic');
    expect(p.gfx.ops.some(([k, pts]) => k === 'fillPoints' && Array.isArray(pts) && pts.length === 4)).toBe(true);
  });
});/**
 * B0 effect plumbing: the pure math of every new hazard effect and power-up kind (spec §5 / §6 B0.4).
 * RunScene and PhysicsTuner only call these; tests/src/biome-effects-runscene.test.js covers the dispatch.
 */
import {
  emptyWards, addWard, tickWards, isWarded, wardMsLeft, WARD_MIN_MS, WARD_MAX_MS,
} from '../../src/systems/Wards.js';
import {
  GUST_MAX_PX_S, gustImpulse, BLIND_MIN_VISIBILITY, BLIND_DEFAULT_MS, blindVisibility, blindOverlayAlpha,
  glideFrictionMul, GLIDE_MIN_FRICTION_MUL, stabilizeToleranceDeg, STABILIZE_MAX_DEG, resolveLanding,
  hazardEffectDurationMs, hazardColorKey, hazardColor, hazardDrawKind, powerupDrawKind, timedPowerupMs,
} from '../../src/systems/BiomeEffects.js';
import { PhysicsTuner, TUNING } from '../../src/systems/PhysicsTuner.js';
import { PHYSICS } from '../../src/constants.js';
import { classifyLanding } from '../../src/systems/TrickTracker.js';
import { loadContent } from './_helpers.js';

const MODS = loadContent().terrainMods;

describe('Wards.js: isWarded(state, query)', () => {
  const ward = { kind: 'ward', durationMs: 4000, mods: ['stickyPatch'], hazards: ['fxGroundHazard'], effects: ['blind', 'scramble'] };

  test('an empty or missing state wards nothing', () => {
    expect(isWarded(emptyWards(), { modId: 'stickyPatch' })).toBe(false);
    expect(isWarded(null, { modId: 'stickyPatch' })).toBe(false);
    expect(isWarded(undefined, { effect: 'blind' })).toBe(false);
  });

  test('a ward answers for the mods, hazards and effects it lists, and nothing else', () => {
    const s = addWard(emptyWards(), 'slickWax', ward);
    expect(isWarded(s, { modId: 'stickyPatch' })).toBe(true);
    expect(isWarded(s, { modId: 'highBandwidth' })).toBe(false);
    expect(isWarded(s, { hazardId: 'fxGroundHazard' })).toBe(true);
    expect(isWarded(s, { hazardId: 'packetSpike' })).toBe(false);
    expect(isWarded(s, { effect: 'blind' })).toBe(true);
    expect(isWarded(s, { effect: 'scramble' })).toBe(true);
    expect(isWarded(s, { effect: 'slow' })).toBe(false);
    expect(isWarded(s, {})).toBe(false);
    expect(isWarded(s, null)).toBe(false);
  });

  test('addWard does not mutate its input, and re-collecting the same ward refreshes it instead of stacking', () => {
    const a = emptyWards();
    const b = addWard(a, 'slickWax', ward);
    expect(a.wards).toHaveLength(0);
    const c = tickWards(b, 1500).state;
    expect(wardMsLeft(c, 'slickWax')).toBe(2500);
    const d = addWard(c, 'slickWax', ward);
    expect(d.wards).toHaveLength(1);
    expect(wardMsLeft(d, 'slickWax')).toBe(4000);
  });

  test('ward durations are clamped to 4-6 s (spec §4)', () => {
    expect([WARD_MIN_MS, WARD_MAX_MS]).toEqual([4000, 6000]);
    expect(wardMsLeft(addWard(emptyWards(), 'a', { ...ward, durationMs: 100 }), 'a')).toBe(4000);
    expect(wardMsLeft(addWard(emptyWards(), 'a', { ...ward, durationMs: 60000 }), 'a')).toBe(6000);
    expect(wardMsLeft(addWard(emptyWards(), 'a', { ...ward, durationMs: 5000 }), 'a')).toBe(5000);
    expect(wardMsLeft(addWard(emptyWards(), 'a', { ...ward, durationMs: undefined }), 'a')).toBe(4000);
  });

  test('tickWards counts down and reports each expired id once', () => {
    let s = addWard(addWard(emptyWards(), 'a', ward), 'b', { ...ward, durationMs: 6000 });
    let r = tickWards(s, 3999);
    expect(r.expired).toEqual([]);
    s = r.state;
    r = tickWards(s, 1);
    expect(r.expired).toEqual(['a']);
    expect(isWarded(r.state, { modId: 'stickyPatch' })).toBe(true); // b still holds
    r = tickWards(r.state, 2000);
    expect(r.expired).toEqual(['b']);
    expect(isWarded(r.state, { modId: 'stickyPatch' })).toBe(false);
    expect(tickWards(r.state, 1000).expired).toEqual([]);
  });

  test('malformed ward lists are ignored, not thrown on', () => {
    const s = addWard(emptyWards(), 'x', { kind: 'ward', durationMs: 4000, mods: 'stickyPatch', hazards: null });
    expect(isWarded(s, { modId: 'stickyPatch' })).toBe(false);
  });
});

describe('PhysicsTuner skips warded mod ids; glide and stabilize reach the effective physics', () => {
  const t = new PhysicsTuner();
  const sticky = MODS.stickyPatch;
  const base = t.getEffective({});

  test('a ward vs stickyPatch makes the sticky zone feel like no zone at all', () => {
    const inSticky = t.getEffective({ zones: [sticky] });
    expect(inSticky.groundResist).toBeGreaterThan(base.groundResist);
    const wards = addWard(emptyWards(), 'slickWax', { durationMs: 4000, mods: ['stickyPatch'] });
    const warded = t.getEffective({ zones: [sticky], wards });
    expect(warded.groundResist).toBeCloseTo(base.groundResist, 12);
    // only the listed mod: a highBandwidth zone still applies under the same ward
    const hb = t.getEffective({ zones: [sticky, MODS.highBandwidth], wards });
    expect(hb.groundResist).toBeCloseTo(t.getEffective({ zones: [MODS.highBandwidth] }).groundResist, 12);
  });

  test('a ward vs slowMotion / conveyorBelt removes those mods too (B1 targets)', () => {
    const wards = addWard(emptyWards(), 'w', { durationMs: 4000, mods: ['slowMotion', 'conveyorBelt'] });
    const slow = t.getEffective({ zones: [MODS.slowMotion], wards });
    expect(slow.gravityPxS2).toBe(base.gravityPxS2);
    const belt = t.getEffective({ zones: [MODS.conveyorBelt], wards });
    expect(belt.beltDrivePxS2).toBe(0);
  });

  test('glide multiplies the ground friction (groundResist) by its frictionMul', () => {
    const g = t.getEffective({ glideFrictionMul: 0.7 });
    expect(g.groundResist).toBeCloseTo(base.groundResist * 0.7, 12);
    expect(t.getEffective({ glideFrictionMul: 1 }).groundResist).toBeCloseTo(base.groundResist, 12);
  });

  test('stabilize bounceMul scales bounce (and so restitution)', () => {
    const s = t.getEffective({ zones: [MODS.bouncySpring], stabilizeBounceMul: 0.5 });
    const n = t.getEffective({ zones: [MODS.bouncySpring] });
    expect(s.bounceMul).toBeCloseTo(n.bounceMul * 0.5, 12);
  });
});

describe('BiomeEffects.js: gust', () => {
  test('the impulse is the def vector when inside the 180 px/s bound', () => {
    expect(GUST_MAX_PX_S).toBe(180);
    expect(gustImpulse([120, -60])).toEqual({ dvx: 120, dvy: -60 });
  });

  test('a larger impulse is scaled down to 180 px/s, keeping its direction', () => {
    const g = gustImpulse([400, -300]);
    expect(Math.hypot(g.dvx, g.dvy)).toBeCloseTo(180, 9);
    expect(g.dvx / g.dvy).toBeCloseTo(400 / -300, 9);
  });

  test('malformed input is a zero impulse', () => {
    expect(gustImpulse(null)).toEqual({ dvx: 0, dvy: 0 });
    expect(gustImpulse([NaN, 5])).toEqual({ dvx: 0, dvy: 5 });
    expect(gustImpulse('x')).toEqual({ dvx: 0, dvy: 0 });
  });
});

describe('BiomeEffects.js: blind', () => {
  test('visibility never drops below 35 % (spec §4) and defaults sensibly', () => {
    expect(BLIND_MIN_VISIBILITY).toBe(0.35);
    expect(blindVisibility(0)).toBe(0.35);
    expect(blindVisibility(-3)).toBe(0.35);
    expect(blindVisibility(0.6)).toBe(0.6);
    expect(blindVisibility(2)).toBe(1);
    expect(blindVisibility(undefined)).toBeGreaterThanOrEqual(0.35);
    expect(blindVisibility(NaN)).toBeGreaterThanOrEqual(0.35);
  });

  test('the overlay alpha is at most 1 - 0.35 at every moment and 0 when the effect is over', () => {
    for (const vis of [0, 0.35, 0.4, 0.8]) {
      for (let left = -100; left <= 1300; left += 10) {
        const a = blindOverlayAlpha(left, 1200, vis);
        expect(a).toBeGreaterThanOrEqual(0);
        expect(a).toBeLessThanOrEqual(1 - BLIND_MIN_VISIBILITY + 1e-12);
        if (left <= 0) expect(a).toBe(0);
      }
    }
    expect(blindOverlayAlpha(600, 1200, 0.4)).toBeCloseTo(0.6, 9); // mid-effect: full dim
  });

  test('the overlay is a pure function of time left (not seed-dependent, no randomness)', () => {
    expect(blindOverlayAlpha(500, 1200, 0.4)).toBe(blindOverlayAlpha(500, 1200, 0.4));
    expect(blindOverlayAlpha(500, 0, 0.4)).toBeGreaterThanOrEqual(0); // zero total never divides by zero
    expect(Number.isFinite(blindOverlayAlpha(500, 0, 0.4))).toBe(true);
  });
});

describe('BiomeEffects.js: glide, stabilize and landing', () => {
  test('glide frictionMul lowers friction, never raises it, never below the floor', () => {
    expect(glideFrictionMul(0.7)).toBe(0.7);
    expect(glideFrictionMul(1.4)).toBe(1);
    expect(glideFrictionMul(0)).toBe(GLIDE_MIN_FRICTION_MUL);
    expect(glideFrictionMul(undefined)).toBe(0.7);
  });

  test('stabilize tolerance is clamped to [0, STABILIZE_MAX_DEG]', () => {
    expect(stabilizeToleranceDeg(12)).toBe(12);
    expect(stabilizeToleranceDeg(-5)).toBe(0);
    expect(stabilizeToleranceDeg(90)).toBe(STABILIZE_MAX_DEG);
    expect(stabilizeToleranceDeg(undefined)).toBe(0);
  });

  test('without stabilize resolveLanding is exactly the old forgiveness rule', () => {
    const cases = [
      { quality: 'crash', angleDeg: 70, impactSpeedPxS: 400 },
      { quality: 'crash', angleDeg: 80, impactSpeedPxS: 400 },
      { quality: 'crash', angleDeg: 60, impactSpeedPxS: 1800 },
      { quality: 'good', angleDeg: 20, impactSpeedPxS: 300 },
      { quality: 'sloppy', angleDeg: 40, impactSpeedPxS: 300 },
    ];
    for (const l of cases) {
      const old = l.quality === 'crash' && Math.abs(l.angleDeg) <= TUNING.forgiveAngleDeg && l.impactSpeedPxS < TUNING.forgiveImpactPxS
        ? { ...l, quality: 'sloppy' } : l;
      expect(resolveLanding(l, 0)).toEqual(old);
    }
  });

  test('stabilize widens landing tolerance: a crash just past the forgiveness angle becomes a wobble, grades lift by the tolerance', () => {
    const crash = { quality: 'crash', angleDeg: TUNING.forgiveAngleDeg + 8, impactSpeedPxS: 400 };
    expect(resolveLanding(crash, 0).quality).toBe('crash');
    expect(resolveLanding(crash, 12).quality).not.toBe('crash');
    const sloppy = { quality: classifyLanding(36, 300).quality, angleDeg: 36, impactSpeedPxS: 300 };
    expect(sloppy.quality).toBe('sloppy');
    expect(resolveLanding(sloppy, 12).quality).toBe('good');
    // never worsens a landing, and never rescues a too-hard impact
    const perfect = { quality: 'perfect', angleDeg: 2, impactSpeedPxS: 300 };
    expect(resolveLanding(perfect, 12).quality).toBe('perfect');
    const slam = { quality: 'crash', angleDeg: 10, impactSpeedPxS: 1800 };
    expect(resolveLanding(slam, 12).quality).toBe('crash');
  });
});

