    expect(hazardColor({ biome: 'b', onHit: { effect: 'gust' }, colorKey: 'amber' }, pal)).toBe(3);
  });
});/**
 * #65 presentation is cosmetic only: with the dissolve / glitch layers on or off, terrain and the simulation are
 * byte-identical.
 *
 * The presentation layer's only reach into the world is TerrainGenerator.bridgeSpanAt (a read-only scratch query) and
 * RunScene._updateLook (which decides the look and when to repaint). So this file proves, for several seeds and masks:
 *  1. terrain digests (every field of every chunk) are identical whether or not a presentation frame loop is
 *     interleaved with generation, in either effects mode (dissolve on, or the reduced-motion hard cut);
 *  2. a streamed "run" (the scene's own generator.update(x) calls) adds and removes the same chunks in the same order,
 *     and the rolling-sled outcome over that terrain is identical;
 *  3. the real RunScene._updateLook repaints at exactly the generator-owed x in the hard-cut mode, never skips one with the
 *     dissolve on, adds graphics-only repaints inside bridges (since #140 no repaint touches a collider), and asks the
 *     generator nothing but reads.
 * The built game is checked the same way end to end with `npm run sim` on the two builds (see the PR).
 */
import { jest } from '@jest/globals';
import crypto from 'crypto';

const FakePhaser = {
  Scene: class {},
  Physics: { Matter: { Matter: { Bodies: {}, Body: {} } } },
  Renderer: { WebGL: { Pipelines: { PostFXPipeline: class {} } } },
  GameObjects: { Container: class {}, Graphics: class {}, BitmapText: class {}, Zone: class {}, Image: class {}, Rectangle: class {}, Text: class {} },
  BlendModes: { ADD: 1 },
  Scenes: { Events: { UPDATE: 'update', SHUTDOWN: 'shutdown', DESTROY: 'destroy' } },
  Math: { Between: (a) => a, Clamp: (v, a, b) => Math.min(b, Math.max(a, v)) },
};
jest.unstable_mockModule('phaser', () => ({ default: FakePhaser }));
jest.unstable_mockModule('../../src/shaders/GlitchPipeline.js', () => ({ GlitchPipeline: { install() {} } }));

const { RunScene } = await import('../../src/scenes/RunScene.js');
const { bridgeLook, veilCovers, VEIL_CELL_PX } = await import('../../src/systems/BiomeTransition.js');
const { REG } = await import('../../src/constants.js');
const { makeGen, loadContent, readDir, rollSim } = await import('./_helpers.js');

const ALL = readDir('biomes').reduce((m, d) => m | d.bit, 0);
const SEEDS = ['alpha', 'bitstream-bluffs', '42', 'shots65-d', '2026-11-13'];
const MASKS = [0, 2, ALL];
const CHUNKS = 120;

const round = (n) => (Number.isFinite(n) ? Math.round(n * 1e4) / 1e4 : n);
const completeOf = (v) => (Array.isArray(v) ? v.map(completeOf)
  : v && typeof v === 'object' ? Object.fromEntries(Object.keys(v).sort().map((k) => [k, completeOf(v[k])]))
    : typeof v === 'number' ? round(v) : v);
const digest = (v) => crypto.createHash('sha256').update(JSON.stringify(v)).digest('hex').slice(0, 32);

/** One frame of everything the presentation layer asks of the world around x, in the given effects mode. */
function presentationFrame(gen, x, enabled, sink) {
  const biomeNow = gen.biomeAtX(x);
  const span = biomeNow === null ? gen.bridgeSpanAt(x) : null;
  const look = bridgeLook(span, x, biomeNow, enabled);
  // what BiomeFx does with the veil each frame
  let covered = 0;
  for (let iy = 0; iy < 17; iy++) for (let ix = 0; ix < 480 / VEIL_CELL_PX; ix++) if (veilCovers(ix, iy, look.veil)) covered++;
  if (sink) sink.push([round(x), look.lookId, round(look.veil), covered]);
}

function chunkDigests(seed, mask, mode) {
  const gen = makeGen(seed, { biomeMask: mask });
  const out = [];
  for (let i = 0; i < CHUNKS; i++) {
    if (mode !== 'none') {
      // probe behind, at, ahead and far ahead (before those chunks have been generated), in both modes' order
      const b = gen.bounds[Math.min(i, gen.bounds.length - 1)];
      for (const dx of [-400, 0, 350, 9000, 25000]) presentationFrame(gen, Math.max(0, b.startX + dx), mode === 'on');
    }
    out.push(completeOf(gen.getChunk(i)));
  }
  return digest(out);
}

describe('terrain is identical with the presentation layer on, off, or absent', () => {
  for (const seed of SEEDS) {
    for (const mask of MASKS) {
      test(`seed ${seed} mask ${mask}: chunk digests`, () => {
        const plain = chunkDigests(seed, mask, 'none');
        expect(chunkDigests(seed, mask, 'on')).toBe(plain);
        expect(chunkDigests(seed, mask, 'off')).toBe(plain);
      });
    }
  }
});

describe('a streamed run and its simulated outcome are identical with the effects on or off', () => {
  function streamRun(seed, mask, mode) {
    const gen = makeGen(seed, { biomeMask: mask });
    const log = [];
    for (let x = 0; x < 2600 * 20; x += 160) {
      if (mode !== 'none') presentationFrame(gen, x, mode === 'on');
      const r = gen.update(x) || {};
      log.push([(r.added || []).map((c) => c.index), (r.removed || []).map((c) => (c && c.index !== undefined ? c.index : c))]);
      if (mode !== 'none') presentationFrame(gen, x + 300, mode === 'on');
    }
    const heights = [];
    for (let x = 0; x < 2400 * 20; x += 997) heights.push(round(gen.heightAt(x)));
    return { log, heights, sim: rollSim(gen, 1800), biomes: [0, 1500, 20000, 30000, 45000].map((x) => gen.biomeAtX(x)) };
  }
  for (const seed of SEEDS.slice(0, 4)) {
    for (const mask of [2, ALL]) {
      test(`seed ${seed} mask ${mask}: add/remove log, heights, rolling-sled outcome`, () => {
        const plain = streamRun(seed, mask, 'none');
        expect(streamRun(seed, mask, 'on')).toEqual(plain);
        expect(streamRun(seed, mask, 'off')).toEqual(plain);
      });
    }
  }
});

describe('RunScene._updateLook: the generator-owed repaints are unchanged, the dissolve only adds graphics repaints', () => {
  const content = loadContent();

  function walk(seed, mask, reduced) {
    const gen = makeGen(seed, { biomeMask: mask });
    const calls = [];
    const owed = []; // x of every generator biome change that owes a repaint (what the world did before the dissolve existed)
    const touched = new Set();
    const terrain = new Proxy(gen, {
      get(t, k) {
        if (typeof k === 'string' && typeof t[k] === 'function') touched.add(k);
        const v = t[k];
        return typeof v === 'function' ? v.bind(t) : v;
      },
    });
    const s = Object.create(RunScene.prototype);
    Object.assign(s, {
      terrain, sled: { x: 0 }, content: { biomes: content.biomes },
      registry: { get: (k) => (k === REG.SETTINGS ? { reduceMotion: reduced ? 'on' : 'off' } : null) },
    });
    // Since #140 refreshPalette repaints graphics only (colliders are never touched), so a call is always collider-safe.
    s.refreshPalette = function refresh() { calls.push({ x: this.sled.x, look: this._lookId }); };
    const veils = [];
    for (let x = 0; x < 2800 * 20; x += 20) {
      s.sled.x = x;
      const biomeNow = gen.biomeAtX(x);
      const changed = s._biomeId !== biomeNow;
      const first = s._biomeId === undefined;
      if (changed) s._biomeId = biomeNow;
      const def = s._biomeDefById(biomeNow);
      if (changed && (def !== null || !first)) owed.push(x);
      s._updateLook(biomeNow, changed && (def !== null || !first));
      veils.push(s._veil);
    }
    return { calls, owed, touched, veils, gen };
  }

  for (const [seed, mask] of [['shots65-d', 2], ['alpha', ALL], ['bitstream-bluffs', ALL]]) {
    test(`seed ${seed} mask ${mask}`, () => {
      const on = walk(seed, mask, false);
      const off = walk(seed, mask, true);
      expect(on.owed.length).toBeGreaterThan(2);
      expect(on.owed).toEqual(off.owed); // the generator's biome changes do not depend on the effects setting
      expect(off.calls.map((c) => c.x)).toEqual(off.owed); // the hard cut repaints exactly where the world always did
      for (const x of on.owed) expect(on.calls.map((c) => c.x)).toContain(x); // the dissolve never skips one
      expect(on.calls.length).toBeGreaterThan(on.owed.length); // and repaints (graphics only) inside bridges as well
      // the generator is only ever read
      for (const name of on.touched) expect(['biomeAtX', 'bridgeSpanAt']).toContain(name);
      // reduced motion: the veil is on for exactly the bridge, never partial
      expect(off.veils.every((v) => v === 0 || v === 1)).toBe(true);
      expect(on.veils.some((v) => v > 0 && v < 1)).toBe(true);
    });
  }

  test('the real generator is left untouched by a whole walk (same digests as a fresh one)', () => {
    const { gen } = walk('shots65-d', 2, false);
    const fresh = makeGen('shots65-d', { biomeMask: 2 });
    for (let i = 0; i < 60; i++) expect(digest(completeOf(gen.getChunk(i)))).toBe(digest(completeOf(fresh.getChunk(i))));
  });
});/**
 * W3 — the biome mask in saved data (D6: seed-best and daily-best compare only within the same mask).
 *
 * The rules that matter here are about old data, not new data: a record written before this campaign
 * has no `biomeMask`, must still load, must keep its ledger hash, and must count as mask 0. Anything
 * that reinterprets an existing run would silently rewrite somebody's leaderboard.
 */
import { SaveStore, sanitizeRun, parseSeedMask } from '../../src/systems/SaveStore.js';
import { DailyPatch } from '../../src/systems/DailyPatch.js';
import { toggleBiome, biomeToggleRows } from '../../src/systems/ProfileStore.js';
import { STORAGE } from '../../src/constants.js';
import { readDir } from './_helpers.js';
const BIOME_DEFS = readDir('biomes');

// Fixed id: the ledger hash covers id, so a fixture whose id varies with its fields would make the
// "mask does not enter the hash" assertion below pass or fail for the wrong reason.
const run = (over = {}) => ({
  version: 1, id: 'r-fixed', seed: 'alpha',
  dailyRuleId: '', startedAt: 1, endedAt: 2, durationMs: 1000, score: 100, distanceM: 10,
  trickPoints: 0, tricks: {}, bestCombo: 1, maxAirtimeMs: 0, cause: 'crash', ledgerHash: 'abcd1234',
  ...over,
});

describe('biomeMask in run records', () => {
  test('a record from before this campaign has no mask and is unchanged by sanitising', () => {
    const old = run();
    expect('biomeMask' in old).toBe(false);
    const out = sanitizeRun(old);
    // Absent, not zero: writing 0 into every historical run would rewrite stored data for no reason.
    expect('biomeMask' in out).toBe(false);
    expect(out.ledgerHash).toBe('abcd1234');
    expect(out.version).toBe(STORAGE.saveVersion);
  });

  test('a mask survives sanitising and is coerced to a non-negative integer', () => {
    expect(sanitizeRun(run({ biomeMask: 21 })).biomeMask).toBe(21);
    expect(sanitizeRun(run({ biomeMask: 0 })).biomeMask).toBe(0);
    expect(sanitizeRun(run({ biomeMask: 5.9 })).biomeMask).toBe(5);
    for (const bad of [-1, NaN, Infinity, '7', null]) {
      expect({ bad, has: 'biomeMask' in sanitizeRun(run({ biomeMask: bad })) })
        .toMatchObject({ bad, has: false });
    }
  });

  test('the mask does NOT enter the ledger hash and saveVersion is not bumped', () => {
    // Both are hard constraints of the campaign: existing saved runs must stay valid, and a version
    // bump would force a migration on every device.
    expect(STORAGE.saveVersion).toBe(1);
    const a = run();
    const b = run({ biomeMask: 16 });
    expect(SaveStore.computeLedgerHash(b)).toBe(SaveStore.computeLedgerHash(a));
  });
});

describe('mask-scoped seed and daily stats', () => {
  const store = (runs) => {
    const s = new SaveStore({ storage: null }); // memory fallback: no localStorage in Jest
    s.runs = runs;
    return s;
  };

  test('seed stats separate masks, and old records count as mask 0', () => {
    const s = store([
      run({ id: 'old', seed: 'alpha', score: 500, distanceM: 50 }), // pre-W3: no field
      run({ id: 'm0', seed: 'alpha', score: 100, distanceM: 10, biomeMask: 0 }),
      run({ id: 'm1', seed: 'alpha', score: 900, distanceM: 90, biomeMask: 1 }),
    ]);
    expect(s.getSeedStats('alpha', { biomeMask: 0 })).toMatchObject({ attempts: 2, bestScore: 500 });
    expect(s.getSeedStats('alpha', { biomeMask: 1 })).toMatchObject({ attempts: 1, bestScore: 900 });
    expect(s.getSeedStats('alpha', { biomeMask: 2 })).toBeNull();
  });

  test('omitting the mask keeps the pre-W3 behaviour of comparing every run', () => {
    // The leaderboard and the legacy tests call this without a mask; that must not silently start
    // ignoring runs.
    const s = store([
      run({ id: 'old', seed: 'alpha', score: 500, distanceM: 50 }),
      run({ id: 'm1', seed: 'alpha', score: 900, distanceM: 90, biomeMask: 1 }),
    ]);
    expect(s.getSeedStats('alpha')).toMatchObject({ attempts: 2, bestScore: 900, bestDistanceM: 90 });
  });

  test('daily stats count only official Daily runs on the date\'s mask (decisions 1/2)', () => {
    // Replaces the old "scoped by the daily seed, which already fixes the mask" test. That rule let a
    // typed `daily-<date>@mask` run, or one replayed from SHARE SEED at another mask, become TODAY'S BEST
    // (audit F1). Marvin's decisions: Daily bests are scoped by gameplay mask, and only a run started from
    // the DAILY RUN item is official. A legacy record (no hashV) counts only on the date's mask and rule,
    // so a pre-W3 record with no mask field no longer counts on a day whose derived mask is non-zero.
    let when = null;
    for (let i = 0; i < 30 && !when; i++) {
      const d = new Date(Date.UTC(2026, 10, 13 + i, 12));
      if (DailyPatch.biomeMaskForDate(d) !== 0) when = d;
    }
    expect(when).not.toBeNull();
    const dateKey = when.toISOString().slice(0, 10);
    const info = DailyPatch.infoForDateKey(dateKey);
    const s = store([
      // A record written before this campaign existed: no biomeMask field at all (mask 0 != the date's).
      run({ id: 'd-old', seed: `daily-${dateKey}`, score: 900, distanceM: 90, dailyRuleId: info.rule.id }),
      // A typed run at another mask: practice, not the Daily.
      run({ id: 'd-new', seed: `daily-${dateKey}`, score: 300, distanceM: 30, biomeMask: 3, dailyRuleId: info.rule.id }),
      // A legacy record on the date's own mask and rule: kept (real Daily history).
      run({ id: 'd-legacy', seed: `daily-${dateKey}`, score: 200, distanceM: 20, biomeMask: info.biomeMask, dailyRuleId: info.rule.id }),
      // A new official run from the DAILY RUN item.
      run({ id: 'd-off', seed: `daily-${dateKey}`, score: 250, distanceM: 25, biomeMask: info.biomeMask, dailyRuleId: info.rule.id, hashV: 2, dailyOfficial: true }),
      run({ id: 'd-other', seed: 'daily-1999-01-01', score: 9999 }),
    ]);
    expect(s.getDailyStats(when)).toMatchObject({ attempts: 2, bestScore: 250, dateKey });
  });
});

describe('daily mask derivation (D6)', () => {
  test('is a pure function of the date: same day, same mask, every caller', () => {
    const d = new Date('2026-11-13T00:00:01Z');
    expect(DailyPatch.biomeMaskForDate(d)).toBe(DailyPatch.biomeMaskForDate(new Date(d.getTime())));
    // Accepts epoch ms as well as a Date.
    expect(DailyPatch.biomeMaskForDate(d.getTime())).toBe(DailyPatch.biomeMaskForDate(d));
  });

  test('is independent of unlocks — a locked biome can appear as a preview', () => {
    // Nothing about the player is an input. This is the whole of D6's "same for every player".
    const masks = new Set();
    for (let i = 0; i < 9; i++) masks.add(DailyPatch.biomeMaskForDate(new Date(Date.UTC(2026, 9, 1 + i))));
    expect([...masks].sort((a, b) => a - b)).toEqual([0, 1, 2, 4, 8, 16]);
  });

  // Before the decision-5 cutover (2026-11-17); the 15-day rotation after it is pinned in daily-w6-rotation.test.js.
  test('mostly mask 0, and cycles rather than drifting', () => {
    const masks = [];
    for (let i = 0; i < 9; i++) masks.push(DailyPatch.biomeMaskForDate(new Date(Date.UTC(2026, 9, 1 + i))));
    expect(masks.filter((m) => m === 0).length).toBe(4);
    // 9-day cycle: the mask repeats exactly 9 days later, so there is no drift.
    for (let i = 0; i < 9; i++) {
      const a = DailyPatch.biomeMaskForDate(new Date(Date.UTC(2026, 9, 1 + i)));
      const b = DailyPatch.biomeMaskForDate(new Date(Date.UTC(2026, 9, 10 + i)));
      expect({ i, b }).toMatchObject({ i, b: a });
    }
  });

  test('an invalid input falls back instead of throwing', () => {
    expect(Number.isFinite(DailyPatch.biomeMaskForDate(new Date('nope')))).toBe(true);
    expect(Number.isFinite(DailyPatch.biomeMaskForDate(undefined))).toBe(true);
  });
});

describe('seed@mask entry (W3)', () => {
  const DEFS = [{ bit: 1 }, { bit: 2 }, { bit: 4 }, { bit: 8 }, { bit: 16 }];

  test('a bare seed is mask 0 and is used verbatim', () => {
    // Every seed string that existed before W3 must keep meaning exactly what it meant.
    for (const seed of ['alpha', 'bitstream-bluffs', '2026-11-13', 'with space', 'UPPER']) {
      expect(parseSeedMask(seed, DEFS)).toEqual({ seed, biomeMask: 0, hadSuffix: false });
    }
  });

  test('a numeric suffix selects a mask', () => {
    expect(parseSeedMask('alpha@1', DEFS)).toEqual({ seed: 'alpha', biomeMask: 1, hadSuffix: true });
    expect(parseSeedMask('alpha@21', DEFS)).toEqual({ seed: 'alpha', biomeMask: 21, hadSuffix: true });
    expect(parseSeedMask('  alpha@16  ', DEFS)).toEqual({ seed: 'alpha', biomeMask: 16, hadSuffix: true });
  });

  test('unknown bits are dropped, because a mask bit with no biome is unplayable terrain', () => {
    // 999 has bits outside the five batch-1 biomes (bits 0-4); only 1|2|4 survive.
    expect(parseSeedMask('alpha@999', DEFS)).toEqual({ seed: 'alpha', biomeMask: 7, hadSuffix: true });
  });

  test('anything that is not a clean suffix is treated as a seed, not rejected', () => {
    // A seed is arbitrary player text; silently refusing it would lose the run they asked for.
    for (const raw of ['alpha@', '@5', 'a@b', 'alpha@x', 'alpha @ 5', '']) {
      expect({ raw, out: parseSeedMask(raw, DEFS).biomeMask }).toMatchObject({ raw, out: 0 });
    }
  });

  test('empty input does not throw', () => {
    expect(parseSeedMask(undefined, DEFS)).toEqual({ seed: '', biomeMask: 0, hadSuffix: false });
    expect(parseSeedMask(null, DEFS)).toEqual({ seed: '', biomeMask: 0, hadSuffix: false });
    expect(parseSeedMask(42, DEFS)).toEqual({ seed: '', biomeMask: 0, hadSuffix: false });
  });
});

describe('profile biome toggles (W3, default ON since issue #65)', () => {
  const DEFS = [
    { id: 'debutmont', bit: 1, name: 'Debutmont', unlockLevel: 1 },
    { id: 'garbage-dump-glacier', bit: 2, name: 'Garbage Dump Glacier', unlockLevel: 7 },
    { id: 'pyramid-peak', bit: 4, name: 'Pyramid Peak', unlockLevel: 10 },
  ];
  const prof = (over = {}) => ({
    v: 1, xp: 0, level: 7, bank: 0, biomeOff: 0,
    pendingBiomes: ['debutmont', 'garbage-dump-glacier'],
    unlocked: { biomes: [], cosmetics: [], boosts: {} },
    ...over,
  });

  test('toggles an unlocked biome OFF and back ON through biomeOff', () => {
    const a = toggleBiome(prof(), 'garbage-dump-glacier', DEFS);
    expect(a.biomeOff).toBe(2);
    expect(toggleBiome(a, 'garbage-dump-glacier', DEFS).biomeOff).toBe(0);
  });

  test('refuses a biome the player has not unlocked', () => {
    // A toggle that honoured a locked bit would hand a low-level profile terrain it never earned.
    const p = prof();
    expect(toggleBiome(p, 'pyramid-peak', DEFS)).toBe(p);
    expect(toggleBiome(p, 'pyramid-peak', DEFS).biomeOff).toBe(0);
  });

  test('refuses the base biome: Debutmont cannot be turned off', () => {
    const p = prof();
    expect(toggleBiome(p, 'debutmont', DEFS)).toBe(p);
  });

  test('is pure and never mutates the profile it was given', () => {
    const p = prof();
    const before = JSON.stringify(p);
    toggleBiome(p, 'garbage-dump-glacier', DEFS);
    expect(JSON.stringify(p)).toBe(before);
  });

  test('an unknown id is a no-op, not a throw', () => {
    const p = prof();
    for (const bad of ['nope', '', null, undefined, 42]) {
      expect(toggleBiome(p, bad, DEFS)).toBe(p);
    }
  });

  test('toggling one biome leaves the others alone', () => {
    // Pyramid Peak unlocked and already explicitly OFF (bit 4).
    const p = prof({ biomeOff: 4, pendingBiomes: ['debutmont', 'garbage-dump-glacier', 'pyramid-peak'] });
    // Turning the glacier OFF adds bit 2 and leaves Pyramid Peak's OFF bit alone.
    expect(toggleBiome(p, 'garbage-dump-glacier', DEFS).biomeOff).toBe(6);
    // Turning Pyramid Peak back ON clears only its own bit.
    expect(toggleBiome(p, 'pyramid-peak', DEFS).biomeOff).toBe(0);
  });

  test('rows list every switchable biome in unlock order with its state, and omit the base biome', () => {
    const rows = biomeToggleRows(
      prof({ biomeOff: 4, pendingBiomes: ['debutmont', 'garbage-dump-glacier', 'pyramid-peak'] }),
      DEFS.slice().reverse(), // input order must not leak into display order
    );
    expect(rows.map((r) => r.id)).toEqual(['garbage-dump-glacier', 'pyramid-peak']);
    expect(rows[0]).toMatchObject({ unlocked: true, enabled: true });
    expect(rows[1]).toMatchObject({ unlocked: true, enabled: false });
  });

  test('a locked biome never shows as enabled, even if its bit is set', () => {
    // Defence in depth: a locked biome is never "on", whatever the profile carries.
    const rows = biomeToggleRows(prof({ biomeOff: 0, level: 1, pendingBiomes: ['debutmont'] }), DEFS);
    expect(rows.find((r) => r.id === 'pyramid-peak')).toMatchObject({ unlocked: false, enabled: false });
  });
});

describe('D6 at the Game Over call site', () => {
  // The rule is already tested on SaveStore. What can silently break is the CALLER: GameOverScene must
  // pass the scope, or a mask-31 run is judged against mask-0 runs and reports a SEED BEST it never
  // set. This pins the scene's side of the contract rather than re-testing the store.
  const store = (runs) => {
    const s = new SaveStore({ storage: null });
    s.runs = runs;
    return s;
  };

  test('a mask-31 run sees no best from a mask-0 run on the same seed', () => {
    const s = store([
      run({ id: 'm0', seed: 'letterkenny', score: 5000, biomeMask: 0 }),
    ]);
    // What the scene asks for when the run being shown is mask 31:
    expect(s.getSeedStats('letterkenny', { biomeMask: 31 })).toBeNull();
    // And what it used to ask for (no scope), which would wrongly report 5000 as the bar to beat:
    expect(s.getSeedStats('letterkenny').bestScore).toBe(5000);
  });

  test('a pre-W3 run with no field is mask 0, so it still supplies a best for mask-0 play', () => {
    const s = store([run({ id: 'old', seed: 'letterkenny', score: 4200 })]);
    expect(s.getSeedStats('letterkenny', { biomeMask: 0 }).bestScore).toBe(4200);
    expect(s.getSeedStats('letterkenny', { biomeMask: 1 })).toBeNull();
  });

  test('the shareable seed carries the mask suffix only when the mask is not 0', () => {
    // Same rule GameOverScene applies to the SHARE SEED line: mask 0 stays suffix-free so every
    // existing seed string is unchanged; a non-zero mask round-trips through the entry parser.
    const shown = (rec) => (Number(rec.biomeMask) || 0 ? `${rec.seed}@${Number(rec.biomeMask)}` : String(rec.seed));
    expect(shown({ seed: 'letterkenny' })).toBe('letterkenny');
    expect(shown({ seed: 'letterkenny', biomeMask: 0 })).toBe('letterkenny');
    const withMask = shown({ seed: 'letterkenny', biomeMask: 31 });
    expect(withMask).toBe('letterkenny@31');
    // And it parses back to the same seed + mask, which is what makes it shareable.
    expect(parseSeedMask(withMask, BIOME_DEFS)).toEqual({ seed: 'letterkenny', biomeMask: 31, hadSuffix: true });
  });
});/**
 * W3 — biome-tied missions must be offerable to a normal credited profile.
 *
 * Luna's round-2 finding #5: `isOfferable` read `profile.unlocked.biomes`, which nothing populates,
 * and `profile.biomeOrder`, which nothing sets. So on a real profile both checks were vacuous or
 * fatal: a level-12 profile carrying three `pendingBiomes` had an empty `unlocked.biomes` list and
 * drew 0/500 biome missions. Manually filling `unlocked.biomes` made 62/500 appear — proof the gate
 * was the only thing blocking them.
 *
 * The subtle half is the mask check. Luna's `biomeOrder` bypass meant that with no order the mask was
 * never consulted at all, so a profile that had switched every signature OFF could still be offered
 * biome missions for terrain it would never see. Both halves are pinned here.
 *
 * Issue #65: unlocked biomes default ON, so the profile carries explicit OFF choices (`biomeOff`) rather than
 * an opt-in mask, and the base biome (Debutmont) has no bit in play: it is always eligible.
 */
import { isOfferable } from '../../src/systems/Missions.js';
import { earnedBiomeIds } from '../../src/systems/ProfileStore.js';

const BIOME_DEFS = [
  { id: 'debutmont', bit: 1, unlockLevel: 1 },
  { id: 'garbage-dump-glacier', bit: 2, unlockLevel: 3 },
  { id: 'pyramid-peak', bit: 4, unlockLevel: 6 },
  { id: 'underwater-mountain', bit: 8, unlockLevel: 10 },
  { id: 'crystal-cavern', bit: 16, unlockLevel: 12 },
];

/** A credited profile as the game actually stores one: pendingBiomes derived, unlocked.biomes empty. */
const credited = (level, off = 0) => ({
  v: 1, xp: 0, level, bank: 0, biomeOff: off,
  pendingBiomes: BIOME_DEFS.filter((d) => d.unlockLevel <= level).map((d) => d.id),
  unlocked: { biomes: [], cosmetics: [], boosts: {} },
  missions: { counter: 0, active: [], progress: {} }, achievements: {}, credited: [],
});

const missionFor = (biome) => ({ id: `m-${biome}`, biome, tier: 2, metric: 'distance', target: 100, xp: 10 });

describe('biome missions reach a real profile', () => {
  test("a credited profile's earned biomes are not an empty list", () => {
    const p = credited(12);
    // The two reads that must agree. `unlocked.biomes` being empty is exactly why the old gate failed.
    expect(p.unlocked.biomes).toEqual([]);
    expect(earnedBiomeIds(p, BIOME_DEFS)).toEqual([
      'debutmont', 'garbage-dump-glacier', 'pyramid-peak', 'underwater-mountain', 'crystal-cavern',
    ]);
  });

  test('a mission for an earned biome is offerable', () => {
    const p = credited(12);
    expect(isOfferable(missionFor('crystal-cavern'), p, 'r1', BIOME_DEFS)).toBe(true);
  });

  test('a mission for a biome above the level is still refused', () => {
    // Unlock is earned, not merely enabled: a level-3 profile cannot be offered a level-12 biome.
    const p = credited(3);
    expect(isOfferable(missionFor('crystal-cavern'), p, 'r1', BIOME_DEFS)).toBe(false);
    expect(isOfferable(missionFor('debutmont'), p, 'r1', BIOME_DEFS)).toBe(true);
  });

  test('a mission for a switched-OFF signature is refused', () => {
    // Luna's biomeOrder bypass: with no order array the mask was never consulted, so this passed.
    const p = credited(12, 16); // crystal-cavern explicitly OFF, everything else on
    expect(isOfferable(missionFor('crystal-cavern'), p, 'r1', BIOME_DEFS)).toBe(false);
    expect(isOfferable(missionFor('pyramid-peak'), p, 'r1', BIOME_DEFS)).toBe(true);
  });

  test('every switchable biome OFF offers no missions for them, but the base biome stays eligible', () => {
    const p = credited(12, 2 | 4 | 8 | 16);
    for (const d of BIOME_DEFS) {
      expect({ id: d.id, offerable: isOfferable(missionFor(d.id), p, 'r1', BIOME_DEFS) })
        .toMatchObject({ id: d.id, offerable: d.id === 'debutmont' });
    }
  });

  test('a fresh default-ON profile is offered missions for every unlocked biome', () => {
    const p = credited(12);
    for (const d of BIOME_DEFS) {
      expect({ id: d.id, offerable: isOfferable(missionFor(d.id), p, 'r1', BIOME_DEFS) })
        .toMatchObject({ id: d.id, offerable: true });
    }
  });

  test('backwards compatibility: the old two-argument call keeps working', () => {
    // Every existing caller and test passes no defs. Without them the mask cannot be resolved to ids,
    // so the gate must still fail closed for a biome the profile demonstrably has not earned.
    const p = credited(12);
    expect(isOfferable(missionFor('crystal-cavern'), p, 'r1')).toBe(true);
    expect(isOfferable(missionFor('crystal-cavern'), credited(1), 'r1')).toBe(false);
  });

  test('non-biome missions are unaffected', () => {
    const plain = { id: 'm-plain', tier: 1, metric: 'distance', target: 100, xp: 10 };
    expect(isOfferable(plain, credited(1), 'r1', BIOME_DEFS)).toBe(true);
  });

  test('an excluded rule still wins over a biome mission', () => {
    const t = { ...missionFor('debutmont'), excludedRuleIds: ['r1'] };
    expect(isOfferable(t, credited(12), 'r1', BIOME_DEFS)).toBe(false);
  });
});/**
 * W3 — biome palette overrides must actually reach the renderer.
 *
 * The gap this file exists for: every biome JSON shipped with `palettes.default` and
 * `palettes.colorblind`, and the per-biome screenshot gate passed — because those shots differ by the
 * GLOBAL palette setting, not by the biome. Nothing read `content.biomes[*].palettes` at all, so all
 * five biomes rendered identically to base terrain and the screenshots could not tell.
 */
import { withBiomePalette } from '../../src/ui/Palette.js';
import { readDir } from './_helpers.js';

const BIOMES = readDir('biomes');
const BASE = {
  bg: '#000010', bgAlt: '#000020', cyan: '#00ffff', magenta: '#ff00ff',
  lime: '#00ff00', amber: '#ffaa00', text: '#ffffff', danger: '#ff0000',
};

describe('withBiomePalette', () => {
  test('a biome override replaces the keys it names', () => {
    const out = withBiomePalette(BASE, { palettes: { default: { cyan: '#8fd8ff' } } }, 'default');
    expect(out.cyan).toBe('#8fd8ff');
  });

  test('keys the biome does not name keep the active palette', () => {
    const out = withBiomePalette(BASE, { palettes: { default: { cyan: '#8fd8ff' } } }, 'default');
    expect(out.text).toBe(BASE.text);
    expect(out.bg).toBe(BASE.bg);
  });

  test('danger can never be overridden, by any biome, in any palette', () => {
    // Hazards must read as hazards everywhere. A biome that recoloured danger would make danger look
    // safe, which is the one cosmetic change that alters how the game plays.
    for (const b of BIOMES) {
      for (const pal of ['default', 'colorblind']) {
        const hostile = { palettes: { [pal]: { danger: '#00ff00' } } };
        expect({ id: b.id, pal, danger: withBiomePalette(BASE, hostile, pal).danger })
          .toMatchObject({ id: b.id, pal, danger: BASE.danger });
      }
    }
  });

  test('a colorblind player keeps the colorblind base for untouched keys', () => {
    // The failure mode: a biome supplying a "full" palette would silently undo the accessibility
    // setting. Overrides are merged, never swapped in whole.
    const cbBase = { ...BASE, cyan: '#9ccbe8', lime: '#e8e0b0' };
    const out = withBiomePalette(cbBase, { palettes: { default: { bg: '#111111' } } }, 'colorblind');
    expect(out.cyan).toBe('#9ccbe8');
    expect(out.lime).toBe('#e8e0b0');
    expect(out.bg).toBe(cbBase.bg); // the biome named no colorblind override
  });

  test('a biome with no palettes block leaves the palette untouched', () => {
    expect(withBiomePalette(BASE, null, 'default')).toEqual(BASE);
    expect(withBiomePalette(BASE, {}, 'default')).toEqual(BASE);
    expect(withBiomePalette(BASE, { palettes: {} }, 'default')).toEqual(BASE);
  });

  test('a malformed colour is ignored rather than rendered', () => {
    const out = withBiomePalette(BASE, { palettes: { default: { cyan: 'not-a-colour', lime: '#12345' } } }, 'default');
    expect(out.cyan).toBe(BASE.cyan);
    expect(out.lime).toBe(BASE.lime);
  });

  test('it does not mutate the base palette', () => {
    const copy = { ...BASE };
    withBiomePalette(BASE, { palettes: { default: { cyan: '#8fd8ff' } } }, 'default');
    expect(BASE).toEqual(copy);
  });

  test('every shipped biome actually declares both palettes, and they differ from base', () => {
    // If a biome's override equalled base for every key it would be a no-op dressed as content.
    for (const b of BIOMES) {
      expect({ id: b.id, has: Boolean(b.palettes && b.palettes.default && b.palettes.colorblind) })
        .toMatchObject({ id: b.id, has: true });
      const def = withBiomePalette(BASE, b, 'default');
      const moved = Object.keys(def).filter((k) => def[k] !== BASE[k]);
      expect({ id: b.id, moved: moved.length > 0 }).toMatchObject({ id: b.id, moved: true });
    }
  });
});/**
 * B1 (biome full treatment): the amended SLOT RULE (spec §4, amended by CC Friday 2026-11-14 from B0 evidence).
 *
 * B0 showed that past 2 km the base 480 px hazard spacing leaves almost no free ground slot for a biome hazard. So a
 * biome chunk whose free scan found no slot may REPLACE ONE existing base ground hazard with its biome hazard:
 *   - the choice comes from the 'biomeHaz' fork with a fixed draw count (the slot's 5th draw), so base streams are
 *     untouched and BIOME_SLOT_DRAWS is unchanged;
 *   - it happens only when the biome footprint fits within the replaced box + BIOME_REPLACE_SLACK_PX (8 px) in both w and
 *     h, so the shard and power-up clearances computed around the base hazard still hold;
 *   - the replaced spot must still pass every biome ground rule (slope, lips, gaps, power-ups, shards with the NEW size,
 *     crash-safe distance, `slow` only before a descent).
 * The fixtures stand in for real content so this file tests the engine, not the B1 tuning.
 */
import crypto from 'crypto';
import { makeGen, loadContent, readDir } from './_helpers.js';
import { FX_GROUND_HAZARD, FX_AIR_HAZARD, FX_WARD_POWERUP, FX_STABILIZE_POWERUP, FX_MASK } from './_biomeFixtures.js';
import { BIOME_SLOT_DRAWS, BIOME_REPLACE_SLACK_PX, SPACING_PX, BIOME_EDGE_MARGIN_PX } from '../../src/systems/TerrainGenerator.js';

const content = loadContent();
/** Shipped content WITHOUT any biome-tagged def (the engine under test, not the B1 tuning). */
const baseOf = (o) => Object.fromEntries(Object.entries(o).filter(([, d]) => !d.biome));
const BASE_H = baseOf(content.hazards);
const BASE_P = baseOf(content.powerups);
const ALL = readDir('biomes').reduce((m, b) => m | b.bit, 0);
const snap = (c) => JSON.parse(JSON.stringify(c));
const clone = (d) => JSON.parse(JSON.stringify(d));

/** Generator with base content plus the given biome hazard defs (power-up fixtures always on). */
function gen(seed, hazards = [FX_GROUND_HAZARD, FX_AIR_HAZARD], mask = FX_MASK) {
  return makeGen(seed, {
    biomeMask: mask,
    hazardDefs: { ...BASE_H, ...Object.fromEntries(hazards.map((d) => [d.id, clone(d)])) },
    powerupDefs: { ...BASE_P, [FX_WARD_POWERUP.id]: clone(FX_WARD_POWERUP), [FX_STABILIZE_POWERUP.id]: clone(FX_STABILIZE_POWERUP) },
  });
}
const baseGen = (seed, mask = FX_MASK) => makeGen(seed, { biomeMask: mask, hazardDefs: BASE_H, powerupDefs: BASE_P });
const chunksOf = (g, n) => Array.from({ length: n }, (_, i) => snap(g.getChunk(i)));

// re-pinned for #65: Debutmont base + arcade bridges. Two more seeds: every biome sector now opens with an arcade
// bridge (about a fifth of its chunks), so four seeds no longer yield the >150 ground-eligible / >10 slow-hazard
// samples the share and fairness tests below need. The tests' bands are unchanged; only the sample grew.
const SEEDS = ['slot-alpha', 'slot-beta', 'slot-gamma', 'slot-delta', 'slot-epsilon', 'slot-zeta'];
const N = 300;

describe('slot rule: base streams untouched', () => {
  test('with biome defs absent, nothing changes at ANY mask (digests pinned at 00978f6, before the slot rule)', () => {
    // First recorded on 00978f6 (v2.5.0, B0) with the same projection: 2 seeds x 200 chunks of JSON.stringify(getChunk(i)).
    // re-pinned for #65 on the #121 (portable math) build: Debutmont base + arcade bridges (all five digests moved: base terrain is now Debutmont, and
    // biome changes are bridged). Mask 1 is the home bit, so it is the same terrain as mask 0.
    const PINNED = { 1: '2af6aff54f97d978', 2: 'f6f6494742aa0b4a', 8: '8dd6019a1fa4c387', 64: '938d3837e2932a36', [ALL]: 'f29bc0ae347569af' };
    // Audit T2 (v2.6.x) moved Micro Mountain's dew swell INTO the chunk points on purpose, so the ALL mask (it contains
    // Micro, bit 512) now has other bytes. To keep this pin about the slot rule, the masks are hashed with the swell
    // stripped from content: that reproduces the 00978f6 bytes exactly, so nothing else moved. The shipped-content
    // digest of the ALL mask is pinned separately below.
    const preT2Mods = { ...content.terrainMods, dewSwell: { ...content.terrainMods.dewSwell } };
    delete preT2Mods.dewSwell.terrainSwell;
    const digestOf = (mask, modDefs) => {
      const parts = [];
      for (const seed of ['slot-a', 'slot-b']) {
        const g = makeGen(seed, { biomeMask: mask, hazardDefs: BASE_H, powerupDefs: BASE_P, modDefs });
        for (let i = 0; i < 200; i++) parts.push(JSON.stringify(g.getChunk(i)));
      }
      return crypto.createHash('sha256').update(parts.join('|')).digest('hex').slice(0, 16);
    };
    const out = {};
    for (const mask of Object.keys(PINNED).map(Number)) out[mask] = digestOf(mask, preT2Mods);
    expect(out).toEqual(Object.fromEntries(Object.entries(PINNED).map(([k, v]) => [Number(k), v])));
    // Masks without Micro are byte-identical with the shipped content too (the swell only touches dewSwell zones)...
    for (const mask of [1, 2, 8, 64]) expect(digestOf(mask, content.terrainMods)).toBe(PINNED[mask]);
    // ...and the ALL mask with the shipped (swelled) content, recorded after audit T2.
    expect(digestOf(ALL, content.terrainMods)).toBe('6ed38294c7a8466d'); // re-pinned for #65: Debutmont base + arcade bridges (on the #121 pmath build)
  });

  test('the slot keeps a fixed draw count: BIOME_SLOT_DRAWS is still 5', () => {
    expect(BIOME_SLOT_DRAWS).toBe(5);
    expect(BIOME_REPLACE_SLACK_PX).toBe(8);
  });
});

describe('slot rule: replacing one base ground hazard', () => {
  const runs = SEEDS.map((s) => ({ fx: chunksOf(gen(s), N), base: chunksOf(baseGen(s), N) }));
  const isFx = (h) => h.defId === FX_GROUND_HAZARD.id;

  test('replacements happen, and each one swaps a base GROUND hazard in place (same x, y, rotation) for the biome def', () => {
    let replaced = 0;
    for (const { fx, base } of runs) {
      for (let i = 0; i < N; i++) {
        const h = fx[i].hazards.find(isFx);
        if (!h) continue;
        const was = base[i].hazards.find((q) => q.x === h.x);
        if (!was) continue;
        replaced++;
        expect({ x: h.x, y: h.y, rotationDeg: h.rotationDeg }).toEqual({ x: was.x, y: was.y, rotationDeg: was.rotationDeg });
        expect(content.hazards[was.defId].placement).not.toBe('air');
        expect(content.hazards[was.defId].biome).toBeUndefined();
      }
    }
    expect(replaced).toBeGreaterThan(20); // fewer since amendment (a) frees more slots: 28 measured
  });

  test('every other hazard, power-up, shard, zone and point of the chunk is unchanged; at most one base hazard per chunk is replaced', () => {
    for (const { fx, base } of runs) {
      for (let i = 0; i < N; i++) {
        const a = fx[i];
        const b = base[i];
        expect(a.points).toEqual(b.points);
        expect(a.zones).toEqual(b.zones);
        expect(a.shards).toEqual(b.shards);
        expect(a.powerups.filter((p) => !p.defId.startsWith('fx'))).toEqual(b.powerups);
        const own = a.hazards.filter((h) => !h.defId.startsWith('fx'));
        const lost = b.hazards.filter((h) => !own.some((q) => q.x === h.x && q.defId === h.defId));
        expect(lost.length).toBeLessThanOrEqual(1);
        for (const h of own) expect(b.hazards).toContainEqual(h);
        if (lost.length) {
          // the lost base hazard is exactly where the biome hazard now is: a swap, never a removal
          const h = a.hazards.find(isFx);
          expect(h && h.x).toBe(lost[0].x);
        }
      }
    }
  });

  test('footprint rule: the biome box fits within the replaced box + 8 px (w and h)', () => {
    for (const { fx, base } of runs) {
      for (let i = 0; i < N; i++) {
        const h = fx[i].hazards.find(isFx);
        const was = h && base[i].hazards.find((q) => q.x === h.x);
        if (!was) continue;
        const s = content.hazards[was.defId].size;
        expect(FX_GROUND_HAZARD.size.w).toBeLessThanOrEqual(s.w + BIOME_REPLACE_SLACK_PX);
        expect(FX_GROUND_HAZARD.size.h).toBeLessThanOrEqual(s.h + BIOME_REPLACE_SLACK_PX);
      }
    }
  });

  test('footprint rule: a biome hazard too big for every base box is never placed by replacement', () => {
    const big = { ...clone(FX_GROUND_HAZARD), size: { w: 80, h: 60 } };
    let free = 0;
    for (const seed of SEEDS) {
      const a = chunksOf(gen(seed, [big, FX_AIR_HAZARD]), N);
      const b = chunksOf(baseGen(seed), N);
      for (let i = 0; i < N; i++) {
        const h = a[i].hazards.find(isFx);
        if (!h) continue;
        free++;
        expect(b[i].hazards.some((q) => q.x === h.x)).toBe(false);
        expect(a[i].hazards.filter((q) => !isFx(q))).toEqual(b[i].hazards);
      }
    }
    expect(free).toBeGreaterThanOrEqual(1);
  });

  test('a `slow` biome hazard keeps its fairness rule on swapped and free slots: descent ahead below 0.6, no climb ahead from 0.6', () => {
    // B1 presence amendment (b): speedFactor < 0.6 needs a descent ahead; a gentler slow needs no climbing segment ahead.
    for (const [k0, needDescent] of [[0.5, true], [0.7, false]]) {
      const slow = { ...clone(FX_GROUND_HAZARD), id: 'fxGroundHazard', onHit: { effect: 'slow', durationMs: 900, speedFactor: k0 } };
      let n = 0;
      for (const seed of SEEDS) {
        const g = gen(seed, [slow, FX_AIR_HAZARD]);
        for (let i = 0; i < N; i++) {
          const c = g.getChunk(i);
          const h = c.hazards.find(isFx);
          if (!h) continue;
          n++;
          const k = Math.max(0, Math.min(c.points.length - 2, Math.floor((h.x - c.startX) / SPACING_PX)));
          if (needDescent) expect(g._descentAhead(c.points, k, c.endX)).toBe(true);
          else {
            const k1 = Math.min(c.points.length - 2, k + Math.ceil(BIOME_EDGE_MARGIN_PX / SPACING_PX));
            for (let j = k; j <= k1; j++) expect(c.points[j + 1].y).toBeGreaterThanOrEqual(c.points[j].y);
          }
        }
      }
      expect(n).toBeGreaterThan(10);
    }
  });

  test('share: with chance 0.5 the biome hazard sits in 40-60 % of GROUND-ELIGIBLE biome chunks (not bridge, not gen-jump)', () => {
    let eligible = 0;
    let has = 0;
    for (const { fx } of runs) {
      for (const c of fx) {
        if (c.biome !== FX_GROUND_HAZARD.biome || c.index === 0 || c.kind === 'bridge' || c.defId === 'gen-jump') continue;
        eligible++;
        if (c.hazards.some(isFx)) has++;
      }
    }
    expect(eligible).toBeGreaterThan(150);
    console.log(`slot-rule share (fixture, chance 0.5): ${has}/${eligible} ground-eligible = ${(has / eligible).toFixed(3)}`);
    expect(has / eligible).toBeGreaterThanOrEqual(0.4);
    expect(has / eligible).toBeLessThanOrEqual(0.6);
  });

  test('the pick among candidates is cands[floor(r * n)] with r the slot\'s 5th draw (spied on the real generator)', () => {
    // Spy on this instance: inside _replaceBiomeGround, every candidate that passes the ground rules goes through
    // _biomeGroundAt with itself as `skip`, in chunk order, so the spy sees the real candidate list and the draw r.
    let multi = 0;
    let notFirst = 0;
    let total = 0;
    for (const seed of [...SEEDS, 'slot-e', 'slot-f', 'slot-g', 'slot-h']) {
      const g = gen(seed);
      const at = g._biomeGroundAt.bind(g);
      const rep = g._replaceBiomeGround.bind(g);
      let log = null;
      g._biomeGroundAt = (...args) => { const r = at(...args); if (log && r && args[6]) log.push(args[6]); return r; };
      g._replaceBiomeGround = (chunk, def, r, ...rest) => {
        log = [];
        const before = chunk.hazards.slice();
        const ok = rep(chunk, def, r, ...rest);
        const cands = log;
        log = null;
        if (ok) {
          total++;
          const k = before.findIndex((q, j) => chunk.hazards[j] !== q);
          const want = cands[Math.min(cands.length - 1, Math.floor(r * cands.length))];
          expect(before[k]).toBe(want);
          if (cands.length > 1) multi++;
          if (want !== cands[0]) notFirst++;
        }
        return ok;
      };
      for (let i = 0; i < 600; i++) g.getChunk(i);
    }
    console.log(`slot-rule pick: ${total} replacements, ${multi} with > 1 candidate, ${notFirst} not the first candidate`);
    expect(total).toBeGreaterThan(20);
    expect(notFirst).toBeGreaterThan(3);
  });

  test('determinism: same (seed, mask, content) twice and in reverse call order is deep-equal', () => {
    const a = gen('slot-det');
    const b = gen('slot-det');
    const rev = [];
    for (let i = 199; i >= 0; i--) rev[i] = snap(b.getChunk(i));
    for (let i = 0; i < 200; i++) expect(snap(a.getChunk(i))).toEqual(rev[i]);
  });
});/**
 * B0 (biome full treatment): biome-tagged hazard and power-up defs.
 *
 * Spec §5: a def with a `biome` field never enters the base hazard / air hazard / power-up lists, so
 * base placement and mask-0 output are untouched by construction. Biome spawns come only from the new
 * `_placeBiomeSpawns` pass, on forks 'biomeHaz' / 'biomePu', inside chunks whose biome is set.
 */
import { makeGen, loadContent } from './_helpers.js';
import { withBiomeFixtures } from './_biomeFixtures.js';
import {
  HAZARD_MIN_SPACING_PX, BIOME_SPAWN_MAX_CHANCE, BIOME_EDGE_MARGIN_PX, BIOME_SLOT_DRAWS, BIOME_HAZARD_MAX_CHANCE,
  BIOME_HAZARD_CLEARANCE_PX,
} from '../../src/systems/TerrainGenerator.js';
import { FX_GROUND_HAZARD, FX_AIR_HAZARD, FX_WARD_POWERUP, FX_STABILIZE_POWERUP, FX_MASK, baseOnly } from './_biomeFixtures.js';

const content = loadContent();

/** Every field, keys sorted, numbers rounded to 4 dp: the golden test's `complete` projection. */
const round = (n) => (Number.isFinite(n) ? Math.round(n * 1e4) / 1e4 : n);
const completeOf = (v) =>
  Array.isArray(v)
    ? v.map(completeOf)
    : v && typeof v === 'object'
      ? Object.fromEntries(Object.keys(v).sort().map((k) => [k, completeOf(v[k])]))
      : typeof v === 'number'
        ? round(v)
        : v;

// #65: Debutmont is the base biome, so at mask 0 its own biome-tagged defs are live. Defs tagged to any OTHER biome still
// change nothing there, which is what the fixtures (tagged garbage-dump-glacier / space-mountain) prove.
describe('isolation: biome-tagged defs of other biomes change NOTHING at mask 0', () => {
  test('300 chunks x 3 seeds: the full-chunk projection is identical with and without the other biomes\' defs', () => {
    const fx = withBiomeFixtures(content);
    for (const seed of ['iso-alpha', 'iso-beta', '2026-11-14']) {
      const withDefs = makeGen(seed, { biomeMask: 0, ...fx });
      const without = makeGen(seed, { biomeMask: 0, hazardDefs: baseOnly(content.hazards), powerupDefs: baseOnly(content.powerups) });
      for (let i = 0; i < 300; i++) {
        expect(completeOf(withDefs.getChunk(i))).toEqual(completeOf(without.getChunk(i)));
      }
    }
  });
});

describe('constructor filter: biome defs leave the base lists and are kept per biome', () => {
  test('hazardList, airHazardList and powerupList hold no biome def; the per-biome maps hold them', () => {
    const g = makeGen('filter', withBiomeFixtures(content));
    const ids = (l) => l.map((d) => d.id);
    expect(g.hazardList.some((d) => d.biome)).toBe(false);
    expect(g.airHazardList.some((d) => d.biome)).toBe(false);
    expect(g.powerupList.some((d) => d.biome)).toBe(false);
    // base lists are exactly what they were without the fixtures
    const base = makeGen('filter', { hazardDefs: baseOnly(content.hazards), powerupDefs: baseOnly(content.powerups) });
    expect(ids(g.hazardList)).toEqual(ids(base.hazardList));
    expect(ids(g.airHazardList)).toEqual(ids(base.airHazardList));
    expect(ids(g.powerupList)).toEqual(ids(base.powerupList));
    expect(ids(g.biomeHazards['garbage-dump-glacier'])).toEqual(['fxGroundHazard']);
    expect(ids(g.biomeHazards['space-mountain'])).toEqual(['fxAirHazard']);
    expect(ids(g.biomePowerups['garbage-dump-glacier'])).toEqual(['fxWardPowerup']);
    expect(ids(g.biomePowerups['space-mountain'])).toEqual(['fxStabilizePowerup']);
  });
});

// ------------------------------------------------------------------------------------------------ placement


const N = 300;
const SEEDS = ['bs-alpha', 'bs-beta', 'bs-gamma', 'bs-delta'];
const FX_IDS = new Set([FX_GROUND_HAZARD.id, FX_AIR_HAZARD.id, FX_WARD_POWERUP.id, FX_STABILIZE_POWERUP.id]);
const fxDefs = { ...content.hazards, ...content.powerups, [FX_GROUND_HAZARD.id]: FX_GROUND_HAZARD, [FX_AIR_HAZARD.id]: FX_AIR_HAZARD,
  [FX_WARD_POWERUP.id]: FX_WARD_POWERUP, [FX_STABILIZE_POWERUP.id]: FX_STABILIZE_POWERUP };
const isFx = (s) => FX_IDS.has(s.defId);
const snap = (c) => JSON.parse(JSON.stringify(c));

/** Fixture content with per-def overrides, e.g. { fxGroundHazard: { spawn: { baseChance: 0.2 } } }. */
function fxGen(seed, over = {}, mask = FX_MASK) {
  const patch = (d) => (over[d.id] ? { ...JSON.parse(JSON.stringify(d)), ...over[d.id] } : d);
  return makeGen(seed, {
    biomeMask: mask,
    ...withBiomeFixtures(content, {
      hazards: Object.fromEntries([FX_GROUND_HAZARD, FX_AIR_HAZARD].map((d) => [d.id, patch(d)])),
      powerups: Object.fromEntries([FX_WARD_POWERUP, FX_STABILIZE_POWERUP].map((d) => [d.id, patch(d)])),
    }),
  });
}

function chunks(gen, n = N) {
  const out = [];
  for (let i = 0; i < n; i++) out.push(snap(gen.getChunk(i)));
  return out;
}

describe('_placeBiomeSpawns: placement of biome hazards and power-ups', () => {
  const all = SEEDS.map((s) => chunks(fxGen(s)));

  test('the pass places fixture hazards and power-ups at all (otherwise every bound below is vacuous)', () => {
    let gh = 0;
    let ah = 0;
    let pu = 0;
    for (const cs of all) {
      for (const c of cs) {
        gh += c.hazards.filter((h) => h.defId === FX_GROUND_HAZARD.id).length;
        ah += c.hazards.filter((h) => h.defId === FX_AIR_HAZARD.id).length;
        pu += c.powerups.filter(isFx).length;
      }
    }
    expect(gh).toBeGreaterThanOrEqual(8); // rare by design: see BIOME_EDGE_MARGIN_PX and the 480 px spacing rule
    expect(ah).toBeGreaterThan(0);
    expect(pu).toBeGreaterThan(10);
  });

  test('biome spawns appear only inside a chunk of THAT def\'s biome', () => {
    for (const cs of all) {
      for (const c of cs) {
        for (const s of [...c.hazards, ...c.powerups].filter(isFx)) expect({ def: s.defId, biome: c.biome }).toEqual({ def: s.defId, biome: fxDefs[s.defId].biome });
      }
    }
  });

  test('at most one biome hazard and one biome power-up per chunk', () => {
    for (const cs of all) {
      for (const c of cs) {
        expect(c.hazards.filter(isFx).length).toBeLessThanOrEqual(1);
        expect(c.powerups.filter(isFx).length).toBeLessThanOrEqual(1);
      }
    }
  });

  test('ground biome hazards keep the base clearances: chunk edges, gaps, lips, spacing, slope, power-ups, shards', () => {
    expect(BIOME_EDGE_MARGIN_PX).toBeGreaterThanOrEqual(96);
    for (const cs of all) {
      let prev = null;
      for (const c of cs) {
        for (const h of c.hazards) {
          // across chunk borders too. B1 presence amendment (a): a pair involving a biome GROUND hazard keeps
          // BIOME_HAZARD_CLEARANCE_PX (240); every other pair keeps the base HAZARD_MIN_SPACING_PX (480).
          const biomeGround = h.defId === FX_GROUND_HAZARD.id || (prev && prev.defId === FX_GROUND_HAZARD.id);
          if (prev != null) expect(h.x - prev.x).toBeGreaterThanOrEqual(biomeGround ? BIOME_HAZARD_CLEARANCE_PX : HAZARD_MIN_SPACING_PX);
          prev = h;
        }
        const h = c.hazards.find((q) => q.defId === FX_GROUND_HAZARD.id);
        if (!h) continue;
        expect(c.kind).not.toBe('bridge');
        expect(c.defId).not.toBe('gen-jump');
        expect(h.x).toBeGreaterThanOrEqual(c.startX + BIOME_EDGE_MARGIN_PX);
        expect(h.x).toBeLessThanOrEqual(c.endX - BIOME_EDGE_MARGIN_PX);
        for (const g of c.gaps) expect(h.x < g.x0 - 96 || h.x > g.x1 + 96).toBe(true);
        for (const l of c.launches) expect(h.x < l.x - 40 || h.x > (l.landX || l.x)).toBe(true);
        for (const p of c.powerups) expect(Math.abs(p.x - h.x)).toBeGreaterThanOrEqual(90);
        const w = FX_GROUND_HAZARD.size.w;
        const top = h.y - FX_GROUND_HAZARD.size.h - 22;
        for (const s of c.shards) expect(s.x >= h.x - w / 2 - 22 && s.x <= h.x + w / 2 + 22 && s.y >= top).toBe(false);
        expect(Math.abs(h.rotationDeg)).toBeLessThan(28);
      }
    }
  });

  test('hazards stay sorted by x in every chunk', () => {
    for (const cs of all) for (const c of cs) expect(c.hazards.map((h) => h.x)).toEqual(c.hazards.map((h) => h.x).sort((a, b) => a - b));
  });

  test('air biome hazards only in jump chunks, floating above the ground, clear of power-ups and gaps', () => {
    for (const cs of all) {
      for (const c of cs) {
        const a = c.hazards.find((q) => q.defId === FX_AIR_HAZARD.id);
        if (!a) continue;
        expect(c.defId).toBe('gen-jump');
        expect(a.rotationDeg).toBe(0);
        const pts = c.points;
        const i = Math.max(0, Math.min(pts.length - 2, Math.floor((a.x - c.startX) / 16)));
        expect(a.y).toBeLessThan(pts[i].y - 60);
        for (const p of c.powerups) expect(Math.abs(p.x - a.x)).toBeGreaterThanOrEqual(90);
      }
    }
  });

  test('biome power-ups: lifted above the ground, never within 90 px of any hazard, clear of gaps and of other power-ups', () => {
    for (const cs of all) {
      for (const c of cs) {
        const p = c.powerups.find(isFx);
        if (!p) continue;
        for (const h of c.hazards) expect(Math.abs(h.x - p.x)).toBeGreaterThanOrEqual(90);
        for (const g of c.gaps) expect(p.x <= g.x0 - 80 || p.x >= g.x1 + 40).toBe(true);
        for (const q of c.powerups) if (q !== p) expect(Math.abs(q.x - p.x)).toBeGreaterThanOrEqual(90);
        expect(p.x).toBeGreaterThanOrEqual(c.startX + BIOME_EDGE_MARGIN_PX);
        expect(p.x).toBeLessThanOrEqual(c.endX - BIOME_EDGE_MARGIN_PX);
        const pts = c.points;
        const i = Math.max(0, Math.min(pts.length - 2, Math.floor((p.x - c.startX) / 16)));
        expect(p.y).toBeLessThan(Math.min(pts[i].y, pts[i + 1].y) - 20);
      }
    }
  });

  test('determinism: same (seed, mask, content) twice and in any call order is deep-equal; streamed chunks match fresh ones', () => {
    const a = fxGen('bs-det');
    const b = fxGen('bs-det');
    const rev = [];
    for (let i = 199; i >= 0; i--) rev[i] = snap(b.getChunk(i));
    for (let i = 0; i < 200; i++) expect(snap(a.getChunk(i))).toEqual(rev[i]);
    const stream = fxGen('bs-det');
    let x = 0;
    for (let f = 0; f < 700; f++) {
      x += 180;
      stream.update(x);
      for (const c of stream.getActiveChunks()) expect(snap(c)).toEqual(snap(b.getChunk(c.index)));
    }
  });

  test('spawn chance comes from the def: power-ups capped at BIOME_SPAWN_MAX_CHANCE (0.5), hazards at BIOME_HAZARD_MAX_CHANCE (0.75)', () => {
    expect(BIOME_SPAWN_MAX_CHANCE).toBe(0.5);
    // B1 presence amendment (c): the hazard slot's cap rose to 0.75; power-ups keep 0.5
    expect(BIOME_HAZARD_MAX_CHANCE).toBe(0.75);
    const n = (cs) => cs.reduce((k, c) => k + c.hazards.filter((h) => h.defId === FX_GROUND_HAZARD.id).length
      + c.powerups.filter((p) => p.defId === FX_WARD_POWERUP.id).length, 0);
    let half = 0;
    let low = 0;
    for (const seed of SEEDS) {
      const capped = chunks(fxGen(seed, { fxGroundHazard: { spawn: { baseChance: 1 } }, fxWardPowerup: { spawn: { baseChance: 1, distanceDecayM: 1 } } }));
      const atCaps = chunks(fxGen(seed, { fxGroundHazard: { spawn: { baseChance: 0.75 } }, fxWardPowerup: { spawn: { baseChance: 0.5 } } }));
      expect(capped).toEqual(atCaps);
      const h = chunks(fxGen(seed));
      half += n(h);
      low += n(chunks(fxGen(seed, { fxGroundHazard: { spawn: { baseChance: 0.1 } }, fxWardPowerup: { spawn: { baseChance: 0.1 } } })));
      // weight 0 disables a def (weight || 1 would resurrect it)
      expect(n(chunks(fxGen(seed, { fxGroundHazard: { weight: 0 }, fxWardPowerup: { weight: 0 } })))).toBe(0);
    }
    expect(low).toBeLessThan(half / 2);
  });

  test('fixed draws: lowering a hazard chance only removes hazards (none move) and leaves the power-up stream alone', () => {
    expect(BIOME_SLOT_DRAWS).toBeGreaterThanOrEqual(4);
    for (const seed of SEEDS) {
      const hi = chunks(fxGen(seed));
      const lo = chunks(fxGen(seed, { fxGroundHazard: { spawn: { baseChance: 0.2 } } }));
      for (let i = 0; i < N; i++) {
        const hiH = hi[i].hazards.filter(isFx);
        const loH = lo[i].hazards.filter(isFx);
        for (const h of loH) expect(hiH).toContainEqual(h);
        // power-ups: removing a hazard can only UNBLOCK a power-up position. The slot tries two positions; when the hazard
        // blocked the first, the power-up sat at the second in `hi` and moves to the freed first one in `lo`.
        const hiP = hi[i].powerups.filter(isFx);
        const loP = lo[i].powerups.filter(isFx);
        for (const p of hiP) {
          if (loP.some((q) => q.x === p.x && q.y === p.y)) continue;
          expect(loP.length).toBe(1);
          expect(hiH.some((h) => Math.abs(h.x - loP[0].x) < 90)).toBe(true);
        }
        for (const p of loP) {
          if (hiP.some((q) => q.x === p.x)) continue;
          expect(hiH.some((h) => Math.abs(h.x - p.x) < 90)).toBe(true);
        }
      }
    }
  });

  test('fixed draws: changing a power-up chance changes NO hazard', () => {
    for (const seed of SEEDS) {
      const a = chunks(fxGen(seed));
      const b = chunks(fxGen(seed, { fxWardPowerup: { spawn: { baseChance: 0.05, distanceDecayM: 1500 } } }));
      for (let i = 0; i < N; i++) expect(b[i].hazards).toEqual(a[i].hazards);
    }
  });

  test('a biome with no biome defs gets no biome spawn, even when another biome has some', () => {
    // debutmont (bit 1) has no fixture def; garbage-dump-glacier and space-mountain do
    let debutmontChunks = 0;
    for (const seed of SEEDS) {
      for (const c of chunks(fxGen(seed, {}, 1 | FX_MASK))) {
        if (c.biome !== 'debutmont') continue;
        debutmontChunks++;
        expect([...c.hazards, ...c.powerups].filter(isFx)).toEqual([]);
      }
    }
    expect(debutmontChunks).toBeGreaterThan(20);
  });

  test('a biome not in the mask gets nothing; base spawns in a biome chunk are untouched by the pass', () => {
    const onlyGarbage = chunks(fxGen('bs-mask', {}, 2));
    for (const c of onlyGarbage) for (const s of [...c.hazards, ...c.powerups]) expect([FX_AIR_HAZARD.id, FX_STABILIZE_POWERUP.id]).not.toContain(s.defId);
    const withFx = chunks(fxGen('bs-mask'));
    const noFx = chunks(makeGen('bs-mask', { biomeMask: FX_MASK, hazardDefs: baseOnly(content.hazards), powerupDefs: baseOnly(content.powerups) }));
    for (let i = 0; i < N; i++) {
      expect(withFx[i].points).toEqual(noFx[i].points);
      expect(withFx[i].zones).toEqual(noFx[i].zones);
      expect(withFx[i].shards).toEqual(noFx[i].shards);
      // B1 slot rule (spec §4, amended 2026-11-14): when the free scan finds no slot, ONE base ground hazard may be swapped
      // IN PLACE (same x, y, rotation) for the chunk's biome hazard. Every other base hazard is untouched.
      const own = withFx[i].hazards.filter((h) => !isFx(h));
      const lost = noFx[i].hazards.filter((h) => !own.some((q) => q.x === h.x && q.defId === h.defId));
      expect(lost.length).toBeLessThanOrEqual(1);
      for (const h of own) expect(noFx[i].hazards).toContainEqual(h);
      if (lost.length) {
        const swap = withFx[i].hazards.find(isFx);
        expect(swap && { x: swap.x, y: swap.y, rotationDeg: swap.rotationDeg }).toEqual({ x: lost[0].x, y: lost[0].y, rotationDeg: lost[0].rotationDeg });
        expect(fxDefs[swap.defId].biome).toBe(withFx[i].biome);
      }
      expect(withFx[i].powerups.filter((p) => !isFx(p))).toEqual(noFx[i].powerups);
    }
  });
});/**
 * Marvin decision 3 / audit ACH-6 + F11, the pure view layer: each biome shows its own state (locked, unlocked
 * but not entered, encountered, completed), and the biome achievements show encountered/target instead of the
 * catalogue size.
 */
import { readFileSync } from 'node:fs';
import path from 'node:path';
import { profileLayout, overlappingPairs, toggleLabel, BIOME_STATE_TAGS, PROFILE_PANEL } from '../../src/ui/ProfileLayout.js';
import { achievementsLayout, achievementRows, ROWS_PER_PAGE } from '../../src/ui/AchievementsLayout.js';
import { biomeToggleRows } from '../../src/systems/ProfileStore.js';
import { defaultProfile, levelForXp } from '../../src/systems/Progression.js';
import { measureText } from '../../src/ui/PixelFont.js';
import { loadContent } from './_helpers.js';

const levels = JSON.parse(readFileSync(path.resolve('src/data/progression/levels.json'), 'utf8'));
const DEFS = Object.values(loadContent().biomes);
const atLevel = (lv, extra = {}) => {
  const p = defaultProfile();
  p.xp = levels.levels.find((l) => l.level === lv).xpMin;
  p.pendingBiomes = levels.levels.filter((l) => l.biome && l.level <= levelForXp(p.xp, levels)).map((l) => l.biome);
  return { ...p, ...extra };
};
const prog = (encountered, completed = []) => ({ biomeProgress: { encountered, completed } });

describe('biomeToggleRows carries the decision 3 state', () => {
  test('locked / unlocked / encountered / completed, plus a locked biome entered in a Daily', () => {
    // level 7: debutmont (base, no row), garbage, pyramid unlocked. Pyramid completed, garbage encountered;
    // underwater (locked, LVL 10) was entered on a Daily mask.
    const p = atLevel(7, prog(['garbage-dump-glacier', 'pyramid-peak', 'underwater-mountain'], ['pyramid-peak']));
    const by = Object.fromEntries(biomeToggleRows(p, DEFS).map((r) => [r.id, r]));
    expect(by.debutmont).toBeUndefined(); // the base biome cannot be turned off, so it has no toggle row
    expect(by['garbage-dump-glacier']).toMatchObject({ unlocked: true, encountered: true, completed: false, state: 'encountered' });
    expect(by['pyramid-peak']).toMatchObject({ unlocked: true, encountered: true, completed: true, state: 'completed' });
    expect(by['underwater-mountain']).toMatchObject({ unlocked: false, encountered: true, state: 'encountered' });
    expect(by['crystal-cavern']).toMatchObject({ unlocked: false, encountered: false, state: 'locked' });
  });
});

describe('toggleLabel: the unlocked row says NEW / SEEN / DONE', () => {
  test('one tag per state, and a different colour for each', () => {
    expect(BIOME_STATE_TAGS).toEqual({ unlocked: 'NEW', encountered: 'SEEN', completed: 'DONE' });
    const row = (state) => ({ name: 'Debutmont', state });
    expect(toggleLabel(row('unlocked')).text).toBe('DEBUTMONT NEW');
    expect(toggleLabel(row('encountered')).text).toBe('DEBUTMONT SEEN');
    expect(toggleLabel(row('completed')).text).toBe('DEBUTMONT DONE');
    const colors = ['unlocked', 'encountered', 'completed'].map((s) => toggleLabel(row(s)).color);
    expect(new Set(colors).size).toBe(3);
  });

  test('the widest label still clears the ON/OFF value in a two-column toggle band', () => {
    // MenuList: label at x 14, value right-aligned at colW - 8 (colW = 194 for the profile's two columns).
    const colW = (PROFILE_PANEL.w - 24 - 4) / 2;
    const room = colW - 8 - measureText('OFF') - 4 - 14;
    for (const d of DEFS) {
      for (const state of ['unlocked', 'encountered', 'completed']) {
        expect(measureText(toggleLabel({ name: d.name, state }).text)).toBeLessThanOrEqual(room);
      }
    }
  });
});

describe('profileLayout shows biome states', () => {
  test('locked names keep LVL n; a locked biome entered on a Daily also says SEEN', () => {
    const p = atLevel(7, prog(['underwater-mountain']));
    const items = profileLayout({ profile: p, levels, playableBiomeIds: DEFS.map((d) => d.id) }).items;
    const texts = items.map((i) => i.text);
    expect(texts).toContain('UNDERWATER MOUNTAIN');
    expect(texts).toContain('LVL 10');
    expect(items.find((i) => i.key === 'state-underwater-mountain').text).toBe('SEEN');
    expect(items.find((i) => i.key === 'state-crystal-cavern')).toBeUndefined();
  });

  test('a biome progress summary reads SEEN n/11 DONE m/11', () => {
    const p = atLevel(7, prog(['garbage-dump-glacier', 'pyramid-peak'], ['pyramid-peak']));
    const it = profileLayout({ profile: p, levels, playableBiomeIds: DEFS.map((d) => d.id) }).items.find((i) => i.key === 'biome-progress');
    expect(it.text).toBe('BIOMES SEEN 2/11 DONE 1/11');
  });

  test('worst cases lay out with no overlapping text and inside the panel', () => {
    const all = levels.biomeOrder;
    const cases = [
      atLevel(1, prog(all, all)), // every biome locked yet seen and done (Daily masks): every tag drawn
      atLevel(24, prog(all, all)),
      atLevel(30, prog(all, all)),
      atLevel(7, prog([])),
    ];
    for (const p of cases) {
      const layout = profileLayout({ profile: p, levels, playableBiomeIds: DEFS.map((d) => d.id), achievementTotal: 29 });
      expect(overlappingPairs(layout.items)).toEqual([]);
      for (const it of layout.items) expect(it.x + it.w).toBeLessThanOrEqual(PROFILE_PANEL.w - 12);
    }
  });
});

