const { RunScene } = await import('../../src/scenes/RunScene.js');
const { TitleScene } = await import('../../src/scenes/TitleScene.js');
const { REG } = await import('../../src/constants.js');
const { EVT } = await import('../../src/events.js');
const { SaveStore, sanitizeRun } = await import('../../src/systems/SaveStore.js');
const { DailyPatch } = await import('../../src/systems/DailyPatch.js');
const { BOOST_DEFS, openingSpeedMul } = await import('../../src/systems/Boosts.js');
const { GameOverScene } = await import('../../src/scenes/GameOverScene.js');
const { isOfficialDaily } = await import('../../src/systems/Ranking.js');
const { verifyLedgerHash } = await import('../../src/systems/SaveStore.js');

// ---------------------------------------------------------------- harness

const NOW = Date.parse('2026-11-13T12:00:00.000Z');
const TODAY_SEED = 'daily-2026-11-13';
const CONTENT = loadContent();
/** Both boosts switched ON and both owned (Sync Level 15+), so the boosted cases are not vacuous. */
const BOOSTED_PROFILE = {
  boosts: { errorCorrection: true, headStart: true },
  unlocked: { biomes: [], cosmetics: [], titles: [], boosts: { headStart: 8, errorCorrection: 15 } },
};

beforeEach(() => {
  // Fake ONLY Date: the scenes' promise chains and the flush below still need real timers/microtasks.
  jest.useFakeTimers({
    now: NOW,
    doNotFake: ['hrtime', 'nextTick', 'performance', 'queueMicrotask', 'requestAnimationFrame', 'cancelAnimationFrame',
      'requestIdleCallback', 'cancelIdleCallback', 'setImmediate', 'clearImmediate', 'setInterval', 'clearInterval',
      'setTimeout', 'clearTimeout'],
  });
  sledCalls.length = 0;
  markers.length = 0;
  texts.length = 0;
  menuItems = null;
});
afterEach(() => jest.useRealTimers());

const flush = () => new Promise((r) => setTimeout(r, 0));

function memStore(runs = []) {
  const s = new SaveStore();
  s.runs = runs.map((r) => sanitizeRun(r)).filter(Boolean);
  return s;
}

let recN = 0;
/** A complete, hash-valid run record. */
function rec(over = {}) {
  recN += 1;
  const r = {
    version: 1, id: `r-${recN}`, seed: 'alpha', dailyRuleId: 'featherweight',
    startedAt: NOW - 60000, endedAt: NOW - 1000, durationMs: 59000, score: 100, distanceM: 50, trickPoints: 0,
    tricks: {}, bestCombo: 1, maxAirtimeMs: 0, cause: 'crash', ...over,
  };
  r.ledgerHash = SaveStore.computeLedgerHash(r);
  return r;
}

function registry(values) {
  return { get: (k) => values.get(k), set: (k, v) => values.set(k, v) };
}

/** The real TitleScene methods on a context with a plain-Map registry. */
function titleCtx(values, over = {}) {
  const t = Object.create(TitleScene.prototype);
  Object.assign(t, {
    registry: registry(values),
    scene: { start: jest.fn() },
    theme: deep(),
    daily: DailyPatch.getDailyInfo(),
    starting: false,
    _closeView() {},
    ...over,
  });
  return t;
}

/** The real RunScene.create() on a context whose Phaser surfaces are inert. */
function runScene(values) {
  const s = Object.create(RunScene.prototype);
  Object.assign(s, {
    registry: registry(values),
    game: deep(), add: deep(), matter: deep(), cameras: deep(), scene: deep(), events: deep(),
    time: deep(), tweens: deep(), input: deep(), sys: deep(),
  });
  s.create();
  return s;
}

/** Press a Title menu item for real: build the menu, take the item, call its onSelect. */
function pressTitle(values, label, over) {
  const t = titleCtx(values, over);
  TitleScene.prototype._buildMenu.call(t);
  const item = menuItems.find((i) => i.label === label);
  if (!item) throw new Error(`no ${label} item`);
  item.onSelect();
  return t;
}


const { PIXELS_PER_METER } = await import('../../src/constants.js');
const { biomeForSector, BASE_BIOME_ID, SECTOR_M } = await import('../../src/systems/TerrainGenerator.js');
const { ProgressionService } = await import('../../src/systems/ProgressionService.js');
const { ProfileStore } = await import('../../src/systems/ProfileStore.js');
const fs = await import('fs');
const LEVELS = JSON.parse(fs.readFileSync('src/data/progression/levels.json', 'utf8'));
const DEFS = Object.values(CONTENT.biomes);
const SECTOR_PX = SECTOR_M * PIXELS_PER_METER;

/** A seed whose 0-based sector 2 is `id` at mask `bit` and sector 3 is the home biome (so sector 2 opens with an arcade bridge). */
function seedFor(id, bit) {
  for (let i = 0; i < 2000; i++) {
    const seed = `d3rs-${i}`;
    if (biomeForSector(seed, 2, bit, DEFS) === id && biomeForSector(seed, 3, bit, DEFS) === BASE_BIOME_ID) return seed;
  }
  throw new Error('no seed');
}

/** Create the run, ride it to world x `furthestX`, then crash at `crashX` through the real doCrash. */
function rideAndCrash(seed, mask, furthestX, crashX = furthestX) {
  const values = new Map([[REG.CONTENT, CONTENT], [REG.SEED, seed], [REG.BIOME_MASK, mask], [REG.SAVE_STORE, memStore()]]);
  const s = runScene(values);
  const emitted = [];
  s.game = { events: { emit: (name, payload) => { emitted.push([name, payload]); } } };
  s.score.setDistance((furthestX - s.startX) / PIXELS_PER_METER);
  s.doCrash({ cause: 'terrain' }, { x: crashX, y: 0, vx: 0, vy: 0 }, 0);
  const end = emitted.find(([n]) => n === EVT.RUN_END);
  return { s, payload: end && end[1], values };
}

describe('decision 3: RunScene reports the biomes a run actually entered', () => {
  // Debutmont is the base (sectors 0-1), then an arcade bridge opens Crystal Cavern at sector 2 (#65).
  const seed = seedFor('crystal-cavern', 16);
  const HOME = BASE_BIOME_ID;

  test('a run that crashes inside the biome sector reports it encountered, not completed', () => {
    const { payload } = rideAndCrash(seed, 16, 2 * SECTOR_PX + SECTOR_PX / 2);
    expect(payload.biomeVisits).toEqual({ encountered: [HOME, 'crystal-cavern'], completed: [HOME] });
  });

  test('a crash still inside the arcade bridge has not entered the biome yet', () => {
    const { payload } = rideAndCrash(seed, 16, 2 * SECTOR_PX + 200);
    expect(payload.biomeVisits).toEqual({ encountered: [HOME], completed: [HOME] });
  });

  test('a run that rides the sector to its end and crashes beyond reports it completed', () => {
    const { payload } = rideAndCrash(seed, 16, 3 * SECTOR_PX + 200);
    expect(payload.biomeVisits).toEqual({ encountered: [HOME, 'crystal-cavern'], completed: [HOME, 'crystal-cavern'] });
  });

  test('a run that stops before sector 2 reports only the home biome (control)', () => {
    const { payload } = rideAndCrash(seed, 16, 2 * SECTOR_PX - 400);
    expect(payload.biomeVisits).toEqual({ encountered: [HOME], completed: [HOME] });
  });

  test('mask 0 plays pure Debutmont, and the record carries no biome fields', () => {
    const { payload } = rideAndCrash(seed, 0, 6 * SECTOR_PX);
    expect(payload.biomeVisits).toEqual({ encountered: [HOME], completed: [HOME] });
    expect(Object.keys(payload.record).filter((k) => /biome(?!Mask)/i.test(k))).toEqual([]);
  });

  test('the visits travel beside the record, never inside it (the ledger hash is untouched)', () => {
    const { payload, values } = rideAndCrash(seed, 16, 3 * SECTOR_PX + 200);
    expect(payload.record).toBe(values.get(REG.LAST_RECORD));
    expect(payload.record.biomeVisits).toBeUndefined();
    expect(payload.record.ledgerHash).toBe(SaveStore.computeLedgerHash(payload.record));
  });

  test('end to end: the real ProgressionService credits RUN_END.biomeVisits into the profile', () => {
    const { payload } = rideAndCrash(seed, 16, 3 * SECTOR_PX + 200);
    const reg = new Map();
    const game = { registry: { get: (k) => reg.get(k), set: (k, v) => reg.set(k, v) }, events: { on() {}, off() {}, once() {} } };
    const store = new ProfileStore({ storage: null, levels: LEVELS });
    store.load();
    const svc = new ProgressionService(game, { levels: LEVELS, store });
    svc.onRunEnd(payload);
    expect(store.profile.biomeProgress).toEqual({ encountered: [HOME, 'crystal-cavern'], completed: [HOME, 'crystal-cavern'] });
    expect(reg.get(REG.PROFILE).biomeProgress.encountered).toEqual([HOME, 'crystal-cavern']);
  });
});

describe('#65: RunScene announces biomes from the generator\'s own answer at the sled (bridges included)', () => {
  test('home on entry, then the arcade bridge, then the biome: one BIOME_ENTER each, palette repainted per change', () => {
    const seed = seedFor('crystal-cavern', 16);
    const values = new Map([[REG.CONTENT, CONTENT], [REG.SEED, seed], [REG.BIOME_MASK, 16], [REG.SAVE_STORE, memStore()]]);
    const s = runScene(values);
    const events = [];
    s.emitIf = (name, payload) => { if (name === EVT.BIOME_ENTER) events.push(payload); };
    s.refreshPalette = jest.fn();
    let owed = 0;
    let prev;
    for (let x = s.startX; x < 3 * SECTOR_PX; x += 200) {
      s.sled.x = x;
      s.sled.y = s.terrain.heightAt(x);
      s.sled.grounded = true;
      const b = s.terrain.biomeAtX(x);
      if (b !== prev) { prev = b; owed++; }
      s.updateFun(16, {}, Math.max(0, (x - s.startX) / 10));
    }
    expect(events.map((e) => [e.id, e.entering])).toEqual([[BASE_BIOME_ID, true], [null, false], ['crystal-cavern', true]]);
    // one repaint per change of the generator's biome; the bridge dissolve adds two more (graphics only: since #140 no
    // repaint touches a collider) inside the bridge
    expect(owed).toBe(3);
    expect(s.refreshPalette.mock.calls).toHaveLength(owed + 2);
  });

  test('a retry on the same RunScene instance announces and repaints the opening biome again', () => {
    // RunScene is one instance across runs; create() starts on the base palette, so it must forget the last run's biome.
    const values = new Map([[REG.CONTENT, CONTENT], [REG.SEED, 'retry-seed'], [REG.BIOME_MASK, 0], [REG.SAVE_STORE, memStore()]]);
    const s = runScene(values);
    const events = [];
    s.emitIf = (name, payload) => { if (name === EVT.BIOME_ENTER) events.push(payload); };
    s.refreshPalette = jest.fn();
    const tick = () => {
      s.sled.x = s.startX + 200;
      s.sled.y = s.terrain.heightAt(s.sled.x);
      s.sled.grounded = true;
      s.updateFun(16, {}, 20);
    };
    tick();
    expect(events.map((e) => [e.id, e.entering])).toEqual([[BASE_BIOME_ID, true]]);
    expect(s.refreshPalette).toHaveBeenCalledTimes(1);
    // The first run ended in Debutmont; the retry starts in Debutmont again.
    s.create();
    s.emitIf = (name, payload) => { if (name === EVT.BIOME_ENTER) events.push(payload); };
    s.refreshPalette = jest.fn();
    tick();
    expect(events.map((e) => [e.id, e.entering])).toEqual([[BASE_BIOME_ID, true], [BASE_BIOME_ID, true]]);
    expect(s.refreshPalette).toHaveBeenCalledTimes(1);
  });
});/**
 * #65 presentation: the arcade bridge look model (systems/BiomeTransition.js) and the generator query it keys on
 * (TerrainGenerator.bridgeSpanAt). Pure, position-keyed, deterministic: no time, no state, no RNG.
 */
import fs from 'fs';
import {
  DISSOLVE_FRAC, REBUILD_FRAC, VEIL_CELL_PX, BAYER8, bridgeProgress, bridgeLook, veilCovers, hash01,
} from '../../src/systems/BiomeTransition.js';
import { BASE_BIOME_ID } from '../../src/data/biomeAliases.js';
import { makeGen, readDir } from './_helpers.js';

const SPAN = { startX: 1000, endX: 2000, fromId: 'debutmont', toId: 'garbage-dump-glacier' };
const at = (t, enabled = true) => bridgeLook(SPAN, SPAN.startX + t * (SPAN.endX - SPAN.startX), null, enabled);

describe('bridge look: dissolve, arcade, reconstruct', () => {
  test('the shares are a quarter each', () => {
    expect(DISSOLVE_FRAC).toBe(0.25);
    expect(REBUILD_FRAC).toBe(0.25);
  });

  test('progress is 0 at the start and 1 at the end', () => {
    expect(bridgeProgress(SPAN, 1000)).toBe(0);
    expect(bridgeProgress(SPAN, 2000)).toBe(1);
    expect(bridgeProgress(SPAN, 1500)).toBe(0.5);
    expect(bridgeProgress({ startX: 5, endX: 5 }, 9)).toBe(0); // a degenerate span never divides by zero
  });

  test('off a bridge there is no veil and the look is the generator\'s biome', () => {
    expect(bridgeLook(null, 123, 'debutmont', true)).toEqual({ veil: 0, lookId: 'debutmont', t: -1 });
    expect(bridgeLook(null, 123, 'debutmont', false)).toEqual({ veil: 0, lookId: 'debutmont', t: -1 });
  });

  test('the first quarter dissolves the outgoing biome: veil 0 -> 1, outgoing look', () => {
    expect(at(0)).toMatchObject({ veil: 0, lookId: 'debutmont' });
    expect(at(0.125)).toMatchObject({ veil: 0.5, lookId: 'debutmont' });
    expect(at(0.24).veil).toBeCloseTo(0.96, 6);
    expect(at(0.24).lookId).toBe('debutmont');
  });

  test('the middle is pure arcade: full veil, no biome look', () => {
    for (const t of [0.25, 0.4, 0.5, 0.6, 0.75]) expect(at(t)).toMatchObject({ veil: 1, lookId: null });
  });

  test('the last quarter reconstructs the incoming biome: veil 1 -> 0, incoming look', () => {
    expect(at(0.76).lookId).toBe('garbage-dump-glacier');
    expect(at(0.875)).toMatchObject({ veil: 0.5, lookId: 'garbage-dump-glacier' });
    expect(at(1)).toMatchObject({ veil: 0, lookId: 'garbage-dump-glacier' });
  });

  test('the look only changes while the veil is full (no pop shows)', () => {
    let prev = at(0);
    for (let i = 1; i <= 1000; i++) {
      const cur = at(i / 1000);
      // sampled every 0.1 % of the bridge: the frame before a flip is within a hair of full (>= 63/64 of the blocks)
      if (cur.lookId !== prev.lookId) { expect(prev.veil).toBeGreaterThanOrEqual(63 / 64); expect(cur.veil).toBeGreaterThanOrEqual(63 / 64); }
      prev = cur;
    }
  });

  test('the veil never decreases through the dissolve and never increases through the reconstruct', () => {
    let prev = at(0).veil;
    for (let i = 1; i <= 250; i++) { const v = at(i / 1000).veil; expect(v).toBeGreaterThanOrEqual(prev); prev = v; }
    prev = at(0.75).veil;
    for (let i = 751; i <= 1000; i++) { const v = at(i / 1000).veil; expect(v).toBeLessThanOrEqual(prev); prev = v; }
  });

  test('reduced motion / effects off is the hard cut: the veil is simply on, the look is the generator\'s', () => {
    for (const t of [0, 0.1, 0.5, 0.9, 1]) expect(at(t, false)).toMatchObject({ veil: 1, lookId: null });
    expect(bridgeLook(SPAN, 1100, null, false).lookId).toBeNull();
  });

  test('an `out` scratch is filled and returned (no allocation), with the same values as a fresh result', () => {
    const out = { veil: -1, lookId: 'x', t: -9 };
    for (const t of [0, 0.1, 0.5, 0.9, 1]) {
      const x = SPAN.startX + t * (SPAN.endX - SPAN.startX);
      for (const enabled of [true, false]) {
        expect(bridgeLook(SPAN, x, null, enabled, out)).toBe(out);
        expect(out).toEqual(bridgeLook(SPAN, x, null, enabled));
      }
    }
    expect(bridgeLook(null, 5, 'debutmont', true, out)).toBe(out);
    expect(out).toEqual({ veil: 0, lookId: 'debutmont', t: -1 });
  });

  test('pure: the same inputs give the same answer in any order (no time, no accumulated state)', () => {
    const ts = [0.9, 0.1, 0.5, 0.3, 0.8, 0.1, 0.9];
    const first = ts.map((t) => at(t));
    const again = [...ts].reverse().map((t) => at(t)).reverse();
    expect(again).toEqual(first);
  });
});

describe('veil blocks: ordered dither', () => {
  test('BAYER8 is a permutation of 0..63', () => {
    expect(BAYER8.flat().sort((a, b) => a - b)).toEqual(Array.from({ length: 64 }, (_, i) => i));
  });

  test('the block size divides the 480 px width', () => {
    expect(480 % VEIL_CELL_PX).toBe(0);
  });

  test('coverage 0 covers nothing, 1 covers everything, and each step adds blocks without removing any', () => {
    const covered = (c) => { const s = new Set(); for (let y = 0; y < 8; y++) for (let x = 0; x < 8; x++) if (veilCovers(x, y, c)) s.add(`${x},${y}`); return s; };
    expect(covered(0).size).toBe(0);
    expect(covered(1).size).toBe(64);
    let prev = covered(0);
    for (let k = 1; k <= 64; k++) {
      const cur = covered(k / 64);
      for (const p of prev) expect(cur.has(p)).toBe(true);
      expect(cur.size).toBe(k);
      prev = cur;
    }
  });

  test('hash01 is in [0, 1) and platform-stable', () => {
    for (let i = 0; i < 500; i++) { const h = hash01(i, 77); expect(h).toBeGreaterThanOrEqual(0); expect(h).toBeLessThan(1); }
    expect(hash01(1, 2)).toBe(hash01(1, 2));
    expect(hash01(1, 2)).not.toBe(hash01(2, 1));
  });
});

describe('TerrainGenerator.bridgeSpanAt agrees with the terrain', () => {
  const ALL = readDir('biomes').reduce((m, d) => m | d.bit, 0);
  const cases = [['alpha', 2], ['alpha', ALL], ['bitstream-bluffs', ALL], ['shots65-d', 2], ['42', 6]];

  test.each(cases)('seed %s mask %i: spans cover exactly the arcade stretches, with the right neighbours', (seed, mask) => {
    const gen = makeGen(seed, { biomeMask: mask });
    const limit = 5200 * 20;
    let bridges = 0;
    for (let x = 0; x < limit; x += 40) {
      const id = gen.biomeAtX(x);
      const span = gen.bridgeSpanAt(x);
      if (id !== null) { expect(span).toBeNull(); continue; }
      expect(span).not.toBeNull();
      expect(span.startX).toBeLessThanOrEqual(x);
      expect(span.endX).toBeGreaterThan(x);
      // inside: arcade all the way; just outside: the neighbours it reports
      expect(gen.biomeAtX(span.startX)).toBeNull();
      expect(gen.biomeAtX(span.endX - 1)).toBeNull();
      if (span.startX > 0) expect(gen.biomeAtX(span.startX - 1)).toBe(span.fromId);
      expect(gen.biomeAtX(span.endX)).toBe(span.toId);
      expect(span.fromId).not.toBe(span.toId);
      expect(span.fromId).not.toBeNull();
      expect(span.toId).not.toBeNull();
      bridges++;
    }
    if (mask === 2 || mask === ALL) expect(bridges).toBeGreaterThan(0);
  });

  test('a mask-0 run has no bridges at all', () => {
    const gen = makeGen('alpha', { biomeMask: 0 });
    for (let x = 0; x < 60000; x += 200) expect(gen.bridgeSpanAt(x)).toBeNull();
  });

  test('a generator with no biome content has no bridges (null is not a bridge there)', () => {
    const gen = makeGen('alpha', { biomeMask: 2, biomeDefs: [] });
    expect(gen.bridgeSpanAt(5000)).toBeNull();
  });

  test('every span is a whole run of chunks and starts a biome change: from the home biome or another', () => {
    const gen = makeGen('shots65-d', { biomeMask: 2 });
    const span = gen.bridgeSpanAt(1100 * 20);
    expect(span).not.toBeNull();
    expect([BASE_BIOME_ID, 'garbage-dump-glacier']).toContain(span.fromId);
    expect(span.endX - span.startX).toBeGreaterThan(40 * 20);
    expect(span.endX - span.startX).toBeLessThan(200 * 20);
  });
});

describe('purity of the presentation modules', () => {
  const read = (p) => fs.readFileSync(p, 'utf8');
  test.each(['src/systems/BiomeTransition.js', 'src/entities/BiomeFx.js'])('%s uses no wall clock, no Math.random and no gameplay stream', (file) => {
    const src = read(file).replace(/\/\*[\s\S]*?\*\//g, '').replace(/\/\/.*$/gm, '');
    expect(src).not.toMatch(/Math\.random/);
    expect(src).not.toMatch(/Date\.now|new Date|performance\.now/);
    expect(src).not.toMatch(/RunRandom|from '.*\/Rng\.js'|PhysicsTuner|ScoreManager|TerrainGenerator/);
  });
});/**
 * E7 (Marvin 2026-11-14, audit TERRAIN-1): a chunk that hosts a biome zone gets NO chunk-template zone, so a
 * biome mechanic can never be multiplied into its opposite (stickyPatch x highBandwidth made sticky ground
 * slippery; thermalUpdraft x compression made an updraft add gravity). Mask 0 is untouched (golden test).
 */
import { makeGen, loadContent, readDir } from './_helpers.js';
import { PhysicsTuner } from '../../src/systems/PhysicsTuner.js';

const BIOMES = readDir('biomes');
const MODS = loadContent().terrainMods;
const ALL_MASK = BIOMES.reduce((m, b) => m | b.bit, 0);
const BIOME_MODS = new Set(BIOMES.map((b) => b.mod));

describe('TERRAIN-1: a biome zone keeps its mechanic where it overlaps a chunk-template zone', () => {
  // Copied from audit/terrain tests/src/audit-terrain.test.js (red at e0ae90f / 8db8dee).
  test('TERRAIN-1: inside every biome zone the effective physics moves in the biome mechanic\'s direction', () => {
    const t = new PhysicsTuner();
    const base = t.getEffective({});
    const keys = ['gravityPxS2', 'groundResist'];
    const sign = (v) => (Math.abs(v) < 1e-9 ? 0 : Math.sign(v));
    const inverted = new Set();
    for (const seed of ['alpha', 'beta', 'gamma']) {
      const gen = makeGen(seed, { biomeMask: ALL_MASK });
      for (let i = 0; i < 300; i++) {
        const c = gen.getChunk(i);
        if (!c.biome) continue;
        const bmod = MODS[BIOMES.find((b) => b.id === c.biome).mod];
        const alone = t.getEffective({ zones: [bmod] });
        for (const z of c.zones) {
          if (z.modId !== bmod.id) continue;
          for (let x = z.x0; x <= z.x1; x += 16) {
            const here = t.getEffective({ zones: gen.getZonesAt(x).map((q) => MODS[q.modId]) });
            for (const k of keys) {
              const want = sign(alone[k] - base[k]);
              if (want !== 0 && sign(here[k] - base[k]) !== want) inverted.add(`${bmod.id}:${k}`);
            }
          }
        }
      }
    }
    expect([...inverted].sort()).toEqual([]);
  });
});

describe('E7: no template zone in a chunk that hosts a biome zone', () => {
  test('every chunk with a biome zone carries exactly that one zone; biome chunks without one may keep a template zone', () => {
    let hosts = 0;
    let templateOnly = 0;
    for (const seed of ['alpha', 'beta', 'gamma']) {
      const gen = makeGen(seed, { biomeMask: ALL_MASK });
      for (let i = 0; i < 300; i++) {
        const c = gen.getChunk(i);
        const biomeZones = c.zones.filter((z) => BIOME_MODS.has(z.modId));
        if (biomeZones.length) {
          hosts++;
          expect(c.zones.map((z) => z.modId)).toEqual([biomeZones[0].modId]);
        } else if (c.biome && c.zones.length) templateOnly++;
      }
    }
    expect(hosts).toBeGreaterThan(50);
    // the rule removes template zones only where a biome zone landed (25 % of biome chunks place none)
    expect(templateOnly).toBeGreaterThan(0);
  });
});/**
 * W6: the six batch-2 biomes, and the proof that each mechanic actually reaches the game.
 *
 * Spec W6 says "same pattern and gates as W3". W3's gate was not "the JSON exists" — it was "every
 * physics biome changes an effective constant", which is what caught a biome that was pure decoration.
 * Four of W6's six mechanics are expressible in the existing constants, but two are not: Micro Mountain
 * lifts the surface, Vertigo Vents kicks the sled off it. Those need their own proofs, or they are data
 * nobody can feel.
 *
 * The batch-1 content assertions live in biomes.test.js and were extended in place (that file already
 * anticipated W6 by name). This file covers what is genuinely new.
 */
import fs from 'fs';
import { PhysicsTuner, geyserStep } from '../../src/systems/PhysicsTuner.js';
import { TerrainGenerator } from '../../src/systems/TerrainGenerator.js';

const readJson = (p) => JSON.parse(fs.readFileSync(p, 'utf8'));
const LEVELS = readJson('src/data/progression/levels.json');
const BIOMES = {
  space: readJson('src/data/biomes/space-mountain.json'),
  candy: readJson('src/data/biomes/candy-cane-canyon.json'),
  jelly: readJson('src/data/biomes/sky-jellyfish-mountain.json'),
  steam: readJson('src/data/biomes/steampunk-slopes.json'),
  micro: readJson('src/data/biomes/micro-mountain.json'),
  vertigo: readJson('src/data/biomes/vertigo-vents.json'),
};
const MOD_FILE = {
  lowGravity: 'src/data/terrainMods/low-gravity.json',
  sugarRush: 'src/data/terrainMods/sugar-rush.json',
  bouncySpring: 'src/data/terrainMods/bouncy-spring.json',
  conveyorBelt: 'src/data/terrainMods/conveyor-belt.json',
  dewSwell: 'src/data/terrainMods/dew-swell.json',
  geyserVent: 'src/data/terrainMods/geyser-vent.json',
};
const MODS = Object.fromEntries(Object.entries(MOD_FILE).map(([id, f]) => [id, readJson(f)]));

// PhysicsTuner takes no arguments: its tuning and base constants are module-level, exactly as
// biomes.test.js constructs it.
function tuner() {
  return new PhysicsTuner();
}

/** Effective physics with and without a single mod's zone active. */
function effectOf(mod) {
  const t = tuner();
  return { base: t.getEffective({}), mod: t.getEffective({ zones: [mod] }) };
}

describe('the six batch-2 biomes exist and point at their own mod', () => {
  test('each names exactly the mod its mechanic needs', () => {
    expect(BIOMES.space.mod).toBe('lowGravity');
    expect(BIOMES.candy.mod).toBe('sugarRush');
    expect(BIOMES.jelly.mod).toBe('bouncySpring');
    expect(BIOMES.steam.mod).toBe('conveyorBelt');
    expect(BIOMES.micro.mod).toBe('dewSwell');
    expect(BIOMES.vertigo.mod).toBe('geyserVent');
  });

  test('each mod file declares the mechanic the spec table names', () => {
    // Pinned to the SPEC TABLE, not to whatever the file happens to say: this is the line that turns a
    // typing mistake ("bouncy" wired to friction) into a test failure instead of a quiet misdesign.
    expect(MODS.lowGravity.physics.gravityMul).toBeLessThan(1);       // Low gravity
    expect(MODS.sugarRush.physics.speedMul).toBeGreaterThan(1);        // Sugar-rush surge...
    expect(MODS.sugarRush.physics.steerMul).toBeLessThan(1);           // ...with reduced steering
    expect(MODS.bouncySpring.physics.bounceMul).toBeGreaterThan(1);    // Bouncy surfaces
    expect(MODS.conveyorBelt.physics.pushForceMul).toBeGreaterThan(1); // Conveyor push
    expect(MODS.dewSwell.terrainSwell.amplitudePx).toBeGreaterThan(0); // Periodic swells
    expect(MODS.geyserVent.launch.velocityPxS).toBeGreaterThan(0);     // Geysers launch you
  });

  test('every batch-2 biome is ordered after batch 1 in levels.json', () => {
    // D4's order is not cosmetic: the unlock ladder must hand out the cheap mechanics before these.
    const order = LEVELS.biomeOrder;
    const batch1 = ['debutmont', 'garbage-dump-glacier', 'pyramid-peak', 'underwater-mountain', 'crystal-cavern'];
    const lastBatch1 = Math.max(...batch1.map((id) => order.indexOf(id)));
    for (const id of Object.keys(BIOMES).length ? ['space-mountain', 'candy-cane-canyon', 'sky-jellyfish-mountain', 'steampunk-slopes', 'micro-mountain', 'vertigo-vents'] : []) {
      expect({ id, afterBatch1: order.indexOf(id) > lastBatch1 }).toMatchObject({ id, afterBatch1: true });
    }
  });
});

describe('the three constant-based mechanics reach the physics', () => {
  test('Space Mountain lowers gravity and nothing else', () => {
    const { base, mod } = effectOf(MODS.lowGravity);
    expect(mod.gravityPxS2).toBeLessThan(base.gravityPxS2);
    expect(mod.groundResist).toBe(base.groundResist);
    expect(mod.bounceMul).toBe(base.bounceMul);
  });

  test('Candy Cane raises speed and cuts steering, in opposite directions', () => {
    const { base, mod } = effectOf(MODS.sugarRush);
    expect(mod.speedMul).toBeGreaterThan(base.speedMul);
    // Steering is airControl, which is where the sled's tilt authority lives.
    expect(mod.airControl).toBeLessThan(base.airControl);
    // Reduced, never removed: a biome with no steering is a cutscene.
    expect(mod.airControl).toBeGreaterThan(0);
  });

  test('Sky Jellyfish raises bounce', () => {
    const { base, mod } = effectOf(MODS.bouncySpring);
    expect(mod.bounceMul).toBeGreaterThan(base.bounceMul);
    expect(mod.restitution).toBeGreaterThan(base.restitution);
  });

  test('Steampunk drives the sled along the belt, with the sign carried separately', () => {
    const { base, mod } = effectOf(MODS.conveyorBelt);
    // The MECHANIC is a drive the belt applies by itself, not a multiplier on the player's push key. The
    // original assertion here checked pushForceMul rose, which was true while the belt did nothing at all
    // -- that is exactly how an absent mechanic passed its own test for a whole workstream.
    expect(mod.beltDrivePxS2).toBeGreaterThan(0);
    expect(base.beltDrivePxS2).toBe(0);
    expect(MODS.conveyorBelt.direction === 1 || MODS.conveyorBelt.direction === -1).toBe(true);
    expect(mod.beltDirection).toBe(MODS.conveyorBelt.direction);
  });

  test('two overlapping sugar strips compound rather than one winning', () => {
    const t = tuner();
    const one = t.getEffective({ zones: [MODS.sugarRush] });
    const two = t.getEffective({ zones: [MODS.sugarRush, MODS.sugarRush] });
    expect(two.speedMul).toBeGreaterThan(one.speedMul);
  });
});

describe('Micro Mountain lifts the surface', () => {
  /** A generator with a single swell zone planted over a known span. */
  function withSwell(swell) {
    const mods = [{ id: 'synthetic', colorKey: 'cyan', physics: {}, terrainSwell: swell, weight: 1, minDistanceM: 0, lengthPx: [1, 2] }];
    const g = new TerrainGenerator({
      seed: 'swell-seed',
      biomeMask: 0,
      chunkTemplates: [],
      hazardDefs: [],
      modDefs: mods,
    });
    // Reach into the generated chunk to plant the zone: generation is seeded, so a synthetic zone is
    // clearer than trying to make the RNG produce one at a known x.
    const chunk = g._chunkAt(0);
    chunk.zones.length = 0;
    chunk.zones.push({ modId: 'synthetic', x0: 0, x1: 600 });
    return g;
  }

  test('the height differs from the un-swelled line, by at most the amplitude', () => {
    const amp = 20;
    const g = withSwell({ amplitudePx: amp, periodPx: 200 });
    let sawOffset = false;
    for (let x = 0; x <= 600; x += 10) {
      const offset = g._swellAt(x);
      expect(Math.abs(offset)).toBeLessThanOrEqual(amp + 1e-9);
      if (Math.abs(offset) > 1) sawOffset = true;
    }
    expect(sawOffset).toBe(true);
  });

  test('the swell is periodic: it returns to the same offset one period later', () => {
    const g = withSwell({ amplitudePx: 18, periodPx: 240 });
    const a = g._swellAt(40);
    const b = g._swellAt(40 + 240);
    expect(Math.abs(a - b)).toBeLessThan(1e-6);
  });

  test('zero outside the zone', () => {
    const g = withSwell({ amplitudePx: 18, periodPx: 240 });
    expect(g._swellAt(700)).toBe(0);
  });

  test('a swell never inverts the surface: amplitude is bounded by the schema test', () => {
    // The bound that matters is in data.test.js (amplitude must stay small). Here we pin the property
    // that makes the bound sufficient: the offset is a sine, so it can never exceed its amplitude.
    const g = withSwell({ amplitudePx: 26, periodPx: 220 });
    for (let x = 0; x < 600; x += 3) expect(Math.abs(g._swellAt(x))).toBeLessThanOrEqual(26 + 1e-9);
  });

  test('junk swell data contributes nothing rather than throwing', () => {
    const g = withSwell({ amplitudePx: 0, periodPx: 0 });
    expect(() => g._swellAt(100)).not.toThrow();
    expect(g._swellAt(100)).toBe(0);
  });
});

describe('Vertigo Vents launches the sled', () => {
  test('the launch is bounded, cooldown-backed, and actually fires through geyserStep', () => {
    const l = MODS.geyserVent.launch;
    // Enough to clear a normal jump, not enough to leave the playfield.
    expect(l.velocityPxS).toBeGreaterThan(300);
    expect(l.velocityPxS).toBeLessThan(1200);
    // Without a cooldown the vent would re-fire on every contact frame and the sled would never land.
    expect(l.cooldownMs).toBeGreaterThanOrEqual(250);
    // The data being sane is not the mechanic. These assert the consumer exists and behaves.
    const fired = geyserStep({ grounded: true, launch: l, cooldownLeftMs: 0 });
    expect(fired.fire).toBe(true);
    expect(fired.dvy).toBe(-l.velocityPxS);
    expect(fired.cooldownMs).toBe(l.cooldownMs);
    // ...and the tuner actually surfaces it from the mod def, so the sled can see it.
    const { mod } = effectOf(MODS.geyserVent);
    expect(mod.geyserLaunch).toEqual(l);
  });
});/**
 * W3 — biomes batch 1: sector assignment and biome content.
 *
 * `biomeForSector` is the whole of W3's terrain-side change. Everything else is data. That makes it
 * the one function where a mistake silently rewrites terrain, so the tests here are weighted towards
 * the properties that would break existing players: mask 0 must be the home biome everywhere, the
 * choice must not depend on call order or on how much terrain has been generated, and sectors 0-1
 * stay the home biome (Debutmont is the base since #65) so every seed opens the same way.
 */
import fs from 'fs';
import path from 'path';
import { TerrainGenerator, biomeForSector, BASE_BIOME_ID } from '../../src/systems/TerrainGenerator.js';
import { SECTOR_M } from '../../src/systems/TerrainGenerator.js';
import { makeGen, loadContent, readDir } from './_helpers.js';
import { PALETTE_KEYS, PALETTE_NAMES } from '../../src/constants.js';
import { Rng, hashInts } from '../../src/systems/Rng.js';
import { PhysicsTuner } from '../../src/systems/PhysicsTuner.js';

const BIOMES = readDir('biomes');

/**
 * Call the real function with the shipped defs. Passing defs explicitly (rather than letting the
 * function reach for content) is what keeps it pure; without them every biome assertion below would
 * pass trivially because nothing could ever be drawn.
 */
const bio = (seed, sector, mask) => biomeForSector(seed, sector, mask, BIOMES);
const byId = (arr) => Object.fromEntries(arr.map((d) => [d.id, d]));

/** Bit of a biome id, from the data (not typed here: the data owns the mask). */
const bitOf = (id) => BIOMES.find((b) => b.id === id).bit;

describe('biome content — src/data/biomes/*.json', () => {
  test('all eleven biomes are defined, batch 1 and batch 2 together', () => {
    // Pinned by NAME, not by count: a missing biome would silently be a locked sector that can never
    // appear, which is the failure mode worth catching. D1 puts all 11 SledHEAD biomes in scope, so this
    // is the complete set W1-W6 must ship.
    expect(BIOMES.map((b) => b.id).sort()).toEqual([
      'candy-cane-canyon',
      'crystal-cavern',
      'debutmont',
      'garbage-dump-glacier',
      'micro-mountain',
      'pyramid-peak',
      'sky-jellyfish-mountain',
      'space-mountain',
      'steampunk-slopes',
      'underwater-mountain',
      'vertigo-vents',
    ]);
  });

  test('mask bits are distinct powers of two', () => {
    // The mask is a bitfield and is stored in run records; a collision would make two biomes
    // indistinguishable in saved data forever.
    const bits = BIOMES.map((b) => b.bit).sort((a, b) => a - b);
    expect(bits).toEqual([1, 2, 4, 8, 16, 32, 64, 128, 256, 512, 1024]);
    expect(new Set(bits).size).toBe(bits.length);
    // Every bit must fit the mask the profile stores, or the 11th biome would be silently unselectable.
    for (const b of BIOMES) expect({ id: b.id, fits: b.bit > 0 && b.bit <= 1024 }).toMatchObject({ id: b.id, fits: true });
  });

  test('every biome carries the fields the loader and UI read', () => {
    for (const b of BIOMES) {
      expect({ id: b.id, hasName: typeof b.name === 'string' && b.name.length > 0 })
        .toMatchObject({ id: b.id, hasName: true });
      expect({ id: b.id, unlockLevel: b.unlockLevel })
        .toMatchObject({ id: b.id, unlockLevel: expect.any(Number) });
      expect(typeof b.background).toBe('string');
      expect(typeof b.lore).toBe('string');
      expect(b.lore.length).toBeGreaterThan(10);
    }
  });

  test('unlock levels match levels.json, which is what actually unlocks them', () => {
    // levels.json is the source of truth for when a biome unlocks (W1 shipped it). A biome JSON that
    // disagrees would display one level and unlock at another.
    const levels = JSON.parse(fs.readFileSync(path.resolve('src/data/progression/levels.json'), 'utf8'));
    for (const b of BIOMES) {
      const entry = levels.levels.find((l) => l.biome === b.id);
      expect({ id: b.id, unlockLevel: b.unlockLevel })
        .toMatchObject({ id: b.id, unlockLevel: entry.level });
    }
  });

  test('palette overrides are complete for BOTH palettes and never touch danger', () => {
    // Spec: "The `danger` colour never changes with the biome. Hazards must read as hazards in
    // every palette." A biome that recolours danger would make its hazards look safe, which is the
    // one cosmetic mistake that changes how the game plays.
    for (const b of BIOMES) {
      expect({ id: b.id, palettes: Object.keys(b.palettes || {}).sort() })
        .toMatchObject({ id: b.id, palettes: [...PALETTE_NAMES].sort() });
      for (const name of PALETTE_NAMES) {
        const overrides = b.palettes[name] || {};
        expect({ id: b.id, palette: name, keys: Object.keys(overrides).length })
          .toMatchObject({ id: b.id, palette: name, keys: expect.any(Number) });
        // Only real palette keys, and never 'danger'.
        for (const k of Object.keys(overrides)) {
          expect({ id: b.id, key: k, known: PALETTE_KEYS.includes(k) }).toMatchObject({
            id: b.id, key: k, known: true,
          });
          expect({ id: b.id, key: k, isDanger: k === 'danger' }).toMatchObject({
            id: b.id, key: k, isDanger: false,
          });
        }
        for (const v of Object.values(overrides)) expect(v).toMatch(/^#[0-9a-f]{6}$/i);
      }
    }
  });

  test('each biome names a mod that exists and expresses exactly ONE mechanic', () => {
    // D2: "exactly one signature mechanic per biome". That is the invariant; how the mechanic is
    // expressed is not. Four of the five mechanics are physical (drag / loft / gravity / sticky), but
    // Crystal Cavern's is scoring ("tricks landed inside score a combo bonus"), which cannot be
    // written as a physics multiplier at all. So the assertion is one mechanic of one kind - not
    // "a physics multiplier" - and a biome carrying both would be a D2 violation, which is the thing
    // actually worth pinning.
    const mods = byId(readDir('terrainMods'));
    for (const b of BIOMES) {
      const def = mods[b.mod];
      expect({ id: b.id, mod: b.mod, exists: Boolean(def) }).toMatchObject({
        id: b.id, mod: b.mod, exists: true,
      });
      const p = def.physics || {};
      // W6 widened the vocabulary: speedMul (sugar rush) and steerMul are physics too, and two mechanics
      // are neither physics nor scoring — a terrain swell and a launch act on the surface and on contact.
      const muls = ['frictionMul', 'gravityMul', 'bounceMul', 'speedMul', 'steerMul', 'pushForceMul']
        .filter((k) => Number.isFinite(p[k]));
      const hasScore = Number.isFinite(def.scoreMul);
      const hasSwell = Boolean(def.terrainSwell);
      const hasLaunch = Boolean(def.launch);
      const kinds = [muls.length > 0, hasScore, hasSwell, hasLaunch].filter(Boolean).length;
      // Exactly ONE kind of mechanic per biome (D2), whichever kind it is.
      expect({ id: b.id, kinds }).toMatchObject({ id: b.id, kinds: 1 });
      // Never both score and physics: that would be two mechanics in one biome.
      if (hasScore) {
        expect({ id: b.id, alsoPhysics: muls.length }).toMatchObject({ id: b.id, alsoPhysics: 0 });
      }
      // Bounded: a gravityMul of 0.2 would not read as a different biome, it would read as a broken
      // game, and it would make that biome's leaderboard incomparable.
      for (const k of muls) {
        expect({ id: b.id, mul: k, bounded: p[k] >= 0.5 && p[k] <= 2 }).toMatchObject({
          id: b.id, mul: k, bounded: true,
        });
      }
      if (hasScore) {
        expect({ id: b.id, scoreMul: def.scoreMul, bounded: def.scoreMul > 1 && def.scoreMul <= 2 })
          .toMatchObject({ id: b.id, scoreMul: def.scoreMul, bounded: true });
      }
    }
  });

  test('currently shipped mods are untouched (additive only)', () => {
    // The three existing mods are referenced by chunk templates and tested elsewhere. W3 must add
    // mods, never redefine the ones already in play.
    const mods = byId(readDir('terrainMods'));
    for (const id of ['compression', 'highBandwidth', 'wirelessBridge']) {
      expect({ id, present: Boolean(mods[id]) }).toMatchObject({ id, present: true });
    }
  });

  test('each biome names 2-3 chunk template ids that exist', () => {
    const chunks = byId(readDir('chunks'));
    for (const b of BIOMES) {
      expect({ id: b.id, n: (b.chunks || []).length }).toMatchObject({ id: b.id, n: expect.any(Number) });
      expect(b.chunks.length).toBeGreaterThanOrEqual(2);
      expect(b.chunks.length).toBeLessThanOrEqual(3);
      for (const cid of b.chunks) {
        expect({ biome: b.id, chunk: cid, exists: Boolean(chunks[cid]) }).toMatchObject({
          biome: b.id, chunk: cid, exists: true,
        });
      }
    }
  });
});

const ALL_MASK = BIOMES.reduce((m, b) => m | b.bit, 0);

describe('biomeForSector', () => {
  const ALL = ALL_MASK;

  test('sectors 0 and 1 are always the home biome, whatever the mask', () => {
    // Every seed and daily key starts with two home (Debutmont) sectors, so every run opens the same way.
    for (const mask of [0, ALL, bitOf('debutmont'), bitOf('crystal-cavern')]) {
      for (const seed of ['alpha', 'bitstream-bluffs', '2026-11-13']) {
        expect({ seed, mask, s0: bio(seed, 0, mask) }).toMatchObject({ seed, mask, s0: BASE_BIOME_ID });
        expect({ seed, mask, s1: bio(seed, 1, mask) }).toMatchObject({ seed, mask, s1: BASE_BIOME_ID });
      }
    }
  });

  test('mask 0 is the home biome everywhere, for thousands of sectors', () => {
    // The whole point of the mask: a player who has enabled nothing plays pure Debutmont.
    for (const seed of ['alpha', 'bitstream-bluffs', '42']) {
      for (let s = 0; s < 2000; s++) {
        expect({ seed, s, biome: bio(seed, s, 0) }).toMatchObject({ seed, s, biome: BASE_BIOME_ID });
      }
    }
  });

  test('is deterministic and independent of call order', () => {
    const a = [];
    for (let s = 0; s < 400; s++) a.push(bio('order', s, ALL));
    // Ask out of order, and twice for good measure.
    const b = new Array(400);
    for (let s = 399; s >= 0; s -= 1) b[s] = bio('order', s, ALL);
    expect(b).toEqual(a);
    for (let s = 0; s < 400; s += 37) expect(bio('order', s, ALL)).toBe(a[s]);
  });

  test('different seeds give different sector layouts', () => {
    // A layout that ignored the seed would make every run identical, which is the bug this catches.
    const layoutA = [];
    const layoutB = [];
    for (let s = 2; s < 400; s++) {
      layoutA.push(bio('seed-a', s, ALL));
      layoutB.push(bio('seed-b', s, ALL));
    }
    const diff = layoutA.filter((v, i) => v !== layoutB[i]).length;
    expect(diff).toBeGreaterThan(150);
  });

  test('never returns a biome whose bit is not in the mask', () => {
    // The single most important invariant: a locked biome must be impossible, not merely unlikely.
    for (const b of BIOMES) {
      const mask = b.bit;
      for (let s = 0; s < 600; s++) {
        const got = bio('locked', s, mask);
        expect({ s, got, ok: got === BASE_BIOME_ID || got === b.id }).toMatchObject({ s, got, ok: true });
      }
    }
  });

  test('each enabled biome actually appears, and base sectors still occur', () => {
    // A mask where one biome never wins its share is a biome the player cannot reach. The home
    // biome must also survive, or the game would be biome soup with no Debutmont left.
    const seen = new Map();
    for (let s = 2; s < 2000; s++) {
      const got = bio('variety', s, ALL);
      seen.set(got, (seen.get(got) || 0) + 1);
    }
    for (const b of BIOMES) expect({ id: b.id, n: seen.get(b.id) || 0 }).toMatchObject({
      id: b.id, n: expect.any(Number),
    });
    for (const b of BIOMES) expect(seen.get(b.id) || 0).toBeGreaterThan(50);
    // The home biome is the base draw (it is never in the eligible pool), so it dominates its own share.
    expect(seen.get(BASE_BIOME_ID) || 0).toBeGreaterThan(200);
  });

  test('the choice draws from its own stream and does not consume the terrain stream', () => {
    // Spec: "drawing from Rng.fork('biome') so no existing random stream is disturbed". Proved by
    // constructing two generators whose biome stream is exercised a different number of times and
    // requiring identical terrain.
    const a = makeGen('stream-check');
    const b = makeGen('stream-check');
    for (let s = 0; s < 500; s++) bio('stream-check', s, ALL); // poke the biome stream
    for (let i = 0; i < 40; i++) {
      expect(JSON.stringify(a.getChunk(i))).toBe(JSON.stringify(b.getChunk(i)));
    }
  });

  test('the sector length used matches the generator, so banners and terrain agree', () => {
    // A banner that fires on a different boundary than the terrain changes would be visibly wrong.
    expect(SECTOR_M).toBe(500);
    const gen = makeGen('alpha');
    // Chunk 0 starts in sector 1 (1-based, see TerrainChunk.sector); sector 2 begins at 500 m.
    expect(gen.getChunk(0).sector).toBe(1);
  });
});

describe('biome mechanics actually reach the physics', () => {
  // A biome whose mod exists but whose multipliers never touch the sled is a skin, not a mechanic -
  // D2 requires one signature mechanic each. This checks the number the tuner hands the physics step,
  // not the JSON, so a typo in a multiplier name (gravityMult vs gravityMul) fails here.
  const mods = byId(readDir('terrainMods'));
  const tuner = () => new PhysicsTuner();

  const effectOf = (modId) => {
    const t = tuner();
    const base = t.getEffective({});
    const mod = t.getEffective({ zones: [mods[modId]] });
    return { base, mod };
  };

  test('every physics biome changes gravity, ground resistance or bounce', () => {
    for (const b of BIOMES) {
      const def = mods[b.mod];
      // Scoring and the two W6 surface/contact mechanics are covered by their own tests below; this one
      // is about the biomes whose mechanic is an effective constant.
      if (Number.isFinite(def.scoreMul) || def.terrainSwell || def.launch) continue;
      const { base, mod } = effectOf(b.mod);
      // W6 widened this from three fields: sugar rush changes terminal speed and steering, the conveyor
      // changes push force. A mechanic that reaches NO effective constant is the bug being caught.
      const changed =
        mod.gravityPxS2 !== base.gravityPxS2 ||
        mod.groundResist !== base.groundResist ||
        mod.bounceMul !== base.bounceMul ||
        mod.speedMul !== base.speedMul ||
        mod.pushForceMul !== base.pushForceMul ||
        mod.airControl !== base.airControl;
      expect({ biome: b.id, mod: b.mod, changed }).toMatchObject({ biome: b.id, mod: b.mod, changed: true });
    }
  });

  test('the direction of each mechanic matches the spec table', () => {
    // "more drag ... more loft", "sticky patches that bleed speed", "updraft zones that extend airtime",
    // "lower gravity and higher drag together". A sign flip would make a biome play the opposite of its
    // name and nobody would notice from the data alone.
    const powder = effectOf('powderFlurry');
    expect(powder.mod.groundResist).toBeGreaterThan(powder.base.groundResist); // more drag
    expect(powder.mod.bounceMul).toBeGreaterThan(powder.base.bounceMul); // more loft

    const sticky = effectOf('stickyPatch');
    expect(sticky.mod.groundResist).toBeGreaterThan(sticky.base.groundResist);

    const thermal = effectOf('thermalUpdraft');
    expect(thermal.mod.gravityPxS2).toBeLessThan(thermal.base.gravityPxS2); // longer airtime

    const slow = effectOf('slowMotion');
    expect(slow.mod.gravityPxS2).toBeLessThan(slow.base.gravityPxS2);
    expect(slow.mod.groundResist).toBeGreaterThan(slow.base.groundResist);
  });

  test('no biome turns the gravity into a different game', () => {
    // Bounds, not direction: a zone may flavour a sector, never disable physics.
    for (const b of BIOMES) {
      const def = mods[b.mod];
      if (Number.isFinite(def.scoreMul) || def.terrainSwell || def.launch) continue;
      const { base, mod } = effectOf(b.mod);
      const ratio = mod.gravityPxS2 / base.gravityPxS2;
      expect({ biome: b.id, ratio: expect.any(Number) }).toMatchObject({ biome: b.id, ratio: expect.any(Number) });
      expect(ratio).toBeGreaterThanOrEqual(0.7);
      expect(ratio).toBeLessThanOrEqual(1.3);
      // The same bound has to hold for the multipliers W6 added, or a biome could quietly make the sled
      // unsteerable (steer ~0) or launch it off the map (speed 3x) without tripping the gravity check.
      expect({ biome: b.id, speed: mod.speedMul }).toMatchObject({ biome: b.id, speed: expect.any(Number) });
      expect(mod.speedMul).toBeGreaterThanOrEqual(0.5);
      expect(mod.speedMul).toBeLessThanOrEqual(1.4);
      // Steering may be reduced hard (that is sugar rush's whole idea) but never to zero: a biome that
      // takes steering away entirely is not a mechanic, it is a cutscene.
      expect(mod.airControl).toBeGreaterThan(0);
      expect(mod.pushForceMul).toBeGreaterThanOrEqual(0.5);
      expect(mod.pushForceMul).toBeLessThanOrEqual(2.5);
    }
  });

  test('zones inside a biome sector are the biome\'s own mod', () => {
    // Confirms the generator wires a biome sector's zone to that biome, not to a shared default.
    for (const b of BIOMES) {
      const gen = new TerrainGenerator({
        seed: 'zone-wiring',
        chunkDefs: readDir('chunks'), hazardDefs: byId(readDir('hazards')), powerupDefs: byId(readDir('powerups')),
        modDefs: mods, biomeDefs: BIOMES, biomeMask: ALL_MASK,
      });
      let found = 0;
      for (let i = 0; i < 400 && found < 3; i++) {
        const c = gen.getChunk(i);
        if (c.biome !== b.id) continue;
        for (const z of c.zones) if (z.modId === b.mod) found++;
      }
      expect({ biome: b.id, mod: b.mod, found }).toMatchObject({ biome: b.id, mod: b.mod, found: expect.any(Number) });
      expect(found).toBeGreaterThan(0);
    }
  });
});

describe('terrain determinism with a biome mask (W3 gate: same seed + mask -> same terrain, twice)', () => {
  // The spec asks for this at the TERRAIN level, not just the sector function. A generator that
  // consulted mutable state (or reused a stream across builds) could agree on which biome owns a
  // sector and still emit different chunks for it.
  const build = (seed, mask, n) => {
    const gen = new TerrainGenerator({
      seed,
      chunkDefs: readDir('chunks'), hazardDefs: byId(readDir('hazards')), powerupDefs: byId(readDir('powerups')),
      modDefs: byId(readDir('terrainMods')), biomeDefs: BIOMES, biomeMask: mask,
    });
    const out = [];
    for (let i = 0; i < n; i++) out.push(JSON.stringify(gen.getChunk(i)));
    return out;
  };

  test('the same seed and mask produce byte-identical chunks on two separate builds', () => {
    for (const mask of [0, 1, 16, ALL_MASK]) {
      const a = build('det-seed', mask, 120);
      const b = build('det-seed', mask, 120);
      expect({ mask, same: JSON.stringify(a) === JSON.stringify(b) }).toMatchObject({ mask, same: true });
    }
  });

  test('a masked build differs from mask 0, so the mask is not silently ignored', () => {
    // Guards the failure that made the first sim comparison meaningless: a mask that never reaches
    // the generator looks deterministic and identical, and proves nothing.
    const zero = build('det-seed', 0, 120);
    const masked = build('det-seed', ALL_MASK, 120);
    expect(JSON.stringify(zero)).not.toBe(JSON.stringify(masked));
  });

  test('generation order does not change the terrain', () => {
    // A player streams chunks left to right; a pooled-chunk bug would make the same chunk differ
    // depending on what was generated before it.
    const gen = new TerrainGenerator({
      seed: 'order-terrain',
      chunkDefs: readDir('chunks'), hazardDefs: byId(readDir('hazards')), powerupDefs: byId(readDir('powerups')),
      modDefs: byId(readDir('terrainMods')), biomeDefs: BIOMES, biomeMask: ALL_MASK,
    });
    const forward = [];
    for (let i = 0; i < 60; i++) forward.push(JSON.stringify(gen.getChunk(i)));
    // Re-read the same chunks in a different order on a fresh generator.
    const gen2 = new TerrainGenerator({
      seed: 'order-terrain',
      chunkDefs: readDir('chunks'), hazardDefs: byId(readDir('hazards')), powerupDefs: byId(readDir('powerups')),
      modDefs: byId(readDir('terrainMods')), biomeDefs: BIOMES, biomeMask: ALL_MASK,
    });
    for (const i of [59, 12, 0, 33, 7, 45]) {
      expect({ i, chunk: JSON.stringify(gen2.getChunk(i)) }).toMatchObject({ i, chunk: forward[i] });
    }
  });
});import { spawnSync } from 'node:child_process';
import { EventEmitter } from 'node:events';
import { mkdtempSync, rmSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { EVT } from '../../src/events.js';
import { SimClock } from '../../src/systems/SimClock.js';
import { assertPrivateCrashBriefChecks, replayFrames, replayKeys } from '../../tools/sim/benchmark-replay.mjs';
import { checkFatalObservation, crashBriefReport } from '../../tools/sim/replay-crash-brief.js';

const tape = { endTick: 2, checkpoints: [[2]] };
const event = { tick: 3, cause: 'hazard', hazardId: 'glitchChasm', x: 12345.625, y: 67.25, speedPxS: 400 };
const observation = () => ({ tick: 3, checked: 1, crashed: true, droppedMs: 0, savedRecord: false, desync: null,
  states: [1, 2, 3].map((t) => [t, t * 2, t * 3, 0, 2, 1, 0, 12345, 42, t === 3]),
  fatalCount: 1, fatalEvent: { ...event }, pageInfo: { gameEntry: 'private-local-path' } });

function fakeGame({ fatalAt = 3, duplicate = false, runId = 'private-run-identity', throws = false } = {}) {
  const run = { runId: 'private-run-identity', simClock: new SimClock(), tapePlayer: { desync: null, checked: 1 },
    sled: { body: { position: { x: 0, y: 0 }, velocity: { x: 0, y: 0 }, angle: 0, angularVelocity: 0 } },
    score: { getTotal: () => 0 }, runRandom: { physicsScramble: { state: 42 } } };
  const events = new EventEmitter();
  const game = { events, registry: { get: () => null }, scene: { getScene: () => run },
    step() {
      const tick = ++run.simClock.tick;
      if (throws) throw new Error('unexpected');
      const payload = { ...event, runId };
      if (tick === 1) events.emit(EVT.CRASH, { ...payload, fatal: false, negated: true });
      if (tick === fatalAt) {
        run.crashed = true;
        events.emit(EVT.CRASH, { ...payload, fatal: true, negated: false });
        if (duplicate) events.emit(EVT.CRASH, { ...payload, fatal: true, negated: false });
      }
    } };
  return game;
}
const drive = (game, crashEvent = EVT.CRASH) => replayFrames({ tickLimit: 3, measure: false, keys: replayKeys, crashEvent }, game);

test('observes only the live fatal replay event, stops on its tick, and detaches the listener', () => {
  const game = fakeGame();
  const observed = drive(game);
  expect(observed).toMatchObject({ tick: 3, crashed: true, fatalCount: 1, fatalEvent: event });
  expect(observed.fatalEvent).not.toHaveProperty('runId');
  expect(game.events.listenerCount(EVT.CRASH)).toBe(0);
  const broken = fakeGame({ throws: true });
  expect(() => drive(broken)).toThrow('unexpected');
  expect(broken.events.listenerCount(EVT.CRASH)).toBe(0);
  const ordinary = fakeGame();
  expect(drive(ordinary, null)).not.toHaveProperty('fatalEvent');
  expect(ordinary.events.listenerCount(EVT.CRASH)).toBe(0);
});

test.each([{ fatalAt: 2 }, { fatalAt: 4 }, { duplicate: true }, { runId: 'unexpected-private-id' }])(
  'rejects an early, missing, duplicate or unassociated fatal event %j', (options) => {
    expect(() => checkFatalObservation(drive(fakeGame(options)), 3)).toThrow(/exactly one fatal crash/);
  });

test('two valid observations pass; independent exact private facts are required and never appear in diagnostics', () => {
  expect(() => assertPrivateCrashBriefChecks(observation(), tape, observation(), 2)).not.toThrow();
  for (const [mutate, expected] of [
    [(r) => { r.fatalEvent.cause = 'private-custom-category'; }, 'Replay emitted an unsupported fatal crash observation'],
    [(r) => { r.fatalEvent.speedPxS = 12345.625; }, 'Fatal observations differed between fresh replays'],
    [(r) => { r.fatalEvent.hazardId = 'private-custom-hazard'; }, 'Fatal observations differed between fresh replays'],
    [(r) => { r.fatalEvent.x = 12345; }, 'Fatal observations differed between fresh replays'],
    [(r) => { r.fatalEvent.y = NaN; }, 'Replay emitted an unsupported fatal crash observation'],
    [(r) => { r.checked = 0; }, 'Crash brief replay did not pass the checkpoint and isolation checks'],
    [(r) => { r.desync = { got: [12345.625] }; }, 'Crash brief replay did not pass the checkpoint and isolation checks'],
    [(r) => { r.savedRecord = true; }, 'Crash brief replay did not pass the checkpoint and isolation checks'],
    [(r) => { r.droppedMs = 42; }, 'Crash brief replay did not pass the checkpoint and isolation checks'],
    [(r) => { r.states.pop(); }, 'Crash brief replay did not pass the checkpoint and isolation checks'],
    [(r) => { r.states[0][2] = 12345.625; }, 'Crash brief observations differed between fresh replays'],
    [(r) => { r.pageInfo.gameEntry = 'other-private-local-path'; }, 'Crash brief observations differed between fresh replays'],
  ]) {
    const result = observation();
    mutate(result);
    expect(() => assertPrivateCrashBriefChecks(result, tape, observation(), 2)).toThrow(new Error(expected));
  }
});

test('report exports only fixed fields, known categories and an optional static fatal terrain hazard ID', () => {
  const report = crashBriefReport({ ...event, runId: 'private-run-identity', seed: 'private-seed', score: 9999 }, 2, 6);
  expect(report).toEqual({
    kind: 'local-replay-crash-brief', reportVersion: 1,
    scope: 'local unverified replay reproduction; not proof of the original crash',
    build: { sameBuildAsserted: true, independentlyVerified: false },
    replay: { freshRuns: 2, checkpointsCheckedPerRun: 6, matchedStateAndFatalEvent: true, savedRunsOrTapes: false },
    crash: { category: 'hazard', hazardId: 'glitchChasm' },
  });
  for (const hazardId of ['private-custom-id', 'ashCloud', 'shatterWall']) {
    expect(crashBriefReport({ ...event, hazardId }, 2, 6).crash).toEqual({ category: 'hazard' });
  }
  expect(crashBriefReport({ ...event, cause: 'terrain' }, 2, 6).crash).toEqual({ category: 'terrain' });
  expect(() => crashBriefReport({ ...event, cause: 'private-unsupported' }, 2, 6)).toThrow(new Error('Replay emitted an unsupported crash category'));
});

test('mode is explicit, strictly independent of airtime and emits nothing or leaks pass-through copy on failure', () => {
  const pin = 'a'.repeat(40), tool = 'tools/sim/benchmark-replay.mjs';
  const launch = (...args) => spawnSync(process.execPath, [tool, ...args], { encoding: 'utf8' });
  const crash = ['--crash-brief-build', pin];
  const tmp = mkdtempSync(join(tmpdir(), 'bb-replay-private-'));
  const local = join(tmp, 'private-tape.json');
  try {
    for (const [args, diagnostic] of [
      [[], 'explicit saved --tape'],
      [['--airtime-build', pin], 'not both'],
      [['--tape', local, '--ticks', '12345'], 'does not accept --ticks'],
      [['--tape', local, '--repeats', '1'], '2–5 fresh runs'],
      [['--tape', local, '--url', 'https://user-secret.invalid/'], 'HTTP loopback'],
      [['--tape', local], 'readable, bounded, complete compatible normal-run tape'],
      [['--private-user-payload'], 'failed before verification'],
    ]) {
      const result = launch(...crash, ...args);
      expect(result).toMatchObject({ status: 1, stdout: '', stderr: expect.stringContaining(diagnostic) });
      expect(result.stderr).not.toMatch(/private-|user-secret|12345/);
      expect(result.stderr).not.toContain(pin);
    }
    writeFileSync(local, '{"seed":"private-user-payload"}');
    expect(launch(...crash, '--tape', local)).toMatchObject({ status: 1, stdout: '',
      stderr: 'Crash brief needs a readable, bounded, complete compatible normal-run tape\n' });
    expect(launch('--crash-brief-build', 'private-bad-build').stderr).toBe('Crash brief requires a full 40-hex Git build commit\n');
  } finally { rmSync(tmp, { force: true, recursive: true }); }
});/**
 * Boosts apply only once the profile OWNS them. Head Start unlocks at Sync Level 8 and the Error Correction
 * Engine at 15 (levels.json; ProfileStore records them in `profile.unlocked.boosts` as `{ id: level }`).
 * A toggle that is switched on but not owned must not change the run and must not mark it modded.
 *
 * The rule lives in the pure Boosts.js: `boostEffects`, `isModdedRun` and `loadoutForRun` take the owned
 * set as `o.unlocked`, and an omitted set owns nothing (default off, like the toggles themselves).
 */
import fs from 'fs';
import { jest } from '@jest/globals';

jest.unstable_mockModule('phaser', () => ({
  default: { Scene: class {}, GameObjects: new Proxy({}, { get: () => class {} }) },
}));
jest.unstable_mockModule('../../src/data/index.js', () => ({ content: {}, loadContent: () => ({}) }));

const { sanitizeProfile } = await import('../../src/systems/ProfileStore.js');
const { boostEffects, isModdedRun, loadoutForRun, BOOST_DEFS } = await import('../../src/systems/Boosts.js');

const LEVELS = JSON.parse(fs.readFileSync('src/data/progression/levels.json', 'utf8'));
const v1 = (o = {}) => sanitizeProfile({ v: 1, ...o }, LEVELS);
const BOTH_ON = { boosts: { errorCorrection: true, headStart: true } };

describe('boosts are gated by their level unlock', () => {
  test('a level-1 profile with boosts.headStart=true does not start a boosted run', () => {
    const p = v1({ boosts: { headStart: true } });
    expect(p.level).toBe(1);
    const loadout = { boosts: { ...p.boosts } };
    expect(boostEffects(loadout, { daily: false }).speedFactor).toBe(1);
    expect(boostEffects(loadout, { daily: false, unlocked: p.unlocked.boosts }))
      .toEqual({ shieldCharges: 0, speedFactor: 1, modded: false });
  });

  test('only owned boosts apply, and only an owned boost marks the run modded', () => {
    const headStartOnly = { headStart: 8 };
    expect(boostEffects(BOTH_ON, { unlocked: headStartOnly })).toEqual({ shieldCharges: 0, speedFactor: BOOST_DEFS.headStart.speedFactor, modded: true });
    expect(isModdedRun(BOTH_ON, { unlocked: headStartOnly })).toBe(true);
    expect(loadoutForRun(BOTH_ON, { unlocked: headStartOnly }).boosts).toEqual({ errorCorrection: false, headStart: true });

    expect(isModdedRun(BOTH_ON, { unlocked: {} })).toBe(false);
    expect(loadoutForRun(BOTH_ON, { unlocked: {} }).boosts).toEqual({ errorCorrection: false, headStart: false });
    expect(boostEffects(BOTH_ON, { unlocked: { headStart: 8, errorCorrection: 15 } }))
      .toEqual({ shieldCharges: 1, speedFactor: BOOST_DEFS.headStart.speedFactor, modded: true });
  });

  test('an omitted owned set owns nothing', () => {
    expect(boostEffects(BOTH_ON)).toEqual({ shieldCharges: 0, speedFactor: 1, modded: false });
    expect(isModdedRun(BOTH_ON)).toBe(false);
  });

  test('a junk unlock value owns nothing', () => {
    for (const junk of [0, -8, '8', true, null, NaN, Infinity]) {
      expect({ junk: String(junk), fx: boostEffects({ boosts: { headStart: true } }, { unlocked: { headStart: junk } }) })
        .toMatchObject({ fx: { speedFactor: 1, modded: false } });
    }
  });

  test('the Daily still refuses owned boosts', () => {
    expect(boostEffects(BOTH_ON, { daily: true, unlocked: { headStart: 8, errorCorrection: 15 } }))
      .toEqual({ shieldCharges: 0, speedFactor: 1, modded: false });
  });
});/**
 * W4 — boosts: default off, refused on the Daily, and the single source of `record.modded`.
 *
 * The dangerous half of this feature is not the shield or the speed; it is the flag. `record.modded`
 * decides whether a run is eligible for any clean board, so it must be derived in exactly one place and
 * must be impossible to forget. Two failure modes are pinned here:
 *
 *   1. A loadout that is absent, empty, or holds a junk value must produce modded=false. If a missing
 *      field read as "boosted", every run would be quietly exiled from the boards.
 *   2. A Daily run must be modded=false even when the player's saved loadout has boosts ON, because the
 *      daily refuses them. Otherwise the daily leaderboard would either hide honest daily runs or admit
 *      a boosted one.
 */
import {
  BOOSTS, BOOST_DEFS, enabledBoosts, loadoutForRun, isModdedRun, boostEffects, setBoost,
} from '../../src/systems/Boosts.js';

// F3: a boost applies only once the profile owns it (`unlocked.boosts`, Sync Level 8 / 15). These tests are
// about what an OWNED boost does, so they pass the owned set; boost-unlocks.test.js covers the gate itself.
const OWNED = { unlocked: { errorCorrection: 15, headStart: 8 } };

describe('defaults', () => {
  test('an absent or empty loadout enables nothing', () => {
    for (const l of [undefined, null, {}, { boosts: {} }, { boosts: { headStart: false } }]) {
      expect({ l: JSON.stringify(l), on: enabledBoosts(l) }).toMatchObject({ on: [] });
    }
  });

  test('a junk value does not enable a boost', () => {
    // 'true', 1, and 'yes' are all not `true`. A hand-edited save must not grant a boost.
    for (const junk of ['true', 1, 'yes', {}, []]) {
      expect({ junk: JSON.stringify(junk), on: enabledBoosts({ boosts: { headStart: junk } }) })
        .toMatchObject({ on: [] });
    }
  });

  test('an unknown boost id is ignored, not carried through', () => {
    expect(enabledBoosts({ boosts: { warpDrive: true, headStart: true } })).toEqual(['headStart']);
  });

  test('a clean run reports modded false', () => {
    expect(isModdedRun({})).toBe(false);
    expect(isModdedRun({ boosts: { headStart: false } })).toBe(false);
  });

  test('any boost reports modded true', () => {
    for (const id of BOOSTS) {
      expect({ id, modded: isModdedRun({ boosts: { [id]: true } }, OWNED) }).toMatchObject({ id, modded: true });
    }
  });
});

describe('the Daily refuses boosts', () => {
  test('a boosted loadout produces a clean run on the daily', () => {
    const loadout = { boosts: { errorCorrection: true, headStart: true } };
    expect(loadoutForRun(loadout, { daily: true }).boosts).toEqual({ errorCorrection: false, headStart: false });
    expect(isModdedRun(loadout, { daily: true })).toBe(false);
  });

  test('the daily still gets no shield and no head start', () => {
    const eff = boostEffects({ boosts: { errorCorrection: true, headStart: true } }, { daily: true });
    expect(eff).toEqual({ shieldCharges: 0, speedFactor: 1, modded: false });
  });

  test('a daily run is never marked modded, even by a boosted save', () => {
    // This is what keeps the daily leaderboard honest while MODDED_RUNS_RANKED is false.
    expect(isModdedRun({ boosts: { headStart: true } }, { daily: true })).toBe(false);
  });
});

describe('effects', () => {
  test('Error Correction Engine starts with exactly one shield charge', () => {
    const eff = boostEffects({ boosts: { errorCorrection: true } }, OWNED);
    expect(eff.shieldCharges).toBe(1);
    expect(eff.speedFactor).toBe(1);
    expect(eff.modded).toBe(true);
  });

  test('Head Start raises the starting speed and nothing else', () => {
    const eff = boostEffects({ boosts: { headStart: true } }, OWNED);
    expect(eff.speedFactor).toBeGreaterThan(1);
    expect(eff.shieldCharges).toBe(0);
  });

  test('both together apply both, and their factors multiply once', () => {
    const eff = boostEffects({ boosts: { errorCorrection: true, headStart: true } }, OWNED);
    expect(eff.shieldCharges).toBe(1);
    expect(eff.speedFactor).toBe(BOOST_DEFS.headStart.speedFactor);
  });

  test('an unboosted run has no effects at all', () => {
    expect(boostEffects({})).toEqual({ shieldCharges: 0, speedFactor: 1, modded: false });
  });

  test('Head Start does not touch a physics constant', () => {
    // Spec W4 / §6: no change to physics tuning constants outside a biome's own bounded mod. Head Start
    // is a starting velocity, so PHYSICS must be identical to a clean run's; this asserts the module
    // exposes no physics override at all.
    const eff = boostEffects({ boosts: { headStart: true } }, OWNED);
    expect(Object.keys(eff).sort()).toEqual(['modded', 'shieldCharges', 'speedFactor']);
    expect(eff).not.toHaveProperty('gravityPxS2');
    expect(eff).not.toHaveProperty('dragUntucked');
  });
});

describe('setBoost', () => {
  test('turning a boost on and off round-trips', () => {
    const on = setBoost({}, 'headStart', true);
    expect(on.boosts.headStart).toBe(true);
    expect(setBoost(on, 'headStart', false).boosts.headStart).toBe(false);
  });

  test('setting a boost does not disturb the other', () => {
    const l = setBoost(setBoost({}, 'headStart', true), 'errorCorrection', true);
    expect(l.boosts).toEqual({ errorCorrection: true, headStart: true });
    const off = setBoost(l, 'headStart', false);
    expect(off.boosts).toEqual({ errorCorrection: true, headStart: false });
  });

  test('an unknown id leaves the loadout usable rather than throwing', () => {
    expect(setBoost({ boosts: { headStart: true } }, 'nope', true).boosts.headStart).toBe(true);
  });
});/**
 * Sky Jellyfish bounce is felt (Marvin's ruling, 2026-11-16). Measured on the real sled in the built game: the zone's
 * body restitution (0.02 * bounceMul^2 = 0.072, and even 0.32 at bounceMul 4) gives a rebound on only one drop pose of
 * five, because Matter restitution on the terrain body plus the sled's own ground handling eats the normal speed. So the
 * felt bounce is a landing rebound: once per scored landing inside a zone that carries `physics.landingRebound`, the
 * sled is thrown back up by a share of its touchdown impact speed (BiomeEffects.springRebound), bounded and decaying.
 * PhysicsTuner combines the share (zones, then the Stabilizer Rails' bounceMul squared, as restitution does).
 */
import {
  springRebound, springReboundVelocity, SPRING_REBOUND_MIN_PX_S, SPRING_REBOUND_MAX_PX_S, stabilizeBounceMul,
} from '../../src/systems/BiomeEffects.js';
import { PhysicsTuner } from '../../src/systems/PhysicsTuner.js';
import { CRASH_IMPACT_PX_S } from '../../src/systems/TrickTracker.js';
import { loadContent } from './_helpers.js';

const C = loadContent();
const MODS = C.terrainMods;
const RAILS = stabilizeBounceMul(C.powerups.stabilizerRails.effect.bounceMul);

describe('BiomeEffects.springRebound (pure)', () => {
  test('no share, no rebound; bad input is no rebound', () => {
    expect(springRebound(600, 0)).toBe(0);
    expect(springRebound(600, undefined)).toBe(0);
    expect(springRebound(NaN, 0.3)).toBe(0);
    expect(springRebound(-500, 0.3)).toBe(0);
  });

  test('the rebound is the share of the impact speed above the felt floor', () => {
    expect(springRebound(500, 0.3)).toBeCloseTo(150, 9);
    expect(springRebound(300, 0.3)).toBe(0);
  });

  test('the felt floor is 120 px/s, inclusive: 500*.2 is quiet, 600*.2 and 800*.2 are felt', () => {
    expect(SPRING_REBOUND_MIN_PX_S).toBe(120);
    expect(springRebound(500, 0.2)).toBe(0);
    expect(springRebound(600, 0.2)).toBeCloseTo(120, 9);
    expect(springRebound(800, 0.2)).toBeCloseTo(160, 9);
    // the Rails cut the share to 0.05: even an 801 px/s impact stays under the floor
    expect(springRebound(801, 0.05)).toBe(0);
  });

  test('a small rebound is no rebound (it ends the chain), a big one is capped (never a launch)', () => {
    expect(SPRING_REBOUND_MIN_PX_S).toBeGreaterThan(0);
    expect(springRebound((SPRING_REBOUND_MIN_PX_S - 1) / 0.3, 0.3)).toBe(0);
    expect(springRebound(CRASH_IMPACT_PX_S, 0.9)).toBe(SPRING_REBOUND_MAX_PX_S);
    expect(SPRING_REBOUND_MAX_PX_S).toBeLessThanOrEqual(300);
  });

  test('the share is clamped below 1, so a rebound never returns more than it got', () => {
    expect(springRebound(200, 5)).toBeLessThan(200);
  });

  test('no infinite pogo: a chain of touchdowns, each one landing at the speed the last rebound left at, stops within 4 bounces', () => {
    const share = MODS.bouncySpring.physics.landingRebound;
    for (const impact of [150, 300, 500, 800, CRASH_IMPACT_PX_S - 1]) {
      let v = impact; let n = 0;
      while ((v = springRebound(v, share)) > 0) { n++; if (n > 10) break; }
      expect(n).toBeLessThanOrEqual(4);
    }
  });
});

const tangent = (v, angleDeg) => {
  const a = (angleDeg * Math.PI) / 180;
  return v.vx * Math.cos(a) + v.vy * Math.sin(a);
};
const outwardNormal = (v, angleDeg) => {
  const a = (angleDeg * Math.PI) / 180;
  return v.vx * Math.sin(a) - v.vy * Math.cos(a);
};

describe('BiomeEffects.springReboundVelocity (slope-normal, no forward energy)', () => {
  test('on flat ground it is a vertical rebound: horizontal speed is untouched', () => {
    const out = springReboundVelocity(420, 180, 0, 150);
    expect(out.vx).toBeCloseTo(420, 9);
    expect(out.vy).toBeCloseTo(-150, 9);
  });

  test('on every slope the along-slope speed is exactly preserved and the outward normal becomes max(old, desired)', () => {
    for (const angle of [-35, -18, 0, 12, 30, 42]) {
      for (const [vx, vy, up] of [[520, 180, 140], [0, 0, 100], [-80, 260, 90], [600, -40, 60]]) {
        const before = { vx, vy };
        const after = springReboundVelocity(vx, vy, angle, up);
        expect(tangent(after, angle)).toBeCloseTo(tangent(before, angle), 9);
        expect(outwardNormal(after, angle)).toBeCloseTo(Math.max(outwardNormal(before, angle), up), 9);
        // a rebound may never inject speed along the slope (a global vertical launch changes this component)
        expect(Math.abs(tangent(after, angle))).toBeLessThanOrEqual(Math.abs(tangent(before, angle)) + 1e-9);
      }
    }
  });

  test('a downhill 600 px/s roll keeps its tangent and gains only the requested 120 px/s normal rebound', () => {
    const a = (30 * Math.PI) / 180;
    const out = springReboundVelocity(600 * Math.cos(a), 600 * Math.sin(a), 30, 120);
    expect(tangent(out, 30)).toBeCloseTo(600, 9);
    expect(outwardNormal(out, 30)).toBeCloseTo(120, 9);
    expect(Math.hypot(out.vx, out.vy)).toBeCloseTo(Math.hypot(600, 120), 9);
    expect(Math.hypot(out.vx, out.vy)).toBeLessThan(Math.hypot(600, 600));
  });

  test('an already-outward velocity faster than the wanted rebound is left alone', () => {
    const out = springReboundVelocity(300, -220, 0, 100);
    expect(out.vx).toBeCloseTo(300, 9);
    expect(out.vy).toBeCloseTo(-220, 9);
    const touching = springReboundVelocity(300, 20, 0, 0);
    expect(touching.vx).toBeCloseTo(300, 9);
    expect(touching.vy).toBeCloseTo(20, 9);
  });

  test('bad input is safe (no NaN velocity)', () => {
    expect(springReboundVelocity(NaN, 5, NaN, NaN)).toEqual({ vx: 0, vy: 5 });
    expect(Number.isFinite(springReboundVelocity(Infinity, 5, undefined, 90).vx)).toBe(true);
  });
});

describe('PhysicsTuner: landingRebound', () => {
  const t = new PhysicsTuner();

  test('base, mask-0 mods and every other biome mod carry no rebound (only bouncySpring changes)', () => {
    expect(t.getEffective({}).landingRebound).toBe(0);
    for (const [id, m] of Object.entries(MODS)) {
      if (id === 'bouncySpring') continue;
      expect([id, t.getEffective({ zones: [m] }).landingRebound]).toEqual([id, 0]);
    }
  });

  test('bouncySpring carries a felt, fair share; its restitution and bounceMul are unchanged', () => {
    const e = t.getEffective({ zones: [MODS.bouncySpring] });
    expect(e.landingRebound).toBeGreaterThanOrEqual(0.15);
    expect(e.landingRebound).toBeLessThanOrEqual(0.45);
    expect(MODS.bouncySpring.physics.bounceMul).toBe(1.9);
    expect(e.restitution).toBeCloseTo(0.02 * 1.9 * 1.9, 12);
    // a strong 800 px/s touchdown in the zone rebounds at the felt 160 px/s the shrink-test measured
    expect(springRebound(800, e.landingRebound)).toBeCloseTo(160, 9);
  });

  test('the Stabilizer Rails scale the share by bounceMul squared (as restitution): the same landing rebounds far less', () => {
    const bare = t.getEffective({ zones: [MODS.bouncySpring] }).landingRebound;
    const railed = t.getEffective({ zones: [MODS.bouncySpring], stabilizeBounceMul: RAILS }).landingRebound;
    expect(railed).toBeCloseTo(bare * RAILS * RAILS, 12);
    expect(springRebound(800, railed)).toBeLessThan(springRebound(800, bare) * 0.5);
    // at the shipped share the railed 801 px/s impact (40 px/s) is below the 120 px/s floor: no rebound at all
    expect(springRebound(801, railed)).toBe(0);
  });

  test('two overlapping spring zones do not compound into a bigger launch (the larger share wins)', () => {
    const one = t.getEffective({ zones: [MODS.bouncySpring] }).landingRebound;
    expect(t.getEffective({ zones: [MODS.bouncySpring, MODS.bouncySpring] }).landingRebound).toBe(one);
  });
});import { PHYSICS } from '../../src/constants.js';
import { TUNING } from '../../src/systems/PhysicsTuner.js';
import { aerodynamicStep, airBrakeKickStep, canopyFuelStep, canopySailFactor, vacuumDivebombStep } from '../../src/systems/BsodAerodynamics.js';

describe('BSOD aerodynamics (pure)', () => {
  test('fuel only drains while held in flight; successive taps share one tank', () => {
    let f = canopyFuelStep(880, true, true, 100);
    expect(f).toEqual({ fuelMs: 780, deployed: true });
    f = canopyFuelStep(f.fuelMs, false, true, 300);
    expect(f).toEqual({ fuelMs: 780, deployed: false });
    f = canopyFuelStep(f.fuelMs, true, true, 200);
    expect(f).toEqual({ fuelMs: 580, deployed: true });
    f = canopyFuelStep(f.fuelMs, true, false, 1);
    expect(f).toEqual({ fuelMs: 880, deployed: false });
  });
  test('no micro negative fuel even on long substep', () => {
    const r=canopyFuelStep(2,true,true,8);
    expect(r.fuelMs).toBe(0);
    expect(r.deployed).toBe(true);
    expect(canopyFuelStep(0,true,true,8).deployed).toBe(false);
  });
  test('low-speed sail catches more tailwind than racing rider', () => {
    expect(canopySailFactor(0)).toBeGreaterThan(canopySailFactor(600));
    const slow=aerodynamicStep({vx:0,relativeAirX:400,parachute:true});
    const fast=aerodynamicStep({vx:600,relativeAirX:400,parachute:true});
    expect(slow.dvx).toBeGreaterThan(fast.dvx);
    expect(slow.dvy).toBeLessThan(0);
  });
  test('signed headwind pulls backwards and wind matching causes no forward acceleration', () => {
    expect(aerodynamicStep({vx:900,relativeAirX:-380,parachute:true}).dvx).toBeLessThan(0);
    expect(aerodynamicStep({vx:50,relativeAirX:0,parachute:true}).dvx).toBe(0);
  });
  test('one AirBrake activation is a pair of IMMEDIATE kicks, not a sustained wing', () => {
    const r=airBrakeKickStep({vx:530,vy:150,decelFraction:PHYSICS.airBrakeDecel,
      liftBudgetFraction:TUNING.airBrakeLiftBudgetFraction,
      upwardRatio:TUNING.airBrakeKickUpRatio,maxUpPxS:TUNING.airBrakeKickUpCapPxS});
    expect(r.vx).toBeCloseTo(212,10);
    expect(r.spentSpeedPxS).toBeCloseTo(318,10);
    expect(r.vy).toBeCloseTo(-318,10); // already descending before pressing: visible upward launch
    expect(aerodynamicStep({vx:r.vx,vy:r.vy,airBrake:true,stepMs:8})).toEqual({dvx:0,dvy:0});
  });
  test('a near-wall tailwind pays for an actual emergency sail catch, not distant free thrust', () => {
    const args={vx:700,relativeAirX:600,parachute:true,stepMs:8};
    const far=aerodynamicStep({...args,proximity01:0});
    const close=aerodynamicStep({...args,proximity01:.95});
    expect(close.dvx).toBeGreaterThan(far.dvx*5);
    expect(aerodynamicStep({...args,relativeAirX:0,proximity01:1}).dvx).toBe(0);
  });
  test('kick is one-time and has NO sustained force, gravity reduction, or descent damping', () => {
    expect(TUNING).not.toHaveProperty('airBrakeGravityMul');
    expect(TUNING).not.toHaveProperty('airBrakeDescentDamp');
    expect(TUNING).not.toHaveProperty('airBrakeSpanMs');
    expect(TUNING).not.toHaveProperty('airBrakePaidLiftRatio');
    const r=airBrakeKickStep({vx:650,vy:-80,decelFraction:PHYSICS.airBrakeDecel,
      liftBudgetFraction:TUNING.airBrakeLiftBudgetFraction,
      upwardRatio:TUNING.airBrakeKickUpRatio,maxUpPxS:TUNING.airBrakeKickUpCapPxS});
    expect(r.vx).toBeCloseTo(260,10);
    expect(r.vy).toBeCloseTo(-420,10); // capped snap, then NORMAL GRAVITY
    expect(aerodynamicStep({vx:r.vx,vy:r.vy,airBrake:true,stepMs:1000})).toEqual({dvx:0,dvy:0});
  });
  test('one-shot kick independent of framerate and display step size', () => {
    const args={vx:530,vy:150,decelFraction:PHYSICS.airBrakeDecel,
      liftBudgetFraction:TUNING.airBrakeLiftBudgetFraction,
      upwardRatio:TUNING.airBrakeKickUpRatio,maxUpPxS:TUNING.airBrakeKickUpCapPxS};
    const out=airBrakeKickStep(args);
    for(const hz of [30,60,120,144]){
      expect(airBrakeKickStep({...args,stepMs:1000/hz})).toEqual(out);
    }
  });
  test('upgraded AirBrake Lift strengthens the same single kick without free forward momentum', () => {
    const args={vx:600,vy:240,decelFraction:PHYSICS.airBrakeDecel,
      liftBudgetFraction:TUNING.airBrakeLiftBudgetFraction,
      upwardRatio:TUNING.airBrakeKickUpRatio,maxUpPxS:TUNING.airBrakeKickUpCapPxS};
    const normal=airBrakeKickStep(args);
    const upgraded=airBrakeKickStep({...args,liftMul:1.3});
    expect(upgraded.vx).toBe(normal.vx);
    expect(upgraded.vy).toBeLessThan(normal.vy);
    expect(upgraded.vy).toBeGreaterThanOrEqual(-420);
  });
  test('vacuum and nearly stopped riders get no free vertical kick', () => {
    const v={vx:530,vy:350,decelFraction:PHYSICS.airBrakeDecel,
      liftBudgetFraction:TUNING.airBrakeLiftBudgetFraction,
      upwardRatio:TUNING.airBrakeKickUpRatio,maxUpPxS:TUNING.airBrakeKickUpCapPxS};
    expect(airBrakeKickStep({...v,atmosphereDensity:0})).toEqual({vx:530,vy:350,spentSpeedPxS:0});
    const stopped=airBrakeKickStep({...v,vx:20});
    expect(stopped.vy).toBe(350); // too little speed was paid to reset a high-speed fall
    expect(stopped.vx).toBeLessThan(20);
    expect(airBrakeKickStep({...v,atmosphereDensity:.1}).spentSpeedPxS)
      .toBeLessThan(airBrakeKickStep(v).spentSpeedPxS);
    expect(aerodynamicStep({atmosphereDensity:0,airBrake:true,relativeAirX:800}))
      .toEqual({dvx:0,dvy:0});
  });
  test('backward speed pays for the same two kicks without gaining absolute forward speed', () => {
    const r=airBrakeKickStep({vx:-600,vy:250,decelFraction:PHYSICS.airBrakeDecel});
    expect(r.vx).toBeCloseTo(-240,10);
    expect(r.vy).toBeLessThan(-300);
    expect(Math.abs(r.vx)).toBeLessThan(600);
  });
  test('already fast upward motion is not capped or slowed by AirBrake', () => {
    const r=airBrakeKickStep({vx:530,vy:-650,maxUpPxS:420});
    expect(r.vy).toBe(-650);
    expect(r.vx).toBeCloseTo(212,10);
  });
  test('stronger decel preserves exact vertical output from previous 40% braking for different speeds, atmospheres and upgrades', () => {
    expect(PHYSICS.airBrakeDecel).toBe(0.60);
    expect(TUNING.airBrakeLiftBudgetFraction).toBe(0.40);
    const oldFraction=0.40, newFraction=PHYSICS.airBrakeDecel;
    for(const vx of [0, 20, 63, 110, 530.6930808429843, 900, -110, -900]){
      for(const vy of [-700, -150, 0, 100, 350, 900]){
        for(const density of [0, .1, .5, 1]){
          for(const liftMul of [1, 1.15, 1.5]){
            const args={vx,vy,atmosphereDensity:density,liftMul,
              liftBudgetFraction:TUNING.airBrakeLiftBudgetFraction,
              upwardRatio:TUNING.airBrakeKickUpRatio,maxUpPxS:TUNING.airBrakeKickUpCapPxS};
            const before=airBrakeKickStep({...args,decelFraction:oldFraction});
            const after=airBrakeKickStep({...args,decelFraction:newFraction});
            expect(after.vy).toBe(before.vy);
            expect(Math.abs(after.vx)).toBeLessThanOrEqual(Math.abs(before.vx));
            expect(after.spentSpeedPxS).toBeGreaterThanOrEqual(before.spentSpeedPxS);
          }
        }
      }
    }
  });
  test('harder braking still does not create continuous lift when held', () => {
    const p=airBrakeKickStep({vx:600,vy:120,decelFraction:PHYSICS.airBrakeDecel,
      liftBudgetFraction:TUNING.airBrakeLiftBudgetFraction,
      upwardRatio:TUNING.airBrakeKickUpRatio});
    expect(p.vx).toBeCloseTo(240);
    expect(p.vy).toBeCloseTo(-360);
    expect(aerodynamicStep({vx:p.vx,vy:p.vy,airBrake:true,stepMs:100})).toEqual({dvx:0,dvy:0});
  });
  test('vacuum kills all aerodynamic force even during contact-danger', () => {
    expect(aerodynamicStep({vx:900,relativeAirX:1200,atmosphereDensity:0,parachute:true,airBrake:true})).toEqual({dvx:0,dvy:0});
  });
});


describe('Space Mountain keeps genuine vacuum but has a small powered divebomb', () => {
  test('only a held airborne divebomb with zero atmosphere produces forward purchase', () => {
    expect(vacuumDivebombStep({airborne:true,divebomb:true,atmosphereDensity:0,stepMs:100}))
      .toEqual({dvx:3.5,dvy:14}); // capped 50ms per physics call
