      .toEqual({dvx:0,dvy:0});
    expect(vacuumDivebombStep({airborne:true,divebomb:false,atmosphereDensity:0}))
      .toEqual({dvx:0,dvy:0});
    expect(vacuumDivebombStep({airborne:false,divebomb:true,atmosphereDensity:0}))
      .toEqual({dvx:0,dvy:0});
  });
