      {meta:{...valid().meta,biomeEntryTick:null}},
      {baselineBiomeEntryTick:null},
      {baselineBiomeEntryFromBridge:false},
    ]) {
      expect(witnessedBiomeTransition({...valid(),...patch})).toBe(false);
