  test('corkscrew owns the open trick key in both orientations', () => {
    expect(layoutButton('tricksRight','ArrowLeft')).toBe('corkscrew');
    expect(layoutButton('tricksLeft','KeyA')).toBe('corkscrew');
  });
  test('right-side tricks, left-side practical controls in a live run', () => {
    const g=game(), router=new InputRouter(g), actions=[];
    g.events.on(EVT.INPUT_ACTION, x=>actions.push(x));
    router.applySettings({...defaultSettings(),controlLayout:'tricksRight'});
    g.events.emit(EVT.RUN_START);
    press('KeyW');press('KeyA');press('KeyS');press('KeyD');
    press('ArrowLeft');press('ArrowRight');press('ArrowUp');
    const p=router.poll();
    expect(p).toMatchObject({
      parachute:true,airBrake:true,divebomb:true,tuck:true,corkscrew:true,
      tilt:1,heli:1,push:false,
    });
    expect(actions.filter(x=>x.pressed).map(x=>x.action)).toEqual(expect.arrayContaining(['up','left','down','right']));
    press('KeyS','keyup');press('ArrowLeft','keyup');
    expect(router.poll()).toMatchObject({divebomb:false,corkscrew:false});
    router.destroy();
  });
  test('switching layouts releases stale held buttons and leaves logical menu directions intact', () => {
    const g=game(), router=new InputRouter(g), actions=[];
    g.events.on(EVT.INPUT_ACTION, x=>actions.push(x));
    router.applySettings({...defaultSettings(),controlLayout:'tricksRight'});
    g.events.emit(EVT.RUN_START);
    press('KeyW');
    expect(router.poll().parachute).toBe(true);
    router.applySettings({...defaultSettings(),controlLayout:'tricksLeft'});
    expect(router.poll().parachute).toBe(false);
    press('KeyW');
    expect(router.poll().tilt).toBe(1);
    router.destroy();
  });
  test('touch overlay replaces dead controls in Trick Deck and restores Classic buttons', () => {
    const pad=new VirtualPad();
    pad.mountTouchOverlay(document.body, { touchOverlay:'on', controlLayout:'tricksRight' });
    pad.setOverlayContext(true);
    const all = () => [...pad.overlay.root.querySelectorAll('[data-btn]')].map(x=>x.dataset.btn);
    expect(all()).toEqual(expect.arrayContaining(['corkscrew','divebomb','parachute','airBrake']));
    expect(all()).not.toContain('push');
    pad.mountTouchOverlay(document.body, { touchOverlay:'on', controlLayout:'classic' });
    expect(all()).toEqual(expect.arrayContaining(['push','heliLeft']));
    expect(all()).not.toContain('corkscrew');
    pad.destroy();
  });
  test('classic preserves W push, S brake, arrow heli and parachute', () => {
    const g=game(), router=new InputRouter(g);
    router.applySettings({...defaultSettings(),controlLayout:'classic'});
    g.events.emit(EVT.RUN_START);
    press('KeyW');press('KeyS');press('ArrowLeft');press('ArrowDown');
    const p=router.poll();
    expect(p).toMatchObject({push:true,brake:true,heli:-1,parachute:true,corkscrew:false});
    router.destroy();
  });
});/**
 * W6 — the conveyor belt must CONVEY, not merely boost a manual push.
 *
 * SPEC §5 W6 names the mechanic: "Conveyor segments that push with or against you". The shipped
 * `conveyor-belt.json` carries `direction: 1` and `physics.pushForceMul: 2.0`.
 *
 * What the implementation does: `pushForceMul` multiplies the W-key push kick in `Sled.js`, so a
 * conveyor only has an effect while the player holds push on flat ground. A conveyor that moves a
 * player who is doing nothing is the mechanic; a conveyor that doubles a manual push is not. And
 * `direction` is read by nothing at all, so "with or against you" does not exist.
 *
 * This file is written against the SPEC's wording rather than the implementation's, which is the
 * lesson W3's palette defect taught: a test asserting the constant changed passes while the
 * mechanic is absent.
 */
import fs from 'fs';
import { PhysicsTuner, conveyorStep } from '../../src/systems/PhysicsTuner.js';

const readJson = (p) => JSON.parse(fs.readFileSync(p, 'utf8'));
const CONVEYOR = readJson('src/data/terrainMods/conveyor-belt.json');

function tuner() {
  return new PhysicsTuner();
}

describe('Steampunk conveyor belts move the sled without a manual push', () => {
  test('a conveyor zone reports a belt force with a direction', () => {
    const phys = tuner().getEffective({ zones: [CONVEYOR] });
    // The belt must express a horizontal drive the sled can apply on its own. A multiplier on the
    // player's push key (pushForceMul) is a different thing and is still allowed to exist.
    expect(phys.beltDrivePxS2).toBeGreaterThan(0);
    expect(phys.beltDirection).toBe(1);
  });

  test('the belt drive is bounded so a conveyor cannot launch like a geyser', () => {
    const phys = tuner().getEffective({ zones: [CONVEYOR] });
    expect(phys.beltDrivePxS2).toBeLessThanOrEqual(4000);
  });

  test('no belt zone means no belt drive', () => {
    const phys = tuner().getEffective({});
    expect(phys.beltDrivePxS2 || 0).toBe(0);
  });

  test('direction -1 is a belt against you, and it is not silently read as forward', () => {
    const reverse = { ...CONVEYOR, direction: -1 };
    const fwd = tuner().getEffective({ zones: [CONVEYOR] });
    const back = tuner().getEffective({ zones: [reverse] });
    expect(back.beltDirection).toBe(-1);
    expect(back.beltDrivePxS2).toBeGreaterThan(0);
    // Same magnitude, opposite sign of intent: the drive stays positive and the sign lives in
    // beltDirection, so a consumer cannot accidentally add a negative magnitude.
    expect(back.beltDrivePxS2).toBeCloseTo(fwd.beltDrivePxS2, 5);
  });

  test('two overlapping belts compound in magnitude', () => {
    const one = tuner().getEffective({ zones: [CONVEYOR] });
    const two = tuner().getEffective({ zones: [CONVEYOR, CONVEYOR] });
    expect(two.beltDrivePxS2).toBeGreaterThan(one.beltDrivePxS2);
  });
});

describe('the belt actually moves the sled, on the ground, with no input', () => {
  const phys = () => new PhysicsTuner().getEffective({ zones: [CONVEYOR] });

  test('a grounded sled gains forward velocity from the belt alone', () => {
    const p = phys();
    const step = conveyorStep({
      grounded: true, drivePxS2: p.beltDrivePxS2, direction: p.beltDirection, slopeDeg: 0, stepMs: 16,
    });
    expect(step.dvx).toBeGreaterThan(0);
    expect(step.dvy).toBeCloseTo(0, 6);
  });

  test('a reverse belt pushes the sled backwards', () => {
    const step = conveyorStep({ grounded: true, drivePxS2: 900, direction: -1, slopeDeg: 0, stepMs: 16 });
    expect(step.dvx).toBeLessThan(0);
  });

  test('an airborne sled is not carried by the belt', () => {
    const step = conveyorStep({ grounded: false, drivePxS2: 900, direction: 1, slopeDeg: 0, stepMs: 16 });
    expect(step.dvx).toBe(0);
    expect(step.dvy).toBe(0);
  });

  test('the belt follows the slope instead of driving into it', () => {
    const flat = conveyorStep({ grounded: true, drivePxS2: 900, direction: 1, slopeDeg: 0, stepMs: 16 });
    const downhill = conveyorStep({ grounded: true, drivePxS2: 900, direction: 1, slopeDeg: 20, stepMs: 16 });
    // On a 20 deg downhill the drive keeps its magnitude but now has a downward component.
    expect(Math.hypot(downhill.dvx, downhill.dvy)).toBeCloseTo(Math.hypot(flat.dvx, flat.dvy), 6);
    expect(downhill.dvy).toBeGreaterThan(0);
  });

  test('no belt under the sled means no movement', () => {
    const noBelt = new PhysicsTuner().getEffective({});
    const step = conveyorStep({
      grounded: true, drivePxS2: noBelt.beltDrivePxS2 || 0, direction: noBelt.beltDirection, slopeDeg: 0, stepMs: 16,
    });
    expect(step.dvx).toBe(0);
  });
});/**
 * Audit F4 / F4b / SHOP-2 / SHOP-5: every cosmetic the game grants or sells is usable.
 *
 *  - F4b: ONE catalogue. Cosmetics.COSMETIC_ITEMS is the source; ProfileStore.SHOP_ITEMS is the same array,
 *    the resolver's lookup is derived from it, and data/cosmetics/cosmetics.json is a mirror pinned here
 *    field by field, so the three can never drift again (the JSON's glow `kind` already had).
 */
import fs from 'fs';
import { jest } from '@jest/globals';

// Sled.js imports Phaser for Matter; its draw path needs only Body.getVelocity.
jest.unstable_mockModule('phaser', () => ({
  default: { Physics: { Matter: { Matter: { Bodies: {}, Body: { getVelocity: () => ({ x: 0, y: 0 }) } } } } },
}));

const { COSMETIC_ITEMS, COSMETIC_HUES, cosmeticFor, resolveCosmetics, themedUiPalette, UI_THEME_KEYS, equippedTitle } = await import('../../src/systems/Cosmetics.js');
const { SHOP_ITEMS, sanitizeProfile, equip, unequip, isOwned, purchase, creditRun } = await import('../../src/systems/ProfileStore.js');
const { shopAllRows, titlesLayout, titlesMenuItems } = await import('../../src/ui/ShopLayout.js');
const { profileLayout, titleBadgeLayout, PROFILE_PANEL } = await import('../../src/ui/ProfileLayout.js');
const { ACHIEVEMENTS } = await import('../../src/systems/Achievements.js');
const { TrailParticles } = await import('../../src/entities/TrailParticles.js');
const { Sled } = await import('../../src/entities/Sled.js');

const read = (p) => JSON.parse(fs.readFileSync(p, 'utf8'));
const COSMETICS_JSON = read('src/data/cosmetics/cosmetics.json');
const LEVELS = read('src/data/progression/levels.json');
const PALETTES = read('src/data/palettes.json');
const MAX_XP = LEVELS.levels[LEVELS.levels.length - 1].xpMin + 1;
const v1 = (o = {}) => sanitizeProfile({ v: 1, ...o }, LEVELS);
const HEX = PALETTES.default;
const INTS = Object.fromEntries(Object.entries(HEX).map(([k, v]) => [k, parseInt(v.slice(1), 16)]));
const int = (h) => parseInt(h.slice(1), 16);
const DRAWN_SLOTS = ['trail', 'glow', 'rider', 'theme'];

describe('F4b: one cosmetic catalogue', () => {
  test('ProfileStore.SHOP_ITEMS is the Cosmetics catalogue, not a copy', () => {
    expect(SHOP_ITEMS).toBe(COSMETIC_ITEMS);
  });

  test('cosmetics.json mirrors the catalogue, every field of every item', () => {
    expect(COSMETICS_JSON.items).toEqual(COSMETIC_ITEMS.map((i) => ({ ...i })));
  });

  test('audit F4 (S3): cosmetics.json agrees with SHOP_ITEMS on id, kind, price and unlockLevel', () => {
    const fromJson = COSMETICS_JSON.items.map((i) => ({ id: i.id, kind: i.kind, price: i.price, unlockLevel: i.unlockLevel }));
    const fromCode = SHOP_ITEMS.map((i) => ({ id: i.id, kind: i.kind, price: i.price, unlockLevel: i.unlockLevel }));
    expect(fromJson).toEqual(fromCode);
  });

  test('the resolver lookup is derived from the catalogue: every item resolves to itself', () => {
    for (const it of COSMETIC_ITEMS) {
      expect(cosmeticFor(it.id)).toMatchObject({ id: it.id, kind: it.kind, slot: it.slot, value: it.value });
    }
  });

  test('a glow item is kind "glow" everywhere (the JSON had drifted to "sledGlow")', () => {
    const glows = COSMETIC_ITEMS.filter((i) => i.slot === 'glow');
    expect(glows.length).toBeGreaterThan(0);
    for (const g of glows) expect(g.kind).toBe('glow');
  });

  test('ids are unique, and a value is unique within its slot (equip() stores the value)', () => {
    const ids = COSMETIC_ITEMS.map((i) => i.id);
    expect(new Set(ids).size).toBe(ids.length);
    const seen = new Set();
    for (const i of COSMETIC_ITEMS) {
      const k = `${i.slot}:${i.value}`;
      expect({ k, dup: seen.has(k) }).toEqual({ k, dup: false });
      seen.add(k);
    }
  });

  test('the catalogue is frozen, so no caller can edit the shared source at runtime', () => {
    expect(Object.isFrozen(COSMETIC_ITEMS)).toBe(true);
    for (const i of COSMETIC_ITEMS) expect(Object.isFrozen(i)).toBe(true);
  });
});

describe('F4: the eleven level-reward cosmetics are real catalogue items', () => {
  const rewards = LEVELS.levels.filter((l) => l.cosmetic).map((l) => ({ id: l.cosmetic, level: l.level }));
  const rewardIds = rewards.map((r) => r.id);

  test('audit F4: levels.json grants eleven cosmetics', () => {
    expect(rewardIds).toEqual(['trail-cyan', 'glow-lime', 'rider-amber', 'theme-magenta', 'trail-magenta',
      'glow-cyan', 'rider-lime', 'theme-amber', 'trail-amber', 'glow-magenta', 'theme-legend']);
  });

  test('each is in the catalogue as a level reward: price 0, unlockLevel = the level that grants it', () => {
    for (const r of rewards) {
      const it = SHOP_ITEMS.find((i) => i.id === r.id);
      expect({ id: r.id, found: Boolean(it) }).toEqual({ id: r.id, found: true });
      expect({ id: r.id, price: it.price, unlockLevel: it.unlockLevel, slot: it.slot })
        .toEqual({ id: r.id, price: 0, unlockLevel: r.level, slot: r.id.split('-')[0] });
    }
  });

  test('audit F4: every level-reward cosmetic can be equipped by a level-30 profile', () => {
    const p = v1({ xp: MAX_XP, unlocked: { cosmetics: rewardIds } });
    expect(rewardIds.filter((id) => equip(p, id) === p)).toEqual([]);
  });

  test('audit F4: an equipped level-reward trail is drawn, not reported missing', () => {
    const hex = { cyan: '#00f0ff', lime: '#a0ff00', amber: '#ffb020', magenta: '#ff2bd6', danger: '#ff0000' };
    const look = resolveCosmetics({ equipped: { trail: 'trail-cyan' } }, {}, hex);
    expect(look.missing).toEqual([]);
  });

  test('owned exactly from its level: not at level-1, yes at level, and never bought', () => {
    for (const r of rewards) {
      const below = v1({ xp: LEVELS.levels.find((l) => l.level === r.level - 1).xpMin, bank: 99999 });
      const at = v1({ xp: LEVELS.levels.find((l) => l.level === r.level).xpMin });
      expect({ id: r.id, below: isOwned(below, r.id), at: isOwned(at, r.id) }).toEqual({ id: r.id, below: false, at: true });
      expect(purchase(below, r.id)).toBe(below); // a level reward is never for sale
      const row = shopAllRows({ profile: below }).find((x) => x.id === r.id);
      expect({ id: r.id, state: row.state, disabled: row.disabled }).toEqual({ id: r.id, state: `LVL ${r.level}`, disabled: true });
    }
  });

  test('a price-0 item is never bought, even when its level is reached but it is somehow not owned', () => {
    // purchase() used to check only level and bank, so any un-owned price-0 item was "bought" for free.
    const p = v1({ xp: MAX_XP, bank: 5 });
    for (const it of SHOP_ITEMS.filter((i) => i.price === 0)) {
      const after = purchase(p, it.id);
      expect({ id: it.id, bank: after.bank, owned: (after.unlocked.cosmetics || []).includes(it.id) })
        .toEqual({ id: it.id, bank: 5, owned: false });
    }
  });
});

describe('F4: every drawable catalogue item reaches the screen', () => {
  const drawable = SHOP_ITEMS.filter((i) => DRAWN_SLOTS.includes(i.slot));
  const rich = () => v1({ xp: MAX_XP, bank: 99999 });
  // Micro glow-up: a biome grant (the Neon Sled Drone) is never sold, so it is earned the way a player earns
  // it: a credited run that completed its biome. Every other item is still owned or bought exactly as before.
  const earn = (p, it) => creditRun(p, { id: `earn-${it.id}`, distanceM: 1 }, LEVELS,
    { biomeVisits: { encountered: [it.biome], completed: [it.biome] } }).profile;
  const own = (p, id) => {
    if (isOwned(p, id)) return p;
    const it = SHOP_ITEMS.find((i) => i.id === id);
    return it && it.grant === 'biome' ? earn(p, it) : purchase(p, id);
  };

  test('every drawable item has a hue of the right shape', () => {
    for (const it of drawable) {
      const hue = COSMETIC_HUES[it.kind] && COSMETIC_HUES[it.kind][it.value];
      expect({ id: it.id, hue: Boolean(hue) }).toEqual({ id: it.id, hue: true });
      if (it.slot === 'trail') expect(hue.stops).toHaveLength(4);
      else expect(hue.color).toMatch(/^#[0-9a-f]{6}$/i);
    }
  });

  test('buy or own, equip, resolve: the slot changes and nothing is missing', () => {
    const base = resolveCosmetics(v1({}), INTS, HEX);
    for (const it of drawable) {
      const p = equip(own(rich(), it.id), it.id);
      expect({ id: it.id, eq: p.equipped[it.slot] }).toEqual({ id: it.id, eq: it.value });
      const look = resolveCosmetics(p, INTS, HEX);
      expect({ id: it.id, missing: look.missing }).toEqual({ id: it.id, missing: [] });
      if (it.slot === 'theme') expect(look.theme).toBe(it.value);
      else expect({ id: it.id, changed: JSON.stringify(look[it.slot]) !== JSON.stringify(base[it.slot]) }).toEqual({ id: it.id, changed: true });
    }
  });

  test('values shared across slots resolve to their own slot (cyan trail vs cyan glow)', () => {
    const p = { equipped: { trail: 'cyan', glow: 'cyan', rider: 'amber', theme: 'magenta' } };
    const look = resolveCosmetics(p, INTS, HEX);
    expect(look.missing).toEqual([]);
    expect(look.trail).toEqual([...COSMETIC_HUES.trail.cyan.stops]);
    expect(look.glow).toBe(COSMETIC_HUES.glow.cyan.color);
  });

  test('Cyan Glow is visibly not the default glow (palette cyan) nor the paid Cold Glow', () => {
    const c = COSMETIC_HUES.glow.cyan.color.toLowerCase();
    expect(c).not.toBe(HEX.cyan.toLowerCase());
    expect(c).not.toBe(COSMETIC_HUES.glow.cold.color.toLowerCase());
  });

  test('colourblind mode refuses every level-reward hue too', () => {
    const p = { equipped: { trail: 'cyan', glow: 'lime', rider: 'amber', theme: 'legend' } };
    const look = resolveCosmetics(p, INTS, HEX, { colorblind: true });
    expect(look).toMatchObject({ overridden: true, rider: HEX.magenta, glow: HEX.cyan, theme: 'default' });
    expect(look.trail).toEqual([HEX.cyan, HEX.lime, HEX.amber, HEX.magenta]);
  });
});

/** A Graphics stand-in that records every colour it is asked to stroke or fill with. */
function recordingGfx() {
  const colors = [];
  const g = {
    colors,
    clear() { return g; },
    lineStyle(w, c) { colors.push(c); return g; },
    fillStyle(c) { colors.push(c); return g; },
  };
  return new Proxy(g, { get: (t, k) => (k in t ? t[k] : () => t) });
}

describe('F4: the equipped trail is what TrailParticles draws', () => {
  const fakeScene = () => ({
    textures: { exists: () => true },
    add: {
      graphics: () => { const g = recordingGfx(); g.setDepth = () => g; return g; },
      particles: () => ({ setDepth() { return this; }, setParticleTint() {}, emitParticleAt() {}, destroy() {} }),
    },
  });

  test('the level-15 Magenta Trail colours the ribbon from its own stops', () => {
    const look = resolveCosmetics({ equipped: { trail: 'magenta' } }, INTS, HEX);
    const tp = new TrailParticles(fakeScene(), INTS, look.trail);
    expect(tp.colorForSpeed(0)).toBe(int(COSMETIC_HUES.trail.magenta.stops[0]));
    tp.update(0, 0, 0);
    tp.update(10, 0, 0);
    expect(tp.gfx.colors).toContain(int(COSMETIC_HUES.trail.magenta.stops[0]));
    expect(tp.gfx.colors).not.toContain(INTS.cyan);
  });
});

describe('F4: the equipped glow and rider are what Sled draws', () => {
  const drawSled = (look) => {
    const s = Object.create(Sled.prototype);
    Object.assign(s, {
      gfx: recordingGfx(), palette: INTS, look,
      body: { angle: 0, position: { x: 0, y: 0 } }, off: { x: 0, y: 0 },
      heliPhase: 0, heliVel: 0, squash: 0, pose: { chute: 0, phi: 0, tuck: 0, brake: 0 },
      invulnerableMs: 0, _time: 0, scrambled: false, shield: false, msSinceContact: 0,
    });
    s._draw();
    return s.gfx.colors;
  };

  test('default look: the sled is palette cyan and the rider palette magenta', () => {
    const c = drawSled(null);
    expect(c).toContain(INTS.cyan);
    expect(c).toContain(INTS.magenta);
  });

  // The level riders are palette amber and lime, which the sled already draws (arms, helmet, runner), so
  // "the colour appears" proves nothing. These count uses instead, and check the default rider (magenta,
  // drawn nowhere else on an unscrambled sled without a chute) is gone.
  const count = (c, v) => c.filter((x) => x === v).length;

  test('the level-29 Magenta Glow and level-9 Amber Rider are drawn', () => {
    const base = drawSled(null);
    const look = resolveCosmetics({ equipped: { glow: 'magenta', rider: 'amber' } }, INTS, HEX);
    const c = drawSled(look);
    expect(c).toContain(int(COSMETIC_HUES.glow.magenta.color));
    const amber = int(COSMETIC_HUES.rider.amber.color);
    expect(count(c, amber)).toBeGreaterThan(count(base, amber));
  });

  test('the level-20 Lime Rider replaces the magenta rider', () => {
    const base = drawSled(null);
    const look = resolveCosmetics({ equipped: { rider: 'lime' } }, INTS, HEX);
    const c = drawSled(look);
    const lime = int(COSMETIC_HUES.rider.lime.color);
    expect(count(c, lime)).toBeGreaterThan(count(base, lime));
    expect(c).not.toContain(INTS.magenta);
  });

  test('the level-18 Cyan Glow is drawn, and the default glow colour is used less (visor only)', () => {
    const base = drawSled(null);
    const look = resolveCosmetics({ equipped: { glow: 'cyan' } }, INTS, HEX);
    const c = drawSled(look);
    expect(c).toContain(int(COSMETIC_HUES.glow.cyan.color));
    expect(count(c, INTS.cyan)).toBeLessThan(count(base, INTS.cyan));
  });
});

// ------------------------------------------------------------------ SHOP-5: themes are UI themes

/** WCAG relative luminance and contrast ratio. */
const lum = (h) => {
  const c = [1, 3, 5].map((i) => parseInt(h.slice(i, i + 2), 16) / 255).map((v) => (v <= 0.03928 ? v / 12.92 : ((v + 0.055) / 1.055) ** 2.4));
  return 0.2126 * c[0] + 0.7152 * c[1] + 0.0722 * c[2];
};
const contrast = (a, b) => { const [x, y] = [lum(a), lum(b)].sort((m, n) => n - m); return (x + 0.05) / (y + 0.05); };
const THEMES = SHOP_ITEMS.filter((i) => i.slot === 'theme');

describe('SHOP-5: a theme recolours the UI palette, never danger, and never under colourblind', () => {
  test('the themeable keys are the UI accents and panel tone: never danger, lime or amber, never the world bg', () => {
    expect([...UI_THEME_KEYS].sort()).toEqual(['bgAlt', 'cyan', 'magenta', 'text']);
  });

  test('no theme defines danger (or any key outside the themeable set)', () => {
    for (const t of THEMES) {
      const ui = COSMETIC_HUES.theme[t.value].ui;
      expect({ id: t.id, ui: Boolean(ui) }).toEqual({ id: t.id, ui: true });
      expect({ id: t.id, extra: Object.keys(ui).filter((k) => !UI_THEME_KEYS.includes(k)) }).toEqual({ id: t.id, extra: [] });
    }
  });

  test('default equipment leaves the palette untouched', () => {
    expect(themedUiPalette(HEX, v1({}))).toEqual(HEX);
    expect(themedUiPalette(HEX, null)).toEqual(HEX);
    expect(themedUiPalette(HEX, { equipped: { theme: 'no-such-theme' } })).toEqual(HEX);
  });

  test('every theme (bought or level reward) changes the primary accent and keeps danger, lime, amber and bg', () => {
    for (const t of THEMES) {
      const out = themedUiPalette(HEX, { equipped: { theme: t.value } });
      expect({ id: t.id, cyan: out.cyan !== HEX.cyan }).toEqual({ id: t.id, cyan: true });
      for (const k of ['danger', 'lime', 'amber', 'bg']) expect({ id: t.id, k, v: out[k] }).toEqual({ id: t.id, k, v: HEX[k] });
    }
  });

  test('an equipped ID works as well as an equipped value', () => {
    expect(themedUiPalette(HEX, { equipped: { theme: 'theme-sunset' } }).cyan)
      .toBe(themedUiPalette(HEX, { equipped: { theme: 'sunset' } }).cyan);
  });

  test('colourblind mode refuses every theme', () => {
    const cb = PALETTES.colorblind;
    for (const t of THEMES) expect(themedUiPalette(cb, { equipped: { theme: t.value } }, { colorblind: true })).toEqual(cb);
  });

  test('every theme stays readable: text and accents at 4.5:1 or better on bg and bgAlt', () => {
    for (const t of THEMES) {
      const p = themedUiPalette(HEX, { equipped: { theme: t.value } });
      for (const fg of ['text', 'cyan', 'magenta', 'lime', 'amber']) {
        for (const bg of ['bg', 'bgAlt']) {
          const r = contrast(p[fg], p[bg]);
          expect({ id: t.id, fg, bg, ok: r >= 4.5, r: Math.round(r * 10) / 10 }).toMatchObject({ id: t.id, fg, bg, ok: true });
        }
      }
    }
  });

  test('no theme lowers danger contrast below the default palette (panel tone stays as dark or darker)', () => {
    const floor = Math.min(contrast(HEX.danger, HEX.bg), contrast(HEX.danger, HEX.bgAlt));
    for (const t of THEMES) {
      const p = themedUiPalette(HEX, { equipped: { theme: t.value } });
      for (const bg of ['bg', 'bgAlt']) {
        expect({ id: t.id, bg, ok: contrast(p.danger, p[bg]) >= floor }).toEqual({ id: t.id, bg, ok: true });
      }
    }
  });

  test('the level-30 Legend theme is distinct from every other theme', () => {
    const legend = themedUiPalette(HEX, { equipped: { theme: 'legend' } });
    for (const t of THEMES.filter((x) => x.value !== 'legend')) {
      const other = themedUiPalette(HEX, { equipped: { theme: t.value } });
      expect({ id: t.id, same: other.cyan === legend.cyan && other.magenta === legend.magenta }).toEqual({ id: t.id, same: false });
    }
  });
});

// ------------------------------------------------------------------ SHOP-2: titles

describe('SHOP-2: titles can be owned, bought, equipped and are shown', () => {
  const titleOf = (lvl) => LEVELS.levels.find((l) => l.level === lvl).title.toUpperCase();

  test('every achievement reward (cosmetic or title) is a catalogue item', () => {
    for (const a of ACHIEVEMENTS.filter((x) => x.reward)) {
      if (a.reward.cosmetic) expect({ a: a.id, ok: SHOP_ITEMS.some((i) => i.id === a.reward.cosmetic) }).toEqual({ a: a.id, ok: true });
      if (a.reward.title) {
        expect({ a: a.id, ok: SHOP_ITEMS.some((i) => i.slot === 'title' && i.value === a.reward.title && i.grant === 'achievement') })
          .toEqual({ a: a.id, ok: true });
      }
    }
  });

  test('an achievement title is owned only once the achievement granted it, and is never for sale', () => {
    for (const id of ['title-cartographer', 'title-omniscient']) {
      const it = SHOP_ITEMS.find((i) => i.id === id);
      const lvl30 = v1({ xp: MAX_XP, bank: 99999 });
      expect({ id, owned: isOwned(lvl30, id) }).toEqual({ id, owned: false });
      expect(purchase(lvl30, id)).toBe(lvl30);
      expect(equip(lvl30, id)).toBe(lvl30);
      const granted = v1({ unlocked: { titles: [it.value] } });
      expect({ id, owned: isOwned(granted, id) }).toEqual({ id, owned: true });
      expect(equip(granted, id).equipped.title).toBe(it.value);
    }
  });

  test('audit SHOP-2 (adapted): Static Rider is offered for 220 on the TITLES screen and can be bought and equipped', () => {
    // The audit test looked for STATIC RIDER on the Profile panel; titles now have their own screen opened
    // from Profile, so the same question is asked of that screen's layout.
    const p = v1({ bank: 1000 });
    const row = titlesLayout({ profile: p, levels: LEVELS }).rows.find((r) => r.id === 'title-static');
    expect(row).toMatchObject({ label: 'STATIC RIDER', state: '220', disabled: false });
    const after = equip(purchase(p, 'title-static'), 'title-static');
    expect(after.bank).toBe(780);
    expect(after.equipped.title).toBe('STATIC RIDER');
  });

  test('the TITLES screen lists the level title as DEFAULT and spells out every state', () => {
    const p = v1({ xp: LEVELS.levels.find((l) => l.level === 3).xpMin, bank: 0, unlocked: { titles: ['CARTOGRAPHER'] } });
    const L = titlesLayout({ profile: p, levels: LEVELS });
    const by = Object.fromEntries(L.rows.filter((r) => r.id).map((r) => [r.id, r]));
    expect(by.default).toMatchObject({ label: `LEVEL: ${titleOf(3)}`, state: 'EQUIPPED', disabled: false });
    expect(by['title-rookie']).toMatchObject({ state: 'EQUIP', disabled: false });
    expect(by['title-static']).toMatchObject({ state: '220', disabled: true }); // broke
    expect(by['title-cartographer']).toMatchObject({ state: 'EQUIP', disabled: false });
    expect(by['title-omniscient']).toMatchObject({ state: 'ACHIEVEMENT', disabled: true });
    const eq = titlesLayout({ profile: equip(p, 'title-rookie'), levels: LEVELS });
    const by2 = Object.fromEntries(eq.rows.filter((r) => r.id).map((r) => [r.id, r]));
    expect(by2['title-rookie']).toMatchObject({ state: 'EQUIPPED', disabled: false });
    expect(by2.default).toMatchObject({ state: 'EQUIP', disabled: false });
    expect(titlesMenuItems(eq).length).toBe(eq.rows.length);
  });

  test('the TITLES screen fits: no overlaps, inside its panel, clear of BACK, on screen', () => {
    const p = v1({ xp: MAX_XP, bank: 99999, unlocked: { titles: ['CARTOGRAPHER', 'OMNISCIENT'] } });
    const L = titlesLayout({ profile: p, levels: LEVELS });
    const ov = (a, b) => a.x < b.x + b.w && b.x < a.x + a.w && a.y < b.y + b.h && b.y < a.y + a.h;
    const back = { x: L.w - 76, y: L.h - 22, w: 68, h: 16 };
    expect(L.h).toBeLessThanOrEqual(270 - 22);
    for (let i = 0; i < L.texts.length; i++) {
      const t = L.texts[i];
      expect({ k: t.key, ok: t.x >= 0 && t.y >= 0 && t.x + t.w <= L.w && t.y + t.h <= L.h && !ov(t, back) }).toEqual({ k: t.key, ok: true });
      for (let j = i + 1; j < L.texts.length; j++) expect({ pair: `${t.key}/${L.texts[j].key}`, hit: ov(t, L.texts[j]) }).toEqual({ pair: `${t.key}/${L.texts[j].key}`, hit: false });
    }
  });

  test('equippedTitle: the equipped title, or null for DEFAULT or an unknown value', () => {
    expect(equippedTitle({ equipped: { title: 'STATIC RIDER' } })).toBe('STATIC RIDER');
    expect(equippedTitle({ equipped: { title: 'title-rookie' } })).toBe('ROOKIE');
    expect(equippedTitle({ equipped: { title: 'default' } })).toBeNull();
    expect(equippedTitle({ equipped: { title: 'NOT A TITLE' } })).toBeNull();
    expect(equippedTitle(null)).toBeNull();
  });

  test('the Title-screen badge shows the equipped title instead of the level title; DEFAULT shows the level title', () => {
    const p = v1({ xp: LEVELS.levels.find((l) => l.level === 3).xpMin, bank: 1000 });
    expect(titleBadgeLayout({ profile: p, levels: LEVELS }).items.map((i) => i.text)).toEqual(['SYNC LEVEL 3', titleOf(3)]);
    const eq = equip(purchase(p, 'title-static'), 'title-static');
    expect(titleBadgeLayout({ profile: eq, levels: LEVELS }).items.map((i) => i.text)).toEqual(['SYNC LEVEL 3', 'STATIC RIDER']);
    expect(titleBadgeLayout({ profile: unequip(eq, 'title'), levels: LEVELS }).items.map((i) => i.text)).toEqual(['SYNC LEVEL 3', titleOf(3)]);
  });

  test('the Profile view shows the equipped title where the level title was', () => {
    const p = v1({ xp: LEVELS.levels.find((l) => l.level === 3).xpMin, unlocked: { titles: ['OMNISCIENT'] } });
    const text = (q) => profileLayout({ profile: q, levels: LEVELS, playableBiomeIds: [] }).items.find((i) => i.key === 'title').text;
    expect(text(p)).toBe(titleOf(3));
    expect(text(equip(p, 'title-omniscient'))).toBe('OMNISCIENT');
  });

  test('the Profile layout has a TITLES button in the bottom strip, clear of ACHIEVEMENTS, SHARD SHOP and BACK', () => {
    const L = profileLayout({ profile: v1({}), levels: LEVELS, playableBiomeIds: [] });
    const back = { x: PROFILE_PANEL.w - 76, y: PROFILE_PANEL.h - 22, w: 68, h: 16 };
    const ov = (a, b) => a.x < b.x + b.w && b.x < a.x + a.w && a.y < b.y + b.h && b.y < a.y + a.h;
    expect(L.titlesButton).toBeTruthy();
    for (const b of [L.achButton, L.shopButton, back]) expect(ov(L.titlesButton, b)).toBe(false);
    expect(L.titlesButton.x + L.titlesButton.w).toBeLessThanOrEqual(PROFILE_PANEL.w);
    expect(L.titlesButton.x).toBeGreaterThan(L.shopButton.x); // left to right: ACHIEVEMENTS, SHOP, TITLES, BACK
  });
});/**
 * W4 cosmetics — the equipped item must actually reach the sled, rider, trail and UI theme.
 *
 * Spec W4: "The sled and rider colours at src/entities/Sled.js (currently fixed palette keys) read the
 * equipped cosmetic; colorblind mode keeps overriding anything that would reduce hazard contrast."
 *
 * That last clause is the one that matters and the one a naive implementation gets wrong: a cosmetic that
 * recolours the rider is fine, a cosmetic that recolours a hazard is a gameplay bug wearing a hat. These
 * tests pin the boundary rather than the colours, so a new cosmetic hue cannot quietly move `danger`.
 */
import {
  COSMETIC_HUES, resolveCosmetics, cosmeticFor,
} from '../../src/systems/Cosmetics.js';
import { equip, purchase } from '../../src/systems/ProfileStore.js';
import { defaultProfile } from '../../src/systems/Progression.js';

const DEFAULT_PROFILE = defaultProfile();

const HEX = /^#[0-9a-fA-F]{6}$/;

/** A palette shaped like getPalette()'s output (ints), plus the hex form the resolver reads. */
const PALETTE = {
  bg: 0x0a0a12, bgAlt: 0x14141f, cyan: 0x00f0ff, magenta: 0xff2fd0,
  lime: 0x9dff3c, amber: 0xffb020, text: 0xe8f4ff, danger: 0xff3355,
};
const PALETTE_HEX = {
  bg: '#0a0a12', bgAlt: '#14141f', cyan: '#00f0ff', magenta: '#ff2fd0',
  lime: '#9dff3c', amber: '#ffb020', text: '#e8f4ff', danger: '#ff3355',
};

const profileWith = (equipped) => ({
  equipped: { trail: 'default', glow: 'default', rider: 'default', theme: 'default', title: 'default', ...equipped },
});

describe('cosmetic catalogue', () => {
  test('every hue the catalogue names has a definition', () => {
    // A cosmetic JSON that names a hue with no entry here would equip to nothing at all, which looks
    // exactly like the feature being unimplemented.
    const kinds = ['trail', 'sledGlow', 'rider', 'theme'];
    for (const kind of kinds) {
      expect(COSMETIC_HUES[kind]).toBeDefined();
      expect(Object.keys(COSMETIC_HUES[kind]).length).toBeGreaterThan(0);
    }
  });

  test('every hue is a valid hex colour', () => {
    for (const kind of Object.keys(COSMETIC_HUES)) {
      for (const [name, v] of Object.entries(COSMETIC_HUES[kind])) {
        // Two shapes ship: a single colour, or four gradient stops for the speed-coloured trail. Both
        // halves are checked, so a typo in either fails here rather than as a silently-invisible sled.
        if (Array.isArray(v.stops)) {
          expect({ kind, name, n: v.stops.length }).toEqual({ kind, name, n: 4 });
          for (const s of v.stops) expect({ kind, name, s }).toEqual({ kind, name, s: expect.stringMatching(HEX) });
        } else {
          expect({ kind, name, col: v.color }).toEqual({ kind, name, col: expect.stringMatching(HEX) });
        }
      }
    }
  });
});

describe('resolveCosmetics', () => {
  test('default equipment leaves the sled exactly as it was before W4', () => {
    // The whole feature is additive: an untouched profile must render the pre-W4 sled, byte for byte.
    const out = resolveCosmetics(profileWith({}), PALETTE, PALETTE_HEX, {});
    expect(out.rider).toBe(PALETTE_HEX.magenta);
    expect(out.glow).toBe(PALETTE_HEX.cyan);
    expect(out.trail).toEqual([PALETTE_HEX.cyan, PALETTE_HEX.lime, PALETTE_HEX.amber, PALETTE_HEX.magenta]);
    expect(out.theme).toBe('default');
    expect(out.overridden).toBe(false);
  });

  test('an equipped rider hue reaches the rider', () => {
    const out = resolveCosmetics(profileWith({ rider: 'rider-hue-mint' }), PALETTE, PALETTE_HEX, {});
    expect(out.rider).toBe(COSMETIC_HUES.rider.mint.color);
    expect(out.rider).not.toBe(PALETTE_HEX.magenta);
  });

  test('an equipped glow reaches the glow, and an equipped trail replaces all four stops', () => {
    const out = resolveCosmetics(
      profileWith({ glow: 'sled-glow-warm', trail: 'trail-hue-ember' }), PALETTE, PALETTE_HEX, {},
    );
    expect(out.glow).toBe(COSMETIC_HUES.sledGlow.warm.color);
    const ember = COSMETIC_HUES.trail.ember.stops;
    expect(out.trail).toEqual(ember);
    expect(out.trail).toHaveLength(4);
  });

  test('an owned-but-unknown id falls back to default instead of throwing', () => {
    // A save from a build that shipped a cosmetic this build does not know must still boot.
    const out = resolveCosmetics(profileWith({ rider: 'rider-hue-nonexistent' }), PALETTE, PALETTE_HEX, {});
    expect(out.rider).toBe(PALETTE_HEX.magenta);
    expect(out.missing).toContain('rider-hue-nonexistent');
  });

  test('a profile that is missing entirely resolves to defaults', () => {
    for (const p of [null, undefined, {}, { equipped: null }]) {
      const out = resolveCosmetics(p, PALETTE, PALETTE_HEX, {});
      expect(out.rider).toBe(PALETTE_HEX.magenta);
      expect(out.overridden).toBe(false);
    }
  });

  test('colourblind mode wins over every cosmetic hue', () => {
    // The safety clause. Colourblind palettes exist so hazards stay distinguishable; a paid cosmetic must
    // never be able to undo that, so with a colourblind palette the cosmetic is refused entirely.
    const out = resolveCosmetics(
      profileWith({ rider: 'rider-hue-plum', glow: 'sled-glow-cold', trail: 'trail-hue-tidal' }),
      PALETTE, PALETTE_HEX, { colorblind: true },
    );
    expect(out.overridden).toBe(true);
    expect(out.rider).toBe(PALETTE_HEX.magenta);
    expect(out.glow).toBe(PALETTE_HEX.cyan);
    expect(out.trail).toEqual([PALETTE_HEX.cyan, PALETTE_HEX.lime, PALETTE_HEX.amber, PALETTE_HEX.magenta]);
  });

  test('the danger colour is never a cosmetic target', () => {
    // If a future hue ever claims `danger`, this fails: cosmetics tint the rider, glow and trail, never
    // the thing that has to read as lethal.
    for (const kind of Object.keys(COSMETIC_HUES)) {
      for (const v of Object.values(COSMETIC_HUES[kind])) {
        expect(Object.keys(v)).not.toContain('danger');
      }
    }
    const out = resolveCosmetics(profileWith({ rider: 'rider-hue-mint', glow: 'sled-glow-warm' }), PALETTE, PALETTE_HEX, {});
    expect(out.danger).toBe(PALETTE_HEX.danger);
  });

  test('the UI theme is reported but never overrides the palette in colourblind mode', () => {
    const on = resolveCosmetics(profileWith({ theme: 'theme-sunset' }), PALETTE, PALETTE_HEX, {});
    expect(on.theme).toBe('sunset');
    const cb = resolveCosmetics(profileWith({ theme: 'theme-sunset' }), PALETTE, PALETTE_HEX, { colorblind: true });
    expect(cb.theme).toBe('default');
  });
});

describe('the two ways an item can be equipped', () => {
  // ProfileStore.equip() writes the item's VALUE ('mint'); a hand-written save or an older test may write
  // the ID ('rider-hue-mint'). Both must render, or an item bought in the shop is invisible.
  test('an equipped VALUE renders (this is what equip() actually stores)', () => {
    const out = resolveCosmetics(profileWith({ rider: 'mint' }), PALETTE, PALETTE_HEX, {});
    expect(out.rider).toBe(COSMETIC_HUES.rider.mint.color);
  });

  test('an equipped ID renders too', () => {
    const out = resolveCosmetics(profileWith({ rider: 'rider-hue-mint' }), PALETTE, PALETTE_HEX, {});
    expect(out.rider).toBe(COSMETIC_HUES.rider.mint.color);
  });

  test('shop equip() output round-trips through the resolver', () => {
    // The integration seam: take the profile the shop produces and resolve it, rather than asserting the
    // shape of equip()'s output and hoping the renderer agrees.
    // Buy then equip, the same two calls the shop makes: equip() correctly refuses an unowned item, so
    // skipping the purchase would test a refused equip and call it a render failure.
    const bought = equip(purchase({ ...DEFAULT_PROFILE, bank: 500 }, 'rider-hue-mint'), 'rider-hue-mint');
    const out = resolveCosmetics(bought, PALETTE, PALETTE_HEX, {});
    expect(out.rider).toBe(COSMETIC_HUES.rider.mint.color);
    expect(out.missing).toEqual([]);
  });
});

describe('cosmeticFor', () => {
  test('resolves an id to its catalogue entry', () => {
    expect(cosmeticFor('rider-hue-mint')).toMatchObject({ slot: 'rider', value: 'mint' });
    expect(cosmeticFor('nope')).toBeNull();
    expect(cosmeticFor(undefined)).toBeNull();
  });
});/**
 * Readable Chaos, phase 3: the crash beat in the shipped RunScene (FX at 0.25x for 400 ms after the hit-stop, an eased
 * camera zoom-in that holds; visual only) and the banner naming the killer in the shipped UIScene.onCrash.
 */
import { jest } from '@jest/globals';

const FakePhaser = {
  Scene: class {},
  Physics: { Matter: { Matter: { Bodies: { rectangle: () => ({}), circle: () => ({}) }, Body: {} } } },
  Renderer: { WebGL: { Pipelines: { PostFXPipeline: class {} } } },
  GameObjects: { Container: class {}, Graphics: class {}, BitmapText: class {}, Zone: class {}, Image: class {}, Rectangle: class {}, Text: class {} },
  BlendModes: { ADD: 1 },
  Scenes: { Events: { UPDATE: 'update', SHUTDOWN: 'shutdown', DESTROY: 'destroy' } },
  Math: { Between: (a) => a, Clamp: (v, a, b) => Math.min(b, Math.max(a, v)) },
};
jest.unstable_mockModule('phaser', () => ({ default: FakePhaser }));
jest.unstable_mockModule('../../src/shaders/GlitchPipeline.js', () => ({ GlitchPipeline: { install() {} } }));

const { RunScene } = await import('../../src/scenes/RunScene.js');
const { UIScene } = await import('../../src/scenes/UIScene.js');
const { CRASH_BEAT } = await import('../../src/systems/CrashReport.js');
const { TUNING } = await import('../../src/systems/PhysicsTuner.js');
const { speedZoom } = await import('../../src/systems/CameraZoom.js');
const { REG } = await import('../../src/constants.js');
const { loadContent } = await import('./_helpers.js');
const { LastDeathMarker } = await import('../../src/entities/LastDeathMarker.js');
const { BestMarker } = await import('../../src/entities/BestMarker.js');

const HS = TUNING.hitStopCrashMs;

function frameStub(crashTimerMs) {
  const fxDts = [];
  const s = Object.create(RunScene.prototype);
  Object.assign(s, {
    sled: { x: 5000, y: 300, vx: 800, vy: 0, speed: 800, render() {}, body: { angle: 0 } },
    crashed: true, crashTimerMs, hitStopMs: 0, shieldCharges: 0,
    cameras: { main: { zoom: 0.7, scrollX: 4800, scrollY: 100, setZoom(z) { this.zoom = z; } } },
    mesh: { cull() {} }, hazards: new Map(), powerups: new Map(), fx: { update: (d) => fxDts.push(d) },
    shardField: null, bestMarker: null, deathMarker: null, groundTelegraph: null, streaks: null,
    bg: { update() {} }, flashRect: { alpha: 0, setAlpha() {} }, runTimeMs: 9000,
    drawStreaks() {}, updateBlindOverlay() {}, updateCamera() {}, heightFn: () => 300,
  });
  return { s, fxDts };
}

describe('crash beat: FX time', () => {
  test('hit-stop 0.08x, then 0.25x for 400 ms, then normal', () => {
    const at = (t) => { const { s, fxDts } = frameStub(t); s.renderFrame(16); return fxDts[0] / 16; };
    expect(at(HS - 1)).toBeCloseTo(0.08, 9);
    expect(at(HS)).toBeCloseTo(CRASH_BEAT.slowScale, 9);
    expect(at(HS + CRASH_BEAT.slowMs - 1)).toBeCloseTo(0.25, 9);
    expect(at(HS + CRASH_BEAT.slowMs)).toBeCloseTo(1, 9);
  });
  test('a live run is untouched', () => {
    const { s, fxDts } = frameStub(0);
    s.crashed = false;
    s.trail = { update() {} };
    s.renderFrame(16);
    expect(fxDts[0]).toBe(16);
  });
});

describe('crash beat: camera zoom-in', () => {
  function cam(crashed, crashTimerMs) {
    const s = Object.create(RunScene.prototype);
    Object.assign(s, {
      sled: { x: 50000, y: 3000, vx: 900, vy: 0, speed: 900 }, crashed, crashTimerMs,
      cameras: { main: { zoom: 1, scrollX: 0, scrollY: 0, setZoom(z) { this.zoom = z; } } },
      _camX: 50000 - 182, _camY: 3000 - 90, _zoom: speedZoom(900), _zoomKick: 0, shakeAmp: 0, bg: null, flashRect: null, blindRect: null,
    });
    s.updateCamera(16);
    return s.cameras.main.zoom;
  }
  test('eases in over the slow-mo and holds; nothing before the hit-stop ends', () => {
    const base = cam(false, 0);
    expect(cam(true, 0)).toBeCloseTo(base, 2);
    expect(cam(true, HS + CRASH_BEAT.slowMs / 2)).toBeGreaterThan(base);
    const full = cam(true, HS + CRASH_BEAT.slowMs);
    expect(full).toBeCloseTo(Math.round(base * (1 + CRASH_BEAT.zoomIn) * 200) / 200, 2);
    expect(cam(true, 900)).toBeCloseTo(full, 6);
  });
});

describe('the crash banner names the killer', () => {
  const CONTENT = loadContent();
  function ui() {
    const banners = [];
    const s = Object.create(UIScene.prototype);
    Object.assign(s, {
      registry: { get: (k) => (k === REG.CONTENT ? CONTENT : undefined) },
      comboInfo: { setText() {} },
      _banner: (text, color, scale) => banners.push([text, color, scale]),
    });
    return { s, banners };
  }
  test('a hazard crash shows the hazard name (biome ones too)', () => {
    for (const [id, name] of [['packetSpike', 'PACKET SPIKE'], ['rollingBoulder', 'ROLLING BOULDER'], ['gearGate', 'GEAR GATE'], ['dewDrop', 'DEW DROP']]) {
      const { s, banners } = ui();
      s.onCrash({ cause: 'hazard', hazardId: id, negated: false });
      expect(banners[0][0]).toBe(name);
      expect(banners[0][1]).toBe('danger');
    }
  });
  test('other causes are named; an absorbed crash still says HASHED BACKUP USED (no killer)', () => {
    const { s, banners } = ui();
    s.onCrash({ cause: 'terrain', negated: false });
    s.onCrash({ cause: 'hazard', hazardId: 'packetSpike', negated: true });
    expect(banners.map((b) => b[0])).toEqual(['HEAD FIRST', 'HASHED BACKUP USED']);
  });
  test('a long name still fits the 480 px HUD at its scale', () => {
    const { s, banners } = ui();
    s.onCrash({ cause: 'chasm', negated: false });
    const [text, , scale] = banners[0];
    expect(text.length * 6 * scale).toBeLessThanOrEqual(470);
  });
});

describe('DIED HERE marker vs the BEST marker (both often stand at the same distance: your best is where you died)', () => {
  const scene = () => {
    const labels = [];
    const chain = (o) => new Proxy(o, { get: (t, k) => (k in t ? t[k] : () => chain(t)) });
    return {
      labels,
      add: {
        graphics: () => chain({}),
        text: (x, y, s) => { const l = chain({ s, x, y, setPosition(px, py) { this.x = px; this.y = py; return this; } }); labels.push(l); return l; },
      },
    };
  };
  test('labels sit on different rows, so they never overprint', () => {
    const PAL = { danger: 1, lime: 2, amber: 3 };
