    new BestMarker(sb, PAL, 1000, 344).update(0, 900, () => 500);
    const sd = scene();
    new LastDeathMarker(sd, PAL, 1004, 344).update(0, 900, () => 500);
    expect(Math.abs(sb.labels[0].y - sd.labels[0].y)).toBeGreaterThanOrEqual(16);
  });
