    const title = t.find((x) => x.text === 'CRASHED' && x.color === 'danger');
    expect(line.y).toBeGreaterThanOrEqual(title.y + 8 * title.scale);
    expect(line.y + 8).toBeLessThanOrEqual(PANEL_Y);
