  expect(() => createDailyShortlist(panel(), { ...pin, buildCommit: 'main' })).toThrow(/40-hex/);
  expect(() => createDailyShortlist(panel(), { ...pin, sourceSha256: 'trusted' })).toThrow(/SHA-256/);
});

test('CLI hashes the exact file bytes, writes JSON only on success, and bounds regular input files', () => {
  const tmp = mkdtempSync(join(tmpdir(), 'bb-shortlist-test-'));
  const file = join(tmp, 'fixture.json');
  const cli = (...args) => spawnSync(process.execPath, ['tools/sim/shortlist-daily.mjs', ...args], { encoding: 'utf8' });
  const run = (p = file) => cli('--panel', p, '--build', pin.buildCommit);
  const raw = Buffer.from(`  ${JSON.stringify(panel())}\n\n`);
  try {
    writeFileSync(file, raw);
    const one = run(), two = run();
    expect(one.status).toBe(0);
    expect(one.stderr).toBe('');
    expect(two.stdout).toBe(one.stdout);
    expect(JSON.parse(one.stdout).source.sha256).toBe(createHash('sha256').update(raw).digest('hex'));
    expect(cli('--panel', file).stdout).toBe('');
    const fatigue = panel();
    fatigue.kind = 'local-tool-assisted-fatigue-bot-panel';
    fatigue.results.forEach((cell) => { cell.humanNoise.version = 2; });
    writeFileSync(file, JSON.stringify(fatigue));
    expect(run()).toMatchObject({
      status: 1, stdout: '',
      stderr: 'Shortlist: Fatigue panels (noise model v2) are not supported by the classic-only shortlist. ' +
        'Rerun the #126 bot panel with --verify and without --fatigue.\n',
    });
    const unverifiedClassic = panel();
    unverifiedClassic.verify = false;
    writeFileSync(file, JSON.stringify(unverifiedClassic));
    expect(run()).toMatchObject({
      status: 1, stdout: '', stderr: 'Shortlist: Use a local #126 bot panel produced with successful --verify\n',
    });
    expect(run(tmp)).toMatchObject({ status: 1, stdout: '', stderr: expect.stringContaining('regular local panel file') });
    writeFileSync(file, Buffer.from([255]));
    expect(run()).toMatchObject({ status: 1, stdout: '', stderr: expect.stringContaining('UTF-8 JSON') });
    writeFileSync(file, Buffer.alloc(MAX_PANEL_BYTES + 1));
    expect(run()).toMatchObject({ status: 1, stdout: '', stderr: expect.stringContaining('4 MiB limit') });
  } finally { rmSync(tmp, { recursive: true, force: true }); }
});/**
 * Decision 5 (Marvin, 2026-11-16): the W6 biomes join the Daily biome rotation from 2026-11-17 (UTC).
 * Every date before the cutover keeps exactly the mask it always had, so past Daily records, practice
 * replays of past dates and the official-run checks stay valid.
 */
import { DailyPatch } from '../../src/systems/DailyPatch.js';

const day = (y, m, d, h = 12) => new Date(Date.UTC(y, m - 1, d, h));
const OLD = [0, 0, 0, 0, 1, 2, 4, 8, 16];
const DAY_MS = 86400000;

describe('Daily rotation cutover (decision 5)', () => {
  test('every date before 2026-11-17 keeps its v1 mask (one full year back)', () => {
    for (let i = 1; i <= 366; i++) {
      const t = Date.UTC(2026, 10, 17) - i * DAY_MS + 12 * 3600000;
      const n = Math.floor(t / DAY_MS);
      expect({ i, m: DailyPatch.biomeMaskForDate(new Date(t)) }).toEqual({ i, m: OLD[n % 9] });
    }
  });

  test('pins the last pre-cutover days and the cutover day itself', () => {
    expect(DailyPatch.biomeMaskForDate(day(2026, 11, 13))).toBe(8);
    expect(DailyPatch.biomeMaskForDate(day(2026, 11, 14))).toBe(16);
    expect(DailyPatch.biomeMaskForDate(day(2026, 11, 16, 23))).toBe(0);
    expect(DailyPatch.CUTOVER_DATE_KEY).toBe('2026-11-17');
    expect(DailyPatch.biomeMaskForDate(day(2026, 11, 17, 0))).toBe(32); // Space Mountain premieres at 00:00 UTC
  });

  test('from the cutover, a 15-day cycle features all 11 biomes once and keeps 4 clear days', () => {
    const masks = [];
    for (let i = 0; i < 15; i++) masks.push(DailyPatch.biomeMaskForDate(day(2026, 11, 17 + i)));
    expect(masks.filter((m) => m === 0).length).toBe(4);
    expect(masks.filter((m) => m !== 0).sort((a, b) => a - b)).toEqual([1, 2, 4, 8, 16, 32, 64, 128, 256, 512, 1024]);
    for (const m of masks) expect(m === 0 || (m & (m - 1)) === 0).toBe(true); // one biome per day, never a mix
    for (let i = 0; i < 15; i++) {
      expect(DailyPatch.biomeMaskForDate(day(2026, 11, 17 + i + 15))).toBe(masks[i]); // cycles, no drift
    }
  });

  test('the six W6 biomes premiere first, each followed by a clear day until the last pair', () => {
    const first = [];
    for (let i = 0; i < 10; i++) first.push(DailyPatch.biomeMaskForDate(day(2026, 11, 17 + i)));
    expect(first).toEqual([32, 0, 64, 0, 128, 0, 256, 0, 512, 1024]);
  });

  test('infoForDateKey uses the same rotation on both sides of the cutover', () => {
    expect(DailyPatch.infoForDateKey('2026-11-14').biomeMask).toBe(16);
    expect(DailyPatch.infoForDateKey('2026-11-17').biomeMask).toBe(32);
    expect(DailyPatch.infoForDateKey('2026-11-19').biomeMask).toBe(64);
  });
});import { DailyPatch } from '../../src/systems/DailyPatch.js';

const MOD_KEYS = ['tuckSpeedMul', 'tuckSteerMul', 'gravityMul', 'frictionMul', 'airControlMul', 'pushForceMul'];

describe('DailyPatch rules data', () => {
  test('several rules with unique ids, names, descriptions and sane multiplier-only modifiers', () => {
    expect(DailyPatch.RULES.length).toBeGreaterThanOrEqual(5);
    const ids = DailyPatch.RULES.map((r) => r.id);
    expect(new Set(ids).size).toBe(ids.length);
    for (const r of DailyPatch.RULES) {
      expect(r.name).toBeTruthy();
      expect(r.description).toBeTruthy();
      const keys = Object.keys(r.modifiers);
      expect(keys.length).toBeGreaterThan(0);
      for (const k of keys) {
        expect(MOD_KEYS).toContain(k);
        expect(r.modifiers[k]).toBeGreaterThanOrEqual(0.4);
        expect(r.modifiers[k]).toBeLessThanOrEqual(2);
      }
    }
  });

  test('the doc example rule exists: tuck +50% speed, steering -50%', () => {
    const r = DailyPatch.getRuleById('tuckBoost');
    expect(r.modifiers).toEqual({ tuckSpeedMul: 1.5, tuckSteerMul: 0.5 });
  });

  test('getRuleById for unknown id is null', () => {
    expect(DailyPatch.getRuleById('nope')).toBeNull();
    expect(DailyPatch.getRuleById(undefined)).toBeNull();
  });
});

describe('DailyPatch.getDailyInfo', () => {
  test('stable within a UTC day, including the last millisecond', () => {
    const a = DailyPatch.getDailyInfo(new Date('2025-03-10T00:00:00.000Z'));
    const b = DailyPatch.getDailyInfo(new Date('2025-03-10T12:34:56.000Z'));
    const c = DailyPatch.getDailyInfo(new Date('2025-03-10T23:59:59.999Z'));
    expect(a.rule.id).toBe(b.rule.id);
    expect(b.rule.id).toBe(c.rule.id);
    expect(a.dateKey).toBe('2025-03-10');
    expect(c.dateKey).toBe('2025-03-10');
    expect(a.seed).toBe('daily-2025-03-10');
  });

  test('changes exactly at 00:00 UTC (consecutive days differ)', () => {
    const before = DailyPatch.getDailyInfo(new Date('2025-03-10T23:59:59.999Z'));
    const after = DailyPatch.getDailyInfo(new Date('2025-03-11T00:00:00.000Z'));
    expect(after.dateKey).toBe('2025-03-11');
    expect(after.rule.id).not.toBe(before.rule.id);
  });

  test('uses UTC, not local time: a timestamp late in the evening in UTC-8 is the next UTC day', () => {
    const d = new Date('2025-06-01T03:30:00.000Z'); // 2025-05-31 evening in California
    expect(DailyPatch.getDailyInfo(d).dateKey).toBe('2025-06-01');
  });

  test('deterministic: same date from different Date objects, and cycles through all rules', () => {
    const seen = new Set();
    for (let day = 0; day < DailyPatch.RULES.length; day++) {
      const d = new Date(Date.UTC(2025, 0, 1 + day, 5));
      const info = DailyPatch.getDailyInfo(d);
      expect(DailyPatch.getDailyInfo(new Date(d.getTime())).rule.id).toBe(info.rule.id);
      seen.add(info.rule.id);
    }
    expect(seen.size).toBe(DailyPatch.RULES.length);
    // periodic with period RULES.length
    const n = DailyPatch.RULES.length;
    expect(DailyPatch.getDailyInfo(new Date(Date.UTC(2025, 0, 1))).rule.id)
      .toBe(DailyPatch.getDailyInfo(new Date(Date.UTC(2025, 0, 1 + n))).rule.id);
  });

  test('index is days-since-epoch modulo length (documented contract)', () => {
    const d = new Date(Date.UTC(2030, 4, 17, 9));
    const days = Math.floor(d.getTime() / 86400000);
    expect(DailyPatch.getDailyInfo(d).rule).toBe(DailyPatch.RULES[days % DailyPatch.RULES.length]);
  });

  test('works before the epoch and with invalid dates (falls back to now, no throw)', () => {
    const old = DailyPatch.getDailyInfo(new Date('1965-02-03T10:00:00Z'));
    expect(DailyPatch.RULES).toContain(old.rule);
    expect(old.dateKey).toBe('1965-02-03');
    expect(() => DailyPatch.getDailyInfo(new Date('garbage'))).not.toThrow();
    expect(DailyPatch.getDailyInfo(new Date('garbage')).dateKey).toMatch(/^\d{4}-\d{2}-\d{2}$/);
  });

  test('default argument is now', () => {
    expect(DailyPatch.getDailyInfo().dateKey).toBe(new Date().toISOString().slice(0, 10));
  });

  test('msUntilNextRule counts down to the next midnight UTC', () => {
    expect(DailyPatch.msUntilNextRule(new Date('2025-03-10T00:00:00.000Z'))).toBe(86400000);
    expect(DailyPatch.msUntilNextRule(new Date('2025-03-10T23:59:59.000Z'))).toBe(1000);
  });
});

describe('DailyPatch countdown helpers', () => {
  test('msUntilNextRule is exact at boundaries and mid-day', () => {
    expect(DailyPatch.msUntilNextRule(new Date('2025-03-10T20:48:00.000Z'))).toBe(3 * 3600000 + 12 * 60000);
    expect(DailyPatch.msUntilNextRule(new Date('2025-03-10T23:59:59.999Z'))).toBe(1);
  });

  test('formatCountdown', () => {
    expect(DailyPatch.formatCountdown(3 * 3600000 + 12 * 60000)).toBe('3H 12M');
    expect(DailyPatch.formatCountdown(3 * 3600000 + 11 * 60000 + 1)).toBe('3H 12M');
    expect(DailyPatch.formatCountdown(3600000)).toBe('1H 0M');
    expect(DailyPatch.formatCountdown(86400000)).toBe('24H 0M');
    expect(DailyPatch.formatCountdown(12 * 60000)).toBe('12M');
    expect(DailyPatch.formatCountdown(30000)).toBe('<1M');
    expect(DailyPatch.formatCountdown(0)).toBe('0M');
    expect(DailyPatch.formatCountdown(-5)).toBe('0M');
    expect(DailyPatch.formatCountdown(NaN)).toBe('0M');
  });

  test('dateKeyFromSeed round-trips getDailyInfo seeds and rejects others', () => {
    const info = DailyPatch.getDailyInfo(new Date('2025-03-10T05:00:00Z'));
    expect(DailyPatch.dateKeyFromSeed(info.seed)).toBe('2025-03-10');
    expect(DailyPatch.dateKeyFromSeed('daily-2025-02-30')).toBeNull();
    expect(DailyPatch.dateKeyFromSeed('seed-1')).toBeNull();
    expect(DailyPatch.dateKeyFromSeed(null)).toBeNull();
  });
});// Validates the JSON content authored by core-logic against the documented schemas.
