import { readDir, loadContent } from './_helpers.js';

const chunks = readDir('chunks');
const mods = readDir('terrainMods');

describe('chunk templates', () => {
  test('ids are unique and files carry required fields', () => {
    const ids = chunks.map((c) => c.id);
    expect(new Set(ids).size).toBe(ids.length);
    for (const c of chunks) {
      expect(['spline', 'noise', 'bridge']).toContain(c.kind);
      expect(c.weight).toBeGreaterThan(0);
      expect(c.minDistanceM).toBeGreaterThanOrEqual(0);
      expect(c.lengthPx).toBeGreaterThanOrEqual(400);
      expect(Array.isArray(c.tags)).toBe(true);
    }
  });

  test('at least 8 spline templates, plus noise and bridge kinds', () => {
    expect(chunks.filter((c) => c.kind === 'spline').length).toBeGreaterThanOrEqual(8);
    expect(chunks.filter((c) => c.kind === 'noise').length).toBeGreaterThanOrEqual(1);
    expect(chunks.filter((c) => c.kind === 'bridge').length).toBeGreaterThanOrEqual(1);
  });

  test('variety: rollers, kickers, big air, step-downs, long carves, bridges are all present', () => {
    const tags = new Set(chunks.flatMap((c) => c.tags));
    for (const t of ['roller', 'kicker', 'big-air', 'steps', 'carve', 'gap']) expect(tags).toContain(t);
  });

  test('spline control points: x in [0,1] non-decreasing from 0 to 1, y finite, net downhill', () => {
    for (const c of chunks.filter((d) => d.kind === 'spline' || d.kind === 'bridge')) {
      const p = c.controlPoints;
      expect(p.length).toBeGreaterThanOrEqual(2);
      expect(p.length).toBeLessThanOrEqual(15);
      expect(p[0]).toEqual({ x: 0, y: 0 });
      expect(p[p.length - 1].x).toBe(1);
      for (let i = 0; i < p.length; i++) {
        expect(p[i].x).toBeGreaterThanOrEqual(0);
        expect(p[i].x).toBeLessThanOrEqual(1);
        expect(Number.isFinite(p[i].y)).toBe(true);
        if (i) expect(p[i].x).toBeGreaterThan(p[i - 1].x);
      }
      expect(p[p.length - 1].y).toBeGreaterThan(0);
      // nominal slope of the template stays inside the generator's limits
      for (let i = 1; i < p.length; i++) {
        const deg = (Math.atan2(p[i].y - p[i - 1].y, (p[i].x - p[i - 1].x) * c.lengthPx) * 180) / Math.PI;
        expect(deg).toBeLessThan(55);
        expect(deg).toBeGreaterThan(-45);
      }
    }
  });

  test('noise and bridge params are sane', () => {
    for (const c of chunks.filter((d) => d.kind === 'noise')) {
      expect(c.noise.amplitudePx).toBeGreaterThan(0);
      expect(c.noise.frequency).toBeGreaterThan(0);
      expect(c.noise.octaves).toBeGreaterThanOrEqual(1);
      expect(c.noise.meanSlopeDeg).toBeGreaterThan(3);
      expect(c.noise.meanSlopeDeg).toBeLessThan(30);
    }
    for (const c of chunks.filter((d) => d.kind === 'bridge')) {
      expect(c.bridge.gapPx).toBeGreaterThanOrEqual(64);
      expect(c.bridge.gapPx).toBeLessThanOrEqual(224);
      expect(c.bridge.bounceBoost).toBeGreaterThan(300);
      expect(c.lengthPx).toBeGreaterThanOrEqual(c.bridge.gapPx * 3);
    }
  });

  test('there is always an early-game template (minDistanceM 0) and intro tags exist', () => {
    expect(chunks.filter((c) => c.kind === 'spline' && c.minDistanceM === 0).length).toBeGreaterThanOrEqual(2);
    expect(chunks.some((c) => c.tags.includes('intro'))).toBe(true);
    // no noise zone or bridge before 150 m
    for (const c of chunks.filter((d) => d.kind !== 'spline')) expect(c.minDistanceM).toBeGreaterThanOrEqual(150);
  });

  test('modIds reference existing terrain mods', () => {
    const ids = new Set(mods.map((m) => m.id));
    for (const c of chunks) for (const id of c.modIds || []) expect(ids).toContain(id);
  });
});

describe('terrain mods', () => {
  test('the three documented mods exist with schema fields and valid palette keys', () => {
    // The three base mods are pinned by name: they back existing chunk templates, so removing or
    // renaming one is a content break. Biome mods (W3) are additive, so this asserts containment
    // rather than an exact list - W3 adds five, W6 will add six more.
    expect(mods.map((m) => m.id)).toEqual(expect.arrayContaining(['compression', 'highBandwidth', 'wirelessBridge']));
    for (const m of mods) {
      expect(PALETTE_KEYS).toContain(m.colorKey);
      expect(m.weight).toBeGreaterThan(0);
      expect(m.minDistanceM).toBeGreaterThanOrEqual(0);
      expect(m.lengthPx).toHaveLength(2);
      expect(m.lengthPx[0]).toBeLessThanOrEqual(m.lengthPx[1]);
      // A mod must do SOMETHING the player can feel: physics (the original contract), a scoring
      // multiplier (W3's echo zone), a terrain swell (W6's dew bumps) or a launch (W6's geysers).
      // The two W6 shapes are their own categories rather than being smuggled into `physics`, because
      // they act on the SURFACE and on CONTACT, not on the effective constants each frame.
      const physical = Object.keys(m.physics || {}).length > 0;
      const scoring = Number.isFinite(m.scoreMul) && m.scoreMul > 1;
      const swell = Boolean(m.terrainSwell && Number.isFinite(m.terrainSwell.amplitudePx));
      const launch = Boolean(m.launch && Number.isFinite(m.launch.velocityPxS));
      expect({ id: m.id, acts: physical || scoring || swell || launch }).toMatchObject({ id: m.id, acts: true });
    }
  });

  test('physics direction matches the doc: high bandwidth = low friction, compression = more gravity', () => {
    const byId = Object.fromEntries(mods.map((m) => [m.id, m]));
    expect(byId.highBandwidth.physics.frictionMul).toBeLessThan(1);
    expect(byId.compression.physics.gravityMul).toBeGreaterThan(1);
    expect(byId.wirelessBridge.physics.bounceMul).toBeGreaterThan(1);
  });

  test('hazard defs follow the schema; the air hazard is a crash hazard from >= 1500 m', () => {
    const hazards = readDir('hazards');
    const ids = hazards.map((h) => h.id);
    expect(new Set(ids).size).toBe(ids.length);
    for (const h of hazards) {
      expect(typeof h.shapeKey).toBe('string');
      expect(h.size.w).toBeGreaterThan(0);
      expect(h.size.h).toBeGreaterThan(0);
      // B0 added 'blind' / 'gust' for biome defs; base defs keep the original three
      expect(h.biome ? ['crash', 'slow', 'scramble', 'blind', 'gust'] : ['crash', 'slow', 'scramble']).toContain(h.onHit.effect);
      expect(h.weight).toBeGreaterThan(0);
      expect(h.minDistanceM).toBeGreaterThanOrEqual(0);
      expect(['ground', 'air']).toContain(h.placement);
      expect(PALETTE_KEYS).toContain(h.colorKey);
    }
    // the BASE air hazard (biome air hazards such as B1's seagullDive are checked in biome-b1-content.test.js)
    const air = hazards.filter((h) => h.placement === 'air' && !h.biome);
    expect(air.map((h) => h.id)).toEqual(['roguePacket']);
    expect(air[0].onHit.effect).toBe('crash');
    expect(air[0].minDistanceM).toBeGreaterThanOrEqual(1500);
  });

  test('loadContent exposes every group', () => {
    const c = loadContent();
    expect(c.chunks.length).toBe(chunks.length);
    // base content is unchanged (spec §8: no new base hazard or power-up); biome-tagged defs are listed separately
    const base = (o) => Object.keys(o).filter((id) => !o[id].biome).sort();
    const biome = (o) => Object.keys(o).filter((id) => o[id].biome).sort();
    expect(base(c.hazards)).toEqual(['garbageDataVent', 'glitchChasm', 'overflowFirewall', 'packetSpike', 'roguePacket']);
    // Shard Magnet (owner request, 2026-11-20) is a base pickup with its own placement, outside the terrain output.
    expect(base(c.powerups)).toEqual(['clockPulse', 'hashedBackup', 'packetBurst', 'shardMagnet']);
    expect(c.powerups.shardMagnet.placement).toBe('own');
    expect(biome(c.hazards)).toEqual(['ashCloud', 'chocolateRiver', 'dewDrop', 'gearGate', 'groomerCat', 'gustFront', 'meteor', 'rollingBoulder', 'seagullDive', 'seaweedTangle', 'shatterWall']);
    expect(biome(c.powerups)).toEqual(['aquaLungBubble', 'clockworkTreads', 'crystalClearGoggles', 'gravityStabilizer', 'heatShield', 'mapleWax', 'royalJellyWax', 'sandrunnerSkis', 'slickWaxSpray', 'stabilizerRails', 'sweetToothCoating']);
  });
});import { readFileSync } from 'node:fs';
import { TextDecoder, TextEncoder } from 'node:util';
import { jest } from '@jest/globals';
import {
  MAX_STRIP_FILE_BYTES, MAX_STRIP_POINTS, MAX_STRIP_POSES, MAX_STRIP_SVG_BYTES, openDownhillRunTrace,
} from '../../src/systems/downhill-run-strip.js';
import { renderRunTraceArt } from '../../src/systems/run-trace-art.js';

globalThis.TextEncoder ??= TextEncoder;
globalThis.TextDecoder ??= TextDecoder;

function tape(samples, fields = {}) {
  return JSON.stringify({
    format: 'bb-ghost-tape', version: 1, simTickHz: 120,
    trace: Buffer.from(new Float32Array(samples.flat()).buffer).toString('base64'), ...fields,
  });
}

const points = [[100, 320, 0.5], [300, 420, 1], [200, 370, 0], [400, 470, -1]];
const path = (svg) => svg.match(/<path d="(M[\d.]+ [\d.]+ L[\s\d.L]+)" fill="none" stroke="url\(#trace\)"/)[1];
const vertices = (svg) => path(svg).split(' ').filter((x) => /^[ML]/.test(x)).length;

describe('Downhill Run Strip', () => {
  test('retains the actual decoded coordinates with v1 nominal sample ticks, not header endpoints', () => {
    const trace = openDownhillRunTrace(tape(points, { endTick: 17, cause: 'crash' }));
    expect(trace.count).toBe(4);
    expect(trace.sample(0)).toEqual({ x: 100, y: 320, tick: 4, nominalSeconds: 4 / 120 });
    expect(trace.sample(3)).toEqual({ x: 400, y: 470, tick: 16, nominalSeconds: 16 / 120 });
    expect(trace.render()).toContain('Trace start - sample 1');
    expect(trace.render()).toContain('Trace end - sample 4');
    expect(trace.render()).not.toContain('crash');
  });

  test('keeps backward X motion, positive Y down and equal geometric scale', () => {
    const svg = openDownhillRunTrace(tape(points)).render();
    expect(path(svg)).toBe('M382 127 L672.67 272.33 L527.33 199.67 L818 345');
    const translated = points.map(([x, y, angle]) => [x + 11000, y - 7000, angle]);
    expect(openDownhillRunTrace(tape(translated)).render()).toBe(svg);
  });

  test('fits the selected interval independently and distinguishes section from trace boundaries', () => {
    const trace = openDownhillRunTrace(tape(points));
    const svg = trace.render({ start: 1, end: 2 });
    expect(svg).toContain('samples 2 through 3 of 4');
    expect(svg).toContain('Section start - sample 2');
    expect(svg).toContain('Section end - sample 3');
    expect(path(svg)).toBe('M818 345 L382 127');
    expect(trace.render({ start: 0, end: 2 })).toContain('Trace start - sample 1');
    expect(trace.render({ start: 1, end: 3 })).toContain('Trace end - sample 4');
    expect(trace.render({ start: 1, end: 2, selected: 1 })).toContain('stroke="#ffc977"');
    expect(svg).not.toContain('stroke="#ffc977"');
  });

  test('bounds the overview but includes endpoints and extrema; detailed sections show each sample', () => {
    const samples = Array.from({ length: MAX_STRIP_POSES }, (_, i) => [i, i % 101, 0]);
    samples[3333] = [1000, -50000, 0];
    samples[4444] = [50000, 90000, 0];
    const trace = openDownhillRunTrace(tape(samples));
    const svg = trace.render();
    expect(vertices(svg)).toBeLessThanOrEqual(MAX_STRIP_POINTS);
    expect(svg.length).toBeLessThan(MAX_STRIP_SVG_BYTES);
    expect(svg).toContain(`${vertices(svg)} of 32768 window poses shown`);
    expect(svg).toContain('Trace end - sample 32768');
    expect(path(svg)).toMatch(/(?:^| )L[\d.]+ 127 /);
    expect(path(svg)).toMatch(/(?:^| )L[\d.]+ 345 /);
    expect(vertices(trace.render({ start: 3332, end: 3334 }))).toBe(3);
  });

  test('keeps a non-extremal cursor on the overview line without changing the exported section', () => {
    const rows = Array.from({ length: 1532 }, (_, i) => [i, 0, 0]);
    // All four points below are in the first decimation bucket. Sample 4 is
    // neither a bucket extreme nor collinear with the retained path.
    for (const [index, y] of [[2, 60], [3, 40], [4, 40], [5, -60]]) rows[index][1] = y;
    const trace = openDownhillRunTrace(tape(rows));
    const withoutCursor = trace.render();
    const preview = trace.render({ selected: 3 });
    const [, x, y] = preview.match(/<circle cx="([\d.]+)" cy="([\d.]+)" r="13"/);
    expect(path(preview)).toContain(` L${x} ${y} `);
    expect(path(withoutCursor)).not.toContain(` L${x} ${y} `);
    expect(path(preview).replace(` L${x} ${y}`, '')).toBe(path(withoutCursor));
    expect(vertices(preview)).toBe(vertices(withoutCursor) + 1);
    expect(vertices(preview)).toBeLessThanOrEqual(MAX_STRIP_POINTS);
    expect(vertices(trace.render({ selected: 2 }))).toBe(vertices(withoutCursor));
    expect(vertices(trace.render({ selected: 1531 }))).toBe(vertices(withoutCursor));
    expect(trace.render()).toBe(withoutCursor);
  });

  test.each([
    [[[4, 1, 0], [4, 5, 0]], 'M600 127 L600 345'],
    [[[1, 4, 0], [5, 4, 0]], 'M64 236 L1136 236'],
    [[[1, 4, 0], [1, 4, 0]], 'M600 236 L600 236'],
    [[[0, 0, 0], [2 ** -149, 2 ** -149, 0]], 'M491 127 L709 345'],
  ])('keeps constant, degenerate and tiny axes finite', (samples, expected) => {
    expect(path(openDownhillRunTrace(tape(samples)).render())).toBe(expected);
  });

  test('exports deterministic static geometry and never embeds arbitrary header fields or payload', () => {
    const malicious = '<script>bad</script><a href="https://invalid.example">';
    const plain = openDownhillRunTrace(tape(points)).render();
    const modified = openDownhillRunTrace(tape(points, {
      runId: malicious, seed: 'private-seed', initials: 'XYZ', score: 1234567,
      inputs: ['raw-input'], checkpoints: ['raw-checkpoint'], verification: 'trusted',
      traceMarker: 'raw-trace', physicsVersion: 999,
    })).render();
    expect(modified).toBe(plain);
    expect(modified).toContain('LOCAL / UNVERIFIED');
    expect(modified).not.toMatch(/<script|<a |href=|foreignObject|onload=|trusted|private-seed|raw-input|raw-checkpoint|XYZ|1234567/);
    expect(modified).not.toContain(JSON.parse(tape(points)).trace);
  });

  test('art preview uses the exact full decoded poses, not section or input metadata', () => {
    const noisy = tape(points, { seed: 'private-seed', runId: '<script>bad</script>', inputs: ['raw-input'], score: 1234567 });
    const trace = openDownhillRunTrace(noisy);
    const svg = renderRunTraceArt(new Float32Array(points.flat()));
    expect(trace.renderArt()).toBe(svg);
    expect(trace.renderArt()).not.toMatch(/private-seed|<script|raw-input|1234567/);
    expect(trace.renderArt()).toContain('LOCAL / UNVERIFIED');
    const section = trace.render({ start: 1, end: 2 });
    expect(section).toBe(openDownhillRunTrace(tape(points)).render({ start: 1, end: 2 }));
    expect(trace.renderArt()).toBe(svg);
  });

  test.each([
    'invalid JSON',
    '{}',
    'null',
    tape(points, { version: 2 }),
    tape(points, { simTickHz: 60 }),
    tape(points, { trace: 'A'.repeat(33) }),
    tape(points, { trace: `${'A'.repeat(31)}=` }),
    tape(points, { trace: `${'A'.repeat(31)}_` }),
    tape(points, { trace: 'A'.repeat(16 * (MAX_STRIP_POSES + 1)) }),
    tape([[1, 2, 0]]),
    tape([[1, 2, 0], [3, 4, Infinity]]),
    tape([[1, 2, 0], [3, NaN, 0]]),
    tape([[1, 2, 0], [1e20, 4, 0]]),
    'é'.repeat(MAX_STRIP_FILE_BYTES / 2 + 1),
  ])('rejects malformed, incompatible or excessive inputs without echoing file data', (json) => {
    expect(() => openDownhillRunTrace(json)).toThrow(/^(Expected|Could not read|GhostTape poses|Use one)/);
  });

  test('rejects invalid windows and selected indices', () => {
    const trace = openDownhillRunTrace(tape(points));
    for (const window of [{ start: -1 }, { start: 1.5 }, { start: 2, end: 2 }, { end: 4 },
      { start: 1, selected: 0 }, { selected: 4 }]) {
      expect(() => trace.render(window)).toThrow(/Choose a section/);
    }
    expect(() => trace.sample(1.1)).toThrow(/Choose a recorded sample/);
  });
});

test('file changes clear artwork immediately; stale reads cannot replace the current preview', async () => {
  const html = readFileSync(new URL('../../tools/downhill-run-strip.html', import.meta.url), 'utf8');
  document.body.replaceChildren(...new DOMParser().parseFromString(html, 'text/html').body.childNodes);
  const image = document.getElementById('run-art'), frame = document.getElementById('run-art-frame');
  const input = document.getElementById('tape'), status = document.getElementById('load-status');
  const methods = ['createObjectURL', 'revokeObjectURL'];
  const saved = methods.map((name) => Object.getOwnPropertyDescriptor(URL, name));
  let sequence = 0;
  const createObjectURL = jest.fn(() => `blob:http://localhost/${++sequence}`);
  const revokeObjectURL = jest.fn();
  Object.defineProperties(URL, {
    createObjectURL: { configurable: true, value: createObjectURL },
    revokeObjectURL: { configurable: true, value: revokeObjectURL },
  });
  const buffer = (text) => new TextEncoder().encode(text).buffer;
  const file = (text) => ({ size: text.length, arrayBuffer: async () => buffer(text) });
  const select = (value) => {
    Object.defineProperty(input, 'files', { configurable: true, value: value ? [value] : [] });
    input.dispatchEvent(new Event('change'));
  };
  const settle = () => new Promise((resolve) => setTimeout(resolve, 0));
  try {
    await import('../../tools/downhill-run-strip.js');
    select(file(tape(points)));
    await settle();
    const first = image.getAttribute('src');
    expect(first).toMatch(/^blob:/);
    expect(frame.hidden).toBe(false);
    expect(document.querySelector('svg')).toBeNull();
    expect(createObjectURL.mock.calls.at(-1)[0].type).toBe('image/svg+xml');
    document.getElementById('zoom-in').click();
    expect(image.getAttribute('src')).toBe(first);

    let finishSlow;
    select({ size: 1, arrayBuffer: () => new Promise((resolve) => { finishSlow = resolve; }) });
    expect(frame.hidden).toBe(true);
    expect(image.hasAttribute('src')).toBe(false);
    expect(revokeObjectURL).toHaveBeenCalledWith(first);
    select(file(tape(points.slice(0, 2))));
    await settle();
    const second = image.getAttribute('src');
    expect(second).toMatch(/^blob:/);
    expect(second).not.toBe(first);
    finishSlow(buffer(tape(points)));
    await settle();
    expect(image.getAttribute('src')).toBe(second);
    expect(status.textContent).toContain('Opened 2 recorded poses');

    select(file('not valid JSON'));
    await settle();
    expect(status.textContent).toBe('Could not read GhostTape JSON');
    expect(image.hasAttribute('src')).toBe(false);
    expect(frame.hidden).toBe(true);
    expect(revokeObjectURL).toHaveBeenCalledWith(second);
    select(null);
    expect(status.textContent).toBe('');
    expect(image.hasAttribute('src')).toBe(false);
  } finally {
    for (const [i, name] of methods.entries()) {
      if (saved[i]) Object.defineProperty(URL, name, saved[i]);
      else delete URL[name];
    }
    document.body.replaceChildren();
  }
});import { jest } from '@jest/globals';
import { defaultSettings,sanitizeSettings } from '../../src/systems/SaveStore.js';
import { BIOME_IDS,HOME_BIOME } from '../../src/systems/music/BiomeVoices.js';
import { melodyPreset,orchestraPreset } from '../../src/systems/music/DynamicOrchestraPresets.js';
import { StemMusicDirector } from '../../src/systems/music/StemMusicDirector.js';
import { AdaptiveBiomeRouter } from '../../src/systems/music/AdaptiveBiomeRouter.js';

const home='voice:bitstream-bluffs';
function fakeDirector() {
	const d=Object.create(StemMusicDirector.prototype);
	d.biome='debutmont';
	d.gains=new Map(['bass','drums','guitar','piano','other',home].map(s=>[s,{}]));
	d.pack={sourceNames:['vocals','drums','bass','guitar','piano','other',home]};
	d.dynamicOrchestra=false;
	d._timbreSignatures=new Map();
	d._stemUserLevels=new Map();
	d.mixer={replaceEffects:jest.fn(()=>true),setRoomSend:jest.fn(()=>true),
		setGain:jest.fn(()=>true),setEffectParam:jest.fn(),selectBiome:jest.fn()};
	d.adaptive={setEnabled:jest.fn(),setSpeed:jest.fn(),setAirborne:jest.fn(),
		setBiome:jest.fn()};
	d.started=false;
	d.speedPxS=0;
	d.airborne=false;
	return d;
}
describe('Dynamic Orchestra gates only replacement recordings, not original-stem DSP',()=>{
	test('defaults OFF and survives strict settings sanitation',()=>{
		expect(defaultSettings().dynamicOrchestra).toBe(false);
		expect(sanitizeSettings({dynamicOrchestra:true}).dynamicOrchestra).toBe(true);
		expect(sanitizeSettings({dynamicOrchestra:false}).dynamicOrchestra).toBe(false);
		expect(sanitizeSettings({dynamicOrchestra:'true'}).dynamicOrchestra).toBe(false);
	});
	test('lead sound differs for each of eleven biomes plus home',()=>{
		const signatures=new Set(BIOME_IDS.map(b=>JSON.stringify(melodyPreset(b))));
		expect(signatures.size).toBe(BIOME_IDS.length);
		expect(melodyPreset(HOME_BIOME).length).toBeGreaterThan(0);
	});
	test('OFF keeps original instrument samples but runs all biome source FX and room sends',()=>{
		const d=fakeDirector();
		d._applyMusicTimbres();
		const map=new Map(d.mixer.replaceEffects.mock.calls.map(x=>[x[0],x[1]]));
		expect(map.get(home)).toEqual(melodyPreset('debutmont'));
		for(const stem of ['bass','drums','guitar','piano','other']){
			expect(map.get(stem)).toEqual(orchestraPreset('debutmont',stem));
			expect(map.get(stem).length).toBeGreaterThan(0);
			// NULL resets each input's standard biome space send. OFF must
			// never force zero or bypass its source effects.
			expect(d.mixer.setRoomSend).toHaveBeenCalledWith(stem,null);
		}
		expect(d.adaptive.setEnabled).not.toHaveBeenCalled();
	});
	test('ON/OFF changes ONLY adaptive replacement routing, leaves processing + clock untouched',()=>{
		const d=fakeDirector();
		d.started=true;
		d.clockStart=12.78;
		d.trackIndex=2;
		d._applyMusicTimbres(); // normally applied on song start/biome change
		const before=new Map(d.mixer.replaceEffects.mock.calls.map(x=>[x[0],x[1]]));
		d.mixer.replaceEffects.mockClear();
		d.mixer.setRoomSend.mockClear();
		d.setDynamicOrchestra(true);
		expect(d.adaptive.setEnabled).toHaveBeenLastCalledWith(true);
		expect(d.started).toBe(true);
		expect(d.clockStart).toBe(12.78);
		expect(d.trackIndex).toBe(2);
		// No FX rebuild, no source dryness/mute just because DO toggles.
		expect(d.mixer.replaceEffects).not.toHaveBeenCalled();
		expect(d.mixer.setRoomSend).not.toHaveBeenCalled();
		d.setDynamicOrchestra(false);
		expect(d.adaptive.setEnabled).toHaveBeenLastCalledWith(false);
		expect(d.mixer.replaceEffects).not.toHaveBeenCalled();
		expect(d.mixer.setRoomSend).not.toHaveBeenCalled();
		for(const stem of ['bass','drums','guitar','piano','other',home])
			expect(before.get(stem).length).toBeGreaterThan(0);
		// Returning to OFF does not stop an original-source effects chain.
		d.biome='crystal-cavern';
		d._applyMusicTimbres();
		for(const stem of ['bass','drums','guitar','piano','other']){
			expect(d.mixer.replaceEffects).toHaveBeenCalledWith(
				stem,orchestraPreset('crystal-cavern',stem),.18);
		}
	});
	test('original bass speed motion works with adaptive OFF and no replacement files',()=>{
		const d=fakeDirector();
		d.adaptive=null;
		d.pack.adaptive=null;
		d.setSpeed(0);
		expect(d.mixer.setGain).toHaveBeenCalledWith('bass',.2,{motion:true,time:.16});
		d.setSpeed(1500);
		expect(d.mixer.setGain).toHaveBeenCalledWith('bass',1.18,{motion:true,time:.16});
	});
	test('original drums duck while airborne in either orchestra mode',()=>{
		const d=fakeDirector();
		d.setAirborne(true);
		expect(d.mixer.setGain).toHaveBeenCalledWith('drums',.22,{motion:true,time:.15});
		d.setAirborne(false);
		expect(d.mixer.setGain).toHaveBeenCalledWith('drums',1,{motion:true,time:.15});
	});
	test('future physical note-replacements remain gated OFF, ON enables them',()=>{
		const r=Object.create(AdaptiveBiomeRouter.prototype);
		r.pack={adaptive:{featuredStem:'other',variants:{
			featured:{debutmont:['first.ogg']},bass:{},drums:{debutmont:['drums.ogg']}}}};
		r.biome='debutmont';
		r.airborne=true;
		r.enabled=false;
		expect(r._variant('featured')).toBeNull();
		expect(r._variant('drums')).toBeNull();
		r.enabled=true;
		expect(r._variant('featured')).toBe('debutmont');
		expect(r._variant('drums')).toBe('debutmont');
	});
	test('source stem presets cannot address vocals or unknown busses',()=>{
		expect(()=>orchestraPreset('debutmont','vocals')).toThrow();
		expect(orchestraPreset('debutmont','bass').length).toBeGreaterThan(0);
		expect(orchestraPreset('no-such-biome','guitar')).toEqual([]);
