});import {jest} from '@jest/globals';
import {EventEmitter} from 'events';
import {
  planFatalCountIn,findOriginalDrumAccent,FatalCrashCountIn,
  FATAL_SYNTHETIC_BEAT_SECONDS,FATAL_DRUM_BEATS,
} from '../../src/systems/music/FatalCrashCountIn.js';
import {AudioSynth} from '../../src/systems/AudioSynth.js';
import {EVT} from '../../src/events.js';
import {defaultSongSelection} from '../../src/systems/music/MusicPlaylist.js';

const param=()=>({value:1,setValueAtTime:jest.fn(),
  linearRampToValueAtTime:jest.fn(),cancelScheduledValues:jest.fn(),
  setTargetAtTime:jest.fn()});
function harness(){
  const sources=[];
  const c={currentTime:11,state:'running',createBufferSource:()=>{
    const src={connect:jest.fn(),stop:jest.fn(),start:jest.fn(),
      buffer:null};sources.push(src);return src;},
    createGain:()=>({gain:param(),connect:jest.fn(),disconnect:jest.fn()})};
  const mono=new Float32Array(48000);
  for(let i=15000;i<16800;i++)mono[i]=.7;
  const buffer={sampleRate:48000,length:mono.length,duration:1,numberOfChannels:1,
    getChannelData:()=>mono};
  const pack={id:'track-A',sampleRate:48000,segments:[
    {startFrame:0,frames:48000},{startFrame:48000,frames:48000}]};
  const cache=new Map([['0/drums',buffer]]);
  const mixer={countInInput:{},recoveryPlan:null,setRecoveryPlan:jest.fn(function(p){this.recoveryPlan=p;return true;}),
    cancelRecoveryPlan:jest.fn(function(){this.recoveryPlan=null;})};
  const scratch={play:jest.fn(()=>.205),cancel:jest.fn()};
  const d={ctx:c,pack,cache,track:{id:'track-A'},packBase:'/music/A',
    clockStart:1,_token:7,started:true,transportPaused:false,
    activeNodes:new Set([{}]),mixer,_loading:null,disposed:false,
    start:jest.fn(),stop:jest.fn(),seekTo:jest.fn()};
  const recovery=new FatalCrashCountIn(c,mixer,scratch);
  return {c,d,mixer,scratch,sources,buffer,pack,recovery};
}

describe('synthetic playback clock is never a verified source pulse',()=>{
  test('time layout is 205ms scratch, 2 silent pulses, 4 genuine drum slots, full band',()=>{
    const p=planFatalCountIn(11);
    expect(p.beatSeconds).toBe(.5);
    expect(p.silenceStart).toBeCloseTo(11.205);
    expect(p.drumsStart).toBeCloseTo(12.205);
    expect(p.beatOnsets).toHaveLength(4);
    expect(p.beatOnsets).toEqual([12.205,12.705,13.205,13.705]);
    expect(p.bandAt).toBeCloseTo(14.205);
    expect(p.verified).toBe(false);
    expect(p.timingKind).toBe('synthetic-unverified');
    expect(FATAL_SYNTHETIC_BEAT_SECONDS).toBe(.5);
    expect(FATAL_DRUM_BEATS).toBe(4);
  });
  test('1 to 3 silent pulses and synthetic tempo differences are testable, not approved grids',()=>{
    for(const silence of [1,2,3]){
      const p=planFatalCountIn(0,{silentBeats:silence,beatSeconds:.375});
      expect(p.silentBeats).toBe(silence);
      expect(p.beatOnsets[1]-p.beatOnsets[0]).toBeCloseTo(.375);
      expect(p.bandAt-p.drumsStart).toBeCloseTo(1.5);
      expect(p.verified).toBe(false);
    }
    expect(planFatalCountIn(3,{timingKind:'verified-source-grid'})).toBeNull();
    expect(planFatalCountIn(3,{beatSeconds:0})).toBeNull();
    expect(planFatalCountIn(3,{silentBeats:4})).toBeNull();
  });
});

describe('actual original decoded drum transient source and same continuous transport',()=>{
  test('find cue from original track pack cache, never create synthetic fake original OGG',()=>{
    const {d,buffer}=harness();
    const cue=findOriginalDrumAccent(d);
    expect(cue.buffer).toBe(buffer);
    expect(cue.source).toBe('original-decoded-ogg-drums');
    expect(cue.excerptSeconds).toBeCloseTo(.14);
    expect(cue.onsetScore).toBeGreaterThan(.015);
    d.cache.clear();
    expect(findOriginalDrumAccent(d)).toBeNull();
  });
  test('four 140ms one-shot drum accents only, not a second song/transport',()=>{
    const {c,d,mixer,scratch,sources,recovery}=harness();
    const result=recovery.start(d);
    expect(result).toMatchObject({active:true,stage:'vinyl-scratch',
      verified:false,trackId:'track-A',scheduledDrumAccents:4,
      clockBasis:'AudioContext.currentTime'});
    expect(scratch.play).toHaveBeenCalledTimes(1);
    expect(scratch.play).toHaveBeenCalledWith('pause');
    expect(mixer.setRecoveryPlan).toHaveBeenCalledTimes(1);
    expect(sources).toHaveLength(4);
    for(let i=0;i<4;i++){
      expect(sources[i].start).toHaveBeenCalledTimes(1);
      expect(sources[i].start.mock.calls[0][0]).toBeCloseTo(result.beatOnsets[i]);
      expect(sources[i].start.mock.calls[0][2]).toBeCloseTo(.14);
    }
    expect(d.start).not.toHaveBeenCalled();
    expect(d.stop).not.toHaveBeenCalled();
    expect(d.seekTo).not.toHaveBeenCalled();
    expect(d.clockStart).toBe(1);
    expect(d._token).toBe(7);
    c.currentTime=result.drumsStart+.1;
    expect(recovery.snapshot()).toMatchObject({active:true,stage:'four-drum-count-in'});
    c.currentTime=result.bandAt+.06;
    expect(recovery.snapshot()).toMatchObject({active:false,stage:'full-band'});
  });
  test('failed/very quiet original sources fail safe, no mix gate and no scratch',()=>{
    const {d,scratch,recovery,mixer}=harness();
    d.cache.clear();
    expect(recovery.start(d)).toBeNull();
    expect(mixer.setRecoveryPlan).not.toHaveBeenCalled();
    expect(scratch.play).not.toHaveBeenCalled();
    expect(d.started).toBe(true);
  });
  test('failed recovery graph scheduling unwinds all gates and preserves continuous recording',()=>{
    const {d,mixer,recovery,scratch}=harness();
    mixer.setRecoveryPlan=jest.fn(plan=>{
      mixer.recoveryPlan=plan;
      throw new Error('simulated WebAudio source recovery parameter failure');
    });
    expect(recovery.start(d)).toBeNull();
    expect(mixer.cancelRecoveryPlan).toHaveBeenCalledTimes(1);
    expect(mixer.recoveryPlan).toBeNull();
    expect(scratch.play).not.toHaveBeenCalled();
    expect(recovery.snapshot()).toEqual({active:false,stage:'idle'});
    expect(d.started).toBe(true);
    expect(d.clockStart).toBe(1);
    expect(d._token).toBe(7);
  });
  test('recovery plan returning false after changing gates cancels its partial state',()=>{
    const {d,mixer,recovery}=harness();
    mixer.setRecoveryPlan=jest.fn(plan=>{mixer.recoveryPlan=plan;return false;});
    expect(recovery.start(d)).toBeNull();
    expect(mixer.cancelRecoveryPlan).toHaveBeenCalledTimes(1);
    expect(mixer.recoveryPlan).toBeNull();
  });

  test('destroy or superseding genuine crash stops exactly four old accents',()=>{
    const {c,d,sources,mixer,recovery}=harness();
    const first=recovery.start(d);
    c.currentTime=first.silenceStart+.01;
    const next=recovery.start(d);
    expect(next.generation).not.toBe(first.generation);
    expect(sources).toHaveLength(8);
    for(const src of sources.slice(0,4))expect(src.stop).toHaveBeenCalled();
    expect(mixer.cancelRecoveryPlan).toHaveBeenCalledTimes(1);
    recovery.cancel();
    expect(mixer.cancelRecoveryPlan).toHaveBeenCalledTimes(2);
    expect(recovery.snapshot().active).toBe(false);
    for(const src of sources.slice(4))expect(src.stop).toHaveBeenCalled();
  });
  test('quiet first segment preloads one later original drum fragment through SAME director cache',async()=>{
    const {d,recovery,buffer}=harness();
    d.cache.set('0/drums',{...buffer,getChannelData:()=>new Float32Array(48000)});
    d._fetchSource=jest.fn(async(info,i,name,token)=>{
      expect(info.pack).toBe(d.pack);
      expect(info.track.id).toBe('track-A');
      expect(name).toBe('drums');expect(token).toBe(7);
      d.cache.set(`${i}/drums`,buffer);return buffer;
    });
    expect(await recovery.prepare(d)).toBe(true);
    expect(d._fetchSource).toHaveBeenCalledTimes(1);
    expect(d._fetchSource.mock.calls[0][1]).toBe(1);
    expect(findOriginalDrumAccent(d).segmentIndex).toBe(1);
  });
});

function eventHarness(){
  const e=new EventEmitter();const a=new AudioSynth({events:e});
  const {c,d,mixer,scratch,recovery}=harness();
  a.ctx=c;a.nodes={musicSrc:{gain:param()},musicBus:{gain:param()},
    master:{gain:param()},musicFilter:{frequency:param()},
    windGain:{gain:param()},windFilter:{frequency:param()},
    gate:{gain:param()},dry:{gain:param()},wet:{gain:param()},staticGain:{gain:param()}};
  a.settings={masterVolume:.9,musicVolume:.8,sfxVolume:.7,
    musicEnabledSongs:defaultSongSelection(),windEnabled:true,windVolume:1};
  a._musicMode='run';a._musicWanted=true;
  a._stemMusic=d;a._fatalCountIn=recovery;a._vinylScratch=scratch;
  a.playSfx=jest.fn();
  d.setMenuMode=jest.fn();d.setBiome=jest.fn();
  d.setBsodDanger=jest.fn();d.setAirborne=jest.fn();
  a._activateStemMusic=jest.fn();
  return {e,a,c,d,mixer,scratch,recovery};
}

describe('EVT.CRASH fatal-only, run lifecycle and manual ownership',()=>{
  test('only authoritative fatal:true plus valid runId can start; negated:false alone is not fatal',()=>{
    const {e,a,scratch,mixer}=eventHarness();
    const invalid=[
      {cause:'legacy',negated:false},
      {cause:'legacy',negated:false,runId:'legacy'},
      {cause:'legacy',negated:false,fatal:false,runId:'old'},
      {cause:'bad',negated:false,fatal:true},
      {cause:'bad',negated:false,fatal:true,runId:''},
      {cause:'bad',negated:false,fatal:true,runId:'   '},
      {cause:'bad',negated:true,fatal:true,runId:'shield'},
    ];
    for(const event of invalid)e.emit(EVT.CRASH,event);
    expect(mixer.setRecoveryPlan).not.toHaveBeenCalled();
    expect(scratch.play).not.toHaveBeenCalled();
    expect(a.getFatalCountInStatus()).toMatchObject({active:false,stage:'idle'});
  });

  test('same-run duplicate never restarts; genuinely new fatal run supersedes recovery',()=>{
    const {e,a,recovery,mixer,c,d}=eventHarness();
    const impact=id=>e.emit(EVT.CRASH,{cause:'bsod',negated:false,fatal:true,runId:id});
    impact('life-1');
    const first=recovery.snapshot();
    expect(first).toMatchObject({active:true,runId:'life-1',scheduledDrumAccents:4});
    e.emit(EVT.RUN_END,{record:{id:'life-1',cause:'crash'}});
    e.emit(EVT.RUN_START,{runId:'life-2',seed:'retry'});
    expect(recovery.snapshot().generation).toBe(first.generation);
    impact('life-1');
    expect(recovery.snapshot().generation).toBe(first.generation);
    c.currentTime+=.4;
    impact('life-2');
    const second=recovery.snapshot();
    expect(second.runId).toBe('life-2');
    expect(second.generation).not.toBe(first.generation);
    expect(mixer.cancelRecoveryPlan).toHaveBeenCalledTimes(1);
    expect(d.clockStart).toBe(1);
    expect(d._token).toBe(7);
  });

  test('negated shield, missing negated, and menu crashes cannot trigger death sequence',()=>{
    const {e,a,scratch,mixer}=eventHarness();
    e.emit(EVT.CRASH,{cause:'hazard',negated:true,fatal:false,runId:'shield-1'});
    e.emit(EVT.CRASH,{cause:'gym-catch',runId:'gym-1'});
    expect(mixer.setRecoveryPlan).not.toHaveBeenCalled();
    a._musicMode='menu';e.emit(EVT.CRASH,{cause:'fatal',negated:false,fatal:true,runId:'menu-1'});
    expect(scratch.play).not.toHaveBeenCalled();
  });
  test('run-end and immediate new run leave music generation and 4 drum slots unchanged',()=>{
    const {e,a,d,c,recovery,mixer}=eventHarness();
    e.emit(EVT.CRASH,{cause:'bsod',negated:false,fatal:true,runId:'fatal-1'});
    const original=recovery.snapshot();
    expect(original).toMatchObject({active:true,scheduledDrumAccents:4});
    e.emit(EVT.RUN_END,{});
    expect(recovery.snapshot().generation).toBe(original.generation);
    expect(mixer.cancelRecoveryPlan).not.toHaveBeenCalled();
    e.emit(EVT.RUN_START,{seed:'new-run'});
    expect(recovery.snapshot().generation).toBe(original.generation);
    expect(d.clockStart).toBe(1);expect(d._token).toBe(7);
    c.currentTime=original.drumsStart+.3;
    expect(a.getBeatTiming()).toMatchObject({trusted:false,
      reason:'fatal-recovery-grid-unverified'});
  });
  test('explicit jukebox intent cancels recovery; muted and user manual pause also override',()=>{
    const {e,a,mixer,recovery}=eventHarness();
    e.emit(EVT.CRASH,{cause:'fatal',negated:false,fatal:true,runId:'fatal-'+(a.__testRunCounter=(a.__testRunCounter||0)+1)});
    a._vinylJukeboxIntent();
    expect(recovery.snapshot().active).toBe(false);
    expect(mixer.cancelRecoveryPlan).toHaveBeenCalledTimes(1);
    a._musicMode='run';e.emit(EVT.CRASH,{cause:'fatal',negated:false,fatal:true,runId:'fatal-'+(a.__testRunCounter=(a.__testRunCounter||0)+1)});
    a._onVinylManualPause({reason:'manual',runId:'X',pauseToken:'X:1'});
    expect(recovery.snapshot().active).toBe(false);
    expect(mixer.cancelRecoveryPlan).toHaveBeenCalledTimes(2);
    a._musicMode='run';a._paused=false;
    e.emit(EVT.CRASH,{cause:'fatal',negated:false,fatal:true,runId:'fatal-'+(a.__testRunCounter=(a.__testRunCounter||0)+1)});
    a.settings.musicVolume=0;a._cancelFatalCountIn();
    expect(recovery.snapshot().active).toBe(false);
  });
});/**
 * W3 — Game Over's two run-starting actions and the biome mask.
 *
 * CC Friday's requirement: "Retry from Game Over must keep the mask of the run being retried."
 *
 * `retry()` set REG.SEED and nothing else. That happens to work today only because nothing clears
 * REG.BIOME_MASK between scenes, so the previous run's value is still sitting in the registry — it is
 * correct by accident, and it breaks the moment a scene resets the registry or `newSeed()` runs first.
 *
 * `newSeed()` is the same bug with a visible consequence: it sets a fresh seed but leaves the previous
 * run's mask behind, so pressing NEW SEED after a Daily run (mask 8, date-derived) starts an ordinary
 * run at mask 8 — a world the player never chose, and one that is not the Daily any more either.
 *
 * These pin the actions themselves, called on the prototype, not a re-implementation.
 */
import { jest } from '@jest/globals';
import { shareableSeed } from '../../src/ui/Format.js';
jest.unstable_mockModule('phaser', () => ({ default: { Scene: class {}, GameObjects: new Proxy({}, { get: () => class {} }) } }));
jest.unstable_mockModule('../../src/data/index.js', () => ({ content: {}, loadContent: () => ({}) }));
const { GameOverScene } = await import('../../src/scenes/GameOverScene.js');
const { REG, SCENES } = await import('../../src/constants.js');

const DEFS = {
  debutmont: { id: 'debutmont', bit: 1 },
  glacier: { id: 'glacier', bit: 2 },
  pyramid: { id: 'pyramid', bit: 4 },
};

/** A capped profile with every batch-1 signature unlocked and none switched OFF (the default, issue #65). */
const capped = (over = {}) => ({
  v: 1, biomeOff: 0, level: 30,
  pendingBiomes: ['debutmont', 'glacier', 'pyramid'],
  unlocked: { biomes: [], cosmetics: [], boosts: {} },
  ...over,
});

/**
 * @param {{rec?:Object, profile?:Object, mask?:number}} o
 */
function scene(o = {}) {
  const values = new Map([[REG.CONTENT, { biomes: DEFS }]]);
  if (o.profile) values.set(REG.PROFILE, o.profile);
  if (o.mask !== undefined) values.set(REG.BIOME_MASK, o.mask);
  const ctx = {
    registry: { get: (k) => values.get(k), set: (k, v) => values.set(k, v) },
    rec: o.rec || { seed: 'alpha', id: 'r1' },
    scene: { start: jest.fn() },
    leaving: false,
    pulse: null,
    _commitPending() {},
  };
  return { ctx, values };
}

describe('RETRY keeps the mask of the run being retried', () => {
  test('a mask-16 run retries at mask 16, not at the profile mask', () => {
    // The run's own mask wins over the profile: the player picked this world (or the Daily did) and
    // asked to try it again, not to change it.
    const { ctx, values } = scene({ mask: 16, profile: capped({ biomeOff: 2 }), rec: { seed: 'alpha', id: 'r1', biomeMask: 16 } });
    GameOverScene.prototype.retry.call(ctx);
    expect(values.get(REG.BIOME_MASK)).toBe(16);
    expect(values.get(REG.SEED)).toBe('alpha');
    expect(ctx.scene.start).toHaveBeenCalledWith(SCENES.RUN);
  });

  test('retry sets the mask explicitly, so it does not depend on registry leftovers', () => {
    // Start with NO mask in the registry at all: nothing to accidentally inherit. A run whose record
    // says mask 2 must still retry at mask 2.
    const { ctx, values } = scene({ profile: capped(), rec: { seed: 'alpha', id: 'r1', biomeMask: 2 } });
    GameOverScene.prototype.retry.call(ctx);
    expect(values.get(REG.BIOME_MASK)).toBe(2);
  });

  test('a mask-0 run retries at 0 even when the profile has signatures enabled', () => {
    // The inverse mistake: falling back to the profile mask would silently switch a clean run into a
    // biome run, so the retry would not be the same run.
    const { ctx, values } = scene({ profile: capped(), rec: { seed: 'alpha', id: 'r1', biomeMask: 0 } });
    GameOverScene.prototype.retry.call(ctx);
    expect(values.get(REG.BIOME_MASK)).toBe(0);
  });

  test('a pre-W3 record with no mask retries at 0', () => {
    const { ctx, values } = scene({ profile: capped(), rec: { seed: 'alpha', id: 'r1' } });
    GameOverScene.prototype.retry.call(ctx);
    expect(values.get(REG.BIOME_MASK)).toBe(0);
  });
});

describe('NEW SEED drops the previous run mask', () => {
  test('NEW SEED after a Daily run does not inherit the Daily mask', () => {
    // The bug this pins: newSeed() set only REG.SEED, so the Daily's date-derived mask stayed in the
    // registry and an ordinary new-seed run was played in it.
    const { ctx, values } = scene({ mask: 8, profile: capped() });
    GameOverScene.prototype.newSeed.call(ctx);
    // The new default: every unlocked biome ON (glacier|pyramid), the base bit left out.
    expect(values.get(REG.BIOME_MASK)).toBe(6);
  });

  test('NEW SEED with every biome explicitly OFF runs at mask 0', () => {
    const { ctx, values } = scene({ mask: 8, profile: capped({ biomeOff: 6 }) });
    GameOverScene.prototype.newSeed.call(ctx);
    expect(values.get(REG.BIOME_MASK)).toBe(0);
  });

  test('NEW SEED never turns on biomes the profile has not unlocked', () => {
    const { ctx, values } = scene({ mask: 8, profile: capped({ biomeMask: 7, pendingBiomes: ['debutmont'] }) });
    GameOverScene.prototype.newSeed.call(ctx);
    expect(values.get(REG.BIOME_MASK)).toBe(0);
  });
});

describe('share seed: the panel and the clipboard cannot disagree', () => {
  // Luna's round-2 finding: the panel rendered `seed@mask` while COPY put the bare seed on the
  // clipboard, so copying a share seed silently dropped the player into a different world.
  test('a mask-31 run shares its mask', () => {
    expect(shareableSeed({ seed: 'alpha', biomeMask: 31 })).toBe('alpha@31');
  });

  test('a mask-0 run shares a bare seed, exactly as before W3', () => {
    expect(shareableSeed({ seed: 'alpha', biomeMask: 0 })).toBe('alpha');
    expect(shareableSeed({ seed: 'alpha' })).toBe('alpha');
  });

  test('an empty or missing seed shares nothing rather than "@0"', () => {
    expect(shareableSeed({ seed: '', biomeMask: 5 })).toBe('');
    expect(shareableSeed(null)).toBe('');
  });
});/**
 * Luna W3 audit probe — is every identifier Game Over's build path uses actually bound?
 *
 * Round 2 verified `shareableSeed()`'s BEHAVIOUR (`alpha@31`, `alpha`, `''`) and stopped there. The
 * scene that CALLS it is a different question: 678 green tests never ran this line, so nothing in the
 * suite would have noticed that the module never imported the function it calls.
 *
 * `_buildStats()` renders the SHARE SEED row and runs unconditionally from `create()` for every
 * finished run. The assertion here is deliberately narrow — a ReferenceError is the defect class
 * under test. Stub artefacts (a Phaser method this fake renderer does not model) are reported but do
 * not fail the test, because they say nothing about Game Over's own code.
 */
import { jest } from '@jest/globals';

/** Widgets chain setters in their constructors; unknown members return `this` so they still build. */
const chainable = (obj, list) => new Proxy(obj, {
  get(t, k) {
    if (k === 'then') return undefined;
    if (k === 'list') return list;
    if (k in t) return t[k];
    if (typeof k !== 'string') return undefined;
    return () => obj;
  },
});
class Container {
  constructor() { return chainable(this, []); }
  add() { return this; }
  remove() { return this; }
}

jest.unstable_mockModule('phaser', () => ({
  default: { Scene: class {}, GameObjects: new Proxy({}, { get: () => Container }) },
}));
jest.unstable_mockModule('../../src/data/index.js', () => ({ content: {}, loadContent: () => ({}) }));

const { GameOverScene } = await import('../../src/scenes/GameOverScene.js');

const fakeTheme = {
  pal: new Proxy({}, { get: () => 0xffffff }),
  css: new Proxy({}, { get: () => '#ffffff' }),
  color: () => 0xffffff,
  bind: (fn) => { try { fn({}, null); } catch (e) { /* painting is not under test */ } return () => {}; },
  refresh: () => {},
  destroy: () => {},
};

const makeScene = (rec) => {
  const s = Object.create(GameOverScene.prototype);
  Object.assign(s, {
    scene: { start: () => {}, stop: () => {} },
    add: new Proxy({}, { get: () => () => chainable({}, []) }),
    tweens: { addCounter: () => chainable({}, []), add: () => chainable({}, []) },
    time: { delayedCall: () => {} },
    input: { on: () => {}, keyboard: null },
    registry: { get: () => undefined, set: () => {} },
    events: { on: () => {}, off: () => {} },
    cameras: { main: chainable({}, []) },
    sys: { game: chainable({}, []), settings: { data: {} } },
    rec,
    theme: fakeTheme,
    alive: true,
  });
  return s;
};

/** Run the build path, separating real scope errors from fake-renderer gaps. */
function build(rec) {
  const s = makeScene(rec);
  try {
    s._buildStats();
    return { ok: true };
  } catch (e) {
    if (e instanceof ReferenceError) return { ok: false, scope: true, err: e };
    return { ok: false, scope: false, err: e };
  }
}

describe("Game Over's build path has every identifier bound", () => {
  test('mask-31 run: no unresolved identifier while rendering SHARE SEED', () => {
    const r = build({ seed: 'alpha', biomeMask: 31, score: 100, ledgerHash: 'deadbeef', distanceM: 100 });
    if (!r.ok && !r.scope) {
      // Not a scope error: this fake renderer does not model everything Button/NeonText touches.
      // Report it so the evidence is honest, but it is not the defect under test.
      console.log(`  (renderer stub gap, not a defect: ${r.err.constructor.name}: ${r.err.message})`);
    }
    expect(r.scope ? r.err.message : null).toBeNull();
  });

  test('mask-0 run: same path, same binding', () => {
    // The mask-0 branch takes the identical call, so an unbound identifier breaks legacy runs too —
    // this is not a "only biome players are affected" defect.
    const r = build({ seed: 'legacy', biomeMask: 0, score: 1, ledgerHash: 'x', distanceM: 1 });
    if (!r.ok && !r.scope) {
      console.log(`  (renderer stub gap, not a defect: ${r.err.constructor.name}: ${r.err.message})`);
    }
    expect(r.scope ? r.err.message : null).toBeNull();
  });
});/**
 * F-LEAD-2: Game Over's DISTANCE BEST line for a clean run must ignore boosted (modded) runs.
 *
 * Ported from the audit/fairness reviewer's harness: the real GameOverScene._loadBest runs on a context with
 * a real in-memory SaveStore, with Phaser and the rendering widgets replaced by inert fakes. NeonText records
 * every string it is given, so the test reads what the player would see.
 *
 * Harness fix: the original deep() Proxy's set trap wrote `t[k] = v` on the shared target, which put every
 * instance field on the mocked Phaser.Scene prototype and leaked state between tests. It uses Reflect.set
 * with the receiver now.
 */
import { jest } from '@jest/globals';
import { loadContent } from './_helpers.js';

// ---------------------------------------------------------------- inert fakes

/** Anything-goes stand-in: every property is another stand-in, every call/construct returns one. */
function deep() {
  const fn = function () {};
  return new Proxy(fn, {
    get(t, k) {
      if (k === 'then') return undefined; // or `await` / Promise.resolve() would hang on it
      if (k === Symbol.toPrimitive) return () => 0;
      if (k === Symbol.iterator) return function* empty() {};
      if (k === 'length') return 0;
      if (typeof k === 'symbol') return undefined;
      if (Object.prototype.hasOwnProperty.call(t, k) && k !== 'name' && k !== 'prototype') return t[k];
      return deep();
    },
    set(t, k, v, receiver) { return Reflect.set(t, k, v, receiver); },
    apply() { return deep(); },
    construct() { return deep(); },
  });
}
const markers = [];
class FakeMarker { constructor(scene, pal, x, m) { markers.push(m); } update() {} markPassed() {} destroy() {} }
class Inert { constructor() { return deep(); } }

/** NeonText records every string it is built with or set to, so a test can read what the player sees. */
const texts = [];
class FakeNeonText {
  constructor(scene, theme, x, y, text) { this.text = text; texts.push(text); }
  setText(t) { this.text = t; texts.push(t); return this; }
  setAlpha() { return this; }
  setColorKey() { return this; }
  setVisible() { return this; }
  setDepth() { return this; }
  destroy() {}
}
let menuItems = null;
class FakeMenuList { constructor(scene, theme, o) { menuItems = o.items; this.rows = []; } }
class FakePanel { add() { return this; } setVisible() { return this; } destroy() {} setTitle() { return this; } setColorKey() { return this; } }

