// ================================================================== UI-3: mission toasts at RUN_END

describe('UI-3: mission toasts emitted at RUN_END finish before RunScene stops the HUD', () => {
  // RunScene stops the HUD CRASH_TO_GAMEOVER_MS after the crash, and RUN_END is emitted at the crash.
  const HUD_STOP_MS = Math.min(950, TIMING.crashToGameOverMs);

  /** UIScene stub with the real strip queue; records every strip text it shows. */
  const hudWith = (completed, queued = []) => {
    const s = makeScene(UIScene.prototype, { [REG.LAST_AWARDS]: { missions: { completed } } });
    const shown = [];
    const c = { visible: false, x: 0, setVisible(v) { this.visible = v; return this; }, setX(x) { this.x = x; return this; } };
    Object.assign(s, {
      stripQueue: queued.map((text) => ({ text, key: 'cyan' })), stripBusy: false, missionToastsThisRun: new Set(), stripC: c,
      stripT: { setText(t) { shown.push(t); return this; }, setColorKey() { return this; } }, _paintStrip() {},
      comboInfo: { setText() { return this; } }, _setPending() {},
    });
    return { s, shown };
  };
  /** Walk the strip queue on the tween clock: each job's slide-out tween completes at delay + duration. */
  const run = (s) => {
    let clock = 0;
    const finished = [];
    for (let guard = 0; guard < 10; guard++) {
      const out = s.__tweens.find((tw) => !tw.done && tw.cfg.onComplete);
      if (!out) break;
      out.done = true;
      clock += (out.cfg.delay || 0) + out.cfg.duration;
      finished.push(clock);
      out.cfg.onComplete();
    }
    return finished;
  };

  test('two completions at RUN_END collapse into one strip that names both and their XP, and finishes in time', () => {
    const { s, shown } = hudWith([{ id: 'm1', title: 'Grab 15 shards', xp: 60 }, { id: 'm2', title: 'Land 3 flips', xp: 40 }]);
    s.onRunEnd();
    const finished = run(s);
    expect(shown).toEqual(['2 MISSIONS DONE  +100 XP']);
    expect(finished.length).toBe(1);
    // A frame of margin (the HUD stop is checked once per frame in RunScene.update).
    expect(finished[0]).toBeLessThanOrEqual(HUD_STOP_MS - 17);
  });

  test('one completion at RUN_END shows its title and finishes in time', () => {
    const { s, shown } = hudWith([{ id: 'm1', title: 'Grab 15 shards', xp: 60 }]);
    s.onRunEnd();
    const finished = run(s);
    expect(shown).toEqual(['GRAB 15 SHARDS DONE  +60 XP']);
    expect(finished[0]).toBeLessThanOrEqual(HUD_STOP_MS - 17);
  });

  test('missions already toasted mid-run are not counted again', () => {
    const { s, shown } = hudWith([{ id: 'm1', title: 'Grab 15 shards', xp: 60 }, { id: 'm2', title: 'Land 3 flips', xp: 40 }]);
    s.missionToastsThisRun.add('m1');
    s.onRunEnd();
    run(s);
    expect(shown).toEqual(['LAND 3 FLIPS DONE  +40 XP']);
  });

  test('the run-end toast goes ahead of stale strips still waiting in the queue', () => {
    const { s, shown } = hudWith([{ id: 'm1', title: 'Grab 15 shards', xp: 60 }], ['SECTOR 4']);
    s.stripBusy = true; // something is mid-slide; SECTOR 4 is waiting behind it
    s.onRunEnd();
    expect(s.stripQueue[0].text).toBe('GRAB 15 SHARDS DONE  +60 XP');
    expect(shown).toEqual([]);
  });

  test('mid-run toasts still waiting in the queue at RUN_END are folded into the run-end strip', () => {
    // Real order: something is mid-slide, two missions complete just before the crash (queued behind it),
    // then RUN_END arrives with the same two in the awards.
    const done = [{ id: 'm1', title: 'Grab 15 shards', xp: 60 }, { id: 'm2', title: 'Land 3 flips', xp: 40 }];
    const { s } = hudWith(done, ['SECTOR 4']);
    s.stripBusy = true;
    for (const c of done) s.onMissionCompleted(c);
    expect(s.stripQueue.map((j) => j.text)).toEqual(['SECTOR 4', 'GRAB 15 SHARDS DONE  +60 XP', 'LAND 3 FLIPS DONE  +40 XP']);
    s.onRunEnd();
    expect(s.stripQueue.map((j) => j.text)).toEqual(['2 MISSIONS DONE  +100 XP', 'SECTOR 4']);
  });

  test('a mid-run toast keeps the normal, slower timing', () => {
    const { s } = hudWith([]);
    s.onMissionCompleted({ id: 'm9', title: 'Reach 500 m in one run', xp: 60 });
    expect(run(s)).toEqual([940]);
  });
});

// ================================================================== F4 fit: the Game Over shop pages too

describe('F4 fit: the Game Over shop popup pages by slot', () => {
  const slotIds = (g) => g.shopView.menu.items.filter((i) => i.rowKind === 'item').map((i) => i.id);

  // Marvin decision 7 (2026-11-14) overturned "retry always wins" in the open shop: once the player has moved
  // the cursor, confirm acts on the highlighted row (here the page row, so it turns the page) and Space /
  // pad RB ('retry') retry. This test used to end with confirm closing the shop and retrying.
  test('left/right reach the popup and turn its page; then confirm turns it too, and retry still retries', () => {
    const g = gameOverHost();
    g._openShop();
    expect(slotIds(g).every((id) => id.startsWith('trail-'))).toBe(true);
    g._onAction('right');
    expect(slotIds(g).length).toBeGreaterThan(0);
    expect(slotIds(g).every((id) => /glow/.test(id))).toBe(true);
    g._onAction('left');
    g._onAction('left');
    expect(slotIds(g).every((id) => id.startsWith('theme-'))).toBe(true);
    expect(g.shopOpen).toBe(true);
    g._onAction('confirm');
    expect(slotIds(g).every((id) => id.startsWith('trail-'))).toBe(true);
    expect(g.retry).not.toHaveBeenCalled();
    expect(g.shopOpen).toBe(true);
    g._onAction('retry');
    expect(g.retry).toHaveBeenCalledTimes(1);
    expect(g.shopOpen).toBe(false);
  });

  // Decision 7, end to end through the REAL ShopView: Enter buys the highlighted row with the same rules as
  // Title -> Profile -> Shop (buy + equip in one save, then confirm on EQUIPPED takes it off).
  test('in a shop opened with B, Enter buys and equips the highlighted row, and Enter again unequips it', () => {
    const g = gameOverHost();
    g._onAction('shop');
    expect(g.shopOpen).toBe(true);
    const m = g.shopView.menu;
    const target = m.items.findIndex((i) => i.rowKind === 'item' && !i.disabled && /^\d+$/.test(String(i.sub)));
    expect(target).toBeGreaterThan(-1);
    const id = m.items[target].id;
    while (g.shopView.menu.selected < target) g._onAction('down');
    expect(g.shopView.menu.items[g.shopView.menu.selected].id).toBe(id);
    const bankBefore = g.registry.get(REG.PROFILE).bank;
    g._onAction('confirm');
    const after = g.registry.get(REG.PROFILE);
    expect(after.unlocked.cosmetics).toContain(id);
    expect(after.bank).toBeLessThan(bankBefore);
    expect(Object.values(after.equipped || {}).some((v) => v === id || id.endsWith(`-${v}`))).toBe(true);
    expect(g.retry).not.toHaveBeenCalled();
    expect(g.shopOpen).toBe(true);
    // The highlighted row is still that item (paging and focus intact), and confirm on EQUIPPED takes it off.
    expect(g.shopView.menu.items[g.shopView.menu.selected].id).toBe(id);
    g._onAction('confirm');
    const off = g.registry.get(REG.PROFILE);
    expect(Object.values(off.equipped || {}).some((v) => v === id || id.endsWith(`-${v}`))).toBe(false);
    expect(off.bank).toBe(after.bank);
  });

  test('a click on the page row turns the page and stays inside the popup', () => {
    const g = gameOverHost();
    g._openShop();
    const m = g.shopView.menu;
    const idx = m.items.findIndex((i) => i.rowKind === 'page');
    m.rows[idx].zone.emit('pointerdown', {}, 10);
    expect(slotIds(g).every((id) => /glow/.test(id))).toBe(true);
    expect(g.retry).not.toHaveBeenCalled();
  });

  test('every page of the popup keeps its panel on screen and inside the dim', () => {
    const g = gameOverHost();
    g._openShop();
    for (let p = 0; p < 4; p++) {
      const pn = g.shopView.panel;
      expect(pn.y + g.shopView.h).toBeLessThanOrEqual(GAME_HEIGHT);
      expect(pn.x + g.shopView.w).toBeLessThanOrEqual(GAME_WIDTH);
      g._onAction('right');
    }
  });
});/**
 * W4 — Game Over initials-entry save/skip keeps a boosted run on the MODDED board.
 *
 * saveEntry() previously queried getLeaderboard(10) and called _showBoard(id) without passing
 * `modded`, so a boosted run that qualified for NEW MODDED TOP 10! flipped the panel to
 * "LEDGER // YOU ARE ON THE BOARD" and queried the clean board as soon as initials were saved.
 * skipEntry() likewise omitted `modded`, flipping the panel title to "LEDGER // TOP 10".
 */
import { jest } from '@jest/globals';

jest.unstable_mockModule('phaser', () => ({ default: { Scene: class {}, GameObjects: new Proxy({}, { get: () => class {} }) } }));
jest.unstable_mockModule('../../src/data/index.js', () => ({ content: {}, loadContent: () => ({}) }));
const { GameOverScene } = await import('../../src/scenes/GameOverScene.js');
const { REG } = await import('../../src/constants.js');

function makeOver(rec, store) {
  let title = '';
  const over = Object.create(GameOverScene.prototype);
  Object.assign(over, {
    rec,
    alive: true,
    leaving: false,
    saved: false,
    entry: { destroy: () => {} },
    rows: [],
    board: { setVisible: jest.fn(), setEntries: jest.fn() },
    right: {
      setColorKey: jest.fn(() => over.right),
      setTitle: jest.fn((t) => { title = t; return over.right; }),
    },
    registry: { get: (k) => (k === REG.SAVE_STORE ? store : undefined) },
    _leaveEntry: jest.fn(() => { over.entry = null; }),
    _persist: jest.fn(async () => true),
  });
  return { over, getTitle: () => title };
}

describe('GameOverScene saveEntry / skipEntry preserve modded board identity', () => {
  test('saveEntry on a modded run queries the modded board and titles MODDED', async () => {
    const store = {
      getLeaderboard: jest.fn(async () => []),
      getModdedLeaderboard: jest.fn(async () => [{ id: 'm1', score: 900, modded: true, initials: 'MRV' }]),
    };
    const { over, getTitle } = makeOver({ id: 'm1', score: 900, modded: true }, store);
    await over.saveEntry('MRV');
    expect(store.getModdedLeaderboard).toHaveBeenCalledWith(10);
    expect(store.getLeaderboard).not.toHaveBeenCalled();
    expect(getTitle()).toBe('MODDED // YOU ARE ON THE BOARD');
    expect(over.modded).toBe(true);
  });

  test('skipEntry on a modded run keeps the MODDED board title', () => {
    const { over, getTitle } = makeOver({ id: 'm2', score: 900, modded: true }, {});
    over.skipEntry();
    expect(getTitle()).toBe('MODDED // TOP 10');
    expect(over.modded).toBe(true);
  });

  test('saveEntry on a clean run still queries the clean board and titles LEDGER', async () => {
    const store = {
      getLeaderboard: jest.fn(async () => [{ id: 'c1', score: 900, modded: false, initials: 'MRV' }]),
      getModdedLeaderboard: jest.fn(async () => []),
    };
    const { over, getTitle } = makeOver({ id: 'c1', score: 900, modded: false }, store);
    await over.saveEntry('MRV');
    expect(store.getLeaderboard).toHaveBeenCalledWith(10);
    expect(store.getModdedLeaderboard).not.toHaveBeenCalled();
    expect(getTitle()).toBe('LEDGER // YOU ARE ON THE BOARD');
    expect(over.modded).toBe(false);
  });
});

test('a session-only record is not presented as a durable leaderboard save', () => {
  const {over,getTitle}=makeOver({id:'local',score:400}, {
    getRunPersistence:()=> 'session-only',
  });
  over._showBoard('local',false);
  expect(getTitle()).toBe('LEDGER // SESSION ONLY');
});

test('pending save status updates to the actual settled result, not a false success', async () => {
  let settle;
  const {over,getTitle}=makeOver({id:'local',score:400}, {
    getRunPersistence:()=> 'pending',
    whenRunSettled:()=>new Promise(resolve=>{settle=resolve;}),
  });
  over.entry=null;
  over._showBoard('local',false);
  expect(getTitle()).toBe('LEDGER // SAVING');
  settle('session-only');
  await Promise.resolve();
  expect(getTitle()).toBe('LEDGER // SESSION ONLY');
});/**
 * Marvin decision 7 (2026-11-14): "Enter purchases the clearly selected item in the Game Over shop."
 *
 * The contract, driven through the scene's real _openShop / _onAction / _closeShop on a stub context (the
 * ShopView is faked, so what is asserted is WHO gets the confirm; ShopView's own buy/equip/unequip and paging
 * rules are the Title -> Profile -> Shop ones and are tested in views-navigation / shop-paging):
 *   - an ARMED shop hands Enter / pad A ('confirm') to the ShopView: buy, equip, unequip or turn the page on
 *     the highlighted row;
 *   - Space / pad RB ('retry') close the shop and retry from anywhere, in one press;
 *   - a shop the player asked for (B / LB) is armed at once;
 *   - an UNREQUESTED autoprompt shop arms after SHOP_ARM_MS, or as soon as the player moves its cursor.
 *     Before that, 'confirm' keeps today's close-and-retry, so an Enter already on its way when the popup
 *     appears restarts the run instead of being swallowed (pillar 3: Game Over accepts retry from frame one);
 *   - the footer says BUY / RETRY only once the shop is armed, above the dim, and is restored on close.
 */
import { jest } from '@jest/globals';

const views = [];
class FakeShopView {
  constructor(scene, theme, o) { this.o = o; this.actions = []; this.destroyed = false; views.push(this); }
  handleAction(a) { this.actions.push(a); return true; }
  destroy() { this.destroyed = true; }
}
jest.unstable_mockModule('phaser', () => ({ default: { Scene: class {}, GameObjects: new Proxy({}, { get: () => class {} }) } }));
jest.unstable_mockModule('../../src/data/index.js', () => ({ content: {}, loadContent: () => ({}) }));
jest.unstable_mockModule('../../src/ui/Views.js', () => ({ ShopView: FakeShopView }));
const { GameOverScene, SHOP_ARM_MS, SHOP_FOOTER } = await import('../../src/scenes/GameOverScene.js');
const { REG, GAME_WIDTH, GAME_HEIGHT } = await import('../../src/constants.js');
const { measureText } = await import('../../src/ui/PixelFont.js');
const { SHOP_PANEL } = await import('../../src/ui/ShopLayout.js');

const proto = GameOverScene.prototype;
const RETRY_FOOTER = 'SPACE / ENTER / A / TAP = RETRY SAME SEED';

const rich = () => ({ v: 1, level: 2, bank: 200, xp: 0, unlocked: { biomes: [], cosmetics: [], boosts: {} }, equipped: {}, boosts: {} });

function scene(o = {}) {
  const values = new Map();
  values.set(REG.PROFILE, rich());
  values.set(REG.LAST_AWARDS, { xp: { total: 10, parts: [] }, shopAutoprompt: Boolean(o.prompt) });
  const timers = [];
  const ctx = {
    alive: true, leaving: false, entry: null, shopOpen: false, shopView: null, shopHint: null, shopTimer: null,
    shopPending: false, shopDim: null,
    theme: { pal: {}, bind: () => () => {} },
    registry: { get: (k) => values.get(k), set: (k, v) => values.set(k, v) },
    time: {
      delayedCall: (ms, fn) => {
        const t = { ms, fn, removed: false, remove() { this.removed = true; return this; } };
        timers.push(t);
        return t;
      },
    },
    add: {
      rectangle: () => {
        const r = { destroyed: false, setOrigin() { return r; }, setDepth(d) { r.depth = d; return r; }, setInteractive() { return r; }, destroy() { r.destroyed = true; } };
        return r;
      },
    },
    footer: { text: RETRY_FOOTER, depth: 0, setText(t) { this.text = t; return this; }, setDepth(d) { this.depth = d; return this; } },
    _buildShopHint() { this.shopHint = { destroy() {} }; },
    retry: jest.fn(function retry() { this.leaving = true; }),
    newSeed: jest.fn(),
    toTitle: jest.fn(),
    skipEntry: jest.fn(),
  };
  for (const k of ['_openShop', '_closeShop', '_onAction', '_cancelShopAutoprompt', '_resumeShopAutoprompt',
    '_buildShopAccess', '_anythingAffordable', '_hideShopHint', '_armShop']) ctx[k] = proto[k];
  ctx.timers = timers;
  return ctx;
}

/** Fire the oldest pending delayed call. */
function fire(ctx, ms) {
  const t = ctx.timers.find((x) => !x.removed && (ms === undefined || x.ms === ms));
  if (!t) return false;
  t.removed = true;
  t.fn();
  return true;
}

/** Game Over with the autoprompt fired (an unrequested shop). */
function autoprompted() {
  const ctx = scene({ prompt: true });
  ctx._buildShopAccess();
  fire(ctx); // SHOP_PROMPT_MS
  expect(ctx.shopOpen).toBe(true);
  return ctx;
}

beforeEach(() => { views.length = 0; });

describe('Enter / pad A buy in a shop the player asked for', () => {
  test('B opens it armed, and confirm reaches the shop instead of retrying', () => {
    const ctx = scene();
    ctx._onAction('shop');
    expect(ctx.shopOpen).toBe(true);
    expect(ctx.shopArmed).toBe(true);
    ctx._onAction('confirm');
    expect(views[0].actions).toEqual(['confirm']);
    expect(ctx.retry).not.toHaveBeenCalled();
    expect(ctx.shopOpen).toBe(true);
  });

  test('cursor movement and paging still belong to the shop', () => {
    const ctx = scene();
    ctx._onAction('shop');
    for (const a of ['down', 'down', 'left', 'right', 'confirm']) ctx._onAction(a);
    expect(views[0].actions).toEqual(['down', 'down', 'left', 'right', 'confirm']);
  });

  test('Space / pad RB (retry) close the shop and retry in one press, and the shop never sees it', () => {
    const ctx = scene();
    ctx._onAction('shop');
    ctx._onAction('retry');
    expect(ctx.retry).toHaveBeenCalledTimes(1);
    expect(ctx.shopOpen).toBe(false);
    expect(views[0].destroyed).toBe(true);
    expect(views[0].actions).toEqual([]);
    // The 'confirm' MenuInput sends right after Space's 'retry' does nothing: the scene is already leaving.
    ctx._onAction('confirm');
    expect(views[0].actions).toEqual([]);
    expect(ctx.retry).toHaveBeenCalledTimes(1);
  });

  test('Esc / pad B close the shop back to Game Over; N / pad X / Y still start a new seed', () => {
    const a = scene();
    a._onAction('shop');
    a._onAction('cancel');
    expect(a.shopOpen).toBe(false);
    expect(a.retry).not.toHaveBeenCalled();
    const b = scene();
    b._onAction('shop');
    b._onAction('alt');
    expect(b.newSeed).toHaveBeenCalledTimes(1);
  });
});

describe('pillar 3: an unrequested autoprompt shop does not swallow an early Enter', () => {
  test('the arm delay is a human reaction time, not zero and not long', () => {
    expect(SHOP_ARM_MS).toBeGreaterThanOrEqual(300);
    expect(SHOP_ARM_MS).toBeLessThanOrEqual(700);
    const ctx = autoprompted();
    expect(ctx.timers.filter((t) => !t.removed).map((t) => t.ms)).toEqual([SHOP_ARM_MS]);
  });

  test('confirm in its first frames closes it and retries; the shop never gets it', () => {
    const ctx = autoprompted();
    expect(ctx.shopArmed).toBe(false);
    ctx._onAction('confirm');
    expect(ctx.retry).toHaveBeenCalledTimes(1);
    expect(ctx.shopOpen).toBe(false);
    expect(views[0].actions).toEqual([]);
  });

  test('once armed, confirm buys the highlighted row', () => {
    const ctx = autoprompted();
    fire(ctx, SHOP_ARM_MS);
    expect(ctx.shopArmed).toBe(true);
    ctx._onAction('confirm');
    expect(views[0].actions).toEqual(['confirm']);
    expect(ctx.retry).not.toHaveBeenCalled();
  });

  test('moving the cursor arms it at once: the player chose that row', () => {
    const ctx = autoprompted();
    ctx._onAction('down');
    expect(ctx.shopArmed).toBe(true);
    ctx._onAction('confirm');
    expect(views[0].actions).toEqual(['down', 'confirm']);
    expect(ctx.retry).not.toHaveBeenCalled();
  });

  test('Space retries even before it is armed', () => {
    const ctx = autoprompted();
    ctx._onAction('retry');
    expect(ctx.retry).toHaveBeenCalledTimes(1);
    expect(views[0].actions).toEqual([]);
  });

  test('the shop that opens after initials entry is unrequested too', () => {
    const ctx = scene({ prompt: true });
    ctx._buildShopAccess();
    ctx.entry = { handleAction: jest.fn() };
    fire(ctx);
    ctx.entry = null;
    ctx._resumeShopAutoprompt();
    fire(ctx);
    expect(ctx.shopOpen).toBe(true);
    expect(ctx.shopArmed).toBe(false);
    ctx._onAction('confirm');
    expect(ctx.retry).toHaveBeenCalledTimes(1);
  });

  test('closing the shop drops the arm timer, and a late arm callback changes nothing', () => {
    const ctx = autoprompted();
    const arm = ctx.timers.find((t) => !t.removed && t.ms === SHOP_ARM_MS);
    ctx._onAction('cancel');
    expect(arm.removed).toBe(true);
    arm.fn();
    expect(ctx.shopArmed).toBe(false);
    expect(ctx.footer.text).toBe(RETRY_FOOTER);
  });
});

describe('with the shop closed, Game Over is unchanged', () => {
  test('confirm and retry both retry, from the first frame', () => {
    const a = scene();
    a._onAction('confirm');
    expect(a.retry).toHaveBeenCalledTimes(1);
    const b = scene();
    b._onAction('retry');
    expect(b.retry).toHaveBeenCalledTimes(1);
  });

  test('pad RB during initials entry saves and retries, like Space', () => {
    const ctx = scene();
    ctx.entry = { handleAction: jest.fn() };
    ctx._onAction('retry');
    expect(ctx.retry).toHaveBeenCalledTimes(1);
    expect(ctx.entry.handleAction).not.toHaveBeenCalled();
  });
});

describe('the on-screen hint', () => {
  test('armed: the footer names BUY and RETRY keys and sits above the dim; close restores it', () => {
    const ctx = scene();
    ctx._onAction('shop');
    expect(ctx.footer.text).toBe(SHOP_FOOTER);
    expect(SHOP_FOOTER).toMatch(/ENTER \/ A = BUY/);
    expect(SHOP_FOOTER).toMatch(/SPACE \/ RB = RETRY/);
    expect(ctx.footer.depth).toBeGreaterThan(400); // the dim is at 400
    expect(ctx.shopHint).toBeNull(); // "SHOP: B / LB" would read as "open the shop" while it is open
    ctx._onAction('cancel');
    expect(ctx.footer.text).toBe(RETRY_FOOTER);
    expect(ctx.footer.depth).toBe(0);
    expect(ctx.shopArmed).toBe(false); // a closed shop is never left armed
  });

  test('unarmed: the footer still promises retry, which is what Enter does then', () => {
    const ctx = autoprompted();
    expect(ctx.footer.text).toBe(RETRY_FOOTER);
    fire(ctx, SHOP_ARM_MS);
    expect(ctx.footer.text).toBe(SHOP_FOOTER);
  });

  test('the shop footer fits 480x270 and clears the shop panel', () => {
    const w = measureText(SHOP_FOOTER);
    const left = Math.round(GAME_WIDTH / 2) - w / 2;
    expect(left).toBeGreaterThanOrEqual(16);
    expect(left + w).toBeLessThanOrEqual(GAME_WIDTH - 16);
    // ShopView sits at y 22 with SHOP_PANEL.h; the footer ink is centred on GAME_HEIGHT - 5, 8 px tall.
    expect(22 + SHOP_PANEL.h).toBeLessThanOrEqual(GAME_HEIGHT - 5 - 4);
  });
});

describe('the retry keys are wired', () => {
  // No suite constructs GameOverScene.create() (it builds the whole screen), so the opt-in is checked at the
  // source, the same way the SHOP key is; the built-game probe presses the real keys.
  test('Game Over opts in to MenuInput\'s retry action, and Title / Pause do not', async () => {
    const fs = await import('node:fs');
    const src = (f) => fs.readFileSync(new URL(`../../src/scenes/${f}`, import.meta.url), 'utf8');
    expect(src('GameOverScene.js')).toMatch(/new MenuInput\(this, \(a\) => this\._onAction\(a\), \{ retryAction: true \}\)/);
    expect(src('TitleScene.js')).not.toMatch(/retryAction/);
    expect(src('PauseScene.js')).not.toMatch(/retryAction/);
  });
});/**
 * W4.1 — the shop autoprompt on Game Over.
 *
 * CC Friday's four required scene cases (notes/cc-friday-shop-popup-2.txt, item 5 of the original note):
 *   (a) pops when affordable, (b) does not pop when broke, (c) retry works while it is open, (d) no errors
 *   on shutdown mid-popup.
 *
 * These call the scene's own methods on a stub context, the way the existing Game Over tests do, rather than
 * re-implementing the decision. The economy rules themselves live in shop-prompt.test.js; this file is only
 * about when the panel appears and who wins the input race.
 */
import { jest } from '@jest/globals';
jest.unstable_mockModule('phaser', () => ({ default: { Scene: class {}, GameObjects: new Proxy({}, { get: () => class {} }) } }));
jest.unstable_mockModule('../../src/data/index.js', () => ({ content: {}, loadContent: () => ({}) }));
const { GameOverScene } = await import('../../src/scenes/GameOverScene.js');
const { REG, SCENES } = await import('../../src/constants.js');
const { SHOP_ITEMS } = await import('../../src/systems/ProfileStore.js');

const proto = GameOverScene.prototype;

/** A profile with enough bank to buy the cheapest paid item. */
const rich = () => ({
  v: 1, level: 2, bank: 200, xp: 0,
  unlocked: { biomes: [], cosmetics: [], boosts: {} },
  equipped: {}, boosts: {},
});

/** A profile with nothing to spend. */
const broke = () => ({
  v: 1, level: 1, bank: 0, xp: 0,
  unlocked: { biomes: [], cosmetics: [], boosts: {} },
  equipped: {}, boosts: {},
});

/**
 * Minimal Game Over scene: registry, a timer fake that records and can fire the delayed call, and spies for
 * the two actions that leave the screen.
 */
function scene(o = {}) {
  const values = new Map();
  values.set(REG.PROFILE, o.profile || broke());
  if (o.awards !== undefined) values.set(REG.LAST_AWARDS, o.awards);
  else values.set(REG.LAST_AWARDS, { xp: { total: 10, parts: [] }, shopAutoprompt: Boolean(o.prompt) });

  const timers = [];
  let nextId = 1;
  const ctx = {
    alive: true,
    leaving: false,
    entry: null,
    shopOpen: false,
    shopView: null,
    shopHint: null,
    shopTimer: null,
    theme: { pal: {}, bind: () => () => {} },
    registry: { get: (k) => values.get(k), set: (k, v) => values.set(k, v) },
    time: {
      delayedCall: (ms, fn) => {
        const t = { id: nextId++, ms, fn, removed: false, remove() { this.removed = true; return this; } };
        timers.push(t);
        return t;
      },
    },
    add: { existing: () => {} },
    _anythingAffordable: proto._anythingAffordable,
    _cancelShopAutoprompt: proto._cancelShopAutoprompt,
    _resumeShopAutoprompt: proto._resumeShopAutoprompt,
    shopPending: false,
    _closeShop: proto._closeShop,
    _hideShopHint: proto._hideShopHint,
    _buildShopHint() { this.shopHint = { destroy() {} }; },
    _openShop() { this.shopOpen = true; this.shopView = { destroy: jest.fn(), handleAction: jest.fn() }; },
    retry: jest.fn(function retry() { this.retried = true; }),
    newSeed: jest.fn(),
    toTitle: jest.fn(),
  };
  ctx.values = values;
  ctx.timers = timers;
  return ctx;
}

/** Run the auto-open timer if it is still pending. */
function fireTimer(ctx) {
  const t = ctx.timers.find((x) => !x.removed);
  if (!t) return false;
  t.removed = true; // a delayedCall runs once
  t.fn();
  return true;
}

describe('(a) pops when the run made something affordable', () => {
  test('the service decision reaches the scene and opens the shop after the delay', () => {
    const ctx = scene({ profile: rich(), prompt: true });
    const shopSpy = jest.spyOn(ctx, '_openShop');
    proto._buildShopAccess.call(ctx);
    expect(ctx.timers.length).toBe(1);
    expect(shopSpy).not.toHaveBeenCalled(); // not before the delay: it must not interrupt the count-up
    fireTimer(ctx);
    expect(shopSpy).toHaveBeenCalledTimes(1);
    shopSpy.mockRestore();
  });

  test('the delay is the settled-count-up value, not zero', () => {
    const ctx = scene({ profile: rich(), prompt: true });
    proto._buildShopAccess.call(ctx);
    expect(ctx.timers[0].ms).toBeGreaterThanOrEqual(1000);
    expect(ctx.timers[0].ms).toBeLessThanOrEqual(2000);
  });

  test('the footer hint is shown when anything is affordable', () => {
    const ctx = scene({ profile: rich(), prompt: false });
    proto._buildShopAccess.call(ctx);
    expect(ctx.shopHint).not.toBeNull();
  });

  test('the hint appears even when the popup does not fire (stockpile player)', () => {
    // This is the amendment's item 3: no interruption, but the shop is still discoverable.
    const ctx = scene({ profile: rich(), prompt: false });
    const shopSpy = jest.spyOn(ctx, '_openShop');
    proto._buildShopAccess.call(ctx);
    expect(ctx.shopHint).not.toBeNull();
    expect(ctx.timers.length).toBe(0);
    expect(shopSpy).not.toHaveBeenCalled();
    shopSpy.mockRestore();
  });
});

describe('(b) does not pop when broke', () => {
  test('no timer and no hint when nothing is affordable', () => {
    const ctx = scene({ profile: broke(), prompt: false });
    proto._buildShopAccess.call(ctx);
    expect(ctx.timers.length).toBe(0);
    expect(ctx.shopHint).toBeNull();
  });

  test('a service flag of false never opens the shop, however rich the player', () => {
    // Belt and braces: the scene obeys the published decision rather than re-deriving it.
    const ctx = scene({ profile: rich(), prompt: false });
    const shopSpy = jest.spyOn(ctx, '_openShop');
    proto._buildShopAccess.call(ctx);
    expect(fireTimer(ctx)).toBe(false);
    expect(shopSpy).not.toHaveBeenCalled();
    shopSpy.mockRestore();
  });

  test('no awards at all (a quit/non-credited run) means no popup', () => {
    const ctx = scene({ profile: rich() });
    ctx.values.set(REG.LAST_AWARDS, null);
    const shopSpy = jest.spyOn(ctx, '_openShop');
    proto._buildShopAccess.call(ctx);
    expect(ctx.timers.length).toBe(0);
    expect(shopSpy).not.toHaveBeenCalled();
    shopSpy.mockRestore();
  });
});

// Marvin decision 7 (2026-11-14): these stubs open the shop through the AUTOPROMPT and never arm it, so they
// now pin the pillar-3 half of the new contract: an unarmed, unrequested shop still hands confirm to retry.
// The armed half (Enter / pad A buy, Space / pad RB retry) is in gameover-shop-buy.test.js.
describe('(c) retry wins while the shop is open', () => {
  test('confirm closes the shop and retries immediately', () => {
    const ctx = scene({ profile: rich(), prompt: true });
    proto._buildShopAccess.call(ctx);
    fireTimer(ctx);
    expect(ctx.shopOpen).toBe(true);
    proto._onAction.call(ctx, 'confirm');
    expect(ctx.shopOpen).toBe(false);
    expect(ctx.retry).toHaveBeenCalledTimes(1);
  });

  test('the shop does not get the confirm that retries', () => {
    const ctx = scene({ profile: rich(), prompt: true });
    ctx._onAction = proto._onAction;
    proto._buildShopAccess.call(ctx);
    fireTimer(ctx);
    const handle = ctx.shopView.handleAction;
    proto._onAction.call(ctx, 'confirm');
    expect(handle).not.toHaveBeenCalled();
  });

  test('cancel closes the shop and stays on Game Over', () => {
    const ctx = scene({ profile: rich(), prompt: true });
    proto._buildShopAccess.call(ctx);
    fireTimer(ctx);
    proto._onAction.call(ctx, 'cancel');
    expect(ctx.shopOpen).toBe(false);
    expect(ctx.retry).not.toHaveBeenCalled();
    expect(ctx.toTitle).not.toHaveBeenCalled();
  });

  test('new seed closes the shop and starts a new run', () => {
    const ctx = scene({ profile: rich(), prompt: true });
    proto._buildShopAccess.call(ctx);
    fireTimer(ctx);
    proto._onAction.call(ctx, 'alt');
    expect(ctx.shopOpen).toBe(false);
    expect(ctx.newSeed).toHaveBeenCalledTimes(1);
  });

  test('cursor keys still belong to the shop', () => {
    const ctx = scene({ profile: rich(), prompt: true });
    proto._buildShopAccess.call(ctx);
    fireTimer(ctx);
    const handle = ctx.shopView.handleAction;
    proto._onAction.call(ctx, 'down');
    expect(handle).toHaveBeenCalledWith('down');
    expect(ctx.shopOpen).toBe(true);
  });

  test('any input before the timer fires cancels the auto-open', () => {
    const ctx = scene({ profile: rich(), prompt: true });
    proto._buildShopAccess.call(ctx);
    proto._onAction.call(ctx, 'down');
    expect(ctx.shopTimer).toBeNull();
    expect(fireTimer(ctx)).toBe(false);
    expect(ctx.shopOpen).toBe(false);
  });

  test('retry before the timer fires leaves no popup behind', () => {
    const ctx = scene({ profile: rich(), prompt: true });
    proto._buildShopAccess.call(ctx);
    proto._onAction.call(ctx, 'confirm');
    expect(ctx.retried).toBe(true);
    expect(fireTimer(ctx)).toBe(false);
  });

  test('B opens the shop on demand when something is affordable', () => {
    const ctx = scene({ profile: rich(), prompt: false });
    proto._buildShopAccess.call(ctx);
    proto._onAction.call(ctx, 'shop');
    expect(ctx.shopOpen).toBe(true);
  });

  test('B does nothing when nothing is affordable', () => {
    const ctx = scene({ profile: broke(), prompt: false });
    proto._buildShopAccess.call(ctx);
    proto._onAction.call(ctx, 'shop');
    expect(ctx.shopOpen).toBe(false);
  });
});

describe('(d) shutdown mid-popup is clean', () => {
  test('a pending timer is removed on shutdown', () => {
    const ctx = scene({ profile: rich(), prompt: true });
    proto._buildShopAccess.call(ctx);
    const t = ctx.shopTimer;
    proto._cancelShopAutoprompt.call(ctx);
    expect(t.removed).toBe(true);
    expect(ctx.shopTimer).toBeNull();
  });

  test('an open shop is torn down on shutdown without throwing', () => {
    const ctx = scene({ profile: rich(), prompt: true });
    proto._buildShopAccess.call(ctx);
    fireTimer(ctx);
    const view = ctx.shopView;
    expect(() => proto._closeShop.call(ctx)).not.toThrow();
    expect(view.destroy).toHaveBeenCalled();
    expect(ctx.shopOpen).toBe(false);
  });

  test('a shop whose destroy throws does not wedge the screen', () => {
    const ctx = scene({ profile: rich(), prompt: true });
    proto._buildShopAccess.call(ctx);
    fireTimer(ctx);
    ctx.shopView.destroy = jest.fn(() => { throw new Error('already destroyed'); });
    expect(() => proto._closeShop.call(ctx)).not.toThrow();
    expect(ctx.shopOpen).toBe(false);
  });

  test('the timer callback is inert once the scene is gone', () => {
    const ctx = scene({ profile: rich(), prompt: true });
    proto._buildShopAccess.call(ctx);
    const t = ctx.shopTimer;
    ctx.alive = false;
    expect(() => t.fn()).not.toThrow();
    expect(ctx.shopOpen).toBe(false);
  });

  test('the timer callback never opens the shop during initials entry, but remembers it', () => {
    const ctx = scene({ profile: rich(), prompt: true });
    proto._buildShopAccess.call(ctx);
    ctx.entry = { handleAction: jest.fn() };
    fireTimer(ctx);
    expect(ctx.shopOpen).toBe(false);
    expect(ctx.shopPending).toBe(true);
  });

  // CC Friday, shop-popup rejection 1: a run that also makes the Top-10 opens initials entry, which used to
  // swallow the popup for good. Early runs on a thin board are exactly when prices get crossed.
  test('the popup that fired under initials entry opens once the entry closes', () => {
    const ctx = scene({ profile: rich(), prompt: true });
    proto._buildShopAccess.call(ctx);
    ctx.entry = { handleAction: jest.fn() };
    fireTimer(ctx);
    ctx.entry = null; // SAVE or SKIP
    proto._resumeShopAutoprompt.call(ctx);
    expect(ctx.shopOpen).toBe(false); // after a beat, not on the same frame as the board appearing
    expect(fireTimer(ctx)).toBe(true);
    expect(ctx.shopOpen).toBe(true);
    expect(ctx.shopPending).toBe(false);
  });

  test('typing in the entry does not drop the pending popup', () => {
    const ctx = scene({ profile: rich(), prompt: true });
    proto._buildShopAccess.call(ctx);
    ctx.entry = { handleAction: jest.fn() };
    fireTimer(ctx);
    proto._onAction.call(ctx, 'up');
    expect(ctx.shopPending).toBe(true);
  });

  test('closing the entry with nothing pending opens nothing', () => {
    const ctx = scene({ profile: rich(), prompt: false });
    proto._buildShopAccess.call(ctx);
    proto._resumeShopAutoprompt.call(ctx);
    expect(fireTimer(ctx)).toBe(false);
    expect(ctx.shopOpen).toBe(false);
  });

  test('retry after the entry closes cancels the resumed popup', () => {
    const ctx = scene({ profile: rich(), prompt: true });
    proto._buildShopAccess.call(ctx);
    ctx.entry = { handleAction: jest.fn() };
    fireTimer(ctx);
    ctx.entry = null;
    proto._resumeShopAutoprompt.call(ctx);
    proto._onAction.call(ctx, 'confirm');
    expect(ctx.retried).toBe(true);
    expect(fireTimer(ctx)).toBe(false);
    expect(ctx.shopOpen).toBe(false);
  });

  test('a resumed popup is inert once the scene is gone', () => {
    const ctx = scene({ profile: rich(), prompt: true });
    proto._buildShopAccess.call(ctx);
    ctx.entry = { handleAction: jest.fn() };
    fireTimer(ctx);
    ctx.entry = null;
    proto._resumeShopAutoprompt.call(ctx);
    ctx.alive = false;
    expect(() => fireTimer(ctx)).not.toThrow();
    expect(ctx.shopOpen).toBe(false);
  });

  test('the TITLE button does not promise B, which belongs to the shop', async () => {
