  expect(command('--build', build, '--out', 'log')).toMatchObject({ status: 1, stdout: '' });
});/**
 * Readable Chaos on the biome hazards (B1 slows, B2 Shatter Wall, B3 moving hazards). Pure scheduling
 * (systems/HazardTelegraph.js):
 *  - every shipped hazard def has a deliberate response (hop / brace / none), pinned by an explicit table;
 *  - a moving hazard is timed with its own `predictX(t)` (B3 API), never with an assumed direction: the stubs below move
 *    toward the sled, away from it, stop, and outrun it, and the arrival is checked against the closing-speed solution;
 *  - a Gear Gate is judged at the predicted arrival with `isPassable` / `gateNextChangeMs`: open there (with a margin on
 *    both sides) means a dim, silent mark that never goes lime; anything else is a normal hop warning.
 */
import { GROUND_WARN, hazardResponse, planTelegraph, predictArrival, TelegraphTracker } from '../../src/systems/HazardTelegraph.js';
import { rollPredictX, gateOpenAt, gateNextChangeMs as gateNext } from '../../src/systems/HazardMotion.js';
import { loadContent } from './_helpers.js';

const DEFS = loadContent().hazards;
const FAR = 1e9;
const sled = (x, speed, extra = {}) => ({ x, vx: speed, speed, grounded: true, landX: null, ...extra });
const base = (id, cx, extra = {}) => ({ hid: `${id}@${cx}`, def: DEFS[id], cx, cy: 0, w: DEFS[id].size.w, h: DEFS[id].size.h, hit: false, ...extra });
/**
 * A moving hazard stub: ground x moves at `v` px/s (signed; + is away from the sled) from run time t0, for at most `range`
 * px (from t0, default nowMs). cx carries a +3 px box offset (a sloped box centre is not the ground x) to prove the prediction is used as a delta.
 */
function mover(id, groundX, v, { nowMs = 0, t0 = nowMs, range = Infinity } = {}) {
  const at = (t) => groundX + Math.sign(v) * Math.min(range, Math.abs(v) * Math.max(0, t - t0) / 1000);
  return base(id, at(nowMs) + 3, { predictX: at });
}
/** Gate stub on the real HazardMotion timing (open 900 of every 1400 ms, phase 0). */
function gate(cx) {
  const m = DEFS.gearGate.motion;
  return base('gearGate', cx, {
    predictX: () => cx,
    isPassable: (t) => gateOpenAt(m, 0, t),
    gateNextChangeMs: (t) => gateNext(m, 0, t),
  });
}

describe('every shipped hazard has a deliberate response', () => {
  const TABLE = {
    packetSpike: 'hop', glitchChasm: 'hop',
    overflowFirewall: 'brace', garbageDataVent: 'brace',
    // B1 slows: amber like the Overflow Firewall (same effect kind, gentler numbers); a hop clears them, nothing crashes
    groomerCat: 'brace', seaweedTangle: 'brace', chocolateRiver: 'brace',
    // B2: blind does not crash; it costs sight for 1.2 s and a hop avoids it
    shatterWall: 'brace',
    // B3: all three crash
    rollingBoulder: 'hop', dewDrop: 'hop', gearGate: 'hop',
    // air hazards have their own telegraph (AirTelegraph)
    roguePacket: null, seagullDive: null, ashCloud: null,
    // B4: both air (the Meteor crashes and gets the AirTelegraph STAY LOW mark; the Gust Front is a visible zone, no crash)
    meteor: null, gustFront: null,
  };
  test('the table covers every def in src/data/hazards (a new def must be classified here)', () => {
    expect(Object.keys(DEFS).sort()).toEqual(Object.keys(TABLE).sort());
  });
  test.each(Object.entries(TABLE))('%s -> %s', (id, want) => {
    expect(hazardResponse(DEFS[id])).toBe(want);
  });
});

describe('predictArrival: a moving hazard is timed with its own predictX', () => {
  const NOW = 5000;
  test('static hazard (no predictX, or one that does not move): exactly dx / vx, the sim oracle rule', () => {
    const plain = base('packetSpike', 1800);
    expect(predictArrival(plain, sled(1000, 640), NOW).etaMs).toBe(800 / 640 * 1000);
    const still = base('packetSpike', 1800, { predictX: () => 1797 });
    expect(predictArrival(still, sled(1000, 640), NOW).etaMs).toBe(800 / 640 * 1000);
    expect(predictArrival(still, sled(1000, 640), NOW).cxAtArrival).toBe(1800);
  });
  test('rolling toward the sled: closing speed is sled + roll speed', () => {
    const h = mover('rollingBoulder', 1800, -200, { nowMs: NOW });
    const a = predictArrival(h, sled(1000, 600), NOW);
    expect(a.etaMs).toBeCloseTo(803 / 800 * 1000, 0);
    expect(a.cxAtArrival).toBeCloseTo(1000 + 600 * a.etaMs / 1000, 0);
  });
  test('rolling away from the sled: closing speed is sled - roll speed', () => {
    const h = mover('dewDrop', 1800, 200, { nowMs: NOW });
    const a = predictArrival(h, sled(1000, 600), NOW);
    expect(a.etaMs).toBeCloseTo(803 / 400 * 1000, 0);
  });
  test('a roll that stops part way: it closes fast, then at sled speed', () => {
    // moves 100 px toward the sled in 0.5 s, then rests
    const h = mover('rollingBoulder', 1800, -200, { range: 100, nowMs: NOW, t0: NOW });
    const a = predictArrival(h, sled(1000, 600), NOW);
    // after 0.5 s: sled at 1300, hazard centre at 1703; the rest at 600 px/s
    expect(a.etaMs).toBeCloseTo(500 + (1703 - 1300) / 600 * 1000, 0);
  });
  test('rolling away faster than the sled: no arrival (Infinity)', () => {
    const h = mover('dewDrop', 1800, 200, { nowMs: NOW });
    expect(predictArrival(h, sled(1000, 150), NOW).etaMs).toBe(Infinity);
  });
  test('the same answer for a real HazardMotion roll in either direction (direction comes from predictX only)', () => {
    for (const dir of [-1, 1]) {
      const motion = { kind: 'roll', speedPxS: 140, rangePx: 160, dir };
      const state = { activeAtMs: NOW - 100, offsetPx: 0 };
      const at = (t) => rollPredictX(state, motion, 1800, t);
      const h = base('rollingBoulder', at(NOW), { predictX: at });
      const a = predictArrival(h, sled(1000, 700), NOW);
      // solve directly by brute force at 1 ms
      let t = 0;
      while (at(NOW + t) - (1000 + 700 * t / 1000) > 0) t += 1;
      expect(Math.abs(a.etaMs - t)).toBeLessThanOrEqual(2);
    }
  });
  test('without a run time the prediction is not used (falls back to static)', () => {
    const h = mover('rollingBoulder', 1800, -200, { nowMs: NOW });
    expect(predictArrival(h, sled(1000, 600), undefined).etaMs).toBe(803 / 600 * 1000);
  });
});

describe('planTelegraph with moving hazards', () => {
  const NOW = 5000;
  test('etaS and the lime window follow the predicted arrival, not dx / vx', () => {
    // toward at 200: dx 243 closes at 800 px/s -> 0.30 s: inside the window (static would say 0.405 s: not yet)
    const toward = mover('rollingBoulder', 1240, -200, { nowMs: NOW });
    const m1 = planTelegraph([toward], sled(1000, 600), FAR, { nowMs: NOW })[0];
    expect(m1.etaS).toBeCloseTo(243 / 800, 3);
    expect(m1).toMatchObject({ state: 'go', color: 'lime' });
    expect(m1.arrivalMs).toBeCloseTo(NOW + 243 / 800 * 1000, 0);
    // away at 200: dx 203 closes at 400 px/s -> 0.51 s: not yet (static would say 0.34 s: hop now)
    const away = mover('dewDrop', 1200, 200, { nowMs: NOW });
    const m2 = planTelegraph([away], sled(1000, 600), FAR, { nowMs: NOW })[0];
    expect(m2.etaS).toBeCloseTo(203 / 400, 3);
    expect(m2).toMatchObject({ state: 'warn', color: 'danger' });
  });
  test('a hazard the sled cannot catch is announced but never goes lime', () => {
    const h = mover('dewDrop', 1100, 200, { nowMs: NOW });
    const m = planTelegraph([h], sled(1000, 150), FAR, { nowMs: NOW })[0];
    expect(m).toMatchObject({ kind: 'hop', state: 'warn' });
    expect(m.etaS).toBe(Infinity);
  });
  test('airborne: "clear" compares the landing with where the hazard will be, not where it is', () => {
    // rolls toward the sled at 200: now at 1403, met at about 1000 + 700 * 403 / 900 = 1313
    const h = mover('rollingBoulder', 1400, -200, { nowMs: NOW });
    const meet = 1000 + 700 * (403 / 900);
    const land = meet + h.w / 2 + GROUND_WARN.clearMarginPx + 2; // past the meeting point, short of the current box
    expect(land).toBeLessThan(h.cx + h.w / 2 + GROUND_WARN.clearMarginPx);
    const m = planTelegraph([h], sled(1000, 700, { grounded: false, landX: land }), FAR, { nowMs: NOW })[0];
    expect(m).toMatchObject({ clear: true, state: 'clear' });
  });
  test('static hazards are planned exactly as before when nowMs is given', () => {
    const list = [base('packetSpike', 1300), base('glitchChasm', 1700), base('overflowFirewall', 1500)];
    const a = planTelegraph(list, sled(1000, 650), FAR);
    const b = planTelegraph(list, sled(1000, 650), FAR, { nowMs: NOW });
    expect(b.map(({ arrivalMs, ...m }) => m)).toEqual(a.map(({ arrivalMs, ...m }) => m));
  });
});

describe('Gear Gate: the cue says whether it will be open at arrival', () => {
  // sled at 1000, 700 px/s, gate at 1700: arrival 1000 ms after now
  const at = (nowMs, dx = 700, extra) => planTelegraph([gate(1000 + dx)], sled(1000, 700, extra), FAR, { nowMs })[0];
  test('closed at arrival: a normal red hop warning, lime in the hop window', () => {
    // arrival at t = 1100 (cycle 1100: closed until 1400)
    expect(at(100)).toMatchObject({ kind: 'hop', state: 'warn', color: 'danger', clear: false, gate: 'closed' });
    expect(at(1100 - 300, 700 * 0.3)).toMatchObject({ state: 'go', color: 'lime', gate: 'closed' });
  });
  test('open at arrival with room on both sides: state open, drawn dim, never lime (even inside the hop window)', () => {
    // arrival at t = 450 (open 0..900)
    expect(at(-550)).toMatchObject({ kind: 'hop', state: 'open', color: 'danger', gate: 'open' });
    expect(at(450 - 300, 700 * 0.3)).toMatchObject({ state: 'open', gate: 'open', color: 'danger' });
  });
  test('open at arrival but within the margin of a change: judged closed (the arrival time is an estimate)', () => {
    const m = GROUND_WARN.gateMarginMs;
    // closes at 900: arrival m/2 before it
    expect(at(900 - m / 2 - 1000)).toMatchObject({ state: 'warn', gate: 'closed' });
    // opened at 1400: arrival m/2 after it
    expect(at(1400 + m / 2 - 1000)).toMatchObject({ state: 'warn', gate: 'closed' });
    // well inside: open
    expect(at(1400 + m + 10 - 1000)).toMatchObject({ state: 'open', gate: 'open' });
    expect(at(900 - m - 10 - 1000)).toMatchObject({ state: 'open', gate: 'open' });
  });
  test('the margin covers a crossing and some eta drift, and fits inside the shortest open spell', () => {
    expect(GROUND_WARN.gateMarginMs).toBeGreaterThanOrEqual(80);
    expect(2 * GROUND_WARN.gateMarginMs).toBeLessThan(DEFS.gearGate.motion.openMs);
  });
  test('non-gate hazards carry gate: null', () => {
    expect(planTelegraph([base('packetSpike', 1300)], sled(1000, 650), FAR, { nowMs: 0 })[0].gate).toBe(null);
  });
  test('tracker: an open gate is silent; when the verdict turns closed it warns once', () => {
    const tr = new TelegraphTracker();
    const g = gate(1700);
    const plan = (nowMs) => planTelegraph([g], sled(1000, 700), FAR, { nowMs });
    expect(plan(-550)[0].state).toBe('open');
    expect(tr.update(-550, plan(-550))).toEqual([]);
    expect(plan(100)[0].state).toBe('warn');
    expect(tr.update(100, plan(100)).map((e) => [e.type, e.ref])).toEqual([['warn', g]]);
    expect(tr.update(116, plan(116))).toEqual([]);
  });
});

describe('TelegraphTracker.lastArrivalMs: the latest planned arrival per hazard (read by the crash report)', () => {
  test('updates every frame a hazard is marked, keeps the last finite value, null when never planned', () => {
    const tr = new TelegraphTracker();
    const h = base('packetSpike', 1700);
    expect(tr.lastArrivalMs(h)).toBe(null);
    tr.update(1000, planTelegraph([h], sled(1000, 700), FAR, { nowMs: 1000 }));
    expect(tr.lastArrivalMs(h)).toBeCloseTo(2000, 6);
    tr.update(1500, planTelegraph([h], sled(1300, 600), FAR, { nowMs: 1500 }));
    expect(tr.lastArrivalMs(h)).toBeCloseTo(1500 + 400 / 600 * 1000, 6);
    // a mark without an arrival (no nowMs) leaves the last one
    tr.update(1600, planTelegraph([h], sled(1350, 600), FAR));
    expect(tr.lastArrivalMs(h)).toBeCloseTo(1500 + 400 / 600 * 1000, 6);
  });
  test('clear and open marks still record their arrival (the sled may crash into it anyway)', () => {
    const tr = new TelegraphTracker();
    const h = base('packetSpike', 1400);
    tr.update(0, planTelegraph([h], sled(1000, 700, { grounded: false, landX: 2000 }), FAR, { nowMs: 0 }));
    expect(tr.lastArrivalMs(h)).toBeCloseTo(400 / 700 * 1000, 6);
  });
});/**
 * Readable Chaos, phase 1: the telegraph wired into the shipped RunScene (stub built from RunScene.prototype, as in
 * biome-effects-runscene.test.js), the drawing entity against a recording graphics fake, and the two new sounds.
 */
import { jest } from '@jest/globals';

const FakePhaser = {
  Scene: class {},
  Physics: { Matter: { Matter: { Bodies: { rectangle: () => ({}), circle: () => ({}) }, Body: {} } } },
  Renderer: { WebGL: { Pipelines: { PostFXPipeline: class {} } } },
  GameObjects: { Container: class {}, Graphics: class {}, BitmapText: class {}, Zone: class {}, Image: class {}, Rectangle: class {}, Text: class {} },
  BlendModes: { ADD: 1 },
  Scenes: { Events: { UPDATE: 'update', SHUTDOWN: 'shutdown', DESTROY: 'destroy' } },
  Math: { Between: (a) => a, Clamp: (v, a, b) => Math.min(b, Math.max(a, v)) },
};
jest.unstable_mockModule('phaser', () => ({ default: FakePhaser }));
jest.unstable_mockModule('../../src/shaders/GlitchPipeline.js', () => ({ GlitchPipeline: { install() {} } }));

const { RunScene } = await import('../../src/scenes/RunScene.js');
const { GroundTelegraph, EDGE_INSET_PX, EDGE_MAX_STACK } = await import('../../src/entities/GroundTelegraph.js');
const { TelegraphTracker, planTelegraph, planTelegraphMarks, GROUND_WARN } = await import('../../src/systems/HazardTelegraph.js');
const { emptyWards, addWard } = await import('../../src/systems/Wards.js');
const { SFX, AudioSynth } = await import('../../src/systems/AudioSynth.js');
const { loadContent } = await import('./_helpers.js');

const DEFS = loadContent().hazards;
const hz = (id, cx, extra = {}) => ({ hid: `${id}@${cx}`, def: DEFS[id], cx, cy: 300 - DEFS[id].size.h / 2, w: DEFS[id].size.w, h: DEFS[id].size.h, hit: false, ...extra });
const PAL = { danger: 0xff0000, amber: 0xffaa00, lime: 0x00ff00, bg: 0x000011, text: 0xffffff, cyan: 0x00ffff };

function makeRun(hazards, sledOver = {}) {
  const sfx = [];
  const s = Object.create(RunScene.prototype);
  Object.assign(s, {
    sfx,
    sled: { x: 1000, y: 280, vx: 650, vy: 0, speed: 650, grounded: true, airEtaMs: Infinity, invulnerableMs: 0, groundAngleDeg: 0, airtimeMs: 0, ...sledOver },
    hazards: new Map([[0, hazards]]),
    wards: emptyWards(),
    teleTracker: new TelegraphTracker(),
    _view: { left: 900, right: 1900, top: 0, bottom: 540 },
    runTimeMs: 5000,
    playSfx(name, opts) { sfx.push([name, opts]); },
  });
  return s;
}

describe('RunScene.updateGroundTelegraph', () => {
  test('announces a crash hazard once (groundWarn), stamps it, then cues the hop once when the window opens', () => {
    const h = hz('packetSpike', 1000 + 1250);
    const s = makeRun([h]);
    Object.defineProperty(s, '_view', { get() { throw new Error('cue planning read the renderer'); } });
    s.updateGroundTelegraph(5000);
    expect(s.sfx).toEqual([['groundWarn', { brace: false }]]);
    expect(h.teleAtMs).toBe(5000);
    expect(s._teleMarks).toHaveLength(1);
    expect(s._teleMarks[0]).toMatchObject({ ref: h, color: 'danger' });
    expect(s._teleMarks[0]).not.toHaveProperty('onScreen');
    s.updateGroundTelegraph(5016);
    expect(s.sfx).toHaveLength(1);
    s.sled.x = h.cx - 650 * 0.37;
    s.updateGroundTelegraph(6000);
    expect(s.sfx[1]).toEqual(['hopCue', undefined]);
    expect(s._teleMarks[0]).toMatchObject({ state: 'go', color: 'lime', arrivalMs: 6370 });
    expect(s.teleTracker.lastArrivalMs(h)).toBe(6370);
    s.updateGroundTelegraph(6016);
    expect(s.sfx).toHaveLength(2);
    expect(h.teleAtMs).toBe(5000);
  });
  test('a slow hazard warns with the brace sound and never cues a hop', () => {
    const h = hz('overflowFirewall', 1400);
    const s = makeRun([h]);
    for (let x = 1000; x < 1400; x += 9) { s.sled.x = x; s.updateGroundTelegraph(5000 + x); }
    expect(s.sfx).toEqual([['groundWarn', { brace: true }]]);
  });
  test('a warded hazard (by id or by effect) is not announced', () => {
    const a = hz('overflowFirewall', 1400);
    const s = makeRun([a]);
    s.wards = addWard(s.wards, 'w1', { kind: 'ward', durationMs: 5000, effects: ['slow'] });
    s.updateGroundTelegraph(5000);
    expect(s.sfx).toEqual([]);
    expect(s._teleMarks).toEqual([]);
    const b = hz('packetSpike', 1400);
    const s2 = makeRun([b]);
    s2.wards = addWard(s2.wards, 'w2', { kind: 'ward', durationMs: 5000, hazards: ['packetSpike'] });
    s2.updateGroundTelegraph(5000);
    expect(s2._teleMarks).toEqual([]);
  });
  test('airborne with the ballistic landing well past the box: dim, silent; the forecast uses sled.airEtaMs', () => {
    const h = hz('packetSpike', 1400);
    const s = makeRun([h], { grounded: false, airEtaMs: 1000 }); // lands at 1650
    s.updateGroundTelegraph(5000);
    expect(s._teleMarks[0]).toMatchObject({ clear: true });
    expect(s.sfx).toEqual([]);
    s.sled.airEtaMs = 500; // lands at 1325, short of the box
    s.updateGroundTelegraph(5016);
    expect(s._teleMarks[0]).toMatchObject({ clear: false });
    expect(s.sfx).toEqual([['groundWarn', { brace: false }]]);
  });
  test('passes the run time: a moving hazard is timed with its predictX, an open Gear Gate stays silent', () => {
    // rolls toward the sled at 200 px/s from run time 5000: dx 243 closes at 850 px/s -> 0.286 s (static: 0.374 s)
    const roll = hz('rollingBoulder', 1243, { predictX: (t) => 1240 - 200 * Math.max(0, t - 5000) / 1000 });
    const s = makeRun([roll]);
    s.updateGroundTelegraph(5000);
    expect(s._teleMarks[0].etaS).toBeCloseTo(243 / 850, 3);
    expect(s._teleMarks[0].arrivalMs).toBeCloseTo(5000 + 243 / 850 * 1000, 0);
    // a gate that is open from 5000 to 6400 (arrival at 5000 + 650 / 650 s): no sound, state open
    const gate = hz('gearGate', 1650, { predictX: () => 1650, isPassable: (t) => t >= 5000 && t < 6400, gateNextChangeMs: (t) => (t < 5000 ? 5000 - t : 6400 - t) });
    const s2 = makeRun([gate]);
    s2.updateGroundTelegraph(5000);
    expect(s2._teleMarks[0]).toMatchObject({ state: 'open', gate: 'open' });
    expect(s2.sfx).toEqual([]);
  });
  test('updateFun runs the telegraph every live frame', () => {
    const h = hz('packetSpike', 2200);
    const s = makeRun([h]);
    Object.assign(s, {
      shardField: null, airTelegraph: null, bestMarker: null, bestM: 0, newBestDone: true, biomeMask: 0, _biomeId: null,
      score: { checkMilestones: () => [] }, terrain: { _sectorOf: () => 1, biomeAtX: () => null },
      tutTimers: { stall: 0 }, tutDone: new Set(['hop', 'flip', 'push', 'tuck']), tutShown: new Set(), _steepMs: 0, _landings: 0, tuckShows: 9,
      hints: { update: () => [] }, lastBoost: null, _airTricks: 0,
    });
    s.launchAheadPx = () => Infinity;
    s.applyHintEvents = () => {};
    s.updateFun(16, { tuck: false }, 100);
    expect(s.sfx).toEqual([['groundWarn', { brace: false }]]);
    expect(s._teleMarks).toHaveLength(1);
  });
});

/** A Graphics fake that records every call. */
function fakeScene() {
  const calls = [];
  const g = new Proxy({}, { get: (_, name) => (name === 'calls' ? calls : (...args) => { calls.push([name, ...args]); return g; }) });
  return { add: { graphics: () => g }, g, calls };
}
const names = (calls) => calls.map((c) => c[0]);
const colours = (calls) => new Set(calls.filter((c) => c[0] === 'lineStyle' || c[0] === 'fillStyle').map((c) => c[2 - (c[0] === 'fillStyle' ? 1 : 0)]));
const xs = (calls) => calls.flatMap((c) => (c[0] === 'lineBetween' ? [c[1], c[3]] : c[0] === 'fillRect' ? [c[1], c[1] + c[3]] : c[0] === 'fillTriangle' || c[0] === 'strokeTriangle' ? [c[1], c[3], c[5]] : []));

describe('GroundTelegraph (drawing)', () => {
  const VIEW = { left: 900, right: 1900, top: 0, bottom: 540 };
  const flat = [{ startX: 0, endX: 2100, points: [{ x: 0, y: 300 }, { x: 2100, y: 300 }] }];
  const draw = (marks, zoom = 1, view = VIEW, chunks = flat) => {
    const sc = fakeScene();
    const t = new GroundTelegraph(sc, PAL);
    sc.calls.length = 0;
    t.update(1234, marks, view, zoom, chunks);
    return sc.calls;
  };
  const plan = (list, x = 1000, speed = 650) => planTelegraphMarks(list, { x, vx: speed, speed, grounded: true, landX: null });

  test('no marks: clears and draws nothing', () => {
    expect(draw([])).toEqual([['clear']]);
  });
  test('an off-screen hazard is drawn at the right screen edge, on the terrain line, in its response colour', () => {
    const calls = draw(plan([hz('packetSpike', 2200)]));
    expect(names(calls)).toContain('lineBetween');
    expect(colours(calls).has(PAL.danger)).toBe(true);
    expect(colours(calls).has(PAL.amber)).toBe(false);
    const x = xs(calls);
    expect(Math.max(...x)).toBeLessThanOrEqual(VIEW.right);
    expect(Math.min(...x)).toBeGreaterThan(VIEW.right - 2 * EDGE_INSET_PX - 30);
    const ys = calls.flatMap((c) => (c[0] === 'lineBetween' ? [c[2], c[4]] : []));
    expect(Math.max(...ys)).toBeLessThanOrEqual(300 + 1);
    expect(Math.min(...ys)).toBeGreaterThan(300 - 120);
  });
  test('the badge interpolates read-only live points and falls back when the viewport extends beyond them', () => {
    const x = VIEW.right - EDGE_INSET_PX;
    const points = Object.freeze([Object.freeze({ x: x - 20, y: 260 }), Object.freeze({ x: x + 20, y: 280 })]);
    const chunks = Object.freeze([Object.freeze({ startX: x - 20, endX: x + 20, points })]);
    const marks = plan([hz('packetSpike', 2200)]);
    const stemY = (...args) => draw(marks, ...args).find(([name]) => name === 'lineBetween')[2];
    expect(stemY(1, VIEW, chunks)).toBe(270);
    expect(stemY(1, { ...VIEW, right: 2000 }, chunks)).toBe(270);
    expect(stemY(1, { ...VIEW, right: 2000, bottom: 600 }, [])).toBe(300);
  });
  test('a brace hazard draws in amber, a hop-window hazard in lime', () => {
    expect(colours(draw(plan([hz('overflowFirewall', 2200)]))).has(PAL.amber)).toBe(true);
    const go = plan([hz('packetSpike', 1000 + 650 * 0.3)]);
    expect(go[0].state).toBe('go');
    const c = colours(draw(go));
    expect(c.has(PAL.lime)).toBe(true);
    expect(c.has(PAL.danger)).toBe(false);
  });
  test('an on-screen hazard gets a light column standing on the box, not an edge marker', () => {
    const h = hz('packetSpike', 1500);
    const calls = draw(plan([h]));
    const col = calls.filter((c) => c[0] === 'lineBetween' && c[1] === h.cx && c[3] === h.cx);
    expect(col.length).toBeGreaterThanOrEqual(2); // soft band + core
    const top = Math.min(...col.map((c) => Math.min(c[2], c[4])));
    expect(top).toBeLessThan(h.cy - h.h / 2 - 100);
    expect(Math.max(...xs(calls))).toBeLessThan(VIEW.right - EDGE_INSET_PX - 40);
  });
  test('the same go mark switches across the current viewport, ignoring the legacy visibility hint', () => {
    const h = hz('packetSpike', 1195, { w: 40 });
    const mark = Object.freeze(planTelegraph([h], { x: 1000, vx: 650, speed: 650, grounded: true }, 1900)[0]);
    expect(mark).toMatchObject({ state: 'go', onScreen: true });
    const triangle = (view) => draw([mark], 1, view).find((c) => c[0] === 'fillTriangle');
    expect(triangle(VIEW)[5]).toBe(h.cx); // roomy current viewport uses the column
    for (const right of [1160, 1180, 1198]) { // fully outside, partial box, centre in but response clips
      const view = { ...VIEW, right };
      const points = triangle(view);
      expect(points[5]).toBe(right - EDGE_INSET_PX);
      expect(Math.max(...xs([points]))).toBeLessThan(right);
    }
    expect(triangle({ ...VIEW, top: 277 })[5]).toBe(VIEW.right - EDGE_INSET_PX); // response above the current view
  });
  test('a clipped go keeps the response slot even after ordinary edge warnings fill the stack', () => {
    const h = (cx, id = 'overflowFirewall') => hz(id, cx);
    const marks = plan([h(1100), h(1120), h(1140), h(1195, 'packetSpike')]);
    expect(marks.map((m) => m.state)).toEqual(['warn', 'warn', 'warn', 'go']);
    const view = { ...VIEW, right: 1080 };
    const calls = draw(marks, 1, view);
    expect(calls.find((c) => c[0] === 'fillTriangle')[5]).toBe(view.right - EDGE_INSET_PX);
    expect(names(calls).filter((n) => n === 'strokeRect')).toHaveLength(EDGE_MAX_STACK);
  });
  test('a hazard high in the view: the column is shortened so the cue on top stays on screen', () => {
    const h = hz('packetSpike', 1500, { cy: 90 });
    const calls = draw(plan([h]));
    const ys = calls.flatMap((c) => (c[0] === 'lineBetween' ? [c[2], c[4]] : []));
    expect(Math.min(...ys)).toBeGreaterThanOrEqual(VIEW.top);
    expect(Math.min(...ys)).toBeLessThan(90 - 10 - 30); // still a column above the box
  });
  test('sizes are counter-scaled: at zoom 0.5 the edge marker is twice as large in world px (same on screen)', () => {
    const view2 = { left: 0, right: 1920, top: 0, bottom: 1080 };
    const span = (calls) => { const x = xs(calls); return Math.max(...x) - Math.min(...x); };
    const a = span(draw(plan([hz('packetSpike', 2400)], 1000, 800)));
    const b = span(draw(plan([hz('packetSpike', 2400)], 1000, 800), 0.5, view2));
    expect(b / a).toBeCloseTo(2, 1);
  });
  test('edge markers stack upward and are capped at EDGE_MAX_STACK', () => {
    const many = [];
    for (let i = 0; i < 5; i++) many.push(hz('packetSpike', 2000 + i * 40));
    const m = plan(many);
    expect(m.length).toBe(5);
    const stems = (calls) => calls.filter((c) => c[0] === 'strokeRect').length;
    expect(stems(draw(m))).toBe(EDGE_MAX_STACK);
    expect(stems(draw(m.slice(0, 1)))).toBe(1);
  });
  test('a clear mark is drawn dim', () => {
    const m = planTelegraph([hz('packetSpike', 2200)], { x: 1000, vx: 650, speed: 650, grounded: false, landX: 3000 }, VIEW.right);
    const alphas = (calls) => calls.filter((c) => c[0] === 'lineStyle').map((c) => c[3]);
    expect(Math.max(...alphas(draw(m)))).toBeLessThanOrEqual(0.35);
    expect(Math.max(...alphas(draw(plan([hz('packetSpike', 2200)]))))).toBeGreaterThan(0.8);
  });
  test('an open Gear Gate is drawn dim, and its glyph has no bar across it (closed has one)', () => {
    const g = (open) => ({ ...hz('gearGate', 2200), predictX: () => 2200, isPassable: () => open, gateNextChangeMs: () => 1000 });
    const mk = (open) => planTelegraph([g(open)], { x: 1000, vx: 650, speed: 650, grounded: true, landX: null }, VIEW.right, { nowMs: 0 });
    const alphas = (calls) => calls.filter((c) => c[0] === 'lineStyle').map((c) => c[3]);
    expect(mk(true)[0].state).toBe('open');
    expect(Math.max(...alphas(draw(mk(true))))).toBeLessThanOrEqual(0.35);
    expect(Math.max(...alphas(draw(mk(false))))).toBeGreaterThan(0.8);
    const lines = (calls) => calls.filter((c) => c[0] === 'lineBetween').length;
    expect(lines(draw(mk(false)))).toBe(lines(draw(mk(true))) + 1);
  });
  test('the B3 and B2 hazards get their own glyphs (not the generic box)', () => {
    for (const id of ['rollingBoulder', 'dewDrop', 'gearGate', 'shatterWall']) {
      const calls = draw(plan([hz(id, 2200)]));
      // the generic glyph is a filled square at half alpha
      expect(calls.some((c) => c[0] === 'fillRect' && c[3] === c[4] && c[3] < 20 && c[2] !== undefined && c[5] === undefined)).toBe(false);
    }
  });
  test('setPalette and destroy', () => {
    const sc = fakeScene();
    const t = new GroundTelegraph(sc, PAL);
    t.setPalette({ ...PAL, danger: 0x123456 });
    sc.calls.length = 0;
    t.update(0, plan([hz('packetSpike', 2200)]), VIEW, 1, flat);
    expect(colours(sc.calls).has(0x123456)).toBe(true);
    t.destroy();
    expect(names(sc.calls)).toContain('destroy');
    expect(() => t.update(0, [], VIEW, 1, flat)).not.toThrow();
  });
});

describe('telegraph sounds', () => {
  test('groundWarn and hopCue are public SFX names', () => {
    expect(SFX).toContain('groundWarn');
    expect(SFX).toContain('hopCue');
  });
  test('each makes sound; the brace warning is a different, lower sound than the hop warning', () => {
    const a = new AudioSynth({ events: { on() {}, off() {} } });
    const rec = [];
    a.nodes = { sfxBus: {} };
    a._osc = (type, f0, f1) => { rec.push([type, f0, f1]); };
    a._noise = () => {};
    const play = (name, opts) => { rec.length = 0; a._sfx(name, 0, 1, 1, opts || {}); return rec.map((r) => r.slice()); };
    const hop = play('groundWarn', { brace: false });
    const brace = play('groundWarn', { brace: true });
    const cue = play('hopCue');
    expect(hop.length).toBeGreaterThan(0);
    expect(brace.length).toBeGreaterThan(0);
    expect(cue.length).toBeGreaterThan(0);
    const top = (r) => Math.max(...r.map((x) => Math.max(x[1], x[2])));
    expect(top(brace)).toBeLessThan(top(hop));
    expect(top(cue)).toBeGreaterThan(top(hop));
    expect(play('nope')).toEqual([]);
    void GROUND_WARN;
  });
});/**
 * Readable Chaos, phase 1: the ground-hazard telegraph. Pure scheduling math (systems/HazardTelegraph.js): which hazards
 * are announced, from how far, in which colour, when the chevron goes lime, and which sounds play once.
 */
import {
  GROUND_WARN, hazardResponse, warnDistancePx, inHopWindow, planTelegraph, TelegraphTracker,
} from '../../src/systems/HazardTelegraph.js';
import { loadContent } from './_helpers.js';

const DEFS = loadContent().hazards;
const hz = (id, cx, extra = {}) => ({ hid: `${id}@${cx}`, def: DEFS[id], cx, cy: 0, w: DEFS[id].size.w, h: DEFS[id].size.h, hit: false, ...extra });
const sled = (x, speed, extra = {}) => ({ x, vx: speed, speed, grounded: true, landX: null, ...extra });
const FAR = 1e9;

describe('hazardResponse: colour is the response, not the def colour', () => {
  test('crash ground hazards are "hop", slow / scramble ground hazards are "brace", air hazards are not telegraphed here', () => {
    expect(hazardResponse(DEFS.packetSpike)).toBe('hop');
    expect(hazardResponse(DEFS.glitchChasm)).toBe('hop');
    expect(hazardResponse(DEFS.overflowFirewall)).toBe('brace');
    expect(hazardResponse(DEFS.garbageDataVent)).toBe('brace');
    expect(hazardResponse(DEFS.roguePacket)).toBe(null);
    expect(hazardResponse(DEFS.seagullDive)).toBe(null);
    expect(hazardResponse({ id: 'noOnHit', placement: 'ground' })).toBe('hop'); // a def without onHit crashes (Hazard.js)
    expect(hazardResponse(null)).toBe(null);
  });
  test('every shipped ground hazard def gets a response', () => {
    for (const d of Object.values(DEFS)) expect(hazardResponse(d)).toBe(d.placement === 'air' ? null : d.onHit.effect === 'crash' ? 'hop' : 'brace');
  });
});

describe('warnDistancePx: about 2 s of travel, clamped', () => {
  test('scales with speed between the clamps', () => {
    expect(warnDistancePx(500)).toBe(500 * GROUND_WARN.leadS);
    expect(warnDistancePx(650)).toBe(1300);
    expect(warnDistancePx(500) / 500).toBeCloseTo(2.0, 9);
  });
  test('clamps: never under minPx (slow sled) or over maxPx (terrain is only streamed so far ahead)', () => {
    expect(warnDistancePx(0)).toBe(GROUND_WARN.minPx);
    expect(warnDistancePx(100)).toBe(GROUND_WARN.minPx);
    expect(warnDistancePx(1200)).toBe(GROUND_WARN.maxPx);
    expect(warnDistancePx(5000)).toBe(GROUND_WARN.maxPx);
    expect(warnDistancePx(NaN)).toBe(GROUND_WARN.minPx);
    // the lead in seconds at the top of the measured speed range stays above the 1.2 s target
    expect(GROUND_WARN.maxPx / 1200).toBeGreaterThanOrEqual(1.2);
  });
});

describe('inHopWindow: the sim hop oracle rule (tools/sim/browser.js policies.hop)', () => {
  const oracle = (dx, vxRaw, lead = 380) => { const vx = Math.max(vxRaw, 60); return dx > 0 && (dx / vx) * 1000 <= lead && (dx / vx) * 1000 > lead - 250; };
  test('agrees with the oracle over a grid of distances and speeds', () => {
    for (let vx = 0; vx <= 1400; vx += 35) for (let dx = -40; dx <= 700; dx += 7) expect(inHopWindow(dx, vx)).toBe(oracle(dx, vx));
  });
  test('boundaries at 650 px/s: 380 ms out is in, 130 ms out is not, behind is not', () => {
    expect(inHopWindow(650 * 0.38, 650)).toBe(true);
    expect(inHopWindow(650 * 0.381, 650)).toBe(false);
    expect(inHopWindow(650 * 0.131, 650)).toBe(true);
    expect(inHopWindow(650 * 0.13, 650)).toBe(false);
    expect(inHopWindow(-1, 650)).toBe(false);
  });
});

describe('planTelegraph', () => {
  test('a crash hazard 2 s out is announced in danger; nothing is announced beyond the warn distance', () => {
    const h = hz('packetSpike', 1000 + 1299);
    const [m] = planTelegraph([h], sled(1000, 650), FAR);
    expect(m).toMatchObject({ ref: h, kind: 'hop', state: 'warn', color: 'danger', clear: false, dx: 1299 });
    expect(m.etaS).toBeCloseTo(1299 / 650, 6);
    expect(planTelegraph([hz('packetSpike', 1000 + 1301)], sled(1000, 650), FAR)).toEqual([]);
  });
  test('slow and scramble hazards are amber "brace" and never go lime', () => {
    for (const id of ['overflowFirewall', 'garbageDataVent']) {
      const [m] = planTelegraph([hz(id, 1200)], sled(1000, 650), FAR);
      expect(m).toMatchObject({ kind: 'brace', state: 'warn', color: 'amber' });
    }
  });
  test('the chevron is lime exactly while the grounded sled is inside the hop window', () => {
    const at = (dx, extra) => planTelegraph([hz('glitchChasm', 1000 + dx)], sled(1000, 800, extra), FAR)[0];
    expect(at(800 * 0.5)).toMatchObject({ state: 'warn', color: 'danger' });
    expect(at(800 * 0.37)).toMatchObject({ state: 'go', color: 'lime' });
    expect(at(800 * 0.14)).toMatchObject({ state: 'go', color: 'lime' });
    expect(at(800 * 0.12)).toMatchObject({ state: 'warn', color: 'danger' }); // too late: back to red
    expect(at(800 * 0.37, { grounded: false })).toMatchObject({ state: 'warn', color: 'danger' }); // cannot hop in the air
  });
  test('never for air hazards, hit hazards, hazards behind the sled or muted (warded) hazards', () => {
    const s = sled(1000, 650);
    expect(planTelegraph([hz('roguePacket', 1500)], s, FAR)).toEqual([]);
    expect(planTelegraph([hz('packetSpike', 1500, { hit: true })], s, FAR)).toEqual([]);
    expect(planTelegraph([hz('packetSpike', 1000)], s, FAR)).toEqual([]);
    expect(planTelegraph([hz('packetSpike', 900)], s, FAR)).toEqual([]);
    const warded = hz('overflowFirewall', 1500);
    expect(planTelegraph([warded, hz('packetSpike', 1600)], s, FAR, { isMuted: (h) => h === warded }).map((m) => m.kind)).toEqual(['hop']);
  });
  test('nearest first, capped at maxMarks, urgency rises from 0 at the warn distance to 1 at the box', () => {
    const list = [];
    for (let i = 0; i < GROUND_WARN.maxMarks + 3; i++) list.push(hz('packetSpike', 2000 - i * 100));
    const marks = planTelegraph(list, sled(1000, 650), FAR);
    expect(marks.length).toBe(GROUND_WARN.maxMarks);
    for (let i = 1; i < marks.length; i++) expect(marks[i].dx).toBeGreaterThan(marks[i - 1].dx);
    expect(marks[0].dx).toBe(1000 - (GROUND_WARN.maxMarks + 2) * 100);
    const u = (dx) => planTelegraph([hz('packetSpike', 1000 + dx)], sled(1000, 650), FAR)[0].urgency;
    expect(u(1300)).toBeCloseTo(0, 6);
    expect(u(650)).toBeCloseTo(0.5, 6);
    expect(u(1)).toBeGreaterThan(0.99);
  });
  test('onScreen: the marker rides the screen edge until the hazard box enters the view', () => {
    const h = hz('packetSpike', 1600);
    expect(planTelegraph([h], sled(1000, 650), 1500)[0].onScreen).toBe(false);
    expect(planTelegraph([h], sled(1000, 650), 1589)[0].onScreen).toBe(false);
    expect(planTelegraph([h], sled(1000, 650), 1591)[0].onScreen).toBe(true); // left edge of the 20 px box is at 1590
  });
  test('airborne and forecast to land well past the hazard: marked clear (drawn dim, no sound); landing short is a normal warning', () => {
    const h = hz('packetSpike', 1400);
    const over = planTelegraph([h], sled(1000, 700, { grounded: false, landX: 1400 + 10 + GROUND_WARN.clearMarginPx + 1 }), FAR)[0];
    expect(over).toMatchObject({ clear: true, state: 'clear' });
    const short = planTelegraph([h], sled(1000, 700, { grounded: false, landX: 1400 + 10 + GROUND_WARN.clearMarginPx - 1 }), FAR)[0];
    expect(short).toMatchObject({ clear: false, state: 'warn', color: 'danger' });
    expect(planTelegraph([h], sled(1000, 700, { grounded: false, landX: null }), FAR)[0].clear).toBe(false);
    expect(planTelegraph([h], sled(1000, 700, { grounded: true, landX: 9999 }), FAR)[0].clear).toBe(false);
  });
  test('accepts any iterable and does not mutate its input', () => {
    const h = Object.freeze(hz('packetSpike', 1500));
    expect(planTelegraph(new Set([h]), sled(1000, 650), FAR).length).toBe(1);
  });
});

describe('TelegraphTracker: each sound once per hazard', () => {
  const plan = (list, s) => planTelegraph(list, s, FAR);
  test('warn fires once when a hazard is first announced, go fires once when it first turns lime', () => {
    const tr = new TelegraphTracker();
    const h = hz('packetSpike', 2000);
    const log = [];
    let x = 600;
    for (let t = 0; t < 3000 && x < 2000; t += 16) { x += 700 * 0.016; for (const e of tr.update(t, plan([h], sled(x, 700)))) log.push({ ...e, x }); }
    expect(log.map((e) => e.type)).toEqual(['warn', 'go']);
    expect(log[0]).toMatchObject({ kind: 'hop', ref: h, sound: true });
    expect(2000 - log[0].x).toBeGreaterThan(1380); // announced at the 1400 px warn distance (2 s at 700 px/s)
    expect((2000 - log[1].x) / 700).toBeLessThanOrEqual(0.38);
    expect((2000 - log[1].x) / 700).toBeGreaterThan(0.36);
  });
  test('a brace hazard warns (kind brace) and never cues a hop', () => {
    const tr = new TelegraphTracker();
    const h = hz('overflowFirewall', 1200);
    const ev = [];
    for (let x = 0; x < 1200; x += 10) ev.push(...tr.update(x, plan([h], sled(x, 600))));
    expect(ev.map((e) => [e.type, e.kind])).toEqual([['warn', 'brace']]);
  });
  test('warn sounds are rate limited (two hazards announced in the same frame: one sound), events are not', () => {
    const tr = new TelegraphTracker();
    const ev = tr.update(1000, plan([hz('packetSpike', 1500), hz('glitchChasm', 1700)], sled(1000, 650)));
    expect(ev.map((e) => e.type)).toEqual(['warn', 'warn']);
    expect(ev.map((e) => e.sound)).toEqual([true, false]);
    const later = tr.update(1000 + GROUND_WARN.warnGapMs, plan([hz('packetSpike', 1900)], sled(1000, 650)));
    expect(later[0].sound).toBe(true);
  });
  test('a clear mark makes no sound until it stops being clear', () => {
    const tr = new TelegraphTracker();
    const h = hz('packetSpike', 1400);
    expect(tr.update(0, plan([h], sled(1000, 700, { grounded: false, landX: 2000 })))).toEqual([]);
    expect(tr.update(16, plan([h], sled(1010, 700, { grounded: false, landX: 1300 }))).map((e) => e.type)).toEqual(['warn']);
  });
  test('firstWarnMs records when each hazard was first announced (the measured telegraph lead)', () => {
    const tr = new TelegraphTracker();
    const h = hz('packetSpike', 1500);
    expect(tr.firstWarnMs(h)).toBe(null);
    tr.update(420, plan([h], sled(1000, 650)));
    tr.update(900, plan([h], sled(1300, 650)));
    expect(tr.firstWarnMs(h)).toBe(420);
  });
});/**
 * Marvin decision 4 (2026-11-14): "Buff Head Start to provide a noticeable opening advantage while keeping
 * runs MODDED." Before, it scaled only the 50 px/s spawn velocity by 1.25 (+1.7 % distance at 5 s).
 *
 * Now Head Start is a real launch plus a short opening surge:
 *  - `speedFactor` (still the launch multiplier on the spawn velocity, through Sled.scaleVelocity) is large;
 *  - `headStartOpening` gives a speed multiplier for the opening seconds, fed to PhysicsTuner's existing
 *    `speedBoost` context (the Packet Burst path: drag scaling, no physics constant touched);
 *  - `openingSpeedMul` fades it out and returns exactly 1 afterwards: no permanent speed buff.
 * The gate (tools/sim/gate-playthrough.mjs) proves the result on the real sled: >= +15 % distance at 10 s.
 */
import {
  BOOST_DEFS, boostEffects, headStartOpening, openingSpeedMul, isModdedRun,
} from '../../src/systems/Boosts.js';

const OWNED = { unlocked: { errorCorrection: 15, headStart: 8 } };
const HS = { boosts: { headStart: true } };

describe('Head Start launch', () => {
  test('the launch multiplier is substantial (was 1.25)', () => {
    expect(BOOST_DEFS.headStart.speedFactor).toBeGreaterThanOrEqual(4);
    expect(boostEffects(HS, OWNED).speedFactor).toBe(BOOST_DEFS.headStart.speedFactor);
  });
});

describe('headStartOpening', () => {
  test('an owned Head Start gives an opening surge with a finite window', () => {
    const o = headStartOpening(HS, OWNED);
    expect(o.speedMul).toBeGreaterThan(1);
    expect(o.ms).toBeGreaterThan(0);
    expect(o.ms).toBeLessThanOrEqual(10000);
    expect(o.fadeMs).toBeGreaterThan(0);
    expect(o.fadeMs).toBeLessThanOrEqual(o.ms);
  });

  test('no surge when Head Start is off, not owned, or on the official Daily', () => {
    const none = { speedMul: 1, ms: 0, fadeMs: 0 };
    expect(headStartOpening({}, OWNED)).toEqual(none);
    expect(headStartOpening({ boosts: { errorCorrection: true } }, OWNED)).toEqual(none);
    expect(headStartOpening(HS, { unlocked: {} })).toEqual(none);
    expect(headStartOpening(HS)).toEqual(none);
    expect(headStartOpening(HS, { ...OWNED, daily: true })).toEqual(none);
  });

  test('a run with the surge is always MODDED (same rule as the launch)', () => {
    expect(headStartOpening(HS, OWNED).speedMul).toBeGreaterThan(1);
    expect(isModdedRun(HS, OWNED)).toBe(true);
    expect(isModdedRun(HS, { ...OWNED, daily: true })).toBe(false);
  });
});

describe('openingSpeedMul: full, then a fade, then exactly 1 forever', () => {
  const o = headStartOpening(HS, OWNED);

  test('full strength from the start until the fade begins', () => {
    expect(openingSpeedMul(o, 0)).toBe(o.speedMul);
    expect(openingSpeedMul(o, o.ms - o.fadeMs)).toBe(o.speedMul);
  });

  test('fades monotonically to 1 by the end of the window', () => {
    let prev = o.speedMul;
    for (let t = o.ms - o.fadeMs; t <= o.ms; t += o.fadeMs / 10) {
      const m = openingSpeedMul(o, t);
      expect(m).toBeLessThanOrEqual(prev + 1e-12);
      expect(m).toBeGreaterThanOrEqual(1);
      prev = m;
    }
    expect(openingSpeedMul(o, o.ms)).toBe(1);
  });

  test('no permanent buff: exactly 1 after the window, at any later time', () => {
    for (const t of [o.ms, o.ms + 1, 20000, 60000, 1e7]) expect(openingSpeedMul(o, t)).toBe(1);
  });

  test('junk input is neutral', () => {
    for (const bad of [null, undefined, {}, { speedMul: NaN, ms: 5000 }, { speedMul: 0.5, ms: 5000, fadeMs: 1000 }]) {
      expect(openingSpeedMul(bad, 100)).toBe(1);
    }
    expect(openingSpeedMul(o, NaN)).toBe(1);
    expect(openingSpeedMul(o, -5)).toBe(o.speedMul);
  });
});import { HintScheduler, HINT_DEFS } from '../../src/systems/HintScheduler.js';

/** Drive the scheduler at 60 Hz with a wants(t) function; returns the event log [{t,id,show}]. */
function run(sch, fromMs, toMs, wantsAt, dangerAt = () => false) {
  const log = [];
  for (let t = fromMs; t <= toMs; t += 16) {
    for (const e of sch.update(t, wantsAt(t), dangerAt(t))) log.push({ t, ...e });
  }
  return log;
}
const shownSpans = (log) => {
  const up = {}; const spans = [];
  for (const e of log) { if (e.show) up[e.id] = e.t; else spans.push({ id: e.id, from: up[e.id], to: e.t }); }
  return spans;
};

describe('HintScheduler', () => {
  test('nothing shows before startMs except early hints', () => {
    const s = new HintScheduler();
    const log = run(s, 0, 2000, () => ({ hop: true, tuck: true, push: false }));
    expect(log).toEqual([]);
    const s2 = new HintScheduler();
    expect(run(s2, 0, 100, () => ({ push: true, hop: true }))[0]).toMatchObject({ id: 'push', show: true });
  });

  test('a hint stays at least minMs even when its trigger vanishes at once', () => {
    const s = new HintScheduler();
    const log = run(s, 3000, 9000, (t) => ({ flip: t < 3200 }));
    const [sp] = shownSpans(log);
    expect(sp.id).toBe('flip');
    expect(sp.to - sp.from).toBeGreaterThanOrEqual(HINT_DEFS.flip.minMs);
    expect(sp.to - sp.from).toBeLessThan(HINT_DEFS.flip.minMs + 40);
  });

  test('never two at once, gap after hide, priority order, hide after maxMs even if trigger stays', () => {
    const s = new HintScheduler();
    const log = run(s, 3000, 30000, () => ({ tuck: true, flip: true, hop: true }));
    let up = 0;
    for (const e of log) { up += e.show ? 1 : -1; expect(up).toBeLessThanOrEqual(1); }
    expect(log[0]).toMatchObject({ id: 'hop', show: true });
    const spans = shownSpans(log);
    for (let i = 1; i < spans.length; i++) expect(spans[i].from - spans[i - 1].to).toBeGreaterThanOrEqual(s.gapMs);
    for (const sp of spans) expect(sp.to - sp.from).toBeLessThanOrEqual(HINT_DEFS[sp.id].maxMs + 40);
    // a timed-out hint with a permanently-true trigger does not come back
    expect(log.filter((e) => e.show && e.id === 'hop').length).toBe(1);
  });

  test('a higher-priority want replaces the current hint only after its minimum', () => {
    const s = new HintScheduler();
    const log = run(s, 3000, 8000, (t) => ({ tuck: true, hop: t >= 3500 }));
    const hop = log.find((e) => e.id === 'hop' && e.show);
    const tuckUp = log.find((e) => e.id === 'tuck' && e.show).t;
    expect(hop.t - tuckUp).toBeGreaterThanOrEqual(HINT_DEFS.tuck.minMs);
  });

  test('danger holds back non-danger hints; danger hints still show', () => {
    const s = new HintScheduler();
    expect(run(s, 3000, 5000, () => ({ flip: true }), () => true)).toEqual([]);
    expect(run(s, 5016, 6000, () => ({ hop: true, flip: true }), () => true)[0]).toMatchObject({ id: 'hop' });
  });

  test('complete() hides immediately, below minMs, and the hint never returns', () => {
    const s = new HintScheduler();
    run(s, 3000, 3100, () => ({ hop: true }));
    expect(s.currentId).toBe('hop');
    expect(s.complete('hop', 3200)).toEqual([{ id: 'hop', show: false }]);
    expect(run(s, 3216, 9000, () => ({ hop: true }))).toEqual([]);
    expect(s.complete('hop', 9100)).toEqual([]);
  });

  test('done ids from storage never show; perRun caps repeats', () => {
    const s = new HintScheduler({ done: new Set(['flip']) });
    const log = run(s, 3000, 40000, () => ({ flip: true, tuck: true }));
    expect(log.some((e) => e.id === 'flip')).toBe(false);
    expect(log.filter((e) => e.show && e.id === 'tuck').length).toBe(1);
  });

  test('trigger that goes false then true again re-arms a timed-out hint', () => {
    const s = new HintScheduler();
    const log = run(s, 3000, 20000, (t) => ({ flip: (t % 8000) < 6500 }));
    expect(log.filter((e) => e.show && e.id === 'flip').length).toBeGreaterThanOrEqual(2);
  });
});import { readFileSync } from 'node:fs';
import { HISTORICAL_TAPE_BYTES, HISTORICAL_TAPE_SHA256, validatePinnedHistoricalAirtimeTape } from '../../tools/qa/historical-airtime-guards.js';

const fixture = readFileSync(new URL('../../tools/conformance/fixtures/cross-engine/collision-heavy.tape.json', import.meta.url));

describe('historical airtime fixture pin', () => {
  test('accepts only the original fixture and preserves its native older tape header', () => {
    expect(fixture.length).toBe(HISTORICAL_TAPE_BYTES);
    expect(HISTORICAL_TAPE_SHA256).toMatch(/^[a-f0-9]{64}$/);
    const tape = validatePinnedHistoricalAirtimeTape(fixture);
    expect(tape).toEqual(JSON.parse(fixture.toString('utf8')));
    expect(tape).toMatchObject({ kodiakVersion: 2, seed: 'CE120-BUMP3', endTick: 1668 });
    expect(tape.checkpoints.map(row => row[0])).toEqual(Array.from({ length: 13 }, (_, i) => (i + 1) * 120));
  });

  test('rejects a same-length byte change, even when the JSON remains valid', () => {
    const altered = Buffer.from(fixture);
    altered[altered.indexOf('CE120-BUMP3')] = 'B'.charCodeAt(0);
    expect(() => JSON.parse(altered.toString('utf8'))).not.toThrow();
    expect(() => validatePinnedHistoricalAirtimeTape(altered)).toThrow('exact committed synthetic');
  });

  test.each([
    ['short', fixture.subarray(0, -1)],
    ['padded', Buffer.concat([fixture, Buffer.from(' ')])],
    ['wrong type', fixture.toString('utf8')],
  ])('rejects %s input', (_, bytes) => {
    expect(() => validatePinnedHistoricalAirtimeTape(bytes)).toThrow('exact committed synthetic');
  });
});import { rectsHit, stackY, placeX, bandHits, placeBand } from '../../src/ui/HudLayout.js';
import { measureText } from '../../src/ui/PixelFont.js';
import { fmtInt } from '../../src/ui/Format.js';

describe('HudLayout.stackY', () => {
  test('keeps classic positions when nothing collides', () => {
    const ys = stackY([{ w: 100, h: 24, pref: 24 }, { w: 100, h: 16, pref: 80 }], { cx: 240, gap: 3 });
    expect(ys).toEqual([24, 80]);
  });
  test('pushes simultaneous banners into separate slots (no overlap, order kept)', () => {
    const items = [{ w: 216, h: 24, pref: 24 }, { w: 228, h: 16, pref: 46 }, { w: 300, h: 16, pref: 80 }, { w: 120, h: 8, pref: 100 }];
    const ys = stackY(items, { cx: 240, gap: 3 });
    for (let i = 1; i < ys.length; i++) expect(ys[i]).toBeGreaterThanOrEqual(ys[i - 1] + items[i - 1].h + 3);
  });
  test('moves a wide item below keep-out rectangles it would hit, but not a narrow one', () => {
    const keep = [{ x: 8, y: 0, w: 120, h: 60 }, { x: 352, y: 0, w: 120, h: 76 }];
    const [wide, narrow] = stackY([{ w: 440, h: 16, pref: 24 }, { w: 100, h: 16, pref: 24 }], { cx: 240, gap: 3, keepOuts: keep });
    expect(wide).toBeGreaterThanOrEqual(79);
    expect(narrow).toBeGreaterThanOrEqual(wide + 16 + 3);
    const [only] = stackY([{ w: 100, h: 16, pref: 24 }], { cx: 240, gap: 3, keepOuts: keep });
    expect(only).toBe(24);
  });
  test('widest realistic banners never intersect fixed HUD rows or each other', () => {
    const scoreW = measureText(fmtInt(9999999)) * 2;
    const left = [{ x: 8, y: 13, w: scoreW, h: 16 }, { x: 8, y: 31, w: measureText('99,999 M'), h: 8 }, { x: 8, y: 41, w: measureText('432 KM/H'), h: 8 }];
    const pendW = measureText(`+${fmtInt(2999970)}`) * 2;
    const right = [{ x: 472 - pendW, y: 43, w: pendW, h: 16 }, { x: 472 - measureText('FLOW x3.00'), y: 62, w: measureText('FLOW x3.00'), h: 8 }];
    const keep = [...left, ...right];
    const items = [
      { w: measureText('BOOST +1,234') * 3, h: 24, pref: 24 }, { w: measureText('PERFECT LANDING +20') * 2, h: 16, pref: 46 },
      { w: 17 * 12, h: 16, pref: 59 }, { w: 440, h: 16, pref: 80 }, { w: measureText('NEW BACKFLIP X2 +150'), h: 8, pref: 100 },
    ];
    const ys = stackY(items, { cx: 240, gap: 3, keepOuts: keep });
    items.forEach((it, i) => {
      const box = { x: 240 - it.w / 2, y: ys[i], w: it.w, h: it.h };
      for (const k of keep) expect(rectsHit(box, k)).toBe(false);
      if (i) expect(ys[i]).toBeGreaterThanOrEqual(ys[i - 1] + items[i - 1].h);
    });
  });
});

describe('HudLayout.placeX', () => {
  test('returns the preferred left when free and the nearest free spot otherwise', () => {
    expect(placeX(100, 240, 20, 8, [], { min: 8, max: 472 })).toBe(8);
    const touch = [{ x: 4, y: 170, w: 108, h: 94 }];
    expect(placeX(100, 242, 20, 8, touch, { min: 8, max: 472 })).toBe(115);
  });
  test('returns null when the row is blocked', () => {
    expect(placeX(100, 240, 20, 8, [{ x: 0, y: 230, w: 480, h: 40 }], { min: 0, max: 480 })).toBeNull();
  });
});

describe('HudLayout.placeBand — a full-width band must not paint through the HUD rows', () => {
  // The W2 defect: the mission toast strip is a full-width band, so its measured text missing the
  // fixed rows is not enough - its background fill crossed them and drew over "FLOW x1.25".
  const FLOW = { x: 380, y: 62, w: 92, h: 8 }; // flowText at FLOW_Y = 62, right-anchored
  const SCORE = { x: 4, y: 4, w: 120, h: 8 };

  test('a band that clears every row stays at its preferred y', () => {
    expect(placeBand(17, 100, [FLOW, SCORE])).toBe(100);
  });

  test('a band crossing a fixed row is pushed below it', () => {
    // 59 is the classic strip position and it crosses FLOW (62..70).
    const y = placeBand(17, 59, [FLOW]);
    expect(y).toBeGreaterThanOrEqual(FLOW.y + FLOW.h);
    expect(bandHits({ y, h: 17 }, [FLOW])).toBe(false);
  });

  test('bandHits is true for a band overlapping a row even if its own text would fit', () => {
    // The whole point: a narrow measured text does not save a full-width band.
    expect(bandHits({ y: 59, h: 17 }, [FLOW])).toBe(true);
    expect(bandHits({ y: 40, h: 17 }, [FLOW])).toBe(false);
  });

  test('it stacks below several rows in turn, not just the first', () => {
    const rows = [{ x: 0, y: 50, w: 480, h: 10 }, { x: 0, y: 63, w: 480, h: 10 }];
    const y = placeBand(16, 40, rows);
    expect(bandHits({ y, h: 16 }, rows)).toBe(false);
    expect(y).toBeGreaterThanOrEqual(73);
  });

  test('it never runs off the bottom of the screen', () => {
    // A pathological keep-out must clamp rather than place the band at y=400 on a 270 px screen.
    const tall = { x: 0, y: 0, w: 480, h: 260 };
    expect(placeBand(17, 59, [tall], { maxY: 270 })).toBeLessThanOrEqual(270);
  });

  test('no keep-outs means no movement', () => {
    expect(placeBand(17, 59, [])).toBe(59);
  });
});import { jest } from '@jest/globals';
import { spawnSync } from 'node:child_process';
import { Rng } from '../../src/systems/Rng.js';
import {
  DEFAULT_NOISE_SEED, FATIGUE_RAMP, NOISE_PROFILES, fatigueAtFrame, makeHopNoise, noiseOutcome, summarizeNoise, verifyNoiseEvidence,
} from '../../tools/sim/human-noise.js';

function sample(profile, noiseSeed = DEFAULT_NOISE_SEED, courseSeed = 'sim-01') {
  const planner = makeHopNoise(profile, courseSeed, noiseSeed);
  const frames = [];
  for (let frame = 0; frame < 2400; frame++) {
    if (planner.step(frame, frame % 40 === 0)) frames.push(frame);
  }
  return { frames, stats: planner.stats() };
}

test('ideal passes each hop intent immediately and introduces no misses or other controls', () => {
  const ideal = sample('ideal');
  expect(ideal.frames).toEqual(Array.from({ length: 60 }, (_, i) => i * 40));
  expect(ideal.stats).toEqual({
    intents: 60, missed: 0, sent: 60, coalesced: 0, delayFrames: 0, pendingAtEnd: false,
  });
});

test('seeded profile jitter and misses repeat and do not draw from global randomness', () => {
  const random = jest.spyOn(Math, 'random').mockImplementation(() => {
    throw new Error('Must not use the global RNG');
  });
  try {
    for (const profile of ['steady', 'distracted']) {
      const result = sample(profile);
      expect(result).toEqual(sample(profile));
      expect(result).not.toEqual(sample(profile, 'another-seed'));
      expect(result).not.toEqual(sample(profile, DEFAULT_NOISE_SEED, 'sim-02'));
      const spec = NOISE_PROFILES[profile];
      const offsets = result.frames.map((frame) => frame % 40);
      expect(offsets.every((offset) => offset >= spec.minDelayFrames && offset <= spec.maxDelayFrames)).toBe(true);
      expect(new Set(offsets).size).toBeGreaterThan(1);
      expect(result.stats.delayFrames).toBe(offsets.reduce((a, b) => a + b, 0));
      expect(result.stats.missed).toBeGreaterThan(0);
      expect(result.stats.sent + result.stats.missed).toBe(60);
    }
  } finally { random.mockRestore(); }
});

test('pending reactions do not stack simultaneous presses or fire twice', () => {
  const planner = makeHopNoise('steady', 'sim-01');
  const first = sample('steady').frames[0];
  expect(first).toBeLessThan(8); // this seed schedules the first intent
  expect(planner.step(0, true)).toBe(false);
  expect(planner.step(1, true)).toBe(false);
  const delivered = [];
  for (let frame = 2; frame < 12; frame++) {
    if (planner.step(frame, false)) delivered.push(frame);
  }
  expect(delivered).toEqual([first]);
  expect(planner.stats()).toMatchObject({ coalesced: 1, sent: 1, pendingAtEnd: false });
  expect(() => planner.step(11, false)).toThrow(/increasing/);
  expect(() => makeHopNoise('toString', 'sim-01')).toThrow(/unknown/i);
});

test('the fatigue ramp starts at 6 simulated seconds, reaches full at 18 and clamps', () => {
  expect(FATIGUE_RAMP).toMatchObject({ frameHz: 60, startFrame: 360, fullFrame: 1080,
    maxAddedDelayFrames: 6, maxAddedMissProbability: .16, unaffectedProfile: 'ideal' });
  const fresh = { phase: 'preRamp', delayFrames: 0, missProbability: 0 };
  expect(fatigueAtFrame(0)).toEqual(fresh);
  expect(fatigueAtFrame(360)).toEqual(fresh);
  expect(fatigueAtFrame(361)).toMatchObject({ phase: 'ramp', delayFrames: 0 });
  expect(fatigueAtFrame(361).missProbability).toBeGreaterThan(0);
  expect(fatigueAtFrame(720)).toEqual({ phase: 'ramp', delayFrames: 3, missProbability: .08 });
  expect(fatigueAtFrame(1079).delayFrames).toBe(5);
  expect(fatigueAtFrame(1080)).toEqual({ phase: 'capped', delayFrames: 6, missProbability: .16 });
  expect(fatigueAtFrame(1800)).toEqual(fatigueAtFrame(1080));
  expect(() => fatigueAtFrame(NaN)).toThrow(/simulated frame/);
});

function planned(profile, course, intentFrames, fatigue) {
  const planner = makeHopNoise(profile, course, DEFAULT_NOISE_SEED, { fatigue });
  const frames = [];
  // Only simulated frame indices, not wall time or number of prior calls.
  for (let frame = Math.min(...intentFrames); frame <= Math.max(...intentFrames) + 30; frame++) {
    if (planner.step(frame, intentFrames.includes(frame))) frames.push(frame);
  }
  return { frames, ...planner.stats() };
}

test.each([false, true])('coalesces an intent on the pending dispatch frame with fatigue=%s', (fatigue) => {
  const firstIntent = FATIGUE_RAMP.startFrame - 1;
  const [dispatch] = planned('steady', 'sim-01', [firstIntent], fatigue).frames;
  expect(dispatch).toBeGreaterThan(FATIGUE_RAMP.startFrame);
  const intents = [firstIntent, 420, 600, 720, 1080, 1600];
  const chance = jest.spyOn(Rng.prototype, 'chance');
  const delay = jest.spyOn(Rng.prototype, 'int');
  try {
    const control = planned('steady', 'sim-01', intents, fatigue);
    const chanceCalls = chance.mock.calls.slice(), delayCalls = delay.mock.calls.slice();
    expect(chanceCalls.length).toBe(intents.length);
    expect(delayCalls.length).toBeGreaterThan(1);
    expect(control.frames).toContain(dispatch);
    expect(control.frames.at(-1)).toBeGreaterThan(dispatch);
    chance.mockClear();
    delay.mockClear();

    const paired = planned('steady', 'sim-01', [firstIntent, dispatch, ...intents.slice(1)], fatigue);
    expect(paired).toEqual({ ...control, intents: control.intents + 1, coalesced: control.coalesced + 1 });
    expect(chance.mock.calls).toEqual(chanceCalls);
    expect(delay.mock.calls).toEqual(delayCalls);
  } finally {
    chance.mockRestore();
    delay.mockRestore();
  }
});

test('early and already planned presses stay identical, and the ideal control stays unchanged at all phases', () => {
  const base = planned('steady', 'sim-01', [359], false);
  const { fatigue, ...early } = planned('steady', 'sim-01', [359], true);
  expect(early).toEqual(base);
  expect(early.frames[0]).toBeGreaterThan(FATIGUE_RAMP.startFrame); // pending press crossed the boundary
  expect(fatigue).toEqual({ applies: true, phaseIntents: { preRamp: 1, ramp: 0, capped: 0 }, addedDelayFrames: 0 });
  const intents = [0, 361, 720, 1080, 2000];
  const { fatigue: control, ...ideal } = planned('ideal', 'sim-01', intents, true);
  expect(ideal).toEqual(planned('ideal', 'sim-01', intents, false));
  expect(ideal.frames).toEqual(intents);
  expect(control).toEqual({ applies: false, phaseIntents: { preRamp: 0, ramp: 0, capped: 0 }, addedDelayFrames: 0 });
});

test('late noisy intents can gain delay or miss; no extra randomness or cross-run state', () => {
  const guard = jest.spyOn(Math, 'random').mockImplementation(() => { throw new Error('No global randomness'); });
  try {
    const base = planned('steady', 'sim-01', [1080], false);
    const delayed = planned('steady', 'sim-01', [1080], true);
    expect(delayed.frames).toEqual([base.frames[0] + 6]);
    expect(delayed.fatigue).toEqual({ applies: true, phaseIntents: { preRamp: 0, ramp: 0, capped: 1 }, addedDelayFrames: 6 });
    expect(delayed).toEqual(planned('steady', 'sim-01', [1080], true));
    expect(planned('steady', 'sim-11', [1080], false).sent).toBe(1);
    expect(planned('steady', 'sim-11', [1080], true)).toMatchObject({ sent: 0, missed: 1 });
    expect(planned('steady', 'sim-01', [0], true).frames).toEqual(base.frames.map((f) => f - 1080));
  } finally { guard.mockRestore(); }
});

test('keeps crashes, deadlines and stalls in the denominator rather than calling them passes', () => {
  const runs = ['maxM', 'crash:hazard', 'timeout', 'stalled'].map((endReason) => ({ endReason }));
  expect(summarizeNoise(runs)).toEqual({ trials: 4, pass: 1, crash: 1, timeout: 1, stalled: 1, passRate: .25 });
  expect(summarizeNoise([]).passRate).toBeNull();
  expect(() => noiseOutcome('browser error')).toThrow();
});

test('verification compares actual tick input and outcomes, ignoring only wall time and playback-only loss of planner stats', () => {
  const record = {
    wallMs: 40, endReason: 'maxM', distM: 191, trace: [[1, 2, 3, 0]],
    humanNoise: { stats: { sent: 1 }, input: { ticks: 20, rows: [[1, 0, 0], [12, 128, 0]] }, final: { score: 90 } },
  };
  const borrowed = { ...record.humanNoise, stats: null };
  expect(verifyNoiseEvidence(record, { ...record, wallMs: 90 })).toBe(true);
  expect(verifyNoiseEvidence(record, { ...record, humanNoise: borrowed })).toBe(false);
  expect(verifyNoiseEvidence(record, { ...record, humanNoise: borrowed }, { playback: true })).toBe(true);
  expect(verifyNoiseEvidence(record, {
    ...record, humanNoise: { ...borrowed, input: { ticks: 20, rows: [[1, 0, 0], [13, 128, 0]] } },
  }, { playback: true })).toBe(false);
  expect(verifyNoiseEvidence(record, { ...record, endReason: 'timeout' }, { playback: true })).toBe(false);
});

test('CLI rejects unsafe or accidental unpaired panel options before browser startup', () => {
  const failedArgs = [
    ['--noiseProfiles', 'steady'],
