});import { spawnSync } from 'node:child_process';
import { mkdtempSync, rmSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { GhostRecorder } from '../../src/systems/ghost/GhostTape.js';
import { runRandomState, runRandomStreams } from '../../src/systems/RunRandom.js';
import { MAX_AIRTIME_FILE_BYTES } from '../../tools/sim/replay-airtime.js';
import { evaluateInputConstraints, hopEdgeBudget } from '../../tools/sim/input-constraints.js';

function codecFixture(changes = []) {
  const seed = 'private-synthetic-fixture', startedAt = Date.UTC(2026, 0, 5, 12);
  const body = { position: { x: 2, y: 3 }, angle: 0, velocity: { x: 2, y: 1 }, angularVelocity: 0 };
  const recorder = new GhostRecorder({
    seed, biomeMask: 0, mode: 'normal', startedAt, dailyRuleId: 'featherweight', controlLayout: 'tricksRight',
    boosts: [], upgradeRanks: null, magnetsDrop: false, kodiaksOn: false, kodiakPackMode: 'same', kodiakVersion: 3,
    startPose: [2, 3, 0, 2, 1, 0], random: runRandomState(runRandomStreams(seed)),
  });
  const scene = { sled: { body }, score: { getTotal: () => 1 } };
  for (let tick = 1; tick <= 245; tick++) recorder.afterTick(tick, scene);
  for (const [tick, pad] of [[1, {}], ...changes]) recorder.input(tick, { variableHop: true, noAutoNudge: true, ...pad });
  return recorder.finish({ runId: `${startedAt}-${seed}`, distanceM: 12, score: 12, endedAt: startedAt + 2050 });
}
const results = (x) => x.candidates.map(({ met }) => met);

test('neutral layout configuration is not an action and produces three versioned candidate manifests', () => {
  const tape = codecFixture();
  expect(tape.inputs).toEqual([[1, 6, 0]]);
  const audit = evaluateInputConstraints(tape);
  expect(audit).toEqual({ observed: {
    hop: { heldTicks: 0, pressEdges: 0, requestedTicks: 0 }, parachute: { heldTicks: 0, pressEdges: 0, requestedTicks: 0 },
  }, candidates: [
    { id: 'no-hop-request', version: 1, input: 'hop', metric: 'requestedTicks', max: 0, met: true },
    { id: 'no-parachute-request', version: 1, input: 'parachute', metric: 'requestedTicks', max: 0, met: true },
    { id: 'hop-edge-budget', version: 1, input: 'hop', metric: 'pressEdges', max: 2, met: true },
  ] });
  expect(JSON.stringify(audit)).not.toContain(tape.seed);
});

test('a sparse hold persists, one-shot is counted once, and terminal-only requests are audited', () => {
  const tape = codecFixture([[10, { hop: true, pressed: { hop: true } }], [20, { hop: true, tilt: .5 }], [28, {}],
    [245, { pressed: { hop: true } }], [246, { pressed: { parachute: true } }]]);
  const audit = evaluateInputConstraints(tape);
  expect(audit.observed).toEqual({ hop: { heldTicks: 18, pressEdges: 2, requestedTicks: 19 },
    parachute: { heldTicks: 0, pressEdges: 1, requestedTicks: 1 } });
  expect(results(audit)).toEqual([false, false, true]);
  expect(results(evaluateInputConstraints(tape, 1))).toEqual([false, false, false]);
});

test('held-only controls are requests but not presses, including a held action through the fatal tick', () => {
  const tape = codecFixture([[243, { hop: true, parachute: true }]]);
  const audit = evaluateInputConstraints(tape, 0);
  expect(audit.observed.hop).toEqual({ heldTicks: 4, pressEdges: 0, requestedTicks: 4 });
  expect(audit.observed.parachute).toEqual(audit.observed.hop);
  expect(results(audit)).toEqual([false, false, true]);
});

test('three explicit edges exceed two, even across adjacent changed rows without a held bit', () => {
  const tape = codecFixture([[4, { tilt: .5, pressed: { hop: true } }], [5, { tilt: -.5, pressed: { hop: true } }],
    [246, { pressed: { hop: true } }]]);
  const audit = evaluateInputConstraints(tape, 2);
  expect(audit.observed.hop).toEqual({ heldTicks: 0, pressEdges: 3, requestedTicks: 3 });
  expect(results(audit)).toEqual([false, true, false]);
  expect(results(evaluateInputConstraints(tape, 3))).toEqual([false, true, true]);
});

test('input after the reproduced fatal boundary is outside the supported tape subset', () => {
  expect(() => evaluateInputConstraints(codecFixture([[247, { pressed: { hop: true } }]]))).toThrow(/invalid saved input/i);
});

test('budget is an explicit bounded base-ten integer only', () => {
  expect(['0', '1', '120', undefined].map(hopEdgeBudget)).toEqual([0, 1, 120, 2]);
  for (const invalid of ['-0', ' 2', '02', '2e0', '2.0', '0x02', '121', '', null]) {
    expect(() => hopEdgeBudget(invalid)).toThrow(/0 to 120/);
  }
});

test('CLI rejects unverified or malformed requests without receipt or private arguments', () => {
  const tool = 'tools/sim/verify-input-constraints.mjs', pin = 'a'.repeat(40);
  const launch = (...args) => spawnSync(process.execPath, [tool, ...args], { encoding: 'utf8' });
  const scratch = mkdtempSync(join(tmpdir(), 'bb-constraint-private-'));
  const path = join(scratch, 'private.json');
  try {
    const base = ['--build', pin, '--tape', path];
    for (const [args, expected] of [
      [[], 'explicit saved --tape'],
      [['--build', 'user-private-build', '--tape', path], 'full 40-hex'],
      [[...base, '--url', 'https://private.example/'], 'HTTP loopback'],
      [[...base, '--max-hop-edges=private-invalid'], '0 to 120'],
      [[...base, '--user-private-arg'], 'accepted options'],
      [base, 'bounded, complete compatible normal-run tape'],
    ]) {
      const result = launch(...args);
      expect(result).toMatchObject({ status: 1, stdout: '', stderr: expect.stringContaining(expected) });
      expect(result.stderr).not.toMatch(/private|aaaaaa/);
    }
    writeFileSync(path, JSON.stringify({ ...codecFixture(), checkpoints: [[120]] }));
    expect(launch(...base)).toMatchObject({ status: 1, stdout: '', stderr: expect.stringContaining('compatible normal-run tape') });
    writeFileSync(path, Buffer.alloc(MAX_AIRTIME_FILE_BYTES + 1));
    expect(launch(...base)).toMatchObject({ status: 1, stdout: '', stderr: expect.stringContaining('bounded') });
  } finally { rmSync(scratch, { recursive: true, force: true }); }
});/**
 * Issue #211: gamepad alias reachability.
 *
 * `GP_BINDINGS` binds two physical inputs to the same pad button:
 *   LB (button 4) and RSLeft (right stick axis 2 < -0.5)  -> pad 'heliLeft'
 *   RB (button 5) and RSRight (right stick axis 2 > 0.5) -> pad 'heliRight'
 * Every gamepad binding previously wrote the single source id 'gamepad', so releasing
 * one alias removed the source and cancelled the other alias that was still held.
 *
 * These assertions describe the required behaviour: each physical alias must keep the
 * logical button held until every alias bound to it is released.
 */
import { EventEmitter } from 'events';
import { InputRouter } from '../../src/systems/InputRouter.js';
import { defaultSettings } from '../../src/systems/SaveStore.js';
import { EVT } from '../../src/events.js';

const game = () => ({ events: new EventEmitter(), canvas: null, registry: { get: () => undefined } });

/** Fake W3C standard-mapping gamepad. buttons[0..16], axes [LSx, LSy, RSx, RSy]. */
function gamepad(over = {}) {
  return {
    connected: true,
    mapping: 'standard',
    axes: [0, 0, 0, 0],
    buttons: Array.from({ length: 17 }, () => ({ pressed: false, value: 0 })),
    ...over,
  };
}

function hold(g, index, down = true) {
  g.buttons[index] = { pressed: down, value: down ? 1 : 0 };
}

function setup(layout = 'classic') {
  const g = game();
  const router = new InputRouter(g);
  const actions = [];
  g.events.on(EVT.INPUT_ACTION, (p) => actions.push(p));
  router.applySettings({ ...defaultSettings(), controlLayout: layout });
  g.events.emit(EVT.RUN_START);
  return { g, router, actions };
}

const key = (type, code) =>
  window.dispatchEvent(new KeyboardEvent(type, { code, bubbles: true, cancelable: true }));

afterEach(() => {
  delete navigator.getGamepads;
  window.dispatchEvent(new Event('blur'));
});

describe('issue #211: LB and RSLeft share pad heliLeft', () => {
  test('a. LB alone drives heli counter-clockwise', () => {
    const { router } = setup();
    const gp = gamepad();
    navigator.getGamepads = () => [gp];
    hold(gp, 4);
    expect(router.poll().heli).toBe(-1);
    router.destroy();
  });

  test('b. RB alone drives heli clockwise', () => {
    const { router } = setup();
    const gp = gamepad();
    navigator.getGamepads = () => [gp];
    hold(gp, 5);
    expect(router.poll().heli).toBe(1);
    router.destroy();
  });

  test('c. releasing LB keeps the still-deflected right stick holding heliLeft', () => {
    const { router } = setup();
    const gp = gamepad();
    navigator.getGamepads = () => [gp];

    hold(gp, 4);
    expect(router.poll().heli).toBe(-1);

    gp.axes[2] = -1; // RSLeft
    expect(router.poll().heli).toBe(-1);

    hold(gp, 4, false); // release LB only; stick is still deflected
    expect(router.poll().heli).toBe(-1);

    gp.axes[2] = 0; // release the stick too
    expect(router.poll().heli).toBe(0);
    router.destroy();
  });

  test('d. releasing the right stick keeps the still-held LB holding heliLeft', () => {
    const { router } = setup();
    const gp = gamepad();
    navigator.getGamepads = () => [gp];

    hold(gp, 4);
    gp.axes[2] = -1;
    expect(router.poll().heli).toBe(-1);

    gp.axes[2] = 0; // release the stick first; LB is still held
    expect(router.poll().heli).toBe(-1);

    hold(gp, 4, false);
    expect(router.poll().heli).toBe(0);
    router.destroy();
  });

  test('e. losing the gamepad releases every gamepad-held button', () => {
    const { router } = setup();
    const gp = gamepad();
    navigator.getGamepads = () => [gp];

    hold(gp, 0); // A -> hop + confirm
    hold(gp, 4); // LB -> heliLeft
    gp.axes[2] = -1; // RSLeft -> heliLeft too
    const s = router.poll();
    expect(s.heli).toBe(-1);
    expect(s.hop).toBe(true);
    expect(s.pressed.confirm).toBe(true);

    navigator.getGamepads = () => [null];
    const gone = router.poll();
    expect(gone.heli).toBe(0);
    expect(gone.hop).toBe(false);
    // 'confirm' is edge-only in the pad state; assert its held set is empty after the disconnect.
    for (const name of Object.keys(router.pad.held)) {
      expect(router.pad.held[name].has('gamepad')).toBe(false);
    }
    router.destroy();
  });

  test('e. gamepaddisconnected also releases gamepad-held buttons', () => {
    const { router } = setup();
    const gp = gamepad();
    navigator.getGamepads = () => [gp];

    hold(gp, 5); // RB -> heliRight
    expect(router.poll().heli).toBe(1);
    expect(router.poll().pressed.hop).toBe(false);

    navigator.getGamepads = () => [null];
    window.dispatchEvent(new Event('gamepaddisconnected'));
    expect(router.poll().heli).toBe(0);
    router.destroy();
  });

  test('f. keyboard and gamepad holds of heliLeft are independent (gamepad release)', () => {
    const { router } = setup('classic');
    const gp = gamepad();
    navigator.getGamepads = () => [gp];

    key('keydown', 'ArrowLeft'); // keyboard holds heliLeft
    expect(router.poll().heli).toBe(-1);

    hold(gp, 4); // gamepad adds its own hold
    expect(router.poll().heli).toBe(-1);

    hold(gp, 4, false); // releasing gamepad must not cancel the keyboard hold
    expect(router.poll().heli).toBe(-1);

    key('keyup', 'ArrowLeft');
    expect(router.poll().heli).toBe(0);
    router.destroy();
  });

  test('f. keyboard and gamepad holds of heliLeft are independent (keyboard release)', () => {
    const { router } = setup('classic');
    const gp = gamepad();
    navigator.getGamepads = () => [gp];

    hold(gp, 4);
    expect(router.poll().heli).toBe(-1);

    key('keydown', 'ArrowLeft');
    expect(router.poll().heli).toBe(-1);

    key('keyup', 'ArrowLeft'); // releasing keyboard must not cancel the gamepad hold
    expect(router.poll().heli).toBe(-1);

    hold(gp, 4, false);
    expect(router.poll().heli).toBe(0);
    router.destroy();
  });

  test('gamepad writes pad state before emitting INPUT_ACTION (listener sees fresh state)', () => {
    const g = game();
    const router = new InputRouter(g);
    const observed = [];
    g.events.on(EVT.INPUT_ACTION, (p) => {
      if (p.action === 'hop') observed.push({ pressed: p.pressed, hop: router.pad.state.hop });
    });
    router.applySettings({ ...defaultSettings(), controlLayout: 'classic' });
    g.events.emit(EVT.RUN_START);
    const gp = gamepad();
    navigator.getGamepads = () => [gp];

    hold(gp, 0); // A -> hop + confirm
    router.poll();
    expect(observed).toContainEqual({ pressed: true, hop: true });

    hold(gp, 0, false);
    router.poll();
    expect(observed).toContainEqual({ pressed: false, hop: false });
    router.destroy();
  });

  test('gamepad INPUT_ACTION events keep source "gamepad"', () => {
    const { router, actions } = setup();
    const gp = gamepad();
    navigator.getGamepads = () => [gp];

    hold(gp, 9); // Start -> pause action
    router.poll();
    hold(gp, 9, false);
    router.poll();

    expect(actions.filter((a) => a.action === 'pause')).toEqual([
      { action: 'pause', pressed: true, source: 'gamepad' },
      { action: 'pause', pressed: false, source: 'gamepad' },
    ]);
    router.destroy();
  });
});/**
 * Issue #211: gameplay-input reachability matrix (issue #211 leaf, NOT full parity).
 *
 * Documents, at runtime, which pad buttons every supported physical input can actually reach.
 * Derived from the real code paths:
 *   - KEYMAP + ControlLayouts.layoutButton (keyboard, per control layout)
 *   - GP_BINDINGS (standard-mapping gamepad)
 *   - TOUCH_CLUSTERS + touchButtonFor (touch overlay, classic vs trick deck)
 *
 * Reachability is observed through VirtualPad's per-button held sets (the single source of truth
 * InputRouter writes to), so a raw pad name is "mapped" only when a real input holds it.
 * See docs/controls/issue-211-input-reachability.md for the human-readable table.
 */
import { EventEmitter } from 'events';
import { InputRouter } from '../../src/systems/InputRouter.js';
import { VirtualPad, HELD_NAMES } from '../../src/systems/VirtualPad.js';
import { TRICK_KEYS_RIGHT, TRICK_KEYS_LEFT } from '../../src/systems/ControlLayouts.js';
import { TOUCH_CLUSTERS, touchButtonFor } from '../../src/systems/TouchOverlay.js';
import { defaultSettings } from '../../src/systems/SaveStore.js';
import { EVT } from '../../src/events.js';

const game = () => ({ events: new EventEmitter(), canvas: null, registry: { get: () => undefined } });
const key = (type, code) =>
  window.dispatchEvent(new KeyboardEvent(type, { code, bubbles: true, cancelable: true }));

const heldNames = (router) => HELD_NAMES.filter((n) => router.pad.held[n].size > 0);
const sorted = (a) => [...a].sort();

function routerFor(layout) {
  const g = game();
  const router = new InputRouter(g);
  router.applySettings({ ...defaultSettings(), controlLayout: layout });
  g.events.emit(EVT.RUN_START);
  return router;
}

function gamepad(over = {}) {
  return {
    connected: true,
    mapping: 'standard',
    axes: [0, 0, 0, 0],
    buttons: Array.from({ length: 17 }, () => ({ pressed: false, value: 0 })),
    ...over,
  };
}

afterEach(() => {
  delete navigator.getGamepads;
  window.dispatchEvent(new Event('blur'));
});

// --------------------------------------------------------------------------------------------- keyboard

describe('issue #211 matrix: keyboard per control layout', () => {
  const CASES = [
    {
      layout: 'classic',
      expected: {
        KeyW: ['push'], KeyA: ['tiltBack'], KeyD: ['tiltForward'], KeyS: ['brake'],
        Space: ['confirm', 'hop'], ShiftLeft: ['reset'], ShiftRight: ['reset'],
        ArrowLeft: ['heliLeft'], ArrowRight: ['heliRight'], ArrowUp: ['airBrake'],
        ArrowDown: ['parachute'], Escape: ['pause'], Enter: ['confirm'],
        NumpadEnter: ['confirm'], Backspace: [],
      },
    },
    {
      layout: 'tricksRight',
      expected: {
        KeyW: ['parachute'], KeyA: ['airBrake'], KeyS: ['divebomb'], KeyD: ['tuck'],
        ArrowUp: ['tiltForward'], ArrowDown: ['tiltBack'], ArrowRight: ['heliRight'],
        ArrowLeft: ['corkscrew'],
        Space: ['confirm', 'hop'], ShiftLeft: ['reset'], Escape: ['pause'], Enter: ['confirm'],
      },
    },
    {
      layout: 'tricksLeft',
      expected: {
        KeyW: ['tiltForward'], KeyS: ['tiltBack'], KeyD: ['heliRight'], KeyA: ['corkscrew'],
        ArrowUp: ['parachute'], ArrowLeft: ['airBrake'], ArrowDown: ['divebomb'],
        ArrowRight: ['tuck'],
        Space: ['confirm', 'hop'], ShiftLeft: ['reset'], Escape: ['pause'], Enter: ['confirm'],
      },
    },
  ];

  for (const { layout, expected } of CASES) {
    test(`${layout}: every key reaches exactly its documented pad buttons`, () => {
      const router = routerFor(layout);
      for (const [code, want] of Object.entries(expected)) {
        key('keydown', code);
        expect(sorted(heldNames(router))).toEqual(sorted(want));
        key('keyup', code);
        expect(heldNames(router)).toEqual([]);
      }
      router.destroy();
    });
  }

  test('trick layouts do NOT reach push, brake or heliLeft on the keyboard', () => {
    for (const layout of ['tricksRight', 'tricksLeft']) {
      const router = routerFor(layout);
      const reachable = new Set();
      for (const e of [...Object.keys(TRICK_KEYS_RIGHT), ...Object.keys(TRICK_KEYS_LEFT),
        'Space', 'ShiftLeft', 'Escape', 'Enter']) {
        key('keydown', e);
        heldNames(router).forEach((n) => reachable.add(n));
        key('keyup', e);
      }
      expect(reachable.has('push')).toBe(false);
      expect(reachable.has('brake')).toBe(false);
      expect(reachable.has('heliLeft')).toBe(false);
      router.destroy();
    }
  });

  test('classic keyboard cannot reach divebomb or corkscrew', () => {
    const router = routerFor('classic');
    const reachable = new Set();
    for (const e of ['KeyW', 'KeyA', 'KeyD', 'KeyS', 'Space', 'ShiftLeft', 'ShiftRight',
      'ArrowLeft', 'ArrowRight', 'ArrowUp', 'ArrowDown', 'Escape', 'Enter', 'NumpadEnter']) {
      key('keydown', e);
      heldNames(router).forEach((n) => reachable.add(n));
      key('keyup', e);
    }
    expect(reachable.has('divebomb')).toBe(false);
    expect(reachable.has('corkscrew')).toBe(false);
    router.destroy();
  });
});

// ---------------------------------------------------------------------------------------------- gamepad

describe('issue #211 matrix: standard gamepad', () => {
  test('each physical gamepad input reaches exactly its bound pad buttons', () => {
    const router = routerFor('classic');
    const gp = gamepad();
    navigator.getGamepads = () => [gp];
    const cases = [
      ['A', (p) => { p.buttons[0] = { pressed: true, value: 1 }; }, ['confirm', 'hop']],
      ['B', (p) => { p.buttons[1] = { pressed: true, value: 1 }; }, ['brake']],
      ['X', (p) => { p.buttons[2] = { pressed: true, value: 1 }; }, ['airBrake']],
      ['Y', (p) => { p.buttons[3] = { pressed: true, value: 1 }; }, ['parachute']],
      ['LB', (p) => { p.buttons[4] = { pressed: true, value: 1 }; }, ['heliLeft']],
      ['RB', (p) => { p.buttons[5] = { pressed: true, value: 1 }; }, ['heliRight']],
      ['LT', (p) => { p.buttons[6] = { pressed: true, value: 1 }; }, ['tuck']],
      ['RT', (p) => { p.buttons[7] = { pressed: true, value: 1 }; }, ['push']],
      ['Back', (p) => { p.buttons[8] = { pressed: true, value: 1 }; }, ['reset']],
      ['Start', (p) => { p.buttons[9] = { pressed: true, value: 1 }; }, ['pause']],
      ['DLeft', (p) => { p.buttons[14] = { pressed: true, value: 1 }; }, ['tiltBack']],
      ['DRight', (p) => { p.buttons[15] = { pressed: true, value: 1 }; }, ['tiltForward']],
      ['RSLeft', (p) => { p.axes[2] = -1; }, ['heliLeft']],
      ['RSRight', (p) => { p.axes[2] = 1; }, ['heliRight']],
    ];
    for (const [, press, want] of cases) {
      const fresh = gamepad();
      navigator.getGamepads = () => [fresh];
      router.poll(); // sync to neutral
      press(fresh);
      router.poll();
      expect(sorted(heldNames(router))).toEqual(sorted(want));
    }
    router.destroy();
  });

  test('d-pad and left-stick directions emit menu actions without a pad button', () => {
    const g = game();
    const router = new InputRouter(g);
    const acts = [];
    g.events.on(EVT.INPUT_ACTION, (a) => acts.push(a));
    const gp = gamepad();
    navigator.getGamepads = () => [gp];
    gp.buttons[12] = { pressed: true, value: 1 }; // DUp
    gp.axes[0] = -1; // LSLeft
    router.poll();
    expect(heldNames(router)).toEqual([]);
    expect(acts.filter((a) => a.pressed).map((a) => a.action)).toEqual(
      expect.arrayContaining(['up', 'left']));
    router.destroy();
  });

  test('gamepad cannot reach divebomb, corkscrew or heli on a stick other than the right stick', () => {
    const router = routerFor('classic');
    const gp = gamepad();
    navigator.getGamepads = () => [gp];
    const reachable = new Set();
    // every button index and both stick axes
    for (let i = 0; i < 17; i++) {
      const fresh = gamepad();
      navigator.getGamepads = () => [fresh];
      fresh.buttons[i] = { pressed: true, value: 1 };
      router.poll();
      heldNames(router).forEach((n) => reachable.add(n));
    }
    for (const [idx, v] of [[0, -1], [0, 1], [1, -1], [1, 1], [3, -1], [3, 1]]) {
      const fresh = gamepad();
      navigator.getGamepads = () => [fresh];
      fresh.axes[idx] = v;
      router.poll();
      heldNames(router).forEach((n) => reachable.add(n));
    }
    expect(reachable.has('divebomb')).toBe(false);
    expect(reachable.has('corkscrew')).toBe(false);
    // heli only comes from LB/RB and the right-stick X axis (axes[2]).
    expect(reachable.has('heliLeft')).toBe(true);
    expect(reachable.has('heliRight')).toBe(true);
    router.destroy();
  });
});

// ------------------------------------------------------------------------------------------------ touch

describe('issue #211 matrix: touch overlay', () => {
  const mount = (layout) => {
    const parent = document.createElement('div');
    document.body.appendChild(parent);
    const pad = new VirtualPad();
    pad.mountTouchOverlay(parent, { touchOverlay: 'on', controlLayout: layout });
    pad.setOverlayContext(true);
    const names = () => [...pad.overlay.root.querySelectorAll('[data-btn]')].map((e) => e.dataset.btn);
    const tap = (name) => { pad.overlay._assign(1, name); pad.overlay._assign(1, null); };
    return { pad, parent, names, tap };
  };

  test('classic overlay reaches classic buttons, not divebomb/corkscrew/confirm', () => {
    const { pad, parent, names, tap } = mount('classic');
    const reachable = new Set();
    for (const n of names()) {
      pad.overlay._assign(1, n);
      heldNames({ pad }).forEach((x) => reachable.add(x));
      pad.overlay._assign(1, null);
    }
    for (const n of ['push', 'brake', 'tuck', 'tiltBack', 'tiltForward', 'heliLeft',
      'heliRight', 'airBrake', 'parachute', 'hop', 'reset', 'pause']) {
      expect(reachable.has(n)).toBe(true);
    }
    expect(reachable.has('divebomb')).toBe(false);
    expect(reachable.has('corkscrew')).toBe(false);
    expect(reachable.has('confirm')).toBe(false);
    tap('hop');
    pad.destroy();
    parent.remove();
  });

  test('trick-deck overlay swaps push->divebomb and heliLeft->corkscrew', () => {
    const { pad, parent, names } = mount('tricksRight');
    const reachable = new Set(names());
    expect(reachable.has('divebomb')).toBe(true);
    expect(reachable.has('corkscrew')).toBe(true);
    expect(reachable.has('push')).toBe(false);
    expect(reachable.has('heliLeft')).toBe(false);
    // and every advertised button really drives the pad
    for (const n of names()) {
      pad.overlay._assign(1, n);
      expect(pad.held[n].size).toBeGreaterThan(0);
      pad.overlay._assign(1, null);
    }
    pad.destroy();
    parent.remove();
  });

  test('touchButtonFor is the single swap source both DOM and legend use', () => {
    expect(touchButtonFor({ name: 'push' }, 'trickDeck').name).toBe('divebomb');
    expect(touchButtonFor({ name: 'heliLeft' }, 'trickDeck').name).toBe('corkscrew');
    expect(touchButtonFor({ name: 'push' }, 'classic').name).toBe('push');
    expect(touchButtonFor({ name: 'heliLeft' }, 'classic').name).toBe('heliLeft');
    // cluster membership pins the spatial buttons the matrix describes
    expect(TOUCH_CLUSTERS.RIGHT.map((b) => b.name)).toEqual(
      expect.arrayContaining(['heliLeft', 'heliRight', 'push', 'hop', 'parachute', 'airBrake']));
    expect(TOUCH_CLUSTERS.TOP.map((b) => b.name)).toEqual(['reset', 'pause']);
  });
});import { jest } from '@jest/globals';
import { StemMusicDirector } from '../../src/systems/music/StemMusicDirector.js';
import { GAME_SONGS, defaultSongSelection } from '../../src/systems/music/MusicPlaylist.js';
import { JukeboxHUD } from '../../src/ui/JukeboxHUD.js';

function bare(){
	const d=Object.create(StemMusicDirector.prototype);
	d.catalog=GAME_SONGS.map(song=>({id:song.id,title:song.label}));
	d.songEnabled=defaultSongSelection();
	d.trackIndex=0;
	d.track=d.catalog[0];
	d.pack={duration:180};
	d.ctx={currentTime:35,state:'running'};
	d.clockStart=10;
	d.started=true;
	d.ready=true;
	d.disposed=false;
	d.transportPaused=false;
	d._resumeOffset=0;
	d._transportHistory=[];
	d._skipHistoryOnce=false;
	d._token=7;
	d._timer=null;
	d._nextPromise=null;
	d._nextIndex=null;
	d._loading=null;
	d.cache=new Map();
	d.scheduled=new Set();
	d.inflight=new Map();
	d.activeNodes=new Set();
	d.adaptive={reset:jest.fn()};
	d.bus={gain:{setTargetAtTime:jest.fn()}};
	d._ensureRunning=jest.fn();
	return d;
}

test('Game Over background tap guard owns real jukebox and open queue geometry',()=>{
	const owns=JukeboxHUD.prototype.ownsPointer;
	const hud={_closed:false,bounds:{x:335,y:4,w:141,h:31},
		queueBounds:{x:245,y:94,w:230,h:93},queue:null};
	expect(owns.call(hud,{x:400,y:18})).toBe(true);
	expect(owns.call(hud,{x:252,y:181})).toBe(false);
	expect(owns.call(hud,{x:120,y:200})).toBe(false);
	hud.queue={};
	expect(owns.call(hud,{x:252,y:181})).toBe(true);
	expect(owns.call(hud,{x:469,y:180})).toBe(true);
	expect(owns.call(hud,{x:250,y:188})).toBe(false);
	expect(owns.call(hud,{x:Number.NaN,y:101})).toBe(false);
	hud._closed=true;
	expect(owns.call(hud,{x:252,y:181})).toBe(false);
});

describe('Jukebox: one shared music director, reliable paused and skipped intent',()=>{
	test('snapshot shows current, previous, two queued and true clock time',()=>{
		const d=bare();
		d._transportHistory=[d.catalog[3]];
		expect(d.transportSnapshot()).toMatchObject({
			state:'playing',current:d.catalog[0],previous:d.catalog[3],
			upcoming:[d.catalog[1],d.catalog[2]],position:25,
			audioSuspended:false,
		});
	});
	test('pause stops one-shot nodes and preserves exact clock position for resume',()=>{
		const d=bare();
		d.activeNodes.add({stop:jest.fn()});
		expect(d.transportPause()).toBe(true);
		expect(d.started).toBe(false);
		expect(d.transportPaused).toBe(true);
		expect(d._resumeOffset).toBe(25);
		expect(d.transportSnapshot().state).toBe('paused');
		expect(d.transportPlay()).toBe(true);
		expect(d.started).toBe(true);
		expect(d.transportPaused).toBe(false);
		expect(d._resumeOffset).toBe(25); // consumed by _ensureRunning()
	});
	test('skip preserves pause, skips disabled songs, clears old playback offset',()=>{
		const d=bare();
		d.songEnabled[d.catalog[1].id]=false;
		d.transportPause();
		expect(d.transportStep(1)).toBe(true);
		expect(d.trackIndex).toBe(2);
		expect(d._resumeOffset).toBe(0);
		expect(d.transportPaused).toBe(true);
		expect(d.transportSnapshot().state).toBe('paused');
		expect(d.transportSnapshot().current).toBe(d.catalog[2]);
	});
	test('previous takes actual history before wrapping playlist',()=>{
		const d=bare();
		d.trackIndex=2;
		d.track=d.catalog[2];
		d._transportHistory=[d.catalog[0]];
		expect(d.transportStep(-1)).toBe(true);
		expect(d.trackIndex).toBe(0);
		expect(d._skipHistoryOnce).toBe(true);
		expect(d._transportHistory).toHaveLength(0);
	});
	test('all four disabled silences playlist; no procedural music fallback',()=>{
		const d=bare();
		d.setSongSelection(Object.fromEntries(GAME_SONGS.map(song=>[song.id,false])));
		expect(d.started).toBe(false);
		expect(d.transportSnapshot()).toMatchObject({
			state:'stopped',current:null,upcoming:[],
		});
		expect(d.transportPlay()).toBe(false);
		expect(d.transportStep(1)).toBe(false);
	});
	test('stale preload cleanup cannot erase newer loading promise',async()=>{
		const d=bare();
		d.pack=null;
		d.started=true;
		d._ensureRunning=StemMusicDirector.prototype._ensureRunning.bind(d);
		d._timer=setInterval(()=>{},100000);
		d._beginTrack=jest.fn(()=>Promise.resolve());
		d._resumeOffset=18.3;
		try {
			d._ensureRunning();
			expect(d._beginTrack).toHaveBeenCalledWith(0,null,18.3);
			expect(d._resumeOffset).toBe(0);
			await d._loading;
		}finally{
			clearInterval(d._timer);
			d._timer=null;
		}
	});
});// Issue #47: hostile racing Kodiaks. Pure behaviour; the game wiring is covered by tools/kodiak-browser-smoke.mjs.
import fs from 'fs';
import { KODIAK_DEFS, KODIAK_KINDS, KODIAK_MIN_SYNC_LEVEL, KODIAK_FIRST_M, KODIAK_KNOCK, kodiaksEnabledFor, kodiakEncounter,
  spawnKodiak, stepKodiak, kodiakBox, kodiakHits, kodiakKnockback, spawnKodiakPack, stepKodiakPack, kodiakThreatening, KODIAK_CLEAR_PX } from '../../src/systems/Kodiaks.js';

/** Run a bear against a sled at constant speed on flat ground; record its phase changes. */
function race(kind, { sledVx = 500, ms = 8000, grounded = () => true, landX = () => null } = {}) {
  const sled = { x: 10000, vx: sledVx, grounded: true, landX: null };
  const k = spawnKodiak('BEARS', { n: 0, kind }, sled);
  const phases = [k.phase], events = [];
  for (let t = 0; t < ms && !k.done; t += 1000 / 120) {
    sled.x += sled.vx / 120;
    sled.grounded = grounded(t);
    sled.landX = landX(t, sled);
    const ev = stepKodiak(k, sled, 1000 / 120);
    if (ev.telegraph || ev.lunge) events.push({ t: Math.round(t), ...ev });
    if (phases.at(-1) !== k.phase) phases.push(k.phase);
  }
  return { k, phases, events, sled };
}

describe('Kodiaks', () => {
  test('three bears, exactly as named: white polar, grizzly brown, Vermont black', () => {
    expect(KODIAK_KINDS).toEqual(['kernelPanic', 'bruteForce', 'blackIce']);
    expect(KODIAK_DEFS.kernelPanic.name).toBe('KERNEL-PANIC KODIAK');
    expect(KODIAK_DEFS.bruteForce.name).toBe('BRUTE-FORCE KODIAK');
    expect(KODIAK_DEFS.blackIce.name).toBe('BLACK-ICE KODIAK');
    expect(KODIAK_DEFS.kernelPanic.color).toBeGreaterThan(0xd00000); // white
    expect(KODIAK_DEFS.blackIce.color).toBeLessThan(0x303030); // black
    for (const d of Object.values(KODIAK_DEFS)) expect(d.onHit).toBeUndefined(); // contact never crashes the sled
    const art = fs.readFileSync('src/entities/KodiakRider.js', 'utf8');
    for (const cue of ['shoulder hump', 'long neck', 'tall rounded ears']) expect(art).toContain(cue);
  });

  test('gated: from the Sync Level in ordinary runs; never on Dailies or in the Gym', () => {
    expect(kodiaksEnabledFor({ level: KODIAK_MIN_SYNC_LEVEL - 1 })).toBe(false);
    expect(kodiaksEnabledFor({ level: KODIAK_MIN_SYNC_LEVEL })).toBe(true);
    expect(kodiaksEnabledFor({ level: 99, daily: true })).toBe(false);
    expect(kodiaksEnabledFor({ level: 99, gym: true })).toBe(false);
  });

  test('encounters are seeded: same seed same schedule, spaced out, all three bears appear', () => {
    const a = Array.from({ length: 12 }, (_, n) => kodiakEncounter('SEED', n));
    expect(a).toEqual(Array.from({ length: 12 }, (_, n) => kodiakEncounter('SEED', n)));
    expect(a[0].atM).toBe(KODIAK_FIRST_M);
    for (let i = 1; i < a.length; i++) expect(a[i].atM - a[i - 1].atM).toBeGreaterThanOrEqual(650);
    expect(new Set(a.map((e) => e.kind)).size).toBe(3);
    expect(kodiakEncounter('OTHER', 3)).not.toEqual(a[3]);
  });

  test('Brute-Force: catches up from behind, telegraphs, lunges, then tires so it can be re-passed', () => {
    const r = race('bruteForce');
    expect(r.phases.slice(0, 4)).toEqual(['approach', 'tele', 'lunge', 'recover']);
    const tele = r.events.find((e) => e.telegraph === 'real'), lunge = r.events.find((e) => e.lunge);
    expect(lunge.t - tele.t).toBeGreaterThanOrEqual(600); // fair warning before the charge
  });

  test('Kernel-Panic: deterministic feints (at most two), always a red telegraph before the real stop', () => {
    const r1 = race('kernelPanic', { sledVx: 520 }), r2 = race('kernelPanic', { sledVx: 520 });
    expect(r1.events).toEqual(r2.events);
    const kinds = r1.events.filter((e) => e.telegraph).map((e) => e.telegraph);
    expect(kinds.filter((x) => x === 'feint').length).toBeLessThanOrEqual(2);
    expect(kinds.at(-1)).toBe('real');
    expect(r1.phases).toContain('lunge');
  });

  test('Black-Ice: reads the predicted landing and slides under it; out-ridden on the ground it leaves', () => {
    const air = (t) => !(t > 1500 && t < 2300);
    const r = race('blackIce', { grounded: (t) => !(t > 1500 && t < 2300), landX: (t, s) => (t > 1500 && t < 2300 ? s.x + 400 : null) });
    expect(r.events.some((e) => e.telegraph === 'real')).toBe(true);
    expect(air(0)).toBe(true);
    const ground = race('blackIce', { sledVx: 900, ms: 15000 });
    expect(ground.phases).toContain('leave');
  });

  test('collision is fair: a sled riding into the bear hits, one hopping over its back does not', () => {
    const bear = kodiakBox(100, 500);
    expect(kodiakHits(bear, { x: 90, y: 480, w: 36, h: 30 })).toBe(true);
    expect(kodiakHits(bear, { x: 90, y: 440, w: 36, h: 30 })).toBe(false); // bottom 470 < back 474 + 4 margin
    expect(kodiakHits(bear, { x: 300, y: 480, w: 36, h: 30 })).toBe(false);
  });

  test('contact shoves the sled backward and up, bounded, and harder the faster the two were closing', () => {
    const still = kodiakKnockback({ speed: 500 }, { vx: 500 }), closing = kodiakKnockback({ speed: 0 }, { vx: 600 });
    expect(still.dvx).toBe(-KODIAK_KNOCK.basePx); // no closing speed: the base push only
    expect(closing.dvx).toBeLessThan(still.dvx); // backward (negative x), and harder when closing
    expect(Math.abs(closing.dvx)).toBeLessThanOrEqual(KODIAK_KNOCK.maxPx); // bounded
    expect(closing.dvy).toBe(-KODIAK_KNOCK.upPx); // up (y grows downward)
    expect(kodiakKnockback({ speed: 120 }, { vx: 520 })).toEqual(kodiakKnockback({ speed: 120 }, { vx: 520 })); // pure
  });

  test('the shove window is set and the push stays well under cruising speed, so a shoved sled keeps moving forward', () => {
    expect(KODIAK_KNOCK.immunityMs).toBeGreaterThan(0);
    expect(KODIAK_KNOCK.maxPx).toBeLessThan(600); // well under a sled's cruising speed: it keeps moving forward
  });

  test('every bear leaves within its lifetime (no perpetual bear combat)', () => {
    for (const kind of KODIAK_KINDS) expect(race(kind, { ms: 20000 }).k.done).toBe(true);
  });

  test('race bears come in packs of 2-3: one type in SAME mode, at least two types in MIXED mode', () => {
    for (let n = 0; n < 30; n++) {
      const same = kodiakEncounter('PACKS', n, 'same'), mixed = kodiakEncounter('PACKS', n, 'mixed');
      expect(same.members.length).toBeGreaterThanOrEqual(2);
      expect(same.members.length).toBeLessThanOrEqual(3);
      expect(new Set(same.members).size).toBe(1);
      expect(new Set(mixed.members).size).toBe(mixed.members.length);
      expect(mixed.members[0]).toBe(same.kind); // same schedule and lead type in both modes
      expect(same.atM).toBe(mixed.atM);
    }
    expect(kodiakEncounter('PACKS', 0, 'same').members.length).toBe(2); // the first pack of a run is 2
  });

  test('a pack attacks one bear at a time, and never while another bear is close enough to need hopping', () => {
    for (const mode of ['same', 'mixed']) for (let n = 0; n < 6; n++) {
      const sled = { x: 20000, vx: 520, grounded: true, landX: null };
      const bears = spawnKodiakPack('ONEATATIME', kodiakEncounter('ONEATATIME', n, mode), sled);
      for (let t = 0; t < 12000; t += 1000 / 120) {
        sled.x += sled.vx / 120;
        // Judge each start of an attack against the pack as it stood when that bear decided (members step in order).
        const before = bears.map((b) => b.phase);
        const blocks = (o) => kodiakThreatening(o) || (!o.done && !o.hit && Math.abs(o.x - sled.x) < KODIAK_CLEAR_PX);
        const pre = bears.map(blocks);
        stepKodiakPack(bears, sled, 1000 / 120);
        const post = bears.map(blocks);
        expect(bears.filter(kodiakThreatening).length).toBeLessThanOrEqual(1);
        // Bear i saw members j < i after their step this tick, and members j > i before theirs.
        bears.forEach((b, i) => {
          if (before[i] === 'approach' && b.phase === 'tele') expect(bears.some((o, j) => j !== i && (j < i ? post[j] : pre[j]))).toBe(false);
        });
      }
    }
  });

  test('a bear you must pass on the ground is much slower than you (a hop clears it at real closing speed)', () => {
    const r = race('bruteForce', { ms: 6000 });
    expect(r.phases).toContain('recover');
    const k = spawnKodiak('SLOW', { n: 0, kind: 'bruteForce' }, { x: 0, vx: 500 });
    k.phase = 'recover'; k.phaseMs = 0; k.x = 400; k.speed = 600;
    for (let i = 0; i < 120; i++) stepKodiak(k, { x: 0, vx: 500, grounded: true, landX: null }, 1000 / 120);
    expect(k.speed).toBeLessThan(500 * 0.5);
  });
});/**
 * Marvin decision 6 (2026-11-14): "Hash all gameplay-affecting settings and score/result data; exclude
 * cosmetics." A versioned ledger hash: new records carry `hashV: 2` and a hash over every gameplay or
 * result field; records without `hashV` keep verifying under the v1 function, which is unchanged.
 */
import {
  SaveStore, sanitizeRun, SHARECODE_PREFIX, base64Encode, base64Decode,
  computeLedgerHashV1, computeLedgerHashV2, verifyLedgerHash, LEDGER_HASH_V,
} from '../../src/systems/SaveStore.js';
import fs from 'fs';
import { creditRun } from '../../src/systems/ProfileStore.js';
import { defaultProfile } from '../../src/systems/Progression.js';

const LEVELS = JSON.parse(fs.readFileSync('src/data/progression/levels.json', 'utf8'));

let seq = 0;
/** A record shaped exactly like the one RunScene builds (crash path), v2. */
function runSceneRecord(over = {}) {
  seq++;
  const r = {
    version: 1,
    id: `v2-${seq}`,
    seed: `seed-${seq}`,
    dailyRuleId: 'tuckBoost',
    biomeMask: 4,
    startedAt: 1000 * seq,
    endedAt: 1000 * seq + 9000,
    durationMs: 9000,
    score: 1234 + seq,
    distanceM: 321,
    trickPoints: 200,
    tricks: { backflip: 2, heli: 1 },
    bestCombo: 1.5,
    bestFlow: 1.4,
    maxAirtimeMs: 900,
    cause: 'crash',
    modded: true,
    boosts: ['headStart'],
    dailyOfficial: false,
    hashV: 2,
    shards: 7,
    nearMisses: 2,
    bonusPoints: 50,
    ledgerHash: '',
    ...over,
  };
  if (over.ledgerHash === undefined) r.ledgerHash = SaveStore.computeLedgerHash(r);
  return r;
}

/** A pre-decision-6 record: no hashV, v1 hash. */
function v1Record(over = {}) {
  seq++;
  const r = {
    version: 1, id: `v1-${seq}`, seed: `seed-${seq}`, dailyRuleId: 'tuckBoost', startedAt: 1000 * seq,
    endedAt: 1000 * seq + 500, durationMs: 500, score: 100 + seq, distanceM: 80, trickPoints: 20,
    tricks: { backflip: 2 }, bestCombo: 1.5, maxAirtimeMs: 1200, cause: 'crash', ledgerHash: '', ...over,
  };
  if (over.ledgerHash === undefined) r.ledgerHash = computeLedgerHashV1(r);
  return r;
}

async function fresh() {
  const s = new SaveStore();
  await s.init();
  return s;
}
const codeOf = (runs) => SHARECODE_PREFIX + base64Encode(JSON.stringify({ app: 'bitstream-bluffs', v: 1, runs }));

describe('ledger hash v2: versioned, covers gameplay and result fields', () => {
  test('LEDGER_HASH_V is 2 and computeLedgerHash dispatches on hashV', () => {
    expect(LEDGER_HASH_V).toBe(2);
    const r = runSceneRecord();
    expect(SaveStore.computeLedgerHash(r)).toBe(computeLedgerHashV2(r));
    const old = v1Record();
    expect(SaveStore.computeLedgerHash(old)).toBe(computeLedgerHashV1(old));
  });

  test('v1 stays byte-identical: a known record keeps its pinned hash', () => {
    // Pinned from the unchanged v1 function: old records must never be re-hashed.
    const r = {
      version: 1, id: 'pin', seed: 'alpha', dailyRuleId: 'tuckBoost', startedAt: 1, endedAt: 2, durationMs: 1,
      score: 10, distanceM: 5, trickPoints: 0, tricks: {}, bestCombo: 1, maxAirtimeMs: 0, cause: 'crash',
    };
    const h = computeLedgerHashV1(r);
    expect(h).toMatch(/^[0-9a-f]{8}$/);
    // v1 ignores every field it never covered, so adding them changes nothing.
    expect(computeLedgerHashV1({ ...r, biomeMask: 4, modded: true, shards: 9 })).toBe(h);
  });

  const MUTATIONS = {
    seed: 'other', dailyRuleId: 'slickLines', biomeMask: 8, modded: false, boosts: [], dailyOfficial: true,
    startedAt: 7, endedAt: 8, durationMs: 1, score: 1, distanceM: 1, trickPoints: 1, tricks: { backflip: 3 },
    bestCombo: 2, bestFlow: 1.9, maxAirtimeMs: 1, cause: 'quit', shards: 99, nearMisses: 9, bonusPoints: 1,
    id: 'renamed', version: 0,
  };
  test.each(Object.keys(MUTATIONS))('v2 changes when %s changes', (k) => {
    const r = runSceneRecord();
    expect(computeLedgerHashV2({ ...r, [k]: MUTATIONS[k] })).not.toBe(computeLedgerHashV2(r));
  });

  test('v2 ignores initials, the hash itself and the local imported marker (not gameplay)', () => {
    const r = runSceneRecord();
    const h = computeLedgerHashV2(r);
    expect(computeLedgerHashV2({ ...r, initials: 'ABC', ledgerHash: 'zz', imported: true })).toBe(h);
  });

  test('absent and default values canonicalise the same way (stable across sanitizeRun)', () => {
    const base = runSceneRecord({ modded: undefined, boosts: undefined, biomeMask: undefined, shards: undefined });
    const explicit = { ...base, modded: false, boosts: [], biomeMask: 0, shards: 0 };
    expect(computeLedgerHashV2(explicit)).toBe(computeLedgerHashV2(base));
    // trick key order does not matter
    expect(computeLedgerHashV2({ ...base, tricks: { heli: 1, backflip: 2 } })).toBe(computeLedgerHashV2(base));
  });

  test('hashV is inside the v2 hash: stripping it falls back to v1 and fails verification', () => {
    const r = runSceneRecord();
    expect(verifyLedgerHash(r)).toBe(true);
    const stripped = { ...r };
    delete stripped.hashV;
    expect(verifyLedgerHash(stripped)).toBe(false);
  });

  test('a RunScene-shaped record round-trips through sanitizeRun and still verifies', () => {
    const r = runSceneRecord();
    const s = sanitizeRun(r);
    expect(s.hashV).toBe(2);
    expect(s.bestFlow).toBe(1.4);
    expect(s.dailyOfficial).toBe(false);
    expect(s.boosts).toEqual(['headStart']);
    expect(verifyLedgerHash(s)).toBe(true);
    const official = runSceneRecord({ modded: undefined, boosts: undefined, dailyOfficial: true });
    expect(verifyLedgerHash(sanitizeRun(official))).toBe(true);
    expect(sanitizeRun(official).dailyOfficial).toBe(true);
  });

  test('sanitizeRun never defaults hashV onto a record that lacks it', () => {
    const s = sanitizeRun(v1Record());
    expect('hashV' in s).toBe(false);
    expect(verifyLedgerHash(s)).toBe(true);
    // an unknown future version is not invented into 2
    expect('hashV' in sanitizeRun({ ...v1Record(), hashV: 'x' })).toBe(false);
  });

  test('verifyLedgerHash rejects an empty hash and never throws on junk', () => {
    expect(verifyLedgerHash({ ...runSceneRecord(), ledgerHash: '' })).toBe(false);
    expect(verifyLedgerHash({ ...v1Record(), ledgerHash: '' })).toBe(false);
    for (const junk of [null, undefined, 5, 'x', {}, []]) expect(verifyLedgerHash(junk)).toBe(false);
  });
});

describe('importSharecode verifies per version (F2)', () => {
  test('v1 and v2 records with valid hashes both import', async () => {
    const s = await fresh();
    const res = await s.importSharecode(codeOf([v1Record({ initials: 'OLD' }), runSceneRecord({ initials: 'NEW' })]));
    expect(res).toEqual({ imported: 2, skipped: 0 });
  });

  test('an empty hash is rejected (no more verification bypass), without throwing', async () => {
    const s = await fresh();
    const a = { ...v1Record({ initials: 'AAA' }), ledgerHash: '' };
    const b = { ...runSceneRecord({ initials: 'BBB' }), ledgerHash: '' };
    const c = v1Record({ initials: 'CCC' });
    delete c.ledgerHash;
    expect(await s.importSharecode(codeOf([a, b, c]))).toEqual({ imported: 0, skipped: 3 });
  });

  test('tampering any v2 gameplay field is rejected', async () => {
    const s = await fresh();
    const r = runSceneRecord({ initials: 'TAM' });
    const bad = [
      { ...r, id: 'm1', modded: undefined },
      { ...r, id: 'm2', biomeMask: 0 },
      { ...r, id: 'm3', dailyOfficial: true },
      { ...r, id: 'm4', shards: 1000 },
    ];
    // ids changed too, so only the tampering (not the id) could make them pass: re-hash nothing.
    expect(await s.importSharecode(codeOf(bad))).toEqual({ imported: 0, skipped: 4 });
  });

  test('imported records are marked imported:true whatever the sharecode says', async () => {
    const s = await fresh();
    const r = runSceneRecord({ initials: 'IMP', imported: false });
    await s.importSharecode(codeOf([r]));
    expect(s.runs[0].imported).toBe(true);
    expect(verifyLedgerHash(s.runs[0])).toBe(true);
    // and a locally saved run is not
    const local = runSceneRecord({ imported: true });
    await s.saveRun(local);
    expect(s.runs.find((x) => x.id === local.id).imported).toBeUndefined();
  });
});

describe('exportSharecode keeps exporting boosted runs, and modded is now hash-protected', () => {
  test('an exported boosted run imports; the same code with modded stripped is rejected', async () => {
    const s = await fresh();
    const r = runSceneRecord();
    await s.saveRun(r);
    await s.setInitials(r.id, 'MOD');
    const code = await s.exportSharecode();
    const payload = JSON.parse(base64Decode(code.slice(SHARECODE_PREFIX.length)));
    expect(payload.runs).toHaveLength(1);
    expect(payload.runs[0].modded).toBe(true);
    expect((await (await fresh()).importSharecode(code)).imported).toBe(1);
    // launder attempt: strip `modded` so the run would land on the clean board
    delete payload.runs[0].modded;
    const laundered = SHARECODE_PREFIX + base64Encode(JSON.stringify(payload));
    expect(await (await fresh()).importSharecode(laundered)).toEqual({ imported: 0, skipped: 1 });
  });
});

describe('crediting idempotency survives the hash change (no double credit)', () => {
  test('a v1 record already credited stays credited: its hash is never recomputed under v2', () => {
    const rec = v1Record();
    const first = creditRun(defaultProfile(), rec, LEVELS);
    expect(first).not.toBeNull();
    // the same stored record after a load: sanitizeRun keeps it v1, so the key is the same hash
    const reloaded = sanitizeRun(rec);
    expect(reloaded.ledgerHash).toBe(rec.ledgerHash);
    expect(creditRun(first.profile, reloaded, LEVELS)).toBeNull();
    // and a v2 record credits once
    const v2 = runSceneRecord();
    const a = creditRun(first.profile, v2, LEVELS);
    expect(a).not.toBeNull();
    expect(creditRun(a.profile, sanitizeRun(v2), LEVELS)).toBeNull();
  });
});import { calculateLocalRankings, MAX_LOCAL_RANKING_RECORDS } from '../../src/systems/local-rankings.js';
import { DailyPatch } from '../../src/systems/DailyPatch.js';
import { DRAFT_BUDGET, DRAFT_RULES_VERSION } from '../../src/systems/DailyDraft.js';
import { SaveStore, verifyLedgerHash } from '../../src/systems/SaveStore.js';

const clean = { board: 'clean', seed: 'ALPHA', biomeMask: 0, dailyRuleId: 'featherweight' };

function record(id, changes = {}) {
  const run = {
    version: 1, hashV: 2, id, seed: clean.seed, dailyRuleId: clean.dailyRuleId,
    startedAt: 1_000, endedAt: 11_000, durationMs: 10_000, score: 100,
    distanceM: 100, tricks: { frontflip: 1, backflip: 0 }, trickPoints: 40,
    bestCombo: 1, maxAirtimeMs: 200, cause: 'crash', dailyOfficial: false, initials: 'AAA',
    ...changes,
  };
  run.ledgerHash = SaveStore.computeLedgerHash(run);
  return run;
}

const ids = (result) => result.rows.map(({ id }) => id);

test('computes existing and derived metrics, tied midranks, and strict Pareto dominance', () => {
  const better = { distanceM: 200, score: 300, tricks: { frontflip: 2, backflip: 1 }, maxAirtimeMs: 500 };
  const rows = [
    record('D', { distanceM: 120, score: 400, durationMs: 6000 }),
    record('C', better), record('A'), record('B', better),
  ];
  const result = calculateLocalRankings(rows, clean);
  expect(result).toEqual(calculateLocalRankings([...rows].reverse(), clean));
  expect(ids(result)).toEqual(['A', 'B', 'C', 'D']);
  expect(result.historySize).toBe(4);
  expect(result.sampleSize).toBe(4);
  expect(result.metrics.averageProgressMps).toEqual({ unit: 'm/s', sampleSize: 4 });
  expect(result.rows[0].values).toEqual({
    distanceM: 100, score: 100, averageProgressMps: 10, trickVariety: 1,
    efficiencyPointsPerM: 1, maxAirtimeMs: 200, survivalMs: 10000,
  });
  expect(result.rows.map((row) => row.percentiles.score)).toEqual([12.5, 50, 50, 87.5]);
  expect(result.rows.map((row) => row.percentiles.distanceM)).toEqual([12.5, 75, 75, 37.5]);
  expect(result.rows.map((row) => row.pareto)).toEqual(['dominated', 'nondominated', 'nondominated', 'nondominated']);
  expect(result.frontierSampleSize).toBe(4);
  expect(result.frontierIds).toEqual(['B', 'C', 'D']);
});

test('discloses missing denominators, overflow and small samples rather than guessing', () => {
  const empty = calculateLocalRankings([], clean);
  expect(empty.rows).toEqual([]);
  expect(empty.metrics.score.sampleSize).toBe(0);

  const solo = calculateLocalRankings([record('solo')], clean);
  expect(solo.metrics.score.sampleSize).toBe(1);
  expect(Object.values(solo.rows[0].percentiles)).toEqual(Array(7).fill(null));
  expect(solo.frontierIds).toEqual(['solo']);

  const result = calculateLocalRankings([
    record('no-time', { durationMs: 0, distanceM: 0 }),
    record('ok'),
    record('overflow', { durationMs: 1e-320, distanceM: 0.1, score: Number.MAX_VALUE }),
  ], clean);
  expect(result.rows[0].values).toMatchObject({
    distanceM: 0, survivalMs: null, averageProgressMps: null, efficiencyPointsPerM: null,
  });
  expect(result.rows[2].values).toMatchObject({ averageProgressMps: null, efficiencyPointsPerM: null });
  expect(result.metrics.distanceM.sampleSize).toBe(3);
  expect(result.metrics.efficiencyPointsPerM.sampleSize).toBe(1);
  expect(result.rows[1].percentiles.efficiencyPointsPerM).toBeNull();
  expect(result.rows.map((r) => r.pareto)).toEqual([null, 'nondominated', null]);
});

test('equal distance-to-duration ratios tie in both percentile and frontier comparisons', () => {
  const result = calculateLocalRankings([
    record('short', { distanceM: 7, durationMs: 925, score: 70 }),
    record('long', { distanceM: 63, durationMs: 8325, score: 630 }),
  ], clean);
  expect(result.rows[0].values.averageProgressMps).toBe(result.rows[1].values.averageProgressMps);
  expect(result.rows.map((row) => row.percentiles.averageProgressMps)).toEqual([50, 50]);
  expect(result.rows.map((row) => row.pareto)).toEqual(['nondominated', 'dominated']);

  const distanceM = 900_000_000_000_003, durationMs = 696;
  const scaled = calculateLocalRankings([
    record('one', { distanceM, durationMs }),
    record('three', { distanceM: 3 * distanceM, durationMs: 3 * durationMs }),
  ], clean);
  expect(scaled.rows.map((row) => row.percentiles.averageProgressMps)).toEqual([50, 50]);
});

test('matches seed, mask, rule and exact canonical paid loadout, and keeps Daily lanes separate', () => {
  const dailyInfo = DailyPatch.infoForDateKey('2026-11-21');
  const daily = { seed: dailyInfo.seed, dailyRuleId: dailyInfo.rule.id, biomeMask: dailyInfo.biomeMask };
  const purchased = { hashV: 3, modded: true, boosts: ['headStart', 'errorCorrection'], upgradeRanks: { bsodGrace: 1 } };
  const draft = {
    ...daily, hashV: 4, dailyOfficial: true, dailyMode: 'draft', modded: true,
    draftRulesVersion: DRAFT_RULES_VERSION, draftBudget: DRAFT_BUDGET, upgradeRanks: { bsodGrace: 1 },
  };
  const history = [
    record('base'),
    record('other-mask', { biomeMask: 1 }),
    record('other-seed', { seed: 'BETA' }),
    record('other-rule', { dailyRuleId: 'heavyPackets' }),
    record('v2-boost', { modded: true, boosts: ['headStart'] }),
    record('purchased', purchased),
    record('other-boost', { ...purchased, boosts: ['errorCorrection'] }),
    record('other-upgrade', { ...purchased, upgradeRanks: { bsodGrace: 2 } }),
    record('pretend-v2-upgrade', { ...purchased, hashV: 2 }),
    record('practice', daily),
    record('classic', { ...daily, dailyOfficial: true }),
    record('wrong-official-rule', { ...daily, dailyRuleId: 'fake', dailyOfficial: true }),
    record('unrankable-official', { ...daily, hashV: 3, dailyOfficial: true, ...purchased }),
    record('draft', draft),
    record('zero-rank-draft', { ...draft, upgradeRanks: {} }),
    record('expired-draft', { ...draft, draftRulesVersion: DRAFT_RULES_VERSION - 1 }),
  ];
  expect(ids(calculateLocalRankings(history, clean))).toEqual(['base']);
  expect(ids(calculateLocalRankings(history, {
    ...clean, board: 'modded', boosts: ['errorCorrection', 'headStart', 'errorCorrection'], upgradeRanks: { bsodGrace: 1 },
  }))).toEqual(['purchased']);
  expect(ids(calculateLocalRankings(history, { ...clean, board: 'modded', boosts: ['headStart'] }))).toEqual(['v2-boost']);
  expect(ids(calculateLocalRankings(history, { ...daily, board: 'clean' }))).toEqual(['practice']);
  expect(ids(calculateLocalRankings(history, { ...daily, board: 'daily-classic' }))).toEqual(['classic']);
  expect(ids(calculateLocalRankings(history, {
    ...daily, board: 'daily-draft', upgradeRanks: { bsodGrace: 1 },
  }))).toEqual(['draft']);
  expect(ids(calculateLocalRankings(history, { ...daily, board: 'daily-draft' }))).toEqual(['zero-rank-draft']);
  expect(calculateLocalRankings(history, {
    ...daily, dailyRuleId: 'fake', board: 'clean',
  }).rows).toEqual([]);
  expect(calculateLocalRankings(history, { ...daily, board: 'modded', ...purchased }).rows).toEqual([]);
});

test('does not put hash-consistent but contradictory loadouts into a cohort', () => {
  const dailyInfo = DailyPatch.infoForDateKey('2026-11-21');
  const daily = { seed: dailyInfo.seed, dailyRuleId: dailyInfo.rule.id, biomeMask: dailyInfo.biomeMask };
  const boosts = ['headStart'];
  const upgradeRanks = { bsodGrace: 1 };
  const history = [
    record('boosts-without-mod-flag', { boosts }),
    record('ranks-without-mod-flag', { hashV: 3, upgradeRanks }),
    record('missing-applied-loadout', { modded: true }),
    record('unknown-boost', { modded: true, boosts: ['futureBoost'] }),
    record('classic-with-boost', { ...daily, dailyOfficial: true, boosts }),
  ];
  expect(history.every(verifyLedgerHash)).toBe(true);
  expect(calculateLocalRankings(history, { ...clean, boosts }).rows).toEqual([]);
  expect(calculateLocalRankings(history, { ...clean, upgradeRanks }).rows).toEqual([]);
  expect(calculateLocalRankings(history, { ...clean, board: 'modded' }).rows).toEqual([]);
  expect(calculateLocalRankings(history, { ...clean, board: 'modded', boosts }).rows).toEqual([]);
  expect(calculateLocalRankings(history, { ...daily, board: 'daily-classic', boosts }).rows).toEqual([]);
});

test('excludes unsupported, tampered, malformed, quit and ambiguous IDs and collapses duplicate analyses', () => {
  const legacy = record('legacy', { hashV: undefined });
  const unknown = record('unknown', { hashV: 99 });
  // Current verification deliberately falls back to v1 for both. This narrower cohort does not.
  expect([legacy, unknown].map(verifyLedgerHash)).toEqual([true, true]);
  const good = record('good');
  const history = [
    null, 123, [], legacy, unknown, good, { ...good, initials: 'ABC' },
    record('collision'), record('collision', { seed: 'OTHER' }),
    { ...record('tampered'), score: 1000 },
    record('negative', { distanceM: -1 }), record('bad-tricks', { tricks: { x: NaN } }),
    record('bad-mask', { biomeMask: -1 }), record('missing', { maxAirtimeMs: undefined }),
    record('quit', { cause: 'quit' }), record('no-initials', { initials: '' }),
    record('imported', { imported: true }),
  ];
  expect(ids(calculateLocalRankings(history, clean))).toEqual(['good']);
  expect(calculateLocalRankings(history, clean)).toEqual(calculateLocalRankings([...history].reverse(), clean));
  expect(ids(calculateLocalRankings(history, { ...clean, seed: 'OTHER' }))).toEqual([]);
});

test('normalizes signed zeros so duplicate order does not change values', () => {
  const positive = record('zero', { distanceM: 0, score: 0, maxAirtimeMs: 0 });
  const signed = record('zero', { distanceM: -0, score: -0, maxAirtimeMs: -0 });
  expect(calculateLocalRankings([positive, signed], clean)).toEqual(calculateLocalRankings([signed, positive], clean));
});

test('consumes the public SaveStore recent-history API without reading or mutating standings', async () => {
  const source = new SaveStore();
  await source.saveRun(record('imported'));
  const store = new SaveStore();
  await store.saveRun(record('local'));
  await store.saveRun(record('uninitialed', { initials: '' }));
  expect(await store.importSharecode(await source.exportSharecode())).toEqual({ imported: 1, skipped: 0 });
  const history = await store.getRecentRuns(10);
  const storesBefore = await store.getRecentRuns(10);
  const standingsBefore = await store.getLeaderboard();
  for (const run of history) {
    Object.freeze(run.tricks);
    Object.freeze(run);
  }
  Object.freeze(history);
  expect(ids(calculateLocalRankings(history, clean))).toEqual(['local']);
  expect(await store.getRecentRuns(10)).toEqual(storesBefore);
  expect(await store.getLeaderboard()).toEqual(standingsBefore);
});

test('requires a bounded input and an explicit valid selection', () => {
  expect(() => calculateLocalRankings(null, clean)).toThrow(TypeError);
  expect(() => calculateLocalRankings(Array(MAX_LOCAL_RANKING_RECORDS + 1), clean)).toThrow(RangeError);
  expect(() => calculateLocalRankings([], { ...clean, biomeMask: undefined })).toThrow(TypeError);
  expect(() => calculateLocalRankings([], { ...clean, board: 'world' })).toThrow(TypeError);
  expect(() => calculateLocalRankings([], { ...clean, boosts: ['futureBoost'] })).toThrow(TypeError);
  expect(() => calculateLocalRankings([], { ...clean, upgradeRanks: { future: 2 } })).toThrow(TypeError);
});/** Follow-up 1: BEST and DIED HERE labels never overprint, whatever the x gap or slope (pure, systems/MarkerLayout.js). */
import { layoutMarkerLabels, joinedMarkerHeight, NEAR_PX, BEST_LABEL_RISE, DEATH_LABEL_RISE } from '../../src/systems/MarkerLayout.js';

const W = 170; // wider than any real label at 12px monospace ("DIED HERE 9999m" is ~110px)
const H = 16;  // label height (12px font)
const BX = 5000;

/** Label rectangle: bottom edge at p.y, text hangs left of p.x for originX 1, centred for 0.5. */
function rect(p) {
  const left = p.originX === 1 ? p.x - W : p.x - W / 2;
  return { l: left, r: left + W, t: p.y - H, b: p.y };
}
const hit = (a, b) => a.l < b.r && b.l < a.r && a.t < b.b && b.t < a.b;
const poleHits = (poleX, poleY, height, r) => poleX > r.l && poleX < r.r && r.b > poleY - height && r.t < poleY;

const DX = [0, 1, 5, 40, 79, 150, 219, 220, 400, -3, -40, -150, -219, -300];
const DY = [0, 30, -30, 70, -70]; // terrain y at the death pole relative to the BEST pole (slope)

describe('layoutMarkerLabels', () => {
  const cases = [];
  for (const dx of DX) for (const dy of DY) cases.push([dx, dy]);

  test.each(cases)('death %i px / %i dy from best: the two labels never overprint', (dx, dy) => {
    const L = layoutMarkerLabels({ x: BX, y: 600 }, { x: BX + dx, y: 600 + dy });
    expect(hit(rect(L.best), rect(L.death))).toBe(false);
  });

  test.each(cases)('death %i px / %i dy from best: no pole crosses either label', (dx, dy) => {
    const best = { x: BX, y: 600 };
    const death = { x: BX + dx, y: 600 + dy };
    const L = layoutMarkerLabels(best, death);
    for (const r of [rect(L.best), rect(L.death)]) {
      expect(poleHits(best.x, best.y, 90, r)).toBe(false);
      expect(poleHits(death.x, death.y, 118, r)).toBe(false);
    }
  });

  test('near poles: both labels hang left of the leftmost pole on one anchor, DIED HERE above BEST', () => {
    const L = layoutMarkerLabels({ x: BX, y: 600 }, { x: BX + 4, y: 600 });
    expect(L.best.originX).toBe(1);
    expect(L.death.originX).toBe(1);
    expect(L.best.x).toBe(L.death.x);
    expect(L.best.x).toBeLessThan(BX);
    expect(L.death.y).toBeLessThan(L.best.y);
  });

  test('far poles: each label stays centred over its own pole at the stock height', () => {
    const L = layoutMarkerLabels({ x: BX, y: 600 }, { x: BX + NEAR_PX, y: 640 });
    expect(L.best).toEqual({ x: BX, y: 600 - BEST_LABEL_RISE, originX: 0.5 });
    expect(L.death).toEqual({ x: BX + NEAR_PX, y: 640 - DEATH_LABEL_RISE, originX: 0.5 });
  });

  test('only one marker (or terrain y not known yet): that label keeps its stock placement', () => {
    expect(layoutMarkerLabels({ x: BX, y: 600 }, null)).toEqual({ best: { x: BX, y: 600 - BEST_LABEL_RISE, originX: 0.5 }, death: null });
    expect(layoutMarkerLabels(null, { x: BX, y: 600 })).toEqual({ best: null, death: { x: BX, y: 600 - DEATH_LABEL_RISE, originX: 0.5 } });
    expect(layoutMarkerLabels({ x: BX, y: 600 }, { x: BX, y: NaN }).death).toBe(null);
  });
});


describe('#253 marker heights are read-only and require physically joined terrain', () => {
  const chunk = (startX, ys) => ({
    startX, endX: startX + 1600,
    points: ys.map((y, i) => ({x: startX + i * 800, y})),
  });
  const joined = () => new Map([
    [0, chunk(0, [300, 500, 700])],
    [1, chunk(1600, [700, 800, 900])],
  ]);

  test('out-of-window markers never prequeue or query another terrain accessor', () => {
    const mesh = joined();
    for (const x of [4500, 5600, 9000, -200, NaN, Infinity]) {
      expect(joinedMarkerHeight(x, mesh)).toBeNaN();
    }
    // Even when inside the marker lookahead radius, the marker is deferred.
    const markerX=4500, sledX=2000;
    expect(markerX-sledX).toBeLessThan(2600);
    expect(joinedMarkerHeight(markerX,mesh)).toBeNaN();
    mesh.set(2, chunk(3200,[900,1100,1300]));
    expect(joinedMarkerHeight(markerX,mesh)).toBeCloseTo(1225);
  });

  test('exact joined polyline interpolation (including both sides of chunk seam)', () => {
    const mesh=joined();
    const samples = new Map([
      [0,300],[400,400],[800,500],[1200,600],[1599,699.75],
      [1600,700],[1600.001,700.000125],[2000,750],[2400,800],[3199,899.875],[3200,900],
    ]);
    for(const [x,y] of samples) expect(joinedMarkerHeight(x,mesh)).toBeCloseTo(y,7);
    // Both neighboring joined chunks interpolate the same shared endpoint.
    const reversed=new Map([...mesh].reverse());
    expect(joinedMarkerHeight(1600,reversed)).toBe(joinedMarkerHeight(1600,mesh));
    expect(joinedMarkerHeight(1600.001,reversed)).toBe(joinedMarkerHeight(1600.001,mesh));
  });

  test('marker lookups cannot mutate a generator chunk cache even at the seam', () => {
    const mesh=joined();
    // Deliberately model a generator whose cached-chunk choice would change a
    // subsequent slope calculation; this function accepts ONLY mesh geometry.
    const generator={_lastChunk:{index:777,startX:0,endX:1600},_pendingAdded:[],
      heightAt:()=>{throw Error('unwanted mutation path: TerrainGenerator.heightAt');}};
    const saved=generator._lastChunk;
    for(let i=0;i<15;i++) for(const x of [1599.99,1600,1600.01]) {
      expect(Number.isFinite(joinedMarkerHeight(x,mesh))).toBe(true);
      expect(generator._lastChunk).toBe(saved);
    }
    expect(generator._pendingAdded).toHaveLength(0);
  });

  test('only physically joined valid chunks can yield a height; malformed inputs fail closed', () => {
    const mesh=joined();
    expect(joinedMarkerHeight(1200,null)).toBeNaN();
    expect(joinedMarkerHeight(1200,new Map())).toBeNaN();
    expect(joinedMarkerHeight(1200,new Map([[1,{startX:0,endX:1600}]]))).toBeNaN();
    expect(joinedMarkerHeight(1200,new Map([[1,{startX:0,endX:1600,points:[{x:0,y:0}]}]]))).toBeNaN();
    expect(joinedMarkerHeight(1200,new Map([[1,{startX:NaN,endX:Infinity,points:[{x:0,y:0},{x:1,y:1}]}]]))).toBeNaN();
    mesh.delete(0);
    expect(joinedMarkerHeight(800,mesh)).toBeNaN();
  });
});/** Issue #253: fail if either real marker is ever handed the mutating heightFn. */
import { readFileSync } from 'node:fs';
import { BestMarker } from '../../src/entities/BestMarker.js';
import { LastDeathMarker } from '../../src/entities/LastDeathMarker.js';
import { joinedMarkerHeight } from '../../src/systems/MarkerLayout.js';

function fakeDrawObject() {
  return {
    visible:false, text:'',
    setDepth(){return this;}, setOrigin(){return this;}, setVisible(v){this.visible=v;return this;},
    setPosition(){return this;}, setColor(){return this;}, setText(t){this.text=t;return this;},
    lineStyle(){return this;}, lineBetween(){return this;}, clear(){return this;},
    fillStyle(){return this;}, fillRect(){return this;}, destroy(){return this;},
  };
}
const scene={add:{graphics:fakeDrawObject,text:fakeDrawObject}};
const palette={lime:0x00ff00,amber:0xffff00,danger:0xff0000};
const points=(startX, ys) => ({
  startX,endX:startX+1600,points:ys.map((y,i)=>({x:startX+i*800,y})),
});

test('RunScene wires both marker update methods exclusively to joined collision geometry',()=>{
  const source=readFileSync(new URL('../../src/scenes/RunScene.js',import.meta.url),'utf8');
  expect(source).toMatch(/this\.markerHeightFn\s*=\s*\(x\)\s*=>\s*joinedMarkerHeight\(x,\s*this\.mesh\.chunks\)/);
  expect(source).toMatch(/this\.bestMarker\.update\(t,\s*sled\.x,\s*this\.markerHeightFn\)/);
  expect(source).toMatch(/this\.deathMarker\.update\(t,\s*sled\.x,\s*this\.markerHeightFn\)/);
  expect(source).not.toMatch(/this\.(?:bestMarker|deathMarker)\.update\([^;]*this\.heightFn/);
});

test.each([['BEST',BestMarker],['DIED HERE',LastDeathMarker]])('%s actual marker defers outside joined mesh then draws at exact joined height without terrain generator call',(_name,Marker)=>{
  const marker=new Marker(scene,palette,4500,225);
  const joined=new Map([[0,points(0,[400,500,600])]]);
  const generator={_lastChunk:Symbol('left-neighbor'),_pendingAdded:[],activeList:[],
    heightAt:()=>{throw Error('CRITICAL: marker invoked mutating TerrainGenerator.heightAt');}};
  const firstCache=generator._lastChunk;
  const heightFn=(x)=>joinedMarkerHeight(x,joined);
  // The marker is within 2600px lookahead but no chunk is physically joined there.
  marker.update(1000,2000,heightFn);
  expect(marker.y).toBeNull(); expect(marker.label.visible).toBe(false);
  expect(generator._lastChunk).toBe(firstCache);
  joined.set(2,points(3200,[900,1100,1300]));
  marker.update(1000,2000,heightFn);
  expect(marker.y).toBe(1225);expect(marker.label.visible).toBe(true);
  expect(generator._lastChunk).toBe(firstCache);
  expect(generator._pendingAdded).toHaveLength(0);
  expect(generator.activeList).toHaveLength(0);
});/**
 * Marvin decision 7: in the open Game Over shop Enter / pad A buy, so retry needs keys of its own. MenuInput
 * gains an OPT-IN `retry` action (`{ retryAction: true }`, used only by GameOverScene):
 *   - keyboard Space fires 'retry' FIRST, then its usual 'confirm' (InputRouter sends Space as 'hop' +
 *     'confirm'; Enter as 'confirm' only, so a keyboard-sourced 'hop' is always Space);
 *   - pad RB (button 5, free in both MenuInput and the menu half of InputRouter) fires 'retry'.
 * Pad A also arrives as 'hop', but from source 'gamepad', so it stays a plain 'confirm' (buy).
 * Without the option nothing changes, so TitleScene and PauseScene never see the new action.
 *
 * Driven through the real constructor and both input paths (InputRouter events and Phaser keydown), not by
 * reading the source.
 */
import { jest } from '@jest/globals';

jest.unstable_mockModule('phaser', () => ({ default: { Scenes: { Events: { UPDATE: 'update' } } } }));
const { MenuInput } = await import('../../src/ui/MenuInput.js');
const { EVT } = await import('../../src/events.js');

/** A tiny emitter with on/off/once/emit, enough for game.events, scene.events and the keyboard plugin. */
function emitter() {
  const m = new Map();
  return {
    on(e, f) { if (!m.has(e)) m.set(e, new Set()); m.get(e).add(f); return this; },
    once(e, f) { return this.on(e, f); },
    off(e, f) { if (m.has(e)) m.get(e).delete(f); return this; },
    emit(e, ...a) { for (const f of [...(m.get(e) || [])]) f(...a); },
  };
}

let pads = [];
beforeAll(() => {
  Object.defineProperty(window.navigator, 'getGamepads', { configurable: true, value: () => pads });
});
afterEach(() => { pads = []; });

function rig(opts) {
  const gameEvents = emitter();
  const keyboard = emitter();
  const sceneEvents = emitter();
  const scene = {
    game: { events: gameEvents, registry: { get: () => null } },
    input: { keyboard, on() {}, off() {} },
    events: sceneEvents,
  };
  const got = [];
  const mi = new MenuInput(scene, (a, src) => got.push(`${a}:${src}`), opts);
  return {
    got, mi,
    router: (action, source = 'keyboard') => gameEvents.emit(EVT.INPUT_ACTION, { action, pressed: true, source }),
    key: (key) => keyboard.emit('keydown', { key, repeat: false }),
    frame: () => sceneEvents.emit('update', 0, 16),
  };
}

const pad = (pressed) => [{ connected: true, axes: [0, 0], buttons: Array.from({ length: 16 }, (_, i) => ({ pressed: pressed.includes(i) })) }];

describe('retryAction: true (Game Over)', () => {
  test('Space through InputRouter fires retry, then confirm; the router\'s own confirm twin is deduped', () => {
    const r = rig({ retryAction: true });
    r.router('hop'); r.router('confirm');
    expect(r.got).toEqual(['retry:keyboard', 'confirm:keyboard']);
  });

  test('Enter through InputRouter is confirm only', () => {
    const r = rig({ retryAction: true });
    r.router('confirm');
    expect(r.got).toEqual(['confirm:keyboard']);
  });

  test('pad A through InputRouter is confirm only (it buys)', () => {
    const r = rig({ retryAction: true });
    r.router('hop', 'gamepad'); r.router('confirm', 'gamepad');
    expect(r.got).toEqual(['confirm:gamepad']);
  });

  test('Space and Enter through Phaser\'s keyboard (no router) behave the same', () => {
    const r = rig({ retryAction: true });
    r.key(' ');
    expect(r.got).toEqual(['retry:keyboard', 'confirm:keyboard']);
    const e = rig({ retryAction: true });
    e.key('Enter');
    expect(e.got).toEqual(['confirm:keyboard']);
  });

  test('pad RB fires retry once per press; pad A from the poll stays confirm', () => {
    const r = rig({ retryAction: true });
    pads = pad([5]); r.frame(); r.frame();
    expect(r.got).toEqual(['retry:gamepad']);
    const a = rig({ retryAction: true });
    pads = pad([0]); a.frame();
    expect(a.got).toEqual(['confirm:gamepad']);
  });

  test('while text entry owns the keyboard, Space does not fire retry through the router', () => {
    const r = rig({ retryAction: true });
    r.mi.rawKeyHandler = () => true;
    r.router('hop'); r.router('confirm');
    expect(r.got).toEqual([]);
  });
});

describe('without the option nothing changes (Title, Pause)', () => {
  test('Space is confirm only, and RB does nothing', () => {
    const r = rig();
    r.router('hop'); r.router('confirm'); r.key(' ');
    expect(r.got).toEqual(['confirm:keyboard']);
    const p = rig();
    pads = pad([5]); p.frame();
    expect(p.got).toEqual([]);
  });
});/**
 * Micro Mountain glow-up: HUGE bees in the backdrop (cosmetic only).
 *
 * SledHEAD canon: Micro Mountain is Pete's bee meadow, ridden as an RC micro sled drone, so ordinary bees are
 * HUGE next to the rider. These pin the pure placement/motion (src/systems/MicroBees.js) and how the
 * dew-drops backdrop draws it: few, big, slow, seeded, low-alpha, palette keys only, behind the terrain.
 */
import fs from 'fs';
import { GAME_WIDTH, GAME_HEIGHT } from '../../src/constants.js';
import { beesAt, beePrimitives, beeLayout, BEE_MAX_FILL_ALPHA, BEE_MAX_LINE_ALPHA } from '../../src/systems/MicroBees.js';
import { Background, motifDecor, motifGeometry, MOTIFS } from '../../src/entities/Background.js';

const SCROLLS = [];
for (let x = 0; x < 80_000; x += 613) SCROLLS.push(x);
const TIMES = [0, 900, 5_000, 31_000, 120_000];
const XM = 96; // the W6 decor overhang rule (biome-backdrops-w6.test.js)
const PALETTE_KEYS = ['bg', 'bgAlt', 'cyan', 'magenta', 'lime', 'amber', 'text'];
const pointsOf = (d) => (d.kind === 'circle' ? [{ x: d.x - d.r, y: d.y - d.r }, { x: d.x + d.r, y: d.y + d.r }] : d.pts);

describe('MicroBees: placement and motion (pure)', () => {
  test('deterministic: same scroll, time and seed give the same bees', () => {
    for (const x of [0, 4321, 77_777]) expect(beesAt(x, 1234, 0)).toEqual(beesAt(x, 1234, 0));
  });

  test('seeded: another seed lays the bees out differently', () => {
    expect(beeLayout(0)).not.toEqual(beeLayout(7));
    expect(beeLayout(3)).toEqual(beeLayout(3));
  });

  test('few: never more than two bees on screen, and some screens have one', () => {
    let most = 0;
    let withBee = 0;
    let n = 0;
    for (const x of SCROLLS) {
      for (const t of TIMES) {
        const b = beesAt(x, t, 0);
        most = Math.max(most, b.length);
        if (b.length) withBee += 1;
        n += 1;
      }
    }
    expect(most).toBeLessThanOrEqual(2);
    expect(withBee / n).toBeGreaterThan(0.25);
    expect(withBee / n).toBeLessThan(0.9);
  });

  test('HUGE: each bee stands a quarter to a half of the screen height', () => {
    let seen = 0;
    for (const x of SCROLLS) {
      for (const bee of beesAt(x, 2000, 0)) {
        const pts = beePrimitives([bee], 1).flatMap(pointsOf);
        const ys = pts.map((p) => p.y);
        const h = Math.max(...ys) - Math.min(...ys);
        expect(h).toBeGreaterThanOrEqual(0.25 * GAME_HEIGHT);
        expect(h).toBeLessThanOrEqual(0.5 * GAME_HEIGHT);
        seen += 1;
      }
    }
    expect(seen).toBeGreaterThan(10);
  });

  test('slow: with the camera still, a bee drifts under 20 px a second', () => {
    for (const x of [500, 9000, 40_000]) {
      const a = beesAt(x, 10_000, 0);
      const b = beesAt(x, 11_000, 0);
      for (const bee of a) {
        const same = b.find((o) => o.id === bee.id);
        if (same) expect(Math.abs(same.x - bee.x)).toBeLessThan(20);
      }
    }
  });

  test('wings a blur: the flap changes from frame to frame (scene time only)', () => {
    let changed = false;
    for (const x of SCROLLS) {
      const a = beesAt(x, 1000, 0);
      const b = beesAt(x, 1016, 0);
      if (a.length && b.length && a[0].flap !== b[0].flap) { changed = true; break; }
    }
    expect(changed).toBe(true);
  });

  test('no Math.random or Date.now anywhere in the module', () => {
    const src = fs.readFileSync('src/systems/MicroBees.js', 'utf8');
    expect(src).not.toMatch(/Math\.random\(|Date\.now\(|performance\.now\(|from 'phaser'/);
  });
});

describe('MicroBees: what is drawn', () => {
  const all = [];
  for (const x of SCROLLS) for (const t of TIMES) all.push(...beePrimitives(beesAt(x, t, 0), 1));

  test('there is something to check', () => {
    expect(all.length).toBeGreaterThan(100);
  });

  test('palette keys only, never danger', () => {
    for (const d of all) expect(PALETTE_KEYS).toContain(d.color);
  });

  test('low alpha everywhere, so hazards and pickups keep their contrast', () => {
    for (const d of all) {
      if (d.kind === 'line') expect(d.alpha).toBeLessThanOrEqual(BEE_MAX_LINE_ALPHA);
      else {
        if (d.color !== 'bg') expect(d.fillAlpha).toBeLessThanOrEqual(BEE_MAX_FILL_ALPHA);
        expect(d.lineAlpha).toBeLessThanOrEqual(BEE_MAX_LINE_ALPHA);
      }
    }
    expect(BEE_MAX_FILL_ALPHA).toBeLessThanOrEqual(0.12);
    expect(BEE_MAX_LINE_ALPHA).toBeLessThanOrEqual(0.35);
  });

  test('inside the W6 decor bounds (0..270 high, 96 px overhang left and right), circles under r 40', () => {
    for (const d of all) {
      for (const p of pointsOf(d)) {
        const ok = Number.isFinite(p.x) && Number.isFinite(p.y) && p.x >= -XM && p.x <= GAME_WIDTH + XM && p.y >= 0 && p.y <= GAME_HEIGHT;
        if (!ok) throw new Error(`${d.kind} point (${p.x}, ${p.y}) off screen`);
      }
      if (d.kind === 'circle') expect(d.r > 0 && d.r < 40).toBe(true);
    }
  });

  test('every primitive carries the depth it was asked for and its bee tag', () => {
    const b = beesAt(SCROLLS.find((x) => beesAt(x, 0, 0).length), 0, 0);
    for (const d of beePrimitives(b, 3)) {
      expect(d.depth).toBe(3);
      expect(Number.isInteger(d.bee)).toBe(true);
    }
  });
});

describe('MicroBees in the dew-drops backdrop', () => {
  const beeX = SCROLLS.find((x) => beesAt(x, 0, 0).length > 0);
  const last = motifGeometry('dew-drops', 0).layers.length - 1;

  test('Micro Mountain\'s dew-drops decor includes the bees, after the near silhouette layer', () => {
    const decor = motifDecor('dew-drops', beeX, 0, 0);
    const bees = decor.filter((d) => d.bee !== undefined);
    expect(bees.length).toBeGreaterThan(0);
    for (const d of bees) expect(d.depth).toBe(last);
    // drawn after the near layer's own decor, so a bee is over the moss and blades, under the terrain
    expect(decor.findIndex((d) => d.bee !== undefined)).toBeGreaterThan(decor.findIndex((d) => d.depth === last));
  });

  test('{bees:false} draws the same backdrop without them', () => {
    const on = motifDecor('dew-drops', beeX, 0, 0);
    const off = motifDecor('dew-drops', beeX, 0, 0, { bees: false });
    expect(off).toEqual(on.filter((d) => d.bee === undefined));
  });

  test('no other motif has bees', () => {
    for (const m of MOTIFS.filter((id) => id !== 'dew-drops')) {
      for (const x of SCROLLS.slice(0, 40)) expect(motifDecor(m, x, 0, 0).some((d) => d.bee !== undefined)).toBe(false);
    }
  });

  const recordingScene = () => {
    const gfx = new Proxy({}, { get: (_, k) => (k === 'setScrollFactor' || k === 'setDepth' ? () => gfx : () => gfx) });
    return { add: { graphics: () => gfx } };
  };
  const PAL = { bg: 1, bgAlt: 2, cyan: 3, magenta: 4, lime: 5, amber: 6, text: 7, danger: 8 };

  test('Background counts the bees it drew: some on Micro, none elsewhere', () => {
    const bg = new Background(recordingScene(), PAL);
    bg.setMotif('dew-drops');
    bg.update(beeX, 0, 0);
    expect(bg.beeCount).toBeGreaterThan(0);
    bg.setMotif(null);
    bg.update(beeX, 0, 0);
    expect(bg.beeCount).toBe(0);
    bg.setMotif('vents');
    bg.update(beeX, 0, 0);
    expect(bg.beeCount).toBe(0);
  });

  test('Background.bees = false (the perf comparison switch) draws none', () => {
    const bg = new Background(recordingScene(), PAL);
    bg.setMotif('dew-drops');
    bg.bees = false;
    bg.update(beeX, 0, 0);
    expect(bg.beeCount).toBe(0);
  });
});

/** WCAG relative luminance and contrast, for the hazard-contrast bound below. */
const lum = (hex) => {
  const c = [1, 3, 5].map((i) => parseInt(hex.slice(i, i + 2), 16) / 255).map((v) => (v <= 0.03928 ? v / 12.92 : ((v + 0.055) / 1.055) ** 2.4));
  return 0.2126 * c[0] + 0.7152 * c[1] + 0.0722 * c[2];
};
const contrast = (a, b) => { const [x, y] = [lum(a), lum(b)].sort((p, q) => q - p); return (x + 0.05) / (y + 0.05); };
const blend = (base, top, a) => `#${[1, 3, 5].map((i) => Math.round(parseInt(base.slice(i, i + 2), 16) * (1 - a) + parseInt(top.slice(i, i + 2), 16) * a).toString(16).padStart(2, '0')).join('')}`;

const inPoly = (x, y, pts) => {
  let c = false;
  for (let i = 0, j = pts.length - 1; i < pts.length; j = i++) {
    const a = pts[i]; const b = pts[j];
    if ((a.y > y) !== (b.y > y) && x < ((b.x - a.x) * (y - a.y)) / (b.y - a.y) + a.x) c = !c;
  }
  return c;
};

describe('MicroBees: hazard and pickup contrast (worst case)', () => {
  const PALETTES = JSON.parse(fs.readFileSync('src/data/palettes.json', 'utf8'));
  const MICRO = JSON.parse(fs.readFileSync('src/data/biomes/micro-mountain.json', 'utf8'));
  // Rasterise real bees on a 2 px grid over plain sky (fills composited in draw order) and keep the brightest
  // pixel a bee can put behind a hazard. "As readable as now" = no worse than the brightest thing the Micro
  // backdrop ALREADY puts behind a hazard: the near moss layer (cyan 0.08) under a grass blade (lime 0.18).
  test.each(['default', 'colorblind'])('%s palette: a Dew Drop (danger) or Royal Jelly (amber) in front of a bee keeps at least the contrast it has against the existing Micro backdrop', (name) => {
    const pal = { ...PALETTES[name], ...MICRO.palettes[name] };
    const existing = blend(blend(pal.bg, pal.cyan, 0.08), pal.lime, 0.18);
    let worst = pal.bg;
    let samples = 0;
    for (let x = 0; x < 40_000; x += 997) {
      for (const bee of beesAt(x, 3000, 0)) {
        const prims = beePrimitives([bee], 1).filter((d) => d.kind !== 'line' && d.fillAlpha > 0);
        for (let gx = bee.x - 80; gx < bee.x + 80; gx += 2) {
          for (let gy = bee.y - 70; gy < bee.y + 50; gy += 2) {
            let c = pal.bg;
            for (const d of prims) {
              const inside = d.kind === 'circle' ? (gx - d.x) ** 2 + (gy - d.y) ** 2 <= d.r * d.r : inPoly(gx, gy, d.pts);
              if (inside) c = blend(c, pal[d.color], d.fillAlpha);
            }
            if (lum(c) > lum(worst)) worst = c;
            samples += 1;
          }
        }
      }
    }
    expect(samples).toBeGreaterThan(10_000);
    expect(worst).not.toBe(pal.bg); // the bees are actually there
    for (const target of ['danger', 'amber']) {
      expect({ name, target, ok: contrast(pal[target], worst) >= contrast(pal[target], existing) })
        .toEqual({ name, target, ok: true });
    }
  });
});/**
 * Micro Mountain glow-up: the real Sled draw path draws the Neon Sled Drone when the look says so.
 *
 * Sled.js is a Phaser entity; like cosmetics-complete, this drives its `_draw` on a bare prototype with a
 * recording Graphics, so the drone is checked on the code that paints the screen, not on the resolver alone.
 */
import fs from 'fs';
import { jest } from '@jest/globals';
import { runRandomStreams } from '../../src/systems/RunRandom.js';

jest.unstable_mockModule('phaser', () => ({
  default: { Physics: { Matter: { Matter: { Bodies: {}, Body: { getVelocity: () => ({ x: 0, y: 0 }) } } } } },
}));

const { resolveCosmetics, COSMETIC_HUES } = await import('../../src/systems/Cosmetics.js');
const { Sled } = await import('../../src/entities/Sled.js');

const PALETTES = JSON.parse(fs.readFileSync('src/data/palettes.json', 'utf8'));
const ints = (hex) => Object.fromEntries(Object.entries(hex).map(([k, v]) => [k, parseInt(v.slice(1), 16)]));
const HEX = PALETTES.default;
const INTS = ints(HEX);
const CB = PALETTES.colorblind;
const CB_INTS = ints(CB);
const int = (h) => parseInt(h.slice(1), 16);
const DRONE_LOOK = resolveCosmetics({ equipped: { rider: 'drone' } }, INTS, HEX);

/** A Graphics stand-in that records every call with its arguments. */
function recordingGfx() {
  const calls = [];
  const g = new Proxy({}, { get: (_, k) => (k === 'calls' ? calls : (...a) => { calls.push([k, ...a]); return g; }) });
  return g;
}

function drawSled(look, { palette = INTS, time = 0, pose = {}, scrambled = false } = {}) {
  const s = Object.create(Sled.prototype);
  Object.assign(s, {
    gfx: recordingGfx(), palette, look,
    body: { angle: 0, position: { x: 100, y: 100 } }, off: { x: 0, y: 0 },
    heliPhase: 0, heliVel: 0, squash: 0, pose: { chute: 0, phi: 10, tuck: 0, brake: 0, ...pose },
    invulnerableMs: 0, _time: time, scrambled, shield: false, msSinceContact: 0, heliInput: 0,
    random: runRandomStreams('drone-test'),
  });
  s._draw();
  return s;
}
const colours = (s) => s.gfx.calls.filter((c) => c[0] === 'fillStyle' || c[0] === 'lineStyle').map((c) => (c[0] === 'fillStyle' ? c[1] : c[2]));
// The neon rider's helmet: an amber disc of radius 4.6 (Sled._draw). The drone has no helmet.
const helmets = (s) => s.gfx.calls.filter((c) => c[0] === 'fillCircle' && c[3] === 4.6).length;

describe('Neon Sled Drone: Sled draws it', () => {
  test('the default look draws the neon rider (helmet) and records shape default', () => {
    const s = drawSled(null);
    expect(s.lastRiderShape).toBe('default');
    expect(helmets(s)).toBe(1);
  });

  test('the drone look draws the drone instead of the rider, in its own frame colour', () => {
    const s = drawSled(DRONE_LOOK);
    expect(s.lastRiderShape).toBe('drone');
    expect(helmets(s)).toBe(0);
    expect(colours(s)).toContain(int(COSMETIC_HUES.rider.drone.color));
    // Two rotor discs, each a closed ring of points, and a blinking light on each rotor arm.
    expect(s.drone.rotors).toHaveLength(2);
    expect(s.drone.lights).toHaveLength(2);
  });

  test('the rotor lights blink from sled time, alternating between the two arms', () => {
    const a = drawSled(DRONE_LOOK, { time: 0 }).drone.lights.map((l) => l.on);
    const b = drawSled(DRONE_LOOK, { time: 260 }).drone.lights.map((l) => l.on);
    expect(a[0]).not.toBe(a[1]);
    expect(b).toEqual([!a[0], !a[1]]);
  });

  test('the rotor blades turn from sled time', () => {
    const a = drawSled(DRONE_LOOK, { time: 0 }).drone.rotors[0].blade;
    const b = drawSled(DRONE_LOOK, { time: 40 }).drone.rotors[0].blade;
    expect(a).not.toEqual(b);
  });

  test('colourblind: the drone is drawn in palette colours only (no cosmetic hue)', () => {
    const look = resolveCosmetics({ equipped: { rider: 'drone' } }, CB_INTS, CB, { colorblind: true });
    const s = drawSled(look, { palette: CB_INTS });
    expect(s.lastRiderShape).toBe('drone');
    const allowed = new Set(Object.values(CB_INTS));
    for (const c of colours(s)) expect(allowed.has(c)).toBe(true);
    expect(colours(s)).not.toContain(CB_INTS.danger);
  });

  test('never drawn in the hazard colour', () => {
    expect(colours(drawSled(DRONE_LOOK))).not.toContain(INTS.danger);
  });

  test('a scramble still overrides the frame colour, as it does for the rider', () => {
    const s = drawSled(DRONE_LOOK, { scrambled: true });
    expect(colours(s)).not.toContain(int(COSMETIC_HUES.rider.drone.color));
  });
});

describe('Wind pom-pom helmet and drone attachment', () => {
  test('stays on the transformed helmet crown through lean, flip, and COM offset', () => {
    const s = drawSled(null, { pose: { phi: -28, tuck: 0.7 } });
    const circles = s.gfx.calls.filter(c => c[0] === 'fillCircle' && c[3] === 4.6);
    const helmet = circles[circles.length - 1];
    const distance = (a, h) => Math.hypot(a.x - h[1], a.y - h[2]);
    expect(s.windPomAnchor).toBeDefined();
    expect(distance(s.windPomAnchor, helmet)).toBeCloseTo(5.5, 3);
    const before = { ...s.windPomAnchor };

    // A center-of-mass offset, 90-degree body flip, and yaw must change the tether
    // in exactly the same frame as they change the rendered helmet.
    s.body.angle = Math.PI / 2;
    s.off = { x: 7, y: -12 };
    s.heliPhase = 165;
    s.gfx.calls.length = 0;
    s._draw();
    const turnedHelmet = s.gfx.calls.find(c => c[0] === 'fillCircle' && c[3] === 4.6);
    expect(s.windPomAnchor).not.toEqual(before);
    expect(Math.abs(distance(s.windPomAnchor, turnedHelmet) - 5.5)).toBeLessThan(0.12); // helicopter yaw foreshortens the crown offset
  });

  test('the drone skin attaches the wind indicator to its transformed rotor mast', () => {
    const s = drawSled(DRONE_LOOK);
    const a = { ...s.windPomAnchor };
    expect(a).toMatchObject({ x: expect.any(Number), y: expect.any(Number) });
    s.body.angle = Math.PI / 3;
    s.off = { x: 9, y: 5 };
    s.gfx.calls.length = 0;
    s._draw();
    expect(s.windPomAnchor).not.toEqual(a);
    expect(Number.isFinite(s.windPomAnchor.x)).toBe(true);
    expect(Number.isFinite(s.windPomAnchor.y)).toBe(true);
  });
});/**
 * Micro Mountain glow-up: the Neon Sled Drone rider skin.
 *
 * Earned, never bought: completing Micro Mountain (decision 3's `biomeProgress.completed`) owns it, the run
 * that completes it grants it through the credit (with a toast entry after the achievements, decision 9),
 * and it lives in the ordinary rider slot of the one cosmetic catalogue. Its SHAPE survives the colourblind
 * palette (it is drawn in palette colours there); its hue does not, like every other cosmetic hue.
 */
import fs from 'fs';
import { COSMETIC_ITEMS, COSMETIC_HUES, resolveCosmetics, cosmeticInSlot } from '../../src/systems/Cosmetics.js';
import { sanitizeProfile, isOwned, purchase, equip, shopItem } from '../../src/systems/ProfileStore.js';
import { shopLayout, shopMenuItems, SHOP_PAGES, SHOP_PANEL } from '../../src/ui/ShopLayout.js';

const read = (p) => JSON.parse(fs.readFileSync(p, 'utf8'));
const LEVELS = read('src/data/progression/levels.json');
const PALETTES = read('src/data/palettes.json');
const HEX = PALETTES.default;
const CB = PALETTES.colorblind;
const INTS = Object.fromEntries(Object.entries(HEX).map(([k, v]) => [k, parseInt(v.slice(1), 16)]));
const MAX_XP = LEVELS.levels[LEVELS.levels.length - 1].xpMin + 1;
const v1 = (o = {}) => sanitizeProfile({ v: 1, ...o }, LEVELS);
const DRONE = 'rider-drone';

describe('Neon Sled Drone: catalogue entry', () => {
  test('a rider-slot item, price 0, granted by completing Micro Mountain', () => {
    const it = COSMETIC_ITEMS.find((i) => i.id === DRONE);
    expect(it).toMatchObject({
      id: DRONE, kind: 'rider', slot: 'rider', name: 'Neon Sled Drone', price: 0, value: 'drone',
      grant: 'biome', biome: 'micro-mountain', unlockText: 'COMPLETE MICRO MOUNTAIN',
    });
    expect(shopItem(DRONE)).toBe(it);
    expect(cosmeticInSlot('rider', 'drone')).toMatchObject({ id: DRONE, slot: 'rider' });
  });

  test('its hue carries the drone shape and a colour that is not the default rider magenta', () => {
    const hue = COSMETIC_HUES.rider.drone;
    expect(hue.shape).toBe('drone');
    expect(hue.color).toMatch(/^#[0-9a-f]{6}$/i);
    expect(hue.color.toLowerCase()).not.toBe(HEX.magenta.toLowerCase());
  });
});

describe('Neon Sled Drone: ownership', () => {
  test('a level-30 profile with a full bank does NOT own it without the completion', () => {
    const p = v1({ xp: MAX_XP, bank: 99999 });
    expect(p.level).toBe(30);
    expect(isOwned(p, DRONE)).toBe(false);
  });

  test('encountering Micro Mountain is not enough', () => {
    expect(isOwned(v1({ biomeProgress: { encountered: ['micro-mountain'], completed: [] } }), DRONE)).toBe(false);
  });

  test('completing another biome is not enough', () => {
    expect(isOwned(v1({ biomeProgress: { encountered: ['debutmont'], completed: ['debutmont'] } }), DRONE)).toBe(false);
  });

  test('owned once Micro Mountain is completed (decision 3), at any level', () => {
    expect(isOwned(v1({ biomeProgress: { encountered: [], completed: ['micro-mountain'] } }), DRONE)).toBe(true);
  });

  test('owned by its grant record in unlocked.cosmetics', () => {
    expect(isOwned(v1({ unlocked: { cosmetics: [DRONE] } }), DRONE)).toBe(true);
  });

  test('never for sale: purchase refuses it and charges nothing', () => {
    const p = v1({ xp: MAX_XP, bank: 99999 });
    expect(purchase(p, DRONE)).toBe(p);
  });

  test('equip refuses it until owned, then equips the value', () => {
    const locked = v1({ xp: MAX_XP });
    expect(equip(locked, DRONE)).toBe(locked);
    const owned = v1({ biomeProgress: { completed: ['micro-mountain'] } });
    expect(equip(owned, DRONE).equipped.rider).toBe('drone');
  });

  test('the grant record and the equipped value survive a save/load round trip', () => {
    const p = equip(v1({ unlocked: { cosmetics: [DRONE] } }), DRONE);
    const back = v1(JSON.parse(JSON.stringify(p)));
    expect(back.unlocked.cosmetics).toContain(DRONE);
    expect(back.equipped.rider).toBe('drone');
    expect(isOwned(back, DRONE)).toBe(true);
  });
});

describe('Neon Sled Drone: resolver', () => {
  const owned = () => equip(v1({ biomeProgress: { completed: ['micro-mountain'] } }), DRONE);

  test('an unequipped profile draws the default rider shape', () => {
    expect(resolveCosmetics(v1({}), INTS, HEX).riderShape).toBe('default');
  });

  test('the equipped drone resolves to the drone shape and its hue, nothing missing', () => {
    const look = resolveCosmetics(owned(), INTS, HEX);
    expect(look.riderShape).toBe('drone');
    expect(look.rider).toBe(COSMETIC_HUES.rider.drone.color);
    expect(look.missing).toEqual([]);
  });

  test('a colour-only rider hue keeps the default shape', () => {
    expect(resolveCosmetics({ equipped: { rider: 'mint' } }, INTS, HEX).riderShape).toBe('default');
  });

  test('colourblind: the shape survives, the hue is refused (drawn in palette colours)', () => {
    const look = resolveCosmetics(owned(), INTS, CB, { colorblind: true });
    expect(look.overridden).toBe(true);
    expect(look.riderShape).toBe('drone');
    expect(look.rider).toBe(CB.magenta);
  });

  test('an unknown rider value draws the default shape', () => {
    expect(resolveCosmetics({ equipped: { rider: 'hovercraft' } }, INTS, HEX).riderShape).toBe('default');
    expect(resolveCosmetics({ equipped: { rider: 'hovercraft' } }, INTS, HEX, { colorblind: true }).riderShape).toBe('default');
  });
});

describe('Neon Sled Drone: the Shard Shop rider page', () => {
  const page = SHOP_PAGES.indexOf('rider');
  const rowOf = (p) => shopLayout({ profile: p, page }).rows.find((r) => r.id === DRONE);

  test('listed on the rider page as locked, with its condition, and not selectable', () => {
    const row = rowOf(v1({ xp: MAX_XP, bank: 99999 }));
    expect(row).toMatchObject({ kind: 'item', label: 'NEON SLED DRONE', state: 'COMPLETE MICRO MOUNTAIN', locked: true, owned: false, disabled: true });
    const item = shopMenuItems(shopLayout({ profile: v1({ xp: MAX_XP, bank: 99999 }), page })).find((m) => m.id === DRONE);
    expect(item).toMatchObject({ sub: 'COMPLETE MICRO MOUNTAIN', disabled: true });
  });

  test('the locked label and its condition fit the panel without overlapping', () => {
    const row = rowOf(v1({}));
    const [label, right] = row.texts;
    expect(label.x + label.w).toBeLessThan(right.x - 6);
    expect(right.x + right.w).toBeLessThanOrEqual(SHOP_PANEL.w);
  });

  test('once Micro Mountain is completed it reads EQUIP and is selectable; equipped it reads EQUIPPED', () => {
    const p = v1({ biomeProgress: { completed: ['micro-mountain'] } });
    expect(rowOf(p)).toMatchObject({ state: 'EQUIP', owned: true, locked: false, disabled: false });
    expect(rowOf(equip(p, DRONE))).toMatchObject({ state: 'EQUIPPED', equipped: true, disabled: false });
  });
});

describe('Neon Sled Drone: granted as the completion is credited', () => {
  // eslint-disable-next-line global-require
  let creditRun; let toastLayout; let sortAchievements;
  beforeAll(async () => {
    ({ creditRun } = await import('../../src/systems/ProfileStore.js'));
    ({ toastLayout } = await import('../../src/ui/AchievementsLayout.js'));
    ({ sortAchievements } = await import('../../src/systems/Achievements.js'));
  });
  let n = 0;
  const rec = (o = {}) => ({ id: `drone-run-${n += 1}`, distanceM: 600, score: 10, endedAt: 1_700_000_000_000, ...o });
  const visits = (encountered, completed) => ({ biomeVisits: { encountered, completed } });

  test('a run that completes Micro Mountain writes the grant record and reports the grant', () => {
    const out = creditRun(v1({}), rec(), LEVELS, visits(['micro-mountain'], ['micro-mountain']));
    expect(out.profile.unlocked.cosmetics).toContain(DRONE);
    expect(isOwned(out.profile, DRONE)).toBe(true);
    expect(out.awards.grants).toEqual([expect.objectContaining({ id: DRONE, kind: 'cosmetic', grant: 'biome', biome: 'micro-mountain', name: 'Neon Sled Drone' })]);
  });

  test('the toast list carries it: one unlock reads UNLOCKED NEON SLED DRONE plus how to use it', () => {
    // A first credit stamps whatever a short run unlocks, so the second run's only unlock is the drone.
    const first = creditRun(v1({}), rec({ distanceM: 1 }), LEVELS, {});
    const out = creditRun(first.profile, rec({ distanceM: 1 }), LEVELS, visits(['micro-mountain'], ['micro-mountain']));
    expect(out.awards.achievements.map((a) => a.id)).toEqual([DRONE]);
    const toast = toastLayout(out.awards.achievements);
    expect(toast.lines[0].text).toBe('UNLOCKED NEON SLED DRONE');
    expect(toast.lines[1].text).toBe('RIDER SKIN: EQUIP IN SHOP'); // whole, not ellipsized (138 px line)
  });

  test('encountering Micro Mountain without completing it grants nothing', () => {
    const out = creditRun(v1({}), rec(), LEVELS, visits(['micro-mountain'], []));
    expect(out.profile.unlocked.cosmetics).not.toContain(DRONE);
    expect(out.awards.grants).toEqual([]);
    expect(out.awards.achievements.some((a) => a.id === DRONE)).toBe(false);
  });

  test('a run with no visits grants nothing', () => {
    const out = creditRun(v1({}), rec(), LEVELS, {});
    expect(out.awards.grants).toEqual([]);
  });

  test('already completed before this run: no second grant and no second toast', () => {
    const p = v1({ biomeProgress: { completed: ['micro-mountain'] } });
    const out = creditRun(p, rec(), LEVELS, visits(['micro-mountain'], ['micro-mountain']));
    expect(out.awards.grants).toEqual([]);
    expect(out.awards.achievements.some((a) => a.id === DRONE)).toBe(false);
    expect(isOwned(out.profile, DRONE)).toBe(true);
  });

  test('a replayed run (same ledger key) is refused and grants nothing', () => {
    const r = rec();
    const first = creditRun(v1({}), r, LEVELS, visits([], []));
    expect(creditRun(first.profile, r, LEVELS, visits(['micro-mountain'], ['micro-mountain']))).toBeNull();
  });

  test('alongside achievements in one credit: the achievements in decision 9 order, then the grant', () => {
    // Pyramid already seen; this run sees Micro and completes it: biomes-2 (Explorer) unlocks in the same credit.
    const p = v1({ biomeProgress: { encountered: ['pyramid-peak'], completed: [] } });
    const out = creditRun(p, rec({ distanceM: 1200 }), LEVELS, visits(['micro-mountain'], ['micro-mountain']));
    const ids = out.awards.achievements.map((a) => a.id);
    expect(ids).toContain('biomes-2');
    expect(ids[ids.length - 1]).toBe(DRONE);
    const defs = out.awards.achievements.filter((a) => a.id !== DRONE);
    expect(defs.map((a) => a.id)).toEqual(sortAchievements(defs).map((a) => a.id));
    expect(Number.isFinite(out.profile.achievements['biomes-2'])).toBe(true);
    // The grant is never stamped as an achievement (the grid would draw a nameless row).
    expect(out.profile.achievements[DRONE]).toBeUndefined();
    expect(out.profile.unlocked.cosmetics).toEqual(expect.arrayContaining(['trail-hue-aurora', DRONE]));
  });

  test('with more than three unlocks the toast ends +N MORE, and the order is the same every time', () => {
    const p = v1({ biomeProgress: { encountered: ['pyramid-peak'], completed: [] } });
    const r = rec({ distanceM: 5000, score: 999999, maxAirtimeMs: 9000, bestCombo: 50 });
    const a = creditRun(p, r, LEVELS, visits(['micro-mountain'], ['micro-mountain']));
    const b = creditRun(p, { ...r }, LEVELS, visits(['micro-mountain'], ['micro-mountain']));
    expect(a.awards.achievements.map((x) => x.id)).toEqual(b.awards.achievements.map((x) => x.id));
    expect(a.awards.achievements.length).toBeGreaterThan(3);
    const lines = toastLayout(a.awards.achievements).lines.map((l) => l.text);
    expect(lines[lines.length - 1]).toBe(`+${a.awards.achievements.length - 2} MORE`);
  });
});/**
