const c = loadContent();
const without = (o) => Object.fromEntries(Object.entries(o).filter(([, d]) => !LATER_BIOMES.has(d.biome)));

function digest(seed, mask) {
  const g = makeGen(seed, { biomeMask: mask, hazardDefs: without(c.hazards), powerupDefs: without(c.powerups) });
  const h = crypto.createHash('sha256');
  for (let i = 0; i < CHUNKS; i++) h.update(JSON.stringify(g.getChunk(i)));
  return h.digest('hex').slice(0, 16);
}

describe('T2 isolation: terrain of every mask except Micro (512) is unchanged since e080803', () => {
  for (const mask of Object.keys(PINNED)) {
    test(`mask ${mask}`, () => {
      const got = {};
      for (const seed of Object.keys(PINNED[mask])) got[seed] = digest(seed, Number(mask));
      expect(got).toEqual(PINNED[mask]);
    });
  }
});/**
 * Audit T2: Micro Mountain's dew swell must be IN the ground the sled rides.
 *
 * Before this fix the swell was added only by TerrainGenerator.heightAt. The chunk points, which drive the Matter
 * collider and the drawn edge (TerrainMesh) and slopeDegAt, were raw. In the built game the sled tracked the raw
 * collider (sd 1.9 px) and not the swelled heightAt (sd 9.5 px), so the swell was unfelt and every heightAt reader
 * (void check, air forecast, safe respawn) disagreed with the real ground by up to the amplitude.
 *
 * Now the swell displaces the points inside each dewSwell zone, with a raised-cosine taper at both zone edges
 * (`terrainSwell.taperPx`), and heightAt is the plain polyline again. These tests pin ONE surface:
 * points == heightAt == slopeDegAt, the displacement is really there, it starts and ends smoothly, and every
 * spawn sits on the swelled ground.
 */
import fs from 'fs';
import { makeGen, loadContent } from './_helpers.js';
import { MAX_TURN_DEG } from '../../src/systems/TerrainGenerator.js';

const MICRO = 512;
const SEEDS = ['alpha', 'beta', 'swell'];
const CHUNKS = 120;
const CONTENT = loadContent();
const DEW = JSON.parse(fs.readFileSync('src/data/terrainMods/dew-swell.json', 'utf8'));
const SW = DEW.terrainSwell;

/** Linear interpolation of the chunk polyline: exactly the surface TerrainMesh builds colliders from. */
function polylineY(chunk, x) {
  const p = chunk.points;
  let i = 0;
  while (i < p.length - 2 && p[i + 1].x < x) i++;
  const a = p[i];
  const b = p[i + 1];
  return a.y + ((b.y - a.y) * (x - a.x)) / (b.x - a.x);
}

/** Slope (deg) of polyline segment i. */
const segDeg = (p, i) => (Math.atan2(p[i + 1].y - p[i].y, p[i + 1].x - p[i].x) * 180) / Math.PI;

/** Every dew-swell zone in the first `n` chunks of a Micro-only run. */
function swellZones(seed, overrides = {}, n = CHUNKS) {
  const gen = makeGen(seed, { biomeMask: MICRO, ...overrides });
  const out = [];
  for (let i = 0; i < n; i++) {
    const c = gen.getChunk(i);
    for (const z of c.zones) if (z.modId === 'dewSwell') out.push({ c, z, i });
  }
  return { gen, out };
}

/**
 * True when the zone's untapered middle holds both a crest (x0 + P/4) and a trough (x0 + 3P/4) of the sine, so the full
 * 2A swing is there to measure. A whole period would need len >= P + 2T, which a long period rarely fits in 420-900 px.
 */
function swings(z) {
  const len = z.x1 - z.x0;
  const taper = Math.min(SW.taperPx, len / 2);
  return taper <= SW.periodPx / 4 && len >= (3 * SW.periodPx) / 4 + taper;
}

/** The same run with the swell switched off in content: same zones, raw geometry. */
function modsWithSwell(terrainSwell) {
  const mods = { ...CONTENT.terrainMods, dewSwell: { ...CONTENT.terrainMods.dewSwell } };
  if (terrainSwell) mods.dewSwell.terrainSwell = terrainSwell;
  else delete mods.dewSwell.terrainSwell;
  return mods;
}

/**
 * Chunk `index` of `gen`'s run, rebuilt with the swell switched off in content (raw geometry, same zones). A whole
 * no-swell RUN drifts after the first swelled chunk (the swell moves lips, so later bounds get another sinceLaunch /
 * noHazX); copying the swelled run's bounds builds the twin from the identical bound.
 */
function rawTwin(gen, index, terrainSwell = null) {
  const twin = makeGen(gen.seed, { biomeMask: MICRO, modDefs: modsWithSwell(terrainSwell) });
  twin.bounds = gen.bounds.slice(0, index + 1).map((b) => ({ ...b }));
  return twin.getChunk(index);
}

// Two of the audit's three T2 tests, verbatim. The third ("slopeDegAt describes the same surface as heightAt") samples a
// +-1 px chord every 4 px; in a zone whose x0 + 3 is a multiple of 4 every 4th sample sits EXACTLY on a vertex, where the
// chord averages two segments and reads half the vertex turn (4.4 deg at 20/660). Off the vertices its error is ~4e-10
// deg. Its vertex-safe form is the slopeDegAt test below; the verbatim one is left to the lead (see the T2 report).
describe('T2 (audit, copied from audit/terrain tests/src/audit-terrain.test.js): dewSwell reaches the surface the sled rides', () => {
  test('T2: heightAt agrees with the collider polyline (chunk.points) inside a dew-swell zone', () => {
    const { gen, out } = swellZones('alpha');
    expect(out.length).toBeGreaterThan(0);
    let maxDelta = 0;
    for (const { c, z } of out) {
      for (let x = z.x0; x <= z.x1; x += 4) maxDelta = Math.max(maxDelta, Math.abs(gen.heightAt(x) - polylineY(c, x)));
    }
    expect(maxDelta).toBeLessThan(0.5);
  });

  test('T2: heightAt is continuous at a dew-swell zone edge (no vertical step)', () => {
    const { gen, out } = swellZones('alpha');
    let maxStep = 0;
    for (const { z } of out) maxStep = Math.max(maxStep, Math.abs(gen.heightAt(z.x1) - gen.heightAt(z.x1 + 0.001)));
    expect(maxStep).toBeLessThan(1);
  });
});

describe('Micro swell: one surface for collider, edge, heightAt and slopeDegAt', () => {
  test('heightAt equals the polyline inside every swell zone (3 seeds, within 0.5 px)', () => {
    for (const seed of SEEDS) {
      const { gen, out } = swellZones(seed);
      expect(out.length).toBeGreaterThan(5);
      let maxDelta = 0;
      for (const { c, z } of out) {
        for (let x = z.x0 - 40; x <= z.x1 + 40; x += 3) maxDelta = Math.max(maxDelta, Math.abs(gen.heightAt(x) - polylineY(c, x)));
      }
      expect(maxDelta).toBeLessThan(0.5);
    }
  });

  test('slopeDegAt is the slope of the polyline segment under x, and the heightAt chord off the vertices agrees', () => {
    for (const seed of SEEDS) {
      const { gen, out } = swellZones(seed);
      let segErr = 0;
      let chordErr = 0;
      for (const { c, z } of out) {
        const p = c.points;
        for (let x = z.x0 + 3; x <= z.x1 - 3; x += 2.5) {
          const i = Math.min(p.length - 2, Math.floor((x - c.startX) / 16));
          segErr = Math.max(segErr, Math.abs(gen.slopeDegAt(x) - segDeg(p, i)));
          // A +-1 px chord that straddles a vertex measures the mean of two segments; that is not a disagreement.
          const off = (x - c.startX) % 16;
          if (off > 1.01 && off < 14.99) {
            const fromHeight = (Math.atan2(gen.heightAt(x + 1) - gen.heightAt(x - 1), 2) * 180) / Math.PI;
            chordErr = Math.max(chordErr, Math.abs(fromHeight - gen.slopeDegAt(x)));
          }
        }
      }
      expect(segErr).toBeLessThan(1e-9);
      expect(chordErr).toBeLessThan(1);
    }
  });

  test('heightAt is continuous at both zone edges, and the swell fades in and out with no kink', () => {
    for (const seed of SEEDS) {
      const { gen, out } = swellZones(seed);
      let maxStep = 0;
      let edgeDisp = 0;
      let maxD2 = 0;
      let maxAdded = 0;
      for (let k = 0; k < out.length; k++) {
        const { c, z, i } = out[k];
        for (const e of [z.x0, z.x1]) maxStep = Math.max(maxStep, Math.abs(gen.heightAt(e) - gen.heightAt(e + 0.001)), Math.abs(gen.heightAt(e) - gen.heightAt(e - 0.001)));
        // d = swelled - raw at each point. Its second difference over 16 px is the swell's own bend (curvature x 256),
        // independent of the base slope. A raised-cosine taper of P/4 peaks at ~3x the sine's bend (0.0054 /px at
        // 20/660/165, radius ~185 px); a radius of 167 px is the bound. No taper is a step of up to A (second difference
        // ~A); 26/220 bent at 0.021 /px. The turn the swell adds at a vertex also stays inside the generator's
        // ordinary MAX_TURN_DEG (10 deg).
        const p = c.points;
        const raw = rawTwin(gen, i).points;
        const d = p.map((pt, j) => pt.y - raw[j].y);
        for (let j = 1; j < p.length - 1; j++) {
          if (p[j].x < z.x0 - 16 || p[j].x > z.x1 + 16) continue;
          maxD2 = Math.max(maxD2, Math.abs(d[j + 1] - 2 * d[j] + d[j - 1]));
          maxAdded = Math.max(maxAdded, Math.abs(segDeg(p, j) - segDeg(p, j - 1) - (segDeg(raw, j) - segDeg(raw, j - 1))));
          if (Math.min(Math.abs(p[j].x - z.x0), Math.abs(z.x1 - p[j].x)) <= 16) edgeDisp = Math.max(edgeDisp, Math.abs(d[j]));
        }
      }
      expect(maxStep).toBeLessThan(0.01);
      expect(edgeDisp).toBeLessThan(1);
      expect(maxD2).toBeLessThan(0.006 * 16 * 16);
      expect(maxAdded).toBeLessThan(MAX_TURN_DEG);
    }
  });
});

describe('Micro swell: the displacement is really in the points', () => {
  test('the raw twin of a swelled chunk has the same zones and the same x grid (displacement is the only difference)', () => {
    const { gen, out } = swellZones('beta');
    for (const { c, i } of out) {
      const raw = rawTwin(gen, i);
      expect(raw.zones).toEqual(c.zones);
      expect(raw.points.map((p) => p.x)).toEqual(c.points.map((p) => p.x));
      expect(raw.points[0].y).toBe(c.points[0].y);
      expect(raw.points[raw.points.length - 1].y).toBe(c.points[c.points.length - 1].y);
    }
  });

  test('peak-to-peak of the displacement is about 2 x amplitude in the zone middle, and zero outside zones', () => {
    for (const seed of SEEDS) {
      const { gen, out } = swellZones(seed);
      const raws = out.map(({ i }) => rawTwin(gen, i));
      let checked = 0;
      let outside = 0;
      for (let k = 0; k < out.length; k++) {
        const { c, z } = out[k];
        const raw = raws[k].points;
        const taper = Math.min(SW.taperPx, (z.x1 - z.x0) / 2);
        let lo = Infinity;
        let hi = -Infinity;
        c.points.forEach((pt, j) => {
          const d = pt.y - raw[j].y;
          if (pt.x < z.x0 || pt.x > z.x1) outside = Math.max(outside, Math.abs(d));
          else if (pt.x >= z.x0 + taper && pt.x <= z.x1 - taper) { lo = Math.min(lo, d); hi = Math.max(hi, d); }
          expect(Math.abs(d)).toBeLessThanOrEqual(SW.amplitudePx + 1e-9);
        });
        if (swings(z)) {
          checked++;
          expect(hi - lo).toBeGreaterThan(0.9 * 2 * SW.amplitudePx);
        }
      }
      expect(checked).toBeGreaterThan(0);
      expect(outside).toBe(0);
      // the read side sees it too: heightAt swings by ~2A around the raw line in the zone middle
      const { c, z } = out.find(({ z: q }) => swings(q));
      const k = out.findIndex((o) => o.z === z);
      let lo = Infinity;
      let hi = -Infinity;
      for (let x = z.x0 + SW.taperPx; x <= z.x1 - SW.taperPx; x += 2) {
        const d = gen.heightAt(x) - polylineY(raws[k], x);
        lo = Math.min(lo, d);
        hi = Math.max(hi, d);
      }
      expect(hi - lo).toBeGreaterThan(0.9 * 2 * SW.amplitudePx);
      expect(c.biome).toBe('micro-mountain');
    }
  });

  test('dew-swell.json declares a taper the code reads: no taper puts the step back at the zone end', () => {
    expect(SW.taperPx).toBeGreaterThan(0);
    expect(SW.taperPx).toBeLessThanOrEqual(DEW.lengthPx[0] / 2);
    const noTaper = swellZones('alpha', { modDefs: modsWithSwell({ ...SW, taperPx: 0 }) });
    let edge = 0;
    noTaper.out.forEach(({ c, z, i }) => {
      const raw = rawTwin(noTaper.gen, i).points;
      c.points.forEach((pt, j) => {
        if (pt.x >= z.x1 - 16 && pt.x <= z.x1) edge = Math.max(edge, Math.abs(pt.y - raw[j].y));
      });
    });
    expect(edge).toBeGreaterThan(5);
  });

  test('same seed + mask gives identical terrain twice', () => {
    const a = makeGen('swell', { biomeMask: MICRO });
    const b = makeGen('swell', { biomeMask: MICRO });
    for (let i = 0; i < 150; i++) expect(JSON.stringify(b.getChunk(i))).toBe(JSON.stringify(a.getChunk(i)));
    // and streaming (pooled chunk objects, any call order) builds the same points
    const s = makeGen('swell', { biomeMask: MICRO });
    for (let x = 0; x < 120000; x += 400) s.update(x);
    for (const c of s.getActiveChunks()) expect(JSON.stringify(c)).toBe(JSON.stringify(a.getChunk(c.index)));
  });
});

describe('Micro swell: spawns sit on the swelled ground', () => {
  const AIR = new Set(Object.values(CONTENT.hazards).filter((h) => h.placement === 'air').map((h) => h.id));

  test('ground hazards, pads, power-ups and shards in Micro chunks use the swelled polyline', () => {
    for (const seed of SEEDS) {
      const { gen } = swellZones(seed);
      for (let i = 0; i < CHUNKS; i++) {
        const c = gen.getChunk(i);
        if (c.biome !== 'micro-mountain') continue;
        for (const h of c.hazards) {
          if (AIR.has(h.defId)) continue;
          expect(Math.abs(h.y - polylineY(c, h.x))).toBeLessThan(0.5);
          const j = Math.min(c.points.length - 2, Math.floor((h.x - c.startX) / 16));
          expect(Math.abs(h.rotationDeg - segDeg(c.points, j))).toBeLessThan(1e-6);
          // clearance rule: a readable slope, on the ground the sled meets
          expect(h.rotationDeg).toBeGreaterThan(-12);
          expect(h.rotationDeg).toBeLessThan(28);
        }
        for (const p of c.bouncePads) expect(Math.abs(p.y - polylineY(c, p.x))).toBeLessThan(0.5);
        for (const p of c.powerups) expect(p.y).toBeLessThan(polylineY(c, p.x) - 20);
        for (const s of c.shards) expect(s.y).toBeLessThanOrEqual(polylineY(c, s.x) - 12 + 0.5);
      }
    }
  });
});/**
 * Mission bookkeeping fixes from the post-sprint audit (MS-1, MS-2, MS-3, F9, BOOT-1).
 * Each test drives the real ProfileStore / MissionsService / Missions code with the shipped data.
 */
import fs from 'fs';
import path from 'path';

import {
  ProfileStore, sanitizeProfile,
} from '../../src/systems/ProfileStore.js';
import { ProgressionService } from '../../src/systems/ProgressionService.js';
import { MissionsService } from '../../src/systems/MissionsService.js';
import { rollSet, isOfferable } from '../../src/systems/Missions.js';
import { REG } from '../../src/constants.js';
import { EVT } from '../../src/events.js';

const read = (p) => JSON.parse(fs.readFileSync(p, 'utf8'));
const LEVELS = read('src/data/progression/levels.json');
const MISSIONS = read('src/data/missions/missions.json');
const BIOME_DEFS = fs.readdirSync('src/data/biomes').filter((f) => f.endsWith('.json'))
  .map((f) => read(path.join('src/data/biomes', f)));
const MAX_XP = LEVELS.levels[LEVELS.levels.length - 1].xpMin + 1;

const memStorage = () => {
  const m = new Map();
  return {
    getItem: (k) => (m.has(k) ? m.get(k) : null),
    setItem: (k, v) => m.set(k, String(v)),
    removeItem: (k) => m.delete(k),
  };
};

function fakeGame() {
  const reg = new Map();
  const handlers = new Map();
  return {
    registry: { get: (k) => reg.get(k), set: (k, v) => reg.set(k, v) },
    events: {
      on: (n, fn) => { if (!handlers.has(n)) handlers.set(n, new Set()); handlers.get(n).add(fn); },
      off: (n, fn) => { handlers.get(n)?.delete(fn); },
      once: () => {},
      emit: (n, p) => { for (const fn of [...(handlers.get(n) || [])]) fn(p); },
    },
  };
}

const rec = (o = {}) => ({
  version: 1, id: 'run-1', seed: 's', dailyRuleId: 'none', startedAt: 0, endedAt: 1000, durationMs: 60000,
  score: 0, distanceM: 0, trickPoints: 0, tricks: {}, bestCombo: 1, maxAirtimeMs: 0, cause: 'crash',
  ledgerHash: 'h1', shards: 0, nearMisses: 0, ...o,
});

const v1 = (o = {}) => sanitizeProfile({ v: 1, ...o }, LEVELS);

/** Boot progression + missions the way services.js does, on the given storage. */
async function boot(storage, saveStore) {
  const game = fakeGame();
  if (saveStore) game.registry.set(REG.SAVE_STORE, saveStore);
  const store = new ProfileStore({ levels: LEVELS, storage });
  const progression = new ProgressionService(game, { levels: LEVELS, store });
  await progression.init();
  const missions = new MissionsService(game, {
    templates: MISSIONS.templates, tierUnlock: MISSIONS.tierUnlock, biomeDefs: BIOME_DEFS, store,
  });
  await missions.init();
  progression.missions = missions;
  return { game, store, progression, missions };
}

describe('MS-3: the sanitizer keeps each active mission once', () => {
  test('duplicate active mission ids are dropped (a hand edit cannot pay one mission three times)', () => {
    const p = v1({ missions: { counter: 1, active: ['t1-distance-500', 't1-distance-500', 't1-distance-500'], progress: {} } });
    expect(p.missions.active).toEqual(['t1-distance-500']);
  });

  test('distinct ids keep their order and the three-slot cap', () => {
    const p = v1({ missions: { counter: 1, active: ['a', 'b', 'a', 'c', 'd'], progress: {} } });
    expect(p.missions.active).toEqual(['a', 'b', 'c']);
  });
});

describe('MS-1: published cumulative progress is what is banked', () => {
  test('20 of 50 banked shards publishes 20/50, not 40/50', async () => {
    const { game, store, missions } = await boot(memStorage());
    const t = MISSIONS.templates.find((x) => x.id === 't1-cum-shards-50');
    store.applyMissions({ active: [t.id], counter: 5, progress: { [t.id]: 20 }, xp: 0, shards: 0 });
    missions.publish();
    const row = game.registry.get(REG.MISSIONS).active.find((r) => r.id === t.id);
    expect(row).toMatchObject({ text: '20/50', fraction: 0.4, done: false });
  });

  test('25 of 50 is not published as DONE', async () => {
    const { game, store, missions } = await boot(memStorage());
    const t = MISSIONS.templates.find((x) => x.id === 't1-cum-shards-50');
    store.applyMissions({ active: [t.id], counter: 5, progress: { [t.id]: 25 }, xp: 0, shards: 0 });
    missions.publish();
    expect(game.registry.get(REG.MISSIONS).active.find((r) => r.id === t.id).done).toBe(false);
  });

  test('a cumulative "runs" mission publishes the banked count, not banked + 1', async () => {
    const { game, store, missions } = await boot(memStorage());
    const t = MISSIONS.templates.find((x) => x.type === 'cumulative' && x.metric === 'runs');
    store.applyMissions({ active: [t.id], counter: 5, progress: { [t.id]: 3 }, xp: 0, shards: 0 });
    missions.publish();
    const row = game.registry.get(REG.MISSIONS).active.find((r) => r.id === t.id);
    expect(row.text).toBe(`3/${t.target}`);
  });

  test('a single-run mission publishes zero between runs', async () => {
    const { game, store, missions } = await boot(memStorage());
    const t = MISSIONS.templates.find((x) => x.id === 't1-distance-500');
    store.applyMissions({ active: [t.id], counter: 5, progress: {}, xp: 0, shards: 0 });
    missions.publish();
    expect(game.registry.get(REG.MISSIONS).active.find((r) => r.id === t.id)).toMatchObject({ text: '0/500', done: false });
  });
});

describe('MS-2: a biome mission completes only on a run with that biome switched on (the base biome is always on)', () => {
  const t = MISSIONS.templates.find((x) => x.id === 't4-pickup-maple-wax');
  const deb = BIOME_DEFS.find((d) => d.id === 'debutmont');
  const other = BIOME_DEFS.find((d) => d.id !== 'debutmont');
  const prof = () => v1({ xp: MAX_XP, missions: { counter: 1, active: [t.id], progress: {} } });
  const roll = (mask, defs = BIOME_DEFS) => rollSet(prof(), [t], rec({ pickups: { mapleWax: 3 }, ...(mask === undefined ? {} : { biomeMask: mask }) }), MISSIONS.templates, { biomeDefs: defs })
    .completed.map((c) => c.id);

  // Issue #65: Debutmont is the base biome, the terrain of every run whatever its mask (Daily mask 0, a
  // Gym, `seed@mask`), and its bit is never in a normal run's mask. The mission is therefore completable
  // on any run; it must not hang on a no-op bit. (#65: the trivial "1500 m in Debutmont" became "Grab 3 Maple Wax in a
  // run", still a Debutmont mission.)
  test('"Grab 3 Maple Wax in a run" is completed by a run whatever its mask, the base bit being a no-op', () => {
    expect(roll(0)).toEqual([t.id]);
    expect(roll(undefined)).toEqual([t.id]);
    expect(roll(other.bit)).toEqual([t.id]);
  });

  test('a biome mission for a NON-base biome still needs that biome on in the run mask', () => {
    const g = MISSIONS.templates.find((x) => x.id === 't4-biome-glacier');
    const gl = BIOME_DEFS.find((d) => d.id === 'garbage-dump-glacier');
    const p = v1({ xp: MAX_XP, missions: { counter: 1, active: [g.id], progress: {} } });
    const run = (mask) => rollSet(p, [g], rec({ distanceM: 2100, biomeMask: mask }), MISSIONS.templates, { biomeDefs: BIOME_DEFS })
      .completed.map((c) => c.id);
    expect(run(0)).toEqual([]);
    expect(run(deb.bit)).toEqual([]);
    expect(run(gl.bit)).toEqual([g.id]);
  });

  test('a run with three Maple Wax and the Debutmont bit on completes it', () => {
    expect(roll(deb.bit)).toEqual([t.id]);
    expect(roll(deb.bit | other.bit)).toEqual([t.id]);
  });

  test('without a biome table the base biome is still always eligible (legacy fallback)', () => {
    expect(roll(0, undefined)).toEqual([t.id]);
    expect(roll(deb.bit, undefined)).toEqual([t.id]);
  });

  async function liveToasts(mask) {
    const { game, store, missions } = await boot(memStorage());
    store.applyMissions({ active: [t.id], counter: 5, progress: {}, xp: 0, shards: 0 });
    store.save({ ...store.profile, xp: MAX_XP });
    const got = [];
    game.events.on(EVT.MISSION_COMPLETED, (p) => got.push(p.id));
    game.registry.set(REG.BIOME_MASK, mask);
    game.events.emit(EVT.RUN_START, { runId: 'r', seed: 's' });
    for (let i = 0; i < 3; i++) game.events.emit(EVT.POWERUP_COLLECTED, { id: 'mapleWax', durationMs: 2000, charges: 0 });
    missions.destroy();
    return got;
  }

  test('stateFor (live mission state) applies the same gate', async () => {
    const { missions } = await boot(memStorage());
    const live = (biomeMask, n = 3) => ({ live: { pickups: { mapleWax: n }, biomeMask } });
    expect(missions.stateFor(t, live(0)).done).toBe(true);
    expect(missions.stateFor(t, live(other.bit)).done).toBe(true);
    expect(missions.stateFor(t, live(deb.bit)).done).toBe(true);
    expect(missions.stateFor(t, live(0, 2)).done).toBe(false);
    const gl = MISSIONS.templates.find((x) => x.id === 't4-biome-glacier');
    expect(missions.stateFor(gl, { live: { distanceM: 2100, biomeMask: 0 } }).done).toBe(false);
  });

  test('the live toast follows the same rule as the payout', async () => {
    expect(await liveToasts(0)).toEqual([t.id]);
    expect(await liveToasts(deb.bit)).toEqual([t.id]);
  });
});

