describe('rewards are sane', () => {
  test('every template pays a positive amount and tiers pay more', () => {
    for (const t of TEMPLATES) {
      expect(xpForTemplate(t)).toBeGreaterThan(0);
    }
    const byTier = {};
    for (const t of TEMPLATES) byTier[t.tier] = Math.min(byTier[t.tier] ?? Infinity, xpForTemplate(t));
    const tiers = Object.keys(byTier).map(Number).sort((a, b) => a - b);
    for (let i = 1; i < tiers.length; i++) {
      expect(byTier[tiers[i]]).toBeGreaterThanOrEqual(byTier[tiers[i - 1]]);
    }
  });

  test('progress text never overruns the strip', () => {
    for (const t of TEMPLATES) {
      const text = missionProgressText(t, 0);
      expect(text.length).toBeLessThanOrEqual(34);
    }
  });
});

/**
 * Would this template still be completable under `rule`? A template is unreachable only if the rule
 * removes the thing it measures. Kept deliberately simple and explicit rather than clever: the point
 * is that each impossible pairing has to be written down.
 */
function isReachableUnder(t, rule) {
  const m = rule.modifiers || {};
  // Rules that only scale speed / friction / gravity / air control never make a metric unreachable;
  // they make it harder. Only a metric the rule zeroes out would be impossible, and no rule does.
  if (t.metric === 'combo' || t.require) return true; // tricks remain performable under every rule
  const zeroing = Object.values(m).some((v) => v === 0);
  return !zeroing;
}

/**
 * Spec W2 gate: "No mission may be impossible under any of the 8 daily rules in DailyPatch.RULES —
 * add a test that checks every template against every rule's constraints, or tag templates with
 * excluded rule ids."
 *
 * The 8 rules are all PHYSICS modifiers (gravity, friction, air control, tuck) — none of them bans a
 * trick family or a metric, so no template needs excluding on those grounds. What they can do is
 * make a target unreachable: gravity +25% (heavyPackets) shortens airtime, so an airtime target tuned
 * to the ceiling of a normal run becomes impossible that day.
 *
 * This test therefore does the real work: it compares each template's target against a MEASURED
 * ceiling per rule, and fails if any template asks for more than the rule can deliver.
 */
describe('daily-rule compatibility (spec gate)', () => {
  const rules = DailyPatch.RULES;

  test('there are exactly 8 daily rules', () => {
    expect(rules).toHaveLength(8);
  });

  test('every template is offerable under every rule (no rule bans a metric)', () => {
    for (const t of TEMPLATES) {
      const excluded = Array.isArray(t.excludedRuleIds) ? t.excludedRuleIds : [];
      expect({ id: t.id, excluded: excluded.length }).toMatchObject({ excluded: 0 });
    }
  });

  test('excludedRuleIds only names real rules, when present', () => {
    const ids = new Set(rules.map((r) => r.id));
    for (const t of TEMPLATES) {
      for (const id of t.excludedRuleIds || []) expect(ids.has(id)).toBe(true);
    }
  });

  test('no airtime target exceeds a measured real-game run under any daily rule', () => {
    // Use the sweep's actual maxima, not a ballistic estimate scaled from one hand-picked baseline.
    // The earlier 1772/sqrt(gravity) ceiling did not correspond to the checked-in pacing run data.
    for (const rule of rules) {
      const cap = reachabilityData.perRule[rule.id].maxAirtimeMs;
      for (const t of TEMPLATES) {
        if (t.metric !== 'maxAirtimeMs') continue;
        if (t.type === 'cumulative') continue; // accumulates across runs, never gated by one day
        expect({ rule: rule.id, id: t.id, target: t.target, cap }).toMatchObject({
          target: expect.any(Number),
        });
        expect(t.target).toBeLessThanOrEqual(cap);
      }
    }
  });

  test("no combo target exceeds the game's own maximum combo multiplier", () => {
    // A bestCombo target is compared directly against ScoreManager.bestCombo, which is
    // comboStart + comboStep * (unique combo-step trick types) — capped by the number of such types
    // that exist. Deriving the ceiling from SCORING instead of typing a number is the point: the
    // first draft of the template table asked for x3 / x5 / x10 / x15, all impossible because the
    // multiplier tops out at x2 (a real defect the simulator caught, not a hypothetical).
    const maxMultiplier = SCORING.comboStart + SCORING.comboStep * SCORING.comboStepTypes.length;
    expect(maxMultiplier).toBe(2);
    for (const t of TEMPLATES) {
      if (t.metric !== 'bestCombo') continue;
      if (t.type === 'cumulative') continue;
      expect({ id: t.id, target: t.target, cap: maxMultiplier }).toMatchObject({ target: expect.any(Number) });
      expect(t.target).toBeLessThanOrEqual(maxMultiplier);
    }
  });

  test('every single-run combo target is attainable at all (not below 1)', () => {
    for (const t of TEMPLATES) {
      if (t.metric !== 'bestCombo' || t.type !== 'singleRun') continue;
      expect(t.target).toBeGreaterThanOrEqual(SCORING.comboStart);
    }
  });

  test('every rule can still draw a full set of three missions', () => {
    for (const rule of rules) {
      const eligible = TEMPLATES.filter((t) => !(t.excludedRuleIds || []).includes(rule.id));
      expect(eligible.length).toBeGreaterThanOrEqual(3);
    }
  });

  test('templates are reachable under every rule with a full set of level-1 missions', () => {
    // A brand-new profile must always be able to make progress that day.
    for (const rule of rules) {
      const p = defaultProfile();
      const out = rollSet(p, [], { ledgerHash: 'x', distanceM: 0 }, TEMPLATES, { ruleId: rule.id });
      expect({ rule: rule.id, n: out.active.length }).toMatchObject({ n: 3 });
    }
  });
});/**
 * Geometry tests for the W2 mission UI. These exist because W1's audit found layout collisions that
 * a pixel probe missed — every rectangle is checked for overlap, containment and text fit here.
 */
import {
  SCREEN, MISSION_PANEL, MISSION_LIST_TITLE, TITLE_BANDS, TITLE_BEST_X, TITLE_BEST_Y,
  TITLE_CARD, TITLE_CARD_INNER_W, TITLE_HORIZON, titleCardLayout, titleMenuLayout, titleBestText, titleChaseText,
  rect, overlaps, insideScreen, missionPanelLayout, missionListLayout, toastSlot,
  charsThatFit, ellipsize, GAMEOVER_MISSIONS_Y, GAMEOVER_ROW_H, GAMEOVER_BOARD_ROWS, columnRows,
  GAMEOVER_BOARD_ROW_H, GAMEOVER_MISSIONS_RULE_Y, LABEL_H, GLYPH_H, entryLayout,
} from '../../src/ui/MissionsLayout.js';
import { measureText, hasGlyph } from '../../src/ui/PixelFont.js';
import { sunGeometry } from '../../src/ui/Backdrop.js';
import fs from 'fs';
import path from 'path';
// The font's own line height, read from the font module rather than from the layout that consumes it.
// This is what stops the "label is one glyph tall" assertion from being a tautology about a local
// constant: the expected height comes from the code that actually draws the glyphs.
import { FONT_LINE_H } from '../../src/ui/PixelFont.js';

describe('overlaps / insideScreen', () => {
  test('detects overlap and respects a required gap', () => {
    const a = rect(0, 0, 10, 10);
    expect(overlaps(a, rect(5, 5, 10, 10))).toBe(true);
    expect(overlaps(a, rect(10, 0, 10, 10))).toBe(false);
    expect(overlaps(a, rect(10, 0, 10, 10), 1)).toBe(true);
  });

  test('touching edges are not an overlap', () => {
    expect(overlaps(rect(0, 0, 10, 10), rect(0, 10, 10, 10))).toBe(false);
  });

  test('insideScreen rejects anything past the virtual viewport', () => {
    expect(insideScreen(rect(0, 0, 480, 270))).toBe(true);
    expect(insideScreen(rect(0, 0, 481, 270))).toBe(false);
    expect(insideScreen(rect(0, 262, 100, 9))).toBe(false);
    expect(insideScreen(rect(-1, 0, 10, 10))).toBe(false);
  });
});

describe('missionPanelLayout', () => {
  test('every rect is inside the screen for 0..3 missions', () => {
    for (let n = 0; n <= 3; n++) {
      const L = missionPanelLayout(n);
      expect(insideScreen(L.panel)).toBe(true);
      expect(insideScreen(L.header)).toBe(true);
      for (const r of [...L.rows, ...L.bars]) expect(insideScreen(r)).toBe(true);
    }
  });

  test('rows never overlap each other or their own bar', () => {
    for (let n = 1; n <= 3; n++) {
      const L = missionPanelLayout(n);
      for (let i = 0; i < L.rows.length; i++) {
        expect(overlaps(L.rows[i], L.bars[i])).toBe(false);
        for (let j = i + 1; j < L.rows.length; j++) {
          expect(overlaps(L.rows[i], L.rows[j])).toBe(false);
          expect(overlaps(L.bars[i], L.bars[j])).toBe(false);
        }
      }
    }
  });

  test('the header clears the first row', () => {
    const L = missionPanelLayout(3);
    expect(overlaps(L.header, L.rows[0])).toBe(false);
  });

  test('the panel grows with the mission count and never exceeds its band', () => {
    const one = missionPanelLayout(1).panel;
    const three = missionPanelLayout(3).panel;
    expect(three.h).toBeGreaterThan(one.h);
    expect(insideScreen(three)).toBe(true);
  });

  test('clamps an out-of-range count instead of drawing off-screen', () => {
    expect(missionPanelLayout(9).rows).toHaveLength(MISSION_PANEL.rows);
    expect(missionPanelLayout(-2).rows).toHaveLength(0);
    expect(missionPanelLayout(undefined).rows).toHaveLength(0);
  });

  test('the panel does not collide with the Title menu band', () => {
    // The Title list starts at y=178; the in-run panel is well clear of it.
    const L = missionPanelLayout(3);
    expect(overlaps(L.panel, rect(0, MISSION_LIST_TITLE.y, 480, 60))).toBe(false);
  });
});

describe('missionListLayout', () => {
  test('every rect is inside the screen for 0..3 missions', () => {
    for (let n = 0; n <= 3; n++) {
      const L = missionListLayout(n);
      expect(insideScreen(L.panel)).toBe(true);
      for (const r of [...L.rows, ...L.bars]) expect(insideScreen(r)).toBe(true);
    }
  });

  test('rows and bars do not overlap each other', () => {
    const L = missionListLayout(3);
    for (let i = 0; i < L.rows.length; i++) {
      expect(overlaps(L.rows[i], L.bars[i])).toBe(false);
      for (let j = i + 1; j < L.rows.length; j++) {
        expect(overlaps(L.rows[i], L.rows[j])).toBe(false);
        expect(overlaps(L.bars[i], L.bars[j])).toBe(false);
      }
    }
  });

  test('the list clears the Title menu and the DAILY PATCH section', () => {
    // These are the real occupied bands on TitleScene, not guesses: the menu panel on the left and the
    // Daily Patch section of the cabinet card directly above the list. A mission list that overlapped
    // either would cover live UI.
    const L = missionListLayout(3);
    expect(overlaps(L.panel, TITLE_BANDS.menu)).toBe(false);
    expect(overlaps(L.panel, TITLE_BANDS.daily)).toBe(false);
    expect(L.panel.y).toBeGreaterThanOrEqual(TITLE_BANDS.daily.y + TITLE_BANDS.daily.h);
    // And it must not run off the bottom of a 270 px screen. The first version of this list landed
    // 1 px from the edge (bottom 269), which reads as clipped — require a real margin.
    expect(insideScreen(L.panel)).toBe(true);
    expect(SCREEN.h - (L.panel.y + L.panel.h)).toBeGreaterThanOrEqual(4);
  });

  test('the list does not collide with the BEST line or the control hint', () => {
    // Luna's W2 finding 3: the full-width list was drawn across y 229..264, over BEST (y 239) and the
    // hint (y 258). The pixel probe passed because it only asked "is there ink?", never "does this
    // rect land on that text?". These are the assertions that were missing.
    const L = missionListLayout(3);
    expect(overlaps(L.panel, TITLE_BANDS.best)).toBe(false);
    expect(overlaps(L.panel, TITLE_BANDS.hint)).toBe(false);
    for (const r of [...L.rows, ...L.bars]) {
      expect(overlaps(r, TITLE_BANDS.best)).toBe(false);
      expect(overlaps(r, TITLE_BANDS.hint)).toBe(false);
    }
  });

  test('BEST sits above the list in the cabinet card, and the hint sits below both', () => {
    // The synthwave Title moved BEST out of the bottom strip, where it shared a band with the list, into
    // the card's player section: same column as the list, so the clearance that matters is now vertical.
    const L = missionListLayout(3);
    expect(TITLE_BANDS.best.y + TITLE_BANDS.best.h).toBeLessThanOrEqual(L.panel.y);
    expect(TITLE_BEST_X).toBe(TITLE_BANDS.best.x);
    expect(TITLE_BEST_Y).toBe(TITLE_BANDS.best.y);
    expect(TITLE_BEST_Y).toBeLessThan(L.panel.y);
    // the whole BEST line (the widest real one) stays inside the card's text column
    expect(TITLE_BEST_X).toBeGreaterThanOrEqual(TITLE_CARD.x + TITLE_CARD.pad);
    for (const [m, sc] of [['500', '500'], ['12,345', '123,456'], ['99,999', '9,999,999']]) {
      expect(TITLE_BEST_X + measureText(titleBestText(m, sc))).toBeLessThanOrEqual(TITLE_CARD.x + TITLE_CARD.w - TITLE_CARD.pad);
    }
    // the common case keeps the exact line the FAIRNESS tests read (run-start-rules)
    expect(titleBestText('500', '500')).toBe('BEST 500 M   500 PTS');
    expect(TITLE_BANDS.hint.y).toBeGreaterThanOrEqual(L.panel.y + L.panel.h);
  });

  test('rows stay inside their own row height', () => {
    // The previous geometry put each bar 8 px below a 9 px row, so bars bled into the next row.
    const L = missionListLayout(3);
    for (let i = 0; i < L.rows.length; i++) {
      expect(overlaps(L.rows[i], L.bars[i])).toBe(false);
      expect(L.bars[i].y + L.bars[i].h).toBeLessThanOrEqual(L.panel.y + L.panel.h);
    }
  });

  test('the glyph constant matches the font it claims to describe', () => {
    // If these ever diverge, every other legibility assertion here silently becomes decorative: the
    // layout would be measuring itself. FONT_LINE_H 9 is 8 ink rows + 1 gap (see PixelFont.buildTexture,
    // which writes font rows 0..7).
    expect(FONT_LINE_H).toBe(9);
    expect(GLYPH_H).toBe(FONT_LINE_H - 1);
  });

  test('every row shows a full glyph height — the text can never be sliced', () => {
    // CC Friday's finding, reproduced from the source rather than from a screenshot: a glyph is
    // FONT_LINE_H - 1 = 8 rows tall, and the old list drew a 5 px "label" with the bar at y+5, so the
    // bar covered the lower two glyph rows of every mission title ("Finish 25 runs" cut in half at
    // native resolution). Two independent conditions have to hold, and the pixel probe could see
    // neither because it only asked whether ink existed:
    //   1. the label rect is at least one full glyph box tall;
    //   2. the bar's rect does not intersect the label's rect at all.
    const L = missionListLayout(3);
    for (let i = 0; i < L.rows.length; i++) {
      expect(L.rows[i].h).toBeGreaterThanOrEqual(FONT_LINE_H - 1);
      expect(overlaps(L.rows[i], L.bars[i])).toBe(false);
      // Row pitch must admit a full glyph plus a gap, or consecutive rows clip each other.
      expect(MISSION_LIST_TITLE.rowH).toBeGreaterThanOrEqual(FONT_LINE_H);
    }
  });

  test('consecutive Title rows never overlap', () => {
    const L = missionListLayout(3);
    for (let i = 1; i < L.rows.length; i += 1) {
      expect(overlaps(L.rows[i - 1], L.rows[i])).toBe(false);
      expect(overlaps(L.bars[i - 1], L.bars[i])).toBe(false);
      expect(overlaps(L.rows[i - 1], L.bars[i])).toBe(false);
    }
  });

  test('every real mission title fits its text box, measured in the real font, upper-cased', () => {
    // Nothing may be silently ellipsized away at scale 1. The Title list draws titles upper-cased and
    // fits them with the MEASURED font width (PixelFont), so the check measures every real template
    // rather than assuming a 6 px advance: the widest is 138 px against a 140 px row (the bar is under
    // the label now, so it no longer takes any of the row's width).
    const L = missionListLayout(3);
    const raw = fs.readFileSync(path.resolve('src/data/missions/missions.json'), 'utf8');
    const titles = [...raw.matchAll(/"title":\s*"([^"]*)"/g)].map((m) => m[1].toUpperCase());
    expect(titles.length).toBeGreaterThanOrEqual(40);
    for (const t of titles) expect(measureText(t)).toBeLessThanOrEqual(L.rows[0].w);
    for (const b of L.bars) expect(b.w).toBe(L.rows[0].w);
  });

  test('the in-run panel and the Title list do not overlap', () => {
    expect(overlaps(missionPanelLayout(3).panel, missionListLayout(3).panel)).toBe(false);
  });
});

describe('Title cabinet layout (synthwave reorganisation)', () => {
  const B = TITLE_BANDS;
  const named = Object.entries(B).filter(([k]) => k !== 'daily' && k !== 'best');

  test('every band is on screen', () => {
    for (const [, r] of Object.entries(B)) expect(insideScreen(r)).toBe(true);
  });

  test('the top-level bands are pairwise disjoint', () => {
    // daily and best are sections INSIDE the card, so they are checked against the card separately
    for (let i = 0; i < named.length; i++) {
      for (let j = i + 1; j < named.length; j++) {
        expect([named[i][0], named[j][0], overlaps(named[i][1], named[j][1])]).toEqual([named[i][0], named[j][0], false]);
      }
    }
  });

  test('the card sections sit inside the card and never overlap each other', () => {
    const C = titleCardLayout();
    const lines = Object.entries(C).filter(([k]) => k !== 'card');
    for (const [, r] of lines) {
      expect(r.x).toBeGreaterThanOrEqual(C.card.x);
      expect(r.y).toBeGreaterThanOrEqual(C.card.y + 2);
      expect(r.x + r.w).toBeLessThanOrEqual(C.card.x + C.card.w);
      expect(r.y + r.h).toBeLessThanOrEqual(C.card.y + C.card.h - 2);
    }
    for (let i = 0; i < lines.length; i++) {
      for (let j = i + 1; j < lines.length; j++) expect([lines[i][0], lines[j][0], overlaps(lines[i][1], lines[j][1])]).toEqual([lines[i][0], lines[j][0], false]);
    }
    // the named bands the scene and other tests read agree with the card's own sections
    expect(overlaps(B.best, C.best)).toBe(true);
    for (const k of ['dailyHead', 'ruleName', 'desc1', 'desc2', 'next', 'chase']) {
      expect(C[k].y).toBeGreaterThanOrEqual(B.daily.y);
      expect(C[k].y + C[k].h).toBeLessThanOrEqual(B.daily.y + B.daily.h);
    }
  });

  test('the card is wide enough for its widest real lines', () => {
    expect(measureText('NEXT PATCH IN 23H 59M')).toBeLessThanOrEqual(TITLE_CARD_INNER_W);
    for (const [st, best] of [[0, null], [12, null], [999, null], [3, '45,678'], [999, '9,999,999']]) {
      expect(measureText(titleChaseText(st, best))).toBeLessThanOrEqual(TITLE_CARD_INNER_W);
    }
    expect(titleChaseText(3, '45,678')).toBe('STREAK 3  TODAY 45,678');
    expect(titleChaseText(0, null)).toBe('NOT PLAYED TODAY');
    // a 2x rule name is used only when it fits; every current rule fits at 1x
    expect(measureText('FEATHERWEIGHT')).toBeLessThanOrEqual(TITLE_CARD_INNER_W);
  });

  test('the six-row menu fills its band on the grid floor, under the horizon, above the hint', () => {
    const g = titleMenuLayout(6);
    expect(g.fits).toBe(true);
    expect({ x: g.x, y: g.y, w: g.w }).toEqual({ x: B.menu.x, y: B.menu.y, w: B.menu.w });
    expect(g.y + g.h).toBeLessThanOrEqual(B.hint.y);
    expect(g.lastRowBottom).toBeLessThanOrEqual(B.menu.y + B.menu.h);
  });

  test('the centre column between the menu and the card stays open from the tagline to the hint', () => {
    // This is what lets the sun, the ranges, the rider and the grid's vanishing point read. Only the help
    // chip (at the foot) and the attract prompt (shown only while the menu is dimmed) may sit in it.
    const centre = rect(B.menu.x + B.menu.w, B.tagline.y + B.tagline.h, B.card.x - (B.menu.x + B.menu.w), B.help.y - (B.tagline.y + B.tagline.h));
    expect(centre.w).toBeGreaterThanOrEqual(90);
    for (const k of ['menu', 'card', 'jukebox', 'logo', 'tagline', 'help', 'hint']) expect([k, overlaps(centre, B[k])]).toEqual([k, false]);
  });

  test('the upper half of the sun is covered only by the logo, never by a panel', () => {
    // the logo over the sun is the intended composition; a panel over it is what the reorganisation fixed
    const s = sunGeometry(TITLE_HORIZON);
    const upper = rect(s.cx - s.r, s.top, s.r * 2, s.r);
    for (const k of ['menu', 'card', 'jukebox', 'help', 'hint']) expect([k, overlaps(upper, B[k])]).toEqual([k, false]);
    // and some of it shows between the logo and the horizon
    expect(s.top).toBeLessThan(B.logo.y + B.logo.h);
    expect(s.cy).toBeGreaterThan(B.logo.y + B.logo.h);
    expect(TITLE_HORIZON).toBeGreaterThan(s.cy);
  });

  test('the attract prompt sits over the sun, clear of the tagline and the panels', () => {
    for (const k of ['logo', 'tagline', 'menu', 'card', 'jukebox']) expect([k, overlaps(B.attract, B[k])]).toEqual([k, false]);
    expect(B.attract.y + B.attract.h).toBeLessThanOrEqual(TITLE_HORIZON);
    // PRESS START at 2x fits its band
    expect(measureText('PRESS START') * 2).toBeLessThanOrEqual(B.attract.w);
  });

  test('the help chip label fits the chip and the hint fits the screen', () => {
    expect(measureText('? HOW TO PLAY') + 6).toBeLessThanOrEqual(B.help.w);
    expect(measureText('↑↓ SELECT   ENTER / A CONFIRM   H / X HOW TO PLAY')).toBeLessThanOrEqual(SCREEN.w - 16);
  });
});

describe('Game Over mission block', () => {
  // Real GameOverScene geometry, transcribed here so the assertion is against the scene, not against
  // the mission module's own opinion of itself. LEDGER panel: y=54, h=160 -> interior local 0..160.
  // Board container sits at local y 22; its rows start 14 below that at GAMEOVER_BOARD_ROW_H pitch.
  const LEDGER = { x: 250, y: 54, w: 216, h: 160 };
  const PANEL_FLOOR = LEDGER.h; // local 160
  const BOARD_Y = 22;
  const ROWS_OFFSET = 14;
  const BUTTONS = { x: 0, y: 220, w: 480, h: 24 };
  /** Local y where the last leaderboard row's text ends. */
  const boardEnd = () => BOARD_Y + ROWS_OFFSET + (GAMEOVER_BOARD_ROWS - 1) * GAMEOVER_BOARD_ROW_H + LABEL_H;
  const block = () => columnRows({ x: 8, y: GAMEOVER_MISSIONS_Y, w: 200, count: 3, rowH: GAMEOVER_ROW_H, barH: 2 });

  test('each progress bar never covers its own label', () => {
    // Two rounds of audits found this defect in different forms: first a bar 2 px INTO an 8 px label
    // (pitch 8), then a bar flush under a label with a zero-pixel gap to the next row (pitch 10), which
    // reads as a slab of ink across the text. The invariant that fixes both is geometric rather than
    // aesthetic: the label and the bar must not intersect, in any row, and the label must keep a full
    // glyph box. A bar placed under the label only satisfies this at a pitch that leaves no gap, so
    // the layout puts it inline instead.
    const geom = block();
    geom.rows.forEach((r, i) => {
      const b = geom.bars[i];
      expect(overlaps(r, b)).toBe(false);
      expect(r.h).toBeGreaterThanOrEqual(FONT_LINE_H - 1);
      // Inline, or below with a real gap — never inside.
      const inline = b.x >= r.x + r.w;
      const below = b.y >= r.y + r.h + 1;
      expect(inline || below).toBe(true);
    });
  });

  test('consecutive mission rows do not collide', () => {
    const geom = block();
    for (let i = 1; i < geom.rows.length; i += 1) {
      expect(overlaps(geom.rows[i - 1], geom.rows[i])).toBe(false);
      expect(overlaps(geom.bars[i - 1], geom.rows[i])).toBe(false);
      expect(overlaps(geom.rows[i - 1], geom.bars[i])).toBe(false);
      // A full glyph box plus a visible gap: rows that merely touch read as one paragraph.
      expect(geom.rows[i].y).toBeGreaterThanOrEqual(geom.rows[i - 1].y + FONT_LINE_H - 1);
    }
  });

  test('the mission title fits its text box at the longest real title', () => {
    // The longest template is 132 px wide at scale 1 ("Collect 1000 shards total"). A text box that
    // cannot hold it silently ellipsizes a mission's target away, which is worse than a tight fit.
    const geom = block();
    expect(geom.textW).toBeGreaterThanOrEqual(132);
  });

  test('the block sits inside the LEDGER panel, in screen coordinates', () => {
    const geom = block();
    for (const r of [...geom.rows, ...geom.bars]) {
      const screen = rect(LEDGER.x + r.x, LEDGER.y + r.y, r.w, r.h);
      expect({ r: screen, ok: insideScreen(screen) }).toMatchObject({ ok: true });
      expect(screen.x).toBeGreaterThanOrEqual(LEDGER.x);
      expect(screen.x + screen.w).toBeLessThanOrEqual(LEDGER.x + LEDGER.w);
      expect(screen.y).toBeGreaterThanOrEqual(LEDGER.y);
      expect(screen.y + screen.h).toBeLessThanOrEqual(LEDGER.y + LEDGER.h);
    }
    expect(GAMEOVER_MISSIONS_RULE_Y).toBeGreaterThan(boardEnd());
    expect(GAMEOVER_MISSIONS_Y).toBeGreaterThan(GAMEOVER_MISSIONS_RULE_Y);
  });

  test('the whole block fits above the panel floor', () => {
    const geom = block();
    const last = geom.bars[geom.bars.length - 1];
    expect(last.y + last.h).toBeLessThanOrEqual(PANEL_FLOOR);
    // Not merely "fits": a zero-margin layout is what made the first attempt look acceptable.
    expect(PANEL_FLOOR - (last.y + last.h)).toBeGreaterThanOrEqual(2);
  });

  test('the block clears the leaderboard rows above it', () => {
    expect(GAMEOVER_MISSIONS_RULE_Y).toBeGreaterThan(boardEnd());
    expect(GAMEOVER_MISSIONS_Y).toBeGreaterThan(boardEnd());
  });

  test('the block does not run through the retry buttons or the XP row', () => {
    const geom = block();
    const last = geom.bars[geom.bars.length - 1];
    const lastScreen = rect(LEDGER.x + last.x, LEDGER.y + last.y, last.w, last.h);
    // Luna's round-2 finding: the first attempt ended near screen y 251, through the buttons at
    // 220..244 and the XP line at 246.
    expect(overlaps(lastScreen, BUTTONS)).toBe(false);
    expect(lastScreen.y + lastScreen.h).toBeLessThanOrEqual(BUTTONS.y);
  });

  test('the panel still shows all ten entries its title advertises', () => {
    // Luna's round-3 finding: the block was bought by trimming the board to 8 rows while the panel
    // title still read "TOP 10". The pitch is tightened instead; the COUNT is the user-visible contract.
    expect(GAMEOVER_BOARD_ROWS).toBe(10);
    expect(GAMEOVER_BOARD_ROW_H).toBeLessThan(11);
    expect(boardEnd()).toBeLessThanOrEqual(GAMEOVER_MISSIONS_RULE_Y); // board ends above the rule
  });
});

describe('Game Over initials-entry stack', () => {
  // CC Friday's blocking regression at 7617a80: the legibility fix moved the two hint lines to local
  // 84/96 to clear the mission separator, but InitialsEntry draws its own SAVE button at local
  // 88..104, so the button box covered the middle of both hint lines. The old probe only measured
  // mission-row glyph heights, so nothing could see this. These assertions exist so it cannot recur.

  test('the SAVE button never overlaps either hint line', () => {
    const L = entryLayout();
    for (const [i, h] of L.hints.entries()) {
      expect({ hint: i, overlap: overlaps(L.save, h) }).toMatchObject({ overlap: false });
      // Disjoint is the floor; a real gap is what reads as separate controls.
      const clear = h.y >= L.save.y + L.save.h || L.save.y >= h.y + h.h;
      expect(clear).toBe(true);
    }
  });

  test('the SAVE button owns the band the entry widget draws it in', () => {
    // Mirrors InitialsEntry's constructor: slotY 14, slotH 28, SAVE at slotY + slotH + 18 with h 16,
    // offset by the widget's own y. If the widget moves, this fails instead of drifting silently.
    const L = entryLayout();
    const widgetSaveY = L.entryY + L.entrySlotY + L.entrySlotH + 18;
    expect(L.save.y).toBe(widgetSaveY);
    expect(L.save.h).toBe(16);
  });

  test('nothing in the entry stack runs into the mission block below it', () => {
    const L = entryLayout();
    expect(L.contentBottom).toBeLessThan(GAMEOVER_MISSIONS_RULE_Y);
    // And a real gap, not a one-pixel join: the rule at 127 plus mission rows from 128.
    expect(GAMEOVER_MISSIONS_RULE_Y - L.contentBottom).toBeGreaterThanOrEqual(2);
    for (const h of L.hints) expect(h.y + h.h).toBeLessThanOrEqual(L.contentBottom);
  });

  test('each hint line gets a full glyph height', () => {
    const L = entryLayout();
    for (const h of L.hints) {
      expect(h.h).toBeGreaterThanOrEqual(FONT_LINE_H - 1);
      // Consecutive hint lines must not merge either.
      expect(h.h).toBeGreaterThanOrEqual(GLYPH_H);
    }
    expect(L.hints[1].y).toBeGreaterThanOrEqual(L.hints[0].y + GLYPH_H);
  });

  test('the stack stays inside the panel and below the title', () => {
    const L = entryLayout();
    expect(L.title.y + L.title.h).toBeLessThanOrEqual(L.entryY + L.entrySlotY);
    for (const r of [L.title, L.slots, L.save, ...L.hints]) {
      expect(r.x).toBeGreaterThanOrEqual(0);
      expect(r.x + r.w).toBeLessThanOrEqual(L.panelW);
      expect(r.y).toBeGreaterThanOrEqual(0);
      expect(r.y + r.h).toBeLessThanOrEqual(GAMEOVER_MISSIONS_RULE_Y);
    }
  });
});

describe('toastSlot', () => {
  test('returns a slot that clears the given HUD strips', () => {
    const strips = [rect(8, 55, 200, 14), rect(8, 70, 200, 10)];
    const slot = toastSlot({ hudStrips: strips });
    expect(slot).not.toBeNull();
    for (const s of strips) expect(overlaps(slot, s, 2)).toBe(false);
    expect(insideScreen(slot)).toBe(true);
  });

  test('with no strips it still returns an on-screen slot', () => {
    const slot = toastSlot({});
    expect(slot).not.toBeNull();
    expect(insideScreen(slot)).toBe(true);
  });

  test('falls back to null rather than drawing over everything when all slots are taken', () => {
    const strips = [rect(0, 55, 480, 60)];
    expect(toastSlot({ hudStrips: strips })).toBeNull();
  });
});

describe('text fit', () => {
  test('charsThatFit is sane for the panel width', () => {
    const L = missionPanelLayout(3);
    expect(charsThatFit(L.rows[0].w)).toBeGreaterThan(10);
    expect(charsThatFit(L.rows[0].w, 0)).toBeGreaterThan(0);
  });

  test('ellipsize shortens only when needed, with one ellipsis', () => {
    expect(ellipsize('short', 300)).toBe('short');
    const long = 'x'.repeat(200);
    const cut = ellipsize(long, 60);
    expect(cut.length).toBeLessThanOrEqual(charsThatFit(60));
    // The pixel font has no '…' glyph (it would draw '?'), so the cut uses the font's own '..' mark,
    // like PixelFont.ellipsize does, and every character of the result must be drawable.
    expect(cut.endsWith('..')).toBe(true);
    expect([...cut].every((ch) => hasGlyph(ch))).toBe(true);
  });

  test('ellipsize never exceeds the row for any real title', () => {
    const rowW = missionPanelLayout(3).rows[0].w;
    const titles = ['Reach 1500 m in one run', 'Parachute + 2 flip types', 'Every trick, one run', 'Collect 1000 shards total'];
    for (const t of titles) {
      expect(ellipsize(t, rowW).length).toBeLessThanOrEqual(charsThatFit(rowW));
    }
  });

  test('handles junk input without throwing', () => {
    expect(() => ellipsize(null, 60)).not.toThrow();
    expect(() => ellipsize(undefined, 0)).not.toThrow();
    expect(ellipsize('abc', 0)).toBeTruthy();
  });
});

describe('Game Over mission block must report what this run earned', () => {
  // CC Friday, W2: Game Over showed only the freshly dealt actives, so clearing "Land a frontflip"
  // for 60 XP was invisible - the player saw three missions they had never seen. These pin the
  // block to the COMPLETED list first, with its payout, and only then the new actives.
  const done = { id: 't1-trick-frontflip', title: 'Land a frontflip', xp: 60, shards: 4 };
  const active = [
    { id: 't1-shards-15', title: 'Collect 15 shards', fraction: 0.4, done: false },
    { id: 't1-airtime-900', title: '900 ms airtime', fraction: 0.1, done: false },
    { id: 't1-dist-250', title: 'Travel 250 m', fraction: 0, done: false },
  ];

  /** Mirror of GameOverScene._buildMissions' row selection (kept in step by the two assertions below). */
  const build = (completed, rows) => {
    const doneRows = completed.slice(0, 3).map((c) => ({
      label: `${c.xp ? `+${c.xp} XP ` : ''}${c.shards ? `+${c.shards} ` : ''}${c.title}`,
      color: 'lime', done: true, fraction: null,
    }));
    const activeRows = rows.slice(0, Math.max(0, 3 - doneRows.length)).map((r) => ({
      label: r.title, color: r.done ? 'lime' : 'text', done: Boolean(r.done),
      fraction: Math.max(0, Math.min(1, r.fraction || 0)),
    }));
    return doneRows.concat(activeRows);
  };

  test('a completed mission leads the block and carries its payout', () => {
    const listed = build([done], active);
    expect(listed[0].label).toContain('Land a frontflip');
    expect(listed[0].label).toContain('+60 XP');
    expect(listed[0].label).toContain('+4');
    expect(listed[0].done).toBe(true);
  });

  test('the payout survives a long mission title', () => {
    // The real failure: a 172 px label against a 166 px budget lost the shard reward to ellipsize.
    // Payout first means the clipped part is the title, which is the expendable half.
    const long = { id: 'l', title: 'Grab 15 shards in a run', xp: 60, shards: 4 };
    const label = build([long], []).length ? build([long], [])[0].label : '';
    expect(label.startsWith('+60 XP +4 ')).toBe(true);
    // And the payout fits the row on its own, with room left for part of the title.
    expect(measureText('+60 XP +4 ')).toBeLessThan(166);
  });

  test('the fresh actives still appear, so the player knows what is next', () => {
    const listed = build([done], active);
    expect(listed).toHaveLength(3);
    expect(listed[1].label).toBe('Collect 15 shards');
    expect(listed[2].label).toBe('900 ms airtime');
  });

  test('a completed mission never also draws a progress bar', () => {
    // Its bar would read 0% (nothing left to do) or 100% (tautology). Both are lies about state.
    for (const row of build([done], active)) {
      if (row.done && row.fraction === null) expect(row.fraction).toBeNull();
    }
    expect(build([done], active)[0].fraction).toBeNull();
  });

  test('a run with no completions still shows the three actives, as before', () => {
    const listed = build([], active);
    expect(listed).toHaveLength(3);
    expect(listed.every((r) => r.fraction !== null)).toBe(true);
  });

  test('three completions fill the band and no actives are squeezed in', () => {
    const three = [done, { ...done, id: 'b', title: 'Second', xp: 30 }, { ...done, id: 'c', title: 'Third', xp: 20 }];
    const listed = build(three, active);
    expect(listed).toHaveLength(3);
    expect(listed.every((r) => r.done)).toBe(true);
  });

  test('a completion with no payout prints no stray punctuation', () => {
    const listed = build([{ id: 'x', title: 'Land a frontflip', xp: 0, shards: 0 }], active);
    expect(listed[0].label).toBe('Land a frontflip');
  });
});/**
 * Pins the MEASURED reachability evidence for mission targets.
 *
 * tools/sim/mission-reachability.mjs plays the real game (headless Chromium, two bot policies) under
 * every DailyPatch rule and writes tools/sim/.reach/reachability.json. This test reads that file and
 * asserts each single-run template's target is at or below what was actually achieved somewhere.
 *
 * Why a pinned file instead of running the browser sweep inside jest: the sweep needs Chromium and a
 * vite server (~4 min). The risk of a stale snapshot is handled by checking the run's own metadata —
 * seed count, rule coverage and policy list — so a template added or retuned without a fresh sweep
 * fails here rather than passing against last week's numbers.
 */
import { readFileSync, existsSync } from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import missionsData from '../../src/data/missions/missions.json';
import { DailyPatch } from '../../src/systems/DailyPatch.js';

const here = path.dirname(fileURLToPath(import.meta.url));
const root = path.resolve(here, '../..');
const EVIDENCE = path.join(root, 'tools/sim/.reach/reachability.json');
const METRICS = ['distanceM', 'score', 'shards', 'nearMisses', 'maxAirtimeMs', 'tricks'];

const evidence = existsSync(EVIDENCE) ? JSON.parse(readFileSync(EVIDENCE, 'utf8')) : null;
const targets = missionsData.templates.filter(
  (t) => t && t.type === 'singleRun' && METRICS.includes(t.metric) && t.target > 0,
);

describe('measured mission reachability (tools/sim evidence)', () => {
  test('the measured evidence file exists', () => {
    expect(evidence).not.toBeNull();
  });

  test('the sweep covered every daily rule plus the neutral case', () => {
    if (!evidence) return;
    const expected = ['none', ...DailyPatch.RULES.map((r) => r.id)].sort();
    expect(Object.keys(evidence.perRule).sort()).toEqual(expected);
  });

  test('the sweep used both bot policies and at least 10 seeds per rule', () => {
    if (!evidence) return;
    expect(evidence.policies).toEqual(expect.arrayContaining(['hop', 'flip']));
    for (const [rule, row] of Object.entries(evidence.perRule)) {
      expect({ rule, runs: row.runs >= 10 }).toMatchObject({ runs: true });
    }
  });

  test('the sweep found no unreachable single-run target', () => {
    if (!evidence) return;
    expect(evidence.failures).toEqual([]);
  });

  test('every single-run target is at or below a MEASURED maximum under every rule', () => {
    if (!evidence) return;
    for (const t of targets) {
      for (const [rule, row] of Object.entries(evidence.perRule)) {
        const seen = row[t.metric] || 0;
        expect({ id: t.id, rule, target: t.target, seen, ok: t.target <= seen }).toMatchObject({
          ok: true,
        });
      }
    }
  });
});/**
 * W2 — MissionsService wiring. Verifies the properties that only show up once the service is
 * attached to ProgressionService: no double payout on a replayed RUN_END, boot fills empty slots,
 * and a broken mission set can never take down XP crediting.
 */
import { MissionsService } from '../../src/systems/MissionsService.js';
import { ProgressionService } from '../../src/systems/ProgressionService.js';
import { ProfileStore, PROFILE_KEY } from '../../src/systems/ProfileStore.js';
import { REG } from '../../src/constants.js';
import { EVT } from '../../src/events.js';
import { satisfies } from '../../src/systems/Missions.js';
import missionsData from '../../src/data/missions/missions.json';
import levels from '../../src/data/progression/levels.json';

const TEMPLATES = missionsData.templates;

const memStorage = () => {
  const m = new Map();
  return {
    getItem: (k) => (m.has(k) ? m.get(k) : null),
    setItem: (k, v) => m.set(k, String(v)),
    removeItem: (k) => m.delete(k),
    clear: () => m.clear(),
    get length() { return m.size; },
    key: (i) => [...m.keys()][i] ?? null,
  };
};

function fakeGame(events) {
  const handlers = new Map();
  const reg = new Map();
  return {
    registry: {
      get: (k) => reg.get(k),
      set: (k, v) => { reg.set(k, v); },
    },
    events: {
      on: (e, fn) => { handlers.set(e, fn); return fn; },
      off: (e, fn) => { if (handlers.get(e) === fn) handlers.delete(e); },
      once: () => {},
      emit: (e, p) => { const fn = handlers.get(e); if (fn) fn(p); else events.push([e, p]); },
    },
  };
}

const rec = (o = {}) => ({
  version: 1, id: 'run-1', seed: 's', dailyRuleId: null, startedAt: 0, endedAt: 60000,
  durationMs: 60000, score: 5000, distanceM: 2000, trickPoints: 0,
  tricks: { backflip: 1, frontflip: 1, helicopterCCW: 1, parachute: 1 },
  bestCombo: 6, maxAirtimeMs: 4000, shards: 40, nearMisses: 12,
  cause: 'crash', ledgerHash: 'abc123', ...o,
});

/** Build a progression + missions pair the way createServices does. */
async function make() {
  const game = fakeGame([]);
  const store = new ProfileStore({ levels, storage: memStorage() });
  store.load();
  const progression = new ProgressionService(game, { levels, store });
  await progression.init();
  const missions = new MissionsService(game, { templates: TEMPLATES, store });
  await missions.init();
  progression.missions = missions;
  return { game, store, progression, missions };
}

describe('MissionsService boot', () => {
  test('fills three slots on a fresh profile', async () => {
    const { store } = await make();
    expect(store.profile.missions.active).toHaveLength(3);
  });

  test('publishes a mission view for the UI', async () => {
    const { game } = await make();
    const view = game.registry.get(REG.MISSIONS);
    expect(view.active).toHaveLength(3);
    for (const row of view.active) {
      expect(typeof row.title).toBe('string');
      expect(row.fraction).toBeGreaterThanOrEqual(0);
      expect(row.fraction).toBeLessThanOrEqual(1);
    }
  });

  test('is stable across boots — the same profile keeps its missions', async () => {
    const storage = memStorage();
    const game = fakeGame([]);
    const s1 = new ProfileStore({ levels, storage });
    s1.load();
    const p1 = new ProgressionService(game, { levels, store: s1 });
    await p1.init();
    const m1 = new MissionsService(game, { templates: TEMPLATES, store: s1 });
    await m1.init();
    const first = [...s1.profile.missions.active];

    const s2 = new ProfileStore({ levels, storage });
    s2.load();
    const p2 = new ProgressionService(game, { levels, store: s2 });
    await p2.init();
    const m2 = new MissionsService(game, { templates: TEMPLATES, store: s2 });
    await m2.init();
    expect([...s2.profile.missions.active]).toEqual(first);
  });
});

describe('RUN_END wiring', () => {
  test('crediting a run rolls missions and reports them in the awards view', async () => {
    const { game, store, progress: _p } = await make();
    game.events.emit(EVT.RUN_END, { record: rec() });
    const awards = game.registry.get(REG.LAST_AWARDS);
    // The roll happened and was reported. Note the counter only advances when a replacement has to
    // be drawn — a run that completes nothing correctly leaves it alone.
    expect(awards.missions).not.toBeNull();
    expect(awards.missions).toHaveProperty('completed');
    expect(Array.isArray(awards.missions.completed)).toBe(true);
    expect(store.profile.missions.active).toHaveLength(3);
  });

  test('a replayed RUN_END pays missions nothing', async () => {
    const { game, store } = await make();
    game.events.emit(EVT.RUN_END, { record: rec({ ledgerHash: 'dup' }) });
    const xpAfterFirst = store.profile.xp;
    const bankAfterFirst = store.profile.bank;
    const activeAfterFirst = [...store.profile.missions.active];

    game.events.emit(EVT.RUN_END, { record: rec({ ledgerHash: 'dup' }) });

    expect(store.profile.xp).toBe(xpAfterFirst);
    expect(store.profile.bank).toBe(bankAfterFirst);
    expect([...store.profile.missions.active]).toEqual(activeAfterFirst);
    const awards = game.registry.get(REG.LAST_AWARDS);
    // The second event was a no-op, so it paid no missions.
    expect(awards.missions).toBeNull();
  });

  test('a run that completes a mission pays XP and shards into the profile', async () => {
    // Build the services ONCE with an extra trivially-easy template, then force it into slot 0
    // directly on the profile. Re-initialising ProgressionService here would call store.load() and
    // re-read storage over the setup — which is what made the first version of this test fail.
    const game = fakeGame([]);
    const easy = { id: 'zzz-easy', type: 'singleRun', tier: 1, title: 'Reach 10 m', metric: 'distanceM', target: 10 };
    const templates = [...TEMPLATES, easy];
    const store = new ProfileStore({ levels, storage: memStorage() });
    store.load();
    const progression = new ProgressionService(game, { levels, store });
    await progression.init();
    const missions = new MissionsService(game, { templates, store });
    await missions.init();
    progression.missions = missions;

    const m = store.profile.missions;
    store.profile = {
      ...store.profile,
      missions: { ...m, active: ['zzz-easy', m.active[0], m.active[1]] },
    };

    const xpBefore = store.profile.xp;
    const bankBefore = store.profile.bank;
    game.events.emit(EVT.RUN_END, { record: rec({ ledgerHash: 'easy-1' }) });
    const awards = game.registry.get(REG.LAST_AWARDS);
    expect(awards.missions.completed.map((c) => c.id)).toContain('zzz-easy');
    expect(store.profile.xp).toBeGreaterThan(xpBefore);
    expect(store.profile.bank).toBeGreaterThan(bankBefore);
  });
});

describe('resilience', () => {
  test('a throwing missions service does not stop XP crediting', async () => {
    const { game, store, progression } = await make();
    progression.missions = { onRunCredited: () => { throw new Error('boom'); } };
    const xpBefore = store.profile.xp;
    expect(() => game.events.emit(EVT.RUN_END, { record: rec({ ledgerHash: 'boom-1' }) })).not.toThrow();
    expect(store.profile.xp).toBeGreaterThan(xpBefore);
    const awards = game.registry.get(REG.LAST_AWARDS);
    expect(awards.missions).toBeNull();
  });

  test('survives a corrupt missions block in storage', async () => {
    const storage = memStorage();
    storage.setItem(PROFILE_KEY, JSON.stringify({ v: 1, missions: { counter: 'nope', active: 'x', progress: 5 } }));
    const game = fakeGame([]);
    const store = new ProfileStore({ levels, storage });
    store.load();
    const missions = new MissionsService(game, { templates: TEMPLATES, store });
    await expect(missions.init()).resolves.toBeTruthy();
    expect(store.profile.missions.active).toHaveLength(3);
  });
});

describe('mid-run live evaluation (spec W2)', () => {
  /** Services with a trivially-completable mission forced into slot 0. */
  async function withEasy() {
    const game = fakeGame([]);
    const easy = { id: 'zzz-live', type: 'singleRun', tier: 1, title: 'Collect 3 shards', metric: 'shards', target: 3 };
    const templates = [...TEMPLATES, easy];
    const store = new ProfileStore({ levels, storage: memStorage() });
    store.load();
    const progression = new ProgressionService(game, { levels, store });
    await progression.init();
    const missions = new MissionsService(game, { templates, store });
    await missions.init();
    progression.missions = missions;
    const m = store.profile.missions;
    store.profile = { ...store.profile, missions: { ...m, active: ['zzz-live', m.active[0], m.active[1]] } };
    return { game, store, progression, missions };
  }

  test('toasts a mission the moment its target is met', async () => {
    const { game } = await withEasy();
    const seen = [];
    game.events.emit(EVT.RUN_START, { seed: 's' });
    game.events.on(EVT.MISSION_COMPLETED, (p) => seen.push(p));

    game.events.emit(EVT.SHARD_COLLECTED, {});
    expect(seen).toHaveLength(0);
    game.events.emit(EVT.SHARD_COLLECTED, {});
    expect(seen).toHaveLength(0);
    game.events.emit(EVT.SHARD_COLLECTED, {});
    expect(seen.map((s) => s.id)).toEqual(['zzz-live']);
    expect(seen[0].title).toBe('Collect 3 shards');
    expect(seen[0].xp).toBeGreaterThan(0);
  });

  test('toasts once, not once per later event', async () => {
    const { game } = await withEasy();
    const seen = [];
    game.events.on(EVT.MISSION_COMPLETED, (p) => seen.push(p));
    game.events.emit(EVT.RUN_START, {});
    for (let i = 0; i < 10; i += 1) game.events.emit(EVT.SHARD_COLLECTED, {});
    expect(seen).toHaveLength(1);
  });

  test('the live toast pays nothing — only RUN_END pays', async () => {
    const { game, store } = await withEasy();
    const xpBefore = store.profile.xp;
    game.events.emit(EVT.RUN_START, {});
    for (let i = 0; i < 5; i += 1) game.events.emit(EVT.SHARD_COLLECTED, {});
    // A pure live pass must not move the profile at all.
    expect(store.profile.xp).toBe(xpBefore);
  });

  test('BSOD Gym mission events cannot toast; the next normal run still can', async () => {
    const { game, store, missions } = await withEasy();
    const seen = [];
    game.events.on(EVT.MISSION_COMPLETED, (p) => seen.push(p.id));
    const bankBefore = store.profile.bank, xpBefore = store.profile.xp;
    game.registry.set(REG.BSOD_GYM, true);
    game.events.emit(EVT.RUN_START, { gym: true });
    for (let i = 0; i < 12; i++) {
      game.events.emit(EVT.SHARD_COLLECTED, {});
      game.events.emit(EVT.NEAR_MISS, { hazardType: 'bsod' });
      game.events.emit(EVT.SCORE_CHANGED, { total: 9999999 });
      game.events.emit(EVT.TRICK, { type: 'frontflip' });
      game.events.emit(EVT.DISTANCE_CHANGED, { meters: 999999 });
    }
    expect(seen).toEqual([]);
    expect(missions._completedThisRun.has('zzz-live')).toBe(false);
    expect(store.profile.bank).toBe(bankBefore);
    expect(store.profile.xp).toBe(xpBefore);
    game.events.emit(EVT.RUN_ABORT, {});
    game.registry.set(REG.BSOD_GYM, false);
    game.events.emit(EVT.RUN_START, { gym: false });
    game.events.emit(EVT.SHARD_COLLECTED, {});
    game.events.emit(EVT.SHARD_COLLECTED, {});
    expect(seen).toEqual([]);
    game.events.emit(EVT.SHARD_COLLECTED, {});
    expect(seen).toEqual(['zzz-live']);
  });

  test('live counters reset on a new run', async () => {
    const { game } = await withEasy();
    game.events.emit(EVT.RUN_START, {});
    game.events.emit(EVT.SHARD_COLLECTED, {});
    game.events.emit(EVT.SHARD_COLLECTED, {});
    game.events.emit(EVT.RUN_START, {}); // new run zeroes the live counters
    const seen = [];
    game.events.on(EVT.MISSION_COMPLETED, (p) => seen.push(p));
    game.events.emit(EVT.SHARD_COLLECTED, {});
    expect(seen).toHaveLength(0);
  });
});

describe('mission XP crossing a level threshold', () => {
  test('awards the level reward, not just the new level number', async () => {
    // Luna W2 finding 4: applyMissions used to raise `xp` and let sanitizeProfile derive `level`, so
    // a mission payout that crossed a threshold showed the new level while permanently losing its
    // reward — the next run then started from the higher level and never went back for it.
    const game = fakeGame([]);
    const easy = { id: 'zzz-level', type: 'singleRun', tier: 1, title: 'Reach 10 m', metric: 'distanceM', target: 10 };
    const store = new ProfileStore({ levels, storage: memStorage() });
    store.load();
    store.profile = { ...store.profile, xp: 70 }; // level 2 threshold is 80 XP
    const missions = new MissionsService(game, { templates: [...TEMPLATES, easy], store });
    await missions.init();
    store.profile.missions.active = [easy.id];

    expect(store.profile.level).toBe(1);
    missions.onRunCredited(rec({ ledgerHash: 'level-1', distanceM: 500 }));

    expect(store.profile.xp).toBeGreaterThanOrEqual(80);
    expect(store.profile.level).toBe(2);
    expect(store.profile.unlocked.cosmetics).toContain('trail-cyan');
  });
});

describe('combo missions (same-combo requirement)', () => {
  test('a combo mission is met only when the tricks land in ONE combo', async () => {
    const game = fakeGame([]);
    const t = { id: 'zzz-combo', type: 'combo', tier: 1, title: 'Backflip + heli, one combo', require: ['backflip', 'helicopter'] };
    // Inert filler: the other two slots must hold missions this run cannot satisfy, or the assertion
    // below is really about whatever the draw happened to return. They were auto-drawn fillers before
    // D7 changed which tiers a level-1 profile draws, and then trick missions appeared here and
    // completed legitimately, failing a test about combo membership.
    const filler = (id) => ({ id, type: 'singleRun', tier: 1, title: 'Unreachable filler', metric: 'score', target: 9_999_999 });
    const store = new ProfileStore({ levels, storage: memStorage() });
    store.load();
    const progression = new ProgressionService(game, { levels, store });
    await progression.init();
    const missions = new MissionsService(game, { templates: [...TEMPLATES, t, filler('zzz-fill-a'), filler('zzz-fill-b')], store });
    await missions.init();
    progression.missions = missions;
    const m = store.profile.missions;
    store.profile = { ...store.profile, missions: { ...m, active: ['zzz-combo', 'zzz-fill-a', 'zzz-fill-b'] } };

    const seen = [];
    game.events.on(EVT.MISSION_COMPLETED, (p) => seen.push(p.id));
    game.events.emit(EVT.RUN_START, {});
    // Backflip lands, combo resets, then a heli: both tricks happened, but not together.
    game.events.emit(EVT.COMBO_CHANGED, { multiplier: 2, tricks: ['backflip'] });
    game.events.emit(EVT.COMBO_CHANGED, { multiplier: 1, tricks: ['helicopterCCW'] });
    expect(seen).toEqual([]);

    // Now both in the same combo.
    game.events.emit(EVT.COMBO_CHANGED, { multiplier: 3, tricks: ['backflip', 'helicopterCW'] });
    expect(seen).toEqual([]);
    game.events.emit(EVT.LANDING, { quality: 'clean' });
    expect(seen).toEqual(['zzz-combo']);
  });

  test('a completed live combo is paid after the combo resets and the run is credited', async () => {
    const game = fakeGame([]);
    const t = { id: 'zzz-combo', type: 'combo', tier: 1, title: 'Backflip + heli', require: ['backflip', 'helicopter'] };
    const store = new ProfileStore({ levels, storage: memStorage() });
    store.load();
    const missions = new MissionsService(game, { templates: [...TEMPLATES, t], store });
    await missions.init();
    store.profile.missions.active = [t.id];
    game.events.emit(EVT.RUN_START, {});
    game.events.emit(EVT.COMBO_CHANGED, { multiplier: 3, tricks: ['backflip', 'helicopterCW'] });
    game.events.emit(EVT.LANDING, { quality: 'clean' });
    game.events.emit(EVT.COMBO_CHANGED, { multiplier: 1, tricks: [] });
    const result = missions.onRunCredited(rec());
    expect(result.completed.map((item) => typeof item === 'string' ? item : item.id)).toContain(t.id);
  });

  test('landed combo rewards persist once when the credited run is replayed', async () => {
    const game = fakeGame([]);
    const t = { id: 'zzz-combo', type: 'combo', tier: 1, title: 'Backflip + heli', require: ['backflip', 'helicopter'] };
    const storage = memStorage();
    const store = new ProfileStore({ levels, storage });
    store.load();
    const progression = new ProgressionService(game, { levels, store });
    await progression.init();
    const missions = new MissionsService(game, { templates: [...TEMPLATES, t], store });
    await missions.init();
    progression.missions = missions;
    store.profile.missions.active = [t.id];
    game.events.emit(EVT.RUN_START, {});
    game.events.emit(EVT.COMBO_CHANGED, { reason: 'trick', tricks: ['backflip', 'helicopterCW'] });
    game.events.emit(EVT.LANDING, { quality: 'clean' });
    game.events.emit(EVT.COMBO_CHANGED, { reason: 'landing', tricks: [] });
    const record = rec({ ledgerHash: 'combo-payout' });
    game.events.emit(EVT.RUN_END, { record });
    const awards = game.registry.get(REG.LAST_AWARDS);
    expect(awards.missions.completed.map((item) => item.id)).toContain(t.id);
    expect(awards.missions.xp).toBeGreaterThan(0);
    expect(awards.missions.shards).toBeGreaterThan(0);
    const xp = store.profile.xp;
    const bank = store.profile.bank;
    const reloaded = new ProfileStore({ levels, storage });
    reloaded.load();
    expect(reloaded.profile.xp).toBe(xp);
    expect(reloaded.profile.bank).toBe(bank);
    game.events.emit(EVT.RUN_END, { record });
    expect(store.profile.xp).toBe(xp);
    expect(store.profile.bank).toBe(bank);
  });

  test('a crashed landing does not complete a pending combo mission', async () => {
    const game = fakeGame([]);
    const t = { id: 'zzz-combo', type: 'combo', tier: 1, title: 'Backflip + heli', require: ['backflip', 'helicopter'] };
    const store = new ProfileStore({ levels, storage: memStorage() });
    store.load();
    const missions = new MissionsService(game, { templates: [...TEMPLATES, t], store });
    await missions.init();
    store.profile.missions.active = [t.id];
    game.events.emit(EVT.RUN_START, {});
    game.events.emit(EVT.COMBO_CHANGED, { reason: 'trick', tricks: ['backflip', 'helicopterCW'] });
    game.events.emit(EVT.LANDING, { quality: 'crash' });
    expect(missions.onRunCredited(rec()).completed.map((item) => item.id)).not.toContain(t.id);
  });

  test('a run record alone cannot satisfy a combo mission', () => {
    // Under-award rather than pay for tricks that merely coexisted in a run.
    const rec = { tricks: { backflip: 2, helicopterCCW: 1 } };
    expect(satisfies({ type: 'combo', require: ['backflip', 'helicopter'] }, { record: rec })).toBe(false);
  });
});/**
 * W4 — modded runs get their own leaderboard tab, decided in Ranking.js and nowhere else.
 *
 * Spec W4: "While the constant is false, modded runs are excluded from the clean top-10, getSeedStats,
 * getDailyStats and the NEW BEST marker; they get their own leaderboard tab". The tab is the part that is
 * easy to skip: excluding a boosted run everywhere it could rank is complete-looking, and it means a
 * player who paid for a boost and scored their best run has nowhere to see it.
 */
import { isModdedOnly, isRankable, rankableOnly } from '../../src/systems/Ranking.js';
import { SaveStore } from '../../src/systems/SaveStore.js';

const rec = (o) => ({
  version: 1, id: o.id || 'r1', score: 1000, distanceM: 500, initials: 'AAA',
  endedAt: 1000, seed: 's', tricks: {}, ...o,
});

describe('isModdedOnly', () => {
  test('a boosted run belongs on the modded board', () => {
    expect(isModdedOnly(rec({ modded: true }))).toBe(true);
  });

  test('a clean run does not', () => {
    expect(isModdedOnly(rec({}))).toBe(false);
    expect(isModdedOnly(rec({ modded: false }))).toBe(false);
  });

  test('a pre-W4 record with no modded field does not', () => {
    // Absent means clean: W4 must not retroactively move every historical run onto the modded tab.
    const old = rec({});
    delete old.modded;
    expect(isModdedOnly(old)).toBe(false);
  });

  test('junk is not modded', () => {
    for (const v of [null, undefined, 42, 'x', []]) expect(isModdedOnly(v)).toBe(false);
  });

  test('when the constant is on, a modded run ranks clean and does not also need the tab', () => {
    // Flipping the constant must move the run onto the clean board, not duplicate it onto both.
    const r = rec({ modded: true });
    expect(isRankable(r, { ranked: true })).toBe(true);
    expect(isModdedOnly(r, { ranked: true })).toBe(false);
  });
});

describe('the two boards are exactly complementary', () => {
  test('every record lands on exactly one of clean / modded', () => {
    const rows = [
      rec({ id: 'clean-1' }),
      rec({ id: 'clean-old' }),
      rec({ id: 'mod-1', modded: true }),
      rec({ id: 'mod-2', modded: true, score: 2000 }),
    ];
    const clean = rankableOnly(rows);
    const modded = rows.filter((r) => isModdedOnly(r));
    expect(clean.length + modded.length).toBe(rows.length);
    // No record appears in both: that would double-count a run on two boards.
    const cleanIds = new Set(clean.map((r) => r.id));
    expect(modded.some((r) => cleanIds.has(r.id))).toBe(false);
  });

  test('flipping the constant moves the modded runs onto the clean board', () => {
    const rows = [rec({ id: 'c' }), rec({ id: 'm', modded: true })];
    expect(rankableOnly(rows).map((r) => r.id)).toEqual(['c']);
    expect(rankableOnly(rows, { ranked: true }).map((r) => r.id)).toEqual(['c', 'm']);
    expect(rows.filter((r) => isModdedOnly(r, { ranked: true }))).toEqual([]);
  });
});

/** A store with no IndexedDB: the in-memory mirror is what reads are served from. */
function makeStore(runs) {
  const s = new SaveStore();
  s.runs = runs;
  return s;
}

describe('qualifiesForModdedTop10 — the board a boosted run can actually enter', () => {
  test('a boosted score qualifies on the MODDED board, and never on the clean one', async () => {
    // The defect this closes: Game Over asked qualifiesForTop10 for a boosted run, which either offered
    // clean-board initials for a run the clean board will never hold, or (with fudged opts) made every
    // clean run on the board unrankable. A boosted run has its own board, so it gets its own question.
    const store = makeStore([]);
    expect(await store.qualifiesForModdedTop10(500)).toBe(true);
    // qualifiesForTop10's `opts` is the candidate record itself, so the boosted candidate is passed as the
    // record: that is what makes the helper (not the caller) decide it cannot rank.
    expect(await store.qualifiesForTop10(500, { modded: true })).toBe(false);
    // A clean candidate still qualifies: the boost exclusion must not have broken the normal path.
    expect(await store.qualifiesForTop10(500, { modded: false })).toBe(true);
  });

  test('a full modded board only admits a score that beats its last entry', async () => {
    const runs = [];
    for (let i = 0; i < 10; i++) {
      runs.push(rec({ id: `mod-${i}`, score: 1000 + i * 100, endedAt: i + 1, modded: true }));
    }
    const store = makeStore(runs);
    expect(await store.qualifiesForModdedTop10(500)).toBe(false);
    expect(await store.qualifiesForModdedTop10(5000)).toBe(true);
  });

  test('ten CLEAN runs do not fill the modded board', async () => {
    // If they did, a boosted player would be denied their own top 10 by runs that are not on it.
    const runs = [];
    for (let i = 0; i < 10; i++) runs.push(rec({ id: `clean-${i}`, score: 9000, endedAt: i + 1 }));
    const store = makeStore(runs);
    expect(await store.qualifiesForModdedTop10(10)).toBe(true);
  });
});/**
 * W4 — a boosted run is invisible to every clean ranking surface, and still gets paid.
 *
 * Spec W4 gates: "tests proving a modded run cannot enter the clean top-10, seed-best, daily-best or
 * streak; a test that flips the constant and proves they then do."
 *
 * Each surface is tested SEPARATELY because they are four different code paths that all have to respect
 * one rule, and because the tempting shortcut — filter inside `_board()` only — fixes the top-10 while
 * leaving seed best, daily best and the streak still counting the boosted run. A player would then see
 * "NEW BEST" for a run that is not on the board at all.
 *
 * The last block is the mirror requirement: the exclusion must be about RANKING only. Shards, Resonance
 * and mission progress are earned by boosted runs too, so suppressing those would be a second, wrong
 * change hiding behind the first.
 */
import { DailyPatch } from '../../src/systems/DailyPatch.js';
import { SaveStore, sanitizeRun } from '../../src/systems/SaveStore.js';
import { isRankable, rankableOnly } from '../../src/systems/Ranking.js';

/** A store with no IndexedDB: exercises the in-memory mirror, which is the source of truth for reads. */
function makeStore() {
  const s = new SaveStore();
  s.runs = [];
  return s;
}

const RUNS = [
  // A clean run at 900 and a boosted run at 9999. If the exclusion is broken, the boosted run wins
  // every surface by score, so any leak is unmistakable rather than a tie-break argument.
  { id: 'clean-1', seed: 'alpha', dailyRuleId: '', startedAt: 1000, endedAt: 2000, durationMs: 1000, score: 900,
    distanceM: 500, trickPoints: 100, tricks: {}, bestCombo: 2, maxAirtimeMs: 100, cause: 'crash',
    initials: 'ABC', shards: 5, modded: false },
  { id: 'mod-1', seed: 'alpha', dailyRuleId: '', startedAt: 3000, endedAt: 4000, durationMs: 1000, score: 9999,
    distanceM: 9000, trickPoints: 5000, tricks: {}, bestCombo: 9, maxAirtimeMs: 900, cause: 'crash',
    initials: 'XYZ', shards: 500, modded: true },
];

/**
 * The same pair on one specific UTC day's daily seed. Built from a real date so `getDailyInfo` derives it,
 * which is the only way the daily-best and streak surfaces are actually reached — with a plain seed they
 * looked clean and the assertions passed without testing anything.
 */
const DAY = new Date('2026-11-13T12:00:00Z');
const DAILY_SEED = `daily-${DAY.toISOString().slice(0, 10)}`;
// Decisions 1/2: the Daily surfaces count only OFFICIAL Daily runs, so both records are stamped as runs
// started from the DAILY RUN item, on the date's own rule and mask. They still differ only in `modded`,
// so the modded gate is the one thing keeping 9999 off these surfaces.
const DAY_INFO = DailyPatch.infoForDateKey(DAY.toISOString().slice(0, 10));
const OFFICIAL = { dailyRuleId: DAY_INFO.rule.id, biomeMask: DAY_INFO.biomeMask, hashV: 2, dailyOfficial: true };
const DAILY_RUNS = [
  { ...RUNS[0], id: 'daily-clean', seed: DAILY_SEED, ...OFFICIAL, startedAt: DAY.getTime(), endedAt: DAY.getTime() + 1000 },
  { ...RUNS[1], id: 'daily-mod', seed: DAILY_SEED, ...OFFICIAL, startedAt: DAY.getTime() + 2000, endedAt: DAY.getTime() + 3000 },
];

const load = (store, runs) => { store.runs = runs.map((r) => sanitizeRun(r)).filter(Boolean); return store; };

describe('module 0: a boosted run is off every clean surface', () => {
  test('top-10', async () => {
    const store = load(makeStore(), RUNS);
    const board = await store.getLeaderboard(10);
    expect(board.map((r) => r.id)).toEqual(['clean-1']);
  });

  test('seed best', () => {
    const store = load(makeStore(), RUNS);
    const stats = store.getSeedStats('alpha');
    expect(stats.bestScore).toBe(900);
    expect(stats.bestDistanceM).toBe(500);
  });

  test('daily best', () => {
    const store = load(makeStore(), DAILY_RUNS);
    // Same daily seed, so only the modded gate can keep 9999 off this surface.
    expect(store.getDailyStats(DAY).bestScore).toBe(900);
  });

  test('the top-10 qualification prompt does not fire for a boosted run', async () => {
    const store = load(makeStore(), RUNS);
    // 9999 clears a board whose real 10th place is 900; only the modded gate can refuse it.
    expect(await store.qualifiesForTop10(9999, { modded: true })).toBe(false);
    expect(await store.qualifiesForTop10(9999, { modded: false })).toBe(true);
  });

  test('a boosted run does not extend a streak', () => {
    // The streak counts days with a stored run on that day's daily seed. A boosted run must not count,
    // or a player could hold a daily streak with boosts while never playing the clean daily.
    const modOnly = load(makeStore(), [DAILY_RUNS[1]]);
    expect(modOnly.getDailyStreak(DAY).streak).toBe(0);
    const cleanOnly = load(makeStore(), [DAILY_RUNS[0]]);
    expect(cleanOnly.getDailyStreak(DAY).streak).toBe(1);
  });
});

describe('module 1: flipping the constant puts them back', () => {
  test('top-10 includes the boosted run when ranking is enabled', async () => {
    const store = load(makeStore(), RUNS);
    const board = await store.getLeaderboard(10, { ranked: true });
    expect(board.map((r) => r.id)).toEqual(['mod-1', 'clean-1']);
  });

  test('seed best includes it too', () => {
    const store = load(makeStore(), RUNS);
    expect(store.getSeedStats('alpha', { ranked: true }).bestScore).toBe(9999);
  });

  test('the helper is what flipped, not the data', () => {
    // Proves the two runs differ only in the `modded` flag, so the flip above is attributable.
    expect(isRankable(RUNS[0], { ranked: true })).toBe(true);
    expect(isRankable(RUNS[1], { ranked: false })).toBe(false);
    expect(rankableOnly(RUNS, { ranked: false }).map((r) => r.id)).toEqual(['clean-1']);
  });
});

describe('module 2: a boosted run still earns everything', () => {
  test('its shards, XP and mission progress are recorded, not suppressed', async () => {
    // sanitizeRun keeps `modded` and `shards`; nothing on the crediting path may drop them. This is the
    // mirror of the exclusion: a boosted run is ranked separately, not punished.
    const rec = sanitizeRun(RUNS[1]);
    expect(rec.modded).toBe(true);
    expect(rec.shards).toBe(500);
    expect(rec.score).toBe(9999);
  });

  test('an old record with no `modded` field is clean, not retroactively disqualified', () => {
    const { modded, ...old } = RUNS[0];
    const rec = sanitizeRun(old);
    expect(rec.modded).toBeUndefined();
    expect(isRankable(rec)).toBe(true);
  });
});/**
 * W4 — `MODDED_RUNS_RANKED` is the single decision point for whether a boosted run ranks.
 *
 * Spec W4: "Every ranking decision goes through ONE helper that reads the constant. Grep must show no
 * other place deciding whether a modded run counts." The W4 brief calls this out as the gate most
 * likely to be faked by scattering `if (!rec.modded)` across five call sites, so the last test here
 * reads the source tree and fails if a second decision appears anywhere.
 *
 * While the constant is false a boosted run must be invisible to every clean ranking surface — top-10,
 * seed best, daily best and streak — while STILL paying Resonance, shards and mission progress. Getting
 * the exclusion right and then also suppressing the payout would be the wrong half of the feature.
 */
import fs from 'node:fs';
import path from 'node:path';
import { ranksModded, isRankable } from '../../src/systems/Ranking.js';

const get = (v) => v;

describe('ranksModded / isRankable', () => {
  test('a clean run always ranks', () => {
    expect(isRankable({ modded: false })).toBe(true);
    expect(isRankable({})).toBe(true);
    expect(isRankable(null)).toBe(false);
  });

  test('a modded run ranks only when the constant says so', () => {
    expect(isRankable({ modded: true })).toBe(false);
    // Flip the constant: same record, now it counts.
    expect(isRankable({ modded: true }, { ranked: true })).toBe(true);
  });

  test('the constant is false as shipped', async () => {
    // The spec ships MODDED_RUNS_RANKED = false; if someone flips it in constants.js every exclusion
    // below becomes vacuous, so pin the shipped value.
    const { MODDED_RUNS_RANKED } = await import('../../src/constants.js');
    expect(MODDED_RUNS_RANKED).toBe(false);
    expect(ranksModded()).toBe(MODDED_RUNS_RANKED);
  });
});

describe('the single-helper rule', () => {
  test('only Ranking.js reads MODDED_RUNS_RANKED', () => {
    const root = path.resolve(process.cwd(), 'src');
    const offenders = [];
    const walk = (dir) => {
      for (const e of fs.readdirSync(dir, { withFileTypes: true })) {
        const p = path.join(dir, e.name);
        if (e.isDirectory()) { walk(p); continue; }
        if (!e.name.endsWith('.js')) continue;
        const rel = path.relative(root, p);
        if (rel === path.join('systems', 'Ranking.js')) continue;
        if (rel === 'constants.js') continue; // where the constant is declared
        // Reading the constant anywhere but Ranking.js means a second decision point. Prose is not a
        // decision, and a comment that NAMES the constant (explaining why a boost path is not ranked) is
        // documentation, not a second implementation.
        const code = fs.readFileSync(p, 'utf8').split('\n')
          .filter((l) => { const t = l.trim(); return !(t.startsWith('//') || t.startsWith('*') || t.startsWith('/*')); })
          .join('\n');
        if (/MODDED_RUNS_RANKED/.test(code)) offenders.push(rel);
      }
    };
    walk(root);
    expect(offenders).toEqual([]);
  });

  test('no ranking surface DECIDES on `modded` inline', () => {
    // The catch this test exists for: `if (!rec.modded) board.push(rec)` instead of filtering through
    // isRankable(). That passes every behavioural test and is still the scattered implementation the spec
    // forbids. Reading and writing the FIELD is fine (sanitizeRun whitelists it, the loadout sets it);
    // what must not appear elsewhere is a use of it in a condition or comparison.
    const root = path.resolve(process.cwd(), 'src');
    const offenders = [];
    const walk = (dir) => {
      for (const e of fs.readdirSync(dir, { withFileTypes: true })) {
        const p = path.join(dir, e.name);
        if (e.isDirectory()) { walk(p); continue; }
        if (!e.name.endsWith('.js')) continue;
        const rel = path.relative(root, p);
        if (rel === path.join('systems', 'Ranking.js')) continue;
        if (rel === 'constants.js') continue;
        const lines = fs.readFileSync(p, 'utf8').split('\n');
        for (const line of lines) {
          const t = line.trim();
          if (t.startsWith('//') || t.startsWith('*') || t.startsWith('/*')) continue; // prose is not a decision
          if (!/\.modded\b/.test(t)) continue;
          // Assignment or whitelisting is not a decision: `r.modded = true`, `modded: true`, `raw.modded === true`
          // inside sanitizeRun's copy is storage. A conditional/comparison use is a decision.
          // A conditional SPREAD that writes the field into a record (`...(this.modded ? { modded: true } : {})`)
          // is still a write: it decides what gets stored, not which record may rank.
          const isWrite = /^\.?[\w.[\]]*\.modded\s*=[^=]/.test(t)
            || /^modded:/.test(t)
            || /\.\.\.\(.*\.modded.*\{.*modded:/.test(t)
            || /\bif \(raw\.modded === true\)/.test(t);
          if (isWrite) continue;
          offenders.push(`${rel}: ${t}`);
        }
      }
    };
    walk(root);
    expect(offenders).toEqual([]);
  });
});/**
 * ui/Motion.js: the reduce-motion decision, easing, and the "always reach the end state" guarantees of the
 * scene helpers. Pure logic only (no Phaser): Motion deliberately imports none, so it runs as-is under Jest.
 */
import { jest } from '@jest/globals';
import {
  resolveReduceMotion, sanitizeReduceMotion, osPrefersReducedMotion, isReducedMotion, motionMs, REDUCED_MS,
  REDUCE_MOTION_QUERY, REDUCE_MOTION_VALUES, Ease, clamp01, lerp, approach, crtOpenPhases, tweenProgress,
  sceneTransition, transitionIn,
} from '../../src/ui/Motion.js';
import { REG } from '../../src/constants.js';
import { defaultSettings, sanitizeSettings } from '../../src/systems/SaveStore.js';

const fakeWin = (matches, opts = {}) => ({
  matchMedia: jest.fn((q) => (opts.throws ? (() => { throw new Error('nope'); })() : { media: q, matches })),
});
const sceneWith = (settings) => ({ registry: { get: (k) => (k === REG.SETTINGS ? settings : undefined) } });

describe('reduce-motion decision', () => {
  test('explicit on/off always win over the OS', () => {
    expect(resolveReduceMotion('on', false)).toBe(true);
    expect(resolveReduceMotion('off', true)).toBe(false);
  });

  test('auto (and anything unknown) follows the OS', () => {
    expect(resolveReduceMotion('auto', true)).toBe(true);
    expect(resolveReduceMotion('auto', false)).toBe(false);
    expect(resolveReduceMotion(undefined, true)).toBe(true);
    expect(resolveReduceMotion('sometimes', false)).toBe(false);
  });

  test('sanitize keeps the three values and maps the rest to auto', () => {
    for (const v of REDUCE_MOTION_VALUES) expect(sanitizeReduceMotion(v)).toBe(v);
    expect(sanitizeReduceMotion(true)).toBe('auto');
    expect(sanitizeReduceMotion(null)).toBe('auto');
  });

  test('settings default is auto and SaveStore sanitizes the field the same way', () => {
    expect(defaultSettings().reduceMotion).toBe('auto');
    expect(sanitizeSettings({ reduceMotion: 'on' }).reduceMotion).toBe('on');
    expect(sanitizeSettings({ reduceMotion: 'off' }).reduceMotion).toBe('off');
    expect(sanitizeSettings({ reduceMotion: 'yes' }).reduceMotion).toBe('auto');
    expect(defaultSettings().worldDance).toBe(true);
    expect(sanitizeSettings({worldDance:false}).worldDance).toBe(false);
    expect(sanitizeSettings({worldDance:true}).worldDance).toBe(true);
    expect(sanitizeSettings({worldDance:'off'}).worldDance).toBe(true);
  });
});

describe('OS query (guarded for jsdom and old browsers)', () => {
  test('reads the prefers-reduced-motion query', () => {
    const win = fakeWin(true);
    expect(osPrefersReducedMotion(win)).toBe(true);
    expect(win.matchMedia).toHaveBeenCalledWith(REDUCE_MOTION_QUERY);
  });

  test('caches the MediaQueryList per window but re-reads `matches` (live OS changes apply)', () => {
    const mql = { matches: false };
    const win = { matchMedia: jest.fn(() => mql) };
    expect(osPrefersReducedMotion(win)).toBe(false);
    mql.matches = true;
    expect(osPrefersReducedMotion(win)).toBe(true);
    expect(win.matchMedia).toHaveBeenCalledTimes(1);
  });

  test('no window, no matchMedia, a throwing or empty matchMedia all mean "no preference"', () => {
    expect(osPrefersReducedMotion(null)).toBe(false);
    expect(osPrefersReducedMotion({})).toBe(false);
    expect(osPrefersReducedMotion(fakeWin(true, { throws: true }))).toBe(false);
    expect(osPrefersReducedMotion({ matchMedia: () => null })).toBe(false);
  });

  test('the jsdom global window (no matchMedia) does not throw', () => {
    expect(() => osPrefersReducedMotion()).not.toThrow();
  });
});

describe('isReducedMotion reads the live settings from a scene or a game', () => {
  test('scene registry, explicit values', () => {
    expect(isReducedMotion(sceneWith({ reduceMotion: 'on' }), fakeWin(false))).toBe(true);
    expect(isReducedMotion(sceneWith({ reduceMotion: 'off' }), fakeWin(true))).toBe(false);
  });

  test('auto defers to the OS; missing settings count as auto', () => {
    expect(isReducedMotion(sceneWith({ reduceMotion: 'auto' }), fakeWin(true))).toBe(true);
    expect(isReducedMotion(sceneWith(undefined), fakeWin(true))).toBe(true);
    expect(isReducedMotion(sceneWith(undefined), fakeWin(false))).toBe(false);
  });

  test('works from a game object and from nothing at all', () => {
    const game = { registry: sceneWith({ reduceMotion: 'on' }).registry };
    expect(isReducedMotion({ game }, fakeWin(false))).toBe(true);
    expect(isReducedMotion(null, fakeWin(false))).toBe(false);
  });

  test('motionMs caps durations only when reduced', () => {
    expect(motionMs(400, false)).toBe(400);
    expect(motionMs(400, true)).toBe(REDUCED_MS);
    expect(motionMs(50, true)).toBe(50);
  });
});

describe('easing', () => {
  test('every curve maps 0 -> 0 and 1 -> 1 and clamps its input', () => {
    for (const [name, f] of Object.entries(Ease)) {
      expect([name, f(0)]).toEqual([name, 0]);
      expect([name, Math.round(f(1) * 1e9) / 1e9]).toEqual([name, 1]);
      expect([name, f(-3)]).toEqual([name, f(0)]);
      expect([name, f(7)]).toEqual([name, f(1)]);
    }
  });

  test('monotone curves are monotone; outBack overshoots then settles', () => {
    for (const name of ['linear', 'inQuad', 'outQuad', 'inCubic', 'outCubic', 'inOutCubic', 'inOutSine']) {
      let prev = -1;
      for (let i = 0; i <= 20; i++) {
        const v = Ease[name](i / 20);
        expect(v).toBeGreaterThanOrEqual(prev);
        prev = v;
      }
    }
    expect(Math.max(...Array.from({ length: 21 }, (_, i) => Ease.outBack(i / 20)))).toBeGreaterThan(1);
  });

  test('clamp01 / lerp', () => {
    expect([clamp01(-1), clamp01(0.4), clamp01(2)]).toEqual([0, 0.4, 1]);
    expect(lerp(10, 20, 0.25)).toBe(12.5);
  });

  test('approach is frame-rate independent: two 8 ms steps equal one 16 ms step', () => {
    const one = approach(16, 40);
    const a = approach(8, 40);
    const two = 1 - (1 - a) * (1 - a);
    expect(two).toBeCloseTo(one, 10);
    expect(approach(40, 40)).toBeCloseTo(0.5, 10);
    expect(approach(0)).toBe(0);
    expect(approach(NaN)).toBe(0);
  });

  test('CRT open: the line draws first, then the panel opens and ends fully open', () => {
    expect(crtOpenPhases(0)).toEqual({ line: 0, open: 0 });
    const early = crtOpenPhases(0.2);
    expect(early.open).toBe(0);
    expect(early.line).toBeGreaterThan(0);
    const late = crtOpenPhases(0.7);
    expect(late.line).toBe(1);
    expect(late.open).toBeGreaterThan(0);
    expect(crtOpenPhases(1).open).toBeCloseTo(1, 9);
  });
});

describe('scene helpers always reach their end state', () => {
  test('tweenProgress without a tween manager jumps to the end and completes once', () => {
    const seen = [];
    const done = jest.fn();
    const tw = tweenProgress({}, { duration: 300, onUpdate: (p) => seen.push(p), onComplete: done });
    expect(tw).toBeNull();
    expect(seen).toEqual([1]);
    expect(done).toHaveBeenCalledTimes(1);
  });

  test('tweenProgress drives eased progress from a real-shaped counter tween, and completes once on stop', () => {
    let cfg = null;
    const scene = { tweens: { addCounter: (c) => { cfg = c; return {}; } } };
    const seen = [];
    const done = jest.fn();
    tweenProgress(scene, { duration: 100, ease: Ease.inQuad, onUpdate: (e, raw) => seen.push([e, raw]), onComplete: done });
    cfg.onUpdate({ getValue: () => 0.5 });
    expect(seen[0]).toEqual([0.25, 0.5]);
    cfg.onStop();
    cfg.onComplete();
    expect(done).toHaveBeenCalledTimes(1);
    expect(seen[seen.length - 1]).toEqual([1, 1]);
  });

  test('sceneTransition fires go() exactly once with no tween manager, and once after the wipe otherwise', () => {
    const go = jest.fn();
    sceneTransition({ registry: sceneWith({ reduceMotion: 'off' }).registry }, go);
    expect(go).toHaveBeenCalledTimes(1);

    let cfg = null;
    const g = { scene: {}, setDepth() { return this; }, clear() {}, fillStyle() {}, fillRect() {} };
    const scene = {
      registry: sceneWith({ reduceMotion: 'off' }).registry,
      tweens: { addCounter: (c) => { cfg = c; return {}; } },
      add: { graphics: () => g },
    };
    const go2 = jest.fn();
    sceneTransition(scene, go2);
    expect(go2).not.toHaveBeenCalled();
    cfg.onUpdate({ getValue: () => 0.5 });
    cfg.onComplete();
    cfg.onStop();
    expect(go2).toHaveBeenCalledTimes(1);
  });

  test('sceneTransition under reduce motion uses a camera fade and still fires once', () => {
    const handlers = {};
    const scene = {
      registry: sceneWith({ reduceMotion: 'on' }).registry,
      cameras: { main: { once: (e, fn) => { handlers[e] = fn; }, fadeOut: jest.fn() } },
      time: { delayedCall: (ms, fn) => { handlers.timer = fn; } },
    };
    const go = jest.fn();
    sceneTransition(scene, go);
    expect(scene.cameras.main.fadeOut).toHaveBeenCalledWith(REDUCED_MS, 0, 0, 0);
    handlers.camerafadeoutcomplete();
    handlers.timer();
    expect(go).toHaveBeenCalledTimes(1);
  });

  test('transitionIn never moves the panel outside the tween and lands exactly on its layout', () => {
    let cfg = null;
    const panel = {
      x: 20, y: 40, alpha: 1, scaleX: 1, scaleY: 1, depth: 500, scene: {},
      setAlpha(a) { this.alpha = a; return this; },
      setScale(x, y) { this.scaleX = x; this.scaleY = y; return this; },
      setPosition(x, y) { this.x = x; this.y = y; return this; },
    };
    const line = { scene: {}, setDepth() { return this; }, clear() {}, fillStyle() {}, fillRect() {}, destroy: jest.fn() };
    const scene = {
      registry: sceneWith({ reduceMotion: 'off' }).registry,
      tweens: { addCounter: (c) => { cfg = c; return {}; } },
      add: { graphics: () => line },
    };
    transitionIn(scene, panel, { w: 200, h: 100 });
    // synchronously: only hidden, geometry untouched
    expect({ x: panel.x, y: panel.y, sy: panel.scaleY, a: panel.alpha }).toEqual({ x: 20, y: 40, sy: 1, a: 0 });
    cfg.onUpdate({ getValue: () => 0.8 });
    expect(panel.scaleY).toBeLessThan(1.2);
    cfg.onComplete();
    expect({ x: panel.x, y: panel.y, sx: panel.scaleX, sy: panel.scaleY, a: panel.alpha }).toEqual({ x: 20, y: 40, sx: 1, sy: 1, a: 1 });
    expect(line.destroy).toHaveBeenCalled();
  });
});import { jest } from '@jest/globals';
import { buildMusicChain, StemFXMixer, MUSIC_PROCESSORS } from '../../src/systems/music/MusicFXGraph.js';

class Param {
	constructor() { this.value = 0; }
	cancelScheduledValues() { return this; }
	setValueAtTime(v) { this.value = v; return this; }
	linearRampToValueAtTime(v) { this.value = v; return this; }
	setTargetAtTime(v) { this.value = v; return this; }
}
class AudioNodeMock {
	constructor(type) {
		this.type = type; this.connections = []; this.closed = false;
		for (const key of ['gain', 'frequency', 'Q', 'pan', 'delayTime']) this[key] = new Param();
		this.fftSize = 512;
	}
	connect(node) { this.connections.push(node); return node; }
	disconnect() { this.connections = []; }
	start() { this.started = true; }
	stop() { this.stopped = true; }
	getByteFrequencyData(array) { array.fill(51); }
}
function fakeContext() {
	const names = ['Gain','BiquadFilter','StereoPanner','WaveShaper','Delay','Oscillator','Convolver','Analyser'];
	const ctx = { sampleRate: 48000, currentTime: 10 };
	for (const name of names) ctx['create' + name] = () => new AudioNodeMock(name);
	ctx.createBuffer = (channels,length) => {
		const data = Array.from({length:channels},()=>new Float32Array(length));
		return {length, getChannelData(ch) {return data[ch];}};
	};
	ctx.createAnalyser = () => {
		const n = new AudioNodeMock('Analyser');
		n.frequencyBinCount = 512;
		return n;
	};
	return ctx;
}
describe('Modular cheap Web Audio processors', () => {
	test('registry includes every planned inexpensive processor family', () => {
