describe('ProfileLayout — signature status reflects what W3 actually ships', () => {
  const BIOMES = readdirSync(path.resolve('src/data/biomes')).filter((f) => f.endsWith('.json'))
    .map((f) => JSON.parse(readFileSync(path.resolve('src/data/biomes', f), 'utf8')));
  const playable = BIOMES.map((b) => b.id);

  test('the W1 "COMING ONLINE" note is gone once signatures exist', () => {
    // Leaving it would tell players their unlocked biomes do nothing, which stopped being true in W3.
    const layout = profileLayout({ profile: maxedProfile(), levels, playableBiomeIds: playable });
    const note = layout.items.find((i) => i.key === 'sig-note');
    expect(note.text).not.toContain('COMING ONLINE');
    expect(note.text).not.toContain('LOCKED');
  });

  test('it counts signatures that are both reached and shipped', () => {
    const layout = profileLayout({ profile: maxedProfile(), levels, playableBiomeIds: playable });
    const note = layout.items.find((i) => i.key === 'sig-note');
    // Maxed profile has reached all 11; W3 ships 5.
    expect(note.text).toBe(`${playable.length} SIGNATURES ONLINE`);
  });

  test('a profile that has earned nothing still has the base biome online (issue #65)', () => {
    const layout = profileLayout({ profile: defaultProfile(), levels, playableBiomeIds: playable });
    const note = layout.items.find((i) => i.key === 'sig-note');
    expect(note.text).toBe('1 SIGNATURE ONLINE');
  });

  test('with no shipped biome content at all, it keeps the original wording', () => {
    // W6-era safety: if content were ever missing, the note must not claim signatures exist.
    const layout = profileLayout({ profile: maxedProfile(), levels, playableBiomeIds: [] });
    expect(layout.items.find((i) => i.key === 'sig-note').text).toBe('SIGNATURE LOCKED - COMING ONLINE');
  });

  test('the note never overlaps the other profile rows in either palette', () => {
    for (const playableIds of [[], playable]) {
      const layout = profileLayout({ profile: maxedProfile(), levels, playableBiomeIds: playableIds });
      expect(overlappingPairs(layout.items)).toEqual([]);
      for (const it of layout.items) expect(it.x + it.w).toBeLessThanOrEqual(PROFILE_PANEL.w);
    }
  });
});

describe('the signature toggle menu cannot cover the biome names', () => {
  // Luna's round-2 finding #4: MenuList was created at y=150 in Views.js while the name rows started
  // at y=146, so the ON/OFF rows drew over the names they belonged to. The band is layout data now.
  // The real view passes content.progression, which is where biomeOrder lives; without it the layout
  // has no names to place and this whole check would pass vacuously.
  // The SHIPPED table, not a two-line stub: loadLevelTable falls back to a biomeOrder-less default for
  // a table under two levels, which would make every assertion here vacuous.
  const levels = JSON.parse(fs.readFileSync(new URL('../../src/data/progression/levels.json', import.meta.url), 'utf8'));
  // Real defs, so the fixture's unlocks track each biome's actual unlockLevel (crystal-cavern is 16,
  // not 12). A hardcoded slice would make the worst case - all five toggle rows - unreachable.
  const BIOME_DEFS = readdirSync(path.resolve('src/data/biomes')).filter((f) => f.endsWith('.json'))
    .map((f) => JSON.parse(readFileSync(path.resolve('src/data/biomes', f), 'utf8')))
    .sort((a, b) => a.bit - b.bit);
  const playable = BIOME_DEFS.map((b) => b.id);
  const withBiomes = (level) => ({
    v: 1, xp: 0, level, bank: 0, biomeMask: 31,
    pendingBiomes: BIOME_DEFS.filter((d) => d.unlockLevel <= level).map((d) => d.id),
    unlocked: { biomes: [], cosmetics: [], boosts: {} },
    missions: { counter: 0, active: [], progress: {} }, achievements: {}, credited: [],
  });

  test('the menu starts below every name row', () => {
    const layout = profileLayout({ profile: withBiomes(12), levels });
    const names = layout.items.filter((it) => it.key.startsWith('sig-') && it.key !== 'sig-head' && it.key !== 'sig-note');
    expect(names.length).toBeGreaterThan(0);
    const lowest = Math.max(...names.map((it) => it.y));
    expect(layout.toggleMenu.y).toBeGreaterThan(lowest);
  });

  test('the menu starts below the last name row in the SHIPPED table', () => {
    // The table lists 11 biomes, so the names occupy four rows. This is the case that actually broke.
    const layout = profileLayout({ profile: withBiomes(12), levels });
    const names = layout.items.filter((it) => /^sig-/.test(it.key) && it.key !== 'sig-head' && it.key !== 'sig-note');
    const lowest = Math.max(...names.map((it) => it.y + it.h));
    expect(layout.toggleMenu.y).toBeGreaterThanOrEqual(lowest);
  });

  test('every toggle row fits inside the panel', () => {
    // Measured against the real shipped table: five unlocked signatures, 11 biomes in the order. The
    // first version passed this with a stub table and still overflowed the panel by 4px in the game,
    // because the names were listed twice - once as plain rows and again as toggle labels.
    // Production inputs (every shipped id is playable): since audit F11 the locked biomes are listed as
    // names too, and without playable ids no toggle row exists at all, so the band would be measured under
    // a name grid the real screen never draws together with toggles.
    const layout = profileLayout({ profile: withBiomes(12), levels, playableBiomeIds: playable });
    const bottom = layout.toggleMenu.y + 5 * layout.toggleMenu.rowH;
    expect(bottom).toBeLessThanOrEqual(PROFILE_PANEL.h);
  });

  test('the last toggle row clears the BACK button', () => {
    // The round-2 fix sized the menu against the PANEL FLOOR, but the panel's bottom strip is occupied
    // by the BACK button (`y: h - 22, h: 16` in the View base class), and `toggleMenu` is returned
    // separately from `items`, so `overlappingPairs(items)` never saw it. With all five signatures
    // unlocked and h=224 the fifth row overlapped the button by 62x3px. This pins the real constraint.
    const VIEW_BACK = { y: PROFILE_PANEL.h - 22, h: 16 };
    for (const level of [1, 4, 7, 10, 13, 16, 29]) {
      const layout = profileLayout({ profile: withBiomes(level), levels, playableBiomeIds: playable });
      const band = layout.toggleMenu;
      const rows = layout.toggleRowCount || 0;
      if (!rows) continue;
      // W6: measured on PHYSICAL rows. With two columns the menu is as tall as its taller column, not as
      // tall as the row count, and measuring the count would fail a layout that is actually correct.
      const physical = layout.togglePhysicalRows !== undefined ? layout.togglePhysicalRows : rows;
      const menuBottom = band.y + physical * band.rowH;
      expect({ level, clear: menuBottom <= VIEW_BACK.y })
        .toEqual({ level, clear: true });
    }
  });

  test('a signature is listed exactly once: either as a pending name or as a toggle', () => {
    const layout = profileLayout({ profile: withBiomes(12), levels, playableBiomeIds: ['debutmont', 'garbage-dump-glacier', 'pyramid-peak', 'underwater-mountain', 'crystal-cavern'] });
    const plain = layout.items.filter((it) => /^sig-/.test(it.key) && it.key !== 'sig-head' && it.key !== 'sig-note').map((it) => it.text);
    // Switchable playable biomes belong in the toggle menu, so none of them should also have a plain name row.
    for (const t of ['GARBAGE DUMP GLACIER', 'PYRAMID PEAK']) {
      expect({ t, listed: plain.includes(t) }).toMatchObject({ t, listed: false });
    }
    // The base biome has no toggle (it cannot be turned off), so it is listed by name, once.
    expect(plain.filter((t) => t === 'DEBUTMONT')).toHaveLength(1);
    // Still-pending ones keep their name so the player can see what is coming.
    expect(plain.length).toBeGreaterThan(0);
  });
});// W1 gates: profile persistence (own key, own version, memory fallback), idempotent crediting,
// backfill from stored runs, and corrupt/future-version tolerance.
import fs from 'fs';
import { defaultProfile, PROFILE_VERSION, rewardsForLevel, levelForXp, xpForRun } from '../../src/systems/Progression.js';
import { ProfileStore, PROFILE_KEY, sanitizeProfile, creditRun, backfillFromRuns } from '../../src/systems/ProfileStore.js';

const levels = () => JSON.parse(fs.readFileSync('src/data/progression/levels.json', 'utf8'));

/** Storage double: real localStorage lives in jsdom, this just lets us break it on purpose. */
function throwingStorage() {
  return {
    getItem() { throw new Error('denied'); },
    setItem() { throw new Error('denied'); },
    removeItem() { throw new Error('denied'); },
  };
}

function rec(over = {}) {
  return {
    id: 'r1', seed: 's', dailyRuleId: 'none', startedAt: 0, endedAt: 1000, durationMs: 60000,
    score: 1000, distanceM: 500, trickPoints: 100, tricks: { backflip: 2 }, bestCombo: 2,
    maxAirtimeMs: 1500, cause: 'crash', ledgerHash: 'h1', shards: 4, nearMisses: 3, ...over,
  };
}

// CC Friday's independent verification of PR #17 (2026-11-13) found that lifetime.bestCombo was being
// rounded to an integer by the sanitizer, while RunRecord.bestCombo is a COMBO MULTIPLIER (SaveStore:
// "highest multiplier", e.g. x1.25). A run showing BEST COMBO x1.25 stored 1, and x2.5 would store 3.
// Missions and achievements read this field, so the loss is not cosmetic.
describe('lifetime floats (CC Friday verification, 2026-11-13)', () => {
  test('bestCombo keeps its fractional multiplier', () => {
    const s = new ProfileStore({ levels: levels() });
    s.credit(rec({ id: 'f1', ledgerHash: 'fh1', bestCombo: 1.25 }));
    expect(s.load().lifetime.bestCombo).toBe(1.25);
    s.credit(rec({ id: 'f2', ledgerHash: 'fh2', bestCombo: 2.5 }));
    expect(s.load().lifetime.bestCombo).toBe(2.5);
    // and it must survive a reload through the sanitizer, which is where the rounding happened
    expect(s.load().lifetime.bestCombo).toBe(2.5);
  });

  test('a fractional bestCombo is not rounded up either (x2.5 is not x3)', () => {
    const s = new ProfileStore({ levels: levels() });
    s.credit(rec({ id: 'f3', ledgerHash: 'fh3', bestCombo: 2.5 }));
    expect(s.load().lifetime.bestCombo).not.toBe(3);
    expect(s.load().lifetime.bestCombo).toBe(2.5);
  });

  test('counters still round: runs, metres, shards and XP stay integers', () => {
    const s = new ProfileStore({ levels: levels() });
    s.credit(rec({ id: 'f4', ledgerHash: 'fh4', distanceM: 500.6, score: 1000.4, shards: 4.5 }));
    const p = s.load();
    expect(Number.isInteger(p.lifetime.runs)).toBe(true);
    expect(Number.isInteger(p.lifetime.distanceM)).toBe(true);
    expect(Number.isInteger(p.lifetime.score)).toBe(true);
    expect(Number.isInteger(p.lifetime.shards)).toBe(true);
    expect(Number.isInteger(p.xp)).toBe(true);
  });

  test('sanitizeProfile rejects junk in float fields without throwing', () => {
    for (const bad of [NaN, Infinity, -5, null, undefined, '1.25', {}, []]) {
      const p = sanitizeProfile({ lifetime: { bestCombo: bad, maxAirtimeMs: bad } });
      expect({ bad: String(bad), bestCombo: p.lifetime.bestCombo }).toMatchObject({
        bestCombo: expect.any(Number),
      });
      expect(p.lifetime.bestCombo).toBeGreaterThanOrEqual(0);
      expect(Number.isFinite(p.lifetime.bestCombo)).toBe(true);
      expect(Number.isFinite(p.lifetime.maxAirtimeMs)).toBe(true);
    }
  });
});

beforeEach(() => localStorage.clear());

describe('own storage key and version', () => {
  test('uses bb.profile, not the settings key', () => {
    expect(PROFILE_KEY).toBe('bb.profile');
    const s = new ProfileStore({ levels: levels() });
    const p = s.load();
    expect(p.v).toBe(PROFILE_VERSION);
    expect(localStorage.getItem('bb.profile')).toContain('"v":1');
    expect(localStorage.getItem('bb.settings')).toBeNull();
  });

  test('round-trips a saved profile without touching STORAGE.saveVersion', () => {
    const T = levels();
    const s = new ProfileStore({ levels: T });
    s.load();
    s.save({ ...s.profile, xp: 500 });
    const s2 = new ProfileStore({ levels: T });
    const p = s2.load();
    expect(p.xp).toBe(500);
    // level is derived from xp against the shipped table, not from a number the caller supplied
    expect(p.level).toBe(levelForXp(500, T));
    expect(p.v).toBe(PROFILE_VERSION);
  });
});

describe('load tolerance', () => {
  test('corrupt JSON loads as a clean default without throwing', () => {
    localStorage.setItem(PROFILE_KEY, '{not json');
    const s = new ProfileStore({ levels: levels() });
    expect(() => s.load()).not.toThrow();
    const p = s.profile;
    expect(p.xp).toBe(0);
    expect(p.level).toBe(1);
  });

  test('a future version loads as a clean default without throwing', () => {
    localStorage.setItem(PROFILE_KEY, JSON.stringify({ v: 99, xp: 123456, level: 30, futureThing: true }));
    const s = new ProfileStore({ levels: levels() });
    const p = s.load();
    expect(p.v).toBe(PROFILE_VERSION);
    expect(p.xp).toBe(0);
    expect(p.futureThing).toBeUndefined();
  });

  test('only an exact numeric v:1 is trusted; every other version is a clean default', () => {
    // Regression: a missing/stringified/array `v` used to be coerced to 1, so another version's
    // bank/xp/credited leaked into v1 state. Only the literal number 1 may be trusted.
    const junk = [
      { xp: 1234, bank: 77 }, // no version at all
      { v: null, xp: 1234 },
      { v: '1', xp: 1234 },
      { v: true, xp: 1234 },
      { v: [1], xp: 1234 },
      { v: { n: 1 }, xp: 1234 },
      { v: 0, xp: 1234 },
      { v: 2, xp: 1234 },
      { v: 1.5, xp: 1234 },
    ];
    for (const body of junk) {
      localStorage.setItem(PROFILE_KEY, JSON.stringify(body));
      const p = new ProfileStore({ levels: levels() }).load();
      expect([body.v, p.v, p.xp, p.bank]).toEqual([body.v, PROFILE_VERSION, 0, 0]);
    }
    // ...and the exact number 1 is still trusted.
    localStorage.setItem(PROFILE_KEY, JSON.stringify({ v: 1, xp: 1234 }));
    expect(new ProfileStore({ levels: levels() }).load().xp).toBe(1234);
  });

  test('an array body loads as a clean default', () => {
    localStorage.setItem(PROFILE_KEY, '[1,2,3]');
    const p = new ProfileStore({ levels: levels() }).load();
    expect(p.xp).toBe(0);
    expect(p.level).toBe(1);
    expect(p.credited).toEqual([]);
  });

  test('missing/blank value loads as a clean default', () => {
    for (const v of [null, '', 'null', '{}']) {
      if (v === null) localStorage.removeItem(PROFILE_KEY); else localStorage.setItem(PROFILE_KEY, v);
      const p = new ProfileStore({ levels: levels() }).load();
      expect(p.level).toBe(1);
      expect(p.credited).toEqual([]);
    }
  });

  test('does not throw when storage itself throws (private mode)', () => {
    const s = new ProfileStore({ levels: levels(), storage: throwingStorage() });
    expect(() => s.load()).not.toThrow();
    expect(() => s.save(s.profile)).not.toThrow();
    expect(s.profile.level).toBe(1);
  });

  test('does not throw when reading the global localStorage getter throws', () => {
    const descriptor = Object.getOwnPropertyDescriptor(globalThis, 'localStorage');
    Object.defineProperty(globalThis, 'localStorage', { configurable: true, get: () => { throw new Error('denied'); } });
    try {
      const s = new ProfileStore({ levels: levels() });
      expect(() => s.load()).not.toThrow();
      expect(s.profile.level).toBe(1);
    } finally {
      if (descriptor) Object.defineProperty(globalThis, 'localStorage', descriptor);
      else delete globalThis.localStorage;
    }
  });
});

describe('sanitizeProfile', () => {
  test('repairs junk fields and keeps the shape complete', () => {
    const p = sanitizeProfile({
      v: 1, xp: 'lots', level: 999, bank: -5,
      lifetime: { runs: -1, tricks: { spin: 'x', flip: 3 }, shards: 2 },
      unlocked: { biomes: ['a', 5, 'a'], cosmetics: 'nope', boosts: { b: 1 } },
      credited: ['h1', 'h1', 7, 'h2'],
      missions: null, achievements: null,
    }, levels());
    expect(Number.isFinite(p.xp)).toBe(true);
    expect(p.xp).toBe(0);
    expect(p.bank).toBe(0);
    expect(p.lifetime.runs).toBe(0);
    expect(p.lifetime.tricks).toEqual({ flip: 3 });
    expect(p.unlocked.biomes).toEqual(['a']);
    expect(p.unlocked.cosmetics).toEqual([]);
    expect(p.unlocked.boosts).toEqual({ b: 1 });
    expect(p.credited).toEqual(['h1', 'h2']);
    expect(p.missions).toEqual({ counter: 0, active: [], progress: {} });
    expect(p.achievements).toEqual({});
  });

  test('recomputes level from xp so a stale level field cannot lie', () => {
    const T = levels();
    const xp = T.levels[3].xpMin; // exactly the 4th level's threshold
    const p = sanitizeProfile({ v: 1, xp, level: 1 }, T);
    expect(p.level).toBe(4);
    // and the stale field is genuinely ignored in the other direction too
    expect(sanitizeProfile({ v: 1, xp: 0, level: 9 }, T).level).toBe(1);
  });

  test('caps the credited ring so a long-lived profile cannot grow forever', () => {
    const many = Array.from({ length: 900 }, (_, i) => `h${i}`);
    const p = sanitizeProfile({ v: 1, credited: many }, levels());
    expect(p.credited.length).toBeLessThanOrEqual(500);
    expect(p.credited[p.credited.length - 1]).toBe('h899');
  });

  test('a fresh profile and a reloaded profile have the identical shape', () => {
    // Regression: derived fields were only attached on the trusted path, so the very first profile
    // (a plain default) lacked them while every later load had them. Anything reading `pendingBiomes`
    // saw `undefined` on a brand-new install. Every path must return the same shape.
    const fresh = new ProfileStore({ levels: levels() }).load();
    const reloaded = new ProfileStore({ levels: levels() }).load();
    expect(JSON.stringify(reloaded)).toBe(JSON.stringify(fresh));
    expect(Object.keys(reloaded).sort()).toEqual(Object.keys(fresh).sort());
    expect(fresh.pendingBiomes).toEqual(['debutmont']); // the base biome (level 1)
    expect(sanitizeProfile(defaultProfile(), levels())).toEqual(fresh);
  });

  test('sanitizeProfile is idempotent (a round trip never changes the profile)', () => {
    const once = sanitizeProfile({ v: 1, xp: 700, credited: ['a', 'b'], achievements: { x: 1 } }, levels());
    expect(sanitizeProfile(once, levels())).toEqual(once);
  });
});

describe('creditRun idempotency', () => {
  test('crediting the same record twice changes nothing and awards XP once', () => {
    const s = new ProfileStore({ levels: levels() });
    s.load();
    const r = rec();
    const a1 = s.credit(r);
    const snap = JSON.stringify(s.profile);
    const a2 = s.credit(r);
    expect(a2).toBeNull();
    expect(JSON.stringify(s.profile)).toBe(snap);
    expect(a1.xp.total).toBeGreaterThan(0);
    expect(s.profile.xp).toBe(a1.xp.total);
    expect(s.profile.lifetime.runs).toBe(1);
  });

  test('a different run is credited normally and accumulates lifetime totals', () => {
    const s = new ProfileStore({ levels: levels() });
    s.load();
    s.credit(rec({ id: 'a', ledgerHash: 'h1', distanceM: 100 }));
    s.credit(rec({ id: 'b', ledgerHash: 'h2', distanceM: 300, score: 5000 }));
    expect(s.profile.lifetime.runs).toBe(2);
    expect(s.profile.lifetime.distanceM).toBe(400);
    expect(s.profile.lifetime.bestScore).toBe(5000);
    expect(s.profile.lifetime.bestDistanceM).toBe(300);
  });

  test('a record with no ledgerHash falls back to its id (still credited once)', () => {
    const s = new ProfileStore({ levels: levels() });
    s.load();
    const r = rec({ ledgerHash: '', id: 'only-id' });
    expect(s.credit(r)).toBeTruthy();
    expect(s.credit(rec({ ledgerHash: '', id: 'only-id' }))).toBeNull();
  });

  test('reports a level-up with the rewards it granted', () => {
    const s = new ProfileStore({ levels: levels() });
    s.load();
    const awards = s.credit(rec({ distanceM: 8000, score: 20000, tricks: { a: 20 }, shards: 40 }));
    expect(awards.leveledTo).toBeGreaterThan(1);
    expect(awards.rewards.title).toBeTruthy();
    expect(awards.rewardsEarned.map((reward) => reward.level)).toEqual(
      Array.from({ length: awards.leveledTo }, (_, i) => i + 1).slice(1),
    );
    expect(s.profile.unlocked.cosmetics).toContain('trail-cyan');
    expect(s.profile.level).toBe(awards.leveledTo);
  });
});

describe('backfillFromRuns', () => {
  test('fills lifetime totals and XP once from existing stored runs', () => {
    const s = new ProfileStore({ levels: levels() });
    s.load();
    const runs = [rec({ id: 'a', ledgerHash: 'h1', distanceM: 200, score: 400 }), rec({ id: 'b', ledgerHash: 'h2', distanceM: 300, score: 600 })];
    const before = s.profile.xp;
    expect(before).toBe(0);
    s.backfill(runs);
    expect(s.profile.lifetime.runs).toBe(2);
    expect(s.profile.lifetime.distanceM).toBe(500);
    expect(s.profile.lifetime.score).toBe(1000);
    expect(s.profile.xp).toBeGreaterThan(0);
    expect(s.profile.credited).toEqual(['h1', 'h2']);
    const xpAfter = s.profile.xp;
    // Backfill is once only: a second call with the same runs adds nothing.
    s.backfill(runs);
    expect(s.profile.xp).toBe(xpAfter);
    expect(s.profile.lifetime.runs).toBe(2);
  });

  test('does nothing for a profile that already has runs', () => {
    const s = new ProfileStore({ levels: levels() });
    s.load();
    s.credit(rec({ id: 'x', ledgerHash: 'hx' }));
    const snap = JSON.stringify(s.profile);
    s.backfill([rec({ id: 'a', ledgerHash: 'h1' })]);
    expect(JSON.stringify(s.profile)).toBe(snap);
  });

  test('backfill is pure-helper friendly and ignores junk entries', () => {
    const out = backfillFromRuns(defaultProfile(), [rec({ ledgerHash: 'h1' }), null, {}, rec({ id: 'z', ledgerHash: '' })], levels());
    expect(out.lifetime.runs).toBe(2);
    expect(out.xp).toBeGreaterThan(0);
  });

  test('produces the expected totals for a known fixture', () => {
    const runs = [
      rec({ id: 'a', ledgerHash: 'f1', distanceM: 100, score: 100, tricks: { t: 1 }, shards: 0, nearMisses: 0, maxAirtimeMs: 0 }),
      rec({ id: 'b', ledgerHash: 'f2', distanceM: 200, score: 200, tricks: { t: 2 }, shards: 2, nearMisses: 1, maxAirtimeMs: 2500 }),
    ];
    const s = new ProfileStore({ levels: levels() });
    s.load();
    s.backfill(runs);
    // distance 10 + 20, score 2 + 4, tricks 12 + 24, shards 0 + 10, near 0 + 2, airtime 0 + 1
    expect(s.profile.xp).toBe(85);
    expect(s.profile.lifetime.tricks).toEqual({ t: 3 });
    expect(s.profile.lifetime.shards).toBe(2);
    expect(s.profile.lifetime.maxAirtimeMs).toBe(2500);
  });
});

describe('biome rewards in W1 are listed but locked', () => {
  test('unlocked.biomes stays empty until W3/W6 ship the biomes', () => {
    const T = levels();
    const s = new ProfileStore({ levels: T });
    s.load();
    // Enough XP to reach the first biome's level, whatever the current curve is.
    const firstBiome = T.levels.find((l) => l.biome && l.level > 1); // the base biome is level 1
    const need = firstBiome.xpMin;
    let total = 0;
    for (let i = 0; i < 40 && total < need; i++) {
      const r = rec({ id: `b${i}`, ledgerHash: `hb${i}`, distanceM: 9000, score: 24000, tricks: { a: 20 }, shards: 40 });
      total += xpForRun(r).total;
      s.credit(r);
    }
    expect(s.profile.level).toBeGreaterThanOrEqual(firstBiome.level);
    // The biome is LISTED (so the UI can show "coming online") but NOT unlocked yet.
    expect(s.profile.unlocked.biomes).toEqual([]);
    expect(s.profile.pendingBiomes).toContain(firstBiome.biome);
  });
});/**
 * Progression crediting fixes from the post-sprint audit (BF-1 backfill order, LVL-1 mission-XP level-ups,
 * ACH-3 daily/streak achievements). Real ProfileStore / ProgressionService with the shipped level table.
 */
import fs from 'fs';
import path from 'path';

import {
  ProfileStore, sanitizeProfile, backfillFromRuns, CREDITED_MAX,
} from '../../src/systems/ProfileStore.js';
import { ProgressionService } from '../../src/systems/ProgressionService.js';
import { MissionsService } from '../../src/systems/MissionsService.js';
import { rollSet } from '../../src/systems/Missions.js';
import { REG } from '../../src/constants.js';
import { EVT } from '../../src/events.js';
import { DailyPatch } from '../../src/systems/DailyPatch.js';

// Decisions 1/2: only an OFFICIAL Daily run (started from the DAILY RUN item: a v2 record with
// dailyOfficial, on the date's own rule and mask) counts as a Daily run. These fixtures used to be any run
// on a daily seed; they are stamped official so the Daily achievements they test are still reached.
const off = (k) => {
  const info = DailyPatch.infoForDateKey(k);
  return { seed: `daily-${k}`, hashV: 2, dailyOfficial: true, dailyRuleId: info.rule.id, ...(info.biomeMask ? { biomeMask: info.biomeMask } : {}) };
};


const read = (p) => JSON.parse(fs.readFileSync(p, 'utf8'));
const LEVELS = read('src/data/progression/levels.json');
const MISSIONS = read('src/data/missions/missions.json');
const BIOME_DEFS = fs.readdirSync('src/data/biomes').filter((f) => f.endsWith('.json'))
  .map((f) => read(path.join('src/data/biomes', f)));
const MAX_XP = LEVELS.levels[LEVELS.levels.length - 1].xpMin + 1;

const memStorage = () => {
  const m = new Map();
  return {
    getItem: (k) => (m.has(k) ? m.get(k) : null),
    setItem: (k, v) => m.set(k, String(v)),
    removeItem: (k) => m.delete(k),
  };
};

function fakeGame() {
  const reg = new Map();
  const handlers = new Map();
  return {
    registry: { get: (k) => reg.get(k), set: (k, v) => reg.set(k, v) },
    events: {
      on: (n, fn) => { if (!handlers.has(n)) handlers.set(n, new Set()); handlers.get(n).add(fn); },
      off: (n, fn) => { handlers.get(n)?.delete(fn); },
      once: () => {},
      emit: (n, p) => { for (const fn of [...(handlers.get(n) || [])]) fn(p); },
    },
  };
}

const rec = (o = {}) => ({
  version: 1, id: 'run-1', seed: 's', dailyRuleId: 'none', startedAt: 0, endedAt: 1000, durationMs: 60000,
  score: 0, distanceM: 0, trickPoints: 0, tricks: {}, bestCombo: 1, maxAirtimeMs: 0, cause: 'crash',
  ledgerHash: 'h1', shards: 0, nearMisses: 0, ...o,
});

const v1 = (o = {}) => sanitizeProfile({ v: 1, ...o }, LEVELS);

/** Boot progression + missions the way services.js does, on the given storage. */
async function boot(storage, saveStore) {
  const game = fakeGame();
  if (saveStore) game.registry.set(REG.SAVE_STORE, saveStore);
  const store = new ProfileStore({ levels: LEVELS, storage });
  const progression = new ProgressionService(game, { levels: LEVELS, store });
  await progression.init();
  const missions = new MissionsService(game, {
    templates: MISSIONS.templates, tierUnlock: MISSIONS.tierUnlock, biomeDefs: BIOME_DEFS, store,
  });
  await missions.init();
  progression.missions = missions;
  return { game, store, progression, missions };
}

describe('BF-1: backfill credits runs oldest first', () => {
  // SaveStore.getRecentRuns returns newest first, and ProgressionService passes that order through.
  const runs = [rec({ id: 'new', ledgerHash: 'n', endedAt: 3000 }), rec({ id: 'mid', ledgerHash: 'm', endedAt: 2000 }), rec({ id: 'old', ledgerHash: 'o', endedAt: 1000 })];

  test('First Descent is stamped with the OLDEST run, not the newest', () => {
    const p = backfillFromRuns(v1(), runs, LEVELS);
    expect(p.achievements['first-descent']).toBe(1000);
  });

  test('the credited ring ends with the newest hash, so the ring keeps the newest runs when it overflows', () => {
    const p = backfillFromRuns(v1(), runs, LEVELS);
    expect(p.credited).toEqual(['o', 'm', 'n']);
    const many = [];
    for (let i = CREDITED_MAX + 5; i >= 1; i--) many.push(rec({ id: `r${i}`, ledgerHash: `h${i}`, endedAt: i }));
    const q = backfillFromRuns(v1(), many, LEVELS);
    expect(q.credited.length).toBe(CREDITED_MAX);
    expect(q.credited[q.credited.length - 1]).toBe(`h${CREDITED_MAX + 5}`);
    expect(q.credited).not.toContain('h1');
  });

  test('the input array is not reordered', () => {
    const copy = runs.slice();
    backfillFromRuns(v1(), copy, LEVELS);
    expect(copy.map((r) => r.id)).toEqual(['new', 'mid', 'old']);
  });
});

describe('LVL-1: a level crossed by mission XP is announced like one crossed by run XP', () => {
  function serviceWithMissionXp(missionXp) {
    const game = fakeGame();
    const store = new ProfileStore({ levels: LEVELS, storage: memStorage() });
    const svc = new ProgressionService(game, {
      levels: LEVELS, store,
      missions: {
        onRunCredited: () => {
          store.applyMissions({ active: [], counter: 1, progress: {}, xp: missionXp, shards: 0 });
          return { completed: missionXp ? [{ id: 'm' }] : [], xp: missionXp, shards: 0 };
        },
      },
    });
    return { game, store, svc };
  }

  test('a level crossed by mission XP is announced on Game Over with its reward', async () => {
    const { game, store, svc } = serviceWithMissionXp(60);
    await svc.init();
    // 500 m = 50 XP; 50 + 60 mission XP = 110 >= 100 (Sync Level 2).
    game.events.emit(EVT.RUN_END, { record: rec({ distanceM: 500 }) });
    const view = game.registry.get(REG.LAST_AWARDS);
    expect(store.profile.level).toBe(2);
    expect(view.progress.level).toBe(2);
    expect({ levelBefore: view.levelBefore, levelAfter: view.levelAfter, leveledTo: view.leveledTo, rewards: view.rewardsEarned.map((r) => r.cosmetic) })
      .toEqual({ levelBefore: 1, levelAfter: 2, leveledTo: 2, rewards: ['trail-cyan'] });
    expect(view.rewards).toMatchObject({ cosmetic: 'trail-cyan' });
    expect(view.earnedCosmetics).toEqual(['trail-cyan']);
  });

  test('run XP and mission XP crossing two levels list both rewards', async () => {
    const { game, svc } = serviceWithMissionXp(1150);
    await svc.init();
    // 1000 m = 100 XP (level 2), + 1150 mission XP = 1250: past level 3's threshold as well.
    game.events.emit(EVT.RUN_END, { record: rec({ distanceM: 1000 }) });
    const view = game.registry.get(REG.LAST_AWARDS);
    const lv3 = LEVELS.levels[2];
    expect(1250 >= lv3.xpMin).toBe(true);
    expect(view.leveledTo).toBe(3);
    expect(view.rewardsEarned.map((r) => r.level)).toEqual([2, 3]);
  });

  test('a run with no level-up and no mission XP still reports no level-up', async () => {
    const { game, svc } = serviceWithMissionXp(0);
    await svc.init();
    game.events.emit(EVT.RUN_END, { record: rec({ distanceM: 100 }) });
    const view = game.registry.get(REG.LAST_AWARDS);
    expect({ leveledTo: view.leveledTo, rewards: view.rewards, earned: view.rewardsEarned }).toEqual({ leveledTo: 0, rewards: null, earned: [] });
  });
});

describe('ACH-3 (daily and streak half): ProgressionService passes the SaveStore streak to the credit', () => {
  async function runWith(saveStore, record) {
    const game = fakeGame();
    game.registry.set(REG.SAVE_STORE, saveStore);
    const store = new ProfileStore({ levels: LEVELS, storage: memStorage() });
    // lifetime.runs > 0 so init skips the backfill and the fake needs no getRecentRuns.
    store.save(v1({ lifetime: { runs: 1 } }));
    const svc = new ProgressionService(game, { levels: LEVELS, store, now: () => Date.parse('2026-11-13T12:00:00Z') });
    await svc.init();
    game.events.emit(EVT.RUN_END, { record });
    return { view: game.registry.get(REG.LAST_AWARDS), store };
  }

  test('a 3-day streak in SaveStore unlocks Three in a Row on the run that makes it', async () => {
    const asked = [];
    const saveStore = { getDailyStreak: (now) => { asked.push(now); return { streak: 3, playedToday: true }; } };
    const { view, store } = await runWith(saveStore, rec({ ...off('2026-11-13') }));
    expect(view.achievements.map((a) => a.id)).toEqual(expect.arrayContaining(['daily-1', 'streak-3']));
    expect(store.profile.lifetime.bestStreak).toBe(3);
    expect(asked).toEqual([Date.parse('2026-11-13T12:00:00Z')]);
  });

  test('a SaveStore that throws or lacks getDailyStreak never blocks the credit', async () => {
    for (const saveStore of [{ getDailyStreak: () => { throw new Error('x'); } }, {}]) {
      const { view } = await runWith(saveStore, rec({ ...off('2026-11-13') }));
      expect(view.credited).toBe(true);
      expect(view.achievements.map((a) => a.id)).toContain('daily-1');
    }
  });
});// W1 gates: XP awards, Sync Level thresholds, rewards — all data-driven from levels.json.
import fs from 'fs';
import path from 'path';
import {
  xpForRun, levelForXp, xpToNext, rewardsForLevel, loadLevelTable, defaultProfile, PROFILE_VERSION,
} from '../../src/systems/Progression.js';

const levelsPath = path.resolve('src/data/progression/levels.json');
const TABLE = JSON.parse(fs.readFileSync(levelsPath, 'utf8'));

/** @returns {Object} a minimal RunRecord. */
function rec(over = {}) {
  return {
    id: 'r1', seed: 's', dailyRuleId: 'none', startedAt: 0, endedAt: 1000, durationMs: 60000,
    score: 1000, distanceM: 500, trickPoints: 100, tricks: { backflip: 2, spin: 1 },
    bestCombo: 2, maxAirtimeMs: 1500, cause: 'crash', ledgerHash: 'abcd1234', shards: 4, nearMisses: 3,
    ...over,
  };
}

describe('levels.json data', () => {
  test('cap matches the last entry and the 11 biomes unlock in the spec order', () => {
    expect(TABLE.cap).toBe(30);
    expect(TABLE.levels[TABLE.levels.length - 1].level).toBe(TABLE.cap);
    const biomes = TABLE.levels.map((l) => l.biome).filter(Boolean);
    expect(biomes).toEqual(TABLE.biomeOrder);
    expect(biomes).toHaveLength(11);
  });

  test('thresholds are strictly increasing and level 1 is free', () => {
    expect(TABLE.levels[0].xpMin).toBe(0);
    for (let i = 1; i < TABLE.levels.length; i++) {
      expect(TABLE.levels[i].xpMin).toBeGreaterThan(TABLE.levels[i - 1].xpMin);
    }
  });

  test('all 11 biomes unlock by the cap', () => {
    const atCap = rewardsForLevel(TABLE.cap, TABLE);
    const unlocked = [];
    for (let l = 1; l <= TABLE.cap; l++) {
      const b = rewardsForLevel(l, TABLE).biome;
      if (b) unlocked.push(b);
    }
    expect(unlocked).toEqual(TABLE.biomeOrder);
    expect(atCap).toBeTruthy();
  });
});

describe('loadLevelTable', () => {
  test('returns the same shape when handed the raw JSON', () => {
    const t = loadLevelTable(TABLE);
    expect(t.cap).toBe(30);
    expect(t.levels).toHaveLength(30);
  });

  test('falls back to a sane default when handed garbage', () => {
    const t = loadLevelTable(null);
    expect(t.levels.length).toBeGreaterThan(1);
    expect(t.cap).toBe(t.levels[t.levels.length - 1].level);
  });

  test('the fallback table agrees with the shipped table on every level it covers', () => {
    // The fallback is only used if levels.json is missing or unusable, so it is easy to forget when
    // retuning — and a stale fallback would silently ship a different early curve in exactly the
    // broken-deploy case where nobody is watching. Assert it cannot drift.
    const fb = loadLevelTable(null);
    for (const l of fb.levels) {
      const shipped = TABLE.levels.find((s) => s.level === l.level);
      expect(shipped).toBeDefined();
      expect(l.xpMin).toBe(shipped.xpMin);
      expect(l.title).toBe(shipped.title);
      expect(l.cosmetic ?? null).toBe(shipped.cosmetic ?? null);
    }
  });
});

describe('xpForRun', () => {
  test('awards distance, tricks, shards and near-misses as separate parts', () => {
    const a = xpForRun(rec());
    expect(a.total).toBeGreaterThan(0);
    const keys = a.parts.map((p) => p.key);
    expect(keys).toEqual(expect.arrayContaining(['distance', 'tricks', 'shards', 'nearMisses']));
    const sum = a.parts.reduce((s, p) => s + p.xp, 0);
    expect(a.total).toBe(sum);
  });

  test('monotonic in distance and score', () => {
    const base = xpForRun(rec());
    const farther = xpForRun(rec({ distanceM: 900 }));
    const better = xpForRun(rec({ score: 4000 }));
    expect(farther.total).toBeGreaterThan(base.total);
    expect(better.total).toBeGreaterThan(base.total);
  });

  test('is pure: same record twice gives identical results and does not mutate the record', () => {
    const r = rec();
    const snapshot = JSON.stringify(r);
    expect(xpForRun(r)).toEqual(xpForRun(r));
    expect(JSON.stringify(r)).toBe(snapshot);
  });

  test('survives a junk/empty record without throwing', () => {
    for (const bad of [null, undefined, {}, { distanceM: -5, score: 'nope', tricks: null }]) {
      const a = xpForRun(bad);
      expect(Number.isFinite(a.total)).toBe(true);
      expect(a.total).toBeGreaterThanOrEqual(0);
    }
  });

  test('daily runs earn the same XP as normal runs (no hidden multiplier)', () => {
    const a = xpForRun(rec({ dailyRuleId: 'tuckBoost' }));
    const b = xpForRun(rec({ dailyRuleId: 'none' }));
    expect(a.total).toBe(b.total);
  });
});

describe('levelForXp / xpToNext', () => {
  test('0 XP is level 1 and the cap is respected', () => {
    expect(levelForXp(0, TABLE)).toBe(1);
    expect(levelForXp(-100, TABLE)).toBe(1);
    expect(levelForXp(10 ** 9, TABLE)).toBe(TABLE.cap);
  });

  test('crossing a threshold raises the level by exactly one', () => {
    const l2 = TABLE.levels[1].xpMin;
    expect(levelForXp(l2 - 1, TABLE)).toBe(1);
    expect(levelForXp(l2, TABLE)).toBe(2);
  });

  test('xpToNext is the remaining XP, 0 at the cap, never negative', () => {
    expect(xpToNext(0, TABLE)).toBe(TABLE.levels[1].xpMin);
    expect(xpToNext(TABLE.levels[TABLE.cap - 1].xpMin, TABLE)).toBe(0);
    expect(xpToNext(10 ** 9, TABLE)).toBe(0);
    for (let l = 1; l < TABLE.cap; l++) {
      expect(xpToNext(TABLE.levels[l - 1].xpMin, TABLE)).toBeGreaterThan(0);
    }
  });
});

describe('tuning targets (D-C: state the numbers)', () => {
  // These assertions run against MEASURED play, not a hand-built record: tests/fixtures/pacing-handsOff.json
  // is the real output of `node tools/sim/pacing.mjs --policy handsOff --seeds 24`, i.e. an untrained player
  // who does nothing but steer. That is the honest benchmark for "a new player" — the hop policy is a
  // competent player and flatters the curve.
  //
  // Regenerate the fixture (and re-check these numbers) if the XP feeds, scoring, or physics change:
  //   node tools/sim/pacing.mjs --policy handsOff --seeds 24
  const FIXTURE = JSON.parse(fs.readFileSync('tests/fixtures/pacing-handsOff.json', 'utf8'));
  const asRecord = (r) => ({ distanceM: r.distM, durationMs: Math.round(r.simSec * 1000), score: r.score,
    tricks: {}, shards: 0, nearMisses: 0, maxAirtimeMs: r.maxAirtimeMs });

  test('level 2 arrives within the first 3 runs of a new player', () => {
    // Play the measured runs in order and check the level reached by run 3.
    let xp = 0;
    for (let i = 0; i < 3; i++) xp += xpForRun(asRecord(FIXTURE.runs[i])).total;
    expect(levelForXp(xp, TABLE)).toBeGreaterThanOrEqual(2);
  });

  test('level 2 is not so cheap that the first run always grants it', () => {
    // The other half of the target: reaching level 2 should still be a small achievement, not automatic.
    const weakest = Math.min(...FIXTURE.runs.map((r) => xpForRun(asRecord(r)).total));
    expect(TABLE.levels[1].xpMin).toBeGreaterThan(weakest);
  });

  test('the base biome is granted at level 1; the first EARNED biome lands within 14-28 minutes of measured play', () => {
    // Issue #65: Debutmont (the old level-4 reward) is now the base biome, granted at level 1. The first biome a
    // player earns is Garbage Dump Glacier, which takes over the old level-4 slot and the original pacing band.
    expect(TABLE.levels[0].biome).toBe('debutmont');
    const firstBiome = TABLE.levels.find((l) => l.biome && l.level > 1);
    expect(firstBiome.biome).toBe('garbage-dump-glacier');
    expect(firstBiome.level).toBe(4);
    // Replay the measured runs until the first biome's threshold is crossed; count real seconds.
    let xp = 0;
    let ms = 0;
    let i = 0;
    while (xp < firstBiome.xpMin && i < 10000) {
      const rec2 = asRecord(FIXTURE.runs[i % FIXTURE.runs.length]);
      xp += xpForRun(rec2).total;
      ms += rec2.durationMs;
      i += 1;
    }
    const minutes = ms / 60000;
    expect(minutes).toBeGreaterThanOrEqual(14);
    expect(minutes).toBeLessThanOrEqual(28);
  });

  test('the curve keeps rising and all 11 biomes arrive by the cap', () => {
    for (let i = 1; i < TABLE.levels.length; i++) {
      expect(TABLE.levels[i].xpMin).toBeGreaterThan(TABLE.levels[i - 1].xpMin);
    }
    const biomes = TABLE.levels.filter((l) => l.biome);
    expect(biomes).toHaveLength(TABLE.biomeOrder.length);
    expect(biomes[biomes.length - 1].level).toBeLessThanOrEqual(TABLE.cap);
    // A cap that takes 100+ hours is not a cap, it is a wall.
    const totalMs = FIXTURE.runs.reduce((a, r) => a + Math.round(r.simSec * 1000), 0);
    const xpPerMin = FIXTURE.runs.reduce((a, r) => a + xpForRun(asRecord(r)).total, 0) / (totalMs / 60000);
    expect(TABLE.levels[TABLE.cap - 1].xpMin / xpPerMin / 60).toBeLessThanOrEqual(40);
  });
});

describe('rewardsForLevel', () => {
  test('returns title plus the biome/cosmetic/boost that level grants', () => {
    const l4 = rewardsForLevel(4, TABLE);
    expect(l4.title).toBe('Frame Pusher');
    // Issue #65: level 4 grants the first earned biome (Debutmont, the old level-4 reward, is the base biome at level 1).
    expect(l4.biome).toBe('garbage-dump-glacier');
    const l1 = rewardsForLevel(1, TABLE);
    expect(l1.biome).toBe('debutmont');
  });

  test('clamps out-of-range levels instead of throwing', () => {
    expect(rewardsForLevel(0, TABLE)).toEqual(rewardsForLevel(1, TABLE));
    expect(rewardsForLevel(999, TABLE)).toEqual(rewardsForLevel(TABLE.cap, TABLE));
    expect(rewardsForLevel('x', TABLE)).toEqual(rewardsForLevel(1, TABLE));
  });
});

