test('private diagnostic reports the failure class without assertion values', () => {
  const tape = { endTick: 2, checkpoints: [[2]] };
  const baseline = { tick: 2, checked: 1, crashed: false, droppedMs: 0, savedRecord: false, desync: null,
    states: [[1, 0], [2, 0]], grounded: [true, false], pageInfo: { gameEntry: 'private-local-path' } };
  for (const [result, expected] of [
    [{ ...baseline, desync: { tick: 2, got: [12345.625], want: [67.25] } }, 'Existing tape checkpoint desynced'],
    [{ ...baseline, states: [[1, 12345.625], [2, 0]] }, 'Replay divergence in trial 2 at tick 1'],
    [{ ...baseline, pageInfo: { gameEntry: 'other-local-path' } }, 'Browser or game entry changed during airtime checks'],
  ]) {
    expect(() => assertPrivateAirtimeChecks(result, tape, baseline, 2)).toThrow(new Error(expected));
  }
});

function observedGame() {
  let reads = 0;
  const run = {
    sled: { body: { position: { x: 0, y: 0 }, velocity: { x: 0, y: 0 }, angle: 0, angularVelocity: 0 },
      get grounded() { reads++; return run.simClock.tick % 2 === 1; } },
    simClock: new SimClock(), score: { getTotal: () => 0 }, runRandom: { physicsScramble: { state: 42 } },
    tapePlayer: { desync: null, checked: 0 },
  };
  return { reads: () => reads, game: { registry: { get: () => null }, scene: { getScene: () => run },
    step() { run.simClock.tick++; run.crashed = run.simClock.tick === 4; } } };
}

test('grounded is read once per completed tick, never on the fatal tick or the ordinary benchmark', () => {
  const strict = observedGame(), ordinary = observedGame();
  const read = (fixture, observeGrounded) => replayFrames({ tickLimit: 8, measure: false, keys: replayKeys, observeGrounded }, fixture.game);
  const result = read(strict, true);
  expect(result.grounded).toEqual([true, false, true]);
  expect(strict.reads()).toBe(3);
  expect(read(ordinary, false)).not.toHaveProperty('grounded');
  expect(ordinary.reads()).toBe(0);
  expect(() => assertReplay(result, { checkpoints: [] }, 8, true)).toThrow(/without crashing/);
});

test('only explicit opt-in with one bounded local file accepts analytics, with no raw path on intake failure', () => {
  const pin = 'a'.repeat(40);
  expect(airtimeBuildPin(pin.toUpperCase())).toBe(pin);
  const base = ['tools/sim/benchmark-replay.mjs', '--airtime-build', pin];
  const launch = (...args) => spawnSync(process.execPath, [...base, ...args], { encoding: 'utf8' });
  const tmp = mkdtempSync(join(tmpdir(), 'bb-replay-airtime-'));
  const tape = join(tmp, 'private.json');
  try {
    expect(launch()).toMatchObject({ status: 1, stdout: '', stderr: expect.stringContaining('explicit saved') });
    expect(launch('--tape', tape, '--ticks', '245')).toMatchObject({ status: 1, stdout: '', stderr: expect.stringContaining('does not accept --ticks') });
    expect(launch('--tape', tape, '--repeats', '1')).toMatchObject({ status: 1, stdout: '', stderr: expect.stringContaining('2–5 fresh runs') });
    expect(launch('--tape', tape).stderr).not.toContain(tmp);
    writeFileSync(tape, Buffer.alloc(MAX_AIRTIME_FILE_BYTES + 1));
    expect(launch('--tape', tape)).toMatchObject({ status: 1, stdout: '', stderr: expect.stringContaining('exceeds 2 MiB') });
    writeFileSync(tape, Buffer.from([255]));
    expect(launch('--tape', tape)).toMatchObject({ status: 1, stdout: '', stderr: expect.stringContaining('UTF-8 JSON') });
  } finally { rmSync(tmp, { force: true, recursive: true }); }
});import { Rng, xxHash32, hashInts } from '../../src/systems/Rng.js';

describe('xxHash32', () => {
  test('matches reference vectors', () => {
    expect(xxHash32('')).toBe(0x02cc5d05);
    expect(xxHash32('a')).toBe(0x550d7456);
    expect(xxHash32('abc')).toBe(0x32d153ff);
    expect(xxHash32('Nobody inspects the spammish repetition')).toBe(0xe2293b2f);
  });

  test('seed parameter changes the hash and result is unsigned 32-bit', () => {
    const a = xxHash32('bitstream', 0);
    const b = xxHash32('bitstream', 1);
    expect(a).not.toBe(b);
    for (const v of [a, b]) {
      expect(Number.isInteger(v)).toBe(true);
      expect(v).toBeGreaterThanOrEqual(0);
      expect(v).toBeLessThan(2 ** 32);
    }
  });

  test('handles long and non-ASCII input deterministically', () => {
    const s = 'sled-é中🚀-'.repeat(20);
    expect(xxHash32(s)).toBe(xxHash32(s));
    expect(xxHash32(s)).not.toBe(xxHash32(s + 'x'));
  });

  test('hashInts is deterministic and scrambles', () => {
    expect(hashInts(1, 2)).toBe(hashInts(1, 2));
    expect(hashInts(1, 2)).not.toBe(hashInts(2, 1));
  });
});

describe('Rng', () => {
  const take = (r, n) => Array.from({ length: n }, () => r.next());

  test('same seed => identical sequence', () => {
    expect(take(new Rng('hello'), 200)).toEqual(take(new Rng('hello'), 200));
  });

  test('different seeds differ', () => {
    expect(take(new Rng('hello'), 20)).not.toEqual(take(new Rng('hellp'), 20));
  });

  test('next() is in [0,1) and roughly uniform', () => {
    const r = new Rng('uniform');
    let sum = 0;
    const buckets = new Array(10).fill(0);
    const N = 20000;
    for (let i = 0; i < N; i++) {
      const v = r.next();
      if (v < 0 || v >= 1) throw new Error('out of range ' + v);
      sum += v;
      buckets[Math.floor(v * 10)]++;
    }
    expect(sum / N).toBeGreaterThan(0.48);
    expect(sum / N).toBeLessThan(0.52);
    buckets.forEach((b) => expect(b).toBeGreaterThan(N / 10 - 300));
  });

  test('int/range/chance/pick behave', () => {
    const r = new Rng('helpers');
    for (let i = 0; i < 500; i++) {
      const n = r.int(3, 7);
      expect(n).toBeGreaterThanOrEqual(3);
      expect(n).toBeLessThanOrEqual(7);
      expect(Number.isInteger(n)).toBe(true);
      const f = r.range(-2, 5);
      expect(f).toBeGreaterThanOrEqual(-2);
      expect(f).toBeLessThan(5);
    }
    expect(r.chance(0)).toBe(false);
    expect(r.chance(1.0001)).toBe(true);
    const seen = new Set();
    for (let i = 0; i < 200; i++) seen.add(r.pick(['a', 'b', 'c']));
    expect(seen.size).toBe(3);
  });

  test('weighted respects weights, skips zeros, handles empty', () => {
    const r = new Rng('weights');
    const items = [{ k: 'a', w: 1 }, { k: 'b', w: 9 }, { k: 'z', w: 0 }];
    const counts = { a: 0, b: 0, z: 0 };
    for (let i = 0; i < 5000; i++) counts[r.weighted(items, (x) => x.w).k]++;
    expect(counts.z).toBe(0);
    expect(counts.b / counts.a).toBeGreaterThan(6);
    expect(r.weighted([], () => 1)).toBeUndefined();
    expect(r.weighted(items, () => 0)).toBeUndefined();
  });

  test('fork: deterministic, independent of consumption, independent streams', () => {
    const a = new Rng('seed');
    const f1 = a.fork('terrain');
    take(a, 50); // consuming the parent must not change forks
    const f2 = a.fork('terrain');
    expect(take(f1, 10)).toEqual(take(f2, 10));
    expect(take(a.fork('terrain'), 10)).not.toEqual(take(a.fork('glitch'), 10));
    // consuming one fork does not shift another
    const g1 = new Rng('seed').fork('glitch');
    const t = new Rng('seed').fork('terrain');
    take(t, 1000);
    const g2 = new Rng('seed').fork('glitch');
    expect(take(g1, 10)).toEqual(take(g2, 10));
  });

  test('numeric seeds are used as state directly', () => {
    expect(take(new Rng(42), 5)).toEqual(take(new Rng(42), 5));
    expect(take(new Rng(42), 5)).not.toEqual(take(new Rng(43), 5));
  });
});// Issue #59 stage 1: gameplay randomness comes from named seeded streams; new seeds from the CSPRNG.
import fs from 'fs';
import { Rng } from '../../src/systems/Rng.js';
import { runRandomStreams, runRandomState, RUN_STREAMS, RUN_RANDOM_VERSION } from '../../src/systems/RunRandom.js';
import { randomSeed } from '../../src/ui/Format.js';

const draws = (rng, n) => Array.from({ length: n }, () => rng.next());

describe('run random streams', () => {
  test('same seed, same scramble sequence; different seed, different sequence', () => {
    expect(draws(runRandomStreams('ABC234').physicsScramble, 50)).toEqual(draws(runRandomStreams('ABC234').physicsScramble, 50));
    expect(draws(runRandomStreams('ABC234').physicsScramble, 5)).not.toEqual(draws(runRandomStreams('ABC235').physicsScramble, 5));
  });

  test('drawing cosmetic randomness never moves the physics stream', () => {
    const a = runRandomStreams('DAILY-1'), b = runRandomStreams('DAILY-1');
    const quiet = draws(a.physicsScramble, 40);
    const noisy = [];
    for (let i = 0; i < 40; i++) { draws(b.visualSled, 7); noisy.push(b.physicsScramble.next()); }
    expect(noisy).toEqual(quiet);
  });

  test('streams are Rng.fork of the run seed, so existing terrain/mission streams are untouched', () => {
    const s = runRandomStreams('legacy-seed');
    expect(s.physicsScramble.baseSeed).toBe(new Rng('legacy-seed').fork(RUN_STREAMS.physicsScramble).baseSeed);
    expect(s.physicsScramble.baseSeed).not.toBe(s.visualSled.baseSeed);
    expect(new Rng('legacy-seed').next()).toBe(new Rng('legacy-seed').next());
  });

  test('stream state snapshot is versioned and tracks consumption', () => {
    const s = runRandomStreams('X');
    const before = runRandomState(s);
    expect(before.version).toBe(RUN_RANDOM_VERSION);
    s.physicsScramble.next();
    const after = runRandomState(s);
    expect(after.physicsScramble).not.toBe(before.physicsScramble);
    expect(after.visualSled).toBe(before.visualSled);
  });

  test('Sled draws scramble torque from the seeded physics stream; no Math.random left in it', () => {
    const src = fs.readFileSync('src/entities/Sled.js', 'utf8');
    expect(src).not.toMatch(/Math\.random/);
    expect(src).toMatch(/this\.random\.physicsScramble\.next\(\) \* 2 - 1\) \* phys\.scrambleJitterDegS2/);
    expect(src).toMatch(/this\.random\.visualSled\.next\(\)/);
    expect(fs.readFileSync('src/scenes/RunScene.js', 'utf8')).toMatch(/this\.runRandom = runRandomStreams\(this\.seed\)/);
  });
});

describe('new seeds use the CSPRNG', () => {
  test('six readable chars taken from getRandomValues, unbiased mapping', () => {
    const fake = { getRandomValues: (a) => { a.set([0, 31, 32, 63, 255, 8]); return a; } };
    // bytes & 31 -> [0, 31, 0, 31, 31, 8] -> 'A', '9', 'A', '9', '9', 'J'
    expect(randomSeed(fake)).toBe('A9A99J');
  });

  test('real platform crypto: valid alphabet, and not one fixed seed for everyone', () => {
    const seen = new Set();
    for (let i = 0; i < 50; i++) {
      const s = randomSeed();
      expect(s).toMatch(/^[A-HJ-NP-Z2-9]{6}$/);
      seen.add(s);
    }
    expect(seen.size).toBeGreaterThan(45);
    expect(fs.readFileSync('src/ui/Format.js', 'utf8')).not.toMatch(/Math\.random/);
  });
});

describe('stage 3: no unseeded randomness left in the game', () => {
  const walk = (dir) => fs.readdirSync(dir, { withFileTypes: true }).flatMap((e) => (e.isDirectory() ? walk(`${dir}/${e.name}`) : e.name.endsWith('.js') ? [`${dir}/${e.name}`] : []));
  test('src/ has no Math.random() call (comments aside)', () => {
    const offenders = walk('src').filter((f) => fs.readFileSync(f, 'utf8').split('\n')
      .some((l) => /Math\.random\(\)/.test(l) && !/^\s*(\*|\/\/)/.test(l)));
    expect(offenders).toEqual([]);
  });

  test('cosmetic streams are named forks: drawing one never moves another or a run stream', async () => {
    const { cosmeticRandom, seedCosmeticRandom } = await import('../../src/systems/CosmeticRandom.js');
    seedCosmeticRandom(7);
    const a = draws(cosmeticRandom('title/fx'), 5);
    seedCosmeticRandom(7);
    draws(cosmeticRandom('audio/sfx'), 50);
    expect(draws(cosmeticRandom('title/fx'), 5)).toEqual(a);
    const run = runRandomStreams('S');
    const before = run.physicsScramble.state;
    draws(run.visualFx, 20); draws(run.visualCamera, 20);
    expect(run.physicsScramble.state).toBe(before);
  });
});/**
 * Run-start rules that live in the scenes: the device BEST the run chases, the Title BEST line, the
 * DAILY RUN seed/mask pairing, which boosts a run may apply, and the mask-0 palette path.
 *
 * The scenes are driven through their REAL prototype methods (TitleScene._buildMenu / startRun /
 * _loadBest, RunScene.create / updateFun / doCrash) with Phaser and the rendering entities replaced by
 * inert fakes. Nothing here re-implements a scene's logic. Harness adapted from the post-sprint audit's
 * fairness tests.
 *
 * Date: every test runs with the clock pinned to 2026-11-13T12:00:00Z. That day's derived Daily mask is 8
 * (Underwater Mountain).
 */
import { jest } from '@jest/globals';
import { loadContent } from './_helpers.js';
import { BSOD_DEFAULTS } from '../../src/systems/BsodPursuit.js';

// ---------------------------------------------------------------- inert fakes

/** Anything-goes stand-in: every property is another stand-in, every call/construct returns one. */
function deep() {
  const fn = function () {};
  return new Proxy(fn, {
    get(t, k) {
      if (k === 'then') return undefined; // or `await` / Promise.resolve() would hang on it
      if (k === Symbol.toPrimitive) return () => 0;
      if (k === Symbol.iterator) return function* empty() {};
      if (k === 'length') return 0;
      if (typeof k === 'symbol') return undefined;
      if (Object.prototype.hasOwnProperty.call(t, k) && k !== 'name' && k !== 'prototype') return t[k];
      return deep();
    },
    // Reflect.set with the receiver, not `t[k] = v`: the scenes' prototype chain runs through one of these
    // (the mocked Phaser.Scene), so a plain write would park every new instance field on that SHARED
    // object and leak it into the next scene built in the same file (a stale `_biomeSector`, for one).
    set(t, k, v, receiver) { return Reflect.set(t, k, v, receiver); },
    apply() { return deep(); },
    construct() { return deep(); },
  });
}

const sledCalls = [];
class FakeSled {
  constructor() {
    this.invulnerableMs = 0;
    this.shield = false;
    return new Proxy(this, {
      get(t, k) {
        if (k in t) return t[k];
        if (k === 'then' || typeof k === 'symbol') return undefined;
        return (...a) => { sledCalls.push([k, ...a]); return deep(); };
      },
    });
  }
  scaleVelocity(f) { sledCalls.push(['scaleVelocity', f]); }
}
const markers = [];
class FakeMarker { constructor(scene, pal, x, m) { markers.push(m); } update() {} markPassed() {} destroy() {} }
class Inert { constructor() { return deep(); } }

const texts = [];
class FakeNeonText {
  constructor(scene, theme, x, y, text) { this.text = text; texts.push(text); }
  setText(t) { this.text = t; texts.push(t); return this; }
  setAlpha() { return this; }
  setColorKey() { return this; }
  setVisible() { return this; }
  setDepth() { return this; }
  destroy() {}
}
let menuItems = null;
class FakeMenuList { constructor(scene, theme, o) { menuItems = o.items; this.rows = []; } }
class FakePanel { add() { return this; } setVisible() { return this; } destroy() {} setTitle() { return this; } setColorKey() { return this; } }

