import { GhostRecorder, TRACE_EVERY, decodeTrace } from '../../src/systems/ghost/GhostTape.js';

const flat = [[50001, 140009, 0], [51025, 140009, 0.5]];
const curve = [[50001, 140009, 0], [50513, 140169, 0.25], [51025, 140049, 0.5]];
const poses = (rows) => new Float32Array(rows.flat());
const art = (rows) => renderRunTraceArt(poses(rows));

function tapeOf(rows, header = {}) {
  const recorder = new GhostRecorder(header);
  rows.forEach(([x, y, angle], index) => {
    recorder.afterTick((index + 1) * TRACE_EVERY, {
      sled: { body: { position: { x, y }, angle, velocity: { x: 0, y: 0 }, angularVelocity: 0 } },
    });
  });
  return recorder.finish({ runId: 'PRIVATE-RUN-ID', distanceM: 812345, score: 987654, endedAt: 1795284763551 });
}

function parseSvg(markup) {
  const doc = new DOMParser().parseFromString(markup, 'image/svg+xml');
  expect(doc.querySelector('parsererror')).toBeNull();
  expect(doc.documentElement.namespaceURI).toBe('http://www.w3.org/2000/svg');
  return doc;
}

test('identical trace bytes recreate identical art; different recorded paths change geometry', () => {
  const tape = tapeOf(curve);
  const svg = renderRunTraceArt(decodeTrace(tape));
  expect(renderRunTraceArt(decodeTrace(tapeOf(curve)))).toBe(svg);
  expect(svg).toContain(`ART V${RUN_TRACE_ART_VERSION}`);
  expect(parseSvg(svg).querySelector('text[letter-spacing="1.3"]').textContent).toBe('LOCAL / UNVERIFIED');
  const a = parseSvg(svg).querySelector('path[stroke-width="4"]').getAttribute('d');
  const b = parseSvg(art(flat)).querySelector('path[stroke-width="4"]').getAttribute('d');
  expect(a).not.toBe(b);
  expect(a.match(/[ML]/g)).toHaveLength(64);
  expect(b.match(/[ML]/g)).toHaveLength(64);
  expect(svg).not.toMatch(/50001|51025|140009|140169/);
});

test('loses world origin and scale, and resamples an equivalent shape consistently', () => {
  const shifted = curve.map(([x, y, angle]) => [x + 3_000_000, y + 1_000_000, -angle]);
  const scaled = curve.map(([x, y, angle]) => [x * 2, y * 3, angle]);
  const interpolatedFlat = [flat[0], [50513, 140009, 0], flat[1]];
  expect(art(shifted)).toBe(art(curve));
  expect(art(scaled)).toBe(art(curve));
  expect(art(interpolatedFlat)).toBe(art(flat));
  const center = parseSvg(art([[7, 8, 0], [7, 8, 0]])).querySelector('path[stroke-width="4"]');
  expect(center.getAttribute('d')).toMatch(/^M480 364(?: L480 364){63}$/);
  // A trace with one flat axis has an empty object bounding box for paint.
  expect(parseSvg(art(flat)).querySelector('#ion').getAttribute('gradientUnits')).toBe('userSpaceOnUse');
});

test.each([['V1', renderRunTraceArt], ['V2', renderRunTraceOrientationStudy]])(
  '%s emits only inert SVG markup and local paint references, within its ASCII byte cap', (_version, render) => {
    const svg = render(poses(curve));
    expect(Buffer.byteLength(svg)).toBeLessThanOrEqual(MAX_ART_SVG_BYTES);
    const doc = parseSvg(svg);
    const allowed = ['svg', 'title', 'desc', 'defs', 'linearGradient', 'radialGradient', 'stop',
      'rect', 'ellipse', 'path', 'g', 'circle', 'text'];
    for (const el of doc.querySelectorAll('*')) {
      expect(allowed).toContain(el.localName);
      for (const attr of el.attributes) {
        expect(attr.name).not.toMatch(/^(?:on|href|src|style)/i);
        if (attr.name !== 'xmlns' && attr.value.includes('url(')) {
          expect(attr.value).toMatch(/^url\(#[a-z]+\)$/);
        }
        if (attr.name !== 'xmlns') expect(attr.value).not.toMatch(/https?:|javascript:|data:/i);
      }
    }
    expect(svg).not.toMatch(/<!DOCTYPE|<\?xml-stylesheet/i);
  });

test('validates all finite complete triples, including points skipped by rendering, and bounds work', () => {
  expect(() => renderRunTraceArt([0, 1, 2, 3, 4, 5])).toThrow(/Float32/);
  expect(() => renderRunTraceArt(new Float32Array(7))).toThrow(/complete/);
  expect(() => art([[0, 0, 0]])).toThrow(/2 to/);
  for (const invalid of [Infinity, NaN, -3.4e38]) {
    const input = new Float32Array(32_000 * 3);
    input[17] = invalid;
    expect(() => renderRunTraceArt(input)).toThrow(/finite and within/);
  }
  const maximum = new Float32Array(MAX_ART_POSES * 3);
  expect(Buffer.byteLength(renderRunTraceArt(maximum))).toBeLessThanOrEqual(MAX_ART_SVG_BYTES);
  expect(() => renderRunTraceArt(new Float32Array((MAX_ART_POSES + 1) * 3))).toThrow(/2 to/);
});

function runCli(files, test) {
  const dir = mkdtempSync(join(tmpdir(), 'bb-trace-art-'));
  try {
    for (const [name, data] of Object.entries(files)) writeFileSync(join(dir, name), data);
    test((name, ...options) => spawnSync(process.execPath,
      ['tools/run-trace-art.mjs', ...options, join(dir, name)], { encoding: 'utf8', timeout: 5000 }));
  } finally {
    rmSync(dir, { recursive: true, force: true });
  }
}

test.each([
  ['V1', renderRunTraceArt, []],
  ['V2', renderRunTraceOrientationStudy, ['--art-v2']],
])('%s CLI writes the same SVG for the real recorder payload and for hostile metadata', (_version, render, options) => {
  const tape = tapeOf(curve, { seed: 'RAW-SEED', initials: 'PLAYER-X', account: '<script>metadata()</script>' });
  const hostile = {
    ...tape, seed: 'malicious.example/other-seed', runId: 'OTHER-RUN-ID',
    initials: '<image href="https://malicious.example/">', email: 'private@example.com',
    inputs: [[1, 4, 9]], checkpoints: [[2, 143599, 732109]], verified: true,
    physicsVersion: 999, simTickHz: 1, endTick: 999999,
  };
  runCli({ 'raw.json': JSON.stringify(tape), 'hostile.json': JSON.stringify(hostile) }, (run) => {
    const raw = run('raw.json', ...options), attack = run('hostile.json', ...options);
    expect(raw.status).toBe(0);
    expect(attack.status).toBe(0);
    expect(raw.stderr).toBe('');
    expect(raw.stdout).toBe(render(poses(curve)));
    expect(attack.stdout).toBe(raw.stdout);
    expect(raw.stdout).not.toMatch(/RAW-SEED|PLAYER-X|PRIVATE-RUN-ID|812345|987654|1795284763551|143599|732109|malicious\.example|private@example\.com|<script|href=/);
    expect(raw.stdout).not.toContain(tape.trace);
  });
});

test.each([['V1', []], ['V2', ['--art-v2']]])(
  '%s CLI rejects partial or invalid encoding, unsupported versions and oversized JSON without SVG output', (_version, options) => {
    const tape = tapeOf(curve);
    const file = (updates) => JSON.stringify({ ...tape, ...updates });
    runCli({
      'version.json': file({ version: 2 }),
      'partial.json': file({ trace: Buffer.concat([Buffer.from(tape.trace, 'base64'), Buffer.from([0])]).toString('base64') }),
      'invalid.json': file({ trace: '?' + tape.trace.slice(1) }),
      'nonfinite.json': JSON.stringify(tapeOf([[0, 0, 0], [NaN, 10, 0]])),
      'too-many-poses.json': file({ trace: 'A'.repeat((MAX_ART_POSES + 1) * 16) }),
      'huge.json': Buffer.alloc(2 * 1024 * 1024 + 1),
    }, (run) => {
      for (const name of ['version.json', 'partial.json', 'invalid.json', 'nonfinite.json', 'too-many-poses.json', 'huge.json']) {
        const result = run(name, ...options);
        expect(result.status).toBe(1);
        expect(result.stdout).toBe('');
        expect(result.stderr).toMatch(/^Trace art:/);
      }
    });
  });


test('defaults to the frozen V1 bytes and ignores orientation unless V2 is explicitly requested', () => {
  const still = curve.map(([x, y]) => [x, y, 0]);
  expect(art(still)).toBe(art(curve));
  expect(createHash('sha256').update(art(curve)).digest('hex'))
    .toBe('ea4554f7982c30c079c6d1da3e17d354e5e08ae5182ca84002bb0bde3fae1fed');
  const render = (rows) => renderRunTraceOrientationStudy(poses(rows));
  const svg = render(curve);
  expect(svg).toBe(render(curve));
  expect(svg).not.toBe(render(still));
  expect(svg).toContain('ART V2');
  expect(svg).toContain('LOCAL / UNVERIFIED');
  expect(svg).toContain('NO ATTESTATION');
  const path = (markup) => parseSvg(markup).querySelector('path[stroke-width="4"]').getAttribute('d');
  expect(path(svg)).toBe(path(art(curve)));
});

test('V2 projects only fixed-size, unsigned wrapped orientation tiers', () => {
  const marks = (rows) => {
    const svg = renderRunTraceOrientationStudy(poses(rows));
    return [...parseSvg(svg).querySelectorAll('g[aria-label="Coarse sampled sled orientation changes"] circle')]
      .map((el) => Number(el.getAttribute('r')));
  };
  const sample = (angle) => [[7, 8, 0], [7, 8, angle]];
  const still = Array(16).fill(2);
  expect(marks(sample(0))).toEqual(still);
  expect(marks([[7, 8, Math.PI - 0.01], [7, 8, -Math.PI + 0.01]])).toEqual(still);
  for (const [angle, radius] of [[0.05, 3], [0.13, 4], [1, 5]]) {
    const expected = [...still];
    expected[8] = radius;
    expect(marks(sample(angle))).toEqual(expected);
    expect(marks(sample(-angle))).toEqual(expected);
  }
  expect(marks([[0, 0, -1e9], [0, 0, 1e9]])).toHaveLength(16);
});

test('V2 validates before quantizing, even for off-path pose components', () => {
  const max = new Float32Array(MAX_ART_POSES * 3);
  expect(Buffer.byteLength(renderRunTraceOrientationStudy(max))).toBeLessThanOrEqual(MAX_ART_SVG_BYTES);
  max[20] = NaN;
  expect(() => renderRunTraceOrientationStudy(max)).toThrow(/finite and within/);
  expect(() => renderRunTraceOrientationStudy(new Float32Array((MAX_ART_POSES + 1) * 3))).toThrow(/2 to/);
});

test('CLI documents V2 and emits no SVG for invalid opt-in arguments or a directory', () => {
  const cli = (...args) => spawnSync(process.execPath, ['tools/run-trace-art.mjs', ...args],
    { encoding: 'utf8', timeout: 5000 });
  const help = cli('--help');
  expect(help.status).toBe(0);
  expect(help.stdout).toMatch(/run-trace-art\.mjs --art-v2 /);
  for (const args of [['--art-v2'], ['--art-v2', '--help'], ['--art-v2', './file', './extra'], ['--art-v2', '.']]) {
    const result = cli(...args);
    expect(result.status).toBe(1);
    expect(result.stdout).toBe('');
    expect(result.stderr).toMatch(/^Trace art:/);
  }
});import { jest } from '@jest/globals';
import {
  SaveStore, defaultSettings, sanitizeSettings, sanitizeRun, normalizeInitials, base64Encode, base64Decode,
  SHARECODE_PREFIX,
} from '../../src/systems/SaveStore.js';
import { STORAGE } from '../../src/constants.js';
import { DailyPatch } from '../../src/systems/DailyPatch.js';

let seq = 0;
function makeRun(over = {}) {
  seq++;
  const r = {
    version: 1, id: `run-${seq}`, seed: 'seed-' + seq, dailyRuleId: 'tuckBoost', startedAt: 1000 * seq,
    endedAt: 1000 * seq + 500, durationMs: 500, score: 100 + seq, distanceM: 80, trickPoints: 20,
    tricks: { backflip: 2 }, bestCombo: 1.5, maxAirtimeMs: 1200, cause: 'crash', ledgerHash: '', ...over,
  };
  if (over.ledgerHash === undefined) r.ledgerHash = SaveStore.computeLedgerHash(r);
  return r;
}

async function fresh() {
  const s = new SaveStore();
  await s.init();
  return s;
}

/** Minimal in-memory IndexedDB double (enough for open/upgrade/getAll/put). */
function makeFakeIndexedDB() {
  const dbs = new Map();
  const later = (fn) => setTimeout(fn, 0);
  return {
    dbs,
    open(name) {
      const req = {};
      later(() => {
        let db = dbs.get(name);
        const isNew = !db;
        if (isNew) {
          db = { stores: new Map(), objectStoreNames: { contains: (n) => db.stores.has(n) } };
          db.createObjectStore = (n, opts) => { db.stores.set(n, { keyPath: opts.keyPath, data: new Map() }); };
          db.transaction = (n) => {
            const tx = {};
            const store = db.stores.get(n);
            tx.objectStore = () => ({
              getAll() {
                const r = {};
                later(() => { r.result = [...store.data.values()].map((v) => JSON.parse(JSON.stringify(v))); r.onsuccess && r.onsuccess(); });
                return r;
              },
              put(v) {
                store.data.set(v[store.keyPath], JSON.parse(JSON.stringify(v)));
                later(() => tx.oncomplete && tx.oncomplete());
                return {};
              },
            });
            return tx;
          };
          dbs.set(name, db);
        }
        req.result = db;
        if (isNew && req.onupgradeneeded) req.onupgradeneeded();
        req.onsuccess && req.onsuccess();
      });
      return req;
    },
  };
}

describe('settings', () => {
  beforeEach(() => localStorage.clear());

  test('defaults when nothing stored', () => {
    expect(new SaveStore().loadSettings()).toEqual(defaultSettings());
    expect(defaultSettings().version).toBe(STORAGE.saveVersion);
  });

  test('round trip through localStorage', () => {
    const s = new SaveStore();
    const cfg = { ...defaultSettings(), masterVolume: 0.3, palette: 'colorblind', screenShake: false, lastInitials: 'ABC', touchOverlay: 'on' };
    s.saveSettings(cfg);
    expect(localStorage.getItem(STORAGE.settingsKey)).toBeTruthy();
    expect(new SaveStore().loadSettings()).toEqual(cfg);
  });

  test('unknown keys are ignored and missing keys defaulted (forward/backward compatible)', () => {
    localStorage.setItem(STORAGE.settingsKey, JSON.stringify({ version: 99, masterVolume: 0.5, futureThing: { a: 1 }, palette: 'colorblind' }));
    const loaded = new SaveStore().loadSettings();
    expect(loaded.masterVolume).toBe(0.5);
    expect(loaded.palette).toBe('colorblind');
    expect(loaded.sfxVolume).toBe(defaultSettings().sfxVolume);
    expect(loaded).not.toHaveProperty('futureThing');
    expect(loaded.version).toBe(STORAGE.saveVersion);
  });

  test('invalid values are sanitised, corrupt JSON falls back to defaults', () => {
    const s = sanitizeSettings({ masterVolume: 7, musicVolume: -1, sfxVolume: 'loud', palette: 'neon', touchOverlay: 'maybe', screenShake: 'yes', touchRotate90: 1, lastInitials: 42 });
    expect(s.masterVolume).toBe(1);
    expect(s.musicVolume).toBe(0);
    expect(s.sfxVolume).toBe(defaultSettings().sfxVolume);
    expect(s.palette).toBe('default');
    expect(s.touchOverlay).toBe('auto');
    expect(s.screenShake).toBe(true);
    expect(s.touchRotate90).toBe(false);
    expect(s.lastInitials).toBe('');
    localStorage.setItem(STORAGE.settingsKey, '{not json');
    expect(new SaveStore().loadSettings()).toEqual(defaultSettings());
    expect(sanitizeSettings(null)).toEqual(defaultSettings());
  });

  test('does not throw and keeps working when localStorage throws (private mode)', () => {
    const orig = Object.getOwnPropertyDescriptor(globalThis, 'localStorage');
    Object.defineProperty(globalThis, 'localStorage', { configurable: true, get() { throw new Error('denied'); } });
    try {
      const s = new SaveStore();
      expect(s.loadSettings()).toEqual(defaultSettings());
      expect(() => s.saveSettings({ ...defaultSettings(), masterVolume: 0.1 })).not.toThrow();
      expect(s.loadSettings().masterVolume).toBe(0.1); // in-memory copy
    } finally {
      Object.defineProperty(globalThis, 'localStorage', orig);
    }
  });

  test('works when localStorage is missing entirely', () => {
    const orig = Object.getOwnPropertyDescriptor(globalThis, 'localStorage');
    Object.defineProperty(globalThis, 'localStorage', { configurable: true, value: undefined });
    try {
      const s = new SaveStore();
      s.saveSettings({ ...defaultSettings(), sfxVolume: 0.2 });
      expect(s.loadSettings().sfxVolume).toBe(0.2);
    } finally {
      Object.defineProperty(globalThis, 'localStorage', orig);
    }
  });

  test('setItem quota errors are swallowed', () => {
    const spy = jest.spyOn(Storage.prototype, 'setItem').mockImplementation(() => { throw new Error('quota'); });
    try {
      expect(() => new SaveStore().saveSettings(defaultSettings())).not.toThrow();
    } finally {
      spy.mockRestore();
    }
  });
});

describe('runs (in-memory fallback: jsdom has no indexedDB)', () => {
  test('init works without indexedDB and uses memory backend', async () => {
    const s = await fresh();
    expect(globalThis.indexedDB).toBeUndefined();
    expect(s.backend).toBe('memory');
  });

  test('saveRun is idempotent by id and ignores invalid records', async () => {
    const s = await fresh();
    const r = makeRun();
    await s.saveRun(r);
    await s.saveRun({ ...r, score: 99999 });
    await s.saveRun({ nonsense: true });
    await s.saveRun(null);
    expect(s.runs).toHaveLength(1);
    expect((await s.getRecentRuns())[0].score).toBe(r.score);
  });

  test('getRecentRuns: most recent first, limited', async () => {
    const s = await fresh();
    const runs = [makeRun({ endedAt: 100 }), makeRun({ endedAt: 300 }), makeRun({ endedAt: 200 })];
    for (const r of runs) await s.saveRun(r);
    expect((await s.getRecentRuns()).map((r) => r.endedAt)).toEqual([300, 200, 100]);
    expect(await s.getRecentRuns(2)).toHaveLength(2);
  });

  test('returned records are copies (mutation does not corrupt the store)', async () => {
    const s = await fresh();
    const r = makeRun();
    await s.saveRun(r);
    const out = await s.getRecentRuns(1);
    out[0].score = -5;
    out[0].tricks.backflip = 99;
    expect((await s.getRecentRuns(1))[0].score).toBe(r.score);
    expect((await s.getRecentRuns(1))[0].tricks.backflip).toBe(2);
  });
});

describe('initials and leaderboard', () => {
  test('setInitials: trims, uppercases, makes the run a leaderboard entry', async () => {
    const s = await fresh();
    const r = makeRun({ score: 500 });
    await s.saveRun(r);
    expect(await s.getLeaderboard()).toEqual([]);
    await s.setInitials(r.id, '  abc ');
    const board = await s.getLeaderboard();
    expect(board).toHaveLength(1);
    expect(board[0].initials).toBe('ABC');
  });

  test('3 chars minimum (RangeError), longer initials allowed up to 12', async () => {
    const s = await fresh();
    const r = makeRun();
    await s.saveRun(r);
    await expect(s.setInitials(r.id, 'AB')).rejects.toBeInstanceOf(RangeError);
    await expect(s.setInitials(r.id, '  ')).rejects.toBeInstanceOf(RangeError);
    await expect(s.setInitials(r.id, 42)).rejects.toBeInstanceOf(RangeError);
    await s.setInitials(r.id, 'sledmaster');
    expect((await s.getLeaderboard())[0].initials).toBe('SLEDMASTER');
    await s.setInitials(r.id, 'a'.repeat(30));
    expect((await s.getLeaderboard())[0].initials).toHaveLength(12);
  });

  test('unknown run id is ignored', async () => {
    const s = await fresh();
    await expect(s.setInitials('ghost', 'ABC')).resolves.toBeUndefined();
    expect(await s.getLeaderboard()).toEqual([]);
  });

  test('sorted by score desc, ties older first, limited to top N (default 10)', async () => {
    const s = await fresh();
    const ids = [];
    for (let i = 0; i < 15; i++) {
      const r = makeRun({ score: 1000 + (i % 5) * 10, endedAt: 5000 + i });
      ids.push(r);
      await s.saveRun(r);
      await s.setInitials(r.id, 'AAA');
    }
    const unranked = makeRun({ score: 99999 });
    await s.saveRun(unranked); // no initials: not on the board
    const board = await s.getLeaderboard();
    expect(board).toHaveLength(10);
    expect(board.map((b) => b.score)).toEqual([...board.map((b) => b.score)].sort((a, b) => b - a));
    expect(board.find((b) => b.id === unranked.id)).toBeUndefined();
    const fortyTies = board.filter((b) => b.score === 1040);
    expect(fortyTies.map((b) => b.endedAt)).toEqual([...fortyTies.map((b) => b.endedAt)].sort((a, b) => a - b));
    expect(await s.getLeaderboard(3)).toHaveLength(3);
  });

  test('qualifiesForTop10: true while not full, then must beat the 10th', async () => {
    const s = await fresh();
    expect(await s.qualifiesForTop10(0)).toBe(true);
    for (let i = 0; i < 10; i++) {
      const r = makeRun({ score: 100 + i * 10, endedAt: i });
      await s.saveRun(r);
      await s.setInitials(r.id, 'ZZZ');
    }
    // 10th place is score 100
    expect(await s.qualifiesForTop10(100)).toBe(false);
    expect(await s.qualifiesForTop10(99)).toBe(false);
    expect(await s.qualifiesForTop10(101)).toBe(true);
  });
});

describe('ledger hash', () => {
  test('8 lowercase hex chars, deterministic, ignores initials and ledgerHash', () => {
    const r = makeRun();
    const h = SaveStore.computeLedgerHash(r);
    expect(h).toMatch(/^[0-9a-f]{8}$/);
    expect(SaveStore.computeLedgerHash({ ...r, initials: 'ABC', ledgerHash: 'whatever' })).toBe(h);
    expect(SaveStore.computeLedgerHash({ ...r, tricks: { backflip: 2 } })).toBe(h);
  });

  test('changes when stable fields change; trick key order does not matter', () => {
    const r = makeRun({ tricks: { a: 1, b: 2 } });
    const h = SaveStore.computeLedgerHash(r);
    expect(SaveStore.computeLedgerHash({ ...r, score: r.score + 1 })).not.toBe(h);
    expect(SaveStore.computeLedgerHash({ ...r, seed: 'other' })).not.toBe(h);
    expect(SaveStore.computeLedgerHash({ ...r, dailyRuleId: 'x' })).not.toBe(h);
    expect(SaveStore.computeLedgerHash({ ...r, tricks: { b: 2, a: 1 } })).toBe(h);
    expect(SaveStore.computeLedgerHash({ ...r, tricks: { a: 1, b: 3 } })).not.toBe(h);
  });

  test('does not throw on garbage', () => {
    expect(SaveStore.computeLedgerHash(null)).toMatch(/^[0-9a-f]{8}$/);
    expect(SaveStore.computeLedgerHash({})).toMatch(/^[0-9a-f]{8}$/);
  });
});

describe('sanitizers and base64', () => {
  test('sanitizeRun drops unknown keys, clamps types, requires id', () => {
    expect(sanitizeRun(null)).toBeNull();
    expect(sanitizeRun({ score: 5 })).toBeNull();
    const r = sanitizeRun({ id: 'x', score: 'nope', hack: true, tricks: { backflip: 2, bad: 'x', neg: -4 }, cause: 'weird', initials: 'ab' });
    expect(r).not.toHaveProperty('hack');
    expect(r.score).toBe(0);
    expect(r.tricks).toEqual({ backflip: 2 });
    expect(r.cause).toBe('crash');
    expect(r).not.toHaveProperty('initials'); // too short
    expect(sanitizeRun({ id: 'y', initials: ' abcd ' }).initials).toBe('ABCD');
  });

  test('sanitizeRun keeps fun-pass counters', () => {
    const r = sanitizeRun({ id: 'z', shards: 7, nearMisses: 2, bonusPoints: 140, hack: 1 });
    expect(r).toMatchObject({ shards: 7, nearMisses: 2, bonusPoints: 140 });
    expect(sanitizeRun({ id: 'q', shards: -1 })).not.toHaveProperty('shards');
  });

  test('normalizeInitials', () => {
    expect(normalizeInitials(' a\u0000bc ')).toBe('ABC');
    expect(normalizeInitials(5)).toBe('');
  });

  test('base64 round trips ASCII, unicode and emoji; rejects junk', () => {
    for (const t of ['', 'a', 'ab', 'abc', 'hello world', 'é中文 🚀 sled', JSON.stringify({ a: [1, 2, 3] })]) {
      expect(base64Decode(base64Encode(t))).toBe(t);
    }
    expect(base64Encode('Man')).toBe('TWFu');
    expect(base64Encode('Ma')).toBe('TWE=');
    expect(() => base64Decode('***')).toThrow();
  });
});

describe('sharecode', () => {
  async function boardStore(n = 3) {
    const s = await fresh();
    const rs = [];
    for (let i = 0; i < n; i++) {
      const r = makeRun({ score: 200 + i * 50 });
      await s.saveRun(r);
      await s.setInitials(r.id, ['AAA', 'BBB', 'CCCC'][i % 3]);
      rs.push(r);
    }
    return { s, rs };
  }

  test('export is a prefixed string; import into a fresh store reproduces the leaderboard', async () => {
    const { s } = await boardStore(4);
    const code = await s.exportSharecode();
    expect(typeof code).toBe('string');
    expect(code.startsWith(SHARECODE_PREFIX)).toBe(true);
    const other = await fresh();
    const res = await other.importSharecode(code);
    expect(res).toEqual({ imported: 4, skipped: 0 });
    expect(await other.getLeaderboard()).toEqual(await s.getLeaderboard());
  });

  test('import dedupes by run id (second import skips everything)', async () => {
    const { s } = await boardStore(3);
    const code = await s.exportSharecode();
    const other = await fresh();
    await other.importSharecode(code);
    expect(await other.importSharecode(code)).toEqual({ imported: 0, skipped: 3 });
    expect(await s.importSharecode(code)).toEqual({ imported: 0, skipped: 3 });
    expect((await other.getLeaderboard()).length).toBe(3);
  });

  test('merge: only new runs are imported', async () => {
    const { s } = await boardStore(2);
    const other = await fresh();
    await other.importSharecode(await s.exportSharecode());
    const extra = makeRun({ score: 9000 });
    await other.saveRun(extra);
    await other.setInitials(extra.id, 'NEW');
    const res = await s.importSharecode(await other.exportSharecode());
    expect(res).toEqual({ imported: 1, skipped: 2 });
    expect((await s.getLeaderboard())[0].id).toBe(extra.id);
  });

  test('accepts bare base64 and raw JSON as well', async () => {
    const { s } = await boardStore(2);
    const code = await s.exportSharecode();
    const bare = code.slice(SHARECODE_PREFIX.length);
    const json = base64Decode(bare);
    for (const variant of [bare, json, `  ${code}\n`]) {
      const o = await fresh();
      expect((await o.importSharecode(variant)).imported).toBe(2);
    }
  });

  test('bad input never throws and imports nothing', async () => {
    const s = await fresh();
    for (const bad of ['', '   ', 'garbage!!!', 'BB1:@@@@', 'BB1:' + base64Encode('not json'), '{"runs": 5}', '[1,2,3]', null, undefined, 42, {}]) {
      const res = await s.importSharecode(bad);
      expect(res.imported).toBe(0);
    }
    expect(s.runs).toHaveLength(0);
  });

  test('skips invalid entries, entries without initials, unknown keys are stripped, tampered hash is rejected', async () => {
    const good = makeRun({ initials: 'OKK', score: 777 });
    const tampered = { ...makeRun({ initials: 'BAD' }), score: 1 }; // hash no longer matches
    const noInitials = makeRun();
    const junk = { id: 5 };
    const withExtra = { ...makeRun({ initials: 'XTR' }), futureField: 'x', nested: { a: 1 } };
    const s = await fresh();
    const code = SHARECODE_PREFIX + base64Encode(JSON.stringify({ v: 99, runs: [good, tampered, noInitials, junk, withExtra, 7] }));
    const res = await s.importSharecode(code);
    expect(res).toEqual({ imported: 2, skipped: 4 });
    const board = await s.getLeaderboard();
    expect(board.map((b) => b.initials).sort()).toEqual(['OKK', 'XTR']);
    expect(s.runs.every((r) => !('futureField' in r) && !('nested' in r))).toBe(true);
  });

  test('works with longer initials too', async () => {
    const s = await fresh();
    const r = makeRun();
    await s.saveRun(r);
    await s.setInitials(r.id, 'LONGNAME');
    const o = await fresh();
    await o.importSharecode(await s.exportSharecode());
    expect((await o.getLeaderboard())[0].initials).toBe('LONGNAME');
  });

  test('empty leaderboard exports a valid code that imports zero runs', async () => {
    const s = await fresh();
    const code = await s.exportSharecode();
    expect(await (await fresh()).importSharecode(code)).toEqual({ imported: 0, skipped: 0 });
  });
});

describe('IndexedDB persistence (fake indexedDB)', () => {
  let original;
  beforeEach(() => { original = Object.getOwnPropertyDescriptor(globalThis, 'indexedDB'); });
  afterEach(() => {
    if (original) Object.defineProperty(globalThis, 'indexedDB', original);
    else delete globalThis.indexedDB;
  });

  test('runs persist across SaveStore instances', async () => {
    const idb = makeFakeIndexedDB();
    globalThis.indexedDB = idb;
    const a = new SaveStore();
    await a.init();
    expect(a.backend).toBe('idb');
    const r = makeRun({ score: 4242 });
    await a.saveRun(r);
    await a.setInitials(r.id, 'XYZ');
    const b = new SaveStore();
    await b.init();
    expect(b.backend).toBe('idb');
    const board = await b.getLeaderboard();
    expect(board).toHaveLength(1);
    expect(board[0]).toMatchObject({ id: r.id, score: 4242, initials: 'XYZ' });
  });

  test('corrupt rows in the database are ignored on load', async () => {
    const idb = makeFakeIndexedDB();
    globalThis.indexedDB = idb;
    const a = new SaveStore();
    await a.init();
    const db = idb.dbs.get(STORAGE.dbName);
    db.stores.get(STORAGE.runsStore).data.set('bad', { id: 'bad', score: 'x', extra: 1 });
    db.stores.get(STORAGE.runsStore).data.set('worse', { nope: true });
    const b = new SaveStore();
    await b.init();
    expect(b.runs.map((r) => r.id)).toEqual(['bad']);
    expect(b.runs[0].score).toBe(0);
  });

  test('open errors fall back to memory without throwing', async () => {
    globalThis.indexedDB = { open() { throw new Error('SecurityError'); } };
    const s = new SaveStore();
    await expect(s.init()).resolves.toBeUndefined();
    expect(s.backend).toBe('memory');
    await s.saveRun(makeRun());
    expect(s.runs).toHaveLength(1);
  });

  test('request error falls back to memory', async () => {
    globalThis.indexedDB = {
      open() {
        const req = {};
        setTimeout(() => { req.error = new Error('boom'); req.onerror && req.onerror(); }, 0);
        return req;
      },
    };
    const s = new SaveStore();
    await s.init();
    expect(s.backend).toBe('memory');
  });

  test('a failed ID can retry the original memory record without duplicate accounting', async () => {
    const idb = makeFakeIndexedDB();
    globalThis.indexedDB = idb;
    const s = await fresh(), r = makeRun();
    const db = s._db, realTx = db.transaction;
    db.transaction = () => { throw new Error('QuotaExceeded'); };
    expect(await s.saveRun(r)).toBe('session-only');
    expect(s.getRunPersistence(r.id)).toBe('session-only');
    db.transaction = realTx;
    expect(await s.saveRun({...r, score:99999})).toBe('committed');
    expect(s.getRunPersistence(r.id)).toBe('committed');
    expect(s.runs).toHaveLength(1);
    expect((await fresh()).runs[0].score).toBe(r.score);
    expect(await s.saveRun(r)).toBe('committed');
  });

  test('concurrent duplicate and initials writes serialize; latest revision commits', async () => {
    globalThis.indexedDB = makeFakeIndexedDB();
    const s = await fresh(), r = makeRun();
    const a = s.saveRun(r), b = s.saveRun(r);
    const c = s.setInitials(r.id, 'ABC');
    expect(s.getRunPersistence(r.id)).toBe('pending');
    expect(await Promise.all([a,b,c])).toEqual(['committed','committed','committed']);
    expect(await s.whenRunSettled(r.id)).toBe('committed');
    expect((await fresh()).runs).toEqual([expect.objectContaining({id:r.id,initials:'ABC'})]);
  });

  test('new runs wait for a concurrent recovery open', async () => {
    const idb = makeFakeIndexedDB();
    globalThis.indexedDB = idb;
    const s = await fresh(), r = makeRun(), next = makeRun();
    const db = s._db, realTx = db.transaction;
    db.transaction = () => { throw new Error('QuotaExceeded'); };
    expect(await s.saveRun(r)).toBe('session-only');
    db.transaction = realTx;
    const retry = s.saveRun(r);
    await Promise.resolve();
    expect(s._initPromise).not.toBeNull();
    expect(await Promise.all([retry, s.saveRun(next)])).toEqual(['committed','committed']);
    expect((await fresh()).runs.map(x=>x.id).sort()).toEqual([r.id,next.id].sort());
  });

  test('late successful open after blocked rejection closes the abandoned connection', async () => {
    const req = {}, close = jest.fn();
    globalThis.indexedDB = {open:()=>req};
    const s = new SaveStore(), pending = s.init();
    req.onblocked();
    await pending;
    req.result = {close};
    req.onsuccess();
    expect(close).toHaveBeenCalledTimes(1);
    expect(s.backend).toBe('memory');
    expect(s._db).toBeNull();
  });

  test('a failing write switches to memory-only and does not throw', async () => {
    const idb = makeFakeIndexedDB();
    globalThis.indexedDB = idb;
    const s = new SaveStore();
    await s.init();
    s._db.transaction = () => { throw new Error('QuotaExceeded'); };
    await expect(s.saveRun(makeRun())).resolves.toBe('session-only');
    expect(s.backend).toBe('memory');
    expect(s.runs).toHaveLength(1);
  });
});

describe('chase queries (seed best, daily best, daily streak)', () => {
  const NOW = Date.parse('2025-03-10T15:00:00Z');
  const dseed = (k) => `daily-${k}`;
  // Decisions 1/2: Daily best and the streak count only OFFICIAL Daily runs (started from the DAILY RUN
  // item: v2 record with dailyOfficial, on the date's own rule and mask). These fixtures used to be any run
  // on a daily seed; they are now stamped official so the surfaces they test are still reached.
  const official = (k) => {
    const info = DailyPatch.infoForDateKey(k);
    return { hashV: 2, dailyOfficial: true, dailyRuleId: info.rule.id, ...(info.biomeMask ? { biomeMask: info.biomeMask } : {}) };
  };

  test('getSeedStats: null when none, maxima and attempts, excludeRunId', async () => {
    const s = await fresh();
    expect(s.getSeedStats('abc')).toBeNull();
    await s.saveRun(makeRun({ id: 'a', seed: 'abc', score: 500, distanceM: 100 }));
    await s.saveRun(makeRun({ id: 'b', seed: 'abc', score: 300, distanceM: 900 }));
    await s.saveRun(makeRun({ id: 'c', seed: 'other', score: 9999 }));
    expect(s.getSeedStats('abc')).toEqual({ seed: 'abc', attempts: 2, bestScore: 500, bestDistanceM: 900 });
    expect(s.getSeedStats('abc', { excludeRunId: 'a' })).toEqual({ seed: 'abc', attempts: 1, bestScore: 300, bestDistanceM: 900 });
    expect(s.getSeedStats('other', { excludeRunId: 'c' })).toBeNull();
    expect(s.getSeedStats('')).toBeNull();
  });

  test('getDailyStats uses the UTC day seed', async () => {
    const s = await fresh();
    await s.saveRun(makeRun({ id: 'd1', seed: dseed('2025-03-10'), score: 70, distanceM: 5, ...official('2025-03-10') }));
    await s.saveRun(makeRun({ id: 'd2', seed: dseed('2025-03-10'), score: 40, distanceM: 50, ...official('2025-03-10') }));
    await s.saveRun(makeRun({ id: 'd3', seed: dseed('2025-03-09'), score: 999, ...official('2025-03-09') }));
    expect(s.getDailyStats(new Date('2025-03-10T23:59:59Z'))).toEqual({
      seed: dseed('2025-03-10'), dateKey: '2025-03-10', attempts: 2, bestScore: 70, bestDistanceM: 50,
    });
    expect(s.getDailyStats(Date.parse('2025-03-11T00:00:00Z'))).toBeNull();
    expect(s.getDailyStats(NOW, { excludeRunId: 'd1' }).bestScore).toBe(40);
  });

  async function storeWith(keys) {
    const s = await fresh();
    let i = 0;
    for (const k of keys) await s.saveRun(makeRun({ id: `x${i++}`, seed: dseed(k), startedAt: 0, endedAt: 0, ...official(k) }));
    return s;
  }

  test('streak: empty store', async () => {
    const s = await fresh();
    expect(s.getDailyStreak(NOW)).toEqual({ streak: 0, playedToday: false, todayKey: '2025-03-10', lastPlayedKey: null });
  });

  test('streak: today counts, consecutive days across month boundary', async () => {
    const s = await storeWith(['2025-03-10', '2025-03-09', '2025-03-08', '2025-02-28', '2025-03-01']);
    const r = s.getDailyStreak(NOW);
    expect(r.playedToday).toBe(true);
    expect(r.streak).toBe(3);
    const s2 = await storeWith(['2025-03-01', '2025-02-28', '2025-02-27', '2025-03-02']);
    expect(s2.getDailyStreak(Date.parse('2025-03-02T01:00:00Z')).streak).toBe(4);
  });

  test('streak: ending yesterday is live, gap resets', async () => {
    const s = await storeWith(['2025-03-09', '2025-03-08']);
    expect(s.getDailyStreak(NOW)).toEqual({ streak: 2, playedToday: false, todayKey: '2025-03-10', lastPlayedKey: '2025-03-09' });
    const g = await storeWith(['2025-03-08', '2025-03-07']);
    expect(g.getDailyStreak(NOW).streak).toBe(0);
    expect(g.getDailyStreak(NOW).lastPlayedKey).toBe('2025-03-08');
    const hole = await storeWith(['2025-03-10', '2025-03-08']);
    expect(hole.getDailyStreak(NOW).streak).toBe(1);
  });

  test('streak: ignores non-daily and future seeds, accepts Date, duplicates count once', async () => {
    const s = await storeWith(['2025-03-10', '2025-03-10', '2025-03-11']);
    await s.saveRun(makeRun({ id: 'n', seed: 'daily-garbage' }));
    const r = s.getDailyStreak(new Date(NOW));
    expect(r.streak).toBe(1);
    expect(r.lastPlayedKey).toBe('2025-03-10');
  });

  test('queries do not alter stored runs or ledger hashes', async () => {
    const s = await fresh();
    const run = makeRun({ id: 'h', seed: dseed('2025-03-10') });
    await s.saveRun(run);
    s.getSeedStats(run.seed); s.getDailyStats(NOW); s.getDailyStreak(NOW);
    expect(s.runs[0].ledgerHash).toBe(SaveStore.computeLedgerHash(s.runs[0]));
  });

  test('few thousand runs stay fast', async () => {
    const s = await fresh();
    for (let i = 0; i < 5000; i++) s.runs.push(sanitizeRun(makeRun({ id: `p${i}`, seed: dseed(new Date(NOW - (i % 400) * 86400000).toISOString().slice(0, 10)) })));
    const t = Date.now();
    s.getDailyStreak(NOW); s.getSeedStats(dseed('2025-03-10')); s.getDailyStats(NOW);
    expect(Date.now() - t).toBeLessThan(200);
  });
});/**
 * ui/Scanlines.js: the menu's rolling bright band must obey REDUCE MOTION immediately, not only when its
 * 7 s pass repeats (Copilot review on PR #32). Stubs a scene just far enough for addScanlines to run and
 * captures the tween config so the test can drive onUpdate mid-pass.
 */
import { addScanlines } from '../../src/ui/Scanlines.js';
import { REG } from '../../src/constants.js';

function makeImage() {
  const img = {
    visible: true,
    scene: true,
    setOrigin() { return img; },
    setDepth() { return img; },
    setAlpha() { return img; },
    setBlendMode() { return img; },
    setVisible(v) { img.visible = v; return img; },
    once() { return img; },
    destroy() { img.scene = null; },
  };
  return img;
}

function makeScene(settings) {
  const tweens = [];
  const scene = {
    registry: { get: (k) => (k === REG.SETTINGS ? settings : undefined) },
    textures: {
      exists: () => true,
      createCanvas: () => ({ context: null, refresh() {} }),
    },
    add: { image: () => makeImage() },
    tweens: { add: (cfg) => { tweens.push(cfg); return { remove() {} }; } },
  };
  return { scene, tweens };
}

describe('scanline roll band and reduce motion', () => {
  test('turning REDUCE MOTION on mid-pass hides the band on the next update, and off shows it again', () => {
    const settings = { reduceMotion: 'off' };
    const { scene, tweens } = makeScene(settings);
    const img = addScanlines(scene, 1, { roll: true });
    const band = img.band;
    expect(band).toBeTruthy();
    expect(band.visible).toBe(true);
    const cfg = tweens.find((t) => t.targets === band);
    expect(typeof cfg.onUpdate).toBe('function');

    settings.reduceMotion = 'on';
    cfg.onUpdate();
    expect(band.visible).toBe(false);

    settings.reduceMotion = 'off';
    cfg.onUpdate();
    expect(band.visible).toBe(true);
  });

  test('the band starts hidden when reduce motion is already on', () => {
    const { scene } = makeScene({ reduceMotion: 'on' });
    const img = addScanlines(scene, 1, { roll: true });
    expect(img.band.visible).toBe(false);
  });
});import { ScoreCorrectionDraft } from '../../src/systems/music/ScoreCorrectionDraft.js';

const score=()=>({
	songId:'test-score',scoreHash:'a'.repeat(64),
	frameCount:48000*12,
	events:{
		melody:[],bass:[],drums:[{
			id:'dr-001',startFrame:24000,class:'kick',
		},{id:'dr-002',startFrame:24480,class:'snare'}],
		guitar:[{
			id:'gu-001',startFrame:24000,endFrame:36000,pitch:60,class:'note',
		},{id:'gu-002',startFrame:24480,endFrame:37000,pitch:72,class:'note'}],
		piano:[],other:[],
	},
});

describe('Non-destructive score correction draft for in-game inspector',()=>{
	test('multiple 10ms nudges and octave correction remain a single atomic operation',()=>{
		const source=score(),original=JSON.stringify(source);
		const draft=new ScoreCorrectionDraft(source);
		expect(draft.modify('gu-001','nudge',-480)).toBe(true);
		expect(draft.modify('gu-001','nudge',-480)).toBe(true);
		expect(draft.modify('gu-001','octave',12)).toBe(true);
		expect(draft.count).toBe(1);
		expect(draft.preview('gu-001')).toMatchObject({
			startFrame:23040,endFrame:35040,pitch:72,status:'correct',
		});
		const patch=draft.export();
		expect(patch).toMatchObject({
			format:'bitstream-performance-patches-v1',
			status:'draft-unreviewed-not-applied-to-audio',
			songId:source.songId,baseScoreHash:source.scoreHash,
		});
		expect(patch.operations).toEqual([{
			id:'gu-001',action:'correct',
			startFrame:23040,endFrame:35040,pitch:72,
		}]);
		expect(JSON.stringify(source)).toBe(original);
	});
	test('clamping negative samples, releases, and overrange pitches',()=>{
		const draft=new ScoreCorrectionDraft(score());
		expect(draft.modify('gu-001','nudge',-4800)).toBe(true);
		expect(draft.modify('gu-001','nudge',-4800)).toBe(true);
		expect(draft.modify('gu-001','nudge',-4800)).toBe(true);
		expect(draft.modify('gu-001','nudge',-4800)).toBe(true);
		expect(draft.modify('gu-001','nudge',-4800)).toBe(true);
		expect(draft.modify('gu-001','nudge',-480)).toBe(false);
		expect(draft.modify('gu-001','octave',12)).toBe(true);
		expect(draft.modify('gu-001','octave',12)).toBe(true);
		expect(draft.modify('gu-001','octave',12)).toBe(true);
		expect(draft.modify('gu-001','octave',12)).toBe(true);
		expect(draft.modify('gu-001','octave',12)).toBe(true);
		expect(draft.modify('gu-001','octave',12)).toBe(false);
		expect(draft.preview('gu-001').pitch).toBe(120);
	});
	test('refuses a draft that would move attacks across adjacent original notes',()=>{
		const draft=new ScoreCorrectionDraft(score());
		// Guitar notes are 10ms apart; the first may meet the second but
		// cannot overtake it without a coordinated chord/group correction.
		expect(draft.modify('gu-001','nudge',480)).toBe(true);
		expect(draft.modify('gu-001','nudge',480)).toBe(false);
		expect(draft.preview('gu-001').startFrame).toBe(24480);
		expect(draft.count).toBe(1);
		// Drums may coincide, but cannot reorder the source class sequence.
		expect(draft.modify('dr-001','nudge',480)).toBe(true);
		expect(draft.modify('dr-001','nudge',480)).toBe(false);
		// The patch remains exactly one valid correction for each role.
		expect(draft.export().operations).toHaveLength(2);
	});
	test('drum class is immutable; simultaneous hit timing only',()=>{
		const draft=new ScoreCorrectionDraft(score());
		expect(draft.modify('dr-001','octave',12)).toBe(false);
		expect(draft.modify('dr-001','nudge',480)).toBe(true);
		expect(draft.preview('dr-001')).toMatchObject({
			startFrame:24480,class:'kick',status:'correct',
		});
		expect(draft.export().operations).toEqual([{
			id:'dr-001',action:'correct',startFrame:24480,
		}]);
	});
	test('revert any event, remove draft when it returns to source',()=>{
		const draft=new ScoreCorrectionDraft(score());
		expect(draft.export()).toBe(null);
		expect(draft.modify('gu-001','nudge',480)).toBe(true);
		expect(draft.modify('gu-001','nudge',-480)).toBe(true);
		expect(draft.count).toBe(0);
		draft.modify('gu-001','accept');
		expect(draft.preview('gu-001').status).toBe('accept');
		expect(draft.modify('gu-001','undo')).toBe(true);
		expect(draft.export()).toBe(null);
	});
	test('reject one event but never touch its neighbor or original',()=>{
		const source=score();
		const draft=new ScoreCorrectionDraft(source);
		expect(draft.modify('gu-001','reject')).toBe(true);
		expect(draft.preview('gu-001').status).toBe('reject');
		expect(draft.preview('gu-002').status).toBe('source-candidate');
		expect(source.events.guitar).toHaveLength(2);
		expect(draft.export().operations[0]).toEqual({
			action:'reject',id:'gu-001',
		});
	});
	test('wrong event ID or unknown action is rejected',()=>{
		const draft=new ScoreCorrectionDraft(score());
		expect(draft.modify('gu-wrong','accept')).toBe(false);
		expect(draft.modify('gu-001','random')).toBe(false);
		expect(draft.count).toBe(0);
	});
	test('different score revisions cannot reuse source drafts',()=>{
		const a=new ScoreCorrectionDraft(score());
		a.modify('gu-001','reject');
		const other=score();other.scoreHash='b'.repeat(64);
		const b=new ScoreCorrectionDraft(other);
		expect(b.count).toBe(0);
		expect(a.export().baseScoreHash).not.toBe(b.scoreHash);
	});
});import { ScoreManager, rotationFactor, airtimeFactor, comboName, milestoneBonus } from '../../src/systems/ScoreManager.js';
import { TrickTracker } from '../../src/systems/TrickTracker.js';
import { SCORING } from '../../src/constants.js';

const trick = (type, count = 1, airtimeMs = 0) => ({ type, count, rotationDeg: count * 360, airtimeMs });

describe('ScoreManager distance', () => {
  test('+1 point per whole metre, monotonic', () => {
    const s = new ScoreManager();
    expect(s.getSnapshot().total).toBe(0);
    expect(s.setDistance(0.5)).toBe(false);
    expect(s.setDistance(1.2)).toBe(true);
    expect(s.setDistance(1.9)).toBe(false);
    expect(s.setDistance(10)).toBe(true);
    expect(s.setDistance(4)).toBe(false); // never goes backwards
    const snap = s.getSnapshot();
    expect(snap.distanceM).toBe(10);
    expect(snap.distancePoints).toBe(10);
    expect(snap.total).toBe(10);
  });
});

describe('ScoreManager tricks and combo', () => {
  test('trick value = base x rotation x airtime modifier', () => {
    const s = new ScoreManager();
    const r = s.addTrick(trick('backflip', 1, 0));
    expect(r.value).toBe(SCORING.trickBase.backflip * rotationFactor(1) * airtimeFactor(0));
    expect(r.isNew).toBe(true);
    const s2 = new ScoreManager();
    const long = s2.addTrick(trick('backflip', 1, 2500));
    expect(long.value).toBe(SCORING.trickBase.backflip * 2); // airtime factor tops out at 2
    expect(long.value).toBeGreaterThan(r.value);
  });

  test('rotation factor grows exponentially; airtime factor is clamped to 1..2', () => {
    expect(rotationFactor(1)).toBe(1);
    expect(rotationFactor(2)).toBe(3);
    expect(rotationFactor(3)).toBe(7);
    expect(rotationFactor(0)).toBe(1);
    expect(airtimeFactor(-10)).toBe(1);
    expect(airtimeFactor(1250)).toBeCloseTo(1.5);
    expect(airtimeFactor(99999)).toBe(2);
  });

  test('unknown trick types are worth nothing but do not throw', () => {
    const s = new ScoreManager();
    expect(s.addTrick(trick('nope')).value).toBe(0);
  });

  test('combo starts x1 and gains +0.25 per UNIQUE trick', () => {
    const s = new ScoreManager();
    expect(s.getMultiplier()).toBe(1);
    expect(s.addTrick(trick('backflip')).multiplier).toBe(1.25);
    expect(s.addTrick(trick('frontflip')).multiplier).toBe(1.5);
    // air brake keeps its points but no longer steps the multiplier (flips and helis are the stars)
    expect(s.addTrick(trick('airBrake')).multiplier).toBe(1.5);
    expect(s.addTrick(trick('helicopterCW')).multiplier).toBe(1.75);
    expect(s.getSnapshot().comboTricks).toEqual(['backflip', 'frontflip', 'airBrake', 'helicopterCW']);
  });

  test('repeating the same trick type does not raise the multiplier and is not flagged new', () => {
    const s = new ScoreManager();
    s.addTrick(trick('backflip', 1));
    const again = s.addTrick(trick('backflip', 2));
    expect(again.isNew).toBe(false);
    expect(again.multiplier).toBe(1.25);
    expect(s.getSnapshot().comboTricks).toEqual(['backflip']);
  });

  test('cumulative double-flip events pay only the increase (never double count)', () => {
    const s = new ScoreManager();
    const a = s.addTrick(trick('backflip', 1, 800));
    const b = s.addTrick(trick('backflip', 2, 800));
    const total = SCORING.trickBase.backflip * rotationFactor(2) * airtimeFactor(800);
    expect(a.value + b.value).toBeCloseTo(total, 0);
    expect(s.getSnapshot().pendingPoints).toBeCloseTo(total, 0);
    expect(b.value).toBeGreaterThan(a.value);
  });

  test('tricks are provisional: nothing banked until landing', () => {
    const s = new ScoreManager();
    s.addTrick(trick('backflip'));
    const snap = s.getSnapshot();
    expect(snap.trickPoints).toBe(0);
    expect(snap.pendingPoints).toBeGreaterThan(0);
    expect(snap.total).toBe(0);
  });

  test('landing banks pending x multiplier and resets the combo', () => {
    const s = new ScoreManager();
    s.addTrick(trick('backflip'));
    s.addTrick(trick('airBrake'));
    const pending = s.getSnapshot().pendingPoints;
    const r = s.onLanding({ quality: 'good' });
    expect(r.multiplierUsed).toBe(1.25);
    // the first clean trick landing already pays its own flow gain (good = +0.15)
    expect(r.flowUsed).toBe(1.15);
    expect(r.banked).toBe(Math.round(pending * 1.25 * 1.15));
    expect(r.bonus).toBe(0);
    const snap = s.getSnapshot();
    expect(snap.trickPoints).toBe(r.banked);
    expect(snap.multiplier).toBe(1);
    expect(snap.comboTricks).toEqual([]);
    expect(snap.pendingPoints).toBe(0);
    expect(snap.bestCombo).toBe(1.25);
  });

  test('perfect landing adds +20 flat (not multiplied), even with no tricks', () => {
    const s = new ScoreManager();
    expect(s.onLanding({ quality: 'perfect' })).toMatchObject({ banked: 0, bonus: 20, multiplierUsed: 1 });
    expect(s.getSnapshot().total).toBe(20);
    s.addTrick(trick('frontflip'));
    s.addTrick(trick('parachute'));
    const r = s.onLanding({ quality: 'perfect' });
    expect(r.bonus).toBe(SCORING.perfectLandingBonus);
    expect(s.getSnapshot().trickPoints).toBe(20 + r.banked + 20);
  });

  test('sloppy/good landings bank but give no bonus', () => {
    for (const q of ['good', 'sloppy']) {
      const s = new ScoreManager();
      s.addTrick(trick('backflip'));
      const r = s.onLanding({ quality: q });
      expect(r.bonus).toBe(0);
      expect(r.banked).toBeGreaterThan(0);
    }
  });

  test('crash landing forfeits the pending combo (no points, no bonus)', () => {
    const s = new ScoreManager();
    s.addTrick(trick('backflip', 2));
    s.addTrick(trick('frontflip'));
    const r = s.onLanding({ quality: 'crash' });
    expect(r.banked).toBe(0);
    expect(r.bonus).toBe(0);
    const snap = s.getSnapshot();
    expect(snap.trickPoints).toBe(0);
    expect(snap.pendingPoints).toBe(0);
    expect(snap.multiplier).toBe(1);
  });

  test('onCrash discards pending tricks but keeps banked points and distance', () => {
    const s = new ScoreManager();
    s.setDistance(50);
    s.addTrick(trick('backflip'));
    s.onLanding({ quality: 'good' });
    const banked = s.getSnapshot().trickPoints;
    s.addTrick(trick('frontflip'));
    s.onCrash();
    const snap = s.getSnapshot();
    expect(snap.trickPoints).toBe(banked);
    expect(snap.pendingPoints).toBe(0);
    expect(snap.total).toBe(50 + banked);
  });

  test('a new combo after landing starts from scratch (paid ledger cleared)', () => {
    const s = new ScoreManager();
    const a = s.addTrick(trick('backflip', 1, 0));
    s.onLanding({ quality: 'good' });
    const b = s.addTrick(trick('backflip', 1, 0));
    expect(b.value).toBe(a.value);
    expect(b.isNew).toBe(true);
  });

  test('bestCombo tracks the highest multiplier of the run', () => {
    const s = new ScoreManager();
    s.addTrick(trick('backflip'));
    s.addTrick(trick('frontflip'));
    s.addTrick(trick('helicopterCW'));
    s.addTrick(trick('helicopterCCW'));
    s.onLanding({ quality: 'good' });
    s.addTrick(trick('backflip'));
    expect(s.getSnapshot().bestCombo).toBe(2);
  });
});

describe('ScoreManager reset penalty and reset()', () => {
  test('Shift reset drops the combo and deducts points, total never negative', () => {
    const s = new ScoreManager();
    s.setDistance(30);
    s.addTrick(trick('backflip'));
    s.addTrick(trick('frontflip'));
    const r = s.penalizeReset();
    expect(r.comboPenalty).toBe(2);
    expect(r.pointsLost).toBe(30); // only had 30 points
    const snap = s.getSnapshot();
    expect(snap.total).toBe(0);
    expect(snap.comboTricks).toEqual([]);
    expect(snap.pendingPoints).toBe(0);
    s.setDistance(500);
    expect(s.getSnapshot().total).toBe(500 - 30);
    expect(s.penalizeReset().pointsLost).toBe(SCORING.resetPenaltyPoints);
    expect(s.getSnapshot().total).toBe(500 - 30 - SCORING.resetPenaltyPoints);
  });

  test('penalty with zero score is free and never goes negative', () => {
    const s = new ScoreManager();
    expect(s.penalizeReset()).toMatchObject({ comboPenalty: 0, pointsLost: 0 });
    expect(s.getSnapshot().total).toBe(0);
  });

  test('reset() clears everything', () => {
    const s = new ScoreManager();
    s.setDistance(100);
    s.addTrick(trick('backflip'));
    s.onLanding({ quality: 'perfect' });
    s.penalizeReset();
    s.reset();
    expect(s.getSnapshot()).toEqual({
      total: 0, distancePoints: 0, trickPoints: 0, distanceM: 0, multiplier: 1, comboTricks: [], pendingPoints: 0,
      bestCombo: 1, penaltyPoints: 0, bonusPoints: 0, shards: 0, nearMisses: 0, milestones: 0,
      bonusByKind: { shard: 0, nearMiss: 0, milestone: 0 },
      comboCounts: {}, flow: 1, flowTimeoutFrac: 0, bestFlow: 1,
    });
  });

  test('snapshot comboTricks is a copy', () => {
    const s = new ScoreManager();
    s.addTrick(trick('backflip'));
    s.getSnapshot().comboTricks.push('x');
    expect(s.getSnapshot().comboTricks).toEqual(['backflip']);
  });
});

describe('ScoreManager bonuses (shards / near misses / milestones)', () => {
  test('addBonus adds immediately to the total and tracks per-kind counts and points', () => {
    const s = new ScoreManager();
    s.setDistance(10);
    let snap = s.addBonus(25, 'shard');
    expect(snap.total).toBe(35);
    expect(snap.bonusPoints).toBe(25);
    expect(snap.shards).toBe(1);
    expect(snap.trickPoints).toBe(0);
    s.addBonus(25, 'shard');
    s.addBonus(100, 'nearMiss');
    snap = s.addBonus(500, 'milestone');
    expect(snap.shards).toBe(2);
    expect(snap.nearMisses).toBe(1);
    expect(snap.milestones).toBe(1);
    expect(snap.bonusPoints).toBe(650);
    expect(snap.bonusByKind).toEqual({ shard: 50, nearMiss: 100, milestone: 500 });
    expect(snap.total).toBe(10 + 650);
  });

  test('bonuses are not part of the pending combo, are not multiplied, and survive crash / reset penalties', () => {
    const s = new ScoreManager();
    s.addTrick(trick('backflip'));
    s.addTrick(trick('frontflip'));
    s.addBonus(40, 'shard');
    expect(s.getSnapshot().pendingPoints).toBe(s.pending);
    const before = s.getSnapshot().pendingPoints;
    s.onLanding({ quality: 'crash' });
    expect(s.getSnapshot().bonusPoints).toBe(40);
    expect(s.getSnapshot().total).toBe(40);
    s.addTrick(trick('backflip'));
    s.onLanding({ quality: 'good' });
    const t = s.getSnapshot().total;
    expect(t).toBeGreaterThan(40);
    expect(before).toBeGreaterThan(0);
    s.penalizeReset();
    expect(s.getSnapshot().bonusPoints).toBe(40);
  });

  test('bad input is sanitised: rounded, negatives / NaN count as 0, unknown kinds add points but no counts', () => {
    const s = new ScoreManager();
    expect(s.addBonus(10.6, 'shard').bonusPoints).toBe(11);
    expect(s.addBonus(-5, 'shard').bonusPoints).toBe(11);
    expect(s.addBonus(NaN, 'nearMiss').bonusPoints).toBe(11);
    const snap = s.addBonus(7, 'weird');
    expect(snap.bonusPoints).toBe(18);
    expect(snap.shards).toBe(2);
    expect(snap.nearMisses).toBe(1);
  });

  test('reset clears bonuses', () => {
    const s = new ScoreManager();
    s.addBonus(50, 'milestone');
    s.reset();
    const snap = s.getSnapshot();
    expect(snap.bonusPoints).toBe(0);
    expect(snap.milestones).toBe(0);
    expect(snap.total).toBe(0);
  });
});

/** One jump: perform tricks, land with the given quality. */
function jump(s, quality, types = ['backflip']) {
  for (const t of types) s.addTrick(trick(t));
  return s.onLanding({ quality });
}

describe('flow streak', () => {
  test('starts at x1.0 and gains +0.25 perfect / +0.15 good, capped at x3.0', () => {
    const s = new ScoreManager();
    expect(s.getFlow()).toBe(1);
    expect(SCORING.flowPerfectStep).toBe(0.25);
    expect(SCORING.flowGoodStep).toBe(0.15);
    expect(SCORING.flowTimeoutMs).toBe(9000);
    expect(jump(s, 'perfect').flowChange).toMatchObject({ changed: true, previous: 1, flow: 1.25, reason: 'gain' });
    jump(s, 'good');
    expect(s.getFlow()).toBe(1.4);
    for (let i = 0; i < 30; i++) jump(s, 'perfect');
    expect(s.getFlow()).toBe(SCORING.flowMax);
    expect(s.getFlow()).toBe(3);
    expect(s.getSnapshot().bestFlow).toBe(SCORING.flowMax);
  });

  test('x2 is reachable: four perfect flip landings', () => {
    const s = new ScoreManager();
    for (let i = 0; i < 4; i++) jump(s, 'perfect');
    expect(s.getFlow()).toBe(2);
  });

  test('landings without a combo-step trick do not build flow (none, air brake or parachute alone)', () => {
    for (const types of [[], ['airBrake'], ['parachute'], ['airBrake', 'parachute']]) {
      const s = new ScoreManager();
      const r = jump(s, 'perfect', types);
      expect(r.flowChange.changed).toBe(false);
      expect(s.getFlow()).toBe(1);
    }
    // a helicopter or a frontflip does
    expect(jump(new ScoreManager(), 'good', ['helicopterCW']).flowChange.reason).toBe('gain');
    expect(jump(new ScoreManager(), 'good', ['frontflip', 'airBrake']).flowChange.reason).toBe('gain');
  });

  test('ANY good or perfect landing refreshes the timeout, tricks or not; sloppy does not', () => {
    const s = new ScoreManager();
    jump(s, 'good');
    s.tick(SCORING.flowTimeoutMs - 1000);
    expect(s.getFlowTimeoutFraction()).toBeCloseTo(1000 / SCORING.flowTimeoutMs, 5);
    s.onLanding({ quality: 'good' }); // no tricks at all
    expect(s.getFlowTimeoutFraction()).toBe(1);
    s.tick(5000);
    jump(s, 'perfect', ['airBrake']); // air brake only: no gain, but the clean landing keeps the streak alive
    expect(s.getFlow()).toBe(1.15);
    expect(s.getFlowTimeoutFraction()).toBe(1);
    s.tick(5000);
    s.onLanding({ quality: 'sloppy' });
    expect(s.getFlowTimeoutFraction()).toBeCloseTo(4000 / SCORING.flowTimeoutMs, 5);
  });

  test('the landing that gains flow pays at the NEW flow (first clean trick landing already pays)', () => {
    const s = new ScoreManager();
    s.addTrick(trick('backflip'));
    const pending = s.getSnapshot().pendingPoints;
    const r = s.onLanding({ quality: 'perfect' });
    expect(r.flowUsed).toBe(1.25);
    expect(r.banked).toBe(Math.round(pending * 1.25 * 1.25));
    expect(r.bonus).toBe(SCORING.perfectLandingBonus); // flat, never multiplied
    // a landing that gains nothing pays at the carried-in flow
    s.addTrick(trick('airBrake'));
    const p2 = s.getSnapshot().pendingPoints;
    const r2 = s.onLanding({ quality: 'good' });
    expect(r2.flowUsed).toBe(1.25);
    expect(r2.banked).toBe(Math.round(p2 * 1.25));
  });

  test('sloppy landing halves the bonus above 1.0 (paid at the carried-in flow) and does not refresh the timeout', () => {
    const s = new ScoreManager();
    for (let i = 0; i < 4; i++) jump(s, 'perfect'); // 2.0
    s.tick(3000);
    s.addTrick(trick('backflip'));
    const pending = s.getSnapshot().pendingPoints;
    const r = s.onLanding({ quality: 'sloppy' });
    expect(r.flowChange).toMatchObject({ reason: 'halved', previous: 2, flow: 1.5, lost: false });
    expect(r.flowUsed).toBe(2);
    expect(r.banked).toBe(Math.round(pending * 1.25 * 2));
    expect(s.getFlowTimeoutFraction()).toBeCloseTo(6000 / SCORING.flowTimeoutMs, 5);
    const none = new ScoreManager();
    expect(jump(none, 'sloppy').flowChange.changed).toBe(false);
  });

  test('halving that leaves a bonus below flowClearBelow clears flow (sloppy landing and shield hit); exact 1.0 is lost', () => {
    const a = new ScoreManager();
    a.flow = 1.08; // bonus 0.08 -> halves to 0.04 < flowClearBelow
    a.flowRemainingMs = 5000;
    a.addTrick(trick('backflip'));
    const r = a.onLanding({ quality: 'sloppy' });
    expect(r.flowChange).toMatchObject({ lost: true, reason: 'halved', previous: 1.08, flow: 1 });
    expect(a.getFlow()).toBe(1);
    expect(a.getFlowTimeoutFraction()).toBe(0);
    const b = new ScoreManager();
    b.flow = 1.04;
    b.flowRemainingMs = 5000;
    expect(b.onShieldHit()).toMatchObject({ lost: true, reason: 'halved', flow: 1 });
    expect(b.flowRemainingMs).toBe(0);
    const c = new ScoreManager();
    c.flow = 1.1;
    expect(c.onShieldHit()).toMatchObject({ lost: false, flow: 1.05 });
    const d = new ScoreManager();
    d.flow = 1.2;
    const ch = d._setFlow(1, 'x');
    expect(ch).toMatchObject({ lost: true, flow: 1 });
    expect(d.flowRemainingMs).toBe(0);
  });

  test('a sloppy landing with zero tricks does not halve flow', () => {
    const s = new ScoreManager();
    for (let i = 0; i < 4; i++) jump(s, 'perfect'); // 2.0
    const r = jump(s, 'sloppy', []);
    expect(r.flowChange.changed).toBe(false);
    expect(s.getFlow()).toBe(2);
  });

  test('crash, crash landing and Shift reset clear flow', () => {
    const build = () => {
      const s = new ScoreManager();
      for (let i = 0; i < 3; i++) jump(s, 'perfect');
      return s;
    };
    let s = build();
    expect(s.onCrash()).toMatchObject({ lost: true, reason: 'crash', previous: 1.75, flow: 1 });
    s = build();
    expect(s.onLanding({ quality: 'crash' }).flowChange).toMatchObject({ lost: true, reason: 'crash' });
    s = build();
    expect(s.penalizeReset().flowChange).toMatchObject({ lost: true, reason: 'reset' });
    expect(s.getFlow()).toBe(1);
    expect(s.onCrash().lost).toBe(false); // nothing left to lose
  });

  test('timeout halves the bonus above 1.0 and restarts the timer; clears (lost) when the bonus falls below 0.05', () => {
    const s = new ScoreManager();
    for (let i = 0; i < 4; i++) jump(s, 'perfect'); // 2.0
    expect(s.tick(SCORING.flowTimeoutMs - 1)).toMatchObject({ changed: false, lost: false });
    const h1 = s.tick(1);
    expect(h1).toMatchObject({ changed: true, lost: false, reason: 'timeout', previous: 2, flow: 1.5, timeoutFrac: 1 });
    expect(s.getFlowTimeoutFraction()).toBe(1); // timer restarted
    expect(s.tick(SCORING.flowTimeoutMs)).toMatchObject({ lost: false, reason: 'timeout', previous: 1.5, flow: 1.25 });
    expect(s.tick(SCORING.flowTimeoutMs)).toMatchObject({ lost: false, reason: 'timeout', flow: 1.13 });
    expect(s.tick(SCORING.flowTimeoutMs)).toMatchObject({ lost: false, reason: 'timeout', flow: 1.07 });
    const gone = s.tick(SCORING.flowTimeoutMs);
    expect(gone).toMatchObject({ lost: true, reason: 'timeout', previous: 1.07, flow: 1 });
    expect(s.getFlowTimeoutFraction()).toBe(0);
    expect(s.tick(99999)).toMatchObject({ lost: false, changed: false });
  });

  test('a clean landing after a timeout halving rebuilds from the halved value', () => {
    const s = new ScoreManager();
    for (let i = 0; i < 4; i++) jump(s, 'perfect');
    s.tick(SCORING.flowTimeoutMs); // 1.5
    jump(s, 'perfect');
    expect(s.getFlow()).toBe(1.75);
    expect(s.getFlowTimeoutFraction()).toBe(1);
  });

  test('onShieldHit halves the flow bonus and keeps the pending combo (or drops it on request)', () => {
    const s = new ScoreManager();
    for (let i = 0; i < 4; i++) jump(s, 'perfect'); // 2.0
    s.addTrick(trick('backflip', 1, 500));
    const pending = s.getSnapshot().pendingPoints;
    expect(s.onShieldHit()).toMatchObject({ changed: true, lost: false, reason: 'halved', previous: 2, flow: 1.5 });
    expect(s.getSnapshot()).toMatchObject({ pendingPoints: pending, comboTricks: ['backflip'], flow: 1.5 });
    expect(s.onShieldHit(true).flow).toBe(1.25);
    expect(s.getSnapshot()).toMatchObject({ pendingPoints: 0, comboTricks: [] });
    expect(new ScoreManager().onShieldHit()).toMatchObject({ changed: false, lost: false, reason: 'none' });
  });

  test('shield-absorbed mid-air hit: later flips are paid once, never re-paid at full cumulative value', () => {
    const s = new ScoreManager();
    // jump: a backflip is finished, then a hazard hit is absorbed by the shield, then the SECOND turn completes
    const a = s.addTrick(trick('backflip', 1, 600));
    s.onShieldHit();
    const b = s.addTrick(trick('backflip', 2, 900));
    const worth = SCORING.trickBase.backflip * rotationFactor(2) * airtimeFactor(900);
    expect(a.value + b.value).toBeCloseTo(worth, 0);
    expect(s.getSnapshot().pendingPoints).toBe(a.value + b.value);
    expect(s.getSnapshot().comboTricks).toEqual(['backflip']);
    const r = s.onLanding({ quality: 'good' });
    expect(r.banked).toBe(Math.round((a.value + b.value) * 1.25 * r.flowUsed));
    // the old behaviour (onCrash on a shield hit) wiped `paid`, so the second event re-paid the whole worth
    const bad = new ScoreManager();
    bad.addTrick(trick('backflip', 1, 600));
    bad.onCrash();
    const re = bad.addTrick(trick('backflip', 2, 900));
    expect(re.value).toBeCloseTo(worth, 0);
    expect(b.value).toBeLessThan(re.value);
  });

  test('REAL tracker + score: backflip, shield-absorbed hit mid-air (tracker not flagged crashed), second backflip, clean landing', () => {
    const s = new ScoreManager();
    const tracker = new TrickTracker();
    let t = 0;
    let angle = 0;
    const events = [];
    const feed = (o) => {
      t += 16;
      angle += o.dAngle || 0;
      const upd = tracker.update({
        timeMs: t, dtMs: 16, x: 0, y: 0, vx: 400, vy: 0, angularVelDegS: 0, groundAngleDeg: 0, crashed: false,
        grounded: !!o.grounded, angleDeg: angle, input: { heli: 0, airBrake: false, parachute: false },
      });
      for (const tr of upd.tricks) events.push({ kind: 'trick', value: s.addTrick(tr).value, count: tr.count, air: tr.airtimeMs });
      if (upd.landing) events.push({ kind: 'landing', ...s.onLanding({ ...upd.landing, quality: 'good' }) });
    };
    feed({ grounded: true });
    for (let i = 0; i < 70; i++) feed({ dAngle: i < 60 ? -6 : 0 }); // first backflip
    s.onShieldHit(); // the hit is absorbed: scene feeds the tracker an UNFLAGGED frame, sled keeps flying
    for (let i = 0; i < 70; i++) feed({ dAngle: i < 60 ? -6 : 0 }); // second backflip
    expect(events.filter((e) => e.kind === 'landing')).toHaveLength(0);
    for (let i = 0; i < 5; i++) feed({ grounded: true });
    const tricks = events.filter((e) => e.kind === 'trick');
    const landings = events.filter((e) => e.kind === 'landing');
    expect(tricks.map((e) => e.count)).toEqual([1, 2]); // never counted from 1 again
    expect(landings).toHaveLength(1);
    const paid = tricks[0].value + tricks[1].value;
    const worthAt = (air) => SCORING.trickBase.backflip * rotationFactor(2) * airtimeFactor(air);
    // two flips are paid once in total: about one double-flip's worth, not a double flip plus a re-paid single
    expect(paid).toBeGreaterThanOrEqual(worthAt(tricks[0].air) - 1);
    expect(paid).toBeLessThanOrEqual(worthAt(tricks[1].air) + 1);
    expect(landings[0].banked).toBe(Math.round(paid * 1.25 * landings[0].flowUsed));
    expect(s.getSnapshot()).toMatchObject({ pendingPoints: 0, comboTricks: [] });
    expect(s.getSnapshot().trickPoints).toBe(landings[0].banked);
  });

  test('best flow survives loss, reset() clears everything, snapshot exposes flow fields', () => {
    const s = new ScoreManager();
    jump(s, 'perfect');
    jump(s, 'perfect');
    const snap = s.getSnapshot();
    expect(snap).toMatchObject({ flow: 1.5, bestFlow: 1.5, flowTimeoutFrac: 1 });
    s.onCrash();
    expect(s.getSnapshot()).toMatchObject({ flow: 1, bestFlow: 1.5 });
    s.reset();
    expect(s.getSnapshot()).toMatchObject({ flow: 1, bestFlow: 1 });
  });

  test('flow does not touch distance or flat bonuses', () => {
    const s = new ScoreManager();
    for (let i = 0; i < 5; i++) jump(s, 'perfect');
    s.setDistance(10);
    s.addBonus(25, 'shard');
    const snap = s.getSnapshot();
    expect(snap.distancePoints).toBe(10);
    expect(snap.bonusPoints).toBe(25);
  });

  test('flow share: a run of clean trick landings pays clearly more with flow than without', () => {
    const s = new ScoreManager();
    let withoutFlow = 0;
    for (let i = 0; i < 8; i++) {
      s.addTrick(trick('backflip', 1, 800));
      const pending = s.getSnapshot().pendingPoints;
      const r = s.onLanding({ quality: i % 2 ? 'good' : 'perfect' });
      withoutFlow += Math.round(pending * 1.25) + r.bonus;
    }
    expect(s.getSnapshot().trickPoints).toBeGreaterThan(withoutFlow * 1.4);
  });
});

describe('unique-trick combo step', () => {
  test('air brake and parachute keep base points but do not step; isNew reflects stepping', () => {
    const s = new ScoreManager();
    const ab = s.addTrick(trick('airBrake'));
    expect(ab.value).toBe(SCORING.trickBase.airBrake);
    expect(ab.isNew).toBe(false);
    expect(s.addTrick(trick('parachute')).multiplier).toBe(1);
    expect(s.addTrick(trick('helicopterCCW')).isNew).toBe(true);
    expect(s.getMultiplier()).toBe(1.25);
    expect(s.getSnapshot().comboTricks).toEqual(['airBrake', 'parachute', 'helicopterCCW']);
  });
});

describe('comboName', () => {
  test('names from type strings and {type,count} objects', () => {
    expect(comboName([{ type: 'backflip', count: 2 }, { type: 'helicopterCW', count: 1 }])).toBe('DOUBLE BACKFLIP + HELI');
    expect(comboName([{ type: 'frontflip', count: 3 }])).toBe('TRIPLE FRONTFLIP');
    expect(comboName(['backflip', 'airBrake'])).toBe('BACKFLIP + AIR BRAKE');
    expect(comboName(['airBrake', 'backflip'])).toBe('BACKFLIP + AIR BRAKE'); // stable order
    expect(comboName([{ type: 'backflip', count: 5 }])).toBe('5X BACKFLIP');
    expect(comboName(['helicopterCW', 'helicopterCCW'])).toBe('DOUBLE HELI');
    expect(comboName([])).toBe('');
    expect(comboName(['nope'])).toBe('');
  });

  test('degrades to short names then N-TRICK COMBO, always within the cap', () => {
    expect(comboName([{ type: 'backflip', count: 2 }, 'helicopterCW', 'parachute'])).toBe('4-TRICK COMBO');
    expect(comboName([{ type: 'backflip', count: 2 }, 'helicopterCW', 'parachute'], 32)).toBe('DOUBLE BACKFLIP + HELI + CHUTE');
    expect(comboName(['backflip', 'helicopterCW', 'parachute'])).toBe('BACKFLIP + HELI + PARACHUTE');
    expect(comboName([{ type: 'backflip', count: 2 }, 'helicopterCW', 'parachute'], 40)).toBe(
      'DOUBLE BACKFLIP + HELI + PARACHUTE',
    );
    const big = comboName([
      { type: 'backflip', count: 2 }, { type: 'frontflip', count: 1 }, { type: 'helicopterCW', count: 2 }, 'airBrake',
    ]);
    expect(big).toBe('6-TRICK COMBO');
    for (const names of [['backflip', 'frontflip', 'helicopterCW', 'airBrake', 'parachute'], [{ type: 'backflip', count: 8 }]]) {
      expect(comboName(names).length).toBeLessThanOrEqual(SCORING.comboNameMaxChars);
    }
    expect(comboName(['backflip', 'frontflip', 'helicopterCW', 'airBrake', 'parachute'])).toBe('5-TRICK COMBO');
  });

  test('ScoreManager exposes the pending name and returns it from onLanding', () => {
    const s = new ScoreManager();
    s.addTrick(trick('backflip', 1));
    s.addTrick(trick('backflip', 2));
    s.addTrick(trick('helicopterCW', 1));
    expect(s.getComboName()).toBe('DOUBLE BACKFLIP + HELI');
    expect(s.getSnapshot().comboCounts).toEqual({ backflip: 2, helicopterCW: 1 });
    expect(s.onLanding({ quality: 'good' }).comboName).toBe('DOUBLE BACKFLIP + HELI');
    expect(s.getComboName()).toBe('');
  });
});

describe('milestone bonus', () => {
  test('milestoneBonus = 100 x min(sector, 10): linear, capped at 1000', () => {
    expect(milestoneBonus(1)).toBe(100);
    expect(milestoneBonus(4)).toBe(400);
    expect(milestoneBonus(10)).toBe(1000);
    expect(milestoneBonus(11)).toBe(1000);
    expect(milestoneBonus(40)).toBe(1000);
    expect(milestoneBonus(0)).toBe(0);
    expect(milestoneBonus(NaN)).toBe(0);
  });

  test('checkMilestones pays each 500 m once, catches up skipped sectors, and counts as a milestone bonus', () => {
    const s = new ScoreManager();
    expect(s.checkMilestones(499.9)).toEqual([]);
    expect(s.checkMilestones(500)).toEqual([{ sector: 1, points: 100, distanceM: 500 }]);
    expect(s.checkMilestones(520)).toEqual([]);
    const jumped = s.checkMilestones(1600);
    expect(jumped.map((m) => m.sector)).toEqual([2, 3]);
    expect(s.checkMilestones(1600)).toEqual([]);
    const snap = s.getSnapshot();
    expect(snap.milestones).toBe(3);
    expect(snap.bonusByKind.milestone).toBe(600);
    s.reset();
    expect(s.checkMilestones(500)).toHaveLength(1);
  });

  test('milestone pay-out is linear then flat: 5 km pays 5500 in total, 10 km 15500 (the old 100 x sector would pay 21000)', () => {
    const s = new ScoreManager();
    s.checkMilestones(5000); // sectors 1..10
    expect(s.getSnapshot().bonusByKind.milestone).toBe(5500);
    s.checkMilestones(10000); // sectors 11..20 at 1000 each
    expect(s.getSnapshot().bonusByKind.milestone).toBe(15500);
  });
});

describe('ScoreManager echo zone (W3)', () => {
  // Crystal Cavern's signature mechanic: tricks landed inside an echo zone score a combo bonus. It is
  // the one batch-1 mechanic that is scoring rather than physics, so it gets its own tests here.
  const landed = (zoneScoreMul) => {
    const s = new ScoreManager();
    s.addTrick(trick('backflip', 1, 0));
    return { s, r: s.onLanding({ quality: 'good' }, { zoneScoreMul }) };
  };

  test('multiplies banked trick points', () => {
    const plain = landed(1).r;
    const echo = landed(1.3).r;
    expect(echo.banked).toBe(Math.round(plain.banked * 1.3));
    expect(echo.zoneMul).toBe(1.3);
    expect(plain.zoneMul).toBe(1);
  });

  test('leaves the perfect-landing flat bonus alone', () => {
    // The flat bonus is deliberately identical everywhere; letting a zone inflate it would make the
    // "perfect landing" reward meaningless inside one biome.
    const s1 = new ScoreManager();
    s1.addTrick(trick('backflip', 1, 0));
    const plain = s1.onLanding({ quality: 'perfect' });
    const s2 = new ScoreManager();
    s2.addTrick(trick('backflip', 1, 0));
    const echo = s2.onLanding({ quality: 'perfect' }, { zoneScoreMul: 1.3 });
    expect(echo.bonus).toBe(plain.bonus);
    expect(echo.banked).toBeGreaterThan(plain.banked);
  });

  test('never reduces a payout, and ignores a nonsensical multiplier', () => {
    // A mod must not be able to take points away, and a corrupt/absent value must be harmless.
    const base = landed(1).r.banked;
    for (const bad of [0.5, 0, -3, NaN, undefined, null, '1.3']) {
      expect({ bad, banked: landed(bad).r.banked }).toMatchObject({ bad, banked: base });
    }
  });

  test('has no effect on a crash', () => {
    const s = new ScoreManager();
    s.addTrick(trick('backflip', 1, 0));
    const r = s.onLanding({ quality: 'crash' }, { zoneScoreMul: 1.3 });
    expect(r.banked).toBe(0);
  });

  test('does not apply to distance points', () => {
    const s = new ScoreManager();
    s.setDistance(100);
    s.addTrick(trick('backflip', 1, 0));
    const before = s.getSnapshot().distancePoints;
    s.onLanding({ quality: 'good' }, { zoneScoreMul: 1.3 });
    expect(s.getSnapshot().distancePoints).toBe(before);
  });
