});// Shard Magnet (owner request 2026-11-20): pull, upgrade softcap, placement outside the terrain output.
import fs from 'fs';
import { magnetStrength, pullStep, magnetSpawn, magnetsDropFor, MAGNET_MIN_SYNC_LEVEL } from '../../src/systems/ShardMagnet.js';
import { upgradeEffects, upgradeBenefit, UPGRADE_CATALOG } from '../../src/systems/PermanentUpgrades.js';
import { DRAFT_UPGRADES, DRAFT_RULES_VERSION, validDraftRanks, draftActiveRanks } from '../../src/systems/DailyDraft.js';

const def = JSON.parse(fs.readFileSync('src/data/powerups/shard-magnet.json', 'utf8'));
const chunk = (index, extra = {}) => ({ index, startX: index * 1600, endX: index * 1600 + 1600, hazards: [], gaps: [], powerups: [], ...extra });

describe('shard magnet', () => {
  test('pull: shards inside the radius move toward the rider, faster near the centre, never overshoot', () => {
    expect(pullStep(300, 0, 0, 0, 96, 360, 16)).toBeNull();
    const rim = pullStep(90, 0, 0, 0, 96, 360, 16), near = pullStep(20, 0, 0, 0, 96, 360, 16);
    expect(rim.x).toBeLessThan(90);
    expect(20 - near.x).toBeGreaterThan(90 - rim.x);
    expect(pullStep(2, 0, 0, 0, 96, 360, 1000)).toEqual({ x: 0, y: 0 });
  });

  test('Magnitude, Measure and Myriad: unlimited ranks, diminishing returns, soft caps; never time on screen', () => {
    const fx = (r) => upgradeEffects(r);
    expect(fx({}).magnetMul).toBe(1);
    expect(fx({}).magnetDurationMul).toBe(1);
    expect(fx({}).magnetSpawnMul).toBe(1);
    expect(magnetStrength(def.effect, fx({ magnetMagnitude: 10 }).magnetMul).radius).toBeGreaterThan(def.effect.pullRadiusPx);
    expect(magnetStrength(def.effect, fx({ magnetMagnitude: 1e6 }).magnetMul).radius).toBeLessThan(def.effect.pullRadiusPx * 2.5);
    expect(fx({ magnetMeasure: 1e6 }).magnetDurationMul).toBeLessThan(2);
    expect(fx({ magnetMyriad: 1e6 }).magnetSpawnMul).toBeLessThan(2);
    for (const id of ['magnetMagnitude', 'magnetMeasure', 'magnetMyriad'])
      expect(upgradeBenefit(id, 3) - upgradeBenefit(id, 2)).toBeLessThan(upgradeBenefit(id, 2) - upgradeBenefit(id, 1));
    expect(fs.readFileSync('src/systems/ShardMagnet.js', 'utf8')).not.toMatch(/msLeft|elapsed|durationMs \*/);
  });

  test('all three magnet upgrades are in the Daily Draft (rules v2)', () => {
    expect(DRAFT_RULES_VERSION).toBe(2);
    expect(DRAFT_UPGRADES.map((u) => u.id)).toEqual(UPGRADE_CATALOG.map((u) => u.id));
    expect(DRAFT_UPGRADES.map((u) => u.id)).toEqual(expect.arrayContaining(['magnetMagnitude', 'magnetMeasure', 'magnetMyriad']));
    expect(validDraftRanks({ magnetMagnitude: 3, magnetMyriad: 1 })).toBe(true);
    expect(draftActiveRanks({ magnetMeasure: 2 })).toEqual({ magnetMeasure: 2 });
  });

  test('magnets drop from Sync Level 5 in ordinary runs, and on every Daily regardless of level', () => {
    expect(MAGNET_MIN_SYNC_LEVEL).toBe(5);
    expect(magnetsDropFor({ level: 4 })).toBe(false);
    expect(magnetsDropFor({ level: 5 })).toBe(true);
    expect(magnetsDropFor({ level: 1, daily: true })).toBe(true);
    expect(magnetsDropFor({})).toBe(false);
  });

  test('MYRIAD MAGNETS raises how many chunks get a magnet, deterministically', () => {
    const flat = () => 500;
    const count = (mul) => Array.from({ length: 80 }, (_, i) => magnetSpawn('MYR', chunk(i + 1), def, flat, 30, mul)).filter(Boolean).length;
    expect(count(2)).toBeGreaterThan(count(1));
    expect(count(2)).toBe(count(2));
  });

  test('placement: deterministic per seed and chunk, clear of hazards and pickups, and some chunks get one', () => {
    const flat = () => 500;
    const a = [], b = [];
    for (let i = 1; i <= 60; i++) { a.push(magnetSpawn('SEED', chunk(i), def, flat, 30)); b.push(magnetSpawn('SEED', chunk(i), def, flat, 30)); }
    expect(a).toEqual(b);
    const placed = a.filter(Boolean);
    expect(placed.length).toBeGreaterThan(3);
    expect(placed.length).toBeLessThan(40);
    for (const p of placed) expect(p.y).toBeLessThan(500);
    const at = placed[0], idx = a.indexOf(at) + 1;
    expect(magnetSpawn('SEED', chunk(idx, { hazards: [{ x: at.x + 30 }] }), def, flat, 30)).toBeNull();
    expect(magnetSpawn('SEED', chunk(idx, { powerups: [{ x: at.x - 60 }] }), def, flat, 30)).toBeNull();
    expect(magnetSpawn('OTHER', chunk(idx), def, flat, 30)).not.toEqual(at);
  });

  test('terrain output stays bit-identical: magnets are excluded from the generator pool', () => {
    expect(def.placement).toBe('own');
    expect(fs.readFileSync('src/systems/TerrainGenerator.js', 'utf8')).toMatch(/allPowerups\.filter\(\(p\) => !p\.biome && p\.placement !== 'own'\)/);
  });
});/**
 * W4 shop view layout — overlap, fit, and the single-list rule.
 *
 * The shop is the densest view in the game: 8 catalogue rows, a slot header per group, a state column, a
 * bank line, two boost toggles and a loadout summary inside one 480x270 canvas. W2 shipped a HUD strip
 * that collided with the mission text and W3 shipped a toggle menu covering the biome names; both were
 * only caught by a human looking at a screenshot.
 *
 * Then the shop itself shipped unreadable, and a human caught it again (CC Friday's W4 rejection). The
 * cause was two independently positioned layers of the same rows, so the fix is structural and these tests
 * pin the structure rather than the pixels:
 *
 *   1. every drawn text box is disjoint from every other one;
 *   2. every box clears the BACK button and stays inside the panel;
 *   3. the menu IS the layout — same rows, same order, same count, so a second layer cannot reappear;
 *   4. the layout is a pure function of the profile, which is what makes the refresh possible at all.
 */
import { shopLayout, shopMenuItems, shopAllRows, SHOP_PAGES, SHOP_PANEL, SHOP_ROW_H, SHOP_GLYPH_H } from '../../src/ui/ShopLayout.js';
import { SHOP_ITEMS } from '../../src/systems/ProfileStore.js';
import { GAME_WIDTH, GAME_HEIGHT } from '../../src/constants.js';

/** A profile at a mid level with shards, one equipped cosmetic and one owned-but-not-equipped. */
const PROFILE = {
  v: 1, xp: 48400, level: 16, bank: 275,
  equipped: { trail: 'ember', glow: 'default', rider: 'default', theme: 'default', title: 'default' },
  unlocked: { cosmetics: ['trail-hue-ember', 'sled-glow-warm'], biomes: [], boosts: {} },
};

/** Everything equipped and both boosts on: the state the rejected build was worst at. */
const RICH = {
  ...PROFILE,
  boosted: true,
  equipped: { trail: 'ember', glow: 'warm', rider: 'mint', theme: 'default', title: 'ROOKIE' },
  unlocked: { cosmetics: ['trail-hue-ember', 'sled-glow-warm', 'rider-hue-mint'], biomes: [], boosts: {} },
};

const overlap = (a, b) => a.x < b.x + b.w && b.x < a.x + a.w && a.y < b.y + b.h && b.y < a.y + a.h;

const findOverlaps = (layout) => {
  const bad = [];
  for (let i = 0; i < layout.texts.length; i++) {
    for (let j = i + 1; j < layout.texts.length; j++) {
      if (overlap(layout.texts[i], layout.texts[j])) bad.push(`${layout.texts[i].key} <-> ${layout.texts[j].key}`);
    }
  }
  return bad;
};

describe('shopLayout — nothing is drawn twice', () => {
  test('no two text boxes overlap on a normal profile', () => {
    expect(findOverlaps(shopLayout({ profile: PROFILE }))).toEqual([]);
  });

  test('no two text boxes overlap once items are owned and boosts are on', () => {
    // The rejected build overlapped exactly here: owned rows say EQUIP instead of a price, and the boost
    // menu was positioned from an estimate of the catalogue's height, so it landed on the TRAIL rows.
    expect(findOverlaps(shopLayout({ profile: RICH }))).toEqual([]);
  });

  test('no two text boxes overlap at level 1 with an empty bank', () => {
    expect(findOverlaps(shopLayout({ profile: { level: 1, bank: 0 } }))).toEqual([]);
  });

  test('every row is a full glyph height clear of the next', () => {
    // Disjoint is not the same as readable: two strings 1px apart pass an intersection test and still read
    // as one smear. W3's rule was "full glyph height clear", so the same rule applies here.
    const L = shopLayout({ profile: RICH });
    const ys = [...new Set(L.texts.map((t) => t.y))].sort((a, b) => a - b);
    for (let i = 1; i < ys.length; i++) expect(ys[i] - ys[i - 1]).toBeGreaterThanOrEqual(SHOP_GLYPH_H);
  });

  test('every box stays inside the panel', () => {
    for (const p of [PROFILE, RICH, { level: 1, bank: 0 }]) {
      const L = shopLayout({ profile: p });
      const bad = L.texts.filter((t) => t.x < 0 || t.y < 0 || t.x + t.w > SHOP_PANEL.w || t.y + t.h > L.h);
      expect(bad.map((b) => b.key)).toEqual([]);
    }
  });

  test('every row clears the BACK button at the panel floor', () => {
    // The base View pins BACK to (w-76, h-22). A row underneath it is a row the player cannot click, which
    // is the same defect as W3's BACK button sitting on a biome name.
    for (const p of [PROFILE, RICH]) {
      const L = shopLayout({ profile: p });
      const back = { x: SHOP_PANEL.w - 76, y: L.h - 22, w: 68, h: 16 };
      const bad = L.texts.filter((t) => overlap(t, back));
      expect(bad.map((b) => b.key)).toEqual([]);
    }
  });

  test('the panel fits on screen at the view origin', () => {
    // Views open at y 22 under the Title header, so the panel must not grow past the canvas.
    const L = shopLayout({ profile: RICH });
    expect(L.h).toBeLessThanOrEqual(GAME_HEIGHT - 22);
    expect(L.w).toBeLessThanOrEqual(GAME_WIDTH);
    expect(SHOP_PANEL.w).toBe(L.w);
  });
});

describe('shopLayout — content', () => {
  test('one row per sellable item, and titles are not sold here', () => {
    // F4 fit: the shop pages by slot, so "the shop" is every page (shopAllRows), not the first one.
    const items = shopAllRows({ profile: PROFILE });
    const sellable = SHOP_ITEMS.filter((i) => i.slot !== 'title');
    expect(items.map((r) => r.id).sort()).toEqual(sellable.map((i) => i.id).sort());
    expect(items.some((r) => r.slot === 'title')).toBe(false);
  });

  test('state is spelled out, not colour-only', () => {
    const byId = Object.fromEntries(shopAllRows({ profile: PROFILE }).map((r) => [r.id, r]));
    // Equipped vs owned-not-equipped vs affordable vs locked each read differently as TEXT.
    expect(byId['trail-hue-ember'].state).toBe('EQUIPPED');
    expect(byId['sled-glow-warm'].state).toBe('EQUIP');
    const pricey = Object.values(byId).find((r) => !r.owned && !r.locked && !r.affordable);
    if (pricey) expect(pricey.state).toMatch(/^\d+$/);
  });

  test('a locked item says its level and cannot be selected', () => {
    const L = shopLayout({ profile: { level: 1, bank: 0 } });
    const locked = L.rows.filter((r) => r.kind === 'item' && r.locked);
    expect(locked.length).toBeGreaterThan(0);
    for (const r of locked) {
      expect(r.state).toMatch(/^LVL \d+$/);
      expect(r.disabled).toBe(true);
    }
  });

  test('boosts are rows in the same list and follow the profile', () => {
    const L = shopLayout({ profile: { ...PROFILE, boosts: { errorCorrection: true, headStart: false } } });
    const boosts = L.rows.filter((r) => r.kind === 'boost');
    expect(boosts.map((b) => b.id)).toEqual(['errorCorrection', 'headStart']);
    expect(boosts[0].on).toBe(true);
    expect(boosts[1].on).toBe(false);
  });

  test('the bank line reflects the actual bank', () => {
    expect(shopLayout({ profile: PROFILE }).bankText).toBe('BANK 275');
    expect(shopLayout({ profile: { bank: 0 } }).bankText).toBe('BANK 0');
  });

  test('the loadout summary names each slot and shows what is equipped', () => {
    const L = shopLayout({ profile: RICH });
    for (const slot of ['TRAIL', 'GLOW', 'RIDER', 'THEME']) expect(L.loadoutText).toContain(slot);
    expect(L.loadoutText).toContain('TRAIL EMBER');
    expect(L.loadoutText).toContain('GLOW WARM');
    expect(L.loadoutText).toContain('THEME DEFAULT');
  });

  test('a broke, empty or hostile profile lays out without throwing', () => {
    for (const p of [null, {}, { bank: undefined, level: undefined }, { bank: -5, equipped: null }]) {
      const L = shopLayout({ profile: p });
      expect(L.texts.length).toBeGreaterThan(0);
      expect(Number.isFinite(L.h)).toBe(true);
    }
  });
});

describe('shopMenuItems — the menu IS the layout', () => {
  test('same rows, same order, same count as the layout', () => {
    // This is the assertion that would have caught the double-draw. Two independently built lists of the
    // same rows cannot stay in agreement, so there must only ever be one.
    const L = shopLayout({ profile: RICH });
    const menu = shopMenuItems(L);
    expect(menu.length).toBe(L.rows.length);
    expect(menu.map((m) => m.label)).toEqual(L.rows.map((r) => r.label));
  });

  test('headers and the loadout line are present but never selectable', () => {
    const L = shopLayout({ profile: RICH });
    const statics = shopMenuItems(L).filter((m) => m.kind === 'static');
    expect(statics.length).toBeGreaterThan(0);
    for (const s of statics) expect(s.disabled).toBe(true);
    const labels = statics.map((s) => s.label);
    expect(labels).toContain('BOOSTS');
    expect(labels).toContain('LOADOUT');
    // F4 fit: the TRAIL heading is now the page selector ("← TRAIL →"), a selectable row, not a static.
    expect(shopMenuItems(L).find((m) => m.rowKind === 'page').label).toContain('TRAIL');
  });

  test('an equipped item is selectable: selecting it returns the slot to DEFAULT (audit SHOP-3)', () => {
    // This used to pin `disabled: true`, which the post-sprint audit (SHOP-3) found to be the defect: with
    // the equipped row skipped there was no way back to the default look. ShopView unequips on select.
    const ember = shopMenuItems(shopLayout({ profile: PROFILE })).find((m) => m.id === 'trail-hue-ember');
    expect(ember.disabled).toBe(false);
    expect(ember.sub).toBe('EQUIPPED');
  });

  test('an owned, un-equipped item is selectable', () => {
    const warm = shopMenuItems(shopLayout({ profile: PROFILE, page: SHOP_PAGES.indexOf('glow') })).find((m) => m.id === 'sled-glow-warm');
    expect(warm.disabled).toBe(false);
  });

  test('an unaffordable, unowned, unlocked item is disabled', () => {
    const poor = { ...PROFILE, bank: 0 };
    const L = shopLayout({ profile: poor });
    for (const m of shopMenuItems(L).filter((x) => x.rowKind === 'item' && !x.disabled)) {
      const row = L.rows.find((r) => r.id === m.id);
      expect(row.price === 0 || row.owned).toBe(true);
    }
  });

  test('the first selectable row is a real row, not a heading', () => {
    const L = shopLayout({ profile: RICH });
    expect(L.firstSelectable).toBeGreaterThanOrEqual(0);
    // F4 fit: the page selector is a real, selectable row (it turns the page).
    expect(['item', 'boost', 'page']).toContain(L.rows[L.firstSelectable].kind);
  });
});

describe('shopLayout — refreshability', () => {
  test('a changed profile changes the bank line, the states and the loadout', () => {
    // Defect 2 was that the static layer never refreshed. The layout is a pure function of the profile, so
    // the structural guarantee is simple: same input -> same output, different input -> different output,
    // with no state captured at construction time.
    const before = shopLayout({ profile: RICH });
    const after = shopLayout({ profile: { ...RICH, bank: 70, equipped: { ...RICH.equipped, glow: 'default' } } });
    expect(before.bankText).toBe('BANK 275');
    expect(after.bankText).toBe('BANK 70');
    expect(before.loadoutText).toContain('GLOW WARM');
    expect(after.loadoutText).toContain('GLOW DEFAULT');
  });

  test('buying an item changes its row from a price to EQUIP', () => {
    const before = shopLayout({ profile: { level: 16, bank: 500 } });
    const after = shopLayout({ profile: { level: 16, bank: 380, unlocked: { cosmetics: ['trail-hue-ember'] } } });
    expect(before.rows.find((r) => r.id === 'trail-hue-ember').owned).toBe(false);
    expect(after.rows.find((r) => r.id === 'trail-hue-ember').owned).toBe(true);
    expect(after.rows.find((r) => r.id === 'trail-hue-ember').state).toBe('EQUIP');
  });

  test('row pitch is exactly the MenuList rowH the view passes', () => {
    const L = shopLayout({ profile: RICH });
    expect(L.rowH).toBe(SHOP_ROW_H);
    const ys = L.rows.map((r) => r.y);
    for (let i = 1; i < ys.length; i++) expect(ys[i] - ys[i - 1]).toBe(SHOP_ROW_H);
  });
});/**
 * Audit F4 fit: the Shard Shop pages by slot.
 *
 * The flat shop was 247 of 248 px tall with 9 cosmetic rows; the level rewards add eleven more. So the
 * catalogue is shown one slot per page (TRAIL / GLOW / RIDER / THEME), selected by a focusable page row,
 * and the bank, boosts and loadout stay on every page (the built-game gate and the Game Over popup both
 * expect the boost rows and the BANK line on whatever page the shop opens on).
 */
import fs from 'fs';

import { shopLayout, shopMenuItems, shopAllRows, SHOP_PAGES, SHOP_PANEL } from '../../src/ui/ShopLayout.js';
import { SHOP_ITEMS, sanitizeProfile } from '../../src/systems/ProfileStore.js';
import { GAME_HEIGHT } from '../../src/constants.js';

const LEVELS = JSON.parse(fs.readFileSync('src/data/progression/levels.json', 'utf8'));
const MAX_XP = LEVELS.levels[LEVELS.levels.length - 1].xpMin + 1;
const v1 = (o = {}) => sanitizeProfile({ v: 1, ...o }, LEVELS);

const overlap = (a, b) => a.x < b.x + b.w && b.x < a.x + a.w && a.y < b.y + b.h && b.y < a.y + a.h;

/** Profiles that stress the page: empty, mid, and level 30 with everything owned and equipped. */
const PROFILES = () => {
  const allIds = SHOP_ITEMS.map((i) => i.id);
  const rich = v1({ xp: MAX_XP, bank: 99999, unlocked: { cosmetics: allIds, titles: [], boosts: { headStart: 8, errorCorrection: 15 } } });
  const eq = {};
  for (const slot of SHOP_PAGES) {
    const last = SHOP_ITEMS.filter((i) => i.slot === slot).pop();
    eq[slot] = last.value;
  }
  return [v1({}), v1({ xp: 48400, bank: 275 }), { ...rich, equipped: { ...rich.equipped, ...eq } }];
};

describe('shop pages', () => {
  test('one page per cosmetic slot, in a fixed order; titles live in the Profile view', () => {
    expect(SHOP_PAGES).toEqual(['trail', 'glow', 'rider', 'theme']);
  });

  test('every catalogue item outside titles appears on exactly one page, its own slot', () => {
    const rows = shopAllRows({ profile: v1({}) });
    const ids = rows.map((r) => r.id);
    expect(new Set(ids).size).toBe(ids.length);
    expect([...ids].sort()).toEqual(SHOP_ITEMS.filter((i) => i.slot !== 'title').map((i) => i.id).sort());
    for (const p of SHOP_PAGES.keys()) {
      for (const r of shopLayout({ profile: v1({}), page: p }).rows.filter((x) => x.kind === 'item')) {
        expect(r.slot).toBe(SHOP_PAGES[p]);
      }
    }
  });

  test('the page row is the first selectable row and spells out where you are', () => {
    for (const p of SHOP_PAGES.keys()) {
      const L = shopLayout({ profile: v1({}), page: p });
      const row = L.rows[L.firstSelectable];
      expect(row.kind).toBe('page');
      expect(row.label).toContain(SHOP_PAGES[p].toUpperCase());
      expect(row.state).toBe(`${p + 1}/${SHOP_PAGES.length}`);
      expect(L.page).toBe(p);
    }
  });

  test('the page index wraps both ways', () => {
    expect(shopLayout({ profile: v1({}), page: -1 }).page).toBe(SHOP_PAGES.length - 1);
    expect(shopLayout({ profile: v1({}), page: SHOP_PAGES.length }).page).toBe(0);
  });

  test('every page keeps the bank, both boost rows and the loadout line', () => {
    for (const p of SHOP_PAGES.keys()) {
      const L = shopLayout({ profile: v1({ bank: 42 }), page: p });
      expect(L.bankText).toBe('BANK 42');
      expect(L.rows.filter((r) => r.kind === 'boost').map((r) => r.id)).toEqual(['errorCorrection', 'headStart']);
      expect(L.rows.some((r) => r.key === 'loadout')).toBe(true);
    }
  });

  test('every page of every stress profile fits at 480x270: no overlaps, inside the panel, clear of BACK', () => {
    for (const prof of PROFILES()) {
      for (const p of SHOP_PAGES.keys()) {
        const L = shopLayout({ profile: prof, page: p });
        const where = `page ${p} level ${prof.level}`;
        expect({ where, h: L.h <= GAME_HEIGHT - 22 }).toEqual({ where, h: true });
        const back = { x: SHOP_PANEL.w - 76, y: L.h - 22, w: 68, h: 16 };
        for (let i = 0; i < L.texts.length; i++) {
          const t = L.texts[i];
          expect({ where, k: t.key, inside: t.x >= 0 && t.y >= 0 && t.x + t.w <= L.w && t.y + t.h <= L.h }).toEqual({ where, k: t.key, inside: true });
          expect({ where, k: t.key, back: overlap(t, back) }).toEqual({ where, k: t.key, back: false });
          for (let j = i + 1; j < L.texts.length; j++) {
            expect({ where, pair: `${t.key}/${L.texts[j].key}`, hit: overlap(t, L.texts[j]) })
              .toEqual({ where, pair: `${t.key}/${L.texts[j].key}`, hit: false });
          }
        }
      }
    }
  });

  test('the panel height is the same on every page, so paging never resizes the frame', () => {
    const hs = new Set(SHOP_PAGES.map((_, p) => shopLayout({ profile: PROFILES()[2], page: p }).h));
    expect(hs.size).toBe(1);
  });

  test('the menu carries the page row as a selectable action with its position as the sub text', () => {
    const L = shopLayout({ profile: v1({}), page: 1 });
    const m = shopMenuItems(L);
    expect(m.length).toBe(L.rows.length);
    const page = m[L.firstSelectable];
    expect(page).toMatchObject({ kind: 'action', rowKind: 'page', disabled: false, sub: `2/${SHOP_PAGES.length}` });
  });
});/**
 * SHOP-1: the shop prompt (Game Over autoprompt and the "SHOP: B" hint) counts only items the Shard Shop
 * actually shows as buyable. Titles have no UI yet, so the shop hides them and the prompt must too.
 */
import fs from 'fs';

import { sanitizeProfile, SHOP_ITEMS } from '../../src/systems/ProfileStore.js';
import { canAffordAnything, newlyAffordable, shopState } from '../../src/systems/ShopPrompt.js';
import { shopAllRows } from '../../src/ui/ShopLayout.js';

const LEVELS = JSON.parse(fs.readFileSync('src/data/progression/levels.json', 'utf8'));
const MAX_XP = LEVELS.levels[LEVELS.levels.length - 1].xpMin + 1;
const v1 = (o = {}) => sanitizeProfile({ v: 1, ...o }, LEVELS);
// F4 fit: the shop pages by slot, so its buyable rows are those on every page.
const buyableRows = (p) => shopAllRows({ profile: p }).filter((r) => r.kind === 'item' && !r.owned && !r.disabled);

describe('SHOP-1: the prompt agrees with the rows the shop shows', () => {
  test('anything the shop prompt calls affordable is a buyable row in the shop', () => {
    // Owns every visible item priced up to 220; bank 225. Only title-static (220, hidden) is "affordable".
    const owned = ['trail-hue-ember', 'trail-hue-tidal', 'sled-glow-warm', 'sled-glow-cold', 'rider-hue-mint', 'rider-hue-plum'];
    const p = v1({ xp: MAX_XP, bank: 225, unlocked: { cosmetics: owned } });
    expect({ prompt: canAffordAnything(shopState(p)), shopHasBuyable: buyableRows(p).length > 0 })
      .toEqual({ prompt: false, shopHasBuyable: false });
  });

  test('crossing the price of a hidden title alone does not autoprompt', () => {
    const owned = SHOP_ITEMS.filter((i) => i.slot !== 'title' && i.price > 0 && i.price <= 220).map((i) => i.id);
    const before = shopState(v1({ xp: MAX_XP, bank: 200, unlocked: { cosmetics: owned } }));
    const after = shopState(v1({ xp: MAX_XP, bank: 225, unlocked: { cosmetics: owned } }));
    expect(newlyAffordable(before, after)).toBe(false);
  });

  test('prompt and shop agree across a grid of banks, levels and owned sets', () => {
    const visible = SHOP_ITEMS.filter((i) => i.slot !== 'title').map((i) => i.id);
    for (const bank of [0, 89, 90, 120, 199, 220, 225, 300, 999]) {
      for (const xp of [0, 1000, MAX_XP]) {
        for (const owned of [[], ['sled-glow-warm'], visible.filter((id) => id !== 'theme-sunset'), visible]) {
          const p = v1({ xp, bank, unlocked: { cosmetics: owned } });
          expect({ bank, xp, owned: owned.length, prompt: canAffordAnything(shopState(p)) })
            .toEqual({ bank, xp, owned: owned.length, prompt: buyableRows(p).length > 0 });
        }
      }
    }
  });
});/**
 * W4.1 — the shop auto-open decision.
 *
 * CC Friday's amendment (notes/cc-friday-shop-popup-2.txt) replaced "any round where something is
 * affordable" with "only when the run NEWLY made something affordable", and named the cases that have to be
 * covered. Each of them is a test here, because the whole value of the feature is not popping up on a
 * player who is already sitting on enough shards.
 *
 * These tests run against the SHIPPED catalogue and the real `purchase()`. A hand-written fixture catalogue
 * would have made the tests pass while the popup disagreed with the real shop, because `isOwned`/`purchase`
 * resolve items from the module-level SHOP_ITEMS and cannot be pointed elsewhere.
 */
import { SHOP_ITEMS, purchase } from '../../src/systems/ProfileStore.js';
import { levelForXp, loadLevelTable } from '../../src/systems/Progression.js';
import { canAffordAnything, newlyAffordable, stateBeforeRun } from '../../src/systems/ShopPrompt.js';

const CHEAP = 'sled-glow-warm'; // 90 shards, level 1
const MID = 'rider-hue-mint'; // 100 shards, level 1
const LEVEL5 = 'trail-hue-tidal'; // 200 shards, needs level 5
const LEVEL_REWARD = 'title-rookie'; // price 0, level 1

const price = (id) => SHOP_ITEMS.find((i) => i.id === id).price;
const st = (bank, level, owned = []) => ({ bank, level, owned });
/** A profile just real enough for the real purchase(). */
const profileAt = (bank, level, owned = []) => ({
  bank, level, xp: 0,
  unlocked: { cosmetics: [...owned], boosts: {}, biomes: [] },
  equipped: {}, boosts: {},
});

describe('the fixture ids still describe the shipped catalogue', () => {
  // Guards the tests themselves: if the catalogue is repriced or releveled, these fail loudly instead of
  // the suite quietly proving nothing about the numbers below.
  test('prices and levels are what the cases assume', () => {
    expect(price(CHEAP)).toBe(90);
    expect(price(MID)).toBe(100);
    expect(price(LEVEL5)).toBe(200);
    expect(price(LEVEL_REWARD)).toBe(0);
    expect(SHOP_ITEMS.find((i) => i.id === LEVEL5).unlockLevel).toBe(5);
  });
});

describe('canAffordAnything', () => {
  test('true when the bank covers a paid item that is not owned and unlocked', () => {
    expect(canAffordAnything(st(90, 1))).toBe(true);
  });

  test('false when broke', () => {
    expect(canAffordAnything(st(0, 1))).toBe(false);
    expect(canAffordAnything(st(89, 1))).toBe(false);
  });

  test('a price-0 level reward is never something to buy', () => {
    // With every paid item owned, the only "affordable" thing left is the free title, which is a reward.
    const paid = SHOP_ITEMS.filter((i) => i.price > 0).map((i) => i.id);
    expect(canAffordAnything(st(0, 9, paid))).toBe(false);
    expect(canAffordAnything(st(9999, 9, paid))).toBe(false);
  });

  test('nothing is affordable when everything buyable at this level is owned', () => {
    const buyableAt1 = SHOP_ITEMS.filter((i) => i.price > 0 && i.unlockLevel <= 1).map((i) => i.id);
    expect(canAffordAnything(st(9999, 1, buyableAt1))).toBe(false);
  });

  test('a level-locked item does not count, however rich the player is', () => {
    // `trail-hue-tidal` is the cheapest thing that needs level 5; own everything else that is level 1-4.
    const others = SHOP_ITEMS.filter((i) => i.price > 0 && i.id !== LEVEL5 && i.unlockLevel <= 4).map((i) => i.id);
    expect(canAffordAnything(st(1000, 4, others))).toBe(false);
    expect(canAffordAnything(st(1000, 5, others))).toBe(true);
  });

  test('bad input is false, never a throw', () => {
    expect(canAffordAnything(null)).toBe(false);
    expect(canAffordAnything(undefined)).toBe(false);
    expect(canAffordAnything({ bank: NaN, level: NaN })).toBe(false);
  });
});

describe('equivalence with the real shop', () => {
  test('anything this says is affordable, purchase() actually buys', () => {
    // The popup must never open a panel where every row is refused. Exhaustive over a bank/level/owned grid.
    const ids = SHOP_ITEMS.map((i) => i.id);
    for (const bank of [0, 45, 89, 90, 100, 120, 150, 199, 200, 250, 300, 999]) {
      for (const level of [1, 2, 3, 4, 5, 6, 8, 9]) {
        for (const owned of [[], [CHEAP], [CHEAP, MID], ids.filter((id) => id !== LEVEL5)]) {
          if (!canAffordAnything(st(bank, level, owned))) continue;
          const prof = profileAt(bank, level, owned);
          const bought = ids.some((id) => purchase(prof, id) !== prof);
          expect(bought).toBe(true);
        }
      }
    }
  });

  test('and the converse: when every purchase() is refused, it says nothing is affordable', () => {
    const ids = SHOP_ITEMS.map((i) => i.id);
    for (const bank of [0, 89, 90, 200, 999]) {
      for (const level of [1, 4, 5, 9]) {
        for (const owned of [[], ids.filter((id) => id !== LEVEL5), ids]) {
          const prof = profileAt(bank, level, owned);
          const bought = ids.some((id) => purchase(prof, id) !== prof);
          if (bought) continue;
          expect(canAffordAnything(st(bank, level, owned))).toBe(false);
        }
      }
    }
  });
});

describe('newlyAffordable — the amendment CC relayed', () => {
  test('a stockpile that grows but crosses nothing new does NOT pop', () => {
    // Already had 150 (above the 90 and 100 prices), earned 50 more: nothing new became buyable.
    expect(newlyAffordable(st(150, 1), st(200, 1))).toBe(false);
  });

  test('a run that crosses a price DOES pop', () => {
    expect(newlyAffordable(st(80, 1), st(90, 1))).toBe(true);
    expect(newlyAffordable(st(0, 1), st(90, 1))).toBe(true);
  });

  test('a level-up that unlocks an item the bank already covers DOES pop', () => {
    // 200 bank the whole time; `trail-hue-tidal` costs 200 but needs level 5.
    // Own everything else buyable below level 5, so the only thing that can change is the unlock.
    const others = SHOP_ITEMS.filter((i) => i.price > 0 && i.id !== LEVEL5 && i.unlockLevel <= 4).map((i) => i.id);
    expect(newlyAffordable(st(200, 4, others), st(200, 5, others))).toBe(true);
    expect(newlyAffordable(st(200, 3, others), st(200, 4, others))).toBe(false);
  });

  test('broke stays quiet', () => {
    expect(newlyAffordable(st(0, 1), st(10, 1))).toBe(false);
    expect(newlyAffordable(st(0, 1), st(89, 1))).toBe(false);
  });

  test('two prices crossed in one run is one decision, not two', () => {
    // 0 -> 250 crosses several prices. The helper is pure and answers a boolean; the scene opens one panel.
    expect(newlyAffordable(st(0, 1), st(250, 1))).toBe(true);
    expect(newlyAffordable(st(0, 1), st(250, 1))).toBe(true);
  });

  test('a price crossed by a level-up AND shards at once still pops once', () => {
    const others = SHOP_ITEMS.filter((i) => i.price > 0 && i.id !== LEVEL5 && i.unlockLevel <= 4).map((i) => i.id);
    expect(newlyAffordable(st(0, 4, others), st(200, 5, others))).toBe(true);
  });

  test('owning the affordable item suppresses the pop', () => {
    // 80 -> 100 crosses two prices (90 and 100). Owning BOTH of those leaves nothing new to buy.
    expect(newlyAffordable(st(80, 1, []), st(100, 1, [CHEAP, MID]))).toBe(false);
    // Control: with only the 100-shard item owned, the 90-shard one is still newly affordable, so the
    // test above is not passing merely because nothing was buyable at all.
    expect(newlyAffordable(st(80, 1, []), st(100, 1, [MID]))).toBe(true);
    expect(newlyAffordable(st(80, 1, []), st(100, 1, []))).toBe(true);
  });

  test('a run that earns nothing cannot newly afford anything', () => {
    expect(newlyAffordable(st(90, 1), st(90, 1))).toBe(false);
    expect(newlyAffordable(st(500, 5), st(500, 5))).toBe(false);
  });

  test('bad input is false, never a throw', () => {
    expect(newlyAffordable(null, null)).toBe(false);
    expect(newlyAffordable(st(0, 1), null)).toBe(false);
  });
});

describe('stateBeforeRun derives "before" without storing anything', () => {
  const table = loadLevelTable();
  const lvl = (xp) => levelForXp(xp, table);

  test('subtracts this run’s shards from the bank', () => {
    const before = stateBeforeRun({ bank: 180, xp: 400 }, { shards: 60, xp: 40 }, lvl, []);
    expect(before.bank).toBe(120);
  });

  test('re-derives the level without this run’s XP, against the real table', () => {
    // Cross a real threshold: take a profile that is level N and hand back enough XP to drop it a level.
    const lv2 = table.levels[1].xpMin;
    const after = { bank: 0, xp: lv2 };
    expect(lvl(after.xp)).toBe(2);
    const before = stateBeforeRun(after, { shards: 0, xp: 10 }, lvl, []);
    expect(lvl(after.xp - 10)).toBe(1);
    expect(before.level).toBe(1);
  });

  test('a level-up during the run is visible in the before/after pair', () => {
    const lv2 = table.levels[1].xpMin;
    const after = { bank: 200, xp: lv2, level: 2, owned: [] };
    const before = stateBeforeRun(after, { shards: 200, xp: 5 }, lvl, []);
    expect(before.level).toBe(1);
    expect(before.bank).toBe(0);
  });

  test('a run that earned nothing derives an identical state', () => {
    const after = { bank: 90, xp: 500, level: lvl(500), owned: ['x'] };
    const before = stateBeforeRun(after, { shards: 0, xp: 0 }, lvl, ['x']);
    expect(before.bank).toBe(90);
    expect(before.level).toBe(lvl(500));
    expect(before.owned).toEqual(['x']);
  });

  test('a missing credit cannot make the bank negative', () => {
    const before = stateBeforeRun({ bank: 10, xp: 0 }, null, lvl, []);
    expect(before.bank).toBe(10);
    expect(before.level).toBe(1);
  });

  test('end to end: a run that crosses a price is detected from the live profile alone', () => {
    const after = { bank: 90, xp: 0, level: 1 };
    const before = stateBeforeRun(after, { shards: 90, xp: 0 }, lvl, []);
    expect(newlyAffordable(before, { ...after, owned: [] })).toBe(true);
  });

  test('end to end: a run on a fat bank that crosses nothing stays quiet', () => {
    const after = { bank: 1000, xp: 5000, level: 1 };
    const before = stateBeforeRun(after, { shards: 50, xp: 20 }, lvl, []);
    expect(newlyAffordable(before, { ...after, owned: [] })).toBe(false);
  });
});// Issue #59 stage 2: fixed simulation tick accumulator and one-shot input edges.
import fs from 'fs';
import { SimClock, SIM_TICK_MS, SIM_MAX_TICKS_PER_FRAME } from '../../src/systems/SimClock.js';

const ticksFor = (hz, seconds) => {
  const c = new SimClock();
  const per = [];
  for (let i = 0; i < hz * seconds; i++) per.push(c.advance(1000 / hz));
  return { total: per.reduce((a, b) => a + b, 0), per, clock: c };
};
const pad = (pressed = {}) => ({ push: true, tilt: 0, pressed: { hop: false, reset: false, pause: false, airBrake: false, parachute: false, confirm: false, ...pressed } });

describe('SimClock', () => {
  test('30, 60 and 120 Hz frames run 4, 2 and 1 whole ticks, every frame, for minutes', () => {
    for (const [hz, each] of [[30, 4], [60, 2], [120, 1]]) {
      const r = ticksFor(hz, 180);
      expect(new Set(r.per)).toEqual(new Set([each]));
      expect(r.total).toBe(120 * 180);
      expect(r.clock.droppedMs).toBe(0);
    }
  });

  test('other refresh rates keep exact simulated time on average (144 Hz, 75 Hz)', () => {
    for (const hz of [144, 75]) {
      const r = ticksFor(hz, 60);
      expect(Math.abs(r.total - 120 * 60)).toBeLessThanOrEqual(1);
    }
  });

  test('a long stall never fast-forwards: at most the 50 ms cap of ticks, the rest is dropped', () => {
    const c = new SimClock();
    expect(c.advance(2000)).toBe(SIM_MAX_TICKS_PER_FRAME);
    expect(c.accMs).toBeLessThan(SIM_TICK_MS);
    expect(c.droppedMs).toBeGreaterThan(1900);
    expect(c.advance(1000 / 60)).toBeLessThanOrEqual(3);
  });

  test('a pressed edge reaches exactly one tick, the first of the frame', () => {
    const c = new SimClock();
    const pads = c.padsFor(pad({ hop: true }), c.advance(1000 / 30));
    expect(pads.map((p) => p.pressed.hop)).toEqual([true, false, false, false]);
    expect(pads.every((p) => p.push)).toBe(true);
  });

  test('an edge polled on a frame with no tick waits for the next tick instead of being lost', () => {
    const c = new SimClock();
    expect(c.padsFor(pad({ hop: true }), c.advance(3))).toEqual([]);
    const next = c.padsFor(pad(), c.advance(6));
    expect(next.map((p) => p.pressed.hop)).toEqual([true]);
    expect(c.padsFor(pad(), c.advance(SIM_TICK_MS)).map((p) => p.pressed.hop)).toEqual([false]);
  });

  test('RunScene advances gameplay only through simTick with the fixed tick', () => {
    const src = fs.readFileSync('src/scenes/RunScene.js', 'utf8');
    expect(src).toMatch(/const r = this\.simTick\(this\.simClock\.tickMs, tickPad\);/);
    const update = src.slice(src.indexOf('  update(time, delta) {'), src.indexOf('  simTick(dt, pad) {'));
    expect(update).not.toMatch(/stepWorld\(|this\.runTimeMs \+=|tickEffects\(/);
  });
});

// Issue #115: timed scheduling (see also tests/determinism/fair-input*.test.js).
describe('SimClock.padsFor with an input timeline', () => {
  const tl = (events, base = {}) => ({ base: { push: false, hop: false, brake: false, ...base }, events, analog: 0 });
  const id = (raw) => raw;

  test('a change goes to the tick whose window contains its timestamp; later ticks keep it', () => {
    const c = new SimClock();
    const n = c.advance(1000 / 30); // ticks end at 8.33, 16.67, 25, 33.33 for frameTime 33.33
    const pads = c.padsFor(pad(), n, { frameTime: 1000 / 30, timeline: tl([{ t: 20, name: 'push', down: true }]), normalize: id });
    expect(pads.map((p) => p.push)).toEqual([false, false, true, true]);
  });

  test('changes in the sub-tick remainder clamp to the last tick; changes before the window to the first', () => {
    const c = new SimClock();
    const n = c.advance(10); // 1 tick, 1.67 ms remainder: tick window (-6.67, 1.67] relative to frameTime 10
    expect(n).toBe(1);
    const pads = c.padsFor(pad(), n, { frameTime: 10, timeline: tl([{ t: -50, name: 'hop', down: true }, { t: 9.9, name: 'push', down: true }]), normalize: id });
    expect(pads[0]).toMatchObject({ hop: true, push: true, pressed: { hop: true } });
  });

  test('a 0-tick frame carries its timeline; a poll skipped in between is bridged, never left stale', () => {
    const c = new SimClock();
    expect(c.padsFor(pad(), c.advance(3), { frameTime: 3, timeline: tl([{ t: 2, name: 'push', down: true }]), normalize: id })).toEqual([]);
    // the next padsFor's poll says push is already released (a consumed poll released it)
    const pads = c.padsFor(pad(), c.advance(1000 / 60), { frameTime: 3 + 1000 / 60, timeline: tl([], { push: false }), normalize: id });
    expect(pads.map((p) => p.push)).toEqual([true, false]);
  });

  test('without a timeline padsFor keeps the legacy fan-out exactly', () => {
    const c = new SimClock();
    const pads = c.padsFor(pad({ hop: true }), c.advance(1000 / 30), { frameTime: 1000 / 30, timeline: null });
    expect(pads.map((p) => p.pressed.hop)).toEqual([true, false, false, false]);
  });

  test('RunScene passes rAF time, the router timeline and its own normalizer to padsFor', () => {
    const src = fs.readFileSync('src/scenes/RunScene.js', 'utf8');
    expect(src).toMatch(/this\.simClock\.padsFor\(polled, ticks, \{\s*frameTime: time, timeline: rawPad && rawPad\.timeline, normalize: \(raw\) => this\.normalizePad\(raw\),/);
  });
});

