/** Chunk stream length. See the note above: ~16.5 km, spans every sector-driven behaviour. */
const CHUNKS = 300;

/**
 * Seeds chosen for spread, not for convenience: two plain strings, a numeric-looking one, one with
 * punctuation (seed strings reach `hashInts` and a punctuation seed exercises a different mixing
 * path than a word), and the daily-run style key the game actually uses.
 */
const SEEDS = ['alpha', 'bitstream-bluffs', '42', 'seed@mask0', '2026-11-13'];

/**
 * Golden digests, recorded at `06e79f5` with `biomeMask = 0`.
 *
 * `shape` covers the geometry only (kind + every point). `full` covers geometry plus every spawned
 * object. They are separate so a failure says WHICH layer moved: a hazard-only change keeps `shape`
 * green and breaks `full`, which is a much cheaper diagnosis than re-deriving both.
 */
const GOLDEN = {
  alpha: {
    shape: 'f562dc6bea3bbe921528423818504d72',
    full: '49d76d04b66e6ad732a11b9baefa590d',
  },
  'bitstream-bluffs': {
    shape: '81e2ac207bbcb23ce1e7447c3d344e05',
    full: 'c4d0afbe5291e1484d197902ae85f228',
  },
  42: {
    shape: 'acb168d64667adf2794a582f25e77fd1',
    full: '0ba820a0940256c8c6da9a3112d5e4cf',
  },
  'seed@mask0': {
    shape: '6dae8ae9045446ea0fd3915b1b733c60',
    full: 'f50efa6c10aaf97d6ffa89425bb15c63',
  },
  '2026-11-13': {
    shape: '6f9d1a090f2bd54e32cf0419a6c8e12a',
    full: 'de6a60d7084ab6e1b0ab77ae37848f5f',
  },
};

/**
 * Whole-chunk digests, recorded at BOTH `06e79f5` and `e0ae90f` with `biomeMask = 0` (identical at
 * both, 2026-11-14 audit). `full` above was written by hand and misses things that are gameplay:
 * power-ups, launches, the zone `modId` (it hashes `z.id`, which does not exist, so every zone
 * hashed as `null`), and hazard rotation (it hashes `speedPxS`, which does not exist either). The
 * audit proved the gap by mutation: swapping a zone modId past 2 km left `full` green. `complete`
 * hashes every field of every chunk instead, so nothing that ships in a chunk can move unseen.
 * `shape` and `full` stay as they were so their history and failure-layer diagnosis still hold.
 */
const COMPLETE = {
  alpha: '89b27d5e315159a45daa1454e4fc30c6',
  'bitstream-bluffs': '98a0ff45aedb2ba622157a96f3703436',
  42: '8ce76450881e0516408f70c877afcdbd',
  'seed@mask0': 'b204706f8fb22f0ee5c10a614d76b984',
  '2026-11-13': '68555f37f29225fc06df702915ba8dd2',
};

/** Every field, keys sorted, numbers rounded like `round` below. */
const completeOf = (v) =>
  Array.isArray(v)
    ? v.map(completeOf)
    : v && typeof v === 'object'
      ? Object.fromEntries(Object.keys(v).sort().map((k) => [k, completeOf(v[k])]))
      : typeof v === 'number'
        ? round(v)
        : v;

/**
 * A chunk reduced to everything that affects play, in a fixed key order.
 *
 * Built explicitly rather than by `JSON.stringify(chunk)` so that adding a purely cosmetic field to
 * a chunk (a future colour, a debug label) does not fail the golden test for no gameplay reason —
 * while any change to a point, a hazard, a shard, a pad or a gap does.
 */
function shapeOf(chunk) {
  return {
    index: chunk.index,
    kind: chunk.kind,
    startX: round(chunk.startX),
    endX: round(chunk.endX),
    points: chunk.points.map((p) => [round(p.x), round(p.y)]),
  };
}

function fullOf(chunk) {
  return {
    ...shapeOf(chunk),
    hazards: (chunk.hazards || []).map((h) => [round(h.x), round(h.y), h.defId, round(h.speedPxS)]),
    shards: (chunk.shards || []).map((s) => [round(s.x), round(s.y)]),
    bouncePads: (chunk.bouncePads || []).map((b) => [round(b.x), round(b.y)]),
    zones: (chunk.zones || []).map((z) => [z.id, round(z.x0), round(z.x1)]),
    gaps: (chunk.gaps || []).map((g) => [round(g.x0), round(g.x1)]),
  };
}

/**
 * 4 decimals: sub-thousandth-of-a-pixel differences are not gameplay and would make the pin
 * brittle against float noise in a legitimate refactor of the maths that provably cannot move a
 * rendered pixel. Anything a player can feel moves a point by far more than 0.0001 px.
 */
const round = (n) => (Number.isFinite(n) ? Math.round(n * 1e4) / 1e4 : n);

function digest(value) {
  return crypto.createHash('sha256').update(JSON.stringify(value)).digest('hex').slice(0, 32);
}

function stream(seed, project) {
  const gen = makeGen(seed, { biomeMask: 0 });
  const out = [];
  for (let i = 0; i < CHUNKS; i++) out.push(project(gen.getChunk(i)));
  return out;
}

describe('golden terrain — mask 0 must never change (SPEC §9)', () => {
  test('the golden table is fully recorded, not left as placeholders', () => {
    // Guards the failure mode where someone adds a seed and forgets to fill in its digests: a
    // placeholder would silently never match, and a `toMatchSnapshot`-style auto-accept habit would
    // turn this whole file into decoration.
    for (const [seed, hashes] of Object.entries(GOLDEN)) {
      expect({ seed, shape: hashes.shape, full: hashes.full }).toMatchObject({
        seed,
        shape: expect.stringMatching(/^[0-9a-f]{32}$/),
        full: expect.stringMatching(/^[0-9a-f]{32}$/),
      });
    }
    expect(Object.keys(GOLDEN).sort()).toEqual([...SEEDS].sort());
    expect(Object.keys(COMPLETE).sort()).toEqual([...SEEDS].sort());
  });

  for (const seed of SEEDS) {
    describe(`seed ${seed}`, () => {
      test('geometry is bit-identical to the recorded baseline', () => {
        expect(digest(stream(seed, shapeOf))).toBe(GOLDEN[seed].shape);
      });

      test('geometry plus every spawned object is bit-identical to the baseline', () => {
        expect(digest(stream(seed, fullOf))).toBe(GOLDEN[seed].full);
      });

      test('every field of every chunk (power-ups, launches, zone modIds included) is bit-identical', () => {
        expect(digest(stream(seed, completeOf))).toBe(COMPLETE[seed]);
      });
    });
  }

  test('mask 0 generates identically in a second generator instance (no hidden state)', () => {
    // Two instances in one process, interleaved reads: catches a module-level cache or a shared
    // mutation that would make the hashes above order-dependent.
    const a = makeGen('alpha', { biomeMask: 0 });
    const b = makeGen('alpha', { biomeMask: 0 });
    for (let i = 0; i < 60; i++) {
      expect(JSON.stringify(fullOf(b.getChunk(59 - i)))).toBe(JSON.stringify(fullOf(a.getChunk(59 - i))));
    }
  });

  test('the range really does cross sector boundaries, so the pin covers them', () => {
    // If CHUNKS were shortened below one sector this test would fail, which is the point: the
    // golden range has to be long enough to exercise the sector-driven behaviour it claims to pin.
    const gen = makeGen('alpha', { biomeMask: 0 });
    const first = gen.getChunk(0);
    const last = gen.getChunk(CHUNKS - 1);
    const spanM = (last.endX - first.startX) / 20; // PIXELS_PER_METER = 20
    expect(spanM).toBeGreaterThan(1500);
    const kinds = new Set();
    for (let i = 0; i < CHUNKS; i++) kinds.add(gen.getChunk(i).kind);
    // Measured at 06e79f5: spline 259 / noise 34 / bridge 7 for seed 'alpha'. All three matter —
    // noise zones and bridge gaps are the two code paths most likely to be disturbed by new
    // biome geometry, so pinning a range that only ever produced splines would miss them.
    expect([...kinds].sort()).toEqual(['bridge', 'noise', 'spline']);
  });
});import { spawnSync } from 'node:child_process';
import { TerrainGenerator, blindClearAheadPx } from '../../src/systems/TerrainGenerator.js';
import { scanBlindClearance, validateOriginWindow } from '../../tools/sim/terrain-preflight.js';
import { loadContent } from './_helpers.js';

const content = loadContent();
const generator = (seed, biomeMask = 16) => new TerrainGenerator({
  seed, biomeMask, chunkDefs: content.chunks, hazardDefs: content.hazards, powerupDefs: content.powerups,
  modDefs: content.terrainMods, biomeDefs: Object.values(content.biomes),
});
const scan = (seed, fromChunk, chunkCount = 1, mask = 16) =>
  scanBlindClearance(generator(seed, mask), content.hazards, { fromChunk, chunkCount });
const wallTo = (result, x, id) => result.findings.find(({ source, target }) => source.worldXPx === x && target.hazardId === id);

const runCLI = (...args) => spawnSync(process.execPath, ['tools/sim/terrain-preflight.mjs', ...args], { encoding: 'utf8' });

// re-pinned for #65: Debutmont base + arcade bridges. The seeds' terrain moved (new base biome, bridged biome changes), so
// the cases were re-found with the same scan (mask 16, chunks 0-255) and keep their intent: a window found past the origin
// crop, one hazard pair inside the nominal blind window and one outside it, and a two-chunk lookahead. fair15 and fair4 kept
// their seeds. terrain-lint-417 no longer has a two-chunk case, so that row is terrain-lint-1 (also two chunks ahead,
// just outside the nominal window).
test.each([
  ['fair15', 28, 57021, 29, 57548, 'packetSpike', 527, 1312, true],
  ['fair4', 119, 267176, 120, 267814, 'packetSpike', 638, 1428, true],
  ['terrain-lint-1', 95, 207609, 97, 209032, 'packetSpike', 1423, 1428, false],
])('production geometry: %s detects exact window past the origin crop', (seed, i, x, j, next, hazardId, gap, clearance, nominal) => {
  const result = scan(seed, i);
  expect(result).toMatchObject({ seed, biomeMask: 16, pixelsPerMeter: 20, originWindow: { fromChunk: i, endChunkExclusive: i + 1 } });
  expect(result.lookahead.additionalChunks).toBeGreaterThanOrEqual(j - i);
  const finding = wallTo(result, x, hazardId);
  expect(finding).toMatchObject({
    source: { hazardId: 'shatterWall', chunkIndex: i, worldXPx: x, placement: 'ground', generatorDistanceM: x / 20 },
    target: { hazardId, chunkIndex: j, worldXPx: next, generatorDistanceM: next / 20, motionKind: null },
    separationPx: gap, separationM: gap / 20, clearAheadPx: clearance, withinNominalBlind: nominal, crossChunk: true,
  });
  expect(Number.isFinite(finding.source.worldYPx)).toBe(true);
  expect(Number.isFinite(finding.target.worldYPx)).toBe(true);
  expect(wallTo(scan(seed, i, 4), x, hazardId)).toEqual(finding);
  expect(scan(seed, i, 1, 0).findings).toEqual([]);
});

test('preserves every pair in stable downstream order rather than reporting only the closest', () => {
  expect(scan('fair4', 119).findings.map(({ target, separationPx, withinNominalBlind }) =>
    [target.worldXPx, separationPx, withinNominalBlind])).toEqual([
    [267814, 638, true], [268534, 1358, false],
  ]);
});

test('strictly forward, inclusive clearance at a chunk boundary, and no lookahead-only origins', () => {
  const x = 100, ppm = 20;
  const blind = { id: 'wall', placement: 'air', onHit: { effect: 'blind', durationMs: 1200 } };
  const clearance = blindClearAheadPx(blind.onHit, x / ppm);
  const border = x + clearance;
  const def = { wall: blind, roll: { id: 'roll', motion: { kind: 'roll' } }, gate: { id: 'gate', motion: { kind: 'gate' } } };
  const at = (defId, x) => ({ defId, x, y: 20 });
  const chunks = [
    { index: 0, startX: 0, endX: border, hazards: [at('wall', x), at('roll', x), at('roll', x - 1), at('gate', x + 2)] },
    { index: 1, startX: border, endX: border + 200, hazards: [at('roll', border + 1), at('wall', border + 100), at('roll', border)] },
  ];
  const result = scanBlindClearance({ seed: 'fixture', biomeMask: 0, ppm, crashHazardIds: new Set(['roll', 'gate']),
    getChunk: (i) => chunks[i] }, def, { chunkCount: 1 });
  expect(result.lookahead).toEqual({ additionalChunks: 1, endInspectedChunkExclusive: 2, throughWorldXPx: border + 200 });
  expect(result.blindSpawnCount).toBe(1);
  expect(result.findings.map(({ source, target, separationPx, crossChunk }) =>
    [source.placement, target.motionKind, separationPx, crossChunk])).toEqual([
    ['air', 'gate', 2, false], ['air', 'roll', clearance, true],
  ]);
});

test('rejects a malformed range or failed lookahead rather than returning a falsely clear result', () => {
  expect(() => validateOriginWindow(4096, 1)).toThrow(/exclusive end/);
  expect(() => validateOriginWindow(0, 257)).toThrow(/origin chunks/);
  expect(() => validateOriginWindow(-1, 1)).toThrow(/origin chunks/);
  expect(() => validateOriginWindow(0, 0)).toThrow(/origin chunks/);
  const terrain = { seed: 'fixture', biomeMask: 0, ppm: 20, crashHazardIds: new Set(), getChunk: (i) => ({
    index: i, startX: i, endX: i + 1, hazards: i === 0 ? [{ defId: 'wall', x: 0, y: 0 }] : [],
  }) };
  expect(() => scanBlindClearance(terrain, { wall: { onHit: { effect: 'blind' } } }, { chunkCount: 1 })).toThrow(/lookahead exceeded/);
  expect(() => scanBlindClearance({ ...terrain, getChunk: (i) => ({ ...terrain.getChunk(i), startX: 2 * i, endX: 2 * i + 1 }) },
    { wall: { onHit: { effect: 'blind' } } }, { chunkCount: 1 })).toThrow(/noncontiguous/);
});

test('CLI emits stable JSON with fingerprinted loaded sources and no output on invalid input', () => {
  const args = ['--seed', 'fair15', '--mask', '16', '--from-chunk', '28', '--chunks', '1'];
  const one = runCLI(...args), two = runCLI(...args);
  expect(one).toMatchObject({ status: 0, stderr: '' });
  expect(two.stdout).toBe(one.stdout);
  expect(JSON.parse(one.stdout).provenance).toMatchObject({ algorithm: 'sha256-framed-relative-path-file-bytes-v1',
    sha256: expect.stringMatching(/^[0-9a-f]{64}$/), files: expect.any(Number),
    generatorFiles: expect.arrayContaining(['src/systems/TerrainGenerator.js']),
    contentGlobs: expect.arrayContaining(['src/data/hazards/*.json']) });
  const literal = runCLI('--seed', '--literal', '--mask', '0', '--chunks', '1');
  expect(literal.status).toBe(0);
  expect(JSON.parse(literal.stdout).seed).toBe('--literal');
  for (const bad of [[], ['--seed', 'x'], ['--seed', 'x', '--mask', '4294967296'], ['--seed', 'x', '--mask', '0x10'],
    ['--seed', 'x', '--mask', '16', '--mask', '0'], ['--seed', 'x', '--mask', '16', '--chunks', '257'],
    ['--seed', 'x', '--mask', '16', '--from-chunk', '4096'], ['--seed', '\n', '--mask', '0'],
    ['--seed', 'x', '--mask', '16', '--out', 'path']]) {
    expect(runCLI(...bad)).toMatchObject({ status: 1, stdout: '', stderr: expect.stringMatching(/^Terrain preflight:/) });
  }
});import crypto from 'crypto';
import {
  TerrainGenerator, SPACING_PX, HAZARD_MIN_SPACING_PX, HAZARD_MIN_X_PX, CREST_TURN_DEG, NOISE_CREST_TURN_DEG, SHARP_TAGS, SECTOR_M,
  HAZARD_SOFT_PX, HAZARD_SAFE_PX, expectedSpeedPxS, POWERUP_FLOOR_FRACTION,
  AIR_HAZARD_MIN_M, AIR_CLEARANCE_PX, AIR_SPEED_LO_MUL, AIR_SPEED_HI_MUL, JUMP_LAUNCH_SPEED_PX_S,
  AIR_MIN_DX_PX, AIR_U_MIN, AIR_U_MAX, AIR_NEAR_MISS_BELOW_PX, HAZARD_RETRY_FROM_M,
} from '../../src/systems/TerrainGenerator.js';
import { SLOW_HAZARD_MIN_DEG, SLOW_HAZARD_CLEAR_PX, RUNOUT_TURN_DEG } from '../../src/systems/TerrainGenerator.js';
import { TERRAIN, PIXELS_PER_METER } from '../../src/constants.js';
import { makeGen as makeGenWithBiomes, loadContent, segAngle, inGap, rollSim, findLaunches } from './_helpers.js';

// These tests pin the core terrain machinery (shape, spacing, hazard and launch frequencies, digests). Since #65 the
// home biome (Debutmont) is the base, so a generator built WITH biome content flavours even mask-0 terrain. The core
// rules here are asserted without biome content, as before; biome terrain has its own tests (biomes.test.js,
// biome-bridges.test.js and the per-biome suites).
const makeGen = (seed, overrides = {}) => makeGenWithBiomes(seed, { biomeDefs: [], ...overrides });

const snap = (c) => JSON.parse(JSON.stringify(c));
const isAirDef = (defs, h) => defs[h.defId].placement === 'air';
/** Ground hazards of a chunk (air hazards float in jump arcs and have their own tests). */
const groundHazards = (defs, c) => c.hazards.filter((h) => !isAirDef(defs, h));
const N = 300; // chunks examined in the bulk tests (several kilometres of track)

describe('TerrainGenerator determinism', () => {
  test('same seed => identical chunks', () => {
    const a = makeGen('alpha');
    const b = makeGen('alpha');
    for (let i = 0; i < 80; i++) expect(snap(a.getChunk(i))).toEqual(snap(b.getChunk(i)));
  });

  test('different seeds differ', () => {
    const a = makeGen('alpha');
    const b = makeGen('beta');
    let diff = 0;
    for (let i = 0; i < 20; i++) if (JSON.stringify(a.getChunk(i).points) !== JSON.stringify(b.getChunk(i).points)) diff++;
    expect(diff).toBeGreaterThanOrEqual(18);
  });

  test('getChunk is independent of call order', () => {
    const seq = makeGen('order');
    const rev = makeGen('order');
    const expected = [];
    for (let i = 0; i < 40; i++) expected.push(snap(seq.getChunk(i)));
    // jump far ahead first, then go backwards
    expect(snap(rev.getChunk(39))).toEqual(expected[39]);
    for (let i = 38; i >= 0; i--) expect(snap(rev.getChunk(i))).toEqual(expected[i]);
  });

  test('chunk content does not depend on content array order', () => {
    const c = loadContent();
    const a = makeGen('x', { chunkDefs: c.chunks });
    const b = makeGen('x', { chunkDefs: c.chunks.slice().reverse() });
    for (let i = 0; i < 30; i++) expect(snap(a.getChunk(i))).toEqual(snap(b.getChunk(i)));
  });

  test('hazard content changes do not change terrain shape', () => {
    const c = loadContent();
    const a = makeGen('shape');
    const b = makeGen('shape', { hazardDefs: {}, powerupDefs: {} });
    for (let i = 0; i < 40; i++) expect(a.getChunk(i).points).toEqual(b.getChunk(i).points);
  });

  test('throws for negative index', () => {
    expect(() => makeGen().getChunk(-1)).toThrow(RangeError);
  });

  test('works with no content at all (builtin fallback)', () => {
    const g = new TerrainGenerator({ seed: 's', chunkDefs: [], hazardDefs: {}, powerupDefs: {}, modDefs: {} });
    for (let i = 0; i < 20; i++) {
      const c = g.getChunk(i);
      expect(c.points.length).toBeGreaterThan(10);
      expect(c.hazards).toEqual([]);
    }
  });
});

describe('TerrainGenerator geometry guarantees', () => {
  const g = makeGen('geometry-seed');
  const chunks = [];
  for (let i = 0; i < N; i++) chunks.push(g.getChunk(i));

  test('chunk 0 starts at x=0 with a gentle run-in', () => {
    const c = chunks[0];
    expect(c.startX).toBe(0);
    expect(c.points[0]).toEqual({ x: 0, y: 0 });
    expect(g.getStartPosition()).toEqual({ x: 0, y: 0 });
    for (let i = 0; i < 20; i++) expect(Math.abs(segAngle(c.points, i))).toBeLessThan(25);
    expect(c.hazards).toEqual([]);
  });

  test('x strictly increasing, spacing within TERRAIN limits, startX/endX match points', () => {
    for (const c of chunks) {
      expect(c.startX).toBe(c.points[0].x);
      expect(c.endX).toBe(c.points[c.points.length - 1].x);
      for (let i = 0; i < c.points.length - 1; i++) {
        const dx = c.points[i + 1].x - c.points[i].x;
        if (dx < TERRAIN.minPointSpacingPx || dx > TERRAIN.maxPointSpacingPx) throw new Error(`bad spacing ${dx}`);
      }
    }
    expect(SPACING_PX).toBeGreaterThanOrEqual(TERRAIN.minPointSpacingPx);
  });

  test('chunk borders share the exact same point and slope is roughly continuous', () => {
    for (let i = 0; i < N - 1; i++) {
      const a = chunks[i];
      const b = chunks[i + 1];
      expect(b.index).toBe(a.index + 1);
      expect(b.points[0]).toEqual(a.points[a.points.length - 1]);
      const sa = segAngle(a.points, a.points.length - 2);
      const sb = segAngle(b.points, 0);
      if (Math.abs(sa - sb) > 12) throw new Error(`slope jump ${sa} -> ${sb} at chunk ${i}`);
    }
  });

  test('slope never exceeds TERRAIN.maxSlopeDeg (outside bridge gaps) and curvature is limited', () => {
    let maxDown = -Infinity;
    let maxUp = Infinity;
    for (const c of chunks) {
      let prev = null;
      for (let i = 0; i < c.points.length - 1; i++) {
        if (inGap(c, i)) { prev = null; continue; }
        const a = segAngle(c.points, i);
        maxDown = Math.max(maxDown, a);
        maxUp = Math.min(maxUp, a);
        if (prev !== null && Math.abs(a - prev) > 17.01) throw new Error(`kink ${prev}->${a}`);
        prev = a;
      }
    }
    expect(maxDown).toBeLessThan(TERRAIN.maxSlopeDeg);
    expect(maxUp).toBeGreaterThan(-TERRAIN.maxSlopeDeg);
    expect(maxDown).toBeLessThanOrEqual(42.0001);
  });

  test('gap interpolation lines are also below the max slope', () => {
    for (const c of chunks) {
      for (const gp of c.gaps) {
        const y0 = g.heightAt(gp.x0);
        const y1 = g.heightAt(gp.x1);
        const a = (Math.atan2(y1 - y0, gp.x1 - gp.x0) * 180) / Math.PI;
        expect(a).toBeLessThan(TERRAIN.maxSlopeDeg);
      }
    }
  });

  test('track is always downhill overall: every chunk descends, and every 4000 px window descends', () => {
    for (const c of chunks) expect(c.points[c.points.length - 1].y).toBeGreaterThan(c.points[0].y);
    for (let x = 0; x + 4000 < chunks[N - 1].startX; x += 500) {
      expect(g.heightAt(x + 4000) - g.heightAt(x)).toBeGreaterThan(150);
    }
  });

  test('all numbers are finite', () => {
    for (const c of chunks) for (const p of c.points) expect(Number.isFinite(p.x) && Number.isFinite(p.y)).toBe(true);
  });

  test('a mix of template kinds and defs is used (data driven)', () => {
    const defs = new Set(chunks.map((c) => c.defId));
    const kinds = new Set(chunks.map((c) => c.kind));
    expect(defs.size).toBeGreaterThanOrEqual(10);
    expect([...kinds].sort()).toEqual(['bridge', 'noise', 'spline']);
  });

  test('chunk defs respect minDistanceM', () => {
    const defs = Object.fromEntries(loadContent().chunks.map((d) => [d.id, d]));
    for (const c of chunks) if (c.defId !== 'gen-jump') expect(c.startX / PIXELS_PER_METER).toBeGreaterThanOrEqual(defs[c.defId].minDistanceM);
  });

  test('pack structure: noise zones appear, and are not adjacent to each other', () => {
    const noiseIdx = chunks.filter((c) => c.kind === 'noise').map((c) => c.index);
    expect(noiseIdx.length).toBeGreaterThan(5);
    for (let i = 1; i < noiseIdx.length; i++) expect(noiseIdx[i] - noiseIdx[i - 1]).toBeGreaterThan(1);
  });

  test('chunk length escalates over the run (spline chunks later in the track are longer on average)', () => {
    const len = (c) => c.endX - c.startX;
    const spl = chunks.filter((c) => c.kind === 'spline');
    const early = spl.filter((c) => c.index < 40);
    const late = spl.filter((c) => c.index > 200);
    const avg = (a) => a.reduce((s, c) => s + len(c) / 1, 0) / a.length;
    expect(avg(late)).toBeGreaterThan(avg(early));
  });
});

describe('TerrainGenerator invariants across many seeds', () => {
  test('continuity, slope limits, descent and spacing hold for 25 seeds x 400 chunks', () => {
    for (let s = 0; s < 25; s++) {
      const gen = makeGen('multi-' + s);
      let prev = null;
      for (let i = 0; i < 400; i++) {
        const c = gen.getChunk(i);
        if (prev) {
          expect(c.points[0]).toEqual(prev.points[prev.points.length - 1]);
          const d = Math.abs(segAngle(prev.points, prev.points.length - 2) - segAngle(c.points, 0));
          if (d > 12) throw new Error(`seed ${s} chunk ${i}: slope jump ${d}`);
        }
        if (!(c.points[c.points.length - 1].y > c.points[0].y)) throw new Error(`seed ${s} chunk ${i} does not descend`);
        for (let k = 0; k < c.points.length - 1; k++) {
          if (inGap(c, k)) continue;
          const a = segAngle(c.points, k);
          if (a >= TERRAIN.maxSlopeDeg || a <= -TERRAIN.maxSlopeDeg) throw new Error(`seed ${s} chunk ${i}: slope ${a}`);
          const dx = c.points[k + 1].x - c.points[k].x;
          if (dx < TERRAIN.minPointSpacingPx || dx > TERRAIN.maxPointSpacingPx) throw new Error('spacing');
        }
        prev = c;
      }
    }
  });
});

describe('TerrainGenerator spawns', () => {
  const g = makeGen('spawns-seed');
  const chunks = [];
  for (let i = 0; i < N; i++) chunks.push(g.getChunk(i));
  const content = loadContent();

  test('hazards: valid defs, ground ones sit on the surface, never at the start, min distance and spacing respected', () => {
    const all = [];
    for (const c of chunks) {
      for (const h of c.hazards) {
        all.push(h);
        expect(content.hazards[h.defId]).toBeDefined();
        expect(h.x).toBeGreaterThanOrEqual(HAZARD_MIN_X_PX);
        expect(h.x).toBeGreaterThanOrEqual(c.startX);
        expect(h.x).toBeLessThanOrEqual(c.endX);
        expect(h.x / PIXELS_PER_METER).toBeGreaterThanOrEqual(content.hazards[h.defId].minDistanceM);
        if (isAirDef(content.hazards, h)) {
          expect(h.y).toBeLessThan(g.heightAt(h.x) - content.hazards[h.defId].size.h); // floats clear of the ground
          expect(h.rotationDeg).toBe(0);
        } else {
          expect(g.heightAt(h.x)).toBeCloseTo(h.y, 6);
          expect(Math.abs(h.rotationDeg)).toBeLessThan(30);
        }
      }
    }
    expect(all.length).toBeGreaterThan(100);
    all.sort((a, b) => a.x - b.x);
    for (let i = 1; i < all.length; i++) expect(all[i].x - all[i - 1].x).toBeGreaterThanOrEqual(HAZARD_MIN_SPACING_PX - 1);
  });

  test('hazards are not placed on bridge chunks, in gaps, or on steep slopes', () => {
    for (const c of chunks) {
      if (c.kind === 'bridge') expect(c.hazards).toEqual([]);
      for (const h of groundHazards(content.hazards, c)) {
        for (const gp of c.gaps) expect(h.x < gp.x0 || h.x > gp.x1).toBe(true);
        const slope = g.slopeDegAt(h.x);
        expect(slope).toBeLessThan(30);
        expect(slope).toBeGreaterThan(-17.5);
      }
    }
  });

  test('all hazard types eventually appear (weighted, data driven)', () => {
    const seen = new Set(chunks.flatMap((c) => c.hazards.map((h) => h.defId)));
    // base defs only: a biome-tagged def (B1+) never spawns at mask 0 by design (spec §5, E4)
    expect([...seen].sort()).toEqual(Object.keys(content.hazards).filter((id) => !content.hazards[id].biome).sort());
  });

  test('hazard density increases past 1000 m', () => {
    let early = 0;
    let late = 0;
    let earlyLen = 0;
    let lateLen = 0;
    for (let s = 0; s < 6; s++) {
      const gen = makeGen('density-' + s);
      for (let i = 0; i < 200; i++) {
        const c = gen.getChunk(i);
        const dM = c.startX / PIXELS_PER_METER;
        const len = c.endX - c.startX;
        if (dM > 150 && dM < 500) { early += c.hazards.length; earlyLen += len; }
        else if (dM > 4500) { late += c.hazards.length; lateLen += len; }
      }
    }
    expect(earlyLen).toBeGreaterThan(0);
    expect(lateLen).toBeGreaterThan(0);
    expect(late / lateLen).toBeGreaterThan((early / earlyLen) * 1.2);
  });

  test('power-ups: valid, lifted above ground, clear of hazards, probability falls with distance', () => {
    let nearCount = 0;
    let farCount = 0;
    let nearLen = 0;
    let farLen = 0;
    for (let s = 0; s < 8; s++) {
      const gen = makeGen('pu-' + s);
      for (let i = 0; i < 300; i++) {
        const c = gen.getChunk(i);
        const dM = c.startX / PIXELS_PER_METER;
        for (const p of c.powerups) {
          expect(content.powerups[p.defId]).toBeDefined();
          expect(p.y).toBeLessThan(gen.heightAt(p.x) - content.powerups[p.defId].radius);
          for (const h of c.hazards) expect(Math.abs(h.x - p.x)).toBeGreaterThanOrEqual(90);
        }
        const len = c.endX - c.startX;
        if (dM < 1000) { nearCount += c.powerups.length; nearLen += len; }
        else if (dM > 5000) { farCount += c.powerups.length; farLen += len; }
      }
    }
    expect(nearCount).toBeGreaterThan(5);
    // falls with distance, but only down to the POWERUP_FLOOR_FRACTION floor (40 % of base), not toward zero
    expect(nearCount / nearLen).toBeGreaterThan((farCount / farLen) * 1.3);
    expect(farCount).toBeGreaterThan(30);
  });

  test('power-up chance floor: late-game spawn rate stays at >= ~40 % of the base chance', () => {
    expect(POWERUP_FLOOR_FRACTION).toBe(0.4);
    // slots are 320-640 px apart (mean 480): expected spawns per slot ~ mean def chance; count over many far chunks
    const defs = Object.values(content.powerups);
    const meanBase = defs.reduce((a, d) => a + d.spawn.baseChance, 0) / defs.length;
    let slots = 0;
    let spawned = 0;
    for (let s = 0; s < 10; s++) {
      const gen = makeGen('floor-' + s);
      for (let i = 400; i < 520; i++) {
        const c = gen.getChunk(i);
        if (c.startX / PIXELS_PER_METER < 8000) continue;
        spawned += c.powerups.length;
        slots += (c.endX - c.startX - 480) / 480;
      }
    }
    expect(slots).toBeGreaterThan(300);
    const rate = spawned / slots;
    expect(rate).toBeGreaterThan(meanBase * POWERUP_FLOOR_FRACTION * 0.6); // clears and hazards remove a few slots
    expect(rate).toBeLessThan(meanBase * 0.6); // decayed chance is ~base/6 here, so the floor (0.4) is what applies
  });

  test('zones: inside their chunk, valid mod ids, respect min distance, wirelessBridge only on bridges', () => {
    let seen = new Set();
    for (const c of chunks) {
      for (const z of c.zones) {
        seen.add(z.modId);
        expect(content.terrainMods[z.modId]).toBeDefined();
        expect(z.x0).toBeLessThan(z.x1);
        expect(z.x0).toBeGreaterThanOrEqual(c.startX);
        expect(z.x1).toBeLessThanOrEqual(c.endX);
        expect(z.x0 / PIXELS_PER_METER).toBeGreaterThanOrEqual(content.terrainMods[z.modId].minDistanceM - 1);
        if (z.modId === 'wirelessBridge') expect(c.kind).toBe('bridge');
        if (c.kind === 'bridge') expect(z.modId).toBe('wirelessBridge');
      }
    }
    expect([...seen].sort()).toEqual(['compression', 'highBandwidth', 'wirelessBridge']);
  });

  test('bridge chunks: gap on polyline points, bounce pad on solid ground before it, boost from def', () => {
    const bridges = chunks.filter((c) => c.kind === 'bridge');
    expect(bridges.length).toBeGreaterThan(3);
    for (const c of bridges) {
      expect(c.gaps.length).toBe(1);
      const { x0, x1 } = c.gaps[0];
      expect(c.points.some((p) => p.x === x0)).toBe(true);
      expect(c.points.some((p) => p.x === x1)).toBe(true);
      expect(x1 - x0).toBeLessThanOrEqual(224);
      expect(x1 - x0).toBeGreaterThanOrEqual(64);
      expect(c.bouncePads.length).toBeGreaterThanOrEqual(1);
      const def = content.chunks.find((d) => d.id === c.defId);
      for (const pad of c.bouncePads) {
        expect(pad.x + pad.width / 2).toBeLessThanOrEqual(x0);
        expect(pad.x - pad.width / 2).toBeGreaterThan(c.startX);
        expect(pad.boost).toBe(def.bridge.bounceBoost);
        expect(g.heightAt(pad.x)).toBeCloseTo(pad.y, 6);
      }
      // landing platform is solid and long enough after the gap
      expect(c.endX - x1).toBeGreaterThanOrEqual(14 * SPACING_PX - 1);
    }
  });

  test('bridge gaps are always jumpable: bounce pad launch at modest speed clears the gap', () => {
    const bridges = chunks.filter((c) => c.kind === 'bridge');
    for (const c of bridges) {
      const { x0, x1 } = c.gaps[0];
      const pad = c.bouncePads[0];
      for (const vx of [250, 400, 700]) {
        let x = pad.x;
        let y = pad.y;
        let vy = -pad.boost;
        const dt = 1 / 240;
        let guard = 0;
        while (x < x1 && guard++ < 10000) {
          x += vx * dt;
          vy += 900 * dt;
          y += vy * dt;
        }
        // at the far edge of the gap the sled must still be above the landing surface
        expect(y).toBeLessThan(g.heightAt(x1));
        expect(x0).toBeLessThan(x);
      }
    }
  });

  test('non-bridge chunks have no gaps or pads', () => {
    for (const c of chunks) if (c.kind !== 'bridge') { expect(c.gaps).toEqual([]); expect(c.bouncePads).toEqual([]); }
  });
});

describe('TerrainGenerator queries', () => {
  test('heightAt interpolates the polyline; slopeDegAt matches segment angle', () => {
    const g = makeGen('queries');
    g.update(0);
    const c = g.getActiveChunks()[0];
    for (let i = 0; i < c.points.length - 1; i += 7) {
      const a = c.points[i];
      const b = c.points[i + 1];
      expect(g.heightAt(a.x)).toBeCloseTo(a.y, 6);
      expect(g.heightAt((a.x + b.x) / 2)).toBeCloseTo((a.y + b.y) / 2, 6);
      expect(g.slopeDegAt((a.x + b.x) / 2)).toBeCloseTo(segAngle(c.points, i), 6);
    }
    expect(g.heightAt(c.endX)).toBeCloseTo(c.points[c.points.length - 1].y, 6);
  });

  test('heightAt works slightly ahead of the live window (extends, reported by next update)', () => {
    const g = makeGen('queries2');
    const ref = makeGen('queries2');
    g.update(0);
    const x = g.getActiveChunks().at(-1).endX + 1500;
    expect(g.heightAt(x)).toBeCloseTo(ref.heightAt(x), 6);
    const r = g.update(0);
    expect(r.added.length).toBeGreaterThan(0);
    expect(r.added.some((c) => c.startX <= x && c.endX >= x)).toBe(true);
  });

  test('heightAt works far ahead of and far behind the live window (temporary rebuild)', () => {
    const g = makeGen('queries3');
    const ref = makeGen('queries3');
    g.update(0);
    expect(g.heightAt(40000)).toBeCloseTo(ref.heightAt(40000), 6);
    for (let x = 0; x < 30000; x += 100) g.update(x);
    expect(g.heightAt(1000)).toBeCloseTo(ref.heightAt(1000), 6);
    expect(g.slopeDegAt(1000)).toBeCloseTo(ref.slopeDegAt(1000), 6);
    // live stream unaffected
    expect(g.getActiveChunks().every((c) => c.index > 5)).toBe(true);
  });

  test('getZonesAt returns the zones containing x', () => {
    const g = makeGen('zones-q');
    let checked = 0;
    for (let i = 0; i < 150 && checked < 5; i++) {
      const c = g.getChunk(i);
      for (const z of c.zones) {
        const mid = (z.x0 + z.x1) / 2;
        const zs = g.getZonesAt(mid);
        expect(zs.some((q) => q.modId === z.modId && q.x0 === z.x0)).toBe(true);
        checked++;
      }
    }
    expect(checked).toBeGreaterThan(0);
    expect(g.getZonesAt(-50)).toEqual([]);
  });

  test('negative x extrapolates and does not throw', () => {
    const g = makeGen('neg');
    expect(() => g.heightAt(-100)).not.toThrow();
    expect(g.getChunkAt(-1)).toBeNull();
  });
});

describe('TerrainGenerator difficulty', () => {
  const g = makeGen('diff');
  test('difficulty steps up once per 500 m sector and keeps rising toward the old baseline', () => {
    const base = g.difficultyAt(0);
    expect(g.difficultyAt(499)).toEqual(base);
    expect(base.sector).toBe(1);
    expect(base.slopeVariance).toBe(1);
    expect(base.hazardDensity).toBeCloseTo(0.8, 6);
    let prev = base;
    for (const d of [500, 1000, 1500, 2500, 4000]) {
      const cur = g.difficultyAt(d);
      expect(cur.sector).toBe(Math.floor(d / SECTOR_M) + 1);
      expect(cur.slopeVariance).toBeGreaterThan(prev.slopeVariance);
      expect(cur.hazardDensity).toBeGreaterThan(prev.hazardDensity);
      expect(cur.glitchFrequency).toBeGreaterThan(prev.glitchFrequency);
      expect(cur.noiseWeightMul).toBeGreaterThan(prev.noiseWeightMul);
      expect(cur.speedBudget).toBeGreaterThanOrEqual(prev.speedBudget);
      prev = cur;
    }
    // the old 1000 m ramp reached 2.1 / 4 by 4000 m; sector steps reach the same ceiling
    expect(g.difficultyAt(4000).hazardDensity).toBeGreaterThan(1.9);
    // the tail creeps on past the old cap, then holds at a hard ceiling
    expect(g.difficultyAt(99999).hazardDensity).toBeCloseTo(2.8, 6);
  });

  test('slope variance makes late terrain bumpier', () => {
    const stdev = (gen, from, to) => {
      const a = [];
      for (let i = from; i < to; i++) {
        const c = gen.getChunk(i);
        if (c.kind !== 'spline' || c.defId === 'gen-jump') continue;
        for (let k = 0; k < c.points.length - 1; k++) a.push(segAngle(c.points, k));
      }
      const m = a.reduce((s, v) => s + v, 0) / a.length;
      return Math.sqrt(a.reduce((s, v) => s + (v - m) ** 2, 0) / a.length);
    };
    let early = 0;
    let late = 0;
    for (let s = 0; s < 4; s++) {
      const gen = makeGen('bumpy-' + s);
      early += stdev(gen, 2, 80);
      late += stdev(gen, 220, 300);
    }
    expect(late).toBeGreaterThan(early);
  });
});

describe('TerrainGenerator streaming and pooling', () => {
  test('update() keeps a 3-screen buffer ahead and drops chunks 2 screens behind', () => {
    const g = makeGen('stream');
    const known = new Set();
    let x = 0;
    for (let f = 0; f < 6000; f++) {
      x += 14; // ~840 px/s at 60 fps
      const { added, removed } = g.update(x);
      for (const c of added) {
        expect(known.has(c.index)).toBe(false);
        known.add(c.index);
      }
      for (const idx of removed) {
        expect(known.has(idx)).toBe(true);
        known.delete(idx);
      }
      const act = g.getActiveChunks();
      expect(act[act.length - 1].endX).toBeGreaterThanOrEqual(x + TERRAIN.bufferAheadScreens * 480);
      expect(act[0].endX).toBeGreaterThanOrEqual(x - TERRAIN.keepBehindScreens * 480 - 1);
      expect(act.length).toBeLessThan(12);
      expect(new Set(act.map((c) => c.index))).toEqual(known);
    }
    expect(x).toBeGreaterThan(80000);
  });

  test('first update generates the initial buffer starting at chunk 0', () => {
    const g = makeGen('first');
    const { added, removed } = g.update(0);
    expect(removed).toEqual([]);
    expect(added[0].index).toBe(0);
    expect(added[added.length - 1].endX).toBeGreaterThanOrEqual(3 * 480);
    expect(g.update(0).added).toEqual([]);
  });

  test('active chunks are contiguous in order', () => {
    const g = makeGen('contig');
    for (let x = 0; x < 50000; x += 37) g.update(x);
    const act = g.getActiveChunks();
    for (let i = 1; i < act.length; i++) {
      expect(act[i].index).toBe(act[i - 1].index + 1);
      expect(act[i].startX).toBe(act[i - 1].endX);
    }
  });

  test('chunk objects are recycled: allocations stay bounded over a very long run', () => {
    const g = makeGen('pool');
    let x = 0;
    let total = 0;
    for (let f = 0; f < 20000; f++) {
      x += 20;
      total += g.update(x).added.length;
    }
    expect(total).toBeGreaterThan(150);
    expect(g.stats.created).toBeLessThan(16);
    expect(g.stats.reused).toBeGreaterThan(total - 16);
    expect(g.pool.length).toBeLessThanOrEqual(6);
    expect(g.activeList.length).toBeLessThan(12);
    expect(g.active.size).toBe(g.activeList.length);
  });

  test('recycled chunk objects are not reused within the same update (consumers still hold them)', () => {
    const g = makeGen('late-reuse');
    let x = 0;
    for (let f = 0; f < 3000; f++) {
      x += 20;
      const before = new Set(g.getActiveChunks());
      const { added, removed } = g.update(x);
      if (removed.length) for (const c of added) expect(before.has(c)).toBe(false);
    }
  });

  test('a recycled chunk can be re-requested and regenerates identically', () => {
    const g = makeGen('regen');
    const first = [];
    let x = 0;
    for (let f = 0; f < 4000; f++) {
      x += 20;
      for (const c of g.update(x).added) if (c.index < 5) first[c.index] = snap(c);
    }
    expect(g.active.has(0)).toBe(false);
    for (let i = 0; i < 5; i++) expect(snap(g.getChunk(i))).toEqual(first[i]);
    // and the live stream is not disturbed by the re-request
    expect(g.getActiveChunks().every((c) => c.index > 4)).toBe(true);
  });

  test('streaming output equals random-access output', () => {
    const a = makeGen('same');
    const b = makeGen('same');
    let x = 0;
    for (let f = 0; f < 2000; f++) {
      x += 25;
      for (const c of a.update(x).added) expect(snap(c)).toEqual(snap(b.getChunk(c.index)));
    }
  });

  test('update() is cheap: well under a millisecond on average once streaming', () => {
    const g = makeGen('perf');
    let x = 0;
    for (let f = 0; f < 300; f++) { x += 15; g.update(x); }
    const t0 = performance.now();
    const frames = 5000;
    for (let f = 0; f < frames; f++) { x += 15; g.update(x); }
    const per = (performance.now() - t0) / frames;
    expect(per).toBeLessThan(0.5);
  });

  test('starting update far from the origin begins at the right chunk', () => {
    const g = makeGen('late-start');
    const ref = makeGen('late-start');
    const { added } = g.update(30000);
    expect(added[0].startX).toBeLessThanOrEqual(30000 - 2 * 480);
    expect(snap(added[0])).toEqual(snap(ref.getChunk(added[0].index)));
  });
});

describe('TerrainGenerator flow rules (QA: hands-off sleds used to stall in dips)', () => {
  const MAX_UP = 12;

  /** Points of the first `n` chunks, bridges excluded (their gap is a deliberate jump). */
  const solid = (g, n) => {
    const out = [];
    for (let i = 0; i < n; i++) {
      const c = g.getChunk(i);
      if (c.kind === 'bridge') continue;
      for (let k = 0; k < c.points.length; k++) out.push({ ...c.points[k], first: k === 0, chunk: c });
    }
    return out;
  };

  test('spline chunks never climb steeper than MAX_UP_DEG and no hill rises far above its valley', () => {
    let worstUp = 0;
    let worstRise = 0;
    for (let s = 0; s < 20; s++) {
      const g = makeGen('flow-' + s);
      for (let i = 0; i < 120; i++) {
        const c = g.getChunk(i);
        if (c.kind !== 'spline') continue;
        let valleyY = c.points[0].y;
        for (let k = 0; k < c.points.length - 1; k++) {
          worstUp = Math.max(worstUp, -segAngle(c.points, k));
          const y = c.points[k + 1].y;
          if (y > c.points[k].y) valleyY = Math.max(valleyY, y);
          else if (y < c.points[k].y) worstRise = Math.max(worstRise, valleyY - y);
        }
      }
    }
    expect(worstUp).toBeLessThanOrEqual(MAX_UP + 1e-6);
    // RISE_MAX_PX is 30 on the raw profile; the start-tangent blend and slope limiter reshape it a little
    expect(worstRise).toBeLessThanOrEqual(70);
  });

  test('a rolling point mass with typical drag never stalls on the first 1.5 km of 40 seeds', () => {
    // 1-D roll along the polyline: 65% of g*sin(slope) (Matter seam losses seen in QA), linear + quadratic drag.
    for (let s = 0; s < 40; s++) {
      const g = makeGen('roll-' + s);
      const pts = solid(g, 40).filter((p, i, a) => i === 0 || p.x > a[i - 1].x);
      let v = 90;
      let i = 0;
      let pos = pts[0].x;
      let below = 0;
      for (let t = 0; t < 120 && i < pts.length - 2 && pos < 1500 * PIXELS_PER_METER; t += 0.01) {
        const a = Math.atan2(pts[i + 1].y - pts[i].y, pts[i + 1].x - pts[i].x);
        v = Math.max(0, v + (900 * Math.sin(a) * 0.65 - 0.2 * v - 0.0003 * v * v) * 0.01);
        pos += v * Math.cos(a) * 0.01;
        while (i < pts.length - 2 && pos >= pts[i + 1].x) i++;
        below = v < 10 ? below + 0.01 : 0;
        if (below > 1) throw new Error(`seed ${s}: stalled at ${Math.round(pos / 20)} m`);
      }
    }
  });

  test('the first segment of every chunk turns by at most 12 degrees from the previous one (noise seams too)', () => {
    for (let s = 0; s < 10; s++) {
      const g = makeGen('seam-' + s);
      let prev = g.getChunk(0);
      for (let i = 1; i < 300; i++) {
        const c = g.getChunk(i);
        if (c.kind !== 'bridge' && prev.kind !== 'bridge') {
          expect(Math.abs(segAngle(prev.points, prev.points.length - 2) - segAngle(c.points, 0))).toBeLessThanOrEqual(12);
        }
        prev = c;
      }
    }
  });
});

describe('TerrainGenerator fun pass: gentle opening', () => {
  test('no crash hazards in the first 150 m (50 seeds), nothing at all in the first 80 m', () => {
    const { hazards } = loadContent();
    for (let sd = 0; sd < 50; sd++) {
      const g = makeGen('gentle-' + sd);
      for (let i = 0; i < 12; i++) {
        const c = g.getChunk(i);
        for (const h of c.hazards) {
          expect(h.x).toBeGreaterThanOrEqual(HAZARD_SOFT_PX);
          if (h.x < HAZARD_SAFE_PX) expect(hazards[h.defId].onHit.effect).not.toBe('crash');
        }
      }
    }
  });

  test('chunk 0 is a speed-building run into one easy jump with a long clean landing', () => {
    for (let sd = 0; sd < 30; sd++) {
      const g = makeGen('open-' + sd);
      const c = g.getChunk(0);
      expect(c.launches.length).toBe(1);
      const l = c.launches[0];
      expect(l.x).toBeLessThan(60 * PIXELS_PER_METER);
      expect(l.x).toBeGreaterThan(400);
      expect(l.airS).toBeGreaterThanOrEqual(0.5);
      expect(l.landX).not.toBeNull();
      // runs downhill all the way up to the lip
      for (let i = 0; i < Math.floor((l.x - 160) / SPACING_PX); i++) expect(segAngle(c.points, i)).toBeGreaterThan(5);
      // landing ramp: a down-slope under the landing point, then at least 240 px of runout in the same chunk
      expect(segAngle(c.points, Math.floor((l.landX - c.startX) / SPACING_PX))).toBeGreaterThan(20);
      expect(c.endX - l.landX).toBeGreaterThan(240);
      expect(c.hazards).toEqual([]);
    }
  });

  test('an independent ballistic check finds the first launch within 60 m', () => {
    for (let sd = 0; sd < 10; sd++) {
      const L = findLaunches(makeGen('first-' + sd), 6, 380, 0.5);
      expect(L.length).toBeGreaterThan(0);
      expect(L[0].x).toBeLessThan(60 * PIXELS_PER_METER);
    }
  });

  test('hazard density ramps in smoothly rather than at full density', () => {
    let early = 0;
    let earlyLen = 0;
    let mid = 0;
    let midLen = 0;
    for (let sd = 0; sd < 12; sd++) {
      const g = makeGen('ramp-' + sd);
      for (let i = 0; i < 60; i++) {
        const c = g.getChunk(i);
        const m = c.startX / PIXELS_PER_METER;
        if (m < 300) { early += c.hazards.length; earlyLen += c.endX - c.startX; }
        else if (m >= 1000 && m < 2500) { mid += c.hazards.length; midLen += c.endX - c.startX; }
      }
    }
    expect(mid / midLen).toBeGreaterThan((early / earlyLen) * 1.2);
  });
});

describe('TerrainGenerator fun pass: launches and crests', () => {
  const content = loadContent();
  const sharp = Object.fromEntries(content.chunks.map((d) => [d.id, (d.tags || []).some((t) => SHARP_TAGS.includes(t))]));
  sharp['gen-jump'] = true;

  test('launches happen every ~2000-3500 px on average and get airier with distance', () => {
    const xs = [];
    const earlyAir = [];
    const lateAir = [];
    for (let sd = 0; sd < 12; sd++) {
      const g = makeGen('launch-' + sd);
      let last = null;
      for (let i = 0; i < 80; i++) {
        for (const l of g.getChunk(i).launches) {
          if (last !== null) xs.push(l.x - last);
          last = l.x;
          (l.x / PIXELS_PER_METER < 800 ? earlyAir : lateAir).push(l.airS);
        }
      }
    }
    const mean = xs.reduce((a, b) => a + b, 0) / xs.length;
    expect(mean).toBeGreaterThan(1800);
    expect(mean).toBeLessThan(3800);
    const avg = (a) => a.reduce((x, y) => x + y, 0) / a.length;
    expect(avg(lateAir)).toBeGreaterThan(avg(earlyAir));
    expect(avg(lateAir)).toBeGreaterThan(0.9);
    expect(Math.max(...lateAir)).toBeLessThan(1.8);
  });

  test('generated jumps land on a down-slope inside the chunk', () => {
    for (let sd = 0; sd < 8; sd++) {
      const g = makeGen('land-' + sd);
      for (let i = 0; i < 80; i++) {
        const c = g.getChunk(i);
        if (c.defId !== 'gen-jump') continue;
        const l = c.launches[0];
        expect(l).toBeDefined();
        expect(l.landX).not.toBeNull();
        expect(segAngle(c.points, Math.floor((l.landX - c.startX) / SPACING_PX))).toBeGreaterThan(25);
      }
    }
  });

  test('landing zones are hazard free (this chunk and the next)', () => {
    for (let sd = 0; sd < 15; sd++) {
      const g = makeGen('zone-' + sd);
      for (let i = 0; i < 100; i++) {
        const c = g.getChunk(i);
        const next = g.getChunk(i + 1);
        for (const l of c.launches) {
          const end = (l.landX == null ? l.x + 700 : l.landX) + 100;
          for (const h of groundHazards(content.hazards, c).concat(groundHazards(content.hazards, next))) expect(h.x < l.x - 40 || h.x > end).toBe(true);
        }
      }
    }
  });

  test('ordinary terrain has round crests: slope never increases by more than CREST_TURN_DEG per segment', () => {
    let worstSpline = 0;
    let worstNoise = 0;
    let worstSharp = 0;
    for (let sd = 0; sd < 15; sd++) {
      const g = makeGen('crest-' + sd);
      for (let i = 0; i < 120; i++) {
        const c = g.getChunk(i);
        for (let k = 1; k < c.points.length - 1; k++) {
          if (inGap(c, k) || inGap(c, k - 1)) continue;
          const inc = segAngle(c.points, k) - segAngle(c.points, k - 1);
          if (c.kind === 'noise') worstNoise = Math.max(worstNoise, inc);
          else if (sharp[c.defId]) worstSharp = Math.max(worstSharp, inc);
          else worstSpline = Math.max(worstSpline, inc);
        }
      }
    }
    expect(worstSpline).toBeLessThanOrEqual(CREST_TURN_DEG + 1e-6);
    expect(worstNoise).toBeLessThanOrEqual(NOISE_CREST_TURN_DEG + 1e-6);
    expect(worstSharp).toBeGreaterThan(CREST_TURN_DEG * 2); // deliberate lips stay sharp
  });
});

describe('TerrainGenerator fun pass: sectors', () => {
  test('chunk.sector is 1-based and follows startX; each sector starts with a calm breather chunk', () => {
    const g = makeGen('sectors');
    let breathers = 0;
    let lastSector = 0;
    for (let i = 0; i < 200; i++) {
      const c = g.getChunk(i);
      expect(c.sector).toBe(Math.floor(c.startX / PIXELS_PER_METER / SECTOR_M) + 1);
      expect(c.sector).toBeGreaterThanOrEqual(lastSector);
      if (c.sector > lastSector && i > 0) {
        breathers++;
        expect(c.breather).toBe(true);
        expect(c.kind).toBe('spline');
        expect(c.defId).not.toBe('gen-jump');
        for (const h of c.hazards) expect(h.x - c.startX).toBeGreaterThan(1000);
      } else expect(c.breather).toBe(false);
      lastSector = c.sector;
    }
    expect(breathers).toBeGreaterThan(10);
  });

  test('hazards get denser sector by sector', () => {
    const dens = (from, to) => {
      let n = 0;
      let len = 0;
      for (let sd = 0; sd < 10; sd++) {
        const g = makeGen('sd-' + sd);
        for (let i = 0; i < 120; i++) {
          const c = g.getChunk(i);
          if (c.sector >= from && c.sector <= to) { n += c.hazards.length; len += c.endX - c.startX; }
        }
      }
      return n / len;
    };
    expect(dens(3, 4)).toBeGreaterThan(dens(1, 2));
    expect(dens(7, 9)).toBeGreaterThan(dens(3, 4));
  });
});

describe('TerrainGenerator fun pass: shards', () => {
  const content = loadContent();
  const hazardBox = (h) => {
    const d = content.hazards[h.defId];
    return { x0: h.x - d.size.w / 2, x1: h.x + d.size.w / 2, top: h.y - d.size.h };
  };

  test('shards are deterministic per seed and independent of call order', () => {
    const a = makeGen('sh-a');
    const b = makeGen('sh-a');
    for (let i = 59; i >= 0; i--) expect(snap(a.getChunk(i).shards)).toEqual(snap(b.getChunk(i).shards));
    const c = makeGen('sh-b');
    let diff = 0;
    for (let i = 0; i < 40; i++) if (JSON.stringify(a.getChunk(i).shards) !== JSON.stringify(c.getChunk(i).shards)) diff++;
    expect(diff).toBeGreaterThan(20);
  });

  test('shape: sorted by x, unique stable ids, 4-9 per group, inside the chunk, ~55-65 % of chunks', () => {
    let withShards = 0;
    let total = 0;
    const ids = new Set();
    for (let sd = 0; sd < 15; sd++) {
      const g = makeGen('shape-' + sd);
      for (let i = 0; i < 100; i++) {
        const c = g.getChunk(i);
        total++;
        expect(Array.isArray(c.shards)).toBe(true);
        if (!c.shards.length) continue;
        withShards++;
        expect(c.shards.length).toBeGreaterThanOrEqual(4);
        expect(c.shards.length).toBeLessThanOrEqual(9);
        c.shards.forEach((s, k) => {
          expect(s.id).toBe(`s${i}-${k}`);
          expect(ids.has(sd + s.id)).toBe(false);
          ids.add(sd + s.id);
          expect(s.x).toBeGreaterThanOrEqual(c.startX);
          expect(s.x).toBeLessThanOrEqual(c.endX);
          if (k) expect(s.x).toBeGreaterThan(c.shards[k - 1].x);
        });
      }
    }
    expect(withShards / total).toBeGreaterThan(0.5);
    expect(withShards / total).toBeLessThan(0.7);
  });

  test('every shard is above the surface and clear of hazard hit boxes', () => {
    for (let sd = 0; sd < 15; sd++) {
      const g = makeGen('clear-' + sd);
      for (let i = 0; i < 150; i++) {
        const c = g.getChunk(i);
        for (const s of c.shards) {
          expect(s.y).toBeLessThanOrEqual(g.heightAt(s.x) - 10);
          for (const h of c.hazards) {
            if (isAirDef(content.hazards, h)) {
              const d = content.hazards[h.defId];
              expect(Math.abs(s.x - h.x) <= d.size.w / 2 + 10 && Math.abs(s.y - h.y) <= d.size.h / 2 + 10).toBe(false);
              continue;
            }
            const b = hazardBox(h);
            expect(s.x >= b.x0 - 10 && s.x <= b.x1 + 10 && s.y >= b.top - 10).toBe(false);
          }
        }
      }
    }
  });

  test('arcs follow launches (shards sit on the ballistic line) and ground lines hug ~14 px above the surface', () => {
    let arcs = 0;
    let lines = 0;
    for (let sd = 0; sd < 10; sd++) {
      const g = makeGen('kind-' + sd);
      for (let i = 0; i < 100; i++) {
        const c = g.getChunk(i);
        if (c.shards.length < 4) continue;
        const heights = c.shards.map((s) => g.heightAt(s.x) - s.y);
        if (heights.every((h) => Math.abs(h - 14) <= 1.5)) lines++;
        else if (c.launches.length || c.bouncePads.length) arcs++;
      }
    }
    expect(arcs).toBeGreaterThan(20);
    expect(lines).toBeGreaterThan(5);
  });

  test('fewer free ground lines and more risky placements as distance grows', () => {
    const ratio = (lo, hi) => {
      let ground = 0;
      let other = 0;
      for (let sd = 0; sd < 25; sd++) {
        const g = makeGen('risk-' + sd);
        for (let i = 0; i < 160; i++) {
          const c = g.getChunk(i);
          const m = c.startX / PIXELS_PER_METER;
          if (m < lo || m >= hi || c.shards.length < 4 || c.launches.length || c.bouncePads.length) continue;
          const heights = c.shards.map((s) => g.heightAt(s.x) - s.y);
          if (heights.every((h) => Math.abs(h - 14) <= 1.5)) ground++;
          else other++;
        }
      }
      return ground / (ground + other);
    };
    expect(ratio(0, 1500)).toBeGreaterThan(ratio(4000, 99999));
  });

  test('chunk objects recycled by update() have their shards (and launches) reset', () => {
    const stream = makeGen('recycle');
    const fresh = makeGen('recycle');
    let x = 0;
    let checked = 0;
    for (let f = 0; f < 600; f++) {
      x += 120;
      stream.update(x);
      for (const c of stream.getActiveChunks()) {
        const ref = fresh.getChunk(c.index);
        expect(snap(c.shards)).toEqual(snap(ref.shards));
        expect(snap(c.launches)).toEqual(snap(ref.launches));
        expect(c.sector).toBe(ref.sector);
        checked++;
      }
    }
    expect(stream.stats.reused).toBeGreaterThan(5);
    expect(checked).toBeGreaterThan(1000);
  });
});

describe('TerrainGenerator fun pass: anti-stall at any distance', () => {
  test('a rolling point mass never stalls on the first 10 000 m of 30 seeds', () => {
    for (let sd = 0; sd < 30; sd++) {
      const r = rollSim(makeGen('late-' + sd), 10000);
      if (r.stalledAtM !== null) throw new Error(`seed ${sd}: stalled at ${Math.round(r.stalledAtM)} m`);
      expect(r.reachedM).toBeGreaterThanOrEqual(10000);
    }
  });

  test('expected speed budget rises with distance and is capped', () => {
    expect(expectedSpeedPxS(0)).toBeLessThan(expectedSpeedPxS(1000));
    expect(expectedSpeedPxS(1e6)).toBeLessThanOrEqual(700);
  });
});

describe('TerrainGenerator fun pass 2: air, runout, slow hazards', () => {
  test('slow-type hazards always have a steady >= 9 deg descent for 600 px behind them', () => {
    let slow = 0;
    for (let sd = 0; sd < 6; sd++) {
      const g = makeGen('slow-' + sd);
      for (let i = 0; i < 100; i++) {
        const c = g.getChunk(i);
        for (const h of c.hazards) {
          if (h.defId !== 'overflowFirewall') continue;
          slow++;
          const k0 = Math.floor((h.x - c.startX) / 16);
          for (let k = k0; k <= Math.min(c.points.length - 2, k0 + 37); k++) {
            expect(segAngle(c.points, k)).toBeGreaterThanOrEqual(SLOW_HAZARD_MIN_DEG - 0.01);
          }
          expect(h.x + SLOW_HAZARD_CLEAR_PX).toBeLessThanOrEqual(c.endX);
        }
      }
    }
    expect(slow).toBeGreaterThan(0);
  });

  test('landing-ramp runouts bend by at most RUNOUT_TURN_DEG per segment', () => {
    for (let sd = 0; sd < 6; sd++) {
      const g = makeGen('run-' + sd);
      for (let i = 0; i < 60; i++) {
        const c = g.getChunk(i);
        if (c.defId !== 'gen-jump') continue;
        let steep = false;
        for (let k = 1; k < c.points.length - 1; k++) {
          const a = segAngle(c.points, k);
          if (a > 30) steep = true;
          else if (steep) {
            expect(segAngle(c.points, k - 1) - a).toBeLessThanOrEqual(RUNOUT_TURN_DEG + 0.01);
          }
        }
      }
    }
  });
});

describe('air hazards (roguePacket in jump arcs)', () => {
  const content = loadContent();
  const airDef = content.hazards.roguePacket;
  const airOf = (c) => c.hazards.filter((h) => isAirDef(content.hazards, h));
  /** Chunks 0..lastIdx of a few seeds that carry an air hazard (with the generator that built them). */
  const collect = (seeds, count, prefix = 'air-') => {
    const out = [];
    for (let sd = 0; sd < seeds; sd++) {
      const g = makeGen(prefix + sd);
      for (let i = 0; i < count; i++) out.push({ g, c: g.getChunk(i), i });
    }
    return out;
  };
  const all = collect(14, 260);

  test('def is an air crash hazard from 1500 m with the documented shape', () => {
    expect(airDef.placement).toBe('air');
    expect(airDef.onHit.effect).toBe('crash');
    expect(airDef.minDistanceM).toBeGreaterThanOrEqual(1500);
    expect(AIR_HAZARD_MIN_M).toBe(1500);
  });

  test('appears, at most one per chunk, only on generated jumps (never chunk 0, breathers, bridges, or before 1500 m)', () => {
    let n = 0;
    for (const { c, i } of all) {
      const air = airOf(c);
      expect(air.length).toBeLessThanOrEqual(1);
      if (!air.length) continue;
      n++;
      expect(i).toBeGreaterThan(0);
      expect(c.defId).toBe('gen-jump');
      expect(c.breather).toBe(false);
      expect(c.kind).not.toBe('bridge');
      expect(air[0].x / PIXELS_PER_METER).toBeGreaterThanOrEqual(1500);
    }
    expect(n).toBeGreaterThan(100);
  });

  test('chance per eligible jump starts near 25 % and rises toward ~55 % (never every jump)', () => {
    const rate = (lo, hi) => {
      let jumps = 0;
      let withAir = 0;
      for (const { c } of all) {
        const m = c.startX / PIXELS_PER_METER;
        if (c.defId !== 'gen-jump' || m < lo || m >= hi) continue;
        jumps++;
        if (airOf(c).length) withAir++;
      }
      return { jumps, share: withAir / Math.max(1, jumps) };
    };
    const early = rate(1500, 3500);
    const late = rate(7000, 100000);
    expect(early.jumps).toBeGreaterThan(80);
    expect(late.jumps).toBeGreaterThan(80);
    expect(early.share).toBeGreaterThan(0.15);
    expect(early.share).toBeLessThan(0.4);
    expect(late.share).toBeGreaterThan(0.38);
    expect(late.share).toBeLessThan(0.7);
    expect(late.share).toBeGreaterThan(early.share);
    const chunksBefore1500 = all.filter(({ c }) => c.startX / PIXELS_PER_METER < 1500 - 1);
    for (const { c } of chunksBefore1500) expect(airOf(c)).toEqual([]);
  });

  test('FAIRNESS: every air hazard keeps >= 70 px clear of every no-hop arc (0.75x .. 1.6x / expected speed), above them', () => {
    let checked = 0;
    let minClear = Infinity;
    for (const { g, c } of all) {
      const air = airOf(c);
      if (!air.length) continue;
      const a = air[0];
      const l = c.launches[0];
      expect(l).toBeDefined();
      const th = (l.angleDeg * Math.PI) / 180;
      const vN = Math.min(expectedSpeedPxS(c.startX / PIXELS_PER_METER), JUMP_LAUNCH_SPEED_PX_S);
      const bw = airDef.size.w * 0.72; // crash hit boxes are 72 % x 80 % of the drawn box
      const bh = airDef.size.h * 0.8;
      const top = a.y - bh / 2;
      const bottom = a.y + bh / 2;
      const hiMul = Math.max(AIR_SPEED_HI_MUL, expectedSpeedPxS(c.startX / PIXELS_PER_METER) / vN);
      expect(hiMul).toBeGreaterThanOrEqual(1.6);
      const muls = [];
      for (let m = AIR_SPEED_LO_MUL; m < hiMul; m += 0.05) muls.push(m);
      muls.push(hiMul);
      for (const m of muls) {
        const v = vN * m;
        for (const k of [-1, -0.5, 0, 0.5, 1]) {
          const x = a.x + (k * bw) / 2;
          const dx = x - l.x;
          expect(dx).toBeGreaterThan(100); // well after the lip
          expect(x).toBeLessThan(l.landX); // well before touch-down
          const arcY = l.y - Math.tan(th) * dx + (900 * dx * dx) / (2 * v * v * Math.cos(th) ** 2);
          const clear = arcY - bottom; // arc passes UNDER the hazard (sled below the box)
          minClear = Math.min(minClear, clear);
          expect(clear).toBeGreaterThanOrEqual(AIR_CLEARANCE_PX - 0.5);
        }
      }
      // a clear line exists through the arc: the box floats above the terrain too, and a line under it is free
      expect(bottom).toBeLessThan(g.heightAt(a.x) - 100);
      expect(top).toBeLessThan(bottom);
      checked++;
    }
    expect(checked).toBeGreaterThan(100);
    expect(minClear).toBeGreaterThanOrEqual(AIR_CLEARANCE_PX - 0.5);
  });

  test('LATE placement: box is >= 400 px past the lip, at 0.55-0.8 of the lip-to-landing span, never closer than the span allows', () => {
    expect(AIR_MIN_DX_PX).toBe(400);
    expect(AIR_SPEED_HI_MUL).toBe(1.6);
    let n = 0;
    for (const { c } of all) {
      const a = airOf(c)[0];
      if (!a) continue;
      const l = c.launches[0];
      const span = l.landX - l.x;
      const dx = a.x - l.x;
      expect(dx).toBeGreaterThanOrEqual(AIR_MIN_DX_PX - 1);
      expect(dx / span).toBeGreaterThanOrEqual(AIR_U_MIN - 0.01);
      expect(dx / span).toBeLessThanOrEqual(AIR_U_MAX + 0.01);
      n++;
    }
    expect(n).toBeGreaterThan(100);
  });

  test('NEAR MISS WINDOW: the nominal (1.0x) and every no-hop arc crosses the box x inside the window under the box', () => {
    let n = 0;
    for (const { g, c } of all) {
      const a = airOf(c)[0];
      if (!a) continue;
      const l = c.launches[0];
      const th = (l.angleDeg * Math.PI) / 180;
      const vN = Math.min(expectedSpeedPxS(c.startX / PIXELS_PER_METER), JUMP_LAUNCH_SPEED_PX_S);
      const bh = airDef.size.h * 0.8;
      const dx = a.x - l.x;
      for (const m of [0.9, 1, 1.25, 1.6]) {
        const arcY = l.y - Math.tan(th) * dx + (900 * dx * dx) / (2 * (vN * m) ** 2 * Math.cos(th) ** 2);
        const below = arcY - (a.y + bh / 2); // how far under the box bottom the flight passes
        const airborne = arcY < g.heightAt(a.x) - 10; // a slower arc has already landed before the box x and never crosses it
        expect(below).toBeGreaterThan(0);
        if (m >= 1) expect(airborne).toBe(true);
        // RunScene pays a near miss for an airborne pass inside this window
        if (airborne) expect(below).toBeLessThan(AIR_NEAR_MISS_BELOW_PX);
      }
      n++;
    }
    expect(n).toBeGreaterThan(100);
  });

  test('a hop at the lip can reach the box (the hazard is reachable only by an over-ambitious arc, not decoration)', () => {
    let reach = 0;
    let n = 0;
    for (const { c } of all) {
      const a = airOf(c)[0];
      if (!a) continue;
      n++;
      const l = c.launches[0];
      const th = (l.angleDeg * Math.PI) / 180;
      const v = JUMP_LAUNCH_SPEED_PX_S;
      const bw = airDef.size.w * 0.72;
      const bh = airDef.size.h * 0.8;
      for (let t = 0.02; t < 2; t += 0.01) {
        const x = l.x + v * Math.cos(th) * t;
        const y = l.y - (v * Math.sin(th) + 360) * t + 450 * t * t;
        if (Math.abs(x - a.x) < bw / 2 + 8 && Math.abs(y - a.y) < bh / 2 + 8) { reach++; break; }
      }
    }
    expect(reach / n).toBeGreaterThan(0.4);
  });

  test('air hazards never overlap power-ups, shards or other hazards and stay out of gaps', () => {
    for (const { c } of all) {
      const a = airOf(c)[0];
      if (!a) continue;
      for (const p of c.powerups) expect(Math.abs(p.x - a.x)).toBeGreaterThanOrEqual(90);
      for (const sh of c.shards) {
        expect(Math.abs(sh.x - a.x) <= airDef.size.w / 2 + 10 && Math.abs(sh.y - a.y) <= airDef.size.h / 2 + 10).toBe(false);
      }
      for (const h of c.hazards) if (h !== a) expect(Math.abs(h.x - a.x)).toBeGreaterThanOrEqual(HAZARD_MIN_SPACING_PX);
      for (const gp of c.gaps) expect(a.x < gp.x0 || a.x > gp.x1).toBe(true);
      expect(c.hazards.map((h) => h.x)).toEqual(c.hazards.map((h) => h.x).sort((p, q) => p - q));
    }
  });

  test('determinism: the same (seed, index) twice is deep-equal including the air hazard, in any call order', () => {
    const a = makeGen('air-det');
    const b = makeGen('air-det');
    let withAir = 0;
    for (let i = 259; i >= 0; i -= 1) {
      const ca = snap(a.getChunk(i));
      expect(snap(a.getChunk(i))).toEqual(ca);
      if (i % 3 === 0) expect(snap(b.getChunk(i))).toEqual(ca);
      if (ca.hazards.some((h) => h.defId === 'roguePacket')) withAir++;
    }
    expect(withAir).toBeGreaterThan(3);
    // streamed (pooled) chunks match fresh ones
    const stream = makeGen('air-det');
    let x = 0;
    for (let f = 0; f < 900; f++) {
      x += 150;
      stream.update(x);
      for (const c of stream.getActiveChunks()) expect(snap(c)).toEqual(snap(b.getChunk(c.index)));
    }
  });

  test('adding the air hazard def changes NOTHING else: terrain, ground hazards, power-ups, shards, zones, launches are identical', () => {
    const groundOnly = Object.fromEntries(Object.entries(content.hazards).filter(([, d]) => d.placement !== 'air'));
    for (let sd = 0; sd < 4; sd++) {
      const withAir = makeGen('iso-' + sd);
      const without = makeGen('iso-' + sd, { hazardDefs: groundOnly });
      for (let i = 0; i < 260; i++) {
        const a = withAir.getChunk(i);
        const b = without.getChunk(i);
        expect(a.points).toEqual(b.points);
        expect(a.shards).toEqual(b.shards);
        expect(a.powerups).toEqual(b.powerups);
        expect(a.zones).toEqual(b.zones);
        expect(a.launches).toEqual(b.launches);
        expect(a.bouncePads).toEqual(b.bouncePads);
        expect(groundHazards(content.hazards, a)).toEqual(b.hazards);
      }
    }
  });
});

describe('longer difficulty ramp (tail past the old caps)', () => {
  const g = makeGen('tail');
    test('expected speed: original curve up to its 620 px/s cap, then creeps to 700 by 6 km and never beyond', () => {
    expect(expectedSpeedPxS(0)).toBe(340);
    expect(expectedSpeedPxS(1000)).toBeCloseTo(520, 6);
    expect(expectedSpeedPxS(1555)).toBeCloseTo(340 + 0.18 * 1555, 3);
    expect(expectedSpeedPxS(1556)).toBeCloseTo(620, 1);
    let prev = expectedSpeedPxS(1556);
    for (let d = 1600; d <= 8000; d += 100) {
      const v = expectedSpeedPxS(d);
      expect(v).toBeGreaterThanOrEqual(prev);
      expect(v - prev).toBeLessThan(2.5); // gentle slope, no jump at the cap
      prev = v;
    }
    expect(expectedSpeedPxS(3000)).toBeGreaterThan(630);
    expect(expectedSpeedPxS(3000)).toBeLessThan(660);
    expect(expectedSpeedPxS(6000)).toBeCloseTo(700, 6);
    expect(expectedSpeedPxS(1e7)).toBe(700);
  });

  test('hazard density: original curve to 2.1 at 3500 m, then creeps toward 2.8 by 10 km, hard cap after', () => {
    expect(g.difficultyAt(3499).hazardDensity).toBeLessThan(2.1);
    expect(g.difficultyAt(3500).hazardDensity).toBeCloseTo(2.1, 6);
    let prev = 2.1;
    for (let d = 3500; d <= 10000; d += 500) {
      const h = g.difficultyAt(d).hazardDensity;
      expect(h).toBeGreaterThanOrEqual(prev - 1e-9);
      expect(h - prev).toBeLessThan(0.1);
      prev = h;
    }
    expect(g.difficultyAt(6500).hazardDensity).toBeGreaterThan(2.3);
    expect(g.difficultyAt(10000).hazardDensity).toBeCloseTo(2.8, 6);
    expect(g.difficultyAt(1e6).hazardDensity).toBeCloseTo(2.8, 6);
    expect(g.difficultyAt(10000).speedBudget).toBeGreaterThan(g.difficultyAt(1500).speedBudget);
  });

  test('flow holds out to ~10 km: no stalls, jump landings stay inside the chunk on a steep ramp, smooth seams', () => {
    let jumps = 0;
    let lateJumps = 0;
    for (let sd = 0; sd < 5; sd++) {
      const gen = makeGen('tenk-' + sd);
      expect(rollSim(gen, 10000).stalledAtM).toBeNull();
      let prev = null;
      for (let i = 0; ; i++) {
        const c = gen.getChunk(i);
        if (c.startX / PIXELS_PER_METER > 10200) break;
        if (c.kind !== 'bridge' && prev && prev.kind !== 'bridge') {
          expect(Math.abs(segAngle(prev.points, prev.points.length - 2) - segAngle(c.points, 0))).toBeLessThanOrEqual(12);
        }
        for (let k = 0; k < c.points.length - 1; k++) {
          if (inGap(c, k)) continue;
          expect(segAngle(c.points, k)).toBeLessThan(TERRAIN.maxSlopeDeg);
        }
        if (c.defId === 'gen-jump' && i > 0) {
          jumps++;
          if (c.startX / PIXELS_PER_METER > 6000) lateJumps++;
          const l = c.launches[0];
          expect(l.landX).not.toBeNull();
          expect(segAngle(c.points, Math.floor((l.landX - c.startX) / SPACING_PX))).toBeGreaterThan(25);
          // the ramp is long enough that a launch at 1.1 x the expected speed still lands on it, inside the chunk
          const vHi = 1.1 * expectedSpeedPxS(c.startX / PIXELS_PER_METER);
          const th = (l.angleDeg * Math.PI) / 180;
          let landed = false;
          for (let t = 0.05; t < 2.5 && !landed; t += 0.02) {
            const x = l.x + vHi * Math.cos(th) * t;
            const y = l.y - vHi * Math.sin(th) * t + 450 * t * t;
            if (x >= c.endX) break;
            if (y >= gen.heightAt(x)) landed = true;
          }
          expect(landed).toBe(true);
        }
        prev = c;
      }
    }
    expect(jumps).toBeGreaterThan(80);
    expect(lateJumps).toBeGreaterThan(20);
  });
});

// #121 (portable math): digests re-pinned once. Terrain generation now uses pmath (tan/atan2/hypot/cos), which differs from native V8 Math in the last bits
// of about 10% of the numbers (max 8.7e-11 px, 6e-16 relative; zero structural differences over 20 seed/mask pairs x 300 chunks, tools/determinism/portable-math/terrain-delta.mjs).
describe('late-game hazard fill (retry of rejected slots past HAZARD_RETRY_FROM_M)', () => {
  // md5 of every chunk starting before 2000 m, taken from the generator BEFORE the late-game fill was added
  const GOLDEN_BEFORE_2000M = {
    alpha: '6e5c7443c540:20', beta: '67e071ba3872:21', gamma: '9dd05cbe30d0:20',
    'sim-01': '3923503d3d32:22', 'sim-17': '5b5cbfedf760:20', 'daily-2026-11-12': 'f14618ca0886:20',
  };

  test('chunks starting before HAZARD_RETRY_FROM_M (so the whole opening and early game) are bit-identical to before', () => {
    expect(HAZARD_RETRY_FROM_M).toBeGreaterThanOrEqual(1500);
    for (const [seed, want] of Object.entries(GOLDEN_BEFORE_2000M)) {
      const g = makeGen(seed);
      const h = crypto.createHash('md5');
      let n = 0;
      for (let i = 0; ; i++) {
        const c = g.getChunk(i);
        if (c.startX / PIXELS_PER_METER >= HAZARD_RETRY_FROM_M) break;
        h.update(JSON.stringify(c));
        n++;
      }
      expect(h.digest('hex').slice(0, 12) + ':' + n).toBe(want);
    }
  });

  test('past 2500 m a 500 m band carries about 5-7 hazards on average (ground + air); spacing rules still hold', () => {
    const content = loadContent();
    let n = 0;
    const seeds = 16;
    for (let s = 1; s <= seeds; s++) {
      const gen = makeGen('sim-' + String(s).padStart(2, '0'));
      let prevGroundX = null;
      for (let i = 0; ; i++) {
        const c = gen.getChunk(i);
        const m = c.startX / PIXELS_PER_METER;
        if (m > 6000) break;
        const ground = groundHazards(content.hazards, c);
        for (let k = 1; k < ground.length; k++) expect(ground[k].x - ground[k - 1].x).toBeGreaterThanOrEqual(HAZARD_MIN_SPACING_PX);
        if (prevGroundX != null && ground.length) expect(ground[0].x - prevGroundX).toBeGreaterThanOrEqual(HAZARD_MIN_SPACING_PX);
        if (ground.length) prevGroundX = ground[ground.length - 1].x;
        if (m >= 2500) n += c.hazards.length;
      }
    }
    const perBand = n / seeds / ((6000 - 2500) / 500);
    expect(perBand).toBeGreaterThan(5);
    expect(perBand).toBeLessThan(7.5);
  });
});import { terrainTopNormal, snapTerrainNormal, installTerrainContactFix } from '../../src/systems/TerrainContact.js';
import { TUNING } from '../../src/systems/PhysicsTuner.js';

const DEG = Math.PI / 180;

/** Terrain collider quad for a segment a->b extruded 64 px down (what TerrainMesh builds). */
function quad(ax, ay, bx, by) {
  return {
    label: 'terrain',
    vertices: [{ x: ax, y: ay }, { x: bx, y: by }, { x: bx, y: by + 64 }, { x: ax, y: ay + 64 }],
  };
}

/** A runner (skid) polygon: 24-gon of radius 4 centred at (cx, cy). */
function skid(cx, cy) {
  const vertices = [];
  for (let i = 0; i < 24; i++) vertices.push({ x: cx + 4 * Math.cos((i * Math.PI) / 12), y: cy + 4 * Math.sin((i * Math.PI) / 12) });
  return { label: 'skid', vertices };
}

/** Collision record like Matter's: normal points from bodyB towards bodyA. */
function collision(A, B, angleDeg, depth = 0.3) {
  const n = { x: Math.cos(angleDeg * DEG), y: Math.sin(angleDeg * DEG) };
  return {
    bodyA: A, bodyB: B, normal: { ...n }, tangent: { x: -n.y, y: n.x }, penetration: { x: n.x * depth, y: n.y * depth }, depth,
  };
}

const angleOf = (v) => Math.atan2(v.y, v.x) / DEG;

describe('terrainTopNormal', () => {
  test('flat ground: straight up', () => {
    const n = terrainTopNormal(quad(0, 100, 16, 100));
    expect(n.x).toBeCloseTo(0, 6);
    expect(n.y).toBeCloseTo(-1, 6);
    expect(n.top).toBeCloseTo(-100, 6);
  });

  test('descending-right slope tilts the normal forward, up to steep ramps', () => {
    for (const slope of [10, 37, 55]) {
      const dy = Math.tan(slope * DEG) * 16;
      const n = terrainTopNormal(quad(0, 100, 16, 100 + dy));
      expect(angleOf(n)).toBeCloseTo(-90 + slope, 4);
    }
  });

  test('independent of vertex order', () => {
    const q = quad(0, 100, 16, 106);
    q.vertices.reverse();
    expect(angleOf(terrainTopNormal(q))).toBeCloseTo(-90 + Math.atan2(6, 16) / DEG, 4);
  });

  test('degenerate input returns null', () => {
    expect(terrainTopNormal(null)).toBeNull();
    expect(terrainTopNormal({ vertices: [] })).toBeNull();
  });
});

describe('snapTerrainNormal', () => {
  const t = quad(32, 100, 48, 103); // ~10.6 degree slope
  const faceDeg = -90 + Math.atan2(3, 16) / DEG;

  test('replaces a 15 degree ghost normal (runner face axis) by the face normal, bodyA = skid (terrain is B)', () => {
    const s = skid(40, 98); // 4 px circle centred just above the surface => overlapping
    const c = collision(s, t, faceDeg + 15, 0.2);
    expect(snapTerrainNormal(c)).toBe(true);
    expect(angleOf(c.normal)).toBeCloseTo(faceDeg, 4);
    expect(c.tangent.x).toBeCloseTo(-c.normal.y, 9);
    expect(c.tangent.y).toBeCloseTo(c.normal.x, 9);
    expect(c.depth).toBeGreaterThan(0);
    expect(c.penetration.x).toBeCloseTo(c.normal.x * c.depth, 9);
  });

  test('replaces a vertical-wall ghost normal; terrain as bodyA flips the sign', () => {
    const s = skid(32.5, 98.5);
    const c = collision(t, s, 180); // wall axis, pointing from B (skid) to A (terrain)
    expect(snapTerrainNormal(c)).toBe(true);
    // normal points from bodyB (skid) to bodyA (terrain): down into the ground
    expect(angleOf(c.normal)).toBeCloseTo(faceDeg + 180, 4);
  });

  test('already-correct normals are left alone', () => {
    const s = skid(40, 98);
    const c = collision(s, t, faceDeg, 0.4);
    const before = JSON.stringify(c);
    expect(snapTerrainNormal(c)).toBe(false);
    expect(JSON.stringify(c)).toBe(before);
  });

  test('a runner far below the top plane (side of a gap) keeps its wall normal', () => {
    const s = skid(32, 130); // 30 px under the surface, i.e. touching the vertical wall
    const c = collision(s, t, 0, 3);
    expect(snapTerrainNormal(c)).toBe(false);
    expect(c.normal.x).toBe(Math.cos(0));
  });

  test('only skid-vs-terrain pairs are touched (head, deck, other bodies)', () => {
    const head = { label: 'head', vertices: skid(40, 98).vertices };
    const deck = { label: 'deck', vertices: skid(40, 98).vertices };
    expect(snapTerrainNormal(collision(head, t, 0))).toBe(false);
    expect(snapTerrainNormal(collision(deck, t, 0))).toBe(false);
    expect(snapTerrainNormal(collision(skid(0, 0), { label: 'hazard', vertices: t.vertices }, 0))).toBe(false);
  });
});

describe('installTerrainContactFix', () => {
  test('wraps Collision.collides once and snaps results when enabled', () => {
    const t = quad(32, 100, 48, 103);
    const s = skid(40, 98);
    const calls = [];
    const Matter = { Collision: { collides: (a, b) => { calls.push([a, b]); return collision(a, b, -75, 0.2); } } };
    const orig = Matter.Collision.collides;
    installTerrainContactFix(Matter);
    installTerrainContactFix(Matter); // idempotent
    expect(Matter.Collision.collides).not.toBe(orig);
    expect(Matter.Collision.collides.original).toBe(orig);
    const out = Matter.Collision.collides(s, t);
    expect(calls).toHaveLength(1);
    expect(TUNING.terrainSnapNormals).toBe(true);
    expect(angleOf(out.normal)).toBeCloseTo(-90 + Math.atan2(3, 16) / DEG, 4);
    // null passes through
    Matter.Collision.collides.original = undefined;
    const M2 = { Collision: { collides: () => null } };
    installTerrainContactFix(M2);
    expect(M2.Collision.collides(s, t)).toBeNull();
  });

  test('tolerates a missing Matter', () => {
    expect(() => installTerrainContactFix(null)).not.toThrow();
    expect(() => installTerrainContactFix({})).not.toThrow();
  });
});

describe('landing tunables', () => {
  test('sane ranges', () => {
    expect(TUNING.landSpinMaxDegS).toBeGreaterThan(0);
    // ground lean (groundTiltMul x 420 deg/s^2) must not reach the cap inside the settle window, or steering would be cut
    expect(TUNING.landSpinMaxDegS).toBeGreaterThan(0.5 * 420 * (TUNING.landSettleMs / 1000));
    expect(TUNING.landSettleMs).toBeGreaterThanOrEqual(TUNING.groundedGraceMs);
    expect(TUNING.terrainSnapMaxDepthPx).toBeGreaterThan(4); // at least a runner radius
  });
});/**
 * W3 at the call sites — the mask a run actually starts with.
 *
 * CC Friday's finding on `3453347`: a normal run never has biomes. `TitleScene.startRun` took the mask
 * only from `maskOverride` or a `seed@mask` suffix, so START RUN and a bare ENTER SEED always ran at
 * mask 0 no matter what the profile had enabled. She set a profile to Sync Level 30 with `biomeMask 31`,
 * pressed START RUN, and the registry mask was 0.
 *
 * Issue #65 flips the default: unlocked biomes are ON unless the player explicitly turned them OFF
 * (`biomeOff`), and the base biome (Debutmont) is the terrain of every run so its bit is never in the mask.
 *
 * These tests pin the CALLER, the same way the D6 tests pin GameOverScene's call site rather than
 * re-testing SaveStore. The rule under test:
 *   explicit `maskOverride` (Daily) > `seed@mask` suffix > the profile's unlocked bits minus its OFF choices.
 * A locked biome's bit is never honoured, whatever the profile carries.
 */
import { jest } from '@jest/globals';
jest.unstable_mockModule('phaser', () => ({ default: { Scene: class {}, GameObjects: new Proxy({}, { get: () => class {} }) } }));
jest.unstable_mockModule('../../src/data/index.js', () => ({ content: {}, loadContent: () => ({}) }));
const { TitleScene } = await import('../../src/scenes/TitleScene.js');
const { REG, SCENES } = await import('../../src/constants.js');

const DEFS = {
  debutmont: { id: 'debutmont', bit: 1 },
  glacier: { id: 'glacier', bit: 2 },
  pyramid: { id: 'pyramid', bit: 4 },
};

/**
 * A TitleScene whose registry is a plain Map. `startRun` is called directly on the prototype so this
 * exercises the real method, not a re-implementation of it.
 * @param {{profile?:Object}} [o]
 */
function scene(o = {}) {
  const values = new Map([[REG.CONTENT, { biomes: DEFS }]]);
  if (o.profile) values.set(REG.PROFILE, o.profile);
  const ctx = {
    registry: { get: (k) => values.get(k), set: (k, v) => values.set(k, v) },
    scene: { start: jest.fn() },
    _closeView() {},
  };
  return { ctx, values };
}

/** A profile at cap with every batch-1 biome unlocked and nothing switched OFF. */
const capped = (over = {}) => ({
  v: 1, biomeOff: 0, level: 30,
  pendingBiomes: ['debutmont', 'glacier', 'pyramid'],
  unlocked: { biomes: [], cosmetics: [], boosts: {} },
  ...over,
});

describe('START RUN / bare seed use the profile mask', () => {
  test('a bare seed starts with every unlocked biome ON by default (the base bit is left out)', () => {
    const { ctx, values } = scene({ profile: capped() });
    TitleScene.prototype.startRun.call(ctx, 'alpha');
    expect(values.get(REG.BIOME_MASK)).toBe(6);
    expect(values.get(REG.SEED)).toBe('alpha');
    expect(ctx.scene.start).toHaveBeenCalledWith(SCENES.RUN);
  });

  test('a profile with every biome explicitly OFF runs at mask 0', () => {
    const { ctx, values } = scene({ profile: capped({ biomeOff: 6 }) });
    TitleScene.prototype.startRun.call(ctx, 'alpha');
    expect(values.get(REG.BIOME_MASK)).toBe(0);
  });

  test('with no profile at all it stays mask 0 rather than throwing', () => {
    // A first launch, or a profile that failed to load. Terrain must still be playable.
    const { ctx, values } = scene();
    TitleScene.prototype.startRun.call(ctx, 'alpha');
    expect(values.get(REG.BIOME_MASK)).toBe(0);
  });

  test('a biome the profile has NOT unlocked never starts ON, whatever the profile carries', () => {
    // Only Debutmont is unlocked, so the glacier/pyramid bits must not appear, even next to a crafted
    // legacy `biomeMask` of 7 or an OFF bit for a biome that is not unlocked. Same rule toggleBiome enforces.
    const { ctx, values } = scene({ profile: capped({ biomeMask: 7, biomeOff: 4, pendingBiomes: ['debutmont'] }) });
    TitleScene.prototype.startRun.call(ctx, 'alpha');
    expect(values.get(REG.BIOME_MASK)).toBe(0);
  });

  test('a legacy biomeMask of 0 does not switch unlocked biomes off', () => {
    const { ctx, values } = scene({ profile: capped({ biomeMask: 0 }) });
    TitleScene.prototype.startRun.call(ctx, 'alpha');
    expect(values.get(REG.BIOME_MASK)).toBe(6);
  });

  test('unlocked.biomes counts too, not just pendingBiomes', () => {
    const { ctx, values } = scene({
      profile: capped({ pendingBiomes: [], unlocked: { biomes: ['glacier'], cosmetics: [], boosts: {} } }),
    });
    TitleScene.prototype.startRun.call(ctx, 'alpha');
    expect(values.get(REG.BIOME_MASK)).toBe(2);
  });
});

describe('an explicit mask wins over the profile', () => {
  test('the seed@mask suffix wins, so a shared seed reproduces exactly', () => {
    // This is what makes a share string shareable: the recipient must see the sender's world, not
    // their own unlocked set.
    const { ctx, values } = scene({ profile: capped() });
    TitleScene.prototype.startRun.call(ctx, 'alpha@2');
    expect(values.get(REG.SEED)).toBe('alpha');
    expect(values.get(REG.BIOME_MASK)).toBe(2);
  });

  test('the suffix wins even when it is @0', () => {
    // `seed@0` is a deliberate request for base terrain, not an absent suffix. Treating 0 as "unset"
    // would make it impossible to share a clean-terrain run with a player who has biomes on.
    const { ctx, values } = scene({ profile: capped() });
    TitleScene.prototype.startRun.call(ctx, 'alpha@0');
    expect(values.get(REG.BIOME_MASK)).toBe(0);
  });

  test('a Daily override wins over both the suffix and the profile', () => {
    // D6: the Daily mask is derived from the date and is the same for every player. It must not be
    // overridden by local unlocks, or two players' Daily runs would be different worlds.
    const { ctx, values } = scene({ profile: capped() });
    TitleScene.prototype.startRun.call(ctx, 'alpha@2', 8);
    expect(values.get(REG.BIOME_MASK)).toBe(8);
  });

  test('a Daily mask 0 is honoured, not treated as absent', () => {
    const { ctx, values } = scene({ profile: capped() });
    TitleScene.prototype.startRun.call(ctx, 'daily-2026-11-13', 0);
    expect(values.get(REG.BIOME_MASK)).toBe(0);
  });

  test('a suffix naming bits with no biome is still stripped to playable bits', () => {
    const { ctx, values } = scene({ profile: capped() });
    TitleScene.prototype.startRun.call(ctx, 'alpha@999');
    expect(values.get(REG.BIOME_MASK)).toBe(7);
  });
});/**
 * HOW TO PLAY (the controls reference that replaced the Title's CONTROLS panel) and the Title's idle /
 * attract and launch behaviour.
 *
 *  - HowToPlayLayout is pure: every keycap, pad glyph and label is a rect, asserted inside the panel and
 *    pairwise disjoint for every control layout, and the keyboard rows are checked against the real trick
 *    bindings in ControlLayouts, so the reference can never teach a key the run does not use.
 *  - HowToPlayView is built on the real View base (through a small fake of the Phaser surface), with
 *    Views.js imported FIRST: Views.js imports HowToPlayView for its Settings row, so the cycle must be safe
 *    in that order.
 *  - TitleScene's wake gate, attract entry and launch are driven through the real prototype methods.
 *
 * The fake Phaser harness is adapted from views-navigation.test.js.
 */
import { jest } from '@jest/globals';
import fs from 'fs';
import path from 'path';


class Emitter {
  constructor() { this._ev = new Map(); }
  on(e, fn, ctx) { if (!this._ev.has(e)) this._ev.set(e, []); this._ev.get(e).push({ fn, ctx, once: false }); return this; }
  once(e, fn, ctx) { if (!this._ev.has(e)) this._ev.set(e, []); this._ev.get(e).push({ fn, ctx, once: true }); return this; }
  off(e, fn) {
    const l = this._ev.get(e);
    if (!l) return this;
    if (!fn) { this._ev.delete(e); return this; }
    this._ev.set(e, l.filter((x) => x.fn !== fn));
    return this;
  }
  emit(e, ...a) {
    const l = this._ev.get(e);
    if (!l || !l.length) return false;
    for (const x of [...l]) {
      if (x.once) this.off(e, x.fn);
      x.fn.apply(x.ctx, a);
    }
    return true;
  }
  listenerCount(e) { return (this._ev.get(e) || []).length; }
  totalListeners() { let n = 0; for (const l of this._ev.values()) n += l.length; return n; }
  removeAllListeners() { this._ev.clear(); return this; }
}

class GO extends Emitter {
  constructor(scene, x = 0, y = 0) {
    super();
    this.scene = scene;
    this.x = x; this.y = y;
    this.visible = true; this.alpha = 1; this.scaleX = 1; this.scaleY = 1; this.depth = 0;
    this.originX = 0; this.originY = 0;
    this.list = [];
    this.destroyed = false;
    this.parentContainer = null;
    this.input = null;
    this.width = 0; this.height = 0;
  }
  add(c) {
    for (const o of [].concat(c)) {
      if (!o) continue;
      if (o.parentContainer && o.parentContainer !== this) o.parentContainer.remove(o);
      this.list.push(o);
      o.parentContainer = this;
      if (this.scene && this.scene.__top) this.scene.__top.delete(o);
    }
    return this;
  }
  remove(c) { for (const o of [].concat(c)) { this.list = this.list.filter((x) => x !== o); if (o) o.parentContainer = null; } return this; }
  setDepth(d) { this.depth = d; return this; }
  setPosition(x, y) { this.x = x; if (y !== undefined) this.y = y; return this; }
  setX(x) { this.x = x; return this; }
  setY(y) { this.y = y; return this; }
  setVisible(v) { this.visible = v; return this; }
  setAlpha(a) { this.alpha = a; return this; }
  setScale(sx, sy) { this.scaleX = sx; this.scaleY = sy === undefined ? sx : sy; return this; }
  setOrigin(ox, oy) { this.originX = ox; this.originY = oy === undefined ? ox : oy; return this; }
  setInteractive() { this.input = { enabled: true }; return this; }
  disableInteractive() { if (this.input) this.input.enabled = false; return this; }
  removeInteractive() { this.input = null; return this; }
  setSize(w, h) { this.width = w; this.height = h; return this; }
  setTint() { return this; }
  clearTint() { return this; }
  setBlendMode() { return this; }
  setScrollFactor() { return this; }
  setMask() { return this; }
  setAngle() { return this; }
  setRotation() { return this; }
  setCenterAlign() { return this; }
  setLeftAlign() { return this; }
  setRightAlign() { return this; }
  setLetterSpacing() { return this; }
  setFontSize() { return this; }
  setDropShadow() { return this; }
  setFillStyle() { return this; }
  setStrokeStyle() { return this; }
  bringToTop() { return this; }
  getBounds() { return { x: this.x, y: this.y, width: this.width, height: this.height }; }
  destroy() {
    if (this.destroyed) return;
    this.destroyed = true;
    for (const c of [...this.list]) if (c && c.destroy) c.destroy();
    this.list = [];
    if (this.parentContainer) this.parentContainer.remove(this);
    if (this.scene && this.scene.__top) this.scene.__top.delete(this);
    this.emit('destroy');
    this.scene = undefined;
  }
}

class BitmapText extends GO {
  constructor(scene, x, y, font, text) { super(scene, x, y); this.text = String(text === undefined ? '' : text); }
  setText(t) { this.text = String(t); return this; }
}
class Zone extends GO {
  constructor(scene, x, y, w, h) { super(scene, x, y); this.width = w; this.height = h; }
}
class Rect extends GO {
  constructor(scene, x, y, w, h) { super(scene, x, y); this.width = w; this.height = h; }
}
/** Graphics: records every drawing call; unknown drawing methods are recorded too. */
class Graphics extends GO {
  constructor(scene) {
    super(scene, 0, 0);
    this.ops = [];
    return new Proxy(this, {
      get(t, k, r) {
        if (typeof k !== 'string' || k in t || k === 'then') return Reflect.get(t, k, r);
        return (...a) => { t.ops.push([k, ...a]); return r; };
      },
    });
  }
  clear() { this.ops = []; return this; }
  fillStyle(...a) { this.ops.push(['fillStyle', ...a]); return this; }
  fillRect(...a) { this.ops.push(['fillRect', ...a]); return this; }
  lineStyle(...a) { this.ops.push(['lineStyle', ...a]); return this; }
  strokeRect(...a) { this.ops.push(['strokeRect', ...a]); return this; }
}
const FakePhaser = {
  Scene: class {},
  GameObjects: { Container: GO, Graphics, BitmapText, Zone, Image: GO, Rectangle: Rect, Text: BitmapText },
  Scenes: { Events: { UPDATE: 'update', SHUTDOWN: 'shutdown', DESTROY: 'destroy' } },
  Math: { Between: (a) => a, Clamp: (v, a, b) => Math.min(b, Math.max(a, v)) },
};

jest.unstable_mockModule('phaser', () => ({ default: FakePhaser }));
jest.unstable_mockModule('../../src/data/index.js', () => ({ content: {}, loadContent: () => ({}) }));

const { REG, GAME_WIDTH, GAME_HEIGHT, SCENES } = await import('../../src/constants.js');
// Views FIRST, then HowToPlayView: the import order a Settings-first load produces.
const { View } = await import('../../src/ui/Views.js');
const { HowToPlayView } = await import('../../src/ui/HowToPlayView.js');
const { HOW_TO_PLAY, howToPlayLayout, howToPlayRects, keyboardRows, GAMEPAD_ROWS, touchGroups, LAYOUT_NAMES } = await import('../../src/ui/HowToPlayLayout.js');
const { TRICK_KEYS_RIGHT, TRICK_KEYS_LEFT } = await import('../../src/systems/ControlLayouts.js');
const { Theme } = await import('../../src/ui/Theme.js');
const { TitleScene, ATTRACT_MS } = await import('../../src/scenes/TitleScene.js');
const { measureText, hasGlyph } = await import('../../src/ui/PixelFont.js');

const PALETTES = JSON.parse(fs.readFileSync(path.resolve('src/data/palettes.json'), 'utf8'));

function makeScene(proto, values = {}) {
  const reg = new Map();
  reg.set(REG.CONTENT, { palettes: PALETTES.palettes || PALETTES });
  for (const [k, v] of Object.entries(values)) reg.set(k, v);
  const registry = { get: (k) => reg.get(k), set: (k, v) => { reg.set(k, v); }, values: reg };
  const game = { registry, events: new Emitter(), canvas: null, config: {} };
  const s = proto ? Object.create(proto) : {};
  const timers = [];
  Object.assign(s, {
    game,
    registry,
    __top: new Set(),
    events: new Emitter(),
    input: Object.assign(new Emitter(), { keyboard: new Emitter() }),
    sys: { settings: { data: {} }, game },
    textures: { exists: () => false },
    cameras: { main: { setBackgroundColor() { return this; }, fadeIn() { return this; }, fadeOut() { return this; }, once() { return this; } } },
    scene: { start: jest.fn(), stop: jest.fn(), get: () => null },
    time: {
      now: 0,
      delayedCall: (ms, fn) => { const t = { ms, fn }; timers.push(t); return t; },
      addEvent: (cfg) => ({ cfg, remove() {} }),
    },
    add: {
      existing: (o) => { if (!o.parentContainer) s.__top.add(o); return o; },
      graphics: () => { const g = new Graphics(s); s.__top.add(g); return g; },
      rectangle: (x, y, w, h) => { const r = new Rect(s, x, y, w, h); s.__top.add(r); return r; },
      zone: (x, y, w, h) => { const r = new Zone(s, x, y, w, h); s.__top.add(r); return r; },
    },
  });
  s.__timers = timers;
  return s;
}

/** Every BitmapText string under a game object. */
function texts(obj, out = []) {
  if (!obj) return out;
  if (typeof obj.text === 'string' && obj.text) out.push(obj.text);
  for (const c of obj.list || []) texts(c, out);
  return out;
}

const overlaps = (a, b) => !(a.x + a.w <= b.x || b.x + b.w <= a.x || a.y + a.h <= b.y || b.y + b.h <= a.y);
const LAYOUTS = Object.keys(LAYOUT_NAMES);

// ================================================================== layout

describe('HowToPlayLayout', () => {
  test('the panel fits the 480x270 screen', () => {
    expect(HOW_TO_PLAY.w).toBeLessThanOrEqual(GAME_WIDTH - 16);
    expect(HOW_TO_PLAY.y).toBeGreaterThanOrEqual(4);
    expect(HOW_TO_PLAY.y + HOW_TO_PLAY.h).toBeLessThanOrEqual(GAME_HEIGHT - 4);
  });

  test.each(LAYOUTS)('%s: every rect is inside the panel and below the title tab', (layout) => {
    const L = howToPlayLayout(layout);
    for (const r of howToPlayRects(L)) {
      expect([r.key, r.x >= 6, r.x + r.w <= HOW_TO_PLAY.w - 6, r.y + r.h <= HOW_TO_PLAY.h - 4]).toEqual([r.key, true, true, true]);
      // only the layout chip shares the tab row; everything else starts under the tab rule (y 15)
      if (r.key !== 'layout-chip') expect([r.key, r.y >= 18]).toEqual([r.key, true]);
    }
    // the chip sits right of the title tab (title + 16 padding + 10 slant + ~26 of data ticks)
    expect(L.layoutChip.x).toBeGreaterThan(measureText('HOW TO PLAY') + 16 + 10 + 26);
  });

  test.each(LAYOUTS)('%s: nothing overlaps anything else', (layout) => {
    const rects = howToPlayRects(howToPlayLayout(layout));
    const hits = [];
    for (let i = 0; i < rects.length; i++) {
      for (let j = i + 1; j < rects.length; j++) if (overlaps(rects[i], rects[j])) hits.push([rects[i].key, rects[j].key]);
    }
    expect(hits).toEqual([]);
  });

  test('the BACK rect is where the View base draws its button', () => {
    const L = howToPlayLayout('classic');
    expect(L.back).toEqual({ x: HOW_TO_PLAY.w - 76, y: HOW_TO_PLAY.h - 22, w: 68, h: 16 });
  });

  test('every string is drawable in the pixel font', () => {
    for (const layout of LAYOUTS) {
      for (const r of keyboardRows(layout)) for (const s of [...r.keys, r.label, r.join || '']) for (const ch of s) expect([s, ch === ' ' || hasGlyph(ch)]).toEqual([s, true]);
    }
    for (const r of GAMEPAD_ROWS) for (const s of [r.label, ...r.glyphs.map((g) => g.text)]) for (const ch of s) expect([s, ch === ' ' || hasGlyph(ch)]).toEqual([s, true]);
    for (const layout of LAYOUTS) for (const g of touchGroups(layout)) for (const s of [g.title, ...g.items]) for (const ch of s) expect([s, ch === ' ' || hasGlyph(ch)]).toEqual([s, true]);
  });

  test('the touch legend lists the buttons the overlay really shows for each layout', async () => {
    const { TOUCH_CLUSTERS, touchButtonFor } = await import('../../src/systems/TouchOverlay.js');
    const short = (l) => (l === 'SPIN CCW' || l === 'SPIN CW' ? 'SPIN' : l);
    for (const layout of LAYOUTS) {
      const mode = layout === 'classic' ? 'classic' : 'trickDeck';
      const groups = touchGroups(layout);
      const legend = Object.fromEntries(groups.map((g) => [g.title, [...g.items].sort()]));
      const real = (cluster) => [...new Set(TOUCH_CLUSTERS[cluster].map((b) => short(touchButtonFor(b, mode).label)))].sort();
      expect(legend['LEFT THUMB']).toEqual(real('LEFT'));
      expect(legend['RIGHT THUMB']).toEqual(real('RIGHT'));
      expect(legend['TOP BAR']).toEqual(real('TOP'));
      const right = groups.find((g) => g.title === 'RIGHT THUMB').items;
      if (layout === 'classic') {
        expect(right).toContain('PUSH');
        expect(right).not.toContain('DIVEBOMB');
      } else {
        // TouchOverlay.setControlLayout swaps PUSH -> DIVEBOMB and SPIN CCW -> CORKSCREW in trick layouts.
        expect(right).toEqual(expect.arrayContaining(['DIVEBOMB', 'CORKSCREW', 'SPIN']));
        expect(right).not.toContain('PUSH');
      }
      // the (longer) trick legend line still fits inside the panel
      for (const g of howToPlayLayout(layout).touch.groups) expect(g.items.x + g.items.w).toBeLessThanOrEqual(HOW_TO_PLAY.w - 8);
    }
  });

  test('the trick layouts teach exactly the keys ControlLayouts binds in a run', () => {
    const glyph = { ArrowUp: '↑', ArrowDown: '↓', ArrowLeft: '←', ArrowRight: '→', KeyW: 'W', KeyA: 'A', KeyS: 'S', KeyD: 'D' };
    const label = { tiltForward: 'TILT FWD', tiltBack: 'TILT BACK', heliRight: 'HELI SPIN', corkscrew: 'CORKSCREW', parachute: 'CHUTE', airBrake: 'AIR BRAKE', divebomb: 'DIVEBOMB', tuck: 'TUCK' };
    for (const [layout, table] of [['tricksRight', TRICK_KEYS_RIGHT], ['tricksLeft', TRICK_KEYS_LEFT]]) {
      const rows = keyboardRows(layout);
      for (const [code, pad] of Object.entries(table)) {
        const row = rows.find((r) => r.label === label[pad]);
        expect([layout, pad, row && row.keys]).toEqual([layout, pad, [glyph[code]]]);
      }
    }
  });

  test('every layout keeps HOP, RESET and PAUSE, and an unknown layout falls back to the default', () => {
    for (const layout of LAYOUTS) {
      const labels = keyboardRows(layout).map((r) => r.label);
      for (const l of ['HOP', 'RESET', 'PAUSE']) expect(labels).toContain(l);
    }
    expect(keyboardRows('bogus')).toEqual(keyboardRows('tricksRight'));
  });
});

// ================================================================== view

describe('HowToPlayView', () => {
  test('is a real View subclass, safe to import after Views.js, and closes on cancel and confirm', () => {
    const s = makeScene(null, { [REG.SETTINGS]: { controlLayout: 'classic' } });
    const theme = new Theme(s);
    for (const action of ['cancel', 'confirm']) {
      const onClose = jest.fn();
      const v = new HowToPlayView(s, theme, { onClose });
      expect(v).toBeInstanceOf(View);
      expect(v).toBeInstanceOf(HowToPlayView);
      const all = texts(v.panel);
      expect(all).toContain('HOW TO PLAY');
      expect(all).toContain('KEYS: CLASSIC');
      for (const t of ['KEYBOARD', 'GAMEPAD', 'TOUCH', 'PUSH', 'BACK']) expect(all).toContain(t);
      v.handleAction('down'); // swallowed, does not close
      expect(onClose).not.toHaveBeenCalled();
      v.handleAction(action);
      expect(onClose).toHaveBeenCalledTimes(1);
      v.destroy();
      expect(v.panel).toBe(null);
    }
    expect({}).not.toBeInstanceOf(HowToPlayView);
  });
});

// ================================================================== title idle / attract / launch

/** Just enough of a Title for the idle and launch paths, on the real prototype. */
function title(over = {}) {
  const t = makeScene(TitleScene.prototype);
  Object.assign(t, {
    starting: false, view: null, dim: null, attract: false, attractExitAt: -Infinity, lastInputAt: 0,
    theme: new Theme(t),
    menu: { handleAction: jest.fn() },
    _enterAttract: jest.fn(function enter() { this.attract = true; }),
    _exitAttract: jest.fn(function exit() { this.attract = false; this.attractExitAt = this.time.now; }),
    ...over,
  });
  return t;
}

describe('Title attract mode', () => {
  test('enters only after ATTRACT_MS without input, and never over an open view', () => {
    expect(ATTRACT_MS).toBe(20000);
    const t = title();
    t._updateAttract(ATTRACT_MS - 1, true);
    expect(t._enterAttract).not.toHaveBeenCalled();
    t._updateAttract(ATTRACT_MS + 1, true);
    expect(t._enterAttract).toHaveBeenCalledTimes(1);
    const v = title({ view: {} });
    v._updateAttract(ATTRACT_MS * 3, true);
    expect(v._enterAttract).not.toHaveBeenCalled();
  });

  test('the input that wakes the cabinet never reaches the menu, and neither does its echo', () => {
    const t = title({ attract: true });
    t.time.now = 50000;
    t._onAction('confirm');
    expect(t._exitAttract).toHaveBeenCalledTimes(1);
    expect(t.attract).toBe(false);
    expect(t.menu.handleAction).not.toHaveBeenCalled();
    // the same key arriving from the second input source a few ms later is still the wake press
    t.time.now = 50040;
    t._onAction('confirm');
    expect(t.menu.handleAction).not.toHaveBeenCalled();
    // a deliberate press afterwards works, and counts as activity
    t.time.now = 51000;
    t._onAction('down');
    expect(t.menu.handleAction).toHaveBeenCalledWith('down');
    expect(t.lastInputAt).toBe(51000);
  });

  test('pad X / Y (alt) opens HOW TO PLAY from the menu', () => {
    const t = title({ _openHelp: jest.fn() });
    t.time.now = 1000;
    t._onAction('alt');
    expect(t._openHelp).toHaveBeenCalledTimes(1);
    expect(t.menu.handleAction).not.toHaveBeenCalled();
  });
});

describe('Title launch', () => {
  test('warps the backdrop, then wipes into the run once', () => {
    const t = title({ backdrop: { warp: jest.fn(() => 700) } });
    t._launch();
    expect(t.backdrop.warp).toHaveBeenCalledTimes(1);
    expect(t.scene.start).not.toHaveBeenCalled();
    expect(t.__timers).toHaveLength(1);
    t.__timers[0].fn(); // the wipe; this harness has no tween manager, so it fires straight away
    expect(t.scene.start).toHaveBeenCalledWith(SCENES.RUN);
    expect(t.scene.start).toHaveBeenCalledTimes(1);
  });

  test('reduced motion (warp returns 0) goes straight to the transition', () => {
    const t = title({ backdrop: { warp: jest.fn(() => 0) } });
    t._launch();
    expect(t.__timers).toHaveLength(0);
    expect(t.scene.start).toHaveBeenCalledWith(SCENES.RUN);
  });
});import { SCORING } from '../../src/constants.js';
import {
  TrickTracker, wrapAngle, classifyLanding, FLIP_TOLERANCE_DEG, AIR_BRAKE_MIN_MS, PARACHUTE_MIN_MS,
  PERFECT_ANGLE_DEG, GOOD_ANGLE_DEG, SLOPPY_ANGLE_DEG, HARD_IMPACT_PX_S, CRASH_IMPACT_PX_S, isMidSpin,
} from '../../src/systems/TrickTracker.js';

const DT = 16;

/** Build a frame sequence helper around a tracker. */
function rig(opts) {
  const tracker = new TrickTracker(opts);
  let t = 0;
  let angle = 0;
  const base = { x: 0, y: 0, vx: 400, vy: 0, angularVelDegS: 0, groundAngleDeg: 0, crashed: false };
  const frame = (o = {}) => {
    t += o.dtMs || DT;
    angle += o.dAngle || 0;
    const state = {
      ...base,
      timeMs: t,
      dtMs: o.dtMs || DT,
      angleDeg: angle,
      grounded: !!o.grounded,
      input: { heli: 0, airBrake: false, parachute: false, ...(o.input || {}) },
      ...(o.state || {}),
    };
    if (o.crashed) state.crashed = true;
    return tracker.update(state);
  };
  const run = (n, o) => {
    const out = [];
    for (let i = 0; i < n; i++) out.push(frame(o));
    return out;
  };
  return { tracker, frame, run, setAngle: (a) => { angle = a; }, get angle() { return angle; } };
}

const allTricks = (results) => results.flatMap((r) => r.tricks);

describe('helpers', () => {
  test('wrapAngle wraps into [-180,180]', () => {
    expect(wrapAngle(190)).toBeCloseTo(-170);
    expect(wrapAngle(-190)).toBeCloseTo(170);
    expect(wrapAngle(720 + 10)).toBeCloseTo(10);
    expect(wrapAngle(0)).toBe(0);
  });

  test('classifyLanding thresholds', () => {
    expect(classifyLanding(0, 100).quality).toBe('perfect');
    expect(classifyLanding(PERFECT_ANGLE_DEG, 100).quality).toBe('perfect');
    expect(classifyLanding(-(PERFECT_ANGLE_DEG + 1), 100).quality).toBe('perfect');
    expect(classifyLanding(GOOD_ANGLE_DEG, 100).quality).toBe('good');
    expect(classifyLanding(GOOD_ANGLE_DEG + 1, 100).quality).toBe('sloppy');
    expect(classifyLanding(SLOPPY_ANGLE_DEG, 100).quality).toBe('sloppy');
    expect(classifyLanding(SLOPPY_ANGLE_DEG + 1, 100).quality).toBe('crash');
    expect(classifyLanding(180, 0).quality).toBe('crash');
    expect(classifyLanding(0, CRASH_IMPACT_PX_S).quality).toBe('crash');
    expect(classifyLanding(0, 899).quality).toBe('perfect');
    expect(classifyLanding(0, 1000).quality).toBe('good'); // too violent to be perfect
    // Keep original nose-down limits, extend only the lean-back side.
    expect(classifyLanding(-22, 100).quality).toBe('perfect');
    expect(classifyLanding(-23, 100).quality).toBe('good');
    expect(classifyLanding(-38, 100).quality).toBe('good');
    expect(classifyLanding(-39, 100).quality).toBe('sloppy');
    expect(classifyLanding(-65, 100).quality).toBe('sloppy');
    expect(classifyLanding(-66, 100).quality).toBe('crash');
    // Yaw is separate: helicopters are more forgiving than pitch, never safe backwards.
    expect(classifyLanding(0, 100, 40).quality).toBe('perfect');
    expect(classifyLanding(0, 100, 41).quality).toBe('good');
    expect(classifyLanding(0, 100, 75).quality).toBe('good');
    expect(classifyLanding(0, 100, 76).quality).toBe('sloppy');
    expect(classifyLanding(0, 100, 120).quality).toBe('sloppy');
    expect(classifyLanding(0, 100, 121).quality).toBe('crash');

    expect(classifyLanding(0, HARD_IMPACT_PX_S).hard).toBe(true);
    expect(classifyLanding(0, HARD_IMPACT_PX_S - 1).hard).toBe(false);
  });
});

describe('TrickTracker basics', () => {
  test('tolerates minimal state (contract stub usage)', () => {
    const t = new TrickTracker();
    const r = t.update({ grounded: true });
    expect(r).toEqual({ tricks: [], landing: null, airborne: false, airtimeMs: 0, rotationDeg: 0 });
    expect(() => t.update({ grounded: false, timeMs: 10, dtMs: 10 })).not.toThrow();
  });

  test('grounded riding produces nothing', () => {
    const r = rig();
    const out = r.run(50, { grounded: true });
    expect(allTricks(out)).toEqual([]);
    expect(out.every((o) => !o.landing && !o.airborne && o.airtimeMs === 0)).toBe(true);
  });

  test('airborne flag and airtime accumulate; landing returned once on touchdown', () => {
    const r = rig();
    r.run(5, { grounded: true });
    const air = r.run(30, {});
    expect(air.every((o) => o.airborne)).toBe(true);
    expect(air[air.length - 1].airtimeMs).toBeCloseTo(30 * DT, 0);
    const land = r.frame({ grounded: true });
    expect(land.landing).not.toBeNull();
    expect(land.landing.airtimeMs).toBeCloseTo(31 * DT, 0);
    expect(land.airborne).toBe(false);
    expect(r.frame({ grounded: true }).landing).toBeNull();
  });

  test('short bumps (< minAirtimeMs) are not jumps: no landing', () => {
    const r = rig({ minAirtimeMs: 120 });
    r.run(3, { grounded: true });
    r.run(4, {}); // ~64 ms
    expect(r.frame({ grounded: true }).landing).toBeNull();
    const r2 = rig({ minAirtimeMs: 50 });
    r2.run(4, {});
    expect(r2.frame({ grounded: true }).landing).not.toBeNull();
  });
});

test('touchdown-only paid AirBrake cannot inherit prior-flight helicopter penalty',()=>{
  const r=rig();
  r.frame({grounded:true});
  // Prior flight had an unfinished 180-degree helicopter. The new paid
  // kick and contact both occur between ordinary tracker samples.
  r.tracker._air=false;
  r.tracker._heliHeld=true;
  r.tracker._heliMax=180;
  r.tracker._heliNet=180;
  r.tracker._corkscrewNet=180;
  const next=r.frame({grounded:true,input:{airBrake:true,airBrakeKicked:true},
    state:{heliDeg:180,midSpin:180,impactVx:200,impactVy:40}});
  expect(next.tricks.map(x=>x.type)).toEqual(['airBrake']);
  expect(next.landing).toMatchObject({quality:'good',shortAirBrakeTouchdown:true,midSpin:false});
  expect(r.tracker._heliHeld).toBe(false);
  expect(r.tracker._heliMax).toBe(0);
});

describe('flips', () => {
  const spin = (dir, turns, opts = {}) => {
    const r = rig();
    r.run(3, { grounded: true });
    const frames = 60;
    const perFrame = (dir * 360 * turns) / frames;
    const out = r.run(frames, { dAngle: perFrame, input: opts.input });
    out.push(...r.run(20, { input: opts.input })); // hang a little more, no further rotation
    return { r, out };
  };

  test('one full CCW rotation = backflip', () => {
    const { out } = spin(-1, 1);
    const tricks = allTricks(out);
    expect(tricks).toHaveLength(1);
    expect(tricks[0].type).toBe('backflip');
    expect(tricks[0].count).toBe(1);
    expect(tricks[0].rotationDeg).toBeGreaterThanOrEqual(360 - FLIP_TOLERANCE_DEG);
  });

  test('one full CW rotation = frontflip', () => {
    const tricks = allTricks(spin(1, 1).out);
    expect(tricks).toHaveLength(1);
    expect(tricks[0].type).toBe('frontflip');
  });

  test('double flip emits cumulative counts 1 then 2', () => {
    const tricks = allTricks(spin(-1, 2).out);
    expect(tricks.map((t) => [t.type, t.count])).toEqual([['backflip', 1], ['backflip', 2]]);
  });

  test('a 3/4 turn is not a flip', () => {
    expect(allTricks(spin(1, 0.75).out)).toEqual([]);
  });

  test('a small tolerance short of 360 still counts', () => {
    const r = rig();
    r.run(2, { grounded: true });
    const out = r.run(40, { dAngle: (360 - FLIP_TOLERANCE_DEG + 1) / 40 });
    expect(allTricks(out).map((t) => t.type)).toEqual(['frontflip']);
  });

  test('rocking back and forth does not accumulate flips', () => {
    const r = rig();
    r.run(2, { grounded: true });
    const out = [];
    for (let k = 0; k < 10; k++) {
      out.push(...r.run(20, { dAngle: 10 }));
      out.push(...r.run(20, { dAngle: -10 }));
    }
    expect(allTricks(out)).toEqual([]);
  });

  test('rotation counts from the angle at takeoff (angles are unwrapped, may start anywhere)', () => {
    const r = rig();
    r.setAngle(1234);
    r.run(3, { grounded: true });
    const out = r.run(60, { dAngle: -6 });
    expect(allTricks(out).map((t) => t.type)).toEqual(['backflip']);
  });

  test('flips do not carry over between jumps', () => {
    const r = rig();
    r.run(2, { grounded: true });
    r.run(30, { dAngle: -6 }); // 180 deg
    r.frame({ grounded: true });
    r.run(2, { grounded: true });
    const out = r.run(30, { dAngle: -6 }); // another 180 deg: still no flip
    expect(allTricks(out)).toEqual([]);
  });

  test('rotationDeg in the update is the signed net rotation, final value on the landing frame', () => {
    const r = rig();
    r.run(2, { grounded: true });
    const out = r.run(30, { dAngle: 6 });
    expect(out[out.length - 1].rotationDeg).toBeCloseTo(180, 5);
    const land = r.frame({ grounded: true });
    expect(land.landing.rotationDeg).toBeCloseTo(180, 5);
  });
});

describe('helicopter spins', () => {
  const heli = (dir, turns) => {
    const r = rig();
    r.run(3, { grounded: true });
    const out = r.run(60, { dAngle: (dir * 360 * turns) / 60, input: { heli: dir } });
    out.push(...r.run(10, {}));
    return allTricks(out);
  };

  test('arrow-key driven CCW spin = helicopterCCW (not a backflip)', () => {
    const t = heli(-1, 1);
    expect(t).toHaveLength(1);
    expect(t[0].type).toBe('helicopterCCW');
  });

  test('arrow-key driven CW spin = helicopterCW', () => {
    const t = heli(1, 1);
    expect(t.map((x) => x.type)).toEqual(['helicopterCW']);
  });

  test('double helicopter counts 1 then 2', () => {
    expect(heli(1, 2).map((x) => [x.type, x.count])).toEqual([['helicopterCW', 1], ['helicopterCW', 2]]);
  });

  test('a flip and a heli spin in the same jump are tracked independently', () => {
    const r = rig();
    r.run(3, { grounded: true });
    const out = [
      ...r.run(60, { dAngle: -6 }),
      ...r.run(60, { dAngle: 6, input: { heli: 1 } }),
    ];
    expect(allTricks(out).map((t) => t.type).sort()).toEqual(['backflip', 'helicopterCW']);
  });
});

describe('air brake and parachute', () => {
  test('a physically paid one-shot AirBrake tap earns immediate trick credit once per jump', () => {
    const r=rig();
    r.run(2,{grounded:true});
    const fired=r.frame({input:{airBrake:true,airBrakeKicked:true}});
    expect(allTricks([fired]).map(t=>t.type)).toEqual(['airBrake']);
    expect(allTricks(r.run(60,{input:{airBrake:true,airBrakeKicked:false}}))).toEqual([]);
    expect(allTricks(r.run(60,{input:{airBrake:false,airBrakeKicked:true}}))).toEqual([]);
    r.run(2,{grounded:true});
    expect(allTricks([r.frame({input:{airBrake:true,airBrakeKicked:true}})]).map(t=>t.type)).toEqual(['airBrake']);
  });

  test('holding a previously spent AirBrake without a fresh kick earns NO trick', () => {
    const r=rig();
    r.run(2,{grounded:true});
    const out=[...r.run(Math.ceil(AIR_BRAKE_MIN_MS/DT)+60,{input:{airBrake:true,airBrakeKicked:false}}),
      ...r.run(20,{input:{airBrake:false}})];
    expect(allTricks(out)).toEqual([]);
  });

  test('a paid one-shot brake on the actual touchdown frame earns its trick even on a short bump',()=>{
    const r=rig();
    r.run(2,{grounded:true});
    r.run(3,{}); // less than minAirtimeMs
    const closing=r.frame({grounded:true,input:{airBrake:true,airBrakeKicked:true}});
    expect(allTricks([closing]).map(t=>t.type)).toEqual(['airBrake']);
    const held=r.run(40,{grounded:true,input:{airBrake:true,airBrakeKicked:false}});
    expect(allTricks(held)).toEqual([]);
  });

  test('two genuine touchdown-only kick pulses both receive credit despite no sampled airborne tick',()=>{
    const r=rig();
    const first=r.frame({grounded:true,input:{airBrakeKicked:true,airBrake:true}});
    const second=r.frame({grounded:true,input:{airBrakeKicked:true,airBrake:true}});
    expect(allTricks([first]).map(t=>t.type)).toEqual(['airBrake']);
    expect(allTricks([second]).map(t=>t.type)).toEqual(['airBrake']);
    const merelyHeld=r.frame({grounded:true,input:{airBrakeKicked:false,airBrake:true}});
    expect(allTricks([merelyHeld])).toEqual([]);
  });

  test('paid AirBrake on a tracked but sub-minimum-airtime touchdown settles immediately with bounded airtime',()=>{
    const r=rig();
    r.frame({grounded:true});
    r.frame({grounded:false});
    const touchdown=r.frame({grounded:true,input:{airBrake:true,airBrakeKicked:true}});
    expect(allTricks([touchdown]).map(t=>t.type)).toEqual(['airBrake']);
    expect(touchdown.landing).toMatchObject({quality:'good',shortAirBrakeTouchdown:true});
    expect(touchdown.tricks[0].airtimeMs).toBe(2*DT);
    expect(touchdown.landing.airtimeMs).toBe(2*DT);
  });

  test('a physically paid airborne AirBrake on one tick settles the later short landing without repeating the trick',()=>{
    const r=rig();
    r.frame({grounded:true});
    const kick=r.frame({grounded:false,input:{airBrake:true,airBrakeKicked:true}});
    expect(kick.tricks.map(t=>t.type)).toEqual(['airBrake']);
    expect(kick.landing).toBe(null);
    const touchdown=r.frame({grounded:true,input:{airBrake:true,airBrakeKicked:false}});
    expect(touchdown.tricks).toEqual([]);
    expect(touchdown.landing).toMatchObject({
      quality:'good',shortAirBrakeTouchdown:true,airtimeMs:2*DT,
    });
  });

  test('short paid AirBrake preserves the current tracked flight unfinished spin penalty',()=>{
    const r=rig();
    r.frame({grounded:true,state:{heliDeg:0,midSpin:0}});
    r.frame({input:{airBrakeKicked:true,heli:1},state:{heliDeg:60,midSpin:60}});
    const landed=r.frame({grounded:true,state:{heliDeg:100,midSpin:100}});
    expect(landed.landing).toMatchObject({quality:'sloppy',midSpin:true,shortAirBrakeTouchdown:true});
  });

  test('a crash frame never credits a paid AirBrake trick',()=>{
    const r=rig();
    r.run(2,{grounded:true});
    r.run(6,{});
    const out=r.frame({grounded:true,crashed:true,input:{airBrake:true,airBrakeKicked:true}});
    expect(allTricks([out])).toEqual([]);
  });

  test('parachute stall fires after PARACHUTE_MIN_MS once per jump', () => {
    const r = rig();
    r.run(2, { grounded: true });
    const out = r.run(Math.ceil(PARACHUTE_MIN_MS / DT) + 40, { input: { parachute: true } });
    expect(allTricks(out).map((t) => t.type)).toEqual(['parachute']);
  });

  test('air brake held on the ground does nothing; second jump can trigger again', () => {
    const r = rig();
    expect(allTricks(r.run(60, { grounded: true, input: { airBrake: true } }))).toEqual([]);
    const a = allTricks([r.frame({input:{airBrake:true,airBrakeKicked:true}})]);
    r.frame({ grounded: true });
    const b = allTricks([r.frame({input:{airBrake:true,airBrakeKicked:true}})]);
    expect(a).toHaveLength(1);
    expect(b).toHaveLength(1);
  });

  test('brake and parachute together give both tricks', () => {
    const r = rig();
    r.run(2, { grounded: true });
    const out = [r.frame({input:{airBrake:true,airBrakeKicked:true,parachute:true}}),
      ...r.run(60,{input:{airBrake:true,parachute:true}})];
    expect(allTricks(out).map(t=>t.type).sort()).toEqual(['airBrake','parachute']);
  });
});

describe('landing quality', () => {
  const land = (angleOffsetDeg, ground = 0, vel = { vx: 400, vy: 200 }) => {
    const r = rig();
    r.run(2, { grounded: true, state: { groundAngleDeg: ground } });
    r.run(25, { state: { groundAngleDeg: ground } });
    r.setAngle(ground + angleOffsetDeg);
    return r.frame({ grounded: true, state: { groundAngleDeg: ground, ...vel } }).landing;
  };

  test('aligned with the slope = perfect', () => {
    const l = land(0, 20, { vx: 400, vy: 300 });
    expect(l.quality).toBe('perfect');
    expect(l.angleDeg).toBeCloseTo(0, 5);
  });

  test('angle is measured relative to ground slope', () => {
    expect(land(0, 30).quality).toBe('perfect');
    expect(land(25, 30).quality).toBe('good');
    expect(land(40, 30).quality).toBe('sloppy');
    expect(land(100, 30).quality).toBe('crash');
    expect(land(-100, 30).quality).toBe('crash');
  });

  test('after full flips the angle wraps (landing a 360 is perfect, landing upside down crashes)', () => {
    expect(land(720 + 3).quality).toBe('perfect');
    expect(land(-360 - 5).quality).toBe('perfect');
    expect(land(180).quality).toBe('crash');
    expect(land(360 + 180).quality).toBe('crash');
  });

  test('impact speed is the velocity component into the ground', () => {
    const flat = land(0, 0, { vx: 600, vy: 400 });
    expect(flat.impactSpeedPxS).toBeCloseTo(400, 5);
    // on a 45 degree slope, moving parallel to it => no impact
    const par = land(0, 45, { vx: 500, vy: 500 });
    expect(par.impactSpeedPxS).toBeCloseTo(0, 5);
    // falling straight down onto a 45 degree slope: cos(45) of the speed is into the ground
    const into = land(0, 45, { vx: 0, vy: 500 });
    expect(into.impactSpeedPxS).toBeCloseTo(500 * Math.SQRT1_2, 3);
    // moving horizontally off a descending slope leaves it (negative -> clamped to 0)
    expect(land(0, 45, { vx: 500, vy: 0 }).impactSpeedPxS).toBe(0);
  });

  test('pre-touchdown velocity (impactVx/Vy) grades the impact when the solver has already removed the normal part', () => {
    // the physics engine resolves the contact before the frame is observed: vx/vy on the landing frame are ~parallel to the ground
    const post = { vx: 600, vy: 0, impactVx: 600, impactVy: 650 };
    const l = land(0, 0, post);
    expect(l.impactSpeedPxS).toBeCloseTo(650, 5);
    expect(l.hard).toBe(true);
    // without the fields the legacy behaviour (post-solve velocity) is unchanged
    expect(land(0, 0, { vx: 600, vy: 0 }).impactSpeedPxS).toBe(0);
    // a violent pre-impact speed is no longer 'perfect'
    expect(land(0, 0, { vx: 600, vy: 0, impactVx: 600, impactVy: 1000 }).quality).toBe('good');
    // only one of the two finite -> ignored
    expect(land(0, 0, { vx: 600, vy: 100, impactVy: 900 }).impactSpeedPxS).toBeCloseTo(100, 5);
  });

  test('a crash frame ignores stale touchdown velocity (the sled may be airborne)', () => {
    const r = rig();
    r.run(2, { grounded: true });
    r.run(25, {});
    const u = r.frame({ crashed: true, state: { vx: 300, vy: 100, impactVx: 900, impactVy: 900 } });
    expect(u.landing.quality).toBe('crash');
    expect(u.landing.impactSpeedPxS).toBeCloseTo(100, 5);
  });

  test('very hard impacts are flagged hard, and crash above the limit', () => {
    expect(land(0, 0, { vx: 100, vy: HARD_IMPACT_PX_S + 50 }).hard).toBe(true);
    expect(land(0, 0, { vx: 100, vy: 100 }).hard).toBe(false);
    expect(land(0, 0, { vx: 100, vy: CRASH_IMPACT_PX_S + 10 }).quality).toBe('crash');
  });

  test('airtime is reported in the landing', () => {
    const l = land(0);
    expect(l.airtimeMs).toBeGreaterThan(300);
  });
});

describe('crash and reset', () => {
  test('crash during a jump: landing is a crash and in-progress tricks are discarded', () => {
    const r = rig();
    r.run(2, { grounded: true });
    r.run(20, { dAngle: -10 }); // 200 deg, not a flip yet
    const c = r.frame({ crashed: true });
    expect(c.landing.quality).toBe('crash');
    expect(c.tricks).toEqual([]);
    // finishing the "rotation" afterwards must not produce a trick
    const out = r.run(40, { grounded: true });
    expect(allTricks(out)).toEqual([]);
    expect(out.every((o) => o.landing === null)).toBe(true);
  });

  test('crash while grounded reports no landing', () => {
    const r = rig();
    r.run(5, { grounded: true });
    expect(r.frame({ grounded: true, crashed: true }).landing).toBeNull();
  });

  test('reset() forgets in-progress air state', () => {
    const r = rig();
    r.run(2, { grounded: true });
    r.run(30, { dAngle: -10 });
    r.tracker.reset();
    // continue spinning in the same air: counted from the reset point only
    const out = r.run(30, { dAngle: -10 });
    expect(allTricks(out)).toEqual([]);
  });

  test('a trick completing on the touchdown frame still counts', () => {
    const r = rig();
    r.run(2, { grounded: true });
    r.run(30, { dAngle: 11 }); // 330 deg
    const last = r.frame({ grounded: true, dAngle: 40 }); // reaches 370 as it lands
    expect(last.tricks.map((t) => t.type)).toEqual(['frontflip']);
    expect(last.landing).not.toBeNull();
  });
});

describe('integration with ScoreManager rules', () => {
  test('double backflip + air brake then perfect landing yields a x1.25 combo (air brake no longer steps)', async () => {
    const { ScoreManager } = await import('../../src/systems/ScoreManager.js');
    const r = rig();
    const sm = new ScoreManager();
    r.run(2, { grounded: true });
    const frames = [];
    for (let i = 0; i < 80; i++) frames.push(r.frame({ dAngle: -9.5, input: { airBrake: i > 5 } }));
    for (const f of frames) for (const t of f.tricks) sm.addTrick(t);
    r.setAngle(0 - Math.round(r.angle / 360) * 360);
    const land = r.frame({ grounded: true, state: { vx: 400, vy: 100 } });
    // angle may be anywhere; force a perfect landing result for the score integration
    const res = sm.onLanding({ quality: 'perfect' });
    expect(land.landing).not.toBeNull();
    expect(res.multiplierUsed).toBe(1.25);
    expect(res.bonus).toBe(20);
    expect(res.banked).toBeGreaterThan(0);
  });
});

describe('helicopter spins from the sled drawing phase (SledFrameState.heliDeg)', () => {
  // Regression: the helicopter spin is a visual rotation, the physics body does not turn, so arrow-key spins used to
  // score nothing. When heliDeg is provided the heli bucket is fed from it and body rotation always counts as flips.
  const spin = ({ turns, dir = 1, bodyPerFrame = 0, frames = 60 }) => {
    const r = rig();
    let heli = 12345; // arbitrary start phase
    r.run(3, { grounded: true, state: { heliDeg: heli } });
    const out = [];
    for (let i = 0; i < frames; i++) {
      heli += (dir * 360 * turns) / frames;
      out.push(r.frame({ dAngle: bodyPerFrame, input: { heli: dir }, state: { heliDeg: heli } }));
    }
    out.push(r.frame({ grounded: true, state: { heliDeg: heli } }));
    return allTricks(out);
  };

  test('a held arrow spin with a motionless body scores helicopterCW / CCW', () => {
    expect(spin({ turns: 1, dir: 1 }).map((t) => [t.type, t.count])).toEqual([['helicopterCW', 1]]);
    expect(spin({ turns: 1, dir: -1 }).map((t) => [t.type, t.count])).toEqual([['helicopterCCW', 1]]);
  });

  test('two turns count 1 then 2; less than a turn scores nothing', () => {
    expect(spin({ turns: 2 }).map((t) => t.count)).toEqual([1, 2]);
    expect(spin({ turns: 0.6 })).toHaveLength(0);
  });

  test('body rotation during a heli spin is a flip, not a helicopter', () => {
    const types = spin({ turns: 1, bodyPerFrame: -6 }).map((t) => t.type).sort();
    expect(types).toEqual(['backflip', 'helicopterCW']);
  });

  test('a re-based drawing phase (huge jump) is ignored', () => {
    const r = rig();
    r.run(3, { grounded: true, state: { heliDeg: 36001 } });
    const out = r.run(30, { input: { heli: 1 }, state: { heliDeg: 40 } });
    out.push(r.frame({ grounded: true, state: { heliDeg: 40 } }));
    expect(allTricks(out)).toHaveLength(0);
  });

  test('without heliDeg the legacy body-rotation rule still applies', () => {
    const r = rig();
    r.run(3, { grounded: true });
    const out = r.run(60, { dAngle: 6, input: { heli: 1 } });
    out.push(r.frame({ grounded: true }));
    expect(allTricks(out).map((t) => t.type)).toEqual(['helicopterCW']);
  });
});

describe('incomplete helicopter landing penalty', () => {
  test('isMidSpin accepts booleans and helicopter phases (60 deg tolerance)', () => {
    expect(isMidSpin(true)).toBe(true);
    expect(isMidSpin(false)).toBe(false);
    expect(isMidSpin(undefined)).toBe(false);
    expect(isMidSpin(0)).toBe(false);
    expect(isMidSpin(40)).toBe(false); // the visual coast after releasing the key
    expect(isMidSpin(60)).toBe(false);
    expect(isMidSpin(61)).toBe(true);
    expect(isMidSpin(180)).toBe(true);
    expect(isMidSpin(360 - 60)).toBe(false);
    expect(isMidSpin(-720 - 20)).toBe(false);
    expect(isMidSpin(-90)).toBe(true);
  });

  test('classifyLanding drops one level, never forces or rescues a crash', () => {
    expect(classifyLanding(0, 100, true).quality).toBe('good');
    expect(classifyLanding(GOOD_ANGLE_DEG, 100, true).quality).toBe('sloppy');
    expect(classifyLanding(GOOD_ANGLE_DEG + 1, 100, true).quality).toBe('sloppy');
    expect(classifyLanding(SLOPPY_ANGLE_DEG + 1, 100, true).quality).toBe('crash');
    expect(classifyLanding(0, CRASH_IMPACT_PX_S, true).quality).toBe('crash');
    expect(classifyLanding(0, 100, 10).quality).toBe('perfect'); // within tolerance of a whole turn
    expect(classifyLanding(0, 100, 90).quality).toBe('sloppy');
    expect(classifyLanding(0, 100, 40).quality).toBe('perfect'); // coast
    expect(classifyLanding(0, 100).quality).toBe('perfect'); // legacy callers unchanged
  });

  test('tracker grades the landing from state.midSpin', () => {
    const land = (midSpin) => {
      const r = rig();
      r.run(2, { grounded: true });
      r.run(12, { grounded: false });
      return r.frame({ grounded: true, state: { vx: 100, vy: 50, midSpin } }).landing;
    };
    expect(land(undefined).quality).toBe('perfect');
    const penalised = land(true);
    expect(penalised.quality).toBe('good');
    expect(penalised.midSpin).toBe(true);
    expect(land(360).quality).toBe('perfect');
  });

  describe('mid-spin only when the phase is genuinely unfinished', () => {
    /** Air phase with a helicopter key held for `heldFrames` (drawing phase advancing `perFrame` deg), then landing. */
    const spinLanding = ({ heldFrames, perFrame, releaseFrames = 0, coastDeg = 0, landPhase }) => {
      const r = rig();
      r.run(2, { grounded: true });
      let phase = 0;
      for (let i = 0; i < heldFrames; i++) {
        phase += perFrame;
        r.frame({ input: { heli: 1 }, state: { heliDeg: phase, midSpin: phase } });
      }
      for (let i = 0; i < releaseFrames; i++) {
        phase += coastDeg / Math.max(1, releaseFrames);
        r.frame({ state: { heliDeg: phase, midSpin: phase } });
      }
      const p = landPhase != null ? landPhase : phase;
      return r.frame({ grounded: true, state: { vx: 100, vy: 50, heliDeg: p, midSpin: p } }).landing;
    };

    test('residual coast after a finished turn (+40 deg, key released) is not a penalty', () => {
      const l = spinLanding({ heldFrames: 40, perFrame: 9, releaseFrames: 10, coastDeg: 40 }); // 360 + 40
      expect(l.midSpin).toBe(false);
      expect(l.quality).toBe('perfect');
    });

    test('a brief key nudge (< a quarter turn) with the key released is not a penalty', () => {
      const l = spinLanding({ heldFrames: 4, perFrame: 8, releaseFrames: 8, coastDeg: 30 }); // 32 + 30 = 62 deg drawn
      expect(l.midSpin).toBe(false);
      expect(l.quality).toBe('perfect');
    });

    test('a real half-turn that was released is still mid-spin and drops a grade', () => {
      const l = spinLanding({ heldFrames: 20, perFrame: 9, releaseFrames: 4, coastDeg: 5 }); // ~185 deg
      expect(l.midSpin).toBe(true);
      expect(l.quality).toBe('crash');
    });

    test('key still held at touchdown with a short spin is mid-spin (the spin is unfinished)', () => {
      const r = rig();
      r.run(2, { grounded: true });
      r.run(10, { input: { heli: 1 }, state: { heliDeg: 30, midSpin: 30 } });
      r.frame({ input: { heli: 1 }, state: { heliDeg: 80, midSpin: 80 } });
      const l = r.frame({ grounded: true, state: { vx: 100, vy: 50, heliDeg: 90, midSpin: 90 } }).landing;
      expect(l.midSpin).toBe(true);
      expect(l.quality).toBe('sloppy');
    });

    test('a spin that crosses the quarter-turn minimum on the touchdown frame is still penalised', () => {
      const r = rig();
      r.run(2, { grounded: true });
      for (let i = 1; i <= 17; i++) r.frame({ input: { heli: 1 }, state: { heliDeg: i * 5, midSpin: i * 5 } }); // 85 deg, key held
      r.frame({ state: { heliDeg: 85, midSpin: 85 } }); // key released, still airborne: max spin so far 85 < 90
      const l = r.frame({ grounded: true, state: { vx: 100, vy: 50, heliDeg: 95, midSpin: 95 } }).landing; // 95 on touchdown
      expect(l.midSpin).toBe(true);
      expect(l.quality).toBe('sloppy');
    });

    test('a landing that is already sloppy does not report a spin cut', () => {
      const land = (groundAngleDeg) => {
        const r = rig();
        r.run(2, { grounded: true });
        r.run(12, { grounded: false });
        return r.frame({ grounded: true, state: { vx: 100, vy: 50, midSpin: true, groundAngleDeg } }).landing;
      };
      const sloppy = land(-(GOOD_ANGLE_DEG + 1));
      expect(sloppy.quality).toBe('sloppy');
      expect(sloppy.midSpin).toBe(false);
      expect(land(0).midSpin).toBe(true); // a perfect landing really was cut to good
    });

    test('an explicit midSpin: true is always honoured', () => {
      const r = rig();
      r.run(2, { grounded: true });
      r.run(10, {});
      expect(r.frame({ grounded: true, state: { vx: 100, vy: 50, midSpin: true } }).landing.midSpin).toBe(true);
    });
  });
});


describe('Corkscrew is a distinct composite trick', () => {
  test('full yaw turn while corkscrewing awards corkscrew, not free heli or flip points', () => {
    const r=rig();
    r.frame({grounded:true,state:{heliDeg:0}});
    const results=[];
    for(let i=1;i<=26;i++) results.push(r.frame({input:{corkscrew:true},state:{heliDeg:i*15},dAngle:8}));
    const types=allTricks(results).map(t=>t.type);
    expect(types).toContain('corkscrew');
    expect(types).not.toContain('helicopterCW');
    expect(types).not.toContain('frontflip');
  });
});

test('Corkscrew is a real scored trick without changing the established x2 combo cap', () => {
  expect(SCORING.trickBase.corkscrew).toBeGreaterThan(SCORING.trickBase.helicopterCW);
  expect(SCORING.comboStepTypes).not.toContain('corkscrew');
  expect(SCORING.comboStart + SCORING.comboStep * SCORING.comboStepTypes.length).toBe(2);
});/**
 * Modal views: navigation, focus and teardown (post-sprint audit fixes U1, U2, U3, UI-1, UI-2, U7a,
 * SHOP-3, F3 - the view half).
 *
 * Harness: a small but real fake of the Phaser surface the UI widgets touch. Every object has a working
 * destroy() (so leaked panels are observable), Zones keep their pointer handlers (so the pointer path can
 * be fired exactly as the built-game gate does) and Graphics record their fillRect calls (so painted
 * highlights can be measured). Scenes are stubs built on the real scene prototypes.
 *
 * Harness and the first red tests come from the UI audit branch (audit/ui at e0ae90f).
 */
import { jest } from '@jest/globals';
import fs from 'fs';
import path from 'path';

// ------------------------------------------------------------------ fake Phaser

class Emitter {
  constructor() { this._ev = new Map(); }
  on(e, fn, ctx) { if (!this._ev.has(e)) this._ev.set(e, []); this._ev.get(e).push({ fn, ctx, once: false }); return this; }
  once(e, fn, ctx) { if (!this._ev.has(e)) this._ev.set(e, []); this._ev.get(e).push({ fn, ctx, once: true }); return this; }
  off(e, fn) {
    const l = this._ev.get(e);
    if (!l) return this;
    if (!fn) { this._ev.delete(e); return this; }
    this._ev.set(e, l.filter((x) => x.fn !== fn));
    return this;
  }
  emit(e, ...a) {
    const l = this._ev.get(e);
    if (!l || !l.length) return false;
    for (const x of [...l]) {
      if (x.once) this.off(e, x.fn);
      x.fn.apply(x.ctx, a);
    }
    return true;
  }
  listenerCount(e) { return (this._ev.get(e) || []).length; }
  totalListeners() { let n = 0; for (const l of this._ev.values()) n += l.length; return n; }
  removeAllListeners() { this._ev.clear(); return this; }
}

class GO extends Emitter {
  constructor(scene, x = 0, y = 0) {
    super();
    this.scene = scene;
    this.x = x; this.y = y;
    this.visible = true; this.alpha = 1; this.scaleX = 1; this.scaleY = 1; this.depth = 0;
    this.originX = 0; this.originY = 0;
    this.list = [];
    this.destroyed = false;
    this.parentContainer = null;
    this.input = null;
    this.width = 0; this.height = 0;
  }
  add(c) {
    for (const o of [].concat(c)) {
      if (!o) continue;
      if (o.parentContainer && o.parentContainer !== this) o.parentContainer.remove(o);
      this.list.push(o);
      o.parentContainer = this;
      if (this.scene && this.scene.__top) this.scene.__top.delete(o);
    }
    return this;
  }
  remove(c) { for (const o of [].concat(c)) { this.list = this.list.filter((x) => x !== o); if (o) o.parentContainer = null; } return this; }
  setDepth(d) { this.depth = d; return this; }
  setPosition(x, y) { this.x = x; if (y !== undefined) this.y = y; return this; }
  setX(x) { this.x = x; return this; }
  setY(y) { this.y = y; return this; }
  setVisible(v) { this.visible = v; return this; }
  setAlpha(a) { this.alpha = a; return this; }
  setScale(sx, sy) { this.scaleX = sx; this.scaleY = sy === undefined ? sx : sy; return this; }
  setOrigin(ox, oy) { this.originX = ox; this.originY = oy === undefined ? ox : oy; return this; }
  setInteractive() { this.input = { enabled: true }; return this; }
  disableInteractive() { if (this.input) this.input.enabled = false; return this; }
  removeInteractive() { this.input = null; return this; }
  setSize(w, h) { this.width = w; this.height = h; return this; }
  setTint() { return this; }
  clearTint() { return this; }
  setBlendMode() { return this; }
  setScrollFactor() { return this; }
  setMask() { return this; }
  setAngle() { return this; }
  setRotation() { return this; }
  setCenterAlign() { return this; }
  setLeftAlign() { return this; }
  setRightAlign() { return this; }
  setLetterSpacing() { return this; }
  setFontSize() { return this; }
  setDropShadow() { return this; }
  setFillStyle() { return this; }
  setStrokeStyle() { return this; }
  bringToTop() { return this; }
  getBounds() { return { x: this.x, y: this.y, width: this.width, height: this.height }; }
  destroy() {
    if (this.destroyed) return;
    this.destroyed = true;
    for (const c of [...this.list]) if (c && c.destroy) c.destroy();
    this.list = [];
    if (this.parentContainer) this.parentContainer.remove(this);
    if (this.scene && this.scene.__top) this.scene.__top.delete(this);
    this.emit('destroy');
    this.scene = undefined;
  }
}

class BitmapText extends GO {
  constructor(scene, x, y, font, text) { super(scene, x, y); this.text = String(text === undefined ? '' : text); }
  setText(t) { this.text = String(t); return this; }
}
class Zone extends GO {
  constructor(scene, x, y, w, h) { super(scene, x, y); this.width = w; this.height = h; }
}
class Rect extends GO {
  constructor(scene, x, y, w, h) { super(scene, x, y); this.width = w; this.height = h; }
}
/** Graphics: records every drawing call; unknown drawing methods are recorded too. */
class Graphics extends GO {
  constructor(scene) {
    super(scene, 0, 0);
    this.ops = [];
    return new Proxy(this, {
      get(t, k, r) {
        if (typeof k !== 'string' || k in t || k === 'then') return Reflect.get(t, k, r);
        return (...a) => { t.ops.push([k, ...a]); return r; };
      },
    });
  }
  clear() { this.ops = []; return this; }
  fillStyle(...a) { this.ops.push(['fillStyle', ...a]); return this; }
  fillRect(...a) { this.ops.push(['fillRect', ...a]); return this; }
  lineStyle(...a) { this.ops.push(['lineStyle', ...a]); return this; }
  strokeRect(...a) { this.ops.push(['strokeRect', ...a]); return this; }
}

const FakePhaser = {
  Scene: class {},
  GameObjects: { Container: GO, Graphics, BitmapText, Zone, Image: GO, Rectangle: Rect, Text: BitmapText },
  Scenes: { Events: { UPDATE: 'update', SHUTDOWN: 'shutdown', DESTROY: 'destroy' } },
  Math: { Between: (a) => a, Clamp: (v, a, b) => Math.min(b, Math.max(a, v)) },
};

jest.unstable_mockModule('phaser', () => ({ default: FakePhaser }));
jest.unstable_mockModule('../../src/data/index.js', () => ({ content: {}, loadContent: () => ({}) }));

