// ================================================================== F3: shop boost gate (view half)

describe('F3: ShopView does not let a locked boost be switched on', () => {
  test('F3: on a level-1 profile no key or pointer path turns Head Start or Error Correction on', () => {
    const { s, view } = shopHost({ ...defaultProfile(), bank: 0 });
    const boostIdx = view.menu.items.map((it, i) => (it.boostId ? i : -1)).filter((i) => i >= 0);
    expect(boostIdx.length).toBe(2);
    for (const i of boostIdx) {
      expect(view.menu.items[i].disabled).toBe(true);
      expect(view.menu.items[i].sub).toMatch(/^LVL \d+$/);
    }
    // Keys: walk the whole list with every action at every stop.
    for (let n = 0; n < view.menu.items.length + 2; n++) {
      expect(boostIdx).not.toContain(view.menu.selected);
      for (const a of ['left', 'right', 'confirm']) {
        const cur = view.menu.items[view.menu.selected];
        if (cur && cur.boostId) view.handleAction(a);
      }
      view.handleAction('down');
    }
    // Pointer: click each boost row's zone.
    for (const i of boostIdx) {
      const z = view.menu.rows[i].zone;
      if (z) { z.emit('pointerover'); z.emit('pointerdown', {}, 10); z.emit('pointerdown', {}, 380); }
    }
    const b = s.registry.get(REG.PROFILE).boosts;
    expect(b.headStart).toBe(false);
    expect(b.errorCorrection).toBe(false);
  });

  test('F3 control: once unlocked.boosts.headStart is granted the toggle works', () => {
    const p = { ...defaultProfile(), xp: LEVELS.levels.find((l) => l.level === 8).xpMin, level: 8, unlocked: { ...defaultProfile().unlocked, boosts: { headStart: 1 } } };
    const { s, view } = shopHost(p);
    focusItem(view, (it) => it.boostId === 'headStart');
    view.handleAction('right');
    expect(s.registry.get(REG.PROFILE).boosts.headStart).toBe(true);
  });
});

// ================================================================== F4 fit: the shop pages by slot

describe('F4 fit: ShopView pages by slot, by key, pad and pointer', () => {
  const ids = (view) => view.menu.items.filter((i) => i.id && !i.boostId).map((i) => i.id);
  const pageRowIdx = (view) => view.menu.items.findIndex((i) => i.rowKind === 'page');
  const lvl30 = () => ({
    ...defaultProfile(), xp: LEVELS.levels[LEVELS.levels.length - 1].xpMin + 1, level: 30, bank: 0,
    unlocked: { ...defaultProfile().unlocked, boosts: { headStart: 8, errorCorrection: 15 } },
  });

  test('the shop opens on TRAIL with focus on the page row', () => {
    const { view } = shopHost(richProfile());
    expect(view.menu.selected).toBe(pageRowIdx(view));
    expect(ids(view).every((id) => id.startsWith('trail-'))).toBe(true);
  });

  test('right / left on the page row turn the page and wrap; focus stays on the page row', () => {
    const { view } = shopHost(richProfile());
    view.handleAction('right');
    expect(ids(view).length).toBeGreaterThan(0);
    expect(ids(view).every((id) => /glow/.test(id))).toBe(true);
    expect(view.menu.selected).toBe(pageRowIdx(view));
    view.handleAction('left');
    view.handleAction('left');
    expect(ids(view).every((id) => id.startsWith('theme-'))).toBe(true);
    expect(texts(view.panel).some((x) => /4\/4/.test(x))).toBe(true);
  });

  test('left / right on an item row also page (the slot is the page), confirm on the page row turns it forward', () => {
    const { view } = shopHost(richProfile());
    focusItem(view, (i) => i.id === 'trail-hue-ember');
    view.handleAction('right');
    expect(ids(view).every((id) => /glow/.test(id))).toBe(true);
    focusItem(view, (i) => i.rowKind === 'page');
    view.handleAction('confirm');
    expect(ids(view).every((id) => /rider/.test(id))).toBe(true);
  });

  test('a pointer click on the page row turns the page', () => {
    const { view } = shopHost(richProfile());
    const z = view.menu.rows[pageRowIdx(view)].zone;
    z.emit('pointerdown', {}, 10);
    expect(ids(view).every((id) => /glow/.test(id))).toBe(true);
  });

  test('left / right on an unlocked boost row toggle the boost and do not turn the page', () => {
    const { s, view } = shopHost(lvl30());
    const before = ids(view);
    focusItem(view, (i) => i.boostId === 'headStart');
    view.handleAction('right');
    expect(s.registry.get(REG.PROFILE).boosts.headStart).toBe(true);
    expect(ids(view)).toEqual(before);
  });

  test('buying works from any page, and the bank line refreshes', () => {
    const { s, view } = shopHost(richProfile());
    view._choose('rider-hue-mint'); // the built-game gate calls exactly this from the first page
    const p = s.registry.get(REG.PROFILE);
    expect(p.bank).toBe(400);
    expect(p.equipped.rider).toBe('mint');
    expect(texts(view.panel)).toContain('BANK 400');
  });

  test('SHOP-3 holds on a later page: confirm on EQUIPPED returns the slot to DEFAULT', () => {
    const p = { ...richProfile(), unlocked: { ...defaultProfile().unlocked, cosmetics: ['rider-hue-mint'] }, equipped: { ...defaultProfile().equipped, rider: 'mint' } };
    const { s, view } = shopHost(p);
    view.handleAction('right');
    view.handleAction('right');
    focusItem(view, (i) => i.id === 'rider-hue-mint');
    expect(view.menu.items[view.menu.selected].sub).toBe('EQUIPPED');
    view.handleAction('confirm');
    expect(s.registry.get(REG.PROFILE).equipped.rider).toBe('default');
    expect(ids(view).every((id) => /rider/.test(id))).toBe(true); // the page did not jump back
  });

  test('every page reaches every one of its rows by up/down', () => {
    const { view } = shopHost(lvl30());
    for (let page = 0; page < 4; page++) {
      const want = new Set(view.menu.items.map((it, i) => (it.disabled ? -1 : i)).filter((i) => i >= 0));
      const seen = new Set();
      for (let n = 0; n < view.menu.items.length * 2; n++) { seen.add(view.menu.selected); view.handleAction('down'); }
      expect([...want].filter((i) => !seen.has(i))).toEqual([]);
      focusItem(view, (i) => i.rowKind === 'page');
      view.handleAction('right');
    }
  });
});

// ================================================================== SHOP-5: the equipped theme reaches the UI

describe('SHOP-5: Theme applies the equipped UI theme', () => {
  const hex = (n) => `#${n.toString(16).padStart(6, '0')}`;
  const base = PALETTES.default;

  test('a scene Theme reads the equipped theme: accents change, danger does not', () => {
    const s = makeScene(null, { [REG.PROFILE]: { ...defaultProfile(), equipped: { ...defaultProfile().equipped, theme: 'sunset' } } });
    const th = new Theme(s);
    expect(hex(th.pal.cyan)).not.toBe(base.cyan);
    expect(th.css.cyan).toBe(hex(th.pal.cyan));
    expect(hex(th.pal.danger)).toBe(base.danger);
    expect(th.color('danger')).toBe(parseInt(base.danger.slice(1), 16));
  });

  test('no theme equipped: the Theme is the plain palette', () => {
    const th = new Theme(makeScene(null, { [REG.PROFILE]: defaultProfile() }));
    expect(th.css).toEqual(base);
  });

  test('colourblind keeps priority over an equipped theme', () => {
    const s = makeScene(null, {
      [REG.PROFILE]: { ...defaultProfile(), equipped: { ...defaultProfile().equipped, theme: 'legend' } },
      [REG.SETTINGS]: { palette: 'colorblind' },
    });
    expect(new Theme(s).css).toEqual(PALETTES.colorblind);
  });

  test('equipping a theme in the shop repaints the open screen live; unequipping restores it', () => {
    const lvl30 = { ...defaultProfile(), xp: LEVELS.levels[LEVELS.levels.length - 1].xpMin + 1, level: 30, bank: 0 };
    const { s, view } = shopHost(lvl30);
    const before = view.theme.pal.cyan;
    view._choose('theme-legend');
    expect(s.registry.get(REG.PROFILE).equipped.theme).toBe('legend');
    expect(view.theme.pal.cyan).not.toBe(before);
    view._choose('theme-legend'); // confirm on EQUIPPED -> DEFAULT (SHOP-3)
    expect(view.theme.pal.cyan).toBe(before);
  });
});

// ================================================================== SHOP-2: titles, by keyboard / pad

describe('SHOP-2: TITLES opens from Profile and buys / equips by keys', () => {
  const lvl3 = (bank = 500, extra = {}) => ({ ...defaultProfile(), xp: LEVELS.levels.find((l) => l.level === 3).xpMin, level: 3, bank, ...extra });
  const toTarget = (prof, kind) => {
    for (let n = 0; n < 40 && (prof._focusTargets()[prof.focusIdx] || {}).kind !== kind; n++) prof.handleAction('down');
    return (prof._focusTargets()[prof.focusIdx] || {}).kind === kind;
  };

  test('first focus on Profile still lands on SHARD SHOP when there are no toggle rows', () => {
    const t = titleHost({ [REG.PROFILE]: lvl3() });
    const prof = openProfile(t);
    prof.handleAction('down'); // the first action only places focus
    expect(prof._focusTargets()[prof.focusIdx].kind).toBe('buy');
  });

  test('down reaches TITLES, confirm opens the TITLES view, Static Rider buys and equips by keys', () => {
    const t = titleHost({ [REG.PROFILE]: lvl3() });
    const prof = openProfile(t);
    expect(toTarget(prof, 'titles')).toBe(true);
    prof.handleAction('confirm');
    const v = t.view;
    expect(v).toBeInstanceOf(TitlesView);
    for (let n = 0; n < 20 && v.menu.items[v.menu.selected].id !== 'title-static'; n++) v.handleAction('down');
    expect(v.menu.items[v.menu.selected].id).toBe('title-static');
    v.handleAction('confirm');
    const p = t.registry.get(REG.PROFILE);
    expect(p.bank).toBe(280);
    expect(p.equipped.title).toBe('STATIC RIDER');
    expect(texts(v.panel)).toContain('BANK 280');
    expect(v.menu.items[v.menu.selected].sub).toBe('EQUIPPED');
  });

  test('BACK from TITLES returns to Profile, which shows the equipped title; confirm on EQUIPPED restores the level title', () => {
    const t = titleHost({ [REG.PROFILE]: lvl3(0, { unlocked: { ...defaultProfile().unlocked, titles: ['CARTOGRAPHER'] } }) });
    const prof = openProfile(t);
    prof.titlesButton.zone.emit('pointerdown');
    let v = t.view;
    for (let n = 0; n < 20 && v.menu.items[v.menu.selected].id !== 'title-cartographer'; n++) v.handleAction('down');
    v.handleAction('confirm');
    v.handleAction('cancel');
    expect(t.view).toBeInstanceOf(ProfileView);
    expect(texts(t.view.panel)).toContain('CARTOGRAPHER');
    expect(v.panel).toBe(null); // the TITLES view is destroyed, not pinned over the menu
    expect(v.alive).toBe(false);
    t.view.titlesButton.zone.emit('pointerdown');
    v = t.view;
    for (let n = 0; n < 20 && v.menu.items[v.menu.selected].id !== 'title-cartographer'; n++) v.handleAction('down');
    v.handleAction('confirm'); // EQUIPPED -> DEFAULT
    expect(t.registry.get(REG.PROFILE).equipped.title).toBe('default');
    v.handleAction('cancel');
    expect(texts(t.view.panel)).toContain(LEVELS.levels[2].title.toUpperCase());
  });

  test('the Title badge redraws with the equipped title when Profile closes', () => {
    const t = titleHost({ [REG.PROFILE]: lvl3() });
    t._buildLevelBadge();
    const badge = () => t.levelBadge.map((b) => texts(b)[0]); // NeonText draws shadow + fill: read one
    expect(badge()).toContain(LEVELS.levels[2].title.toUpperCase());
    const prof = openProfile(t);
    prof.titlesButton.zone.emit('pointerdown');
    t.view._choose('title-static');
    t.view.handleAction('cancel'); // back to Profile
    t.view.handleAction('cancel'); // back to Title
    expect(t.view).toBe(null);
    expect(badge()).toContain('STATIC RIDER');
    expect(badge()).not.toContain(LEVELS.levels[2].title.toUpperCase());
  });

  test('a locked achievement title cannot be equipped by any key', () => {
    const t = titleHost({ [REG.PROFILE]: lvl3(99999) });
    openProfile(t).titlesButton.zone.emit('pointerdown');
    const v = t.view;
    for (let n = 0; n < 20; n++) { v.handleAction('confirm'); v.handleAction('down'); }
    expect(['default', 'ROOKIE', 'STATIC RIDER']).toContain(t.registry.get(REG.PROFILE).equipped.title);
    expect(v.menu.items.find((i) => i.id === 'title-omniscient').disabled).toBe(true);
  });
});/**
 * W4 defect 3 + 4 gates: the Title menu can be counted, and a modded Game Over tells the truth.
 *
 * CC Friday rejected W4 at 3bc06e2 for four screens, not for logic. Two of the four are unobservable in a
 * unit test (a shop that renders twice, a run labelled NEW TOP 10 when it is unranked) unless the geometry
 * and the labels are computed somewhere testable and then asserted. That is what this file pins:
 *
 *   * the Title menu cannot silently gain a seventh row — its height and its clearance from the DAILY PATCH
 *     strip are computed, and the row count that fits is proven rather than assumed;
 *   * a boosted run is judged by the same helper that keeps it off the clean board, so it is never offered
 *     clean-board initials, a seed best, or a clean top-10 headline.
 */
import { titleMenuLayout, TITLE_BANDS, SCREEN } from '../../src/ui/MissionsLayout.js';
import { ranksModded, isRankable, isModdedOnly } from '../../src/systems/Ranking.js';
import { MODDED_RUNS_RANKED } from '../../src/constants.js';

const overlaps = (a, b) => !(a.x + a.w <= b.x || b.x + b.w <= a.x || a.y + a.h <= b.y || b.y + b.h <= a.y);

// The synthwave Title reorganisation moved the menu onto the grid floor (y 154..254, left) and the DAILY PATCH
// into the right-hand cabinet card, so the band the menu must stay out of from below is now the control hint
// (y 258), and the Daily Patch is beside it rather than under it. The gates are the same: the row count that
// fits is computed and proven, and the panel overlaps nothing live.
describe('Title menu geometry (defect 3: SETTINGS overflowed into DAILY PATCH)', () => {
  test('the shipped six-row menu fits the band', () => {
    const geo = titleMenuLayout(6);
    expect(geo.fits).toBe(true);
    expect(geo.lastRowBottom).toBeLessThanOrEqual(TITLE_BANDS.menu.y + TITLE_BANDS.menu.h);
    expect(geo.lastRowBottom).toBeLessThanOrEqual(TITLE_BANDS.hint.y);
  });

  test('a seventh row would NOT fit — this is why SHARD SHOP moved to PROFILE', () => {
    // If a future change makes seven rows fit, this test should be updated rather than deleted; until then
    // it is the reason the shop entry lives on the Profile screen and the proof that the reason is real.
    const geo = titleMenuLayout(7);
    expect(geo.fits).toBe(false);
    expect(geo.lastRowBottom).toBeGreaterThan(TITLE_BANDS.hint.y);
  });

  test('the panel never overlaps the DAILY PATCH, the hint or the screen edge', () => {
    const geo = titleMenuLayout(6);
    const panel = { x: geo.x, y: geo.y, w: geo.w, h: geo.h };
    expect(overlaps(panel, TITLE_BANDS.daily)).toBe(false);
    expect(overlaps(panel, TITLE_BANDS.hint)).toBe(false);
    expect(panel.y + panel.h).toBeLessThanOrEqual(TITLE_BANDS.hint.y);
    expect(panel.y + panel.h).toBeLessThanOrEqual(SCREEN.h);
  });

  test('the panel height is the sum of its rows, not the rows times the text scale', () => {
    // The old formula multiplied by `scale`, so a 6-row panel claimed to be 196px tall and was drawn to
    // 188 while reporting 228 for seven rows. MenuList scales the glyphs, not the pitch.
    const three = titleMenuLayout(3);
    const six = titleMenuLayout(6);
    expect(six.h - three.h).toBe(three.rowH * 3);
    expect(six.h).toBeLessThan(TITLE_BANDS.menu.h + 40);
  });

  test('the panel clears the cabinet card and the HOW TO PLAY chip beside it', () => {
    // The CONTROLS panel that used to sit beside the menu is now the HOW TO PLAY view; the right-hand
    // neighbour is the cabinet card, with the help chip in the open column between them. Overlap would cover
    // the Daily Patch or the chip, which is the kind of thing only a screenshot catches.
    const geo = titleMenuLayout(6);
    const panel = { x: geo.x, y: geo.y, w: geo.w, h: geo.h };
    expect(overlaps(panel, TITLE_BANDS.card)).toBe(false);
    expect(overlaps(panel, TITLE_BANDS.help)).toBe(false);
  });
});

describe('a modded run is unranked, and says so (defect 4)', () => {
  const clean = { id: 'a', score: 900, modded: false };
  const boosted = { id: 'b', score: 900, modded: true };

  test('the shipped constant keeps boosted runs off the clean board', () => {
    expect(MODDED_RUNS_RANKED).toBe(false);
  });

  test('Ranking is the only thing deciding, and it agrees for both boards', () => {
    // Game Over asks isRankable/ranksModded rather than testing rec.modded itself. These three assertions
    // are the contract those call sites depend on.
    expect(isRankable(boosted)).toBe(false);
    expect(isModdedOnly(boosted)).toBe(true);
    expect(isRankable(clean)).toBe(true);
    expect(isModdedOnly(clean)).toBe(false);
    expect(ranksModded()).toBe(false);
  });

  test('flipping the constant makes a boosted run rankable and stops it being modded-only', () => {
    // The spec's W4 gate: flip the constant and prove the exclusion actually follows it, so the exclusion
    // is not accidental behaviour that happens to match the default.
    expect(isRankable(boosted, { ranked: true })).toBe(true);
    expect(isModdedOnly(boosted, { ranked: true })).toBe(false);
  });

  test('a modded run that earns a score still earns it — the board is separate, not a penalty', () => {
    // Spec W4 is explicit: boosted runs still earn Resonance, shards and mission progress. Nothing in
    // Ranking may zero a score; it only decides which board the score appears on.
    expect(boosted.score).toBe(clean.score);
    expect(isRankable(boosted)).toBe(false);
  });
});import { AudioSynth } from '../../src/systems/AudioSynth.js';
import { motifDecor } from '../../src/entities/Background.js';
import { biomeDanceStyle, sunDanceGeometry, WorldDanceEnvelope } from '../../src/systems/WorldDance.js';

/**
 * A deliberately partial AudioSynth: this is a UNIT SEAM, not a synth.
 * It proves the sample *shape* and the downstream contract, never that a real
 * synth is audible. Two seams are stubbed for that reason:
 *   - `_vinylAudible()` in production also requires `this.nodes`
 *     (AudioSynth.js:713-718); this fixture omits `nodes`, so without the stub
 *     `getWorldDanceSample()` would return null. The stub is the seam.
 *   - `getFatalCountInStatus()` is stubbed to a permanent idle state so the
 *     fixture does not depend on the count-in state machine or its timers.
 * `track.id: 'diagnostic'` is NOT a catalog song. `hasEnabledSongs()` succeeds
 * only because `sanitizeSongSelection()` defaults the real catalog songs to
 * enabled (MusicPlaylist.js:11-17,43-44) — it says nothing about 'diagnostic'.
 */
function audioFixture() {
  const synth = Object.create(AudioSynth.prototype);
  synth.ctx = { currentTime: 0, state: 'running' };
  synth._stemMusic = {
    started: true,
    transportPaused: false,
    track: { id: 'diagnostic' },
    pack: { id: 'diagnostic', frameCount: 480000, sampleRate: 48000 },
    clockStart: 0,
    _token: 1,
    activeNodes: { size: 6 },
    songEnabled: { diagnostic: true },
    mixer: { energy: () => ({ bass: 0.3, mid: 0.3, treble: 0 }) },
  };
  synth._destroyed = false;
  synth._musicMode = 'run';
  synth._paused = false;
  synth._musicWanted = true;
  synth.settings = { masterVolume: 1, musicVolume: 1, musicEnabledSongs: { diagnostic: true } };
  synth._vinylAudible = () => true; // unit seam: the fixture has no `nodes` (see above)
  synth.getFatalCountInStatus = () => ({ active: false }); // unit seam: keep recovery idle (see above)
  return synth;
}

const CADENCE_MS = 50;
const BEAT_MS = 500;

/**
 * Drive the real producer (`getWorldDanceSample`/`getSyntheticMeterTiming`)
 * into the real envelope on a uniform render cadence. Every frame advances the
 * audio clock by exactly `CADENCE_MS` and passes the same `dt`, so intensity
 * smoothing and pulse decay see the same interval — no synthetic gaps.
 */
function cadence(frames, energyAt) {
  const synth = audioFixture();
  const envelope = new WorldDanceEnvelope();
  const series = [];
  for (let i = 0; i < frames; i++) {
    const timeMs = i * CADENCE_MS;
    synth.ctx.currentTime = timeMs / 1000;
    const { bass, mid } = energyAt(i);
    synth._stemMusic.mixer.energy = () => ({ bass, mid, treble: 0 });
    const sample = synth.getWorldDanceSample();
    const timing = synth.getSyntheticMeterTiming();
    series.push({ timeMs, strength: envelope.update(sample, CADENCE_MS, timing) });
  }
  return series;
}

/** The settled ordinary-beat level of a uniform 0.30/0.30 cadence: the peak of
 * the last full beat window after several measures of adaptation. */
function settledLevel() {
  const strengths = cadence(120, () => ({ bass: 0.3, mid: 0.3 })).map(f => f.strength);
  return Math.max(...strengths.slice(-BEAT_MS / CADENCE_MS));
}

const meter = (revision, beatIndex, measureIndex = 0, overrides = {}) => ({
  timingKind: 'synthetic-unverified',
  use: 'cosmetic-only',
  trusted: false,
  canAuthorizeGameplay: false,
  beatIndex,
  measureIndex,
  beatInMeasure: beatIndex % 4 + 1,
  transportRevision: revision,
  ...overrides,
});

/**
 * Sun geometry from the real `sunDanceGeometry()`. These are RADIUS deltas:
 * the drawn sun's width/height changes by twice each delta (+4.8p/-3.6p px at
 * radius 40 mean a +9.6p/-7.2p px full width/height change). Do not read a
 * radius delta as a diameter change.
 */
function sunPixels(strength) {
  const sun = sunDanceGeometry(strength, 40);
  return {
    strength,
    widthRadiusDeltaPx: sun.widthRadius - 40,
    heightRadiusDeltaPx: sun.heightRadius - 40,
  };
}

/**
 * MEASURED decor displacement, not a formula. Drive the production
 * `motifDecor()` twice at a fixed (motif, scrollX, timeMs, seed): once with no
 * horizon dance, once with the motif's real horizon dance value for this
 * strength (`biomeDanceStyle`, the same value Background passes at
 * Background.js:777-779). Return the observed max |Δy| across every primitive's
 * `pts[].y` and `y`.
 *
 * The theoretical ceiling is 1.7 × horizonDance (|sin| ≤ 1), which for these
 * motifs stays at or below 1.19 × strength; `sin` attenuates the observed value
 * below that, so assertions use a loose bound and never an exact float.
 * Motif dependence is real: stars, jellyfish and brass-pipes never feed
 * `horizonDanceOffset()` into a primitive and measure exactly 0.
 */
function measureDecorDisplacement(motif, strength, at = { scrollX: 400, timeMs: 1234, seed: 0 }) {
  const { horizon } = biomeDanceStyle(motif, strength);
  const still = motifDecor(motif, at.scrollX, at.timeMs, at.seed, { horizonDance: 0, bees: false });
  const dancing = motifDecor(motif, at.scrollX, at.timeMs, at.seed, { horizonDance: horizon, bees: false });
  expect(dancing).toHaveLength(still.length);
  let maxAbsDeltaY = 0;
  for (let i = 0; i < still.length; i++) {
    const before = still[i].pts || [];
    const after = dancing[i].pts || [];
    expect(after).toHaveLength(before.length);
    for (let j = 0; j < before.length; j++) {
      maxAbsDeltaY = Math.max(maxAbsDeltaY, Math.abs(before[j].y - after[j].y));
    }
    if (typeof still[i].y === 'number' && typeof dancing[i].y === 'number') {
      maxAbsDeltaY = Math.max(maxAbsDeltaY, Math.abs(still[i].y - dancing[i].y));
    }
  }
  return { motif, strength, horizonDance: horizon, maxAbsDeltaY };
}

describe('World Dance diagnostic: producer, unverified meter, envelope and pixels', () => {
  test('AudioSynth producer sample shape flows into the real envelope', () => {
    const synth = audioFixture();
    const sample = synth.getWorldDanceSample();
    const timing = synth.getSyntheticMeterTiming();

    expect(sample).toMatchObject({
      revision: expect.any(String),
      timeMs: expect.any(Number),
      bass: 0.3,
      mid: 0.3,
    });
    expect(Number.isFinite(sample.timeMs)).toBe(true);
    expect(timing).toMatchObject({
      timingKind: 'synthetic-unverified',
      use: 'cosmetic-only',
      trusted: false,
      canAuthorizeGameplay: false,
      beatIndex: expect.any(Number),
      measureIndex: expect.any(Number),
      beatInMeasure: 1,
    });
    expect(Number.isInteger(timing.beatIndex)).toBe(true);
    expect(Number.isInteger(timing.measureIndex)).toBe(true);
    expect(timing.transportRevision).toBe(sample.revision);

    const envelope = new WorldDanceEnvelope();
    const strength = envelope.update(sample, 16.7, timing);
    expect(Number.isFinite(strength)).toBe(true);
    expect(strength).toBeGreaterThanOrEqual(0);
    expect(strength).toBeLessThanOrEqual(1);
    expect(envelope.revision).toBe(sample.revision);
    expect(envelope.lastSampleMs).toBe(sample.timeMs);
  });

  test.each([
    ['null sample', null],
    ['non-finite time', { revision: 'r', timeMs: Infinity, bass: 0.3, mid: 0.3 }],
    ['missing revision', { timeMs: 1, bass: 0.3, mid: 0.3 }],
    ['non-string revision', { revision: 4, timeMs: 1, bass: 0.3, mid: 0.3 }],
    ['NaN bass', { revision: 'r', timeMs: 1, bass: NaN, mid: 0.3 }],
  ])('%s resets the envelope', (_label, sample) => {
    const envelope = new WorldDanceEnvelope();
    envelope.pulse = 0.8;
    envelope.mixLevel = 0.3;
    expect(envelope.update(sample, 16.7)).toBe(0);
    expect(envelope.strength).toBe(0);
  });

  test('matching unverified meter boundary accents after neutral first observation; invalid gates add none', () => {
    const sample0 = { revision: 'r', timeMs: 0, bass: 0.3, mid: 0.3 };
    const envelope = new WorldDanceEnvelope();
    envelope.update(sample0, 16.7, meter('r', 3, 0));
    expect(envelope.meterPulse).toBe(0);
    expect(envelope.update({ ...sample0, timeMs: 500 }, 16.7, meter('r', 4, 1, { beatInMeasure: 1 }))).toBeGreaterThan(0);
    expect(envelope.meterPulse).toBeCloseTo(0.85);

    const rejects = [
      { timingKind: 'verified' },
      { trusted: true },
      { canAuthorizeGameplay: true },
      { beatIndex: 1.5 },
      { transportRevision: 'other' },
    ];
    for (const override of rejects) {
      const fresh = new WorldDanceEnvelope();
      fresh.update(sample0, 16.7, meter('r', 0, 0));
      const pulseBefore = fresh.meterPulse;
      fresh.update({ ...sample0, timeMs: 500 }, 16.7, meter('r', 1, 0, override));
      expect(fresh.meterPulse).toBe(pulseBefore);
    }
  });

  test('revision changes and backward clock movement reset to zero', () => {
    const envelope = new WorldDanceEnvelope();
    envelope.update({ revision: 'r', timeMs: 0, bass: 0.1, mid: 0.1 }, 16.7);
    envelope.update({ revision: 'r', timeMs: 50, bass: 0.8, mid: 0.3 }, 50);
    expect(envelope.strength).toBeGreaterThan(0);
    expect(envelope.update({ revision: 'next', timeMs: 100, bass: 0.3, mid: 0.3 }, 16.7)).toBe(0);
    envelope.update({ revision: 'next', timeMs: 150, bass: 0.8, mid: 0.3 }, 50);
    expect(envelope.update({ revision: 'next', timeMs: 120, bass: 0.3, mid: 0.3 }, 16.7)).toBe(0);
  });

  test('silence cannot bounce, even at a valid unverified meter boundary', () => {
    const envelope = new WorldDanceEnvelope();
    envelope.update({ revision: 'r', timeMs: 0, bass: 0, mid: 0 }, 16.7, meter('r', 0, 0));
    const strength = envelope.update({ revision: 'r', timeMs: 500, bass: 0, mid: 0 }, 16.7, meter('r', 1, 0));
    expect(strength).toBeLessThanOrEqual(1e-12);
  });

  test('uniform cadence reaches a steady state across several beats', () => {
    // 120 frames × 50 ms = 6000 ms = 12 synthetic beats (500 ms each), so the
    // startup adaptation is long past and we can compare whole beat windows.
    const series = cadence(120, () => ({ bass: 0.3, mid: 0.3 }));
    const strengths = series.map(f => f.strength);
    const perBeat = BEAT_MS / CADENCE_MS;
    const settled = Math.max(...strengths.slice(-perBeat));
    const earlier = Math.max(...strengths.slice(-2 * perBeat, -perBeat));

    // Bounded, and genuinely steady: every frame of the last two beat windows
    // agrees with the same phase of the previous 500 ms beat.
    expect(settled).toBeGreaterThan(0);
    expect(settled).toBeLessThanOrEqual(1);
    expect(Math.abs(settled - earlier)).toBeLessThan(1e-6);
    for (let i = strengths.length - 2 * perBeat; i < strengths.length - perBeat; i++) {
      expect(strengths[i + perBeat]).toBeCloseTo(strengths[i], 6);
    }

    const settledPixels = sunPixels(settled);
    // Radius deltas from the real sunDanceGeometry(): +4.8p / -3.6p px at r=40.
    expect(settledPixels.widthRadiusDeltaPx).toBeCloseTo(4.8 * settled, 10);
    expect(settledPixels.heightRadiusDeltaPx).toBeCloseTo(-3.6 * settled, 10);

    // Measured decor displacement at this settled strength (not a formula).
    const motifs = ['candy-stripes', 'stars', 'vents', 'dew-drops', 'jellyfish', 'brass-pipes'];
    const decor = motifs.map(m => measureDecorDisplacement(m, settled));
    const byMotif = Object.fromEntries(decor.map(d => [d.motif, d]));
    for (const d of decor) {
      // Theoretical ceiling: |1.7·horizonDance·sin(...)| ≤ 1.7·horizonDance,
      // and horizonDance ≤ 0.7·strength, hence ≤ 1.19·strength. Loose, never exact.
      expect(d.maxAbsDeltaY).toBeLessThanOrEqual(1.19 * settled);
    }
    // These motifs do route horizonDance into decor roots: real, non-zero motion.
    expect(byMotif['candy-stripes'].maxAbsDeltaY).toBeGreaterThan(0.5 * 1.7 * byMotif['candy-stripes'].horizonDance);
    expect(byMotif.vents.maxAbsDeltaY).toBeGreaterThan(0);
    expect(byMotif['dew-drops'].maxAbsDeltaY).toBeGreaterThan(0);
    // These never feed horizonDanceOffset() into a primitive: exactly zero,
    // not "a small number we never measured".
    expect(byMotif.stars.maxAbsDeltaY).toBe(0);
    expect(byMotif.jellyfish.maxAbsDeltaY).toBe(0);
    expect(byMotif['brass-pipes'].maxAbsDeltaY).toBe(0);

    console.log('World Dance settled level (ordinary beat, measured)', {
      settledStrength: settled,
      sun: settledPixels,
      decorDisplacementsPx: decor,
      theoreticalCeilingPx: 1.19 * settled,
    });
  });

  // Name this for what it proves: a bounded decay from the onset peak. It does NOT prove
  // convergence to `settled`, because this sequence sustains a different level (0.52/0.25)
  // than settledLevel() (0.30/0.30), so the post-decay plateau is a different equilibrium.
  test('transient onset peaks above settled then decays monotonically from the peak', () => {
    const transient = cadence(20, i => (
      i === 0 ? { bass: 0.1, mid: 0.08 } : { bass: 0.52, mid: 0.25 }
    ));
    const strengths = transient.map(f => f.strength);
    const onsetPeak = Math.max(...strengths);
    const settled = settledLevel();

    expect(onsetPeak).toBeGreaterThan(settled);

    // At least three post-onset frames must decay monotonically, and the peak must fall
    // appreciably rather than staying pinned. This is a decay bound, not a convergence test.
    const afterOnset = strengths.slice(1);
    expect(afterOnset.length).toBeGreaterThanOrEqual(4);
    for (let i = 1; i < 4; i++) {
      expect(afterOnset[i]).toBeLessThan(afterOnset[i - 1]);
    }
    expect(afterOnset[3]).toBeLessThan(onsetPeak * 0.75);

    const transientPixels = sunPixels(onsetPeak);
    // Sun deltas are radius deltas; a rendered sun's full width/height changes
    // by twice these values (+9.6p / -7.2p px full extent at r=40).
    expect(transientPixels.widthRadiusDeltaPx).toBeCloseTo(4.8 * onsetPeak, 10);
    expect(transientPixels.heightRadiusDeltaPx).toBeCloseTo(-3.6 * onsetPeak, 10);

    console.log('World Dance transient onset peak vs settled level (measured)', {
      onsetPeakStrength: onsetPeak,
      settledStrength: settled,
      sun: transientPixels,
    });
  });
});

