});#!/usr/bin/env python3
"""Conservative v2 candidate release detector experiments — NOT shipped audio.

Shared 48kHz performance-v1 output is the only eventual replacement contract.
Current game music/audio remains v1. These algorithms generate *candidate*
hypotheses for offline comparison and human review, never calibrated confidence.

Design: 10ms spectral novelty provides coarse attacks, 2ms RMS slopes
refine sample-frame positions. >=80ms cross-attack suppression prevents
reverb echoes from becoming extra notes while retaining 120ms re-attacks.
2048-sample windows + interpolated 8192-bin FFT give harmonic-supported pitch
hypotheses and remove release v1's impossible low-semitone bins.
"""
import math
import numpy as np
import librosa
from scipy.signal import find_peaks

RATE=16000
HOP=160
ROLE_MIN_GAP_SEC=.080
FFT_LEN=8192
PITCH_LOW=41
PITCH_HIGH=91
PITCHES=np.arange(PITCH_LOW,PITCH_HIGH+1)
FUNDAMENTALS=440.0*2.0**((PITCHES-69.0)/12.0)


def rms_envelope(y,step=32,width=64):
	"""Windowed RMS with ~2ms attack grid, centered windows."""
	if y.ndim!=1 or len(y)<width*2:
		raise ValueError('Detector needs mono audio longer than two windows')
	y=np.asarray(y,dtype='float64')
	sq=y*y
	prefix=np.r_[0.,np.cumsum(sq)]
	centers=np.arange(0,len(y),step)
	l=np.maximum(0,centers-width//2)
	r=np.minimum(len(y),centers+width//2)
	rms=np.sqrt(np.maximum(0,(prefix[r]-prefix[l])/(r-l)))
	return centers,rms

def source_onsets(y,min_gap_sec=ROLE_MIN_GAP_SEC):
	"""Source-aware onset proposals, not an accuracy label.

	FFT flux remains source-derived, while attack timestamp comes from
	measuring actual waveform RMS growth. Return 16kHz-sample onset indices,
	coarse candidate stats, and uncalibrated detector diagnostics.
	"""
	y=np.asarray(y,dtype='float32')
	if not len(y):return [],{'proposals':0,'retained':0,'status':'empty'}
	stft=np.abs(librosa.stft(y,n_fft=1024,hop_length=HOP,center=True))
	positive=np.maximum(0,np.diff(np.log1p(stft*25),axis=1))
	# Weight low and mid pitched energy; ignore upper hiss to avoid triggers
	# from stem leakage. Clipped frequency support starts above sub-bass.
	freq=np.fft.rfftfreq(1024,1/RATE)
	band=(freq>70)&(freq<5300)
	flux=np.mean(positive[band],axis=0)
	if len(flux)<4:return [],{'proposals':0,'retained':0,'status':'too-short'}
	threshold=max(.001,float(np.percentile(flux,68))*.23)
	gap=max(1,round(min_gap_sec*RATE/HOP))
	peaks,_=find_peaks(flux,prominence=threshold,distance=gap)
	centers,env=rms_envelope(y)
	# Local waveform-envelope gradients: sharp rises, not smooth decays.
	# diff(t) compares energy approximately 8ms before to 4ms after.
	l=np.maximum(0,np.arange(len(env))-4)
	r=np.minimum(len(env)-1,np.arange(len(env))+2)
	rise=np.maximum(0,env[r]-env[l])
	min_rise=max(float(np.percentile(rise,90))*.16,
		float(np.percentile(env,85))*.018,2e-5)
	onsets=[]
	for p in peaks:
		coarse=(int(p)+1)*HOP
		# Broadband flux is routinely up to 15ms early; search both sides.
		a=max(0,round((coarse-.025*RATE)/32))
		b=min(len(env),round((coarse+.04*RATE)/32)+1)
		if b<=a:continue
		chunk=rise[a:b]
		k=int(a+np.argmax(chunk))
		if rise[k]<min_rise:continue
		start=int(centers[k])
		# Discard any candidate with low attack contrast compared to the
		# immediately preceding local envelope. A genuine re-pluck
		# must exhibit a new attack, not just a bright sustain harmonic.
		before=float(np.median(env[max(0,k-8):max(1,k-3)]))
		after=float(np.median(env[min(len(env)-1,k+1):min(len(env),k+5)]))
		if after<before*1.14 and after-before<min_rise*.55:
			continue
		if onsets and start-onsets[-1] < min_gap_sec*RATE:
			# Prefer the candidate with stronger local amplitude slope.
			old=round(onsets[-1]/32)
			if rise[k]>rise[min(len(rise)-1,old)]*1.35:
				onsets[-1]=start
			continue
		onsets.append(start)
	return onsets,{'proposals':len(peaks),'retained':len(onsets),
		'resolutionMs':2.,'minimumGapMs':round(min_gap_sec*1000,1),
		'confidenceCalibrated':False}

def harmonic_candidates(y,onset,window_samples=2048,max_notes=2):
	"""Interpolate off-grid harmonics; subharmonic aliases are penalized.

	Return tuple (MIDI, raw heuristic salience). No salience is a confidence
	probability. Separate sustained/mixed-stem tests must qualify this model.
	"""
	y=np.asarray(y,dtype='float32')
	start=max(0,int(onset)+160)
	stop=min(len(y),start+window_samples)
	frame=y[start:stop]
	if len(frame)<384:return []
	frame=frame-np.mean(frame)
	window=np.hanning(len(frame))
	magnitude=np.abs(np.fft.rfft(frame*window,n=FFT_LEN))
	hz=np.fft.rfftfreq(FFT_LEN,d=1/RATE)
	# 8192-point padding is interpolation, NOT additional acoustic
	# resolution; 128ms actual window is the limiting low-note span.
	harmonics=[]
	base=[]
	for f in FUNDAMENTALS:
		energy=[]
		for harmonic in range(1,6):
			frequency=f*harmonic
			if frequency>4000:
				energy.append(0.);continue
			bin0=np.searchsorted(hz,frequency)
			halfwidth=max(2,round((4.0+frequency*.004)*FFT_LEN/RATE))
			seg=magnitude[max(0,bin0-halfwidth):min(len(magnitude),bin0+halfwidth+1)]
			energy.append(float(seg.max()) if seg.size else 0.)
		# Stronger harmonics are not independently interpreted as a
		# low pitch without support near f and 2f.
		score=sum(v/(i**1.1) for i,v in enumerate(energy,1))
		anchor=energy[0]+energy[1]*.6
		harmonics.append(score)
		base.append(anchor)
	harmonics=np.asarray(harmonics)
	base=np.asarray(base)
	global_max=float(np.max(harmonics)) if len(harmonics) else 0.
	if global_max<=1e-6:return []
	# Relative floor and local neighborhood competition stop spurious
	# scores 1 semitone from a real fundamental.
	local,_=find_peaks(harmonics,distance=2)
	candidates=[]
	for idx in local:
		if harmonics[idx]<global_max*.34 or base[idx]<max(base)*.27:
			continue
		pitch=int(PITCHES[idx])
		candidates.append((pitch,float(harmonics[idx]),float(base[idx])))
	candidates.sort(key=lambda x:x[1],reverse=True)
	selected=[]
	for pitch,salience,fundamental in candidates:
		if any(abs(pitch-m)<2 for m,_ in selected):
			continue
		# If a lower detected candidate also explains the harmonic, do
		# not count the overtone as an independent note.
		if any(pitch-m in (12,19,24) and strength>=salience*.6
			for m,strength in selected):
			continue
		selected.append((pitch,salience))
		if len(selected)>=max_notes:break
	return selected

def accompaniment(y):
	"""Generate standalone candidate score-v1 legacy note API, source-driven."""
	attacks,stats=source_onsets(y)
	events=[]
	for i,attack in enumerate(attacks):
		pitches=harmonic_candidates(y,attack)
		if not pitches:continue
		start=round(attack/RATE,4)
		if i+1<len(attacks):
			duration=min(.7,max(.095,(attacks[i+1]-attack)/RATE*.85))
		else:
			duration=.3
		for pitch,salience in pitches:
			events.append({'midi':pitch,'start':start,
				'end':round(start+duration,4),
				'confidence':None,'expression':{'estimatedVelocity':None}})
	return events,{**stats,'hypothesizedNotes':len(events),
		'algorithm':'experimental-v2-harmonic-rms-onsets',
		'quality':'unverified-candidate-not-publishable'}


def bass_replucks(y):
	"""Split same-pitch sustained YIN spans on validated re-attack cues.

	We preserve the legacy pitch track and do NOT invent octave guesses.
	This isolates Fable's missing repeated-bass-note defect from unrelated
	pitch model changes. Old + new share identical role/event JSON.
	"""
	from render_full_dynamic_orchestra_v1 import choose_bass_events
	old,meta=choose_bass_events(y)
	attacks,attack_meta=source_onsets(y,min_gap_sec=.09)
	out=[]
	for item in old:
		a=item['start']
		b=item['end']
		pitch=item['midi']
		# A 0.30-0.38s legitimate pluck with reverb tail often has one
		# phantom attack 140ms later. Short segments cannot establish
		# a repeated-note pattern, so do not modify them at all.
		if b-a<.42:
			out.append(item)
			continue
		within=sorted(t/RATE for t in attacks if a+.10<=t/RATE<=b-.07)
		regular=[t for t in within if t<=b-.09]
		gaps=np.diff(regular)
		# Multiple attacks at near-regular subbeat intervals are stronger
		# evidence of re-striking than a single source transient. This
		# conservative gate intentionally leaves ambiguous notes alone.
		if len(regular)<2 or len(gaps)<1 or np.min(gaps)<.085 or (
			np.max(gaps)>.27) or np.std(gaps)>max(.019,np.mean(gaps)*.24):
			out.append(item)
			continue
		earlier=[t/RATE for t in attacks if a-.03<=t/RATE<=a+.08]
		first=min(earlier,key=lambda t:abs(t-a-.045)) if earlier else a
		points=[first]
		for t in regular:
			if t-points[-1]>=.08 and b-t>=.07:
				points.append(t)
		if len(points)<3:
			out.append(item)
			continue
		for i,start in enumerate(points):
			end=points[i+1] if i+1<len(points) else b
			if end-start>=.065:
				out.append({'midi':pitch,'start':round(start,4),
					'end':round(end,4)})
	return out,{'algorithm':'release-v1-YIN-pitch-plus-v2-source-reattacks',
		'baselineBassEvents':len(old),'candidateBassEvents':len(out),
		'addedReattacks':len(out)-len(old),'attackProposals':attack_meta,
		'confidenceCalibrated':False}


def drum_simultaneous(y):
	"""Independent per-family onset streams, including simultaneous co-hits.

	Unlike release v1 (one class per broadband onset), each family has its
	own spectral/onset evidence. Synthetic tests may still expose false
	co-hits; do not deploy until real drums manually reviewed.
	"""
	from scipy.signal import butter,sosfiltfilt
	y=np.asarray(y,dtype='float32')
	if len(y)<RATE//4:return [],{'reason':'too-short'}
	config={
		'kick':(45,180,.055),
		'snare':(350,3500,.055),
		'hat':(4400,7500,.044),
	}
	out=[]
	raw=[]
	for kind,(low,high,gap) in config.items():
		sos=butter(4,[low,high],btype='bandpass',fs=RATE,output='sos')
		band=sosfiltfilt(sos,y).astype('float32')
		centers,env=rms_envelope(band)
		idx=np.arange(len(env))
		past=np.maximum(0,idx-5)
		future=np.minimum(len(env)-1,idx+2)
		gain=np.maximum(0,env[future]-env[past])
		# Refractory windows affect ONLY this drum family.
		threshold=max(
			float(np.percentile(gain,87))*.3,
			float(np.max(gain))*.023,
			1e-5)
		peaks,_=find_peaks(gain,
			distance=max(1,round(gap*RATE/32)),
			prominence=threshold)
		for peak in peaks:
			frame=int(centers[peak])
			before=float(np.median(env[max(0,peak-8):max(1,peak-3)]))
			after=float(np.median(env[min(len(env)-1,peak+1):
				min(len(env),peak+5)]))
			if after-before<max(threshold*.4,2e-5):
				continue
			if after < before*1.2 and after-before<threshold:
				continue
			raw.append((frame,kind,float(gain[peak]),after))
	# Co-hits across band families remain distinct source events.
	raw.sort(key=lambda x:(x[0],x[1]))
	# A strongly decaying repeat of the SAME family inside 170ms is
	# echo-suspect. Never compare across families: kick+snare co-hits
	# are intentional. This is a hypothesis, not real-hit truth, and
	# could reject legitimate quiet ghost notes: audit on human gold.
	accepted={}
	removed_echo_suspects=0
	for frame,kind,gain,energy in raw:
		last=accepted.get(kind)
		if last is not None:
			last_frame,last_gain,last_energy=last
			dt=(frame-last_frame)/RATE
			if .052<=dt<=.17 and gain<last_gain*.52 and (
				energy<last_energy*.83):
				removed_echo_suspects+=1
				continue
		accepted[kind]=(frame,gain,energy)
		out.append({'t':round(frame/RATE,4),'type':kind})
	return out,{'algorithm':'v2-family-independent-band-envelope-attacks',
		'removedEchoSuspects':removed_echo_suspects,
		'candidateHits':len(out),
		'families':{role:sum(x['type']==role for x in out)
			for role in config},'confidenceCalibrated':False}#!/usr/bin/env python3
"""Comparative review queue for two source-pinned performance-v1 scores.

IMPORTANT: Neither score is ground truth. Matches/disagreements are only
*model-to-model agreement*, not precision, recall or a proof of accuracy.
Rank disagreements and conservative source-attack-density alarms for a
future human-annotated real-song gold set. No WAV/Opus outputs or game writes.
"""
import argparse
import json
import math
from collections import defaultdict
from pathlib import Path

from performance_v1 import read, ROLES,STEMS
from evaluate_performance_v1 import match_events

RATE=48000
WINDOW_SEC=8
WINDOW=WINDOW_SEC*RATE
TOLERANCE_MS=50
TOLERANCE=round(RATE*TOLERANCE_MS/1000)
PRIORITY={'melody':5.,'bass':4.,'drums':3.5,'guitar':2.,'piano':2.5,'other':2.}
SONG_NAMES={
	'FEsxYVStla4':'Pope',
	'local-one-more-run-bitstream-bluffs':'One More Run',
	'WRBGQUqD54U':'Runs Out of Code',
	'FYImnz5-hXs':'Varmont',
}

def label(role,item):
	return item['class'] if role=='drums' else item['pitch']

def same_pitch_match(base,alternate,role,tolerance=TOLERANCE):
	a=defaultdict(list);b=defaultdict(list)
	for item in base:a[label(role,item)].append(item)
	for item in alternate:b[label(role,item)].append(item)
	matches=[]
	for key in a.keys()|b.keys():
		lhs=sorted(a[key],key=lambda e:e['startFrame'])
		rhs=sorted(b[key],key=lambda e:e['startFrame'])
		matches.extend(match_events(lhs,rhs,tolerance))
	return matches

def summarize_pair(old,new,role):
	pairs=same_pitch_match(old,new,role)
	deltas=[b['startFrame']-a['startFrame'] for a,b in pairs]
	agree=len(pairs)
	nold=len(old);nnew=len(new)
	return {
		'role':role,
		'oldEvents':nold,
		'candidateEvents':nnew,
		'samePitchWithin50ms':agree,
		'onlyOld':nold-agree,
		'onlyCandidate':nnew-agree,
		'agreementPerOld':round(agree/nold,4) if nold else None,
		'agreementPerCandidate':round(agree/nnew,4) if nnew else None,
		'medianCandidateMinusReleaseMs':round(
			float(sorted(deltas)[len(deltas)//2])*1000/RATE,2) if deltas else None,
		'labels':'model-to-model agreement ONLY, never accuracy',
	}

def audit(base,alternate):
	if base['songId']!=alternate['songId']:
		raise ValueError('score song mismatch')
	if base['quality']!='provisional-unreviewed':
		raise ValueError('baseline is not an unchanged shipped performance')
	if alternate['quality']!='experimental-candidate-unreviewed':
		raise ValueError('alternate must explicitly be experimental')
	if base['scoreHash']==alternate['scoreHash']:
		raise ValueError('candidate was not changed')
	for key in ('sampleRate','frameCount','featuredStem'):
		if base[key]!=alternate[key]:raise ValueError('score geometry mismatch')
	if base['provenance']['sourceStemSha256']!=alternate['provenance']['sourceStemSha256']:
		raise ValueError('SOURCE FINGERPRINT MISMATCH')
	if (alternate['provenance']['evidence'].get('parentScoreHash')
		!=base['scoreHash']):
		raise ValueError('candidate does not descend from this baseline')
	if alternate['events']['melody']!=base['events']['melody']:
		raise ValueError('candidate changed unchanged source melodic notes')
	durations=int(math.ceil(base['frameCount']/WINDOW))
	whole={role:summarize_pair(base['events'][role],alternate['events'][role],role)
		for role in ROLES}
	sections=[]
	for section in range(durations):
		low=section*WINDOW
		high=min(base['frameCount'],(section+1)*WINDOW)
		real_duration=(high-low)/RATE
		if real_duration<3:continue
		for role in ROLES:
			if role=='melody':continue
			prior=[e for e in base['events'][role] if low<=e['startFrame']<high]
			after=[e for e in alternate['events'][role] if low<=e['startFrame']<high]
			c=summarize_pair(prior,after,role)
			if not c['oldEvents'] and not c['candidateEvents']:continue
			disagree=c['onlyOld']+c['onlyCandidate']
			# Both excessive unmatched density and empty candidate output
			# indicate review priority, not an accuracy judgment.
			contribution=PRIORITY[role]*(disagree/max(1.,real_duration))
			density_new=c['candidateEvents']/real_duration
			density_old=c['oldEvents']/real_duration
			suspicion=round(contribution,3)
			sections.append({
				'songId':base['songId'],'song':SONG_NAMES.get(base['songId'],base['songId']),
				'role':role,'startFrame':low,'endFrame':high,
				'startSec':round(low/RATE,3),'endSec':round(high/RATE,3),
				'priorityProxy':suspicion,
				'disagreementsPerSec':round(disagree/real_duration,3),
				'candidateDensityPerSec':round(density_new,3),
				'releaseDensityPerSec':round(density_old,3),
				'releaseCount':c['oldEvents'],
				'candidateCount':c['candidateEvents'],
				'samePitchWithin50ms':c['samePitchWithin50ms'],
				'mismatchOld':c['onlyOld'],
				'mismatchCandidate':c['onlyCandidate'],
				'goldStatus':'UNVERIFIED — inspection priority only',
			})
	sections.sort(key=lambda row:(-row['priorityProxy'],row['startFrame'],row['role']))
	return {'songId':base['songId'],
		'originalHash':base['scoreHash'],'candidateHash':alternate['scoreHash'],
		'roleComparisons':whole,'priorityExcerpts':sections}

def main():
	p=argparse.ArgumentParser(description=__doc__)
	p.add_argument('--baseline',required=True,type=Path)
	p.add_argument('--candidate',required=True,type=Path)
	p.add_argument('--out',required=True,type=Path)
	p.add_argument('--top',type=int,default=20)
	a=p.parse_args()
	if a.out.exists():raise FileExistsError('Never overwrite a previous review')
	if a.top<1 or a.top>300:raise ValueError('bad top count')
	old_root=a.baseline
	new_root=a.candidate
	originals=sorted(old_root.glob('packs/*/performance.json'))
	if len(originals)!=4:raise ValueError('must compare all four shipped scores')
	items=[]
	for old_file in originals:
		folder=old_file.parent.name
		new_file=new_root/'packs'/folder/'performance-candidate-v2.json'
		audit_result=audit(read(old_file),read(new_file))
		items.append(audit_result)
		print('REAL_SONG_DIFFERENTIAL',audit_result['songId'],flush=True)
		for role,result in audit_result['roleComparisons'].items():
			print(' ',role,'old',result['oldEvents'],
				'new',result['candidateEvents'],
				'pitch-onset-agreement',result['samePitchWithin50ms'],
				'unmatched',result['onlyOld']+result['onlyCandidate'],flush=True)
	ranked=sorted([row for item in items for row in item['priorityExcerpts']],
		key=lambda row:(-row['priorityProxy'],row['songId'],row['startFrame'],row['role']))
	# Diversify the earliest six gold excerpts across songs/roles so
	# manual QA doesn't only see one song or one bad detector family.
	selected=[]
	seen=set()
	for row in ranked:
		key=(row['songId'],row['role'])
		if key in seen:continue
		selected.append(row);seen.add(key)
		if len(selected)>=min(a.top,12):break
	for row in ranked:
		if len(selected)>=a.top:break
		if row not in selected:selected.append(row)
	report={'format':'bitstream-real-music-model-disagreement-queue-v1',
		'goldStatus':'NONE — candidate AND baseline unverified',
		'comparison':'one-to-one exact pitch/hit-class and ±50ms',
		'selectionNotGold':'PRIORITY PROXY ONLY; no onset accuracy claims',
		'fourSongs':items,'proposedReviewExcerpts':selected,
		'allRankedExcerpts':ranked}
	a.out.parent.mkdir(parents=True,exist_ok=True)
	a.out.write_text(json.dumps(report,indent=2)+'\n')
	print('REVIEW_QUEUE_SAVED',a.out,'RANKED',len(ranked),
		'SELECTED',len(selected),flush=True)

if __name__=='__main__':
	main()#!/usr/bin/env python3
"""Offline-only cross-band audit of drum-family confusion, NOT real-song gold.

Each proposal uses pre/post bandpassed RMS attack evidence; labels derive
solely from synthetic fixture generation. No classifier is shipped or trained.
"""
import argparse
import hashlib
import json
from collections import defaultdict
from pathlib import Path

import numpy as np
from scipy.signal import butter, sosfiltfilt
from benchmark_drums_v4 import make_cases
from benchmark_drum_family_gate_v5 import select_families
from detector_candidate_v2 import drum_simultaneous, RATE
from detector_candidate_v4 import drum_echo_similarity_probe
from evaluate_performance_v1 import match_events

FAMILIES={'kick':(45,180),'snare':(350,3500),'hat':(4400,7500)}
SECONDS_PER_CLIP=12


def attack_bands(wave):
	"""Pre-filter once per fixture; don't touch input arrays."""
	wave=np.asarray(wave,dtype='float32')
	return {kind:sosfiltfilt(butter(4,[lo,hi],btype='bandpass',
		fs=RATE,output='sos'),wave).astype('float32')
		for kind,(lo,hi) in FAMILIES.items()}


def attack_features(bands,t):
	"""Local 12ms pre/12ms post energy increase in each family band."""
	center=round(t*RATE)
	out={}
	for kind,band in bands.items():
		left=band[max(0,center-192):max(0,center)]
		right=band[max(0,center+48):min(len(band),center+240)]
		before=float(np.sqrt(np.mean(left**2))) if len(left) else 0.
		after=float(np.sqrt(np.mean(right**2))) if len(right) else 0.
		out[kind]=max(0.,after-before)
	return out


def source_predictions(wave):
	v2,_=drum_simultaneous(wave,echo_guard='ratio-only')
	v4,_=drum_echo_similarity_probe(wave)
	return select_families(v2,v4,('v2','v4','v2'))


def classify_predictions(predicted,gold):
	"""One-to-one exact-class 20ms matching; never count near other class."""
	matched=set()
	for kind in FAMILIES:
		p=sorted(({'startFrame':round(hit['t']*48000),'id':i}
			for i,hit in enumerate(predicted) if hit['type']==kind),
			key=lambda v:(v['startFrame'],v['id']))
		g=sorted(({'startFrame':round(hit['t']*48000),'id':i}
			for i,hit in enumerate(gold) if hit['type']==kind),
			key=lambda v:(v['startFrame'],v['id']))
		matched.update(a['id'] for a,b in match_events(p,g,960))
	return matched


def audit_case(name,gold,wave,seed,cohort):
	proposals=source_predictions(wave)
	matched=classify_predictions(proposals,gold)
	bands=attack_bands(wave)
	rows=[]
	for i,hit in enumerate(proposals):
		strength=attack_features(bands,hit['t'])
		kind=hit['type']
		total=sum(strength.values())
		dominance=strength[kind]/max(1e-10,total)
		strongest=max(strength,key=strength.get)
		rows.append({'type':kind,'timeSec':hit['t'],'matchedSyntheticHit':i in matched,
			'dominance':round(dominance,6),'strongestAttackBand':strongest,
			'attackRise':{key:round(value,8) for key,value in strength.items()}})
	return {'scenario':name,'seed':seed,'cohort':cohort,
		'audioSha256':hashlib.sha256(wave.tobytes()).hexdigest(),
		'syntheticTruthCount':len(gold),'predictions':rows}


def summarize(rows):
	result={}
	for kind in FAMILIES:
		result[kind]={}
		for label in (True,False):
			vals=[hit for row in rows for hit in row['predictions']
				if hit['type']==kind and hit['matchedSyntheticHit']==label]
			fractions=sorted(hit['dominance'] for hit in vals)
			def quantile(q):
				return round(fractions[int(q*(len(fractions)-1))],4) if fractions else None
			result[kind]['matched' if label else 'falsePositive']={
				'count':len(vals),'dominanceP10':quantile(.1),
				'dominanceMedian':quantile(.5),'dominanceP90':quantile(.9),
				'strongestOwnBand':sum(hit['strongestAttackBand']==kind for hit in vals)}
	return result


def run(seeds):
	if not seeds or len(seeds)!=len(set(seeds)) or len(seeds)>12:
		raise ValueError('Require 1-12 unique synthetic seeds')
	cases=[]
	for seed in seeds:
		for name,gold,wave,cohort in make_cases(seed):
			cases.append(audit_case(name,gold,wave,seed,cohort))
			print('AUDIT',seed,name,flush=True)
	return {'format':'bitstream-cross-band-drum-diagnostic-v6',
		'status':'synthetic fixture audit ONLY; no human-reviewed labels or source gold',
		'candidate':'V5 snare-only family selector, unapproved',
		'seeds':seeds,'summary':summarize(cases),'cases':cases,
		'sourceHashes':{name:hashlib.sha256((Path(__file__).parent/name)
			.read_bytes()).hexdigest() for name in
			('detector_candidate_v2.py','detector_candidate_v4.py')},
		'approvedForAudio':False,'humanVerified':False}


def main():
	p=argparse.ArgumentParser(description=__doc__)
	p.add_argument('--out',required=True,type=Path)
	p.add_argument('--seeds',default='559103,71,337,1097')
	a=p.parse_args()
	if a.out.exists():raise FileExistsError(a.out)
	report=run([int(x) for x in a.seeds.split(',')])
	a.out.parent.mkdir(parents=True,exist_ok=True)
	a.out.write_text(json.dumps(report,indent=2)+'\n')
	print('SUMMARY',json.dumps(report['summary'],sort_keys=True),flush=True)
	print('EVIDENCE',a.out,flush=True)

if __name__=='__main__':
	main()#!/usr/bin/env python3
"""Research-only: attribute V2/V4 synthetic drum errors by class and cause.

This is *not* source-recording accuracy or a human gold corpus. Reuses the
project's one-to-one performance onset matcher with real 20/50ms gates.
Does not change scores, audio or the game; refuses to overwrite evidence.
"""
import argparse
import hashlib
import json
from collections import defaultdict
from pathlib import Path

from benchmark_drums_v4 import make_cases, fixtures
from detector_candidate_v2 import drum_simultaneous
from detector_candidate_v4 import drum_echo_similarity_probe
from evaluate_performance_v1 import match_events, metrics

FRAMES_PER_SECOND=48000
KINDS=('kick','snare','hat')
METHODS=('v2Ratio','v4Texture')
TOLERANCES=(20,50)


def aligned_error_details(predicted,gold,kind,tolerance_ms):
	"""Class-aware one-to-one matching; includes exact unmatched events."""
	to_rows=lambda events:sorted(({'startFrame':round(e['t']*FRAMES_PER_SECOND),
		'type':e['type'],'id':index} for index,e in enumerate(events)
		if e['type']==kind),key=lambda row:(row['startFrame'],row['id']))
	p=to_rows(predicted)
	g=to_rows(gold)
	pairs=match_events(p,g,tolerance_ms*FRAMES_PER_SECOND//1000)
	p_ids={a['id'] for a,b in pairs}
	g_ids={b['id'] for a,b in pairs}
	return {'metrics':metrics(pairs,len(p),len(g),12*FRAMES_PER_SECOND),
		'falsePositiveFrames':[x['startFrame'] for x in p if x['id'] not in p_ids],
		'falseNegativeFrames':[x['startFrame'] for x in g if x['id'] not in g_ids]}


def categorize_suppression(rejections,gold,tolerance_ms=20):
	"""Near synthetic truth is an observation, not causal accuracy attribution."""
	near,away=0,0
	for row in rejections:
		if not row['rejected']:
			continue
		matches=any(g['type']==row['type'] and
			abs(g['t']-row['t'])*1000<=tolerance_ms for g in gold)
		if matches:near+=1
		else:away+=1
	return {'nearKnownSyntheticHit':near,'awayFromKnownSyntheticHits':away,
		'interpretation':'proximity only, not a verified causal suppression label'}


def audit_case(name,gold,wave,seed,cohort):
	old,_=drum_simultaneous(wave,echo_guard='ratio-only')
	new,diag=drum_echo_similarity_probe(wave)
	methods={'v2Ratio':old,'v4Texture':new}
	by_method={}
	for key,events in methods.items():
		by_method[key]={str(tol)+'ms':{
			kind:aligned_error_details(events,gold,kind,tol) for kind in KINDS}
			for tol in TOLERANCES}
	return {'scenario':name,'seed':seed,'cohort':cohort,
		'audioSha256':hashlib.sha256(wave.tobytes()).hexdigest(),
		'goldEvents':len(gold),'methods':by_method,
		'v4Suppression':categorize_suppression(diag['suspects'],gold)}


def summarize(rows):
	"""Micro-score all known synthetic events; avoid averaging empty classes."""
	result={}
	for cohort in sorted({row['cohort'] for row in rows}):
		subset=[row for row in rows if row['cohort']==cohort]
		result[cohort]={}
		for tol in TOLERANCES:
			key=str(tol)+'ms'
			result[cohort][key]={}
			for method in METHODS:
				result[cohort][key][method]={}
				for kind in KINDS:
					base=[row['methods'][method][key][kind]['metrics'] for row in subset]
					tp=sum(m['truePositive'] for m in base)
					fp=sum(m['falsePositive'] for m in base)
					fn=sum(m['falseNegative'] for m in base)
					precision=tp/(tp+fp) if tp+fp else 1. if not fn else 0.
					recall=tp/(tp+fn) if tp+fn else 1.
					f1=2*precision*recall/(precision+recall) if precision+recall else 0.
					result[cohort][key][method][kind]={
						'tp':tp,'fp':fp,'fn':fn,'precision':round(precision,4),
						'recall':round(recall,4),'f1':round(f1,4)}
	return result


def run(seeds):
	if not seeds or len(set(seeds))!=len(seeds) or len(seeds)>12:
		raise ValueError('Require 1–12 distinct seeds')
	rows=[]
	for seed in seeds:
		for name,gold,wave,cohort in make_cases(seed):
			rows.append(audit_case(name,gold,wave,seed,cohort))
			print('AUDITED',seed,name,flush=True)
	return {'format':'bitstream-drum-v4-synthetic-error-attribution-v1',
		'status':'SYNTHETIC ONLY; not human-verified source gold; not playable',
		'seeds':seeds,'methodSourceHashes':{
			'v2':hashlib.sha256((Path(__file__).parent/'detector_candidate_v2.py')
				.read_bytes()).hexdigest(),
			'v4':hashlib.sha256((Path(__file__).parent/'detector_candidate_v4.py')
				.read_bytes()).hexdigest()},
		'summaryMicroByClass':summarize(rows),'cases':rows,
		'approvedForAudio':False,'humanVerified':False}


def main():
	p=argparse.ArgumentParser(description=__doc__)
	p.add_argument('--out',required=True,type=Path)
	p.add_argument('--seeds',default='559103,71,337,1097')
	a=p.parse_args()
	if a.out.exists():
		raise FileExistsError(a.out)
	report=run([int(s) for s in a.seeds.split(',')])
	a.out.parent.mkdir(parents=True,exist_ok=True)
	a.out.write_text(json.dumps(report,indent=2)+'\n')
	print('MICRO_F1_SYNTHETIC',json.dumps(report['summaryMicroByClass'],
		sort_keys=True),flush=True)
	print('EVIDENCE',a.out,flush=True)

if __name__=='__main__':
	main()#!/usr/bin/env python3
"""Read-only source-FLAC drum audit: V5/V6 versus release UNLABELED events.

Runs ffmpeg inside CT211 through its authorized Proxmox host, streams only
short 16kHz mono float PCM windows, and checks FULL source SHA-256 first.
No source is modified, no media copied to repo, no scores treated as gold.
"""
import argparse
import hashlib
import json
import math
import shlex
import subprocess
from collections import Counter, defaultdict
from pathlib import Path

import numpy as np
from audit_cross_band_v6 import source_predictions
from detector_candidate_v6 import cross_band_veto
from evaluate_performance_v1 import match_events

SOURCE_PATHS={
	'FEsxYVStla4':'/root/bitstream-maxi/launch33/stems/htdemucs_6s/01_FEsxYVStla4/drums.flac',
	'WRBGQUqD54U':'/root/bitstream-maxi/launch33/stems/htdemucs_6s/03_WRBGQUqD54U/drums.flac',
	'FYImnz5-hXs':'/root/bitstream-maxi/launch33/stems/htdemucs_6s/31_FYImnz5-hXs/drums.flac',
	'local-one-more-run-bitstream-bluffs':'/root/bitstream-maxi/launch33/stems/grouped_6s/33_one_more_run/drums.flac',
}
RATE=48000
KINDS=('kick','snare','hat')
STATUS='real source audio but NO human gold; disagreements are NOT confirmed errors'

def proxmox(args,timeout=90):
	command=['ssh','-F','/dev/null','-T','-o','BatchMode=yes',
		'-o','ConnectTimeout=7','root@ursa-major',
		shlex.join(['pct','exec','211','--',*args])]
	return subprocess.run(command,stdout=subprocess.PIPE,stderr=subprocess.PIPE,
		check=True,timeout=timeout)


def verify_master(song,score):
	if song not in SOURCE_PATHS:raise ValueError('Unknown approved source stem')
	if score['songId']!=song or score.get('quality')!='provisional-unreviewed':
		raise ValueError('Wrong or nonprovisional source score')
	expected=score['provenance']['sourceStemSha256']['drums']
	actual=proxmox(['sha256sum',SOURCE_PATHS[song]],timeout=90).stdout
	decoded=actual.decode('ascii').strip().split()
	if len(decoded)!=2 or decoded[0]!=expected or decoded[1]!=SOURCE_PATHS[song]:
		raise ValueError('Source stem hash/path mismatch: '+song)
	return expected


def read_pcm(song,start_frame,end_frame):
	if not 0<=start_frame<end_frame or end_frame-start_frame>RATE*20:
		raise ValueError('Window must be positive and at most 20s')
	start=start_frame/RATE
	duration=(end_frame-start_frame)/RATE
	cmd=['ffmpeg','-nostdin','-hide_banner','-loglevel','error',
		'-ss',format(start,'.8f'),'-i',SOURCE_PATHS[song],
		'-t',format(duration,'.8f'),'-ac','1','-ar','16000',
		'-f','f32le','pipe:1']
	pcm=proxmox(cmd).stdout
	if len(pcm)%4:raise ValueError('Invalid remote PCM alignment')
	wave=np.frombuffer(pcm,dtype='<f4').copy()
	expected=duration*16000
	if abs(len(wave)-expected)>320 or not np.all(np.isfinite(wave)):
		raise ValueError('Short or non-finite remote PCM')
	return wave

def event_rows(events,start_frame,release=False):
	if release:
		return sorted(({'startFrame':int(e['startFrame']),'type':e['class']}
			for e in events),key=lambda e:(e['startFrame'],e['type']))
	return sorted(({'startFrame':start_frame+round(e['t']*RATE),
		'type':e['type']} for e in events),
		key=lambda e:(e['startFrame'],e['type']))


def compare_to_release(candidate,baseline,tolerance_ms):
	counts={}
	for kind in KINDS:
		c=sorted((e for e in candidate if e['type']==kind),
			key=lambda e:e['startFrame'])
		b=sorted((e for e in baseline if e['type']==kind),
			key=lambda e:e['startFrame'])
		pairs=match_events(c,b,round(tolerance_ms*RATE/1000))
		counts[kind]={'releaseCount':len(b),'candidateCount':len(c),
			'pairedWithRelease':len(pairs),
			'candidateUnpairedWithRelease':len(c)-len(pairs),
			'releaseUnpairedWithCandidate':len(b)-len(pairs)}
	return counts


def count_by_family(events):
	c=Counter(e['type'] for e in events)
	return {k:c[k] for k in KINDS}


def clip_audit(song,score,queue_row,window_label,source_hash):
	start=queue_row['startFrame']
	end=queue_row['endFrame']
	wave=read_pcm(song,start,end)
	v5=source_predictions(wave)
	v6,details=cross_band_veto(wave)
	release=[e for e in score['events']['drums'] if
		start<=e['startFrame']<end and e['class'] in KINDS]
	v5rows=event_rows(v5,start)
	v6rows=event_rows(v6,start)
	releaserows=event_rows(release,start,True)
	v5set=Counter((e['startFrame'],e['type']) for e in v5rows)
	v6set=Counter((e['startFrame'],e['type']) for e in v6rows)
	if v6set-v5set:raise ValueError('V6 added events outside V5 proposals')
	return {'song':song,'window':window_label,
		'startFrame':start,'endFrame':end,'sourceStemSha256':source_hash,
		'decodedPcmSha256':hashlib.sha256(wave.tobytes()).hexdigest(),
		'decodedPcmSamples16k':len(wave),'originalReleaseScoreHash':score['scoreHash'],
		'status':STATUS,'releaseCounts':count_by_family(releaserows),
		'v5Counts':count_by_family(v5rows),
		'v6Counts':count_by_family(v6rows),
		'v6RejectedCounts':details['removed'],
		'v6Retention':len(v6rows)/len(v5rows) if v5rows else None,
		'releaseComparisonsNotGold':{
			str(tol)+'ms':{
				'v5':compare_to_release(v5rows,releaserows,tol),
				'v6':compare_to_release(v6rows,releaserows,tol)}
			for tol in (20,50)}}

def main():
	parser=argparse.ArgumentParser(description=__doc__)
	parser.add_argument('--score-root',type=Path,default=Path('public/music/packs'))
	parser.add_argument('--out',type=Path,required=True)
	parser.add_argument('--include-fixed-windows',action='store_true')
	args=parser.parse_args()
	if args.out.exists():raise FileExistsError(args.out)
	scores={}
	queues={}
	sources={}
	# Fail closed on ANY master mismatch BEFORE producing candidate predictions.
	for package in sorted(args.score_root.glob('*/performance.json')):
		score=json.loads(package.read_text())
		song=score['songId']
		if song not in SOURCE_PATHS:continue
		queue=json.loads((package.parent/'review-queue-v1.json').read_text())
		if queue['songId']!=song or queue['baselineScoreHash']!=score['scoreHash'] or (
			queue['status']!='machine-ranked-disagreement-not-human-verified'):
			raise ValueError('Review queue does not match frozen source score: '+song)
		sources[song]=verify_master(song,score)
		scores[song]=score
		queues[song]=queue
	if set(scores)!=set(SOURCE_PATHS):
		raise ValueError('All four source-song packages must be verified')
	rows=[]
	for song in sorted(scores):
		score=scores[song]
		windows=[(x['id'],x) for x in queues[song]['excerpts']
			if x['role']=='drums']
		if args.include_fixed_windows:
			for start in (14,75):
				a=start*RATE
				b=min(a+8*RATE,score['frameCount'])
				windows.append((f'fixed-{start}s',{'startFrame':a,'endFrame':b}))
		for name,item in windows:
			if not 0<=item['startFrame']<item['endFrame']<=score['frameCount']:
				raise ValueError('Invalid source review excerpt bounds')
			row=clip_audit(song,score,item,name,sources[song])
			rows.append(row)
			print('REAL_SOURCE_UNLABELED',song,name,'released',row['releaseCounts'],
				'v5',row['v5Counts'],'v6',row['v6Counts'],flush=True)

	report={'format':'bitstream-v6-real-source-unlabeled-differential-v1',
		'status':STATUS,'humanVerified':False,'approvedForAudio':False,
		'readOnly':True,'sourceNode':'CT211 via Ursa Major pct exec',
		'fullSourceStemHashes':sources,
		'scoreSourceHashes':{song:score['scoreHash'] for song,score in scores.items()},
		'detectorCodeHashes':{n:hashlib.sha256((Path(__file__).parent/n).read_bytes())
			.hexdigest() for n in ('detector_candidate_v2.py',
				'detector_candidate_v4.py','detector_candidate_v6.py')},
		'windows':rows}
	args.out.parent.mkdir(parents=True,exist_ok=True)
	args.out.write_text(json.dumps(report,indent=2)+'\n')
	print('COMPLETED',len(rows),'real FLAC windows, NO accuracy claims',flush=True)
	print('EVIDENCE',args.out,flush=True)


