"""Differential *synthetic* benchmark, NOT evidence for musical gold accuracy.

Runs untouched release v1 vs new unapproved candidate v2 on equally known
sample-exact note events. Reverb, dense repeated attacks, low MIDI pitches,
and simultaneous chord attacks challenge old FFT-bin/onset methods.
Save metrics *including failures*: no cherry-picked single perfect example.
"""
import argparse
import hashlib
import json
import math
from pathlib import Path

import numpy as np
from scipy.signal import butter,sosfilt
from evaluate_performance_v1 import match_events,metrics
from render_full_dynamic_orchestra_v1 import choose_feature_events
from detector_candidate_v2 import accompaniment,source_onsets

RATE=16000
GROUND_SEED=2473
NOTE_DURATION=.265
TRACK_SECONDS=12

def generate(plucked,echo=False):
	"""Independent time-domain harmonic synth with no shared detector code."""
	rng=np.random.default_rng(GROUND_SEED)
	n=RATE*TRACK_SECONDS
	y=np.zeros(n,dtype=np.float64)
	for i,item in enumerate(plucked):
		origin=int(round(item['start']*RATE))
		end=min(n,origin+round(NOTE_DURATION*RATE))
		nframes=end-origin
		if nframes<=0:continue
		t=np.arange(nframes)/RATE
		f=440.0*2**((item['midi']-69)/12)
		# Mixed inharmonic attack and realistic harmonic envelopes:
		# fundamental sometimes weaker than third harmonic.
		signal=np.zeros(nframes)
		for harmonic in range(1,6):
			a=(.25 if harmonic==1 and i%3==0 else .95)/harmonic**1.0
			signal+=a*np.sin(2*np.pi*f*harmonic*t+
				(harmonic*.23+i*.11))
		env=(1-np.exp(-t/.0045))*np.exp(-t/.095)
		signal*=env*(.07 if i%4 else .11)
		signal+=rng.standard_normal(nframes)*np.exp(-t/.002)*.009
		y[origin:end]+=signal
	if echo:
		delay1=int(round(.075*RATE))
		delay2=int(round(.142*RATE))
		old=y.copy()
		y[delay1:]+=old[:-delay1]*.42
		y[delay2:]+=old[:-delay2]*.22
	y+=rng.standard_normal(n)*.00002
	return np.asarray(y,dtype='float32')

def fixture(name):
	if name=='chromatic-low':
		# Includes each of 8 release v1 *unreachable* low semitones.
		pitches=[41,43,44,46,48,50,52,55,41,43,44,46,48,50,52,55,
			58,60,63,66,69,72,75,79]
		events=[{'start':.4+i*.37,'midi':p}
			for i,p in enumerate(pitches)]
		return events,False
	if name=='repeated-eighths':
		# Re-struck identical pitch at 125ms; 9 groups of 4 notes.
		# 96 repetitions before old v1 grouped them into 12 events.
		events=[{'start':.35+i*.125,'midi':41+((i//4)%9)*3}
			for i in range(88)]
		return events,False
	if name=='plucks-with-echoes':
		pitches=[48,53,58,64,55,60,52,67,57,62,50,65,53,59,61,68,
			48,53,58,64,55,60,52,67,57,62,50,65]
		events=[{'start':.42+i*.36,'midi':p}
			for i,p in enumerate(pitches)]
		return events,True
	if name=='two-note-chords':
		pitches=[(48,55),(50,57),(53,60),(55,62),(57,64),(60,67),
			(48,60),(52,64),(55,67),(57,69),(53,65),(48,60),
			(50,62),(55,67),(57,69),(60,72),(59,71),(57,69)]
		events=[{'start':.35+i*.55,'midi':pitch}
			for i,duo in enumerate(pitches) for pitch in duo]
		return events,False
	raise ValueError(name)

def compare(predicted,gold,total_seconds,window_ms):
	pmap, gmap={},{}
	for e in predicted:pmap.setdefault(e['midi'],[]).append({
		'startFrame':round(e['start']*48000)})
	for e in gold:gmap.setdefault(e['midi'],[]).append({
		'startFrame':round(e['start']*48000)})
	pairs=[]
	for pitch in pmap.keys()|gmap.keys():
		pairs.extend(match_events(sorted(pmap.get(pitch,[]),
			key=lambda v:v['startFrame']),
			sorted(gmap.get(pitch,[]),key=lambda v:v['startFrame']),
			round(window_ms*48)))
	return metrics(pairs,len(predicted),len(gold),round(total_seconds*48000))

def run():
	report={'format':'bitstream-synthetic-detector-differential-v1',
		'seed':GROUND_SEED,'rate':RATE,
		'groundTruth':'sample-exact synthetic generation only; NOT artist human gold',
		'candidateStatus':'research-only-do-not-promote',
		'tests':[]}
	for name in ('chromatic-low','repeated-eighths',
		'plucks-with-echoes','two-note-chords'):
		ground,echo=fixture(name)
		y=generate(ground,echo=echo)
		old,old_stats=choose_feature_events(y)
		new,new_stats=accompaniment(y)
		old20=compare(old,ground,TRACK_SECONDS,20)
		old50=compare(old,ground,TRACK_SECONDS,50)
		new20=compare(new,ground,TRACK_SECONDS,20)
		new50=compare(new,ground,TRACK_SECONDS,50)
		item={'fixture':name,'events':len(ground),'audioSha256':hashlib.sha256(
			y.tobytes()).hexdigest(),'baseline':{'20ms':old20,'50ms':old50},
			'candidate':{'20ms':new20,'50ms':new50},
			'baselineStats':old_stats,'candidateStats':new_stats}
		report['tests'].append(item)
		print(name,'gold',len(ground),
			'baseEvents',len(old),'candidateEvents',len(new),
			'old20',old20['f1'],'new20',new20['f1'],
			'old50',old50['f1'],'new50',new50['f1'],
			'bias20',(old20['signedBiasMs'],new20['signedBiasMs']),
			flush=True)
		report.setdefault('results',[]).append({
			'name':name,
			'oldF1At20ms':old20['f1'],
			'newF1At20ms':new20['f1'],
			'oldPrecisionAt20ms':old20['precision'],
			'newPrecisionAt20ms':new20['precision'],
			'oldRecallAt20ms':old20['recall'],
			'newRecallAt20ms':new20['recall'],
			'oldBiasMs':old20['signedBiasMs'],
			'newBiasMs':new20['signedBiasMs']})
	return report

if __name__=='__main__':
	p=argparse.ArgumentParser(description=__doc__)
	p.add_argument('--out',type=Path,required=True)
	args=p.parse_args()
	if args.out.exists():raise FileExistsError(args.out)
	report=run()
	args.out.parent.mkdir(parents=True,exist_ok=True)
	args.out.write_text(json.dumps(report,indent=2)+'\n')
	print('SYNTHETIC_DIFFERENTIAL_REPORT_CREATED',args.out)#!/usr/bin/env python3
"""V5 research-only classwise V2/V4 selectors; never playable music.

The family recipes are fixed before the alternate-seed validation. Synthetic
holdouts test stability, NOT real-song quality or an independent gold corpus.
"""
import argparse
import hashlib
import json
from pathlib import Path

from benchmark_drums_v4 import make_cases, fixtures
from detector_candidate_v2 import drum_simultaneous
from detector_candidate_v4 import drum_echo_similarity_probe

FAMILIES=('kick','snare','hat')
RECIPES={
	'v2Ratio':('v2','v2','v2'),
	'v4Texture':('v4','v4','v4'),
	'v5SnareOnly':('v2','v4','v2'),
	'v5SnareKick':('v4','v4','v2'),
	'v5SnareHat':('v2','v4','v4'),
	'v5KickOnly':('v4','v2','v2'),
}
DEFAULT_DEVELOPMENT=(559103,71,337,1097)
DEFAULT_VALIDATION=(17,41,809,2027)


def select_families(v2,v4,recipe):
	"""Select candidate event families without modifying either input."""
	if len(recipe)!=len(FAMILIES) or any(s not in ('v2','v4') for s in recipe):
		raise ValueError('Invalid class selector recipe')
	if any(x.get('type') not in FAMILIES for x in [*v2,*v4]):
		raise ValueError('Unrecognized synthetic drum family')
	out=[dict(event) for family,source in zip(FAMILIES,recipe)
		for event in (v2 if source=='v2' else v4)
		if event['type']==family]
	return sorted(out,key=lambda e:(e['t'],e['type']))


def test_case(name,gold,wave,seed,cohort):
	v2,_=drum_simultaneous(wave,echo_guard='ratio-only')
	v4,_=drum_echo_similarity_probe(wave)
	method_results={}
	for label,recipe in RECIPES.items():
		selected=select_families(v2,v4,recipe)
		method_results[label]={str(tol)+'ms':fixtures.compare(selected,gold,tol)
			for tol in (20,50)}
	return {'scenario':name,'seed':seed,'cohort':cohort,
		'audioSha256':hashlib.sha256(wave.tobytes()).hexdigest(),
		'goldCountSynthetic':len(gold),'metrics':method_results}


def summarize(rows):
	report={}
	for cohort in sorted({row['cohort'] for row in rows}):
		selected=[row for row in rows if row['cohort']==cohort]
		report[cohort]={}
		for tol in (20,50):
			key=str(tol)+'ms'
			report[cohort][key]={name:{
				'macroF1':round(sum(row['metrics'][name][key]['f1']
					for row in selected)/len(selected),4),
				'falsePositive':sum(row['metrics'][name][key]['falsePositive']
					for row in selected),
				'falseNegative':sum(row['metrics'][name][key]['falseNegative']
					for row in selected)} for name in RECIPES}
	return report


def run(development=DEFAULT_DEVELOPMENT,validation=DEFAULT_VALIDATION):
	if not development or not validation or len(set((*development,*validation)))!=len(development)+len(validation):
		raise ValueError('Development and validation seeds must be distinct')
	if len(development)>12 or len(validation)>12:
		raise ValueError('At most twelve seeds per split')
	output={}
	for split,seeds in (('development',development),('alternate-seed-validation',validation)):
		rows=[]
		for seed in seeds:
			for name,gold,wave,cohort in make_cases(seed):
				rows.append(test_case(name,gold,wave,seed,cohort))
				print(split,seed,name,flush=True)
		output[split]={'seeds':list(seeds),'summary':summarize(rows),
			'cases':rows}
	return {'format':'bitstream-synthetic-drum-family-gating-research-v5',
		'status':'SYNTHETIC RESEARCH ONLY; not gold; not for playback',
		'recipes':{name:dict(zip(FAMILIES,recipe))
			for name,recipe in RECIPES.items()},
		'sourceSha256':{name:hashlib.sha256((Path(__file__).parent/name)
			.read_bytes()).hexdigest() for name in
			('detector_candidate_v2.py','detector_candidate_v4.py')},
		'splits':output,'humanVerified':False,'approvedForPlayback':False}


def main():
	p=argparse.ArgumentParser(description=__doc__)
	p.add_argument('--out',required=True,type=Path)
	a=p.parse_args()
	if a.out.exists():
		raise FileExistsError(a.out)
	result=run()
	a.out.parent.mkdir(parents=True,exist_ok=True)
	a.out.write_text(json.dumps(result,indent=2)+'\n')
	for split,data in result['splits'].items():
		print('SUMMARY',split,json.dumps(data['summary'],sort_keys=True),flush=True)
	print('EVIDENCE',a.out,flush=True)

if __name__=='__main__':
	main()#!/usr/bin/env python3
"""Simultaneous kick/snare/hat gold-synthetic probes (never artist gold)."""
import argparse
import hashlib
import json
import math
from pathlib import Path

import numpy as np
from scipy.signal import butter,sosfiltfilt
from evaluate_performance_v1 import match_events,metrics
from render_full_dynamic_orchestra_v1 import choose_drum_events
from detector_candidate_v2 import drum_simultaneous

RATE=16000
LENGTH=12
SEED=559103

def hits(case):
	if case=='cohits':
		# Kick+snare simultaneous on some beats; hats on subdivisions.
		return sorted(
			[{'t':round(.4+i*.42,4),'type':'kick'}
				for i in range(26)] +
			[{'t':round(.4+i*.84,4),'type':'snare'}
				for i in range(13)] +
			[{'t':round(.4+i*.21,4),'type':'hat'}
				for i in range(52)],key=lambda e:e['t'])
	if case=='isolated':
		return sorted([{'t':.4+i*.34,'type':('kick','snare','hat')[i%3]}
			for i in range(32)],key=lambda e:e['t'])
	if case=='hats-roll':
		return sorted(
			[{'t':round(.4+i*.07,4),'type':'hat'} for i in range(150)] +
			[{'t':round(.4+i*.56,4),'type':'kick'} for i in range(19)] +
			[{'t':round(.68+i*.56,4),'type':'snare'} for i in range(19)],
			key=lambda e:e['t'])
	if case=='echoed-cohits':
		return hits('cohits')
	raise ValueError(case)

def synth(notes,echo=False):
	rng=np.random.default_rng(SEED)
	y=np.zeros(LENGTH*RATE,dtype='float64')
	for i,event in enumerate(notes):
		t=event['t']
		start=round(t*RATE)
		dur={'kick':.165,'snare':.14,'hat':.067}[event['type']]
		length=min(round(dur*RATE),len(y)-start)
		if length<=0:continue
		time=np.arange(length)/RATE
		if event['type']=='kick':
			f=72*np.exp(-time/.05)+49
			tone=np.sin(np.cumsum(2*np.pi*f/RATE))
			s=tone*np.exp(-time/.045)*.21
			s+=rng.standard_normal(length)*np.exp(-time/.002)*.008
		elif event['type']=='snare':
			noise=rng.standard_normal(length)
			sos=butter(4,[500,3200],fs=RATE,btype='bandpass',output='sos')
			s=sosfiltfilt(sos,noise)*np.exp(-time/.035)*.15
		else:
			noise=rng.standard_normal(length)
			sos=butter(4,[4700,7600],fs=RATE,btype='bandpass',output='sos')
			s=sosfiltfilt(sos,noise)*np.exp(-time/.016)*.16
		s*=np.minimum(1,time/.0018)
		# Optional independently struck ghost-note velocity; default
		# remains byte-identical to the original four synthetic fixtures.
		velocity=event.get('velocity',1.)
		if not 0<velocity<=1.5:raise ValueError('invalid synthetic velocity')
		y[start:start+length]+=s*velocity
	if echo:
		prev=y.copy()
		for delay,amount in ((.080,.34),(.15,.18)):
			offset=round(delay*RATE)
			y[offset:]+=prev[:-offset]*amount
	y+=rng.standard_normal(len(y))*.000015
	return y.astype('float32')

def compare(pred,gold,tol):
	predmap,goldmap={},{}
	for row in pred:
		predmap.setdefault(row['type'],[]).append({
			'startFrame':round(row['t']*48000)})
	for row in gold:
		goldmap.setdefault(row['type'],[]).append({
			'startFrame':round(row['t']*48000)})
	pairs=[]
	for kind in predmap.keys()|goldmap.keys():
		a=sorted(predmap.get(kind,[]),key=lambda x:x['startFrame'])
		b=sorted(goldmap.get(kind,[]),key=lambda x:x['startFrame'])
		pairs.extend(match_events(a,b,round(tol*48)))
	return metrics(pairs,len(pred),len(gold),LENGTH*48000)

def run():
	d={'format':'bitstream-drums-synthetic-differential-v1',
		'seed':SEED,'goldStatus':'synthetic only not human',
		'passages':[],'candidateReleaseApproved':False}
	for case in ('isolated','cohits','hats-roll','echoed-cohits'):
		ground=hits(case)
		y=synth(ground,echo=case=='echoed-cohits')
		old,os=choose_drum_events(y)
		new,ns=drum_simultaneous(y)
		v1=compare(old,ground,20)
		v2=compare(new,ground,20)
		item={'scenario':case,'audioSha256':hashlib.sha256(y.tobytes()).hexdigest(),
			'ground':len(ground),'baselineCount':len(old),'candidateCount':len(new),
			'baseline':{'20ms':v1,'50ms':compare(old,ground,50)},
			'candidate':{'20ms':v2,'50ms':compare(new,ground,50)},
			'baselineDiagnostics':os,'candidateDiagnostics':ns}
		d['passages'].append(item)
		print(case,'GOLD',len(ground),'OLD',len(old),'NEW',len(new),
			'oldF1',v1['f1'],'newF1',v2['f1'],
			'oldTP',v1['truePositive'],'newTP',v2['truePositive'],
			'newBias',v2['signedBiasMs'],flush=True)
	return d

if __name__=='__main__':
	p=argparse.ArgumentParser(description=__doc__)
	p.add_argument('--out',type=Path,required=True)
	a=p.parse_args()
	if a.out.exists():raise FileExistsError(a.out)
	report=run()
	a.out.parent.mkdir(parents=True,exist_ok=True)
	a.out.write_text(json.dumps(report,indent=2)+'\n')
	print('SYNTHETIC_DRUMS_RESULTS',a.out)#!/usr/bin/env python3
"""Controlled comparison of independent drum streams and anchored fusion.

Never mistake these generated notes for real-song human gold. Includes all
adversarial quiet/echo cases, and reports BOTH event F1 and absolute counts.
"""
import argparse
import hashlib
import json
from pathlib import Path

from benchmark_drums_candidate_v2 import hits, synth, compare
from stress_detector_candidate_v2 import drum_fixture, scaled_drum_audio
from render_full_dynamic_orchestra_v1 import choose_drum_events
from detector_candidate_v2 import drum_simultaneous
from detector_candidate_v3 import drum_anchor_fusion


def run():
	scenarios=[]
	for name in ('isolated','cohits','hats-roll','echoed-cohits'):
		gold=hits(name)
		scenarios.append((name,gold,synth(gold,echo=name=='echoed-cohits')))
	for name in ('quiet-ghost-snare-120ms','quiet-ghost-kick-120ms',
		'real-snare-double-80ms','real-snare-double-155ms',
		'original-snare-echo-80ms'):
		gold,echo=drum_fixture(name)
		gold.sort(key=lambda item:item['t'])
		scenarios.append((name,gold,scaled_drum_audio(gold,echo)))
	results=[]
	for name,gold,wave in scenarios:
		original,_=choose_drum_events(wave)
		ratio,_=drum_simultaneous(wave,echo_guard='ratio-only')
		uncut,_=drum_simultaneous(wave,echo_guard='none')
		fused0,_=drum_anchor_fusion(wave,candidate_echo_guard='none')
		fused1,_=drum_anchor_fusion(wave,candidate_echo_guard='ratio-only')
		metrics={
			'baseline':compare(original,gold,20),
			'v2Ratio':compare(ratio,gold,20),
			'v2None':compare(uncut,gold,20),
			'v3AnchorNone':compare(fused0,gold,20),
			'v3AnchorRatio':compare(fused1,gold,20)}
		results.append({'scenario':name,'gold':len(gold),
			'audioSha256':hashlib.sha256(wave.tobytes()).hexdigest(),
			'metrics':metrics})
		print(name,'gold',len(gold), ' '.join(
			k+'='+str(round(v['f1'],3))+'('+str(v['falsePositive'])+
			'fp,'+str(v['falseNegative'])+'fn)'
			for k,v in metrics.items()),flush=True)
	return {'format':'bitstream-drums-fusion-synthetic-research-v1',
		'status':'synthetic only; not source gold; no release approval',
		'results':results,
		'summary':{key:round(sum(x['metrics'][key]['f1'] for x in results)/
			len(results),4) for key in
			('baseline','v2Ratio','v2None','v3AnchorNone','v3AnchorRatio')}}

if __name__=='__main__':
	p=argparse.ArgumentParser()
	p.add_argument('--out',type=Path,required=True)
	args=p.parse_args()
	if args.out.exists():raise FileExistsError(args.out)
	report=run()
	args.out.parent.mkdir(parents=True,exist_ok=True)
	args.out.write_text(json.dumps(report,indent=2)+'\n')
	print('MACRO_F1_BY_CASE_SYNTHETIC_NOT_REAL',report['summary'],flush=True)#!/usr/bin/env python3
"""Unapproved drum V4 echo-texture probe vs released/V2 on held-out SYNTH.

No real song labels or owner listening; metrics cannot authorize audio changes.
Standalone checkout may lack private biome synth used only by rendering,
so substitute its static BIOMES attribute while importing fixture utilities.
"""
import argparse
import hashlib
import json
import sys
import types
from pathlib import Path
import numpy as np

try:
	import render_biome_orchestras_v2
except ModuleNotFoundError as error:
	if error.name != 'render_biome_orchestras_v2':
		raise
	sys.modules['render_biome_orchestras_v2'] = types.SimpleNamespace(BIOMES=())

import benchmark_drums_candidate_v2 as fixtures
from stress_detector_candidate_v2 import drum_fixture
from detector_candidate_v2 import drum_simultaneous
from detector_candidate_v4 import drum_echo_similarity_probe
from render_full_dynamic_orchestra_v1 import choose_drum_events

ORIGINAL=('isolated', 'cohits', 'hats-roll', 'echoed-cohits',
	'quiet-ghost-snare-120ms', 'quiet-ghost-kick-120ms',
	'real-snare-double-80ms', 'real-snare-double-155ms',
	'original-snare-echo-80ms')


def make_cases(seed):
	fixtures.SEED=seed
	for name in ORIGINAL:
		if name in ('isolated','cohits','hats-roll','echoed-cohits'):
			gold=fixtures.hits(name)
			wave=fixtures.synth(gold,echo=name=='echoed-cohits')
		else:
			gold, echo=drum_fixture(name)
			gold.sort(key=lambda item:item['t'])
			wave=fixtures.synth(gold,echo=echo)
		yield name,gold,wave,'original fixture family'

	for stem,delay,velocity in (('snare',.095,.26),('kick',.145,.27)):
		name='quiet-ghost-'+stem+'-'+str(round(delay*1000))+'ms-holdout'
		base,_=drum_fixture('quiet-ghost-'+stem+'-120ms')
		gold=[]
		for item in base:
			item=item.copy()
			if item['velocity']<1:
				item['t']=round(item['t']+delay-.120,4)
				item['velocity']=velocity
			gold.append(item)
		gold.sort(key=lambda item:item['t'])
		yield name,gold,fixtures.synth(gold,echo=False),'withheld ghost offset'
	for stem,delay,amount in (('cohits',.11,.37),('snare',.065,.29)):
		name='echo-'+stem+'-'+str(round(delay*1000))+'ms-holdout'
		gold=fixtures.hits('cohits') if stem=='cohits' else \
			drum_fixture('original-snare-echo-80ms')[0]
		gold.sort(key=lambda item:item['t'])
		wave=fixtures.synth(gold,echo=False)
		shift=round(delay*fixtures.RATE)
		original=wave.copy()
		wave[shift:]+=original[:-shift]*amount
		yield name,gold,wave,'withheld echo offset'


def test_case(name,gold,wave,seed,cohort):
	methods={
		'releaseV1':choose_drum_events(wave)[0],
		'v2Ratio':drum_simultaneous(wave,echo_guard='ratio-only')[0],
		'v2None':drum_simultaneous(wave,echo_guard='none')[0],
		'v4Texture':drum_echo_similarity_probe(wave)[0],
	}
	metrics={method:fixtures.compare(events,gold,20) for method,events in
		methods.items()}
	return {'scenario':name,'seed':seed,'cohort':cohort,
		'audioSha256':hashlib.sha256(wave.tobytes()).hexdigest(),
		'goldCount':len(gold),'metrics':metrics}

def main():
	p=argparse.ArgumentParser(description=__doc__)
	p.add_argument('--out',required=True,type=Path)
	p.add_argument('--seeds',default='559103,71,337,1097')
	a=p.parse_args()
	if a.out.exists():
		raise FileExistsError(a.out)
	seeds=[int(item) for item in a.seeds.split(',')]
	if len(seeds)!=len(set(seeds)) or not 1<=len(seeds)<=12:
		raise ValueError('Need 1-12 unique synthetic seeds')
	results=[]
	for seed in seeds:
		for name,gold,wave,cohort in make_cases(seed):
			item=test_case(name,gold,wave,seed,cohort)
			results.append(item)
			print(seed,name,'V2',round(item['metrics']['v2Ratio']['f1'],3),
				'V4',round(item['metrics']['v4Texture']['f1'],3),flush=True)
	summary={}
	for cohort in sorted(set(row['cohort'] for row in results)):
		rows=[row for row in results if row['cohort']==cohort]
		summary[cohort]={key:round(sum(row['metrics'][key]['f1'] for row
			in rows)/len(rows),4) for key in results[0]['metrics']}
	source=Path(__file__)
	report={'format':'bitstream-drum-v4-synthetic-blind-probe-v1',
		'status':'SYNTHETIC ONLY; not validated on real music; NOT FOR PLAYBACK',
		'candidateSourceSha256':hashlib.sha256(
			(source.parent/'detector_candidate_v4.py').read_bytes()).hexdigest(),
		'seeds':seeds,'summaryMacroF1':summary,'results':results,
		'approvedForPlayback':False,'goldIsHumanVerified':False}
	a.out.parent.mkdir(parents=True,exist_ok=True)
	a.out.write_text(json.dumps(report,indent=2)+'\n')
	print('SYNTHETIC_MACRO_ONLY',summary,flush=True)
	print('EVIDENCE',a.out,flush=True)

if __name__=='__main__':
	main()<!doctype html>
