<label for="danger">Real BSOD proximity (music-only): <strong id="danger-value" class="out">0%</strong></label>
<input type="range" id="danger" min="0" max="100" step="1" value="0">
<div class="controls">
<button id="play" class="primary" type="button">Play passage</button>
<button id="clean" type="button">A: Clean</button>
<button id="threat" type="button">B: Near BSOD</button>
<button id="stop" type="button">Stop</button>
</div><p id="status" role="status">Select a song and press Play. Browser audio begins after your click.</p>
</div>
<p class="warning"><strong>Scope:</strong> This is a <strong>sound-design audition</strong>, not the game’s timing/transcription validator. It uses actual shipped Ogg stems and the same BSOD threat processor, but a simplified loop mix (not the full gameplay EQ, atmosphere, adaptive orchestration, SFX, or six-stem master graph). A good sound here must still pass real-engine testing and human listening.</p>
<p>Nothing here saves settings, spends shards, changes game files, or touches Control Friday’s playtesting build. Keep your volume reasonable before pressing Play.</p>
<script type="module">
import {createBsodThreatProcessor} from '/src/systems/music/BsodThreatProcessor.js';
const byId=id=>document.getElementById(id);
const song=byId('song'),passage=byId('passage'),melody=byId('melody'),
 danger=byId('danger'),dangerText=byId('danger-value'),status=byId('status');
const play=byId('play'),stop=byId('stop');
let ctx=null,master=null,token=0,running=[],processors=[],pack=null,base=null;
const setStatus=s=>{status.textContent=s};
const catalogUrl=new URL('/public/music/catalog.json',location.href);
const response=await fetch(catalogUrl);
if(!response.ok)throw Error('Music catalog unavailable');
const catalog=await response.json();
const order=[...catalog.tracks].sort((a,b)=>Number(b.id==='local-one-more-run-bitstream-bluffs')-Number(a.id==='local-one-more-run-bitstream-bluffs'));
for(const item of order) song.add(new Option(item.title,item.id));
function resetAudio(){
	token++;
	for(const node of running){try{node.stop()}catch{}try{node.disconnect()}catch{}}
	running=[];
	for(const proc of processors)proc.destroy();
	processors=[];
}
function applyThreat(){
	const amount=Number(danger.value)/100;
	dangerText.textContent=Math.round(amount*100)+'%';
	for(const proc of processors)proc.setDanger(amount);
}
async function loadTrack(){
	resetAudio();
	const item=catalog.tracks.find(x=>x.id===song.value);
	const url=new URL(item.manifest,catalogUrl);
	const res=await fetch(url);
	if(!res.ok)throw Error('Music pack manifest unavailable');
	pack=await res.json();base=url;
	passage.replaceChildren();
	for(const i of [0,Math.floor(pack.segments.length/2),pack.segments.length-2]){
		if(i<0||[...passage.options].some(o=>o.value===String(i)))continue;
		const time=pack.segments[i].startFrame/pack.sampleRate;
		passage.add(new Option((time<15?'Opening':i>pack.segments.length-4?'Late':'Middle')+
			' — '+Math.round(time)+'s',String(i)));
	}
	setStatus('Loaded song choices. Press Play to audition.');
}
async function playPassage(){
	resetAudio();
	const myToken=token;
	play.disabled=true;
	setStatus('Decoding original source stems…');
	try{
		ctx ||= new AudioContext();
		await ctx.resume();
		if(!master){
			master=ctx.createGain();master.gain.value=.19;
			const comp=ctx.createDynamicsCompressor();
			comp.threshold.value=-10;comp.ratio.value=6;
			master.connect(comp);comp.connect(ctx.destination);
		}
		const chosen=pack.segments[Number(passage.value)];
		const names=['drums','bass','guitar','piano','other',melody.value];
		const tracks=await Promise.all(names.map(async name=>{
			const rel=chosen.sources[name];
			if(!rel)throw Error('Missing '+name+' in source pack');
			const r=await fetch(new URL(rel,base));if(!r.ok)throw Error('Missing asset '+rel);
			return {name,buffer:await ctx.decodeAudioData(await r.arrayBuffer())};
		}));
		if(myToken!==token)return;
		const at=ctx.currentTime+.08;
		for(const {name,buffer} of tracks){
			const source=ctx.createBufferSource();source.buffer=buffer;source.loop=true;
			if(['guitar','piano','other'].includes(name)){
				const effect=createBsodThreatProcessor(ctx,master);
				processors.push(effect);source.connect(effect.input);
			}else source.connect(master);
			source.start(at);running.push(source);
		}
		applyThreat();
		setStatus('Playing '+names.length+' original stems — switch A/B or move danger slider.');
	}catch(e){resetAudio();setStatus('Could not play: '+e.message);console.error(e)}
	finally{play.disabled=false}
}
song.addEventListener('change',()=>loadTrack().catch(e=>setStatus(e.message)));
passage.addEventListener('change',()=>{resetAudio();setStatus('Press Play to load this passage.')});
melody.addEventListener('change',()=>{resetAudio();setStatus('Press Play to load this melody.')});
danger.addEventListener('input',applyThreat);
byId('clean').addEventListener('click',()=>{danger.value='0';applyThreat()});
byId('threat').addEventListener('click',()=>{danger.value='97';applyThreat()});
play.addEventListener('click',()=>playPassage());
stop.addEventListener('click',()=>{resetAudio();setStatus('Stopped.')});
loadTrack().catch(e=>setStatus(e.message));
</script></body></html>#!/usr/bin/env python3
"""Reproducible four-track full-length six-stem preview builder.

Original 11-stem One More Run files are NEVER modified: the verified grouped
six-stem derivative is mapped into a throwaway source-manifest mirror.
All output is separate segmented 48kHz stereo Ogg/Opus; never put source
stems or media in the public game repository without explicit approval.
"""
import argparse
import json
import tempfile
from pathlib import Path

from pack_song import build, STEMS

SLOTS=(1,33,3,31)

def create_mirror(master,folder):
	manifest=json.loads((master/'game-stems-manifest.json').read_text())
	status=json.loads((master/'stem_status.json').read_text())
	one=next(t for t in manifest['tracks'] if int(t['slot'])==33)
	group=one.get('grouped_6s',{})
	mapping=group.get('stemFiles',{})
	if set(mapping)!=set(STEMS):
		raise ValueError('One More Run must have validated grouped six-stem derivative')
	frames=group.get('frames')
	if not isinstance(frames,int) or frames<=0:
		raise ValueError('Missing grouping frame count')
	one['stem_files']=dict(mapping)
	one['stem_names']=list(STEMS)
	one['stem_layout']='grouped_6s'
	status['tracks'][one['id']]={
		'status':'complete',
		'stems':{stem:{
			'file':relative,'frames':frames,'sample_rate':44100,'channels':2,
		} for stem,relative in mapping.items()},
	}
	(folder/'stems').symlink_to(master/'stems',target_is_directory=True)
	(folder/'game-stems-manifest.json').write_text(json.dumps(manifest,indent=2)+'\n')
	(folder/'stem_status.json').write_text(json.dumps(status,indent=2)+'\n')
	return {int(t['slot']):t for t in manifest['tracks']}

def main():
	p=argparse.ArgumentParser(description=__doc__)
	p.add_argument('--master',type=Path,default=Path('/root/bitstream-maxi/launch33'))
	p.add_argument('--out',type=Path,required=True)
	p.add_argument('--chunk-seconds',type=int,default=12)
	p.add_argument('--bitrate',default='64k')
	a=p.parse_args()
	master=a.master.resolve()
	out=a.out.resolve()
	if not master.is_dir() or not (master/'game-stems-manifest.json').is_file():
		raise FileNotFoundError('No six-stem master roster')
	if master==out or master.is_relative_to(out) or out.is_relative_to(master):
		raise ValueError('Refusing output inside (or enclosing) the immutable source master tree')
	if out.exists():
		raise FileExistsError('Refusing to overwrite an existing four-song preview')
	if not 2<=a.chunk_seconds<=30:
		raise ValueError('Chunk must be 2-30 seconds')
	out.mkdir(parents=True)
	with tempfile.TemporaryDirectory(prefix='bitstream-master-mirror-',
		dir=out.parent) as scratch:
		stage=Path(scratch)
		roster=create_mirror(master,stage)
		if any(slot not in roster for slot in SLOTS):
			raise ValueError('One or more of four songs absent from source roster')
		for slot in SLOTS:
			build(stage,out,slot,a.chunk_seconds,0,a.bitrate)
	catalog=json.loads((out/'catalog.json').read_text())
	if len(catalog['tracks'])!=4:
		raise ValueError('Expected four full songs, not a short preview')
	print('FOUR_FULL_SONG_PACKS_COMPLETE',out)

if __name__=='__main__':
	main()#!/usr/bin/env python3
"""Full-length provisional 4-song melodic voice by model-FREE audio pitch DSP.

This uses librosa YIN on the six-stem *vocals* source; it does NOT reuse any
SheetSage research-weight derivatives. The score is deliberately approximate.
Each 12s encoded voice chunk aligns exactly to its six source stem frames.
The original FLAC/WAV files are only read; the additive files are produced in
a new staging folder and embedded as voice:bitstream-bluffs in pack.json.
"""
import argparse
import json
import subprocess
from pathlib import Path

import librosa
import numpy as np
from scipy.ndimage import median_filter

RATE=48000
EXTRACT_RATE=16000
HOP=160
CORE=('vocals','drums','bass','guitar','piano','other')

def read_mono(path):
	cmd=['ffmpeg','-v','error','-nostdin','-i',str(path),'-ar',str(EXTRACT_RATE),
		'-ac','1','-f','f32le','pipe:1']
	p=subprocess.run(cmd,capture_output=True,check=True,timeout=180)
	return np.frombuffer(p.stdout,dtype='<f4').copy()

def detect(y,expected_duration):
	if len(y)<1000:
		raise ValueError('Empty vocals stem')
	f0=librosa.yin(y.astype('float64'),fmin=95,fmax=1000,sr=EXTRACT_RATE,
		frame_length=2048,hop_length=HOP,center=True, trough_threshold=.15)
	rms=librosa.feature.rms(y=y,frame_length=2048,hop_length=HOP,center=True)[0]
	n=min(len(rms),len(f0))
	rms=rms[:n]
	f0=f0[:n]
	floor=max(.0005,float(np.percentile(rms,83))*.20)
	voiced=(rms>floor)&np.isfinite(f0)&(f0>96)&(f0<990)
	notes=np.rint(librosa.hz_to_midi(np.clip(f0,95,1000))).astype('int16')
	notes=median_filter(notes,size=9)
	notes[~voiced]=-1
	events=[]
	start=None
	last=None
	for i,v in enumerate(np.append(notes,-100)):
		if i<n and v==last:
			continue
		if start is not None and last>=0:
			a=start*HOP/EXTRACT_RATE
			b=min(expected_duration,i*HOP/EXTRACT_RATE)
			if b-a>=.075:
				events.append({'start':round(a,5),'end':round(b,5),
					'midi':int(last)})
		start=i
		last=int(v)
	# Merge same-note runs across short breaks, leave discrete repeated
	# long breaks separate so we do not hide real re-attacks.
	merged=[]
	for e in events:
		if merged and merged[-1]['midi']==e['midi'] and e['start']-merged[-1]['end']<=.045:
			merged[-1]['end']=e['end']
		else:
			merged.append(e)
	if len(merged)<25:
		raise ValueError('Vocal pitch extraction too sparse: '+str(len(merged)))
	return merged,{'frames':n,'rmsFloor':floor,'voicedFraction':float(voiced.mean()),
		'rawDetectedNotes':len(events),'mergedNotes':len(merged)}

def synth(events,frames):
	"""Buzzy-but-gentle source note sequence for LIVE biome filtering."""
	mono=np.zeros(frames,dtype='float32')
	for e in events:
		a=round(e['start']*RATE)
		b=min(frames,round(e['end']*RATE))
		if b-a<32:
			continue
		t=np.arange(b-a,dtype=np.float64)/RATE
		f=440.*2**((e['midi']-69)/12)
		# Some harmonics are essential: sine-only loses its character if
		# the biome UI applies a lowpass/bandpass filter.
		phase=2*np.pi*f*t
		s=.68*np.sin(phase)+.31*np.sin(2*phase)+.17*np.sin(3*phase)
		s+=.10*np.sin(4*phase)
		gate=np.minimum(1,t/.006)*np.minimum(1,(e['end']-e['start']-t)/.023)
		s*=np.clip(gate,0,1)
		mono[a:b]+=(s*.19).astype('float32')
	peak=float(np.max(np.abs(mono)))
	if peak>.74:
		mono*=.74/peak
	return mono

def encode(path,mono,segment,bitrate='64k'):
	start=segment['startFrame']
	stop=start+segment['frames']
	mono_chunk=mono[start:stop]
	if len(mono_chunk)!=segment['frames']:
		raise ValueError('Frame mismatch')
	stereo=np.repeat(mono_chunk[:,None],2,axis=1)
	command=['ffmpeg','-v','error','-nostdin','-y','-f','f32le','-ar',str(RATE),
		'-ac','2','-i','pipe:0','-c:a','libopus','-application','audio',
		'-b:a',bitrate,'-vbr','on',str(path)]
	subprocess.run(command,input=stereo.astype('<f4').tobytes(),
		check=True,capture_output=True,timeout=100)
	if not path.exists() or path.stat().st_size<500:
		raise ValueError('Missing/short voice chunk: '+str(path))

def run(a):
	if a.out.exists():
		raise FileExistsError('Refusing to overwrite '+str(a.out))
	a.out.mkdir(parents=True)
	master=json.loads((a.master/'game-stems-manifest.json').read_text())
	manifest=json.loads((a.pack_source/'catalog.json').read_text())
	report={'format':'bitstream-provisional-melody-v1',
		'extraction':'Model-free librosa YIN isolated vocals; tentative not verified',
		'songs':[]}
	for song in manifest['tracks']:
		info=next(x for x in master['tracks'] if x['id']==song['id'])
		path=a.master/info['stem_files']['vocals'] if info['slot']!=33 else (
			a.master/info['grouped_6s']['stemFiles']['vocals'])
		orig=json.loads((a.pack_source/song['manifest']).read_text())
		if 'voice:bitstream-bluffs' in orig['segments'][0]['sources']:
			raise ValueError('Already contains voice')
		duration=orig['frameCount']/RATE
		samples=read_mono(path)
		events,stats=detect(samples,duration)
		sound=synth(events,orig['frameCount'])
		dirname=Path(song['manifest']).parent
		target=a.out/dirname
		target.mkdir(parents=True,exist_ok=True)
		for idx,segment in enumerate(orig['segments']):
			name=f'{idx:04d}-voice-home.ogg'
			encode(target/name,sound,segment)
		# Keep original source packs unchanged: distribution step copies
		# only this new voice and patches the working public manifests.
		(target/'melody-audit-private.json').write_text(json.dumps({
			'song':song['id'],'duration':duration,'stats':stats,
			'notes':events},indent=2)+'\n')
		report['songs'].append({'id':song['id'],'title':song['title'],
			'duration':duration,'eventCount':len(events),
			'voiceSegments':len(orig['segments']),'statistics':stats})
		print('MELODY_READY',song['id'],'notes',len(events),
			'segments',len(orig['segments']),flush=True)
	(a.out/'private-summary.json').write_text(json.dumps(report,indent=2)+'\n')
	print('FOUR_SONGS_SYNTH_DONE',flush=True)

if __name__=='__main__':
	p=argparse.ArgumentParser(description=__doc__)
	p.add_argument('--master',required=True,type=Path)
	p.add_argument('--pack-source',required=True,type=Path)
	p.add_argument('--out',required=True,type=Path)
	run(p.parse_args())#!/usr/bin/env python3
"""Build a SMALL and source-pinned in-game review shortlist from the existing
UNLABELED model-disagreement audit. No inferred errors are called true.

This is NOT a gold set and NOT a new transcription. The exported artifacts
never contain source audio and never modify a game sound or user profile.
"""
import argparse
import json
from collections import defaultdict
from pathlib import Path

from performance_v1 import read,ROLES

FORMAT='bitstream-music-review-queue-v1'
STATUS='machine-ranked-disagreement-not-human-verified'
SOURCE_FORMAT='bitstream-real-music-model-disagreement-queue-v1'


def make_queues(audit, music_root):
	if audit.get('format')!=SOURCE_FORMAT or audit.get('goldStatus')!=(
		'NONE — candidate AND baseline unverified'):
		raise ValueError('invalid original model-disagreement audit')
	selection=audit.get('proposedReviewExcerpts')
	if not isinstance(selection,list) or len(selection)!=20:
		raise ValueError('expected precisely the preserved 20 proposed excerpts')
	grouped=defaultdict(list)
	seen=set()
	for index,part in enumerate(selection):
		song=part['songId']
		role=part['role']
		start,end=part['startFrame'],part['endFrame']
		if role not in ROLES or role=='melody':
			raise ValueError('bad review role')
		if not all(type(v) is int for v in (start,end)) or not (
			0<=start<end and end-start<=8*48000):
			raise ValueError('invalid sample-frame range')
		key=(song,role,start,end)
		if key in seen:raise ValueError('duplicate selected excerpt')
		seen.add(key)
		row={
			'id':role+'-'+str(start),
			'role':role,
			'startFrame':start,
			'endFrame':end,
			'priorityOrder':index+1,
			'releaseCount':part['releaseCount'],
			'candidateCount':part['candidateCount'],
			'samePitchWithin50ms':part['samePitchWithin50ms'],
			'disagreementProxy':part['priorityProxy'],
		}
		if any(type(row[k]) is not int or row[k]<0 for k in (
			'releaseCount','candidateCount','samePitchWithin50ms','priorityOrder')):
			raise ValueError('invalid reference counts')
		if row['samePitchWithin50ms']>min(
			row['releaseCount'],row['candidateCount']):
			raise ValueError('impossible one-to-one agreement count')
		grouped[song].append(row)
	catalog=json.loads((music_root/'catalog.json').read_text())
	songs=catalog.get('tracks',[])
	if len(songs)!=4:raise ValueError('wrong song manifest count')
	output={}
	for song in songs:
		id=song['id']
		assert id in grouped,'song missing from manual-review shortlist'
		pack_path=music_root/song['manifest']
		pack=json.loads(pack_path.read_text())
		parent=read(pack_path.parent/'performance.json')
		candidate=read(pack_path.parent/'performance-candidate-v2.json')
		if parent['quality']!='provisional-unreviewed' or (
			candidate['quality']!='experimental-candidate-unreviewed'):
			raise ValueError('non-matching original score source')
		if candidate['provenance']['evidence']['parentScoreHash']!=parent['scoreHash']:
			raise ValueError('not a candidate descended from release score')
		if (parent['scoreHash']!=pack['performance']['scoreHash'] or
			candidate['scoreHash']!=pack['experimentalPerformance']['scoreHash']):
			raise ValueError('score hashes do not match pack')
		if candidate['provenance']['sourceStemSha256']!=parent['provenance']['sourceStemSha256']:
			raise ValueError('wrong original master audio')
		for row in grouped[id]:
			if row['endFrame']>parent['frameCount']:
				raise ValueError('review exceeds music duration')
		output[id]={
			'format':FORMAT,'songId':id,'status':STATUS,
			'baselineScoreHash':parent['scoreHash'],
			'experimentalScoreHash':candidate['scoreHash'],
			'selectionMethod':'machine ranking of pitch/class disagreements within 50ms, NOT correctness',
			'excerpts':grouped[id]}
		print('UNVERIFIED_REVIEW_SHORTLIST',id,len(grouped[id]),flush=True)
	return output


def main():
	p=argparse.ArgumentParser(description=__doc__)
	p.add_argument('--audit',required=True,type=Path)
	p.add_argument('--music-root',required=True,type=Path)
	p.add_argument('--output-dir',required=True,type=Path)
	a=p.parse_args()
	audit=json.loads(a.audit.read_text())
	result=make_queues(audit,a.music_root)
	if a.output_dir.exists():
		raise FileExistsError('review queue output must be a fresh directory')
	# User-facing queue is small; no large original model audit is copied.
	a.output_dir.mkdir(parents=True)
	catalog=json.loads((a.music_root/'catalog.json').read_text())
	for song in catalog['tracks']:
		path=a.output_dir/Path(song['manifest']).parent/'review-queue-v1.json'
		path.parent.mkdir(parents=True,exist_ok=True)
		path.write_text(json.dumps(result[song['id']],indent=2)+'\n')
	assert sum(len(x['excerpts']) for x in result.values())==20
	print('TWENTY_SOURCE_PINNED_REVIEW_EXCERPTS_NOT_HUMAN_GOLD')

