"""Real music detector-v2 *differential*, not unlabeled 'accuracy'.

Compare selected 30s source passages from all 4 actual FLAC song parts against
the immutable original release-v1 scores. Do not classify unmatched notes as
true/false without gold. Never write into public game packs or original scores.
"""
import argparse
import hashlib
import json
import math
import subprocess
from collections import Counter
from pathlib import Path

import numpy as np
from detector_candidate_v2 import accompaniment
from performance_v1 import read,STEMS,sha256_file

ROLE_NAMES=('guitar','piano','other')
PARTS=((14,30),(75,30))

def read_audio_window(source,start,duration):
	cmd=['ffmpeg','-nostdin','-hide_banner','-loglevel','error',
		'-ss',str(start),'-i',str(source),'-t',str(duration),
		'-ac','1','-ar','16000','-f','f32le','pipe:1']
	result=subprocess.run(cmd,stdout=subprocess.PIPE,stderr=subprocess.PIPE,
		timeout=95,check=True)
	out=np.frombuffer(result.stdout,dtype='<f4').copy()
	if len(out)<duration*16000*.95:raise ValueError('short source window')
	if not np.all(np.isfinite(out)):raise ValueError('non-finite source')
	return out

def stats(events,length_sec):
	midis=[e['midi'] for e in events]
	times=[e['start'] for e in events]
	ordered=all(x<=y for x,y in zip(times,times[1:]))
	# Chord notes may occur at same frame.
	same_pitch_repeats=0
	most_recent={}
	for e in events:
		prev=most_recent.get(e['midi'])
		if prev is not None and .075<=e['start']-prev<=.26:
			same_pitch_repeats+=1
		most_recent[e['midi']]=e['start']
	# Do not call this 'flams' without truth; only candidate event density.
	attacks=sorted(set(times))
	close=sum(a-b<.08 for a,b in zip(attacks[1:],attacks[:-1]))
	return {'events':len(events),'notesPerMinute':round(
		len(events)*60/length_sec,1),'possibleLow41to55':sum(
		p<=55 for p in midis),'uniqueLowPitches':sorted(set(
		p for p in midis if p<=55)),'uniquePitches':len(set(midis)),
		'uniqueAttacks':len(attacks),'attacksLessThan80msApart':close,
		'nearRepeatsSamePitch75to260ms':same_pitch_repeats,
		'sortedByOnset':ordered}

def main():
	p=argparse.ArgumentParser(description=__doc__)
	p.add_argument('--master',required=True,type=Path)
	p.add_argument('--score-root',required=True,type=Path)
	p.add_argument('--catalog',required=True,type=Path)
	p.add_argument('--out',required=True,type=Path)
	p.add_argument('--only-song',action='append')
	a=p.parse_args()
	if a.out.exists():raise FileExistsError(a.out)
	roster=json.loads((a.master/'game-stems-manifest.json').read_text())
	catalog=json.loads((a.catalog/'catalog.json').read_text())
	reports=[]
	for song in catalog['tracks']:
		if a.only_song and song['id'] not in a.only_song:continue
		row=next(r for r in roster['tracks'] if r['id']==song['id'])
		stems=row['stem_files'] if row['slot']!=33 else row['grouped_6s']['stemFiles']
		score=read(a.score_root/Path(song['manifest']).parent/'performance.json')
		assert score['songId']==song['id']
		if score['quality']!='provisional-unreviewed':raise ValueError('Not original release')
		for role in ROLE_NAMES:
			source=a.master/stems[role]
			if sha256_file(source)!=score['provenance']['sourceStemSha256'][role]:
				raise ValueError('wrong source audio: '+role)
			for start,duration in PARTS:
				y=read_audio_window(source,start,duration)
				candidate,info=accompaniment(y)
				# Original release uses rounded 48kHz frame timestamps.
				old=[{'midi':e['pitch'],
					'start':round(e['startFrame']/48000-start,4)}
					for e in score['events'][role] if
					start*48000<=e['startFrame']<(start+duration)*48000]
				item={'song':song['id'],'role':role,
					'startSec':start,'durationSec':duration,
					'sourceStemSha256':score['provenance']['sourceStemSha256'][role],
					'decodedWindowSha256':hashlib.sha256(y.tobytes()).hexdigest(),
					'baseline':stats(old,duration),
					'candidate':stats(candidate,duration),
					'candidateDetector':info,
					'goldValidation':'NONE — cannot infer true/false positives from counts'}
				reports.append(item)
				print('REAL_SOURCE_UNLABELED',song['id'],role,start,
					'old',len(old),'new',len(candidate),
					'lowold',item['baseline']['possibleLow41to55'],
					'lownew',item['candidate']['possibleLow41to55'],
					'oldHighDensity',item['baseline']['attacksLessThan80msApart'],
					'newHighDensity',item['candidate']['attacksLessThan80msApart'],
					flush=True)
	report={'format':'bitstream-real-source-detector-audit-v1',
		'readOnly':True,'modelConfidenceCalibrated':False,
		'passages':reports,'claims':'descriptive event differences only; NO gold/music accuracy',
		'generatorSha256':sha256_file(Path(__file__)),
		'detectorSha256':sha256_file(Path(__file__).with_name(
			'detector_candidate_v2.py'))}
	a.out.parent.mkdir(parents=True,exist_ok=True)
	a.out.write_text(json.dumps(report,indent=2)+'\n')
	print('REAL_SOURCE_DIFFERENTIAL_COMPLETED',len(reports),'passages',flush=True)

if __name__=='__main__':
	main()#!/usr/bin/env python3
"""Conservative v2 candidate release detector experiments — NOT shipped audio.

Shared 48kHz performance-v1 output is the only eventual replacement contract.
Current game music/audio remains v1. These algorithms generate *candidate*
hypotheses for offline comparison and human review, never calibrated confidence.

Design: 10ms spectral novelty provides coarse attacks, 2ms RMS slopes
refine sample-frame positions. >=80ms cross-attack suppression prevents
reverb echoes from becoming extra notes while retaining 120ms re-attacks.
2048-sample windows + interpolated 8192-bin FFT give harmonic-supported pitch
hypotheses and remove release v1's impossible low-semitone bins.
"""
import math
import numpy as np
import librosa
from scipy.signal import find_peaks

RATE=16000
HOP=160
ROLE_MIN_GAP_SEC=.080
FFT_LEN=8192
PITCH_LOW=41
PITCH_HIGH=91
PITCHES=np.arange(PITCH_LOW,PITCH_HIGH+1)
FUNDAMENTALS=440.0*2.0**((PITCHES-69.0)/12.0)


def rms_envelope(y,step=32,width=64):
	"""Windowed RMS with ~2ms attack grid, centered windows."""
	if y.ndim!=1 or len(y)<width*2:
		raise ValueError('Detector needs mono audio longer than two windows')
	y=np.asarray(y,dtype='float64')
	sq=y*y
	prefix=np.r_[0.,np.cumsum(sq)]
	centers=np.arange(0,len(y),step)
	l=np.maximum(0,centers-width//2)
	r=np.minimum(len(y),centers+width//2)
	rms=np.sqrt(np.maximum(0,(prefix[r]-prefix[l])/(r-l)))
	return centers,rms

def source_onsets(y,min_gap_sec=ROLE_MIN_GAP_SEC):
	"""Source-aware onset proposals, not an accuracy label.

	FFT flux remains source-derived, while attack timestamp comes from
	measuring actual waveform RMS growth. Return 16kHz-sample onset indices,
	coarse candidate stats, and uncalibrated detector diagnostics.
	"""
	y=np.asarray(y,dtype='float32')
	if not len(y):return [],{'proposals':0,'retained':0,'status':'empty'}
	stft=np.abs(librosa.stft(y,n_fft=1024,hop_length=HOP,center=True))
	positive=np.maximum(0,np.diff(np.log1p(stft*25),axis=1))
	# Weight low and mid pitched energy; ignore upper hiss to avoid triggers
	# from stem leakage. Clipped frequency support starts above sub-bass.
	freq=np.fft.rfftfreq(1024,1/RATE)
	band=(freq>70)&(freq<5300)
	flux=np.mean(positive[band],axis=0)
	if len(flux)<4:return [],{'proposals':0,'retained':0,'status':'too-short'}
	threshold=max(.001,float(np.percentile(flux,68))*.23)
	gap=max(1,round(min_gap_sec*RATE/HOP))
	peaks,_=find_peaks(flux,prominence=threshold,distance=gap)
	centers,env=rms_envelope(y)
	# Local waveform-envelope gradients: sharp rises, not smooth decays.
	# diff(t) compares energy approximately 8ms before to 4ms after.
	l=np.maximum(0,np.arange(len(env))-4)
	r=np.minimum(len(env)-1,np.arange(len(env))+2)
	rise=np.maximum(0,env[r]-env[l])
	min_rise=max(float(np.percentile(rise,90))*.16,
		float(np.percentile(env,85))*.018,2e-5)
	onsets=[]
	for p in peaks:
		coarse=(int(p)+1)*HOP
		# Broadband flux is routinely up to 15ms early; search both sides.
		a=max(0,round((coarse-.025*RATE)/32))
		b=min(len(env),round((coarse+.04*RATE)/32)+1)
		if b<=a:continue
		chunk=rise[a:b]
		k=int(a+np.argmax(chunk))
		if rise[k]<min_rise:continue
		start=int(centers[k])
		# Discard any candidate with low attack contrast compared to the
		# immediately preceding local envelope. A genuine re-pluck
		# must exhibit a new attack, not just a bright sustain harmonic.
		before=float(np.median(env[max(0,k-8):max(1,k-3)]))
		after=float(np.median(env[min(len(env)-1,k+1):min(len(env),k+5)]))
		if after<before*1.14 and after-before<min_rise*.55:
			continue
		if onsets and start-onsets[-1] < min_gap_sec*RATE:
			# Prefer the candidate with stronger local amplitude slope.
			old=round(onsets[-1]/32)
			if rise[k]>rise[min(len(rise)-1,old)]*1.35:
				onsets[-1]=start
			continue
		onsets.append(start)
	return onsets,{'proposals':len(peaks),'retained':len(onsets),
		'resolutionMs':2.,'minimumGapMs':round(min_gap_sec*1000,1),
		'confidenceCalibrated':False}

def harmonic_candidates(y,onset,window_samples=2048,max_notes=2):
	"""Interpolate off-grid harmonics; subharmonic aliases are penalized.

	Return tuple (MIDI, raw heuristic salience). No salience is a confidence
	probability. Separate sustained/mixed-stem tests must qualify this model.
	"""
	y=np.asarray(y,dtype='float32')
	start=max(0,int(onset)+160)
	stop=min(len(y),start+window_samples)
	frame=y[start:stop]
	if len(frame)<384:return []
	frame=frame-np.mean(frame)
	window=np.hanning(len(frame))
	magnitude=np.abs(np.fft.rfft(frame*window,n=FFT_LEN))
	hz=np.fft.rfftfreq(FFT_LEN,d=1/RATE)
	# 8192-point padding is interpolation, NOT additional acoustic
	# resolution; 128ms actual window is the limiting low-note span.
	harmonics=[]
	base=[]
	for f in FUNDAMENTALS:
		energy=[]
		for harmonic in range(1,6):
			frequency=f*harmonic
			if frequency>4000:
				energy.append(0.);continue
			bin0=np.searchsorted(hz,frequency)
			halfwidth=max(2,round((4.0+frequency*.004)*FFT_LEN/RATE))
			seg=magnitude[max(0,bin0-halfwidth):min(len(magnitude),bin0+halfwidth+1)]
			energy.append(float(seg.max()) if seg.size else 0.)
		# Stronger harmonics are not independently interpreted as a
		# low pitch without support near f and 2f.
		score=sum(v/(i**1.1) for i,v in enumerate(energy,1))
		anchor=energy[0]+energy[1]*.6
		harmonics.append(score)
		base.append(anchor)
	harmonics=np.asarray(harmonics)
	base=np.asarray(base)
	global_max=float(np.max(harmonics)) if len(harmonics) else 0.
	if global_max<=1e-6:return []
	# Relative floor and local neighborhood competition stop spurious
	# scores 1 semitone from a real fundamental.
	local,_=find_peaks(harmonics,distance=2)
	candidates=[]
	for idx in local:
		if harmonics[idx]<global_max*.34 or base[idx]<max(base)*.27:
			continue
		pitch=int(PITCHES[idx])
		candidates.append((pitch,float(harmonics[idx]),float(base[idx])))
	candidates.sort(key=lambda x:x[1],reverse=True)
	selected=[]
	for pitch,salience,fundamental in candidates:
		if any(abs(pitch-m)<2 for m,_ in selected):
			continue
		# If a lower detected candidate also explains the harmonic, do
		# not count the overtone as an independent note.
		if any(pitch-m in (12,19,24) and strength>=salience*.6
			for m,strength in selected):
			continue
		selected.append((pitch,salience))
		if len(selected)>=max_notes:break
	return selected

def accompaniment(y):
	"""Generate standalone candidate score-v1 legacy note API, source-driven."""
	attacks,stats=source_onsets(y)
	events=[]
	for i,attack in enumerate(attacks):
		pitches=harmonic_candidates(y,attack)
		if not pitches:continue
		start=round(attack/RATE,4)
		if i+1<len(attacks):
			duration=min(.7,max(.095,(attacks[i+1]-attack)/RATE*.85))
		else:
			duration=.3
		for pitch,salience in pitches:
			events.append({'midi':pitch,'start':start,
				'end':round(start+duration,4),
				'confidence':None,'expression':{'estimatedVelocity':None}})
	return events,{**stats,'hypothesizedNotes':len(events),
		'algorithm':'experimental-v2-harmonic-rms-onsets',
		'quality':'unverified-candidate-not-publishable'}


def bass_replucks(y):
	"""Split same-pitch sustained YIN spans on validated re-attack cues.

	We preserve the legacy pitch track and do NOT invent octave guesses.
	This isolates Fable's missing repeated-bass-note defect from unrelated
	pitch model changes. Old + new share identical role/event JSON.
	"""
	from render_full_dynamic_orchestra_v1 import choose_bass_events
	old,meta=choose_bass_events(y)
	attacks,attack_meta=source_onsets(y,min_gap_sec=.09)
	out=[]
	for item in old:
		a=item['start']
		b=item['end']
		pitch=item['midi']
		# A 0.30-0.38s legitimate pluck with reverb tail often has one
		# phantom attack 140ms later. Short segments cannot establish
		# a repeated-note pattern, so do not modify them at all.
		if b-a<.42:
			out.append(item)
			continue
		within=sorted(t/RATE for t in attacks if a+.10<=t/RATE<=b-.07)
		regular=[t for t in within if t<=b-.09]
		gaps=np.diff(regular)
		# Multiple attacks at near-regular subbeat intervals are stronger
		# evidence of re-striking than a single source transient. This
		# conservative gate intentionally leaves ambiguous notes alone.
		if len(regular)<2 or len(gaps)<1 or np.min(gaps)<.085 or (
			np.max(gaps)>.27) or np.std(gaps)>max(.019,np.mean(gaps)*.24):
			out.append(item)
			continue
		earlier=[t/RATE for t in attacks if a-.03<=t/RATE<=a+.08]
		first=min(earlier,key=lambda t:abs(t-a-.045)) if earlier else a
		points=[first]
		for t in regular:
			if t-points[-1]>=.08 and b-t>=.07:
				points.append(t)
		if len(points)<3:
			out.append(item)
			continue
		for i,start in enumerate(points):
			end=points[i+1] if i+1<len(points) else b
			if end-start>=.065:
				out.append({'midi':pitch,'start':round(start,4),
					'end':round(end,4)})
	return out,{'algorithm':'release-v1-YIN-pitch-plus-v2-source-reattacks',
		'baselineBassEvents':len(old),'candidateBassEvents':len(out),
		'addedReattacks':len(out)-len(old),'attackProposals':attack_meta,
		'confidenceCalibrated':False}


def drum_simultaneous(y,echo_guard='ratio-only'):
	"""Independent per-family onset streams, including simultaneous co-hits.

	Unlike release v1 (one class per broadband onset), each family has its
	own spectral/onset evidence. Synthetic tests may still expose false
	co-hits; do not deploy until real drums manually reviewed.
	"""
	from scipy.signal import butter,sosfiltfilt
	y=np.asarray(y,dtype='float32')
	if len(y)<RATE//4:return [],{'reason':'too-short'}
	config={
		'kick':(45,180,.055),
		'snare':(350,3500,.055),
		'hat':(4400,7500,.044),
	}
	if echo_guard not in ('correlated-attack','ratio-only','none'):
		raise ValueError('invalid experimental echo guard')
	out=[]
	raw=[]
	filtered={}
	for kind,(low,high,gap) in config.items():
		sos=butter(4,[low,high],btype='bandpass',fs=RATE,output='sos')
		band=sosfiltfilt(sos,y).astype('float32')
		filtered[kind]=band
		centers,env=rms_envelope(band)
		idx=np.arange(len(env))
		past=np.maximum(0,idx-5)
		future=np.minimum(len(env)-1,idx+2)
		gain=np.maximum(0,env[future]-env[past])
		# Refractory windows affect ONLY this drum family.
		threshold=max(
			float(np.percentile(gain,87))*.3,
			float(np.max(gain))*.023,
			1e-5)
		peaks,_=find_peaks(gain,
			distance=max(1,round(gap*RATE/32)),
			prominence=threshold)
		for peak in peaks:
			frame=int(centers[peak])
			before=float(np.median(env[max(0,peak-8):max(1,peak-3)]))
			after=float(np.median(env[min(len(env)-1,peak+1):
				min(len(env),peak+5)]))
			if after-before<max(threshold*.4,2e-5):
				continue
			if after < before*1.2 and after-before<threshold:
				continue
			raw.append((frame,kind,float(gain[peak]),after))
	# Co-hits across band families remain distinct source events.
	raw.sort(key=lambda x:(x[0],x[1]))
	# A strongly decaying repeat of the SAME family inside 170ms is
	# echo-suspect. Never compare across families: kick+snare co-hits
	# are intentional. This is a hypothesis, not real-hit truth, and
	# could reject legitimate quiet ghost notes: audit on human gold.
	accepted={}
	removed_echo_suspects=0
	for frame,kind,gain,energy in raw:
		last=accepted.get(kind)
		if last is not None:
			last_frame,last_gain,last_energy=last
			dt=(frame-last_frame)/RATE
			echo_window=.052<=dt<=.17 and gain<last_gain*.52 and (
				energy<last_energy*.83)
			reject=False
			if echo_guard=='ratio-only':
				reject=echo_window
			elif echo_guard=='correlated-attack' and echo_window:
				# An echoed snare/hat is a delayed, scaled copy of the
				# earlier waveform, unlike an independently re-struck
				# noisy membrane or cymbal. One anchored window avoids
				# treating all quiet ghost notes as room echoes.
				# Tonal kick attacks can also be highly correlated when
				# truly struck again, so kick echo rejection waits for
				# separately calibrated time/frequency evidence.
				if kind!='kick':
					band=filtered[kind]
					size=round(.024*RATE)
					a=band[last_frame+32:last_frame+32+size]
					b=band[frame+32:frame+32+size]
					if len(a)==size and len(b)==size:
						den=float(np.linalg.norm(a)*np.linalg.norm(b))
						corr=abs(float(np.dot(a,b))/den) if den>1e-8 else 0.
						reject=corr>.68
			if reject:
				removed_echo_suspects+=1
				continue
		accepted[kind]=(frame,gain,energy)
		out.append({'t':round(frame/RATE,4),'type':kind})
	return out,{'algorithm':'v2-family-independent-band-envelope-attacks',
		'echoGuard':echo_guard,
		'removedEchoSuspects':removed_echo_suspects,
		'candidateHits':len(out),
		'families':{role:sum(x['type']==role for x in out)
			for role in config},'confidenceCalibrated':False}#!/usr/bin/env python3
"""Research-only V3: anchor provisional drum-family co-hits to the original
broadband onset proposals. This is a test of disagreement/false-event
containment, NOT a gold-verified new drum renderer.

The released v1 detector is deliberately left unchanged. No output here is
eligible for game playback, and no calibrated confidence is supplied.
"""
from bisect import bisect_left

from detector_candidate_v2 import drum_simultaneous, RATE


def drum_anchor_fusion(y, *, candidate_echo_guard='none',
	join_window_ms=38, merge_same_class_ms=32, preserve_baseline=True):
	from render_full_dynamic_orchestra_v1 import choose_drum_events
	baseline, bdiag=choose_drum_events(y)
	candidates, cdiag=drum_simultaneous(y,echo_guard=candidate_echo_guard)
	if not baseline:
		return [], {'algorithm':'v3-release-anchored-cohit-probe',
			'status':'no-baseline-anchors-no-claims','candidateEvents':len(candidates)}
	tolerance=join_window_ms/1000
	redundancy=merge_same_class_ms/1000
	events=[]
	used=set()
	for original in baseline:
		origin=original['t']
		nearest={}
		for index,hit in enumerate(candidates):
			delta=abs(hit['t']-origin)
			if delta>tolerance:continue
			role=hit['type']
			if role not in nearest or delta<nearest[role][0]:
				nearest[role]=(delta,index,hit)
		# Deliberately test v1 fallback since independent V2 onset streams
		# can lose true low-amplitude re-strikes during echo filtering.
		if preserve_baseline:
			key=original['type']
			if key in nearest:
				distance,idx,hit=nearest.pop(key)
				events.append({'t':hit['t'],'type':key})
				used.add(idx)
			else:
				events.append({'t':origin,'type':key})
		for role,(distance,idx,hit) in nearest.items():
			if idx in used:continue
			events.append({'t':hit['t'],'type':role})
			used.add(idx)
	events.sort(key=lambda x:(x['t'],x['type']))
	# no double same-class hit when adjacent v1 anchors share a V2 event.
	merged=[]
	for item in events:
		if merged and any(
			e['type']==item['type'] and 0<=item['t']-e['t']<redundancy
			for e in merged[-5:]
		):
			continue
		merged.append(item)
	return merged, {'algorithm':'v3-release-anchored-cohit-probe',
		'baselineEvents':len(baseline),'candidateEvents':len(candidates),
		'outputEvents':len(merged),'experimentalEchoGuard':candidate_echo_guard,
		'confidenceCalibrated':False,'status':'synthetic-research-only'}#!/usr/bin/env python3
"""Research ONLY: classify V2 drum-restrike vs delayed-copy echo proposals.

This never changes frozen scores, live stems, renderer behavior or settings.
Source-gold accuracy is unknown; do not promote on synthetic benchmarks.
"""
from collections import deque
import numpy as np
from scipy.signal import butter, sosfiltfilt
from detector_candidate_v2 import RATE, drum_simultaneous

BANDS = {'kick': (1600, 6500), 'snare': (450, 3300), 'hat': (4700, 7300)}


def aligned_attack_similarity(band, first, second):
	"""Compare attack texture in one pre-filtered family band.

	Returns maximum normalized correlation over a small alignment tolerance.
	This is a heuristic, NOT a probability of a genuine hit.
	"""
	a = int(first * RATE) + 48
	b = int(second * RATE) + 48
	length = int(.013 * RATE)
	if a < 0 or b < 0 or max(a, b) + length + 72 >= len(band):
		return 0.0, 0.0
	ref = band[a:a + length]
	ref_norm = float(np.linalg.norm(ref))
	if ref_norm < 1e-9:
		return 0.0, 0.0
	best = 0.0
	for offset in range(-64, 65, 8):
		comp = band[b + offset:b + offset + length]
		den = ref_norm * float(np.linalg.norm(comp))
		if den > 1e-9:
			best = max(best, abs(float(np.dot(ref, comp)) / den))
	ref_energy = float(np.sqrt(np.mean(ref ** 2)))
	comp_energy = float(np.sqrt(np.mean(band[b:b + length] ** 2)))
	return best, comp_energy / max(ref_energy, 1e-9)


def drum_echo_similarity_probe(y, *, correlation_cut=.65, energy_cut=.82):
	"""Return unapproved candidate events plus per-pair diagnostics."""
	y = np.asarray(y, dtype='float32')
	proposals, _ = drum_simultaneous(y, echo_guard='none')
	if not proposals:
		return [], {'algorithm':'v4-attack-texture-probe',
			'status':'synthetic-research-only-not-calibrated',
			'proposals':0,'accepted':0,'suspects':[],
			'confidenceCalibrated':False}
	filtered = {kind:sosfiltfilt(butter(3, [low, high],
		btype='bandpass', fs=RATE, output='sos'), y)
		for kind, (low, high) in BANDS.items()}
	accepted = []
	suspects = []
	recent = {kind:deque() for kind in BANDS}
	for proposal in proposals:
		kind = proposal['type']
		current = proposal['t']
		history = recent[kind]
		while history and current-history[0]['t'] > .17:
			history.popleft()
		prior = [hit for hit in history if .05 <= current-hit['t'] <= .17]
		if not prior:
			accepted.append(proposal)
			history.append(proposal)
			continue
		best_match = (0., 0., None)
		for hit in prior:
			corr, ratio = aligned_attack_similarity(filtered[kind], hit['t'], current)
			if corr > best_match[0]:
				best_match = (corr, ratio, hit['t'])
		corr, ratio, reference = best_match
		rejected = corr >= correlation_cut and ratio < energy_cut
		suspects.append({'type':kind, 't':current,
			'refT':reference, 'correlation':round(corr, 4),
			'ratio':round(ratio, 4), 'rejected':rejected})
		if not rejected:
			accepted.append(proposal)
			history.append(proposal)
	return accepted, {'algorithm':'v4-attack-texture-probe',
		'status':'synthetic-research-only-not-calibrated',
		'proposals':len(proposals),'accepted':len(accepted),
		'suspects':suspects,'confidenceCalibrated':False}#!/usr/bin/env python3
"""V6 research-only: V5 family selection with attack band-dominance veto.

Thresholds fixed from synthetic development diagnostics BEFORE alternate
seed runs. Values are heuristic, NOT calibrated probabilities. Never playable.
"""
from audit_cross_band_v6 import (attack_bands,attack_features,
	source_predictions,FAMILIES)

# Candidate thresholds chosen only using 559103/71/337/1097 development.
# Low kick threshold preserves mixed low-frequency co-hit attacks.
MIN_FAMILY_SHARE={'kick':.10,'snare':.10,'hat':.10}


def cross_band_veto(wave, *, thresholds=None):
	limits=MIN_FAMILY_SHARE if thresholds is None else thresholds
	if set(limits)!=set(FAMILIES) or any(not 0<=v<=1 for v in limits.values()):
		raise ValueError('Invalid family-support thresholds')
	predicted=source_predictions(wave)
	if not predicted:
		return [],{'algorithm':'v6-cross-band-veto-unapproved',
			'input':0,'retained':0,'removed':{},'status':'synthetic-only'}
	bands=attack_bands(wave)
	kept=[]
	removed={kind:0 for kind in FAMILIES}
	for event in predicted:
		strength=attack_features(bands,event['t'])
		kind=event['type']
		total=sum(strength.values())
		fraction=strength[kind]/max(1e-10,total)
		if fraction < limits[kind]:
			removed[kind]+=1
		else:
			kept.append(event.copy())
	return kept,{'algorithm':'v6-cross-band-veto-unapproved',
		'input':len(predicted),'retained':len(kept),'removed':removed,
		'thresholds':dict(limits),'status':'synthetic-only',
		'confidenceCalibrated':False}#!/usr/bin/env python3
"""Evaluate a *human verified* note/hit gold set against performance-v1.

No 125ms synthetic tolerance. One-to-one max-cardinality onset matching at
both 20ms and 50ms, with a secondary minimization of absolute timing error,
separately by role+pitch (drums by hit type). Reports signed bias, jitter,
false/missed events per minute. Never claims accuracy without verified gold.
"""
import argparse
import json
import math
from collections import defaultdict
from pathlib import Path
from performance_v1 import RATE,ROLES,read

GOLD_FORMAT='bitstream-performance-gold-v1'
TOLERANCES=(20,50)

def _better(a,b):
	"""More matches first, then less total absolute onset error."""
	if a[0]!=b[0]:return a[0]>b[0]
	return a[1]<b[1]

def match_events(predicted,gold,tolerance_frames):
	"""Monotonic max-cardinality, min-absolute-error matching.

	Musical onsets of the same pitch/class are temporally ordered; using
	DP avoids the many-to-one 'flam' matching that inflated old scores.
	"""
	n,m=len(predicted),len(gold)
	dp=[[(0,0) for j in range(m+1)] for i in range(n+1)]
	choices=[[None for j in range(m+1)] for i in range(n+1)]
	for i in range(n-1,-1,-1):
		for j in range(m-1,-1,-1):
			best=dp[i+1][j]
			move='skip-prediction'
			if _better(dp[i][j+1],best):
				best=dp[i][j+1];move='skip-gold'
			error=predicted[i]['startFrame']-gold[j]['startFrame']
			if abs(error)<=tolerance_frames:
				next_count,next_error=dp[i+1][j+1]
				option=(next_count+1,next_error+abs(error))
				if _better(option,best) or option==best:
					best=option;move='matched'
			dp[i][j]=best;choices[i][j]=move
	pairs=[]
	i=j=0
	while i<n and j<m:
		move=choices[i][j]
		if move=='matched':
			pairs.append((predicted[i],gold[j]))
			i+=1;j+=1
		elif move=='skip-prediction':i+=1
		else:j+=1
	return pairs

def _category(role,event):
	return event.get('class') if role=='drums' else event.get('pitch')

def validate_gold(gold,score):
	if not isinstance(gold,dict) or gold.get('format')!=GOLD_FORMAT or (
		gold.get('status')!='human-verified'):
		raise ValueError('Gold set is NOT verified')
	if gold.get('songId')!=score['songId'] or gold.get('baseScoreHash')!=score['scoreHash']:
		raise ValueError('Gold set does not reference this exact candidate score')
	if gold.get('sampleRate')!=RATE:
		raise ValueError('wrong gold reference sample rate')
	excerpts=gold.get('excerpts')
	if not isinstance(excerpts,list) or not excerpts:
		raise ValueError('missing gold excerpts')
	seen=set()
	for part in excerpts:
		id=part.get('id')
		if not isinstance(id,str) or not id or id in seen:raise ValueError('duplicate excerpt id')
		seen.add(id)
		a,b=part.get('startFrame'),part.get('endFrame')
		if not isinstance(a,int) or not isinstance(b,int) or not 0<=a<b<=score['frameCount']:
			raise ValueError('bad gold passage')
		if b-a>RATE*90:raise ValueError('gold excerpt longer than a single passage')
		annotations=part.get('annotations')
		if not isinstance(annotations,dict) or not annotations or (
			set(annotations)-set(ROLES)):
			raise ValueError('missing/invalid gold role annotations')
		for role,events in annotations.items():
			if not isinstance(events,list):raise ValueError('bad gold note list')
			for event in events:
				t=event.get('startFrame')
				if not isinstance(t,int) or not a<=t<b:
					raise ValueError('gold note outside excerpt')
				key=_category(role,event)
				if role=='drums':
					if key not in ('kick','snare','hat','tom','cymbal'):
						raise ValueError('bad gold drum class')
				elif not isinstance(key,int) or not 0<=key<=127:
					raise ValueError('bad gold pitch')
	return gold

def metrics(pairs,total_pred,total_gold,duration_frames):
	tp=len(pairs);fp=total_pred-tp;fn=total_gold-tp
	precision=tp/total_pred if total_pred else 1.0 if not total_gold else 0.
	recall=tp/total_gold if total_gold else 1.
	f1=(2*precision*recall/(precision+recall)) if precision+recall else 0.
	err=[(pred['startFrame']-gold['startFrame'])*1000/RATE
		for pred,gold in pairs]
	avg=sum(err)/len(err) if err else None
	sd=(math.sqrt(sum((v-avg)**2 for v in err)/len(err))) if err else None
	slope=None
	if len(pairs)>=3:
		x=[gold['startFrame']/RATE/60 for _,gold in pairs]
		mean_x=sum(x)/len(x)
		var=sum((v-mean_x)**2 for v in x)
		if var>1e-9:
			slope=sum((v-mean_x)*(e-avg) for v,e in zip(x,err))/var
	minutes=duration_frames/RATE/60
	return {
		'truePositive':tp,'falsePositive':fp,'falseNegative':fn,
		'precision':round(precision,6),'recall':round(recall,6),
		'f1':round(f1,6),
		'signedBiasMs':round(avg,3) if avg is not None else None,
		'jitterSdMs':round(sd,3) if sd is not None else None,
		'driftMsPerMinute':round(slope,3) if slope is not None else None,
		'falseEventsPerMinute':round(fp/minutes,3) if minutes else None,
		'missedEventsPerMinute':round(fn/minutes,3) if minutes else None,
	}

def evaluate(score,gold):
	validate_gold(gold,score)
	report={'format':'bitstream-performance-evaluation-v1',
		'songId':score['songId'],'candidateScoreHash':score['scoreHash'],
		'goldStatus':'human-verified','tolerancesMs':list(TOLERANCES),
		'excerpts':[],'aggregate':{}}
	total_duration=0
	all_groups={tol:{'pred':0,'gold':0,'pairs':[]} for tol in TOLERANCES}
	for excerpt in gold['excerpts']:
		a,b=excerpt['startFrame'],excerpt['endFrame']
		total_duration+=b-a
		item={'id':excerpt['id'],'startFrame':a,'endFrame':b,'roles':{},'metrics':{}}
		for role,human in excerpt['annotations'].items():
			candidates=[e for e in score['events'][role]
				if a<=e['startFrame']<b]
			item['roles'][role]={'predicted':len(candidates),'gold':len(human)}
		for tolerance in TOLERANCES:
			pairs=[]
			n_pred=n_gold=0
			for role,human in excerpt['annotations'].items():
				candidates=[e for e in score['events'][role] if a<=e['startFrame']<b]
				n_pred+=len(candidates);n_gold+=len(human)
				cat_pred=defaultdict(list);cat_human=defaultdict(list)
				for row in candidates:cat_pred[_category(role,row)].append(row)
				for row in human:cat_human[_category(role,row)].append(row)
				for category in cat_pred.keys()|cat_human.keys():
					h=sorted(cat_human[category],key=lambda row:row['startFrame'])
					p=sorted(cat_pred[category],key=lambda row:row['startFrame'])
					pairs.extend(match_events(p,h,round(tolerance*RATE/1000)))
			agg=all_groups[tolerance]
			agg['pred']+=n_pred;agg['gold']+=n_gold;agg['pairs'].extend(pairs)
			item['metrics'][str(tolerance)+'ms']=metrics(pairs,n_pred,n_gold,b-a)
		report['excerpts'].append(item)
	for tolerance,agg in all_groups.items():
		report['aggregate'][str(tolerance)+'ms']=metrics(agg['pairs'],
			agg['pred'],agg['gold'],total_duration)
	return report

def main():
	p=argparse.ArgumentParser(description=__doc__)
	p.add_argument('--performance',required=True,type=Path)
	p.add_argument('--gold',required=True,type=Path)
	p.add_argument('--out',type=Path,required=True)
	a=p.parse_args()
	if a.out.exists():raise FileExistsError('Never overwrite an evaluation report')
	score=read(a.performance)
	gold=json.loads(a.gold.read_text())
	report=evaluate(score,gold)
	a.out.write_text(json.dumps(report,indent=2)+'\n')
	print('MANUALLY_VERIFIED_GOLD_EVALUATION',a.out,
		json.dumps(report['aggregate'],sort_keys=True))

if __name__=='__main__':
	main()#!/usr/bin/env python3
"""Exact-source candidate performance v2 exporter — NEVER game music directly.

Reads immutable v1 captured score and all six original isolated FLAC stems,
verifies all source fingerprints, recomputes ONLY accompaniment, bass repeated
attacks and drum-family hits, then creates a *different*, immutable score with
experimental-candidate-unreviewed status. Melody and source hashes preserved.

The shipping JS pack validator intentionally refuses candidate quality; no
public music manifest is changed. Run on CT211 from private scratch tree.
"""
import argparse
import hashlib
import json
from pathlib import Path

from detector_candidate_v2 import accompaniment,bass_replucks,drum_simultaneous
from performance_v1 import (
	ROLES,STEMS,DETECTORS,from_legacy,read,to_legacy,verify_origin,
	sha256_file,write_new
)
from render_full_dynamic_orchestra_v1 import sample_mono

NEW_DETECTORS=dict(DETECTORS,**{
	'guitar':'experimental-v2-RMS-waveform-onsets-harmonic-pitch',
	'piano':'experimental-v2-RMS-waveform-onsets-harmonic-pitch',
	'other':'experimental-v2-RMS-waveform-onsets-harmonic-pitch',
	'bass':'experimental-v2-legacy-YIN-plus-regular-source-reattacks',
	'drums':'experimental-v2-independent-drum-families-echo-hypotheses',
})

def capture(song,master,packs,old_root,new_root,code_hash):
	id=song['id']
	manifest=json.loads((packs/song['manifest']).read_text())
	if manifest['id']!=id:raise ValueError('song manifest mismatch')
	roster=json.loads((master/'game-stems-manifest.json').read_text())
	source=next(t for t in roster['tracks'] if t['id']==id)
	stems=source['stem_files'] if source['slot']!=33 else source['grouped_6s']['stemFiles']
	source_paths={role:master/stems[role] for role in STEMS}
	old=read(old_root/Path(song['manifest']).parent/'performance.json')
	if old['quality']!='provisional-unreviewed':
		raise ValueError('parent is not immutable release score')
	verify_origin(old,id,manifest['frameCount'],old['featuredStem'],
		source_paths)
	result={role:to_legacy(old,role) for role in ROLES}
	diag={}
	for role in ('guitar','piano','other'):
		y=sample_mono(source_paths[role])
		if len(y)<20000:raise ValueError('source too short')
		result[role],diag[role]=accompaniment(y)
		del y
	for role,fn in (('bass',bass_replucks),('drums',drum_simultaneous)):
		y=sample_mono(source_paths[role])
		result[role],diag[role]=fn(y)
		del y
	if result['melody']!=to_legacy(old,'melody'):
		raise ValueError('candidate unexpectedly changed vocal/biome melody')
	for role in ROLES:
		if not result[role]:
			raise ValueError('empty candidate role: '+role)
		if role=='drums':
			position=[r['t'] for r in result[role]]
		else:
			position=[r['start'] for r in result[role]]
		if position!=sorted(position):
			raise ValueError('unordered candidate role: '+role)
	evidence=dict(old['provenance'].get('evidence',{}))
	evidence.update({
		'parentScoreHash':old['scoreHash'],
		'candidateDetectorSha256':code_hash,
		'candidateApproval':'NO — synthetic probes only, no verified real gold',
		'candidateMethod':'separate-bucket-analysis-v2-experiment',
		'goldAnnotations':'none',
	})
	score=from_legacy(id,old['frameCount'],old['featuredStem'],result,
		old['provenance']['sourceStemSha256'],extra_provenance=evidence,
		quality='experimental-candidate-unreviewed',
		detectors=NEW_DETECTORS)
	original_counts={role:len(old['events'][role]) for role in ROLES}
	new_counts={role:len(score['events'][role]) for role in ROLES}
	assert original_counts['melody']==new_counts['melody']
	# The file is explicitly NOT copied to public/music or a game pack.
	dest=new_root/Path(song['manifest']).parent/'performance-candidate-v2.json'
	write_new(dest,score)
	print('IMMUTABLE_CANDIDATE_EXPERIMENT',id,'hash',score['scoreHash'],
		'prior',original_counts,'candidate',new_counts,flush=True)
	return {'songId':id,'parentScoreHash':old['scoreHash'],
		'candidateScoreHash':score['scoreHash'],'candidateQuality':score['quality'],
		'previousCounts':original_counts,'newCounts':new_counts,
		'methodDiagnostics':diag}

def main():
	p=argparse.ArgumentParser(description=__doc__)
	p.add_argument('--master',type=Path,required=True)
	p.add_argument('--packs',type=Path,required=True)
	p.add_argument('--parent',type=Path,required=True)
	p.add_argument('--out',type=Path,required=True)
	p.add_argument('--song-id',action='append')
	a=p.parse_args()
	if a.out.exists():raise FileExistsError('Candidate output must be new')
	a.out.mkdir(parents=True)
	catalog=json.loads((a.packs/'catalog.json').read_text())
	code_hash=sha256_file(Path(__file__).with_name('detector_candidate_v2.py'))
	results=[]
	for song in catalog['tracks']:
		if a.song_id and song['id'] not in a.song_id:continue
		results.append(capture(song,a.master,a.packs,a.parent,a.out,code_hash))
	expected=len(a.song_id) if a.song_id else 4
	if len(results)!=expected:
		raise ValueError('wrong song count')
	index={'format':'bitstream-unapproved-candidate-index-v2',
		'quality':'experimental-candidate-unreviewed',
		'candidateDetectorSha256':code_hash,
		'artifactScope':'CT211 PRIVATE; not part of game; no audio rendered',
		'songResults':results}
	(a.out/'candidate-index.json').write_text(json.dumps(index,indent=2)+'\n')
	print('RESEARCH_CANDIDATES_ONLY_NOT_SHIPPED',len(results),flush=True)

if __name__=='__main__':
	main()#!/usr/bin/env python3
"""Freeze the exact CURRENT full-song release detector events in performance-v1.

This is a source score capture, not a better transcription or gold truth.
Reads six original stems and the original release vocal audit, runs the same
shipped release-v1 detectors, and stores content-addressed, private-path-free
immutable note/hit timelines. No re-rendering or original audio modification.
"""
import argparse
import inspect
import json
from pathlib import Path

from performance_v1 import ROLES,STEMS,from_legacy,write_new,sha256_file,verify_melody_audit
from render_full_dynamic_orchestra_v1 import (
	sample_mono,choose_feature_events,choose_bass_events,choose_drum_events
)
from render_additional_instruments_v1 import FEATURED

def build_song(song,roster,master,source_packs,melody_source,out,legacy_audit=None,
		extra_audit=None):
	id= song['id']
	relative=Path(song['manifest']).parent
	manifest=json.loads((source_packs/song['manifest']).read_text())
	if manifest['id']!=id or id not in FEATURED:
		raise ValueError('song/manifest identifier mismatch')
	original=next(row for row in roster['tracks'] if row['id']==id)
	stems=original['grouped_6s']['stemFiles'] if original['slot']==33 else original['stem_files']
	source_paths={role:master/stems[role] for role in STEMS}
	for role,path in source_paths.items():
		if not path.is_file():raise FileNotFoundError(f'{id} missing {role}')
	hashes={role:sha256_file(source_paths[role]) for role in STEMS}
	scores={}
	for role in ('guitar','piano','other'):
		score,stats=choose_feature_events(sample_mono(source_paths[role]))
		scores[role]=score
		print('EXTRACTED_RELEASE_NOTES',id,role,len(score),stats['sourceOnsets'],flush=True)
	scores['bass'],bs=choose_bass_events(sample_mono(source_paths['bass']))
	print('EXTRACTED_RELEASE_NOTES',id,'bass',len(scores['bass']),flush=True)
	scores['drums'],ds=choose_drum_events(sample_mono(source_paths['drums']))
	print('EXTRACTED_RELEASE_HITS',id,'drums',len(scores['drums']),flush=True)
	voice=melody_source/relative/'melody-audit-private.json'
	audit=json.loads(voice.read_text())
	if audit['song']!=id:
		raise ValueError('provisional melody score wrong song')
	scores['melody']=audit['notes']
	featured=FEATURED[id]
	if legacy_audit:
		legacy=legacy_audit['songs'][id]
		expected=legacy['noteCounts']
		for role,k in [('melody','melody'),('bass','bass'),
			('drums','drums'),(featured,'featured')]:
			if len(scores[role])!=expected[k]:
				raise ValueError(f'SHIPPED_RELEASE_EVENT_COUNT_MISMATCH {id} {role}: '
					f'{len(scores[role])} vs {expected[k]}')
	if extra_audit:
		legacy=extra_audit['songs'][id]
		for role,info in legacy['additionalParts'].items():
			if len(scores[role])!=info['notes']:
				raise ValueError(f'SHIPPED_EXTRA_EVENT_COUNT_MISMATCH {id} {role}')
	# Code provenance belongs to this release capture. Source stems,
	# model checkpoint and pre-existing vocal/YIN note audit must all be
	# accounted for, even though no later guessing changes these events.
	analyzer_file=Path(inspect.getsourcefile(choose_feature_events))
	result=from_legacy(id,manifest['frameCount'],featured,scores,hashes,{
		'melodyAuditSha256':sha256_file(voice),
		'releaseExtractorSha256':sha256_file(analyzer_file),
		'extractorSpec':'FFT1024@16kHz, 160-hop, YIN on bass/vocals; uncalibrated',
		'checkpoint':'no-neural-model-release-heuristics',
	})
	verify_melody_audit(result,voice)
	file=out/relative/'performance.json'
	write_new(file,result)
	print('PERFORMANCE_V1_CREATED',id,'sha256',result['scoreHash'],
		'counts',json.dumps({role:len(v) for role,v in result['events'].items()},
		sort_keys=True),'file',file,flush=True)
	return result

def main():
	p=argparse.ArgumentParser(description=__doc__)
	p.add_argument('--master',type=Path,required=True)
	p.add_argument('--source-packs',type=Path,required=True)
	p.add_argument('--melody-source',type=Path,required=True)
	p.add_argument('--out',type=Path,required=True)
	p.add_argument('--legacy-audit',type=Path)
	p.add_argument('--extra-audit',type=Path)
	p.add_argument('--song-id',action='append',help='optional repeatable song ID')
	a=p.parse_args()
	if a.out.exists():raise FileExistsError('Do not overwrite prior score capture')
	a.out.mkdir(parents=True)
	catalog=json.loads((a.source_packs/'catalog.json').read_text())
	roster=json.loads((a.master/'game-stems-manifest.json').read_text())
	legacy=json.loads(a.legacy_audit.read_text()) if a.legacy_audit else None
	extra=json.loads(a.extra_audit.read_text()) if a.extra_audit else None
	selected=[song for song in catalog['tracks']
		if not a.song_id or song['id'] in a.song_id]
	if not selected or (a.song_id and len(selected)!=len(set(a.song_id))):
		raise ValueError('unknown or repeated song ID')
	for song in selected:
		build_song(song,roster,a.master,a.source_packs,a.melody_source,
			a.out,legacy,extra)
	(a.out/'capture-manifest.json').write_text(json.dumps({
		'format':'bitstream-performance-capture-index-v1',
		'songIds':[song['id'] for song in selected],
		'algorithm':'exact original release v1 provisional MIDI extraction',
		'productionAudio':'unchanged',
		'manualGoldSet':'not yet annotated'
	},indent=2)+'\n')
	print('PERFORMANCE_V1_CAPTURE_PASS',len(selected),'songs',flush=True)

if __name__=='__main__':
	main()#!/usr/bin/env python3
"""Install verified full-length biome re-performance assets into public packs.

Original six song stem chunks never overwritten. New voice:<biome> sources
are explicit, and the adaptive manifest names five independent replacement instrument
recordings per biome (guitar, piano, other, bass, airborne drums).
Fails closed: rejects partial/missing/misaligned replacement families.
"""
import argparse
import json
import shutil
from pathlib import Path

BIOMES=(
	'debutmont','garbage-dump-glacier','pyramid-peak','underwater-mountain',
	'crystal-cavern','space-mountain','candy-cane-canyon',
	'sky-jellyfish-mountain','steampunk-slopes','micro-mountain','vertigo-vents',
)
ROLES=('featured','bass','drums','melody','guitar','piano','other')
FEATURED={
	'FEsxYVStla4':'other',
	'local-one-more-run-bitstream-bluffs':'piano',
	'WRBGQUqD54U':'guitar',
	'FYImnz5-hXs':'other',
}
def install(a):
	root=a.music_root
	catalog=json.loads((root/'catalog.json').read_text())
	assert len(catalog['tracks'])==4
	for track in catalog['tracks']:
		assert track['id'] in FEATURED,track['id']
		manifest=root/track['manifest']
		doc=json.loads(manifest.read_text())
		assert 'adaptive' not in doc, 'Do not overwrite an existing orchestra version'
		n=len(doc['segments'])
		assert n>=15
		rel=Path(track['manifest']).parent
		replacements=a.replacement_root/rel/'adaptive'
		dest=manifest.parent/'adaptive'
		assert not dest.exists(),dest
		mapping={role:{} for role in ('featured','bass','drums','guitar','piano','other')}
		melody={}
		roles=('featured','bass','drums','melody')+tuple(
			r for r in ('guitar','piano','other') if r!=FEATURED[doc['id']])
		extra=a.extra_root/rel/'adaptive'
		for biome in BIOMES:
			for role in roles:
				source_root=extra if role in ('guitar','piano','other') else replacements
				files=[source_root/biome/f'{role}-{i:04d}.ogg'
					for i in range(n)]
				if any(not file.is_file() or file.stat().st_size<=500
					for file in files):
					raise ValueError(f'Missing replacement {track["id"]} {biome} {role}')
				names=[f'adaptive/{biome}/{role}-{i:04d}.ogg'
					for i in range(n)]
				if role=='melody':
					melody[biome]=names
				else:
					mapping[role][biome]=names
		# Check all files for this pack BEFORE copying, and use a
		# temp directory so interruption doesn't publish a half-version.
		stage=manifest.parent/'adapt-staging'
		assert not stage.exists()
		shutil.copytree(replacements,stage)
		shutil.copytree(extra,stage,dirs_exist_ok=True)
		stage.rename(dest)
		for i,seg in enumerate(doc['segments']):
			for biome in BIOMES:
				seg['sources']['voice:'+biome]=melody[biome][i]
			assert len(seg['sources'])==18 # six original + home + eleven
		doc['adaptive']={'featuredStem':FEATURED[doc['id']],
			'variants':mapping}
		doc['orchestraVersion']='provisional-full-reperformance-v2'
		doc['scoreDisclaimer']='Source-derived automatic note estimates, NOT artist-verified. Original six stems retained. Dynamic Orchestra OFF plays original instrumental stems and biome melody; ON uses five genuine newly performed 11-biome instrumental recordings.'
		temp=manifest.with_suffix('.tmp')
		temp.write_text(json.dumps(doc,indent=2)+'\n')
		temp.replace(manifest)
		print('INSTALLED',doc['id'],n,'segments',len(BIOMES),
			'biomes',n*6*len(BIOMES),'replacement clips',flush=True)
	print('FOUR_FULL_DYNAMIC_ORCHESTRA_PACKS_INSTALLED',flush=True)

if __name__=='__main__':
	p=argparse.ArgumentParser(description=__doc__)
	p.add_argument('--music-root',required=True,type=Path)
	p.add_argument('--replacement-root',required=True,type=Path)
	p.add_argument('--extra-root',required=True,type=Path)
	install(p.parse_args())#!/usr/bin/env python3
"""Fixed audio segmentation: per-segment Opus encoder plus decoded frame gate.

The old ffmpeg '-f segment' on a continuous Opus stream produced 575688
decoded frames for nominal 576000 samples (6.5ms gap per 12s).
For a per-file encoder the Opus pre-skip/granule trim applies *per file*.
This module is shared by EVERY game melody/accompaniment/drum renderer.
"""
import subprocess
from pathlib import Path

import numpy as np


def decoded_frame_count(path,rate=48000,channels=2):
	result=subprocess.run([
		'ffmpeg','-hide_banner','-v','error','-nostdin',
		'-i',str(path),'-ac',str(channels),'-ar',str(rate),
		'-f','s16le','pipe:1'],
		capture_output=True,check=True,timeout=45)
	width=channels*2
	if len(result.stdout)%width:
		raise ValueError('Corrupt PCM decoder output: '+str(path))
	return len(result.stdout)//width


def encode_exact_segments(audio,dest,stem_name,segments,rate=48000,bitrate='52k'):
	"""Encode sample-accurate clips from full float32 stereo PCM; fail closed.

	The destination must not already contain files for this stem. The
	input audio must have precisely the expected number of frames.
	"""
	audio=np.asarray(audio,dtype='<f4')
	if audio.ndim!=2 or audio.shape[1]!=2 or not np.isfinite(audio).all():
		raise ValueError('Expected finite stereo PCM')
	if not segments or sum(seg['frames'] for seg in segments)!=audio.shape[0]:
		raise ValueError('Segment manifest does not match rendered PCM')
	dest=Path(dest)
	dest.mkdir(parents=True,exist_ok=True)
	for i,seg in enumerate(segments):
		path=dest/f'{stem_name}-{i:04d}.ogg'
		if path.exists():
			raise FileExistsError('Refusing overwriting audio: '+str(path))
		start=seg['startFrame']
		frames=seg['frames']
		if start<0 or frames<=0 or start+frames>len(audio):
			raise ValueError('Unsafe frame range')
		chunk=audio[start:start+frames]
		part=path.with_suffix('.part')
		try:
			result=subprocess.run([
				'ffmpeg','-hide_banner','-v','error','-nostdin','-y',
				'-f','f32le','-ar',str(rate),'-ac','2','-i','pipe:0',
				'-c:a','libopus','-application','audio','-b:a',bitrate,
				'-frame_duration','20','-vbr','on','-f','ogg',str(part)],
				input=chunk.tobytes(),capture_output=True,timeout=120)
			if result.returncode:
				raise RuntimeError(result.stderr.decode(errors='replace')[-900:])
			decoded=decoded_frame_count(part,rate)
			if decoded!=frames:
				raise ValueError('Decoded Opus frame count mismatch: '+str(part)+
					' actual='+str(decoded)+' required='+str(frames))
			part.rename(path)
		finally:
			if part.exists():
				part.unlink()
	return [f'{stem_name}-{i:04d}.ogg' for i in range(len(segments))]#!/usr/bin/env python3
"""Build a small, independent Opus music pack from validated Demucs six-stem masters.

Read-only master inputs; derivative output outside the source bank. No Demucs invocation.
"""
import argparse
import json
import os
import shutil
import subprocess
from pathlib import Path

STEMS = ("vocals", "drums", "bass", "guitar", "piano", "other")
RATE = 48000
CHANNELS = 2
SAMPLE_BYTES = 2 * CHANNELS


def require(condition, message):
	if not condition:
		raise ValueError(message)


def encode_segment(pcm, target, bitrate):
	command = [
		"ffmpeg", "-hide_banner", "-loglevel", "error", "-nostdin", "-y",
		"-f", "s16le", "-ar", str(RATE), "-ac", str(CHANNELS), "-i", "pipe:0",
		"-c:a", "libopus", "-application", "audio", "-b:a", bitrate,
		"-vbr", "on", "-f", "ogg", str(target),
	]
	result = subprocess.run(command, input=pcm, capture_output=True, check=False)
	if result.returncode:
		raise RuntimeError("ffmpeg encode failed: " + result.stderr.decode(errors="replace")[-1000:])


def build(root, out, slot, chunk_seconds, preview_seconds, bitrate):
	roster = json.loads((root / "game-stems-manifest.json").read_text())
	status = json.loads((root / "stem_status.json").read_text())
	track = next((t for t in roster["tracks"] if int(t["slot"]) == slot), None)
	require(track is not None, "Unknown roster slot")
	track_id = str(track["id"])
	checked = status["tracks"].get(track_id, {})
	require(checked.get("status") == "complete", "Track is not fully validated yet")
	details = checked["stems"]
	for stem in STEMS:
		path = root / track["stem_files"][stem]
		require(path.is_file(), "Missing " + str(path))
		require(details[stem]["sample_rate"] == 44100, "Unexpected master sample rate")
		require(details[stem]["channels"] == 2, "Unexpected channel count")
	require(len({details[s]["frames"] for s in STEMS}) == 1, "Master stems differ in length")
	total_source_frames = details["vocals"]["frames"]
	full_frames = round(total_source_frames * RATE / 44100)
	frame_limit = full_frames if preview_seconds <= 0 else min(full_frames, preview_seconds * RATE)
	chunk_frames = chunk_seconds * RATE
	counts = [min(chunk_frames, frame_limit - start) for start in range(0, frame_limit, chunk_frames)]
	require(bool(counts), "No source audio")
	name = f"{slot:02d}_{track_id}"
	pack_dir = out / "packs" / name
	require(not pack_dir.exists(), "Pack already exists: " + str(pack_dir))
	build_dir = out / "packs" / (".building-" + name)
	require(not build_dir.exists(), "Previous staging directory exists: " + str(build_dir))
	build_dir.mkdir(parents=True)
	try:
		segments = [
			{"startFrame": i * chunk_frames, "frames": frames, "sources": {}}
			for i, frames in enumerate(counts)
		]
		for stem in STEMS:
			input_file = root / track["stem_files"][stem]
			command = [
				"ffmpeg", "-hide_banner", "-loglevel", "error", "-nostdin",
				"-i", str(input_file), "-vn", "-ar", str(RATE),
				"-ac", str(CHANNELS), "-f", "s16le", "pipe:1",
			]
			proc = subprocess.Popen(command, stdout=subprocess.PIPE, stderr=subprocess.DEVNULL)
			try:
				for i, frames in enumerate(counts):
					pcm = proc.stdout.read(frames * SAMPLE_BYTES)
					require(len(pcm) == frames * SAMPLE_BYTES, "Unexpected EOF in " + stem)
					filename = f"{i:04d}-{stem}.ogg"
					encode_segment(pcm, build_dir / filename, bitrate)
					segments[i]["sources"][stem] = filename
			finally:
				if proc.stdout:
					proc.stdout.close()
				if proc.poll() is None:
					proc.terminate()
				proc.wait()
		pack = {
			"format": "bitstream-music-pack-v1",
			"id": track_id,
			"title": track["title"],
			"source": "Demucs htdemucs_6s / " + name,
			"sampleRate": RATE,
			"frameCount": frame_limit,
			"preview": preview_seconds > 0,
			"segments": segments,
		}
		(build_dir / "pack.json").write_text(json.dumps(pack, indent=2) + "\n")
		build_dir.rename(pack_dir)
	except BaseException:
		shutil.rmtree(build_dir, ignore_errors=True)
		raise
	catalog_file = out / "catalog.json"
	catalog = json.loads(catalog_file.read_text()) if catalog_file.exists() else {
		"format": "bitstream-music-catalog-v1", "tracks": []
	}
	previous = next((t for t in catalog["tracks"] if t["id"] == track_id), {})
	catalog["tracks"] = [t for t in catalog["tracks"] if t["id"] != track_id]
	# Repacking must not drop catalog-only metadata such as a confirmed youtubeId (billboard artwork, #54).
	extra = {k: v for k, v in previous.items() if k not in ("id", "title", "manifest")}
	catalog["tracks"].append({
		"id": track_id,
		"title": track["title"],
		**extra,
		"manifest": "packs/" + name + "/pack.json",
	})
	tmp = out / "catalog.json.tmp"
	tmp.write_text(json.dumps(catalog, indent=2) + "\n")
	tmp.replace(catalog_file)
	print(json.dumps({"pack": str(pack_dir), "segments": len(segments), "seconds": round(frame_limit/RATE, 2), "tracks": len(catalog["tracks"])}, indent=2))


def main():
	p = argparse.ArgumentParser(description=__doc__)
	p.add_argument("--root", type=Path, default=Path("/root/bitstream-maxi/launch32"))
	p.add_argument("--out", type=Path, required=True, help="New independent derivative directory")
	p.add_argument("--slot", type=int, required=True)
	p.add_argument("--chunk-seconds", type=int, default=10)
	p.add_argument("--preview-seconds", type=int, default=0, help="0 = full track")
	p.add_argument("--bitrate", default="80k")
	a = p.parse_args()
	require(a.chunk_seconds >= 2 and a.chunk_seconds <= 30, "chunk size must be 2..30 seconds")
	require(a.preview_seconds >= 0, "preview seconds cannot be negative")
	require(a.root.resolve() != a.out.resolve(), "Refusing to write to source bank")
	require(not a.root.resolve().is_relative_to(a.out.resolve()), "Output must not contain source bank")
	require(not a.out.resolve().is_relative_to(a.root.resolve()), "Output must be outside master bank")
	build(a.root, a.out, a.slot, a.chunk_seconds, a.preview_seconds, a.bitrate)


if __name__ == "__main__":
	main()#!/usr/bin/env python3
"""Canonical, versioned source-event score shared by game and offline rendering.

No detector is called from here. Scores contain the exact events the released
renderer consumed, now with integer 48kHz frames, uncalibrated detector
provenance, stable event identities and a fingerprint for correction layers.

An event ID is source-anchor based, not a random UUID. When a re-transcription
moves an onset, an old correction must report a conflict rather than silently
attaching to a different note. No private paths or raw source audio embedded.
"""
import copy
import hashlib
import json
import math
from collections import Counter
from pathlib import Path

FORMAT='bitstream-performance-v1'
ROLES=('melody','bass','drums','guitar','piano','other')
STEMS=('vocals','bass','drums','guitar','piano','other')
RATE=48000
DETECTORS={
	'melody':'release-v1-vocal-YIN-median9-45ms-merge',
	'bass':'release-v1-bass-YIN-median5-pitch-change',
	'drums':'release-v1-broadband-flux-10ms-one-hit-class',
	'guitar':'release-v1-fft1024-onset10ms-no-harmonic-summation',
	'piano':'release-v1-fft1024-onset10ms-no-harmonic-summation',
	'other':'release-v1-fft1024-onset10ms-no-harmonic-summation',
}
MAX_EVENTS_PER_ROLE=150000

def sha256_file(path):
	digest=hashlib.sha256()
	with Path(path).open('rb') as f:
		for block in iter(lambda:f.read(1024*1024),b''):
			digest.update(block)
	return digest.hexdigest()

def verify_origin(record,song_id,frame_count,featured,stems):
	"""Hard-fail when an archive's audio differs from captured score inputs."""
	validate(record)
	if record['songId']!=song_id or record['frameCount']!=frame_count:
		raise ValueError('song or sample count mismatch for score')
	if record['featuredStem']!=featured:
		raise ValueError('featured role mismatch for score')
	if set(stems)!=set(STEMS):raise ValueError('incomplete source stems')
	for role,path in stems.items():
		if sha256_file(path)!=record['provenance']['sourceStemSha256'][role]:
			raise ValueError('original source hash changed: '+role)
	return record

def verify_melody_audit(record,path):
	"""Source-YIN audit JSON is a necessary seventh provenance input."""
	actual=sha256_file(path)
	expected=record.get('provenance',{}).get('evidence',{}).get('melodyAuditSha256')
	if expected!=actual:
		raise ValueError('source melody audit changed since score capture')
	return record

def canonical(data):
	return json.dumps(data,ensure_ascii=False,sort_keys=True,
		separators=(',',':'),allow_nan=False).encode('utf-8')

def content_hash(data):
	return hashlib.sha256(canonical(data)).hexdigest()

def stable_id(song_id,role,event,collision):
	anchor={k:event[k] for k in ('startFrame','endFrame','pitch','class')
		if k in event}
	return role[:2]+'-'+hashlib.sha256(canonical(
		[song_id,role,anchor,collision])).hexdigest()[:20]

def _seconds_to_frame(value,frames):
	if not isinstance(value,(float,int)) or isinstance(value,bool) or not math.isfinite(value):
		raise ValueError('nonfinite event time')
	frame=round(value*RATE)
	if frame<0:return 0
	return min(frame,frames)

def from_legacy(song_id,frame_count,featured,events_by_role,source_hashes,extra_provenance=None,quality='provisional-unreviewed',detectors=None):
	"""Losslessly preserve legacy 4-decimal event times as integer samples.

	Return values reconstitute source times at 4 decimals and reproduce
	round(start * 48000); original release rendering seeds remain unchanged.
	Source hashes cover six isolated FLAC stems, without exposing paths.
	"""
	if featured not in ('guitar','piano','other'):
		raise ValueError('invalid featured role')
	if not isinstance(frame_count,int) or frame_count<1:
		raise ValueError('invalid song duration')
	if set(events_by_role)!=set(ROLES):raise ValueError('missing score roles')
	if set(source_hashes)!=set(STEMS):raise ValueError('missing source stems')
	if quality not in ('provisional-unreviewed','experimental-candidate-unreviewed'):
		raise ValueError('unapproved score creation quality')
	if detectors is not None and set(detectors)!=set(ROLES):
		raise ValueError('incomplete detector version roster')
	layers={}
	for role in ROLES:
		collisions=Counter()
		events=[]
		for idx,event in enumerate(events_by_role[role]):
			if role=='drums':
				start=_seconds_to_frame(event['t'],frame_count)
				if start>=frame_count:continue
				kind=event['type']
				if kind not in ('kick','snare','hat','tom','cymbal'):
					raise ValueError('unrecognized percussion family')
				item={'startFrame':start,'class':kind,'renderOrdinal':idx,
					'velocity':event.get('velocity') if isinstance(event.get('velocity'),int) else None,
					'confidence':None}
			else:
				start=_seconds_to_frame(event['start'],frame_count)
				end=_seconds_to_frame(event['end'],frame_count)
				if start>=frame_count or end<=start:continue
				pitch=int(event['midi'])
				if not 0<=pitch<=127:raise ValueError('out-of-range pitch')
				item={'startFrame':start,'endFrame':end,'pitch':pitch,
					'class':'note','renderOrdinal':idx,
					'velocity':None,'confidence':None}
				expression=event.get('expression')
				if expression and isinstance(expression.get('estimatedVelocity'),int):
					item['reportedHeuristicVelocity']=expression['estimatedVelocity']
				if 'confidence' in event:
					item['reportedHeuristicConfidence']=event['confidence']
			key=canonical({k:v for k,v in item.items() if k not in (
				'renderOrdinal','velocity','confidence','reportedHeuristicVelocity',
				'reportedHeuristicConfidence')})
			ordinal=collisions[key]
			collisions[key]+=1
			item['id']=stable_id(song_id,role,item,ordinal)
			events.append(item)
		layers[role]=events
	record={
		'format':FORMAT,'songId':song_id,'sampleRate':RATE,
		'frameCount':frame_count,'featuredStem':featured,
		'quality':quality,
		'calibratedConfidence':False,
		'clock':{'status':'unannotated','beats':[],'sections':[]},
		'harmony':{'status':'unannotated','chords':[]},
		'texture':{'status':'source-only','sourceRoles':['other']},
		'provenance':{
			'encoderRevision':'release-v1-score-capture',
			'sourceStemSha256':dict(sorted(source_hashes.items())),
			'evidence':dict(sorted((extra_provenance or {}).items())),
			'detectors':dict(sorted((detectors or DETECTORS).items())),
			'notes':'The release FFT/YIN estimators are approximate, NOT calibrated. '
				'No guessed confidence is treated as a probability; '
				'original note times, durations, pitches and order preserved.',
		},
		'events':layers,
	}
	record['scoreHash']=content_hash(record)
	validate(record)
	return record

def validate(record):
	if not isinstance(record,dict):raise ValueError('score not object')
	if record.get('format')!=FORMAT:raise ValueError('incorrect score format')
	if record.get('sampleRate')!=RATE:raise ValueError('wrong source sample rate')
	if not isinstance(record.get('songId'),str) or not record['songId']:
		raise ValueError('missing song id')
	if not isinstance(record.get('frameCount'),int) or record['frameCount']<1:
		raise ValueError('wrong duration')
	if record.get('quality') not in ('provisional-unreviewed','human-correction-layer-applied','experimental-candidate-unreviewed'):
		raise ValueError('unexpected approval metadata')
	if record['quality']=='human-correction-layer-applied' and (
		not isinstance(record.get('derivedFromScoreHash'),str) or
		len(record['derivedFromScoreHash'])!=64):
		raise ValueError('missing correction source hash')
	if record.get('calibratedConfidence') is not False:
		raise ValueError('uncalibrated score falsely claimed confidence')
	if record.get('featuredStem') not in ('guitar','piano','other'):
		raise ValueError('featured role invalid')
	if not isinstance(record.get('events'),dict) or set(record['events'])!=set(ROLES):
		raise ValueError('missing event families')
	prov=record.get('provenance',{})
	hashes=prov.get('sourceStemSha256',{})
	if not isinstance(hashes,dict) or set(hashes)!=set(STEMS):
		raise ValueError('incomplete source provenance')
	if any(not isinstance(v,str) or len(v)!=64 or any(c not in '0123456789abcdef' for c in v)
		for v in hashes.values()):
		raise ValueError('bad original source stem fingerprint')
	evidence=prov.get('evidence',{})
	if not isinstance(evidence,dict):
		raise ValueError('bad provenance evidence')
	for key,value in evidence.items():
		if key.endswith('Sha256') and (
			not isinstance(value,str) or len(value)!=64 or
			any(c not in '0123456789abcdef' for c in value)):
			raise ValueError('bad provenance evidence hash')

	seen=set()
	for role,events in record['events'].items():
		if not isinstance(events,list) or len(events)>MAX_EVENTS_PER_ROLE:
			raise ValueError('implausible role event count')
		for item in events:
			if not isinstance(item,dict):raise ValueError('event not object')
			start=item.get('startFrame')
			if not isinstance(start,int) or isinstance(start,bool) or not 0<=start<record['frameCount']:
				raise ValueError('invalid event start')
			end=item.get('endFrame')
			if role=='drums':
				if end is not None or item.get('class') not in ('kick','snare','hat','tom','cymbal'):
					raise ValueError('invalid percussion hit')
			else:
				if not isinstance(end,int) or end<=start or end>record['frameCount']:
					raise ValueError('invalid note release')
				if item.get('class')!='note' or not isinstance(item.get('pitch'),int) or not 0<=item['pitch']<=127:
					raise ValueError('invalid melodic note')
			if not isinstance(item.get('id'),str) or item['id'] in seen:
				raise ValueError('missing/duplicate event identity')
			seen.add(item['id'])
			if item.get('confidence') is not None:
				raise ValueError('uncalibrated confidence must be null')
			if item.get('velocity') is not None and (
				not isinstance(item['velocity'],int) or not 1<=item['velocity']<=127):
				raise ValueError('invalid velocity')
	expected=content_hash({k:v for k,v in record.items() if k!='scoreHash'})
	if expected!=record.get('scoreHash'):
		raise ValueError('score fingerprint mismatch')
	return record

def to_legacy(record,role):
	"""Convert one immutable candidate layer to the exact historic renderer API.

	Keeping renderOrdinal stable is required: v1 features fixed index-dependent
	velocity/pan and pseudo-random note excitation. Do NOT sort/reorder.
	"""
	validate(record)
	if role not in ROLES:raise ValueError('invalid role')
	out=[]
	for item in record['events'][role]:
		if role=='drums':
			out.append({'t':round(item['startFrame']/RATE,4),
				'type':item['class']})
		else:
			n={'start':round(item['startFrame']/RATE,4),
				'end':round(item['endFrame']/RATE,4),'midi':item['pitch']}
			if item.get('reportedHeuristicConfidence') is not None:
				n['confidence']=item['reportedHeuristicConfidence']
			if item.get('reportedHeuristicVelocity') is not None:
				n['expression']={'estimatedVelocity':item['reportedHeuristicVelocity']}
			out.append(n)
	return out

def write_new(path,record):
	path=Path(path)
	validate(record)
	path.parent.mkdir(parents=True,exist_ok=True)
	# Exclusive create: never clobber a historical score or corrected layer.
	with path.open('x',encoding='utf-8') as f:
		json.dump(record,f,ensure_ascii=False,indent=2,allow_nan=False)
		f.write('\n')
	return path

def read(path):
	return validate(json.loads(Path(path).read_text(encoding='utf-8')))

def apply_patch_layer(record,layer):
	"""Never silently apply edits against changed automatic scores.

	Explicit revision conflicts are returned and never discarded. The editor
	and human-acceptance workflow can be built against this stable contract.
	"""
	validate(record)
	if layer.get('format')!='bitstream-performance-patches-v1':
		raise ValueError('patch format')
	if layer.get('songId')!=record['songId']:
		raise ValueError('patch song mismatch')
	if layer.get('baseScoreHash')!=record['scoreHash']:
		return None,[{'reason':'base-score-changed','wanted':layer.get('baseScoreHash'),
			'actual':record['scoreHash']}]
	clean=copy.deepcopy(record)
	by_id={event['id']:(role,event) for role,events in clean['events'].items() for event in events}
	conflicts=[]
	edited=set()
	for op in layer.get('operations',[]):
		eid=op.get('id')
		if eid in edited:
			conflicts.append({'id':eid,'reason':'double-edit'});continue
		if eid not in by_id:
			conflicts.append({'id':eid,'reason':'missing-event'});continue
		action=op.get('action')
		role,event=by_id[eid]
		if action not in ('accept','reject','retime','octave','correct'):
			conflicts.append({'id':eid,'reason':'unsupported-operation'});continue
		if action=='correct':
			start,end,pitch=op.get('startFrame'),op.get('endFrame'),op.get('pitch')
			valid_start=isinstance(start,int) and not isinstance(start,bool) and 0<=start<record['frameCount']
			valid_end=role=='drums' and end is None or (
				role!='drums' and isinstance(end,int) and not isinstance(end,bool)
				and valid_start and start<end<=record['frameCount'])
			valid_pitch=role=='drums' and pitch is None or (
				role!='drums' and isinstance(pitch,int) and not isinstance(pitch,bool)
				and 0<=pitch<=127)
			if not (valid_start and valid_end and valid_pitch):
				conflicts.append({'id':eid,'reason':'invalid-combined-correction'});continue
			# Do not cross the onsets of adjacent source events; render
			# ordinal controls legacy timbre/pan and stays unchanged.
			ordered=clean['events'][role]
			index=next((i for i,e in enumerate(ordered) if e['id']==eid),None)
			if index is None or (index>0 and ordered[index-1]['startFrame']>start) or (
				index+1<len(ordered) and ordered[index+1]['startFrame']<start):
				conflicts.append({'id':eid,'reason':'would-cross-neighbor-onset'});continue
		if action=='retime':
			start,end=op.get('startFrame'),op.get('endFrame')
			if not isinstance(start,int) or start<0 or start>=record['frameCount'] or (
				role!='drums' and (not isinstance(end,int) or end<=start or end>record['frameCount'])):
				conflicts.append({'id':eid,'reason':'invalid-retiming'});continue
		if action=='octave' and (role=='drums' or op.get('offset') not in (-12,12)
			or not 0<=event['pitch']+op['offset']<=127):
			conflicts.append({'id':eid,'reason':'invalid-octave'});continue
		edited.add(eid)
		if action=='reject':
			clean['events'][role].remove(event)
		elif action=='accept':
			event['humanStatus']='accepted'
		elif action=='retime':
			event['startFrame']=start
			if role!='drums':event['endFrame']=end
			event['humanStatus']='corrected'
		elif action=='octave':
			event['pitch']+=op['offset']
			event['humanStatus']='corrected'
		elif action=='correct':
			event['startFrame']=start
			if role!='drums':
				event['endFrame']=end
				event['pitch']=pitch
			event['humanStatus']='corrected'
	if conflicts:return None,conflicts
	clean['quality']='human-correction-layer-applied'
	clean['derivedFromScoreHash']=record['scoreHash']
	# Preserve the source score; corrected scores are a new artifact.
	clean['scoreHash']=content_hash({k:v for k,v in clean.items() if k!='scoreHash'})
	try:
		validate(clean)
	except ValueError as exc:
		return None,[{'reason':'corrected-score-invalid','detail':str(exc)}]
	return clean,[]#!/usr/bin/env python3
"""Provisional independent performances for the two *unfeatured* parts.

On 11 biome instruments across 4 full songs, analyze each original source
instrument stem on its own, then render a completely new note waveform,
aligned to the existing 12s segmentation. This adds Guitar/Piano/Other real
instrument substitutions; the featured part already exists in V1.
All original masters, approved sample labs, and staging remain unchanged.
"""
import argparse
import json
from pathlib import Path

from render_full_dynamic_orchestra_v1 import (
	BIOMES, sample_mono, choose_feature_events, render_notes, encode_segments
)
from performance_v1 import read as read_performance,verify_origin,to_legacy,STEMS

INSTRUMENTS=('guitar','piano','other')
FEATURED={
	'FEsxYVStla4':'other',
	'local-one-more-run-bitstream-bluffs':'piano',
	'WRBGQUqD54U':'guitar',
	'FYImnz5-hXs':'other',
}

def render(a):
	if a.out.exists():
		raise FileExistsError('Never overwrite an earlier independent instrument render')
	a.out.mkdir(parents=True)
	catalog=json.loads((a.source_packs/'catalog.json').read_text())
	roster=json.loads((a.master/'game-stems-manifest.json').read_text())
	assert len(catalog['tracks'])==4
	report={'schemaVersion':1,'purpose':'source-independent score reconstruction of both unfeatured parts',
		'approval':'not artist-approved; source note guesses including octave errors; will re-render later',
		'songs':{}}
	for song in catalog['tracks']:
		id=song['id']
		assert id in FEATURED
		original=next(row for row in roster['tracks'] if row['id']==id)
		stem_files=(original['grouped_6s']['stemFiles'] if original['slot']==33
			else original['stem_files'])
		base=json.loads((a.source_packs/song['manifest']).read_text())
		frames=base['frameCount']
		n=len(base['segments'])
		assert frames>48000*90 and n>=15
		dest=a.out/Path(song['manifest']).parent/'adaptive'
		performance=None
		if a.performance_root:
			performance=read_performance(a.performance_root/Path(song['manifest']).parent/
				'performance.json')
			if performance['quality']!='provisional-unreviewed' and not a.allow_unapproved_scores:
				raise ValueError('Experimental/corrected score requires explicit '
					'--allow-unapproved-scores in private rendering only')
			verify_origin(performance,id,frames,FEATURED[id],{
				role:a.master/stem_files[role] for role in STEMS})
			print('LOCKED_EXTRA_SCORE',id,performance['scoreHash'],flush=True)
		elif not a.legacy_direct_extraction:
			raise ValueError('New releases require --performance-root; '
				'legacy direct extraction needs explicit --legacy-direct-extraction')
		counts={}
		for role in INSTRUMENTS:
			if role==FEATURED[id]: continue
			if performance:
				events=to_legacy(performance,role)
				details={'method':'content-addressed-performance-v1',
					'scoreHash':performance['scoreHash']}
			else:
				source=a.master/stem_files[role]
				events,details=choose_feature_events(sample_mono(source))
			if len(events)<80:
				raise ValueError('Too few note candidates for '+id+' '+role)
			counts[role]={'notes':len(events),'evidence':details}
			for biome in BIOMES:
				audio=render_notes(events,biome,frames,role)
				names=encode_segments(audio,dest/biome,role,base['segments'])
				assert len(names)==n
				print('EXTRA_REAL_INSTRUMENT',id,role,biome,len(names),
					flush=True)
		report['songs'][id]={'featured':FEATURED[id],
			'scoreHash':performance['scoreHash'] if performance else None,
			'additionalParts':counts}
	(a.out/'private-additional-audit.json').write_text(json.dumps(report,indent=2)+'\n')
	print('ALL_FOUR_SONGS_TWO_EXTRA_INSTRUMENT_PARTS_COMPLETED',flush=True)

if __name__=='__main__':
	p=argparse.ArgumentParser(description=__doc__)
	p.add_argument('--master',type=Path,required=True)
	p.add_argument('--source-packs',type=Path,required=True)
	p.add_argument('--out',type=Path,required=True)
	p.add_argument('--allow-unapproved-scores',action='store_true',
		help='PRIVATE AUDITION ONLY: permit experimental source candidates')
	group=p.add_mutually_exclusive_group(required=True)
	group.add_argument('--performance-root',type=Path)
	group.add_argument('--legacy-direct-extraction',action='store_true')
	render(p.parse_args())#!/usr/bin/env python3
"""Render REAL separate full-song replacement recordings for 11 biome families.

Private work-in-progress: source-driven note resynthesis is approximate, NOT
artist-approved. Retains all six original source stems independently.
The drums and bass are entirely newly generated, as is the primary featured
Guitar/Piano/Other part. Every mountain voice is also independently rendered.
No time-stretching/filtering of source stems counts as a replacement.
"""
import argparse
import hashlib
import json
import math
import subprocess
from pathlib import Path

import numpy as np
import librosa
from scipy.signal import find_peaks, resample_poly
from scipy.ndimage import median_filter

import render_biome_orchestras_v2 as orchestra
from performance_v1 import read as read_performance, verify_origin, verify_melody_audit, to_legacy, STEMS

RATE=48000
SYNTH_RATE=24000
HOP=160
EXTRACT_RATE=16000
BIOMES=orchestra.BIOMES
ROLES=('featured','bass','drums','melody')

def sample_mono(path):
	cmd=['ffmpeg','-v','error','-nostdin','-i',str(path),'-ar',
		str(EXTRACT_RATE),'-ac','1','-f','f32le','pipe:1']
	p=subprocess.run(cmd,capture_output=True,check=True,timeout=210)
	return np.frombuffer(p.stdout,dtype='<f4').copy()

def extract_onsets(y, min_distance=2):
	"""Onset grid is 10ms, with only 20ms refractory period."""
	spec=np.abs(librosa.stft(y,n_fft=1024,hop_length=HOP))
	flux=np.maximum(0,np.diff(np.log1p(spec*20),axis=1))
	strength=np.mean(flux,axis=0)
	if len(strength)<10: raise ValueError('Silent/short stem')
	threshold=float(np.percentile(strength,65))
	peaks,_=find_peaks(strength,distance=min_distance,
		prominence=max(.004,threshold*.20))
	seconds=(peaks+1)*HOP/EXTRACT_RATE
	return seconds,strength,spec

def choose_feature_events(y):
	"""Source-derived polyphonic pitch hypotheses, from actual stem attacks.

	At every source transient, take a few strong independent spectral peaks,
	with overtone suppression. Never invent note events on a fixed beat grid.
	This is experimental; model/stem leakage and harmonics are unverified.
	"""
	onsets,flux,spec=extract_onsets(y)
	freq=np.fft.rfftfreq(1024,1/EXTRACT_RATE)
	events=[]
	for i,sec in enumerate(onsets):
		center=round(sec*EXTRACT_RATE/HOP)
		left=max(0,center)
		right=min(spec.shape[1],center+8)
		if right<=left:continue
		spectrum=np.mean(spec[:,left:right],axis=1)
		peaks,_=find_peaks(spectrum,distance=2)
		peaks=[int(v) for v in peaks if 90<freq[v]<1900]
		peaks=sorted(peaks,key=lambda q:spectrum[q],reverse=True)
		if not peaks: continue
		selected=[]
		for idx in peaks:
			midi=int(round(69+12*math.log2(freq[idx]/440)))
			if not 41<=midi<=91:continue
			if any(abs(midi-m)<3 for m in selected):continue
			# Overtone suppression: don't add the octave when a much
			# stronger fundamental has already been picked.
			if any(abs(midi-m-12)<=1 for m in selected):continue
			selected.append(midi)
			if len(selected)>=2:break
		if not selected:continue
		duration=min(.7,max(.095,(onsets[i+1]-sec)*.85)) if i+1<len(onsets) else .3
		for midi in selected:
			events.append({'midi':midi,'start':round(float(sec),4),
				'end':round(float(sec+duration),4),'confidence':.72,
				'expression':{'estimatedVelocity':83}})
	return events,{'sourceOnsets':len(onsets),'hypothesizedNotes':len(events),
		'minimumOnsetSpacingMs':round(float(np.min(np.diff(onsets))*1000),1)
			if len(onsets)>1 else None}

def choose_bass_events(y):
	"""Estimate bass note fundamentals continuously, without a beat grid."""
	hop=320
	f0=librosa.yin(y.astype('float64'),fmin=38,fmax=320,
		sr=EXTRACT_RATE,hop_length=hop,frame_length=2048,center=True)
	rms=librosa.feature.rms(y=y,hop_length=hop,frame_length=2048)[0]
	n=min(len(f0),len(rms))
	f0=f0[:n];rms=rms[:n]
	threshold=max(.001,float(np.percentile(rms,82))*.15)
	notes=np.rint(librosa.hz_to_midi(np.clip(f0,38,320))).astype('int16')
	notes=median_filter(notes,size=5)
	notes[(rms<threshold)|~np.isfinite(f0)]=-1
	events=[]
	start=None;last=None
	for i,midi in enumerate(np.append(notes,-100)):
		if i<n and midi==last:continue
		if start is not None and last>=0:
			a=start*hop/EXTRACT_RATE
			b=i*hop/EXTRACT_RATE
			if b-a>=.08:events.append({'midi':int(last),
				'start':round(a,4),'end':round(b,4)})
		start=i;last=int(midi)
	return events,{'bassNotes':len(events),'minimumEnergy':round(threshold,6)}

def choose_drum_events(y):
	onsets,flux,spec=extract_onsets(y,min_distance=2)
	freq=np.fft.rfftfreq(1024,1/EXTRACT_RATE)
	out=[]
	for time in onsets:
		i=round(time*EXTRACT_RATE/HOP)
		window=spec[:,i:min(i+5,spec.shape[1])]
		if not window.size:continue
		pow=np.mean(window,axis=1)
		low=float(pow[freq<180].sum())
		mid=float(pow[(freq>=180)&(freq<1900)].sum())
		high=float(pow[freq>=1900].sum())
		kind='kick' if low>mid*1.05 else 'hat' if high>mid*1.2 else 'snare'
		out.append({'t':round(float(time),4),'type':kind})
	return out,{'drumHits':len(out),
		'minimumInterHitMs':round(float(np.min(np.diff(onsets))*1000),2)
			if len(onsets)>1 else None}

def render_notes(events,biome,frames,kind):
	"""Actual separately synthesized notes using the lab's individual
	physical-instrument models; not a filtered original recording."""
	mode=orchestra.CHARACTERS[biome][2]
	out=np.zeros((frames,2),dtype='float32')
	last_bong=-3.
	for index,note in enumerate(events):
		start=float(note['start'])
		end=float(note['end'])
		midi=int(note['midi'])
		if start>=frames/RATE or end<start+.075 or not 35<=midi<=98:
			continue
		pos=round(start*RATE)
		if pos>=frames:continue
		hold=min(2.0,max(.09,end-start))
		rng=np.random.default_rng(orchestra.stable_seed('full-v1',biome,
			kind,index,midi,round(start,3)))
		velocity=87 if kind=='melody' else 73
		voice=orchestra.corrected_note(midi,hold,velocity,mode,rng,'orchestral')
		voice=resample_poly(voice.astype('float32'),2,1)
		n=min(frames-pos,len(voice))
		pan=.5 if kind=='melody' else .28+.44*(index%7)/6
		left=math.cos(pan*math.pi/2)
		right=math.sin(pan*math.pi/2)
		amplitude=.25 if kind=='melody' else .20
		out[pos:pos+n,0]+=voice[:n]*left*amplitude
		out[pos:pos+n,1]+=voice[:n]*right*amplitude
		if kind=='melody' and mode=='holopad' and midi<=80 and start-last_bong>=1.45:
			bong=orchestra.crystal_bong(midi,velocity,rng)
			bong=resample_poly(bong,2,1)
			n=min(len(bong),frames-pos)
			out[pos:pos+n,:]+=bong[:n,None]*.045
			last_bong=start
	return out

def render_bass(events,biome,frames):
	mode=orchestra.CHARACTERS[biome][4]
	out=np.zeros((frames,2),dtype='float32')
	for note in events:
		start=float(note['start']);end=float(note['end'])
		pos=round(start*RATE)
		if pos>=frames or end-start<.06:continue
		freq=440*2**((int(note['midi'])-69)/12)
		if freq>165:freq/=2
		if freq<43:freq*=2
		n=min(round(min(1.5,end-start)*RATE),frames-pos)
		if n<=0:continue
		t=np.arange(n,dtype='float64')/RATE
		p=2*np.pi*freq*t
		s=.8*np.sin(p)
		if mode in ('saw','piston','volcanic','brass'):s+=.3*np.sin(2*p)+.16*np.sin(3*p)
		if mode in ('taffy','analog','pocket'):s+=.2*np.sin(2.01*p)
		if mode in ('liquid','breath','sineglass'):s+=.12*np.sin(.5*p)
		g=np.minimum(1,t/.012)*np.minimum(1,(n/RATE-t)/.12)
		s=(s*g*.135).astype('float32')
		out[pos:pos+n,0]+=s*.74
		out[pos:pos+n,1]+=s*.74
	return out

def render_drums(events,biome,frames):
	"""Entirely newly excited kick/snare/hat/tom sound sources,
	independently synthesized for each biome. 10ms source event grid.
	Original drum recording never enters this function."""
	_,_,_,foley,_=orchestra.CHARACTERS[biome]
	seed=orchestra.stable_seed('drums-full-v1',biome)
	rng=np.random.default_rng(seed)
	out=np.zeros((frames,2),dtype='float32')
	timbre={
		'wood':.35,'scrap':.87,'sistrum':.72,'bubble':.28,'glass':.74,
		'telemetry':.64,'wrapper':.83,'rain':.25,'gear':.9,
		'thimble':.76,'steam':.62,
	}.get(foley,.5)
	for event in events:
		pos=round(float(event['t'])*RATE)
		if not 0<=pos<frames:continue
		kind=event['type']
		duration={'kick':.14,'snare':.105,'hat':.052}.get(kind,.085)
		n=min(frames-pos,round(duration*RATE))
		t=np.arange(n,dtype='float64')/RATE
		if kind=='kick':
			freq=95*(1+t*25)**-.60
			s=np.sin(2*np.pi*np.cumsum(freq)/RATE)*np.exp(-t/0.055)
			s+=.10*rng.standard_normal(n)*np.exp(-t/.003)
			s*=.4
		else:
			noise=rng.standard_normal(n)
			tone=390+1250*timbre if kind=='snare' else 2400+2800*timbre
			s=(noise*(.24+.5*timbre)+
				np.sin(2*np.pi*tone*t)*(.8-.25*timbre))
			s*=np.exp(-t/(.026 if kind=='hat' else .048))*.11
		s*=np.minimum(1,t/.0007)
		out[pos:pos+n,0]+=(s*.80).astype('float32')
		out[pos:pos+n,1]+=(s*.72).astype('float32')
	return out

def encode_segments(audio,dest,stem_name,segments):
	"""Sample-exact independent Opus files, never ffmpeg segment muxer.

	Each file starts a NEW encoder so Opus pre-skip and end-granule trimming
	apply to its own exact source frames. Real decoded PCM count MUST match
	the corresponding pack.json segment length, including a partial tail.
	"""
	from opus_exact_segments import encode_exact_segments
	return encode_exact_segments(audio,dest,stem_name,segments,rate=RATE,bitrate='52k')


def run(a):
	if a.out.exists():raise FileExistsError(a.out)
	a.out.mkdir(parents=True)
	roster=json.loads((a.master/'game-stems-manifest.json').read_text())
	catalog=json.loads((a.source_packs/'catalog.json').read_text())
	report={'format':'bitstream-dynamic-orchestra-resynthesis-v1',
		'quality':'experimental, source onset/pitch hypotheses, NOT artist approved',
		'styles':'genuinely new independent biome instrumental recordings, not source FX',
		'songs':{}}
	for track in catalog['tracks']:
		source=next(x for x in roster['tracks'] if x['id']==track['id'])
		manifest=json.loads((a.source_packs/track['manifest']).read_text())
		frames=int(manifest['frameCount'])
		srcstem=source['stem_files'] if source['slot']!=33 else (
			source['grouped_6s']['stemFiles'])
		featured={'FEsxYVStla4':'other','local-one-more-run-bitstream-bluffs':'piano',
			'WRBGQUqD54U':'guitar','FYImnz5-hXs':'other'}[track['id']]
		performance=None
		if a.performance_root:
			performance=read_performance(a.performance_root/Path(track['manifest']).parent/
				'performance.json')
			if performance['quality']!='provisional-unreviewed' and not a.allow_unapproved_scores:
				raise ValueError('Experimental/corrected score requires explicit '
					'--allow-unapproved-scores in private rendering only')
			verify_origin(performance,track['id'],frames,featured,{
				role:a.master/srcstem[role] for role in STEMS})
			verify_melody_audit(performance,
				a.melody_source/Path(track['manifest']).parent/
				'melody-audit-private.json')
			feature_notes=to_legacy(performance,featured)
			bass_notes=to_legacy(performance,'bass')
			drum_notes=to_legacy(performance,'drums')
			melody_notes=to_legacy(performance,'melody')
			fs=bs=ds={'method':'content-addressed-performance-v1'}
			print('LOCKED_SCORE',track['id'],performance['scoreHash'],flush=True)
		else:
			if not a.legacy_direct_extraction:
				raise ValueError('New releases require --performance-root; '
					'legacy direct extraction needs explicit --legacy-direct-extraction')
			print('LEGACY_UNVERSIONED_EXTRACTION',track['id'],flush=True)
			feature_notes,fs=choose_feature_events(sample_mono(a.master/srcstem[featured]))
			bass_notes,bs=choose_bass_events(sample_mono(a.master/srcstem['bass']))
			drum_notes,ds=choose_drum_events(sample_mono(a.master/srcstem['drums']))
			melody_notes=json.loads((a.melody_source/Path(track['manifest']).parent/
				'melody-audit-private.json').read_text())['notes']
		scores={'featured':feature_notes,'bass':bass_notes,'drums':drum_notes,
			'melody':melody_notes}
		relative=Path(track['manifest']).parent
		dest=a.out/relative/'adaptive'
		for biome in BIOMES:
			for role in ROLES:
				if role in ('featured','melody'):
					audio=render_notes(scores[role],biome,frames,role)
				elif role=='bass':
					audio=render_bass(scores[role],biome,frames)
				else:
					audio=render_drums(scores[role],biome,frames)
				names=encode_segments(audio,dest/biome,role,manifest['segments'])
				print('REPERFORM',track['id'],biome,role,
					len(names),'segments',flush=True)
		report['songs'][track['id']]={'featuredStem':featured,
			'noteCounts':{k:len(v) for k,v in scores.items()},
			'extraction':{'featured':fs,'bass':bs,'drums':ds},
			'scoreHash':performance['scoreHash'] if performance else None,
			'biomes':len(BIOMES)}
	(a.out/'private-audit.json').write_text(json.dumps(report,indent=2)+'\n')
	print('TRUE_FULL_SONG_ORCHESTRA_COMPLETE',flush=True)

if __name__=='__main__':
	p=argparse.ArgumentParser(description=__doc__)
	p.add_argument('--master',required=True,type=Path)
	p.add_argument('--source-packs',required=True,type=Path)
	p.add_argument('--melody-source',required=True,type=Path)
	p.add_argument('--out',required=True,type=Path)
	p.add_argument('--allow-unapproved-scores',action='store_true',
		help='PRIVATE AUDITION ONLY: permit experimental source candidates')
	group=p.add_mutually_exclusive_group(required=True)
	group.add_argument('--performance-root',type=Path,
		help='Root of immutable versioned performance-v1 song scores')
	group.add_argument('--legacy-direct-extraction',action='store_true',
		help='Historical reproduction ONLY; bypasses canonical score capture')
	run(p.parse_args())#!/usr/bin/env python3
"""Offline, source-bound optional piano-friendly reinterpretation of One More Run.

Never edits original OGGs, release scores, beat grids, music packs, or gameplay.
Supports reproducible A/B/C listening extracts, a source-indexed contour
analysis JSON, and full-length additive MIDI/audio lead for a separate review.
"""
from __future__ import annotations
import argparse, hashlib, json, math, struct, subprocess
from pathlib import Path
import numpy as np
import librosa
from scipy.ndimage import median_filter

RATE=48000
PITCH_RATE=16000
HOP=160  # 10 ms source-contour frames
BPM_PROMPT=160
STEMS=('vocals','drums','bass','guitar','piano','other')
REVIEW_WINDOWS=((24.,48.),(60.,84.),(108.,132.),(144.,168.))


def read_ogg(path:Path,rate:int,channels:int=1)->np.ndarray:
	p=subprocess.run(['ffmpeg','-nostdin','-v','error','-i',str(path),
		'-ar',str(rate),'-ac',str(channels),'-f','f32le','pipe:1'],
		capture_output=True,timeout=35,check=True)
	data=np.frombuffer(p.stdout,'<f4').copy()
	return data.reshape(-1,channels) if channels>1 else data


def smooth_pitch(f0,rms,flatness):
	"""Use voice energy + spectral structure: never call all YIN f0 'voiced'."""
	f0=np.asarray(f0,dtype=np.float64)
	rms=np.asarray(rms,dtype=np.float64)
	flatness=np.asarray(flatness,dtype=np.float64)
	n=min(len(f0),len(rms),len(flatness))
	f0=f0[:n];rms=rms[:n];flatness=flatness[:n]
	floor=max(.0015,float(np.percentile(rms,76))*.22)
	mask=(rms>floor)&np.isfinite(f0)&(f0>=105)&(f0<=1050)&(flatness<.34)
	midi=69+12*np.log2(np.maximum(1e-9,f0)/440)
	# Ignore isolated octave errors and vibrato: medians performed only inside
	# continuously voiced islands so silence never becomes invented notes.
	midi=np.where(mask,midi,np.nan)
	return midi,mask,{'energyFloor':floor,'voicedFraction':float(mask.mean())}


def classify_contour(values:np.ndarray, times:np.ndarray):
	"""Classify one vocal phrase: long coherent rise vs tiny end-of-note scoop.

	Returns separate note-center and meaningful segment transitions; avoids
	inventing bend curves in the shipping integer-note performance schema.
	"""
	assert len(values)==len(times) and len(values)>0
	valid=np.isfinite(values)
	if valid.sum()<5:return {'kind':'unvoiced','stable':None,'transitions':[]}
	v=values[valid];t=times[valid]
	L=len(v)
	middle=v[int(.25*L):max(int(.75*L),int(.25*L)+1)]
	center=float(np.median(middle))
	stable=int(np.rint(center))
	duration=float(t[-1]-t[0]+.01)
	initial=float(np.median(v[:max(2,int(.17*L))]))
	final=float(np.median(v[-max(2,int(.13*L)):]))
	terminal=final-center
	start=initial-center
	# A dramatic start glide must be coherent and land on a sustainable note;
	# a tiny or short terminal scoop is not a structural new piano note.
	# The *stable destination* must occupy at least ~80 ms.
	end_section=v[max(0,int(.65*L)):]
	steady_end=bool(len(end_section)>=8 and np.median(np.abs(end_section-np.median(end_section)))<.8)
	transitions=[]
	kind='steady'
	if duration>=.19 and abs(start)>=1.55 and steady_end:
		limit=min(len(v)-1,max(5,int(.43*L)))
		line=v[:limit]
		trend=np.sign(center-initial)
		if trend and float((np.diff(line)*trend>.025).mean())>=.52:
			# Prefer the audible start anchor of a deliberate rise/fall,
			# not the median halfway through the singer's fast initial bend.
			lead=v[:max(3,int(.07*L))]
			# The early stable starting pitch of a genuine glide matters.
			# Median of a few beginning samples is less noisy than a minimum.
			start_anchor=np.median(lead)
			from_pitch=int(np.rint(start_anchor));to_pitch=stable
			if from_pitch!=to_pitch:
				kind='structural-onset-glide'
				transitions=[{'fromPitch':from_pitch,'toPitch':to_pitch,
					'slideSeconds':min(.3,max(.07,duration*.36))}]
	if kind=='steady' and abs(terminal)>=.55 and duration>=.17:
		kind='terminal-ornament-removed'
	return {'kind':kind,'stable':stable,'transitions':transitions,
		'initialCents':round(start*100), 'terminalCents':round(terminal*100),
		'durationSeconds':round(duration,3)}


def segment_notes(midi:np.ndarray,mask:np.ndarray,hop_seconds=.01):
	"""Segment robust note centers, retaining source reattacks and rests.

	Disjoint voiced islands are NOT merged across a genuine >=70ms rest.
	Consecutive rapid pitch excursions are held as candidate phrases rather
	than emitted as dozens of detuned notes.
	"""
	midi=np.asarray(midi,dtype=np.float64)
	mask=np.asarray(mask,dtype=bool)
	assert len(mask)==len(midi)
	# A 7-frame median suppresses transitory pitch/voicedness flutters.
	voiced=median_filter(mask.astype('uint8'),size=7,mode='nearest')>0
	runs=[];start=None
	for i,active in enumerate(np.r_[voiced,False]):
		if active and start is None:start=i
		elif not active and start is not None:
			if (i-start)*hop_seconds>=.075:runs.append((start,i))
			start=None
	result=[]
	for start,end in runs:
		vals=midi[start:end];frames=np.arange(start,end)*hop_seconds
		# Remove detectors' missed frames without smoothing across silence.
		good=np.isfinite(vals)
		if good.sum()<8:continue
		centered=vals.copy()
		for x in np.where(~good)[0]:
			near=np.where(good)[0];centered[x]=vals[near[np.argmin(np.abs(near-x))]]
		centered=median_filter(centered,size=9,mode='nearest')
		# Split on a center step only when it is sustained: unlike turning
		# every vibrato cycle into a new note, this requires >=100ms.
		labels=np.rint(centered).astype(int)
		starts=[0]
		minlen=max(9,int(.095/hop_seconds))
		for j in range(minlen,len(labels)-minlen):
			before=int(np.rint(np.median(centered[max(0,j-minlen):j])))
			after=int(np.rint(np.median(centered[j:j+minlen])))
			if abs(after-before)>=1 and after!=before and j-starts[-1]>=minlen and np.median(np.abs(centered[j:j+minlen]-after))<.45:
				starts.append(j)
		starts.append(len(labels))
		for a,b in zip(starts[:-1],starts[1:]):
			if (b-a)*hop_seconds<.075:continue
			segvals=centered[a:b]
			info=classify_contour(segvals,np.arange(start+a,start+b)*hop_seconds)
			if info['stable'] is None:continue
			result.append({'start':round((start+a)*hop_seconds,5),
				'end':round((start+b)*hop_seconds,5),
				'pitch':info['stable'],'kind':info['kind'],
				'transitions':info['transitions'],
				'initialCents':info['initialCents'],
				'terminalCents':info['terminalCents']})
	return result


def extract_source(pack:Path,segments:list,stem:str,rate:int):
	parts=[];hashes=[]
	for i,seg in enumerate(segments):
		f=pack/seg['sources'][stem]
		assert f.is_file(),f
		hashes.append(hashlib.sha256(f.read_bytes()).hexdigest())
		part=read_ogg(f,rate)
		# Convert exact 48 kHz pack-length source durations at target sample rate,
		# because decoded Opus final padding must not drift segment boundaries.
		length=round(seg['frames']*rate/RATE)
		if len(part)<length-4:raise ValueError(f'Short original OGG: {f} {len(part)} < {length}')
		parts.append(np.pad(part[:length],(0,max(0,length-len(part)))))
	return np.concatenate(parts),hashes


def notes_from_original(pack:Path,meta:dict):
	vocals,hashes=extract_source(pack,meta['segments'],'vocals',PITCH_RATE)
	print('VOCAL_SOURCE_READ',len(vocals),len(hashes),flush=True)
	# Full track one reference source clock; use deterministic librosa YIN.
	f0=librosa.yin(vocals.astype(np.float64),fmin=105,fmax=1050,
		sr=PITCH_RATE,frame_length=2048,hop_length=HOP,center=True,trough_threshold=.15)
	rms=librosa.feature.rms(y=vocals,frame_length=2048,hop_length=HOP,center=True)[0]
	# Flatness is only a weak voicing indicator; never claim gold transcription.
	flat=librosa.feature.spectral_flatness(y=vocals,n_fft=2048,
		hop_length=HOP,center=True)[0]
	midi,mask,stats=smooth_pitch(f0,rms,flat)
	notes=segment_notes(midi,mask)
	stats.update({'rawVoicedFrames':int(np.isfinite(midi).sum()),
		'rawPitchFrames':int(len(f0)),'noteCount':len(notes),
		'candidateStructuralGlides':sum(x['kind']=='structural-onset-glide' for x in notes),
		'candidateTerminalScoopsRemoved':sum(x['kind']=='terminal-ornament-removed' for x in notes)})
	return notes,stats,hashes


def piano_wave(freq,n):
	"""Simple original soft hammer-like harmonic piano approximation."""
	t=np.arange(n,dtype=np.float64)/RATE
	phase=2*np.pi*freq*t
	# This is an intentionally original synthetic instrument, not a sampled
	# acoustic grand. Fast attack + percussive exponential decay/release.
	partial=(.78*np.sin(phase)+.33*np.sin(2*phase)*np.exp(-2.5*t)+
		.16*np.sin(3*phase)*np.exp(-4*t)+.05*np.sin(4*phase)*np.exp(-5*t))
	decay=np.exp(-1.25*t)
	gate=np.minimum(1,t/.009)
	return partial*decay*gate


def performance_events(notes,mode):
	"""Pure score-to-piano event transform with optional staircase glides."""
	out=[]
	for i,n in enumerate(notes):
		start=float(n['start']);end=float(n['end']);pitch=int(n['pitch'])
		if not (0<=pitch<=127 and end>start):continue
		trans=n['transitions'] if mode=='expressive' else []
		if trans and (end-start)>.20:
			tr=trans[0];begin=int(tr['fromPitch']);target=int(tr['toPitch'])
			steps=min(4,abs(target-begin))
			step_len=min(.065,(end-start)*.35/max(1,steps))
			for k in range(steps):
				f=(k+0.5)/steps
				p=int(np.rint(begin+(target-begin)*f))
				out.append((start+k*step_len,start+(k+1)*step_len,p))
			start+=steps*step_len
		out.append((start,end,pitch))
	return out


def render_events(events,duration,volume=.17):
	N=round(duration*RATE)
	y=np.zeros(N,dtype=np.float32)
	for start,end,pitch in events:
		a=max(0,int(round(start*RATE)));b=min(N,int(round(end*RATE)))
		if b-a<120:continue
		freq=440*2**((pitch-69)/12)
		z=piano_wave(freq,b-a)
		# Short, bounded release to avoid discontinuities between reattacks.
		fade=min(int(.035*RATE),len(z)//2)
		z[-fade:]*=np.linspace(1,0,fade)
		y[a:b]+=np.asarray(z*volume,dtype=np.float32)
	return np.clip(y,-.90,.90)


def write_midi(events,path):
	"""Editable SMF0 percussion-independent piano take at 160 BPM.

	MIDI generation tempo is informational; precise source event seconds are
	mapped through that MIDI tempo without claiming a verified beat grid.
	"""
	def vlq(v):
		v=int(v);b=[v&127];v>>=7
		while v:b.insert(0,(v&127)|128);v>>=7
		return bytes(b)
	def tick(sec):return int(round(sec*(160/60)*480))
	ev=[(0,0,b'\xff\x51\x03'+int(60e6/BPM_PROMPT).to_bytes(3,'big')),
		(0,1,bytes([0xc0,0]))]
	for a,b,p in events:
		if b<=a:continue
		ev.extend([(tick(a),3,bytes((0x90,p,92))),
			(tick(b),2,bytes((0x80,p,0)))])
	ev.sort(key=lambda x:(x[0],x[1]))
	blob=bytearray();pos=0
	for t,_,data in ev:
		blob+=vlq(t-pos)+data;pos=t
	blob+=b'\x00\xff\x2f\x00'
	path.write_bytes(b'MThd'+struct.pack('>IHHH',6,0,1,480)+b'MTrk'+struct.pack('>I',len(blob))+blob)


def write_mp3(path,signal,channels=2):
	data=np.clip(signal,-.985,.985)
	if data.ndim==1 and channels==2:data=np.stack((data,data),axis=1)
	proc=subprocess.run(['ffmpeg','-nostdin','-v','error','-y','-f','f32le',
		'-ar',str(RATE),'-ac',str(channels),'-i','pipe:0','-codec:a','libmp3lame',
		'-q:a','4',str(path)],input=data.astype('<f4').tobytes(),
		capture_output=True,timeout=75)
	if proc.returncode:raise RuntimeError(proc.stderr.decode()[:500])


def main():
	a=argparse.ArgumentParser()
	a.add_argument('--source-pack',type=Path,required=True)
	a.add_argument('--out',type=Path,required=True)
	args=a.parse_args()
	pack=args.source_pack
	meta=json.loads((pack/'pack.json').read_text())
	if meta.get('id')!='local-one-more-run-bitstream-bluffs':raise ValueError('Wrong source pack')
	assert meta['sampleRate']==RATE
	duration=meta['frameCount']/RATE
	if abs(duration-174.6)>1e-4:raise ValueError('Unexpected source duration')
	out=args.out;out.mkdir(parents=True,exist_ok=True)
	if list(out.iterdir()):raise FileExistsError('Refuse to overwrite nonempty output: '+str(out))
	notes,stats,hashes=notes_from_original(pack,meta)
	print('NOTES',stats,flush=True)
	if len(notes)<80:raise RuntimeError('Sparse source analysis, refusing fake melody')
	preview={'format':'bitstream-piano-friendly-source-contour-research-v1',
		'kind':'UNVERIFIED_PROVISIONAL_LISTENING_EXPERIMENT_NOT_RELEASE_SCORE',
		'songId':meta['id'],'sourceManifestSha256':hashlib.sha256((pack/'pack.json').read_bytes()).hexdigest(),
		'vocalOggSegmentHashes':hashes,'samplingHz':PITCH_RATE,
		'pitchHopSeconds':HOP/PITCH_RATE,'generator':'librosa.YIN+flatness+RMS+median+note-center',
		'intendedSunoPromptBpm':BPM_PROMPT,
		'timingQuantization':'No beat-grid snapping: exact source phrase starts retained because released beat phase unverified',
		'pitchQuantization':'nearest equal-temperament semitone; separate expressive glides rendered as piano-note staircase',
		'notes':notes,'analysis':stats}
	(out/'unverified-source-contour.json').write_text(json.dumps(preview,indent=2)+'\n')
	flat_events=performance_events(notes,'piano')
	expressive_events=performance_events(notes,'expressive')
	write_midi(flat_events,out/'B_piano_friendly_160bpm.mid')
	write_midi(expressive_events,out/'C_selective_glides_160bpm.mid')
	print('MIDI_WRITTEN',len(flat_events),len(expressive_events),flush=True)
	# Render one coherent melody clock, never a per-section restarted voice.
	flat=render_events(flat_events,duration)
	exp=render_events(expressive_events,duration)
	# Snapshot original source *accompaniment* only for the selected windows.
	# No original-song or original-vocal OGG is ever overwritten or re-encoded
	# into the game. User-owned review copies are kept on isolated feature branch.
	results=[]
	for k,(start,end) in enumerate(REVIEW_WINDOWS,1):
		start_frame=round(start*RATE);end_frame=round(end*RATE)
		accomp=np.zeros((end_frame-start_frame,2),dtype=np.float32)
		orig_vocals=np.zeros_like(accomp)
		for stem in STEMS:
			for i,seg in enumerate(meta['segments']):
				seg_start=seg['startFrame'];seg_end=seg_start+seg['frames']
				lo=max(start_frame,seg_start);hi=min(end_frame,seg_end)
				if hi<=lo:continue
				path=pack/seg['sources'][stem]
				original=read_ogg(path,RATE,2)
				part=original[lo-seg_start:hi-seg_start]
				if len(part)!=hi-lo:raise ValueError('OGG sample clock mismatch')
				if stem=='vocals':orig_vocals[lo-start_frame:hi-start_frame]+=part
				else:accomp[lo-start_frame:hi-start_frame]+=part
		# one gain across ALL variations, not each independently mastered
		base=.55*accomp
		variants={'A_original_song_vocals':base+.55*orig_vocals,
			'B_piano_friendly':base+flat[start_frame:end_frame,None],
			'C_selective_glides':base+exp[start_frame:end_frame,None]}
		common_gain=min(1.,.92/max(float(np.max(np.abs(v))) for v in variants.values()))
		files=[]
		for label,source in variants.items():
			path=out/f'window{k}_{int(start):03d}-{int(end):03d}_{label}.mp3'
			write_mp3(path,source*common_gain)
			files.append({'name':path.name,'sha256':hashlib.sha256(path.read_bytes()).hexdigest(),
				'peak':round(float(np.max(np.abs(source*common_gain))),3)})
		print('WINDOW_READY',k,start,end,'files',len(files),flush=True)
		results.append({'index':k,'originalStartSeconds':start,'originalEndSeconds':end,
			'commonGain':round(common_gain,4),'files':files})
	(out/'README.md').write_text('# One More Run — optional piano-friendly melody audition\n\n'
		'**Research only**. Source-original vocals vs piano-friendly and selectively expressive piano interpretations.\n'
		'Preserves the actual source-note timing (the 160 BPM Suno prompt is not a beat-grid phase).\n'
		'All audio derives from the same user-owned OGG pack; synthetic piano sound, not an acoustic grand.\n'
		'No game/runtime changes, original files or released scores altered. Human note accuracy not verified.\n\n'
		+''.join(f'## Window {x["index"]}: {x["originalStartSeconds"]:.0f}–{x["originalEndSeconds"]:.0f}s\n'+
		''.join(f'- [{y["name"]}]({y["name"]})\n' for y in x['files'])+'\n' for x in results)
		+'Editable research-only MIDI: [piano-friendly](B_piano_friendly_160bpm.mid), '
		'[selective glides](C_selective_glides_160bpm.mid).\n'
		'Pitch contour and source stem SHA evidence: [source notes](unverified-source-contour.json).\n')
	(out/'manifest.json').write_text(json.dumps({'research':preview['kind'],
		'sourceManifestSha256':preview['sourceManifestSha256'],
		'notes':stats,'windows':results},indent=2)+'\n')
	print('ALL_COMPLETE',len(results),'WINDOWS',flush=True)

if __name__=='__main__':main()#!/usr/bin/env python3
"""Three source-grounded comparative drum count-ins for Marvin.

Research clips ONLY. Uses actual local One More Run OGG stems unchanged.
One recorded MIDI event sequence is also saved as a standard format-0 SMF.
No modifications to original assets, score, music engine, or main.
"""
from pathlib import Path
import os
from subprocess import run
from hashlib import sha256
import json
import math
import struct
import wave
import numpy as np
from scipy import signal

REPO=Path(__file__).resolve().parents[2]
ROOT=Path(os.environ.get('BITSTREAM_MUSIC_SOURCE_DIR',str(REPO/'public/music/packs/33_local-one-more-run-bitstream-bluffs')))
OUT=Path(os.environ.get('BITSTREAM_DRUM_PREVIEW_OUTPUT',str(REPO/'docs/music-review/drum-countin-ab-20261119')))
OUT.mkdir(parents=True,exist_ok=True)
RATE=48000
BPM=160
BEAT=60/BPM
CRASH_AT=.9
DRUMS_AT=CRASH_AT+.205+2*BEAT
BAND_AT=DRUMS_AT+4*BEAT
DURATION=BAND_AT+2.4
START=61.8
COUNT=int(round(DURATION*RATE))
SOURCE_START=int(round((START-60)*RATE))
STEMS={'drums':'drums','bass':'bass','guitar':'guitar','piano':'piano','other':'other','melody':'voice-home'}
LEVELS={'drums':1.,'bass':.84,'guitar':.9,'piano':.8,'other':.72,'melody':.72}
RNG=np.random.default_rng(20261119)

def decode(path):
	cmd=['ffmpeg','-v','error','-i',str(path),'-ar',str(RATE),'-ac','2','-f','f32le','pipe:1']
	p=run(cmd,capture_output=True,check=True,timeout=25)
	return np.frombuffer(p.stdout,dtype='<f4').reshape(-1,2).copy()

sources={}
for role,name in STEMS.items():
	f=ROOT/f'0005-{name}.ogg'
	assert f.exists(),f
	a=decode(f)
	assert len(a)>SOURCE_START+COUNT,(f,len(a),SOURCE_START+COUNT)
	sources[role]=a
	print('ORIGINAL_AUDIO',role,sha256(f.read_bytes()).hexdigest()[:20], 'frames',len(a))

# Continuous source soundtrack position remains identical across A/B/C.
# The same original audio's exact pre-crash and post-count-in remains audible.
context=np.zeros((COUNT,2),np.float64)
for role,volume in LEVELS.items():
	context+=volume*sources[role][SOURCE_START:SOURCE_START+COUNT]
# Band disappears while evaluating the count-in; short click-free ramps.
env=np.zeros(COUNT,dtype=np.float64)
pre=int(CRASH_AT*RATE)
post=int(BAND_AT*RATE)
env[:pre]=1.
fade=round(.014*RATE)
env[pre-fade:pre]=np.linspace(1,0,fade)
env[post:]=1.
env[post:post+fade]=np.linspace(0,1,fade)

# Natural version: ONLY original drums, exactly their continuous segment.
audio_natural=np.zeros((COUNT,2),np.float64)
audio_natural[int(DRUMS_AT*RATE):int(BAND_AT*RATE)]=sources['drums'][SOURCE_START+int(DRUMS_AT*RATE):SOURCE_START+int(BAND_AT*RATE)]
fade10=round(.008*RATE)
start=int(DRUMS_AT*RATE)
end=int(BAND_AT*RATE)
audio_natural[start:start+fade10]*=np.linspace(0,1,fade10)[:,None]
audio_natural[end-fade10:end]*=np.linspace(1,0,fade10)[:,None]

# MIDI file: humanized but explicitly authored FOUR-BEAT sample-kit performance.
# Standard percussion MIDI channel 10, 160 BPM, meaningful drum note/velocity.
# The render is a freshly synthesized original kit, not MIDI decoded from stem.
notes=[
	(0.,36,114,.17),(0.,42,80,.07),
	(.5,42,41,.055),
	(1.,38,114,.14),(1.,42,84,.07),
	(1.5,42,47,.055),
	(2.,36,118,.18),(2.,42,92,.075),
	(2.5,38,39,.09),(2.5,42,56,.055),
	(3.,38,124,.15),(3.,36,91,.15),(3.,46,80,.19),
]
# Event sequence with integer ticks, tempo meta event, end of track.
def vlq(v):
	v=int(v);b=[v&0x7f];v>>=7
	while v:b.insert(0,(v&0x7f)|0x80);v>>=7
	return bytes(b)

events=[(0,0,b'\xff\x51\x03'+(375000).to_bytes(3,'big'))]
for beat,note,velocity,length in notes:
	on=int(round(beat*480));off=int(round((beat+length/BEAT)*480))
	events.append((on,2,bytes((0x99,note,velocity))))
	events.append((off,1,bytes((0x89,note,0))))
events.sort(key=lambda x:(x[0],x[1]))
track=bytearray();previous=0
for tick,_,message in events:
	track.extend(vlq(tick-previous));track.extend(message);previous=tick
track.extend(b'\x00\xff\x2f\x00')
mid=(b'MThd'+struct.pack('>IHHH',6,0,1,480)+b'MTrk'+struct.pack('>I',len(track))+track)
(OUT/'B_recorded-midi-drum-performance_160bpm.mid').write_bytes(mid)

def note_kit(note,vel):
	# Fully original synthesized test kit, using note/velocity information
	# from MIDI events (kick GM36, snare 38, hats 42/46).
	sec={36:.27,38:.24,42:.105,46:.22}[note]
	t=np.arange(int(sec*RATE),dtype=np.float64)/RATE
	seed=int(note*20000+vel*101)
	rng=np.random.default_rng(seed)
	noise=rng.normal(0,1,len(t))
	if note==36:
		freq=47+75*np.exp(-t*31)
		phase=2*np.pi*np.cumsum(freq)/RATE
		body=np.sin(phase)*np.exp(-t*21)
		click=signal.sosfilt(signal.butter(2,1500,btype='highpass',fs=RATE,output='sos'),noise)*np.exp(-t*195)
		return (.84*body+.13*click)*(vel/127)**1.2
	if note==38:
		band=signal.sosfilt(signal.butter(2,[750,9000],btype='bandpass',fs=RATE,output='sos'),noise)
		body=np.sin(2*np.pi*203*t)*np.exp(-t*32)
		return (.32*body+.35*band*np.exp(-t*17))*(vel/127)**1.3
	band=signal.sosfilt(signal.butter(3,5000,btype='highpass',fs=RATE,output='sos'),noise)
	env=np.exp(-t*(47 if note==42 else 21))
	return .22*band*env*(vel/127)**1.15

midi_render=np.zeros((COUNT,2),np.float64)
for beat,note,velocity,length in notes:
	at=int(round((DRUMS_AT+beat*BEAT)*RATE))
	part=note_kit(note,velocity)
	usable=min(len(part),COUNT-at)
	midi_render[at:at+usable,0]+=part[:usable]
	midi_render[at:at+usable,1]+=part[:usable]*.96

# Different original drum hits: 4 UNIQUE actual OGG-transient excerpts,
# with no identical source offset among the four.
# These source times are documented as audition guesses, NOT verified beat grid.
clip_source_times=[60.76,61.44,63.68,65.54]
varied=np.zeros((COUNT,2),np.float64)
for beat_idx,src_sec in enumerate(clip_source_times):
	at=int(round((DRUMS_AT+beat_idx*BEAT)*RATE))
	src=int(round((src_sec-60-.014)*RATE))
	length=int(.19*RATE)
	part=sources['drums'][src:src+length].copy()
	assert len(part)==length
	ramp=int(.008*RATE)
	part[:ramp]*=np.linspace(0,1,ramp)[:,None]
	part[-ramp:]*=np.linspace(1,0,ramp)[:,None]
	varied[at:at+length]+=part

# Level-match just DRUMS during the four-beat section for fair comparison.
lo=int(DRUMS_AT*RATE);hi=int(BAND_AT*RATE)
def rms(x):return float(np.sqrt(np.mean(x*x)))
target=rms(audio_natural[lo:hi])
for key,drums in [('B',midi_render),('C',varied)]:
	current=rms(drums[lo:hi]);factor=float(np.clip(target/max(1e-6,current),.45,2.4))
	drums*=factor
	print('DRUM_MATCH',key,'targetRms',round(target,5),'rms',round(rms(drums[lo:hi]),5),'factor',round(factor,3))

# Identical soundtrack prelude, identical silence/no-scratch, identical
# original-band return at the same original source position in ALL versions.
common=context*env[:,None]
rendered={
	'A_original-natural-drum-stem': common+audio_natural,
	'B_recorded-midi-drum-kit': common+midi_render,
	'C_four-varied-original-drum-hits': common+varied,
}
# Shared fixed factor only; never independently compress/normalize variants.
maxpeak=max(float(np.max(np.abs(v))) for v in rendered.values())
gain=min(.95, .82/maxpeak)
print('GLOBAL_SINGLE_GAIN',gain,'peak',maxpeak)
paths=[]
for name,samples in rendered.items():
	pcm=np.int16(np.clip(samples*gain,-.999,.999)*32767)
	wav=OUT/(name+'.wav')
	with wave.open(str(wav),'wb') as w:
		w.setnchannels(2);w.setsampwidth(2);w.setframerate(RATE)
		w.writeframes(pcm.tobytes())
	mp3=OUT/(name+'.mp3')
	res=run(['ffmpeg','-nostdin','-v','error','-y','-i',str(wav),'-codec:a','libmp3lame','-q:a','4',str(mp3)],capture_output=True)
	if res.returncode!=0:raise RuntimeError(res.stderr.decode()[:300])
	wav.unlink()
	paths.append({'file':mp3.name,'bytes':mp3.stat().st_size,'sha256':sha256(mp3.read_bytes()).hexdigest(),
		'drumRms':round(rms(samples[lo:hi])*gain,5),'peak':round(float(np.max(np.abs(samples))*gain),4)})
	print('EXPORTED',mp3.name,mp3.stat().st_size)

metadata={'song':'One More Run','promptBpm':160,'releaseBeatVerification':'NOT VERIFIED','researchBeatSeconds':BEAT,
 'originalSourceSegment':'0005', 'originalSourceStartSeconds':START,
 'originalSourceStemHashesSha256':{role:sha256((ROOT/f'0005-{name}.ogg').read_bytes()).hexdigest() for role,name in STEMS.items()},
 'testCrashAtClipSeconds':CRASH_AT,'countInStartAtClipSeconds':DRUMS_AT,
 'fullBandReturnsAtClipSeconds':BAND_AT,'clipDurationSeconds':DURATION,
 'scratch':'INTENTIONALLY OMITTED in all 3: compare drum treatment without existing artificial scratch',
 'drumKitB':'MIDI SMF0, GM channel 10, original synthesized kit, kick/snare/hats, humanized velocity',
 'differentOriginalHitsC':clip_source_times,'outputs':paths}
(OUT/'metadata.json').write_text(json.dumps(metadata,indent=2)+'\n')
print('META',json.dumps(metadata,indent=2))#!/usr/bin/env python3
"""Offline research ONLY: analyze three 12-second samples per original recording.

Stems provide independent onset/tempo hypotheses; neither metrical quarter-note
identity nor phase is certified automatically. Never promotes candidate to
release BeatGridCatalog; no audio writing, no sound asset mutation.
"""
import argparse
import hashlib
import json
import subprocess
from pathlib import Path

import numpy as np
from scipy.ndimage import gaussian_filter1d, uniform_filter1d
from scipy.signal import correlate, find_peaks

ROOT = Path(__file__).resolve().parents[2]
PACKS = ROOT / 'public/music/packs'
TARGET_RATE = 11025
HOP = 110
MIN_LAG, MAX_LAG = 27, 118


def decode_stem(path, seconds=11.5):
	cmd = ['ffmpeg', '-v', 'error', '-nostdin', '-i', str(path), '-t', str(seconds),
		'-ar', str(TARGET_RATE), '-ac', '1', '-f', 'f32le', 'pipe:1']
	process = subprocess.run(cmd, capture_output=True, check=True, timeout=40)
	return np.frombuffer(process.stdout, dtype='<f4').astype('float64')


def onset_envelope(audio):
	# Two independent envelope scales detect short percussive and longer bass
	# transitions, avoiding a single naive broadband onset threshold.
	if len(audio) < TARGET_RATE * 5:
		return np.zeros(0)
	energy = audio * audio
	short = np.sqrt(np.maximum(0, uniform_filter1d(energy, size=256)[::HOP]))
	long = np.sqrt(np.maximum(0, uniform_filter1d(energy, size=900)[::HOP]))
	ratio = np.maximum(0, short / (long + 1e-5) - 1.0)
	flux = np.maximum(0, np.diff(np.log1p(short * 100), prepend=0))
	combined = gaussian_filter1d(flux * 0.7 + ratio * 0.3, sigma=1)
	combined -= np.percentile(combined, 45)
	combined = np.maximum(0, combined)
	if np.max(combined) > 0:
		combined /= np.max(combined)
	return combined


def candidates(envelope):
	if len(envelope) < 300 or float(np.std(envelope)) < .005:
		return []
	centered = envelope - np.mean(envelope)
	acf = correlate(centered, centered, method='fft')[len(centered) - 1:]
	normalized = acf / (np.maximum(np.arange(len(acf), 0, -1), 1) *
		(float(np.var(centered)) + 1e-9))
	region = normalized[MIN_LAG:MAX_LAG]
	peaks, _ = find_peaks(region, distance=8)
	values = sorted([(float(region[i]), int(i + MIN_LAG)) for i in peaks], reverse=True)
	if not values:
		values = [(float(np.max(region)), int(np.argmax(region) + MIN_LAG))]
	out = []
	for strength, lag in values[:5]:
		period = lag * HOP / TARGET_RATE
		# Evaluate phase in sample bins; never claim onsets are downbeats.
		frames = np.arange(len(envelope), dtype=float)
		phases = np.linspace(0, lag, max(10, lag), endpoint=False)
		def score(phase):
			indices = np.arange(phase, len(envelope), lag).astype(int)
			indices = indices[(indices >= 0) & (indices < len(envelope))]
			return float(np.mean(envelope[indices])) if len(indices) else 0.0
		best_phase = max(phases, key=score)
		pulse_strength = score(best_phase)
		background = float(np.mean(envelope))
		out.append(dict(bpm=round(60 / period, 2), periodSeconds=round(period, 5),
			phaseOffsetSeconds=round(float(best_phase) * HOP / TARGET_RATE, 4),
			autocorrelation=round(strength, 4), pulseOnsetStrength=round(pulse_strength, 4),
			onsetMean=round(background, 4),
			note='Machine hypothesis only; subdivision vs quarter-note identity unknown'))
	return out


def main():
	p = argparse.ArgumentParser()
	p.add_argument('--out', required=True)
	args = p.parse_args()
	out = Path(args.out)
	if out.exists():
		raise SystemExit('Refusing to overwrite existing research report: ' + str(out))
	tracks = []
	for manifest in sorted(PACKS.glob('*/pack.json')):
		meta = json.loads(manifest.read_text())
		segments = meta['segments']
		selected = sorted(set([0, len(segments) // 2, max(0, len(segments) - 2)]))
		windows = []
		for index in selected:
			seg = segments[index]
			window = dict(startSeconds=round(seg['startFrame'] / meta['sampleRate'], 6),
				segmentIndex=index, stemEvidence={})
			for stem in ['drums', 'bass']:
				path = manifest.parent / seg['sources'][stem]
				audio = decode_stem(path)
				window['stemEvidence'][stem] = dict(
					sha256=hashlib.sha256(path.read_bytes()).hexdigest(),
					durationSeconds=round(len(audio) / TARGET_RATE, 4),
					rms=round(float(np.sqrt(np.mean(audio * audio))), 5),
					candidatePulses=candidates(onset_envelope(audio)))
			windows.append(window)
		tracks.append(dict(trackId=meta['id'], sampleRate=meta['sampleRate'],
			frameCount=meta['frameCount'], durationSeconds=round(meta['frameCount'] / meta['sampleRate'], 3),
			status='RESEARCH_ONLY_UNVERIFIED_NOT_GYM_TRUSTED',
			manifestSha256=hashlib.sha256(manifest.read_bytes()).hexdigest(),
			windows=windows))
		print('ANALYZED', meta['id'],
			[(w['startSeconds'],w['stemEvidence']['drums']['candidatePulses'][0]['bpm']
				if w['stemEvidence']['drums']['candidatePulses'] else None) for w in windows], flush=True)
	report=dict(format='bitstream-gym-beat-candidate-research-v1',
		status='RESEARCH_ONLY_NO_TRUSTED_GRIDS',
		method='dual-stem onset envelopes + autocorrelation + phase ranking in 3 sampled 11.5s sections',
		limitations=['half/double-time ambiguity','cannot distinguish quarter pulse from syncopation',
			'sampled windows not full audio','source stem separation artifacts',
			'no independent human musical spot check'],tracks=tracks)
	out.parent.mkdir(parents=True, exist_ok=True)
	out.write_text(json.dumps(report, indent=2) + '\n')
	print('REPORT', out, 'SHA256', hashlib.sha256(out.read_bytes()).hexdigest())


