"""Catalog-only release gate cases, independent of the 4745-audio-file QA."""
import copy
import unittest
from validate_performance_release import assert_catalog_compatible


def baseline():
	return {'format':'bitstream-music-catalog-v1','tracks':[
		{'id':id,'title':id,'manifest':f'packs/{i:02d}_{id}/pack.json'}
		for i,id in enumerate(('FEsxYVStla4','local-one-more-run-bitstream-bluffs',
			'WRBGQUqD54U','FYImnz5-hXs'),1)]}


class TestReleaseCatalogMetadata(unittest.TestCase):
	def test_exact_prior_catalog_passes(self):
		cat=baseline()
		assert_catalog_compatible(cat,copy.deepcopy(cat))

	def test_three_new_billboard_ids_do_not_invalidate_source_release(self):
		old=baseline();new=copy.deepcopy(old)
		for row in new['tracks']:
			if len(row['id'])==11:row['youtubeId']=row['id']
		assert_catalog_compatible(new,old)

	def test_future_local_track_can_gain_confirmed_video(self):
		old=baseline();new=copy.deepcopy(old)
		new['tracks'][1]['youtubeId']='ABCDE12345_'
		assert_catalog_compatible(new,old)

	def test_published_video_reference_must_not_change_or_disappear(self):
		old=baseline();old['tracks'][0]['youtubeId']='FEsxYVStla4'
		for variant in ('WRBGQUqD54U',None):
			with self.subTest(variant=variant):
				new=copy.deepcopy(old)
				if variant is None: del new['tracks'][0]['youtubeId']
				else: new['tracks'][0]['youtubeId']=variant
				with self.assertRaisesRegex(AssertionError,'PUBLISHED_YOUTUBE_ID_CHANGED'):
					assert_catalog_compatible(new,old)

	def test_malformed_video_ids_fail(self):
		for malformed in (None,12,'bad','!ABCDE12345','valid-with-spaces'):
			with self.subTest(malformed=malformed):
				old=baseline();new=copy.deepcopy(old)
				new['tracks'][0]['youtubeId']=malformed
				with self.assertRaisesRegex(AssertionError,'INVALID_YOUTUBE_ID'):
					assert_catalog_compatible(new,old)

	def test_never_ignore_catalog_source_or_other_field_changes(self):
		old=baseline()
		for change in ('id','title','manifest','new_metadata','order','format','extra_top'):
			with self.subTest(change=change):
				new=copy.deepcopy(old)
				if change=='new_metadata':new['tracks'][0]['artworkOverride']='fake.png'
				elif change=='order':new['tracks'].reverse()
				elif change=='format':new['format']='v2'
				elif change=='extra_top':new['danger']=True
				else:new['tracks'][0][change]='changed'
				with self.assertRaises(AssertionError):
					assert_catalog_compatible(new,old)

	def test_track_count_drift_fails(self):
		old=baseline();new=copy.deepcopy(old);new['tracks'].pop()
		with self.assertRaisesRegex(AssertionError,'CATALOG_TRACK_COUNT_CHANGED'):
			assert_catalog_compatible(new,old)


if __name__=='__main__':unittest.main()#!/usr/bin/env python3
"""Source-hash-pinned, UNLABELED drum-event review triage.

Finds contentious attacks in actual drum FLACs. No 'false positive' labels:
the original release score is provisional and not independent ground truth.
Does not write in-game Music Lab data, score files, or audio assets.
"""
import argparse
import hashlib
import json
from collections import Counter, defaultdict
from pathlib import Path

from audit_cross_band_v6 import attack_bands, attack_features, source_predictions
from audit_real_drums_v6 import (KINDS, RATE, SOURCE_PATHS, STATUS,
	event_rows, read_pcm, verify_master)
from detector_candidate_v6 import cross_band_veto, MIN_FAMILY_SHARE
from evaluate_performance_v1 import match_events

CATEGORIES=('vetoed-but-release-agrees','retained-but-release-disagrees',
	'cross-family-coincidence','short-same-family-restrike',
	'vetoed-and-release-disagrees')
REVIEW_STATUS='machine-only-review-priority, NOT human gold, NOT a confirmed error'


def attach_release_matches(candidates, released, tolerance_ms):
	"""Match same-family events one-to-one; record release sample frames."""
	matches={}
	for family in KINDS:
		p=sorted([e for e in candidates if e['type']==family],
			key=lambda x:(x['startFrame'],x['index']))
		g=sorted([e for e in released if e['type']==family],
			key=lambda x:x['startFrame'])
		for pred,ref in match_events(p,g,round(tolerance_ms*RATE/1000)):
			matches[pred['index']]=ref['startFrame']
	return matches

def describe_candidate(event, siblings, v6_remaining, match20, match50, bands,
	start_frame, end_frame):
	kind=event['type']
	frame=event['startFrame']
	key=(frame,kind)
	preserved=v6_remaining[key]>0
	if preserved:v6_remaining[key]-=1
	t=event['relativeSec']
	rise=attack_features(bands,t)
	total=sum(rise.values())
	share=rise[kind]/max(1e-10,total)
	nearest_other=min((abs(frame-x['startFrame']) for x in siblings
		if x['index']!=event['index'] and x['type']!=kind),default=None)
	nearest_same=min((abs(frame-x['startFrame']) for x in siblings
		if x['index']!=event['index'] and x['type']==kind),default=None)
	near_cross=nearest_other is not None and nearest_other<=round(.025*RATE)
	quick_strike=nearest_same is not None and (
		round(.050*RATE)<=nearest_same<=round(.180*RATE))
	boundary=frame-start_frame<round(.200*RATE) or (
		end_frame-frame<round(.200*RATE))
	concordant=event['index'] in match20
	reasons=[]
	if not preserved:
		reasons.append('vetoed-but-release-agrees' if concordant
			else 'vetoed-and-release-disagrees')
	elif not concordant:
		reasons.append('retained-but-release-disagrees')
	if near_cross:reasons.append('cross-family-coincidence')
	if quick_strike:reasons.append('short-same-family-restrike')
	# Never convert V1 release agreement into positive/negative accuracy labels.
	return {'class':kind,'startFrame':frame,
		'startSeconds':round(frame/RATE,5),'windowRelativeMs':round(t*1000,2),
		'v6Retained':preserved,'v6OwnBandShare':round(share,5),
		'v6Threshold':MIN_FAMILY_SHARE[kind],
		'attackEnergyRise':{k:round(float(v),8) for k,v in rise.items()},
		'strongestBand':max(rise,key=rise.get),
		'within20msOfProvisionalRelease':concordant,
		'matchedProvisionalReleaseFrame20ms':match20.get(event['index']),
		'matchedProvisionalReleaseFrame50ms':match50.get(event['index']),
		'nearestOtherFamilyMs':round(nearest_other*1000/RATE,2)
			if nearest_other is not None else None,
		'nearestSameFamilyMs':round(nearest_same*1000/RATE,2)
			if nearest_same is not None else None,
		'withinWindowBoundary200ms':boundary,
		'machineReasons':reasons,
		'status':REVIEW_STATUS}

def triage_window(song,score,part,source_hash):
	start,end=part['startFrame'],part['endFrame']
	if not 0<=start<end<=score['frameCount'] or end-start>20*RATE:
		raise ValueError('Untrusted or overlength window')
	wave=read_pcm(song,start,end)
	before_hash=hashlib.sha256(wave.tobytes()).hexdigest()
	v5=source_predictions(wave)
	v6,diagnostics=cross_band_veto(wave)
	after_hash=hashlib.sha256(wave.tobytes()).hexdigest()
	if before_hash!=after_hash:raise ValueError('Mutated source PCM')
	rows=[{**e,'relativeSec':v5[i]['t'],'index':i}
		for i,e in enumerate(event_rows(v5,start))]
	# Event rows sort independently of V5 order; recover positions by
	# startFrame/class rather than assuming detector ordering is stable.
	position=defaultdict(list)
	for e in v5:
		position[(start+round(e['t']*RATE),e['type'])].append(e['t'])
	for e in rows:
		instances=position[(e['startFrame'],e['type'])]
		if not instances:raise ValueError('Unmatched proposal identity')
		e['relativeSec']=instances.pop(0)
	if any(position.values()):raise ValueError('Unconsumed proposal identities')
	released=event_rows([r for r in score['events']['drums'] if
		start<=r['startFrame']<end and r['class'] in KINDS],start,True)
	match20=attach_release_matches(rows,released,20)
	match50=attach_release_matches(rows,released,50)
	remain=Counter((e['startFrame'],e['type']) for e in event_rows(v6,start))
	bands=attack_bands(wave)
	annotated=[describe_candidate(e,rows,remain,match20,match50,
		bands,start,end) for e in rows]
	if any(remain.values()):raise ValueError('V6 emitted an unknown onset')
	if sum(e['v6Retained'] for e in annotated)!=len(v6):
		raise ValueError('Event matching count mismatch')
	return {'songId':song,'sourceStemSha256':source_hash,
		'baselineScoreHash':score['scoreHash'],
		'windowId':part['id'],'startFrame':start,'endFrame':end,
		'decodedPcmSha256':before_hash,'decodedPcmSamples16k':len(wave),
		'provisionalReleaseCount':len(released),'v5Count':len(v5),
		'v6Count':len(v6),'v6SuppressedCount':diagnostics['input']-len(v6),
		'events':annotated,'status':REVIEW_STATUS}
def shortlist(windows,per_song=8):
	"""Diversify songs/classes/reasons; never mark judgments as accurate."""
	by_song=defaultdict(list)
	for part in windows:
		for e in part['events']:
			if e['withinWindowBoundary200ms'] or not e['machineReasons']:
				continue
			best=min((CATEGORIES.index(r) for r in e['machineReasons']))
			by_song[part['songId']].append({
				'songId':part['songId'],'windowId':part['windowId'],
				'startFrame':e['startFrame'],'startSeconds':e['startSeconds'],
				'class':e['class'],'rankBucket':best,
				'v6Retained':e['v6Retained'],
				'v6OwnBandShare':e['v6OwnBandShare'],
				'machineReasons':e['machineReasons'],
				'sourceStemSha256':part['sourceStemSha256'],
				'baselineScoreHash':part['baselineScoreHash'],
				'status':REVIEW_STATUS})
	out=[]
	for song in sorted(by_song):
		options=sorted(by_song[song],key=lambda x:(x['rankBucket'],
			abs(x['v6OwnBandShare']-.1),x['startFrame'],x['class']))
		chosen=[]
		reasons_seen=set()
		# One representative per available reason bucket first.
		for reason in range(len(CATEGORIES)):
			for row in options:
				if row['rankBucket']==reason and all(
					abs(row['startFrame']-seen['startFrame'])>RATE//3
					for seen in chosen):
					chosen.append(row)
					reasons_seen.add(reason)
					break
		for row in options:
			if len(chosen)>=per_song:break
			if row not in chosen and all(
				abs(row['startFrame']-seen['startFrame'])>RATE//3
				for seen in chosen):chosen.append(row)
		out.extend(chosen[:per_song])
	return sorted(out,key=lambda x:(x['songId'],x['rankBucket'],
		x['startFrame'],x['class']))
def load_source_windows(root):
	songs={}
	for item in sorted(root.glob('*/performance.json')):
		score=json.loads(item.read_text())
		song=score['songId']
		if song not in SOURCE_PATHS:continue
		queue=json.loads((item.parent/'review-queue-v1.json').read_text())
		if queue.get('songId')!=song or queue.get('baselineScoreHash')!=score.get('scoreHash'):
			raise ValueError('Review queue source/score mismatch')
		if queue.get('status')!='machine-ranked-disagreement-not-human-verified':
			raise ValueError('Review queue is not marked unverified')
		hash_verified=verify_master(song,score)
		parts=[{**x,'id':x['id']} for x in queue['excerpts']
			if x['role']=='drums']
		for start in (14,75):
			a=start*RATE
			b=min(a+8*RATE,score['frameCount'])
			parts.append({'id':f'fixed-{start}s','startFrame':a,'endFrame':b})
		songs[song]=(score,parts,hash_verified)
	if set(songs)!=set(SOURCE_PATHS):
		raise ValueError('Four source FLAC hashes not verified')
	return songs


def run(root):
	windows=[]
	for song,(score,parts,source_hash) in load_source_windows(root).items():
		for part in parts:
			window=triage_window(song,score,part,source_hash)
			windows.append(window)
			print('REVIEW_TRIAGE',song,part['id'],len(window['events']),
				'preserved',window['v6Count'],flush=True)
	picks=shortlist(windows)
	return {'format':'bitstream-real-drum-machine-review-triage-v7',
		'status':REVIEW_STATUS,'humanVerified':False,'approvedForAudio':False,
		'source':STATUS,'timebaseHz':RATE,
		'modelAgreementIsNotTruth':True,'windows':windows,
		'shortlist':picks,'shortlistCategoryOrder':list(CATEGORIES),
		'detectorSourceSha256':{n:hashlib.sha256((Path(__file__).parent/n)
			.read_bytes()).hexdigest() for n in (
			'detector_candidate_v2.py','detector_candidate_v4.py',
			'detector_candidate_v6.py')}}
def main():
	p=argparse.ArgumentParser(description=__doc__)
	p.add_argument('--score-root',type=Path,default=Path('public/music/packs'))
	p.add_argument('--out',type=Path,required=True)
	a=p.parse_args()
	if a.out.exists():raise FileExistsError(a.out)
	report=run(a.score_root)
	a.out.parent.mkdir(parents=True,exist_ok=True)
	a.out.write_text(json.dumps(report,indent=2)+'\n')
	print('UNVERIFIED REVIEW PRIORITIES',len(report['shortlist']),
		'FROM',len(report['windows']),'real-source windows',flush=True)
	print('EVIDENCE',a.out,flush=True)


if __name__=='__main__':
	main()#!/usr/bin/env python3
"""Finish an already installed V1 3-part orchestra with 2 more real parts.

Source pack has original six unchanged, 11 biome voice stems, 3 V1
instrument role recordings. After new Guitar/Piano/Other files have been
staged alongside them, this script verifies ALL new clips and changes only
pack.json metadata to route all five instrumental roles in V2.
Never silently change an existing approved orchestra; V1->V2 only.
"""
import argparse
import json
from pathlib import Path

BIOMES=(
	'debutmont','garbage-dump-glacier','pyramid-peak','underwater-mountain',
	'crystal-cavern','space-mountain','candy-cane-canyon',
	'sky-jellyfish-mountain','steampunk-slopes','micro-mountain','vertigo-vents',
)
STEMS=('guitar','piano','other')
FEATURED={
	'FEsxYVStla4':'other',
	'local-one-more-run-bitstream-bluffs':'piano',
	'WRBGQUqD54U':'guitar',
	'FYImnz5-hXs':'other',
}

def patch(root):
	catalog=json.loads((root/'catalog.json').read_text())
	if {track['id'] for track in catalog['tracks']}!=set(FEATURED):
		raise ValueError('The source music catalog does not contain exactly the four owner songs')
	modified=[]
	for track in catalog['tracks']:
		f=root/track['manifest']
		doc=json.loads(f.read_text())
		id=track['id']
		assert doc['orchestraVersion']=='provisional-full-reperformance-v1',id
		assert doc['adaptive']['featuredStem']==FEATURED[id],id
		assert set(doc['adaptive']['variants'])=={'featured','bass','drums'},id
		n=len(doc['segments'])
		roles=[stem for stem in STEMS if stem!=FEATURED[id]]
		assert len(roles)==2 and n>=15
		paths={}
		for role in roles:
			paths[role]={}
			for biome in BIOMES:
				files=[f'adaptive/{biome}/{role}-{i:04d}.ogg' for i in range(n)]
				for rel in files:
					child=f.parent/rel
					if not child.is_file() or child.stat().st_size<=500:
						raise FileNotFoundError('Incomplete extra instrument recording: '+str(child))
				paths[role][biome]=files
		modified.append((f,doc,paths))
	# Only mutate manifests after verifying *all four complete*.
	for f,doc,paths in modified:
		doc['adaptive']['variants'].update(paths)
		# The featured role is already a replacement of its original
		# source stem. A named duplicate role is intentionally absent.
		doc['adaptive']['variants'][FEATURED[doc['id']]]={}
		doc['orchestraVersion']='provisional-full-reperformance-v2'
		doc['scoreDisclaimer']=(
			'PRE-ALPHA: independently regenerated full-length melody, guitar, '
			'piano, other, bass, and airborne percussion. Onset/pitch detection '
			'is provisional and will be rerendered. Dynamic Orchestra defaults '
			'OFF: original six source stems (other than synthesized biome lead) '
			'stay intact; airborne drums and bass speed fades still operate.'
		)
		tmp=f.with_suffix('.v2-tmp')
		assert not tmp.exists()
		tmp.write_text(json.dumps(doc,indent=2)+'\n')
		tmp.replace(f)
		print('UPGRADED_FULL_FIVE_INSTRUMENTS',doc['id'],len(doc['segments']),flush=True)

if __name__=='__main__':
	p=argparse.ArgumentParser(description=__doc__)
	p.add_argument('--music-root',type=Path,required=True)
	a=p.parse_args()
	patch(a.music_root)#!/usr/bin/env python3
"""Source-preserving four-song real orchestra release gate.

Checks full-song frame-accurate pack segments, all 12 distinct voice sources,
11 mountain variant triplets and known-safe paths. Verifies original six
Opus chunks against the private baseline hash, and decodes selected first,
middle and final chunks to ensure that adaptive swaps won't underrun.
"""
import argparse
import hashlib
import json
import subprocess
from pathlib import Path

from install_full_dynamic_orchestra_v1 import BIOMES,FEATURED

ROLES=('featured','bass','drums','melody','guitar','piano','other')
STEMS=('vocals','drums','bass','guitar','piano','other')
def filehash(path):
	h=hashlib.sha256()
	with path.open('rb') as f:
		for block in iter(lambda:f.read(1<<20),b''):
			h.update(block)
	return h.digest()

def probe(file):
	p=subprocess.run(['ffprobe','-v','error','-show_entries',
		'stream=codec_name,sample_rate,channels:format=duration',
		'-of','json',str(file)],capture_output=True,text=True,check=True,timeout=20)
	data=json.loads(p.stdout)
	stream=data['streams'][0]
	assert stream['codec_name']=='opus' and int(stream['sample_rate'])==48000
	assert stream['channels']==2
	return float(data['format']['duration'])

def decoded_frames(file):
	p=subprocess.run(['ffmpeg','-v','error','-nostdin','-i',str(file),
		'-ac','2','-ar','48000','-f','s16le','pipe:1'],
		capture_output=True,check=True,timeout=30)
	assert len(p.stdout)%4==0, ('Corrupt decoded audio',file)
	return len(p.stdout)//4


def validate(music,baseline):
	catalog=json.loads((music/'catalog.json').read_text())
	assert catalog['format']=='bitstream-music-catalog-v1'
	assert len(catalog['tracks'])==4
	assert {t['id'] for t in catalog['tracks']}==set(FEATURED)
	report={'songs':[],'originalsIdentical':True,'roles':list(ROLES)}
	total_source=0
	total_replacements=0
	for track in catalog['tracks']:
		pack_path=music/track['manifest']
		old_path=baseline/track['manifest']
		pack=json.loads(pack_path.read_text())
		old=json.loads(old_path.read_text())
		assert pack['id']==track['id'] and pack['sampleRate']==48000
		assert pack['frameCount']==old['frameCount']
		assert pack['orchestraVersion']=='provisional-full-reperformance-v2'
		assert pack['adaptive']['featuredStem']==FEATURED[track['id']]
		assert set(pack['adaptive']['variants'])=={'featured','bass','drums','guitar','piano','other'}
		assert len(pack['segments'])==len(old['segments'])>=15
		n=len(pack['segments'])
		for role in ('featured','bass','drums','guitar','piano','other'):
			expected=set() if role==FEATURED[track['id']] else set(BIOMES)
			assert set(pack['adaptive']['variants'][role])==expected
		for i,seg in enumerate(pack['segments']):
			old_seg=old['segments'][i]
			assert seg['startFrame']==old_seg['startFrame']
			assert seg['frames']==old_seg['frames']
			assert set(seg['sources'])==set(STEMS)|{
				'voice:bitstream-bluffs'}|{'voice:'+b for b in BIOMES}
			for stem in STEMS:
				original=music/Path(track['manifest']).parent/seg['sources'][stem]
				prior=baseline/Path(track['manifest']).parent/old_seg['sources'][stem]
				assert original.is_file() and prior.is_file()
				assert filehash(original)==filehash(prior),original
				total_source+=1
			for name in ('voice:bitstream-bluffs',):
				assert (music/Path(track['manifest']).parent/seg['sources'][name]).is_file()
				total_source+=1
			for biome in BIOMES:
				voice=music/Path(track['manifest']).parent/seg['sources']['voice:'+biome]
				assert voice.is_file() and voice.stat().st_size>500
				total_replacements+=1
				for role in ('featured','bass','drums','guitar','piano','other'):
					if role==FEATURED[track['id']]: continue
					path=pack['adaptive']['variants'][role][biome][i]
					assert '..' not in path and not path.startswith('/')
					full=music/Path(track['manifest']).parent/path
					assert full.is_file() and full.stat().st_size>500
					total_replacements+=1
		# Decode the beginning, middle and tail of every selected role.
		# FFmpeg's 20ms Opus packetization permits up to ~20ms pad,
		# but never early truncation >40ms.
		for idx in sorted({0,n//2,n-1}):
			seg=pack['segments'][idx]
			required=seg['frames']/48000
			for biome in ('debutmont','crystal-cavern','vertigo-vents'):
				for role in ('melody','featured','bass','drums')+tuple(r for r in ('guitar','piano','other') if r!=FEATURED[track['id']]):
					name=(seg['sources']['voice:'+biome] if role=='melody' else
						pack['adaptive']['variants'][role][biome][idx])
					full=music/Path(track['manifest']).parent/name
					actual_frames=decoded_frames(full)
					assert actual_frames==seg['frames'], (
						full,'decoded',actual_frames,'required',seg['frames'])
					assert probe(full)>0
		report['songs'].append({'id':track['id'],'duration':pack['frameCount']/48000,
			'segments':n,'originalStems':len(STEMS),
			'biomes':len(BIOMES),'reperformedRoles':list(ROLES)})
	all_files=list(music.rglob('*.ogg'))
	assert len(all_files)==total_source+total_replacements
	assert total_source==455 and total_replacements==4290,(total_source,total_replacements)
	report.update({'passed':True,'sourceOggsPreserved':total_source,
		'brandNewBiomeOggs':total_replacements,'totalOggs':len(all_files),
		'bytes':sum(f.stat().st_size for f in all_files),
		'licenseScope':'User requested publishing four personal tracks to main',
		'limitations':'Pitch/onset resynthesis provisional; human approval pending; not proof of note-perfect transcription'})
	return report

if __name__=='__main__':
	p=argparse.ArgumentParser(description=__doc__)
	p.add_argument('--music-root',type=Path,required=True)
	p.add_argument('--baseline',type=Path,required=True)
	p.add_argument('--report',type=Path,required=True)
	a=p.parse_args()
	assert not a.report.exists()
	result=validate(a.music_root,a.baseline)
	a.report.write_text(json.dumps(result,indent=2)+'\n')
	print('FULL_DYNAMIC_ORCHESTRA_QA_PASS',result['sourceOggsPreserved'],
		'unchanged source',result['brandNewBiomeOggs'],
		'new parts',result['totalOggs'],'total',flush=True)#!/usr/bin/env python3
"""Release gate: decode every game music Opus clip and check exact source frames.

Fable's 6.5ms defect escaped the old 40ms tolerance. There is NO tolerance
here: all 4745 decoded clips must have exactly the segment's integer
sample-frame count. All six original source stems and original home voice
must remain SHA-256 unchanged; no model weights or raw source FLAC/WAV
are distributed. The track manifests, not guessed durations, are truth.
"""
import argparse
import hashlib
import json
import subprocess
import sys
from concurrent.futures import ThreadPoolExecutor, as_completed
from pathlib import Path

ROLES=('featured','bass','drums','guitar','piano','other')
ORIGINAL=('vocals','drums','bass','guitar','piano','other','voice:bitstream-bluffs')

def sha256(path):
	h=hashlib.sha256()
	with path.open('rb') as f:
		for block in iter(lambda:f.read(1024*1024),b''):
			h.update(block)
	return h.hexdigest()

def check_sample(job):
	path,frames,kind=job
	proc=subprocess.run(['ffmpeg','-nostdin','-v','error','-i',str(path),
		'-ac','2','-ar','48000','-f','s16le','pipe:1'],
		stdout=subprocess.PIPE,stderr=subprocess.PIPE,timeout=90)
	if proc.returncode:
		raise ValueError('PCM decode failed: '+str(path)+' '+proc.stderr.decode(errors='replace')[-600:])
	n=len(proc.stdout)
	if n%4 or n//4!=frames:
		raise ValueError('SAMPLE COUNT MISMATCH '+str(path)+
			' decoded='+str(n//4)+' expected='+str(frames))
	return kind

def build_jobs(root,prior):
	cat=json.loads((root/'catalog.json').read_text())
	oldcat=json.loads((prior/'catalog.json').read_text())
	assert len(cat['tracks'])==len(oldcat['tracks'])==4
	assert [t['id'] for t in cat['tracks']]==[t['id'] for t in oldcat['tracks']]
	jobs=[]
	songReport=[]
	originalHashCount=0
	for item in cat['tracks']:
		relative=Path(item['manifest'])
		doc=json.loads((root/relative).read_text())
		previous=json.loads((prior/relative).read_text())
		assert doc['frameCount']==previous['frameCount']
		assert doc['sampleRate']==48000
		assert len(doc['segments'])==len(previous['segments'])
		assert doc['id']==item['id']
		roles=doc['adaptive']['variants']
		assert set(roles)==set(ROLES)
		stems=doc['segments'][0]['sources']
		allVoices=[n for n in stems if n.startswith('voice:') and n!='voice:bitstream-bluffs']
		assert len(allVoices)==11
		cursor=0
		touched=set()
		for i,(seg,old) in enumerate(zip(doc['segments'],previous['segments'])):
			assert seg['startFrame']==cursor==old['startFrame']
			assert seg['frames']==old['frames']>0
			cursor+=seg['frames']
			assert set(seg['sources'])==set(old['sources'])
			for name,path in seg['sources'].items():
				if name in ORIGINAL:
					assert path==old['sources'][name]
				full=(root/relative.parent/path).resolve()
				assert full.is_relative_to(root.resolve()) and full.is_file()
				if name in ORIGINAL:
					priorFile=(prior/relative.parent/old['sources'][name]).resolve()
					assert priorFile.is_file()
					if sha256(full)!=sha256(priorFile):
						raise ValueError('Original stem was changed: '+str(full))
					originalHashCount+=1
				assert full not in touched, ('duplicate clip',full)
				touched.add(full)
				jobs.append((full,seg['frames'],'original' if name in ORIGINAL else 'reperformed'))
			for role,variants in roles.items():
				if role==doc['adaptive']['featuredStem']:
					assert variants=={}
					continue
				assert set(variants)==set(n.split(':',1)[1] for n in allVoices)
				for biome,paths in variants.items():
					assert len(paths)==len(doc['segments'])
					path=paths[i]
					full=(root/relative.parent/path).resolve()
					assert full.is_relative_to(root.resolve()) and full.is_file()
					assert full not in touched, ('duplicate clip',full)
					touched.add(full)
					jobs.append((full,seg['frames'],'reperformed'))
		assert cursor==doc['frameCount']
		songReport.append({'id':item['id'],'durationSeconds':cursor/48000,
			'segments':len(doc['segments']),'decodedClips':len(touched)})
	assert len(jobs)==4745,len(jobs)
	assert len({row[0] for row in jobs})==len(jobs)
	assert originalHashCount==455,originalHashCount
	return jobs,songReport,originalHashCount

def main():
	p=argparse.ArgumentParser(description=__doc__)
	p.add_argument('--music',type=Path,required=True)
	p.add_argument('--baseline',type=Path,required=True)
	p.add_argument('--report',type=Path,required=True)
	p.add_argument('--workers',type=int,default=8)
	a=p.parse_args()
	assert not a.report.exists()
	assert 1<=a.workers<=32
	jobs,songs,untouched=build_jobs(a.music,a.baseline)
	print('MANIFEST_AND_SHA256_PASS',len(jobs),'audio clips',untouched,
		'original files unchanged',flush=True)
	counts={'original':0,'reperformed':0}
	failures=[]
	with ThreadPoolExecutor(max_workers=a.workers) as pool:
		pending={pool.submit(check_sample,job):job[0] for job in jobs}
		for i,future in enumerate(as_completed(pending),1):
			try:
				kind=future.result()
				counts[kind]+=1
			except Exception as exc:
				failures.append(str(exc))
				if len(failures)>6:
					for other in pending:other.cancel()
					break
			if i%250==0 or i==len(jobs):
				print('PCM_DECODE_VERIFIED',i,'/',len(jobs),
					'failures',len(failures),flush=True)
	if failures:
		for error in failures[:10]:print('FAIL',error,file=sys.stderr)
		raise ValueError('Sample exact decode validation failed '+str(len(failures)))
	assert counts=={'original':455,'reperformed':4290},counts
	report={'format':'bitstream-opus-frame-exact-gate-v1','passed':True,
		'rate':48000,'channels':2,'expectedOgg':4745,
		'originalSha256Unchanged':untouched,'decodedFramesExact':len(jobs),
		'counts':counts,'songs':songs,
		'fix':'independent Opus encoding per 12s integer-sample segment',
		'notes':'No content transcription improvements claimed. This is an audio packaging repair.'}
	a.report.write_text(json.dumps(report,indent=2)+'\n')
	print('SAMPLE_EXACT_RELEASE_GATE_PASS',report['decodedFramesExact'],flush=True)

if __name__=='__main__':
	main()#!/usr/bin/env python3
"""Fail-closed release gate: new score sidecars, ZERO changed audio bytes.

Checks the exact original 4745 Ogg sources and untouched gameplay pack
segments against the already-published previous main, *and* checks every
performance-v1 event and hash. Separate score artifact only; no claim of
musical accuracy or corrected note events.
"""
import argparse
import hashlib
import json
import re
from pathlib import Path

from performance_v1 import ROLES,read,sha256_file

EXPECTED_COUNTS={
	'FEsxYVStla4':{'bass':209,'drums':1743,'guitar':1216,
		'melody':716,'other':2228,'piano':1256},
	'local-one-more-run-bitstream-bluffs':{
		'bass':301,'drums':1860,'guitar':2028,'melody':464,
		'other':3548,'piano':2896},
	'WRBGQUqD54U':{'bass':202,'drums':1787,'guitar':2214,
		'melody':576,'other':1952,'piano':1716},
	'FYImnz5-hXs':{'bass':143,'drums':1600,'guitar':834,
		'melody':595,'other':2004,'piano':1664},
}

YOUTUBE_VIDEO_ID=re.compile(r'[A-Za-z0-9_-]{11}\Z')

def assert_catalog_compatible(current,baseline):
	"""Permit *only* optional billboard YouTube IDs, never source/audio changes.

	An older release without video references may gain them. Once a reference
	is published, removal or silent replacement still requires explicit review.
	All non-youtubeId catalog fields, track ordering, and manifest links must
	match the previous release exactly.
	"""
	assert current.keys()==baseline.keys(), 'CATALOG_TOP_LEVEL_CHANGED'
	assert current['format']==baseline['format'], 'CATALOG_FORMAT_CHANGED'
	assert len(current['tracks'])==len(baseline['tracks'])==4, 'CATALOG_TRACK_COUNT_CHANGED'
	for new,old in zip(current['tracks'],baseline['tracks']):
		assert {k:v for k,v in new.items() if k!='youtubeId'}=={
			k:v for k,v in old.items() if k!='youtubeId'}, 'SHIPPING_CATALOG_CONTENT_CHANGED'
		if 'youtubeId' in new:
			assert isinstance(new['youtubeId'],str) and YOUTUBE_VIDEO_ID.fullmatch(new['youtubeId']), 'INVALID_YOUTUBE_ID'
		if 'youtubeId' in old:
			assert new.get('youtubeId')==old['youtubeId'], 'PUBLISHED_YOUTUBE_ID_CHANGED'


def run(current,baseline):
	current=Path(current)
	baseline=Path(baseline)
	cat=json.loads((current/'catalog.json').read_text())
	oldcat=json.loads((baseline/'catalog.json').read_text())
	assert_catalog_compatible(cat,oldcat)
	ogg_count=0
	review_total=0
	scores={}
	for song in cat['tracks']:
		id=song['id']
		new_path=current/song['manifest']
		old_path=baseline/song['manifest']
		pack=json.loads(new_path.read_text())
		old_pack=json.loads(old_path.read_text())
		meta=pack.pop('performance')
		comparison=pack.pop('experimentalPerformance',None)
		review_descriptor=pack.pop('diagnosticReviewQueue',None)
		# All diagnostic pointers are metadata ONLY. Every field
		# controlling source audio, rendering, effects and selection must
		# match the prior published release byte-for-byte as JSON values.
		assert pack==old_pack,'SHIPPING_AUDIO_MANIFEST_WAS_MODIFIED '+id
		assert meta['path']=='performance.json'
		score_path=(new_path.parent/meta['path']).resolve()
		assert score_path.is_relative_to(current.resolve())
		score=read(score_path)
		assert score['songId']==id
		assert score['scoreHash']==meta['scoreHash']
		assert score['frameCount']==pack['frameCount']==old_pack['frameCount']
		assert score['featuredStem']==pack['adaptive']['featuredStem']
		assert {name:len(rows) for name,rows in score['events'].items()}==EXPECTED_COUNTS[id],id
		assert score['quality']=='provisional-unreviewed'
		assert score['calibratedConfidence'] is False
		if comparison is not None:
			assert comparison['path']=='performance-candidate-v2.json'
			assert comparison['parentScoreHash']==score['scoreHash']
			sidecar=(new_path.parent/comparison['path']).resolve()
			assert sidecar.is_relative_to(current.resolve())
			candidate=read(sidecar)
			assert candidate['songId']==id
			assert candidate['quality']=='experimental-candidate-unreviewed'
			assert candidate['calibratedConfidence'] is False
			assert candidate['scoreHash']==comparison['scoreHash']
			assert candidate['scoreHash']!=score['scoreHash']
			assert candidate['frameCount']==score['frameCount']
			assert candidate['featuredStem']==score['featuredStem']
			assert (candidate['provenance']['sourceStemSha256']==
				score['provenance']['sourceStemSha256'])
			assert (candidate['provenance']['evidence']['parentScoreHash']==
				score['scoreHash'])
			assert candidate['events']['melody']==score['events']['melody']
		if review_descriptor is not None:
			assert comparison is not None
			assert review_descriptor['path']=='review-queue-v1.json'
			assert review_descriptor['baselineScoreHash']==score['scoreHash']
			assert review_descriptor['experimentalScoreHash']==candidate['scoreHash']
			review_path=(new_path.parent/review_descriptor['path']).resolve()
			assert review_path.is_relative_to(current.resolve())
			review=json.loads(review_path.read_text())
			assert review['format']=='bitstream-music-review-queue-v1'
			assert review['status']=='machine-ranked-disagreement-not-human-verified'
			assert review['songId']==id
			assert review['baselineScoreHash']==score['scoreHash']
			assert review['experimentalScoreHash']==candidate['scoreHash']
			assert 'NOT correctness' in review['selectionMethod']
			rows=review['excerpts']
			assert isinstance(rows,list) and 1<=len(rows)<=20
			assert all(row['role'] in ('bass','drums','guitar','piano','other')
				and row['startFrame']>=0 and row['endFrame']<=score['frameCount']
				and row['startFrame']<row['endFrame']
				and row['endFrame']-row['startFrame']<=8*48000
				and row['samePitchWithin50ms']<=min(row['releaseCount'],
					row['candidateCount']) for row in rows)
			assert len({row['id'] for row in rows})==len(rows)
			review_total+=len(rows)
		# All 4,745 packaged Ogg clips unchanged: compare hashes for each
		# relative path in both deployed trees, not only file size.
		original={p.relative_to(old_path.parent):p for p in
			old_path.parent.rglob('*.ogg')}
		new={p.relative_to(new_path.parent):p for p in new_path.parent.rglob('*.ogg')}
		if new.keys()!=original.keys():
			raise AssertionError('MEDIA_FILES_ADDED_OR_REMOVED '+id)
		for rel,file in new.items():
			if sha256_file(file)!=sha256_file(original[rel]):
				raise AssertionError('OGG_CHANGED '+id+' '+str(rel))
		ogg_count+=len(new)
		scores[id]={'scoreHash':score['scoreHash'],
			'experimentalScoreHash':candidate['scoreHash'] if comparison else None,
			'events':sum(len(score['events'][role]) for role in ROLES),
			'unchangedAudio':len(new)}
		print('ORIGINAL_AUDIO_AND_SCORE_IDENTITY_PASS',id,
			'OGG',len(new),'events',scores[id]['events'],flush=True)
	assert ogg_count==4745,ogg_count
	assert sum(row['events'] for row in scores.values())==33752
	assert review_total in (0,20),'incomplete original 20-passage review shortlist'
	return {'format':'bitstream-performance-release-gate-v1',
		'scores':scores,'unchangedOgg':ogg_count,'sourceTracks':4,
		'unverifiedReviewExcerpts':review_total,
		'uncalibrated':True,
		'meaning':'source event provenance and score playback markers only; no improved pitch/timing'}

def main():
	p=argparse.ArgumentParser(description=__doc__)
	p.add_argument('--current',type=Path,required=True)
	p.add_argument('--baseline',type=Path,required=True)
	p.add_argument('--report',type=Path,required=True)
	a=p.parse_args()
	if a.report.exists():raise FileExistsError(a.report)
	result=run(a.current,a.baseline)
	a.report.parent.mkdir(parents=True,exist_ok=True)
	a.report.write_text(json.dumps(result,indent=2)+'\n')
	print('PERFORMANCE_RELEASE_EVIDENCE_GATE_PASS',result['unchangedOgg'],
		'ORIGINAL_AUDIO_BYTES_UNCHANGED',flush=True)

if __name__=='__main__':
	main()#!/usr/bin/env python3
